                            { t: 'Variance', v: totalVariance, c: totalVariance >= 0 ? '#10b981' : '#ef4444', icon: totalVariance >= 0 ? <CheckCircleOutlined /> : <WarningOutlined /> },
                            { t: 'Over Budget', v: overBudgetCount, c: '#ef4444', icon: <RiseOutlined /> },
