                                {apSummary && apSummary.totalOutstanding > 0 && (
                                    <AgingBar current={apSummary.current || 0} d30={apSummary.aging30 || 0} d60={apSummary.aging60 || 0} d90={apSummary.aging90 || 0} d90plus={apSummary.aging90plus || 0} />
