                            >
                                <div style={{
                                    width: 36, height: 36, borderRadius: 10, margin: '0 auto 8px',
                                    background: `${item.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    fontSize: 18, color: item.color,
                                }}>{item.icon}</div>
                                <Text strong style={{ fontSize: 12, display: 'block' }}>{item.title}</Text>
                                <Text type="secondary" style={{ fontSize: 10 }}>{item.desc}</Text>
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
        </div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import RbacGuard from '@/components/common/RbacGuard';
import { Table, Button, Space, Tag, Input, Select, Drawer, Form, InputNumber, message, Typography, Card, Tooltip, Divider, DatePicker, Empty, Spin, Popconfirm, Row, Col, Alert, Modal } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, SearchOutlined, ReloadOutlined, CheckCircleOutlined, UndoOutlined, EyeOutlined, MinusCircleOutlined, FileExcelOutlined, FilePdfOutlined  } from '@ant-design/icons';
import { accountingService, AcctJournal, AcctJournalLine, AcctAccount } from '@/lib/accountingService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import dayjs from 'dayjs';

const { Text } = Typography;
const { RangePicker } = DatePicker;
const formatCurrency = (v: number | string) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(Number(v) || 0);
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const statusColor: Record<string, string> = { draft: 'gold', posted: 'green', reversed: 'volcano', void: 'default' };
const typeColor: Record<string, string> = { general: 'blue', adjusting: 'purple', closing: 'orange', opening: 'cyan', reversal: 'red' };

export default function JournalEntriesPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [journals, setJournals] = useState<AcctJournal[]>([]);
    const [accounts, setAccounts] = useState<AcctAccount[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [filterStatus, setFilterStatus] = useState<string | undefined>();
    const [filterType, setFilterType] = useState<string | undefined>();
    const [dateRange, setDateRange] = useState<[string, string] | null>(null);

    // Create drawer
    const [createOpen, setCreateOpen] = useState(false);
    const [form] = Form.useForm();

    // Detail drawer
    const [detailOpen, setDetailOpen] = useState(false);
    const [selectedJournal, setSelectedJournal] = useState<AcctJournal | null>(null);
    const [journalLines, setJournalLines] = useState<AcctJournalLine[]>([]);
    const [detailLoading, setDetailLoading] = useState(false);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [j, a] = await Promise.all([
                accountingService.getJournals(undefined, { status: filterStatus, journalType: filterType, dateFrom: dateRange?.[0], dateTo: dateRange?.[1], search: search || undefined }),
                accounts.length ? Promise.resolve(accounts) : accountingService.getAccounts(),
            ]);
            setJournals(j);
            if (!accounts.length) setAccounts(a);
        } catch (e: any) { message.error(e.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterType, dateRange, search]);

    useEffect(() => { load(); }, [load]);

    const accountMap = React.useMemo(() => {
        const m = new Map<string, AcctAccount>();
        accounts.forEach(a => m.set(a.id, a));
        return m;
    }, [accounts]);

    const openCreate = async () => {
        if (!accounts.length) setAccounts(await accountingService.getAccounts());
        form.resetFields();
        form.setFieldsValue({
            journalType: 'general', journalDate: dayjs().format('YYYY-MM-DD'), currencyCode: 'IDR', exchangeRate: 1,
            lines: [{ accountId: undefined, description: '', debit: 0, credit: 0 }, { accountId: undefined, description: '', debit: 0, credit: 0 }],
        });
        setCreateOpen(true);
    };

    const viewDetail = async (journal: AcctJournal) => {
        setSelectedJournal(journal);
        setDetailOpen(true);
        setDetailLoading(true);
        try { setJournalLines(await accountingService.getJournalLines(journal.id)); }
        catch (e: any) { message.error(e.message); }
        finally { setDetailLoading(false); }
    };

    const handleCreate = async () => {
        try {
            const values = await form.validateFields();
            // Validate lines
            const lines = values.lines.filter((l: any) => l.accountId && (l.debit > 0 || l.credit > 0));
            if (lines.length < 2) { message.error('At least 2 lines required'); return; }
            const totalDebit = lines.reduce((s: number, l: any) => s + (l.debit || 0), 0);
            const totalCredit = lines.reduce((s: number, l: any) => s + (l.credit || 0), 0);
            if (Math.abs(totalDebit - totalCredit) > 0.01) { message.error(`Unbalanced: Debit ${formatCurrency(totalDebit)} â‰  Credit ${formatCurrency(totalCredit)}`); return; }

            await accountingService.createJournal(undefined, { ...values, lines });
            message.success('Journal created');
            setCreateOpen(false); load();
        } catch (e: any) { if (e.message) message.error(e.message); }
    };

    const handlePost = async (id: string) => {
        try { await accountingService.postJournal(id); message.success('Journal posted'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    const handleReverse = async (id: string) => {
        try { await accountingService.reverseJournal(id); message.success('Journal reversed'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    const handleDelete = async (id: string) => {
        try { await accountingService.deleteJournal(id); message.success('Deleted'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    // Live balance check in form
    const formLines = Form.useWatch('lines', form) || [];
    const liveDebit = formLines.reduce((s: number, l: any) => s + (l?.debit || 0), 0);
    const liveCredit = formLines.reduce((s: number, l: any) => s + (l?.credit || 0), 0);
    const isBalanced = Math.abs(liveDebit - liveCredit) < 0.01;

    const postableAccounts = accounts.filter(a => !a.isHeader && a.status === 'active');
    const accountOptions = postableAccounts.map(a => ({ value: a.id, label: `${a.accountCode} - ${a.name}`, searchText: `${a.accountCode} ${a.name}` }));

    const columns: any[] = [
        { title: 'Number', dataIndex: 'journalNumber', key: 'journalNumber', width: 140, render: (v: string, r: AcctJournal) => <Button type="link" onClick={() => viewDetail(r)} style={{ fontFamily: 'monospace', padding: 0 }}>{v}</Button> },
        { title: 'Date', dataIndex: 'journalDate', key: 'journalDate', width: 110, sorter: (a: any, b: any) => a.journalDate.localeCompare(b.journalDate) },
        { title: 'Type', dataIndex: 'journalType', key: 'journalType', width: 100, render: (v: string) => <Tag color={typeColor[v] || 'default'}>{v}</Tag> },
        { title: 'Reference', dataIndex: 'reference', key: 'reference', width: 130, ellipsis: true },
        { title: 'Memo', dataIndex: 'memo', key: 'memo', ellipsis: true },
        { title: 'Debit', dataIndex: 'totalDebit', key: 'totalDebit', width: 140, align: 'right' as const, render: (v: number) => <Text style={{ fontFamily: 'monospace' }}>{formatCurrency(v)}</Text> },
        { title: 'Credit', dataIndex: 'totalCredit', key: 'totalCredit', width: 140, align: 'right' as const, render: (v: number) => <Text style={{ fontFamily: 'monospace' }}>{formatCurrency(v)}</Text> },
        { title: 'Status', dataIndex: 'status', key: 'status', width: 100, render: (v: string) => <Tag color={statusColor[v]}>{v}</Tag> },
        { title: '', key: 'actions', width: 140, render: (_: any, r: AcctJournal) => (
            <Space size="small">
                <Tooltip title="View"><Button icon={<EyeOutlined />} size="small" type="text" onClick={() => viewDetail(r)} /></Tooltip>
                {r.status === 'draft' && <Popconfirm title="Post this journal? This action is irreversible." onConfirm={() => handlePost(r.id)}><Tooltip title="Post"><Button icon={<CheckCircleOutlined />} size="small" type="text" style={{ color: '#52c41a' }} /></Tooltip></Popconfirm>}
                {r.status === 'posted' && <Popconfirm title="Reverse this journal?" onConfirm={() => handleReverse(r.id)}><Tooltip title="Reverse"><Button icon={<UndoOutlined />} size="small" type="text" style={{ color: '#fa8c16' }} /></Tooltip></Popconfirm>}
                {r.status === 'draft' && <Popconfirm title="Delete this journal?" onConfirm={() => handleDelete(r.id)}><Tooltip title="Delete"><Button icon={<DeleteOutlined />} size="small" type="text" danger /></Tooltip></Popconfirm>}
            </Space>
        )},
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Journal Entries</AuroraText>}
            subTitle={<DecryptedText text={`${journals.length} entries recorded`} animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
                    style={{ background: `linear-gradient(135deg, ${themeColor}, var(--theme-secondary, #6366f1))`, border: 'none', borderRadius: 10 }}>New Journal Entry</Button>
            </div>

            <Card size="small" style={{ ...glass }}>
                <Space wrap>
                    <Input.Search placeholder="Search..." value={search} onChange={e => setSearch(e.target.value)} onSearch={() => load()} style={{ width: 240 }} allowClear />
                    <Select placeholder="Status" value={filterStatus} onChange={setFilterStatus} allowClear style={{ width: 130 }}
                        options={[{ value: 'draft', label: 'Draft' }, { value: 'posted', label: 'Posted' }, { value: 'reversed', label: 'Reversed' }]} />
                    <Select placeholder="Type" value={filterType} onChange={setFilterType} allowClear style={{ width: 130 }}
                        options={[{ value: 'general', label: 'General' }, { value: 'adjusting', label: 'Adjusting' }, { value: 'closing', label: 'Closing' }, { value: 'reversal', label: 'Reversal' }]} />
                    <RangePicker onChange={(dates) => setDateRange(dates ? [dates[0]!.format('YYYY-MM-DD'), dates[1]!.format('YYYY-MM-DD')] : null)} />
                    <Button icon={<ReloadOutlined />} onClick={load}>Refresh</Button>
                    <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'acct_journals', title: 'Journal Entries', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'journalNumber' }, { header: 'Date', key: 'journalDate' }, { header: 'Memo', key: 'memo' }, { header: 'Debit', key: 'totalDebit' }, { header: 'Credit', key: 'totalCredit' }, { header: 'Status', key: 'status' }], data: journals })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'acct_journals', title: 'Journal Entries', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'journalNumber' }, { header: 'Date', key: 'journalDate' }, { header: 'Memo', key: 'memo' }, { header: 'Debit', key: 'totalDebit' }, { header: 'Credit', key: 'totalCredit' }, { header: 'Status', key: 'status' }], data: journals })} /></Tooltip></RbacGuard>
                </Space>
            </Card>

            <Card style={{ ...glass }} styles={{ body: { padding: 0 } }}>
                <Table dataSource={journals.map(j => ({ ...j, key: j.id }))} columns={columns} loading={loading} size="small"
                    pagination={{ pageSize: 20, showSizeChanger: true, showTotal: (t) => `${t} entries` }}
                    scroll={{ x: 1100 }} locale={{ emptyText: <Empty description="No journal entries" /> }} />
            </Card>

            {/* â”€â”€â”€ Create Journal Drawer â”€â”€â”€ */}
            <Drawer title="New Journal Entry" open={createOpen} onClose={() => setCreateOpen(false)} width={800}
                extra={<Space><Button onClick={() => setCreateOpen(false)}>Cancel</Button><Button type="primary" onClick={handleCreate} disabled={!isBalanced}>Save</Button></Space>}>

                <Form form={form} layout="vertical" autoComplete="off">
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="journalType" label="Type"><Select options={[{ value: 'general', label: 'General' }, { value: 'adjusting', label: 'Adjusting' }]} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="journalDate" label="Date" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col>
                        <Col span={8}><Form.Item name="reference" label="Reference"><Input placeholder="e.g. INV-001" /></Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="currencyCode" label="Currency"><Select options={[{ value: 'IDR', label: 'IDR' }, { value: 'USD', label: 'USD' }, { value: 'EUR', label: 'EUR' }]} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="exchangeRate" label="Exchange Rate"><InputNumber style={{ width: '100%' }} min={0} precision={4} /></Form.Item></Col>
                        <Col span={8} />
                    </Row>
                    <Form.Item name="memo" label="Memo"><Input.TextArea rows={2} placeholder="Journal description..." /></Form.Item>

                    <Divider>Journal Lines</Divider>

                    {/* Balance indicator */}
                    <Alert type={isBalanced ? 'success' : 'error'} showIcon style={{ marginBottom: 16 }}
                        message={isBalanced
                            ? `Balanced â€” Debit: ${formatCurrency(liveDebit)} = Credit: ${formatCurrency(liveCredit)}`
                            : `Unbalanced â€” Debit: ${formatCurrency(liveDebit)} â‰  Credit: ${formatCurrency(liveCredit)} (Diff: ${formatCurrency(Math.abs(liveDebit - liveCredit))})`} />

                    <Form.List name="lines">
                        {(fields, { add, remove }) => (
                            <>
                                <div style={{ display: 'grid', gridTemplateColumns: '2fr 2fr 1fr 1fr 40px', gap: 8, marginBottom: 8, padding: '0 4px' }}>
                                    <Text strong style={{ fontSize: 12 }}>Account</Text>
                                    <Text strong style={{ fontSize: 12 }}>Description</Text>
                                    <Text strong style={{ fontSize: 12, textAlign: 'right' }}>Debit</Text>
                                    <Text strong style={{ fontSize: 12, textAlign: 'right' }}>Credit</Text>
                                    <div />
                                </div>
                                {fields.map(({ key, name, ...rest }) => (
                                    <div key={key} style={{ display: 'grid', gridTemplateColumns: '2fr 2fr 1fr 1fr 40px', gap: 8, marginBottom: 4, alignItems: 'start' }}>
                                        <Form.Item {...rest} name={[name, 'accountId']} rules={[{ required: true, message: '' }]} style={{ marginBottom: 0 }}>
                                            <Select showSearch placeholder="Select account" options={accountOptions} optionFilterProp="label"
                                                filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())} />
                                        </Form.Item>
                                        <Form.Item {...rest} name={[name, 'description']} style={{ marginBottom: 0 }}><Input placeholder="Line description" /></Form.Item>
                                        <Form.Item {...rest} name={[name, 'debit']} style={{ marginBottom: 0 }}><InputNumber style={{ width: '100%' }} min={0} precision={0} placeholder="0" /></Form.Item>
                                        <Form.Item {...rest} name={[name, 'credit']} style={{ marginBottom: 0 }}><InputNumber style={{ width: '100%' }} min={0} precision={0} placeholder="0" /></Form.Item>
                                        <Button icon={<MinusCircleOutlined />} type="text" danger onClick={() => remove(name)} disabled={fields.length <= 2} />
                                    </div>
                                ))}
                                <Button type="dashed" onClick={() => add({ accountId: undefined, description: '', debit: 0, credit: 0 })} icon={<PlusOutlined />} style={{ width: '100%', marginTop: 8 }}>Add Line</Button>
                            </>
                        )}
                    </Form.List>
                </Form>
            </Drawer>

            {/* â”€â”€â”€ Detail Drawer â”€â”€â”€ */}
            <Drawer title={selectedJournal ? `Journal: ${selectedJournal.journalNumber}` : 'Journal Detail'} open={detailOpen} onClose={() => setDetailOpen(false)} width={700}>
                {selectedJournal && (
                    <>
                        <Row gutter={[16, 12]}>
                            <Col span={8}><Text type="secondary">Number</Text><br /><Text strong style={{ fontFamily: 'monospace' }}>{selectedJournal.journalNumber}</Text></Col>
                            <Col span={8}><Text type="secondary">Date</Text><br /><Text>{selectedJournal.journalDate}</Text></Col>
                            <Col span={8}><Text type="secondary">Status</Text><br /><Tag color={statusColor[selectedJournal.status]}>{selectedJournal.status}</Tag></Col>
                            <Col span={8}><Text type="secondary">Type</Text><br /><Tag color={typeColor[selectedJournal.journalType]}>{selectedJournal.journalType}</Tag></Col>
                            <Col span={8}><Text type="secondary">Reference</Text><br /><Text>{selectedJournal.reference || '-'}</Text></Col>
                            <Col span={8}><Text type="secondary">Currency</Text><br /><Text>{selectedJournal.currencyCode} (rate: {selectedJournal.exchangeRate})</Text></Col>
                            <Col span={24}><Text type="secondary">Memo</Text><br /><Text>{selectedJournal.memo || '-'}</Text></Col>
                        </Row>
                        <Divider>Lines</Divider>
                        {detailLoading ? <Spin /> : (
                            <Table dataSource={journalLines.map(l => ({ ...l, key: l.id }))} size="small" pagination={false}
                                columns={[
                                    { title: '#', dataIndex: 'lineNumber', width: 40 },
                                    { title: 'Account', dataIndex: 'accountId', render: (id: string) => { const a = accountMap.get(id); return a ? `${a.accountCode} - ${a.name}` : id; } },
                                    { title: 'Description', dataIndex: 'description', ellipsis: true },
                                    { title: 'Debit', dataIndex: 'debit', width: 130, align: 'right' as const, render: (v: number) => v > 0 ? <Text style={{ fontFamily: 'monospace' }}>{formatCurrency(v)}</Text> : '' },
                                    { title: 'Credit', dataIndex: 'credit', width: 130, align: 'right' as const, render: (v: number) => v > 0 ? <Text style={{ fontFamily: 'monospace' }}>{formatCurrency(v)}</Text> : '' },
                                ]}
                                summary={() => (
                                    <Table.Summary.Row>
                                        <Table.Summary.Cell index={0} colSpan={3}><Text strong>Total</Text></Table.Summary.Cell>
                                        <Table.Summary.Cell index={1} align="right"><Text strong style={{ fontFamily: 'monospace' }}>{formatCurrency(selectedJournal.totalDebit)}</Text></Table.Summary.Cell>
                                        <Table.Summary.Cell index={2} align="right"><Text strong style={{ fontFamily: 'monospace' }}>{formatCurrency(selectedJournal.totalCredit)}</Text></Table.Summary.Cell>
                                    </Table.Summary.Row>
                                )} />
                        )}
                        {selectedJournal.status === 'draft' && (
                            <Space style={{ marginTop: 16 }}>
                                <Popconfirm title="Post this journal?" onConfirm={async () => { await handlePost(selectedJournal.id); setDetailOpen(false); }}>
                                    <Button type="primary" icon={<CheckCircleOutlined />}>Post Journal</Button>
                                </Popconfirm>
                                <Popconfirm title="Delete?" onConfirm={async () => { await handleDelete(selectedJournal.id); setDetailOpen(false); }}>
                                    <Button danger icon={<DeleteOutlined />}>Delete</Button>
                                </Popconfirm>
                            </Space>
                        )}
                        {selectedJournal.status === 'posted' && (
                            <Popconfirm title="Reverse this journal?" onConfirm={async () => { await handleReverse(selectedJournal.id); setDetailOpen(false); }}>
                                <Button icon={<UndoOutlined />} style={{ marginTop: 16 }}>Reverse Journal</Button>
                            </Popconfirm>
                        )}
                    </>
                )}
            </Drawer>
        </div>
        </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState, useMemo, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import RbacGuard from '@/components/common/RbacGuard';
import { Table, Select, DatePicker, Card, Typography, Space, Tag, Button, Spin, Empty, Row, Col, Statistic, Divider, Tooltip } from 'antd';
import { SearchOutlined, ReloadOutlined, DownloadOutlined, BookOutlined, FileExcelOutlined, FilePdfOutlined  } from '@ant-design/icons';
import { accountingService, AcctAccount, AcctJournalLine } from '@/lib/accountingService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import dayjs from 'dayjs';

const { Text } = Typography;
const { RangePicker } = DatePicker;
const formatCurrency = (v: number | string) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(Number(v) || 0);
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

// snake_case → camelCase
const snakeToCamel = (row: any) => {
    if (!row) return row;
    const out: any = {};
    for (const [k, v] of Object.entries(row)) {
        const camelKey = k.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
        out[camelKey] = typeof v === 'object' && v !== null && !Array.isArray(v) ? snakeToCamel(v) : v;
    }
    return out;
};

export default function GeneralLedgerPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [accounts, setAccounts] = useState<AcctAccount[]>([]);
    const [selectedAccountId, setSelectedAccountId] = useState<string | undefined>();
    const [dateRange, setDateRange] = useState<[string, string] | null>(null);
    const [lines, setLines] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [accountsLoading, setAccountsLoading] = useState(true);

    useEffect(() => {
        (async () => {
            try {
                const accts = await accountingService.getAccounts();
                setAccounts(accts);
            } catch (e) { console.error(e); }
            finally { setAccountsLoading(false); }
        })();
    }, []);

    const postableAccounts = useMemo(() =>
        accounts.filter(a => !a.isHeader && a.status === 'active')
            .map(a => ({ value: a.id, label: `${a.accountCode} - ${a.name}`, code: a.accountCode, name: a.name, type: a.accountType }))
            .sort((a, b) => a.code.localeCompare(b.code)),
    [accounts]);

    const selectedAccount = useMemo(() => accounts.find(a => a.id === selectedAccountId), [accounts, selectedAccountId]);

    const loadLedger = useCallback(async () => {
        if (!selectedAccountId) return;
        setLoading(true);
        try {
            const raw = await accountingService.getGeneralLedger(undefined, selectedAccountId, {
                dateFrom: dateRange?.[0], dateTo: dateRange?.[1],
            });
            // Convert and compute running balance
            const converted = raw.map((r: any) => snakeToCamel(r));
            const openingBalance = Number(selectedAccount?.openingBalance || 0);
            let running = openingBalance;
            const withBalance = converted.map((line: any) => {
                const d = Number(line.baseDebit || line.debit || 0);
                const c = Number(line.baseCredit || line.credit || 0);
                running += d - c;
                return { ...line, debitNum: d, creditNum: c, runningBalance: running };
            });
            setLines(withBalance);
        } catch (e: any) { console.error(e); setLines([]); }
        finally { setLoading(false); }
    }, [selectedAccountId, dateRange, selectedAccount]);

    useEffect(() => { if (selectedAccountId) loadLedger(); }, [selectedAccountId, loadLedger]);

    const totalDebit = lines.reduce((s, l) => s + l.debitNum, 0);
    const totalCredit = lines.reduce((s, l) => s + l.creditNum, 0);
    const openingBal = Number(selectedAccount?.openingBalance || 0);
    const closingBal = lines.length > 0 ? lines[lines.length - 1].runningBalance : openingBal;

    const exportCSV = () => {
        if (!lines.length || !selectedAccount) return;
        const header = 'Date,Journal,Description,Debit,Credit,Balance\n';
        const rows = lines.map(l => {
            const j = l.acctJournals || {};
            return `${j.journalDate || ''},${j.journalNumber || ''},"${(l.description || '').replace(/"/g, '""')}",${l.debitNum},${l.creditNum},${l.runningBalance}`;
        }).join('\n');
        const blob = new Blob([header + rows], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `ledger_${selectedAccount.accountCode}_${new Date().toISOString().slice(0, 10)}.csv`;
        a.click(); URL.revokeObjectURL(url);
    };

    const columns: any[] = [
        { title: 'Date', key: 'date', width: 110, render: (_: any, r: any) => r.acctJournals?.journalDate || '-' },
        { title: 'Journal #', key: 'journal', width: 140, render: (_: any, r: any) => <Text style={{ fontFamily: 'monospace' }}>{r.acctJournals?.journalNumber || '-'}</Text> },
        { title: 'Description', dataIndex: 'description', key: 'description', ellipsis: true, render: (v: string) => v || <Text type="secondary">-</Text> },
        { title: 'Debit', key: 'debit', width: 150, align: 'right' as const, render: (_: any, r: any) => r.debitNum > 0 ? <Text style={{ fontFamily: 'monospace', color: '#52c41a' }}>{formatCurrency(r.debitNum)}</Text> : '' },
        { title: 'Credit', key: 'credit', width: 150, align: 'right' as const, render: (_: any, r: any) => r.creditNum > 0 ? <Text style={{ fontFamily: 'monospace', color: '#ff4d4f' }}>{formatCurrency(r.creditNum)}</Text> : '' },
        { title: 'Balance', key: 'balance', width: 160, align: 'right' as const, render: (_: any, r: any) => <Text strong style={{ fontFamily: 'monospace' }}>{formatCurrency(r.runningBalance)}</Text> },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>General Ledger</AuroraText>}
            subTitle={<DecryptedText text="Account transaction history and balances" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                {lines.length > 0 && <Button icon={<DownloadOutlined />} onClick={exportCSV}>Export CSV</Button>}
            </div>

            {/* Filters */}
            <Card size="small" style={{ ...glass }}>
                <Space wrap size="middle">
                    <div>
                        <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>Account</Text>
                        <Select
                            showSearch placeholder="Select an account..." value={selectedAccountId} onChange={setSelectedAccountId}
                            style={{ width: 360 }} loading={accountsLoading} optionFilterProp="label" options={postableAccounts}
                            filterOption={(input, opt) => (opt?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                        />
                    </div>
                    <div>
                        <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>Date Range</Text>
                        <RangePicker onChange={(dates) => setDateRange(dates ? [dates[0]!.format('YYYY-MM-DD'), dates[1]!.format('YYYY-MM-DD')] : null)}
                            presets={[
                                { label: 'This Month', value: [dayjs().startOf('month'), dayjs()] },
                                { label: 'Last Month', value: [dayjs().subtract(1, 'month').startOf('month'), dayjs().subtract(1, 'month').endOf('month')] },
                                { label: 'Last 3 Months', value: [dayjs().subtract(3, 'month').startOf('month'), dayjs()] },
                                { label: 'This Year', value: [dayjs().startOf('year'), dayjs()] },
                            ]}
                        />
                    </div>
                    <div style={{ paddingTop: 20 }}>
                        <Button icon={<ReloadOutlined />} onClick={loadLedger} disabled={!selectedAccountId}>Refresh</Button>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'acct_ledger', title: 'General Ledger', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Code', key: 'code' }, { header: 'Name', key: 'name' }, { header: 'Type', key: 'accountType' }, { header: 'Balance', key: 'balance' }], data: accounts })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'acct_ledger', title: 'General Ledger', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Code', key: 'code' }, { header: 'Name', key: 'name' }, { header: 'Type', key: 'accountType' }, { header: 'Balance', key: 'balance' }], data: accounts })} /></Tooltip></RbacGuard>
                    </div>
                </Space>
            </Card>

            {!selectedAccountId ? (
                <Card style={{ borderRadius: 12, textAlign: 'center', padding: 40 }}>
                    <BookOutlined style={{ fontSize: 48, color: '#8c8c8c', marginBottom: 16 }} />
                    <br /><Text type="secondary" style={{ fontSize: 16 }}>Select an account above to view its transaction history</Text>
                </Card>
            ) : (
                <>
                    {/* Account info + summary */}
                    {selectedAccount && (
                        <Row gutter={[14, 14]}>
                            {[
                                { t: 'Opening Balance', v: openingBal, c: '#3b82f6' },
                                { t: 'Total Debit', v: totalDebit, c: '#10b981' },
                                { t: 'Total Credit', v: totalCredit, c: '#ef4444' },
                                { t: 'Closing Balance', v: closingBal, c: '#8b5cf6' },
                            ].map((s, i) => (
                                <Col xs={24} sm={6} key={i}>
                                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                                        <Card size="small" style={{ ...glass }}>
                                            <Statistic title={s.t} value={s.v} formatter={(v) => formatCurrency(Number(v))} valueStyle={{ fontSize: 16, fontWeight: 600, color: s.c, fontFamily: 'monospace' }} />
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </Row>
                    )}

                    {/* Transaction table */}
                    <Card style={{ borderRadius: 12 }} bodyStyle={{ padding: 0 }}>
                        <Table scroll={{ x: 900 }} dataSource={lines.map((l, i) => ({ ...l, key: l.id || i }))} columns={columns} loading={loading}
                            size="small" pagination={{ pageSize: 50, showSizeChanger: true, showTotal: (t) => `${t} transactions` }}
                            locale={{ emptyText: <Empty description="No transactions found for this account" /> }}
                            summary={() => lines.length > 0 ? (
                                <Table.Summary.Row>
                                    <Table.Summary.Cell index={0} colSpan={3}><Text strong>Totals</Text></Table.Summary.Cell>
                                    <Table.Summary.Cell index={1} align="right"><Text strong style={{ fontFamily: 'monospace', color: '#52c41a' }}>{formatCurrency(totalDebit)}</Text></Table.Summary.Cell>
                                    <Table.Summary.Cell index={2} align="right"><Text strong style={{ fontFamily: 'monospace', color: '#ff4d4f' }}>{formatCurrency(totalCredit)}</Text></Table.Summary.Cell>
                                    <Table.Summary.Cell index={3} align="right"><Text strong style={{ fontFamily: 'monospace', color: '#722ed1' }}>{formatCurrency(closingBal)}</Text></Table.Summary.Cell>
                                </Table.Summary.Row>
                            ) : undefined}
                        />
                    </Card>
                </>
            )}
        </div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import RbacGuard from '@/components/common/RbacGuard';
import { Table, Card, Typography, Space, Tag, Button, Input, Select, Row, Col, Statistic, Empty, Modal, Descriptions, Progress, message, Popconfirm, InputNumber, DatePicker, Form, Divider, Tooltip } from 'antd';
import { SearchOutlined, ReloadOutlined, PlusOutlined, EyeOutlined, DollarOutlined, DeleteOutlined, MinusCircleOutlined, WarningOutlined, CheckCircleOutlined, SendOutlined, FileExcelOutlined, FilePdfOutlined  } from '@ant-design/icons';
import { accountingService, AcctInvoice, AcctInvoiceSummary, AcctInvoiceLine, AcctContact, AcctAccount } from '@/lib/accountingService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import dayjs from 'dayjs';

const { Text } = Typography;
const formatCurrency = (v: number | string) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(Number(v) || 0);
const fmtShort = (v: number) => { if (Math.abs(v) >= 1e9) return `${(v/1e9).toFixed(1)}B`; if (Math.abs(v) >= 1e6) return `${(v/1e6).toFixed(0)}M`; if (Math.abs(v) >= 1e3) return `${(v/1e3).toFixed(0)}K`; return String(Math.round(v)); };

const statusColor: Record<string, string> = { draft: 'default', sent: 'blue', partial: 'orange', paid: 'green', overdue: 'red', cancelled: 'default' };
const statusIcon: Record<string, React.ReactNode> = { paid: <CheckCircleOutlined />, overdue: <WarningOutlined /> };
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

// ─── Aging Stacked Bar ──────────────────────────────────
function AgingBar({ summary }: { summary: AcctInvoiceSummary }) {
    const buckets = [
        { value: summary.current || 0, color: '#10b981', label: 'Current' },
        { value: summary.aging30 || 0, color: '#f59e0b', label: '1-30d' },
        { value: summary.aging60 || 0, color: '#f97316', label: '31-60d' },
        { value: summary.aging90 || 0, color: '#ef4444', label: '61-90d' },
        { value: summary.aging90plus || 0, color: '#991b1b', label: '90+d' },
    ].filter(b => b.value > 0);
    const total = buckets.reduce((s, b) => s + b.value, 0);
    if (total === 0) return null;
    return (
        <div>
            <div style={{ display: 'flex', borderRadius: 6, overflow: 'hidden', height: 10, marginBottom: 10 }}>
                {buckets.map((b, i) => (
                    <Tooltip key={i} title={`${b.label}: ${formatCurrency(b.value)}`}>
                        <div style={{ width: `${(b.value / total) * 100}%`, background: b.color, transition: 'width 0.6s ease' }} />
                    </Tooltip>
                ))}
            </div>
            <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap' }}>
                {buckets.map((b, i) => (
                    <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11 }}>
                        <span style={{ width: 8, height: 8, borderRadius: 2, background: b.color }} />
                        <Text type="secondary" style={{ fontSize: 11 }}>{b.label}</Text>
                        <Text strong style={{ fontSize: 11, fontFamily: 'monospace' }}>{fmtShort(b.value)}</Text>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default function AccountsPayablePage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [invoices, setInvoices] = useState<AcctInvoice[]>([]);
    const [summary, setSummary] = useState<AcctInvoiceSummary | null>(null);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [detailModal, setDetailModal] = useState<AcctInvoice | null>(null);
    const [detailLines, setDetailLines] = useState<AcctInvoiceLine[]>([]);
    const [paymentModal, setPaymentModal] = useState<AcctInvoice | null>(null);
    const [paymentAmount, setPaymentAmount] = useState<number>(0);
    const [createOpen, setCreateOpen] = useState(false);
    const [createLoading, setCreateLoading] = useState(false);
    const [contacts, setContacts] = useState<AcctContact[]>([]);
    const [accounts, setAccounts] = useState<AcctAccount[]>([]);
    const [form] = Form.useForm();
    const [lines, setLines] = useState<{ description: string; quantity: number; unitPrice: number }[]>([{ description: '', quantity: 1, unitPrice: 0 }]);

    const load = async () => {
        setLoading(true);
        try {
            const [inv, sum] = await Promise.all([
                accountingService.getInvoices(undefined, { invoiceType: 'payable', status: statusFilter, search: search || undefined }),
                accountingService.getInvoiceSummary(undefined, 'payable'),
            ]);
            setInvoices(inv); setSummary(sum);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };
    useEffect(() => { load(); }, [statusFilter]);

    const openDetail = async (inv: AcctInvoice) => {
        setDetailModal(inv);
        try { setDetailLines(await accountingService.getInvoiceLines(inv.id)); } catch { setDetailLines([]); }
    };

    const handlePayment = async () => {
        if (!paymentModal || paymentAmount <= 0) return;
        try {
            await accountingService.recordPayment(paymentModal.id, paymentAmount);
            message.success('Payment recorded');
            setPaymentModal(null); setPaymentAmount(0); load();
        } catch (e: any) { message.error(e.message); }
    };

    const handleDelete = async (id: string) => {
        try { await accountingService.deleteInvoice(id); message.success('Bill deleted'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    const handleSend = async (id: string) => {
        try { await accountingService.updateInvoiceStatus(id, 'sent'); message.success('Bill marked as sent'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    const openCreate = async () => {
        setCreateOpen(true);
        try {
            const [c, a] = await Promise.all([
                accountingService.getContacts(undefined, { contactType: 'vendor' }),
                accountingService.getAccounts(),
            ]);
            setContacts(c); setAccounts(a.filter(acc => !acc.isHeader));
        } catch (e) { console.error(e); }
    };

    const handleCreate = async () => {
        try {
            const vals = await form.validateFields();
            setCreateLoading(true);
            const contact = contacts.find(c => c.id === vals.contactId);
            const invoiceLines = lines.filter(l => l.description).map(l => ({ description: l.description, quantity: l.quantity, unitPrice: l.unitPrice, amount: l.quantity * l.unitPrice }));
            const apAccount = accounts.find(a => a.accountCode === '2110');
            await accountingService.createInvoice(undefined, {
                invoiceType: 'payable', contactId: vals.contactId, contactName: contact?.name || '',
                invoiceDate: vals.invoiceDate?.format('YYYY-MM-DD') || dayjs().format('YYYY-MM-DD'),
                dueDate: vals.dueDate.format('YYYY-MM-DD'), reference: vals.reference || undefined,
                notes: vals.notes || undefined, accountId: apAccount?.id, status: 'draft', lines: invoiceLines,
            } as any);
            message.success('Bill created');
            setCreateOpen(false); form.resetFields(); setLines([{ description: '', quantity: 1, unitPrice: 0 }]); load();
        } catch (e: any) { if (e.message) message.error(e.message); }
        finally { setCreateLoading(false); }
    };

    const lineTotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);

    const columns: any[] = [
        { title: 'Bill #', dataIndex: 'invoiceNumber', width: 150, render: (v: string) => <Text strong style={{ fontFamily: 'monospace' }}>{v}</Text> },
        { title: 'Vendor', dataIndex: 'contactName', ellipsis: true },
        { title: 'Date', dataIndex: 'invoiceDate', width: 110 },
        { title: 'Due Date', dataIndex: 'dueDate', width: 110, render: (v: string, r: AcctInvoice) => { const d = new Date(v); const isOverdue = d < new Date() && Number(r.amountDue) > 0; return <Text type={isOverdue ? 'danger' : undefined}>{v}</Text>; } },
        { title: 'Total', dataIndex: 'totalAmount', width: 160, align: 'right' as const, render: (v: number) => <Text style={{ fontFamily: 'monospace' }}>{formatCurrency(v)}</Text> },
        { title: 'Paid', dataIndex: 'amountPaid', width: 160, align: 'right' as const, render: (v: number) => Number(v) > 0 ? <Text style={{ fontFamily: 'monospace', color: '#10b981' }}>{formatCurrency(v)}</Text> : '' },
        { title: 'Due', dataIndex: 'amountDue', width: 160, align: 'right' as const, render: (v: number) => Number(v) > 0 ? <Text strong style={{ fontFamily: 'monospace', color: '#ef4444' }}>{formatCurrency(v)}</Text> : <Tag color="green">Paid</Tag> },
        { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color={statusColor[v]} icon={statusIcon[v]}>{v}</Tag> },
        { title: '', width: 140, render: (_: any, r: AcctInvoice) => (
            <Space size="small">
                <Button type="text" size="small" icon={<EyeOutlined />} onClick={() => openDetail(r)} />
                {r.status === 'draft' && <Button type="text" size="small" icon={<SendOutlined />} onClick={() => handleSend(r.id)} />}
                {Number(r.amountDue) > 0 && r.status !== 'draft' && <Button type="text" size="small" icon={<DollarOutlined />} onClick={() => { setPaymentModal(r); setPaymentAmount(Number(r.amountDue)); }} />}
                {r.status === 'draft' && <Popconfirm title="Delete?" onConfirm={() => handleDelete(r.id)}><Button type="text" size="small" danger icon={<DeleteOutlined />} /></Popconfirm>}
            </Space>
        ) },
    ];

    const summaryCards = summary ? [
        { title: 'Total Bills', value: summary.totalInvoices, color: '#3b82f6', prefix: undefined, formatter: undefined },
        { title: 'Outstanding', value: summary.totalOutstanding, color: '#f59e0b', prefix: undefined, formatter: (v: any) => formatCurrency(Number(v)) },
        { title: 'Overdue', value: summary.overdue, color: '#ef4444', prefix: undefined, formatter: (v: any) => formatCurrency(Number(v)) },
        { title: 'Current', value: summary.current, color: '#10b981', prefix: undefined, formatter: (v: any) => formatCurrency(Number(v)) },
    ] : [];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Accounts Payable</AuroraText>}
            subTitle={<DecryptedText text="Manage vendor bills and track payments" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
                    style={{ background: `linear-gradient(135deg, ${themeColor}, var(--theme-secondary, #6366f1))`, border: 'none', borderRadius: 10 }}>Create Bill</Button>
            </div>

            {/* Summary Cards */}
            {summary && (
                <Row gutter={[12, 12]}>
                    {summaryCards.map((card, i) => (
                        <Col xs={12} sm={6} key={i}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                                <Card size="small" style={{ ...glass }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                                        <div style={{ width: 40, height: 40, borderRadius: 10, background: `${card.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                            <Text strong style={{ color: card.color, fontSize: card.formatter ? 14 : 20, fontFamily: 'monospace' }}>
                                                {card.formatter ? fmtShort(Number(card.value)) : card.value}
                                            </Text>
                                        </div>
                                        <div>
                                            <Text type="secondary" style={{ fontSize: 11, display: 'block' }}>{card.title}</Text>
                                            <Text strong style={{ fontSize: card.formatter ? 15 : 22, color: card.color, fontFamily: 'monospace' }}>
                                                {card.formatter ? formatCurrency(Number(card.value)) : card.value}
                                            </Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>
            )}

            {/* Aging Report */}
            {summary && summary.totalOutstanding > 0 && (
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                    <Card size="small" style={{ ...glass }}>
                        <Text strong style={{ marginBottom: 10, display: 'block', fontSize: 13 }}>Aging Report</Text>
                        <AgingBar summary={summary} />
                    </Card>
                </motion.div>
            )}

            {/* Filters */}
            <Card size="small" style={{ ...glass }}>
                <Space wrap>
                    <Input placeholder="Search bills..." prefix={<SearchOutlined style={{ opacity: 0.4 }} />} value={search} onChange={e => setSearch(e.target.value)} onPressEnter={load} style={{ width: 260, borderRadius: 8 }} allowClear />
                    <Select placeholder="Status" value={statusFilter} onChange={setStatusFilter} allowClear style={{ width: 140 }} options={[{ value: 'draft', label: 'Draft' }, { value: 'sent', label: 'Sent' }, { value: 'partial', label: 'Partial' }, { value: 'paid', label: 'Paid' }]} />
                    <Button icon={<ReloadOutlined />} onClick={load}>Refresh</Button>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'acct_payables', title: 'Accounts Payable', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Invoice #', key: 'invoiceNumber' }, { header: 'Vendor', key: 'contactName' }, { header: 'Amount', key: 'totalAmount' }, { header: 'Status', key: 'status' }], data: invoices })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'acct_payables', title: 'Accounts Payable', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Invoice #', key: 'invoiceNumber' }, { header: 'Vendor', key: 'contactName' }, { header: 'Amount', key: 'totalAmount' }, { header: 'Status', key: 'status' }], data: invoices })} /></Tooltip></RbacGuard>
                </Space>
            </Card>

            {/* Table */}
            <Card style={{ ...glass }} styles={{ body: { padding: 0 } }}>
                <Table scroll={{ x: 900 }} dataSource={invoices.map(i => ({ ...i, key: i.id }))} columns={columns} loading={loading} size="small"
                    pagination={{ pageSize: 20, showTotal: t => `${t} bills` }}
                    locale={{ emptyText: <Empty description="No vendor bills found" /> }}
                />
            </Card>

            {/* Detail Modal */}
            <Modal title={`Bill: ${detailModal?.invoiceNumber}`} open={!!detailModal} onCancel={() => setDetailModal(null)} footer={null} width={700}>
                {detailModal && (
                    <>
                        <Descriptions column={2} size="small" bordered style={{ marginBottom: 16 }}>
                            <Descriptions.Item label="Vendor">{detailModal.contactName}</Descriptions.Item>
                            <Descriptions.Item label="Status"><Tag color={statusColor[detailModal.status]}>{detailModal.status}</Tag></Descriptions.Item>
                            <Descriptions.Item label="Invoice Date">{detailModal.invoiceDate}</Descriptions.Item>
                            <Descriptions.Item label="Due Date">{detailModal.dueDate}</Descriptions.Item>
                            <Descriptions.Item label="Reference">{detailModal.reference || '-'}</Descriptions.Item>
                            <Descriptions.Item label="Currency">{detailModal.currencyCode}</Descriptions.Item>
                            <Descriptions.Item label="Subtotal">{formatCurrency(detailModal.subtotal)}</Descriptions.Item>
                            <Descriptions.Item label="Tax">{formatCurrency(detailModal.taxAmount)}</Descriptions.Item>
                            <Descriptions.Item label="Total">{formatCurrency(detailModal.totalAmount)}</Descriptions.Item>
                            <Descriptions.Item label="Paid">{formatCurrency(detailModal.amountPaid)}</Descriptions.Item>
                            <Descriptions.Item label="Amount Due" span={2}><Text strong style={{ color: Number(detailModal.amountDue) > 0 ? '#ef4444' : '#10b981', fontSize: 16 }}>{formatCurrency(detailModal.amountDue)}</Text></Descriptions.Item>
                        </Descriptions>
                        {detailModal.notes && <Card size="small" style={{ marginBottom: 16 }}><Text type="secondary">Notes: </Text>{detailModal.notes}</Card>}
                        <Text strong>Line Items</Text>
                        <Table scroll={{ x: 900 }} dataSource={detailLines.map(l => ({ ...l, key: l.id }))} size="small" pagination={false} style={{ marginTop: 8 }}
                            columns={[
                                { title: '#', dataIndex: 'lineNumber', width: 40 },
                                { title: 'Description', dataIndex: 'description' },
                                { title: 'Qty', dataIndex: 'quantity', width: 60, align: 'right' as const, render: (v: number) => Number(v) },
                                { title: 'Price', dataIndex: 'unitPrice', width: 140, align: 'right' as const, render: (v: number) => formatCurrency(v) },
                                { title: 'Amount', dataIndex: 'amount', width: 160, align: 'right' as const, render: (v: number) => <Text strong>{formatCurrency(v)}</Text> },
                            ]}
                        />
                        {Number(detailModal.totalAmount) > 0 && (
                            <Progress percent={Math.round((Number(detailModal.amountPaid) / Number(detailModal.totalAmount)) * 100)} status={detailModal.status === 'paid' ? 'success' : 'active'} style={{ marginTop: 12 }} />
                        )}
                    </>
                )}
            </Modal>

            {/* Payment Modal */}
            <Modal title={`Record Payment — ${paymentModal?.invoiceNumber}`} open={!!paymentModal} onOk={handlePayment} onCancel={() => setPaymentModal(null)} okText="Record Payment">
                {paymentModal && (
                    <div style={{ padding: '16px 0' }}>
                        <Text type="secondary">Amount Due: </Text><Text strong style={{ color: '#ef4444' }}>{formatCurrency(paymentModal.amountDue)}</Text>
                        <br /><br />
                        <Text>Payment Amount:</Text>
                        <InputNumber value={paymentAmount} onChange={v => setPaymentAmount(v || 0)} style={{ width: '100%', marginTop: 8 }}
                            formatter={v => `Rp ${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, '.')} parser={v => Number((v || '').replace(/Rp\s?|(\.)/g, ''))}
                            min={0} max={Number(paymentModal.amountDue)}
                        />
                    </div>
                )}
            </Modal>

            {/* Create Bill Modal */}
            <Modal title="Create New Bill" open={createOpen} onOk={handleCreate} onCancel={() => setCreateOpen(false)} okText="Create Bill" width={720} confirmLoading={createLoading} destroyOnClose>
                <Form form={form} layout="vertical" size="small" initialValues={{ invoiceDate: dayjs(), dueDate: dayjs().add(30, 'day') }}>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="contactId" label="Vendor" rules={[{ required: true }]}><Select showSearch placeholder="Select vendor" optionFilterProp="label" options={contacts.map(c => ({ value: c.id, label: `${c.code ? c.code+' — ' : ''}${c.name}` }))} /></Form.Item></Col>
                        <Col span={12}><Form.Item name="reference" label="Reference / PO #"><Input placeholder="PO-2026-XXX" /></Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="invoiceDate" label="Bill Date" rules={[{ required: true }]}><DatePicker style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={12}><Form.Item name="dueDate" label="Due Date" rules={[{ required: true }]}><DatePicker style={{ width: '100%' }} /></Form.Item></Col>
                    </Row>
                    <Form.Item name="notes" label="Notes"><Input.TextArea rows={2} placeholder="Additional notes..." /></Form.Item>
                </Form>
                <Divider style={{ margin: '8px 0 12px' }}>Line Items</Divider>
                <div style={{ marginBottom: 8 }}>
                    <Row gutter={8} style={{ marginBottom: 4 }}>
                        <Col span={10}><Text type="secondary" style={{ fontSize: 11 }}>Description</Text></Col>
                        <Col span={4}><Text type="secondary" style={{ fontSize: 11 }}>Qty</Text></Col>
                        <Col span={5}><Text type="secondary" style={{ fontSize: 11 }}>Unit Price</Text></Col>
                        <Col span={4}><Text type="secondary" style={{ fontSize: 11 }}>Amount</Text></Col>
                        <Col span={1} />
                    </Row>
                    {lines.map((line, i) => (
                        <Row gutter={8} key={i} style={{ marginBottom: 6 }}>
                            <Col span={10}><Input value={line.description} onChange={e => { const n = [...lines]; n[i].description = e.target.value; setLines(n); }} placeholder="Description" size="small" /></Col>
                            <Col span={4}><InputNumber value={line.quantity} onChange={v => { const n = [...lines]; n[i].quantity = v || 1; setLines(n); }} min={1} style={{ width: '100%' }} size="small" /></Col>
                            <Col span={5}><InputNumber value={line.unitPrice} onChange={v => { const n = [...lines]; n[i].unitPrice = v || 0; setLines(n); }} min={0} style={{ width: '100%' }} size="small" formatter={v => `${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, '.')} parser={v => Number((v || '').replace(/\./g, ''))} /></Col>
                            <Col span={4}><Text strong style={{ lineHeight: '30px', fontFamily: 'monospace', fontSize: 12 }}>{formatCurrency(line.quantity * line.unitPrice)}</Text></Col>
                            <Col span={1}>{lines.length > 1 && <Button type="text" size="small" danger icon={<MinusCircleOutlined />} onClick={() => setLines(lines.filter((_, j) => j !== i))} />}</Col>
                        </Row>
                    ))}
                    <Button type="dashed" size="small" icon={<PlusOutlined />} onClick={() => setLines([...lines, { description: '', quantity: 1, unitPrice: 0 }])} style={{ width: '100%', marginTop: 4 }}>Add Line</Button>
                </div>
                <div style={{ textAlign: 'right', marginTop: 12, padding: '10px 14px', background: `${themeColor}08`, borderRadius: 10 }}>
                    <Text type="secondary">Total: </Text><Text strong style={{ fontSize: 18, fontFamily: 'monospace' }}>{formatCurrency(lineTotal)}</Text>
                </div>
            </Modal>
        </div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import RbacGuard from '@/components/common/RbacGuard';
import { Table, Card, Typography, Space, Tag, Button, Input, Select, Row, Col, Empty, Modal, Descriptions, Progress, message, Popconfirm, InputNumber, DatePicker, Form, Divider, Tooltip } from 'antd';
import { SearchOutlined, ReloadOutlined, EyeOutlined, DollarOutlined, DeleteOutlined, WarningOutlined, CheckCircleOutlined, PlusOutlined, MinusCircleOutlined, SendOutlined, FileExcelOutlined, FilePdfOutlined  } from '@ant-design/icons';
import { accountingService, AcctInvoice, AcctInvoiceSummary, AcctInvoiceLine, AcctContact, AcctAccount } from '@/lib/accountingService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import dayjs from 'dayjs';

const { Text } = Typography;
const formatCurrency = (v: number | string) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(Number(v) || 0);
const fmtShort = (v: number) => { if (Math.abs(v) >= 1e9) return `${(v/1e9).toFixed(1)}B`; if (Math.abs(v) >= 1e6) return `${(v/1e6).toFixed(0)}M`; if (Math.abs(v) >= 1e3) return `${(v/1e3).toFixed(0)}K`; return String(Math.round(v)); };

const statusColor: Record<string, string> = { draft: 'default', sent: 'blue', partial: 'orange', paid: 'green', overdue: 'red', cancelled: 'default' };
const statusIcon: Record<string, React.ReactNode> = { paid: <CheckCircleOutlined />, overdue: <WarningOutlined /> };
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

function AgingBar({ summary }: { summary: AcctInvoiceSummary }) {
    const buckets = [
        { value: summary.current || 0, color: '#10b981', label: 'Current' },
        { value: summary.aging30 || 0, color: '#f59e0b', label: '1-30d' },
        { value: summary.aging60 || 0, color: '#f97316', label: '31-60d' },
        { value: summary.aging90 || 0, color: '#ef4444', label: '61-90d' },
        { value: summary.aging90plus || 0, color: '#991b1b', label: '90+d' },
    ].filter(b => b.value > 0);
    const total = buckets.reduce((s, b) => s + b.value, 0);
    if (total === 0) return null;
    return (
        <div>
            <div style={{ display: 'flex', borderRadius: 6, overflow: 'hidden', height: 10, marginBottom: 10 }}>
                {buckets.map((b, i) => (
                    <Tooltip key={i} title={`${b.label}: ${formatCurrency(b.value)}`}>
                        <div style={{ width: `${(b.value / total) * 100}%`, background: b.color, transition: 'width 0.6s ease' }} />
                    </Tooltip>
                ))}
            </div>
            <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap' }}>
                {buckets.map((b, i) => (
                    <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11 }}>
                        <span style={{ width: 8, height: 8, borderRadius: 2, background: b.color }} />
                        <Text type="secondary" style={{ fontSize: 11 }}>{b.label}</Text>
                        <Text strong style={{ fontSize: 11, fontFamily: 'monospace' }}>{fmtShort(b.value)}</Text>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default function AccountsReceivablePage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [invoices, setInvoices] = useState<AcctInvoice[]>([]);
    const [summary, setSummary] = useState<AcctInvoiceSummary | null>(null);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [detailModal, setDetailModal] = useState<AcctInvoice | null>(null);
    const [detailLines, setDetailLines] = useState<AcctInvoiceLine[]>([]);
    const [paymentModal, setPaymentModal] = useState<AcctInvoice | null>(null);
    const [paymentAmount, setPaymentAmount] = useState<number>(0);
    const [createOpen, setCreateOpen] = useState(false);
    const [createLoading, setCreateLoading] = useState(false);
    const [contacts, setContacts] = useState<AcctContact[]>([]);
    const [accounts, setAccounts] = useState<AcctAccount[]>([]);
    const [form] = Form.useForm();
    const [lines, setLines] = useState<{ description: string; quantity: number; unitPrice: number }[]>([{ description: '', quantity: 1, unitPrice: 0 }]);

    const load = async () => {
        setLoading(true);
        try {
            const [inv, sum] = await Promise.all([
                accountingService.getInvoices(undefined, { invoiceType: 'receivable', status: statusFilter, search: search || undefined }),
                accountingService.getInvoiceSummary(undefined, 'receivable'),
            ]);
            setInvoices(inv); setSummary(sum);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };
    useEffect(() => { load(); }, [statusFilter]);

    const openDetail = async (inv: AcctInvoice) => {
        setDetailModal(inv);
        try { setDetailLines(await accountingService.getInvoiceLines(inv.id)); } catch { setDetailLines([]); }
    };

    const handlePayment = async () => {
        if (!paymentModal || paymentAmount <= 0) return;
        try {
            await accountingService.recordPayment(paymentModal.id, paymentAmount);
            message.success('Payment received');
            setPaymentModal(null); setPaymentAmount(0); load();
        } catch (e: any) { message.error(e.message); }
    };

    const handleSend = async (id: string) => {
        try { await accountingService.updateInvoiceStatus(id, 'sent'); message.success('Invoice sent'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    const handleDelete = async (id: string) => {
        try { await accountingService.deleteInvoice(id); message.success('Invoice deleted'); load(); }
        catch (e: any) { message.error(e.message); }
    };

    const openCreate = async () => {
        setCreateOpen(true);
        try {
            const [c, a] = await Promise.all([
                accountingService.getContacts(undefined, { contactType: 'customer' }),
                accountingService.getAccounts(),
            ]);
            setContacts(c); setAccounts(a.filter(acc => !acc.isHeader));
        } catch (e) { console.error(e); }
    };

    const handleCreate = async () => {
        try {
            const vals = await form.validateFields();
            setCreateLoading(true);
            const contact = contacts.find(c => c.id === vals.contactId);
            const invoiceLines = lines.filter(l => l.description).map(l => ({ description: l.description, quantity: l.quantity, unitPrice: l.unitPrice, amount: l.quantity * l.unitPrice }));
            const arAccount = accounts.find(a => a.accountCode === '1210');
            await accountingService.createInvoice(undefined, {
                invoiceType: 'receivable', contactId: vals.contactId, contactName: contact?.name || '',
                invoiceDate: vals.invoiceDate?.format('YYYY-MM-DD') || dayjs().format('YYYY-MM-DD'),
                dueDate: vals.dueDate.format('YYYY-MM-DD'), reference: vals.reference || undefined,
                notes: vals.notes || undefined, accountId: arAccount?.id, status: 'draft', lines: invoiceLines,
            } as any);
            message.success('Invoice created');
            setCreateOpen(false); form.resetFields(); setLines([{ description: '', quantity: 1, unitPrice: 0 }]); load();
        } catch (e: any) { if (e.message) message.error(e.message); }
        finally { setCreateLoading(false); }
    };

    const lineTotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);

    const columns: any[] = [
        { title: 'Invoice #', dataIndex: 'invoiceNumber', width: 150, render: (v: string) => <Text strong style={{ fontFamily: 'monospace' }}>{v}</Text> },
        { title: 'Customer', dataIndex: 'contactName', ellipsis: true },
        { title: 'Date', dataIndex: 'invoiceDate', width: 110 },
        { title: 'Due Date', dataIndex: 'dueDate', width: 110, render: (v: string, r: AcctInvoice) => { const isOverdue = new Date(v) < new Date() && Number(r.amountDue) > 0; return <Text type={isOverdue ? 'danger' : undefined}>{v}</Text>; } },
        { title: 'Total', dataIndex: 'totalAmount', width: 160, align: 'right' as const, render: (v: number) => <Text style={{ fontFamily: 'monospace' }}>{formatCurrency(v)}</Text> },
        { title: 'Received', dataIndex: 'amountPaid', width: 160, align: 'right' as const, render: (v: number) => Number(v) > 0 ? <Text style={{ fontFamily: 'monospace', color: '#10b981' }}>{formatCurrency(v)}</Text> : '' },
        { title: 'Outstanding', dataIndex: 'amountDue', width: 160, align: 'right' as const, render: (v: number) => Number(v) > 0 ? <Text strong style={{ fontFamily: 'monospace', color: '#3b82f6' }}>{formatCurrency(v)}</Text> : <Tag color="green">Paid</Tag> },
        { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color={statusColor[v]} icon={statusIcon[v]}>{v}</Tag> },
        { title: '', width: 160, render: (_: any, r: AcctInvoice) => (
            <Space size="small">
                <Button type="text" size="small" icon={<EyeOutlined />} onClick={() => openDetail(r)} />
                {r.status === 'draft' && <Button type="text" size="small" onClick={() => handleSend(r.id)}>Send</Button>}
                {Number(r.amountDue) > 0 && r.status !== 'draft' && <Button type="text" size="small" icon={<DollarOutlined />} onClick={() => { setPaymentModal(r); setPaymentAmount(Number(r.amountDue)); }} />}
                {r.status === 'draft' && <Popconfirm title="Delete?" onConfirm={() => handleDelete(r.id)}><Button type="text" size="small" danger icon={<DeleteOutlined />} /></Popconfirm>}
            </Space>
        ) },
    ];

    const summaryCards = summary ? [
        { title: 'Total Invoices', value: summary.totalInvoices, color: '#3b82f6', isCount: true },
        { title: 'Outstanding', value: summary.totalOutstanding, color: '#8b5cf6', isCount: false },
        { title: 'Overdue', value: summary.overdue, color: '#ef4444', isCount: false },
        { title: 'Current', value: summary.current, color: '#10b981', isCount: false },
    ] : [];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Accounts Receivable</AuroraText>}
            subTitle={<DecryptedText text="Manage customer invoices and track collections" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
                    style={{ background: `linear-gradient(135deg, ${themeColor}, var(--theme-secondary, #6366f1))`, border: 'none', borderRadius: 10 }}>Create Invoice</Button>
            </div>

            {summary && (
                <Row gutter={[12, 12]}>
                    {summaryCards.map((card, i) => (
                        <Col xs={12} sm={6} key={i}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                                <Card size="small" style={{ ...glass }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                                        <div style={{ width: 40, height: 40, borderRadius: 10, background: `${card.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                            <Text strong style={{ color: card.color, fontSize: card.isCount ? 20 : 14, fontFamily: 'monospace' }}>
                                                {card.isCount ? card.value : fmtShort(Number(card.value))}
                                            </Text>
                                        </div>
                                        <div>
                                            <Text type="secondary" style={{ fontSize: 11, display: 'block' }}>{card.title}</Text>
                                            <Text strong style={{ fontSize: card.isCount ? 22 : 15, color: card.color, fontFamily: 'monospace' }}>
                                                {card.isCount ? card.value : formatCurrency(Number(card.value))}
                                            </Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>
            )}

            {summary && summary.totalOutstanding > 0 && (
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                    <Card size="small" style={{ ...glass }}>
                        <Text strong style={{ marginBottom: 10, display: 'block', fontSize: 13 }}>Aging Report</Text>
                        <AgingBar summary={summary} />
                    </Card>
                </motion.div>
            )}

            <Card size="small" style={{ ...glass }}>
                <Space wrap>
                    <Input placeholder="Search invoices..." prefix={<SearchOutlined style={{ opacity: 0.4 }} />} value={search} onChange={e => setSearch(e.target.value)} onPressEnter={load} style={{ width: 260, borderRadius: 8 }} allowClear />
                    <Select placeholder="Status" value={statusFilter} onChange={setStatusFilter} allowClear style={{ width: 140 }} options={[{ value: 'draft', label: 'Draft' }, { value: 'sent', label: 'Sent' }, { value: 'partial', label: 'Partial' }, { value: 'paid', label: 'Paid' }]} />
                    <Button icon={<ReloadOutlined />} onClick={load}>Refresh</Button>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'acct_receivables', title: 'Accounts Receivable', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Invoice #', key: 'invoiceNumber' }, { header: 'Customer', key: 'contactName' }, { header: 'Amount', key: 'totalAmount' }, { header: 'Status', key: 'status' }], data: invoices })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'acct_receivables', title: 'Accounts Receivable', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Invoice #', key: 'invoiceNumber' }, { header: 'Customer', key: 'contactName' }, { header: 'Amount', key: 'totalAmount' }, { header: 'Status', key: 'status' }], data: invoices })} /></Tooltip></RbacGuard>
                </Space>
            </Card>

            <Card style={{ ...glass }} styles={{ body: { padding: 0 } }}>
                <Table scroll={{ x: 900 }} dataSource={invoices.map(i => ({ ...i, key: i.id }))} columns={columns} loading={loading} size="small"
                    pagination={{ pageSize: 20, showTotal: t => `${t} invoices` }}
                    locale={{ emptyText: <Empty description="No customer invoices found" /> }}
                />
            </Card>

            <Modal title={`Invoice: ${detailModal?.invoiceNumber}`} open={!!detailModal} onCancel={() => setDetailModal(null)} footer={null} width={700}>
                {detailModal && (
                    <>
                        <Descriptions column={2} size="small" bordered style={{ marginBottom: 16 }}>
                            <Descriptions.Item label="Customer">{detailModal.contactName}</Descriptions.Item>
                            <Descriptions.Item label="Status"><Tag color={statusColor[detailModal.status]}>{detailModal.status}</Tag></Descriptions.Item>
                            <Descriptions.Item label="Invoice Date">{detailModal.invoiceDate}</Descriptions.Item>
                            <Descriptions.Item label="Due Date">{detailModal.dueDate}</Descriptions.Item>
                            <Descriptions.Item label="Reference">{detailModal.reference || '-'}</Descriptions.Item>
                            <Descriptions.Item label="Currency">{detailModal.currencyCode}</Descriptions.Item>
                            <Descriptions.Item label="Subtotal">{formatCurrency(detailModal.subtotal)}</Descriptions.Item>
                            <Descriptions.Item label="Tax">{formatCurrency(detailModal.taxAmount)}</Descriptions.Item>
                            <Descriptions.Item label="Total">{formatCurrency(detailModal.totalAmount)}</Descriptions.Item>
                            <Descriptions.Item label="Received">{formatCurrency(detailModal.amountPaid)}</Descriptions.Item>
                            <Descriptions.Item label="Outstanding" span={2}><Text strong style={{ color: Number(detailModal.amountDue) > 0 ? '#3b82f6' : '#10b981', fontSize: 16 }}>{formatCurrency(detailModal.amountDue)}</Text></Descriptions.Item>
                        </Descriptions>
                        {detailModal.notes && <Card size="small" style={{ marginBottom: 16 }}><Text type="secondary">Notes: </Text>{detailModal.notes}</Card>}
                        <Text strong>Line Items</Text>
                        <Table scroll={{ x: 900 }} dataSource={detailLines.map(l => ({ ...l, key: l.id }))} size="small" pagination={false} style={{ marginTop: 8 }}
                            columns={[
                                { title: '#', dataIndex: 'lineNumber', width: 40 },
                                { title: 'Description', dataIndex: 'description' },
                                { title: 'Qty', dataIndex: 'quantity', width: 60, align: 'right' as const, render: (v: number) => Number(v) },
                                { title: 'Price', dataIndex: 'unitPrice', width: 140, align: 'right' as const, render: (v: number) => formatCurrency(v) },
                                { title: 'Amount', dataIndex: 'amount', width: 160, align: 'right' as const, render: (v: number) => <Text strong>{formatCurrency(v)}</Text> },
                            ]}
                        />
                        {Number(detailModal.totalAmount) > 0 && (
                            <Progress percent={Math.round((Number(detailModal.amountPaid) / Number(detailModal.totalAmount)) * 100)} status={detailModal.status === 'paid' ? 'success' : 'active'} style={{ marginTop: 12 }} />
                        )}
                    </>
                )}
            </Modal>

            <Modal title={`Record Payment — ${paymentModal?.invoiceNumber}`} open={!!paymentModal} onOk={handlePayment} onCancel={() => setPaymentModal(null)} okText="Record Payment">
                {paymentModal && (
                    <div style={{ padding: '16px 0' }}>
                        <Text type="secondary">Outstanding: </Text><Text strong style={{ color: '#3b82f6' }}>{formatCurrency(paymentModal.amountDue)}</Text>
                        <br /><br />
                        <Text>Payment Amount:</Text>
                        <InputNumber value={paymentAmount} onChange={v => setPaymentAmount(v || 0)} style={{ width: '100%', marginTop: 8 }}
                            formatter={v => `Rp ${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, '.')} parser={v => Number((v || '').replace(/Rp\s?|(\.)/g, ''))}
                            min={0} max={Number(paymentModal.amountDue)}
                        />
                    </div>
                )}
            </Modal>

            <Modal title="Create New Invoice" open={createOpen} onOk={handleCreate} onCancel={() => setCreateOpen(false)} okText="Create Invoice" width={720} confirmLoading={createLoading} destroyOnClose>
                <Form form={form} layout="vertical" size="small" initialValues={{ invoiceDate: dayjs(), dueDate: dayjs().add(30, 'day') }}>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="contactId" label="Customer" rules={[{ required: true }]}><Select showSearch placeholder="Select customer" optionFilterProp="label" options={contacts.map(c => ({ value: c.id, label: `${c.code ? c.code+' — ' : ''}${c.name}` }))} /></Form.Item></Col>
                        <Col span={12}><Form.Item name="reference" label="Reference / SO #"><Input placeholder="SO-2026-XXX" /></Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="invoiceDate" label="Invoice Date" rules={[{ required: true }]}><DatePicker style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={12}><Form.Item name="dueDate" label="Due Date" rules={[{ required: true }]}><DatePicker style={{ width: '100%' }} /></Form.Item></Col>
                    </Row>
                    <Form.Item name="notes" label="Notes"><Input.TextArea rows={2} placeholder="Additional notes..." /></Form.Item>
                </Form>
                <Divider style={{ margin: '8px 0 12px' }}>Line Items</Divider>
                <div style={{ marginBottom: 8 }}>
                    <Row gutter={8} style={{ marginBottom: 4 }}>
                        <Col span={10}><Text type="secondary" style={{ fontSize: 11 }}>Description</Text></Col>
                        <Col span={4}><Text type="secondary" style={{ fontSize: 11 }}>Qty</Text></Col>
                        <Col span={5}><Text type="secondary" style={{ fontSize: 11 }}>Unit Price</Text></Col>
                        <Col span={4}><Text type="secondary" style={{ fontSize: 11 }}>Amount</Text></Col>
                        <Col span={1} /></Row>
                    {lines.map((line, i) => (
                        <Row gutter={8} key={i} style={{ marginBottom: 6 }}>
                            <Col span={10}><Input value={line.description} onChange={e => { const n = [...lines]; n[i].description = e.target.value; setLines(n); }} placeholder="Description" size="small" /></Col>
                            <Col span={4}><InputNumber value={line.quantity} onChange={v => { const n = [...lines]; n[i].quantity = v || 1; setLines(n); }} min={1} style={{ width: '100%' }} size="small" /></Col>
                            <Col span={5}><InputNumber value={line.unitPrice} onChange={v => { const n = [...lines]; n[i].unitPrice = v || 0; setLines(n); }} min={0} style={{ width: '100%' }} size="small" formatter={v => `${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, '.')} parser={v => Number((v || '').replace(/\./g, ''))} /></Col>
                            <Col span={4}><Text strong style={{ lineHeight: '30px', fontFamily: 'monospace', fontSize: 12 }}>{formatCurrency(line.quantity * line.unitPrice)}</Text></Col>
                            <Col span={1}>{lines.length > 1 && <Button type="text" size="small" danger icon={<MinusCircleOutlined />} onClick={() => setLines(lines.filter((_, j) => j !== i))} />}</Col>
                        </Row>
                    ))}
                    <Button type="dashed" size="small" icon={<PlusOutlined />} onClick={() => setLines([...lines, { description: '', quantity: 1, unitPrice: 0 }])} style={{ width: '100%', marginTop: 4 }}>Add Line</Button>
                </div>
                <div style={{ textAlign: 'right', marginTop: 12, padding: '10px 14px', background: `${themeColor}08`, borderRadius: 10 }}>
                    <Text type="secondary">Total: </Text><Text strong style={{ fontSize: 18, fontFamily: 'monospace' }}>{formatCurrency(lineTotal)}</Text>
                </div>
            </Modal>
        </div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Button, Space, Tag, Spin, Empty, Row, Col, Select, Modal, Form, Input, InputNumber, DatePicker, Upload, message, Badge, Tooltip, Popconfirm } from 'antd';
import { BankOutlined, PlusOutlined, UploadOutlined, CheckCircleOutlined, CloseCircleOutlined, LinkOutlined, DisconnectOutlined, SwapOutlined, ThunderboltOutlined, FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { accountingService, AcctBankAccount, AcctBankStatement, AcctBankStatementLine } from '@/lib/accountingService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const fmt = (v: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(v || 0);

export default function ReconciliationPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [bankAccounts, setBankAccounts] = useState<AcctBankAccount[]>([]);
    const [selectedAccount, setSelectedAccount] = useState<string | null>(null);
    const [statements, setStatements] = useState<AcctBankStatement[]>([]);
    const [selectedStatement, setSelectedStatement] = useState<string | null>(null);
    const [lines, setLines] = useState<AcctBankStatementLine[]>([]);
    const [linesLoading, setLinesLoading] = useState(false);
    const [accountModal, setAccountModal] = useState(false);
    const [importModal, setImportModal] = useState(false);
    const [form] = Form.useForm();
    const [importForm] = Form.useForm();
    const [msgApi, ctxHolder] = message.useMessage();

    const load = useCallback(async () => { setLoading(true); try { setBankAccounts(await accountingService.getBankAccounts()); } catch {} finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    const loadStmts = useCallback(async (id: string) => { setSelectedAccount(id); setSelectedStatement(null); setLines([]); try { setStatements(await accountingService.getBankStatements(id)); } catch {} }, []);
    const loadLines = useCallback(async (id: string) => { setSelectedStatement(id); setLinesLoading(true); try { setLines(await accountingService.getBankStatementLines(id)); } catch {} finally { setLinesLoading(false); } }, []);

    const addAccount = async () => { try { const v = await form.validateFields(); await accountingService.createBankAccount(undefined, v); msgApi.success('Added'); setAccountModal(false); form.resetFields(); load(); } catch (e: any) { if (e.message) msgApi.error(e.message); } };
    const doImport = async () => { try { const v = await importForm.validateFields(); if (!selectedAccount) return; await accountingService.importBankStatement(selectedAccount, { statementDate: v.statementDate.format('YYYY-MM-DD'), openingBalance: v.openingBalance || 0, closingBalance: v.closingBalance || 0, source: 'csv', lines: v.lines || [] }); msgApi.success('Imported'); setImportModal(false); importForm.resetFields(); loadStmts(selectedAccount); } catch (e: any) { if (e.message) msgApi.error(e.message); } };
    const autoMatch = async () => { if (!selectedStatement) return; try { const c = await accountingService.autoMatchBankStatement(selectedStatement); msgApi.success(`Matched ${c} txns`); loadLines(selectedStatement); } catch { msgApi.error('Failed'); } };

    const matchedCount = lines.filter(l => l.matched).length;
    const unmatchedCount = lines.length - matchedCount;
    const matchPct = lines.length > 0 ? Math.round((matchedCount / lines.length) * 100) : 0;

    const cols = [
        { title: 'Date', dataIndex: 'transactionDate', key: 'd', width: 110, render: (v: string) => dayjs(v).format('DD MMM YYYY') },
        { title: 'Description', dataIndex: 'description', key: 'desc', ellipsis: true },
        { title: 'Reference', dataIndex: 'reference', key: 'ref', width: 120, render: (v: string) => v ? <Text style={{ fontFamily: 'monospace', fontSize: 11 }}>{v}</Text> : '—' },
        { title: 'Amount', dataIndex: 'amount', key: 'amt', width: 160, align: 'right' as const, render: (v: number) => <Text strong style={{ fontFamily: 'monospace', color: v >= 0 ? '#10b981' : '#ef4444' }}>{fmt(v)}</Text> },
        { title: 'Status', key: 'st', width: 120, render: (_: any, r: AcctBankStatementLine) => r.matched ? <Tag color="green" icon={<CheckCircleOutlined />}>Matched</Tag> : <Tag color="orange" icon={<CloseCircleOutlined />}>Unmatched</Tag> },
        { title: '', key: 'a', width: 50, render: (_: any, r: AcctBankStatementLine) => r.matched ? <Popconfirm title="Unmatch?" onConfirm={() => accountingService.unmatchBankTransaction(r.id).then(() => loadLines(selectedStatement!))}><Button size="small" type="text" icon={<DisconnectOutlined />} danger /></Popconfirm> : null },
    ];
    const expData = lines.map(l => ({ date: l.transactionDate, description: l.description || '', reference: l.reference || '', amount: l.amount, status: l.matched ? 'Matched' : 'Unmatched' }));

    if (loading) return <CMSLayout title="Bank Reconciliation"><div style={{ display: 'flex', justifyContent: 'center', padding: 120 }}><Spin size="large" /></div></CMSLayout>;

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Bank Reconciliation</AuroraText>}
            subTitle={<DecryptedText text="Match bank statements against journal entries" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
