const chartData = [
    { time: '00:00', requests: 4000, latency: 120 },
    { time: '04:00', requests: 3000, latency: 110 },
    { time: '08:00', requests: 5000, latency: 140 },
    { time: '12:00', requests: 8000, latency: 180 },
