                    className="col-span-3 lg:col-span-1"
                />
                <BentoGridItem
                    title="Occupancy"
                    description="482 pax currently in the building."
                    icon={<KeyOutlined />}
                    className="col-span-3 lg:col-span-1"
                />
            </BentoGrid>

            {/* CHARTS ROW */}
            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
