                            maxItems={3}
                            animIndex={17}
                        />
                    </Col>
                </Row>
            </div>
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import {
    Table, Button, Space, Modal, Form, Input, Select, Tag, Card,
    message, Typography, Tooltip, Drawer, Descriptions, Row, Col,
    InputNumber, DatePicker, Statistic, Segmented, Tabs, Spin,
} from "antd";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    SearchOutlined, EyeOutlined, DollarOutlined,
    AppstoreOutlined, UnorderedListOutlined, RocketOutlined,
    TrophyOutlined, FunnelPlotOutlined, FileTextOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import dayjs from "dayjs";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const { TextArea } = Input;

interface Deal {
    id: string; name: string; description: string; amount: number; currency: string;
    stage: string; probability: number; closeDate: string; accountId: string;
    contactId: string; type: string; leadSource: string; nextStep: string;
    lossReason: string; status: string; accountName: string; contactName: string;
    createdAt: string; expectedRevenue: number;
    quotes: { id: string; quoteNumber: string; name: string; total: number; status: string; validUntil: string; createdAt: string; }[];
}

const STAGES = [
    { value: "prospecting", label: "Prospecting", color: "#1677ff", prob: 10 },
    { value: "qualification", label: "Qualification", color: "var(--theme-color, #8b5cf6)", prob: 25 },
    { value: "proposal", label: "Proposal", color: "#eb2f96", prob: 50 },
    { value: "negotiation", label: "Negotiation", color: "#fa8c16", prob: 75 },
    { value: "closed_won", label: "Closed Won", color: "#52c41a", prob: 100 },
    { value: "closed_lost", label: "Closed Lost", color: "#ff4d4f", prob: 0 },
];
const DEAL_TYPES = [{ value: "new_business", label: "New Business" }, { value: "existing_business", label: "Existing Business" }, { value: "renewal", label: "Renewal" }];
const SOURCES = ["web", "phone", "referral", "partner", "campaign", "social", "other"];

const DEAL_FIELDS: FieldDef[] = [
    { name: "name", label: "Deal Name", required: true }, { name: "amount", label: "Amount" },
    { name: "stage", label: "Stage" }, { name: "probability", label: "Probability (%)" },
    { name: "closeDate", label: "Close Date" }, { name: "type", label: "Type" },
    { name: "leadSource", label: "Lead Source" }, { name: "nextStep", label: "Next Step" },
    { name: "description", label: "Description" },
];

export default function DealsPage() {
    const [deals, setDeals] = useState<Deal[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<Deal | null>(null);
    const [form] = Form.useForm();
    const [search, setSearch] = useState("");
    const [stageFilter, setStageFilter] = useState<string | undefined>();
    const [detailOpen, setDetailOpen] = useState(false);
    const [selected, setSelected] = useState<Deal | null>(null);
    const [viewMode, setViewMode] = useState<string>("board");
    const [aiAction, setAiAction] = useState("");
    const [aiLoading, setAiLoading] = useState(false);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($tenantId: String!, $stage: String, $search: String) { deals(tenantId: $tenantId, stage: $stage, search: $search) { id name description amount currency stage probability closeDate accountId contactId type leadSource nextStep lossReason status accountName contactName createdAt expectedRevenue quotes { id quoteNumber name total status validUntil createdAt } } }`, { tenantId: DEFAULT_TENANT_ID, stage: stageFilter || null, search: search || null });
            setDeals(data.deals || []);
        } catch (err: any) { message.error("Failed to load: " + err.message); }
        finally { setLoading(false); }
    }, [search, stageFilter]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleGenerateAI = async () => {
        if (!selected) return;
        setAiLoading(true);
        try { const data = await gql(`query($dealId: String!) { generateDealNextBestAction(dealId: $dealId) }`, { dealId: selected.id }); setAiAction(data.generateDealNextBestAction); message.success("AI Next Best Action generated!"); }
        catch (err: any) { message.error("Generation failed: " + err.message); }
        finally { setAiLoading(false); }
    };

    const openDetails = (d: Deal) => { setSelected(d); setAiAction(""); setDetailOpen(true); };

    const handleSave = async (values: any) => {
        try {
            const input = { name: values.name, description: values.description || null, amount: values.amount || null, currency: values.currency || 'USD', stage: values.stage || 'prospecting', probability: values.probability ?? STAGES.find(s => s.value === (values.stage || 'prospecting'))?.prob ?? 10, closeDate: values.closeDate?.format('YYYY-MM-DD') || null, accountId: values.accountId || null, contactId: values.contactId || null, type: values.type || null, leadSource: values.leadSource || null, nextStep: values.nextStep || null };
            if (editing) { await gql(`mutation($id: String!, $input: UpdateDealInput!) { updateDeal(id: $id, input: $input) { id } }`, { id: editing.id, input }); message.success("Deal updated"); }
            else { await gql(`mutation($tenantId: String!, $input: CreateDealInput!) { createDeal(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input }); message.success("Deal created"); }
            setIsModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try { await gql(`mutation($tenantId: String!, $input: CreateDealInput!) { createDeal(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input: { name: r.name, amount: r.amount || null, stage: r.stage || 'prospecting', probability: r.probability || 10, type: r.type || null, leadSource: r.leadSource || null, nextStep: r.nextStep || null, description: r.description || null } }); success++; }
            catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadData(); return { success, failed, errors };
    };

    const handleStageChange = async (id: string, newStage: string) => {
        try { const prob = STAGES.find(s => s.value === newStage)?.prob ?? 10; const status = newStage === 'closed_won' ? 'closed_won' : newStage === 'closed_lost' ? 'closed_lost' : 'open'; await gql(`mutation($id: String!, $input: UpdateDealInput!) { updateDeal(id: $id, input: $input) { id } }`, { id, input: { stage: newStage, probability: prob, status } }); message.success("Stage updated"); loadData(); }
        catch (err: any) { message.error(err.message); }
    };

    const handleDelete = async (id: string) => { try { await gql(`mutation($id: String!) { deleteDeal(id: $id) }`, { id }); message.success("Deleted"); loadData(); } catch (err: any) { message.error(err.message); } };

    const formatAmount = (v: number) => { if (!v) return '—'; return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(v); };

    const openDeals = deals.filter(d => d.status === 'open');
    const totalPipeline = openDeals.reduce((s, d) => s + (d.amount || 0), 0);
    const weightedPipeline = openDeals.reduce((s, d) => s + (d.amount || 0) * (d.probability || 0) / 100, 0);
    const wonAmount = deals.filter(d => d.stage === 'closed_won').reduce((s, d) => s + (d.amount || 0), 0);

    const renderBoard = () => {
        const pipelineStages = STAGES.filter(s => s.value !== 'closed_lost');
        return (<div style={{ display: 'flex', gap: 12, overflowX: 'auto', paddingBottom: 8 }}>
            {pipelineStages.map(stage => {
                const stageDeals = deals.filter(d => d.stage === stage.value);
                const stageTotal = stageDeals.reduce((s, d) => s + (d.amount || 0), 0);
                return (<div key={stage.value} style={{ minWidth: 260, maxWidth: 280, flex: '0 0 auto', background: 'rgba(255,255,255,0.5)', backdropFilter: 'blur(8px)', borderRadius: 8, padding: 12, borderTop: `3px solid ${stage.color}` }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}><div><Text strong style={{ fontSize: 13 }}>{stage.label}</Text><br /><Text type="secondary" style={{ fontSize: 11 }}>{stageDeals.length} deals · {formatAmount(stageTotal)}</Text></div></div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                        {stageDeals.length === 0 && <Text type="secondary" style={{ fontSize: 12, textAlign: 'center', padding: 16 }}>No deals</Text>}
                        {stageDeals.map(deal => (<Card key={deal.id} size="small" hoverable style={{ borderRadius: 6, cursor: 'pointer' }} onClick={() => openDetails(deal)}>
                            <Text strong style={{ fontSize: 13 }}>{deal.name}</Text><br /><Text type="secondary" style={{ fontSize: 11 }}>{deal.accountName || 'No account'}</Text>
                            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 8, marginBottom: 4 }}><Tooltip title="Expected Revenue"><Text style={{ color: '#52c41a', fontWeight: 600, fontSize: 12 }}>{formatAmount(deal.expectedRevenue)}</Text></Tooltip><Tooltip title="Deal Amount"><Text style={{ color: stage.color, fontWeight: 500, fontSize: 12 }}>{formatAmount(deal.amount)}</Text></Tooltip></div>
                            <div style={{ display: 'flex', justifyContent: 'space-between' }}><Text type="secondary" style={{ fontSize: 11 }}>{deal.probability}% prob</Text>{deal.closeDate && <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(deal.closeDate).format('MMM D')}</Text>}</div>
                            <div style={{ marginTop: 8, display: 'flex', gap: 4, flexWrap: 'wrap' }}>{STAGES.filter(s => s.value !== deal.stage && s.value !== 'closed_lost').slice(0, 3).map(s => (<Tag key={s.value} color={s.color} style={{ cursor: 'pointer', fontSize: 10, margin: 0 }} onClick={(e) => { e.stopPropagation(); handleStageChange(deal.id, s.value); }}>→ {s.label}</Tag>))}</div>
                        </Card>))}
                    </div>
                </div>);
            })}
        </div>);
    };

    const columns: ColumnsType<Deal> = [
        { title: "Deal", key: "deal", render: (_, r) => <div><Text strong>{r.name}</Text><br /><Text type="secondary" style={{ fontSize: 12 }}>{r.accountName || 'No account'}</Text></div>, sorter: (a, b) => a.name.localeCompare(b.name) },
        { title: "Amount", key: "amount", width: 120, align: "right", render: (_, r) => <Text strong>{formatAmount(r.amount)}</Text>, sorter: (a, b) => (a.amount || 0) - (b.amount || 0) },
        { title: "Expected Rev.", key: "expectedRevenue", width: 130, align: "right", render: (_, r) => <Text style={{ color: '#52c41a' }}>{formatAmount(r.expectedRevenue)}</Text>, sorter: (a, b) => (a.expectedRevenue || 0) - (b.expectedRevenue || 0) },
        { title: "Stage", key: "stage", width: 140, render: (_, r) => { const s = STAGES.find(s => s.value === r.stage); return <Tag color={s?.color}>{s?.label || r.stage}</Tag>; } },
        { title: "Probability", key: "prob", width: 100, align: "right", render: (_, r) => `${r.probability || 0}%` },
        { title: "Close Date", key: "close", width: 120, render: (_, r) => r.closeDate ? dayjs(r.closeDate).format('MMM D, YYYY') : '—', sorter: (a, b) => (a.closeDate || '').localeCompare(b.closeDate || '') },
        { title: "Actions", key: "actions", width: 130, render: (_, r) => (<Space>
            <Tooltip title="View"><Button type="text" icon={<EyeOutlined />} onClick={() => openDetails(r)} /></Tooltip>
            <Tooltip title="Edit"><Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue({ name: r.name, description: r.description, amount: r.amount, stage: r.stage, probability: r.probability, closeDate: r.closeDate ? dayjs(r.closeDate) : null, type: r.type, leadSource: r.leadSource, nextStep: r.nextStep }); setIsModalOpen(true); }} /></Tooltip>
            <Tooltip title="Delete"><Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id) })} /></Tooltip>
        </Space>) },
    ];

    const formSteps = [
        { title: "Deal Info", icon: <DollarOutlined />, fields: ["name", "amount", "stage", "probability", "closeDate"], content: (<><Row gutter={16}><Col span={16}><Form.Item name="name" label="Deal Name" rules={[{ required: true }]}><Input placeholder="e.g., Acme Corp — Enterprise License" /></Form.Item></Col><Col span={8}><Form.Item name="amount" label="Amount"><InputNumber style={{ width: '100%' }} prefix="$" formatter={v => `${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')} /></Form.Item></Col></Row><Row gutter={16}><Col span={8}><Form.Item name="stage" label="Stage" initialValue="prospecting"><Select options={STAGES.map(s => ({ value: s.value, label: s.label }))} /></Form.Item></Col><Col span={8}><Form.Item name="probability" label="Probability (%)"><InputNumber style={{ width: '100%' }} min={0} max={100} /></Form.Item></Col><Col span={8}><Form.Item name="closeDate" label="Close Date"><DatePicker style={{ width: '100%' }} /></Form.Item></Col></Row></>) },
        { title: "Details", icon: <FileTextOutlined />, fields: ["type", "leadSource", "nextStep", "description"], content: (<><Row gutter={16}><Col span={8}><Form.Item name="type" label="Type"><Select allowClear options={DEAL_TYPES} /></Form.Item></Col><Col span={8}><Form.Item name="leadSource" label="Lead Source"><Select allowClear options={SOURCES.map(v => ({ value: v, label: v.charAt(0).toUpperCase() + v.slice(1) }))} /></Form.Item></Col><Col span={8}><Form.Item name="nextStep" label="Next Step"><Input placeholder="e.g., Send proposal" /></Form.Item></Col></Row><Form.Item name="description" label="Description"><TextArea rows={2} /></Form.Item></>) },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Deals</AuroraText>}
            subTitle={<DecryptedText text="Track your sales pipeline and opportunities" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Segmented key="view" options={[{ value: 'board', icon: <AppstoreOutlined /> }, { value: 'list', icon: <UnorderedListOutlined /> }]} value={viewMode} onChange={(v) => setViewMode(v as string)} />,
            <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>New Deal</Button>,
                <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'crm_deals', title: 'CRM Deals', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Deal', key: 'dealName' }, { header: 'Amount', key: 'amount' }, { header: 'Stage', key: 'stage' }, { header: 'Win %', key: 'probability' }, { header: 'Account', key: 'accountName' }], data: deals })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'crm_deals', title: 'CRM Deals', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Deal', key: 'dealName' }, { header: 'Amount', key: 'amount' }, { header: 'Stage', key: 'stage' }, { header: 'Win %', key: 'probability' }, { header: 'Account', key: 'accountName' }], data: deals })} /></Tooltip></RbacGuard>,
        ]}>
            <Row gutter={16} style={{ marginBottom: 16 }}>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0 }}><Card ><Statistic title="Pipeline Value (Open)" value={totalPipeline} prefix={<DollarOutlined />} precision={0} formatter={(v) => formatAmount(Number(v))} /></Card></motion.div></Col>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}><Card ><Statistic title="Expected Revenue (Open)" value={weightedPipeline} prefix={<FunnelPlotOutlined />} precision={0} valueStyle={{ color: '#52c41a' }} formatter={(v) => formatAmount(Number(v))} /></Card></motion.div></Col>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}><Card ><Statistic title="Won Revenue" value={wonAmount} prefix={<TrophyOutlined />} precision={0} valueStyle={{ color: '#52c41a' }} formatter={(v) => formatAmount(Number(v))} /></Card></motion.div></Col>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}><Card ><Statistic title="Open Deals" value={openDeals.length} prefix={<FunnelPlotOutlined />} /></Card></motion.div></Col>
            </Row>
            <Card style={{ marginBottom: 16 }}><Space wrap>
                <Input prefix={<SearchOutlined />} placeholder="Search deals..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: 250 }} allowClear />
                <Select placeholder="Stage" value={stageFilter} onChange={setStageFilter} allowClear style={{ width: 160 }} options={STAGES.map(s => ({ value: s.value, label: s.label }))} />
            </Space></Card>

            {viewMode === 'board' ? renderBoard() : (<Card  styles={{ body: { padding: 0 } }}><Table scroll={{ x: 900 }} columns={columns} dataSource={deals.map(d => ({ ...d, key: d.id }))} loading={loading} pagination={{ pageSize: 20, showSizeChanger: true }} size="middle" /></Card>)}

            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? "Edit Deal" : "New Deal"} entityName="deal" steps={formSteps} fields={DEAL_FIELDS} width={700} onBatchCreate={handleBatchCreate} gradient={["#f59e0b", "#ef4444"]} editMode={!!editing} />

            <Drawer title={`Deal: ${selected?.name || ''}`} open={detailOpen} onClose={() => setDetailOpen(false)} width={600}>
                {selected && (<Tabs defaultActiveKey="details" items={[
                    { key: "details", label: "Details", children: (<Descriptions column={1} bordered size="small">
                        <Descriptions.Item label="Amount"><Text strong>{formatAmount(selected.amount)}</Text></Descriptions.Item>
                        <Descriptions.Item label="Expected Revenue"><Text type="success">{formatAmount(selected.expectedRevenue)}</Text></Descriptions.Item>
                        <Descriptions.Item label="Stage"><Tag color={STAGES.find(s => s.value === selected.stage)?.color}>{STAGES.find(s => s.value === selected.stage)?.label}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Probability">{selected.probability}%</Descriptions.Item>
                        <Descriptions.Item label="Close Date">{selected.closeDate ? dayjs(selected.closeDate).format('MMM D, YYYY') : '—'}</Descriptions.Item>
                        <Descriptions.Item label="Account">{selected.accountName || '—'}</Descriptions.Item>
                        <Descriptions.Item label="Contact">{selected.contactName || '—'}</Descriptions.Item>
                        <Descriptions.Item label="Type"><Text style={{ textTransform: 'capitalize' }}>{selected.type?.replace('_', ' ') || '—'}</Text></Descriptions.Item>
                        <Descriptions.Item label="Lead Source"><Text style={{ textTransform: 'capitalize' }}>{selected.leadSource || '—'}</Text></Descriptions.Item>
                        <Descriptions.Item label="Next Step">{selected.nextStep || '—'}</Descriptions.Item>
                        {selected.lossReason && <Descriptions.Item label="Loss Reason">{selected.lossReason}</Descriptions.Item>}
                        <Descriptions.Item label="Description">{selected.description || '—'}</Descriptions.Item>
                    </Descriptions>) },
                    { key: "quotes", label: `Quotes (${selected.quotes?.length || 0})`, children: (<Table scroll={{ x: 900 }} dataSource={selected.quotes || []} rowKey="id" pagination={false} size="small" columns={[{ title: 'Quote #', dataIndex: 'quoteNumber', render: t => <Text strong>{t}</Text> }, { title: 'Name', dataIndex: 'name' }, { title: 'Status', dataIndex: 'status', render: t => <Tag>{t}</Tag> }, { title: 'Total', dataIndex: 'total', render: t => formatAmount(t) }, { title: 'Date', dataIndex: 'createdAt', render: t => dayjs(t).format('MMM D, YY') }]} />) },
                    { key: "ai", label: "AI Insights", children: (<Spin spinning={aiLoading}><div style={{ marginBottom: 16 }}><Text>Use Gemini 2.5 Pro to analyze the deal and get an actionable recommendation.</Text></div><Button type="primary" onClick={handleGenerateAI} style={{ marginBottom: 16 }} icon={<RocketOutlined />}>Generate Next Best Action</Button>{aiAction && (<Card size="small" style={{ background: '#f6ffed', borderColor: '#b7eb8f' }}><p style={{ margin: 0 }}>{aiAction}</p></Card>)}</Spin>) }
                ]} />)}
            </Drawer>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import {
    Table, Button, Space, Modal, Form, Input, Select, Tag, Card,
    message, Typography, Avatar, Tooltip, Drawer, Descriptions, Row, Col,
    Steps, Switch, InputNumber, DatePicker,
} from "antd";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    UserOutlined, SearchOutlined, EyeOutlined,
    SwapOutlined, IdcardOutlined, GlobalOutlined,
    FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;

interface Individual {
    id: string; firstName: string; lastName: string; salutation: string;
    jobTitle: string; department: string; company: string; status: string;
    leadStatus: string; leadSource: string; source: string; individualType: string;
    avatarUrl: string; email: string; phone: string; gender: string;
    nationality: string; linkedinUrl: string; twitterHandle: string; website: string;
    tags: any; customFields: any; createdAt: string; updatedAt: string;
}

const LEAD_STATUSES = [
    { value: "new", label: "New", color: "blue" },
    { value: "contacted", label: "Contacted", color: "cyan" },
    { value: "qualified", label: "Qualified", color: "green" },
    { value: "converted", label: "Converted", color: "gold" },
    { value: "lost", label: "Lost", color: "red" },
];
const SOURCES = ["web", "phone", "referral", "partner", "campaign", "social", "other"];

const INDIVIDUAL_FIELDS: FieldDef[] = [
    { name: "firstName", label: "First Name", required: true },
    { name: "lastName", label: "Last Name", required: true },
    { name: "salutation", label: "Salutation" }, { name: "jobTitle", label: "Job Title" },
    { name: "company", label: "Company" }, { name: "email", label: "Email" },
    { name: "phone", label: "Phone" }, { name: "department", label: "Department" },
    { name: "source", label: "Source" }, { name: "leadStatus", label: "Lead Status" },
    { name: "leadSource", label: "Lead Source" }, { name: "individualType", label: "Type" },
    { name: "linkedinUrl", label: "LinkedIn URL" }, { name: "website", label: "Website" },
];

export default function IndividualsPage() {
    const [individuals, setIndividuals] = useState<Individual[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<Individual | null>(null);
    const [form] = Form.useForm();
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [leadFilter, setLeadFilter] = useState<string | undefined>();
    const [detailOpen, setDetailOpen] = useState(false);
    const [selected, setSelected] = useState<Individual | null>(null);
    const [convertOpen, setConvertOpen] = useState(false);
    const [convertTarget, setConvertTarget] = useState<Individual | null>(null);
    const [convertForm] = Form.useForm();
    const [convertStep, setConvertStep] = useState(0);
    const [createDeal, setCreateDeal] = useState(false);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!, $status: String, $leadStatus: String, $search: String) {
                    individuals(tenantId: $tenantId, status: $status, leadStatus: $leadStatus, search: $search) {
                        id firstName lastName salutation jobTitle department company
                        status leadStatus leadSource source individualType
                        avatarUrl email phone gender nationality linkedinUrl twitterHandle website
                        tags customFields createdAt updatedAt
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID, status: statusFilter || null, leadStatus: leadFilter || null, search: search || null });
            setIndividuals(data.individuals || []);
        } catch (err: any) { message.error("Failed to load: " + err.message); }
        finally { setLoading(false); }
    }, [search, statusFilter, leadFilter]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const input = {
                firstName: values.firstName, lastName: values.lastName, salutation: values.salutation,
                jobTitle: values.jobTitle, department: values.department, company: values.company,
                leadStatus: values.leadStatus || null, leadSource: values.leadSource || null,
                source: values.source || null, individualType: values.individualType || 'person',
                linkedinUrl: values.linkedinUrl || null, website: values.website || null,
                email: values.email || null, phone: values.phone || null,
            };
            if (editing) {
                await gql(`mutation($id: String!, $input: UpdateIndividualInput!) { updateIndividual(id: $id, input: $input) { id } }`, { id: editing.id, input });
                message.success("Individual updated");
            } else {
                await gql(`mutation($tenantId: String!, $input: CreateIndividualInput!) { createIndividual(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input });
                message.success("Individual created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $input: CreateIndividualInput!) { createIndividual(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input: { firstName: r.firstName, lastName: r.lastName, salutation: r.salutation || null, jobTitle: r.jobTitle || null, department: r.department || null, company: r.company || null, leadStatus: r.leadStatus || null, leadSource: r.leadSource || null, source: r.source || null, individualType: r.individualType || 'person', linkedinUrl: r.linkedinUrl || null, website: r.website || null, email: r.email || null, phone: r.phone || null } });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.firstName} ${r.lastName}: ${e.message}`); }
        }
        loadData(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try { await gql(`mutation($id: String!) { deleteIndividual(id: $id) }`, { id }); message.success("Deleted"); loadData(); }
        catch (err: any) { message.error(err.message); }
    };

    const handleConvert = async () => {
        try {
            const v = await convertForm.validateFields();
            const input: any = { individualId: convertTarget!.id, accountName: v.accountName || null, accountId: v.accountId || null, contactTitle: v.contactTitle || null, contactRole: v.contactRole || null, createDeal };
            if (createDeal) { input.dealName = v.dealName || null; input.dealAmount = v.dealAmount || null; input.dealStage = v.dealStage || 'prospecting'; input.dealCloseDate = v.dealCloseDate?.format('YYYY-MM-DD') || null; }
            await gql(`mutation($tenantId: String!, $input: ConvertLeadInput!) { convertLead(tenantId: $tenantId, input: $input) { accountId contactId dealId } }`, { tenantId: DEFAULT_TENANT_ID, input });
            message.success(`${convertTarget!.firstName} ${convertTarget!.lastName} converted!`);
            setConvertOpen(false); convertForm.resetFields(); setConvertTarget(null); setConvertStep(0); setCreateDeal(false); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const columns: ColumnsType<Individual> = [
        { title: "Name", key: "name", sorter: (a, b) => a.lastName.localeCompare(b.lastName), render: (_, r) => (<Space><Avatar src={r.avatarUrl} icon={<UserOutlined />} style={{ backgroundColor: '#1677ff' }} /><div><Text strong>{r.salutation ? `${r.salutation} ` : ''}{r.firstName} {r.lastName}</Text><br /><Text type="secondary" style={{ fontSize: 12 }}>{[r.jobTitle, r.company].filter(Boolean).join(' at ') || 'No title'}</Text></div></Space>) },
        { title: "Email", dataIndex: "email", key: "email", width: 200, ellipsis: true, render: (v: string) => v || '—' },
        { title: "Phone", dataIndex: "phone", key: "phone", width: 140, render: (v: string) => v || '—' },
        { title: "Lead Status", key: "leadStatus", width: 130, render: (_, r) => { if (!r.leadStatus) return <Tag>Not a Lead</Tag>; const ls = LEAD_STATUSES.find(s => s.value === r.leadStatus); return <Tag color={ls?.color || 'default'}>{ls?.label || r.leadStatus}</Tag>; }, filters: LEAD_STATUSES.map(s => ({ text: s.label, value: s.value })), onFilter: (v, r) => r.leadStatus === v },
        { title: "Source", dataIndex: "source", key: "source", width: 100, render: (v) => v ? <Tag>{v}</Tag> : '—' },
        { title: "Status", dataIndex: "status", key: "status", width: 100, render: (v) => <Tag color={v === 'active' ? 'green' : 'default'}>{v}</Tag> },
        { title: "Actions", key: "actions", width: 150, render: (_, r) => (<Space>
            <Tooltip title="View"><Button type="text" icon={<EyeOutlined />} onClick={() => { setSelected(r); setDetailOpen(true); }} /></Tooltip>
            <Tooltip title="Edit"><Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue({ firstName: r.firstName, lastName: r.lastName, salutation: r.salutation, jobTitle: r.jobTitle, department: r.department, company: r.company, leadStatus: r.leadStatus, leadSource: r.leadSource, source: r.source, individualType: r.individualType, linkedinUrl: r.linkedinUrl, website: r.website, email: r.email, phone: r.phone }); setIsModalOpen(true); }} /></Tooltip>
            {r.leadStatus && r.leadStatus !== 'converted' && <Tooltip title="Convert Lead"><Button type="text" icon={<SwapOutlined />} style={{ color: '#52c41a' }} onClick={() => { setConvertTarget(r); convertForm.resetFields(); convertForm.setFieldsValue({ accountName: r.company || '', contactTitle: r.jobTitle || '' }); setConvertStep(0); setCreateDeal(false); setConvertOpen(true); }} /></Tooltip>}
            <Tooltip title="Delete"><Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete ${r.firstName} ${r.lastName}?`, onOk: () => handleDelete(r.id) })} /></Tooltip>
        </Space>) },
    ];

    const formSteps = [
        { title: "Personal Info", icon: <IdcardOutlined />, fields: ["salutation", "firstName", "lastName", "jobTitle", "company", "email", "phone"], content: (<><Row gutter={16}><Col span={6}><Form.Item name="salutation" label="Salutation"><Select allowClear options={['Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.'].map(v => ({ value: v, label: v }))} /></Form.Item></Col><Col span={9}><Form.Item name="firstName" label="First Name" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={9}><Form.Item name="lastName" label="Last Name" rules={[{ required: true }]}><Input /></Form.Item></Col></Row><Row gutter={16}><Col span={12}><Form.Item name="jobTitle" label="Job Title"><Input /></Form.Item></Col><Col span={12}><Form.Item name="company" label="Company"><Input /></Form.Item></Col></Row><Row gutter={16}><Col span={12}><Form.Item name="email" label="Email"><Input type="email" /></Form.Item></Col><Col span={12}><Form.Item name="phone" label="Phone"><Input /></Form.Item></Col></Row></>) },
        { title: "Lead & Source", icon: <GlobalOutlined />, fields: ["department", "source", "leadStatus", "leadSource", "individualType", "linkedinUrl", "website"], content: (<><Row gutter={16}><Col span={12}><Form.Item name="department" label="Department"><Input /></Form.Item></Col><Col span={12}><Form.Item name="source" label="Source"><Select allowClear options={SOURCES.map(v => ({ value: v, label: v.charAt(0).toUpperCase() + v.slice(1) }))} /></Form.Item></Col></Row><Row gutter={16}><Col span={8}><Form.Item name="leadStatus" label="Lead Status"><Select allowClear options={LEAD_STATUSES} /></Form.Item></Col><Col span={8}><Form.Item name="leadSource" label="Lead Source"><Select allowClear options={SOURCES.map(v => ({ value: v, label: v.charAt(0).toUpperCase() + v.slice(1) }))} /></Form.Item></Col><Col span={8}><Form.Item name="individualType" label="Type" initialValue="person"><Select options={[{ value: 'person', label: 'Person' }, { value: 'organization', label: 'Organization' }]} /></Form.Item></Col></Row><Row gutter={16}><Col span={12}><Form.Item name="linkedinUrl" label="LinkedIn URL"><Input /></Form.Item></Col><Col span={12}><Form.Item name="website" label="Website"><Input /></Form.Item></Col></Row></>) },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Individuals</AuroraText>}
            subTitle={<DecryptedText text="People in your CRM — contacts, leads, and team members" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
                <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'crm_individuals', title: 'CRM Individuals', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'First Name', key: 'firstName' }, { header: 'Last Name', key: 'lastName' }, { header: 'Email', key: 'email' }, { header: 'Phone', key: 'phone' }, { header: 'Status', key: 'status' }], data: individuals })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'crm_individuals', title: 'CRM Individuals', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'First Name', key: 'firstName' }, { header: 'Last Name', key: 'lastName' }, { header: 'Email', key: 'email' }, { header: 'Phone', key: 'phone' }, { header: 'Status', key: 'status' }], data: individuals })} /></Tooltip></RbacGuard>,
            <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>Add Individual</Button>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>
            <Card style={{ marginBottom: 16 }}><Space wrap>
                <Input prefix={<SearchOutlined />} placeholder="Search by name..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: 250 }} allowClear />
                <Select placeholder="Status" value={statusFilter} onChange={setStatusFilter} allowClear style={{ width: 130 }} options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }]} />
                <Select placeholder="Lead Status" value={leadFilter} onChange={setLeadFilter} allowClear style={{ width: 150 }} options={LEAD_STATUSES} />
            </Space></Card>
            <Card  styles={{ body: { padding: 0 } }}><Table scroll={{ x: 900 }} columns={columns} dataSource={individuals.map(i => ({ ...i, key: i.id }))} loading={loading} pagination={{ pageSize: 20, showSizeChanger: true }} size="middle" /></Card>

            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? "Edit Individual" : "Add Individual"} entityName="individual" steps={formSteps} fields={INDIVIDUAL_FIELDS} width={700} onBatchCreate={handleBatchCreate} gradient={["var(--theme-color, #8b5cf6)", "var(--theme-accent, #a855f7)"]} editMode={!!editing} />

            <Drawer title="Individual Details" open={detailOpen} onClose={() => setDetailOpen(false)} width={500}>
                {selected && (<Descriptions column={1} bordered size="small">
                    <Descriptions.Item label="Name">{selected.salutation ? `${selected.salutation} ` : ''}{selected.firstName} {selected.lastName}</Descriptions.Item>
                    <Descriptions.Item label="Job Title">{selected.jobTitle || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Company">{selected.company || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Department">{selected.department || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Email">{selected.email || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Phone">{selected.phone || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Lead Status">{selected.leadStatus ? <Tag color={LEAD_STATUSES.find(s => s.value === selected.leadStatus)?.color}>{selected.leadStatus}</Tag> : 'Not a Lead'}</Descriptions.Item>
                    <Descriptions.Item label="Source">{selected.source || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Status"><Tag color={selected.status === 'active' ? 'green' : 'default'}>{selected.status}</Tag></Descriptions.Item>
                    {selected.linkedinUrl && <Descriptions.Item label="LinkedIn"><a href={selected.linkedinUrl} target="_blank" rel="noreferrer">{selected.linkedinUrl}</a></Descriptions.Item>}
                    <Descriptions.Item label="Created">{new Date(selected.createdAt).toLocaleDateString()}</Descriptions.Item>
                </Descriptions>)}
            </Drawer>

            <Modal title={`Convert Lead: ${convertTarget?.firstName || ''} ${convertTarget?.lastName || ''}`} open={convertOpen} onCancel={() => { setConvertOpen(false); setConvertTarget(null); setConvertStep(0); }} width={650} footer={[convertStep > 0 && <Button key="back" onClick={() => setConvertStep(s => s - 1)}>Back</Button>, convertStep < 2 && <Button key="next" type="primary" onClick={() => setConvertStep(s => s + 1)}>Next</Button>, convertStep === 2 && <Button key="convert" type="primary" style={{ background: '#52c41a', borderColor: '#52c41a' }} onClick={handleConvert}>Convert Lead</Button>].filter(Boolean)}>
                <Steps current={convertStep} size="small" style={{ marginBottom: 24 }} items={[{ title: 'Account' }, { title: 'Contact' }, { title: 'Deal (Optional)' }]} />
                <Form form={convertForm} layout="vertical">
                    {convertStep === 0 && (<><Form.Item name="accountName" label="Account Name" rules={[{ required: true }]}><Input placeholder="e.g., Acme Corp" /></Form.Item><Typography.Text type="secondary">A new account will be created, or link to existing.</Typography.Text><Form.Item name="accountId" label="Or Link to Existing Account (ID)" style={{ marginTop: 12 }}><Input placeholder="Existing account UUID (optional)" /></Form.Item></>)}
                    {convertStep === 1 && (<><Form.Item name="contactTitle" label="Contact Title"><Input placeholder="e.g., VP of Sales" /></Form.Item><Form.Item name="contactRole" label="Contact Role"><Select allowClear options={[{ value: 'decision_maker', label: 'Decision Maker' }, { value: 'influencer', label: 'Influencer' }, { value: 'end_user', label: 'End User' }, { value: 'champion', label: 'Champion' }]} /></Form.Item></>)}
                    {convertStep === 2 && (<><Form.Item label="Create a Deal?"><Switch checked={createDeal} onChange={setCreateDeal} /></Form.Item>{createDeal && (<><Form.Item name="dealName" label="Deal Name" rules={[{ required: createDeal }]}><Input placeholder="e.g., Enterprise License" /></Form.Item><Row gutter={16}><Col span={8}><Form.Item name="dealAmount" label="Amount"><InputNumber style={{ width: '100%' }} prefix="$" /></Form.Item></Col><Col span={8}><Form.Item name="dealStage" label="Stage" initialValue="prospecting"><Select options={[{ value: 'prospecting', label: 'Prospecting' }, { value: 'qualification', label: 'Qualification' }, { value: 'proposal', label: 'Proposal' }]} /></Form.Item></Col><Col span={8}><Form.Item name="dealCloseDate" label="Close Date"><DatePicker style={{ width: '100%' }} /></Form.Item></Col></Row></>)}</>)}
                </Form>
            </Modal>
            </motion.div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import {
    Card, Tabs, Table, Tag, Typography, Progress, Space, Badge, Tooltip,
    message, Spin, Row, Col, Statistic, Button, Empty,
} from "antd";
import {
    ThunderboltOutlined, TrophyOutlined, WarningOutlined,
    RiseOutlined, FallOutlined, ReloadOutlined,
    UserOutlined, DollarOutlined, BulbOutlined, FireOutlined,
    CheckCircleOutlined, ClockCircleOutlined, FunnelPlotOutlined,
    FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';

const { Text, Title } = Typography;

interface LeadScore {
    individualId: string; firstName: string; lastName: string;
    email: string; company: string; leadStatus: string;
    score: number; grade: string; factors: string[];
}

interface DealInsight {
    dealId: string; dealName: string; stage: string;
    amount: number; probability: number; accountName: string;
    contactName: string; closeDate: string; daysSinceCreation: number;
    riskLevel: string; insights: string[]; recommendation: string;
}

const gradeColors: Record<string, string> = { A: '#10b981', B: '#3b82f6', C: '#f59e0b', D: '#f97316', F: '#ef4444' };
const gradeLabels: Record<string, string> = { A: 'Hot', B: 'Warm', C: 'Nurture', D: 'Cold', F: 'Disqualified' };
const riskColors: Record<string, string> = { low: '#10b981', medium: '#f59e0b', high: '#ef4444' };

// ── Lead Grade Distribution (donut-like visual) ──
function GradeDistribution({ leads }: { leads: LeadScore[] }) {
    const grades = ['A', 'B', 'C', 'D', 'F'];
    const total = leads.length || 1;
    return (
        <div style={{ display: 'flex', gap: 10 }}>
            {grades.map((g, i) => {
                const cnt = leads.filter(l => l.grade === g).length;
                const pct = Math.round((cnt / total) * 100);
                return (
                    <motion.div key={g} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.08 }}
                        style={{ flex: 1, padding: '12px 8px', borderRadius: 12, background: `${gradeColors[g]}08`, border: `1px solid ${gradeColors[g]}25`, textAlign: 'center' }}>
                        <div style={{ width: 36, height: 36, borderRadius: '50%', background: `${gradeColors[g]}20`, margin: '0 auto 6px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 800, fontSize: 16, color: gradeColors[g] }}>{g}</div>
                        <Text strong style={{ fontSize: 22, color: gradeColors[g], display: 'block' }}>{cnt}</Text>
                        <Text style={{ fontSize: 10, display: 'block', color: '#6b7280' }}>{gradeLabels[g]}</Text>
                        <Text style={{ fontSize: 9, color: '#9ca3af' }}>{pct}%</Text>
                    </motion.div>
                );
            })}
        </div>
    );
}

// ── Deal Risk Funnel ──
function RiskFunnel({ deals }: { deals: DealInsight[] }) {
    const risks = [
        { key: 'low', label: 'Low Risk', icon: <CheckCircleOutlined />, color: '#10b981' },
        { key: 'medium', label: 'Medium Risk', icon: <ClockCircleOutlined />, color: '#f59e0b' },
        { key: 'high', label: 'High Risk', icon: <WarningOutlined />, color: '#ef4444' },
    ];
    const total = deals.length || 1;
    const fmt = (v: number) => v ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(v) : '$0';

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {risks.map((r, i) => {
                const filtered = deals.filter(d => d.riskLevel === r.key);
                const cnt = filtered.length;
                const pct = Math.round((cnt / total) * 100);
                const totalAmt = filtered.reduce((s, d) => s + (d.amount || 0), 0);
                return (
                    <motion.div key={r.key} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.1 }}
                        style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                        <div style={{ minWidth: 100, display: 'flex', alignItems: 'center', gap: 6 }}>
                            <span style={{ color: r.color, fontSize: 14 }}>{r.icon}</span>
                            <Text style={{ fontSize: 11, fontWeight: 600 }}>{r.label}</Text>
                        </div>
                        <div style={{ flex: 1, position: 'relative', height: 28, borderRadius: 14, background: 'rgba(0,0,0,0.03)', overflow: 'hidden' }}>
                            <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ delay: 0.3 + i * 0.1, duration: 0.6 }}
                                style={{ height: '100%', borderRadius: 14, background: `${r.color}30`, position: 'absolute' }} />
                            <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ delay: 0.3 + i * 0.1, duration: 0.6 }}
                                style={{ height: '100%', borderRadius: 14, background: r.color, opacity: 0.8, display: 'flex', alignItems: 'center', paddingLeft: 10, minWidth: cnt > 0 ? 50 : 0 }}>
                                {cnt > 0 && <Text style={{ fontSize: 10, fontWeight: 700, color: '#fff' }}>{cnt} deals</Text>}
                            </motion.div>
                        </div>
                        <Text style={{ fontSize: 10, color: '#6b7280', minWidth: 80, textAlign: 'right' }}>{fmt(totalAmt)}</Text>
                    </motion.div>
                );
            })}
        </div>
    );
}

// ── AI Recommendations Widget ──
function AIRecommendations({ deals }: { deals: DealInsight[] }) {
    const highRisk = deals.filter(d => d.riskLevel === 'high').slice(0, 5);
    if (highRisk.length === 0) return <Empty description="No at-risk deals — pipeline is healthy 🎉" />;
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {highRisk.map((d, i) => (
                <motion.div key={d.dealId} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}
                    style={{ padding: '10px 14px', borderRadius: 10, borderLeft: `3px solid #ef4444` }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 4 }}>
                        <div>
                            <Text strong style={{ fontSize: 12 }}>{d.dealName}</Text>
                            <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>{d.accountName} · {d.daysSinceCreation}d old</Text>
                        </div>
                        <Tag color="red" style={{ fontSize: 10, borderRadius: 10, margin: 0 }}>HIGH RISK</Tag>
                    </div>
                    <div style={{ padding: '6px 8px', borderRadius: 6, background: 'rgba(239,68,68,0.06)', marginTop: 4 }}>
                        <BulbOutlined style={{ color: '#f59e0b', marginRight: 4 }} />
                        <Text style={{ fontSize: 11, color: '#374151' }}>💡 {d.recommendation}</Text>
                    </div>
                </motion.div>
            ))}
        </div>
    );
}

export default function AIIntelligencePage() {
    const [leads, setLeads] = useState<LeadScore[]>([]);
    const [deals, setDeals] = useState<DealInsight[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    leadScores(tenantId: $tenantId) {
                        individualId firstName lastName email company leadStatus score grade factors
                    }
                    dealInsights(tenantId: $tenantId) {
                        dealId dealName stage amount probability accountName contactName
                        closeDate daysSinceCreation riskLevel insights recommendation
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setLeads(data.leadScores || []);
            setDeals(data.dealInsights || []);
        } catch (err: any) { message.error("Failed: " + err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const fmt = (v: number) => v ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(v) : '$0';

    const avgScore = leads.length ? Math.round(leads.reduce((s, l) => s + l.score, 0) / leads.length) : 0;
    const hotLeads = leads.filter(l => l.grade === 'A' || l.grade === 'B').length;
    const atRisk = deals.filter(d => d.riskLevel === 'high').length;
    const totalPipeline = deals.reduce((s, d) => s + (d.amount || 0), 0);
    const weightedPipeline = deals.reduce((s, d) => s + (d.amount || 0) * ((d.probability || 0) / 100), 0);
    const avgDealAge = deals.length > 0 ? Math.round(deals.reduce((s, d) => s + (d.daysSinceCreation || 0), 0) / deals.length) : 0;

    const leadColumns: ColumnsType<LeadScore> = [
        {
            title: "Lead", key: "name",
            render: (_, r) => (
                <Space>
                    <div style={{ width: 32, height: 32, borderRadius: '50%', background: `${gradeColors[r.grade]}15`, border: `2px solid ${gradeColors[r.grade]}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, fontSize: 12, color: gradeColors[r.grade] }}>{r.firstName[0]}{r.lastName[0]}</div>
                    <div><Text strong>{r.firstName} {r.lastName}</Text>{r.company && <><br /><Text type="secondary" style={{ fontSize: 11 }}>{r.company}</Text></>}</div>
                </Space>
            ),
        },
        {
            title: "Score", key: "score", width: 180, sorter: (a, b) => a.score - b.score, defaultSortOrder: 'descend',
            render: (_, r) => (
                <Space>
                    <Progress type="circle" percent={r.score} size={40}
                        strokeColor={gradeColors[r.grade]} format={() => r.score} />
                    <Tag color={gradeColors[r.grade]} style={{ fontWeight: 'bold', fontSize: 14, padding: '2px 10px', borderRadius: 10 }}>{r.grade}</Tag>
                </Space>
            ),
        },
        {
            title: "Status", key: "status", width: 110,
            render: (_, r) => r.leadStatus ? <Tag>{r.leadStatus}</Tag> : <Tag color="default">No status</Tag>,
        },
        {
            title: "Scoring Factors", key: "factors",
            render: (_, r) => (
                <Tooltip title={r.factors.join('\n')}>
                    <Text type="secondary" style={{ fontSize: 12 }}>
                        {r.factors.slice(0, 3).join(' · ')}{r.factors.length > 3 ? ` +${r.factors.length - 3} more` : ''}
                    </Text>
                </Tooltip>
            ),
        },
    ];

    const dealColumns: ColumnsType<DealInsight> = [
        {
            title: "Deal", key: "name",
            render: (_, r) => (
                <div><Text strong>{r.dealName}</Text>{r.accountName && <><br /><Text type="secondary" style={{ fontSize: 11 }}>{r.accountName}</Text></>}</div>
            ),
        },
        { title: "Amount", key: "amount", width: 120, align: "right", render: (_, r) => <Text strong>{fmt(r.amount)}</Text> },
        { title: "Stage", key: "stage", width: 120, render: (_, r) => <Tag color="blue">{r.stage}</Tag> },
        {
            title: "Win %", key: "prob", width: 80,
            render: (_, r) => <Progress type="circle" percent={r.probability} size={32} strokeColor={r.probability >= 70 ? '#10b981' : r.probability >= 40 ? '#f59e0b' : '#ef4444'} />,
        },
        {
            title: "Risk", key: "risk", width: 90,
            render: (_, r) => <Badge color={riskColors[r.riskLevel]} text={<Text style={{ color: riskColors[r.riskLevel], fontWeight: 600 }}>{r.riskLevel.toUpperCase()}</Text>} />,
            sorter: (a, b) => { const o = { high: 3, medium: 2, low: 1 }; return (o[b.riskLevel as keyof typeof o] || 0) - (o[a.riskLevel as keyof typeof o] || 0); },
        },
        { title: "Age", key: "age", width: 70, render: (_, r) => <Text>{r.daysSinceCreation}d</Text>, sorter: (a, b) => b.daysSinceCreation - a.daysSinceCreation },
        {
            title: "AI Recommendation", key: "rec",
            render: (_, r) => (
                <Tooltip title={r.insights.join('\n')}>
                    <Text style={{ fontSize: 12 }}>💡 {r.recommendation}</Text>
                </Tooltip>
            ),
        },
    ];

    if (loading) return (
        <CMSLayout title={<AuroraText colors={[themeColor, "#8b5cf6", "#06b6d4"]}>AI Intelligence</AuroraText>} subTitle="Analyzing pipeline...">
            <div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /><br /><Text type="secondary" style={{ marginTop: 8 }}>Running AI analysis on leads & deals...</Text></div>
        </CMSLayout>
    );

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "#8b5cf6", "#06b6d4"]} className="text-[22px] font-bold tracking-tight">AI Intelligence</AuroraText>}
            subTitle={<DecryptedText text="AI-powered lead scoring, deal insights & pipeline analytics" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} style={{ borderRadius: 8 }}>Refresh Analysis</Button>,
                <Tooltip key="xl" title="Export leads to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'crm_lead_scoring', title: 'CRM Lead Scoring Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'firstName', format: (v: string, row: any) => `${v} ${row.lastName}` }, { header: 'Email', key: 'email' }, { header: 'Company', key: 'company' }, { header: 'Score', key: 'score' }, { header: 'Grade', key: 'grade' }, { header: 'Status', key: 'leadStatus' }], data: leads })} /></Tooltip>,
                <Tooltip key="pd" title="Export deals to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'crm_deal_insights', title: 'CRM Deal Insights Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Deal', key: 'dealName' }, { header: 'Account', key: 'accountName' }, { header: 'Amount', key: 'amount', format: (v: number) => fmt(v) }, { header: 'Stage', key: 'stage' }, { header: 'Win %', key: 'probability' }, { header: 'Risk', key: 'riskLevel' }, { header: 'Age (d)', key: 'daysSinceCreation' }], data: deals })} /></Tooltip>,
            ]}>

            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {/* KPI Stats */}
                <Row gutter={[12, 12]}>
                    {[
                        { title: 'Avg Lead Score', value: `${avgScore}/100`, icon: <ThunderboltOutlined />, color: avgScore >= 50 ? '#10b981' : '#f59e0b' },
                        { title: 'Hot Leads (A/B)', value: `${hotLeads}/${leads.length}`, icon: <FireOutlined />, color: '#ef4444' },
                        { title: 'At-Risk Deals', value: atRisk, icon: <WarningOutlined />, color: atRisk > 0 ? '#ef4444' : '#10b981' },
                        { title: 'Total Pipeline', value: fmt(totalPipeline), icon: <DollarOutlined />, color: '#3b82f6' },
                        { title: 'Weighted Pipeline', value: fmt(weightedPipeline), icon: <FunnelPlotOutlined />, color: '#8b5cf6' },
                        { title: 'Avg Deal Age', value: `${avgDealAge}d`, icon: <ClockCircleOutlined />, color: '#06b6d4' },
                    ].map((s, i) => (
                        <Col key={i} xs={12} md={4}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" style={{ borderTop: `3px solid ${s.color}` }}>
                                    <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 18 }} />
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Analytics Row */}
                <Row gutter={[16, 16]}>
                    <Col xs={24} md={12}>
                        <Card size="small" style={{ height: '100%' }} title={<><ThunderboltOutlined /> <Text strong style={{ fontSize: 13 }}>Lead Grade Distribution</Text></>}>
                            <GradeDistribution leads={leads} />
                        </Card>
                    </Col>
                    <Col xs={24} md={12}>
                        <Card size="small" style={{ height: '100%' }} title={<><FunnelPlotOutlined /> <Text strong style={{ fontSize: 13 }}>Deal Risk Analysis</Text></>}>
                            <RiskFunnel deals={deals} />
                        </Card>
                    </Col>
                </Row>

                {/* AI Recommendations */}
                <Card size="small"  title={<><BulbOutlined style={{ color: '#f59e0b' }} /> <Text strong style={{ fontSize: 13 }}>AI Action Items — High-Risk Deals</Text></>}>
                    <AIRecommendations deals={deals} />
                </Card>

                {/* Data Tables */}
                <Card >
                    <Tabs defaultActiveKey="leads" items={[
                        {
                            key: 'leads', label: <span><UserOutlined /> Lead Scoring <Badge count={leads.length} style={{ backgroundColor: themeColor }} /></span>,
                            children: <Table columns={leadColumns} dataSource={leads.map(l => ({ ...l, key: l.individualId }))}
                                pagination={{ pageSize: 15 }} size="middle" scroll={{ x: 900 }} />,
                        },
                        {
                            key: 'deals', label: <span><RiseOutlined /> Deal Insights <Badge count={deals.length} style={{ backgroundColor: '#3b82f6' }} /></span>,
                            children: <Table columns={dealColumns} dataSource={deals.map(d => ({ ...d, key: d.dealId }))}
                                pagination={{ pageSize: 15 }} size="middle" scroll={{ x: 900 }} />,
                        },
                    ]} />
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import {
    Card, Row, Col, Statistic, Typography, Select, Input, Tag, Table, Collapse,
    message, Space, Segmented, Spin, Badge, Empty, theme,
} from "antd";
import {
    DollarOutlined, FunnelPlotOutlined, TeamOutlined, BarChartOutlined,
    SearchOutlined, AppstoreOutlined, UnorderedListOutlined, ReloadOutlined,
    TrophyOutlined, CloseCircleOutlined, CalendarOutlined, FilterOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, Cell, LabelList } from "recharts";
import dayjs from "dayjs";

const { Text } = Typography;

const glass = { 
    background: 'rgba(255, 255, 255, 0.4)', 
    backdropFilter: 'blur(16px)', 
    border: '1px solid rgba(255, 255, 255, 0.5)', 
    borderRadius: 14,
    boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.07)'
};

const gradientBorder = (color: string) => ({
    background: `linear-gradient(135deg, ${color}08, ${color}03)`,
    borderImage: `linear-gradient(135deg, ${color}, ${color}40) 1`,
    borderWidth: 1,
    borderStyle: 'solid' as const,
    borderRadius: 14,
    backdropFilter: 'blur(12px)',
});

interface Deal {
    id: string; dealName: string; amount: number; probability: number; stage: string;
    closeDate: string; accountId: string; contactId: string; ownerId: string;
    priority: string; status: string; lostReason: string; wonReason: string;
    nextStep: string; notes: string; createdAt: string; updatedAt: string;
    account?: { companyName: string }; contact?: { firstName: string; lastName: string };
}

const STAGES = [
    { value: "prospecting", label: "Prospecting", prob: 10, color: "#3b82f6" },
    { value: "qualification", label: "Qualification", prob: 20, color: "#6366f1" },
    { value: "needs_analysis", label: "Needs Analysis", prob: 40, color: "#8b5cf6" },
    { value: "proposal", label: "Proposal", prob: 60, color: "#f59e0b" },
    { value: "negotiation", label: "Negotiation", prob: 80, color: "#f97316" },
    { value: "closed_won", label: "Closed Won", prob: 100, color: "#10b981" },
    { value: "closed_lost", label: "Closed Lost", prob: 0, color: "#ef4444" },
];

const PRIORITIES = [
    { value: "low", label: "Low", color: "#94a3b8" },
    { value: "medium", label: "Medium", color: "#3b82f6" },
    { value: "high", label: "High", color: "#f59e0b" },
    { value: "critical", label: "Critical", color: "#ef4444" },
];

const fmt = (v: number) => {
    if (!v) return "$0";
    return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(v);
};

const fmtShort = (v: number) => {
    if (v >= 1e6) return `$${(v / 1e6).toFixed(1)}M`;
    if (v >= 1e3) return `$${(v / 1e3).toFixed(0)}K`;
    return `$${v}`;
};

export default function PipelinePage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [deals, setDeals] = useState<Deal[]>([]);
    const [loading, setLoading] = useState(true);
    const [viewMode, setViewMode] = useState<string>("board");
    const [search, setSearch] = useState("");
    const [priorityFilter, setPriorityFilter] = useState<string | undefined>();
    const [ownerFilter, setOwnerFilter] = useState<string | undefined>();
    const [dateRange, setDateRange] = useState<string | undefined>();
    const [sortBy, setSortBy] = useState<string>("amount_desc");
    const [funnelStageFilter, setFunnelStageFilter] = useState<string | undefined>();

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql<{ deals: Deal[] }>(`query($tenantId: String!) { deals(tenantId: $tenantId) { id dealName amount probability stage closeDate accountId contactId ownerId priority status lostReason wonReason nextStep notes createdAt updatedAt account { companyName } contact { firstName lastName } } }`, { tenantId: DEFAULT_TENANT_ID });
            setDeals(data.deals || []);
        } catch (err: any) { message.error("Failed to load deals: " + err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const handleStageChange = async (dealId: string, newStage: string) => {
        try {
            const prob = STAGES.find(s => s.value === newStage)?.prob ?? 10;
            await gql(`mutation($id: ID!, $input: UpdateDealInput!) { updateDeal(id: $id, input: $input) { id stage } }`, { id: dealId, input: { stage: newStage, probability: prob } });
            message.success("Stage updated");
            loadData();
        } catch (err: any) { message.error(err.message); }
    };

    // ─── Computed data ────────────────────────────────────
    const openStages = STAGES.filter(s => s.value !== "closed_won" && s.value !== "closed_lost");
    const openDeals = useMemo(() => deals.filter(d => d.stage !== "closed_won" && d.stage !== "closed_lost"), [deals]);
    const totalPipeline = useMemo(() => openDeals.reduce((s, d) => s + (d.amount || 0), 0), [openDeals]);
    const weightedPipeline = useMemo(() => openDeals.reduce((s, d) => s + (d.amount || 0) * (d.probability || 0) / 100, 0), [openDeals]);
    const avgDealSize = openDeals.length > 0 ? totalPipeline / openDeals.length : 0;

    // Pipeline velocity: avg deal size × win rate × number of deals / avg sales cycle
    const avgCycleDays = useMemo(() => {
        const closedWithDates = deals.filter(d => d.stage === "closed_won" && d.createdAt && d.closeDate);
        if (closedWithDates.length === 0) return 30;
        const totalDays = closedWithDates.reduce((s, d) => s + Math.max(dayjs(d.closeDate).diff(dayjs(d.createdAt), "day"), 1), 0);
        return Math.round(totalDays / closedWithDates.length);
    }, [deals]);

    // Stage distribution percentage for progress bar
    const stageDistribution = useMemo(() => {
        const total = openDeals.length || 1;
        return openStages.map(stage => ({
            ...stage,
            count: openDeals.filter(d => d.stage === stage.value).length,
            pct: Math.round(openDeals.filter(d => d.stage === stage.value).length / total * 100),
        }));
    }, [openDeals, openStages]);

    const owners = useMemo(() => {
        const set = new Set<string>();
        deals.forEach(d => { if (d.ownerId) set.add(d.ownerId); });
        return Array.from(set);
    }, [deals]);

    const filteredDeals = useMemo(() => {
        let filtered = [...deals];
        if (search) filtered = filtered.filter(d => d.dealName?.toLowerCase().includes(search.toLowerCase()));
        if (priorityFilter) filtered = filtered.filter(d => d.priority === priorityFilter);
        if (ownerFilter) filtered = filtered.filter(d => d.ownerId === ownerFilter);
        if (funnelStageFilter) filtered = filtered.filter(d => d.stage === funnelStageFilter);
        if (dateRange) {
            const now = dayjs();
            filtered = filtered.filter(d => {
                if (!d.closeDate) return false;
                const cd = dayjs(d.closeDate);
                if (dateRange === "month") return cd.isSame(now, "month");
                if (dateRange === "quarter") return cd.quarter() === now.quarter() && cd.year() === now.year();
                return cd.year() === now.year();
            });
        }
        // Sort
        if (sortBy === "amount_desc") filtered.sort((a, b) => (b.amount || 0) - (a.amount || 0));
        else if (sortBy === "close_asc") filtered.sort((a, b) => (a.closeDate || "").localeCompare(b.closeDate || ""));
        else if (sortBy === "prob_desc") filtered.sort((a, b) => (b.probability || 0) - (a.probability || 0));
        return filtered;
    }, [deals, search, priorityFilter, ownerFilter, dateRange, sortBy, funnelStageFilter]);

    const allWonDeals = deals.filter(d => d.stage === "closed_won");
    const allLostDeals = deals.filter(d => d.stage === "closed_lost");
    const wonDeals = allWonDeals.slice(0, 10);
    const lostDeals = allLostDeals.slice(0, 10);
    const totalWonAmount = allWonDeals.reduce((s, d) => s + (d.amount || 0), 0);
    const totalLostAmount = allLostDeals.reduce((s, d) => s + (d.amount || 0), 0);
    const winRate = (allWonDeals.length + allLostDeals.length) > 0
        ? Math.round(allWonDeals.length / (allWonDeals.length + allLostDeals.length) * 100) : 0;

    // ─── Summary cards ───────────────────────────────────
    const summaryCards = [
        { label: "Total Pipeline", value: totalPipeline, prefix: <DollarOutlined />, color: "#3b82f6", formatter: fmt },
        { label: "Weighted Pipeline", value: weightedPipeline, prefix: <FunnelPlotOutlined />, color: "#8b5cf6", formatter: fmt },
        { label: "Deals in Pipeline", value: openDeals.length, prefix: <TeamOutlined />, color: themeColor, formatter: undefined },
        { label: "Avg Deal Size", value: avgDealSize, prefix: <BarChartOutlined />, color: "#f59e0b", formatter: fmt },
    ];

    // ─── Funnel data ─────────────────────────────────────
    const funnelData = STAGES.filter(s => s.value !== "closed_lost").map(stage => {
        const stageDeals = deals.filter(d => d.stage === stage.value);
        return { ...stage, count: stageDeals.length, total: stageDeals.reduce((s, d) => s + (d.amount || 0), 0) };
    });
    const maxFunnelCount = Math.max(...funnelData.map(d => d.count), 1);

    // ─── Bar chart data ──────────────────────────────────
    const barData = STAGES.filter(s => s.value !== "closed_lost").map(stage => {
        const stageDeals = deals.filter(d => d.stage === stage.value);
        return { name: stage.label, value: stageDeals.reduce((s, d) => s + (d.amount || 0), 0), count: stageDeals.length, fill: stage.color };
    });

    // ─── Close date badge color ──────────────────────────
    const closeDateColor = (dateStr: string) => {
        if (!dateStr) return undefined;
        const d = dayjs(dateStr);
        if (d.isBefore(dayjs(), "day")) return "#ef4444";
        if (d.diff(dayjs(), "day") <= 7) return "#f59e0b";
        return "#10b981";
    };

    const priorityBorderColor = (p: string) => PRIORITIES.find(pr => pr.value === p)?.color || "#94a3b8";

    // ─── Kanban Board ────────────────────────────────────
    const renderBoard = () => {
        const boardStages = STAGES.filter(s => s.value !== "closed_lost");
        return (
            <div style={{ display: "flex", gap: 12, overflowX: "auto", paddingBottom: 8 }}>
                {boardStages.map((stage, si) => {
                    const stageDeals = filteredDeals.filter(d => d.stage === stage.value);
                    const stageTotal = stageDeals.reduce((s, d) => s + (d.amount || 0), 0);
                    return (
                        <motion.div key={stage.value} initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: si * 0.05 }}
                            style={{ minWidth: 260, maxWidth: 280, flex: "0 0 auto", background: isDark ? "rgba(255,255,255,0.04)" : "rgba(255,255,255,0.5)", backdropFilter: "blur(8px)", borderRadius: 10, padding: 12, borderTop: `3px solid ${stage.color}` }}>
                            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
                                <div>
                                    <Text strong style={{ fontSize: 13 }}>{stage.label}</Text><br />
                                    <Text type="secondary" style={{ fontSize: 11 }}>{stageDeals.length} deals · {fmtShort(stageTotal)}</Text>
                                </div>
                                <Badge count={stageDeals.length} style={{ backgroundColor: stage.color }} />
                            </div>
                            <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 480, overflowY: "auto" }}>
                                {stageDeals.length === 0 && <Text type="secondary" style={{ fontSize: 12, textAlign: "center", padding: 20 }}>No deals</Text>}
                                {stageDeals.map(deal => (
                                    <motion.div key={deal.id}
                                        whileHover={{ scale: 1.02, boxShadow: "0 4px 16px rgba(0,0,0,0.12)" }}
                                        transition={{ type: "spring", stiffness: 400, damping: 25 }}
                                        style={{
                                            borderRadius: 8, padding: 12,
                                            background: isDark ? "rgba(255,255,255,0.06)" : "#fff",
                                            border: "1px solid rgba(0,0,0,0.06)",
                                            borderLeft: `3px solid ${priorityBorderColor(deal.priority)}`,
                                            cursor: "default",
                                        }}>
                                        {/* Deal name + account */}
                                        <div style={{ display: "flex", alignItems: "center", gap: 4, flexWrap: "wrap" }}>
                                            <Text strong style={{ fontSize: 13 }}>{deal.dealName}</Text>
                                            {deal.account?.companyName && (
                                                <Tag style={{ fontSize: 9, margin: 0, borderRadius: 10 }}>
                                                    {deal.account.companyName}
                                                </Tag>
                                            )}
                                        </div>

                                        {/* Amount + probability */}
                                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 8 }}>
                                            <Text style={{ color: "#10b981", fontWeight: 700, fontSize: 14 }}>
                                                {fmt(deal.amount)}
                                            </Text>
                                            <Tag color={stage.color} style={{ fontSize: 10, margin: 0, borderRadius: 10 }}>
                                                {deal.probability}%
                                            </Tag>
                                        </div>

                                        {/* Close date + owner avatar */}
                                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 6 }}>
                                            {deal.closeDate ? (
                                                <Text style={{ fontSize: 11, color: closeDateColor(deal.closeDate) }}>
                                                    <CalendarOutlined style={{ marginRight: 3 }} />
                                                    {dayjs(deal.closeDate).format("MMM D")}
                                                    {dayjs(deal.closeDate).isBefore(dayjs(), "day") && " (overdue)"}
                                                </Text>
                                            ) : <span />}
                                            {deal.ownerId && (
                                                <div style={{
                                                    width: 24, height: 24, borderRadius: "50%",
                                                    background: `${themeColor}20`, color: themeColor,
                                                    display: "flex", alignItems: "center", justifyContent: "center",
                                                    fontSize: 10, fontWeight: 700,
                                                }}>
                                                    {deal.ownerId.slice(0, 2).toUpperCase()}
                                                </div>
                                            )}
                                        </div>

                                        {/* Contact + next step */}
                                        {(deal.contact || deal.nextStep) && (
                                            <div style={{ marginTop: 6, paddingTop: 6, borderTop: "1px dashed rgba(0,0,0,0.06)" }}>
                                                {deal.contact && (
                                                    <Text type="secondary" style={{ fontSize: 10, display: "block" }}>
                                                        👤 {deal.contact.firstName} {deal.contact.lastName}
                                                    </Text>
                                                )}
                                                {deal.nextStep && (
                                                    <Text type="secondary" style={{ fontSize: 10, display: "block" }}>
                                                        📋 {deal.nextStep}
                                                    </Text>
                                                )}
                                            </div>
                                        )}

                                        {/* Stage move dropdown */}
                                        <Select size="small" placeholder="Move to…"
                                            style={{ width: "100%", marginTop: 8 }} value={undefined}
                                            onChange={(v) => { if (v) handleStageChange(deal.id, v); }}
                                            options={STAGES.filter(s => s.value !== deal.stage).map(s => ({
                                                value: s.value, label: `→ ${s.label}`,
                                            }))} />
                                    </motion.div>
                                ))}
                            </div>
                        </motion.div>
                    );
                })}
            </div>
        );
    };

    // ─── List view columns ───────────────────────────────
    const columns: ColumnsType<Deal> = [
        { title: "Deal", key: "deal", render: (_, r) => <div><Text strong>{r.dealName}</Text><br /><Text type="secondary" style={{ fontSize: 11 }}>{r.account?.companyName || "—"}</Text></div>, sorter: (a, b) => (a.dealName || "").localeCompare(b.dealName || "") },
        { title: "Amount", key: "amount", width: 120, align: "right", render: (_, r) => <Text strong style={{ color: "#10b981" }}>{fmt(r.amount)}</Text>, sorter: (a, b) => (a.amount || 0) - (b.amount || 0) },
        { title: "Stage", key: "stage", width: 140, render: (_, r) => { const s = STAGES.find(s => s.value === r.stage); return <Tag color={s?.color}>{s?.label || r.stage}</Tag>; } },
        { title: "Probability", key: "prob", width: 90, align: "right", render: (_, r) => `${r.probability || 0}%`, sorter: (a, b) => (a.probability || 0) - (b.probability || 0) },
        { title: "Priority", key: "priority", width: 90, render: (_, r) => <Tag color={priorityBorderColor(r.priority)}>{r.priority || "—"}</Tag> },
        { title: "Close Date", key: "close", width: 110, render: (_, r) => r.closeDate ? <Text style={{ color: closeDateColor(r.closeDate) }}>{dayjs(r.closeDate).format("MMM D, YYYY")}</Text> : "—", sorter: (a, b) => (a.closeDate || "").localeCompare(b.closeDate || "") },
        { title: "Contact", key: "contact", width: 140, render: (_, r) => r.contact ? `${r.contact.firstName} ${r.contact.lastName}` : "—" },
        { title: "Move Stage", key: "action", width: 150, render: (_, r) => <Select size="small" placeholder="Move…" style={{ width: "100%" }} value={undefined} onChange={(v) => { if (v) handleStageChange(r.id, v); }} options={STAGES.filter(s => s.value !== r.stage).map(s => ({ value: s.value, label: s.label }))} /> },
    ];

    if (loading) return <CMSLayout title="Sales Pipeline" subTitle="Loading…"><div style={{ textAlign: "center", padding: 100 }}><Spin size="large" /></div></CMSLayout>;

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Sales Pipeline</AuroraText>}
            subTitle={<DecryptedText text="Visualize and manage your deal pipeline" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Segmented key="view" options={[{ value: "board", icon: <AppstoreOutlined /> }, { value: "list", icon: <UnorderedListOutlined /> }]} value={viewMode} onChange={(v) => setViewMode(v as string)} />,
                <button key="reload" onClick={loadData} style={{ border: "none", background: "none", cursor: "pointer", fontSize: 16 }}><ReloadOutlined /></button>,
            ]}
        >
            {/* ── Summary Cards ─────────────────────────── */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {summaryCards.map((c, i) => (
                    <Col xs={12} sm={6} key={i}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card style={{
                                ...gradientBorder(c.color),
                                borderTop: `3px solid ${c.color}`,
                                background: isDark ? `rgba(255,255,255,0.04)` : `linear-gradient(135deg, ${c.color}06, rgba(255,255,255,0.65))`,
                                backdropFilter: 'blur(12px)',
                            }} styles={{ body: { padding: "14px 16px" } }}>
                                <Statistic title={<Text style={{ fontSize: 11 }}>{c.label}</Text>} value={c.value} prefix={c.prefix}
                                    valueStyle={{ color: c.color, fontSize: 20, fontFamily: "monospace" }}
                                    formatter={c.formatter ? (v) => c.formatter!(Number(v)) : undefined} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* ── Pipeline Stage Progress ───────────────── */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.15 }}>
                <Card size="small" style={{ marginBottom: 16, background: isDark ? "rgba(255,255,255,0.04)" : glass.background }}
                    styles={{ body: { padding: "12px 16px" } }}>
                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
                        <Text strong style={{ fontSize: 12 }}>Stage Distribution</Text>
                        <Space size={12}>
                            <Text type="secondary" style={{ fontSize: 10 }}>Avg Cycle: {avgCycleDays}d</Text>
                            <Text type="secondary" style={{ fontSize: 10 }}>Win Rate: {winRate}%</Text>
                        </Space>
                    </div>
                    <div style={{ display: "flex", height: 8, borderRadius: 4, overflow: "hidden", gap: 1 }}>
                        {stageDistribution.map(s => (
                            <motion.div key={s.value} initial={{ width: 0 }} animate={{ width: `${s.pct}%` }}
                                transition={{ duration: 0.6, delay: 0.2 }}
                                title={`${s.label}: ${s.count} deals (${s.pct}%)`}
                                style={{ background: s.color, minWidth: s.count > 0 ? 4 : 0, borderRadius: 2, cursor: "pointer" }}
                                onClick={() => setFunnelStageFilter(funnelStageFilter === s.value ? undefined : s.value)} />
                        ))}
                    </div>
                    <div style={{ display: "flex", gap: 12, marginTop: 6, flexWrap: "wrap" }}>
                        {stageDistribution.filter(s => s.count > 0).map(s => (
                            <Text key={s.value} style={{ fontSize: 10 }}>
                                <span style={{ display: "inline-block", width: 8, height: 8, borderRadius: "50%", background: s.color, marginRight: 4 }} />
                                {s.label}: {s.count}
                            </Text>
                        ))}
                    </div>
                </Card>
            </motion.div>

            {/* ── Funnel Visualization ──────────────────── */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.2 }}>
                <Card size="small" style={{ marginBottom: 16, background: isDark ? "rgba(255,255,255,0.04)" : glass.background }} styles={{ body: { padding: "16px 20px" } }}>
                    <Text strong style={{ fontSize: 13, display: "block", marginBottom: 12 }}>Pipeline Funnel</Text>
                    <div style={{ display: "flex", alignItems: "flex-end", gap: 4 }}>
                        {funnelData.map((stage, i) => {
                            const widthPct = Math.max(stage.count / maxFunnelCount * 100, 18);
                            const isActive = funnelStageFilter === stage.value;
                            const conversionRate = i > 0 && funnelData[i - 1].count > 0
                                ? Math.round(stage.count / funnelData[i - 1].count * 100) : null;
                            return (
                                <div key={stage.value} style={{ display: "flex", flexDirection: "column", alignItems: "center", flex: `0 0 ${widthPct}%`, minWidth: 75 }}>
                                    {conversionRate !== null && (
                                        <Text style={{ fontSize: 9, color: isDark ? "#aaa" : "#888", marginBottom: 2 }}>
                                            {conversionRate}% →
                                        </Text>
                                    )}
                                    <motion.div initial={{ scaleX: 0 }} animate={{ scaleX: 1 }} transition={{ delay: 0.25 + i * 0.07 }}
                                        onClick={() => setFunnelStageFilter(isActive ? undefined : stage.value)}
                                        style={{
                                            width: "100%", height: 60, borderRadius: 6, cursor: "pointer",
                                            background: `linear-gradient(135deg, ${stage.color}, ${stage.color}cc)`,
                                            display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
                                            opacity: funnelStageFilter && !isActive ? 0.4 : 1, transition: "all 0.2s",
                                            border: isActive ? "2px solid #fff" : "1px solid transparent",
                                            boxShadow: isActive ? `0 0 14px ${stage.color}60` : "0 2px 6px rgba(0,0,0,0.08)",
                                            clipPath: i === funnelData.length - 1
                                                ? undefined
                                                : "polygon(0 0, 92% 0, 100% 50%, 92% 100%, 0 100%, 8% 50%)",
                                        }}>
                                        <Text style={{ color: "#fff", fontSize: 10, fontWeight: 600, lineHeight: 1 }}>{stage.label}</Text>
                                        <Text style={{ color: "#fff", fontSize: 15, fontWeight: 800 }}>{stage.count}</Text>
                                        <Text style={{ color: "rgba(255,255,255,0.8)", fontSize: 9 }}>{fmtShort(stage.total)}</Text>
                                    </motion.div>
                                </div>
                            );
                        })}
                    </div>
                    {funnelStageFilter && <Tag closable onClose={() => setFunnelStageFilter(undefined)} color={STAGES.find(s => s.value === funnelStageFilter)?.color} style={{ marginTop: 8 }}>Filtering: {STAGES.find(s => s.value === funnelStageFilter)?.label}</Tag>}
                </Card>
            </motion.div>

            {/* ── Filters & Controls ───────────────────── */}
            <Card size="small" style={{ marginBottom: 16, background: isDark ? "rgba(255,255,255,0.04)" : glass.background }} styles={{ body: { padding: "10px 14px" } }}>
                <Space wrap>
                    <Input prefix={<SearchOutlined />} placeholder="Search deals…" value={search} onChange={e => setSearch(e.target.value)} style={{ width: 200 }} allowClear />
                    <Select placeholder="Priority" value={priorityFilter} onChange={setPriorityFilter} allowClear style={{ width: 120 }} options={PRIORITIES.map(p => ({ value: p.value, label: p.label }))} />
                    <Select placeholder="Owner" value={ownerFilter} onChange={setOwnerFilter} allowClear style={{ width: 140 }}
                        options={owners.map(o => ({ value: o, label: o.slice(0, 8) + "…" }))} />
                    <Select placeholder="Close Date" value={dateRange} onChange={setDateRange} allowClear style={{ width: 130 }}
                        options={[{ value: "month", label: "This Month" }, { value: "quarter", label: "This Quarter" }, { value: "year", label: "This Year" }]} />
                    <Select placeholder="Sort" value={sortBy} onChange={setSortBy} style={{ width: 155 }}
                        options={[{ value: "amount_desc", label: "Amount ↓" }, { value: "close_asc", label: "Close Date ↑" }, { value: "prob_desc", label: "Probability ↓" }]} />
                    <FilterOutlined style={{ opacity: 0.4 }} />
                </Space>
            </Card>

            {/* ── Main View (Kanban / List) ────────────── */}
            {viewMode === "board" ? renderBoard() : (
                <Card style={{ background: isDark ? "rgba(255,255,255,0.04)" : glass.background }} styles={{ body: { padding: 0 } }}>
                    <Table scroll={{ x: 1000 }} columns={columns} dataSource={filteredDeals.filter(d => d.stage !== "closed_lost").map(d => ({ ...d, key: d.id }))}
                        pagination={{ pageSize: 20, showSizeChanger: true }} size="middle" />
                </Card>
            )}

            {/* ── Stage Value Bar Chart ────────────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                <Card size="small" title={<Space><BarChartOutlined style={{ color: themeColor }} /> Deal Value by Stage</Space>} style={{ marginTop: 16, background: isDark ? "rgba(255,255,255,0.04)" : glass.background }}>
                    <div style={{ height: 260 }}>
                        {barData.some(d => d.value > 0) ? (
                            <ResponsiveContainer>
                                <BarChart data={barData} layout="vertical" margin={{ left: 10, right: 30 }}>
                                    <CartesianGrid strokeDasharray="3 3" stroke={isDark ? "rgba(255,255,255,0.06)" : "#f0f0f0"} />
                                    <XAxis type="number" tickFormatter={(v) => fmtShort(v)} tick={{ fontSize: 10 }} />
                                    <YAxis type="category" dataKey="name" tick={{ fontSize: 11 }} width={100} />
                                    <RTooltip formatter={(v: number) => fmt(v)} />
                                    <Bar dataKey="value" radius={[0, 6, 6, 0]} name="Deal Value">
                                        {barData.map((d, i) => <Cell key={i} fill={d.fill} />)}
                                        <LabelList dataKey="count" position="right" formatter={(v: number) => `${v} deals`} style={{ fontSize: 10, fill: isDark ? "#ccc" : "#666" }} />
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        ) : <Empty description="No deal data" />}
                    </div>
                </Card>
            </motion.div>

            {/* ── Closed Deals Section ─────────────────── */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                <Collapse ghost style={{ marginTop: 16 }} items={[
                    {
                        key: "closed",
                        label: (
                            <Space wrap>
                                <TrophyOutlined /> Closed Deals
                                <Tag color="green">{allWonDeals.length} Won ({fmt(totalWonAmount)})</Tag>
                                <Tag color="red">{allLostDeals.length} Lost ({fmt(totalLostAmount)})</Tag>
                                <Tag color={winRate >= 50 ? "green" : winRate >= 25 ? "orange" : "red"}>Win Rate: {winRate}%</Tag>
                            </Space>
                        ),
                        children: (
                            <Row gutter={[16, 16]}>
                                {/* Win/Loss ratio visual bar */}
                                <Col span={24}>
                                    <div style={{ display: "flex", height: 6, borderRadius: 3, overflow: "hidden", marginBottom: 8 }}>
                                        <div style={{ width: `${winRate}%`, background: "#10b981", transition: "width 0.6s" }} />
                                        <div style={{ width: `${100 - winRate}%`, background: "#ef4444", transition: "width 0.6s" }} />
                                    </div>
                                </Col>
                                <Col xs={24} md={12}>
                                    <Card size="small"
                                        title={
                                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                                <Text style={{ color: "#10b981" }}><TrophyOutlined /> Won Deals</Text>
                                                <Text type="secondary" style={{ fontSize: 11 }}>Total: {fmt(totalWonAmount)}</Text>
                                            </div>
                                        }
                                        style={{ borderTop: "3px solid #10b981", background: isDark ? "rgba(16,185,129,0.05)" : "rgba(16,185,129,0.04)" }}>
                                        {wonDeals.length === 0 ? <Empty description="No won deals yet" /> : wonDeals.map((d, i) => (
                                            <motion.div key={d.id} initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }}
                                                transition={{ delay: i * 0.03 }}
                                                style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: "1px solid rgba(0,0,0,0.04)" }}>
                                                <div>
                                                    <Text strong style={{ fontSize: 12 }}>{d.dealName}</Text>
                                                    {d.account?.companyName && <Text type="secondary" style={{ fontSize: 10, display: "block" }}>{d.account.companyName}</Text>}
                                                    <Text type="secondary" style={{ fontSize: 10, display: "block" }}>{d.wonReason || "No reason recorded"}</Text>
                                                </div>
                                                <div style={{ textAlign: "right", minWidth: 80 }}>
                                                    <Text style={{ color: "#10b981", fontWeight: 600, fontSize: 12 }}>{fmt(d.amount)}</Text>
                                                    <br />
                                                    <Text type="secondary" style={{ fontSize: 10 }}>
                                                        {d.closeDate ? dayjs(d.closeDate).format("MMM D, YYYY") : ""}
                                                    </Text>
                                                </div>
                                            </motion.div>
                                        ))}
                                    </Card>
                                </Col>
                                <Col xs={24} md={12}>
                                    <Card size="small"
                                        title={
                                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                                <Text style={{ color: "#ef4444" }}><CloseCircleOutlined /> Lost Deals</Text>
                                                <Text type="secondary" style={{ fontSize: 11 }}>Total: {fmt(totalLostAmount)}</Text>
                                            </div>
                                        }
                                        style={{ borderTop: "3px solid #ef4444", background: isDark ? "rgba(239,68,68,0.05)" : "rgba(239,68,68,0.04)" }}>
                                        {lostDeals.length === 0 ? <Empty description="No lost deals" /> : lostDeals.map((d, i) => (
                                            <motion.div key={d.id} initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }}
                                                transition={{ delay: i * 0.03 }}
                                                style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: "1px solid rgba(0,0,0,0.04)" }}>
                                                <div>
                                                    <Text strong style={{ fontSize: 12 }}>{d.dealName}</Text>
                                                    {d.account?.companyName && <Text type="secondary" style={{ fontSize: 10, display: "block" }}>{d.account.companyName}</Text>}
                                                    <Text type="secondary" style={{ fontSize: 10, display: "block" }}>{d.lostReason || "No reason recorded"}</Text>
                                                </div>
                                                <div style={{ textAlign: "right", minWidth: 80 }}>
                                                    <Text style={{ color: "#ef4444", fontWeight: 600, fontSize: 12 }}>{fmt(d.amount)}</Text>
                                                    <br />
                                                    <Text type="secondary" style={{ fontSize: 10 }}>
                                                        {d.closeDate ? dayjs(d.closeDate).format("MMM D, YYYY") : ""}
                                                    </Text>
                                                </div>
                                            </motion.div>
                                        ))}
                                    </Card>
                                </Col>
                            </Row>
                        ),
                    },
                ]} />
            </motion.div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import {
    Table, Button, Space, Modal, Form, Input, Select, Tag, Card,
    message, Typography, Tooltip, Drawer, Descriptions, Row, Col,
    InputNumber, Statistic, Switch,
} from "antd";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    SearchOutlined, EyeOutlined, ShoppingOutlined,
    DollarOutlined, CheckCircleOutlined, AppstoreOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const { TextArea } = Input;

interface Product {
    id: string; name: string; code: string; description: string;
    unitPrice: number; currency: string; category: string;
    isActive: boolean; createdAt: string;
}

const CATEGORIES = ["Software", "Hardware", "Service", "Subscription", "Consulting", "Support", "Other"];

const PRODUCT_FIELDS: FieldDef[] = [
    { name: "name", label: "Name", required: true },
    { name: "code", label: "Product Code" },
    { name: "unitPrice", label: "Unit Price", required: true },
    { name: "category", label: "Category" },
    { name: "isActive", label: "Active" },
    { name: "description", label: "Description" },
];

export default function ProductsPage() {
    const [products, setProducts] = useState<Product[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<Product | null>(null);
    const [form] = Form.useForm();
    const [search, setSearch] = useState("");
    const [detailOpen, setDetailOpen] = useState(false);
    const [selected, setSelected] = useState<Product | null>(null);

    const fmt = (v: number) => v ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(v) : '$0.00';

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($tenantId: String!, $search: String) { products(tenantId: $tenantId, search: $search) { id name code description unitPrice currency category isActive createdAt } }`, { tenantId: DEFAULT_TENANT_ID, search: search || null });
            setProducts(data.products || []);
        } catch (err: any) { message.error("Failed: " + err.message); }
        finally { setLoading(false); }
    }, [search]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const input = { name: values.name, code: values.code || null, description: values.description || null, unitPrice: values.unitPrice, currency: values.currency || 'USD', category: values.category || null };
            if (editing) {
                await gql(`mutation($id: String!, $input: UpdateProductInput!) { updateProduct(id: $id, input: $input) { id } }`, { id: editing.id, input: { ...input, isActive: values.isActive } });
                message.success("Updated");
            } else {
                await gql(`mutation($tenantId: String!, $input: CreateProductInput!) { createProduct(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input });
                message.success("Created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try { await gql(`mutation($tenantId: String!, $input: CreateProductInput!) { createProduct(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input: { name: r.name, code: r.code || null, description: r.description || null, unitPrice: r.unitPrice || 0, currency: r.currency || 'USD', category: r.category || null } }); success++; }
            catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadData(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => { await gql(`mutation($id: String!) { deleteProduct(id: $id) }`, { id }); message.success("Deleted"); loadData(); };

    const activeProducts = products.filter(p => p.isActive);
    const avgPrice = activeProducts.length ? activeProducts.reduce((s, p) => s + p.unitPrice, 0) / activeProducts.length : 0;

    const columns: ColumnsType<Product> = [
        { title: "Product", key: "name", render: (_, r) => <div><Text strong>{r.name}</Text>{r.code && <><br /><Text type="secondary" code>{r.code}</Text></>}</div>, sorter: (a, b) => a.name.localeCompare(b.name) },
        { title: "Price", key: "price", width: 120, align: "right", render: (_, r) => <Text strong>{fmt(r.unitPrice)}</Text>, sorter: (a, b) => a.unitPrice - b.unitPrice },
        { title: "Category", key: "cat", width: 120, render: (_, r) => r.category ? <Tag>{r.category}</Tag> : '—' },
        { title: "Status", key: "active", width: 90, render: (_, r) => <Tag color={r.isActive ? 'green' : 'default'}>{r.isActive ? 'Active' : 'Inactive'}</Tag> },
        { title: "Actions", key: "actions", width: 130, render: (_, r) => (<Space>
            <Tooltip title="View"><Button type="text" icon={<EyeOutlined />} onClick={() => { setSelected(r); setDetailOpen(true); }} /></Tooltip>
            <Tooltip title="Edit"><Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue({ name: r.name, code: r.code, description: r.description, unitPrice: r.unitPrice, category: r.category, isActive: r.isActive }); setIsModalOpen(true); }} /></Tooltip>
            <Tooltip title="Delete"><Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id) })} /></Tooltip>
        </Space>) },
    ];

    const formSteps = [
        { title: "Product Info", icon: <ShoppingOutlined />, fields: ["name", "code", "unitPrice", "category"], content: (<><Row gutter={16}><Col span={16}><Form.Item name="name" label="Name" rules={[{ required: true }]}><Input /></Form.Item></Col><Col span={8}><Form.Item name="code" label="Product Code"><Input placeholder="e.g., SKU-001" /></Form.Item></Col></Row><Row gutter={16}><Col span={8}><Form.Item name="unitPrice" label="Unit Price" rules={[{ required: true }]}><InputNumber style={{ width: '100%' }} prefix="$" min={0} /></Form.Item></Col><Col span={8}><Form.Item name="category" label="Category"><Select allowClear options={CATEGORIES.map(c => ({ value: c, label: c }))} /></Form.Item></Col>{editing && <Col span={8}><Form.Item name="isActive" label="Active" valuePropName="checked"><Switch /></Form.Item></Col>}</Row></>) },
        { title: "Description", icon: <AppstoreOutlined />, fields: ["description", "isActive"], content: (<Form.Item name="description" label="Description"><TextArea rows={4} /></Form.Item>) },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Products</AuroraText>}
            subTitle={<DecryptedText text="Product catalog for quotes and deals" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>Add Product</Button>,
                <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'crm_products', title: 'CRM Products', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Code', key: 'code' }, { header: 'Category', key: 'category' }, { header: 'Price', key: 'price' }], data: products })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'crm_products', title: 'CRM Products', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Code', key: 'code' }, { header: 'Category', key: 'category' }, { header: 'Price', key: 'price' }], data: products })} /></Tooltip></RbacGuard>,
        ]}>
            <Row gutter={16} style={{ marginBottom: 16 }}>
                <Col span={8}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0 }}><Card ><Statistic title="Total Products" value={products.length} prefix={<ShoppingOutlined />} /></Card></motion.div></Col>
                <Col span={8}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}><Card ><Statistic title="Active" value={activeProducts.length} prefix={<CheckCircleOutlined />} valueStyle={{ color: '#52c41a' }} /></Card></motion.div></Col>
                <Col span={8}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}><Card ><Statistic title="Avg Price" value={avgPrice} prefix={<DollarOutlined />} precision={2} formatter={v => fmt(Number(v))} /></Card></motion.div></Col>
            </Row>
            <Card style={{ marginBottom: 16 }}><Input prefix={<SearchOutlined />} placeholder="Search products..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: 300 }} allowClear /></Card>
            <Card  styles={{ body: { padding: 0 } }}><Table scroll={{ x: 900 }} columns={columns} dataSource={products.map(p => ({ ...p, key: p.id }))} loading={loading} pagination={{ pageSize: 20 }} size="middle" /></Card>

            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? "Edit Product" : "Add Product"} entityName="product" steps={formSteps} fields={PRODUCT_FIELDS} width={600} onBatchCreate={handleBatchCreate} gradient={["#ec4899", "#f43f5e"]} editMode={!!editing} />

            <Drawer title="Product Details" open={detailOpen} onClose={() => setDetailOpen(false)} width={450}>
                {selected && (<Descriptions column={1} bordered size="small">
                    <Descriptions.Item label="Name">{selected.name}</Descriptions.Item>
                    <Descriptions.Item label="Code">{selected.code || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Price"><Text strong>{fmt(selected.unitPrice)}</Text></Descriptions.Item>
                    <Descriptions.Item label="Category">{selected.category || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Status"><Tag color={selected.isActive ? 'green' : 'default'}>{selected.isActive ? 'Active' : 'Inactive'}</Tag></Descriptions.Item>
                    <Descriptions.Item label="Description">{selected.description || '—'}</Descriptions.Item>
                </Descriptions>)}
            </Drawer>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import {
    Table, Button, Space, Modal, Form, Input, Select, Tag, Card,
    message, Typography, Tooltip, Drawer, Descriptions, Row, Col,
    InputNumber, Statistic, DatePicker,
} from "antd";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    SearchOutlined, EyeOutlined, FileTextOutlined,
    DollarOutlined, CheckCircleOutlined, ClockCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import dayjs from "dayjs";

const { Text } = Typography;
const { TextArea } = Input;

interface Quote {
    id: string; quoteNumber: string; name: string;
    dealId: string; accountId: string; contactId: string;
    status: string; subtotal: number; discountPercent: number;
    taxPercent: number; total: number; validUntil: string;
    description: string; dealName: string; accountName: string;
    contactName: string; createdAt: string;
}

const STATUSES = [
    { value: "draft", label: "Draft", color: "default" },
    { value: "presented", label: "Presented", color: "blue" },
    { value: "accepted", label: "Accepted", color: "green" },
    { value: "rejected", label: "Rejected", color: "red" },
    { value: "expired", label: "Expired", color: "orange" },
];

const QUOTE_FIELDS: FieldDef[] = [
    { name: "name", label: "Quote Name", required: true },
    { name: "discountPercent", label: "Discount %" },
    { name: "taxPercent", label: "Tax %" },
    { name: "validUntil", label: "Valid Until" },
    { name: "description", label: "Description" },
    { name: "status", label: "Status" },
];

export default function QuotesPage() {
    const [quotes, setQuotes] = useState<Quote[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<Quote | null>(null);
    const [form] = Form.useForm();
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [detailOpen, setDetailOpen] = useState(false);
    const [selected, setSelected] = useState<Quote | null>(null);

    const fmt = (v: number) => v ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(v) : '$0';

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($tenantId: String!, $status: String, $search: String) { quotes(tenantId: $tenantId, status: $status, search: $search) { id quoteNumber name dealId accountId contactId status subtotal discountPercent taxPercent total validUntil description dealName accountName contactName createdAt } }`, { tenantId: DEFAULT_TENANT_ID, status: statusFilter || null, search: search || null });
            setQuotes(data.quotes || []);
        } catch (err: any) { message.error("Failed: " + err.message); }
        finally { setLoading(false); }
    }, [search, statusFilter]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                const input = { name: values.name, status: values.status || null, discountPercent: values.discountPercent || 0, taxPercent: values.taxPercent || 0, validUntil: values.validUntil?.format('YYYY-MM-DD') || null, description: values.description || null };
                await gql(`mutation($id: String!, $input: UpdateQuoteInput!) { updateQuote(id: $id, input: $input) { id } }`, { id: editing.id, input });
                message.success("Updated");
            } else {
                const input = { name: values.name, discountPercent: values.discountPercent || 0, taxPercent: values.taxPercent || 0, validUntil: values.validUntil?.format('YYYY-MM-DD') || null, description: values.description || null };
                await gql(`mutation($tenantId: String!, $input: CreateQuoteInput!) { createQuote(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input });
                message.success("Created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try { await gql(`mutation($tenantId: String!, $input: CreateQuoteInput!) { createQuote(tenantId: $tenantId, input: $input) { id } }`, { tenantId: DEFAULT_TENANT_ID, input: { name: r.name, discountPercent: r.discountPercent || 0, taxPercent: r.taxPercent || 0, validUntil: r.validUntil || null, description: r.description || null } }); success++; }
            catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadData(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => { await gql(`mutation($id: String!) { deleteQuote(id: $id) }`, { id }); message.success("Deleted"); loadData(); };

    const totalValue = quotes.reduce((s, q) => s + (q.total || 0), 0);
    const acceptedValue = quotes.filter(q => q.status === 'accepted').reduce((s, q) => s + (q.total || 0), 0);
    const draftCount = quotes.filter(q => q.status === 'draft').length;

    const columns: ColumnsType<Quote> = [
        { title: "#", dataIndex: "quoteNumber", key: "num", width: 110, render: v => <Text strong style={{ fontFamily: 'monospace' }}>{v}</Text> },
        { title: "Quote", key: "name", render: (_, r) => <div><Text strong>{r.name}</Text>{r.dealName && <><br /><Text type="secondary" style={{ fontSize: 12 }}>Deal: {r.dealName}</Text></>}</div> },
        { title: "Account", key: "account", width: 140, render: (_, r) => r.accountName || '—' },
        { title: "Total", key: "total", width: 120, align: "right", render: (_, r) => <Text strong>{fmt(r.total)}</Text>, sorter: (a, b) => (a.total || 0) - (b.total || 0) },
        { title: "Status", key: "status", width: 100, render: (_, r) => { const s = STATUSES.find(s => s.value === r.status); return <Tag color={s?.color}>{s?.label || r.status}</Tag>; } },
        { title: "Valid Until", key: "valid", width: 120, render: (_, r) => r.validUntil ? dayjs(r.validUntil).format('MMM D, YYYY') : '—' },
        { title: "Actions", key: "actions", width: 130, render: (_, r) => (<Space>
            <Tooltip title="View"><Button type="text" icon={<EyeOutlined />} onClick={() => { setSelected(r); setDetailOpen(true); }} /></Tooltip>
            <Tooltip title="Edit"><Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue({ name: r.name, status: r.status, discountPercent: r.discountPercent, taxPercent: r.taxPercent, validUntil: r.validUntil ? dayjs(r.validUntil) : null, description: r.description }); setIsModalOpen(true); }} /></Tooltip>
            <Tooltip title="Delete"><Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete ${r.quoteNumber}?`, onOk: () => handleDelete(r.id) })} /></Tooltip>
        </Space>) },
    ];

    const formSteps = [
        { title: "Quote Info", icon: <FileTextOutlined />, fields: ["name", "status", "discountPercent", "taxPercent"], content: (<><Form.Item name="name" label="Quote Name" rules={[{ required: true }]}><Input placeholder="e.g., Acme Corp — Enterprise Package" /></Form.Item><Row gutter={16}>{editing && <Col span={8}><Form.Item name="status" label="Status"><Select options={STATUSES} /></Form.Item></Col>}<Col span={8}><Form.Item name="discountPercent" label="Discount %"><InputNumber style={{ width: '100%' }} min={0} max={100} suffix="%" /></Form.Item></Col><Col span={8}><Form.Item name="taxPercent" label="Tax %"><InputNumber style={{ width: '100%' }} min={0} max={100} suffix="%" /></Form.Item></Col></Row></>) },
        { title: "Details", icon: <DollarOutlined />, fields: ["validUntil", "description"], content: (<><Form.Item name="validUntil" label="Valid Until"><DatePicker style={{ width: '100%' }} /></Form.Item><Form.Item name="description" label="Description"><TextArea rows={2} /></Form.Item></>) },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Quotes</AuroraText>}
            subTitle={<DecryptedText text="Sales quotes and proposals" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>New Quote</Button>,
                <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'crm_quotes', title: 'CRM Quotes', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Quote #', key: 'quoteNumber' }, { header: 'Account', key: 'accountName' }, { header: 'Total', key: 'total' }, { header: 'Status', key: 'status' }], data: quotes })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'crm_quotes', title: 'CRM Quotes', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Quote #', key: 'quoteNumber' }, { header: 'Account', key: 'accountName' }, { header: 'Total', key: 'total' }, { header: 'Status', key: 'status' }], data: quotes })} /></Tooltip></RbacGuard>,
        ]}>
            <Row gutter={16} style={{ marginBottom: 16 }}>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0 }}><Card ><Statistic title="Total Value" value={totalValue} prefix={<DollarOutlined />} precision={0} formatter={v => fmt(Number(v))} /></Card></motion.div></Col>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}><Card ><Statistic title="Accepted" value={acceptedValue} prefix={<CheckCircleOutlined />} precision={0} valueStyle={{ color: '#52c41a' }} formatter={v => fmt(Number(v))} /></Card></motion.div></Col>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}><Card ><Statistic title="Drafts" value={draftCount} prefix={<ClockCircleOutlined />} /></Card></motion.div></Col>
                <Col span={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}><Card ><Statistic title="Total Quotes" value={quotes.length} prefix={<FileTextOutlined />} /></Card></motion.div></Col>
            </Row>
            <Card style={{ marginBottom: 16 }}><Space wrap>
                <Input prefix={<SearchOutlined />} placeholder="Search quotes..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: 250 }} allowClear />
                <Select placeholder="Status" value={statusFilter} onChange={setStatusFilter} allowClear style={{ width: 140 }} options={STATUSES} />
            </Space></Card>
            <Card  styles={{ body: { padding: 0 } }}><Table scroll={{ x: 900 }} columns={columns} dataSource={quotes.map(q => ({ ...q, key: q.id }))} loading={loading} pagination={{ pageSize: 20 }} size="middle" /></Card>

            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? "Edit Quote" : "New Quote"} entityName="quote" steps={formSteps} fields={QUOTE_FIELDS} width={600} onBatchCreate={handleBatchCreate} gradient={["#0ea5e9", "#6366f1"]} editMode={!!editing} />

            <Drawer title="Quote Details" open={detailOpen} onClose={() => setDetailOpen(false)} width={500}>
                {selected && (<Descriptions column={1} bordered size="small">
                    <Descriptions.Item label="Quote #"><Text code>{selected.quoteNumber}</Text></Descriptions.Item>
                    <Descriptions.Item label="Name">{selected.name}</Descriptions.Item>
                    <Descriptions.Item label="Status"><Tag color={STATUSES.find(s => s.value === selected.status)?.color}>{selected.status}</Tag></Descriptions.Item>
                    <Descriptions.Item label="Subtotal">{fmt(selected.subtotal)}</Descriptions.Item>
                    <Descriptions.Item label="Discount">{selected.discountPercent || 0}%</Descriptions.Item>
                    <Descriptions.Item label="Tax">{selected.taxPercent || 0}%</Descriptions.Item>
                    <Descriptions.Item label="Total"><Text strong style={{ fontSize: 16 }}>{fmt(selected.total)}</Text></Descriptions.Item>
                    <Descriptions.Item label="Deal">{selected.dealName || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Account">{selected.accountName || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Contact">{selected.contactName || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Valid Until">{selected.validUntil ? dayjs(selected.validUntil).format('MMM D, YYYY') : '—'}</Descriptions.Item>
                    <Descriptions.Item label="Description">{selected.description || '—'}</Descriptions.Item>
                    <Descriptions.Item label="Created">{dayjs(selected.createdAt).format('MMM D, YYYY')}</Descriptions.Item>
                </Descriptions>)}
            </Drawer>
        </CMSLayout>
    );
}

