import React, { useState } from "react";
import { Modal, Form, Input, Select, message } from "antd";
import { dremioService } from "@/lib/dremioService";

interface AddSourceModalProps {
    open: boolean;
    onClose: () => void;
    onSuccess: () => void;
}

const SOURCE_TYPES = [
    { value: "NAS", label: "NAS (File System)" },
    { value: "S3", label: "Amazon S3 / MinIO" },
    { value: "POSTGRES", label: "PostgreSQL" },
    { value: "MYSQL", label: "MySQL" },
    { value: "MSSQL", label: "SQL Server" },
    { value: "ORACLE", label: "Oracle" },
    { value: "MONGO", label: "MongoDB" },
    { value: "ELASTICSEARCH", label: "Elasticsearch" },
    { value: "HIVE", label: "Hive" },
    { value: "NESSIE", label: "Nessie (Iceberg)" },
];

export default function AddSourceModal({ open, onClose, onSuccess }: AddSourceModalProps) {
    const [form] = Form.useForm();
    const [creating, setCreating] = useState(false);
    const [sourceType, setSourceType] = useState("");

    const handleCreate = async () => {
        try {
            const values = await form.validateFields();
            setCreating(true);

            const config: Record<string, any> = {};
            const type = values.sourceType;

            // Build config based on source type
            if (type === "S3") {
                config.accessKey = values.accessKey || "";
                config.accessSecret = values.accessSecret || "";
                config.secure = false;
                config.externalBucketList = values.buckets ? values.buckets.split(",").map((b: string) => b.trim()) : [];
                config.propertyList = values.endpoint ? [
                    { name: "fs.s3a.endpoint", value: values.endpoint },
                    { name: "fs.s3a.path.style.access", value: "true" },
                ] : [];
            } else if (type === "POSTGRES" || type === "MYSQL" || type === "MSSQL") {
                config.hostname = values.hostname || "";
                config.port = values.port || (type === "POSTGRES" ? "5432" : type === "MYSQL" ? "3306" : "1433");
                config.databaseName = values.databaseName || "";
                config.username = values.dbUsername || "";
                config.password = values.dbPassword || "";
            } else if (type === "NESSIE") {
                config.nessieEndpoint = values.nessieEndpoint || "";
                config.nessieAuthType = "NONE";
                if (values.warehouseLocation) {
                    config.awsRootPath = values.warehouseLocation;
                }
                config.propertyList = [];
                if (values.s3Endpoint) {
                    config.propertyList.push(
                        { name: "fs.s3a.endpoint", value: values.s3Endpoint },
                        { name: "fs.s3a.path.style.access", value: "true" },
                        { name: "dremio.s3.compat", value: "true" },
                    );
                }
                if (values.s3AccessKey) {
                    config.awsAccessKey = values.s3AccessKey;
                    config.awsAccessSecret = values.s3SecretKey || "";
                }
            } else {
                // Generic — pass raw JSON config
                try {
                    Object.assign(config, JSON.parse(values.rawConfig || "{}"));
                } catch { /* ignore parse error */ }
            }

            await dremioService.createSource(values.sourceName, type, config);
            message.success(`Source "${values.sourceName}" created`);
            onSuccess();
            onClose();
            form.resetFields();
            setSourceType("");
        } catch (err: any) {
            if (err.errorFields) return; // Form validation
            message.error("Failed to create source: " + err.message);
        } finally {
            setCreating(false);
        }
    };

    const renderConfigFields = () => {
        switch (sourceType) {
            case "S3":
                return (
                    <>
                        <Form.Item name="accessKey" label="Access Key"><Input /></Form.Item>
                        <Form.Item name="accessSecret" label="Secret Key"><Input.Password /></Form.Item>
                        <Form.Item name="endpoint" label="Endpoint (e.g. minio:9000)"><Input placeholder="minio:9000" /></Form.Item>
                        <Form.Item name="buckets" label="Buckets (comma-separated)"><Input placeholder="bucket1, bucket2" /></Form.Item>
                    </>
                );
            case "POSTGRES":
            case "MYSQL":
            case "MSSQL":
                return (
                    <>
                        <Form.Item name="hostname" label="Hostname" rules={[{ required: true }]}><Input /></Form.Item>
                        <Form.Item name="port" label="Port"><Input placeholder={sourceType === "POSTGRES" ? "5432" : sourceType === "MYSQL" ? "3306" : "1433"} /></Form.Item>
                        <Form.Item name="databaseName" label="Database" rules={[{ required: true }]}><Input /></Form.Item>
                        <Form.Item name="dbUsername" label="Username"><Input /></Form.Item>
                        <Form.Item name="dbPassword" label="Password"><Input.Password /></Form.Item>
                    </>
                );
            case "NESSIE":
                return (
                    <>
                        <Form.Item name="nessieEndpoint" label="Nessie API Endpoint" rules={[{ required: true }]}><Input placeholder="http://nessie:19120/api/v2" /></Form.Item>
                        <Form.Item name="warehouseLocation" label="Warehouse Location"><Input placeholder="s3://bucket/warehouse" /></Form.Item>
                        <Form.Item name="s3Endpoint" label="S3 Endpoint"><Input placeholder="minio:9000" /></Form.Item>
                        <Form.Item name="s3AccessKey" label="S3 Access Key"><Input /></Form.Item>
                        <Form.Item name="s3SecretKey" label="S3 Secret Key"><Input.Password /></Form.Item>
                    </>
                );
            default:
                return (
                    <Form.Item name="rawConfig" label="Configuration (JSON)">
                        <Input.TextArea rows={6} placeholder='{"key": "value"}' style={{ fontFamily: "monospace" }} />
                    </Form.Item>
                );
        }
    };

    return (
        <Modal
            title="Add Data Source"
            open={open}
            onCancel={() => { onClose(); form.resetFields(); setSourceType(""); }}
            onOk={handleCreate}
            confirmLoading={creating}
            width={520}
            okText="Create Source"
        >
            <Form form={form} layout="vertical">
                <Form.Item name="sourceName" label="Source Name" rules={[{ required: true, message: "Name is required" }]}>
                    <Input placeholder="my-source" />
                </Form.Item>
                <Form.Item name="sourceType" label="Source Type" rules={[{ required: true }]}>
                    <Select
                        placeholder="Select type"
                        options={SOURCE_TYPES}
                        onChange={(val) => setSourceType(val)}
                    />
                </Form.Item>
                {sourceType && renderConfigFields()}
            </Form>
        </Modal>
    );
}

import React, { useEffect, useState, useMemo } from 'react';
import { Card, Spin, Empty, Breadcrumb, Button, Input, List, Typography, Tooltip, Tag, Row, Col, Statistic, Space, Select, Dropdown, Menu } from 'antd';
import {
    AppstoreOutlined,
    UnorderedListOutlined,
    ReloadOutlined,
    SearchOutlined,
    DatabaseOutlined,
    FolderOpenOutlined,
    CheckCircleOutlined,
    HomeOutlined,
    FilterOutlined,
    SortAscendingOutlined,
    SortDescendingOutlined,
    MenuFoldOutlined,
    MenuUnfoldOutlined,
    CloudServerOutlined,
    PlusOutlined
} from '@ant-design/icons';
import { dremioService, CatalogItem } from '@/lib/dremioService';
import { getTypeIcon } from './utils';
import { MagicButton } from '@/components/custom/MagicButton';

const { Text } = Typography;

interface CatalogBrowserProps {
    path: string[];
    id: string;
    type: string;
    onNavigate: (path: string[], type: string, id: string) => void;
    sidebarOpen?: boolean;
    onToggleSidebar?: () => void;
    onAddSource?: () => void;
}

export default function CatalogBrowser({ path, id, type, onNavigate, sidebarOpen, onToggleSidebar, onAddSource }: CatalogBrowserProps) {
    console.log("CatalogBrowser rendering:", { path, id, type });
    const [loading, setLoading] = useState(false);
    const [items, setItems] = useState<CatalogItem[]>([]);
    const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
    const [searchQuery, setSearchQuery] = useState('');
    const [filterType, setFilterType] = useState<string>('ALL');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
    const [sourcesCount, setSourcesCount] = useState(0);

    useEffect(() => {
        dremioService.getSources().then(res => setSourcesCount(res.length)).catch(console.error);
    }, []);

    useEffect(() => {
        loadChildren();
    }, [id, path]);

    const loadChildren = async () => {
        try {
            setLoading(true);
            console.log("Loading children for:", { id, path, type });

            // Handle HOME/Root case
            if (type === 'HOME' || (!id && path.length === 0)) {
                const result = await dremioService.getCatalog();
                console.log("Root catalog result:", result);
                setItems(result || []);
                return;
            }

            // Prefer ID-based lookup for containers as it's more robust
            if (id) {
                const result = await dremioService.getCatalogChildren(id);
                console.log("Children result (by ID):", result);
                setItems(result || []);
            } else {
                // Fallback to path if ID is missing
                const result = await dremioService.getCatalogByPath(path);
                console.log("Children result (by Path):", result);
                setItems(result.children || []);
            }
        } catch (error) {
            console.error("Failed to load catalog children:", error);
            setItems([]);
        } finally {
            setLoading(false);
        }
    };

    const handleItemClick = (item: CatalogItem) => {
        onNavigate(item.path, item.type, item.id);
    };

    // Dremio-queryable file extensions
    const QUERYABLE_EXTENSIONS = ['xlsx', 'xls', 'csv', 'tsv', 'json', 'parquet', 'orc', 'avro'];

    const isQueryableFile = (item: CatalogItem): boolean => {
        if (item.type !== 'FILE') return true; // Non-FILE items always pass
        const name = item.path[item.path.length - 1] || '';
        const ext = name.split('.').pop()?.toLowerCase() || '';
        return QUERYABLE_EXTENSIONS.includes(ext);
    };

    const processedItems = useMemo(() => {
        // 0. Filter out non-queryable files
        let result = items.filter(isQueryableFile);

        // 1. Search Filter
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            result = result.filter(item =>
                (item.path[item.path.length - 1] || '').toLowerCase().includes(query)
            );
        }

        // 2. Type Filter
        if (filterType !== 'ALL') {
            if (filterType === 'FOLDER') {
                result = result.filter(item => ['FOLDER', 'SPACE', 'SOURCE', 'HOME'].includes(item.type));
            } else if (filterType === 'DATASET') {
                result = result.filter(item => ['DATASET', 'PHYSICAL_DATASET', 'VIRTUAL_DATASET', 'DATASET_TABLE', 'DATASET_VIRTUAL', 'FILE'].includes(item.type));
            }
        }

        // 3. Sorting
        result = [...result].sort((a, b) => {
            const nameA = (a.path[a.path.length - 1] || '').toLowerCase();
            const nameB = (b.path[b.path.length - 1] || '').toLowerCase();
            return sortOrder === 'asc' ? nameA.localeCompare(nameB) : nameB.localeCompare(nameA);
        });

        return result;
    }, [items, searchQuery, filterType, sortOrder]);

    const breadcrumbItems = [
        {
            title: <HomeOutlined />,
            onClick: () => onNavigate([], 'HOME', '')
        },
        ...path.map((p, index) => ({
            title: p,
            onClick: () => {
                const newPath = path.slice(0, index + 1);
                onNavigate(newPath, 'FOLDER', '');
            }
        }))
    ];

    const glassCardStyle = {
        background: 'rgba(255, 255, 255, 0.6)',
        backdropFilter: 'blur(12px)',
        WebkitBackdropFilter: 'blur(12px)',
        boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.04)',
        border: '1px solid rgba(255, 255, 255, 0.5)',
    };

    const glassHeaderStyle = {
        background: 'rgba(255, 255, 255, 0.1)',
        borderBottom: '1px solid rgba(var(--theme-color-rgb, 139, 92, 246), 0.2)',
    };

    const renderGridItem = (item: CatalogItem) => {
        const name = item.path[item.path.length - 1];

        return (
            <div
                key={item.id}
                onClick={() => handleItemClick(item)}
                className="group relative flex flex-col items-center justify-center p-4 rounded-xl border border-gray-100 dark:border-gray-800 bg-white dark:bg-gray-900/40 shadow-sm hover:border-[rgba(var(--theme-color-rgb,139,92,246),0.3)] dark:hover:border-[rgba(var(--theme-color-rgb,139,92,246),0.5)] hover:shadow-md hover:shadow-[rgba(var(--theme-color-rgb,139,92,246),0.1)] transition-all cursor-pointer aspect-square"
            >
                <div className="mb-3 transform group-hover:scale-110 transition-transform duration-300">
                    <span className="flex text-[32px]">
                        {getTypeIcon(item.type, (item as any).containerType)}
                    </span>
                </div>
                <Text
                    className="text-center font-medium text-gray-700 dark:text-gray-300 group-hover:text-[color:var(--theme-color, #7c3aed)] dark:group-hover:text-[color:var(--theme-color, #7c3aed)] w-full truncate px-2"
                    style={{ fontSize: 13 }}
                >
                    {name}
                </Text>
                <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {item.type === 'FOLDER' && <Tag bordered={false} className="m-0 text-[10px] bg-orange-50 text-orange-600">DIR</Tag>}
                    {['DATASET', 'PHYSICAL_DATASET', 'VIRTUAL_DATASET', 'FILE'].includes(item.type) && <Tag bordered={false} className="m-0 text-[10px] bg-blue-50 text-blue-600">DS</Tag>}
                </div>
            </div>
        );
    };

    const renderListItem = (item: CatalogItem) => {
        const name = item.path[item.path.length - 1];
        return (
            <List.Item
                onClick={() => handleItemClick(item)}
                className="cursor-pointer hover:bg-gray-50 dark:hover:bg-white/5 rounded-lg px-2 transition-colors border-0 !border-b-0 mb-1"
                style={{ border: 'none' }}
            >
                <List.Item.Meta
                    avatar={<div className="mt-1">{getTypeIcon(item.type, (item as any).containerType)}</div>}
                    title={
                        <span className="text-sm font-medium text-gray-700 dark:text-gray-200 group-hover:text-[color:var(--theme-color, #7c3aed)]">
                            {name}
                        </span>
                    }
                    description={
                        <span className="text-xs text-gray-400">
                            {item.type.replace(/_/g, ' ')}
                        </span>
                    }
                />
            </List.Item>
        );
    };

    return (
        <div className="h-full flex flex-col gap-4 overflow-hidden">
            {/* Header Card */}
            <Card
                size="small"
                style={glassCardStyle}
                className="dark:!bg-[rgba(15,15,23,0.6)] dark:!border-[rgba(var(--theme-color-rgb,139,92,246),0.2)]"
                styles={{ header: glassHeaderStyle }}
                title={
                    <div className="flex items-center gap-3">
                        {onToggleSidebar && (
                            <Button
                                type="text"
                                icon={sidebarOpen ? <MenuFoldOutlined /> : <MenuUnfoldOutlined />}
                                onClick={onToggleSidebar}
                                className="text-gray-500 hover:text-[color:var(--theme-color, #7c3aed)]"
                            />
                        )}
                        <span style={{ background: 'linear-gradient(to right, var(--theme-color, #8b5cf6), var(--theme-secondary, #6366f1))', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', fontWeight: 600 }}>
                            {path[path.length - 1] || 'Catalog'}
                        </span>
                    </div>
                }
                extra={
                    <Space size={8}>
                        {/* Sources Count */}
                        <Tag icon={<CloudServerOutlined />}  bordered={false} className="px-2 py-0.5 text-[11px] bg-[rgba(var(--theme-color-rgb,139,92,246),0.05)] text-[color:var(--theme-color, #7c3aed)] dark:bg-[rgba(var(--theme-color-rgb,139,92,246),0.2)] dark:text-[color:var(--theme-color, #7c3aed)] rounded-md m-0">
                            {sourcesCount} Sources
                        </Tag>

                        {/* Search */}
                        <Input
                            prefix={<SearchOutlined className="text-gray-400" />}
                            placeholder="Filter..."
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            className="w-32 md:w-48 !bg-transparent border-b !border-0 focus:border-b-[var(--theme-color,#7c3aed)] transition-colors"
                            bordered={false}
                            size="small"
                        />

                        <div className="w-px h-4 bg-gray-200 dark:bg-gray-700 mx-1" />

                        {/* Filter Type */}
                        <Select
                            value={filterType}
                            onChange={setFilterType}
                            size="small"
                            bordered={false}
                            className="w-24 text-xs"
                            dropdownMatchSelectWidth={false}
                            suffixIcon={<FilterOutlined className="text-xs text-gray-400" />}
                            options={[
                                { value: 'ALL', label: 'All Types' },
                                { value: 'FOLDER', label: 'Folders' },
                                { value: 'DATASET', label: 'Datasets' },
                            ]}
                        />

                        {/* Sort Order */}
                        <Tooltip title={`Sort by Name (${sortOrder === 'asc' ? 'A-Z' : 'Z-A'})`}>
                            <Button
                                type="text"
                                size="small"
                                icon={sortOrder === 'asc' ? <SortAscendingOutlined /> : <SortDescendingOutlined />}
                                onClick={() => setSortOrder(prev => prev === 'asc' ? 'desc' : 'asc')}
                                className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)]"
                            />
                        </Tooltip>

                        <div className="w-px h-4 bg-gray-200 dark:bg-gray-700 mx-1" />

                        {/* View Mode */}
                        <div className="flex bg-gray-100 dark:bg-gray-800 rounded-lg p-0.5">
                            <Button
                                type="text"
                                size="small"
                                icon={<AppstoreOutlined style={{ fontSize: 12 }} />}
                                className={viewMode === 'grid' ? 'bg-white dark:bg-gray-700 shadow-sm text-[color:var(--theme-color, #7c3aed)]' : 'text-gray-400'}
                                onClick={() => setViewMode('grid')}
                                style={{ width: 24, height: 24, minWidth: 24 }}
                            />
                            <Button
                                type="text"
                                size="small"
                                icon={<UnorderedListOutlined style={{ fontSize: 12 }} />}
                                className={viewMode === 'list' ? 'bg-white dark:bg-gray-700 shadow-sm text-[color:var(--theme-color, #7c3aed)]' : 'text-gray-400'}
                                onClick={() => setViewMode('list')}
                                style={{ width: 24, height: 24, minWidth: 24 }}
                            />
                        </div>

                        <div className="w-px h-4 bg-gray-200 dark:bg-gray-700 mx-1" />

                        {/* Refresh */}
                        <Tooltip title="Refresh">
                            <Button type="text" size="small" icon={<ReloadOutlined />} onClick={loadChildren} />
                        </Tooltip>

                        {/* Add Source */}
                        {onAddSource && (
                            <MagicButton
                                icon={<PlusOutlined style={{ fontSize: 10 }} />}
                                onClick={onAddSource}
                                size="small"
                            >
                                Add Source
                            </MagicButton>
                        )}
                    </Space>
                }
            >
                <Breadcrumb items={breadcrumbItems} className="text-xs" />
            </Card>

            {/* Stats Card */}
            <Card
                size="small"
                style={glassCardStyle}
                className="dark:!bg-[rgba(15,15,23,0.6)] dark:!border-[rgba(var(--theme-color-rgb,139,92,246),0.2)]"
                bodyStyle={{ padding: 12 }}
            >
                <Row gutter={16} align="middle" justify="start">
                    <Col>
                        <Statistic
                            title={<span className="text-[10px] text-gray-500 uppercase tracking-wider">Items</span>}
                            value={items.length}
                            valueStyle={{ color: 'var(--theme-color, #8b5cf6)', fontWeight: 600, fontSize: 16 }}
                            suffix={<span className="text-xs text-gray-400">total</span>}
                        />
                    </Col>
                    <Col>
                        <div className="h-8 w-px bg-gray-100 dark:bg-gray-800 mx-2" />
                    </Col>
                    <Col>
                        <Statistic
                            title={<span className="text-[10px] text-gray-500 uppercase tracking-wider">Type</span>}
                            value={type || 'Container'}
                            valueStyle={{ color: '#6366f1', fontWeight: 600, fontSize: 16 }}
                        />
                    </Col>
                </Row>
            </Card>

            {/* Content */}
            <div className="flex-1 overflow-auto custom-scrollbar">
                {loading ? (
                    <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-2">
                        <Spin />
                        <span className="text-sm">Loading contents...</span>
                    </div>
                ) : processedItems.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-gray-400">
                        <Empty
                            image={Empty.PRESENTED_IMAGE_SIMPLE}
                            description="No items found"
                        />
                    </div>
                ) : (
                    viewMode === 'grid' ? (
                        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 pb-4">
                            {processedItems.map(renderGridItem)}
                        </div>
                    ) : (
                        <List
                            itemLayout="horizontal"
                            dataSource={processedItems}
                            renderItem={renderListItem}
                            className="w-full"
                        />
                    )
                )}
            </div>
        </div>
    );
}

"use client";

import React from 'react';
import { Tree, Card } from 'antd';

interface CatalogTreeProps {
    onSelect: (path: string[], type: string, id: string) => void;
}

export default function CatalogTreeSimple({ onSelect }: CatalogTreeProps) {
    return (
        <Card title="Catalog">
            <p>Simple Catalog Tree</p>
        </Card>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { Tree, Input, Button, Card, Space, ConfigProvider, theme, message, Tag, Dropdown, Modal } from 'antd';
import type { TreeProps, MenuProps } from 'antd';
import {
    FolderAddOutlined,
    TableOutlined,
    FolderOutlined,
    SearchOutlined,
    ReloadOutlined,
    PlusOutlined,
    ExpandAltOutlined,
    CompressOutlined,
    CaretRightOutlined,
    CaretDownOutlined,
    CloudServerOutlined,
    DeleteOutlined,
    EditOutlined,
    MoreOutlined,
} from '@ant-design/icons';
import { dremioService, CatalogItem, DremioSource } from '@/lib/dremioService';
import { getTypeIcon } from './utils';
import { TooltipWrapper as AnimatedTooltip } from '@/components/mvpblocks/AnimatedTooltip';

interface CatalogTreeProps {
    onSelect: (path: string[], type: string, id: string) => void;
    onCreateSpace?: () => void;
    onCreateVDS?: () => void;
    onAddSource?: () => void;
    onDeleteItem?: (id: string, type: string, tag: string) => void;
    onEditVDS?: (id: string, tag: string) => void;
    onRenameSpace?: (id: string, tag: string, currentName: string) => void;
    refreshTrigger?: number;
    className?: string;
    style?: React.CSSProperties;
}

export default function CatalogTree({ onSelect, onCreateSpace, onCreateVDS, onAddSource, onDeleteItem, onEditVDS, onRenameSpace, refreshTrigger = 0, className, style }: CatalogTreeProps) {
    const [treeGroups, setTreeGroups] = useState<{
        spaces: any[];
        lakehouse: any[];
        storage: any[];
        databases: any[];
    }>({ spaces: [], lakehouse: [], storage: [], databases: [] });

    const [expandedKeys, setExpandedKeys] = useState<React.Key[]>([]);
    const [selectedKeys, setSelectedKeys] = useState<React.Key[]>([]);
    const [searchValue, setSearchValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [collapsedSections, setCollapsedSections] = useState<Record<string, boolean>>({});
    const { token } = theme.useToken();

    useEffect(() => {
        loadData();
    }, [refreshTrigger]);

    const loadData = async () => {
        try {
            setLoading(true);
            const [catalog, sourcesDetail] = await Promise.all([
                dremioService.getCatalog(),
                dremioService.getSources()
            ]);

            const groups: typeof treeGroups = {
                spaces: [],
                lakehouse: [],
                storage: [],
                databases: []
            };

            // Process Spaces and Home from Catalog
            catalog.forEach(item => {
                const name = item.path[item.path.length - 1];
                const type = item.containerType || item.type;

                const node: any = {
                    title: name,
                    key: item.id,
                    isLeaf: false,
                    icon: getTypeIcon(type),
                    data: item
                };

                if (type === 'SPACE' || type === 'HOME') {
                    groups.spaces.push(node);
                }
            });

            // Process Sources directly from Sources API to ensure visibility
            sourcesDetail.forEach(source => {
                const sourceType = (source.type || 'UNKNOWN').toUpperCase();
                const node: any = {
                    title: source.name,
                    key: source.id,
                    isLeaf: false, // Sources always have children
                    icon: getTypeIcon('SOURCE', sourceType),
                    data: {
                        id: source.id,
                        path: [source.name],
                        type: 'SOURCE',
                        containerType: sourceType,
                        tag: source.tag,
                        sourceType: sourceType
                    }
                };

                // Add explicit checks for common source types
                if (['NESSIE', 'ICEBERG', 'DELTA'].includes(sourceType)) {
                    groups.lakehouse.push(node);
                } else if (['S3', 'AWS', 'AWS S3', 'MINIO', 'AZURE_STORAGE', 'AZURE', 'GCS', 'ADLS', 'HDFS', 'NAS', 'FILESYSTEM'].includes(sourceType)) {
                    groups.storage.push(node);
                } else {
                    groups.databases.push(node);
                }
            });

            setTreeGroups(groups);
        } catch (error) {
            console.error("Failed to load catalog tree:", error);
            message.error("Failed to load catalog");
        } finally {
            setLoading(false);
        }
    };

    const onLoadData = ({ key, children, data }: any) => {
        return new Promise<void>(async (resolve) => {
            if (children && children.length > 0) {
                resolve();
                return;
            }
            try {
                const item = data as CatalogItem;
                // For sources, we might need to use getCatalogChildren or getCatalogByPath
                // Dremio API usually works with path for children
                const detail = await dremioService.getCatalogByPath(item.path);
                const childrenItems = detail.children || [];

                const mapNodes = (list: any[]): any[] => {
                    return list.map(node => {
                        if (node.key === key) {
                            return {
                                ...node,
                                children: childrenItems.map(child => ({
                                    title: child.path[child.path.length - 1],
                                    key: child.id,
                                    isLeaf: ['DATASET', 'PHYSICAL_DATASET', 'VIRTUAL_DATASET', 'DATASET_TABLE', 'DATASET_VIRTUAL'].includes(child.type),
                                    icon: getTypeIcon(child.type),
                                    data: child
                                }))
                            };
                        }
                        if (node.children) return { ...node, children: mapNodes(node.children) };
                        return node;
                    });
                };

                setTreeGroups(prev => ({
                    spaces: mapNodes(prev.spaces),
                    lakehouse: mapNodes(prev.lakehouse),
                    storage: mapNodes(prev.storage),
                    databases: mapNodes(prev.databases)
                }));
            } catch (error) {
                console.error("Failed to load children:", error);
            }
            resolve();
        });
    };

    const onTreeSelect: TreeProps['onSelect'] = (keys, info: any) => {
        setSelectedKeys(keys);
        if (keys.length > 0) {
            const item = info.node.data as CatalogItem;
            onSelect(item.path, item.type, item.id);
        }
    };

    // Filter logic for grouped trees
    const filteredGroups = useMemo(() => {
        if (!searchValue) return treeGroups;
        const lowerSearch = searchValue.toLowerCase();

        const filterNodes = (nodes: any[]): any[] => {
            return nodes.map(node => {
                const match = (node.title as string).toLowerCase().includes(lowerSearch);
                const children = node.children ? filterNodes(node.children) : [];
                if (match || children.length > 0) return { ...node, children };
                return null;
            }).filter(Boolean) as any[];
        };

        return {
            spaces: filterNodes(treeGroups.spaces),
            lakehouse: filterNodes(treeGroups.lakehouse),
            storage: filterNodes(treeGroups.storage),
            databases: filterNodes(treeGroups.databases)
        };
    }, [treeGroups, searchValue]);

    const titleRender = (node: any) => {
        const isSelected = selectedKeys.includes(node.key);
        const item = node.data;
        // Check for NESSIE either in sourceType (from our mapping) or from item.containerType if available
        const isNessie = (item.sourceType === 'NESSIE' || item.containerType === 'NESSIE');
        const subtext = isNessie ? 'main' : undefined;

        // Count for folders/sources
        const count = node.children?.length || (item as any).children?.length || 0;

        return (
            <div className="flex items-center w-full pr-2 h-full py-1 group/item" style={{ gap: 8 }}>
                <span className="shrink-0 flex items-center">
                    {node.icon}
                </span>

                <span className={`truncate text-[13px] ${isSelected ? 'font-semibold text-white' : 'text-gray-700 dark:text-gray-200'}`}>
                    {node.title}
                </span>

                {subtext && (
                    <Tag bordered={false} className="ml-1 px-1 py-0 text-[10px] bg-gray-100 dark:bg-gray-800 text-gray-400 rounded flex items-center gap-1">
                        <ReloadOutlined style={{ fontSize: 8 }} />
                        {subtext}
                    </Tag>
                )}

                <span className={`ml-auto text-[10px] transition-opacity ${isSelected ? 'text-white/70' : 'text-gray-400 opacity-60 group-hover/item:opacity-100'}`}>
                    {count > 0 ? count : ''}
                </span>
            </div>
        );
    };

    const getContextMenu = (node: any): MenuProps['items'] => {
        const item = node.data;
        const type = item?.type || item?.containerType || '';
        const items: MenuProps['items'] = [];
        if (['DATASET', 'VIRTUAL_DATASET', 'DATASET_VIRTUAL'].includes(type)) {
            items.push({ key: 'editVDS', icon: <EditOutlined />, label: 'Edit VDS' });
            items.push({ type: 'divider' });
            items.push({ key: 'deleteVDS', icon: <DeleteOutlined />, label: 'Delete VDS', danger: true });
        }
        if (type === 'SPACE') {
            items.push({ key: 'renameSpace', icon: <EditOutlined />, label: 'Rename Space' });
            items.push({ type: 'divider' });
            items.push({ key: 'deleteSpace', icon: <DeleteOutlined />, label: 'Delete Space', danger: true });
        }
        if (type === 'SOURCE') {
            items.push({ key: 'deleteSource', icon: <DeleteOutlined />, label: 'Delete Source', danger: true });
        }
        return items.length > 0 ? items : [{ key: 'none', label: 'No actions', disabled: true }];
    };

    const handleContextAction = (key: string, node: any) => {
        const item = node.data;
        const tag = item?.tag || '';
        const name = item?.path?.[item.path.length - 1] || 'this item';

        // Non-destructive actions
        if (key === 'editVDS') {
            if (onEditVDS) onEditVDS(item.id, tag);
            else message.info('Edit VDS handler not connected');
            return;
        }
        if (key === 'renameSpace') {
            if (onRenameSpace) onRenameSpace(item.id, tag, name);
            else message.info('Rename handler not connected');
            return;
        }

        // Destructive actions — confirm first
        Modal.confirm({
            title: `Delete "${name}"?`,
            content: 'This action cannot be undone.',
            okText: 'Delete',
            okType: 'danger',
            onOk: () => {
                if (onDeleteItem) onDeleteItem(item.id, key, tag);
                else message.info('Delete handler not connected');
            },
        });
    };

    const toggleSection = (key: string) => {
        setCollapsedSections(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const renderHeader = (title: string, count: number, sectionKey: string, onAdd?: () => void) => (
        <div
            className="flex items-center w-full py-2 group/header select-none px-2 mb-1 cursor-pointer hover:bg-gray-50 dark:hover:bg-white/5 rounded-sm transition-colors"
            onClick={() => toggleSection(sectionKey)}
        >
            <span className="mr-1.5 text-[10px] text-[#8b929e] transition-transform" style={{ transform: collapsedSections[sectionKey] ? 'rotate(0deg)' : 'rotate(90deg)' }}>
                <CaretRightOutlined />
            </span>
            <span className="text-[11px] font-bold uppercase tracking-widest text-[#8b929e]">
                {title} ({count})
            </span>
            {onAdd && (
                <PlusOutlined
                    onClick={(e) => { e.stopPropagation(); onAdd(); }}
                    className="ml-auto text-[12px] text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)] opacity-0 group-hover/header:opacity-100 transition-opacity p-1 cursor-pointer"
                />
            )}
        </div>
    );

    const handleExpandAll = () => {
        setCollapsedSections({});
    };

    const handleCollapseAll = () => {
        setCollapsedSections({
            spaces: true,
            sources: true,
            lakehouse: true,
            storage: true,
            databases: true
        });
    };

    const treeProps: Partial<TreeProps> = {
        showLine: false,
        showIcon: false,
        switcherIcon: () => <span style={{ width: 0 }} />,
        loadData: onLoadData,
        onExpand: (keys) => {
            setExpandedKeys(keys);
        },
        expandedKeys: expandedKeys,
        autoExpandParent: true,
        onSelect: onTreeSelect,
        selectedKeys: selectedKeys,
        titleRender: titleRender,
        blockNode: true,
        className: "custom-dremio-tree"
    };

    return (
        <Card
            size="small"
            title={
                <div className="flex items-center gap-2">
                    <span style={{
                        background: 'linear-gradient(to right, var(--theme-color, #8b5cf6), var(--theme-secondary, #6366f1))',
                        WebkitBackgroundClip: 'text',
                        WebkitTextFillColor: 'transparent',
                        fontWeight: 600,
                        fontSize: '14px'
                    }}>
                        Explorer
                    </span>
                </div>
            }
            extra={
                <div className="flex items-center gap-1">
                    <AnimatedTooltip content="Expand All">
                        <Button
                            type="text"
                            icon={<ExpandAltOutlined style={{ fontSize: 14 }} />}
                            onClick={handleExpandAll}
                            size="small"
                            className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)] flex items-center justify-center w-7 h-7"
                        />
                    </AnimatedTooltip>
                    <AnimatedTooltip content="Collapse All">
                        <Button
                            type="text"
                            icon={<CompressOutlined style={{ fontSize: 14 }} />}
                            onClick={handleCollapseAll}
                            size="small"
                            className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)] flex items-center justify-center w-7 h-7"
                        />
                    </AnimatedTooltip>

                    <div className="w-[1px] h-3 bg-gray-200 dark:bg-gray-700 mx-1" />

                    {onCreateSpace && (
                        <AnimatedTooltip content="New Space">
                            <Button
                                type="text"
                                icon={<FolderAddOutlined style={{ fontSize: 14 }} />}
                                onClick={onCreateSpace}
                                size="small"
                                className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)] flex items-center justify-center w-7 h-7"
                            />
                        </AnimatedTooltip>
                    )}
                    {onAddSource && (
                        <AnimatedTooltip content="Add Source">
                            <Button
                                type="text"
                                icon={<PlusOutlined style={{ fontSize: 14 }} />}
                                onClick={onAddSource}
                                size="small"
                                className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)] flex items-center justify-center w-7 h-7"
                            />
                        </AnimatedTooltip>
                    )}
                </div>
            }
            style={{
                display: 'flex',
                flexDirection: 'column',
                minHeight: 'calc(100vh - 200px)',
                background: 'transparent',
                backdropFilter: 'none',
                WebkitBackdropFilter: 'none',
                boxShadow: 'none',
                border: 'none',
                ...style
            }}
            className={`dark:!bg-transparent dark:!border-none ${className}`}
            styles={{
                header: {
                    background: 'transparent',
                    borderBottom: '1px solid rgba(var(--theme-color-rgb, 139, 92, 246), 0.2)',
                    minHeight: 40,
                    padding: '0 12px'
                },
                body: {
                    padding: '12px 0',
                    flex: 1,
                    overflow: 'auto'
                }
            }}
        >
            <div className="px-3 mb-4 flex items-center gap-2">
                <Input
                    placeholder="Search catalog..."
                    prefix={<SearchOutlined style={{ color: token.colorTextPlaceholder, fontSize: 13 }} />}
                    value={searchValue}
                    onChange={(e) => setSearchValue(e.target.value)}
                    size="small"
                    className="flex-1 rounded-md border-gray-200 dark:border-gray-800 bg-gray-50/50 dark:bg-gray-900/50 h-8 hover:bg-white dark:hover:bg-gray-800 focus:bg-white dark:focus:bg-gray-800 transition-all"
                    allowClear
                />
                <AnimatedTooltip content="Refresh Catalog">
                    <Button
                        type="text"
                        icon={<ReloadOutlined style={{ fontSize: 13 }} />}
                        onClick={loadData}
                        size="small"
                        className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)]"
                    />
                </AnimatedTooltip>
            </div>

            <ConfigProvider
                theme={{
                    components: {
                        Tree: {
                            controlItemBgActive: 'var(--theme-color, #7c3aed)',
                            controlItemBgHover: 'rgba(var(--theme-color-rgb, 139, 92, 246), 0.05)',
                            paddingXS: 4
                        }
                    }
                }}
            >
                <div className="px-1 custom-scrollbar overflow-x-hidden overflow-y-auto" style={{ maxHeight: 'calc(100vh - 280px)' }}>
                    {/* Spaces Section */}
                    {(filteredGroups.spaces.length > 0 || !searchValue) && (
                        <div className="mb-4">
                            {renderHeader("Spaces", treeGroups.spaces.length, 'spaces', onCreateSpace)}
                            {!collapsedSections['spaces'] && <Tree {...treeProps} treeData={filteredGroups.spaces} />}
                        </div>
                    )}

                    <div>
                        {renderHeader(
                            "Sources",
                            treeGroups.lakehouse.length + treeGroups.storage.length + treeGroups.databases.length,
                            'sources',
                            onAddSource
                        )}

                        {!collapsedSections['sources'] && (
                            <>
                                {/* Lakehouse Section */}
                                {(filteredGroups.lakehouse.length > 0 || !searchValue) && (
                                    <div className="mb-4">
                                        {renderHeader("Lakehouse Catalogs", treeGroups.lakehouse.length, 'lakehouse')}
                                        {!collapsedSections['lakehouse'] && <Tree {...treeProps} treeData={filteredGroups.lakehouse} />}
                                    </div>
                                )}

                                {/* Storage Section */}
                                {(filteredGroups.storage.length > 0 || !searchValue) && (
                                    <div className="mb-4">
                                        {renderHeader("Object Storage", treeGroups.storage.length, 'storage')}
                                        {!collapsedSections['storage'] && <Tree {...treeProps} treeData={filteredGroups.storage} />}
                                    </div>
                                )}

                                {/* Databases Section */}
                                {(filteredGroups.databases.length > 0 || !searchValue) && (
                                    <div className="mb-2">
                                        {renderHeader("Databases", treeGroups.databases.length, 'databases')}
                                        {!collapsedSections['databases'] && <Tree {...treeProps} treeData={filteredGroups.databases} />}
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>

                <style jsx global>{`
                    .custom-dremio-tree .ant-tree-treenode {
                        padding: 0 4px !important;
                        margin-bottom: 2px;
                        width: 100%;
                    }
                    .custom-dremio-tree .ant-tree-node-content-wrapper {
                        padding: 0 4px !important;
                        border-radius: 4px;
                        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
                        line-height: 28px;
                        height: 28px;
                    }
                    .custom-dremio-tree .ant-tree-switcher {
                        line-height: 28px !important;
                        display: flex !important;
                        align-items: center;
                        justify-content: center;
                        width: 16px !important;
                    }
                    .custom-dremio-tree .ant-tree-node-content-wrapper:hover {
                        background: rgba(var(--theme-color-rgb, 124, 58, 237), 0.08) !important;
                    }
                    .custom-dremio-tree .ant-tree-node-selected {
                        background: none !important;
                        transition: none !important;
                    }
                `}</style>
            </ConfigProvider>
        </Card>
    );

}

"use client";

import React, { useState } from "react";
import { Modal, Form, Input, Select, Button, message, Space, Tag } from "antd";
import { EyeOutlined, SaveOutlined } from "@ant-design/icons";
import { dremioService, CatalogItem } from "@/lib/dremioService";

interface CreateVDSModalProps {
    open: boolean;
    onClose: () => void;
    onCreated?: () => void;
    defaultSQL?: string;
    spaces?: CatalogItem[];
}

export default function CreateVDSModal({ open, onClose, onCreated, defaultSQL, spaces = [] }: CreateVDSModalProps) {
    const [form] = Form.useForm();
    const [creating, setCreating] = useState(false);
    const [previewLoading, setPreviewLoading] = useState(false);
    const [previewCount, setPreviewCount] = useState<number | null>(null);

    const handleCreate = async () => {
        try {
            const values = await form.validateFields();
            setCreating(true);

            const pathParts = values.targetPath.split(".").map((p: string) => p.trim());
            const sqlContext = values.sqlContext ? values.sqlContext.split(".").map((p: string) => p.trim()) : undefined;

            await dremioService.createVDS(pathParts, values.sql, sqlContext);
            message.success(`Virtual dataset "${values.targetPath}" created`);
            form.resetFields();
            onClose();
            onCreated?.();
        } catch (err: any) {
            if (err.errorFields) return;
            message.error("Failed to create VDS: " + err.message);
        } finally {
            setCreating(false);
        }
    };

    const handlePreview = async () => {
        try {
            const sql = form.getFieldValue("sql");
            if (!sql?.trim()) {
                message.warning("Enter a SQL query first");
                return;
            }
            setPreviewLoading(true);
            const result = await dremioService.runSQL(`${sql.trim()} LIMIT 10`);
            setPreviewCount(result.rowCount);
            message.success(`Preview: ${result.rowCount} rows returned`);
        } catch (err: any) {
            message.error("Preview failed: " + err.message);
        } finally {
            setPreviewLoading(false);
        }
    };

    return (
        <Modal
            title="Create Virtual Dataset (View)"
            open={open}
            onCancel={() => { form.resetFields(); setPreviewCount(null); onClose(); }}
            footer={
                <Space>
                    <Button onClick={onClose}>Cancel</Button>
                    <Button icon={<EyeOutlined />} onClick={handlePreview} loading={previewLoading}>
                        Preview
                    </Button>
                    <Button type="primary" icon={<SaveOutlined />} onClick={handleCreate} loading={creating}
                        style={{ background: "linear-gradient(135deg, #1890ff, #096dd9)", border: "none" }}>
                        Create View
                    </Button>
                </Space>
            }
            width={600}
        >
            <Form form={form} layout="vertical" initialValues={{ sql: defaultSQL || "" }}>
                <Form.Item
                    name="targetPath"
                    label="Target Path"
                    rules={[{ required: true, message: "Path is required (e.g. MySpace.my_view)" }]}
                    help="e.g. MySpace.my_view or @admin.my_view"
                >
                    <Input placeholder="Space.view_name" />
                </Form.Item>
                <Form.Item
                    name="sql"
                    label="SQL Query"
                    rules={[{ required: true, message: "SQL is required" }]}
                >
                    <Input.TextArea
                        rows={6}
                        placeholder="SELECT * FROM source.schema.table WHERE ..."
                        style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12 }}
                    />
                </Form.Item>
                <Form.Item
                    name="sqlContext"
                    label="SQL Context (Optional)"
                    help="Default schema context, e.g. nessie"
                >
                    <Input placeholder="source.schema" />
                </Form.Item>
                {previewCount !== null && (
                    <Tag color="green" style={{ marginTop: 8 }}>
                        Preview returned {previewCount} rows
                    </Tag>
                )}
            </Form>
        </Modal>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Spin, Empty, Tag, Button, Space, message, Tooltip, Statistic, Row, Col, Card, Pagination, theme } from "antd";
import {
    DownloadOutlined,
    FileExcelOutlined,
    ReloadOutlined,
    TableOutlined,
    ColumnWidthOutlined,
} from "@ant-design/icons";
import { dremioService, QueryResult, QueryColumn } from "@/lib/dremioService";

interface DataPreviewProps {
    path: string[];
    limit?: number;
}

export default function DataPreview({ path, limit = 100 }: DataPreviewProps) {
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [result, setResult] = useState<QueryResult | null>(null);
    const [loading, setLoading] = useState(false);

    const tableContainerRef = React.useRef<HTMLDivElement>(null);
    const [tableScrollHeight, setTableScrollHeight] = useState<number>(400);

    React.useEffect(() => {
        if (!tableContainerRef.current) return;

        const observer = new ResizeObserver((entries) => {
            for (const entry of entries) {
                // The absolute-table flex container only holds the Table now.
                // Subtracting 40 explicitly reserves space for the Table Head row, letting the body take the rest.
                const newHeight = entry.contentRect.height - 40;
                setTableScrollHeight(Math.max(newHeight, 100)); // Minimum height ensures it never collapses completely
            }
        });

        observer.observe(tableContainerRef.current);
        return () => observer.disconnect();
    }, [result]); // Re-bind observer when result renders the table into DOM

    const loadPreview = async () => {
        if (!path.length) return;
        setLoading(true);
        try {
            const res = await dremioService.getDatasetPreview(path, limit);
            setResult(res);
        } catch (err: any) {
            message.error("Failed to preview: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { loadPreview(); }, [path.join("."), limit]);

    const handleExportCsv = async () => {
        const sql = `SELECT * FROM ${path.map(p => `"${p}"`).join(".")}`;
        try {
            const csv = await dremioService.exportCsv(sql);
            dremioService.downloadCsv(csv, `${path[path.length - 1]}.csv`);
            message.success("CSV downloaded");
        } catch (err: any) {
            message.error("Export failed: " + err.message);
        }
    };

    const handleExportExcel = async () => {
        if (!result) return;
        try {
            await dremioService.downloadExcel(result, `${path[path.length - 1]}.xlsx`);
            message.success("Excel downloaded");
        } catch (err: any) {
            message.error("Export failed: " + err.message);
        }
    };

    const buildColumns = (cols: QueryColumn[]) =>
        cols.map((col) => ({
            title: (
                <Tooltip title={`Type: ${col.type}`}>
                    <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                        <ColumnWidthOutlined style={{ fontSize: 10, color: "#8c8c8c" }} />
                        <span style={{ fontSize: 12, fontWeight: 600 }}>{col.name}</span>
                        <Tag style={{ fontSize: 9, lineHeight: "14px", marginLeft: 4, padding: "0 4px", border: "none" }} color="default">
                            {col.type}
                        </Tag>
                    </div>
                </Tooltip>
            ),
            dataIndex: col.name,
            key: col.name,
            ellipsis: true,
            width: Math.max(120, col.name.length * 10),
            render: (val: any) => {
                if (val === null || val === undefined) return <span style={{ color: "#bfbfbf", fontStyle: "italic" }}>NULL</span>;
                if (typeof val === "boolean") return <Tag color={val ? "green" : "red"}>{String(val)}</Tag>;
                if (typeof val === "object") return <Tag color="geekblue">{JSON.stringify(val)}</Tag>;
                return <span style={{ fontSize: 13, fontFamily: "'Inter', sans-serif" }}>{String(val)}</span>;
            },
        }));

    if (loading) return <div style={{ textAlign: "center", padding: 60 }}><Spin tip="Loading preview..." size="large" /></div>;

    // Wrapped in Card even for empty state
    if (!result) return (
        <Card
            style={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                borderRadius: 8,
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
                border: '1px solid rgba(0,0,0,0.06)'
            }}
        >
            <Empty description="Select a dataset to view data" image={Empty.PRESENTED_IMAGE_SIMPLE} />
        </Card>
    );

    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(50);

    const paginatedRows = result ? result.rows.slice((currentPage - 1) * pageSize, currentPage * pageSize).map((r, i) => ({ ...r, _key: ((currentPage - 1) * pageSize) + i })) : [];

    return (
        <Card
            size="small"
            styles={{
                body: { padding: 0, flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' },
                header: { minHeight: 48, padding: '0 16px' }
            }}
            style={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
                borderRadius: 8,
                border: '1px solid rgba(0,0,0,0.06)'
            }}
            title={
                <Space size={16}>
                    <Space size={4}>
                        <TableOutlined style={{ color: 'var(--theme-color, #7c3aed)' }} />
                        <span style={{ fontWeight: 600 }}>{path[path.length - 1]}</span>
                    </Space>
                    <Space size={12} split={<span style={{ color: '#e5e7eb' }}>|</span>}>
                        <Statistic
                            title={null}
                            value={result.rowCount}
                            prefix={<span style={{ fontSize: 12, color: '#6b7280' }}>Rows:</span>}
                            valueStyle={{ fontSize: 14, fontWeight: 500 }}
                        />
                        <Statistic
                            title={null}
                            value={result.columns.length}
                            prefix={<span style={{ fontSize: 12, color: '#6b7280' }}>Cols:</span>}
                            valueStyle={{ fontSize: 14, fontWeight: 500 }}
                        />
                    </Space>
                </Space>
            }
            extra={
                <Space>
                    <Button type="text" size="small" icon={<ReloadOutlined />} onClick={loadPreview}>Refresh</Button>
                    <Button size="small" icon={<DownloadOutlined />} onClick={handleExportCsv}>CSV</Button>
                    <Button size="small" icon={<FileExcelOutlined />} onClick={handleExportExcel}>Excel</Button>
                </Space>
            }
        >
            <div ref={tableContainerRef} className="absolute-table" style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
                <Table
                    columns={buildColumns(result.columns)}
                    dataSource={paginatedRows}
                    rowKey="_key"
                    size="small"
                    scroll={{ x: "max-content", y: tableScrollHeight }}
                    pagination={false}
                    bordered
                />
            </div>

            <div className="custom-pagination-wrapper" style={{ padding: '8px 16px', borderTop: `1px solid ${isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'}`, display: 'flex', justifyContent: 'flex-end', flexShrink: 0 }}>
                <style dangerouslySetInnerHTML={{
                    __html: `
                    .custom-pagination-wrapper .ant-pagination-prev .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-next .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-jump-prev .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-jump-next .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-jump-prev .ant-pagination-item-container,
                    .custom-pagination-wrapper .ant-pagination-jump-next .ant-pagination-item-container,
                    .custom-pagination-wrapper .ant-pagination-prev button,
                    .custom-pagination-wrapper .ant-pagination-next button {
                        background-color: rgba(var(--theme-color-rgb, 139, 92, 246), 0.1) !important;
                        color: var(--theme-color, #7c3aed) !important;
                        border-radius: 50% !important;
                        border: none !important;
                        display: flex !important;
                        align-items: center !important;
                        justify-content: center !important;
                        min-width: 24px;
                        height: 24px;
                    }
                    .custom-pagination-wrapper .ant-pagination-prev:hover .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-next:hover .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-jump-prev:hover .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-jump-next:hover .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-jump-prev:hover .ant-pagination-item-container,
                    .custom-pagination-wrapper .ant-pagination-jump-next:hover .ant-pagination-item-container,
                    .custom-pagination-wrapper .ant-pagination-prev:hover button,
                    .custom-pagination-wrapper .ant-pagination-next:hover button {
                        background-color: rgba(var(--theme-color-rgb, 139, 92, 246), 0.2) !important;
                    }
                    .custom-pagination-wrapper .ant-pagination-disabled .ant-pagination-item-link,
                    .custom-pagination-wrapper .ant-pagination-disabled button {
                        background-color: rgba(0, 0, 0, 0.04) !important;
                        color: rgba(0, 0, 0, 0.25) !important;
                    }
                `}} />
                <Pagination
                    current={currentPage}
                    pageSize={pageSize}
                    total={result.rows.length}
                    size="small"
                    showSizeChanger
                    pageSizeOptions={['25', '50', '100']}
                    showTotal={(total: number) => `${total} rows`}
                    onChange={(page: number, size: number) => { setCurrentPage(page); setPageSize(size); }}
                />
            </div>
        </Card>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Modal, Form, Input, Select, message, Spin } from "antd";
import { dremioService, DremioSource } from "@/lib/dremioService";

const SOURCE_TYPES = [
    { value: "NAS", label: "NAS (File System)" },
    { value: "S3", label: "Amazon S3 / MinIO" },
    { value: "POSTGRES", label: "PostgreSQL" },
    { value: "MYSQL", label: "MySQL" },
    { value: "MSSQL", label: "SQL Server" },
    { value: "ORACLE", label: "Oracle" },
    { value: "MONGO", label: "MongoDB" },
    { value: "ELASTICSEARCH", label: "Elasticsearch" },
    { value: "HIVE", label: "Hive" },
    { value: "NESSIE", label: "Nessie (Iceberg)" },
];

function configToFormValues(detail: DremioSource): Record<string, any> {
    const c = detail.config || {};
    const base: Record<string, any> = {
        sourceName: detail.name,
        sourceType: detail.type || "",
    };
    const type = (detail.type || "").toUpperCase();

    if (type === "S3") {
        base.accessKey = c.accessKey ?? "";
        base.accessSecret = c.accessSecret ?? "";
        base.buckets = Array.isArray(c.externalBucketList) ? c.externalBucketList.join(", ") : "";
        const pl = c.propertyList || [];
        const endpoint = pl.find((p: any) => p?.name === "fs.s3a.endpoint");
        base.endpoint = endpoint?.value ?? "";
    } else if (["POSTGRES", "MYSQL", "MSSQL"].includes(type)) {
        base.hostname = c.hostname ?? "";
        base.port = c.port ?? "";
        base.databaseName = c.databaseName ?? "";
        base.dbUsername = c.username ?? "";
        base.dbPassword = ""; // Often not returned; leave blank to keep
    } else if (type === "NESSIE") {
        base.nessieEndpoint = c.nessieEndpoint ?? "";
        base.warehouseLocation = c.awsRootPath ?? "";
        base.s3AccessKey = c.awsAccessKey ?? "";
        base.s3SecretKey = c.awsAccessSecret ?? "";
        const pl = c.propertyList || [];
        const ep = pl.find((p: any) => p?.name === "fs.s3a.endpoint");
        base.s3Endpoint = ep?.value ?? "";
    } else {
        base.rawConfig = c && Object.keys(c).length ? JSON.stringify(c, null, 2) : "{}";
    }
    return base;
}

interface EditSourceModalProps {
    open: boolean;
    onClose: () => void;
    onSuccess: () => void;
    sourceId: string | null;
    sourceTag?: string; // If not provided, will use tag from loaded detail
}

export default function EditSourceModal({ open, onClose, onSuccess, sourceId, sourceTag = "" }: EditSourceModalProps) {
    const [form] = Form.useForm();
    const [saving, setSaving] = useState(false);
    const [loading, setLoading] = useState(false);
    const [sourceType, setSourceType] = useState("");
    const [loadedTag, setLoadedTag] = useState("");

    useEffect(() => {
        if (!open || !sourceId) return;
        setLoading(true);
        setSourceType("");
        setLoadedTag("");
        dremioService
            .getSourceDetail(sourceId)
            .then((detail) => {
                setLoadedTag(detail.tag || "");
                const values = configToFormValues(detail);
                form.setFieldsValue(values);
                setSourceType(values.sourceType || "");
            })
            .catch((err: any) => {
                message.error("Failed to load source: " + err.message);
                onClose();
            })
            .finally(() => setLoading(false));
    }, [open, sourceId, form, onClose]);

    const handleSave = async () => {
        if (!sourceId) return;
        try {
            const values = await form.validateFields();
            setSaving(true);

            const config: Record<string, any> = {};
            const type = values.sourceType;

            if (type === "S3") {
                config.accessKey = values.accessKey || "";
                config.accessSecret = values.accessSecret || "";
                config.secure = false;
                config.externalBucketList = values.buckets ? values.buckets.split(",").map((b: string) => b.trim()) : [];
                config.propertyList = values.endpoint
                    ? [
                        { name: "fs.s3a.endpoint", value: values.endpoint },
                        { name: "fs.s3a.path.style.access", value: "true" },
                    ]
                    : [];
            } else if (type === "POSTGRES" || type === "MYSQL" || type === "MSSQL") {
                config.hostname = values.hostname || "";
                config.port = values.port || (type === "POSTGRES" ? "5432" : type === "MYSQL" ? "3306" : "1433");
                config.databaseName = values.databaseName || "";
                config.username = values.dbUsername || "";
                if (values.dbPassword) config.password = values.dbPassword;
            } else if (type === "NESSIE") {
                config.nessieEndpoint = values.nessieEndpoint || "";
                config.nessieAuthType = "NONE";
                if (values.warehouseLocation) config.awsRootPath = values.warehouseLocation;
                config.propertyList = [];
                if (values.s3Endpoint) {
                    config.propertyList.push(
                        { name: "fs.s3a.endpoint", value: values.s3Endpoint },
                        { name: "fs.s3a.path.style.access", value: "true" },
                        { name: "dremio.s3.compat", value: "true" },
                    );
                }
                if (values.s3AccessKey) {
                    config.awsAccessKey = values.s3AccessKey;
                    config.awsAccessSecret = values.s3SecretKey || "";
                }
            } else {
                try {
                    Object.assign(config, JSON.parse(values.rawConfig || "{}"));
                } catch {
                    /* ignore */
                }
            }

            const tag = sourceTag || loadedTag;
            if (!tag) throw new Error("Source tag is required for update");
            await dremioService.updateSource(sourceId, tag, {
                name: values.sourceName,
                type: values.sourceType,
                config,
            });
            message.success(`Source "${values.sourceName}" updated`);
            onSuccess();
            onClose();
            form.resetFields();
            setSourceType("");
        } catch (err: any) {
            if (err.errorFields) return;
            message.error("Failed to update source: " + err.message);
        } finally {
            setSaving(false);
        }
    };

    const renderConfigFields = () => {
        switch (sourceType) {
            case "S3":
                return (
                    <>
                        <Form.Item name="accessKey" label="Access Key"><Input /></Form.Item>
                        <Form.Item name="accessSecret" label="Secret Key"><Input.Password /></Form.Item>
                        <Form.Item name="endpoint" label="Endpoint (e.g. minio:9000)"><Input placeholder="minio:9000" /></Form.Item>
                        <Form.Item name="buckets" label="Buckets (comma-separated)"><Input placeholder="bucket1, bucket2" /></Form.Item>
                    </>
                );
            case "POSTGRES":
            case "MYSQL":
            case "MSSQL":
                return (
                    <>
                        <Form.Item name="hostname" label="Hostname" rules={[{ required: true }]}><Input /></Form.Item>
                        <Form.Item name="port" label="Port"><Input placeholder={sourceType === "POSTGRES" ? "5432" : sourceType === "MYSQL" ? "3306" : "1433"} /></Form.Item>
                        <Form.Item name="databaseName" label="Database" rules={[{ required: true }]}><Input /></Form.Item>
                        <Form.Item name="dbUsername" label="Username"><Input /></Form.Item>
                        <Form.Item name="dbPassword" label="Password"><Input.Password placeholder="Leave blank to keep current" /></Form.Item>
                    </>
                );
            case "NESSIE":
                return (
                    <>
                        <Form.Item name="nessieEndpoint" label="Nessie API Endpoint" rules={[{ required: true }]}><Input placeholder="http://nessie:19120/api/v2" /></Form.Item>
                        <Form.Item name="warehouseLocation" label="Warehouse Location"><Input placeholder="s3://bucket/warehouse" /></Form.Item>
                        <Form.Item name="s3Endpoint" label="S3 Endpoint"><Input placeholder="minio:9000" /></Form.Item>
                        <Form.Item name="s3AccessKey" label="S3 Access Key"><Input /></Form.Item>
                        <Form.Item name="s3SecretKey" label="S3 Secret Key"><Input.Password /></Form.Item>
                    </>
                );
            default:
                return (
                    <Form.Item name="rawConfig" label="Configuration (JSON)">
                        <Input.TextArea rows={6} placeholder='{"key": "value"}' style={{ fontFamily: "monospace" }} />
                    </Form.Item>
                );
        }
    };

    return (
        <Modal
            title="Edit Data Source"
            open={open}
            onCancel={() => { onClose(); form.resetFields(); setSourceType(""); }}
            onOk={handleSave}
            confirmLoading={saving}
            width={520}
            okText="Save"
            destroyOnClose
        >
            {loading ? (
                <div style={{ textAlign: "center", padding: 32 }}><Spin size="large" /></div>
            ) : (
                <Form form={form} layout="vertical">
                    <Form.Item name="sourceName" label="Source Name" rules={[{ required: true, message: "Name is required" }]}>
                        <Input placeholder="my-source" />
                    </Form.Item>
                    <Form.Item name="sourceType" label="Source Type" rules={[{ required: true }]}>
                        <Select
                            placeholder="Select type"
                            options={SOURCE_TYPES}
                            onChange={(val) => setSourceType(val)}
                        />
                    </Form.Item>
                    {sourceType && renderConfigFields()}
                </Form>
            )}
        </Modal>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Modal, Input, Form, message, Spin } from 'antd';
import { dremioService, CatalogDetail } from '@/lib/dremioService';

interface EditVDSModalProps {
    open: boolean;
    onClose: () => void;
    onSuccess?: () => void;
    vdsId: string | null;
}

export default function EditVDSModal({ open, onClose, onSuccess, vdsId }: EditVDSModalProps) {
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [sql, setSql] = useState('');
    const [sqlContext, setSqlContext] = useState('');
    const [vdsDetail, setVdsDetail] = useState<CatalogDetail | null>(null);

    useEffect(() => {
        if (open && vdsId) {
            loadVDS();
        }
    }, [open, vdsId]);

    const loadVDS = async () => {
        if (!vdsId) return;
        setLoading(true);
        try {
            const detail = await dremioService.getCatalogById(vdsId);
            setVdsDetail(detail);
            setSql(detail.sql || '');
            setSqlContext(detail.sqlContext?.join('.') || '');
        } catch (err: any) {
            message.error('Failed to load VDS: ' + err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!vdsId || !vdsDetail?.tag || !sql.trim()) return;
        setSaving(true);
        try {
            const ctx = sqlContext.trim() ? sqlContext.split('.').map(s => s.trim()) : undefined;
            await dremioService.updateVDS(vdsId, vdsDetail.tag, sql, ctx);
            message.success('VDS updated successfully');
            onClose();
            onSuccess?.();
        } catch (err: any) {
            message.error('Failed to update VDS: ' + err.message);
        } finally {
            setSaving(false);
        }
    };

    const handleClose = () => {
        setSql('');
        setSqlContext('');
        setVdsDetail(null);
        onClose();
    };

    const vdsName = vdsDetail?.path?.[vdsDetail.path.length - 1] || 'Virtual Dataset';

    return (
        <Modal
            title={`Edit VDS — ${vdsName}`}
            open={open}
            onCancel={handleClose}
            onOk={handleSave}
            okText="Save Changes"
            confirmLoading={saving}
            width={700}
            destroyOnClose
        >
            {loading ? (
                <div style={{ textAlign: 'center', padding: 40 }}>
                    <Spin size="large" />
                </div>
            ) : (
                <Form layout="vertical">
                    <Form.Item label="Path">
                        <Input
                            value={vdsDetail?.path?.join(' → ') || ''}
                            disabled
                            style={{ fontFamily: 'monospace', fontSize: 13 }}
                        />
                    </Form.Item>
                    <Form.Item label="SQL Context" extra="Dot-separated schema context (e.g. myspace.subfolder)">
                        <Input
                            value={sqlContext}
                            onChange={(e) => setSqlContext(e.target.value)}
                            placeholder="Optional: myspace.subfolder"
                            style={{ fontFamily: 'monospace', fontSize: 13 }}
                        />
                    </Form.Item>
                    <Form.Item label="SQL Definition" required>
                        <Input.TextArea
                            value={sql}
                            onChange={(e) => setSql(e.target.value)}
                            rows={10}
                            placeholder="SELECT * FROM ..."
                            style={{
                                fontFamily: "'JetBrains Mono', 'Fira Code', monospace",
                                fontSize: 13,
                                lineHeight: 1.6,
                                background: '#1e1e2e',
                                color: '#cdd6f4',
                                border: '1px solid #45475a',
                                borderRadius: 8,
                            }}
                        />
                    </Form.Item>
                </Form>
            )}
        </Modal>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Modal, Input, Form, message } from 'antd';
import { dremioService } from '@/lib/dremioService';

interface RenameSpaceModalProps {
    open: boolean;
    onClose: () => void;
    onSuccess?: () => void;
    spaceId: string | null;
    spaceTag: string;
    currentName: string;
}

export default function RenameSpaceModal({ open, onClose, onSuccess, spaceId, spaceTag, currentName }: RenameSpaceModalProps) {
    const [newName, setNewName] = useState('');
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        if (open) setNewName(currentName);
    }, [open, currentName]);

    const handleRename = async () => {
        if (!spaceId || !newName.trim() || newName.trim() === currentName) return;
        setSaving(true);
        try {
            await dremioService.renameSpace(spaceId, spaceTag, newName.trim());
            message.success(`Space renamed to "${newName.trim()}"`);
            onClose();
            onSuccess?.();
        } catch (err: any) {
            message.error('Failed to rename space: ' + err.message);
        } finally {
            setSaving(false);
        }
    };

    return (
        <Modal
            title="Rename Space"
            open={open}
            onCancel={onClose}
            onOk={handleRename}
            okText="Rename"
            confirmLoading={saving}
            destroyOnClose
        >
            <Form layout="vertical">
                <Form.Item label="Current Name">
                    <Input value={currentName} disabled />
                </Form.Item>
                <Form.Item label="New Name" required>
                    <Input
                        value={newName}
                        onChange={(e) => setNewName(e.target.value)}
                        placeholder="Enter new space name"
                        autoFocus
                        onPressEnter={handleRename}
                    />
                </Form.Item>
            </Form>
        </Modal>
    );
}

"use client";

import React, { useState } from "react";
import { Input, Button, Space, Table, message, Spin, Tag, Tooltip, Card, Typography } from "antd";
import {
    PlayCircleOutlined,
    ClearOutlined,
    DownloadOutlined,
    FileExcelOutlined,
    CopyOutlined,
    CheckOutlined,
    CodeOutlined,
    SaveOutlined,
    StopOutlined,
    LeftOutlined,
    RightOutlined,
} from "@ant-design/icons";
import { dremioService, QueryResult, QueryColumn } from "@/lib/dremioService";
import { motion } from "framer-motion";

const { Text } = Typography;

interface SQLEditorProps {
    defaultSQL?: string;
    context?: string[];
}

export default function SQLEditor({ defaultSQL, context }: SQLEditorProps) {
    const [sql, setSQL] = useState(defaultSQL || "");
    const [result, setResult] = useState<QueryResult | null>(null);
    const [loading, setLoading] = useState(false);
    const [copiedSQL, setCopiedSQL] = useState(false);
    const [currentJobId, setCurrentJobId] = useState<string | null>(null);
    const [pageOffset, setPageOffset] = useState(0);
    const PAGE_SIZE = 500;

    const runQuery = async () => {
        if (!sql.trim()) {
            message.warning("Enter a SQL query");
            return;
        }
        setLoading(true);
        setResult(null);
        setPageOffset(0);
        try {
            const res = await dremioService.runSQL(sql.trim(), context);
            setResult(res);
            setCurrentJobId(res.jobId || null);
            message.success(`Query completed: ${res.rowCount} rows`);
        } catch (err: any) {
            message.error("Query failed: " + err.message);
        } finally {
            setLoading(false);
            setCurrentJobId(null);
        }
    };

    const handleCancel = async () => {
        if (!currentJobId) return;
        try {
            await dremioService.cancelJob(currentJobId);
            message.warning('Job cancelled');
            setLoading(false);
            setCurrentJobId(null);
        } catch (err: any) {
            message.error('Cancel failed: ' + err.message);
        }
    };

    const loadPage = async (offset: number) => {
        if (!result?.jobId) return;
        try {
            const res = await dremioService.getJobResults(result.jobId, offset, PAGE_SIZE);
            setResult(res);
            setPageOffset(offset);
        } catch (err: any) {
            message.error('Failed to load page: ' + err.message);
        }
    };

    const handleExportCsv = async () => {
        if (!sql.trim()) return;
        try {
            const csv = await dremioService.exportCsv(sql.trim());
            dremioService.downloadCsv(csv);
            message.success("CSV downloaded");
        } catch (err: any) {
            message.error("Export failed: " + err.message);
        }
    };

    const handleExportExcel = async () => {
        if (!result) return;
        try {
            await dremioService.downloadExcel(result);
            message.success("Excel downloaded");
        } catch (err: any) {
            message.error("Export failed: " + err.message);
        }
    };

    const handleCopy = () => {
        navigator.clipboard.writeText(sql);
        setCopiedSQL(true);
        setTimeout(() => setCopiedSQL(false), 2000);
    };

    const buildColumns = (cols: QueryColumn[]) =>
        cols.map((col) => ({
            title: (
                <Tooltip title={col.type}>
                    <span style={{ fontSize: 12, fontWeight: 600 }}>{col.name}</span>
                </Tooltip>
            ),
            dataIndex: col.name,
            key: col.name,
            ellipsis: true,
            width: 160,
            render: (val: any) => {
                if (val === null || val === undefined) return <span style={{ color: "#8c8c8c", fontStyle: "italic" }}>NULL</span>;
                if (typeof val === "object") return <Tag color="blue">{JSON.stringify(val)}</Tag>;
                return <span style={{ fontSize: 12 }}>{String(val)}</span>;
            },
        }));

    return (
        <div style={{ display: "flex", flexDirection: "column", height: "100%", gap: 16 }}>
            {/* Editor Card */}
            <Card
                size="small"
                styles={{
                    body: { padding: 0 },
                    header: { minHeight: 40, padding: '0 12px' }
                }}
                title={
                    <Space size={8}>
                        <CodeOutlined style={{ color: 'var(--theme-color, #7c3aed)' }} />
                        <span style={{ fontSize: 13, fontWeight: 600 }}>Query Editor</span>
                    </Space>
                }
                extra={
                    <Space size={4}>
                        <Tooltip title="Copy SQL">
                            <Button
                                type="text"
                                size="small"
                                icon={copiedSQL ? <CheckOutlined style={{ color: "#52c41a" }} /> : <CopyOutlined />}
                                onClick={handleCopy}
                            />
                        </Tooltip>
                        <Tooltip title="Clear">
                            <Button
                                type="text"
                                size="small"
                                icon={<ClearOutlined />}
                                onClick={() => { setSQL(""); setResult(null); }}
                            />
                        </Tooltip>
                    </Space>
                }
                style={{
                    boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
                    borderRadius: 8,
                    overflow: 'hidden',
                    border: '1px solid rgba(0,0,0,0.06)'
                }}
            >
                <div style={{ position: "relative" }}>
                    <Input.TextArea
                        value={sql}
                        onChange={(e) => setSQL(e.target.value)}
                        placeholder="SELECT * FROM source.schema.table LIMIT 100"
                        autoSize={{ minRows: 6, maxRows: 12 }}
                        style={{
                            fontFamily: "'JetBrains Mono', 'Fira Code', monospace",
                            fontSize: 13,
                            lineHeight: 1.6,
                            border: "none",
                            borderRadius: 0,
                            padding: 16,
                            backgroundColor: "#1e1e1e", // Dark editor background
                            color: "#d4d4d4", // Light text
                            resize: "none"
                        }}
                        onKeyDown={(e) => {
                            if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
                                e.preventDefault();
                                runQuery();
                            }
                        }}
                        className="custom-scrollbar"
                    />

                    <div style={{
                        position: 'absolute',
                        bottom: 12,
                        right: 12,
                        zIndex: 10,
                        display: 'flex',
                        gap: 8
                    }}>
                        {loading && (
                            <Button
                                danger
                                icon={<StopOutlined />}
                                onClick={handleCancel}
                                shape="round"
                                style={{ height: 32, fontSize: 13, fontWeight: 500 }}
                            >
                                Cancel
                            </Button>
                        )}
                        <Button
                            type="primary"
                            icon={<PlayCircleOutlined />}
                            onClick={runQuery}
                            loading={loading}
                            shape="round"
                            style={{
                                background: "linear-gradient(135deg, var(--theme-color, #7c3aed), var(--theme-secondary, #6366f1))",
                                border: "none",
                                boxShadow: "0 4px 12px rgba(124, 58, 237, 0.3)",
                                height: 32,
                                paddingLeft: 16,
                                paddingRight: 16,
                                fontSize: 13,
                                fontWeight: 500
                            }}
                        >
                            Run (Cmd+Enter)
                        </Button>
                    </div>
                </div>
            </Card>

            {/* Results Area */}
            {result && (
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3 }}
                    style={{ flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}
                >
                    <Card
                        size="small"
                        styles={{
                            body: { padding: 0, flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' },
                            header: { minHeight: 40, padding: '0 12px' }
                        }}
                        style={{
                            height: '100%',
                            display: 'flex',
                            flexDirection: 'column',
                            boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
                            borderRadius: 8,
                            border: '1px solid rgba(0,0,0,0.06)'
                        }}
                        title={
                            <Space>
                                <Tag color="success" style={{ margin: 0 }}>
                                    {result.rowCount} rows
                                </Tag>
                                <Text type="secondary" style={{ fontSize: 12 }}>
                                    Job: {result.jobId?.substring(0, 8)}
                                </Text>
                            </Space>
                        }
                        extra={
                            <Space size={8}>
                                <Button size="small" disabled={pageOffset <= 0} icon={<LeftOutlined />} onClick={() => loadPage(Math.max(0, pageOffset - PAGE_SIZE))}>Prev</Button>
                                <Tag style={{ margin: 0, fontSize: 11 }}>Offset {pageOffset}–{pageOffset + (result?.rows?.length || 0)}</Tag>
                                <Button size="small" disabled={(result?.rows?.length || 0) < PAGE_SIZE} icon={<RightOutlined />} onClick={() => loadPage(pageOffset + PAGE_SIZE)}>Next</Button>
                                <Button size="small" icon={<DownloadOutlined />} onClick={handleExportCsv}>CSV</Button>
                                <Button size="small" icon={<FileExcelOutlined />} onClick={handleExportExcel}>Excel</Button>
                            </Space>
                        }
                    >
                        <Table
                            columns={buildColumns(result.columns)}
                            dataSource={result.rows.map((r, i) => ({ ...r, _key: i }))}
                            rowKey="_key"
                            size="small"
                            scroll={{ x: "max-content", y: 400 }}
                            pagination={{
                                pageSize: 50,
                                showSizeChanger: true,
                                showTotal: (total) => `${total} rows`,
                                size: "small",
                            }}
                            bordered
                            style={{ fontSize: 12 }}
                        />
                    </Card>
                </motion.div>
            )}

            {!result && !loading && (
                <div style={{
                    flex: 1,
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    opacity: 0.5,
                    flexDirection: 'column',
                    gap: 12
                }}>
                    <CodeOutlined style={{ fontSize: 48, color: '#d1d5db' }} />
                    <Text type="secondary">Run a query to see results</Text>
                </div>
            )}

            {loading && !result && (
                <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                    <Spin size="large" tip="Executing query..." />
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, List, Button, Modal, Form, Input, Select, Space, message, Tag, Popconfirm, Empty, Spin, Descriptions, Typography, Badge } from "antd";
import {
    PlusOutlined,
    DeleteOutlined,
    EditOutlined,
    CloudServerOutlined,
    DatabaseOutlined,
    ReloadOutlined,
    InfoCircleOutlined,
    GlobalOutlined,
    HddOutlined,
    AmazonOutlined,
    ConsoleSqlOutlined,
} from "@ant-design/icons";
import { dremioService, DremioSource } from "@/lib/dremioService";
import { motion } from "framer-motion";
import EditSourceModal from "./EditSourceModal";

const { Title, Text } = Typography;

const SOURCE_TYPES = [
    { value: "NAS", label: "NAS (File System)" },
    { value: "S3", label: "Amazon S3 / MinIO" },
    { value: "POSTGRES", label: "PostgreSQL" },
    { value: "MYSQL", label: "MySQL" },
    { value: "MSSQL", label: "SQL Server" },
    { value: "ORACLE", label: "Oracle" },
    { value: "MONGO", label: "MongoDB" },
    { value: "ELASTICSEARCH", label: "Elasticsearch" },
    { value: "HIVE", label: "Hive" },
    { value: "NESSIE", label: "Nessie (Iceberg)" },
];

const getSourceIcon = (type: string) => {
    switch (type) {
        case 'S3': return <AmazonOutlined style={{ fontSize: 28, color: '#f90' }} />;
        case 'POSTGRES':
        case 'MYSQL':
        case 'MSSQL': return <ConsoleSqlOutlined style={{ fontSize: 28, color: '#1890ff' }} />;
        case 'NAS': return <HddOutlined style={{ fontSize: 28, color: '#52c41a' }} />;
        case 'NESSIE': return <GlobalOutlined style={{ fontSize: 28, color: '#722ed1' }} />;
        default: return <CloudServerOutlined style={{ fontSize: 28, color: '#8c8c8c' }} />;
    }
};

export default function SourceManager() {
    const [sources, setSources] = useState<DremioSource[]>([]);
    const [loading, setLoading] = useState(true);
    const [addModalVisible, setAddModalVisible] = useState(false);
    const [detailSource, setDetailSource] = useState<DremioSource | null>(null);
    const [editSourceId, setEditSourceId] = useState<string | null>(null);
    const [editSourceTag, setEditSourceTag] = useState("");
    const [creating, setCreating] = useState(false);
    const [form] = Form.useForm();
    const [sourceType, setSourceType] = useState("");

    const loadSources = async () => {
        setLoading(true);
        try {
            const list = await dremioService.getSources();
            setSources(list);
        } catch (err: any) {
            message.error("Failed to load sources: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { loadSources(); }, []);

    const handleCreate = async () => {
        try {
            const values = await form.validateFields();
            setCreating(true);

            const config: Record<string, any> = {};
            const type = values.sourceType;

            // Build config based on source type
            if (type === "S3") {
                config.accessKey = values.accessKey || "";
                config.accessSecret = values.accessSecret || "";
                config.secure = false;
                config.externalBucketList = values.buckets ? values.buckets.split(",").map((b: string) => b.trim()) : [];
                config.propertyList = values.endpoint ? [
                    { name: "fs.s3a.endpoint", value: values.endpoint },
                    { name: "fs.s3a.path.style.access", value: "true" },
                ] : [];
            } else if (type === "POSTGRES" || type === "MYSQL" || type === "MSSQL") {
                config.hostname = values.hostname || "";
                config.port = values.port || (type === "POSTGRES" ? "5432" : type === "MYSQL" ? "3306" : "1433");
                config.databaseName = values.databaseName || "";
                config.username = values.dbUsername || "";
                config.password = values.dbPassword || "";
            } else if (type === "NESSIE") {
                config.nessieEndpoint = values.nessieEndpoint || "";
                config.nessieAuthType = "NONE";
                if (values.warehouseLocation) {
                    config.awsRootPath = values.warehouseLocation;
                }
                config.propertyList = [];
                if (values.s3Endpoint) {
                    config.propertyList.push(
                        { name: "fs.s3a.endpoint", value: values.s3Endpoint },
                        { name: "fs.s3a.path.style.access", value: "true" },
                        { name: "dremio.s3.compat", value: "true" },
                    );
                }
                if (values.s3AccessKey) {
                    config.awsAccessKey = values.s3AccessKey;
                    config.awsAccessSecret = values.s3SecretKey || "";
                }
            } else {
                // Generic — pass raw JSON config
                try {
                    Object.assign(config, JSON.parse(values.rawConfig || "{}"));
                } catch { /* ignore parse error */ }
            }

            await dremioService.createSource(values.sourceName, type, config);
            message.success(`Source "${values.sourceName}" created`);
            setAddModalVisible(false);
            form.resetFields();
            loadSources();
        } catch (err: any) {
            if (err.errorFields) return; // Form validation
            message.error("Failed to create source: " + err.message);
        } finally {
            setCreating(false);
        }
    };

    const handleDelete = async (source: DremioSource) => {
        try {
            await dremioService.deleteSource(source.id, source.tag);
            message.success(`Source "${source.name}" deleted`);
            loadSources();
        } catch (err: any) {
            message.error("Failed to delete source: " + err.message);
        }
    };

    const handleDetail = async (source: DremioSource) => {
        try {
            const detail = await dremioService.getSourceDetail(source.id);
            setDetailSource(detail);
        } catch (err: any) {
            message.error("Failed to load source detail: " + err.message);
        }
    };

    const renderConfigFields = () => {
        switch (sourceType) {
            case "S3":
                return (
                    <>
                        <Form.Item name="accessKey" label="Access Key"><Input /></Form.Item>
                        <Form.Item name="accessSecret" label="Secret Key"><Input.Password /></Form.Item>
                        <Form.Item name="endpoint" label="Endpoint (e.g. minio:9000)"><Input placeholder="minio:9000" /></Form.Item>
                        <Form.Item name="buckets" label="Buckets (comma-separated)"><Input placeholder="bucket1, bucket2" /></Form.Item>
                    </>
                );
            case "POSTGRES":
            case "MYSQL":
            case "MSSQL":
                return (
                    <>
                        <Form.Item name="hostname" label="Hostname" rules={[{ required: true }]}><Input /></Form.Item>
                        <Form.Item name="port" label="Port"><Input placeholder={sourceType === "POSTGRES" ? "5432" : sourceType === "MYSQL" ? "3306" : "1433"} /></Form.Item>
                        <Form.Item name="databaseName" label="Database" rules={[{ required: true }]}><Input /></Form.Item>
                        <Form.Item name="dbUsername" label="Username"><Input /></Form.Item>
                        <Form.Item name="dbPassword" label="Password"><Input.Password /></Form.Item>
                    </>
                );
            case "NESSIE":
                return (
                    <>
                        <Form.Item name="nessieEndpoint" label="Nessie API Endpoint" rules={[{ required: true }]}><Input placeholder="http://nessie:19120/api/v2" /></Form.Item>
                        <Form.Item name="warehouseLocation" label="Warehouse Location"><Input placeholder="s3://bucket/warehouse" /></Form.Item>
                        <Form.Item name="s3Endpoint" label="S3 Endpoint"><Input placeholder="minio:9000" /></Form.Item>
                        <Form.Item name="s3AccessKey" label="S3 Access Key"><Input /></Form.Item>
                        <Form.Item name="s3SecretKey" label="S3 Secret Key"><Input.Password /></Form.Item>
                    </>
                );
            default:
                return (
                    <Form.Item name="rawConfig" label="Configuration (JSON)">
                        <Input.TextArea rows={6} placeholder='{"key": "value"}' style={{ fontFamily: "monospace" }} />
                    </Form.Item>
                );
        }
    };

    return (
        <div style={{ display: "flex", flexDirection: "column", gap: 24, padding: 8 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <Space direction="vertical" size={2}>
                    <Title level={4} style={{ margin: 0 }}>Data Sources</Title>
                    <Text type="secondary">Manage connections to external databases and file systems</Text>
                </Space>
                <Space>
                    <Button icon={<ReloadOutlined />} onClick={loadSources}>Refresh</Button>
                    <Button icon={<PlusOutlined />} type="primary" onClick={() => setAddModalVisible(true)}
                        style={{
                            background: "linear-gradient(135deg, var(--theme-color, #7c3aed), var(--theme-secondary, #6366f1))",
                            border: "none",
                            boxShadow: "0 4px 10px rgba(124, 58, 237, 0.3)"
                        }}>
                        Add Source
                    </Button>
                </Space>
            </div>

            {loading ? (
                <div style={{ textAlign: "center", padding: 60 }}><Spin size="large" /></div>
            ) : sources.length === 0 ? (
                <Empty
                    description="No sources configured. Add one to get started."
                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                >
                    <Button type="primary" onClick={() => setAddModalVisible(true)}>Connect Source</Button>
                </Empty>
            ) : (
                <List
                    grid={{ gutter: 24, xs: 1, sm: 1, md: 2, lg: 3, xl: 4 }}
                    dataSource={sources}
                    renderItem={(source) => (
                        <List.Item>
                            <motion.div whileHover={{ y: -4 }}>
                                <Card
                                    hoverable
                                    bordered={false}
                                    style={{
                                        borderRadius: 12,
                                        boxShadow: '0 2px 12px rgba(0,0,0,0.04)',
                                        overflow: 'hidden'
                                    }}
                                    actions={[
                                        <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditSourceId(source.id); setEditSourceTag(source.tag); }}>Edit</Button>,
                                        <Button key="info" type="text" icon={<InfoCircleOutlined />} onClick={() => handleDetail(source)}>Details</Button>,
                                        <Popconfirm key="del" title={`Delete "${source.name}"?`} onConfirm={() => handleDelete(source)} okText="Delete" okType="danger">
                                            <Button type="text" danger icon={<DeleteOutlined />}>Delete</Button>
                                        </Popconfirm>,
                                    ]}
                                >
                                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', padding: '16px 0' }}>
                                        <div style={{
                                            width: 64, height: 64,
                                            borderRadius: '50%',
                                            background: '#f9fafb',
                                            display: 'flex',
                                            justifyContent: 'center',
                                            alignItems: 'center',
                                            marginBottom: 16,
                                            border: '1px solid #f3f4f6'
                                        }}>
                                            {getSourceIcon(source.type)}
                                        </div>
                                        <Title level={5} style={{ margin: 0, marginBottom: 4 }}>{source.name}</Title>
                                        <Tag color="geekblue" style={{ borderRadius: 10, padding: '0 10px' }}>{source.type}</Tag>

                                        {/* Datasets count removed due to type mismatch */}
                                    </div>
                                </Card>
                            </motion.div>
                        </List.Item>
                    )}
                />
            )}

            {/* Add Source Modal */}
            <Modal
                title="Add Data Source"
                open={addModalVisible}
                onCancel={() => { setAddModalVisible(false); form.resetFields(); setSourceType(""); }}
                onOk={handleCreate}
                confirmLoading={creating}
                width={520}
                okText="Create Source"
            >
                <Form form={form} layout="vertical">
                    <Form.Item name="sourceName" label="Source Name" rules={[{ required: true, message: "Name is required" }]}>
                        <Input placeholder="my-source" />
                    </Form.Item>
                    <Form.Item name="sourceType" label="Source Type" rules={[{ required: true }]}>
                        <Select
                            placeholder="Select type"
                            options={SOURCE_TYPES}
                            onChange={(val) => setSourceType(val)}
                        />
                    </Form.Item>
                    {sourceType && renderConfigFields()}
                </Form>
            </Modal>

            <EditSourceModal
                open={!!editSourceId}
                onClose={() => { setEditSourceId(null); setEditSourceTag(""); }}
                onSuccess={loadSources}
                sourceId={editSourceId}
                sourceTag={editSourceTag}
            />

            {/* Source Detail Modal */}
            <Modal
                title={`Source: ${detailSource?.name || ""}`}
                open={!!detailSource}
                onCancel={() => setDetailSource(null)}
                footer={null}
                width={600}
            >
                {detailSource && (
                    <Descriptions column={1} size="small" bordered>
                        <Descriptions.Item label="ID">{detailSource.id}</Descriptions.Item>
                        <Descriptions.Item label="Name">{detailSource.name}</Descriptions.Item>
                        <Descriptions.Item label="Type"><Tag color="blue">{detailSource.type}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Tag">{detailSource.tag}</Descriptions.Item>
                        {detailSource.config && (
                            <Descriptions.Item label="Configuration">
                                <pre style={{ fontSize: 11, maxHeight: 300, overflow: "auto", margin: 0, padding: 10, background: '#f5f5f5', borderRadius: 4 }}>
                                    {JSON.stringify(detailSource.config, null, 2)}
                                </pre>
                            </Descriptions.Item>
                        )}
                    </Descriptions>
                )}
            </Modal>
        </div>
    );
}

