                    <Col xs={24} md={10}>
                        <Card size="small" style={{ ...glass, height: '100%' }} title={<Space><CloudServerOutlined style={{ color: '#8b5cf6' }} /><Text strong>Container Registry</Text></Space>}>
                            {IMAGES.map((img, i) => (
