                </Row>
            </motion.div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { Card, Row, Col, Typography, Spin, message, Table, Tag, Empty, Timeline, theme, Select, Tooltip } from "antd";
import {
    RocketOutlined, CheckCircleOutlined, CloseCircleOutlined, SyncOutlined,
    ClockCircleOutlined, BranchesOutlined, FieldTimeOutlined, DeploymentUnitOutlined,
    PieChartOutlined, LineChartOutlined, CloudServerOutlined, UserOutlined,
} from "@ant-design/icons";
import {
    AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid,
    Tooltip as RTooltip, ResponsiveContainer, PieChart, Pie, Cell, ReferenceLine,
} from "recharts";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Pipeline { id: string; name: string; repository: string; branch: string; status: string; stages: string[]; trigger: string; duration: number; startedAt: string; finishedAt: string; commit: string; author: string; }
interface Build { id: string; pipelineId: string; stage: string; status: string; duration: number; log: string; startedAt: string; finishedAt: string; }
interface Deployment { id: string; pipelineId: string; environment: string; status: string; version: string; deployedBy: string; deployedAt: string; rollbackTarget: string; }

const STATUS_MAP: Record<string, { color: string; antColor: string }> = {
    success: { color: '#10b981', antColor: 'green' }, failed: { color: '#ef4444', antColor: 'red' },
    running: { color: '#3b82f6', antColor: 'blue' }, pending: { color: '#9ca3af', antColor: 'default' },
    cancelled: { color: '#f59e0b', antColor: 'orange' },
};
const ENV_COLORS: Record<string, string> = { dev: '#3b82f6', staging: '#f59e0b', production: '#10b981' };
const TRIGGER_COLORS = ['#3b82f6', '#8b5cf6', '#f59e0b', '#10b981', '#ef4444', '#06b6d4'];

const fmtDur = (s: number) => { if (!s) return '—'; const m = Math.floor(s / 60); const sec = s % 60; return m > 0 ? `${m}m ${sec}s` : `${sec}s`; };

export default function PipelinesDashboardPage() {
    const [pipelines, setPipelines] = useState<Pipeline[]>([]);
    const [builds, setBuilds] = useState<Build[]>([]);
    const [deployments, setDeployments] = useState<Deployment[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState<string | null>(null);
    const [branchFilter, setBranchFilter] = useState<string | null>(null);
    const [expandedPipeline, setExpandedPipeline] = useState<string | null>(null);
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');

    useEffect(() => {
        (async () => {
            try {
                const [pData, bData, dData] = await Promise.all([
                    gql(`query($tenantId: String!) { devopsPipelines(tenantId: $tenantId) }`, { tenantId: DEFAULT_TENANT_ID }),
                    gql(`query($tenantId: String!) { devopsBuilds(tenantId: $tenantId) }`, { tenantId: DEFAULT_TENANT_ID }),
                    gql(`query($tenantId: String!) { devopsDeployments(tenantId: $tenantId) }`, { tenantId: DEFAULT_TENANT_ID }),
                ]);
                setPipelines(Array.isArray(pData.devopsPipelines) ? pData.devopsPipelines : []);
                setBuilds(Array.isArray(bData.devopsBuilds) ? bData.devopsBuilds : []);
                setDeployments(Array.isArray(dData.devopsDeployments) ? dData.devopsDeployments : []);
            } catch (err: any) { message.error("Failed to load pipeline data: " + err.message); }
            finally { setLoading(false); }
        })();
    }, []);

    const glassCard = isDark
        ? { background: 'rgba(255,255,255,0.06)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.10)', borderRadius: 14 }
        : glass;
    const gridStroke = isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0';
    const tickStyle = { fontSize: 10, fill: isDark ? '#aaa' : '#666' };
    const tooltipStyle = { background: isDark ? 'rgba(30,30,30,0.95)' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : '#e5e7eb'}`, borderRadius: 8, fontSize: 12 };

    // ── Stats ──────────────────────────────────────────────
    const sorted = useMemo(() => [...pipelines].sort((a, b) => dayjs(b.startedAt).unix() - dayjs(a.startedAt).unix()), [pipelines]);
    const successCount = pipelines.filter(p => p.status === 'success').length;
    const successRate = pipelines.length > 0 ? Math.round((successCount / pipelines.length) * 100) : 0;
    const runningCount = pipelines.filter(p => p.status === 'running').length;
    const avgDuration = pipelines.length > 0 ? Math.round(pipelines.reduce((s, p) => s + (p.duration || 0), 0) / pipelines.length) : 0;
    const failedToday = pipelines.filter(p => p.status === 'failed' && dayjs(p.startedAt).isSame(dayjs(), 'day')).length;

    const stats = [
        { t: 'Total Pipelines', v: pipelines.length, c: '#3b82f6', i: <RocketOutlined /> },
        { t: 'Success Rate', v: `${successRate}%`, c: '#10b981', i: <CheckCircleOutlined /> },
        { t: 'Running Now', v: runningCount, c: '#8b5cf6', i: <SyncOutlined spin={runningCount > 0} /> },
        { t: 'Avg Duration', v: fmtDur(avgDuration), c: '#f59e0b', i: <FieldTimeOutlined /> },
        { t: 'Failed Today', v: failedToday, c: '#ef4444', i: <CloseCircleOutlined /> },
    ];

    // ── Pipeline Stage Viz (last 8) ────────────────────────
    const recentPipelines = sorted.slice(0, 8);

    // ── Filtered pipelines for table ──────────────────────
    const branches = useMemo(() => [...new Set(pipelines.map(p => p.branch))], [pipelines]);
    const tableData = useMemo(() => {
        let data = sorted;
        if (statusFilter) data = data.filter(p => p.status === statusFilter);
        if (branchFilter) data = data.filter(p => p.branch === branchFilter);
        return data;
    }, [sorted, statusFilter, branchFilter]);

    // ── Build Success Trend (30 days) ─────────────────────
    const buildTrend = useMemo(() => {
        const map: Record<string, { success: number; failed: number }> = {};
        const start = dayjs().subtract(30, 'day');
        builds.filter(b => dayjs(b.startedAt).isAfter(start)).forEach(b => {
            const key = dayjs(b.startedAt).format('MM/DD');
            if (!map[key]) map[key] = { success: 0, failed: 0 };
            if (b.status === 'success') map[key].success++; else if (b.status === 'failed') map[key].failed++;
        });
        return Object.entries(map).sort(([a], [b]) => a.localeCompare(b)).map(([day, v]) => ({ day, ...v }));
    }, [builds]);

    // ── Build Duration Trend ──────────────────────────────
    const durationTrend = useMemo(() => {
        const map: Record<string, { total: number; count: number }> = {};
        const start = dayjs().subtract(30, 'day');
        builds.filter(b => dayjs(b.startedAt).isAfter(start) && b.duration > 0).forEach(b => {
            const key = dayjs(b.startedAt).format('MM/DD');
            if (!map[key]) map[key] = { total: 0, count: 0 };
            map[key].total += b.duration; map[key].count++;
        });
        return Object.entries(map).sort(([a], [b]) => a.localeCompare(b)).map(([day, v]) => ({ day, avg: Math.round(v.total / v.count) }));
    }, [builds]);

    // ── Environment Status ────────────────────────────────
    const envStatus = useMemo(() => {
        const envs = ['dev', 'staging', 'production'];
        return envs.map(env => {
            const envDeps = deployments.filter(d => d.environment === env).sort((a, b) => dayjs(b.deployedAt).unix() - dayjs(a.deployedAt).unix());
            const latest = envDeps[0] || null;
            return { env, latest };
        });
    }, [deployments]);

    // ── Recent Deployments (last 15) ──────────────────────
    const recentDeploys = useMemo(() =>
        [...deployments].sort((a, b) => dayjs(b.deployedAt).unix() - dayjs(a.deployedAt).unix()).slice(0, 15),
    [deployments]);

    // ── Trigger Distribution ──────────────────────────────
    const triggerData = useMemo(() => {
        const map: Record<string, number> = {};
        pipelines.forEach(p => { const t = p.trigger || 'unknown'; map[t] = (map[t] || 0) + 1; });
        return Object.entries(map).map(([name, value]) => ({ name, value }));
    }, [pipelines]);

    if (loading) return (
        <CMSLayout title="CI/CD Pipelines" subTitle="Loading...">
            <div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div>
        </CMSLayout>
    );

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#3b82f6', '#10b981']}>CI/CD Pipelines</AuroraText>}
            subTitle={<DecryptedText text="Pipeline orchestration, build analytics & deployment tracking" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>

            {/* ── 1. Pipeline Stats ──────────────────────────── */}
            <Row gutter={[12, 12]}>
                {stats.map((s, i) => (
                    <Col key={i} xs={12} md={4} lg={Math.floor(24 / stats.length)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glassCard, borderTop: `3px solid ${s.c}` }} styles={{ body: { padding: '14px 16px' } }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                    <div>
                                        <Text type="secondary" style={{ fontSize: 11 }}>{s.t}</Text>
                                        <div style={{ fontSize: 22, fontWeight: 700, color: s.c, fontFamily: 'monospace', lineHeight: 1.3 }}>{s.v}</div>
                                    </div>
                                    <div style={{ width: 32, height: 32, borderRadius: 10, background: `${s.c}12`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: s.c, fontSize: 16 }}>{s.i}</div>
                                </div>
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* ── 2. Pipeline Stage Visualization ────────────── */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.2 }}>
                <Card size="small" style={glassCard} title={<><RocketOutlined style={{ color: themeColor }} /> <Text strong style={{ fontSize: 13 }}>Pipeline Stage Flow</Text></>}>
                    {recentPipelines.length > 0 ? (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                            {recentPipelines.map((p, pi) => {
                                const pBuilds = builds.filter(b => b.pipelineId === p.id);
                                const isExpanded = expandedPipeline === p.id;
                                return (
                                    <motion.div key={p.id} initial={{ opacity: 0, x: -12 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 + pi * 0.04 }}
                                        style={{ padding: '10px 14px', borderRadius: 10, background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.015)', border: `1px solid ${isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'}`, cursor: 'pointer' }}
                                        onClick={() => setExpandedPipeline(isExpanded ? null : p.id)}
                                    >
                                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                                <Text strong style={{ fontSize: 12 }}>{p.name}</Text>
                                                <Tag style={{ fontSize: 9, borderRadius: 8, margin: 0 }} color="blue"><BranchesOutlined /> {p.branch}</Tag>
                                                {p.commit && <Text code style={{ fontSize: 9 }}>{p.commit.slice(0, 7)}</Text>}
                                                {p.author && <Text type="secondary" style={{ fontSize: 10 }}><UserOutlined /> {p.author}</Text>}
                                            </div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                                <Text type="secondary" style={{ fontSize: 10 }}>{fmtDur(p.duration)}</Text>
                                                <Text type="secondary" style={{ fontSize: 10 }}>{dayjs(p.startedAt).format('MMM D HH:mm')}</Text>
                                            </div>
                                        </div>
                                        {/* Stage nodes */}
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 0, marginTop: 8, overflowX: 'auto' }}>
                                            {(p.stages || []).map((stage, si) => {
                                                const build = pBuilds.find(b => b.stage === stage);
                                                const st = build?.status || (si === 0 && p.status === 'running' ? 'running' : 'pending');
                                                const sc = STATUS_MAP[st]?.color || '#9ca3af';
                                                return (
                                                    <React.Fragment key={si}>
                                                        {si > 0 && <div style={{ width: 24, height: 2, background: isDark ? 'rgba(255,255,255,0.12)' : '#d1d5db', flexShrink: 0 }} />}
                                                        <Tooltip title={`${stage}: ${st}`}>
                                                            <div style={{
                                                                minWidth: 28, height: 28, borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                                background: `${sc}20`, border: `2px solid ${sc}`, fontSize: 9, fontWeight: 600, color: sc, flexShrink: 0,
                                                                animation: st === 'running' ? 'pulse 1.5s infinite' : undefined,
                                                                padding: '0 6px',
                                                            }}>
                                                                {stage.slice(0, 4)}
                                                            </div>
                                                        </Tooltip>
                                                    </React.Fragment>
                                                );
                                            })}
                                            <div style={{ marginLeft: 10 }}>
                                                <Tag color={STATUS_MAP[p.status]?.antColor || 'default'} style={{ borderRadius: 10, fontSize: 10, margin: 0 }}>
                                                    {p.status === 'running' && <SyncOutlined spin style={{ marginRight: 4 }} />}{p.status}
                                                </Tag>
                                            </div>
                                        </div>
                                        {/* Expanded build details */}
                                        {isExpanded && pBuilds.length > 0 && (
                                            <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} style={{ marginTop: 10, paddingTop: 8, borderTop: `1px dashed ${isDark ? 'rgba(255,255,255,0.1)' : '#e5e7eb'}` }}>
                                                {pBuilds.map(b => (
                                                    <div key={b.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '4px 0', fontSize: 11 }}>
                                                        <Text style={{ fontSize: 11 }}>{b.stage}</Text>
                                                        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                                                            <Tag color={STATUS_MAP[b.status]?.antColor || 'default'} style={{ borderRadius: 8, fontSize: 9, margin: 0 }}>{b.status}</Tag>
                                                            <Text type="secondary" style={{ fontSize: 10, fontFamily: 'monospace' }}>{fmtDur(b.duration)}</Text>
                                                        </div>
                                                    </div>
                                                ))}
                                            </motion.div>
                                        )}
                                    </motion.div>
                                );
                            })}
                        </div>
                    ) : <Empty description="No pipelines found" />}
                </Card>
            </motion.div>

            {/* ── 3. Pipeline List Table ──────────────────────── */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                <Card size="small" style={glassCard} title={<><DeploymentUnitOutlined style={{ color: '#3b82f6' }} /> <Text strong style={{ fontSize: 13 }}>All Pipelines</Text></>}
                    extra={<div style={{ display: 'flex', gap: 8 }}>
                        <Select allowClear placeholder="Status" size="small" style={{ width: 110 }} value={statusFilter} onChange={setStatusFilter}
                            options={Object.keys(STATUS_MAP).map(s => ({ label: s, value: s }))} />
                        <Select allowClear placeholder="Branch" size="small" style={{ width: 120 }} value={branchFilter} onChange={setBranchFilter}
                            options={branches.map(b => ({ label: b, value: b }))} />
                    </div>}
                >
                    <Table dataSource={tableData} rowKey="id" size="small" pagination={{ pageSize: 8, size: 'small' }} columns={[
                        { title: '#', dataIndex: 'id', width: 70, render: (v: string) => <Text strong style={{ fontSize: 11, color: '#3b82f6' }}>#{v.slice(-5)}</Text> },
                        { title: 'Name', dataIndex: 'name', render: (v: string) => <Text strong style={{ fontSize: 12 }}>{v}</Text> },
                        { title: 'Branch', dataIndex: 'branch', render: (v: string) => <Tag style={{ fontSize: 10, borderRadius: 8 }}><BranchesOutlined /> {v}</Tag> },
                        { title: 'Stages', dataIndex: 'stages', width: 120, render: (_: any, r: Pipeline) => (
                            <div style={{ display: 'flex', gap: 3 }}>
                                {(r.stages || []).map((_, si) => {
                                    const b = builds.find(b => b.pipelineId === r.id && b.stage === r.stages[si]);
                                    const c = STATUS_MAP[b?.status || 'pending']?.color || '#9ca3af';
                                    return <div key={si} style={{ width: 8, height: 8, borderRadius: '50%', background: c }} />;
                                })}
                            </div>
                        )},
                        { title: 'Status', dataIndex: 'status', width: 95, render: (v: string) => (
                            <Tag color={STATUS_MAP[v]?.antColor || 'default'} style={{ borderRadius: 10, fontSize: 10 }}>
                                {v === 'running' && <SyncOutlined spin style={{ marginRight: 3 }} />}{v}
                            </Tag>
                        )},
                        { title: 'Duration', dataIndex: 'duration', width: 80, render: (v: number) => <Text style={{ fontSize: 11, fontFamily: 'monospace' }}>{fmtDur(v)}</Text> },
                        { title: 'Trigger', dataIndex: 'trigger', width: 80, render: (v: string) => <Tag style={{ fontSize: 9, borderRadius: 8 }}>{v}</Tag> },
                        { title: 'Author', dataIndex: 'author', render: (v: string) => <Text type="secondary" style={{ fontSize: 11 }}>{v}</Text> },
                        { title: 'Started', dataIndex: 'startedAt', width: 120, render: (v: string) => <Text type="secondary" style={{ fontSize: 10 }}>{dayjs(v).format('MMM D HH:mm')}</Text> },
                    ]} />
                </Card>
            </motion.div>

            {/* ── 4 & 5. Build Trends ────────────────────────── */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={12}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.35 }}>
                        <Card size="small" style={glassCard} title={<><CheckCircleOutlined style={{ color: '#10b981' }} /> <Text strong style={{ fontSize: 13 }}>Build Success Trend</Text></>}>
                            <div style={{ height: 260 }}>
                                {buildTrend.length > 0 ? (
                                    <ResponsiveContainer>
                                        <AreaChart data={buildTrend}>
                                            <defs>
                                                <linearGradient id="successGrad" x1="0" y1="0" x2="0" y2="1">
                                                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                                                    <stop offset="95%" stopColor="#10b981" stopOpacity={0.02} />
                                                </linearGradient>
                                                <linearGradient id="failGrad" x1="0" y1="0" x2="0" y2="1">
                                                    <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3} />
                                                    <stop offset="95%" stopColor="#ef4444" stopOpacity={0.02} />
                                                </linearGradient>
                                            </defs>
                                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                            <XAxis dataKey="day" tick={tickStyle} />
                                            <YAxis tick={tickStyle} />
                                            <RTooltip contentStyle={tooltipStyle} />
                                            <Area type="monotone" dataKey="success" stroke="#10b981" fill="url(#successGrad)" strokeWidth={2} name="Success" />
                                            <Area type="monotone" dataKey="failed" stroke="#ef4444" fill="url(#failGrad)" strokeWidth={2} name="Failed" />
                                        </AreaChart>
                                    </ResponsiveContainer>
                                ) : <Empty description="No build data" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={12}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                        <Card size="small" style={glassCard} title={<><LineChartOutlined style={{ color: '#f59e0b' }} /> <Text strong style={{ fontSize: 13 }}>Build Duration Trend</Text></>}>
                            <div style={{ height: 260 }}>
                                {durationTrend.length > 0 ? (
                                    <ResponsiveContainer>
                                        <LineChart data={durationTrend}>
                                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                            <XAxis dataKey="day" tick={tickStyle} />
                                            <YAxis tickFormatter={v => fmtDur(v)} tick={tickStyle} />
                                            <RTooltip contentStyle={tooltipStyle} formatter={(v: number) => fmtDur(v)} />
                                            <ReferenceLine y={300} stroke="#ef4444" strokeDasharray="6 3" label={{ value: '5m target', fill: '#ef4444', fontSize: 10, position: 'right' }} />
                                            <Line type="monotone" dataKey="avg" stroke="#f59e0b" strokeWidth={2} dot={{ r: 3, fill: '#f59e0b' }} name="Avg Duration (s)" />
                                        </LineChart>
                                    </ResponsiveContainer>
                                ) : <Empty description="No build duration data" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ── 6. Environment Deployment Status ───────────── */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.45 }}>
                <Card size="small" style={glassCard} title={<><CloudServerOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Environment Deployment Status</Text></>}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 0, flexWrap: 'wrap' }}>
                        {envStatus.map((e, ei) => (
                            <React.Fragment key={e.env}>
                                {ei > 0 && (
                                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '0 8px' }}>
                                        <Text type="secondary" style={{ fontSize: 16 }}>→</Text>
                                    </div>
                                )}
                                <div style={{
                                    flex: 1, minWidth: 180, padding: '14px 18px', borderRadius: 12,
                                    background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.015)',
                                    border: `1px solid ${e.latest?.status === 'failed' ? '#ef4444' : ENV_COLORS[e.env]}40`,
                                    borderTop: `3px solid ${ENV_COLORS[e.env]}`,
                                }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                                        <Text strong style={{ fontSize: 13, textTransform: 'capitalize' }}>{e.env}</Text>
                                        <div style={{
                                            width: 10, height: 10, borderRadius: '50%',
                                            background: e.latest ? (e.latest.status === 'failed' ? '#ef4444' : '#10b981') : '#9ca3af',
                                            boxShadow: e.latest?.status !== 'failed' ? `0 0 6px ${e.latest ? '#10b981' : '#9ca3af'}` : '0 0 6px #ef4444',
                                        }} />
                                    </div>
                                    {e.latest ? (<>
                                        <Text style={{ fontSize: 14, fontWeight: 700, fontFamily: 'monospace', color: ENV_COLORS[e.env] }}>{e.latest.version}</Text>
                                        <div style={{ marginTop: 4 }}>
                                            <Text type="secondary" style={{ fontSize: 10 }}><UserOutlined /> {e.latest.deployedBy}</Text>
                                        </div>
                                        <div><Text type="secondary" style={{ fontSize: 10 }}><ClockCircleOutlined /> {dayjs(e.latest.deployedAt).format('MMM D HH:mm')}</Text></div>
                                        <Tag color={e.latest.status === 'failed' ? 'red' : 'green'} style={{ fontSize: 9, borderRadius: 8, marginTop: 6 }}>{e.latest.status}</Tag>
                                    </>) : <Text type="secondary" style={{ fontSize: 11 }}>No deployments</Text>}
                                </div>
                            </React.Fragment>
                        ))}
                    </div>
                </Card>
            </motion.div>

            {/* ── 7 & 8. Timeline + Trigger Donut ────────────── */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}>
                        <Card size="small" style={{ ...glassCard, maxHeight: 420, overflow: 'auto' }}
                            title={<><FieldTimeOutlined style={{ color: '#06b6d4' }} /> <Text strong style={{ fontSize: 13 }}>Recent Deployments</Text></>}>
                            {recentDeploys.length > 0 ? (
                                <Timeline items={recentDeploys.map(d => ({
                                    color: d.status === 'failed' ? 'red' : ENV_COLORS[d.environment] || '#3b82f6',
                                    children: (
                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 4 }}>
                                            <div>
                                                <Text strong style={{ fontSize: 12, fontFamily: 'monospace' }}>{d.version}</Text>
                                                <div style={{ display: 'flex', gap: 4, marginTop: 2 }}>
                                                    <Tag color={ENV_COLORS[d.environment] || 'blue'} style={{ fontSize: 9, borderRadius: 8, margin: 0, color: '#fff' }}>{d.environment}</Tag>
                                                    <Tag color={d.status === 'failed' ? 'red' : 'green'} style={{ fontSize: 9, borderRadius: 8, margin: 0 }}>{d.status}</Tag>
                                                </div>
                                            </div>
                                            <div style={{ textAlign: 'right' }}>
                                                <Text type="secondary" style={{ fontSize: 10 }}>{d.deployedBy}</Text>
                                                <div><Text type="secondary" style={{ fontSize: 10 }}>{dayjs(d.deployedAt).format('MMM D HH:mm')}</Text></div>
                                            </div>
                                        </div>
                                    ),
                                }))} />
                            ) : <Empty description="No deployments" />}
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.55 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }}
                            title={<><PieChartOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Pipeline Triggers</Text></>}>
                            <div style={{ height: 300, position: 'relative' }}>
                                {triggerData.length > 0 ? (<>
                                    <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', textAlign: 'center', zIndex: 1, pointerEvents: 'none' }}>
                                        <div style={{ fontSize: 24, fontWeight: 800, color: themeColor }}>{pipelines.length}</div>
                                        <Text type="secondary" style={{ fontSize: 10 }}>Total</Text>
                                    </div>
                                    <ResponsiveContainer>
                                        <PieChart>
                                            <Pie data={triggerData} cx="50%" cy="50%" innerRadius={55} outerRadius={90} paddingAngle={3} dataKey="value"
                                                label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                                                labelLine={{ stroke: '#999', strokeWidth: 1 }}>
                                                {triggerData.map((_, i) => <Cell key={i} fill={TRIGGER_COLORS[i % TRIGGER_COLORS.length]} />)}
                                            </Pie>
                                            <RTooltip contentStyle={tooltipStyle} />
                                        </PieChart>
                                    </ResponsiveContainer>
                                </>) : <Empty description="No trigger data" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

        </div>
        <style jsx global>{`
            @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
        `}</style>
        </CMSLayout>
    );
}

'use client';
import React from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Statistic, Space, Tag, Button, Table, Badge, Progress } from 'antd';
import { BugOutlined, SafetyCertificateOutlined, CheckCircleOutlined, WarningOutlined, ReloadOutlined, LinkOutlined, CodeOutlined, PercentageOutlined } from '@ant-design/icons';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const PROJECTS = [
    { name: 'admin', gate: 'OK', bugs: 2, vulns: 0, smells: 15, coverage: 78, duplication: 3.2, lines: 48500, color: '#10b981' },
    { name: 'middleware', gate: 'OK', bugs: 0, vulns: 1, smells: 8, coverage: 82, duplication: 2.1, lines: 12300, color: '#10b981' },
    { name: 'landing-page', gate: 'WARN', bugs: 1, vulns: 0, smells: 5, coverage: 65, duplication: 4.5, lines: 8900, color: '#f59e0b' },
];

const ISSUES = [
    { key: 'BUG-1', type: 'Bug', severity: 'Major', file: 'src/lib/graphqlClient.ts', line: 45, message: 'Possible null dereference', effort: '15min' },
    { key: 'BUG-2', type: 'Bug', severity: 'Minor', file: 'src/app/admin/crm/deals/page.tsx', line: 89, message: 'Unused variable assignment', effort: '5min' },
    { key: 'BUG-3', type: 'Bug', severity: 'Minor', file: 'src/app/page.tsx', line: 12, message: 'Missing alt attribute', effort: '2min' },
    { key: 'VULN-1', type: 'Vulnerability', severity: 'Critical', file: 'src/middleware/auth/auth.service.ts', line: 23, message: 'Hardcoded credential detected', effort: '30min' },
    { key: 'SMELL-1', type: 'Code Smell', severity: 'Minor', file: 'src/config/menuConfig.tsx', line: 156, message: 'Cognitive complexity too high', effort: '1h' },
];

export default function SonarQubePage() {
    const { themeColor } = usePreferencesStore();
    const totalBugs = PROJECTS.reduce((s, p) => s + p.bugs, 0);
    const totalVulns = PROJECTS.reduce((s, p) => s + p.vulns, 0);
    const avgCoverage = Math.round(PROJECTS.reduce((s, p) => s + p.coverage, 0) / PROJECTS.length);

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#4e9bcd', '#10b981']}>SonarQube</AuroraText>} subTitle={<DecryptedText text="Code quality gates, coverage metrics & vulnerability scanning" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[<Button key="o" icon={<LinkOutlined />} type="primary" onClick={() => window.open('http://localhost:9092', '_blank')}>Open SonarQube</Button>, <Button key="r" icon={<ReloadOutlined />} />]}>
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Projects', v: PROJECTS.length, c: '#3b82f6', i: <CodeOutlined /> }, { t: 'Bugs', v: totalBugs, c: totalBugs > 0 ? '#f59e0b' : '#10b981', i: <BugOutlined /> }, { t: 'Vulnerabilities', v: totalVulns, c: totalVulns > 0 ? '#ef4444' : '#10b981', i: <WarningOutlined /> }, { t: 'Avg Coverage', v: `${avgCoverage}%`, c: avgCoverage >= 80 ? '#10b981' : '#f59e0b', i: <PercentageOutlined /> }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} prefix={s.i} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Row gutter={[14, 14]}>
                    {PROJECTS.map((p, i) => (
                        <Col key={p.name} xs={24} md={8}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 + i * 0.06 }}>
                                <Card size="small" hoverable style={{ ...glass, borderTop: `3px solid ${p.color}` }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                                        <Text strong style={{ fontSize: 14 }}>{p.name}</Text>
                                        <Tag color={p.gate === 'OK' ? 'green' : 'orange'} style={{ borderRadius: 10, fontSize: 10 }}>{p.gate === 'OK' ? '✓ Passed' : '⚠ Warning'}</Tag>
                                    </div>
                                    <Row gutter={4}><Col span={6}><Text type="secondary" style={{ fontSize: 9 }}>Bugs</Text><br /><Text strong style={{ color: p.bugs > 0 ? '#f59e0b' : '#10b981' }}>{p.bugs}</Text></Col><Col span={6}><Text type="secondary" style={{ fontSize: 9 }}>Vulns</Text><br /><Text strong style={{ color: p.vulns > 0 ? '#ef4444' : '#10b981' }}>{p.vulns}</Text></Col><Col span={6}><Text type="secondary" style={{ fontSize: 9 }}>Smells</Text><br /><Text strong>{p.smells}</Text></Col><Col span={6}><Text type="secondary" style={{ fontSize: 9 }}>Dup%</Text><br /><Text strong>{p.duplication}%</Text></Col></Row>
                                    <div style={{ marginTop: 8 }}><Text type="secondary" style={{ fontSize: 10 }}>Coverage</Text><Progress percent={p.coverage} size="small" strokeColor={p.coverage >= 80 ? '#10b981' : p.coverage >= 60 ? '#f59e0b' : '#ef4444'} /></div>
                                    <Text type="secondary" style={{ fontSize: 9 }}>{p.lines.toLocaleString()} lines</Text>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={glass} title={<Space><BugOutlined style={{ color: '#ef4444' }} /><Text strong>Open Issues</Text><Badge count={ISSUES.length} style={{ backgroundColor: '#ef4444' }} /></Space>}>
                    <Table dataSource={ISSUES} rowKey="key" size="small" pagination={false} columns={[
                        { title: 'Key', dataIndex: 'key', width: 70, render: (v: string) => <Text strong style={{ fontSize: 11, color: '#3b82f6' }}>{v}</Text> },
                        { title: 'Type', dataIndex: 'type', render: (v: string) => <Tag color={v === 'Bug' ? 'red' : v === 'Vulnerability' ? 'orange' : 'blue'} style={{ borderRadius: 10, fontSize: 10 }}>{v}</Tag> },
                        { title: 'Severity', dataIndex: 'severity', width: 80, render: (v: string) => <Tag color={v === 'Critical' ? '#ef4444' : v === 'Major' ? '#f59e0b' : '#6b7280'} style={{ borderRadius: 10, fontSize: 10, color: '#fff' }}>{v}</Tag> },
                        { title: 'File', dataIndex: 'file', render: (v: string, r: any) => <Text style={{ fontSize: 10, fontFamily: 'monospace' }}>{v}:{r.line}</Text> },
                        { title: 'Message', dataIndex: 'message', render: (v: string) => <Text style={{ fontSize: 11 }}>{v}</Text> },
                        { title: 'Effort', dataIndex: 'effort', width: 60 },
                    ]} />
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Button, Space, Tag, Spin, Empty, Row, Col, Modal, Form, Input, Select, Breadcrumb, Dropdown, message, Tooltip, Upload, Badge, Popconfirm } from 'antd';
import { FolderOutlined, FileOutlined, PlusOutlined, UploadOutlined, DeleteOutlined, EditOutlined, DownloadOutlined, EyeOutlined, FolderAddOutlined, ArrowLeftOutlined, FileExcelOutlined, FilePdfOutlined, FileImageOutlined, FileWordOutlined, FileZipOutlined, FileUnknownOutlined, LockOutlined, ShareAltOutlined, HomeOutlined, ReloadOutlined } from '@ant-design/icons';
import { documentService, DocFolder, DocFile } from '@/lib/documentService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const fileIcon = (mime?: string) => {
    if (!mime) return <FileUnknownOutlined style={{ color: '#6b7280' }} />;
    if (mime.includes('image')) return <FileImageOutlined style={{ color: '#10b981' }} />;
    if (mime.includes('pdf')) return <FilePdfOutlined style={{ color: '#ef4444' }} />;
    if (mime.includes('spreadsheet') || mime.includes('excel')) return <FileExcelOutlined style={{ color: '#10b981' }} />;
    if (mime.includes('word') || mime.includes('document')) return <FileWordOutlined style={{ color: '#3b82f6' }} />;
    if (mime.includes('zip') || mime.includes('archive')) return <FileZipOutlined style={{ color: '#f59e0b' }} />;
    return <FileOutlined style={{ color: '#6366f1' }} />;
};
const fmtSize = (b: number) => { if (b >= 1e9) return `${(b/1e9).toFixed(1)} GB`; if (b >= 1e6) return `${(b/1e6).toFixed(1)} MB`; if (b >= 1e3) return `${(b/1e3).toFixed(1)} KB`; return `${b} B`; };

export default function FileExplorerPage() {
    const { themeColor } = usePreferencesStore();
    const [loading, setLoading] = useState(true);
    const [folders, setFolders] = useState<DocFolder[]>([]);
    const [files, setFiles] = useState<DocFile[]>([]);
    const [currentFolder, setCurrentFolder] = useState<string | undefined>(undefined);
    const [breadcrumbs, setBreadcrumbs] = useState<{ id?: string; name: string }[]>([{ name: 'Root' }]);
    const [folderModal, setFolderModal] = useState(false);
    const [previewFile, setPreviewFile] = useState<DocFile | null>(null);
    const [form] = Form.useForm();
    const [msgApi, ctxHolder] = message.useMessage();

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [f, fi] = await Promise.all([
                documentService.getFolders(undefined, currentFolder),
                documentService.getFiles(undefined, { folderId: currentFolder }),
            ]);
            setFolders(f); setFiles(fi);
        } catch {} finally { setLoading(false); }
    }, [currentFolder]);
    useEffect(() => { load(); }, [load]);

    const openFolder = (folder: DocFolder) => {
        setCurrentFolder(folder.id);
        setBreadcrumbs(prev => [...prev, { id: folder.id, name: folder.name }]);
    };
    const goToBreadcrumb = (index: number) => {
        const bc = breadcrumbs.slice(0, index + 1);
        setBreadcrumbs(bc);
        setCurrentFolder(bc[bc.length - 1].id);
    };
    const goUp = () => { if (breadcrumbs.length > 1) goToBreadcrumb(breadcrumbs.length - 2); };

    const createFolder = async () => {
        try {
            const vals = await form.validateFields();
            await documentService.createFolder(undefined, { ...vals, parentId: currentFolder });
            msgApi.success('Folder created');
            setFolderModal(false); form.resetFields(); load();
        } catch (e: any) { if (e.message) msgApi.error(e.message); }
    };
    const deleteFolder = async (id: string) => { try { await documentService.deleteFolder(id); msgApi.success('Deleted'); load(); } catch { msgApi.error('Failed'); } };
    const deleteFile = async (id: string) => { try { await documentService.deleteFile(id); msgApi.success('Deleted'); load(); } catch { msgApi.error('Failed'); } };

    const combined = [
        ...folders.map(f => ({ key: `f-${f.id}`, isFolder: true, id: f.id, name: f.name, mimeType: 'folder', sizeBytes: 0, updatedAt: f.createdAt, createdBy: f.createdBy, color: f.color, childCount: f.childCount, fileCount: f.fileCount, status: 'active', tags: [] as string[], currentVersion: 0 })),
        ...files.map(f => ({ key: `d-${f.id}`, isFolder: false, id: f.id, name: f.name, mimeType: f.mimeType || '', sizeBytes: f.sizeBytes, updatedAt: f.updatedAt, createdBy: f.createdBy, color: undefined as string | undefined, childCount: 0, fileCount: 0, status: f.status, tags: f.tags, currentVersion: f.currentVersion })),
    ];

    const columns = [
        {
            title: 'Name', key: 'name', ellipsis: true,
            render: (_: any, r: typeof combined[0]) => (
                <Space>
                    {r.isFolder ? <FolderOutlined style={{ color: r.color || themeColor, fontSize: 16 }} /> : fileIcon(r.mimeType)}
                    <Text strong={r.isFolder} style={{ cursor: r.isFolder ? 'pointer' : undefined }} onClick={() => r.isFolder && openFolder(r as any)}>{r.name}</Text>
                    {r.currentVersion > 1 && <Tag style={{ fontSize: 10, padding: '0 4px' }}>v{r.currentVersion}</Tag>}
                </Space>
            ),
            sorter: (a: typeof combined[0], b: typeof combined[0]) => (a.isFolder === b.isFolder ? a.name.localeCompare(b.name) : a.isFolder ? -1 : 1),
            defaultSortOrder: 'ascend' as const,
        },
        { title: 'Type', key: 'type', width: 100, render: (_: any, r: typeof combined[0]) => r.isFolder ? <Tag color="blue">Folder</Tag> : <Tag>{(r.mimeType || '').split('/').pop()}</Tag> },
        { title: 'Size', key: 'size', width: 100, render: (_: any, r: typeof combined[0]) => r.isFolder ? `${r.fileCount || 0} files` : fmtSize(r.sizeBytes) },
        { title: 'Modified', key: 'mod', width: 140, render: (_: any, r: typeof combined[0]) => r.updatedAt ? dayjs(r.updatedAt).format('DD MMM YYYY HH:mm') : '—' },
        { title: 'Owner', dataIndex: 'createdBy', key: 'owner', width: 100, render: (v: string) => v || '—' },
        {
            title: '', key: 'actions', width: 80,
            render: (_: any, r: typeof combined[0]) => (
                <Space size={4}>
                    {!r.isFolder && <Tooltip title="Preview"><Button size="small" type="text" icon={<EyeOutlined />} onClick={() => setPreviewFile(r as any)} /></Tooltip>}
                    <Popconfirm title="Delete?" onConfirm={() => r.isFolder ? deleteFolder(r.id) : deleteFile(r.id)}>
                        <Button size="small" type="text" icon={<DeleteOutlined />} danger />
                    </Popconfirm>
                </Space>
            ),
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>File Explorer</AuroraText>}
            subTitle={<DecryptedText text="Browse, upload & manage documents" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
            {ctxHolder}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>

                {/* Toolbar */}
                <Card style={glass} size="small">
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 10 }}>
                        <Space>
                            {breadcrumbs.length > 1 && <Button icon={<ArrowLeftOutlined />} size="small" onClick={goUp} />}
                            <Breadcrumb items={breadcrumbs.map((bc, i) => ({
                                title: i === 0 ? <HomeOutlined /> : bc.name,
                                onClick: i < breadcrumbs.length - 1 ? () => goToBreadcrumb(i) : undefined,
                                className: i < breadcrumbs.length - 1 ? 'cursor-pointer' : '',
                            }))} />
                        </Space>
                        <Space>
                            <Button icon={<ReloadOutlined />} size="small" onClick={load} />
                            <Button icon={<FolderAddOutlined />} onClick={() => { form.resetFields(); setFolderModal(true); }}>New Folder</Button>
                            <Upload showUploadList={false} multiple beforeUpload={() => false} onChange={info => { if (info.file) { msgApi.success(`${info.file.name} queued for upload`); } }}>
                                <Button type="primary" icon={<UploadOutlined />} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>Upload</Button>
                            </Upload>
                        </Space>
                    </div>
                </Card>

                {/* Stats Row */}
                <Row gutter={[10, 10]}>
                    {[
                        { t: 'Folders', v: folders.length, c: '#6366f1', icon: <FolderOutlined /> },
                        { t: 'Files', v: files.length, c: '#10b981', icon: <FileOutlined /> },
                        { t: 'Total Size', v: fmtSize(files.reduce((s, f) => s + f.sizeBytes, 0)), c: '#3b82f6', icon: <FileOutlined /> },
                    ].map((s, i) => (
                        <Col key={i} xs={8}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, textAlign: 'center', borderTop: `2px solid ${s.c}` }}>
                                <div style={{ color: s.c, fontSize: 14, marginBottom: 2 }}>{s.icon}</div>
                                <Text strong style={{ fontSize: 16, color: s.c, display: 'block' }}>{s.v}</Text>
                                <Text type="secondary" style={{ fontSize: 10 }}>{s.t}</Text>
                            </Card>
                        </motion.div></Col>
                    ))}
                </Row>

                {/* File Table */}
                <Card style={glass}>
                    {loading ? <div style={{ textAlign: 'center', padding: 60 }}><Spin size="large" /></div> :
                        combined.length === 0 ? <Empty description="This folder is empty." /> :
                        <Table scroll={{ x: 800 }} dataSource={combined} columns={columns} size="small" pagination={{ pageSize: 30, showTotal: t => `${t} items` }} />
                    }
                </Card>
            </motion.div>

            <Modal title="New Folder" open={folderModal} onOk={createFolder} onCancel={() => setFolderModal(false)} okText="Create">
                <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
                    <Form.Item name="name" label="Folder Name" rules={[{ required: true }]}><Input placeholder="Project Documents" /></Form.Item>
                    <Form.Item name="color" label="Color" initialValue="#6366f1"><Input type="color" style={{ width: 60, height: 32 }} /></Form.Item>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                </Form>
            </Modal>

            <Modal title="File Preview" open={!!previewFile} onCancel={() => setPreviewFile(null)} footer={null} width={600}>
                {previewFile && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginTop: 16 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <div style={{ fontSize: 32 }}>{fileIcon(previewFile.mimeType)}</div>
                            <div>
                                <Text strong style={{ fontSize: 16, display: 'block' }}>{previewFile.name}</Text>
                                <Text type="secondary" style={{ fontSize: 12 }}>{fmtSize(previewFile.sizeBytes)} • Version {previewFile.currentVersion}</Text>
                            </div>
                        </div>
                        <Row gutter={[12, 8]}>
                            {[{ l: 'Type', v: previewFile.mimeType }, { l: 'Status', v: previewFile.status }, { l: 'Created', v: previewFile.createdAt ? dayjs(previewFile.createdAt).format('DD MMM YYYY') : '—' }, { l: 'Owner', v: previewFile.createdBy || '—' }].map((p, i) => (
                                <Col span={12} key={i}><Text type="secondary" style={{ fontSize: 11 }}>{p.l}:</Text><br /><Text style={{ fontSize: 12 }}>{p.v}</Text></Col>
                            ))}
                        </Row>
                        {previewFile.tags?.length > 0 && <Space wrap>{previewFile.tags.map(t => <Tag key={t}>{t}</Tag>)}</Space>}
                    </div>
                )}
            </Modal>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Tag, Spin, Empty, Space, Button, Tooltip } from 'antd';
import { ClockCircleOutlined, FileOutlined, FileImageOutlined, FilePdfOutlined, FileExcelOutlined, FileWordOutlined, FileUnknownOutlined, EyeOutlined, DownloadOutlined } from '@ant-design/icons';
import { documentService, DocFile } from '@/lib/documentService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const fmtSize = (b: number) => { if (b >= 1e6) return `${(b/1e6).toFixed(1)} MB`; if (b >= 1e3) return `${(b/1e3).toFixed(1)} KB`; return `${b} B`; };

const fileIcon = (mime?: string) => {
    if (!mime) return <FileUnknownOutlined style={{ color: '#6b7280' }} />;
    if (mime.includes('image')) return <FileImageOutlined style={{ color: '#10b981' }} />;
    if (mime.includes('pdf')) return <FilePdfOutlined style={{ color: '#ef4444' }} />;
    if (mime.includes('excel') || mime.includes('spreadsheet')) return <FileExcelOutlined style={{ color: '#10b981' }} />;
    if (mime.includes('word') || mime.includes('document')) return <FileWordOutlined style={{ color: '#3b82f6' }} />;
    return <FileOutlined style={{ color: '#6366f1' }} />;
};

export default function RecentDocumentsPage() {
    const { themeColor } = usePreferencesStore();
    const [loading, setLoading] = useState(true);
    const [files, setFiles] = useState<DocFile[]>([]);

    useEffect(() => { (async () => { setLoading(true); try { setFiles(await documentService.getRecentFiles(undefined, 50)); } catch {} finally { setLoading(false); } })(); }, []);

    const columns = [
        {
            title: 'Document', key: 'name', ellipsis: true,
            render: (_: any, r: DocFile) => (
                <Space>
                    <div style={{ width: 32, height: 32, borderRadius: 8, background: 'rgba(99,102,241,0.08)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{fileIcon(r.mimeType)}</div>
                    <div>
                        <Text strong style={{ display: 'block', fontSize: 13 }}>{r.name}</Text>
                        <Text type="secondary" style={{ fontSize: 11 }}>{fmtSize(r.sizeBytes)} • v{r.currentVersion}</Text>
                    </div>
                </Space>
            ),
        },
        { title: 'Type', key: 'type', width: 100, render: (_: any, r: DocFile) => <Tag>{(r.mimeType || 'unknown').split('/').pop()}</Tag> },
        { title: 'Modified', key: 'mod', width: 160, render: (_: any, r: DocFile) => <Tooltip title={r.updatedAt ? dayjs(r.updatedAt).format('DD MMM YYYY HH:mm') : ''}><Text type="secondary" style={{ fontSize: 12 }}><ClockCircleOutlined style={{ marginRight: 4 }} />{r.updatedAt ? dayjs(r.updatedAt).fromNow() : '—'}</Text></Tooltip> },
        { title: 'Owner', dataIndex: 'createdBy', key: 'owner', width: 100, render: (v: string) => v || '—' },
        { title: 'Status', key: 'st', width: 90, render: (_: any, r: DocFile) => <Tag color={r.status === 'active' ? 'green' : r.status === 'archived' ? 'orange' : 'default'}>{r.status}</Tag> },
        { title: 'Tags', key: 'tags', width: 150, render: (_: any, r: DocFile) => r.tags?.length ? <Space wrap size={4}>{r.tags.slice(0, 2).map(t => <Tag key={t} style={{ fontSize: 10 }}>{t}</Tag>)}{r.tags.length > 2 && <Tag style={{ fontSize: 10 }}>+{r.tags.length - 2}</Tag>}</Space> : '—' },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Recent Documents</AuroraText>}
            subTitle={<DecryptedText text="Recently uploaded and modified files" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>
                <Card style={glass}>
                    {loading ? <div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" /></div> :
                        files.length === 0 ? <Empty description="No recent documents found." /> :
                        <Table scroll={{ x: 800 }} dataSource={files.map(f => ({ ...f, key: f.id }))} columns={columns} size="small" pagination={{ pageSize: 20, showTotal: t => `${t} documents` }} />
                    }
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Tag, Spin, Empty, Space } from 'antd';
import { ShareAltOutlined, FileOutlined, FileImageOutlined, FilePdfOutlined, FileExcelOutlined, FileWordOutlined, FileUnknownOutlined, LockOutlined, EyeOutlined, EditOutlined } from '@ant-design/icons';
import { documentService, DocFile } from '@/lib/documentService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const fmtSize = (b: number) => { if (b >= 1e6) return `${(b/1e6).toFixed(1)} MB`; if (b >= 1e3) return `${(b/1e3).toFixed(1)} KB`; return `${b} B`; };
const fileIcon = (mime?: string) => {
    if (!mime) return <FileUnknownOutlined style={{ color: '#6b7280' }} />;
    if (mime.includes('image')) return <FileImageOutlined style={{ color: '#10b981' }} />;
    if (mime.includes('pdf')) return <FilePdfOutlined style={{ color: '#ef4444' }} />;
    if (mime.includes('excel') || mime.includes('spreadsheet')) return <FileExcelOutlined style={{ color: '#10b981' }} />;
    if (mime.includes('word')) return <FileWordOutlined style={{ color: '#3b82f6' }} />;
    return <FileOutlined style={{ color: '#6366f1' }} />;
};

const permColor: Record<string, string> = { admin: 'red', edit: 'blue', view: 'green' };
const permIcon: Record<string, React.ReactNode> = { admin: <LockOutlined />, edit: <EditOutlined />, view: <EyeOutlined /> };

export default function SharedDocumentsPage() {
    const { themeColor } = usePreferencesStore();
    const [loading, setLoading] = useState(true);
    const [files, setFiles] = useState<DocFile[]>([]);

    useEffect(() => { (async () => { setLoading(true); try { setFiles(await documentService.getSharedFiles()); } catch {} finally { setLoading(false); } })(); }, []);

    const columns = [
        {
            title: 'Document', key: 'name', ellipsis: true,
            render: (_: any, r: DocFile) => <Space><div style={{ width: 32, height: 32, borderRadius: 8, background: 'rgba(99,102,241,0.08)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{fileIcon(r.mimeType)}</div><div><Text strong style={{ display: 'block', fontSize: 13 }}>{r.name}</Text><Text type="secondary" style={{ fontSize: 11 }}>{fmtSize(r.sizeBytes)}</Text></div></Space>,
