                    </Form.Item>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} placeholder="Template description..." /></Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

'use client';
import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Tag, Spin, Empty, Row, Col, Button, Modal, Form, Input, Space, message, Steps, Badge, Tabs } from 'antd';
import { ApartmentOutlined, PlusOutlined, CheckCircleOutlined, CloseCircleOutlined, ClockCircleOutlined, SendOutlined, DeleteOutlined } from '@ant-design/icons';
import { documentService, DocWorkflow, DocWorkflowInstance } from '@/lib/documentService';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const statusConfig: Record<string, { color: string; icon: React.ReactNode }> = {
    pending: { color: 'blue', icon: <ClockCircleOutlined /> },
    in_progress: { color: 'orange', icon: <ClockCircleOutlined /> },
    approved: { color: 'green', icon: <CheckCircleOutlined /> },
    rejected: { color: 'red', icon: <CloseCircleOutlined /> },
    cancelled: { color: 'default', icon: <CloseCircleOutlined /> },
};

export default function WorkflowsPage() {
    const { themeColor } = usePreferencesStore();
    const [loading, setLoading] = useState(true);
    const [workflows, setWorkflows] = useState<DocWorkflow[]>([]);
    const [instances, setInstances] = useState<DocWorkflowInstance[]>([]);
    const [modal, setModal] = useState(false);
    const [form] = Form.useForm();
    const [msgApi, ctxHolder] = message.useMessage();

    useEffect(() => {
        (async () => {
            setLoading(true);
            try {
                const [wf, inst] = await Promise.all([documentService.getWorkflows(), documentService.getWorkflowInstances()]);
                setWorkflows(wf); setInstances(inst);
            } catch {} finally { setLoading(false); }
        })();
    }, []);

    const createWf = async () => {
        try {
            const vals = await form.validateFields();
            const steps = (vals.steps || '').split(',').map((s: string) => s.trim()).filter(Boolean).map((s: string, i: number) => ({ step: i + 1, name: s, approver: '' }));
            await documentService.createWorkflow(undefined, { name: vals.name, description: vals.description, steps });
            msgApi.success('Workflow created');
            setModal(false); form.resetFields();
            setWorkflows(await documentService.getWorkflows());
        } catch (e: any) { if (e.message) msgApi.error(e.message); }
    };

    const approve = async (id: string) => { try { await documentService.approveWorkflowStep(id); msgApi.success('Approved'); setInstances(await documentService.getWorkflowInstances()); } catch { msgApi.error('Failed'); } };
    const reject = async (id: string) => { try { await documentService.rejectWorkflowStep(id); msgApi.success('Rejected'); setInstances(await documentService.getWorkflowInstances()); } catch { msgApi.error('Failed'); } };

    const pendingCount = instances.filter(i => ['pending', 'in_progress'].includes(i.status)).length;
    const approvedCount = instances.filter(i => i.status === 'approved').length;
    const rejectedCount = instances.filter(i => i.status === 'rejected').length;

    const instanceCols = [
        { title: 'Document', dataIndex: 'fileName', key: 'file', ellipsis: true, render: (v: string) => <Text strong>{v || '—'}</Text> },
        { title: 'Workflow', dataIndex: 'workflowName', key: 'wf', width: 160, render: (v: string) => v || '—' },
        { title: 'Step', dataIndex: 'currentStep', key: 'step', width: 60, align: 'center' as const, render: (v: number) => <Tag>{v + 1}</Tag> },
        {
            title: 'Status', key: 'st', width: 110,
            render: (_: any, r: DocWorkflowInstance) => {
                const cfg = statusConfig[r.status] || statusConfig.pending;
                return <Tag color={cfg.color} icon={cfg.icon}>{r.status}</Tag>;
            },
        },
        { title: 'Submitted By', dataIndex: 'submittedBy', key: 'by', width: 110, render: (v: string) => v || '—' },
        { title: 'Date', key: 'date', width: 130, render: (_: any, r: DocWorkflowInstance) => r.createdAt ? dayjs(r.createdAt).format('DD MMM YYYY') : '—' },
        {
            title: '', key: 'actions', width: 120,
            render: (_: any, r: DocWorkflowInstance) => ['pending', 'in_progress'].includes(r.status) ? (
                <Space size={4}>
                    <Button size="small" type="primary" onClick={() => approve(r.id)} style={{ borderRadius: 6, background: '#10b981', borderColor: '#10b981', fontSize: 11 }}>Approve</Button>
                    <Button size="small" danger onClick={() => reject(r.id)} style={{ borderRadius: 6, fontSize: 11 }}>Reject</Button>
                </Space>
            ) : null,
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Approval Workflows</AuroraText>}
            subTitle={<DecryptedText text="Document approval chains with multi-step review" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[<Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { form.resetFields(); setModal(true); }} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>New Workflow</Button>]}>
            {ctxHolder}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>

                {/* KPIs */}
                <Row gutter={[14, 14]}>
                    {[
                        { t: 'Workflows', v: workflows.length, c: '#6366f1' },
                        { t: 'Pending', v: pendingCount, c: '#f59e0b' },
                        { t: 'Approved', v: approvedCount, c: '#10b981' },
                        { t: 'Rejected', v: rejectedCount, c: '#ef4444' },
                    ].map((s, i) => (
                        <Col key={i} xs={12} sm={6}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                            <Card size="small" style={{ ...glass, textAlign: 'center', borderTop: `3px solid ${s.c}` }}>
                                <Text style={{ fontSize: 24, fontWeight: 700, color: s.c, display: 'block' }}>{s.v}</Text>
                                <Text type="secondary" style={{ fontSize: 11 }}>{s.t}</Text>
                            </Card>
                        </motion.div></Col>
                    ))}
                </Row>

                {loading ? <div style={{ textAlign: 'center', padding: 60 }}><Spin size="large" /></div> : (
                    <Tabs defaultActiveKey="instances" items={[
                        {
                            key: 'instances', label: <Space>Approval Queue <Badge count={pendingCount} style={{ background: '#f59e0b' }} /></Space>,
                            children: instances.length === 0 ? <Card style={glass}><Empty description="No approval requests." /></Card> :
                                <Card style={glass}><Table scroll={{ x: 900 }} dataSource={instances.map(i => ({ ...i, key: i.id }))} columns={instanceCols} size="small" pagination={{ pageSize: 15 }} /></Card>,
                        },
                        {
                            key: 'workflows', label: `Workflow Definitions (${workflows.length})`,
                            children: workflows.length === 0 ? <Card style={glass}><Empty description="No workflows defined." /></Card> :
                                <Row gutter={[14, 14]}>{workflows.map((wf, i) => (
                                    <Col key={wf.id} xs={24} sm={12} lg={8}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                        <Card style={{ ...glass, borderLeft: `3px solid ${themeColor}` }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                                                <Text strong style={{ fontSize: 14 }}>{wf.name}</Text>
                                                <Tag color={wf.status === 'active' ? 'green' : 'default'}>{wf.status}</Tag>
                                            </div>
                                            {wf.description && <Text type="secondary" style={{ fontSize: 11, display: 'block', marginBottom: 8 }}>{wf.description}</Text>}
                                            <Steps size="small" items={(wf.steps || []).map((s: any) => ({ title: s.name, status: 'wait' as const }))} />
                                        </Card>
                                    </motion.div></Col>
                                ))}</Row>,
                        },
                    ]} />
                )}
            </motion.div>

            <Modal title="New Workflow" open={modal} onOk={createWf} onCancel={() => setModal(false)} okText="Create">
                <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
                    <Form.Item name="name" label="Workflow Name" rules={[{ required: true }]}><Input placeholder="Document Approval" /></Form.Item>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                    <Form.Item name="steps" label="Steps (comma-separated)" rules={[{ required: true }]}><Input placeholder="Draft Review, Manager Approval, Legal Review, Final Sign-off" /></Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { Card, Row, Col, Typography, Spin, Segmented, Table, Tag, Empty, Switch, Tooltip, theme } from "antd";
import {
    DollarOutlined, ShoppingCartOutlined, RiseOutlined, FallOutlined,
    UserOutlined, UndoOutlined, PercentageOutlined, BarChartOutlined,
    PieChartOutlined, HeatMapOutlined, TrophyOutlined, CalendarOutlined,
    ArrowRightOutlined,
} from "@ant-design/icons";
import {
    AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid,
    Tooltip as RTooltip, ResponsiveContainer, PieChart, Pie, Cell,
    Treemap, ReferenceLine, Legend,
} from "recharts";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const COLORS = ['#10b981', '#3b82f6', '#8b5cf6', '#f59e0b', '#ef4444', '#ec4899', '#06b6d4', '#84cc16'];
const FUNNEL_COLORS = ['#94a3b8', '#3b82f6', '#8b5cf6', '#f59e0b', '#06b6d4', '#10b981'];
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const fmt = (v: number) => v ? `Rp ${v.toLocaleString('id-ID')}` : 'Rp 0';
const fmtShort = (v: number) => { if (v >= 1e9) return `Rp ${(v / 1e9).toFixed(1)}B`; if (v >= 1e6) return `Rp ${(v / 1e6).toFixed(1)}M`; if (v >= 1e3) return `Rp ${(v / 1e3).toFixed(0)}K`; return `Rp ${v}`; };

type Period = 'today' | '7d' | '30d' | '90d' | 'year';
interface Order { id: string; orderNumber: string; status: string; totalAmount: number; subtotal: number; tax: number; shippingCost: number; discount: number; paymentMethod: string; paymentStatus: string; customerId: string; shippingAddress: string; fulfillmentType: string; createdAt: string; updatedAt: string; completedAt: string; }
interface OrderItem { id: string; orderId: string; itemId: string; itemName: string; quantity: number; unitPrice: number; totalPrice: number; category: string; sku: string; }
interface Customer { id: string; name: string; email: string; phone: string; customerType: string; totalOrders: number; totalSpent: number; createdAt: string; lastOrderDate: string; }

const PERIOD_DAYS: Record<Period, number> = { today: 1, '7d': 7, '30d': 30, '90d': 90, year: 365 };

function filterByPeriod<T extends { createdAt: string }>(items: T[], period: Period): T[] {
    const start = dayjs().subtract(PERIOD_DAYS[period], 'day').startOf('day');
    return items.filter(i => dayjs(i.createdAt).isAfter(start));
}
function filterPrevPeriod<T extends { createdAt: string }>(items: T[], period: Period): T[] {
    const days = PERIOD_DAYS[period];
    const end = dayjs().subtract(days, 'day').startOf('day');
    const start = end.subtract(days, 'day');
    return items.filter(i => { const d = dayjs(i.createdAt); return d.isAfter(start) && d.isBefore(end); });
}

const GET_ORDERS = `query($tenantId: String!) { ecomOrders(tenantId: $tenantId) { id orderNumber status totalAmount subtotal tax shippingCost discount paymentMethod paymentStatus customerId shippingAddress fulfillmentType createdAt updatedAt completedAt } }`;
const GET_ORDER_ITEMS = `query($tenantId: String!) { ecomOrderItems(tenantId: $tenantId) { id orderId itemId itemName quantity unitPrice totalPrice category sku } }`;
const GET_CUSTOMERS = `query($tenantId: String!) { ecomCustomers(tenantId: $tenantId) { id name email phone customerType totalOrders totalSpent createdAt lastOrderDate } }`;
const GET_STATS = `query($tenantId: String!) { ecomStats(tenantId: $tenantId) }`;

export default function SalesAnalyticsPage() {
    const [loading, setLoading] = useState(true);
    const [orders, setOrders] = useState<Order[]>([]);
    const [items, setItems] = useState<OrderItem[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [stats, setStats] = useState<any>(null);
    const [period, setPeriod] = useState<Period>('30d');
    const [compare, setCompare] = useState(false);
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');

    useEffect(() => {
        const vars = { tenantId: DEFAULT_TENANT_ID };
        Promise.allSettled([
            gql(GET_ORDERS, vars), gql(GET_ORDER_ITEMS, vars),
            gql(GET_CUSTOMERS, vars), gql(GET_STATS, vars),
        ]).then(([o, i, c, s]) => {
            if (o.status === 'fulfilled') setOrders((o.value as any).ecomOrders || []);
            if (i.status === 'fulfilled') setItems((i.value as any).ecomOrderItems || []);
            if (c.status === 'fulfilled') setCustomers((c.value as any).ecomCustomers || []);
            if (s.status === 'fulfilled') setStats((s.value as any).ecomStats);
        }).finally(() => setLoading(false));
    }, []);

    const glassCard = isDark
        ? { background: 'rgba(255,255,255,0.06)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.10)', borderRadius: 14 }
        : glass;
    const gridStroke = isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0';
    const tickStyle = { fontSize: 10, fill: isDark ? '#aaa' : '#666' };
    const tooltipStyle = { background: isDark ? 'rgba(30,30,30,0.95)' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : '#e5e7eb'}`, borderRadius: 8, fontSize: 12 };

    // Filtered data
    const cur = useMemo(() => filterByPeriod(orders, period), [orders, period]);
    const prev = useMemo(() => filterPrevPeriod(orders, period), [orders, period]);
    const curValid = useMemo(() => cur.filter(o => o.status !== 'cancelled' && o.status !== 'refunded'), [cur]);
    const prevValid = useMemo(() => prev.filter(o => o.status !== 'cancelled' && o.status !== 'refunded'), [prev]);
    const curItemIds = useMemo(() => new Set(cur.map(o => o.id)), [cur]);
    const curItems = useMemo(() => items.filter(i => curItemIds.has(i.orderId)), [items, curItemIds]);

    // KPIs
    const totalRevenue = curValid.reduce((s, o) => s + (o.totalAmount || 0), 0);
    const prevRevenue = prevValid.reduce((s, o) => s + (o.totalAmount || 0), 0);
    const ordersCount = curValid.length;
    const prevOrdersCount = prevValid.length;
    const avgOrder = ordersCount > 0 ? totalRevenue / ordersCount : 0;
    const prevAvg = prevOrdersCount > 0 ? prevRevenue / prevOrdersCount : 0;
    const uniqueCustomers = new Set(cur.map(o => o.customerId)).size;
    const conversionRate = customers.length > 0 ? (uniqueCustomers / customers.length) * 100 : 0;
    const prevUniqueCustomers = new Set(prev.map(o => o.customerId)).size;
    const prevConversion = customers.length > 0 ? (prevUniqueCustomers / customers.length) * 100 : 0;
    const repeatCustomers = useMemo(() => {
        const cMap: Record<string, number> = {};
        cur.forEach(o => { cMap[o.customerId] = (cMap[o.customerId] || 0) + 1; });
        const repeats = Object.values(cMap).filter(c => c > 1).length;
        return uniqueCustomers > 0 ? (repeats / uniqueCustomers) * 100 : 0;
    }, [cur, uniqueCustomers]);
    const prevRepeat = useMemo(() => {
        const cMap: Record<string, number> = {};
        prev.forEach(o => { cMap[o.customerId] = (cMap[o.customerId] || 0) + 1; });
        const repeats = Object.values(cMap).filter(c => c > 1).length;
        return prevUniqueCustomers > 0 ? (repeats / prevUniqueCustomers) * 100 : 0;
    }, [prev, prevUniqueCustomers]);
    const refundRate = cur.length > 0 ? (cur.filter(o => o.status === 'refunded').length / cur.length) * 100 : 0;
    const prevRefundRate = prev.length > 0 ? (prev.filter(o => o.status === 'refunded').length / prev.length) * 100 : 0;

    const trendPct = (curr: number, prv: number) => prv > 0 ? ((curr - prv) / prv) * 100 : curr > 0 ? 100 : 0;
    const kpis = [
        { title: 'Total Revenue', value: fmtShort(totalRevenue), icon: <DollarOutlined />, color: '#10b981', trend: trendPct(totalRevenue, prevRevenue) },
        { title: 'Orders Count', value: ordersCount.toString(), icon: <ShoppingCartOutlined />, color: '#3b82f6', trend: trendPct(ordersCount, prevOrdersCount) },
        { title: 'Avg Order Value', value: fmtShort(avgOrder), icon: <BarChartOutlined />, color: '#8b5cf6', trend: trendPct(avgOrder, prevAvg) },
        { title: 'Conversion Rate', value: `${conversionRate.toFixed(1)}%`, icon: <PercentageOutlined />, color: '#f59e0b', trend: trendPct(conversionRate, prevConversion) },
        { title: 'Repeat Customer', value: `${repeatCustomers.toFixed(1)}%`, icon: <UserOutlined />, color: '#06b6d4', trend: trendPct(repeatCustomers, prevRepeat) },
        { title: 'Refund Rate', value: `${refundRate.toFixed(1)}%`, icon: <UndoOutlined />, color: '#ef4444', trend: trendPct(refundRate, prevRefundRate), invertColor: true },
    ];

    // Revenue trend
    const revenueTrend = useMemo(() => {
        const map: Record<string, { revenue: number; prev: number }> = {};
        const days = PERIOD_DAYS[period];
        const groupBy = days <= 7 ? 'day' : days <= 90 ? 'day' : 'week';
        curValid.forEach(o => {
            const key = groupBy === 'week' ? dayjs(o.createdAt).startOf('week').format('MM/DD') : dayjs(o.createdAt).format('MM/DD');
            if (!map[key]) map[key] = { revenue: 0, prev: 0 };
            map[key].revenue += o.totalAmount || 0;
        });
        if (compare) prevValid.forEach(o => {
            const shifted = dayjs(o.createdAt).add(days, 'day');
            const key = groupBy === 'week' ? shifted.startOf('week').format('MM/DD') : shifted.format('MM/DD');
            if (!map[key]) map[key] = { revenue: 0, prev: 0 };
            map[key].prev += o.totalAmount || 0;
        });
        return Object.entries(map).sort(([a], [b]) => a.localeCompare(b)).map(([date, v]) => ({ date, revenue: v.revenue, prev: v.prev }));
    }, [curValid, prevValid, period, compare]);

    // Category treemap
    const categoryData = useMemo(() => {
        const map: Record<string, number> = {};
        curItems.forEach(i => { const cat = i.category || 'Uncategorized'; map[cat] = (map[cat] || 0) + (i.totalPrice || 0); });
        return Object.entries(map).map(([name, value], i) => ({ name, size: value, fill: COLORS[i % COLORS.length] })).sort((a, b) => b.size - a.size);
    }, [curItems]);

    // Order funnel
    const FUNNEL_STAGES = ['pending', 'confirmed', 'processing', 'shipped', 'delivered', 'completed'];
    const funnelData = useMemo(() => {
        const counts = FUNNEL_STAGES.map(s => cur.filter(o => o.status === s).length);
        const cumulative: number[] = [];
        FUNNEL_STAGES.forEach((_, i) => { cumulative.push(counts.slice(i).reduce((a, b) => a + b, 0) + (i > 0 ? counts.slice(0, i).reduce((a, b) => a + b, 0) - cumulative[0] + counts[0] : 0)); });
        const stageTotals = FUNNEL_STAGES.map((s, i) => {
            const ordered = cur.filter(o => FUNNEL_STAGES.indexOf(o.status) >= i).length;
            return ordered;
        });
        const max = Math.max(...stageTotals, 1);
        return FUNNEL_STAGES.map((s, i) => ({
            stage: s.charAt(0).toUpperCase() + s.slice(1), count: stageTotals[i],
            width: Math.max(25, Math.round((stageTotals[i] / max) * 100)),
            dropoff: i > 0 && stageTotals[i - 1] > 0 ? Math.round((1 - stageTotals[i] / stageTotals[i - 1]) * 100) : 0,
            color: FUNNEL_COLORS[i],
        }));
    }, [cur]);

    // Hourly heatmap
    const heatmapData = useMemo(() => {
        const grid: number[][] = Array.from({ length: 7 }, () => Array(24).fill(0));
        cur.forEach(o => { if (o.createdAt) { const d = dayjs(o.createdAt); grid[d.day()][d.hour()]++; } });
        const max = Math.max(...grid.flat(), 1);
        return { grid, max };
    }, [cur]);

    // Top products
    const topProducts = useMemo(() => {
        const map: Record<string, { name: string; sku: string; units: number; revenue: number }> = {};
        curItems.forEach(i => {
            const key = i.itemId || i.itemName;
            if (!map[key]) map[key] = { name: i.itemName, sku: i.sku || '-', units: 0, revenue: 0 };
            map[key].units += i.quantity || 0;
            map[key].revenue += i.totalPrice || 0;
        });
        return Object.values(map).sort((a, b) => b.revenue - a.revenue).slice(0, 10);
    }, [curItems]);
    const topMaxRevenue = topProducts.length > 0 ? topProducts[0].revenue : 1;

    // Payment methods
    const paymentData = useMemo(() => {
        const map: Record<string, number> = {};
        curValid.forEach(o => { const m = o.paymentMethod || 'Unknown'; map[m] = (map[m] || 0) + (o.totalAmount || 0); });
        return Object.entries(map).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
    }, [curValid]);

    // Fulfillment types
    const fulfillmentData = useMemo(() => {
        const map: Record<string, number> = {};
        curValid.forEach(o => { const t = o.fulfillmentType || 'Physical'; map[t] = (map[t] || 0) + 1; });
        return Object.entries(map).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
    }, [curValid]);

    // Monthly revenue comparison
    const monthlyComparison = useMemo(() => {
        const thisYear = dayjs().year();
        const map: Record<string, { current: number; previous: number }> = {};
        orders.filter(o => o.status !== 'cancelled' && o.status !== 'refunded').forEach(o => {
            const d = dayjs(o.createdAt);
            const month = d.format('MMM');
            if (!map[month]) map[month] = { current: 0, previous: 0 };
            if (d.year() === thisYear) map[month].current += o.totalAmount || 0;
            else if (d.year() === thisYear - 1) map[month].previous += o.totalAmount || 0;
        });
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        return months.map(m => ({ month: m, current: map[m]?.current || 0, previous: map[m]?.previous || 0 }));
    }, [orders]);
    const monthlyAvg = monthlyComparison.reduce((s, m) => s + m.current, 0) / 12;

    if (loading) return (
        <CMSLayout title="Sales Analytics" subTitle="Loading...">
            <div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div>
        </CMSLayout>
    );

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#f59e0b', '#10b981', themeColor]} className="text-[22px] font-bold tracking-tight">Sales Analytics</AuroraText>}
            subTitle={<DecryptedText text="Deep commerce analytics — revenue, products & customer insights" animateOn="view" revealDirection="start" speed={60} sequential />}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* Period Selector */}
            <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap' }}>
                <Segmented
                    options={[
                        { label: 'Today', value: 'today' }, { label: '7 Days', value: '7d' },
                        { label: '30 Days', value: '30d' }, { label: '90 Days', value: '90d' },
                        { label: 'This Year', value: 'year' },
                    ]}
                    value={period} onChange={v => setPeriod(v as Period)}
                />
                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <Switch size="small" checked={compare} onChange={setCompare} />
                    <Text type="secondary" style={{ fontSize: 11 }}>Compare previous period</Text>
                </div>
            </motion.div>

            {/* KPI Cards */}
            <Row gutter={[12, 12]}>
                {kpis.map((k, i) => (
                    <Col key={i} xs={12} md={4}>
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                            <Card size="small" style={{ ...glassCard, borderTop: `3px solid ${k.color}` }} styles={{ body: { padding: '14px 16px' } }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                    <div>
                                        <Text type="secondary" style={{ fontSize: 11 }}>{k.title}</Text>
                                        <div style={{ fontSize: 22, fontWeight: 700, color: k.color, fontFamily: 'monospace', lineHeight: 1.3 }}>{k.value}</div>
                                    </div>
                                    <div style={{ width: 32, height: 32, borderRadius: 10, background: `${k.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: k.color, fontSize: 16 }}>{k.icon}</div>
                                </div>
                                {compare && (
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginTop: 2 }}>
                                        {(k.invertColor ? k.trend <= 0 : k.trend >= 0)
                                            ? <RiseOutlined style={{ fontSize: 10, color: k.invertColor ? '#10b981' : '#10b981' }} />
                                            : <FallOutlined style={{ fontSize: 10, color: k.invertColor ? '#ef4444' : '#ef4444' }} />}
                                        <Text style={{ fontSize: 10, color: (k.invertColor ? k.trend <= 0 : k.trend >= 0) ? '#10b981' : '#ef4444' }}>
                                            {Math.abs(k.trend).toFixed(1)}% vs prev
                                        </Text>
                                    </div>
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Quick Insights Bar */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.25 }}>
                <Card size="small" style={{ ...glassCard, borderLeft: `3px solid ${themeColor}` }} styles={{ body: { padding: '10px 16px' } }}>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 20, alignItems: 'center' }}>
                        {[
                            { label: 'Gross Revenue', value: fmtShort(curValid.reduce((s, o) => s + (o.subtotal || 0), 0)), color: '#10b981' },
                            { label: 'Total Tax', value: fmtShort(curValid.reduce((s, o) => s + (o.tax || 0), 0)), color: '#f59e0b' },
                            { label: 'Shipping Collected', value: fmtShort(curValid.reduce((s, o) => s + (o.shippingCost || 0), 0)), color: '#3b82f6' },
                            { label: 'Discounts Given', value: fmtShort(curValid.reduce((s, o) => s + (o.discount || 0), 0)), color: '#ef4444' },
                            { label: 'Unique Customers', value: uniqueCustomers.toString(), color: '#8b5cf6' },
                            { label: 'Avg Items/Order', value: ordersCount > 0 ? (curItems.length / ordersCount).toFixed(1) : '0', color: '#06b6d4' },
                        ].map((m, i) => (
                            <React.Fragment key={m.label}>
                                {i > 0 && <div style={{ width: 1, height: 28, background: isDark ? 'rgba(255,255,255,0.08)' : '#e5e7eb' }} />}
                                <div>
                                    <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>{m.label}</Text>
                                    <Text strong style={{ fontSize: 14, fontFamily: 'monospace', color: m.color }}>{m.value}</Text>
                                </div>
                            </React.Fragment>
                        ))}
                    </div>
                </Card>
            </motion.div>

            {/* Revenue Trend + Category Treemap */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                        <Card size="small" style={glassCard} title={<><RiseOutlined style={{ color: '#10b981' }} /> <Text strong style={{ fontSize: 13 }}>Revenue Trend</Text></>}>
                            <div style={{ height: 280 }}>
                                {revenueTrend.length > 0 ? (
                                    <ResponsiveContainer>
                                        <AreaChart data={revenueTrend}>
                                            <defs>
                                                <linearGradient id="salesRevGrad" x1="0" y1="0" x2="0" y2="1">
                                                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                                                    <stop offset="95%" stopColor="#10b981" stopOpacity={0.02} />
                                                </linearGradient>
                                            </defs>
                                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                            <XAxis dataKey="date" tick={tickStyle} />
                                            <YAxis tickFormatter={v => fmtShort(v)} tick={tickStyle} />
                                            <RTooltip formatter={(v: number) => fmt(v)} contentStyle={tooltipStyle} />
                                            <Area type="monotone" dataKey="revenue" stroke="#10b981" fill="url(#salesRevGrad)" strokeWidth={2} name="Revenue" />
                                            {compare && <Area type="monotone" dataKey="prev" stroke="#8b5cf6" fill="none" strokeWidth={1.5} strokeDasharray="6 3" name="Previous Period" />}
                                        </AreaChart>
                                    </ResponsiveContainer>
                                ) : <Empty description="No revenue data for this period" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.35 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><PieChartOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Sales by Category</Text></>}>
                            <div style={{ height: 280 }}>
                                {categoryData.length > 0 ? (
                                    <ResponsiveContainer>
                                        <Treemap data={categoryData} dataKey="size" nameKey="name" aspectRatio={4 / 3}>
                                            {categoryData.map((entry, i) => (
                                                <Cell key={i} fill={entry.fill} />
                                            ))}
                                            <RTooltip formatter={(v: number) => fmt(v)} contentStyle={tooltipStyle} />
                                        </Treemap>
                                    </ResponsiveContainer>
                                ) : <Empty description="No category data" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Order Status Funnel */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                <Card size="small" style={glassCard} title={<><BarChartOutlined style={{ color: '#3b82f6' }} /> <Text strong style={{ fontSize: 13 }}>Order Status Funnel</Text></>}>
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, padding: '8px 0' }}>
                        {funnelData.map((f, i) => (
                            <React.Fragment key={f.stage}>
                                <motion.div initial={{ scaleX: 0 }} animate={{ scaleX: 1 }} transition={{ delay: 0.45 + i * 0.07 }}
                                    style={{ width: `${f.width}%`, minWidth: 140, padding: '10px 16px', borderRadius: 8, background: `${f.color}18`, border: `1px solid ${f.color}30`, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Text style={{ fontSize: 12, fontWeight: 600 }}>{f.stage}</Text>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                        <Text style={{ fontSize: 16, fontWeight: 700, color: f.color }}>{f.count}</Text>
                                        {f.dropoff > 0 && <Tag style={{ fontSize: 9, margin: 0, borderRadius: 8 }} color={f.dropoff > 30 ? 'red' : f.dropoff > 15 ? 'orange' : 'green'}>-{f.dropoff}%</Tag>}
                                    </div>
                                </motion.div>
                                {i < funnelData.length - 1 && <ArrowRightOutlined style={{ color: '#d1d5db', fontSize: 10, transform: 'rotate(90deg)' }} />}
                            </React.Fragment>
                        ))}
                    </div>
                </Card>
            </motion.div>

            {/* Hourly Heatmap + Top Products */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><HeatMapOutlined style={{ color: '#f59e0b' }} /> <Text strong style={{ fontSize: 13 }}>Hourly Sales Heatmap</Text></>}>
                            <div style={{ overflowX: 'auto' }}>
                                <div style={{ display: 'grid', gridTemplateColumns: '36px repeat(24, 1fr)', gap: 2, minWidth: 500 }}>
                                    <div />
                                    {Array.from({ length: 24 }, (_, h) => (
                                        <Text key={h} type="secondary" style={{ fontSize: 8, textAlign: 'center' }}>{h}</Text>
                                    ))}
                                    {heatmapData.grid.map((row, d) => (
                                        <React.Fragment key={d}>
                                            <Text type="secondary" style={{ fontSize: 9, lineHeight: '20px' }}>{DAYS[d]}</Text>
                                            {row.map((val, h) => {
                                                const intensity = heatmapData.max > 0 ? val / heatmapData.max : 0;
                                                return (
                                                    <Tooltip key={h} title={`${DAYS[d]} ${h}:00 — ${val} orders`}>
                                                        <div style={{
                                                            height: 20, borderRadius: 3, cursor: 'default',
                                                            background: val === 0
                                                                ? (isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.03)')
                                                                : `rgba(245, 158, 11, ${0.15 + intensity * 0.75})`,
                                                            border: `1px solid ${val === 0 ? 'transparent' : `rgba(245, 158, 11, ${0.1 + intensity * 0.3})`}`,
                                                        }} />
                                                    </Tooltip>
                                                );
                                            })}
                                        </React.Fragment>
                                    ))}
                                </div>
                            </div>
                            <div style={{ display: 'flex', justifyContent: 'center', gap: 4, marginTop: 8, alignItems: 'center' }}>
                                <Text type="secondary" style={{ fontSize: 9 }}>Low</Text>
                                {[0.15, 0.35, 0.55, 0.75, 0.9].map((o, i) => (
                                    <div key={i} style={{ width: 16, height: 10, borderRadius: 2, background: `rgba(245, 158, 11, ${o})` }} />
                                ))}
                                <Text type="secondary" style={{ fontSize: 9 }}>High</Text>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.55 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><TrophyOutlined style={{ color: '#10b981' }} /> <Text strong style={{ fontSize: 13 }}>Top Products by Revenue</Text></>}>
                            <Table dataSource={topProducts} pagination={false} size="small" rowKey="name"
                                columns={[
                                    { title: '#', key: 'rank', width: 30, render: (_: any, __: any, i: number) => <Text type="secondary" style={{ fontSize: 11 }}>{i + 1}</Text> },
                                    { title: 'Product', dataIndex: 'name', key: 'name', ellipsis: true, render: (v: string) => <Text strong style={{ fontSize: 12 }}>{v}</Text> },
                                    { title: 'SKU', dataIndex: 'sku', key: 'sku', width: 80, render: (v: string) => <Text type="secondary" style={{ fontSize: 10 }}>{v}</Text> },
                                    { title: 'Units', dataIndex: 'units', key: 'units', width: 55, align: 'right' as const, render: (v: number) => <Tag style={{ borderRadius: 8, margin: 0, fontSize: 10 }} color="blue">{v}</Tag> },
                                    {
                                        title: 'Avg Price', key: 'avg', width: 85, align: 'right' as const,
                                        render: (_: any, r: any) => (
                                            <Text type="secondary" style={{ fontSize: 11, fontFamily: 'monospace' }}>
                                                {r.units > 0 ? fmtShort(r.revenue / r.units) : '-'}
                                            </Text>
                                        ),
                                    },
                                    {
                                        title: 'Revenue', dataIndex: 'revenue', key: 'revenue', width: 140, align: 'right' as const,
                                        render: (v: number) => (
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 6, justifyContent: 'flex-end' }}>
                                                <div style={{ flex: 1, maxWidth: 50, height: 6, borderRadius: 3, background: isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0' }}>
                                                    <div style={{ width: `${(v / topMaxRevenue) * 100}%`, height: '100%', borderRadius: 3, background: '#10b981' }} />
                                                </div>
                                                <Text strong style={{ fontSize: 11, fontFamily: 'monospace', color: '#10b981' }}>{fmtShort(v)}</Text>
                                            </div>
                                        ),
                                    },
                                ]}
                            />
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Payment Donut + Fulfillment Bar */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.6 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><PieChartOutlined style={{ color: '#06b6d4' }} /> <Text strong style={{ fontSize: 13 }}>Payment Method Breakdown</Text></>}>
                            <div style={{ height: 280, position: 'relative' }}>
                                <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', textAlign: 'center', zIndex: 1, pointerEvents: 'none' }}>
                                    <div style={{ fontSize: 18, fontWeight: 800, color: themeColor }}>{fmtShort(totalRevenue)}</div>
                                    <Text type="secondary" style={{ fontSize: 10 }}>Total Revenue</Text>
                                </div>
                                {paymentData.length > 0 ? (
                                    <ResponsiveContainer>
                                        <PieChart>
                                            <Pie data={paymentData} cx="50%" cy="50%" innerRadius={55} outerRadius={90} paddingAngle={3} dataKey="value"
                                                label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                                                labelLine={{ stroke: isDark ? '#666' : '#999', strokeWidth: 1 }}>
                                                {paymentData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                                            </Pie>
                                            <RTooltip formatter={(v: number) => fmt(v)} contentStyle={tooltipStyle} />
                                        </PieChart>
                                    </ResponsiveContainer>
                                ) : <Empty description="No payment data" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.65 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><BarChartOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Fulfillment Type Distribution</Text></>}>
                            <div style={{ height: 280 }}>
                                {fulfillmentData.length > 0 ? (
                                    <ResponsiveContainer>
                                        <BarChart data={fulfillmentData} layout="vertical">
                                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                            <XAxis type="number" tick={tickStyle} />
                                            <YAxis dataKey="name" type="category" tick={tickStyle} width={80} />
                                            <RTooltip contentStyle={tooltipStyle} />
                                            <Bar dataKey="value" name="Orders" radius={[0, 6, 6, 0]} barSize={24}>
                                                {fulfillmentData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                                            </Bar>
                                        </BarChart>
                                    </ResponsiveContainer>
                                ) : <Empty description="No fulfillment data" />}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Monthly Revenue Comparison */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.7 }}>
                <Card size="small" style={glassCard} title={<><CalendarOutlined style={{ color: themeColor }} /> <Text strong style={{ fontSize: 13 }}>Monthly Revenue Comparison (Current vs Previous Year)</Text></>}>
                    <div style={{ height: 300 }}>
                        <ResponsiveContainer>
                            <BarChart data={monthlyComparison}>
                                <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                <XAxis dataKey="month" tick={tickStyle} />
                                <YAxis tickFormatter={v => fmtShort(v)} tick={tickStyle} />
                                <RTooltip formatter={(v: number) => fmt(v)} contentStyle={tooltipStyle} />
                                <Legend wrapperStyle={{ fontSize: 11 }} />
                                <ReferenceLine y={monthlyAvg} stroke="#f59e0b" strokeDasharray="6 3" label={{ value: `Avg: ${fmtShort(monthlyAvg)}`, position: 'insideTopRight', fill: '#f59e0b', fontSize: 10 }} />
                                <Bar dataKey="current" name="This Year" fill="#10b981" radius={[4, 4, 0, 0]} barSize={20} />
                                <Bar dataKey="previous" name="Last Year" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={20} opacity={0.6} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </Card>
            </motion.div>
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { Card, Row, Col, Typography, Spin, Table, Tag, Drawer, Timeline, Badge, Tooltip, message, theme } from "antd";
import {
    TeamOutlined, UserAddOutlined, SyncOutlined, DollarOutlined,
    ShoppingCartOutlined, MailOutlined, PlusOutlined, EnvironmentOutlined,
    CrownOutlined, ClockCircleOutlined,
} from "@ant-design/icons";
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip,
    ResponsiveContainer, PieChart, Pie, Cell, AreaChart, Area, Line, ComposedChart,
} from "recharts";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const COLORS = ['#10b981', '#3b82f6', '#8b5cf6', '#f59e0b', '#ef4444', '#ec4899', '#06b6d4', '#84cc16'];
const fmtCurrency = (v: number) => v ? `$${v.toLocaleString()}` : '$0';

interface Customer {
    id: string; name: string; email: string; phone: string; customerType: string;
    totalOrders: number; totalSpent: number; loyaltyTier: string; tags: string[];
    address: string; city: string; createdAt: string; lastOrderDate: string;
}
interface Order {
    id: string; customerId: string; totalAmount: number; status: string;
    createdAt: string; completedAt: string;
}

const GET_CUSTOMERS = `query($tenantId: String!) {
    ecomCustomers(tenantId: $tenantId) {
        id name email phone customerType totalOrders totalSpent
        loyaltyTier tags address city createdAt lastOrderDate
    }
}`;
const GET_ORDERS = `query($tenantId: String!) {
    ecomOrders(tenantId: $tenantId) {
        id customerId totalAmount status createdAt completedAt
    }
}`;

// ── RFM helpers ──
function rfmScore(value: number, thresholds: number[]): number {
    if (value >= thresholds[3]) return 5;
    if (value >= thresholds[2]) return 4;
    if (value >= thresholds[1]) return 3;
    if (value >= thresholds[0]) return 2;
    return 1;
}

function getSegmentLabel(r: number, f: number, m: number): { label: string; color: string } {
    if (r >= 4 && f >= 4 && m >= 4) return { label: 'Champions', color: '#10b981' };
    if (f >= 4) return { label: 'Loyal', color: '#3b82f6' };
    if (r >= 4 && f <= 2) return { label: 'New', color: '#06b6d4' };
    if (r >= 3 && f >= 3) return { label: 'Potential', color: '#8b5cf6' };
    if (r <= 2 && f >= 3) return { label: 'At Risk', color: '#f59e0b' };
    if (r <= 2 && f <= 2) return { label: 'Lost', color: '#ef4444' };
    return { label: 'Others', color: '#94a3b8' };
}

const SEGMENT_ORDER = ['Champions', 'Loyal', 'Potential', 'New', 'At Risk', 'Lost', 'Others'];
const TIER_COLORS: Record<string, string> = { gold: '#f59e0b', silver: '#94a3b8', bronze: '#cd7f32', platinum: '#8b5cf6', vip: '#ef4444' };

export default function CustomerInsightsPage() {
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedSegment, setSelectedSegment] = useState<string | null>(null);
    const [drawerCustomer, setDrawerCustomer] = useState<Customer | null>(null);
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');

    useEffect(() => {
        (async () => {
            try {
                const [cData, oData] = await Promise.all([
                    gql(GET_CUSTOMERS, { tenantId: DEFAULT_TENANT_ID }),
                    gql(GET_ORDERS, { tenantId: DEFAULT_TENANT_ID }),
                ]);
                setCustomers(cData.ecomCustomers || []);
                setOrders(oData.ecomOrders || []);
            } catch (err: any) { message.error("Failed to load data: " + err.message); }
            finally { setLoading(false); }
        })();
    }, []);

    const glassCard = isDark
        ? { background: 'rgba(255,255,255,0.06)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.10)', borderRadius: 14 }
        : glass;
    const gridStroke = isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0';
    const tickStyle = { fontSize: 10, fill: isDark ? '#aaa' : '#666' };
    const tooltipStyle = { background: isDark ? 'rgba(30,30,30,0.95)' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : '#e5e7eb'}`, borderRadius: 8, fontSize: 12 };

    // ── KPI Calculations ──
    const now = dayjs();
    const thisMonth = customers.filter(c => dayjs(c.createdAt).isSame(now, 'month'));
    const returning = customers.filter(c => (c.totalOrders || 0) > 1);
    const returningRate = customers.length > 0 ? Math.round((returning.length / customers.length) * 100) : 0;
    const totalSpentAll = customers.reduce((s, c) => s + (c.totalSpent || 0), 0);
    const avgLTV = customers.length > 0 ? Math.round(totalSpentAll / customers.length) : 0;
    const totalOrdersAll = customers.reduce((s, c) => s + (c.totalOrders || 0), 0);
    const avgOrders = customers.length > 0 ? (totalOrdersAll / customers.length).toFixed(1) : '0';

    const kpis = [
        { title: 'Total Customers', value: customers.length.toLocaleString(), icon: <TeamOutlined />, color: themeColor },
        { title: 'New This Month', value: thisMonth.length.toLocaleString(), icon: <UserAddOutlined />, color: '#3b82f6' },
        { title: 'Returning Rate', value: `${returningRate}%`, icon: <SyncOutlined />, color: '#8b5cf6' },
        { title: 'Avg Lifetime Value', value: fmtCurrency(avgLTV), icon: <DollarOutlined />, color: '#10b981' },
        { title: 'Avg Orders/Customer', value: avgOrders, icon: <ShoppingCartOutlined />, color: '#f59e0b' },
    ];

    // ── RFM Analysis ──
    const rfmData = useMemo(() => {
        if (customers.length === 0) return { segments: {}, customerRFM: new Map() };
        const recencies = customers.map(c => c.lastOrderDate ? dayjs().diff(dayjs(c.lastOrderDate), 'day') : 999);
        const frequencies = customers.map(c => c.totalOrders || 0);
        const monetaries = customers.map(c => c.totalSpent || 0);
        const sortedR = [...recencies].sort((a, b) => a - b);
        const sortedF = [...frequencies].sort((a, b) => a - b);
        const sortedM = [...monetaries].sort((a, b) => a - b);
        const pct = (arr: number[], p: number) => arr[Math.floor(arr.length * p)] || 0;
        const rThresh = [pct(sortedR, 0.8), pct(sortedR, 0.6), pct(sortedR, 0.4), pct(sortedR, 0.2)]; // inverted: low days = high score
        const fThresh = [pct(sortedF, 0.2), pct(sortedF, 0.4), pct(sortedF, 0.6), pct(sortedF, 0.8)];
        const mThresh = [pct(sortedM, 0.2), pct(sortedM, 0.4), pct(sortedM, 0.6), pct(sortedM, 0.8)];

        const segments: Record<string, Customer[]> = {};
        const customerRFM = new Map<string, { r: number; f: number; m: number; label: string; color: string }>();
        customers.forEach((c, i) => {
            const rVal = 6 - rfmScore(recencies[i], rThresh); // invert: fewer days = higher score
            const fVal = rfmScore(frequencies[i], fThresh);
            const mVal = rfmScore(monetaries[i], mThresh);
            const seg = getSegmentLabel(rVal, fVal, mVal);
            if (!segments[seg.label]) segments[seg.label] = [];
            segments[seg.label].push(c);
            customerRFM.set(c.id, { r: rVal, f: fVal, m: mVal, ...seg });
        });
        return { segments, customerRFM };
    }, [customers]);

    // ── CLV Distribution ──
    const clvBuckets = useMemo(() => {
        const buckets = [
            { label: '$0', min: 0, max: 0.01, count: 0, color: '#94a3b8' },
            { label: '<$100', min: 0.01, max: 100, count: 0, color: '#3b82f6' },
            { label: '$100-500', min: 100, max: 500, count: 0, color: '#8b5cf6' },
            { label: '$500-2K', min: 500, max: 2000, count: 0, color: '#f59e0b' },
            { label: '$2K-10K', min: 2000, max: 10000, count: 0, color: '#10b981' },
            { label: '$10K+', min: 10000, max: Infinity, count: 0, color: '#ef4444' },
        ];
        customers.forEach(c => {
            const v = c.totalSpent || 0;
            const b = buckets.find(b => v >= b.min && v < b.max);
            if (b) b.count++;
        });
        return buckets;
    }, [customers]);

    // ── Growth Trend (12 months) ──
    const growthData = useMemo(() => {
        const map: Record<string, number> = {};
        const months: string[] = [];
        for (let i = 11; i >= 0; i--) {
            const m = dayjs().subtract(i, 'month').format('YYYY-MM');
            months.push(m);
            map[m] = 0;
        }
        customers.forEach(c => {
            const m = dayjs(c.createdAt).format('YYYY-MM');
            if (map[m] !== undefined) map[m]++;
        });
        let cum = customers.filter(c => dayjs(c.createdAt).isBefore(dayjs().subtract(12, 'month'))).length;
        return months.map(m => {
            cum += map[m];
            return { month: dayjs(m + '-01').format('MMM YY'), newCustomers: map[m], cumulative: cum };
        });
    }, [customers]);

    // ── Segmentation Donut ──
    const segmentDonut = useMemo(() => {
        const map: Record<string, number> = {};
        customers.forEach(c => { const t = c.customerType || 'Unknown'; map[t] = (map[t] || 0) + 1; });
        return Object.entries(map).map(([name, value]) => ({ name: name.charAt(0).toUpperCase() + name.slice(1), value }));
    }, [customers]);

    // ── Top Customers ──
    const topCustomers = useMemo(() =>
        [...customers].sort((a, b) => (b.totalSpent || 0) - (a.totalSpent || 0)).slice(0, 20), [customers]);

    // ── Cohort Retention ──
    const cohortData = useMemo(() => {
        if (customers.length === 0 || orders.length === 0) return [];
        const cohorts: { month: string; m0: number; retention: number[] }[] = [];
        for (let i = 5; i >= 0; i--) {
            const cohortMonth = dayjs().subtract(i, 'month').format('YYYY-MM');
            const cohortCustomers = customers.filter(c => dayjs(c.createdAt).format('YYYY-MM') === cohortMonth);
            if (cohortCustomers.length === 0) { cohorts.push({ month: dayjs(cohortMonth + '-01').format('MMM YY'), m0: 0, retention: [] }); continue; }
            const ids = new Set(cohortCustomers.map(c => c.id));
            const retention: number[] = [];
            for (let j = 1; j <= Math.min(6, i); j++) {
                const targetMonth = dayjs(cohortMonth + '-01').add(j, 'month').format('YYYY-MM');
                const active = orders.filter(o => ids.has(o.customerId) && dayjs(o.createdAt).format('YYYY-MM') === targetMonth);
                const uniqueActive = new Set(active.map(o => o.customerId)).size;
                retention.push(Math.round((uniqueActive / cohortCustomers.length) * 100));
            }
            cohorts.push({ month: dayjs(cohortMonth + '-01').format('MMM YY'), m0: cohortCustomers.length, retention });
        }
        return cohorts;
    }, [customers, orders]);

    // ── Geographic Distribution ──
    const geoData = useMemo(() => {
        const map: Record<string, number> = {};
        customers.forEach(c => { if (c.city) map[c.city] = (map[c.city] || 0) + 1; });
        return Object.entries(map).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([city, count]) => ({ city, count }));
    }, [customers]);

    // ── Drawer: customer orders ──
    const drawerOrders = useMemo(() =>
        drawerCustomer ? orders.filter(o => o.customerId === drawerCustomer.id).sort((a, b) => dayjs(b.createdAt).unix() - dayjs(a.createdAt).unix()) : [],
    [drawerCustomer, orders]);

    const drawerRFM = drawerCustomer ? rfmData.customerRFM.get(drawerCustomer.id) : null;

    if (loading) return <CMSLayout title="Customer Insights"><div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div></CMSLayout>;

    const segs = rfmData.segments as Record<string, Customer[]>;
    const segmentGrid = SEGMENT_ORDER.filter(s => segs[s]?.length);
    const filteredBySegment = selectedSegment && segs[selectedSegment] ? segs[selectedSegment] : null;

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Customer Insights</AuroraText>}
            subTitle={<DecryptedText text="Customer segmentation, lifetime value & retention analysis" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* KPI Cards */}
            <Row gutter={[12, 12]}>
                {kpis.map((k, i) => (
                    <Col key={i} xs={12} sm={8} md={4} lg={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                            <Card size="small" style={{ ...glassCard, borderTop: `3px solid ${k.color}` }} styles={{ body: { padding: '14px 16px' } }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                    <div>
                                        <Text type="secondary" style={{ fontSize: 11 }}>{k.title}</Text>
                                        <div style={{ fontSize: 22, fontWeight: 700, color: k.color, fontFamily: 'monospace', lineHeight: 1.3 }}>{k.value}</div>
                                    </div>
                                    <div style={{ width: 32, height: 32, borderRadius: 10, background: `${k.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: k.color, fontSize: 16 }}>{k.icon}</div>
                                </div>
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* RFM Analysis Grid */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                <Card size="small" style={glassCard} title={<><CrownOutlined style={{ color: themeColor }} /> <Text strong style={{ fontSize: 13 }}>RFM Segmentation</Text></>}>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 10 }}>
                        {segmentGrid.map(seg => {
                            const custs = segs[seg];
                            const segColor = getSegmentLabel(0, 0, 0).color;
                            const color = seg === 'Champions' ? '#10b981' : seg === 'Loyal' ? '#3b82f6' : seg === 'New' ? '#06b6d4' : seg === 'Potential' ? '#8b5cf6' : seg === 'At Risk' ? '#f59e0b' : seg === 'Lost' ? '#ef4444' : '#94a3b8';
                            const isActive = selectedSegment === seg;
                            return (
                                <motion.div key={seg} whileHover={{ scale: 1.03 }} whileTap={{ scale: 0.97 }}
                                    onClick={() => setSelectedSegment(isActive ? null : seg)}
                                    style={{ padding: '14px 16px', borderRadius: 12, cursor: 'pointer', background: isActive ? `${color}20` : `${color}08`, border: `2px solid ${isActive ? color : `${color}25`}`, transition: 'all 0.2s' }}>
                                    <Text style={{ fontSize: 11, color, fontWeight: 600, display: 'block' }}>{seg}</Text>
                                    <div style={{ fontSize: 26, fontWeight: 800, color, lineHeight: 1.3 }}>{custs.length}</div>
                                    <Text type="secondary" style={{ fontSize: 10 }}>{customers.length > 0 ? Math.round((custs.length / customers.length) * 100) : 0}% of total</Text>
                                </motion.div>
                            );
                        })}
                    </div>
                    {filteredBySegment && (
                        <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} style={{ marginTop: 12 }}>
                            <Table dataSource={filteredBySegment.slice(0, 10)} rowKey="id" size="small" pagination={false}
                                columns={[
                                    { title: 'Name', dataIndex: 'name', render: (v: string, r: Customer) => <Text strong className="cursor-pointer" onClick={() => setDrawerCustomer(r)}>{v}</Text> },
                                    { title: 'Orders', dataIndex: 'totalOrders', width: 70 },
                                    { title: 'Total Spent', dataIndex: 'totalSpent', width: 120, render: (v: number) => <Text style={{ color: themeColor, fontFamily: 'monospace' }}>{fmtCurrency(v)}</Text> },
                                    { title: 'Last Order', dataIndex: 'lastOrderDate', width: 100, render: (v: string) => v ? dayjs(v).format('MMM DD') : '—' },
                                ]} />
                        </motion.div>
                    )}
                </Card>
            </motion.div>

            {/* CLV Distribution + Growth Trend */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={12}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.35 }}>
                        <Card size="small" style={glassCard} title={<><DollarOutlined style={{ color: '#10b981' }} /> <Text strong style={{ fontSize: 13 }}>Customer Lifetime Value Distribution</Text></>}>
                            <div style={{ height: 260 }}>
                                <ResponsiveContainer>
                                    <BarChart data={clvBuckets}>
                                        <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                        <XAxis dataKey="label" tick={tickStyle} />
                                        <YAxis tick={tickStyle} />
                                        <RTooltip contentStyle={tooltipStyle} />
                                        <Bar dataKey="count" name="Customers" radius={[6, 6, 0, 0]} barSize={36}>
                                            {clvBuckets.map((b, i) => <Cell key={i} fill={b.color} />)}
                                        </Bar>
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={12}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><UserAddOutlined style={{ color: '#3b82f6' }} /> <Text strong style={{ fontSize: 13 }}>Customer Growth Trend</Text></>}>
                            <div style={{ height: 260 }}>
                                <ResponsiveContainer>
                                    <ComposedChart data={growthData}>
                                        <defs>
                                            <linearGradient id="growGrad" x1="0" y1="0" x2="0" y2="1">
                                                <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
                                                <stop offset="95%" stopColor="#3b82f6" stopOpacity={0.02} />
                                            </linearGradient>
                                        </defs>
                                        <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                        <XAxis dataKey="month" tick={tickStyle} />
                                        <YAxis yAxisId="left" tick={tickStyle} />
                                        <YAxis yAxisId="right" orientation="right" tick={tickStyle} />
                                        <RTooltip contentStyle={tooltipStyle} />
                                        <Area yAxisId="left" type="monotone" dataKey="newCustomers" stroke="#3b82f6" fill="url(#growGrad)" strokeWidth={2} name="New Customers" />
                                        <Line yAxisId="right" type="monotone" dataKey="cumulative" stroke="#10b981" strokeWidth={2} dot={{ r: 3 }} name="Cumulative" />
                                    </ComposedChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Segmentation Donut + Geographic */}
            <Row gutter={[16, 16]}>
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.45 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><TeamOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Customer Segmentation</Text></>}>
                            <div style={{ height: 280, position: 'relative' }}>
                                <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', textAlign: 'center', zIndex: 1, pointerEvents: 'none' }}>
                                    <div style={{ fontSize: 28, fontWeight: 800, color: themeColor }}>{customers.length}</div>
                                    <Text type="secondary" style={{ fontSize: 10 }}>Total</Text>
                                </div>
                                <ResponsiveContainer>
                                    <PieChart>
                                        <Pie data={segmentDonut} cx="50%" cy="50%" innerRadius={60} outerRadius={95}
                                            paddingAngle={3} dataKey="value"
                                            label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                                            labelLine={{ stroke: '#999', strokeWidth: 1 }}>
                                            {segmentDonut.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                                        </Pie>
                                        <RTooltip contentStyle={tooltipStyle} />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}>
                        <Card size="small" style={{ ...glassCard, height: '100%' }} title={<><EnvironmentOutlined style={{ color: '#06b6d4' }} /> <Text strong style={{ fontSize: 13 }}>Geographic Distribution</Text></>}>
                            <div style={{ height: 280 }}>
                                {geoData.length > 0 ? (
                                    <ResponsiveContainer>
                                        <BarChart data={geoData} layout="vertical" margin={{ left: 10 }}>
                                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                            <XAxis type="number" tick={tickStyle} />
                                            <YAxis dataKey="city" type="category" tick={tickStyle} width={90} />
                                            <RTooltip contentStyle={tooltipStyle} />
                                            <Bar dataKey="count" name="Customers" radius={[0, 6, 6, 0]} barSize={18}>
                                                {geoData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                                            </Bar>
                                        </BarChart>
                                    </ResponsiveContainer>
                                ) : <div style={{ textAlign: 'center', padding: 60 }}><Text type="secondary">No city data available</Text></div>}
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Top Customers Table */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.55 }}>
                <Card size="small" style={glassCard} title={<><CrownOutlined style={{ color: '#f59e0b' }} /> <Text strong style={{ fontSize: 13 }}>Top 20 Customers by Lifetime Value</Text></>}>
                    <Table dataSource={topCustomers} rowKey="id" size="small" pagination={false} scroll={{ x: 900 }}
                        onRow={(r) => ({ onClick: () => setDrawerCustomer(r), style: { cursor: 'pointer' } })}
                        columns={[
                            { title: 'Name', dataIndex: 'name', width: 150, render: (v: string) => <Text strong>{v}</Text> },
                            { title: 'Email', dataIndex: 'email', width: 180, ellipsis: true },
                            { title: 'Orders', dataIndex: 'totalOrders', width: 70, sorter: (a: Customer, b: Customer) => (a.totalOrders || 0) - (b.totalOrders || 0) },
                            { title: 'Total Spent', dataIndex: 'totalSpent', width: 120, sorter: (a: Customer, b: Customer) => (a.totalSpent || 0) - (b.totalSpent || 0),
                                render: (v: number) => <Text strong style={{ color: '#10b981', fontFamily: 'monospace' }}>{fmtCurrency(v)}</Text> },
                            { title: 'Avg Order', key: 'avg', width: 100,
                                render: (_: unknown, r: Customer) => <Text style={{ fontFamily: 'monospace' }}>{r.totalOrders > 0 ? fmtCurrency(Math.round((r.totalSpent || 0) / r.totalOrders)) : '—'}</Text> },
                            { title: 'Last Order', dataIndex: 'lastOrderDate', width: 100, render: (v: string) => v ? dayjs(v).format('MMM DD, YY') : '—' },
                            { title: 'Segment', key: 'seg', width: 100,
                                render: (_: unknown, r: Customer) => { const s = rfmData.customerRFM.get(r.id); return s ? <Tag color={s.color} style={{ borderRadius: 10, fontSize: 10, margin: 0 }}>{s.label}</Tag> : '—'; } },
                            { title: 'Tier', dataIndex: 'loyaltyTier', width: 90,
                                render: (v: string) => v ? <Tag color={TIER_COLORS[v?.toLowerCase()] || 'default'} style={{ borderRadius: 10, fontSize: 10, margin: 0, textTransform: 'capitalize' }}>{v}</Tag> : '—' },
                        ]} />
                </Card>
            </motion.div>

            {/* Cohort Retention Grid */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.6 }}>
                <Card size="small" style={glassCard} title={<><ClockCircleOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Cohort Retention Analysis</Text></>}>
                    <div style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                            <thead>
                                <tr>
                                    <th style={{ padding: '8px 12px', textAlign: 'left', borderBottom: `1px solid ${gridStroke}` }}>
                                        <Text type="secondary" style={{ fontSize: 11 }}>Cohort</Text>
                                    </th>
                                    <th style={{ padding: '8px 12px', textAlign: 'center', borderBottom: `1px solid ${gridStroke}` }}>
                                        <Text type="secondary" style={{ fontSize: 11 }}>Size</Text>
                                    </th>
                                    {[1, 2, 3, 4, 5, 6].map(m => (
                                        <th key={m} style={{ padding: '8px 12px', textAlign: 'center', borderBottom: `1px solid ${gridStroke}` }}>
                                            <Text type="secondary" style={{ fontSize: 11 }}>M{m}</Text>
                                        </th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {cohortData.map((c, ri) => (
                                    <tr key={ri}>
                                        <td style={{ padding: '8px 12px', borderBottom: `1px solid ${gridStroke}` }}>
                                            <Text strong style={{ fontSize: 12 }}>{c.month}</Text>
                                        </td>
                                        <td style={{ padding: '8px 12px', textAlign: 'center', borderBottom: `1px solid ${gridStroke}` }}>
                                            <Tag style={{ margin: 0, borderRadius: 8 }}>{c.m0}</Tag>
                                        </td>
                                        {[0, 1, 2, 3, 4, 5].map(ci => {
                                            const val = c.retention[ci];
                                            if (val === undefined) return <td key={ci} style={{ padding: '8px 12px', textAlign: 'center', borderBottom: `1px solid ${gridStroke}` }}><Text type="secondary" style={{ fontSize: 10 }}>—</Text></td>;
                                            const bg = val >= 60 ? 'rgba(16,185,129,0.2)' : val >= 30 ? 'rgba(245,158,11,0.15)' : val > 0 ? 'rgba(239,68,68,0.12)' : 'transparent';
                                            const textColor = val >= 60 ? '#10b981' : val >= 30 ? '#f59e0b' : '#ef4444';
                                            return (
                                                <td key={ci} style={{ padding: '8px 12px', textAlign: 'center', borderBottom: `1px solid ${gridStroke}`, background: bg, borderRadius: 0 }}>
                                                    <Text strong style={{ fontSize: 12, color: textColor }}>{val}%</Text>
                                                </td>
                                            );
                                        })}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </motion.div>
        </div>

        {/* Customer Detail Drawer */}
        <Drawer open={!!drawerCustomer} onClose={() => setDrawerCustomer(null)} width={480}
            title={<Text strong style={{ fontSize: 16 }}>{drawerCustomer?.name}</Text>}>
            {drawerCustomer && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                    {/* Profile */}
                    <Card size="small" style={{ borderRadius: 12, background: isDark ? 'rgba(255,255,255,0.04)' : '#f9fafb' }}>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, fontSize: 12 }}>
                            <div><Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Email</Text><Text>{drawerCustomer.email || '—'}</Text></div>
                            <div><Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Phone</Text><Text>{drawerCustomer.phone || '—'}</Text></div>
                            <div><Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Type</Text><Tag color="blue" style={{ borderRadius: 10, textTransform: 'capitalize' }}>{drawerCustomer.customerType || '—'}</Tag></div>
                            <div><Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Tier</Text><Tag color={TIER_COLORS[drawerCustomer.loyaltyTier?.toLowerCase()] || 'default'} style={{ borderRadius: 10, textTransform: 'capitalize' }}>{drawerCustomer.loyaltyTier || '—'}</Tag></div>
                            <div style={{ gridColumn: '1 / -1' }}><Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Address</Text><Text>{[drawerCustomer.address, drawerCustomer.city].filter(Boolean).join(', ') || '—'}</Text></div>
                        </div>
                    </Card>

                    {/* RFM Scores */}
                    {drawerRFM && (
                        <Card size="small" style={{ borderRadius: 12, borderLeft: `3px solid ${drawerRFM.color}` }}>
                            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8 }}>RFM Scores</Text>
                            <div style={{ display: 'flex', gap: 10 }}>
                                {[{ label: 'Recency', val: drawerRFM.r }, { label: 'Frequency', val: drawerRFM.f }, { label: 'Monetary', val: drawerRFM.m }].map(s => (
                                    <div key={s.label} style={{ flex: 1, textAlign: 'center', padding: '8px 4px', borderRadius: 8, background: isDark ? 'rgba(255,255,255,0.04)' : '#f0f0f0' }}>
                                        <Text type="secondary" style={{ fontSize: 9, display: 'block' }}>{s.label}</Text>
                                        <Badge count={s.val} style={{ backgroundColor: s.val >= 4 ? '#10b981' : s.val >= 3 ? '#f59e0b' : '#ef4444' }} />
                                    </div>
                                ))}
                                <div style={{ flex: 1, textAlign: 'center', padding: '8px 4px', borderRadius: 8, background: `${drawerRFM.color}15` }}>
                                    <Text type="secondary" style={{ fontSize: 9, display: 'block' }}>Segment</Text>
                                    <Tag color={drawerRFM.color} style={{ borderRadius: 10, margin: 0, fontSize: 10 }}>{drawerRFM.label}</Tag>
                                </div>
                            </div>
                        </Card>
                    )}

                    {/* Order History */}
                    <Card size="small" style={{ borderRadius: 12 }} title={<Text strong style={{ fontSize: 12 }}>Order History ({drawerOrders.length})</Text>}>
                        {drawerOrders.length > 0 ? (
                            <Table dataSource={drawerOrders.slice(0, 10)} rowKey="id" size="small" pagination={false}
                                columns={[
                                    { title: 'Date', dataIndex: 'createdAt', width: 90, render: (v: string) => dayjs(v).format('MMM DD, YY') },
                                    { title: 'Amount', dataIndex: 'totalAmount', render: (v: number) => <Text style={{ fontFamily: 'monospace' }}>{fmtCurrency(v)}</Text> },
                                    { title: 'Status', dataIndex: 'status', width: 90, render: (v: string) => <Tag color={v === 'completed' ? 'green' : v === 'cancelled' ? 'red' : 'blue'} style={{ borderRadius: 10, fontSize: 10, margin: 0, textTransform: 'capitalize' }}>{v}</Tag> },
                                ]} />
                        ) : <Text type="secondary" style={{ fontSize: 12 }}>No orders yet</Text>}
                    </Card>

                    {/* Purchase Timeline */}
                    {drawerOrders.length > 0 && (
                        <Card size="small" style={{ borderRadius: 12 }} title={<Text strong style={{ fontSize: 12 }}>Purchase Timeline</Text>}>
                            <Timeline items={drawerOrders.slice(0, 6).map(o => ({
                                color: o.status === 'completed' ? 'green' : o.status === 'cancelled' ? 'red' : 'blue',
                                children: (
                                    <div>
                                        <Text style={{ fontSize: 12 }}>{fmtCurrency(o.totalAmount)}</Text>
                                        <Text type="secondary" style={{ fontSize: 10, marginLeft: 8 }}>{dayjs(o.createdAt).format('MMM DD, YYYY')}</Text>
                                    </div>
                                ),
                            }))} />
                        </Card>
                    )}

                    {/* Quick Actions */}
                    <div style={{ display: 'flex', gap: 8 }}>
                        <Tooltip title="Create Order"><motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}
                            style={{ flex: 1, padding: '10px', borderRadius: 10, border: 'none', cursor: 'pointer', background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, color: '#fff', fontWeight: 600, fontSize: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
                            <PlusOutlined /> Create Order
                        </motion.button></Tooltip>
                        <Tooltip title="Send Email"><motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}
                            style={{ flex: 1, padding: '10px', borderRadius: 10, border: `1px solid ${isDark ? 'rgba(255,255,255,0.15)' : '#d9d9d9'}`, cursor: 'pointer', background: 'transparent', color: isDark ? '#fff' : '#333', fontWeight: 600, fontSize: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
                            <MailOutlined /> Send Email
                        </motion.button></Tooltip>
                    </div>
                </div>
            )}
        </Drawer>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Tag, Card, Typography, Input, Button, Space, Tooltip, Row, Col, Modal, Form, Select, message } from "antd";
import { UserOutlined, SearchOutlined, ReloadOutlined, PlusOutlined, DeleteOutlined, TeamOutlined, ShoppingCartOutlined, DollarOutlined, MailOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { inventoryService, EcomCustomer, EcomStatsType } from "@/lib/inventoryService";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import { CrmAccountPicker, CrmContactPicker } from "@/components/inventory/CrmPicker";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const TYPE_COLORS: Record<string, string> = { individual: 'blue', company: 'purple', reseller: 'gold' };
const STATUS_COLORS: Record<string, string> = { active: 'green', inactive: 'default', blocked: 'red' };
const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : 'â€”';

const CUSTOMER_FIELDS: FieldDef[] = [
    { name: 'customerCode', label: 'Customer Code', required: true },
    { name: 'firstName', label: 'First Name', required: true },
    { name: 'lastName', label: 'Last Name' },
    { name: 'email', label: 'Email' },
    { name: 'phone', label: 'Phone' },
    { name: 'company', label: 'Company' },
    { name: 'customerType', label: 'Type' },
    { name: 'address', label: 'Address' },
    { name: 'city', label: 'City' },
    { name: 'accountId', label: 'CRM Account' },
    { name: 'contactId', label: 'CRM Contact' },
];

export default function CustomersPage() {
    const [stats, setStats] = useState<EcomStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [customers, setCustomers] = useState<EcomCustomer[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [modalOpen, setModalOpen] = useState(false);
    const [saving, setSaving] = useState(false);
    const [form] = Form.useForm();

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const [statsData, custData] = await Promise.all([
                inventoryService.getEcomStats(),
                inventoryService.getEcomCustomers(),
            ]);
            setStats(statsData);
            setCustomers(custData);
        } catch (err) { console.error(err); message.error("Failed to load customers"); } finally { setLoading(false); }
    };

    const handleCreate = async (values: any) => {
        setSaving(true);
        try {
            await inventoryService.createEcomCustomer('default', values);
            message.success("Customer created");
            setModalOpen(false);
            form.resetFields();
            load();
        } catch { message.error("Failed to create customer"); } finally { setSaving(false); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const record of records) {
            try {
                await inventoryService.createEcomCustomer('default', record);
                success++;
            } catch (e: any) {
                failed++;
                errors.push(`${record.customerCode || record.firstName || 'Unknown'}: ${e.message || 'Failed'}`);
            }
        }
        load();
        return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await inventoryService.deleteEcomCustomer(id);
            message.success("Customer deleted");
            load();
        } catch { message.error("Failed to delete"); }
    };

    const kpiCards = [
        { title: 'Total Customers', value: stats?.totalCustomers || 0, icon: <TeamOutlined />, color: themeColor },
        { title: 'Active', value: stats?.activeCustomers || 0, icon: <UserOutlined />, color: '#10b981' },
        { title: 'Total Orders', value: stats?.totalOrders || 0, icon: <ShoppingCartOutlined />, color: '#3b82f6' },
        { title: 'Revenue', value: fmtCurrency(stats?.totalRevenue), icon: <DollarOutlined />, color: '#f59e0b' },
    ];

    const filtered = customers.filter(c => {
        if (!search) return true;
        const s = search.toLowerCase();
        return c.firstName?.toLowerCase().includes(s) || c.lastName?.toLowerCase().includes(s) ||
            c.email?.toLowerCase().includes(s) || c.customerCode?.toLowerCase().includes(s) || c.company?.toLowerCase().includes(s);
    });

    const columns = [
        { title: 'Code', dataIndex: 'customerCode', width: 110, render: (v: string) => <Text code className="text-xs">{v}</Text> },
        { title: 'Name', key: 'name', render: (_: any, r: EcomCustomer) => <Text strong className="text-sm">{r.firstName} {r.lastName || ''}</Text> },
        { title: 'Email', dataIndex: 'email', ellipsis: true, render: (v: string) => v ? <Text className="text-xs"><MailOutlined className="mr-1" />{v}</Text> : 'â€”' },
        { title: 'Phone', dataIndex: 'phone', width: 130 },
        { title: 'Company', dataIndex: 'company', width: 150, ellipsis: true, render: (v: string) => v || 'â€”' },
        { title: 'Type', dataIndex: 'customerType', width: 100,
            render: (v: string) => <Tag color={TYPE_COLORS[v] || 'default'} className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: 'Orders', dataIndex: 'totalOrders', width: 70, sorter: (a: any, b: any) => (a.totalOrders || 0) - (b.totalOrders || 0) },
        { title: 'Total Spent', dataIndex: 'totalSpent', width: 140, sorter: (a: any, b: any) => (a.totalSpent || 0) - (b.totalSpent || 0),
            render: (v: number) => <Text strong style={{ color: themeColor }}>{fmtCurrency(v)}</Text> },
        { title: 'City', dataIndex: 'city', width: 120, render: (v: string) => v || 'â€”' },
        { title: 'Status', dataIndex: 'status', width: 90,
            render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'} className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: '', key: 'actions', width: 50,
            render: (_: any, r: EcomCustomer) => (
                <Button size="small" danger icon={<DeleteOutlined />}
                    onClick={() => Modal.confirm({ title: 'Delete customer?', onOk: () => handleDelete(r.id) })} />
            ),
        },
    ];

    const customerSteps = [
        {
            title: "Identity",
            fields: ["customerCode", "firstName", "lastName", "customerType"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="customerCode" label="Code" rules={[{ required: true }]}><Input placeholder="CUST-XXX" /></Form.Item></Col>
                        <Col span={8}><Form.Item name="firstName" label="First Name" rules={[{ required: true }]}><Input /></Form.Item></Col>
                        <Col span={8}><Form.Item name="lastName" label="Last Name"><Input /></Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="company" label="Company"><Input /></Form.Item></Col>
                        <Col span={12}><Form.Item name="customerType" label="Type" initialValue="individual">
                            <Select options={[{ value: 'individual', label: 'Individual' }, { value: 'company', label: 'Company' }, { value: 'reseller', label: 'Reseller' }]} />
                        </Form.Item></Col>
                    </Row>
                </>
            ),
        },
        {
            title: "Contact & Address",
            fields: ["email", "phone", "address", "city"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="email" label="Email"><Input /></Form.Item></Col>
                        <Col span={12}><Form.Item name="phone" label="Phone"><Input /></Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={16}><Form.Item name="address" label="Address"><Input /></Form.Item></Col>
                        <Col span={8}><Form.Item name="city" label="City"><Input /></Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="accountId" label="Link to CRM Account">
                                <CrmAccountPicker placeholder="Search CRM accounts..." />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="contactId" label="Link to CRM Contact">
                                <CrmContactPicker placeholder="Search CRM contacts..." />
                            </Form.Item>
                        </Col>
                    </Row>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Customers</AuroraText>}
            subTitle={<DecryptedText text="Customer registry and purchase history" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={12} md={6}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...glass,
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={{ flex: 1, ...glass, borderRadius: 12, border: '1px solid rgba(255,255,255,0.5)' }}>
                    <div className="flex items-center justify-between mb-3">
                        <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search customers..."
                            value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 300, borderRadius: 8 }} size="small" />
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_customers', title: 'eCommerce Customers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'firstName' }, { header: 'Surname', key: 'lastName' }, { header: 'Email', key: 'email' }, { header: 'Phone', key: 'phone' }, { header: 'Status', key: 'status' }], data: filtered })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_customers', title: 'eCommerce Customers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'firstName' }, { header: 'Surname', key: 'lastName' }, { header: 'Email', key: 'email' }, { header: 'Phone', key: 'phone' }, { header: 'Status', key: 'status' }], data: filtered })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />}
                                onClick={() => { form.resetFields(); setModalOpen(true); }}
                                style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, borderRadius: 8, border: 'none' }}>
                                New Customer
                            </Button>
                        </Space>
                    </div>
                    <Table dataSource={filtered} columns={columns} rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false, showTotal: (t) => `${t} customers` }} scroll={{ x: 1200 }} />
                </Card>
            </div>

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); form.resetFields(); }}
                onSubmit={handleCreate}
                form={form}
                title="New Customer"
                entityName="customer"
                steps={customerSteps}
                fields={CUSTOMER_FIELDS}
                loading={saving}
                onBatchCreate={handleBatchCreate}
                gradient={["#6366f1", "var(--theme-color, #8b5cf6)"]}
            />
        </CMSLayout>
    );
}

"use client";
import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { Card, Row, Col, Statistic, Typography, Spin, Progress, Tag, Space, Badge, Tooltip } from "antd";
import {
    ShoppingCartOutlined, DollarOutlined, UserOutlined, GiftOutlined,
    CheckCircleOutlined, ClockCircleOutlined, SendOutlined, CarOutlined,
    InboxOutlined, CloseCircleOutlined, TagsOutlined, PercentageOutlined,
    ArrowRightOutlined, RiseOutlined, ShopOutlined, TrophyOutlined,
    StarOutlined, ThunderboltOutlined,
} from "@ant-design/icons";
import { inventoryService, EcomStatsType, EcomOrder } from "@/lib/inventoryService";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useTheme } from "next-themes";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { useRouter } from "next/navigation";
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { AnimatedCircularProgressBar } from "@/components/magicui/animated-circular-progress-bar";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer } from 'recharts';

const { Text, Title } = Typography;
const fmt = (v: number) => v ? `Rp ${v.toLocaleString('id-ID')}` : 'Rp 0';
const fmtShort = (v: number) => {
    if (v >= 1e9) return `Rp ${(v / 1e9).toFixed(1)}B`;
    if (v >= 1e6) return `Rp ${(v / 1e6).toFixed(1)}M`;
    if (v >= 1e3) return `Rp ${(v / 1e3).toFixed(0)}K`;
    return `Rp ${v}`;
};

const STATUS_CFG: Record<string, { color: string; icon: React.ReactNode; emoji: string }> = {
    pending: { color: '#94a3b8', icon: <ClockCircleOutlined />, emoji: '⏳' },
    confirmed: { color: '#3b82f6', icon: <CheckCircleOutlined />, emoji: '✅' },
    processing: { color: '#8b5cf6', icon: <InboxOutlined />, emoji: '📦' },
    shipped: { color: '#06b6d4', icon: <SendOutlined />, emoji: '🚚' },
    delivered: { color: '#0ea5e9', icon: <CarOutlined />, emoji: '📬' },
    completed: { color: '#10b981', icon: <CheckCircleOutlined />, emoji: '🎉' },
    cancelled: { color: '#ef4444', icon: <CloseCircleOutlined />, emoji: '❌' },
    refunded: { color: '#f97316', icon: <CloseCircleOutlined />, emoji: '💸' },
};

// Revenue Trend Recharts
function RevenueTrend({ orders, isDark, textColor }: { orders: EcomOrder[], isDark: boolean, textColor: string }) {
    const dateMap: Record<string, number> = {};
    orders.filter(o => o.status !== 'cancelled').forEach(o => {
        if (o.createdAt) {
            const d = new Date(o.createdAt).toLocaleDateString('en-CA');
            dateMap[d] = (dateMap[d] || 0) + (o.totalAmount || 0);
        }
    });
    const entries = Object.entries(dateMap).sort(([a], [b]) => a.localeCompare(b)).slice(-14);
    if (entries.length < 2) return <Text type="secondary" style={{ fontSize: 12 }}>Not enough data for trend</Text>;

    const data = entries.map(([date, revenue]) => ({ date, revenue }));

    const CustomTooltip = ({ active, payload, label }: any) => {
        if (active && payload && payload.length) {
            return (
                <div style={{ background: isDark ? 'rgba(15, 23, 42, 0.8)' : 'rgba(255,255,255,0.8)', padding: '12px 16px', border: '1px solid rgba(255,255,255,0.2)', borderRadius: 12, backdropFilter: 'blur(8px)' }}>
                    <p className="font-semibold" style={{ color: textColor, margin: 0, marginBottom: 8 }}>{label}</p>
                    <p style={{ color: '#10b981', margin: 0, fontSize: 13, fontWeight: 'bold' }}>
                        Revenue: {fmt(payload[0].value)}
                    </p>
                </div>
            );
        }
        return null;
    };

    return (
        <div style={{ height: 250, width: '100%', marginTop: 20 }}>
            <ResponsiveContainer>
                <AreaChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                    <defs>
                        <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#10b981" stopOpacity={0.5}/>
                            <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                        </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.05)"} />
                    <XAxis dataKey="date" stroke={isDark ? "rgba(255,255,255,0.4)" : "rgba(0,0,0,0.4)"} tickLine={false} axisLine={false} tick={{fontSize: 10}} minTickGap={20} />
                    <YAxis stroke={isDark ? "rgba(255,255,255,0.4)" : "rgba(0,0,0,0.4)"} tickLine={false} axisLine={false} tick={{fontSize: 10}} tickFormatter={fmtShort} width={60} />
                    <RechartsTooltip content={<CustomTooltip />} />
                    <Area type="monotone" dataKey="revenue" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorRev)" activeDot={{ r: 6, strokeWidth: 0, fill: '#10b981' }} />
                </AreaChart>
            </ResponsiveContainer>
        </div>
    );
}

// Order Status Funnel
function OrderFunnel({ stats }: { stats: EcomStatsType }) {
    const stages = [
        { key: 'pending', label: 'Pending', value: stats.pending || 0 },
        { key: 'confirmed', label: 'Confirmed', value: stats.confirmed || 0 },
        { key: 'processing', label: 'Processing', value: stats.processing || 0 },
        { key: 'shipped', label: 'Shipped', value: stats.shipped || 0 },
        { key: 'delivered', label: 'Delivered', value: stats.delivered || 0 },
        { key: 'completed', label: 'Completed', value: stats.completed || 0 },
    ];
    const total = stats.totalOrders || 1;

    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
            {stages.map((s, i) => {
                const cfg = STATUS_CFG[s.key];
                const pct = Math.round((s.value / total) * 100);
                return (
                    <React.Fragment key={s.key}>
                        <motion.div initial={{ scaleX: 0 }} animate={{ scaleX: 1 }} transition={{ delay: i * 0.08 }}
                            style={{ flex: 1, background: `linear-gradient(135deg, ${cfg.color}18, ${cfg.color}08)`, border: `1px solid ${cfg.color}22`, borderRadius: 8, padding: '8px 6px', textAlign: 'center', position: 'relative', overflow: 'hidden', minWidth: 50 }}>
                            <div style={{ position: 'absolute', bottom: 0, left: 0, width: `${pct}%`, height: 3, background: cfg.color, borderRadius: 3 }} />
                            <Text style={{ fontSize: 9, color: cfg.color, display: 'block', lineHeight: 1.2 }}>{cfg.emoji} {s.label}</Text>
                            <Text strong style={{ fontSize: 16, color: cfg.color }}>{s.value}</Text>
                        </motion.div>
                        {i < stages.length - 1 && <ArrowRightOutlined style={{ color: '#d1d5db', fontSize: 10 }} />}
                    </React.Fragment>
                );
            })}
        </div>
    );
}

export default function EcommerceDashboard() {
