                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Total Revenue"
                        description="Lifetime generated revenue"
                        icon={<DollarOutlined style={{ color: '#10b981' }} />}
