                            <div style={{ display: 'flex', flexDirection: 'column', gap: 6, minHeight: 250 }}>
                                <AnimatePresence>
                                    {recent.map((o, i) => {
                                        const cfg = STATUS_CFG[o.status || 'pending'];
                                        return (
                                            <motion.div key={o.id} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.05 }}
