export default function DiscountsPage() {
    const [stats, setStats] = useState<EcomDiscountStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [discounts, setDiscounts] = useState<EcomDiscount[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [modalOpen, setModalOpen] = useState(false);
    const [editDiscount, setEditDiscount] = useState<EcomDiscount | null>(null);
    const [saving, setSaving] = useState(false);
    const [form] = Form.useForm();

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const [s, d] = await Promise.all([
                inventoryService.getEcomDiscountStats(),
                inventoryService.getEcomDiscounts(),
            ]);
            setStats(s);
            setDiscounts(d);
        } catch (err) { console.error(err); message.error("Failed to load discounts"); } finally { setLoading(false); }
    };

    const handleDelete = async (id: string) => {
        try { await inventoryService.deleteEcomDiscount(id); message.success("Discount deleted"); load(); }
        catch { message.error("Failed"); }
    };

    const openNew = () => { setEditDiscount(null); form.resetFields(); setModalOpen(true); };

    const openEdit = (d: EcomDiscount) => {
        setEditDiscount(d);
        form.setFieldsValue({
            ...d,
            validFrom: d.validFrom ? dayjs(d.validFrom) : undefined,
            validUntil: d.validUntil ? dayjs(d.validUntil) : undefined,
        });
        setModalOpen(true);
    };

    const generateCode = () => {
        const code = 'SAVE' + Math.random().toString(36).substring(2, 8).toUpperCase();
        form.setFieldsValue({ code });
    };

    const handleSave = async (values: any) => {
        setSaving(true);
        try {
            const input = {
                code: values.code, name: values.name, description: values.description,
                discountType: values.discountType, discountValue: values.discountValue,
                minOrderAmount: values.minOrderAmount, maxDiscountAmount: values.maxDiscountAmount,
                usageLimit: values.usageLimit,
                validFrom: values.validFrom?.toISOString?.() || values.validFrom,
                validUntil: values.validUntil?.toISOString?.() || values.validUntil,
                autoApply: values.autoApply || false,
                appliesTo: values.appliesTo,
                stackable: values.stackable || false,
                notes: values.notes, status: values.status || 'active',
            };
            if (editDiscount) {
                await inventoryService.updateEcomDiscount(editDiscount.id, input as any);
                message.success('Discount updated');
            } else {
                await inventoryService.createEcomDiscount('default', input as any);
                message.success('Discount created');
            }
            setModalOpen(false);
            form.resetFields();
            load();
        } catch (e: any) {
            message.error(e.message || 'Failed');
        } finally { setSaving(false); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createEcomDiscount('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.name || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        load();
        return { success, failed, errors };
    };

    const kpiCards = [
        { title: 'Total Discounts', value: stats?.totalDiscounts || 0, icon: <PercentageOutlined />, color: '#10b981' },
        { title: 'Active', value: stats?.active || 0, icon: <CheckCircleOutlined />, color: '#3b82f6' },
        { title: 'Coupons', value: stats?.coupons || 0, icon: <CopyOutlined />, color: themeColor },
        { title: 'Auto-Apply', value: stats?.autoApply || 0, icon: <ThunderboltOutlined />, color: '#f59e0b' },
        { title: 'Expired', value: stats?.expired || 0, icon: <ClockCircleOutlined />, color: '#94a3b8' },
        { title: 'Total Used', value: stats?.totalUsed || 0, icon: <DollarOutlined />, color: '#ef4444' },
    ];

    const filtered = discounts.filter(d => {
        if (statusFilter && d.status !== statusFilter) return false;
        if (search && !d.name?.toLowerCase().includes(search.toLowerCase()) && !d.code?.toLowerCase().includes(search.toLowerCase())) return false;
        return true;
    });

    const columns = [
        { title: 'Discount', key: 'name', render: (_: any, r: EcomDiscount) => (
            <div>
                <Text strong className="text-sm">{r.name}</Text>
                {r.code && <div><Tag color="purple" className="text-xs mt-1">{r.code}</Tag></div>}
            </div>
        )},
        { title: 'Type', key: 'type', width: 130,
            render: (_: any, r: EcomDiscount) => (
                <Text strong style={{ color: '#10b981' }}>
                    {r.discountType === 'percentage' ? `${r.discountValue}% off` : fmtCurrency(r.discountValue) + ' off'}
                </Text>
            ),
        },
        { title: 'Min Order', dataIndex: 'minOrderAmount', width: 130, render: (v: number) => v ? fmtCurrency(v) : 'â€”' },
        { title: 'Uses', key: 'uses', width: 100,
            render: (_: any, r: EcomDiscount) => <Text>{r.timesUsed || 0}{r.usageLimit ? ` / ${r.usageLimit}` : ''}</Text> },
        { title: 'Valid Until', dataIndex: 'validUntil', width: 120,
            render: (v: string) => v ? new Date(v).toLocaleDateString() : 'âˆž' },
        { title: 'Features', key: 'features', width: 140,
            render: (_: any, r: EcomDiscount) => (
                <Space size={4}>
                    {r.autoApply && <Tag color="orange" className="text-xs">Auto</Tag>}
                    {r.stackable && <Tag color="cyan" className="text-xs">Stackable</Tag>}
                    {r.code && <Tag color="purple" className="text-xs">Coupon</Tag>}
                </Space>
            ),
        },
        { title: 'Status', dataIndex: 'status', width: 90,
            render: (v: string) => <Tag color={v === 'active' ? 'green' : v === 'expired' ? 'volcano' : 'default'} className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: '', key: 'actions', width: 100,
            render: (_: any, r: EcomDiscount) => (
                <Space size="small">
                    <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(r)} />
                    <Button size="small" danger icon={<DeleteOutlined />}
                        onClick={() => Modal.confirm({ title: 'Delete discount?', onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const discountSteps = [
        {
            title: "Basic Info",
            fields: ["name", "code", "status", "description"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={10}><Form.Item name="name" label="Discount Name" rules={[{ required: true }]}><Input placeholder="e.g. New Customer Discount" /></Form.Item></Col>
                        <Col span={8}>
                            <Form.Item name="code" label="Coupon Code">
                                <Input placeholder="SAVE20" addonAfter={<Button type="link" size="small" onClick={generateCode} style={{ padding: 0, height: 'auto' }}>Generate</Button>} />
                            </Form.Item>
                        </Col>
                        <Col span={6}><Form.Item name="status" label="Status" initialValue="active">
                            <Select options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }]} />
                        </Form.Item></Col>
                    </Row>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={1} placeholder="Discount details..." /></Form.Item>
                </>
            ),
        },
        {
            title: "Discount Rules",
            fields: ["discountType", "discountValue", "minOrderAmount", "maxDiscountAmount"],
            content: (
                <Row gutter={16}>
                    <Col span={6}><Form.Item name="discountType" label="Discount Type" initialValue="percentage">
                        <Select options={[{ value: 'percentage', label: 'Percentage' }, { value: 'fixed_amount', label: 'Fixed Amount' }]} />
                    </Form.Item></Col>
                    <Col span={6}><Form.Item name="discountValue" label="Value" rules={[{ required: true }]}>
                        <InputNumber min={0} style={{ width: '100%' }} />
                    </Form.Item></Col>
                    <Col span={6}><Form.Item name="minOrderAmount" label="Min Order"><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                    <Col span={6}><Form.Item name="maxDiscountAmount" label="Max Discount"><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                </Row>
            ),
        },
        {
            title: "Validity & Options",
            fields: ["validFrom", "validUntil", "usageLimit", "appliesTo", "autoApply", "stackable", "notes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="validFrom" label="Valid From"><DatePicker showTime style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="validUntil" label="Valid Until"><DatePicker showTime style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={4}><Form.Item name="usageLimit" label="Usage Limit"><InputNumber min={0} style={{ width: '100%' }} placeholder="0=âˆž" /></Form.Item></Col>
                        <Col span={4}><Form.Item name="appliesTo" label="Applies To" initialValue="order">
                            <Select options={[{ value: 'order', label: 'Order' }, { value: 'item', label: 'Item' }, { value: 'shipping', label: 'Shipping' }]} />
                        </Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={6}><Form.Item name="autoApply" label="Auto-Apply" valuePropName="checked"><Switch /></Form.Item></Col>
                        <Col span={6}><Form.Item name="stackable" label="Stackable" valuePropName="checked"><Switch /></Form.Item></Col>
                        <Col span={12}><Form.Item name="notes" label="Notes"><Input.TextArea rows={1} /></Form.Item></Col>
                    </Row>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={["#10b981", "#059669", "#34d399", "#00ffff", "#ff00ff"]}>Discounts</AuroraText>}
            subTitle={<DecryptedText text="Manage discount codes, coupons, and auto-apply rules" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...glass,
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={{ flex: 1, ...glass, borderRadius: 12, border: '1px solid rgba(255,255,255,0.5)' }}>
                    <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                        <div className="flex items-center gap-3">
                            <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search discounts or codes..."
                                value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 260, borderRadius: 8 }} size="small" />
                            <Select placeholder="Status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 130 }} size="small"
                                options={[{ value: 'active', label: 'Active' }, { value: 'expired', label: 'Expired' }, { value: 'inactive', label: 'Inactive' }]} />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_discounts', title: 'eCommerce Discounts', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Code', key: 'code' }, { header: 'Type', key: 'discountType' }, { header: 'Value', key: 'value' }, { header: 'Status', key: 'status' }], data: discounts })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_discounts', title: 'eCommerce Discounts', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Code', key: 'code' }, { header: 'Type', key: 'discountType' }, { header: 'Value', key: 'value' }, { header: 'Status', key: 'status' }], data: discounts })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />} onClick={openNew}
                                style={{ background: 'linear-gradient(135deg, #10b981, #059669)', border: 'none', borderRadius: 8 }}>
                                New Discount
                            </Button>
                        </Space>
                    </div>
                    <Table dataSource={filtered} columns={columns} rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false, showTotal: (t) => `${t} discounts` }} scroll={{ x: 1000 }} />
                </Card>
            </div>

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditDiscount(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editDiscount ? "Edit Discount" : "New Discount"}
                entityName="discount"
                steps={discountSteps}
                fields={DISCOUNT_FIELDS}
                loading={saving}
                onBatchCreate={handleBatchCreate}
                gradient={["#10b981", "#059669"]}
                editMode={!!editDiscount}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Tag, Card, Typography, Input, Space, Button, Tooltip, Row, Col, message, Modal, Select, Form, InputNumber, DatePicker } from "antd";
import { TagOutlined, SearchOutlined, ReloadOutlined, DollarOutlined, CheckCircleOutlined, ClockCircleOutlined, DeleteOutlined, PlusOutlined, EditOutlined, ThunderboltOutlined, FireOutlined, PercentageOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { inventoryService, EcomOffer, EcomOfferStatsType } from "@/lib/inventoryService";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : '—';

const OFFER_TYPES = [
    { value: 'flash_sale', label: 'Flash Sale' },
    { value: 'seasonal', label: 'Seasonal' },
    { value: 'clearance', label: 'Clearance' },
    { value: 'bundle_deal', label: 'Bundle Deal' },
    { value: 'bogo', label: 'Buy One Get One' },
    { value: 'limited_time', label: 'Limited Time' },
];

const OFFER_TYPE_COLORS: Record<string, string> = {
    flash_sale: 'red', seasonal: 'blue', clearance: 'orange',
    bundle_deal: 'purple', bogo: 'cyan', limited_time: 'magenta',
};

const OFFER_FIELDS: FieldDef[] = [
    { name: 'name', label: 'Offer Name', required: true },
    { name: 'offerType', label: 'Type', required: true },
    { name: 'status', label: 'Status' },
    { name: 'description', label: 'Description' },
    { name: 'discountType', label: 'Discount Type' },
    { name: 'discountValue', label: 'Discount Value', type: 'number', required: true },
    { name: 'minOrderAmount', label: 'Min Order Amount', type: 'number' },
    { name: 'maxUses', label: 'Max Uses', type: 'number' },
    { name: 'startDate', label: 'Start Date', type: 'date' },
    { name: 'endDate', label: 'End Date', type: 'date' },
    { name: 'appliesTo', label: 'Applies To' },
    { name: 'bannerText', label: 'Banner Text' },
    { name: 'badgeText', label: 'Badge Text' },
    { name: 'notes', label: 'Notes' },
];

export default function OffersPage() {
    const [stats, setStats] = useState<EcomOfferStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [offers, setOffers] = useState<EcomOffer[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [modalOpen, setModalOpen] = useState(false);
    const [editOffer, setEditOffer] = useState<EcomOffer | null>(null);
    const [saving, setSaving] = useState(false);
    const [form] = Form.useForm();

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const [s, o] = await Promise.all([
                inventoryService.getEcomOfferStats(),
                inventoryService.getEcomOffers(),
            ]);
            setStats(s);
            setOffers(o);
        } catch (err) { console.error(err); message.error("Failed to load offers"); } finally { setLoading(false); }
    };

    const handleDelete = async (id: string) => {
        try { await inventoryService.deleteEcomOffer(id); message.success("Offer deleted"); load(); }
        catch { message.error("Failed"); }
    };

    const openNew = () => { setEditOffer(null); form.resetFields(); setModalOpen(true); };

    const openEdit = (o: EcomOffer) => {
        setEditOffer(o);
        form.setFieldsValue({
            ...o,
            startDate: o.startDate ? dayjs(o.startDate) : undefined,
            endDate: o.endDate ? dayjs(o.endDate) : undefined,
        });
        setModalOpen(true);
    };

    const handleSave = async (values: any) => {
        setSaving(true);
        try {
            const input = {
                name: values.name, description: values.description,
                offerType: values.offerType, discountType: values.discountType,
                discountValue: values.discountValue, minOrderAmount: values.minOrderAmount,
                maxUses: values.maxUses,
                startDate: values.startDate?.toISOString?.() || values.startDate,
                endDate: values.endDate?.toISOString?.() || values.endDate,
                appliesTo: values.appliesTo, bannerText: values.bannerText,
                badgeText: values.badgeText, notes: values.notes,
                status: values.status || 'draft',
            };
            if (editOffer) {
                await inventoryService.updateEcomOffer(editOffer.id, input as any);
                message.success('Offer updated');
            } else {
                await inventoryService.createEcomOffer('default', input as any);
                message.success('Offer created');
            }
            setModalOpen(false);
            form.resetFields();
            load();
        } catch (e: any) {
            message.error(e.message || 'Failed');
        } finally { setSaving(false); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createEcomOffer('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.name || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        load();
        return { success, failed, errors };
    };

    const kpiCards = [
        { title: 'Total Offers', value: stats?.totalOffers || 0, icon: <TagOutlined />, color: '#ef4444' },
        { title: 'Active', value: stats?.active || 0, icon: <ThunderboltOutlined />, color: '#10b981' },
        { title: 'Draft', value: stats?.draft || 0, icon: <ClockCircleOutlined />, color: '#94a3b8' },
        { title: 'Expired', value: stats?.expired || 0, icon: <ClockCircleOutlined />, color: '#f59e0b' },
        { title: 'Total Uses', value: stats?.totalUses || 0, icon: <FireOutlined />, color: themeColor },
    ];

    const filtered = offers.filter(o => {
        if (statusFilter && o.status !== statusFilter) return false;
        if (search && !o.name?.toLowerCase().includes(search.toLowerCase())) return false;
        return true;
    });

    const columns = [
        { title: 'Offer', dataIndex: 'name', render: (v: string, r: EcomOffer) => (
            <div>
                <Text strong className="text-sm">{v}</Text>
                {r.description && <Text type="secondary" className="text-xs block" style={{ maxWidth: 250 }}>{r.description.substring(0, 60)}{(r.description.length || 0) > 60 ? '...' : ''}</Text>}
            </div>
        )},
        { title: 'Type', dataIndex: 'offerType', width: 120,
            render: (v: string) => <Tag color={OFFER_TYPE_COLORS[v] || 'default'} className="rounded-full text-xs capitalize">{v?.replace(/_/g, ' ') || '—'}</Tag> },
        { title: 'Discount', key: 'discount', width: 130,
            render: (_: any, r: EcomOffer) => (
                <Text strong style={{ color: '#ef4444' }}>
                    {r.discountType === 'percentage' ? `${r.discountValue}%` : fmtCurrency(r.discountValue)}
                </Text>
            ),
        },
        { title: 'Uses', key: 'uses', width: 100,
            render: (_: any, r: EcomOffer) => <Text>{r.currentUses || 0}{r.maxUses ? ` / ${r.maxUses}` : ''}</Text> },
        { title: 'Period', key: 'period', width: 180,
            render: (_: any, r: EcomOffer) => (
                <Text className="text-xs">
                    {r.startDate ? new Date(r.startDate).toLocaleDateString() : '—'} → {r.endDate ? new Date(r.endDate).toLocaleDateString() : '∞'}
                </Text>
            ),
        },
        { title: 'Status', dataIndex: 'status', width: 100,
            render: (v: string) => {
                const colors: Record<string, string> = { active: 'green', draft: 'default', expired: 'volcano', paused: 'orange' };
                return <Tag color={colors[v] || 'default'} className="rounded-full text-xs capitalize">{v}</Tag>;
            },
        },
        { title: '', key: 'actions', width: 100,
            render: (_: any, r: EcomOffer) => (
                <Space size="small">
                    <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(r)} />
                    <Button size="small" danger icon={<DeleteOutlined />}
                        onClick={() => Modal.confirm({ title: 'Delete offer?', onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const offerSteps = [
        {
            title: "Basic Info",
            fields: ["name", "offerType", "status", "description"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="name" label="Offer Name" rules={[{ required: true }]}><Input placeholder="e.g. Summer Flash Sale" /></Form.Item></Col>
                        <Col span={6}><Form.Item name="offerType" label="Type" rules={[{ required: true }]}><Select options={OFFER_TYPES} /></Form.Item></Col>
                        <Col span={6}><Form.Item name="status" label="Status" initialValue="draft">
                            <Select options={[{ value: 'draft', label: 'Draft' }, { value: 'active', label: 'Active' }, { value: 'paused', label: 'Paused' }]} />
                        </Form.Item></Col>
                    </Row>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} placeholder="Offer details..." /></Form.Item>
                </>
            ),
        },
        {
            title: "Discount & Limits",
            fields: ["discountType", "discountValue", "minOrderAmount", "maxUses"],
            content: (
                <Row gutter={16}>
                    <Col span={6}><Form.Item name="discountType" label="Discount Type" initialValue="percentage">
                        <Select options={[{ value: 'percentage', label: 'Percentage' }, { value: 'fixed_amount', label: 'Fixed Amount' }]} />
                    </Form.Item></Col>
                    <Col span={6}><Form.Item name="discountValue" label="Value" rules={[{ required: true }]}>
                        <InputNumber min={0} style={{ width: '100%' }} />
                    </Form.Item></Col>
                    <Col span={6}><Form.Item name="minOrderAmount" label="Min Order"><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                    <Col span={6}><Form.Item name="maxUses" label="Max Uses"><InputNumber min={0} style={{ width: '100%' }} placeholder="0 = unlimited" /></Form.Item></Col>
                </Row>
            ),
        },
        {
            title: "Schedule & Display",
            fields: ["startDate", "endDate", "appliesTo", "bannerText", "badgeText", "notes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="startDate" label="Start Date"><DatePicker showTime style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="endDate" label="End Date"><DatePicker showTime style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="appliesTo" label="Applies To" initialValue="all_products">
                            <Select options={[{ value: 'all_products', label: 'All Products' }, { value: 'specific_items', label: 'Specific Items' }, { value: 'category', label: 'Category' }]} />
                        </Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="bannerText" label="Banner Text"><Input placeholder="e.g. 🔥 50% OFF!" /></Form.Item></Col>
                        <Col span={8}><Form.Item name="badgeText" label="Badge Text"><Input placeholder="e.g. HOT DEAL" /></Form.Item></Col>
                        <Col span={8}><Form.Item name="notes" label="Notes"><Input.TextArea rows={1} /></Form.Item></Col>
                    </Row>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={["#ef4444", "#f59e0b", "#f97316", "#ff6b6b", "#ff00ff"]}>Offers</AuroraText>}
            subTitle={<DecryptedText text="Create and manage promotional offers & flash sales" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={Math.floor(24 / kpiCards.length)}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...glass,
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={{ flex: 1, ...glass, borderRadius: 12, border: '1px solid rgba(255,255,255,0.5)' }}>
                    <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                        <div className="flex items-center gap-3">
                            <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search offers..."
                                value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 240, borderRadius: 8 }} size="small" />
                            <Select placeholder="Status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 130 }} size="small"
                                options={[{ value: 'active', label: 'Active' }, { value: 'draft', label: 'Draft' }]} />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_offers', title: 'eCommerce Offers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'offerType' }, { header: 'Discount', key: 'discountValue' }, { header: 'Status', key: 'status' }], data: offers })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_offers', title: 'eCommerce Offers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'offerType' }, { header: 'Discount', key: 'discountValue' }, { header: 'Status', key: 'status' }], data: offers })} /></Tooltip></RbacGuard>
            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_offers', title: 'eCommerce Offers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'offerType' }, { header: 'Discount', key: 'discountValue' }, { header: 'Status', key: 'status' }], data: offers })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_offers', title: 'eCommerce Offers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'offerType' }, { header: 'Discount', key: 'discountValue' }, { header: 'Status', key: 'status' }], data: offers })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />} onClick={openNew}
                                style={{ background: 'linear-gradient(135deg, #ef4444, #f97316)', border: 'none', borderRadius: 8 }}>
                                New Offer
                            </Button>
                        </Space>
                    </div>
                    <Table dataSource={filtered} columns={columns} rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false, showTotal: (t) => `${t} offers` }} scroll={{ x: 900 }} />
                </Card>
            </div>

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditOffer(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editOffer ? "Edit Offer" : "New Offer"}
                entityName="offer"
                steps={offerSteps}
                fields={OFFER_FIELDS}
                loading={saving}
                onBatchCreate={handleBatchCreate}
                gradient={["#ef4444", "#f97316"]}
                editMode={!!editOffer}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Tag, Card, Typography, Input, Space, Button, Tooltip, Row, Col, Drawer, message, Modal, Select, Form, InputNumber, Divider } from "antd";
import { ShoppingCartOutlined, SearchOutlined, ReloadOutlined, DollarOutlined, CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, SendOutlined, EyeOutlined, CarOutlined, DeleteOutlined, InboxOutlined, PlusOutlined, MinusCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { inventoryService, EcomOrder, EcomOrderItem, EcomStatsType, EcomCustomer } from "@/lib/inventoryService";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import ItemPicker from "@/components/inventory/ItemPicker";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const ORDER_STATUS: Record<string, { color: string; icon: React.ReactNode }> = {
    pending: { color: 'default', icon: <ClockCircleOutlined /> },
    confirmed: { color: 'blue', icon: <CheckCircleOutlined /> },
    processing: { color: 'processing', icon: <InboxOutlined /> },
    shipped: { color: 'cyan', icon: <SendOutlined /> },
    delivered: { color: 'geekblue', icon: <CarOutlined /> },
    completed: { color: 'green', icon: <CheckCircleOutlined /> },
    cancelled: { color: 'red', icon: <CloseCircleOutlined /> },
    refunded: { color: 'volcano', icon: <CloseCircleOutlined /> },
};

const PAYMENT_COLORS: Record<string, string> = { unpaid: 'red', partial: 'orange', paid: 'green', refunded: 'volcano' };
const FULFILLMENT_COLORS: Record<string, string> = { physical: 'blue', ticket: 'purple', scheduled: 'cyan', rental: 'orange' };

const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : 'â€”';

interface OrderLineItem {
    key: number;
    itemId?: string;
    itemName: string;
    itemSku?: string;
    quantity: number;
    unitPrice: number;
    discount: number;
    subtotal: number;
}

export default function OrdersPage() {
    const [stats, setStats] = useState<EcomStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [orders, setOrders] = useState<EcomOrder[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [selectedOrder, setSelectedOrder] = useState<EcomOrder | null>(null);
    const [orderItems, setOrderItems] = useState<EcomOrderItem[]>([]);
    const [drawerOpen, setDrawerOpen] = useState(false);

    // New Order modal
    const [orderModalOpen, setOrderModalOpen] = useState(false);
    const [orderForm] = Form.useForm();
    const [customers, setCustomers] = useState<EcomCustomer[]>([]);
    const [lineItems, setLineItems] = useState<OrderLineItem[]>([]);
    const [lineKeyCounter, setLineKeyCounter] = useState(0);

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const [statsData, ordersData] = await Promise.all([
                inventoryService.getEcomStats(),
                inventoryService.getEcomOrders(),
            ]);
            setStats(statsData);
            setOrders(ordersData);
        } catch (err) { console.error(err); message.error("Failed to load orders"); } finally { setLoading(false); }
    };

    const viewOrder = async (order: EcomOrder) => {
        setSelectedOrder(order);
        setDrawerOpen(true);
        try {
            const items = await inventoryService.getEcomOrderItems(order.id);
            setOrderItems(items);
        } catch { setOrderItems([]); }
    };

    const handleStatusChange = async (id: string, newStatus: string) => {
        try {
            await inventoryService.updateEcomOrderStatus(id, newStatus);
            message.success(`Status â†’ ${newStatus}`);
            load();
        } catch { message.error("Failed to update status"); }
    };

    const handleDelete = async (id: string) => {
        try {
            await inventoryService.deleteEcomOrder(id);
            message.success("Order deleted");
            load();
        } catch { message.error("Failed to delete"); }
    };

    // â”€â”€â”€ New Order helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const openNewOrder = async () => {
        orderForm.resetFields();
        setLineItems([]);
        setLineKeyCounter(0);
        setOrderModalOpen(true);
        try {
            const c = await inventoryService.getEcomCustomers();
            setCustomers(c);
        } catch { setCustomers([]); }
    };

    const onCustomerChange = (customerId: string) => {
        const c = customers.find(x => x.id === customerId);
        if (c) {
            orderForm.setFieldsValue({
                customerName: `${c.firstName} ${c.lastName || ''}`.trim(),
                customerEmail: c.email,
                customerPhone: c.phone,
            });
        }
    };

    const addLineItem = () => {
        const key = lineKeyCounter + 1;
        setLineKeyCounter(key);
        setLineItems(prev => [...prev, { key, itemName: '', quantity: 1, unitPrice: 0, discount: 0, subtotal: 0 }]);
    };

    const removeLineItem = (key: number) => {
        setLineItems(prev => prev.filter(l => l.key !== key));
    };

    const updateLineItem = (key: number, updates: Partial<OrderLineItem>) => {
        setLineItems(prev => prev.map(l => {
            if (l.key !== key) return l;
            const updated = { ...l, ...updates };
            updated.subtotal = (updated.quantity * updated.unitPrice) - (updated.discount || 0);
            return updated;
        }));
    };

    const orderSubtotal = lineItems.reduce((sum, l) => sum + l.subtotal, 0);

    const handleCreateOrder = async () => {
        try {
            const values = await orderForm.validateFields();
            if (lineItems.length === 0) { message.warning('Add at least one line item'); return; }
            const shippingCost = values.shippingCost || 0;
            const order = await inventoryService.createEcomOrder('default', {
                orderNumber: values.orderNumber,
                customerId: values.customerId,
                customerName: values.customerName,
                customerEmail: values.customerEmail,
                customerPhone: values.customerPhone,
                shippingAddress: values.shippingAddress,
                shippingCity: values.shippingCity,
                shippingProvince: values.shippingProvince,
                shippingPostalCode: values.shippingPostalCode,
                shippingMethod: values.shippingMethod,
                shippingCost,
                subtotal: orderSubtotal,
                totalAmount: orderSubtotal + shippingCost,
                paymentMethod: values.paymentMethod,
                notes: values.notes,
                source: 'admin',
            } as any);
            // Add line items
            for (const l of lineItems) {
                await inventoryService.addEcomOrderItem(order.id, {
                    itemId: l.itemId,
                    itemName: l.itemName,
                    itemSku: l.itemSku,
                    quantity: l.quantity,
                    unitPrice: l.unitPrice,
                    discount: l.discount,
                    subtotal: l.subtotal,
                } as any);
            }
            message.success('Order created');
            setOrderModalOpen(false);
            load();
        } catch (e: any) {
            if (e.errorFields) return;
            message.error(e.message || 'Failed to create order');
        }
    };

    const kpiCards = [
        { title: 'Total Orders', value: stats?.totalOrders || 0, icon: <ShoppingCartOutlined />, color: themeColor },
        { title: 'Pending', value: stats?.pending || 0, icon: <ClockCircleOutlined />, color: '#94a3b8' },
        { title: 'Processing', value: stats?.processing || 0, icon: <InboxOutlined />, color: '#3b82f6' },
        { title: 'Shipped', value: stats?.shipped || 0, icon: <SendOutlined />, color: '#06b6d4' },
        { title: 'Completed', value: stats?.completed || 0, icon: <CheckCircleOutlined />, color: '#10b981' },
        { title: 'Revenue', value: fmtCurrency(stats?.totalRevenue), icon: <DollarOutlined />, color: '#f59e0b' },
    ];

    const TRANSITIONS: Record<string, { label: string; color: string; next: string }> = {
        pending: { label: 'Confirm', color: '#3b82f6', next: 'confirmed' },
        confirmed: { label: 'Process', color: themeColor, next: 'processing' },
        processing: { label: 'Ship', color: '#06b6d4', next: 'shipped' },
        shipped: { label: 'Delivered', color: '#10b981', next: 'delivered' },
        delivered: { label: 'Complete', color: '#059669', next: 'completed' },
    };

    const CANCELLABLE = new Set(['pending', 'confirmed', 'processing', 'shipped']);

    const filteredOrders = orders.filter(o => {
        if (statusFilter && o.status !== statusFilter) return false;
        if (search && !o.orderNumber?.toLowerCase().includes(search.toLowerCase()) && !o.customerName?.toLowerCase().includes(search.toLowerCase())) return false;
        return true;
    });

    const columns = [
        { title: 'Order #', dataIndex: 'orderNumber', width: 140, render: (v: string) => <Text code className="text-xs">{v}</Text> },
        { title: 'Customer', dataIndex: 'customerName', ellipsis: true, render: (v: string) => <Text strong className="text-sm">{v || 'â€”'}</Text> },
        { title: 'Total', dataIndex: 'totalAmount', width: 140, render: (v: number) => <Text strong style={{ color: themeColor }}>{fmtCurrency(v)}</Text> },
        { title: 'Payment', dataIndex: 'paymentStatus', width: 100,
            render: (v: string) => <Tag color={PAYMENT_COLORS[v] || 'default'} className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: 'Source', dataIndex: 'source', width: 80, render: (v: string) => <Tag className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: 'Date', dataIndex: 'createdAt', width: 100, render: (v: string) => v ? new Date(v).toLocaleDateString() : 'â€”' },
        { title: 'Status', dataIndex: 'status', width: 120,
            render: (v: string) => {
                const s = ORDER_STATUS[v] || { color: 'default', icon: null };
                return <Tag icon={s.icon} color={s.color} className="rounded-full text-xs capitalize">{v}</Tag>;
            },
        },
        { title: '', key: 'actions', width: 220,
            render: (_: any, r: EcomOrder) => {
                const action = TRANSITIONS[r.status || ''];
                const canCancel = CANCELLABLE.has(r.status || '');
                return (
                    <Space size="small">
                        <Button size="small" icon={<EyeOutlined />} onClick={() => viewOrder(r)} />
                        {action && (
                            <Button size="small" type="primary" onClick={() => handleStatusChange(r.id, action.next)}
                                style={{ background: action.color, border: 'none', fontSize: 11 }}>{action.label}</Button>
                        )}
                        {canCancel && (
                            <Button size="small" danger onClick={() => Modal.confirm({
                                title: 'Cancel this order?',
                                content: ['processing', 'shipped'].includes(r.status || '')
                                    ? 'Stock will be automatically restored for physical items.'
                                    : 'This order has not been processed yet.',
                                okText: 'Cancel Order',
                                okButtonProps: { danger: true },
                                onOk: () => handleStatusChange(r.id, 'cancelled'),
                            })} style={{ fontSize: 11 }}>Cancel</Button>
                        )}
                        <Button size="small" danger icon={<DeleteOutlined />}
                            onClick={() => Modal.confirm({ title: 'Delete order?', onOk: () => handleDelete(r.id) })} />
                    </Space>
                );
            },
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Orders</AuroraText>}
            subTitle={<DecryptedText text="Order management across all fulfillment types" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...glass,
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={{ flex: 1, ...glass, borderRadius: 12, border: '1px solid rgba(255,255,255,0.5)' }}>
                    <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                        <div className="flex items-center gap-3">
                            <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search orders..."
                                value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 240, borderRadius: 8 }} size="small" />
                            <Select placeholder="Status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 130 }} size="small"
                                options={Object.keys(ORDER_STATUS).map(k => ({ value: k, label: k.charAt(0).toUpperCase() + k.slice(1) }))} />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_orders', title: 'eCommerce Orders', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Order #', key: 'orderNumber' }, { header: 'Customer', key: 'customerName' }, { header: 'Total', key: 'totalAmount' }, { header: 'Payment', key: 'paymentStatus' }, { header: 'Status', key: 'status' }, { header: 'Date', key: 'createdAt' }], data: filteredOrders })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_orders', title: 'eCommerce Orders', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Order #', key: 'orderNumber' }, { header: 'Customer', key: 'customerName' }, { header: 'Total', key: 'totalAmount' }, { header: 'Payment', key: 'paymentStatus' }, { header: 'Status', key: 'status' }, { header: 'Date', key: 'createdAt' }], data: filteredOrders })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />} onClick={openNewOrder}
                                style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: 'none', borderRadius: 8 }}>
                                New Order
                            </Button>
                        </Space>
                    </div>
                    <Table dataSource={filteredOrders} columns={columns} rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false, showTotal: (t) => `${t} orders` }} scroll={{ x: 1100 }} />
                </Card>
            </div>

            {/* Order Detail Drawer */}
            <Drawer title={`Order ${selectedOrder?.orderNumber || ''}`} open={drawerOpen} onClose={() => setDrawerOpen(false)}
                width={560} styles={{ body: { padding: 16 } }}>
                {selectedOrder && (
                    <div className="space-y-4">
                        <Card size="small" style={{ borderRadius: 10 }}>
                            <Row gutter={16}>
                                <Col span={12}><Text type="secondary" className="text-xs block">Customer</Text><Text strong>{selectedOrder.customerName}</Text></Col>
                                <Col span={12}><Text type="secondary" className="text-xs block">Email</Text><Text>{selectedOrder.customerEmail || 'â€”'}</Text></Col>
                            </Row>
                            <Row gutter={16} className="mt-2">
                                <Col span={12}><Text type="secondary" className="text-xs block">Total</Text><Text strong style={{ color: themeColor, fontSize: 16 }}>{fmtCurrency(selectedOrder.totalAmount)}</Text></Col>
                                <Col span={12}><Text type="secondary" className="text-xs block">Payment</Text><Tag color={PAYMENT_COLORS[selectedOrder.paymentStatus || ''] || 'default'}>{selectedOrder.paymentStatus} ({selectedOrder.paymentMethod || 'â€”'})</Tag></Col>
                            </Row>
                            <Row gutter={16} className="mt-2">
                                <Col span={12}><Text type="secondary" className="text-xs block">Shipping</Text><Text>{selectedOrder.shippingMethod || 'â€”'} â†’ {selectedOrder.shippingCity || 'â€”'}</Text></Col>
                                <Col span={12}><Text type="secondary" className="text-xs block">Source</Text><Tag>{selectedOrder.source}</Tag></Col>
                            </Row>
                        </Card>

                        <Card size="small" title="Line Items" style={{ borderRadius: 10 }}>
                            <Table dataSource={orderItems} rowKey="id" size="small" pagination={false}
                                columns={[
                                    { title: 'Item', dataIndex: 'itemName', render: (v: string) => <Text strong className="text-sm">{v}</Text> },
                                    { title: 'Type', dataIndex: 'fulfillmentType', width: 80, render: (v: string) => <Tag color={FULFILLMENT_COLORS[v] || 'default'} className="text-xs capitalize">{v}</Tag> },
                                    { title: 'Qty', dataIndex: 'quantity', width: 50 },
                                    { title: 'Price', dataIndex: 'unitPrice', width: 110, render: (v: number) => fmtCurrency(v) },
                                    { title: 'Subtotal', dataIndex: 'subtotal', width: 120, render: (v: number) => <Text strong>{fmtCurrency(v)}</Text> },
                                    { title: 'Status', dataIndex: 'status', width: 90, render: (v: string) => <Tag className="text-xs capitalize">{v}</Tag> },
                                ]}
                            />
                        </Card>
                    </div>
                )}
            </Drawer>

            {/* â”€â”€â”€ New Order Modal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <Modal title="New Order" open={orderModalOpen} onCancel={() => setOrderModalOpen(false)}
                onOk={handleCreateOrder} okText="Create Order" width={720}>
                <Form form={orderForm} layout="vertical">
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="orderNumber" label="Order Number" rules={[{ required: true }]}>
                                <Input placeholder="ORD-2026-XXX" />
                            </Form.Item>
                        </Col>
                        <Col span={16}>
                            <Form.Item name="customerId" label="Customer">
                                <Select placeholder="Select customer (optional)" showSearch allowClear
                                    filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                                    onChange={onCustomerChange}
                                    options={customers.map(c => ({
                                        value: c.id, label: `${c.customerCode} â€” ${c.firstName} ${c.lastName || ''}`
                                    }))} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="customerName" label="Customer Name" rules={[{ required: true }]}>
                                <Input placeholder="Full name" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="customerEmail" label="Email">
                                <Input placeholder="email@example.com" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="customerPhone" label="Phone">
                                <Input placeholder="+62..." />
                            </Form.Item>
                        </Col>
                    </Row>

                    <Divider plain style={{ margin: '8px 0' }}>Line Items</Divider>
                    <div style={{ marginBottom: 12 }}>
                        {lineItems.map((line) => (
                            <div key={line.key} style={{ display: 'flex', gap: 8, marginBottom: 8, alignItems: 'center' }}>
                                <div style={{ flex: 3 }}>
                                    <ItemPicker
                                        onItemSelect={(item) => { if (item) updateLineItem(line.key, { itemId: item.id, itemName: item.name, itemSku: item.sku, unitPrice: item.sellingPrice || item.costPrice || 0 }); }}
                                    />
                                </div>
                                <InputNumber min={1} value={line.quantity} onChange={v => updateLineItem(line.key, { quantity: v || 1 })} style={{ width: 70 }} placeholder="Qty" />
                                <InputNumber min={0} value={line.unitPrice} onChange={v => updateLineItem(line.key, { unitPrice: v || 0 })} style={{ width: 120 }} prefix="Rp" placeholder="Price" />
                                <InputNumber min={0} value={line.discount} onChange={v => updateLineItem(line.key, { discount: v || 0 })} style={{ width: 100 }} prefix="-Rp" placeholder="Disc" />
                                <span style={{ width: 100, textAlign: 'right', fontWeight: 600, fontSize: 13 }}>
                                    {fmtCurrency(line.subtotal)}
                                </span>
                                <Button size="small" type="text" danger icon={<MinusCircleOutlined />} onClick={() => removeLineItem(line.key)} />
                            </div>
                        ))}
                        <Button type="dashed" onClick={addLineItem} icon={<PlusOutlined />} style={{ width: '100%' }}>
                            Add Item
                        </Button>
                    </div>

                    <Divider plain style={{ margin: '8px 0' }}>Shipping & Payment</Divider>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="shippingAddress" label="Address">
                                <Input placeholder="Street address" />
                            </Form.Item>
                        </Col>
                        <Col span={5}>
                            <Form.Item name="shippingCity" label="City">
                                <Input placeholder="City" />
                            </Form.Item>
                        </Col>
                        <Col span={5}>
                            <Form.Item name="shippingProvince" label="Province">
                                <Input placeholder="Province" />
                            </Form.Item>
                        </Col>
                        <Col span={6}>
                            <Form.Item name="shippingMethod" label="Shipping Method">
                                <Select placeholder="Select" allowClear options={[
                                    { value: 'standard', label: 'Standard' }, { value: 'express', label: 'Express' },
                                    { value: 'same_day', label: 'Same Day' }, { value: 'pickup', label: 'Pickup' },
                                ]} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={6}>
                            <Form.Item name="shippingCost" label="Shipping Cost">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" />
                            </Form.Item>
                        </Col>
                        <Col span={6}>
                            <Form.Item name="paymentMethod" label="Payment Method">
                                <Select placeholder="Select" allowClear options={[
                                    { value: 'bank_transfer', label: 'Bank Transfer' }, { value: 'cash', label: 'Cash' },
                                    { value: 'credit_card', label: 'Credit Card' }, { value: 'ewallet', label: 'E-Wallet' },
                                ]} />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="notes" label="Notes">
                                <Input.TextArea rows={1} placeholder="Order notes..." />
                            </Form.Item>
                        </Col>
                    </Row>
                    <div style={{ textAlign: 'right', fontSize: 16, fontWeight: 700, color: themeColor }}>
                        Subtotal: {fmtCurrency(orderSubtotal)} | Total: {fmtCurrency(orderSubtotal + (orderForm.getFieldValue('shippingCost') || 0))}
                    </div>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Tag, Card, Typography, Input, Space, Button, Tooltip, Row, Col, Drawer, message, Modal, Select, Form, InputNumber, Divider } from "antd";
import { GiftOutlined, SearchOutlined, ReloadOutlined, DollarOutlined, CheckCircleOutlined, EyeOutlined, DeleteOutlined, PlusOutlined, MinusCircleOutlined, ShoppingOutlined, EditOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { inventoryService, EcomPackage, EcomPackageItem, EcomPackageStatsType } from "@/lib/inventoryService";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { AuroraText } from "@/components/magicui/aurora-text";
import ItemPicker from "@/components/inventory/ItemPicker";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : 'â€”';

const PACKAGE_FIELDS: FieldDef[] = [
    { name: 'name', label: 'Package Name', required: true },
    { name: 'sku', label: 'SKU' },
    { name: 'status', label: 'Status' },
    { name: 'description', label: 'Description' },
    { name: 'packagePrice', label: 'Package Price', type: 'number', required: true },
    { name: 'regularPrice', label: 'Regular Price', type: 'number' },
    { name: 'notes', label: 'Notes' },
];

export default function PackagesPage() {
    const [stats, setStats] = useState<EcomPackageStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [packages, setPackages] = useState<EcomPackage[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [selected, setSelected] = useState<EcomPackage | null>(null);
    const [pkgItems, setPkgItems] = useState<EcomPackageItem[]>([]);
    const [drawerOpen, setDrawerOpen] = useState(false);
    const [modalOpen, setModalOpen] = useState(false);
    const [editMode, setEditMode] = useState(false);
    const [saving, setSaving] = useState(false);
    const [form] = Form.useForm();
    const [lineItems, setLineItems] = useState<{ key: number; itemId?: string; itemName: string; itemSku?: string; quantity: number; unitPrice: number }[]>([]);
    const [lineKey, setLineKey] = useState(0);

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const [s, p] = await Promise.all([
                inventoryService.getEcomPackageStats(),
                inventoryService.getEcomPackages(),
            ]);
            setStats(s);
            setPackages(p);
        } catch (err) { console.error(err); message.error("Failed to load packages"); } finally { setLoading(false); }
    };

    const viewPackage = async (pkg: EcomPackage) => {
        setSelected(pkg);
        setDrawerOpen(true);
        try {
            const items = await inventoryService.getEcomPackageItems(pkg.id);
            setPkgItems(items);
        } catch { setPkgItems([]); }
    };

    const handleDelete = async (id: string) => {
        try { await inventoryService.deleteEcomPackage(id); message.success("Package deleted"); load(); }
        catch { message.error("Failed to delete"); }
    };

    const openNew = () => { setEditMode(false); form.resetFields(); setLineItems([]); setLineKey(0); setModalOpen(true); };

    const openEdit = (pkg: EcomPackage) => {
        setEditMode(true);
        setSelected(pkg);
        form.setFieldsValue({ name: pkg.name, sku: pkg.sku, description: pkg.description, packagePrice: pkg.packagePrice, regularPrice: pkg.regularPrice, savings: pkg.savings, status: pkg.status, notes: pkg.notes });
        setLineItems([]);
        setModalOpen(true);
    };

    const addLine = () => { const k = lineKey + 1; setLineKey(k); setLineItems(p => [...p, { key: k, itemName: '', quantity: 1, unitPrice: 0 }]); };
    const removeLine = (k: number) => setLineItems(p => p.filter(l => l.key !== k));
    const updateLine = (k: number, u: any) => setLineItems(p => p.map(l => l.key !== k ? l : { ...l, ...u }));

    const calcRegular = () => lineItems.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0);

    const handleSave = async (values: any) => {
        setSaving(true);
        try {
            const regular = values.regularPrice || calcRegular();
            const pkg = values.packagePrice || 0;
            const input = {
                name: values.name, sku: values.sku, description: values.description,
                packagePrice: pkg, regularPrice: regular, savings: regular - pkg,
                notes: values.notes, status: values.status || 'active',
                items: lineItems.map(l => ({ itemId: l.itemId, itemName: l.itemName, itemSku: l.itemSku, quantity: l.quantity, unitPrice: l.unitPrice })),
            };
            if (editMode && selected) {
                await inventoryService.updateEcomPackage(selected.id, input as any);
                message.success('Package updated');
            } else {
                await inventoryService.createEcomPackage('default', input as any);
                message.success('Package created');
            }
            setModalOpen(false);
            form.resetFields();
            load();
        } catch (e: any) {
            message.error(e.message || 'Failed');
        } finally { setSaving(false); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createEcomPackage('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.name || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        load();
        return { success, failed, errors };
    };

    const kpiCards = [
        { title: 'Total Packages', value: stats?.totalPackages || 0, icon: <GiftOutlined />, color: themeColor },
        { title: 'Active', value: stats?.active || 0, icon: <CheckCircleOutlined />, color: '#10b981' },
        { title: 'Inactive', value: stats?.inactive || 0, icon: <GiftOutlined />, color: '#94a3b8' },
        { title: 'Total Sold', value: stats?.totalSold || 0, icon: <ShoppingOutlined />, color: '#3b82f6' },
        { title: 'Total Savings', value: fmtCurrency(stats?.totalSavings), icon: <DollarOutlined />, color: '#f59e0b' },
    ];

    const filtered = packages.filter(p => {
        if (statusFilter && p.status !== statusFilter) return false;
        if (search && !p.name?.toLowerCase().includes(search.toLowerCase()) && !p.sku?.toLowerCase().includes(search.toLowerCase())) return false;
        return true;
    });

    const columns = [
        { title: 'Package', dataIndex: 'name', render: (v: string, r: EcomPackage) => (<div><Text strong className="text-sm">{v}</Text>{r.sku && <Text type="secondary" className="text-xs block">{r.sku}</Text>}</div>) },
        { title: 'Package Price', dataIndex: 'packagePrice', width: 140, render: (v: number) => <Text strong style={{ color: themeColor }}>{fmtCurrency(v)}</Text> },
        { title: 'Regular Price', dataIndex: 'regularPrice', width: 140, render: (v: number) => <Text type="secondary" style={{ textDecoration: 'line-through' }}>{fmtCurrency(v)}</Text> },
        { title: 'Savings', dataIndex: 'savings', width: 120, render: (v: number) => <Tag color="green" className="rounded-full">{fmtCurrency(v)}</Tag> },
        { title: 'Sold', dataIndex: 'timesSold', width: 70, render: (v: number) => v || 0 },
        { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color={v === 'active' ? 'green' : 'default'} className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: '', key: 'actions', width: 130, render: (_: any, r: EcomPackage) => (
            <Space size="small">
                <Button size="small" icon={<EyeOutlined />} onClick={() => viewPackage(r)} />
                <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(r)} />
                <Button size="small" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: 'Delete package?', onOk: () => handleDelete(r.id) })} />
            </Space>
        )},
    ];

    const packageSteps = [
        {
            title: "Package Info",
            fields: ["name", "sku", "status", "description"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}><Form.Item name="name" label="Package Name" rules={[{ required: true }]}><Input placeholder="e.g. Snorkeling Adventure Bundle" /></Form.Item></Col>
                        <Col span={6}><Form.Item name="sku" label="SKU"><Input placeholder="PKG-XXX" /></Form.Item></Col>
                        <Col span={6}><Form.Item name="status" label="Status" initialValue="active">
                            <Select options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }]} />
                        </Form.Item></Col>
                    </Row>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} placeholder="Package description..." /></Form.Item>
                </>
            ),
        },
        {
            title: "Pricing",
            fields: ["packagePrice", "regularPrice", "notes"],
            content: (
                <Row gutter={16}>
                    <Col span={8}><Form.Item name="packagePrice" label="Package Price" rules={[{ required: true }]}><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                    <Col span={8}><Form.Item name="regularPrice" label="Regular Price"><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                    <Col span={8}><Form.Item name="notes" label="Notes"><Input.TextArea rows={1} /></Form.Item></Col>
                </Row>
            ),
        },
        {
            title: "Items",
            fields: [],
            content: (
                <>
                    {!editMode && (
                        <div style={{ marginBottom: 12 }}>
                            {lineItems.map(l => (
                                <div key={l.key} style={{ display: 'flex', gap: 8, marginBottom: 8, alignItems: 'center' }}>
                                    <div style={{ flex: 3 }}>
                                        <ItemPicker onItemSelect={(item) => { if (item) updateLine(l.key, { itemId: item.id, itemName: item.name, itemSku: item.sku, unitPrice: item.sellingPrice || item.costPrice || 0 }); }} />
                                    </div>
                                    <InputNumber min={1} value={l.quantity} onChange={v => updateLine(l.key, { quantity: v || 1 })} style={{ width: 70 }} />
                                    <InputNumber min={0} value={l.unitPrice} onChange={v => updateLine(l.key, { unitPrice: v || 0 })} style={{ width: 120 }} prefix="Rp" />
                                    <span style={{ width: 100, textAlign: 'right', fontWeight: 600, fontSize: 13 }}>{fmtCurrency(l.quantity * l.unitPrice)}</span>
                                    <Button size="small" type="text" danger icon={<MinusCircleOutlined />} onClick={() => removeLine(l.key)} />
                                </div>
                            ))}
                            <Button type="dashed" onClick={addLine} icon={<PlusOutlined />} style={{ width: '100%' }}>Add Item</Button>
                            {lineItems.length > 0 && (
                                <div style={{ textAlign: 'right', marginTop: 8, fontWeight: 700, color: themeColor }}>
                                    Regular Total: {fmtCurrency(calcRegular())}
                                </div>
                            )}
                        </div>
                    )}
                    {editMode && <Text type="secondary">Items cannot be edited here. View the package drawer for current items.</Text>}
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Packages</AuroraText>}
            subTitle={<DecryptedText text="Bundle products into packages with special pricing" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={Math.floor(24 / kpiCards.length)}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...glass,
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={{ flex: 1, ...glass, borderRadius: 12, border: '1px solid rgba(255,255,255,0.5)' }}>
                    <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                        <div className="flex items-center gap-3">
                            <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search packages..."
                                value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 240, borderRadius: 8 }} size="small" />
                            <Select placeholder="Status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 130 }} size="small"
                                options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }]} />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_packages', title: 'eCommerce Packages', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Price', key: 'price' }, { header: 'Status', key: 'status' }], data: packages })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_packages', title: 'eCommerce Packages', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Price', key: 'price' }, { header: 'Status', key: 'status' }], data: packages })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />} onClick={openNew}
                                style={{ background: 'linear-gradient(135deg, var(--theme-color, #8b5cf6), #a78bfa)', border: 'none', borderRadius: 8 }}>
                                New Package
                            </Button>
                        </Space>
                    </div>
                    <Table dataSource={filtered} columns={columns} rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false, showTotal: (t) => `${t} packages` }} scroll={{ x: 900 }} />
                </Card>
            </div>

            {/* Detail Drawer */}
            <Drawer title={`Package: ${selected?.name || ''}`} open={drawerOpen} onClose={() => setDrawerOpen(false)}
                width={520} styles={{ body: { padding: 16 } }}>
                {selected && (
                    <div className="space-y-4">
                        <Card size="small" style={{ borderRadius: 10 }}>
                            <Row gutter={16}>
                                <Col span={8}><Text type="secondary" className="text-xs block">Package Price</Text><Text strong style={{ color: themeColor, fontSize: 18 }}>{fmtCurrency(selected.packagePrice)}</Text></Col>
                                <Col span={8}><Text type="secondary" className="text-xs block">Regular Price</Text><Text style={{ textDecoration: 'line-through' }}>{fmtCurrency(selected.regularPrice)}</Text></Col>
                                <Col span={8}><Text type="secondary" className="text-xs block">Savings</Text><Tag color="green">{fmtCurrency(selected.savings)}</Tag></Col>
                            </Row>
                            {selected.description && <Text className="text-sm block mt-2">{selected.description}</Text>}
                        </Card>
                        <Card size="small" title="Package Contents" style={{ borderRadius: 10 }}>
                            <Table dataSource={pkgItems} rowKey="id" size="small" pagination={false}
                                columns={[
                                    { title: 'Item', dataIndex: 'itemName', render: (v: string) => <Text strong className="text-sm">{v}</Text> },
                                    { title: 'SKU', dataIndex: 'itemSku', width: 100, render: (v: string) => <Text code className="text-xs">{v || 'â€”'}</Text> },
                                    { title: 'Qty', dataIndex: 'quantity', width: 50 },
                                    { title: 'Unit Price', dataIndex: 'unitPrice', width: 120, render: (v: number) => fmtCurrency(v) },
                                ]}
                            />
                        </Card>
                    </div>
                )}
            </Drawer>

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditMode(false); form.resetFields(); setLineItems([]); }}
                onSubmit={handleSave}
                form={form}
                title={editMode ? "Edit Package" : "New Package"}
                entityName="package"
                steps={packageSteps}
                fields={PACKAGE_FIELDS}
                loading={saving}
                onBatchCreate={handleBatchCreate}
                gradient={["var(--theme-color, #8b5cf6)", "#a78bfa"]}
                editMode={editMode}
            />
        </CMSLayout>
    );
}

