                                        <div className="flex items-center gap-2 mt-1">
                                            <Text type="secondary" code className="text-xs">{detailDrawer.sku || 'No SKU'}</Text>
                                            <Tag color={STATUS_COLORS[detailDrawer.status || 'active']} className="rounded-full text-xs m-0">{detailDrawer.status}</Tag>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex gap-2 flex-wrap">
                                    <Tag color={ft?.color || 'blue'} className="rounded-full">{ft?.label || detailDrawer.fulfillmentType}</Tag>
                                    {detailDrawer.brand && <Tag className="rounded-full">ðŸ·ï¸ {detailDrawer.brand}</Tag>}
                                    {(detailDrawer.tags || []).map((t: string) => <Tag key={t} className="rounded-full text-xs">{t}</Tag>)}
                                </div>
                            </div>

                            <div style={{ padding: '16px 24px 24px' }}>
                                {/* Price Summary */}
                                <Row gutter={10} style={{ marginBottom: 16 }}>
                                    <Col span={8}>
                                        <Card size="small" style={{ borderRadius: 10, textAlign: 'center', background: isDark ? 'rgba(255,255,255,0.04)' : '#f9fafb' }}>
                                            <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Cost</Text>
                                            <Text strong style={{ fontSize: 14 }}>{fmtCurrency(detailDrawer.costPrice)}</Text>
                                        </Card>
                                    </Col>
                                    <Col span={8}>
                                        <Card size="small" style={{ borderRadius: 10, textAlign: 'center', background: isDark ? 'rgba(99,102,241,0.08)' : '#f0f0ff' }}>
                                            <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Sell</Text>
                                            <Text strong style={{ fontSize: 14, color: themeColor }}>{fmtCurrency(detailDrawer.sellingPrice)}</Text>
                                        </Card>
                                    </Col>
                                    <Col span={8}>
                                        <Card size="small" style={{ borderRadius: 10, textAlign: 'center', background: profit >= 0 ? (isDark ? 'rgba(34,197,94,0.08)' : '#f0fdf4') : (isDark ? 'rgba(239,68,68,0.08)' : '#fef2f2') }}>
                                            <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Margin</Text>
                                            <Text strong style={{ fontSize: 14, color: profit >= 0 ? '#16a34a' : '#dc2626' }}>
                                                {(detailDrawer.costPrice || 0) > 0 ? `${marginPct.toFixed(0)}%` : 'â€”'}
                                            </Text>
                                        </Card>
                                    </Col>
                                </Row>

                                {/* Details */}
                                <Descriptions column={2} size="small" bordered style={{ borderRadius: 10, marginBottom: 16 }}>
                                    <Descriptions.Item label="Type">{detailDrawer.itemType || 'â€”'}</Descriptions.Item>
                                    <Descriptions.Item label="Tax">{detailDrawer.taxRate || 0}%</Descriptions.Item>
                                    <Descriptions.Item label="Currency">{detailDrawer.currency || 'IDR'}</Descriptions.Item>
                                    <Descriptions.Item label="UOM">{detailDrawer.primaryUom || 'â€”'}</Descriptions.Item>
                                </Descriptions>

                                {detailDrawer.description && (
                                    <Card size="small" style={{ borderRadius: 10, background: '#fafafa', marginBottom: 16 }}>
                                        <Text type="secondary" className="text-xs uppercase tracking-wider block mb-1">Description</Text>
                                        <Paragraph className="!mb-0" style={{ fontSize: 13 }}>{detailDrawer.description}</Paragraph>
                                    </Card>
                                )}

                                {/* Type-specific metadata display */}
                                {detailDrawer.metadata && Object.keys(detailDrawer.metadata).length > 0 && (
                                    <Card size="small" style={{ borderRadius: 10, background: `${ft?.color || '#6366f1'}05`, border: `1px solid ${ft?.color || '#6366f1'}15`, marginBottom: 16 }}>
                                        <Text type="secondary" className="text-xs uppercase tracking-wider block mb-2">
                                            {detailDrawer.fulfillmentType === 'ticket' ? 'ðŸŽ« Event Info' : detailDrawer.fulfillmentType === 'scheduled' ? 'ðŸ—“ï¸ Route Info' : detailDrawer.fulfillmentType === 'rental' ? 'ðŸ”‘ Rental Info' : 'ðŸ“‹ Details'}
                                        </Text>
                                        <Descriptions column={2} size="small">
                                            {detailDrawer.metadata.venue && <Descriptions.Item label="Venue">{detailDrawer.metadata.venue}</Descriptions.Item>}
                                            {detailDrawer.metadata.eventDate && <Descriptions.Item label="Date">{detailDrawer.metadata.eventDate}</Descriptions.Item>}
                                            {detailDrawer.metadata.capacity && <Descriptions.Item label="Capacity">{detailDrawer.metadata.capacity}</Descriptions.Item>}
                                            {detailDrawer.metadata.origin && <Descriptions.Item label="Route">{detailDrawer.metadata.origin} â†’ {detailDrawer.metadata.destination}</Descriptions.Item>}
                                            {detailDrawer.metadata.durationMinutes && <Descriptions.Item label="Duration">{detailDrawer.metadata.durationMinutes} min</Descriptions.Item>}
                                            {detailDrawer.metadata.vehicleName && <Descriptions.Item label="Vehicle">{detailDrawer.metadata.vehicleName}</Descriptions.Item>}
                                            {detailDrawer.metadata.rentalPeriod && <Descriptions.Item label="Period"><Tag className="rounded-full text-xs capitalize">{detailDrawer.metadata.rentalPeriod}</Tag></Descriptions.Item>}
                                            {detailDrawer.metadata.depositAmount && <Descriptions.Item label="Deposit">{fmtCurrency(detailDrawer.metadata.depositAmount)}</Descriptions.Item>}
                                            {detailDrawer.metadata.condition && <Descriptions.Item label="Condition"><Tag className="rounded-full text-xs capitalize">{detailDrawer.metadata.condition}</Tag></Descriptions.Item>}
                                            {detailDrawer.metadata.seatSections?.length > 0 && <Descriptions.Item label="Sections" span={2}>{detailDrawer.metadata.seatSections.map((s: string) => <Tag key={s} className="rounded-full text-xs">{s}</Tag>)}</Descriptions.Item>}
                                        </Descriptions>
                                    </Card>
                                )}

                                <Divider style={{ margin: '12px 0' }} />
                                <div className="flex gap-2 flex-wrap">
                                    <Button type="primary" icon={<EditOutlined />} onClick={() => { setDetailDrawer(null); openEditModal(detailDrawer); }}
                                        style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: 'none', borderRadius: 8 }}>Edit Product</Button>
                                    <Button icon={<CopyOutlined />} onClick={() => { handleDuplicate(detailDrawer); setDetailDrawer(null); }}
                                        style={{ borderRadius: 8 }}>Duplicate</Button>
                                    <Button onClick={() => { setDetailDrawer(null); router.push('/admin/inventory/items'); }}
                                        style={{ borderRadius: 8 }}>Open in Item Master</Button>
                                    <Popconfirm title="Delete this product permanently?" onConfirm={() => handleDelete(detailDrawer.id)}>
                                        <Button danger icon={<DeleteOutlined />} style={{ borderRadius: 8 }}>Delete</Button>
                                    </Popconfirm>
                                </div>
                            </div>
                        </div>
                    );
                })()}
            </Drawer>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Tag, Card, Typography, Input, Space, Button, Tooltip, Row, Col, Drawer, message, Modal, Select, Form, InputNumber, Divider } from "antd";
import { RollbackOutlined, SearchOutlined, ReloadOutlined, DollarOutlined, CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, EyeOutlined, DeleteOutlined, PlusOutlined, MinusCircleOutlined , FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { inventoryService, EcomReturn, EcomReturnItem, EcomReturnStatsType, EcomOrder } from "@/lib/inventoryService";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { AuroraText } from "@/components/magicui/aurora-text";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const STATUS_CONFIG: Record<string, { color: string; icon: React.ReactNode }> = {
    requested: { color: 'orange', icon: <ClockCircleOutlined /> },
    approved: { color: 'blue', icon: <CheckCircleOutlined /> },
    received: { color: 'cyan', icon: <RollbackOutlined /> },
    completed: { color: 'green', icon: <CheckCircleOutlined /> },
    rejected: { color: 'red', icon: <CloseCircleOutlined /> },
};

const REASON_OPTIONS = [
    { value: 'changed_mind', label: 'Changed Mind' },
    { value: 'defective', label: 'Defective Product' },
    { value: 'wrong_item', label: 'Wrong Item Received' },
    { value: 'damaged', label: 'Damaged in Shipping' },
    { value: 'not_as_described', label: 'Not as Described' },
    { value: 'other', label: 'Other' },
];

const RESOLUTION_OPTIONS = [
    { value: 'refund', label: 'Full Refund' },
    { value: 'partial_refund', label: 'Partial Refund' },
    { value: 'exchange', label: 'Exchange' },
    { value: 'store_credit', label: 'Store Credit' },
];

const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : 'â€”';

const TRANSITIONS: Record<string, { label: string; color: string; next: string }> = {
    requested: { label: 'Approve', color: '#3b82f6', next: 'approved' },
    approved: { label: 'Mark Received', color: '#06b6d4', next: 'received' },
    received: { label: 'Complete', color: '#10b981', next: 'completed' },
};

const RETURN_FIELDS: FieldDef[] = [
    { name: 'orderId', label: 'Order', required: true },
    { name: 'orderNumber', label: 'Order Number' },
    { name: 'customerName', label: 'Customer' },
    { name: 'customerEmail', label: 'Email' },
    { name: 'reason', label: 'Reason', required: true },
    { name: 'resolution', label: 'Resolution', required: true },
    { name: 'refundMethod', label: 'Refund Method' },
    { name: 'refundAmount', label: 'Refund Amount', type: 'number' },
    { name: 'restockingFee', label: 'Restocking Fee', type: 'number' },
    { name: 'notes', label: 'Notes' },
];

export default function ReturnsPage() {
    const [stats, setStats] = useState<EcomReturnStatsType | null>(null);
    const [returns, setReturns] = useState<EcomReturn[]>([]);
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | undefined>();
    const [selected, setSelected] = useState<EcomReturn | null>(null);
    const [returnItems, setReturnItems] = useState<EcomReturnItem[]>([]);
    const [drawerOpen, setDrawerOpen] = useState(false);
    const [modalOpen, setModalOpen] = useState(false);
    const [saving, setSaving] = useState(false);
    const [form] = Form.useForm();
    const [orders, setOrders] = useState<EcomOrder[]>([]);
    const [lineItems, setLineItems] = useState<{ key: number; itemName: string; itemSku?: string; quantity: number; unitPrice: number; condition: string; restock: boolean }[]>([]);
    const [lineKey, setLineKey] = useState(0);

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const [s, r] = await Promise.all([
                inventoryService.getEcomReturnStats(),
                inventoryService.getEcomReturns(),
            ]);
            setStats(s);
            setReturns(r);
        } catch (err) { console.error(err); message.error("Failed to load returns"); } finally { setLoading(false); }
    };

    const viewReturn = async (ret: EcomReturn) => {
        setSelected(ret);
        setDrawerOpen(true);
        try {
            const items = await inventoryService.getEcomReturnItems(ret.id);
            setReturnItems(items);
        } catch { setReturnItems([]); }
    };

    const handleStatusChange = async (id: string, newStatus: string) => {
        try { await inventoryService.updateEcomReturnStatus(id, newStatus); message.success(`Status â†’ ${newStatus}`); load(); }
        catch { message.error("Failed to update status"); }
    };

    const handleDelete = async (id: string) => {
        try { await inventoryService.deleteEcomReturn(id); message.success("Return deleted"); load(); }
        catch { message.error("Failed to delete"); }
    };

    const openNewReturn = async () => {
        form.resetFields(); setLineItems([]); setLineKey(0); setModalOpen(true);
        try { const o = await inventoryService.getEcomOrders(); setOrders(o); } catch { setOrders([]); }
    };

    const onOrderChange = (orderId: string) => {
        const o = orders.find(x => x.id === orderId);
        if (o) { form.setFieldsValue({ orderNumber: o.orderNumber, customerName: o.customerName, customerEmail: o.customerEmail }); }
    };

    const addLine = () => { const k = lineKey + 1; setLineKey(k); setLineItems(p => [...p, { key: k, itemName: '', quantity: 1, unitPrice: 0, condition: 'unopened', restock: true }]); };
    const removeLine = (k: number) => setLineItems(p => p.filter(l => l.key !== k));
    const updateLine = (k: number, u: any) => setLineItems(p => p.map(l => l.key !== k ? l : { ...l, ...u }));

    const handleCreate = async (values: any) => {
        setSaving(true);
        try {
            if (!lineItems.length) { message.warning('Add at least one item'); setSaving(false); return; }
            const subtotal = lineItems.reduce((s, l) => s + l.quantity * l.unitPrice, 0);
            await inventoryService.createEcomReturn('default', {
                orderId: values.orderId, orderNumber: values.orderNumber,
                customerName: values.customerName, customerEmail: values.customerEmail,
                reason: values.reason, resolution: values.resolution,
                subtotal, refundAmount: values.refundAmount || subtotal,
                restockingFee: values.restockingFee || 0,
                refundMethod: values.refundMethod || 'original_payment',
                notes: values.notes, internalNotes: values.internalNotes,
                items: lineItems.map(l => ({ itemName: l.itemName, itemSku: l.itemSku, quantity: l.quantity, unitPrice: l.unitPrice, condition: l.condition, restock: l.restock })),
            } as any);
            message.success('Return created');
            setModalOpen(false);
            form.resetFields();
            load();
        } catch (e: any) {
            message.error(e.message || 'Failed');
        } finally { setSaving(false); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createEcomReturn('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.orderNumber || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        load();
        return { success, failed, errors };
    };

    const kpiCards = [
        { title: 'Total Returns', value: stats?.totalReturns || 0, icon: <RollbackOutlined />, color: '#f59e0b' },
        { title: 'Requested', value: stats?.requested || 0, icon: <ClockCircleOutlined />, color: '#f97316' },
        { title: 'Approved', value: stats?.approved || 0, icon: <CheckCircleOutlined />, color: '#3b82f6' },
        { title: 'Received', value: stats?.received || 0, icon: <RollbackOutlined />, color: '#06b6d4' },
        { title: 'Completed', value: stats?.completed || 0, icon: <CheckCircleOutlined />, color: '#10b981' },
        { title: 'Total Refunded', value: fmtCurrency(stats?.totalRefunded), icon: <DollarOutlined />, color: '#ef4444' },
    ];

    const filtered = returns.filter(r => {
        if (statusFilter && r.status !== statusFilter) return false;
        if (search && !r.returnNumber?.toLowerCase().includes(search.toLowerCase()) && !r.customerName?.toLowerCase().includes(search.toLowerCase())) return false;
        return true;
    });

    const columns = [
        { title: 'Return #', dataIndex: 'returnNumber', width: 140, render: (v: string) => <Text code className="text-xs">{v}</Text> },
        { title: 'Order', dataIndex: 'orderNumber', width: 130, render: (v: string) => <Text className="text-xs">{v || 'â€”'}</Text> },
        { title: 'Customer', dataIndex: 'customerName', ellipsis: true, render: (v: string) => <Text strong className="text-sm">{v || 'â€”'}</Text> },
        { title: 'Reason', dataIndex: 'reason', width: 130, render: (v: string) => <Tag className="rounded-full text-xs capitalize">{v?.replace(/_/g, ' ') || 'â€”'}</Tag> },
        { title: 'Refund', dataIndex: 'refundAmount', width: 130, render: (v: number) => <Text strong style={{ color: '#ef4444' }}>{fmtCurrency(v)}</Text> },
        { title: 'Refund Status', dataIndex: 'refundStatus', width: 110,
            render: (v: string) => <Tag color={v === 'refunded' ? 'green' : v === 'pending' ? 'orange' : 'default'} className="rounded-full text-xs capitalize">{v}</Tag> },
        { title: 'Date', dataIndex: 'createdAt', width: 100, render: (v: string) => v ? new Date(v).toLocaleDateString() : 'â€”' },
        { title: 'Status', dataIndex: 'status', width: 110,
            render: (v: string) => { const s = STATUS_CONFIG[v] || { color: 'default', icon: null }; return <Tag icon={s.icon} color={s.color} className="rounded-full text-xs capitalize">{v}</Tag>; }
        },
        { title: '', key: 'actions', width: 200,
            render: (_: any, r: EcomReturn) => {
                const action = TRANSITIONS[r.status || ''];
                return (
                    <Space size="small">
                        <Button size="small" icon={<EyeOutlined />} onClick={() => viewReturn(r)} />
                        {action && (
                            <Button size="small" type="primary" onClick={() => handleStatusChange(r.id, action.next)}
                                style={{ background: action.color, border: 'none', fontSize: 11 }}>{action.label}</Button>
                        )}
                        {r.status === 'requested' && (
                            <Button size="small" danger onClick={() => handleStatusChange(r.id, 'rejected')} style={{ fontSize: 11 }}>Reject</Button>
                        )}
                        <Button size="small" danger icon={<DeleteOutlined />}
                            onClick={() => Modal.confirm({ title: 'Delete return?', onOk: () => handleDelete(r.id) })} />
                    </Space>
                );
            },
        },
    ];

    const returnSteps = [
        {
            title: "Order",
            fields: ["orderId", "orderNumber", "customerName"],
            content: (
                <Row gutter={16}>
                    <Col span={12}>
                        <Form.Item name="orderId" label="Order" rules={[{ required: true }]}>
                            <Select placeholder="Select order" showSearch allowClear onChange={onOrderChange}
                                filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                                options={orders.map(o => ({ value: o.id, label: `${o.orderNumber} â€” ${o.customerName || ''}` }))} />
                        </Form.Item>
                    </Col>
                    <Col span={6}><Form.Item name="orderNumber" label="Order #"><Input disabled /></Form.Item></Col>
                    <Col span={6}><Form.Item name="customerName" label="Customer"><Input disabled /></Form.Item></Col>
                </Row>
            ),
        },
        {
            title: "Reason & Resolution",
            fields: ["reason", "resolution", "refundMethod", "refundAmount", "restockingFee", "notes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="reason" label="Reason" rules={[{ required: true }]}><Select options={REASON_OPTIONS} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="resolution" label="Resolution" rules={[{ required: true }]}><Select options={RESOLUTION_OPTIONS} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="refundMethod" label="Refund Method">
                            <Select options={[{ value: 'original_payment', label: 'Original Payment' }, { value: 'store_credit', label: 'Store Credit' }, { value: 'bank_transfer', label: 'Bank Transfer' }]} />
                        </Form.Item></Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}><Form.Item name="refundAmount" label="Refund Amount"><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="restockingFee" label="Restocking Fee"><InputNumber min={0} prefix="Rp" style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={8}><Form.Item name="notes" label="Notes"><Input.TextArea rows={1} /></Form.Item></Col>
                    </Row>
                </>
            ),
        },
        {
            title: "Return Items",
            fields: [],
            content: (
                <div style={{ marginBottom: 12 }}>
                    {lineItems.map(l => (
                        <div key={l.key} style={{ display: 'flex', gap: 8, marginBottom: 8, alignItems: 'center' }}>
                            <Input value={l.itemName} onChange={e => updateLine(l.key, { itemName: e.target.value })} placeholder="Item name" style={{ flex: 2 }} />
                            <InputNumber min={1} value={l.quantity} onChange={v => updateLine(l.key, { quantity: v || 1 })} style={{ width: 70 }} placeholder="Qty" />
                            <InputNumber min={0} value={l.unitPrice} onChange={v => updateLine(l.key, { unitPrice: v || 0 })} style={{ width: 120 }} prefix="Rp" />
                            <Select value={l.condition} onChange={v => updateLine(l.key, { condition: v })} style={{ width: 110 }}
                                options={[{ value: 'unopened', label: 'Unopened' }, { value: 'opened', label: 'Opened' }, { value: 'damaged', label: 'Damaged' }]} />
                            <Button size="small" type="text" danger icon={<MinusCircleOutlined />} onClick={() => removeLine(l.key)} />
                        </div>
                    ))}
                    <Button type="dashed" onClick={addLine} icon={<PlusOutlined />} style={{ width: '100%' }}>Add Item</Button>
                </div>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={["#f59e0b", "#ef4444", "#f97316", "#00ffff", "#ff00ff"]}>Returns</AuroraText>}
            subTitle={<DecryptedText text="Manage customer returns & refunds with auto-restocking" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...glass,
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                <Card size="small" style={{ flex: 1, ...glass, borderRadius: 12, border: '1px solid rgba(255,255,255,0.5)' }}>
                    <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                        <div className="flex items-center gap-3">
                            <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search returns..."
                                value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 240, borderRadius: 8 }} size="small" />
                            <Select placeholder="Status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 130 }} size="small"
                                options={Object.keys(STATUS_CONFIG).map(k => ({ value: k, label: k.charAt(0).toUpperCase() + k.slice(1) }))} />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ecommerce_returns', title: 'eCommerce Returns', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Return #', key: 'returnNumber' }, { header: 'Order #', key: 'orderNumber' }, { header: 'Reason', key: 'reason' }, { header: 'Status', key: 'status' }], data: returns })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ecommerce_returns', title: 'eCommerce Returns', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Return #', key: 'returnNumber' }, { header: 'Order #', key: 'orderNumber' }, { header: 'Reason', key: 'reason' }, { header: 'Status', key: 'status' }], data: returns })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />} onClick={openNewReturn}
                                style={{ background: 'linear-gradient(135deg, #f59e0b, #ef4444)', border: 'none', borderRadius: 8 }}>
                                New Return
                            </Button>
                        </Space>
                    </div>
                    <Table dataSource={filtered} columns={columns} rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false, showTotal: (t) => `${t} returns` }} scroll={{ x: 1200 }} />
                </Card>
            </div>

            <Drawer title={`Return ${selected?.returnNumber || ''}`} open={drawerOpen} onClose={() => setDrawerOpen(false)}
                width={520} styles={{ body: { padding: 16 } }}>
                {selected && (
                    <div className="space-y-4">
                        <Card size="small" style={{ borderRadius: 10 }}>
                            <Row gutter={16}>
                                <Col span={12}><Text type="secondary" className="text-xs block">Customer</Text><Text strong>{selected.customerName}</Text></Col>
                                <Col span={12}><Text type="secondary" className="text-xs block">Order</Text><Text code>{selected.orderNumber}</Text></Col>
                            </Row>
                            <Row gutter={16} className="mt-2">
                                <Col span={8}><Text type="secondary" className="text-xs block">Reason</Text><Tag className="capitalize">{selected.reason?.replace(/_/g, ' ')}</Tag></Col>
                                <Col span={8}><Text type="secondary" className="text-xs block">Resolution</Text><Tag color="blue" className="capitalize">{selected.resolution?.replace(/_/g, ' ')}</Tag></Col>
                                <Col span={8}><Text type="secondary" className="text-xs block">Refund</Text><Text strong style={{ color: '#ef4444' }}>{fmtCurrency(selected.refundAmount)}</Text></Col>
                            </Row>
                        </Card>
                        <Card size="small" title="Return Items" style={{ borderRadius: 10 }}>
                            <Table dataSource={returnItems} rowKey="id" size="small" pagination={false}
                                columns={[
                                    { title: 'Item', dataIndex: 'itemName', render: (v: string) => <Text strong className="text-sm">{v}</Text> },
                                    { title: 'Qty', dataIndex: 'quantity', width: 50 },
                                    { title: 'Price', dataIndex: 'unitPrice', width: 110, render: (v: number) => fmtCurrency(v) },
                                    { title: 'Condition', dataIndex: 'condition', width: 100, render: (v: string) => <Tag className="text-xs capitalize">{v}</Tag> },
                                    { title: 'Restock', dataIndex: 'restock', width: 70, render: (v: boolean) => <Tag color={v ? 'green' : 'red'}>{v ? 'Yes' : 'No'}</Tag> },
                                ]}
                            />
                        </Card>
                    </div>
                )}
            </Drawer>

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); form.resetFields(); setLineItems([]); }}
                onSubmit={handleCreate}
                form={form}
                title="New Return Request"
                entityName="return"
                steps={returnSteps}
                fields={RETURN_FIELDS}
                loading={saving}
                onBatchCreate={handleBatchCreate}
                gradient={["#f59e0b", "#ef4444"]}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { Card, Typography, Input, Space, Button, Tag, Row, Col, Segmented, Table, message, Select, Tooltip, theme } from "antd";
import { StarOutlined, SearchOutlined, ReloadOutlined, CheckCircleOutlined, CloseCircleOutlined, FlagOutlined, LikeOutlined, WarningOutlined, SafetyCertificateOutlined } from "@ant-design/icons";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { AuroraText } from "@/components/magicui/aurora-text";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { supaRest, supaUpdate } from "@/lib/supaRest";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, ReferenceLine } from "recharts";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Review {
    id: string; product_id: string; product_name: string; customer_id: string;
    customer_name: string; customer_email: string; rating: number; title: string;
    content: string; status: string; is_verified_purchase: boolean; helpful_count: number;
    report_count: number; admin_response: string; created_at: string; updated_at: string;
}

const RATING_COLORS: Record<number, string> = { 5: '#22c55e', 4: '#84cc16', 3: '#eab308', 2: '#f97316', 1: '#ef4444' };
const STATUS_TABS = ['All', 'Pending', 'Approved', 'Rejected', 'Flagged'];
const SORT_OPTIONS = [
    { value: 'newest', label: 'Newest' }, { value: 'oldest', label: 'Oldest' },
    { value: 'highest', label: 'Highest Rating' }, { value: 'lowest', label: 'Lowest Rating' },
    { value: 'reported', label: 'Most Reported' },
];

const Stars = ({ rating, size = 14 }: { rating: number; size?: number }) => (
    <span style={{ fontSize: size, letterSpacing: 1 }}>
        {[1, 2, 3, 4, 5].map(i => (
            <span key={i} style={{ color: i <= rating ? RATING_COLORS[rating] || '#eab308' : '#d1d5db' }}>★</span>
        ))}
    </span>
);

export default function ReviewsPage() {
    const [reviews, setReviews] = useState<Review[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusTab, setStatusTab] = useState('All');
    const [sortBy, setSortBy] = useState('newest');
    const [search, setSearch] = useState('');
    const [productFilter, setProductFilter] = useState<string | undefined>();
    const [ratingFilter, setRatingFilter] = useState<number[]>([]);
    const [visibleCount, setVisibleCount] = useState(10);
    const [expanded, setExpanded] = useState<Set<string>>(new Set());
    const [replyInputs, setReplyInputs] = useState<Record<string, string>>({});
    const [replyLoading, setReplyLoading] = useState<string | null>(null);
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');

    useEffect(() => { load(); }, []);

    const load = async () => {
        setLoading(true);
        try {
            const data = await supaRest<Review[]>('ecommerce_reviews', { order: 'created_at.desc' });
            setReviews(data);
        } catch (e) { console.error(e); message.error('Failed to load reviews'); }
        finally { setLoading(false); }
    };

    const handleStatus = async (id: string, status: string) => {
        try {
            await supaUpdate('ecommerce_reviews', id, { status, updated_at: new Date().toISOString() });
            message.success(`Review ${status}`);
            setReviews(prev => prev.map(r => r.id === id ? { ...r, status } : r));
        } catch { message.error('Failed to update'); }
    };

    const handleReply = async (id: string) => {
        const text = replyInputs[id]?.trim();
        if (!text) return;
        setReplyLoading(id);
        try {
            await supaUpdate('ecommerce_reviews', id, { admin_response: text, updated_at: new Date().toISOString() });
            message.success('Reply sent');
            setReviews(prev => prev.map(r => r.id === id ? { ...r, admin_response: text } : r));
            setReplyInputs(prev => ({ ...prev, [id]: '' }));
        } catch { message.error('Failed to reply'); }
        finally { setReplyLoading(null); }
    };

    // === Stats ===
    const stats = useMemo(() => {
        const total = reviews.length;
        const avg = total ? reviews.reduce((s, r) => s + r.rating, 0) / total : 0;
        const pending = reviews.filter(r => r.status === 'pending').length;
        const approved = reviews.filter(r => r.status === 'approved').length;
        const rejected = reviews.filter(r => r.status === 'rejected').length;
        return { total, avg, pending, approved, rejected };
    }, [reviews]);

    // === Rating distribution ===
    const ratingDist = useMemo(() => {
        const counts = [0, 0, 0, 0, 0];
        reviews.forEach(r => { if (r.rating >= 1 && r.rating <= 5) counts[r.rating - 1]++; });
        const total = reviews.length || 1;
        return [5, 4, 3, 2, 1].map(star => ({ star, count: counts[star - 1], pct: Math.round((counts[star - 1] / total) * 100) }));
    }, [reviews]);

    // === Rating trend (12 months) ===
    const trendData = useMemo(() => {
        const map: Record<string, { sum: number; cnt: number }> = {};
        reviews.forEach(r => {
            if (!r.created_at) return;
            const d = new Date(r.created_at);
            const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
            if (!map[key]) map[key] = { sum: 0, cnt: 0 };
            map[key].sum += r.rating; map[key].cnt++;
        });
        return Object.entries(map).sort(([a], [b]) => a.localeCompare(b)).slice(-12)
            .map(([month, { sum, cnt }]) => ({ month, avg: +(sum / cnt).toFixed(2) }));
    }, [reviews]);

    // === Top reviewed products ===
    const topProducts = useMemo(() => {
        const map: Record<string, { name: string; count: number; sum: number; positive: number; latest: string }> = {};
        reviews.forEach(r => {
            const k = r.product_id || r.product_name;
            if (!map[k]) map[k] = { name: r.product_name, count: 0, sum: 0, positive: 0, latest: '' };
            map[k].count++; map[k].sum += r.rating;
            if (r.rating >= 4) map[k].positive++;
            if (!map[k].latest || r.created_at > map[k].latest) map[k].latest = r.created_at;
        });
        return Object.entries(map).map(([id, v]) => ({ id, ...v, avg: +(v.sum / v.count).toFixed(1), positivePct: Math.round((v.positive / v.count) * 100) }))
            .sort((a, b) => b.count - a.count).slice(0, 10);
    }, [reviews]);

    // === Sentiment ===
    const sentiment = useMemo(() => {
        const pos = reviews.filter(r => r.rating >= 4).length;
        const neu = reviews.filter(r => r.rating === 3).length;
        const neg = reviews.filter(r => r.rating <= 2).length;
        const t = reviews.length || 1;
        return { pos, neu, neg, posPct: Math.round((pos / t) * 100), neuPct: Math.round((neu / t) * 100), negPct: Math.round((neg / t) * 100) };
    }, [reviews]);

    // === Filtered reviews ===
    const productOptions = useMemo(() => {
        const set = new Map<string, string>();
        reviews.forEach(r => set.set(r.product_id || r.product_name, r.product_name));
        return Array.from(set.entries()).map(([v, l]) => ({ value: v, label: l }));
    }, [reviews]);

    const filtered = useMemo(() => {
        let list = [...reviews];
        if (statusTab !== 'All') list = list.filter(r => r.status === statusTab.toLowerCase());
        if (productFilter) list = list.filter(r => (r.product_id || r.product_name) === productFilter);
        if (ratingFilter.length) list = list.filter(r => ratingFilter.includes(r.rating));
        if (search) list = list.filter(r => r.content?.toLowerCase().includes(search.toLowerCase()) || r.title?.toLowerCase().includes(search.toLowerCase()) || r.customer_name?.toLowerCase().includes(search.toLowerCase()));
        switch (sortBy) {
            case 'oldest': list.sort((a, b) => (a.created_at || '').localeCompare(b.created_at || '')); break;
            case 'highest': list.sort((a, b) => b.rating - a.rating); break;
            case 'lowest': list.sort((a, b) => a.rating - b.rating); break;
            case 'reported': list.sort((a, b) => (b.report_count || 0) - (a.report_count || 0)); break;
            default: list.sort((a, b) => (b.created_at || '').localeCompare(a.created_at || ''));
        }
        return list;
    }, [reviews, statusTab, productFilter, ratingFilter, search, sortBy]);

    const kpiCards = [
        { title: 'Total Reviews', value: stats.total, icon: <StarOutlined />, color: themeColor },
        { title: 'Avg Rating', value: stats.avg.toFixed(1), icon: <Stars rating={Math.round(stats.avg)} size={12} />, color: '#eab308', extra: <Stars rating={Math.round(stats.avg)} size={11} /> },
        { title: 'Pending', value: stats.pending, icon: <WarningOutlined />, color: '#f97316' },
        { title: 'Approved', value: stats.approved, icon: <CheckCircleOutlined />, color: '#22c55e' },
        { title: 'Rejected', value: stats.rejected, icon: <CloseCircleOutlined />, color: '#ef4444' },
    ];

    const borderForStatus = (s: string) => s === 'approved' ? '2px solid rgba(34,197,94,0.35)' : s === 'flagged' ? '2px solid #f97316' : s === 'rejected' ? '1px solid rgba(239,68,68,0.25)' : '1px solid rgba(255,255,255,0.45)';

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#eab308', '#f97316', '#22c55e']}>Reviews & Ratings</AuroraText>}
            subTitle={<DecryptedText text="Product review moderation & analytics" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {/* KPI Cards */}
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4} lg={4}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={glass}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center" style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>{s.icon}</div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                            {s.extra && <div style={{ marginTop: -2 }}>{s.extra}</div>}
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Rating Distribution + Sentiment + Trend */}
                <Row gutter={[14, 14]}>
                    <Col xs={24} md={8}>
                        <Card size="small" style={glass} title={<Text strong style={{ fontSize: 13 }}>⭐ Rating Distribution</Text>}>
                            <div style={{ textAlign: 'center', marginBottom: 10 }}>
                                <Text strong style={{ fontSize: 28, color: RATING_COLORS[Math.round(stats.avg)] || '#eab308' }}>{stats.avg.toFixed(1)}</Text>
                                <div><Stars rating={Math.round(stats.avg)} size={18} /></div>
                                <Text type="secondary" style={{ fontSize: 11 }}>{stats.total} reviews</Text>
                            </div>
                            {ratingDist.map(d => (
                                <div key={d.star} style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
                                    <Text style={{ fontSize: 12, width: 28 }}>{d.star}★</Text>
                                    <div style={{ flex: 1, height: 10, background: isDark ? 'rgba(255,255,255,0.06)' : '#f3f4f6', borderRadius: 5, overflow: 'hidden' }}>
                                        <motion.div initial={{ width: 0 }} animate={{ width: `${d.pct}%` }} transition={{ delay: 0.2, duration: 0.6 }}
                                            style={{ height: '100%', background: RATING_COLORS[d.star], borderRadius: 5 }} />
                                    </div>
                                    <Text style={{ fontSize: 11, width: 50, textAlign: 'right' }}>{d.count} ({d.pct}%)</Text>
                                </div>
                            ))}
                        </Card>
                    </Col>
                    <Col xs={24} md={8}>
                        <Card size="small" style={glass} title={<Text strong style={{ fontSize: 13 }}>💬 Sentiment Summary</Text>}>
                            <div style={{ display: 'flex', height: 18, borderRadius: 9, overflow: 'hidden', marginBottom: 12 }}>
                                {sentiment.posPct > 0 && <div style={{ width: `${sentiment.posPct}%`, background: '#22c55e' }} />}
                                {sentiment.neuPct > 0 && <div style={{ width: `${sentiment.neuPct}%`, background: '#eab308' }} />}
                                {sentiment.negPct > 0 && <div style={{ width: `${sentiment.negPct}%`, background: '#ef4444' }} />}
                            </div>
                            {[
                                { label: 'Positive (4-5★)', value: sentiment.pos, pct: sentiment.posPct, color: '#22c55e' },
                                { label: 'Neutral (3★)', value: sentiment.neu, pct: sentiment.neuPct, color: '#eab308' },
                                { label: 'Negative (1-2★)', value: sentiment.neg, pct: sentiment.negPct, color: '#ef4444' },
                            ].map(s => (
                                <div key={s.label} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '6px 0' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                        <div style={{ width: 10, height: 10, borderRadius: 3, background: s.color }} />
                                        <Text style={{ fontSize: 12 }}>{s.label}</Text>
                                    </div>
                                    <Text strong style={{ fontSize: 12, color: s.color }}>{s.value} ({s.pct}%)</Text>
                                </div>
                            ))}
                        </Card>
                    </Col>
                    <Col xs={24} md={8}>
                        <Card size="small" style={glass} title={<Text strong style={{ fontSize: 13 }}>📈 Rating Trend</Text>}>
                            {trendData.length >= 2 ? (
                                <ResponsiveContainer width="100%" height={150}>
                                    <LineChart data={trendData}>
                                        <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'} />
                                        <XAxis dataKey="month" tick={{ fontSize: 10 }} />
                                        <YAxis domain={[0, 5]} tick={{ fontSize: 10 }} />
                                        <RTooltip />
                                        <ReferenceLine y={4} stroke="#f59e0b" strokeDasharray="4 4" label={{ value: 'Target', fontSize: 10, fill: '#f59e0b' }} />
                                        <Line type="monotone" dataKey="avg" stroke={themeColor} strokeWidth={2} dot={{ fill: themeColor, r: 3 }} />
                                    </LineChart>
                                </ResponsiveContainer>
                            ) : <Text type="secondary" style={{ fontSize: 12 }}>Not enough data for trend</Text>}
                        </Card>
                    </Col>
                </Row>

                {/* Top Reviewed Products */}
                <Card size="small" style={glass} title={<Text strong style={{ fontSize: 13 }}>🏆 Top Reviewed Products</Text>}>
                    <Table dataSource={topProducts} rowKey="id" size="small" pagination={false} scroll={{ x: 600 }}
                        onRow={r => ({ onClick: () => setProductFilter(r.id), style: { cursor: 'pointer' } })}
                        columns={[
                            { title: 'Product', dataIndex: 'name', ellipsis: true, render: (v: string) => <Text strong className="text-sm">{v || '—'}</Text> },
                            { title: 'Reviews', dataIndex: 'count', width: 80, sorter: (a: any, b: any) => a.count - b.count },
                            { title: 'Avg Rating', dataIndex: 'avg', width: 120, render: (v: number) => <><Stars rating={Math.round(v)} size={12} /> <Text style={{ fontSize: 11 }}>{v}</Text></> },
                            { title: 'Positive %', dataIndex: 'positivePct', width: 100, render: (v: number) => <Tag color={v >= 70 ? 'green' : v >= 40 ? 'orange' : 'red'} className="rounded-full text-xs">{v}%</Tag> },
                            { title: 'Latest', dataIndex: 'latest', width: 100, render: (v: string) => <Text className="text-xs">{v ? new Date(v).toLocaleDateString() : '—'}</Text> },
                        ]}
                    />
                </Card>

                {/* Moderation Queue */}
                <Card size="small" style={{ ...glass, borderRadius: 12 }}>
                    <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                        <div className="flex items-center gap-3 flex-wrap">
                            <Segmented options={STATUS_TABS} value={statusTab} onChange={v => { setStatusTab(v as string); setVisibleCount(10); }} size="small" />
                            <Input prefix={<SearchOutlined className="text-gray-400" />} placeholder="Search reviews..." value={search}
                                onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 200, borderRadius: 8 }} size="small" />
                        </div>
                        <Space>
                            <Select placeholder="Product" allowClear value={productFilter} onChange={setProductFilter}
                                showSearch filterOption={(input, opt) => (opt?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                                options={productOptions} style={{ minWidth: 150 }} size="small" />
                            <Select placeholder="Rating" allowClear mode="multiple" value={ratingFilter} onChange={setRatingFilter}
                                options={[5, 4, 3, 2, 1].map(r => ({ value: r, label: `${r}★` }))} style={{ minWidth: 100 }} size="small" />
                            <Select value={sortBy} onChange={setSortBy} options={SORT_OPTIONS} style={{ width: 140 }} size="small" />
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={load} size="small" /></Tooltip>
                        </Space>
                    </div>

                    <Text type="secondary" style={{ fontSize: 11, marginBottom: 8, display: 'block' }}>{filtered.length} review{filtered.length !== 1 ? 's' : ''}</Text>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                        <AnimatePresence>
                            {filtered.slice(0, visibleCount).map((r, i) => {
                                const isExpanded = expanded.has(r.id);
                                const contentShort = r.content?.length > 180 && !isExpanded;
                                return (
                                    <motion.div key={r.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ delay: i * 0.03 }}>
                                        <Card size="small" style={{
                                            ...glass, borderLeft: `4px solid ${RATING_COLORS[r.rating] || '#d1d5db'}`,
                                            border: borderForStatus(r.status),
                                            borderLeftWidth: 4, borderLeftColor: RATING_COLORS[r.rating] || '#d1d5db',
                                            opacity: r.status === 'rejected' ? 0.6 : 1,
                                            boxShadow: r.status === 'approved' ? `0 0 12px ${RATING_COLORS[r.rating]}15` : undefined,
                                        }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' }}>
                                                <div style={{ flex: 1, minWidth: 200 }}>
                                                    <div className="flex items-center gap-2 flex-wrap">
                                                        <Text strong style={{ fontSize: 13 }}>{r.customer_name || 'Anonymous'}</Text>
                                                        {r.is_verified_purchase && <Tag color="blue" className="rounded-full text-xs" icon={<SafetyCertificateOutlined />}>Verified</Tag>}
                                                        <Stars rating={r.rating} size={13} />
                                                        <Tag className="rounded-full text-xs" style={{ margin: 0 }}>{r.product_name}</Tag>
                                                    </div>
                                                    {r.title && <Text strong style={{ fontSize: 13, display: 'block', marginTop: 4 }}>{r.title}</Text>}
                                                    <Text style={{ fontSize: 12, display: 'block', marginTop: 2, lineHeight: 1.5 }}>
                                                        {contentShort ? r.content.slice(0, 180) + '...' : r.content}
                                                        {r.content?.length > 180 && (
                                                            <Button type="link" size="small" style={{ padding: '0 4px', fontSize: 11 }}
                                                                onClick={() => setExpanded(prev => { const n = new Set(prev); isExpanded ? n.delete(r.id) : n.add(r.id); return n; })}>
                                                                {isExpanded ? 'Show less' : 'Read more'}
                                                            </Button>
                                                        )}
                                                    </Text>
                                                    <div className="flex items-center gap-3 mt-1">
                                                        <Text type="secondary" style={{ fontSize: 10 }}>{r.created_at ? new Date(r.created_at).toLocaleDateString() : '—'}</Text>
                                                        {(r.helpful_count || 0) > 0 && <Text type="secondary" style={{ fontSize: 10 }}><LikeOutlined /> {r.helpful_count}</Text>}
                                                        {(r.report_count || 0) > 0 && <Text type="secondary" style={{ fontSize: 10, color: '#f97316' }}><FlagOutlined /> {r.report_count}</Text>}
                                                        <Tag color={r.status === 'approved' ? 'green' : r.status === 'rejected' ? 'red' : r.status === 'flagged' ? 'orange' : 'default'} className="rounded-full text-xs capitalize">{r.status}</Tag>
                                                    </div>
                                                </div>
                                                <Space size={4} wrap>
                                                    {r.status !== 'approved' && <Button size="small" type="primary" icon={<CheckCircleOutlined />} onClick={() => handleStatus(r.id, 'approved')}
                                                        style={{ background: '#22c55e', border: 'none', fontSize: 11, borderRadius: 6 }}>Approve</Button>}
                                                    {r.status !== 'rejected' && <Button size="small" danger icon={<CloseCircleOutlined />} onClick={() => handleStatus(r.id, 'rejected')}
                                                        style={{ fontSize: 11, borderRadius: 6 }}>Reject</Button>}
                                                    {r.status !== 'flagged' && <Button size="small" icon={<FlagOutlined />} onClick={() => handleStatus(r.id, 'flagged')}
                                                        style={{ color: '#f97316', borderColor: '#f97316', fontSize: 11, borderRadius: 6 }}>Flag</Button>}
                                                </Space>
                                            </div>
                                            {/* Admin response */}
                                            {r.admin_response && (
                                                <div style={{ marginTop: 8, padding: '8px 12px', borderRadius: 8, background: isDark ? 'rgba(59,130,246,0.08)' : '#eff6ff', borderLeft: '3px solid #3b82f6' }}>
                                                    <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Admin Response</Text>
                                                    <Text style={{ fontSize: 12 }}>{r.admin_response}</Text>
                                                </div>
                                            )}
                                            {!r.admin_response && (
                                                <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
                                                    <Input size="small" placeholder="Write admin response..." value={replyInputs[r.id] || ''}
                                                        onChange={e => setReplyInputs(prev => ({ ...prev, [r.id]: e.target.value }))}
                                                        onPressEnter={() => handleReply(r.id)} style={{ borderRadius: 6, flex: 1 }} />
                                                    <Button size="small" type="primary" loading={replyLoading === r.id} onClick={() => handleReply(r.id)}
                                                        disabled={!replyInputs[r.id]?.trim()} style={{ borderRadius: 6, fontSize: 11 }}>Reply</Button>
                                                </div>
                                            )}
                                        </Card>
                                    </motion.div>
                                );
                            })}
                        </AnimatePresence>
                    </div>

                    {visibleCount < filtered.length && (
                        <div style={{ textAlign: 'center', marginTop: 12 }}>
                            <Button onClick={() => setVisibleCount(prev => prev + 10)} style={{ borderRadius: 8 }}>
                                Load More ({filtered.length - visibleCount} remaining)
                            </Button>
                        </div>
                    )}
                    {filtered.length === 0 && !loading && (
                        <div style={{ textAlign: 'center', padding: 40 }}>
                            <Text type="secondary">No reviews found</Text>
                        </div>
                    )}
                </Card>
            </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
