];

const CATEGORIES = ['all', 'kpi', 'survey', 'checklist', 'audit', 'assessment'];
const MODULES = ['all', 'HR', 'CRM', 'PM', 'ITSM'];

export default function FormLibraryPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [messageApi, contextHolder] = message.useMessage();
    const [search, setSearch] = useState('');
    const [category, setCategory] = useState('all');
    const [module, setModule] = useState('all');
    const [previewId, setPreviewId] = useState<string | null>(null);

    const filtered = LIBRARY.filter(t => {
        if (category !== 'all' && t.category !== category) return false;
        if (module !== 'all' && t.module !== module) return false;
        if (search && !t.name.toLowerCase().includes(search.toLowerCase()) && !t.tags.some(tag => tag.includes(search.toLowerCase()))) return false;
        return true;
    });

    const popular = LIBRARY.filter(t => t.popular);
    const preview = LIBRARY.find(t => t.id === previewId);

    const handleInstall = (tpl: Template) => {
        messageApi.success(`"${tpl.name}" template installed! Redirecting to builder...`);
        setTimeout(() => router.push('/admin/forms/builder'), 1000);
    };

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#8b5cf6', '#ec4899']}>Template Library</AuroraText>}
            subTitle={<DecryptedText text="Pre-built form templates — install with one click" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <Button key="custom" type="primary" icon={<FormOutlined />} onClick={() => router.push('/admin/forms/builder')}
                    style={{ background: themeColor, borderColor: themeColor }}>Build Custom</Button>,
            ]}
        >
            {contextHolder}
            <div style={{ maxWidth: 1200, margin: '0 auto' }}>
                {/* Search & Filter */}
                <Card style={{ ...glass, marginBottom: 16 }} bodyStyle={{ padding: '12px 16px' }}>
                    <Space wrap>
                        <Input prefix={<SearchOutlined />} placeholder="Search templates..." value={search} onChange={e => setSearch(e.target.value)}
                            style={{ width: 240 }} allowClear />
                        <Select value={category} onChange={setCategory} style={{ width: 140 }}
                            options={CATEGORIES.map(c => ({ value: c, label: c === 'all' ? 'All Categories' : c.charAt(0).toUpperCase() + c.slice(1) }))} />
                        <Select value={module} onChange={setModule} style={{ width: 120 }}
                            options={MODULES.map(m => ({ value: m, label: m === 'all' ? 'All Modules' : m }))} />
                        <Text type="secondary" style={{ fontSize: 11 }}>{filtered.length} templates</Text>
                    </Space>
                </Card>

                {/* Popular Row (only when no filters) */}
                {category === 'all' && module === 'all' && !search && (
                    <div style={{ marginBottom: 16 }}>
                        <Space style={{ marginBottom: 8 }}>
                            <StarFilled style={{ color: '#f59e0b' }} />
                            <Text strong style={{ fontSize: 13 }}>Popular Templates</Text>
                        </Space>
                        <Row gutter={[12, 12]}>
                            {popular.map((tpl, i) => (
                                <Col xs={24} sm={12} md={6} key={tpl.id}>
                                    <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                        <Card hoverable size="small" style={{ borderRadius: 12, borderTop: `3px solid ${tpl.color}`, cursor: 'pointer' }}
                                            onClick={() => setPreviewId(tpl.id)}>
                                            <Space align="start">
                                                <div style={{ width: 32, height: 32, borderRadius: 8, background: `${tpl.color}15`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, color: tpl.color }}>
                                                    {tpl.icon}
                                                </div>
                                                <div>
                                                    <Text strong style={{ fontSize: 11 }}>{tpl.name}</Text>
                                                    <div>
                                                        <Tag style={{ fontSize: 9 }}>{tpl.module}</Tag>
                                                        <StarFilled style={{ color: '#f59e0b', fontSize: 10, marginLeft: 2 }} />
                                                    </div>
                                                </div>
                                            </Space>
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </Row>
                    </div>
                )}

                {/* Template Grid */}
                <Row gutter={[16, 16]}>
                    <AnimatePresence>
                        {filtered.map((tpl, i) => (
                            <Col xs={24} sm={12} md={8} key={tpl.id}>
                                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                                    exit={{ opacity: 0, scale: 0.95 }} transition={{ delay: i * 0.03 }}>
                                    <Card hoverable style={{ ...glass, borderLeft: `4px solid ${tpl.color}`, height: '100%' }}>
                                        <Space direction="vertical" size={8} style={{ width: '100%' }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                                <Space>
                                                    <div style={{ width: 36, height: 36, borderRadius: 10, background: `${tpl.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, color: tpl.color }}>
                                                        {tpl.icon}
                                                    </div>
                                                    <div>
                                                        <Text strong style={{ fontSize: 13 }}>{tpl.name}</Text>
                                                        {tpl.popular && <StarFilled style={{ color: '#f59e0b', fontSize: 11, marginLeft: 4 }} />}
                                                        <div>
                                                            <Tag color={tpl.color} style={{ fontSize: 9, borderRadius: 8 }}>{tpl.module}</Tag>
                                                            <Tag style={{ fontSize: 9, borderRadius: 8 }}>{tpl.category}</Tag>
                                                        </div>
                                                    </div>
                                                </Space>
                                            </div>
                                            <Text type="secondary" style={{ fontSize: 11, lineHeight: 1.4 }}>{tpl.description}</Text>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                <Space size={4}>
                                                    <Tag style={{ fontSize: 9 }}>{tpl.fields} fields</Tag>
                                                    {tpl.scoring && <Tag color="purple" style={{ fontSize: 9, borderRadius: 8 }}>Scoring</Tag>}
                                                </Space>
                                                <Space size={4}>
                                                    <Button type="text" size="small" icon={<EyeOutlined />} onClick={() => setPreviewId(tpl.id)}>Preview</Button>
                                                    <Button type="primary" size="small" icon={<DownloadOutlined />}
                                                        style={{ background: tpl.color, borderColor: tpl.color, borderRadius: 6 }}
                                                        onClick={() => handleInstall(tpl)}>Install</Button>
                                                </Space>
                                            </div>
                                        </Space>
                                    </Card>
                                </motion.div>
                            </Col>
                        ))}
                    </AnimatePresence>
                </Row>

                {filtered.length === 0 && (
                    <Card style={{ ...glass, textAlign: 'center', padding: 40 }}>
                        <Text type="secondary">No templates match your filters</Text>
                    </Card>
                )}
            </div>

            {/* Preview Modal */}
            <Modal title={preview?.name} open={!!previewId} onCancel={() => setPreviewId(null)}
                footer={[
                    <Button key="close" onClick={() => setPreviewId(null)}>Close</Button>,
                    <Button key="install" type="primary" icon={<DownloadOutlined />}
                        style={{ background: preview?.color, borderColor: preview?.color }}
                        onClick={() => { if (preview) handleInstall(preview); setPreviewId(null); }}>Install Template</Button>,
                ]} width={500}>
                {preview && (
                    <div style={{ padding: '8px 0' }}>
                        <Space style={{ marginBottom: 12 }}>
                            <div style={{ width: 40, height: 40, borderRadius: 10, background: `${preview.color}15`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, color: preview.color }}>{preview.icon}</div>
                            <div>
                                <Tag color={preview.color}>{preview.module}</Tag>
                                <Tag>{preview.category}</Tag>
                                {preview.scoring && <Tag color="purple">Scoring Enabled</Tag>}
                            </div>
                        </Space>
                        <Paragraph style={{ fontSize: 13 }}>{preview.description}</Paragraph>
                        <Divider style={{ margin: '10px 0' }} />
                        <Row gutter={16}>
                            <Col span={8}><Text type="secondary" style={{ fontSize: 11 }}>Fields</Text><div><Text strong>{preview.fields}</Text></div></Col>
                            <Col span={8}><Text type="secondary" style={{ fontSize: 11 }}>Category</Text><div><Text strong>{preview.category}</Text></div></Col>
                            <Col span={8}><Text type="secondary" style={{ fontSize: 11 }}>Module</Text><div><Text strong>{preview.module}</Text></div></Col>
                        </Row>
                        <Divider style={{ margin: '10px 0' }} />
                        <Space wrap>
                            {preview.tags.map(tag => <Tag key={tag} style={{ borderRadius: 8 }}>{tag}</Tag>)}
                        </Space>
                    </div>
                )}
            </Modal>
        </CMSLayout>
    );
}

"use client";
import React, { useState, useEffect, useCallback, Suspense } from "react";
import { Card, Button, Space, Tag, Typography, Row, Col, Select, Input, Switch, Divider, message, Empty, Spin, Tooltip, Badge, Tabs } from "antd";
import {
    BranchesOutlined, PlusOutlined, DeleteOutlined, ArrowRightOutlined,
    EyeOutlined, EyeInvisibleOutlined, CheckCircleOutlined, FormOutlined,
    ThunderboltOutlined, QuestionCircleOutlined, ReloadOutlined,
    CopyOutlined, SaveOutlined, SettingOutlined, FilterOutlined,
} from "@ant-design/icons";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useSearchParams } from "next/navigation";

const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Rule {
    id: string;
    sourceField: string;
    operator: string;
    value: string;
    action: string;
    targetField: string;
    enabled: boolean;
}

const OPERATORS = [
    { value: 'equals', label: '= Equals' },
    { value: 'not_equals', label: '≠ Not equals' },
    { value: 'contains', label: '∋ Contains' },
    { value: 'greater_than', label: '> Greater than' },
    { value: 'less_than', label: '< Less than' },
    { value: 'is_empty', label: '∅ Is empty' },
    { value: 'is_not_empty', label: '≠∅ Is not empty' },
    { value: 'starts_with', label: 'Starts with' },
    { value: 'ends_with', label: 'Ends with' },
];

const ACTIONS = [
    { value: 'show', label: '👁 Show field', color: '#10b981' },
    { value: 'hide', label: '🙈 Hide field', color: '#ef4444' },
    { value: 'require', label: '✱ Make required', color: '#f59e0b' },
    { value: 'optional', label: '○ Make optional', color: '#6b7280' },
    { value: 'set_value', label: '✏ Set value', color: '#3b82f6' },
    { value: 'skip_section', label: '⏭ Skip section', color: '#8b5cf6' },
    { value: 'calculate', label: '🔢 Calculate', color: '#06b6d4' },
];

function LogicContent() {
    const { themeColor } = usePreferencesStore();
    const searchParams = useSearchParams();
    const templateId = searchParams.get('templateId') || '';
    const [messageApi, ctx] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [fields, setFields] = useState<any[]>([]);
    const [rules, setRules] = useState<Rule[]>([]);

    const loadFields = useCallback(async () => {
        if (!templateId) { setLoading(false); return; }
        setLoading(true);
        try {
            const res = await gql<{ formFields: any[] }>(`
                query($tid: String!) { formFields(templateId: $tid) { id label type required } }
            `, { tid: templateId });
            setFields(res.formFields || []);
            // Generate sample rules from existing fields
            if ((res.formFields || []).length >= 2) {
                const f = res.formFields || [];
                setRules([{
                    id: 'rule-1', sourceField: f[0]?.id || '', operator: 'equals',
                    value: 'Yes', action: 'show', targetField: f[1]?.id || '', enabled: true,
                }]);
            }
        } catch (e: any) { messageApi.error(e.message); }
        setLoading(false);
    }, [templateId, messageApi]);

    useEffect(() => { loadFields(); }, [loadFields]);

    // Demo fields if none loaded
    const demoFields = fields.length > 0 ? fields : [
        { id: 'f1', label: 'Employment Type', type: 'select' },
        { id: 'f2', label: 'Years of Experience', type: 'number' },
        { id: 'f3', label: 'Department', type: 'select' },
        { id: 'f4', label: 'Manager Name', type: 'text' },
        { id: 'f5', label: 'Performance Score', type: 'rating' },
        { id: 'f6', label: 'Bonus Eligible', type: 'checkbox' },
        { id: 'f7', label: 'Comments', type: 'textarea' },
        { id: 'f8', label: 'Upload Documents', type: 'file' },
    ];

    const demoRules = rules.length > 0 ? rules : [
        { id: 'r1', sourceField: 'f1', operator: 'equals', value: 'Contract', action: 'hide', targetField: 'f6', enabled: true },
        { id: 'r2', sourceField: 'f2', operator: 'greater_than', value: '5', action: 'show', targetField: 'f7', enabled: true },
        { id: 'r3', sourceField: 'f5', operator: 'greater_than', value: '4', action: 'require', targetField: 'f7', enabled: false },
    ];

    const [activeRules, setActiveRules] = useState<Rule[]>(demoRules);

    const addRule = () => {
        const newRule: Rule = {
            id: `rule-${Date.now()}`, sourceField: demoFields[0]?.id || '',
            operator: 'equals', value: '', action: 'show',
            targetField: demoFields[1]?.id || '', enabled: true,
        };
        setActiveRules([...activeRules, newRule]);
    };

    const updateRule = (id: string, field: keyof Rule, value: any) => {
        setActiveRules(activeRules.map(r => r.id === id ? { ...r, [field]: value } : r));
    };

    const deleteRule = (id: string) => {
        setActiveRules(activeRules.filter(r => r.id !== id));
    };

    const getFieldLabel = (id: string) => demoFields.find(f => f.id === id)?.label || id;
    const getActionConfig = (action: string) => ACTIONS.find(a => a.value === action) || ACTIONS[0];

    const handleSave = () => {
        messageApi.success(`${activeRules.length} conditional logic rules saved!`);
    };

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#8b5cf6', '#06b6d4']}>Conditional Logic</AuroraText>}
            subTitle={<DecryptedText text="Show, hide, or modify fields based on user answers" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <Button key="save" type="primary" icon={<SaveOutlined />} onClick={handleSave}
                    style={{ background: themeColor, borderColor: themeColor }}>Save Rules</Button>,
                <Button key="add" icon={<PlusOutlined />} onClick={addRule}>Add Rule</Button>,
            ]}
        >
            {ctx}
            <div style={{ maxWidth: 1000, margin: '0 auto' }}>
                {/* Stats */}
                <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                    {[
                        { label: 'Total Rules', value: activeRules.length, color: '#3b82f6', icon: <BranchesOutlined /> },
                        { label: 'Active', value: activeRules.filter(r => r.enabled).length, color: '#10b981', icon: <CheckCircleOutlined /> },
                        { label: 'Fields', value: demoFields.length, color: '#8b5cf6', icon: <FormOutlined /> },
                        { label: 'Actions Used', value: new Set(activeRules.map(r => r.action)).size, color: '#f59e0b', icon: <ThunderboltOutlined /> },
                    ].map((s, i) => (
                        <Col xs={12} md={6} key={i}>
                            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                <Card style={{ ...glass, borderTop: `3px solid ${s.color}` }} bodyStyle={{ padding: '12px 16px' }}>
                                    <Space>
                                        <span style={{ fontSize: 18, color: s.color }}>{s.icon}</span>
                                        <div>
                                            <Text type="secondary" style={{ fontSize: 10 }}>{s.label}</Text>
                                            <div><Text strong style={{ fontSize: 20, color: s.color }}>{s.value}</Text></div>
                                        </div>
                                    </Space>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Rules */}
                <Space direction="vertical" size={12} style={{ width: '100%' }}>
                    <AnimatePresence>
                        {activeRules.map((rule, idx) => {
                            const actionCfg = getActionConfig(rule.action);
                            return (
                                <motion.div key={rule.id}
                                    initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }}
                                    exit={{ opacity: 0, x: 20 }} transition={{ delay: idx * 0.05 }}>
                                    <Card
                                        style={{
                                            ...glass,
                                            borderLeft: `4px solid ${rule.enabled ? actionCfg.color : '#d1d5db'}`,
                                            opacity: rule.enabled ? 1 : 0.6,
                                        }}
                                        bodyStyle={{ padding: '16px 20px' }}
                                    >
                                        {/* Rule Header */}
                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                                            <Space>
                                                <Badge count={idx + 1} style={{ backgroundColor: rule.enabled ? actionCfg.color : '#d1d5db' }} />
                                                <Text strong style={{ fontSize: 13 }}>Rule {idx + 1}</Text>
                                                <Tag color={actionCfg.color} style={{ borderRadius: 8, fontSize: 10 }}>{actionCfg.label}</Tag>
                                            </Space>
                                            <Space size={4}>
                                                <Switch size="small" checked={rule.enabled}
                                                    onChange={v => updateRule(rule.id, 'enabled', v)} />
                                                <Button type="text" danger size="small" icon={<DeleteOutlined />}
                                                    onClick={() => deleteRule(rule.id)} />
                                            </Space>
                                        </div>

                                        {/* Rule Configuration */}
                                        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
                                            <Text type="secondary" style={{ fontSize: 11, minWidth: 30 }}>WHEN</Text>
                                            <Select size="small" value={rule.sourceField} style={{ minWidth: 160 }}
                                                onChange={v => updateRule(rule.id, 'sourceField', v)}
                                                options={demoFields.map(f => ({ value: f.id, label: f.label }))} />

                                            <Select size="small" value={rule.operator} style={{ minWidth: 130 }}
                                                onChange={v => updateRule(rule.id, 'operator', v)}
                                                options={OPERATORS} />

                                            {!['is_empty', 'is_not_empty'].includes(rule.operator) && (
                                                <Input size="small" value={rule.value} placeholder="Value"
                                                    style={{ width: 120 }}
                                                    onChange={e => updateRule(rule.id, 'value', e.target.value)} />
                                            )}

                                            <ArrowRightOutlined style={{ color: actionCfg.color, fontSize: 14 }} />

                                            <Text type="secondary" style={{ fontSize: 11, minWidth: 35 }}>THEN</Text>
                                            <Select size="small" value={rule.action} style={{ minWidth: 140 }}
                                                onChange={v => updateRule(rule.id, 'action', v)}
                                                options={ACTIONS.map(a => ({ value: a.value, label: a.label }))} />

                                            <Select size="small" value={rule.targetField} style={{ minWidth: 160 }}
                                                onChange={v => updateRule(rule.id, 'targetField', v)}
                                                options={demoFields.map(f => ({ value: f.id, label: f.label }))} />
                                        </div>

                                        {/* Preview sentence */}
                                        <div style={{ marginTop: 10, padding: '6px 10px', borderRadius: 6, background: `${actionCfg.color}08`, fontSize: 11 }}>
                                            <Text type="secondary">
                                                When <Text strong>"{getFieldLabel(rule.sourceField)}"</Text>
                                                {' '}{OPERATORS.find(o => o.value === rule.operator)?.label.toLowerCase() || rule.operator}
                                                {!['is_empty', 'is_not_empty'].includes(rule.operator) && <> <Text strong>"{rule.value}"</Text></>}
                                                {' → '}{actionCfg.label.toLowerCase()} <Text strong>"{getFieldLabel(rule.targetField)}"</Text>
                                            </Text>
                                        </div>
                                    </Card>
                                </motion.div>
                            );
                        })}
                    </AnimatePresence>
                </Space>

                {activeRules.length === 0 && (
                    <Card style={{ ...glass, textAlign: 'center', padding: 40 }}>
                        <BranchesOutlined style={{ fontSize: 40, color: '#d1d5db', marginBottom: 12 }} />
                        <div><Text type="secondary">No conditional logic rules yet</Text></div>
                        <Button type="primary" icon={<PlusOutlined />} onClick={addRule} style={{ marginTop: 12, background: themeColor }}>
                            Add First Rule
                        </Button>
                    </Card>
                )}

                {/* How It Works */}
                <Card style={{ ...glass, marginTop: 20 }}
                    title={<Space><QuestionCircleOutlined style={{ color: '#6366f1' }} /> How Conditional Logic Works</Space>}>
                    <Row gutter={[16, 16]}>
                        {[
                            { step: '1', title: 'Set Trigger', desc: 'Choose a source field and define when the rule activates', color: '#3b82f6', icon: <FilterOutlined /> },
                            { step: '2', title: 'Define Condition', desc: 'Set the operator and value to match (equals, contains, etc.)', color: '#f59e0b', icon: <SettingOutlined /> },
                            { step: '3', title: 'Choose Action', desc: 'Show, hide, require, or modify the target field', color: '#10b981', icon: <ThunderboltOutlined /> },
                            { step: '4', title: 'Live Preview', desc: 'Rules apply in real-time as users fill the form', color: '#8b5cf6', icon: <EyeOutlined /> },
                        ].map((s, i) => (
                            <Col xs={24} sm={12} md={6} key={i}>
                                <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 + i * 0.1 }}>
                                    <div style={{ textAlign: 'center' }}>
                                        <div style={{ width: 40, height: 40, borderRadius: 10, background: `${s.color}12`, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 8px', fontSize: 18, color: s.color }}>
                                            {s.icon}
                                        </div>
                                        <Text strong style={{ fontSize: 12 }}>{s.title}</Text>
                                        <div><Text type="secondary" style={{ fontSize: 10 }}>{s.desc}</Text></div>
                                    </div>
                                </motion.div>
                            </Col>
                        ))}
                    </Row>
                </Card>
            </div>
        </CMSLayout>
    );
}

export default function FormLogicPage() { return <React.Suspense fallback={<div>Loading...</div>}><FormLogicPageContent /></React.Suspense>; } 
function FormLogicPageContent() {
    return (
        <Suspense fallback={<div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" /></div>}>
            <LogicContent />
        </Suspense>
    );
}

"use client";
import React, { useState, useEffect, useCallback } from "react";
import { Card, Button, Space, Tag, Typography, Row, Col, Table, Select, Switch, message, Avatar, Badge, Empty, Spin, Tooltip, Divider, Input, Modal, Checkbox, theme } from "antd";
import {
    LockOutlined, TeamOutlined, UserOutlined, CheckCircleOutlined,
    EyeOutlined, EditOutlined, DeleteOutlined, PlusOutlined,
    ReloadOutlined, SafetyOutlined, FormOutlined, SettingOutlined,
    KeyOutlined, GlobalOutlined, StopOutlined, CrownOutlined,
} from "@ant-design/icons";
import { motion } from "framer-motion";
import type { ColumnsType } from "antd/es/table";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface PermissionEntry {
    id: string;
    roleName: string;
    roleColor: string;
    roleIcon: React.ReactNode;
    canCreate: boolean;
    canEdit: boolean;
    canDelete: boolean;
    canSubmit: boolean;
    canReview: boolean;
    canViewAnalytics: boolean;
    canExport: boolean;
    canManageSettings: boolean;
}

const DEFAULT_PERMISSIONS: PermissionEntry[] = [
    { id: 'admin', roleName: 'Administrator', roleColor: '#ef4444', roleIcon: <CrownOutlined />, canCreate: true, canEdit: true, canDelete: true, canSubmit: true, canReview: true, canViewAnalytics: true, canExport: true, canManageSettings: true },
    { id: 'manager', roleName: 'Manager', roleColor: '#8b5cf6', roleIcon: <TeamOutlined />, canCreate: true, canEdit: true, canDelete: false, canSubmit: true, canReview: true, canViewAnalytics: true, canExport: true, canManageSettings: false },
    { id: 'reviewer', roleName: 'Reviewer', roleColor: '#3b82f6', roleIcon: <EyeOutlined />, canCreate: false, canEdit: false, canDelete: false, canSubmit: false, canReview: true, canViewAnalytics: true, canExport: false, canManageSettings: false },
    { id: 'employee', roleName: 'Employee', roleColor: '#10b981', roleIcon: <UserOutlined />, canCreate: false, canEdit: false, canDelete: false, canSubmit: true, canReview: false, canViewAnalytics: false, canExport: false, canManageSettings: false },
    { id: 'external', roleName: 'External User', roleColor: '#f59e0b', roleIcon: <GlobalOutlined />, canCreate: false, canEdit: false, canDelete: false, canSubmit: true, canReview: false, canViewAnalytics: false, canExport: false, canManageSettings: false },
];

const PERMISSION_LABELS: { key: keyof PermissionEntry; label: string; icon: React.ReactNode; color: string; desc: string }[] = [
    { key: 'canCreate', label: 'Create', icon: <PlusOutlined />, color: '#10b981', desc: 'Create new form templates' },
    { key: 'canEdit', label: 'Edit', icon: <EditOutlined />, color: '#3b82f6', desc: 'Modify existing templates & fields' },
    { key: 'canDelete', label: 'Delete', icon: <DeleteOutlined />, color: '#ef4444', desc: 'Remove templates & submissions' },
    { key: 'canSubmit', label: 'Submit', icon: <FormOutlined />, color: '#8b5cf6', desc: 'Fill and submit forms' },
    { key: 'canReview', label: 'Review', icon: <CheckCircleOutlined />, color: '#f59e0b', desc: 'Approve or reject submissions' },
    { key: 'canViewAnalytics', label: 'Analytics', icon: <EyeOutlined />, color: '#06b6d4', desc: 'View reports & analytics' },
    { key: 'canExport', label: 'Export', icon: <KeyOutlined />, color: '#ec4899', desc: 'Export data to CSV/PDF' },
    { key: 'canManageSettings', label: 'Settings', icon: <SettingOutlined />, color: '#6366f1', desc: 'Manage form settings' },
];

export default function FormPermissionsPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [messageApi, ctx] = message.useMessage();
    const [permissions, setPermissions] = useState<PermissionEntry[]>(DEFAULT_PERMISSIONS);
    const [selectedRole, setSelectedRole] = useState<string | null>(null);

    const togglePermission = (roleId: string, permKey: keyof PermissionEntry) => {
        if (roleId === 'admin') { messageApi.warning('Administrator permissions cannot be modified'); return; }
        setPermissions(prev => prev.map(p => {
            if (p.id === roleId) return { ...p, [permKey]: !(p[permKey] as boolean) };
            return p;
        }));
    };

    const handleSave = () => {
        messageApi.success('Permissions saved successfully!');
    };

    const selectedPerm = permissions.find(p => p.id === selectedRole);

    const columns: ColumnsType<PermissionEntry> = [
        { title: 'Role', dataIndex: 'roleName', width: 160, fixed: 'left', render: (v: string, rec) => (
            <Space>
                <Avatar size="small" style={{ backgroundColor: rec.roleColor, fontSize: 11 }}>{rec.roleIcon}</Avatar>
                <div>
                    <Text strong style={{ fontSize: 12 }}>{v}</Text>
                    {rec.id === 'admin' && <Tag color="red" style={{ fontSize: 8, marginLeft: 4, borderRadius: 6 }}>Super</Tag>}
                </div>
            </Space>
        )},
        ...PERMISSION_LABELS.map(perm => ({
            title: <Tooltip title={perm.desc}><Space size={2}>{perm.icon}<Text style={{ fontSize: 10 }}>{perm.label}</Text></Space></Tooltip>,
            key: perm.key,
            width: 90,
            align: 'center' as const,
            render: (_: any, rec: PermissionEntry) => (
                <Switch size="small" checked={rec[perm.key] as boolean}
                    disabled={rec.id === 'admin'}
                    onChange={() => togglePermission(rec.id, perm.key)}
                    style={rec[perm.key] ? { backgroundColor: perm.color } : {}} />
            ),
        })),
        { title: '', key: 'actions', width: 50, render: (_: any, rec: PermissionEntry) => (
            <Tooltip title="View Details"><Button type="text" size="small" icon={<SettingOutlined />} onClick={() => setSelectedRole(rec.id)} /></Tooltip>
        )},
    ];

    // Stats
    const totalPerms = permissions.reduce((sum, p) => sum + PERMISSION_LABELS.filter(l => p[l.key] as boolean).length, 0);

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#ef4444', '#8b5cf6']}>Access Control</AuroraText>}
            subTitle={<DecryptedText text="Role-based permissions for form operations" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <Button key="save" type="primary" icon={<SafetyOutlined />} onClick={handleSave}
                    style={{ background: 'linear-gradient(135deg, #8b5cf6, #6d28d9)', border: 'none' }}>Save Permissions</Button>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={() => setPermissions(DEFAULT_PERMISSIONS)} />,
            ]}
        >
            {ctx}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                {/* Stats */}
                <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                    {[
                        { label: 'Roles', value: permissions.length, color: '#8b5cf6', icon: <TeamOutlined /> },
                        { label: 'Permissions', value: PERMISSION_LABELS.length, color: '#3b82f6', icon: <KeyOutlined /> },
                        { label: 'Active Grants', value: totalPerms, color: '#10b981', icon: <CheckCircleOutlined /> },
                        { label: 'Restricted', value: (permissions.length * PERMISSION_LABELS.length) - totalPerms, color: '#ef4444', icon: <StopOutlined /> },
                    ].map((s, i) => (
                        <Col xs={12} md={6} key={i}>
                            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                <Card style={{ ...glass, borderTop: `3px solid ${s.color}` }} bodyStyle={{ padding: '12px 16px' }}>
                                    <Space>
                                        <span style={{ fontSize: 18, color: s.color }}>{s.icon}</span>
                                        <div>
                                            <Text type="secondary" style={{ fontSize: 10 }}>{s.label}</Text>
                                            <div><Text strong style={{ fontSize: 20, color: s.color }}>{s.value}</Text></div>
                                        </div>
                                    </Space>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Permission Legend */}
                <Card style={{ ...glass, marginBottom: 16 }} bodyStyle={{ padding: '10px 16px' }}>
                    <Space wrap size={8}>
                        <Text strong style={{ fontSize: 11 }}><LockOutlined /> Permission Types:</Text>
                        {PERMISSION_LABELS.map(p => (
                            <Tooltip key={p.key as string} title={p.desc}>
                                <Tag icon={p.icon} color={p.color} style={{ borderRadius: 8, fontSize: 10, cursor: 'help' }}>{p.label}</Tag>
                            </Tooltip>
                        ))}
                    </Space>
                </Card>

                {/* Permissions Matrix */}
                <Card size="small" title={<Space><SafetyOutlined style={{ color: '#8b5cf6' }} /> Permission Matrix</Space>}
                    extra={<Badge count={`${permissions.length} roles × ${PERMISSION_LABELS.length} permissions`} style={{ backgroundColor: '#6b7280', fontSize: 10 }} />}
                    style={glass}>
                    <Table<PermissionEntry>
                        dataSource={permissions}
                        columns={columns}
                        rowKey="id"
                        pagination={false}
                        size="small"
                        scroll={{ x: 950 }}
                        rowClassName={(rec) => rec.id === 'admin' ? 'admin-row' : ''}
                    />
                </Card>

                {/* Role Cards */}
                <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
                    {permissions.map((role, i) => {
                        const grantCount = PERMISSION_LABELS.filter(l => role[l.key] as boolean).length;
                        return (
                            <Col xs={24} sm={12} md={8} lg={4.8} key={role.id}>
                                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.05 }}>
                                    <Card size="small" style={{ ...glass, borderTop: `3px solid ${role.roleColor}`, textAlign: 'center', cursor: 'pointer' }}
                                        onClick={() => setSelectedRole(role.id)} hoverable>
                                        <Avatar size={40} style={{ backgroundColor: role.roleColor, marginBottom: 8 }}>{role.roleIcon}</Avatar>
                                        <div><Text strong style={{ fontSize: 12 }}>{role.roleName}</Text></div>
                                        <div style={{ margin: '6px 0' }}>
                                            <Text style={{ fontSize: 22, fontWeight: 700, color: role.roleColor }}>{grantCount}</Text>
                                            <Text type="secondary" style={{ fontSize: 10 }}> / {PERMISSION_LABELS.length}</Text>
                                        </div>
                                        <div style={{ height: 4, borderRadius: 2, background: isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0', overflow: 'hidden' }}>
                                            <div style={{ width: `${(grantCount / PERMISSION_LABELS.length) * 100}%`, height: '100%', background: role.roleColor, borderRadius: 2 }} />
                                        </div>
                                    </Card>
                                </motion.div>
                            </Col>
                        );
                    })}
                </Row>
            </motion.div>

            {/* Role Detail Modal */}
            <Modal title={selectedPerm ? `${selectedPerm.roleName} Permissions` : ''} open={!!selectedRole}
                onCancel={() => setSelectedRole(null)} footer={null} width={420}>
                {selectedPerm && (
                    <div style={{ padding: '8px 0' }}>
                        <div style={{ textAlign: 'center', marginBottom: 16 }}>
                            <Avatar size={48} style={{ backgroundColor: selectedPerm.roleColor }}>{selectedPerm.roleIcon}</Avatar>
                            <div style={{ marginTop: 8 }}><Text strong style={{ fontSize: 16 }}>{selectedPerm.roleName}</Text></div>
                        </div>
                        <Space direction="vertical" size={8} style={{ width: '100%' }}>
                            {PERMISSION_LABELS.map(perm => (
                                <div key={perm.key as string} style={{
                                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                    padding: '8px 12px', borderRadius: 8,
                                    background: (selectedPerm[perm.key] as boolean) ? `${perm.color}08` : isDark ? 'rgba(255,255,255,0.03)' : '#fafafa',
                                    border: `1px solid ${(selectedPerm[perm.key] as boolean) ? `${perm.color}20` : isDark ? 'rgba(255,255,255,0.08)' : '#f0f0f0'}`,
                                }}>
                                    <Space>
                                        <span style={{ color: perm.color }}>{perm.icon}</span>
                                        <div>
                                            <Text strong style={{ fontSize: 12 }}>{perm.label}</Text>
                                            <div><Text type="secondary" style={{ fontSize: 10 }}>{perm.desc}</Text></div>
                                        </div>
                                    </Space>
                                    <Switch size="small" checked={selectedPerm[perm.key] as boolean}
                                        disabled={selectedPerm.id === 'admin'}
                                        onChange={() => togglePermission(selectedPerm.id, perm.key)}
                                        style={(selectedPerm[perm.key] as boolean) ? { backgroundColor: perm.color } : {}} />
                                </div>
                            ))}
                        </Space>
                    </div>
                )}
            </Modal>
        </CMSLayout>
    );
}

