"use client";
import React, { useState, useEffect, useCallback } from "react";
import { Table, Button, Card, Space, Tag, Input, Select, message, Tooltip, Typography, Row, Col, Statistic, Drawer, Progress, Descriptions, Timeline, Badge, Popconfirm, theme } from "antd";
import { SearchOutlined, ReloadOutlined, EyeOutlined, CheckCircleOutlined, CloseCircleOutlined, DeleteOutlined, ClockCircleOutlined, FileTextOutlined, TrophyOutlined, InboxOutlined, ExpandOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import type { ColumnsType } from "antd/es/table";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255, 255, 255, 0.4)', backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)', boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.07)', border: '1px solid rgba(255, 255, 255, 0.6)', borderRadius: 12 };

interface Submission {
    id: string; tenantId: string; templateId: string; submittedBy?: string;
    status: string; totalScore: number; maxPossibleScore: number;
    percentage: number; grade?: string; reviewerId?: string;
    reviewerNotes?: string; reviewedAt?: string; submittedAt?: string;
    templateName?: string; templateCategory?: string;
    fieldValues?: any[]; createdAt: string; updatedAt: string;
}

const STATUS_MAP: Record<string, { color: string; icon: React.ReactNode }> = {
    draft: { color: 'default', icon: <ClockCircleOutlined /> },
    submitted: { color: 'processing', icon: <InboxOutlined /> },
    reviewed: { color: 'warning', icon: <EyeOutlined /> },
    approved: { color: 'success', icon: <CheckCircleOutlined /> },
    rejected: { color: 'error', icon: <CloseCircleOutlined /> },
};

function gradeColor(grade?: string) {
    if (!grade) return '#595959';
    if (grade === 'Excellent') return '#52c41a';
    if (grade === 'Good') return '#1890ff';
    if (grade === 'Satisfactory') return '#faad14';
    return '#ff4d4f';
}

export default function FormSubmissionsPage() {
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [data, setData] = useState<Submission[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [detailOpen, setDetailOpen] = useState(false);
    const [detail, setDetail] = useState<Submission | null>(null);
    const [scores, setScores] = useState<any[]>([]);
    const [messageApi, ctx] = message.useMessage();
    const router = useRouter();

    const stats = {
        total: data.length,
        submitted: data.filter(d => d.status === 'submitted').length,
        approved: data.filter(d => d.status === 'approved').length,
        avgScore: data.filter(d => d.percentage > 0).length > 0
            ? (data.reduce((a, d) => a + d.percentage, 0) / data.filter(d => d.percentage > 0).length).toFixed(1) : '0',
    };

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const res = await gql<{ formSubmissions: Submission[] }>(`
                query($tid: String!, $st: String) {
                    formSubmissions(tenantId: $tid, status: $st) {
                        id tenantId templateId submittedBy status totalScore maxPossibleScore
                        percentage grade reviewerId reviewerNotes reviewedAt submittedAt
                        templateName templateCategory createdAt updatedAt
                    }
                }
            `, { tid: DEFAULT_TENANT_ID, st: statusFilter || null });
            setData(res.formSubmissions || []);
        } catch (e: any) { messageApi.error(e.message); }
        setLoading(false);
    }, [statusFilter, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const openDetail = async (rec: Submission) => {
        setDetail(rec);
        setDetailOpen(true);
        try {
            const [subRes, scoreRes] = await Promise.all([
                gql<{ formSubmission: Submission }>(`
                    query($id: String!) { formSubmission(id: $id) {
                        id status totalScore maxPossibleScore percentage grade reviewerNotes
                        submittedAt reviewedAt templateName templateCategory
                        fieldValues { id fieldId value numericValue jsonValue score maxScore fieldLabel fieldType fieldKpiConfig fieldOptions createdAt }
                    } }
                `, { id: rec.id }),
                gql<{ formScores: any[] }>(`
                    query($sid: String!) { formScores(submissionId: $sid) { id dimension score maxScore weight weightedScore } }
                `, { sid: rec.id }),
            ]);
            setDetail(subRes.formSubmission);
            setScores(scoreRes.formScores || []);
        } catch { /* keep what we have */ }
    };

    const handleReview = async (id: string, status: string) => {
        try {
            await gql(`mutation($id: String!, $input: ReviewSubmissionInput!) { reviewSubmission(id: $id, input: $input) { id } }`,
                { id, input: { status, reviewerId: '00000000-0000-0000-0000-000000000001' } });
            messageApi.success(`Submission ${status}`);
            setDetailOpen(false); loadData();
        } catch (e: any) { messageApi.error(e.message); }
    };

    const handleCalcScore = async (id: string) => {
        try {
            await gql(`mutation($sid: String!) { calculateFormScore(submissionId: $sid) { id totalScore percentage grade } }`, { sid: id });
            messageApi.success('Score calculated');
            openDetail(detail!);
            loadData();
        } catch (e: any) { messageApi.error(e.message); }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteSubmission(id: $id) }`, { id });
            messageApi.success('Submission deleted');
            loadData();
        } catch (e: any) { messageApi.error(e.message); }
    };

    const columns: ColumnsType<Submission> = [
        { title: 'Form', dataIndex: 'templateName', key: 'templateName', render: (n: string, rec) => (
            <Space direction="vertical" size={0}>
                <Text strong style={{ cursor: 'pointer', color: '#1890ff' }} onClick={() => openDetail(rec)}>{n || 'Unknown'}</Text>
                {rec.templateCategory && <Tag style={{ fontSize: 10 }}>{rec.templateCategory}</Tag>}
            </Space>
        )},
        { title: 'Status', dataIndex: 'status', key: 'status', width: 120, render: (s: string) => {
            const sm = STATUS_MAP[s];
            return <Badge status={s === 'approved' ? 'success' : s === 'rejected' ? 'error' : 'processing'} text={<Tag color={sm?.color} icon={sm?.icon}>{s}</Tag>} />;
        }},
        { title: 'Score', key: 'score', width: 160, render: (_: any, rec) => rec.percentage > 0 ? (
            <Space><Progress type="circle" size={36} percent={rec.percentage} strokeColor={gradeColor(rec.grade)} format={() => rec.totalScore.toFixed(1)} />{rec.grade && <Tag color={gradeColor(rec.grade)}>{rec.grade}</Tag>}</Space>
        ) : <Text type="secondary">—</Text> },
        { title: 'Submitted', dataIndex: 'submittedAt', key: 'submittedAt', width: 140, render: (d: string) => d ? <Tooltip title={dayjs(d).format('YYYY-MM-DD HH:mm')}><Text type="secondary">{dayjs(d).fromNow()}</Text></Tooltip> : '—' },
        { title: '', key: 'actions', width: 100, align: 'right' as const, render: (_: any, rec) => (
            <Space size={4}>
                <Tooltip title="View"><Button type="text" size="small" icon={<EyeOutlined />} onClick={() => openDetail(rec)} /></Tooltip>
                <Tooltip title="Full Review"><Button type="text" size="small" icon={<ExpandOutlined />} onClick={() => router.push(`/admin/forms/response?id=${rec.id}`)} /></Tooltip>
                <Popconfirm title="Delete?" onConfirm={() => handleDelete(rec.id)}><Button type="text" size="small" icon={<DeleteOutlined />} danger /></Popconfirm>
            </Space>
        )},
    ];

    return (
        <CMSLayout
            title={<AuroraText>Submissions</AuroraText>}
            subTitle={<DecryptedText text="Review form responses and manage scoring" speed={40} revealDirection="start" />}
            extra={[<Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />]}
        >
            {ctx}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    {[
                        { title: 'Total', value: stats.total, color: '#1890ff', icon: <FileTextOutlined /> },
                        { title: 'Pending Review', value: stats.submitted, color: '#fa8c16', icon: <ClockCircleOutlined /> },
                        { title: 'Approved', value: stats.approved, color: '#52c41a', icon: <CheckCircleOutlined /> },
                        { title: 'Avg Score', value: stats.avgScore + '%', color: '#722ed1', icon: <TrophyOutlined /> },
                    ].map((s, i) => (
                        <Col xs={12} md={6} key={i}>
                            <Card style={{ ...glass, borderLeft: `3px solid ${s.color}` }} bodyStyle={{ padding: '16px 20px' }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 24 }} />
                            </Card>
                        </Col>
                    ))}
                </Row>
                <Card style={{ ...glass, marginBottom: 16 }} bodyStyle={{ padding: '12px 16px' }}>
                    <Row gutter={12} align="middle">
                        <Col flex="auto"><Input prefix={<SearchOutlined />} placeholder="Search…" value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 300 }} /></Col>
                        <Col><Select placeholder="Status" allowClear style={{ width: 140 }} value={statusFilter || undefined} onChange={v => setStatusFilter(v || '')}
                            options={Object.entries(STATUS_MAP).map(([v]) => ({ value: v, label: v }))} /></Col>
                    </Row>
                </Card>
                <Card style={glass}>
                    <Table<Submission> dataSource={data.filter(d => !search || d.templateName?.toLowerCase().includes(search.toLowerCase()))} columns={columns} rowKey="id" loading={loading} pagination={{ pageSize: 15 }} size="middle" />
                </Card>

                <Drawer title={detail?.templateName || 'Submission'} open={detailOpen} onClose={() => { setDetailOpen(false); setDetail(null); setScores([]); }} width={640}
                    extra={detail?.status === 'submitted' ? (
                        <Space>
                            <Button icon={<TrophyOutlined />} onClick={() => handleCalcScore(detail!.id)}>Calculate Score</Button>
                            <Button type="primary" icon={<CheckCircleOutlined />} onClick={() => handleReview(detail!.id, 'approved')} style={{ background: '#52c41a' }}>Approve</Button>
                            <Button danger icon={<CloseCircleOutlined />} onClick={() => handleReview(detail!.id, 'rejected')}>Reject</Button>
                        </Space>
                    ) : null}
                >
                    {detail && (
                        <Space direction="vertical" size={16} style={{ width: '100%' }}>
                            <Descriptions column={2} size="small" bordered>
                                <Descriptions.Item label="Status"><Tag color={STATUS_MAP[detail.status]?.color}>{detail.status}</Tag></Descriptions.Item>
                                <Descriptions.Item label="Score">{detail.totalScore > 0 ? `${detail.totalScore.toFixed(2)} / ${detail.maxPossibleScore}` : '—'}</Descriptions.Item>
                                <Descriptions.Item label="Percentage">{detail.percentage > 0 ? <Progress percent={detail.percentage} size="small" strokeColor={gradeColor(detail.grade)} /> : '—'}</Descriptions.Item>
                                <Descriptions.Item label="Grade">{detail.grade ? <Tag color={gradeColor(detail.grade)}>{detail.grade}</Tag> : '—'}</Descriptions.Item>
                                <Descriptions.Item label="Submitted">{detail.submittedAt ? dayjs(detail.submittedAt).format('YYYY-MM-DD HH:mm') : '—'}</Descriptions.Item>
                                <Descriptions.Item label="Reviewed">{detail.reviewedAt ? dayjs(detail.reviewedAt).format('YYYY-MM-DD HH:mm') : '—'}</Descriptions.Item>
                            </Descriptions>
                            {scores.length > 0 && (
                                <Card size="small" title="Dimension Scores" style={{ background: isDark ? 'rgba(255,255,255,0.03)' : '#fafafa' }}>
                                    {scores.map((s: any) => (
                                        <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 0', borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'}` }}>
                                            <Text style={{ width: 120 }}>{s.dimension}</Text>
                                            <Progress percent={Math.round((s.score / s.maxScore) * 100)} size="small" style={{ flex: 1 }} />
                                            <Text type="secondary">{s.score.toFixed(1)}/{s.maxScore}</Text>
                                            <Tag>{(s.weight * 100).toFixed(0)}%</Tag>
                                        </div>
                                    ))}
                                </Card>
                            )}
                            {(detail.fieldValues?.length ?? 0) > 0 && (
                                <Card size="small" title="Answers" style={{ background: isDark ? 'rgba(255,255,255,0.03)' : '#fafafa' }}>
                                    {detail.fieldValues!.map((fv: any) => (
                                        <div key={fv.id} style={{ padding: '8px 0', borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'}` }}>
                                            <Text strong>{fv.fieldLabel}</Text> <Tag style={{ fontSize: 10 }}>{fv.fieldType}</Tag>
                                            <div style={{ marginTop: 4 }}>
                                                <Text>{fv.value || (fv.numericValue != null ? fv.numericValue : JSON.stringify(fv.jsonValue))}</Text>
                                                {fv.score > 0 && <Text type="secondary" style={{ marginLeft: 8 }}>Score: {fv.score}/{fv.maxScore}</Text>}
                                            </div>
                                        </div>
                                    ))}
                                </Card>
                            )}
                            {detail.reviewerNotes && <Card size="small" title="Reviewer Notes"><Text>{detail.reviewerNotes}</Text></Card>}
                        </Space>
                    )}
                </Drawer>
            </motion.div>
        </CMSLayout>
    );
}

"use client";
import React, { useState, useEffect, useCallback } from "react";
import { Table, Button, Card, Space, Tag, Input, Select, Modal, Form, message, Tooltip, Dropdown, Badge, Typography, Row, Col, Statistic, Drawer, Rate, Skeleton, Popconfirm, theme, Segmented } from "antd";
import { PlusOutlined, SearchOutlined, ReloadOutlined, CopyOutlined, EditOutlined, DeleteOutlined, EyeOutlined, RocketOutlined, DownloadOutlined, UploadOutlined, FormOutlined, BarChartOutlined, FileTextOutlined, CheckCircleOutlined, ClockCircleOutlined, SafetyOutlined, MoreOutlined, StarOutlined, AuditOutlined, UnorderedListOutlined, ShareAltOutlined, LinkOutlined, AppstoreOutlined } from "@ant-design/icons";
import { motion, AnimatePresence } from "framer-motion";
import type { ColumnsType } from "antd/es/table";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);

const { Text, Paragraph } = Typography;

// ─── Types ──────────────────────────────────────────────

interface FormTemplate {
    id: string; tenantId: string; name: string; description?: string;
    category: string; status: string; settings?: any; scoringConfig?: any;
    styleConfig?: any; version: number; tags?: string[]; fieldCount?: number;
    fields?: FormField[]; createdAt: string; updatedAt: string;
}

interface FormField {
    id: string; fieldType: string; label: string; description?: string;
    isRequired: boolean; sortOrder: number; sectionTitle?: string;
    options?: any; kpiConfig?: any;
}

// ─── Constants ──────────────────────────────────────────

const CATEGORIES = [
    { value: 'kpi', label: 'KPI', color: '#f5222d', icon: <BarChartOutlined /> },
    { value: 'survey', label: 'Survey', color: '#1890ff', icon: <FormOutlined /> },
    { value: 'assessment', label: 'Assessment', color: '#52c41a', icon: <CheckCircleOutlined /> },
    { value: 'checklist', label: 'Checklist', color: '#fa8c16', icon: <UnorderedListOutlined /> },
    { value: 'feedback', label: 'Feedback', color: '#722ed1', icon: <StarOutlined /> },
    { value: 'audit', label: 'Audit', color: '#13c2c2', icon: <AuditOutlined /> },
    { value: 'custom', label: 'Custom', color: '#595959', icon: <FileTextOutlined /> },
];

const STATUSES = [
    { value: 'draft', label: 'Draft', color: 'default' },
    { value: 'published', label: 'Published', color: 'green' },
    { value: 'archived', label: 'Archived', color: 'orange' },
    { value: 'closed', label: 'Closed', color: 'red' },
];

const glass = { background: 'rgba(255, 255, 255, 0.4)', backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)', boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.07)', border: '1px solid rgba(255, 255, 255, 0.6)', borderRadius: 12 };

const TEMPLATE_FRAGMENT = `
    id tenantId name description category status settings scoringConfig
    styleConfig version tags fieldCount createdAt updatedAt
`;

// ─── Page ───────────────────────────────────────────────

export default function FormTemplatesPage() {
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [data, setData] = useState<FormTemplate[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [catFilter, setCatFilter] = useState<string>('');
    const [statusFilter, setStatusFilter] = useState<string>('');
    const [modalOpen, setModalOpen] = useState(false);
    const [editRecord, setEditRecord] = useState<FormTemplate | null>(null);
    const [detailOpen, setDetailOpen] = useState(false);
    const [detailRecord, setDetailRecord] = useState<FormTemplate | null>(null);
    const [detailFields, setDetailFields] = useState<FormField[]>([]);
    const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
    const [form] = Form.useForm();
    const [messageApi, ctx] = message.useMessage();
    const router = useRouter();

    // ── Stats ──
    const stats = {
        total: data.length,
        published: data.filter(d => d.status === 'published').length,
        kpi: data.filter(d => d.category === 'kpi').length,
        draft: data.filter(d => d.status === 'draft').length,
    };

    // ── Load ──
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const res = await gql<{ formTemplates: FormTemplate[] }>(`
                query($tid: String!, $cat: String, $st: String, $q: String) {
                    formTemplates(tenantId: $tid, category: $cat, status: $st, search: $q) { ${TEMPLATE_FRAGMENT} }
                }
            `, { tid: DEFAULT_TENANT_ID, cat: catFilter || null, st: statusFilter || null, q: search || null });
            setData(res.formTemplates || []);
        } catch (e: any) { messageApi.error(e.message); }
        setLoading(false);
    }, [catFilter, statusFilter, search, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    // ── CRUD ──
    const handleSave = async () => {
        try {
            const values = await form.validateFields();
            if (editRecord) {
                await gql(`mutation($id: String!, $input: UpdateFormTemplateInput!) { updateFormTemplate(id: $id, input: $input) { id } }`,
                    { id: editRecord.id, input: values });
                messageApi.success('Template updated');
            } else {
                await gql(`mutation($tid: String!, $input: CreateFormTemplateInput!) { createFormTemplate(tenantId: $tid, input: $input) { id } }`,
                    { tid: DEFAULT_TENANT_ID, input: values });
                messageApi.success('Template created');
            }
            setModalOpen(false); form.resetFields(); setEditRecord(null); loadData();
        } catch (e: any) { if (e.errorFields) return; messageApi.error(e.message); }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteFormTemplate(id: $id) }`, { id });
            messageApi.success('Template deleted');
            loadData();
        } catch (e: any) { messageApi.error(e.message); }
    };

    const handleDuplicate = async (id: string) => {
        try {
            await gql(`mutation($id: String!, $tid: String!) { duplicateFormTemplate(id: $id, tenantId: $tid) { id name } }`,
                { id, tid: DEFAULT_TENANT_ID });
            messageApi.success('Template duplicated');
            loadData();
        } catch (e: any) { messageApi.error(e.message); }
    };

    const handlePublish = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { publishFormTemplate(id: $id) { id status } }`, { id });
            messageApi.success('Template published');
            loadData();
        } catch (e: any) { messageApi.error(e.message); }
    };

    // ── Export/Import ──
    const handleExport = async (id: string) => {
        try {
            const res = await gql<{ formTemplate: FormTemplate }>(`
                query($id: String!) {
                    formTemplate(id: $id) { ${TEMPLATE_FRAGMENT} fields { id fieldType label description placeholder isRequired sortOrder sectionTitle sectionId options kpiConfig validation conditional defaultValue metadata } }
                }
            `, { id });
            const tpl = res.formTemplate;
            const exportData = {
                _type: 'nusantarasoft_form_template',
                _version: '1.0',
                _exportedAt: new Date().toISOString(),
                template: { name: tpl.name, description: tpl.description, category: tpl.category, settings: tpl.settings, scoringConfig: tpl.scoringConfig, tags: tpl.tags },
                fields: (tpl.fields || []).map((f: any) => ({ fieldType: f.fieldType, label: f.label, description: f.description, placeholder: f.placeholder, isRequired: f.isRequired, sortOrder: f.sortOrder, sectionTitle: f.sectionTitle, sectionId: f.sectionId, options: f.options, kpiConfig: f.kpiConfig, validation: f.validation, conditional: f.conditional, defaultValue: f.defaultValue, metadata: f.metadata })),
            };
            const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a'); a.href = url; a.download = `${tpl.name.replace(/[^a-z0-9]/gi, '_').toLowerCase()}_form.json`; a.click();
            URL.revokeObjectURL(url);
            messageApi.success(`Exported: ${tpl.name}`);
        } catch (e: any) { messageApi.error(e.message); }
    };

    const handleImport = async (file: File) => {
        try {
            const text = await file.text();
            const data = JSON.parse(text);
            if (data._type !== 'nusantarasoft_form_template') throw new Error('Invalid form template file');
            // Create template
            const res = await gql<{ createFormTemplate: FormTemplate }>(`
                mutation($tid: String!, $input: CreateFormTemplateInput!) {
                    createFormTemplate(tenantId: $tid, input: $input) { id name }
                }
            `, { tid: DEFAULT_TENANT_ID, input: { ...data.template, name: `${data.template.name} (Imported)`, status: 'draft' } });
            // Save fields
            if (data.fields?.length > 0) {
                await gql(`
                    mutation($tid: String!, $fields: [FormFieldInput!]!) {
                        saveFormFields(templateId: $tid, fields: $fields) { id }
                    }
                `, { tid: res.createFormTemplate.id, fields: data.fields });
            }
            messageApi.success(`Imported: ${res.createFormTemplate.name} with ${data.fields?.length || 0} fields`);
            loadData();
        } catch (e: any) { messageApi.error('Import failed: ' + e.message); }
        return false;
    };

    const handleCopyShareLink = (id: string) => {
        const url = `${window.location.origin}/admin/forms/fill?id=${id}`;
        navigator.clipboard.writeText(url);
        messageApi.success('Share link copied to clipboard!');
    };

    const openDetail = async (record: FormTemplate) => {
        setDetailRecord(record);
        setDetailOpen(true);
        try {
            const res = await gql<{ formTemplate: FormTemplate }>(`
                query($id: String!) {
                    formTemplate(id: $id) { ${TEMPLATE_FRAGMENT} fields { id fieldType label description isRequired sortOrder sectionTitle options kpiConfig } }
                }
            `, { id: record.id });
            setDetailFields(res.formTemplate.fields || []);
        } catch { setDetailFields([]); }
    };

    // ── Columns ──
    const columns: ColumnsType<FormTemplate> = [
        {
            title: 'Name', dataIndex: 'name', key: 'name',
            render: (name: string, rec) => (
                <Space direction="vertical" size={0}>
                    <Text strong style={{ cursor: 'pointer', color: '#1890ff' }} onClick={() => openDetail(rec)}>{name}</Text>
                    {rec.description && <Text type="secondary" style={{ fontSize: 12 }}>{rec.description.slice(0, 60)}{rec.description.length > 60 ? '…' : ''}</Text>}
                </Space>
            ),
        },
        {
            title: 'Category', dataIndex: 'category', key: 'category', width: 120,
            render: (cat: string) => {
                const c = CATEGORIES.find(c => c.value === cat);
                return c ? <Tag icon={c.icon} color={c.color}>{c.label}</Tag> : <Tag>{cat}</Tag>;
            },
        },
        {
            title: 'Status', dataIndex: 'status', key: 'status', width: 110,
            render: (st: string) => {
                const s = STATUSES.find(s => s.value === st);
                return <Badge status={st === 'published' ? 'success' : st === 'draft' ? 'default' : 'warning'} text={<Tag color={s?.color}>{s?.label || st}</Tag>} />;
            },
        },
        {
            title: 'Fields', dataIndex: 'fieldCount', key: 'fieldCount', width: 80, align: 'center' as const,
            render: (c: number) => <Tag color="blue">{c || 0}</Tag>,
        },
        {
            title: 'Version', dataIndex: 'version', key: 'version', width: 80, align: 'center' as const,
            render: (v: number) => <Text type="secondary">v{v}</Text>,
        },
        {
            title: 'Updated', dataIndex: 'updatedAt', key: 'updatedAt', width: 130,
            render: (d: string) => <Tooltip title={dayjs(d).format('YYYY-MM-DD HH:mm')}><Text type="secondary">{dayjs(d).fromNow()}</Text></Tooltip>,
        },
        {
            title: '', key: 'actions', width: 160, align: 'right' as const,
            render: (_: any, rec) => (
                <Space size={4}>
                    <Tooltip title="View"><Button type="text" size="small" icon={<EyeOutlined />} onClick={() => openDetail(rec)} /></Tooltip>
                    <Tooltip title="Edit"><Button type="text" size="small" icon={<EditOutlined />} onClick={() => { setEditRecord(rec); form.setFieldsValue({ name: rec.name, description: rec.description, category: rec.category, tags: rec.tags }); setModalOpen(true); }} /></Tooltip>
                    <Tooltip title="Open Builder"><Button type="text" size="small" icon={<FormOutlined style={{ color: '#8b5cf6' }} />} onClick={() => router.push(`/admin/forms/builder?id=${rec.id}`)} /></Tooltip>
                    {rec.status === 'published' && <Tooltip title="Fill Form"><Button type="text" size="small" icon={<CheckCircleOutlined style={{ color: '#10b981' }} />} onClick={() => router.push(`/admin/forms/fill?id=${rec.id}`)} /></Tooltip>}
                    {rec.status === 'draft' && <Tooltip title="Publish"><Button type="text" size="small" icon={<RocketOutlined style={{ color: '#52c41a' }} />} onClick={() => handlePublish(rec.id)} /></Tooltip>}
                    <Dropdown menu={{ items: [
                        { key: 'dup', label: 'Duplicate', icon: <CopyOutlined />, onClick: () => handleDuplicate(rec.id) },
                        { key: 'export', label: 'Export JSON', icon: <DownloadOutlined />, onClick: () => handleExport(rec.id) },
                        { key: 'share', label: 'Copy Share Link', icon: <LinkOutlined />, onClick: () => handleCopyShareLink(rec.id) },
                        { type: 'divider' as const },
                        { key: 'del', label: <Popconfirm title="Delete this template?" onConfirm={() => handleDelete(rec.id)}><span style={{ color: '#ff4d4f' }}>Delete</span></Popconfirm>, icon: <DeleteOutlined style={{ color: '#ff4d4f' }} />, danger: true },
                    ] }}><Button type="text" size="small" icon={<MoreOutlined />} /></Dropdown>
                </Space>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText>Form Builder</AuroraText>}
            subTitle={<DecryptedText text="Create KPI evaluations, surveys, checklists & more" speed={40} revealDirection="start" />}
            extra={[
                <Segmented
                    key="view"
                    options={[
                        { value: 'grid', icon: <AppstoreOutlined /> },
                        { value: 'table', icon: <UnorderedListOutlined /> }
                    ]}
                    value={viewMode}
                    onChange={(val) => setViewMode(val as "grid" | "table")}
                />,
                <Button key="import" icon={<UploadOutlined />} onClick={() => { const input = document.createElement('input'); input.type = 'file'; input.accept = '.json'; input.onchange = (e: any) => { if (e.target.files?.[0]) handleImport(e.target.files[0]); }; input.click(); }}>Import</Button>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditRecord(null); form.resetFields(); setModalOpen(true); }} style={{ background: '#8b5cf6', borderColor: '#8b5cf6' }}>New Template</Button>,
            ]}
        >
            {ctx}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.4 }}>
                {/* Stats Row */}
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    {[
                        { title: 'Total Forms', value: stats.total, color: '#1890ff', icon: <FormOutlined /> },
                        { title: 'Published', value: stats.published, color: '#52c41a', icon: <CheckCircleOutlined /> },
                        { title: 'KPI Forms', value: stats.kpi, color: '#f5222d', icon: <BarChartOutlined /> },
                        { title: 'Drafts', value: stats.draft, color: '#faad14', icon: <ClockCircleOutlined /> },
                    ].map((s, i) => (
                        <Col xs={12} md={6} key={i}>
                            <Card style={{ ...glass, borderLeft: `3px solid ${s.color}` }} bodyStyle={{ padding: '16px 20px' }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 24 }} />
                            </Card>
                        </Col>
                    ))}
                </Row>

                {/* Filters */}
                <Card style={{ ...glass, marginBottom: 16 }} bodyStyle={{ padding: '12px 16px' }}>
                    <Row gutter={12} align="middle">
                        <Col flex="auto">
                            <Input prefix={<SearchOutlined />} placeholder="Search templates…" value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 300 }} />
                        </Col>
                        <Col>
                            <Select placeholder="Category" allowClear style={{ width: 140 }} value={catFilter || undefined} onChange={v => setCatFilter(v || '')}
                                options={CATEGORIES.map(c => ({ value: c.value, label: c.label }))} />
                        </Col>
                        <Col>
                            <Select placeholder="Status" allowClear style={{ width: 130 }} value={statusFilter || undefined} onChange={v => setStatusFilter(v || '')}
                                options={STATUSES.map(s => ({ value: s.value, label: s.label }))} />
                        </Col>
                    </Row>
                </Card>

                {/* Data View */}
                {viewMode === 'table' ? (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                        <Card style={glass}>
                            <Table<FormTemplate>
                                dataSource={data} columns={columns} rowKey="id"
                                loading={loading} pagination={{ pageSize: 15, showSizeChanger: true, showTotal: (t) => `${t} templates` }}
                                size="middle"
                            />
                        </Card>
                    </motion.div>
                ) : (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                        <Row gutter={[16, 16]}>
                            <AnimatePresence>
                                {data.map((rec, index) => {
                                    const c = CATEGORIES.find(cat => cat.value === rec.category);
                                    return (
                                        <Col xs={24} sm={12} md={8} lg={6} key={rec.id}>
                                            <motion.div
                                                initial={{ opacity: 0, y: 20 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                exit={{ opacity: 0, scale: 0.9 }}
                                                transition={{ delay: index * 0.05 }}
                                            >
                                                <Card
                                                    hoverable
                                                    style={{ ...glass, height: '100%', borderTop: `3px solid ${c?.color || '#d9d9d9'}` }}
                                                    bodyStyle={{ padding: 16 }}
                                                    actions={[
                                                        <Tooltip key="preview" title="View Details"><EyeOutlined onClick={() => openDetail(rec)} /></Tooltip>,
                                                        <Tooltip key="edit" title="Builder"><FormOutlined style={{ color: '#8b5cf6' }} onClick={() => router.push(`/admin/forms/builder?id=${rec.id}`)} /></Tooltip>,
                                                        rec.status === 'published' ? <Tooltip key="fill" title="Fill Form"><CheckCircleOutlined style={{ color: '#10b981' }} onClick={() => router.push(`/admin/forms/fill?id=${rec.id}`)} /></Tooltip> : <Tooltip key="publish" title="Publish"><RocketOutlined style={{ color: '#52c41a' }} onClick={() => handlePublish(rec.id)} /></Tooltip>,
                                                        <Dropdown key="more" menu={{ items: [
                                                            { key: 'editMeta', label: 'Edit Metadata', icon: <EditOutlined />, onClick: () => { setEditRecord(rec); form.setFieldsValue({ name: rec.name, description: rec.description, category: rec.category, tags: rec.tags }); setModalOpen(true); } },
                                                            { key: 'dup', label: 'Duplicate', icon: <CopyOutlined />, onClick: () => handleDuplicate(rec.id) },
                                                            { key: 'export', label: 'Export JSON', icon: <DownloadOutlined />, onClick: () => handleExport(rec.id) },
                                                            { key: 'share', label: 'Copy Share Link', icon: <LinkOutlined />, onClick: () => handleCopyShareLink(rec.id) },
                                                            { type: 'divider' },
                                                            { key: 'del', label: <Popconfirm title="Delete this template?" onConfirm={() => handleDelete(rec.id)}><span style={{ color: '#ff4d4f' }}>Delete</span></Popconfirm>, icon: <DeleteOutlined style={{ color: '#ff4d4f' }} />, danger: true },
                                                        ] }}><MoreOutlined /></Dropdown>
                                                    ]}
                                                >
                                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                                                        <div style={{ fontWeight: 600, fontSize: 16 }}>
                                                            <a onClick={() => openDetail(rec)} style={{ color: 'inherit' }}>{rec.name}</a>
                                                        </div>
                                                    </div>
                                                    <div style={{ color: '#666', fontSize: 12, height: 36, overflow: 'hidden', textOverflow: 'ellipsis', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', marginBottom: 12 }}>
                                                        {rec.description || 'No description provided.'}
                                                    </div>
                                                    <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 12 }}>
                                                        {c ? <Tag icon={c.icon} color={c.color} style={{ margin: 0 }}>{c.label}</Tag> : <Tag style={{ margin: 0 }}>{rec.category}</Tag>}
                                                        {(() => {
                                                            const s = STATUSES.find(st => st.value === rec.status);
                                                            return <Badge status={rec.status === 'published' ? 'success' : rec.status === 'draft' ? 'default' : 'warning'} text={<Tag color={s?.color} style={{ margin: 0 }}>{s?.label || rec.status}</Tag>} />;
                                                        })()}
                                                    </div>
                                                    <div style={{ display: 'flex', justifyContent: 'space-between', color: '#888', fontSize: 11 }}>
                                                        <span><FileTextOutlined /> {rec.fieldCount || 0} fields</span>
                                                        <span>v{rec.version} · {dayjs(rec.updatedAt).fromNow(true)} ago</span>
                                                    </div>
                                                </Card>
                                            </motion.div>
                                        </Col>
                                    );
                                })}
                            </AnimatePresence>
                        </Row>
                    </motion.div>
                )}

                {/* Create/Edit Modal */}
                <Modal title={editRecord ? 'Edit Template' : 'New Form Template'} open={modalOpen}
                    onCancel={() => { setModalOpen(false); form.resetFields(); setEditRecord(null); }}
                    onOk={handleSave} okText={editRecord ? 'Update' : 'Create'} width={560}
                    styles={{ body: { paddingTop: 16 } }}
                >
                    <Form form={form} layout="vertical">
                        <Form.Item name="name" label="Template Name" rules={[{ required: true, message: 'Name is required' }]}>
                            <Input placeholder="e.g. Employee KPI Evaluation Q2 2026" />
                        </Form.Item>
                        <Form.Item name="description" label="Description">
                            <Input.TextArea rows={3} placeholder="Purpose and instructions for this form" />
                        </Form.Item>
                        <Row gutter={16}>
                            <Col span={12}>
                                <Form.Item name="category" label="Category" initialValue="custom">
                                    <Select options={CATEGORIES.map(c => ({ value: c.value, label: c.label }))} />
                                </Form.Item>
                            </Col>
                            <Col span={12}>
                                <Form.Item name="tags" label="Tags">
                                    <Select mode="tags" placeholder="Add tags" />
                                </Form.Item>
                            </Col>
                        </Row>
                    </Form>
                </Modal>

                {/* Detail Drawer */}
                <Drawer title={detailRecord?.name || 'Template Details'} open={detailOpen} onClose={() => { setDetailOpen(false); setDetailRecord(null); setDetailFields([]); }}
                    width={600} extra={
                        <Space>
                            {detailRecord?.status === 'draft' && <Button type="primary" size="small" icon={<RocketOutlined />} onClick={() => { handlePublish(detailRecord!.id); setDetailOpen(false); }}>Publish</Button>}
                            <Button size="small" icon={<EditOutlined />} onClick={() => { if (detailRecord) { setEditRecord(detailRecord); form.setFieldsValue({ name: detailRecord.name, description: detailRecord.description, category: detailRecord.category, tags: detailRecord.tags }); setModalOpen(true); setDetailOpen(false); } }}>Edit</Button>
                            <Button size="small" type="primary" icon={<FormOutlined />} onClick={() => { if (detailRecord) { router.push(`/admin/forms/builder?id=${detailRecord.id}`); } }} style={{ background: '#8b5cf6', borderColor: '#8b5cf6' }}>Open Builder</Button>
                        </Space>
                    }
                >
                    {detailRecord && (
                        <Space direction="vertical" size={16} style={{ width: '100%' }}>
                            <Row gutter={12}>
                                <Col span={8}><Text type="secondary">Category</Text><br />{(() => { const c = CATEGORIES.find(c => c.value === detailRecord.category); return c ? <Tag icon={c.icon} color={c.color}>{c.label}</Tag> : <Tag>{detailRecord.category}</Tag>; })()}</Col>
                                <Col span={8}><Text type="secondary">Status</Text><br /><Tag color={STATUSES.find(s => s.value === detailRecord.status)?.color}>{detailRecord.status}</Tag></Col>
                                <Col span={8}><Text type="secondary">Version</Text><br /><Text>v{detailRecord.version}</Text></Col>
                            </Row>
                            {detailRecord.description && <Paragraph type="secondary">{detailRecord.description}</Paragraph>}
                            {(detailRecord.tags?.length ?? 0) > 0 && <div>{detailRecord.tags!.map((t: string) => <Tag key={t} color="blue">{t}</Tag>)}</div>}
                            {detailRecord.scoringConfig?.grading_scale && (
                                <Card size="small" title="Grading Scale" style={{ background: isDark ? 'rgba(255,255,255,0.03)' : '#fafafa' }}>
                                    {detailRecord.scoringConfig.grading_scale.map((g: any, i: number) => (
                                        <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 0', borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'}` }}>
                                            <Tag color={g.color}>{g.label}</Tag>
                                            <Text type="secondary">{g.min} – {g.max}</Text>
                                        </div>
                                    ))}
                                </Card>
                            )}
                            <Card size="small" title={`Fields (${detailFields.length})`} style={{ background: isDark ? 'rgba(255,255,255,0.03)' : '#fafafa' }}>
                                {detailFields.length === 0 ? <Text type="secondary">No fields yet. Use the Builder to add fields.</Text> :
                                    detailFields.map((f, i) => (
                                        <div key={f.id} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 0', borderBottom: i < detailFields.length - 1 ? `1px solid ${isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0'}` : 'none' }}>
                                            <Tag color="blue" style={{ minWidth: 70, textAlign: 'center' }}>{f.fieldType}</Tag>
                                            <div style={{ flex: 1 }}>
                                                <Text strong>{f.label}</Text>
                                                {f.isRequired && <Text type="danger" style={{ marginLeft: 4 }}>*</Text>}
                                                {f.sectionTitle && <Text type="secondary" style={{ fontSize: 11, display: 'block' }}>§ {f.sectionTitle}</Text>}
                                            </div>
                                            {f.kpiConfig?.weight && <Tag color="red">{f.kpiConfig.weight}%</Tag>}
                                        </div>
                                    ))
                                }
                            </Card>
                        </Space>
                    )}
                </Drawer>
            </motion.div>
        </CMSLayout>
    );
}

"use client";
import React, { useState } from "react";
import { Card, Button, Space, Tag, Typography, Row, Col, Switch, Divider, Timeline, Select, Steps, Badge, Empty, Tooltip, Input, message } from "antd";
import {
    ThunderboltOutlined, FormOutlined, MailOutlined, BellOutlined,
    TeamOutlined, CheckCircleOutlined, ClockCircleOutlined, RocketOutlined,
    PlusOutlined, SettingOutlined, BranchesOutlined, PlayCircleOutlined,
    EditOutlined, DeleteOutlined, ArrowRightOutlined, SyncOutlined,
    ApartmentOutlined, FlagOutlined, SafetyOutlined, StarOutlined,
    ApiOutlined,
} from "@ant-design/icons";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const { Text, Title, Paragraph } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Workflow {
    id: string;
    name: string;
    trigger: string;
    actions: string[];
    enabled: boolean;
    lastRun?: string;
    runCount: number;
}

const SAMPLE_WORKFLOWS: Workflow[] = [
    {
        id: '1', name: 'KPI Auto-Scoring', trigger: 'on_submit',
        actions: ['calculate_score', 'notify_reviewer', 'update_hr_record'],
        enabled: true, lastRun: '2 hours ago', runCount: 47,
    },
    {
        id: '2', name: 'Survey Completion Reminder', trigger: 'on_due_date',
        actions: ['send_reminder', 'escalate_to_manager'],
        enabled: true, lastRun: '1 day ago', runCount: 23,
    },
    {
        id: '3', name: 'Audit Form Approval', trigger: 'on_submit',
        actions: ['assign_reviewer', 'create_itsm_ticket', 'send_notification'],
        enabled: false, lastRun: '3 days ago', runCount: 12,
    },
    {
        id: '4', name: 'Employee Onboarding', trigger: 'on_publish',
        actions: ['assign_to_department', 'set_due_date', 'notify_assignees'],
        enabled: true, lastRun: 'Never', runCount: 0,
    },
    {
        id: '5', name: 'Quality Assessment Flow', trigger: 'on_review',
        actions: ['calculate_score', 'update_pm_metrics', 'create_report'],
        enabled: true, lastRun: '5 hours ago', runCount: 31,
    },
];

const TRIGGERS: Record<string, { label: string; color: string; icon: React.ReactNode }> = {
    on_submit: { label: 'On Submit', color: '#3b82f6', icon: <FormOutlined /> },
    on_review: { label: 'On Review', color: '#8b5cf6', icon: <CheckCircleOutlined /> },
    on_due_date: { label: 'Before Due Date', color: '#f59e0b', icon: <ClockCircleOutlined /> },
    on_publish: { label: 'On Publish', color: '#10b981', icon: <RocketOutlined /> },
    on_assign: { label: 'On Assignment', color: '#ec4899', icon: <TeamOutlined /> },
    scheduled: { label: 'Scheduled', color: '#06b6d4', icon: <SyncOutlined /> },
};

const ACTIONS: Record<string, { label: string; color: string; icon: React.ReactNode; module?: string }> = {
    calculate_score: { label: 'Calculate Score', color: '#8b5cf6', icon: <StarOutlined />, module: 'Forms' },
    notify_reviewer: { label: 'Notify Reviewer', color: '#3b82f6', icon: <MailOutlined />, module: 'Notifications' },
    send_notification: { label: 'Send Notification', color: '#3b82f6', icon: <BellOutlined />, module: 'Notifications' },
    send_reminder: { label: 'Send Reminder', color: '#f59e0b', icon: <ClockCircleOutlined />, module: 'Notifications' },
    assign_reviewer: { label: 'Auto-Assign Reviewer', color: '#10b981', icon: <TeamOutlined />, module: 'Forms' },
    assign_to_department: { label: 'Assign to Department', color: '#ec4899', icon: <ApartmentOutlined />, module: 'HR' },
    set_due_date: { label: 'Set Due Date', color: '#06b6d4', icon: <FlagOutlined />, module: 'Forms' },
    notify_assignees: { label: 'Notify Assignees', color: '#f59e0b', icon: <MailOutlined />, module: 'Notifications' },
    escalate_to_manager: { label: 'Escalate to Manager', color: '#ef4444', icon: <ArrowRightOutlined />, module: 'HR' },
    update_hr_record: { label: 'Update HR Record', color: '#ef4444', icon: <TeamOutlined />, module: 'HR' },
    update_pm_metrics: { label: 'Update PM Metrics', color: '#13c2c2', icon: <ApiOutlined />, module: 'PM' },
    create_itsm_ticket: { label: 'Create ITSM Ticket', color: '#722ed1', icon: <SafetyOutlined />, module: 'ITSM' },
    create_report: { label: 'Generate Report', color: '#1890ff', icon: <FormOutlined />, module: 'Reports' },
};

export default function FormWorkflowsPage() {
    const { themeColor } = usePreferencesStore();
    const [workflows, setWorkflows] = useState<Workflow[]>(SAMPLE_WORKFLOWS);
    const [messageApi, contextHolder] = message.useMessage();
    const [expandedId, setExpandedId] = useState<string | null>('1');

    const toggleEnabled = (id: string) => {
        setWorkflows(wfs => wfs.map(w => w.id === id ? { ...w, enabled: !w.enabled } : w));
        const wf = workflows.find(w => w.id === id);
        messageApi.success(`${wf?.name} ${wf?.enabled ? 'disabled' : 'enabled'}`);
    };

    const stats = {
        total: workflows.length,
        active: workflows.filter(w => w.enabled).length,
        totalRuns: workflows.reduce((s, w) => s + w.runCount, 0),
    };

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#f59e0b', '#10b981']}>Form Workflows</AuroraText>}
            subTitle={<DecryptedText text="Automate form lifecycle with triggers & actions" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <Button key="new" type="primary" icon={<PlusOutlined />} style={{ background: themeColor, borderColor: themeColor }}>
                    Create Workflow
                </Button>,
            ]}
        >
            {contextHolder}
            <div style={{ maxWidth: 1000, margin: '0 auto' }}>
                {/* Stats */}
                <Row gutter={[16, 16]} style={{ marginBottom: 20 }}>
                    {[
                        { label: 'Total Workflows', value: stats.total, color: '#3b82f6', icon: <BranchesOutlined /> },
                        { label: 'Active', value: stats.active, color: '#10b981', icon: <PlayCircleOutlined /> },
                        { label: 'Total Runs', value: stats.totalRuns, color: '#8b5cf6', icon: <ThunderboltOutlined /> },
                    ].map((s, i) => (
                        <Col xs={8} key={i}>
                            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card style={{ ...glass, borderTop: `3px solid ${s.color}` }} bodyStyle={{ padding: '14px 18px' }}>
                                    <Space>
                                        <span style={{ fontSize: 20, color: s.color }}>{s.icon}</span>
                                        <div>
                                            <Text type="secondary" style={{ fontSize: 10 }}>{s.label}</Text>
                                            <div><Text strong style={{ fontSize: 20, color: s.color }}>{s.value}</Text></div>
                                        </div>
                                    </Space>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Workflow Cards */}
                <Space direction="vertical" size={12} style={{ width: '100%' }}>
                    <AnimatePresence>
                        {workflows.map((wf, idx) => {
                            const trigger = TRIGGERS[wf.trigger] || TRIGGERS['on_submit'];
                            const isExpanded = expandedId === wf.id;

                            return (
                                <motion.div key={wf.id}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: idx * 0.05 }}
                                >
                                    <Card
                                        style={{
                                            ...glass,
                                            borderLeft: `4px solid ${wf.enabled ? trigger.color : '#d1d5db'}`,
                                            opacity: wf.enabled ? 1 : 0.6,
                                            cursor: 'pointer',
                                        }}
                                        bodyStyle={{ padding: '16px 20px' }}
                                        onClick={() => setExpandedId(isExpanded ? null : wf.id)}
                                    >
                                        {/* Header */}
                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                            <Space size={12}>
                                                <div style={{
                                                    width: 36, height: 36, borderRadius: 10,
                                                    background: `${trigger.color}15`,
                                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                    fontSize: 18, color: trigger.color,
                                                }}>
                                                    {trigger.icon}
                                                </div>
                                                <div>
                                                    <Text strong style={{ fontSize: 14 }}>{wf.name}</Text>
                                                    <div>
                                                        <Tag color={trigger.color} style={{ fontSize: 10 }}>{trigger.label}</Tag>
                                                        <Tag style={{ fontSize: 10 }}>{wf.actions.length} actions</Tag>
                                                        {wf.runCount > 0 && <Text type="secondary" style={{ fontSize: 10, marginLeft: 4 }}>{wf.runCount} runs</Text>}
                                                    </div>
                                                </div>
                                            </Space>
                                            <Space onClick={e => e.stopPropagation()}>
                                                <Text type="secondary" style={{ fontSize: 11, marginRight: 8 }}>
                                                    {wf.lastRun || 'Never'}
                                                </Text>
                                                <Switch checked={wf.enabled} onChange={() => toggleEnabled(wf.id)} size="small" />
                                            </Space>
                                        </div>

                                        {/* Expanded Detail */}
                                        <AnimatePresence>
                                            {isExpanded && (
                                                <motion.div
                                                    initial={{ height: 0, opacity: 0 }}
                                                    animate={{ height: 'auto', opacity: 1 }}
                                                    exit={{ height: 0, opacity: 0 }}
                                                    transition={{ duration: 0.2 }}
                                                    style={{ overflow: 'hidden' }}
                                                >
                                                    <Divider style={{ margin: '12px 0' }} />
                                                    <div style={{ padding: '0 4px' }}>
                                                        <Text type="secondary" style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1 }}>Action Pipeline</Text>
                                                        <div style={{ marginTop: 10 }}>
                                                            <Steps direction="vertical" size="small" current={wf.actions.length}
                                                                items={wf.actions.map(actionKey => {
                                                                    const action = ACTIONS[actionKey];
                                                                    if (!action) return { title: actionKey };
                                                                    return {
                                                                        title: (
                                                                            <Space>
                                                                                <span style={{ color: action.color }}>{action.icon}</span>
                                                                                <Text style={{ fontSize: 12 }}>{action.label}</Text>
                                                                                {action.module && <Tag style={{ fontSize: 9 }}>{action.module}</Tag>}
                                                                            </Space>
                                                                        ),
                                                                        status: 'finish' as const,
                                                                        icon: <div style={{
                                                                            width: 24, height: 24, borderRadius: 6,
                                                                            background: `${action.color}20`, color: action.color,
                                                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                                            fontSize: 12,
                                                                        }}>{action.icon}</div>,
                                                                    };
                                                                })}
                                                            />
                                                        </div>
                                                        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 8 }}>
                                                            <Button size="small" icon={<PlayCircleOutlined />} style={{ borderRadius: 6 }}>Test Run</Button>
                                                            <Button size="small" icon={<EditOutlined />} style={{ borderRadius: 6 }}>Edit</Button>
                                                        </div>
                                                    </div>
                                                </motion.div>
                                            )}
                                        </AnimatePresence>
                                    </Card>
                                </motion.div>
                            );
                        })}
                    </AnimatePresence>
                </Space>

                {/* Integration Map */}
                <Card style={{ ...glass, marginTop: 20 }}
                    title={<Space><ApiOutlined style={{ color: '#6366f1' }} /> Cross-Module Integration Map</Space>}>
                    <Row gutter={[16, 16]}>
                        {[
                            { module: 'HR', desc: 'KPI scores → Employee records, Onboarding forms → Auto-assign', color: '#ef4444', icon: <TeamOutlined /> },
                            { module: 'PM', desc: 'Quality metrics → Project dashboard, Checklists → Task completion', color: '#13c2c2', icon: <FlagOutlined /> },
                            { module: 'ITSM', desc: 'Audit forms → Tickets, Security assessments → Compliance', color: '#722ed1', icon: <SafetyOutlined /> },
                            { module: 'CRM', desc: 'Surveys → Customer records, Feedback → Case creation', color: '#1890ff', icon: <FormOutlined /> },
                            { module: 'Notifications', desc: 'Reminders, Escalations, Approval alerts', color: '#f59e0b', icon: <BellOutlined /> },
                            { module: 'Reports', desc: 'Auto-generated KPI reports, Submission analytics', color: '#10b981', icon: <StarOutlined /> },
                        ].map((m, i) => (
                            <Col xs={24} sm={12} md={8} key={i}>
                                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.05 }}>
                                    <Card size="small" hoverable style={{
                                        borderRadius: 12, borderLeft: `3px solid ${m.color}`,
                                        background: `linear-gradient(135deg, ${m.color}05, rgba(255,255,255,0.8))`,
                                        height: '100%',
