                        </motion.div>
                    </Col>

                    {/* Tenure Distribution */}
                    <Col xs={24} md={8}>
                        <motion.div {...anim(9)}>
                            <Card title={<><ClockCircleOutlined /> Tenure Distribution</>} size="small" style={{ ...glass, height: '100%' }}>
                                {tenureGroups.map((g, i) => (
                                    <motion.div key={g.label} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.5 + i * 0.08 }}
