"use client";
import React, { useState, useEffect, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { Card, Table, Tag, Typography, Row, Col, Statistic, Select, Space, Segmented, Avatar, Badge, Tooltip, Progress, Button } from "antd";
import { ClockCircleOutlined, CheckCircleOutlined, ExclamationCircleOutlined, AppstoreOutlined, UnorderedListOutlined, UserOutlined, FieldTimeOutlined, ThunderboltOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const ATT_Q = `query($t:String!,$m:String,$e:String){hrAttendance(tenantId:$t,month:$m,employeeId:$e){id employeeId employeeName employeeNumber date clockIn clockOut status workHours overtimeHours notes}}`;
const EMP_Q = `query($t:String!){hrEmployees(tenantId:$t,status:"active"){id firstName lastName employeeNumber departmentName}}`;

const statusConfig: Record<string, { color: string; bg: string; icon: string; label: string }> = {
    present: { color: '#10b981', bg: 'rgba(16,185,129,0.08)', icon: '✅', label: 'Present' },
    late: { color: '#f59e0b', bg: 'rgba(245,158,11,0.08)', icon: '⏰', label: 'Late' },
    absent: { color: '#ef4444', bg: 'rgba(239,68,68,0.08)', icon: '❌', label: 'Absent' },
    half_day: { color: '#3b82f6', bg: 'rgba(59,130,246,0.08)', icon: '🔵', label: 'Half Day' },
    remote: { color: '#8b5cf6', bg: 'rgba(139,92,246,0.08)', icon: '🏠', label: 'Remote' },
    leave: { color: '#06b6d4', bg: 'rgba(6,182,212,0.08)', icon: '🏖️', label: 'On Leave' },
};

// Calendar Heatmap Component
function CalendarHeatmap({ records, month }: { records: any[]; month: string }) {
    const startOfMonth = dayjs(month + '-01');
    const daysInMonth = startOfMonth.daysInMonth();
    const startDay = startOfMonth.day(); // 0=Sun
    const weeks = Math.ceil((daysInMonth + startDay) / 7);
    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    const dateMap = useMemo(() => {
        const m = new Map<string, any[]>();
        records.forEach(r => {
            const key = r.date;
            if (!m.has(key)) m.set(key, []);
            m.get(key)!.push(r);
        });
        return m;
    }, [records]);

    return (
        <div style={{ overflowX: 'auto' }}>
            {/* Weekday headers */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 4, marginBottom: 4 }}>
                {weekDays.map(d => <div key={d} style={{ textAlign: 'center', fontSize: 10, color: '#9ca3af', fontWeight: 600, padding: 2 }}>{d}</div>)}
            </div>
            {/* Calendar grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 4 }}>
                {/* Empty cells before month start */}
                {Array.from({ length: startDay }, (_, i) => <div key={`empty-${i}`} style={{ aspectRatio: '1', borderRadius: 8 }} />)}
                {/* Day cells */}
                {Array.from({ length: daysInMonth }, (_, i) => {
                    const day = i + 1;
                    const dateStr = startOfMonth.date(day).format('YYYY-MM-DD');
                    const dayRecords = dateMap.get(dateStr) || [];
                    const isToday = dayjs().format('YYYY-MM-DD') === dateStr;
                    const isFuture = dayjs(dateStr).isAfter(dayjs());
                    const isWeekend = [0, 6].includes(startOfMonth.date(day).day());

                    // Determine dominant status
                    let bg = 'rgba(0,0,0,0.02)';
                    let borderColor = 'transparent';
                    if (dayRecords.length > 0) {
                        const present = dayRecords.filter(r => r.status === 'present').length;
                        const late = dayRecords.filter(r => r.status === 'late').length;
                        const absent = dayRecords.filter(r => r.status === 'absent').length;
                        if (absent > 0) { bg = statusConfig.absent.bg; borderColor = statusConfig.absent.color + '44'; }
                        else if (late > 0) { bg = statusConfig.late.bg; borderColor = statusConfig.late.color + '44'; }
                        else if (present > 0) { bg = statusConfig.present.bg; borderColor = statusConfig.present.color + '44'; }
                    }
                    if (isWeekend && dayRecords.length === 0) bg = 'rgba(0,0,0,0.03)';

                    return (
                        <Tooltip key={day} title={dayRecords.length > 0 ?
                            <div>{dayRecords.map((r, j) => <div key={j}>{r.employeeName}: {statusConfig[r.status]?.icon} {r.status} {r.workHours ? `(${r.workHours}h)` : ''}</div>)}</div>
                            : isFuture ? 'Future' : isWeekend ? 'Weekend' : 'No data'}>
                            <motion.div whileHover={{ scale: 1.1 }} style={{
                                aspectRatio: '1', borderRadius: 8, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                                background: isToday ? `linear-gradient(135deg, rgba(59,130,246,0.15), rgba(139,92,246,0.15))` : bg,
                                border: isToday ? '2px solid #3b82f6' : `1px solid ${borderColor}`,
                                opacity: isFuture ? 0.3 : 1, cursor: 'default', position: 'relative', minWidth: 44, minHeight: 44,
                            }}>
                                <Text style={{ fontSize: 12, fontWeight: isToday ? 700 : 500, color: isToday ? '#3b82f6' : isWeekend ? '#9ca3af' : undefined }}>{day}</Text>
                                {dayRecords.length > 0 && (
                                    <div style={{ display: 'flex', gap: 2, marginTop: 2 }}>
                                        {dayRecords.slice(0, 3).map((r, j) => (
                                            <div key={j} style={{ width: 5, height: 5, borderRadius: '50%', backgroundColor: statusConfig[r.status]?.color || '#6b7280' }} />
                                        ))}
                                        {dayRecords.length > 3 && <Text style={{ fontSize: 7, color: '#9ca3af' }}>+{dayRecords.length - 3}</Text>}
                                    </div>
                                )}
                            </motion.div>
                        </Tooltip>
                    );
                })}
            </div>
            {/* Legend */}
            <div style={{ display: 'flex', gap: 12, marginTop: 12, justifyContent: 'center', flexWrap: 'wrap' }}>
                {Object.entries(statusConfig).filter(([k]) => ['present', 'late', 'absent'].includes(k)).map(([key, cfg]) => (
                    <Space key={key} size={4}><div style={{ width: 8, height: 8, borderRadius: '50%', backgroundColor: cfg.color }} /><Text style={{ fontSize: 11 }}>{cfg.label}</Text></Space>
                ))}
            </div>
        </div>
    );
}

// Employee attendance summary card
function EmployeeSummaryCard({ emp, records }: { emp: any; records: any[] }) {
    const empRecords = records.filter(r => r.employeeId === emp.id);
    const present = empRecords.filter(r => r.status === 'present').length;
    const late = empRecords.filter(r => r.status === 'late').length;
    const absent = empRecords.filter(r => r.status === 'absent').length;
    const totalHours = empRecords.reduce((s, r) => s + (r.workHours || 0), 0);
    const totalOT = empRecords.reduce((s, r) => s + (r.overtimeHours || 0), 0);
    const total = present + late + absent || 1;
    const attendancePct = Math.round(((present + late) / total) * 100);

    if (empRecords.length === 0) return null;

    return (
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} whileHover={{ y: -2, boxShadow: '0 4px 16px rgba(0,0,0,0.08)' }}
            style={{ ...glass, padding: 14, borderRadius: 12, cursor: 'default' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
                <Avatar style={{ backgroundColor: attendancePct >= 90 ? '#10b981' : attendancePct >= 70 ? '#f59e0b' : '#ef4444', fontSize: 11 }}>{emp.firstName[0]}{emp.lastName[0]}</Avatar>
                <div style={{ flex: 1 }}>
                    <Text strong style={{ fontSize: 13, display: 'block' }}>{emp.firstName} {emp.lastName}</Text>
                    <Text type="secondary" style={{ fontSize: 10 }}>{emp.departmentName}</Text>
                </div>
                <div style={{ textAlign: 'right' }}>
                    <Text strong style={{ fontSize: 16, color: attendancePct >= 90 ? '#10b981' : '#f59e0b' }}>{attendancePct}%</Text>
                </div>
            </div>
            <Progress percent={attendancePct} showInfo={false} size="small" strokeColor={attendancePct >= 90 ? '#10b981' : attendancePct >= 70 ? '#f59e0b' : '#ef4444'} style={{ marginBottom: 8 }} />
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <Space size={12}>
                    <Tooltip title="Present"><Text style={{ fontSize: 11 }}>✅ {present}</Text></Tooltip>
                    <Tooltip title="Late"><Text style={{ fontSize: 11 }}>⏰ {late}</Text></Tooltip>
                    <Tooltip title="Absent"><Text style={{ fontSize: 11 }}>❌ {absent}</Text></Tooltip>
                </Space>
                <Space size={8}>
                    <Tooltip title="Work Hours"><Text style={{ fontSize: 11, color: '#3b82f6' }}><FieldTimeOutlined /> {totalHours.toFixed(1)}h</Text></Tooltip>
                    {totalOT > 0 && <Tooltip title="Overtime"><Text style={{ fontSize: 11, color: '#f59e0b' }}><ThunderboltOutlined /> {totalOT.toFixed(1)}h</Text></Tooltip>}
                </Space>
            </div>
        </motion.div>
    );
}

export default function AttendancePage() {
    const [records, setRecords] = useState<any[]>([]);
    const [employees, setEmployees] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [month, setMonth] = useState(dayjs().format('YYYY-MM'));
    const [selectedEmployee, setSelectedEmployee] = useState<string | undefined>();
    const [viewMode, setViewMode] = useState<string>('calendar');
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();

    useEffect(() => {
        setLoading(true);
        Promise.all([
            gql(ATT_Q, { t: DEFAULT_TENANT_ID, m: month, e: selectedEmployee }).catch(() => ({ hrAttendance: [] })),
            gql(EMP_Q, { t: DEFAULT_TENANT_ID }).catch(() => ({ hrEmployees: [] })),
        ]).then(([a, e]) => { setRecords(a.hrAttendance || []); setEmployees(e.hrEmployees || []); })
            .finally(() => setLoading(false));
    }, [month, selectedEmployee]);

    const present = records.filter(r => r.status === 'present').length;
    const late = records.filter(r => r.status === 'late').length;
    const absent = records.filter(r => r.status === 'absent').length;
    const totalHours = records.reduce((s, r) => s + (r.workHours || 0), 0);
    const totalOT = records.reduce((s, r) => s + (r.overtimeHours || 0), 0);
    const avgHours = records.length > 0 ? (totalHours / records.filter(r => r.workHours > 0).length).toFixed(1) : '—';

    // Unique employees with records
    const uniqueEmps = useMemo(() => {
        const ids = new Set(records.map(r => r.employeeId));
        return employees.filter(e => ids.has(e.id));
    }, [records, employees]);

    const columns = [
        { title: 'Employee', key: 'emp', render: (_: any, r: any) => <Space><Avatar size="small" style={{ backgroundColor: statusConfig[r.status]?.color || themeColor, fontSize: 10 }}>{r.employeeName?.split(' ').map((n: string) => n[0]).join('')}</Avatar><div><Text strong style={{ fontSize: 13 }}>{r.employeeName}</Text><br/><Text type="secondary" style={{ fontSize: 10 }}>{r.employeeNumber}</Text></div></Space> },
        { title: 'Date', dataIndex: 'date', key: 'date', render: (v: string) => <Text>{dayjs(v).format('ddd, MMM D')}</Text> },
        { title: 'Clock In', dataIndex: 'clockIn', key: 'in', render: (v: string) => v ? <Tag color="blue" style={{ borderRadius: 12 }}>{dayjs(v).format('HH:mm')}</Tag> : <Text type="secondary">—</Text> },
        { title: 'Clock Out', dataIndex: 'clockOut', key: 'out', render: (v: string) => v ? <Tag color="purple" style={{ borderRadius: 12 }}>{dayjs(v).format('HH:mm')}</Tag> : <Text type="secondary">—</Text> },
        { title: 'Hours', dataIndex: 'workHours', key: 'hrs', render: (v: number) => v ? <Text strong>{v}h</Text> : '—' },
        { title: 'Overtime', dataIndex: 'overtimeHours', key: 'ot', render: (v: number) => v && v > 0 ? <Tag color="orange" style={{ borderRadius: 12 }}><ThunderboltOutlined /> {v}h</Tag> : '—' },
        { title: 'Status', dataIndex: 'status', key: 'status', render: (v: string) => <Tag color={statusConfig[v]?.color} style={{ borderRadius: 20 }}>{statusConfig[v]?.icon} {statusConfig[v]?.label || v}</Tag> },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#06b6d4', '#3b82f6', themeColor]} className="text-[22px] font-bold tracking-tight">Attendance</AuroraText>}
            subTitle={<DecryptedText text="Daily attendance tracking & work hours log" animateOn="view" revealDirection="start" speed={60} sequential />}
            extra={[<Segmented key="view" value={viewMode} onChange={(v: any) => setViewMode(v)} options={[{ label: <><AppstoreOutlined /> Calendar</>, value: 'calendar' }, { label: <><UnorderedListOutlined /> Table</>, value: 'table' }]} />, <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'hr_attendance', title: 'HR Attendance', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Employee', key: 'employeeName' }, { header: 'Date', key: 'date' }, { header: 'Clock In', key: 'clockIn' }, { header: 'Clock Out', key: 'clockOut' }, { header: 'Status', key: 'status' }, { header: 'Hours', key: 'totalHours' }], data: records })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'hr_attendance', title: 'HR Attendance Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Employee', key: 'employeeName' }, { header: 'Date', key: 'date' }, { header: 'Clock In', key: 'clockIn' }, { header: 'Clock Out', key: 'clockOut' }, { header: 'Status', key: 'status' }, { header: 'Hours', key: 'totalHours' }], data: records })} /></Tooltip></RbacGuard>]}
        >
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {/* Stats Row */}
                <Row gutter={[12, 12]}>
                    <Col xs={24} sm={4}><Card size="small" style={{ ...glass, borderTop: '3px solid #10b981' }}><Statistic title="Present" value={present} prefix={<CheckCircleOutlined />} valueStyle={{ color: '#10b981', fontSize: 20 }} /></Card></Col>
                    <Col xs={24} sm={4}><Card size="small" style={{ ...glass, borderTop: '3px solid #f59e0b' }}><Statistic title="Late" value={late} prefix={<ExclamationCircleOutlined />} valueStyle={{ color: '#f59e0b', fontSize: 20 }} /></Card></Col>
                    <Col xs={24} sm={4}><Card size="small" style={{ ...glass, borderTop: '3px solid #ef4444' }}><Statistic title="Absent" value={absent} prefix={<ClockCircleOutlined />} valueStyle={{ color: '#ef4444', fontSize: 20 }} /></Card></Col>
                    <Col xs={24} sm={4}><Card size="small" style={{ ...glass, borderTop: '3px solid #3b82f6' }}><Statistic title="Total Hours" value={totalHours.toFixed(1)} suffix="h" valueStyle={{ color: '#3b82f6', fontSize: 20 }} /></Card></Col>
                    <Col xs={24} sm={4}><Card size="small" style={{ ...glass, borderTop: '3px solid #f59e0b' }}><Statistic title="Overtime" value={totalOT.toFixed(1)} suffix="h" prefix={<ThunderboltOutlined />} valueStyle={{ color: '#f59e0b', fontSize: 20 }} /></Card></Col>
                    <Col xs={24} sm={4}><Card size="small" style={{ ...glass, borderTop: '3px solid #8b5cf6' }}><Statistic title="Avg Hours" value={avgHours} suffix="h" valueStyle={{ color: '#8b5cf6', fontSize: 20 }} /></Card></Col>
                </Row>

                {/* Filters */}
                <Card size="small" style={glass}>
                    <Space wrap>
                        <Select value={month} onChange={setMonth} style={{ width: 180 }}
                            options={Array.from({ length: 6 }, (_, i) => { const m = dayjs().subtract(i, 'month').format('YYYY-MM'); return { label: dayjs(m).format('MMMM YYYY'), value: m }; })} />
                        <Select placeholder="All Employees" allowClear value={selectedEmployee} onChange={setSelectedEmployee} style={{ width: 220 }} showSearch optionFilterProp="label"
                            options={employees.map(e => ({ label: `${e.firstName} ${e.lastName} (${e.employeeNumber})`, value: e.id }))} prefix={<UserOutlined />} />
                    </Space>
                </Card>

                {viewMode === 'calendar' ? (
                    <Row gutter={[16, 16]}>
                        {/* Calendar Heatmap */}
                        <Col xs={24} md={14}>
                            <Card style={glass} title={<Space><AppstoreOutlined /> <Text strong>Attendance Calendar — {dayjs(month).format('MMMM YYYY')}</Text></Space>}>
                                <CalendarHeatmap records={records} month={month} />
                            </Card>
                        </Col>
                        {/* Employee Summary Cards */}
                        <Col xs={24} md={10}>
                            <Card style={glass} title={<Space><UserOutlined /> <Text strong>Employee Summary</Text></Space>}>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: 10, maxHeight: 450, overflowY: 'auto' }}>
                                    {uniqueEmps.map((emp, i) => <EmployeeSummaryCard key={emp.id} emp={emp} records={records} />)}
                                    {uniqueEmps.length === 0 && <Text type="secondary" style={{ textAlign: 'center', padding: 40 }}>No attendance data for this period</Text>}
                                </div>
                            </Card>
                        </Col>
                    </Row>
                ) : (
                    <Card style={glass}>
                        <Table scroll={{ x: 900 }} dataSource={records} columns={columns} rowKey="id" loading={loading} pagination={{ pageSize: 20 }} size="middle" />
                    </Card>
                )}
            </motion.div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { Card, Row, Col, Statistic, Typography, Spin, Progress, Tag, Avatar, List, Space, Tooltip, Badge } from "antd";
import {
    TeamOutlined, ApartmentOutlined, UserAddOutlined,
    CoffeeOutlined, ManOutlined, WomanOutlined,
    SolutionOutlined, TrophyOutlined, ReadOutlined,
    FileTextOutlined, WalletOutlined, CalendarOutlined,
    RiseOutlined, ArrowUpOutlined, ArrowDownOutlined,
    MailOutlined, PhoneOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import FormIntegrationWidget from "@/components/forms/FormIntegrationWidget";
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { AnimatedCircularProgressBar } from "@/components/magicui/animated-circular-progress-bar";

const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const anim = (i: number) => ({ initial: { opacity: 0, y: 20 }, animate: { opacity: 1, y: 0 }, transition: { delay: i * 0.06, duration: 0.4 } });

const STATS_QUERY = `query($t:String!){hrDashboardStats(tenantId:$t){totalEmployees activeEmployees totalDepartments totalPositions maleCount femaleCount totalPayroll avgSalary pendingLeaveRequests totalLeaveRequests openJobPostings totalApplicants totalReviews totalTrainings newHiresThisMonth contractCount fullTimeCount}}`;
const RECENT_EMPS = `query($t:String!){hrEmployees(tenantId:$t,status:"active"){id firstName lastName email phone departmentName positionTitle hireDate avatarUrl}}`;
const DEPT_Q = `query($t:String!){hrDepartments(tenantId:$t){id name code status}}`;
const ALL_EMPS = `query($t:String!){hrEmployees(tenantId:$t){id departmentId departmentName employmentStatus baseSalary hireDate}}`;

function GenderDonut({ male, female }: { male: number; female: number }) {
    const total = male + female || 1;
    const mp = Math.round((male / total) * 100);
    const fp = 100 - mp;
    const r = 38, cx = 50, cy = 50, c = 2 * Math.PI * r;
    const d1 = (mp / 100) * c;
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: 20, justifyContent: 'center' }}>
            <svg viewBox="0 0 100 100" width={90} height={90}>
                <circle cx={cx} cy={cy} r={r} fill="none" stroke="#f3e8ff" strokeWidth={12} />
                <circle cx={cx} cy={cy} r={r} fill="none" stroke="#3b82f6" strokeWidth={12}
                    strokeDasharray={`${d1} ${c - d1}`} strokeLinecap="round"
                    style={{ transform: 'rotate(-90deg)', transformOrigin: '50% 50%' }}>
                    <animate attributeName="stroke-dasharray" from={`0 ${c}`} to={`${d1} ${c - d1}`} dur="1s" fill="freeze" />
                </circle>
                <circle cx={cx} cy={cy} r={r} fill="none" stroke="#ec4899" strokeWidth={12}
                    strokeDasharray={`${(fp / 100) * c} ${c - (fp / 100) * c}`} strokeLinecap="round"
                    strokeDashoffset={`-${d1}`}
                    style={{ transform: 'rotate(-90deg)', transformOrigin: '50% 50%' }}>
                    <animate attributeName="stroke-dasharray" from={`0 ${c}`} to={`${(fp / 100) * c} ${c - (fp / 100) * c}`} dur="1s" fill="freeze" />
                </circle>
                <text x={cx} y={cy + 5} textAnchor="middle" fontSize="14" fontWeight="700" fill="currentColor">{total}</text>
            </svg>
            <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                    <div style={{ width: 10, height: 10, borderRadius: '50%', backgroundColor: '#3b82f6' }} />
                    <ManOutlined style={{ color: '#3b82f6' }} /> <Text strong>{male}</Text> <Text type="secondary" style={{ fontSize: 12 }}>({mp}%)</Text>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <div style={{ width: 10, height: 10, borderRadius: '50%', backgroundColor: '#ec4899' }} />
                    <WomanOutlined style={{ color: '#ec4899' }} /> <Text strong>{female}</Text> <Text type="secondary" style={{ fontSize: 12 }}>({fp}%)</Text>
                </div>
            </div>
        </div>
    );
}

function MiniBar({ value, max, color }: { value: number; max: number; color: string }) {
    const pct = Math.round((value / (max || 1)) * 100);
    return (
        <motion.div initial={{ scaleX: 0 }} animate={{ scaleX: 1 }} transition={{ duration: 0.6 }}
            style={{ height: 6, width: '100%', borderRadius: 3, background: `${color}15`, overflow: 'hidden', transformOrigin: 'left' }}>
            <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ delay: 0.3, duration: 0.8 }}
                style={{ height: '100%', borderRadius: 3, background: `linear-gradient(90deg, ${color}, ${color}aa)` }} />
        </motion.div>
    );
}

export default function HrDashboardPage() {
    const [stats, setStats] = useState<any>(null);
    const [employees, setEmployees] = useState<any[]>([]);
    const [departments, setDepartments] = useState<any[]>([]);
    const [allEmps, setAllEmps] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();

    useEffect(() => {
        Promise.all([
            gql(STATS_QUERY, { t: DEFAULT_TENANT_ID }),
            gql(RECENT_EMPS, { t: DEFAULT_TENANT_ID }),
            gql(DEPT_Q, { t: DEFAULT_TENANT_ID }),
            gql(ALL_EMPS, { t: DEFAULT_TENANT_ID }),
        ]).then(([st, emp, dept, all]) => {
            setStats(st.hrDashboardStats);
            setEmployees((emp.hrEmployees || []).sort((a: any, b: any) => new Date(b.hireDate).getTime() - new Date(a.hireDate).getTime()).slice(0, 5));
            setDepartments(dept.hrDepartments || []);
            setAllEmps(all.hrEmployees || []);
        }).catch(console.error).finally(() => setLoading(false));
    }, []);

    const fmt = (v: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(v);

    if (loading) return <CMSLayout title="HR Dashboard"><div style={{ display: 'flex', justifyContent: 'center', padding: 120 }}><Spin size="large" /></div></CMSLayout>;

    const s = stats || {};
    const deptColors = ['#3b82f6', '#8b5cf6', '#f59e0b', '#10b981', '#ec4899', '#06b6d4', '#ef4444', '#6366f1'];

    // Department headcount
    const deptHeadcount = departments.map((d, i) => ({
        ...d,
        count: allEmps.filter(e => e.departmentName === d.name && e.employmentStatus === 'active').length,
        color: deptColors[i % deptColors.length],
    })).sort((a, b) => b.count - a.count);
    const maxDeptCount = Math.max(...deptHeadcount.map(d => d.count), 1);

    // Salary distribution by department
    const deptSalary = departments.map((d, i) => {
        const emps = allEmps.filter(e => e.departmentName === d.name && e.employmentStatus === 'active');
        const totalSal = emps.reduce((sum, e) => sum + (Number(e.baseSalary) || 0), 0);
        return { name: d.name, total: totalSal, avg: emps.length > 0 ? Math.round(totalSal / emps.length) : 0, count: emps.length, color: deptColors[i % deptColors.length] };
    }).filter(d => d.total > 0).sort((a, b) => b.total - a.total);

    const statCards = [
        { label: 'Total Employees', value: s.totalEmployees || 0, icon: <TeamOutlined />, color: '#3b82f6', suffix: '' },
        { label: 'Active', value: s.activeEmployees || 0, icon: <TeamOutlined />, color: '#10b981', suffix: '' },
        { label: 'Departments', value: s.totalDepartments || 0, icon: <ApartmentOutlined />, color: '#8b5cf6', suffix: '' },
        { label: 'Open Positions', value: s.openJobPostings || 0, icon: <SolutionOutlined />, color: '#f59e0b', suffix: '' },
        { label: 'New Hires', value: s.newHiresThisMonth || 0, icon: <UserAddOutlined />, color: '#06b6d4', suffix: '/mo' },
        { label: 'Pending Leave', value: s.pendingLeaveRequests || 0, icon: <CoffeeOutlined />, color: '#ef4444', suffix: '' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#8b5cf6', '#ec4899', themeColor]} className="text-[22px] font-bold tracking-tight">HR Dashboard</AuroraText>}
            subTitle={<DecryptedText text="Human capital management overview" animateOn="view" revealDirection="start" speed={60} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
                {/* Top Stats (BENTO GRID) */}
                <BentoGrid className="mb-6 max-w-full">
                    <BentoGridItem
                        title="Total Employees"
                        description="Active human capital in the system."
                        icon={<TeamOutlined style={{ color: '#3b82f6' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-blue-500/10">
                                <Statistic value={s.totalEmployees || 0} valueStyle={{ color: '#3b82f6', fontSize: 32, fontWeight: 800 }} />
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Open Positions"
                        description="Current hiring requirements."
                        icon={<SolutionOutlined style={{ color: '#f59e0b' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-amber-500/10">
                                <Statistic value={s.openJobPostings || 0} valueStyle={{ color: '#f59e0b', fontSize: 32, fontWeight: 800 }} />
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="New Hires"
                        description="Onboarded this month."
                        icon={<UserAddOutlined style={{ color: '#06b6d4' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-cyan-500/10">
                                <Statistic value={s.newHiresThisMonth || 0} valueStyle={{ color: '#06b6d4', fontSize: 32, fontWeight: 800 }} suffix="/mo" />
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Pending Leave"
                        description="Requests requiring manager approval."
                        icon={<CoffeeOutlined style={{ color: '#ef4444' }} />}
                        header={
                            <div className="flex flex-col h-full w-full items-center justify-center rounded-xl bg-red-500/10">
                                <AnimatedCircularProgressBar
                                    max={100}
                                    min={0}
                                    value={s.pendingLeaveRequests || 0}
                                    gaugePrimaryColor="#ef4444"
                                    gaugeSecondaryColor="rgba(239, 68, 68, 0.1)"
                                    className="w-[80px] h-[80px] scale-90"
                                />
                                <div style={{ fontSize: 11, marginTop: 4, color: "#ef4444", fontWeight: 600 }}>Action Required</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                </BentoGrid>

                {/* Main Content */}
                <Row gutter={[16, 16]}>
                    {/* Payroll Summary */}
                    <Col xs={24} md={8}>
                        <motion.div {...anim(6)}>
                            <Card title={<><WalletOutlined /> Payroll Summary</>} size="small" style={{ ...glass, height: '100%' }}>
                                <Statistic title="Monthly Payroll" value={fmt(s.totalPayroll || 0)} valueStyle={{ fontSize: 20, fontWeight: 700, color: '#10b981' }} />
                                <div style={{ marginTop: 16, padding: 12, background: 'rgba(16,185,129,0.06)', borderRadius: 10 }}>
                                    <Text type="secondary" style={{ fontSize: 12 }}>Average Salary</Text>
                                    <div style={{ fontSize: 18, fontWeight: 600, color: '#3b82f6' }}>{fmt(s.avgSalary || 0)}</div>
                                </div>
                                <div style={{ marginTop: 12, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Text type="secondary" style={{ fontSize: 11 }}>Headcount Cost Ratio</Text>
                                    <Tag color="blue">{s.activeEmployees || 0} employees</Tag>
                                </div>
                            </Card>
                        </motion.div>
                    </Col>

                    {/* Gender Distribution */}
                    <Col xs={24} md={8}>
                        <motion.div {...anim(7)}>
                            <Card title={<><TeamOutlined /> Gender Distribution</>} size="small" style={{ ...glass, height: '100%' }}>
                                <GenderDonut male={s.maleCount || 0} female={s.femaleCount || 0} />
                                <div style={{ marginTop: 16, display: 'flex', gap: 12 }}>
                                    <div style={{ flex: 1, padding: 8, borderRadius: 8, background: 'rgba(59,130,246,0.06)', textAlign: 'center' }}>
                                        <Text style={{ fontSize: 11, color: '#3b82f6' }}>Full-Time</Text>
                                        <div style={{ fontWeight: 700, color: '#3b82f6' }}>{s.fullTimeCount || 0}</div>
                                    </div>
                                    <div style={{ flex: 1, padding: 8, borderRadius: 8, background: 'rgba(245,158,11,0.06)', textAlign: 'center' }}>
                                        <Text style={{ fontSize: 11, color: '#f59e0b' }}>Contract</Text>
                                        <div style={{ fontWeight: 700, color: '#f59e0b' }}>{s.contractCount || 0}</div>
                                    </div>
                                </div>
                            </Card>
                        </motion.div>
                    </Col>

                    {/* Department Distribution */}
                    <Col xs={24} md={8}>
                        <motion.div {...anim(8)}>
                            <Card title={<><ApartmentOutlined /> Department Distribution</>} size="small" style={{ ...glass, height: '100%' }}>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                                    {deptHeadcount.slice(0, 6).map((d, i) => (
                                        <motion.div key={d.id} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.5 + i * 0.08 }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 2 }}>
                                                <Text style={{ fontSize: 12 }}>{d.name}</Text>
                                                <Badge count={d.count} style={{ backgroundColor: d.color }} size="small" />
                                            </div>
                                            <MiniBar value={d.count} max={maxDeptCount} color={d.color} />
                                        </motion.div>
                                    ))}
                                </div>
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Bottom Row */}
                <Row gutter={[16, 16]}>
                    {/* Recent Hires */}
                    <Col xs={24} md={12}>
                        <motion.div {...anim(9)}>
                            <Card title={<><UserAddOutlined /> Recent Team Members</>} size="small" style={{ ...glass, height: '100%' }}>
                                <List
                                    dataSource={employees}
                                    renderItem={(emp: any, i: number) => (
                                        <motion.div key={emp.id} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.6 + i * 0.1 }}>
                                            <List.Item style={{ padding: '8px 0', borderBottom: '1px solid rgba(0,0,0,0.04)' }}>
                                                <List.Item.Meta
                                                    avatar={<Avatar style={{ backgroundColor: deptColors[i % deptColors.length], fontSize: 12 }}>{emp.firstName?.[0]}{emp.lastName?.[0]}</Avatar>}
                                                    title={<Text strong style={{ fontSize: 13 }}>{emp.firstName} {emp.lastName}</Text>}
                                                    description={<Space size={4} wrap><Tag color="blue" style={{ fontSize: 10, margin: 0 }}>{emp.departmentName}</Tag><Tag style={{ fontSize: 10, margin: 0 }}>{emp.positionTitle}</Tag></Space>}
                                                />
                                                <div style={{ textAlign: 'right' }}>
                                                    <Text type="secondary" style={{ fontSize: 10, display: 'block' }}><CalendarOutlined /> {emp.hireDate}</Text>
                                                    {emp.email && <Text type="secondary" style={{ fontSize: 10, display: 'block' }}><MailOutlined /> {emp.email?.split('@')[0]}@...</Text>}
                                                </div>
                                            </List.Item>
                                        </motion.div>
                                    )}
                                />
                            </Card>
                        </motion.div>
                    </Col>

                    {/* Quick Metrics */}
                    <Col xs={24} md={12}>
                        <motion.div {...anim(10)}>
                            <Card title={<><RiseOutlined /> Quick Metrics</>} size="small" style={{ ...glass, height: '100%' }}>
                                <Row gutter={[12, 12]}>
                                    <Col span={12}>
                                        <div style={{ padding: 14, borderRadius: 10, background: 'rgba(245,158,11,0.06)', borderLeft: '3px solid #f59e0b' }}>
                                            <SolutionOutlined style={{ color: '#f59e0b', fontSize: 18 }} />
                                            <div style={{ fontWeight: 700, fontSize: 20, color: '#f59e0b', marginTop: 4 }}>{s.openJobPostings || 0}</div>
                                            <Text type="secondary" style={{ fontSize: 11 }}>Open Postings</Text>
                                            <div><Text style={{ fontSize: 10, color: '#6b7280' }}>{s.totalApplicants || 0} applicants</Text></div>
                                        </div>
                                    </Col>
                                    <Col span={12}>
                                        <div style={{ padding: 14, borderRadius: 10, background: 'rgba(139,92,246,0.06)', borderLeft: '3px solid #8b5cf6' }}>
                                            <TrophyOutlined style={{ color: '#8b5cf6', fontSize: 18 }} />
                                            <div style={{ fontWeight: 700, fontSize: 20, color: '#8b5cf6', marginTop: 4 }}>{s.totalReviews || 0}</div>
                                            <Text type="secondary" style={{ fontSize: 11 }}>Performance Reviews</Text>
                                            <div><Text style={{ fontSize: 10, color: '#6b7280' }}>completed</Text></div>
                                        </div>
                                    </Col>
                                    <Col span={12}>
                                        <div style={{ padding: 14, borderRadius: 10, background: 'rgba(6,182,212,0.06)', borderLeft: '3px solid #06b6d4' }}>
                                            <ReadOutlined style={{ color: '#06b6d4', fontSize: 18 }} />
                                            <div style={{ fontWeight: 700, fontSize: 20, color: '#06b6d4', marginTop: 4 }}>{s.totalTrainings || 0}</div>
                                            <Text type="secondary" style={{ fontSize: 11 }}>Training Programs</Text>
                                            <div><Text style={{ fontSize: 10, color: '#6b7280' }}>active</Text></div>
                                        </div>
                                    </Col>
                                    <Col span={12}>
                                        <div style={{ padding: 14, borderRadius: 10, background: 'rgba(239,68,68,0.06)', borderLeft: '3px solid #ef4444' }}>
                                            <CoffeeOutlined style={{ color: '#ef4444', fontSize: 18 }} />
                                            <div style={{ fontWeight: 700, fontSize: 20, color: '#ef4444', marginTop: 4 }}>{s.pendingLeaveRequests || 0}</div>
                                            <Text type="secondary" style={{ fontSize: 11 }}>Pending Leaves</Text>
                                            <div><Text style={{ fontSize: 10, color: '#6b7280' }}>{s.totalLeaveRequests || 0} total requests</Text></div>
                                        </div>
                                    </Col>
                                </Row>
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Salary by Department */}
                {deptSalary.length > 0 && (
                    <motion.div {...anim(11)}>
                        <Card title={<><WalletOutlined /> Salary Distribution by Department</>} size="small" style={glass}>
                            <div style={{ display: 'flex', gap: 12, overflowX: 'auto', paddingBottom: 4 }}>
                                {deptSalary.map((d, i) => (
                                    <motion.div key={d.name} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.8 + i * 0.08 }}
                                        style={{ minWidth: 160, flex: 1, padding: 14, borderRadius: 12, background: `${d.color}08`, border: `1px solid ${d.color}22`, textAlign: 'center' }}>
                                        <Text style={{ fontSize: 11, color: d.color, display: 'block', fontWeight: 600, marginBottom: 4 }}>{d.name}</Text>
                                        <div style={{ fontWeight: 700, fontSize: 15, color: d.color }}>{fmt(d.total)}</div>
                                        <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>Avg: {fmt(d.avg)}</Text>
                                        <Tag color={d.color} style={{ marginTop: 4, fontSize: 10 }}>{d.count} employees</Tag>
                                    </motion.div>
                                ))}
                            </div>
                        </Card>
                    </motion.div>
                )}

                {/* Form Builder Integration */}
                <Row gutter={[16, 16]}>
                    <Col xs={24} md={12}>
                        <FormIntegrationWidget
                            categories={['kpi', 'assessment']}
                            title="KPI & Evaluations"
                            maxItems={3}
                            animIndex={12}
                        />
                    </Col>
                    <Col xs={24} md={12}>
                        <FormIntegrationWidget
                            categories={['survey', 'feedback']}
                            title="Employee Surveys"
                            maxItems={3}
                            animIndex={13}
                        />
                    </Col>
                </Row>
            </div>
        </CMSLayout>
    );
}

