    { job: 'postgres', container: 'postgres', lines: 2340, rate: '3/s', level: 'info', color: '#10b981' },
    { job: 'landing-page', container: 'landing-page', lines: 1890, rate: '2/s', level: 'info', color: '#ec4899' },
