'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { Table, Tag, Button, Modal, Form, Input, InputNumber, Select, Space, message, Tabs, Progress, Drawer, Row, Col, Card, Typography, Tooltip, theme } from 'antd';
import { PlusOutlined, ReloadOutlined, ScheduleOutlined, CheckCircleOutlined, ClockCircleOutlined, TeamOutlined, DollarOutlined, SearchOutlined, SendOutlined, LoginOutlined, CloseCircleOutlined, EyeOutlined, UserOutlined , FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import RbacGuard from '@/components/common/RbacGuard';
import { inventoryService, BookingSchedule, BookingOccurrence, Booking, BookingPassenger, BookingStatsType, InvItem } from '@/lib/inventoryService';
import DecryptedText from "@/components/react-bits/DecryptedText";
import { AuroraText } from "@/components/magicui/aurora-text";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

const STATUS_COLORS: Record<string, string> = {
    active: 'green', suspended: 'orange', cancelled: 'red',
    scheduled: 'blue', boarding: 'cyan', departed: 'geekblue', completed: 'green',
    pending: 'gold', confirmed: 'blue', checked_in: 'green', no_show: 'red',
};

const BOOKING_FIELDS: FieldDef[] = [
    { name: 'bookingCode', label: 'Booking Code', required: true },
    { name: 'scheduleId', label: 'Schedule / Route', required: true },
    { name: 'occurrenceId', label: 'Departure' },
    { name: 'class', label: 'Class', required: true },
    { name: 'passengerCount', label: 'Passengers', type: 'number', required: true },
    { name: 'customerName', label: 'Customer Name', required: true },
    { name: 'customerEmail', label: 'Customer Email' },
    { name: 'customerPhone', label: 'Customer Phone' },
    { name: 'totalAmount', label: 'Total Amount', type: 'number' },
    { name: 'paidAmount', label: 'Paid Amount', type: 'number' },
    { name: 'notes', label: 'Notes' },
];

export default function BookingsPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const { startDate, endDate } = useDateRangeStore();
    const [schedules, setSchedules] = useState<BookingSchedule[]>([]);
    const [occurrences, setOccurrences] = useState<BookingOccurrence[]>([]);
    const [bookings, setBookings] = useState<Booking[]>([]);
    const [stats, setStats] = useState<BookingStatsType | null>(null);
    const [passengers, setPassengers] = useState<BookingPassenger[]>([]);
    const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);
    const [loading, setLoading] = useState(false);
    const [tab, setTab] = useState('schedules');
    const [search, setSearch] = useState('');
    const [items, setItems] = useState<InvItem[]>([]);

    // New Booking modal
    const [bookingModalOpen, setBookingModalOpen] = useState(false);
    const [bookingForm] = Form.useForm();
    const [selectedScheduleId, setSelectedScheduleId] = useState<string | undefined>();

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [s, o, b, st, it] = await Promise.all([
                inventoryService.getSchedules(),
                inventoryService.getOccurrences(),
                inventoryService.getBookings(),
                inventoryService.getBookingStats(),
                inventoryService.getItems(),
            ]);
            setSchedules(s); setOccurrences(o); setBookings(b); setStats(st); setItems(it);
        } catch (e: any) { message.error(e.message); }
        setLoading(false);
    }, []);

    useEffect(() => { load(); }, [load]);

    const loadPassengers = async (booking: Booking) => {
        const p = await inventoryService.getPassengers(booking.id);
        setPassengers(p);
        setSelectedBooking(booking);
    };

    const handleStatusChange = async (id: string, status: string, type: 'booking' | 'occurrence') => {
        try {
            if (type === 'booking') await inventoryService.updateBookingStatus(id, status);
            else await inventoryService.updateOccurrenceStatus(id, status);
            message.success('Status updated');
            load();
        } catch (e: any) { message.error(e.message); }
    };

    const handleCreateBooking = async (values: any) => {
        await inventoryService.createBooking('default', values);
        message.success('Booking created');
        setBookingModalOpen(false);
        bookingForm.resetFields();
        setSelectedScheduleId(undefined);
        load();
    };

    const handleBatchCreateBooking = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createBooking('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.bookingCode || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        load();
        return { success, failed, errors };
    };

    const recalcTotal = () => {
        const cls = bookingForm.getFieldValue('class') || 'economy';
        const pax = bookingForm.getFieldValue('passengerCount') || 1;
        const sid = bookingForm.getFieldValue('scheduleId');
        const sched = schedules.find(s => s.id === sid);
        if (!sched) return;
        const price = cls === 'vip' ? (sched.priceVip || 0) : cls === 'business' ? (sched.priceBusiness || 0) : (sched.priceEconomy || 0);
        bookingForm.setFieldsValue({ totalAmount: price * pax });
    };

    const fmt = (v: number) => `Rp ${(v || 0).toLocaleString('id-ID')}`;

    const kpis = [
        { label: 'Total Schedules', value: stats?.totalSchedules || 0, icon: <ScheduleOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { label: 'Upcoming Departures', value: stats?.upcomingDepartures || 0, icon: <ClockCircleOutlined />, color: '#2563eb' },
        { label: 'Total Bookings', value: stats?.totalBookings || 0, icon: <TeamOutlined />, color: '#0891b2' },
        { label: 'Confirmed', value: stats?.confirmedBookings || 0, icon: <CheckCircleOutlined />, color: '#16a34a' },
        { label: 'Checked In', value: stats?.checkedInBookings || 0, icon: <LoginOutlined />, color: '#059669' },
        { label: 'Total Revenue', value: fmt(stats?.totalRevenue || 0), icon: <DollarOutlined />, color: '#dc2626' },
    ];

    const scheduleColumns = [
        { title: 'Code', dataIndex: 'scheduleCode', render: (v: string) => <Tag style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Route / Event', dataIndex: 'routeName', ellipsis: true },
        { title: 'Origin', dataIndex: 'origin', ellipsis: true },
        { title: 'Destination', dataIndex: 'destination', ellipsis: true, render: (v: string) => v || 'â€”' },
        { title: 'Time', render: (_: any, r: BookingSchedule) => `${r.departureTime || 'â€”'} â†’ ${r.arrivalTime || 'â€”'}` },
        { title: 'Vessel', dataIndex: 'vehicleName', render: (v: string) => v || 'â€”' },
        { title: 'Capacity', dataIndex: 'capacity', render: (v: number) => <strong>{v}</strong> },
        { title: 'Product', dataIndex: 'itemId', width: 160, ellipsis: true, render: (v: string) => {
            if (!v) return <Tag color="default">â€”</Tag>;
            const item = items.find(i => i.id === v);
            return <Tag color="purple" style={{ fontSize: 11, maxWidth: 140, overflow: 'hidden', textOverflow: 'ellipsis' }}>ðŸŽ« {item?.name || 'Linked'}</Tag>;
        }},
        { title: 'Economy', dataIndex: 'priceEconomy', render: fmt },
        { title: 'Business', dataIndex: 'priceBusiness', render: fmt },
        { title: 'VIP', dataIndex: 'priceVip', render: (v: number) => v ? fmt(v) : 'â€”' },
        { title: 'Status', dataIndex: 'status', render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'}>{v}</Tag> },
    ];

    const occurrenceColumns = [
        { title: 'Route', render: (_: any, r: BookingOccurrence) => {
            const s = schedules.find(s => s.id === r.scheduleId);
            return <span style={{ fontWeight: 500 }}>{s?.routeName || 'â€”'}</span>;
        }},
        { title: 'Date', dataIndex: 'departureDate', render: (v: string) => new Date(v).toLocaleDateString('id-ID', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }) },
        { title: 'Time', dataIndex: 'departureTime', render: (v: string) => v || 'â€”' },
        { title: 'Capacity', render: (_: any, r: BookingOccurrence) => {
            const isFull = (r.bookedCount || 0) >= (r.totalCapacity || 1);
            return (
                <Space direction="vertical" size={0} style={{ width: 120 }}>
                    <span>{r.bookedCount || 0}/{r.totalCapacity || 0} booked</span>
                    {isFull
                        ? <Tag color="red" style={{ fontWeight: 700, margin: '4px 0' }}>ðŸš« SOLD OUT</Tag>
                        : <Progress percent={Math.round(((r.bookedCount || 0) / (r.totalCapacity || 1)) * 100)} size="small"
                            strokeColor={(r.bookedCount || 0) / (r.totalCapacity || 1) > 0.8 ? '#f5222d' : '#1890ff'} />
                    }
                </Space>
            );
        }},
        { title: 'Checkâ€‘ins', render: (_: any, r: BookingOccurrence) => `${r.checkedInCount || 0}/${r.bookedCount || 0}` },
        { title: 'Status', dataIndex: 'status', render: (v: string, r: BookingOccurrence) => {
            const isFull = (r.bookedCount || 0) >= (r.totalCapacity || 1);
            return (
                <Space>
                    <Tag color={STATUS_COLORS[v] || 'default'}>{v}</Tag>
                    {isFull && v === 'scheduled' && <Tag color="volcano">FULL</Tag>}
                </Space>
            );
        }},
        { title: 'Actions', render: (_: any, r: BookingOccurrence) => {
            const next: Record<string, string[]> = { scheduled: ['boarding'], boarding: ['departed'], departed: ['completed'], completed: [] };
            return (
                <Space>
                    {(next[r.status || ''] || []).map(s => (
                        <Button key={s} size="small" type="primary" onClick={() => handleStatusChange(r.id, s, 'occurrence')}>
                            {s === 'boarding' ? 'Board' : s === 'departed' ? 'Depart' : 'Complete'}
                        </Button>
                    ))}
                </Space>
            );
        }},
    ];

    const bookingColumns = [
        { title: 'Code', dataIndex: 'bookingCode', render: (v: string) => <Tag style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Customer', dataIndex: 'customerName' },
        { title: 'Route', render: (_: any, r: Booking) => {
            const s = schedules.find(s => s.id === r.scheduleId);
            return s?.routeName || 'â€”';
        }},
        { title: 'Date', render: (_: any, r: Booking) => {
            const o = occurrences.find(o => o.id === r.occurrenceId);
            return o ? new Date(o.departureDate).toLocaleDateString('id-ID') : 'â€”';
        }},
        { title: 'Pax', dataIndex: 'passengerCount', render: (v: number) => <strong>{v}</strong> },
        { title: 'Class', dataIndex: 'class', render: (v: string) => <Tag color={v === 'vip' ? 'gold' : v === 'business' ? 'blue' : 'default'}>{v?.toUpperCase()}</Tag> },
        { title: 'Amount', dataIndex: 'totalAmount', render: fmt },
        { title: 'Status', dataIndex: 'status', render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'}>{v?.replace('_', ' ')}</Tag> },
        { title: 'Actions', render: (_: any, r: Booking) => {
            const next: Record<string, string[]> = { pending: ['confirmed', 'cancelled'], confirmed: ['checked_in', 'cancelled'], checked_in: ['completed', 'no_show'], completed: [], cancelled: [], no_show: [] };
            return (
                <Space>
                    <Button size="small" icon={<EyeOutlined />} onClick={() => loadPassengers(r)}>Passengers</Button>
                    {(next[r.status || ''] || []).map(s => (
                        <Button key={s} size="small" type={s === 'cancelled' || s === 'no_show' ? 'default' : 'primary'} danger={s === 'cancelled' || s === 'no_show'}
                            onClick={() => handleStatusChange(r.id, s, 'booking')}>
                            {s === 'confirmed' ? 'Confirm' : s === 'checked_in' ? 'Check In' : s === 'completed' ? 'Complete' : s === 'cancelled' ? 'Cancel' : 'No Show'}
                        </Button>
                    ))}
                </Space>
            );
        }},
    ];

    const filteredSchedules = schedules.filter(s => !search || s.routeName.toLowerCase().includes(search.toLowerCase()) || s.scheduleCode.toLowerCase().includes(search.toLowerCase()));
    const filteredBookings = bookings.filter(b => !search || (b.customerName || '').toLowerCase().includes(search.toLowerCase()) || b.bookingCode.toLowerCase().includes(search.toLowerCase()));

    const filteredOccurrences = selectedScheduleId
        ? occurrences.filter(o => o.scheduleId === selectedScheduleId && o.status !== 'completed')
        : [];

    const bookingSteps = [
        {
            title: "Route & Schedule",
            icon: <ScheduleOutlined />,
            fields: ["bookingCode", "scheduleId", "occurrenceId", "class", "passengerCount"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={10}>
                            <Form.Item name="bookingCode" label="Booking Code" rules={[{ required: true }]}>
                                <Input placeholder="BKG-2026-XXX" />
                            </Form.Item>
                        </Col>
                        <Col span={14}>
                            <Form.Item name="scheduleId" label="Schedule / Route" rules={[{ required: true, message: 'Select a schedule' }]}>
                                <Select placeholder="Select route" showSearch
                                    filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                                    onChange={(v) => { setSelectedScheduleId(v); bookingForm.setFieldsValue({ occurrenceId: undefined }); recalcTotal(); }}
                                    options={schedules.filter(s => s.status === 'active').map(s => ({
                                        value: s.id, label: `${s.scheduleCode} â€” ${s.routeName} (${s.origin} â†’ ${s.destination || 'â€”'})`
                                    }))} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={14}>
                            <Form.Item name="occurrenceId" label="Departure">
                                <Select placeholder={selectedScheduleId ? 'Select departure' : 'Select a schedule first'} disabled={!selectedScheduleId}
                                    options={filteredOccurrences.map(o => ({
                                        value: o.id,
                                        label: `${new Date(o.departureDate).toLocaleDateString('id-ID')} ${o.departureTime || ''} â€” ${o.bookedCount || 0}/${o.totalCapacity || 0} booked`
                                    }))} />
                            </Form.Item>
                        </Col>
                        <Col span={5}>
                            <Form.Item name="class" label="Class" rules={[{ required: true }]} initialValue="economy">
                                <Select onChange={() => recalcTotal()} options={[
                                    { value: 'economy', label: 'Economy' }, { value: 'business', label: 'Business' }, { value: 'vip', label: 'VIP' },
                                ]} />
                            </Form.Item>
                        </Col>
                        <Col span={5}>
                            <Form.Item name="passengerCount" label="Passengers" rules={[{ required: true }]} initialValue={1}>
                                <InputNumber min={1} max={50} style={{ width: '100%' }} onChange={() => recalcTotal()} />
                            </Form.Item>
                        </Col>
                    </Row>
                </>
            ),
        },
        {
            title: "Customer & Payment",
            icon: <UserOutlined />,
            fields: ["customerName", "customerEmail", "customerPhone", "totalAmount", "paidAmount", "notes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="customerName" label="Customer Name" rules={[{ required: true }]}>
                                <Input placeholder="Full name" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="customerEmail" label="Email">
                                <Input placeholder="email@example.com" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="customerPhone" label="Phone">
                                <Input placeholder="+62..." />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="totalAmount" label="Total Amount">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="paidAmount" label="Paid Amount">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="notes" label="Notes">
                        <Input.TextArea rows={2} placeholder="Booking notes..." />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Bookings & Ticketing</AuroraText>}
            subTitle={<DecryptedText text="Schedule management, passenger bookings, and check-in tracking" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>

                {/* KPI Cards */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 14, marginBottom: 24 }}>
                    {kpis.map((k, i) => (
                        <motion.div key={i} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}
                            style={{ ...(isDark ? glassDark : glass), padding: '16px 18px', borderTop: `3px solid ${k.color}`, position: 'relative', overflow: 'hidden' }}>
                            <div style={{ position: 'absolute', top: -10, right: -10, width: 60, height: 60, borderRadius: '50%', background: `radial-gradient(circle, ${k.color}18 0%, transparent 70%)`, pointerEvents: 'none' }} />
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6, position: 'relative' }}>
                                <span style={{ color: k.color, fontSize: 14 }}>{k.icon}</span>
                                <span style={{ color: isDark ? 'rgba(255,255,255,0.5)' : 'rgba(0,0,0,0.45)', fontSize: 10, letterSpacing: 0.5, textTransform: 'uppercase' as const }}>{k.label}</span>
                            </div>
                            <div style={{ fontSize: 22, fontWeight: 800, color: k.color, position: 'relative', letterSpacing: -0.5 }}>{typeof k.value === 'number' ? k.value : k.value}</div>
                        </motion.div>
                    ))}
                </div>

                {/* Search + Actions */}
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
                    <Input prefix={<SearchOutlined />} placeholder="Search schedules, bookings..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: 320 }} allowClear />
                    <Space>
                        <Button icon={<ReloadOutlined />} onClick={load} loading={loading}>Refresh</Button>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_bookings', title: 'Booking Schedules', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Facility', key: 'facility' }, { header: 'Status', key: 'status' }, { header: 'Capacity', key: 'maxCapacity' }], data: schedules })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_bookings', title: 'Booking Schedules', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Facility', key: 'facility' }, { header: 'Status', key: 'status' }, { header: 'Capacity', key: 'maxCapacity' }], data: schedules })} /></Tooltip></RbacGuard>
                        <Button type="primary" icon={<PlusOutlined />}
                            onClick={() => { bookingForm.resetFields(); setSelectedScheduleId(undefined); setBookingModalOpen(true); setTab('bookings'); }}
                            style={{ background: 'linear-gradient(135deg, var(--theme-color, #7c3aed), #2563eb)', border: 'none', borderRadius: 8 }}>
                            New Booking
                        </Button>
                    </Space>
                </div>

                <Card size="small" style={{ flex: 1, ...(isDark ? glassDark : glass), borderLeft: `3px solid var(--theme-color, #7c3aed)` }}>
                    {/* Tabs */}
                    <Tabs activeKey={tab} onChange={setTab} items={[
                        { key: 'schedules', label: `ðŸ—“ï¸ Schedules (${schedules.length})`, children: (
                            <Table dataSource={filteredSchedules} columns={scheduleColumns} rowKey="id" size="middle" loading={loading}
                                pagination={{ pageSize: 10 }} scroll={{ x: 1200 }} />
                        )},
                        { key: 'departures', label: `ðŸš¢ Departures (${occurrences.length})`, children: (
                            <Table dataSource={occurrences} columns={occurrenceColumns} rowKey="id" size="middle" loading={loading}
                                pagination={{ pageSize: 10 }} scroll={{ x: 900 }} />
                        )},
                        { key: 'bookings', label: `ðŸŽ« Bookings (${bookings.length})`, children: (
                            <Table dataSource={filteredBookings} columns={bookingColumns} rowKey="id" size="middle" loading={loading}
                                pagination={{ pageSize: 10 }} scroll={{ x: 1100 }} />
                        )},
                    ]} />
                </Card>

                {/* Passenger Drawer */}
                <Drawer title={`Passengers â€” ${selectedBooking?.bookingCode}`} open={!!selectedBooking} onClose={() => setSelectedBooking(null)} width={520}>
                    {selectedBooking && (
                        <div>
                            <div style={{ marginBottom: 16, padding: 12, background: isDark ? 'rgba(255,255,255,0.04)' : '#f8f9fa', borderRadius: 8 }}>
                                <p style={{ margin: 0 }}><strong>Customer:</strong> {selectedBooking.customerName}</p>
                                <p style={{ margin: 0 }}><strong>Class:</strong> <Tag color={selectedBooking.class === 'vip' ? 'gold' : selectedBooking.class === 'business' ? 'blue' : 'default'}>{selectedBooking.class?.toUpperCase()}</Tag></p>
                                <p style={{ margin: 0 }}><strong>Amount:</strong> {fmt(selectedBooking.totalAmount || 0)}</p>
                            </div>
                            <Table dataSource={passengers} rowKey="id" size="small" pagination={false}
                                columns={[
                                    { title: '#', render: (_: any, __: any, i: number) => i + 1, width: 40 },
                                    { title: 'Name', dataIndex: 'name' },
                                    { title: 'ID Number', dataIndex: 'idNumber', render: (v: string) => v ? <Tag style={{ fontFamily: 'monospace', fontSize: 11 }}>{v}</Tag> : 'â€”' },
                                    { title: 'Nationality', dataIndex: 'nationality', render: (v: string) => v || 'â€”' },
                                    { title: 'Class', dataIndex: 'class', render: (v: string) => <Tag>{v?.toUpperCase()}</Tag> },
                                    { title: 'Notes', dataIndex: 'notes', render: (v: string) => v || 'â€”' },
                                ]}
                            />
                        </div>
                    )}
                </Drawer>

                {/* â”€â”€â”€ Booking SteppedFormModal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
                <SteppedFormModal
                    open={bookingModalOpen}
                    onCancel={() => { setBookingModalOpen(false); bookingForm.resetFields(); setSelectedScheduleId(undefined); }}
                    onSubmit={handleCreateBooking}
                    form={bookingForm}
                    title="New Booking"
                    entityName="booking"
                    steps={bookingSteps}
                    fields={BOOKING_FIELDS}
                    width={650}
                    loading={false}
                    onBatchCreate={handleBatchCreateBooking}
                    gradient={["var(--theme-color, #7c3aed)", "#2563eb"]}
                />
            </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { Button, Card, Col, Descriptions, Divider, Drawer, Form, Input, InputNumber, message, Modal, Progress, Row, Select, Space, Table, Tag, Tooltip, Typography , theme } from "antd";
import {
    CarOutlined, PlusOutlined, ReloadOutlined, SearchOutlined,
    DeleteOutlined, EditOutlined, EyeOutlined,
    ToolOutlined, DollarOutlined, ExclamationCircleOutlined,
    CheckCircleOutlined, WarningOutlined, CloseCircleOutlined,
    ThunderboltOutlined, CalendarOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import {
    inventoryService, FixedAsset, FixedAssetStatsType
} from "@/lib/inventoryService";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

const ASSET_STATUSES: Record<string, { color: string; icon: React.ReactNode }> = {
    active: { color: 'green', icon: <CheckCircleOutlined /> },
    maintenance: { color: 'orange', icon: <ToolOutlined /> },
    disposed: { color: 'default', icon: <CloseCircleOutlined /> },
    written_off: { color: 'red', icon: <WarningOutlined /> },
};

const CONDITIONS: Record<string, string> = {
    excellent: 'green', good: 'blue', fair: 'orange', poor: 'red', damaged: 'volcano',
};

const CATEGORIES = [
    { value: 'vehicle', label: 'Vehicle' },
    { value: 'equipment', label: 'Equipment' },
    { value: 'furniture', label: 'Furniture' },
    { value: 'building', label: 'Building' },
    { value: 'electronics', label: 'Electronics' },
    { value: 'machinery', label: 'Machinery' },
    { value: 'land', label: 'Land' },
    { value: 'software', label: 'Software' },
    { value: 'other', label: 'Other' },
];

const DEP_METHODS = [
    { value: 'straight_line', label: 'Straight Line' },
    { value: 'declining_balance', label: 'Declining Balance' },
    { value: 'no_depreciation', label: 'No Depreciation' },
];

const fmtCurrency = (v?: number) => v != null ? `Rp ${v.toLocaleString()}` : '-';
const fmtDate = (v?: string) => v ? new Date(v).toLocaleDateString() : 'Ã¢â‚¬â€';

const ASSET_FIELDS: FieldDef[] = [
    { name: 'assetName', label: 'Asset Name', required: true },
    { name: 'assetCategory', label: 'Category' },
    { name: 'serialNumber', label: 'Serial Number' },
    { name: 'purchaseDate', label: 'Purchase Date' },
    { name: 'purchasePrice', label: 'Purchase Price', type: 'number' },
    { name: 'depreciationMethod', label: 'Depreciation Method' },
    { name: 'usefulLifeMonths', label: 'Useful Life (months)', type: 'number' },
    { name: 'salvageValue', label: 'Salvage Value', type: 'number' },
    { name: 'location', label: 'Location' },
    { name: 'assignedTo', label: 'Assigned To' },
    { name: 'condition', label: 'Condition' },
    { name: 'warrantyExpiry', label: 'Warranty Expiry' },
    { name: 'maintenanceSchedule', label: 'Maintenance Schedule' },
    { name: 'insurancePolicy', label: 'Insurance Policy' },
    { name: 'notes', label: 'Notes' },
];

export default function FixedAssetsPage() {
    const [stats, setStats] = useState<FixedAssetStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const { startDate, endDate } = useDateRangeStore();
    const [assets, setAssets] = useState<FixedAsset[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");
    const [filterCategory, setFilterCategory] = useState<string | undefined>();
    const [filterStatus, setFilterStatus] = useState<string | undefined>();

    // Modals
    const [modalOpen, setModalOpen] = useState(false);
    const [editingAsset, setEditingAsset] = useState<FixedAsset | null>(null);
    const [form] = Form.useForm();

    // Detail Drawer
    const [drawerOpen, setDrawerOpen] = useState(false);
    const [selectedAsset, setSelectedAsset] = useState<FixedAsset | null>(null);

    // Dispose Modal
    const [disposeModalOpen, setDisposeModalOpen] = useState(false);
    const [disposeForm] = Form.useForm();
    const [disposeAssetId, setDisposeAssetId] = useState<string | null>(null);

    useEffect(() => { loadAll(); }, [filterCategory, filterStatus]);

    const loadAll = async () => {
        setLoading(true);
        try {
            const [statsData, assetsData] = await Promise.all([
                inventoryService.getFixedAssetStats(),
                inventoryService.getFixedAssets('default', {
                    assetCategory: filterCategory, status: filterStatus,
                }),
            ]);
            setStats(statsData);
            setAssets(assetsData);
        } catch (err) {
            console.error(err);
            message.error("Failed to load fixed assets");
        } finally {
            setLoading(false);
        }
    };

    const handleCreateOrUpdate = async (values: any) => {
        if (editingAsset) {
            await inventoryService.updateFixedAsset(editingAsset.id, values);
            message.success("Asset updated");
        } else {
            await inventoryService.createFixedAsset('default', values);
            message.success("Asset created");
        }
        setModalOpen(false);
        setEditingAsset(null);
        form.resetFields();
        loadAll();
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createFixedAsset('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.assetName || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        loadAll();
        return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await inventoryService.deleteFixedAsset(id);
            message.success("Asset deleted");
            loadAll();
        } catch { message.error("Failed to delete"); }
    };

    const handleDispose = async () => {
        try {
            const values = await disposeForm.validateFields();
            await inventoryService.disposeFixedAsset(disposeAssetId!, values.disposalMethod, values.disposalValue);
            message.success("Asset disposed");
            setDisposeModalOpen(false);
            disposeForm.resetFields();
            loadAll();
        } catch { message.error("Failed to dispose"); }
    };

    const handleRunDepreciation = async () => {
        try {
            const result = await inventoryService.runDepreciation();
            message.success(`Depreciation run: ${result.processed} assets processed, total: ${fmtCurrency(result.totalDepreciation)}`);
            loadAll();
        } catch { message.error("Failed to run depreciation"); }
    };

    const openEdit = (asset: FixedAsset) => {
        setEditingAsset(asset);
        form.setFieldsValue(asset);
        setModalOpen(true);
    };

    const openDetail = async (asset: FixedAsset) => {
        try {
            const full = await inventoryService.getFixedAsset(asset.id);
            setSelectedAsset(full);
            setDrawerOpen(true);
        } catch {
            setSelectedAsset(asset);
            setDrawerOpen(true);
        }
    };

    // Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ KPI Cards Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
    const kpiCards = [
        { title: 'Total Assets', value: stats?.totalAssets || 0, icon: <CarOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { title: 'Active', value: stats?.active || 0, icon: <CheckCircleOutlined />, color: '#10b981' },
        { title: 'Maintenance', value: stats?.maintenance || 0, icon: <ToolOutlined />, color: '#f59e0b' },
        { title: 'Disposed', value: stats?.disposed || 0, icon: <CloseCircleOutlined />, color: '#94a3b8' },
        { title: 'Purchase Value', value: fmtCurrency(stats?.totalPurchaseValue), icon: <DollarOutlined />, color: '#3b82f6' },
        { title: 'Current Value', value: fmtCurrency(stats?.totalCurrentValue), icon: <DollarOutlined />, color: '#059669' },
    ];

    // Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ Depreciation Bar Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
    const depPct = stats && stats.totalPurchaseValue
        ? Math.round((stats.totalAccumulatedDep / stats.totalPurchaseValue) * 100)
        : 0;

    // Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ Columns Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
    const columns = [
        {
            title: 'Asset #', dataIndex: 'assetNumber', width: 140,
            render: (v: string) => <Text code className="text-xs">{v}</Text>,
        },
        {
            title: 'Name', dataIndex: 'assetName', ellipsis: true,
            render: (v: string, r: FixedAsset) => (
                <a onClick={() => openDetail(r)} className="cursor-pointer">
                    <Text strong className="text-sm" style={{ color: themeColor }}>{v}</Text>
                </a>
            ),
        },
        {
            title: 'Category', dataIndex: 'assetCategory', width: 120,
            render: (v: string) => v ? <Tag className="rounded-full text-xs capitalize">{v}</Tag> : 'Ã¢â‚¬â€',
        },
        {
            title: 'Purchase Price', dataIndex: 'purchasePrice', width: 140,
            render: (v: number) => fmtCurrency(v),
        },
        {
            title: 'Current Value', dataIndex: 'currentValue', width: 140,
            render: (v: number) => <Text strong>{fmtCurrency(v)}</Text>,
        },
        {
            title: 'Depreciation', key: 'dep', width: 150,
            render: (_: any, r: FixedAsset) => {
                if (!r.purchasePrice || r.depreciationMethod === 'no_depreciation') return <Text className="text-xs">N/A</Text>;
                const pct = r.purchasePrice ? Math.round(((r.accumulatedDepreciation || 0) / r.purchasePrice) * 100) : 0;
                return (
                    <div>
                        <Text className="text-xs">{fmtCurrency(r.accumulatedDepreciation)}</Text>
                        <Progress percent={pct} size="small" strokeColor={pct >= 80 ? '#ef4444' : '#6366f1'}
                            showInfo={false} className="!mb-0" />
                    </div>
                );
            },
        },
        {
            title: 'Condition', dataIndex: 'condition', width: 100,
            render: (v: string) => v ? <Tag color={CONDITIONS[v] || 'default'} className="rounded-full text-xs capitalize">{v}</Tag> : 'Ã¢â‚¬â€',
        },
        {
            title: 'Location', dataIndex: 'location', width: 130, ellipsis: true,
        },
        {
            title: 'Status', dataIndex: 'status', width: 120,
            render: (v: string) => {
                const s = ASSET_STATUSES[v] || { color: 'default', icon: null };
                return <Tag icon={s.icon} color={s.color} className="rounded-full text-xs">{v}</Tag>;
            },
        },
        {
            title: '', key: 'actions', width: 150,
            render: (_: any, r: FixedAsset) => (
                <Space size="small">
                    <Tooltip title="View"><Button size="small" icon={<EyeOutlined />} onClick={() => openDetail(r)} /></Tooltip>
                    <Tooltip title="Edit"><Button size="small" icon={<EditOutlined />} onClick={() => openEdit(r)} /></Tooltip>
                    {r.status === 'active' && (
                        <Tooltip title="Dispose">
                            <Button size="small" icon={<CloseCircleOutlined />} style={{ borderColor: '#f59e0b', color: '#f59e0b' }}
                                onClick={() => { setDisposeAssetId(r.id); disposeForm.resetFields(); setDisposeModalOpen(true); }} />
                        </Tooltip>
                    )}
                    <Button size="small" danger icon={<DeleteOutlined />}
                        onClick={() => Modal.confirm({ title: 'Delete this asset?', onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const filteredAssets = assets.filter(a =>
        !searchTerm || a.assetName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        a.assetNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (a.serialNumber || '').toLowerCase().includes(searchTerm.toLowerCase())
    );

    const assetSteps = [
        {
            title: "Asset Info",
            icon: <CarOutlined />,
            fields: ["assetName", "assetCategory", "serialNumber", "purchaseDate", "purchasePrice"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="assetName" label="Asset Name" rules={[{ required: true }]}>
                                <Input placeholder="e.g. Toyota Avanza B 1234 CD" />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="assetCategory" label="Category">
                                <Select placeholder="Select" options={CATEGORIES} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="serialNumber" label="Serial Number">
                                <Input placeholder="SN-XXX" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="purchaseDate" label="Purchase Date">
                                <Input type="date" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="purchasePrice" label="Purchase Price">
                                <InputNumber min={0} style={{ width: '100%' }} placeholder="0" />
                            </Form.Item>
                        </Col>
                    </Row>
                </>
            ),
        },
        {
            title: "Depreciation",
            icon: <ThunderboltOutlined />,
            fields: ["depreciationMethod", "usefulLifeMonths", "salvageValue"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="depreciationMethod" label="Method" initialValue="straight_line">
                                <Select options={DEP_METHODS} />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="usefulLifeMonths" label="Useful Life (months)">
                                <InputNumber min={1} style={{ width: '100%' }} placeholder="60" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="salvageValue" label="Salvage Value">
                                <InputNumber min={0} style={{ width: '100%' }} placeholder="0" />
                            </Form.Item>
                        </Col>
                    </Row>
                </>
            ),
        },
        {
            title: "Location & Maintenance",
            icon: <CalendarOutlined />,
            fields: ["location", "assignedTo", "condition", "warrantyExpiry", "maintenanceSchedule", "insurancePolicy", "notes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="location" label="Location">
                                <Input placeholder="Building A, Floor 2" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="assignedTo" label="Assigned To">
                                <Input placeholder="Department or person" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="condition" label="Condition" initialValue="good">
                                <Select options={[
                                    { value: 'excellent', label: 'Excellent' },
                                    { value: 'good', label: 'Good' },
                                    { value: 'fair', label: 'Fair' },
                                    { value: 'poor', label: 'Poor' },
                                    { value: 'damaged', label: 'Damaged' },
                                ]} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="warrantyExpiry" label="Warranty Expiry">
                                <Input type="date" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="maintenanceSchedule" label="Maintenance Schedule">
                                <Select placeholder="Select" options={[
                                    { value: 'monthly', label: 'Monthly' },
                                    { value: 'quarterly', label: 'Quarterly' },
                                    { value: 'bi_annual', label: 'Bi-Annual' },
                                    { value: 'annual', label: 'Annual' },
                                ]} allowClear />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="insurancePolicy" label="Insurance Policy">
                                <Input placeholder="Policy #" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="notes" label="Notes">
                        <Input.TextArea rows={2} placeholder="Asset notes" />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Fixed Assets</AuroraText>}
            subTitle={
                <DecryptedText
                    text="Track, depreciate, and manage company-owned assets and equipment"
                    animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential
                />
            }
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                {/* KPI Cards */}
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...(isDark ? glassDark : glass), borderTop: `3px solid ${s.color}`, position: 'relative', overflow: 'hidden',
                                }}>
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18 }}>
                                            {s.icon}
                                        </div>
                                        <div>
                                            <Text type="secondary" className="text-xs block">{s.title}</Text>
                                            <Text strong className="text-lg">{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Depreciation Summary */}
                {stats && stats.totalPurchaseValue > 0 && (
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                        <Card size="small" style={{
                            borderRadius: 12, background: 'linear-gradient(135deg, rgba(99,102,241,0.08), rgba(139,92,246,0.06))',
                            border: '1px solid rgba(99,102,241,0.15)',
                        }}>
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-xl flex items-center justify-center"
                                        style={{ background: 'rgba(99,102,241,0.12)', color: themeColor, fontSize: 20 }}>
                                        <ThunderboltOutlined />
                                    </div>
                                    <div>
                                        <Text type="secondary" className="text-xs block">Total Accumulated Depreciation</Text>
                                        <Text strong className="text-lg">{fmtCurrency(stats.totalAccumulatedDep)}</Text>
                                        <Text type="secondary" className="text-xs ml-2">({depPct}% of purchase value)</Text>
                                    </div>
                                    <div style={{ width: 200 }}>
                                        <Progress percent={depPct} strokeColor={{
                                            '0%': '#6366f1', '100%': depPct > 80 ? '#ef4444' : '#10b981',
                                        }} />
                                    </div>
                                </div>
                                <Button type="primary" icon={<ThunderboltOutlined />}
                                    onClick={() => Modal.confirm({
                                        title: 'Run Monthly Depreciation?',
                                        content: 'This will calculate and apply depreciation for all active assets.',
                                        onOk: handleRunDepreciation,
                                    })}
                                    style={{ background: 'linear-gradient(135deg, #6366f1, var(--theme-color, #7c3aed))', border: 'none', borderRadius: 8 }}>
                                    Run Depreciation
                                </Button>
                            </div>
                        </Card>
                    </motion.div>
                )}

                {/* Main Table Card */}
                <Card size="small" style={{
                    flex: 1, ...(isDark ? glassDark : glass), borderLeft: `3px solid var(--theme-color, #7c3aed)`,
                }}>
                    <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-3">
                            <Text strong style={{
                                background: 'linear-gradient(to right, #6366f1, var(--theme-color, #7c3aed))',
                                WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', fontSize: 15,
                            }}>
                                <CarOutlined /> Assets ({filteredAssets.length})
                            </Text>
                            <Input prefix={<SearchOutlined className="text-gray-400" />}
                                placeholder="Search..." value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)} allowClear
                                style={{ maxWidth: 220, borderRadius: 8 }} size="small" />
                            <Select value={filterCategory} onChange={v => setFilterCategory(v)} allowClear
                                placeholder="Category" style={{ width: 130 }} size="small"
                                options={CATEGORIES} />
                            <Select value={filterStatus} onChange={v => setFilterStatus(v)} allowClear
                                placeholder="Status" style={{ width: 130 }} size="small"
                                options={[
                                    { value: 'active', label: 'Active' },
                                    { value: 'maintenance', label: 'Maintenance' },
                                    { value: 'disposed', label: 'Disposed' },
                                ]} />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={loadAll} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_fixed-assets', title: 'Fixed Assets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Code', key: 'assetCode' }, { header: 'Category', key: 'category' }, { header: 'Status', key: 'status' }, { header: 'Value', key: 'acquisitionCost' }], data: assets })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_fixed-assets', title: 'Fixed Assets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Code', key: 'assetCode' }, { header: 'Category', key: 'category' }, { header: 'Status', key: 'status' }, { header: 'Value', key: 'acquisitionCost' }], data: assets })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />}
                                onClick={() => { setEditingAsset(null); form.resetFields(); setModalOpen(true); }}
                                style={{ background: 'linear-gradient(135deg, #6366f1, var(--theme-color, #7c3aed))', borderRadius: 8, border: 'none' }}>
                                New Asset
                            </Button>
                        </Space>
                    </div>

                    <Table
                        dataSource={filteredAssets} columns={columns}
                        rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 15, showSizeChanger: false }}
                        scroll={{ x: 1400 }}
                    />
                </Card>
            </div>

            {/* Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ Stepped Form Modal for Create/Edit Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ */}
            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditingAsset(null); form.resetFields(); }}
                onSubmit={handleCreateOrUpdate}
                form={form}
                title={editingAsset ? "Edit Asset" : "New Fixed Asset"}
                entityName="fixed_asset"
                steps={assetSteps}
                fields={ASSET_FIELDS}
                width={700}
                loading={false}
                onBatchCreate={handleBatchCreate}
                gradient={["#6366f1", "var(--theme-color, #7c3aed)"]}
                editMode={!!editingAsset}
                initialValues={editingAsset || undefined}
            />

            {/* Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ Dispose Modal Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ */}
            <Modal title="Dispose Asset" open={disposeModalOpen}
                onCancel={() => setDisposeModalOpen(false)} onOk={handleDispose}
                okText="Dispose" okButtonProps={{ danger: true }}>
                <Form form={disposeForm} layout="vertical">
                    <Form.Item name="disposalMethod" label="Disposal Method" rules={[{ required: true }]}>
                        <Select placeholder="Select method" options={[
                            { value: 'sold', label: 'Sold' },
                            { value: 'scrapped', label: 'Scrapped' },
                            { value: 'donated', label: 'Donated' },
                            { value: 'recycled', label: 'Recycled' },
                        ]} />
                    </Form.Item>
                    <Form.Item name="disposalValue" label="Disposal Value (if sold)">
                        <InputNumber min={0} style={{ width: '100%' }} placeholder="0" />
                    </Form.Item>
                </Form>
            </Modal>

            {/* Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ Detail Drawer Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ */}
            <Drawer title={selectedAsset?.assetName || 'Asset Detail'} open={drawerOpen}
                onClose={() => setDrawerOpen(false)} width={520}
                extra={selectedAsset && (
                    <Space>
                        <Button icon={<EditOutlined />} onClick={() => { setDrawerOpen(false); openEdit(selectedAsset); }}>Edit</Button>
                    </Space>
                )}>
                {selectedAsset && (
                    <div>
                        <Descriptions column={2} size="small" bordered>
                            <Descriptions.Item label="Asset #" span={1}>
                                <Text code>{selectedAsset.assetNumber}</Text>
                            </Descriptions.Item>
                            <Descriptions.Item label="Category" span={1}>
                                <Tag className="capitalize">{selectedAsset.assetCategory || 'N/A'}</Tag>
                            </Descriptions.Item>
                            <Descriptions.Item label="Serial #" span={1}>{selectedAsset.serialNumber || 'Ã¢â‚¬â€'}</Descriptions.Item>
                            <Descriptions.Item label="Condition" span={1}>
                                <Tag color={CONDITIONS[selectedAsset.condition || ''] || 'default'} className="capitalize">
                                    {selectedAsset.condition || 'Ã¢â‚¬â€'}
                                </Tag>
                            </Descriptions.Item>
                            <Descriptions.Item label="Status" span={2}>
                                {(() => {
                                    const s = ASSET_STATUSES[selectedAsset.status || ''] || { color: 'default', icon: null };
                                    return <Tag icon={s.icon} color={s.color}>{selectedAsset.status}</Tag>;
                                })()}
                            </Descriptions.Item>
                        </Descriptions>

                        <Divider className="!my-3"><Text type="secondary" className="text-xs">Financial</Text></Divider>
                        <Descriptions column={2} size="small" bordered>
                            <Descriptions.Item label="Purchase Date">{fmtDate(selectedAsset.purchaseDate)}</Descriptions.Item>
                            <Descriptions.Item label="Purchase Price">{fmtCurrency(selectedAsset.purchasePrice)}</Descriptions.Item>
                            <Descriptions.Item label="Current Value">
                                <Text strong style={{ color: '#10b981' }}>{fmtCurrency(selectedAsset.currentValue)}</Text>
                            </Descriptions.Item>
                            <Descriptions.Item label="Salvage Value">{fmtCurrency(selectedAsset.salvageValue)}</Descriptions.Item>
                        </Descriptions>

                        <Divider className="!my-3"><Text type="secondary" className="text-xs">Depreciation</Text></Divider>
                        <Descriptions column={2} size="small" bordered>
                            <Descriptions.Item label="Method" span={1}>
                                {selectedAsset.depreciationMethod?.replace(/_/g, ' ') || 'Ã¢â‚¬â€'}
                            </Descriptions.Item>
                            <Descriptions.Item label="Useful Life" span={1}>
                                {selectedAsset.usefulLifeMonths ? `${selectedAsset.usefulLifeMonths} months` : 'Ã¢â‚¬â€'}
                            </Descriptions.Item>
                            <Descriptions.Item label="Accumulated Dep." span={1}>
                                <Text style={{ color: '#ef4444' }}>{fmtCurrency(selectedAsset.accumulatedDepreciation)}</Text>
                            </Descriptions.Item>
                            <Descriptions.Item label="Last Dep. Date" span={1}>
                                {fmtDate(selectedAsset.lastDepreciationDate)}
                            </Descriptions.Item>
                        </Descriptions>
                        {selectedAsset.purchasePrice && selectedAsset.depreciationMethod !== 'no_depreciation' && (
                            <div className="mt-3">
                                <Progress
                                    percent={Math.round(((selectedAsset.accumulatedDepreciation || 0) / selectedAsset.purchasePrice) * 100)}
                                    strokeColor={{ '0%': '#6366f1', '100%': '#ef4444' }}
                                    format={pct => `${pct}% depreciated`}
                                />
                            </div>
                        )}

                        <Divider className="!my-3"><Text type="secondary" className="text-xs">Location & Assignment</Text></Divider>
                        <Descriptions column={2} size="small" bordered>
                            <Descriptions.Item label="Location">{selectedAsset.location || 'Ã¢â‚¬â€'}</Descriptions.Item>
                            <Descriptions.Item label="Assigned To">{selectedAsset.assignedTo || 'Ã¢â‚¬â€'}</Descriptions.Item>
                            <Descriptions.Item label="Warranty" span={2}>{fmtDate(selectedAsset.warrantyExpiry)}</Descriptions.Item>
                        </Descriptions>

                        <Divider className="!my-3"><Text type="secondary" className="text-xs">Maintenance</Text></Divider>
                        <Descriptions column={2} size="small" bordered>
                            <Descriptions.Item label="Schedule">{selectedAsset.maintenanceSchedule || 'Ã¢â‚¬â€'}</Descriptions.Item>
                            <Descriptions.Item label="Last Maint.">{fmtDate(selectedAsset.lastMaintenanceDate)}</Descriptions.Item>
                            <Descriptions.Item label="Next Maint.">{fmtDate(selectedAsset.nextMaintenanceDate)}</Descriptions.Item>
                            <Descriptions.Item label="Insurance">{selectedAsset.insurancePolicy || 'Ã¢â‚¬â€'}</Descriptions.Item>
                        </Descriptions>

                        {selectedAsset.status === 'disposed' && (
                            <>
                                <Divider className="!my-3"><Text type="secondary" className="text-xs">Disposal</Text></Divider>
                                <Descriptions column={2} size="small" bordered>
                                    <Descriptions.Item label="Disposed Date">{fmtDate(selectedAsset.disposedDate)}</Descriptions.Item>
                                    <Descriptions.Item label="Method">{selectedAsset.disposalMethod || 'Ã¢â‚¬â€'}</Descriptions.Item>
                                    <Descriptions.Item label="Disposal Value" span={2}>{fmtCurrency(selectedAsset.disposalValue)}</Descriptions.Item>
                                </Descriptions>
                            </>
                        )}

                        {selectedAsset.notes && (
                            <>
                                <Divider className="!my-3" />
                                <Text type="secondary" className="text-xs block mb-1">Notes</Text>
                                <Text>{selectedAsset.notes}</Text>
                            </>
                        )}
                    </div>
                )}
            </Drawer>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useMemo, useCallback, Suspense } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { Alert, Badge, Button, Card, Col, Descriptions, Divider, Drawer, Empty, Form, Image, Input, InputNumber, message, Modal, Popconfirm, Progress, Row, Segmented, Select, Space, Spin, Statistic, Steps, Switch, Table, Tabs, Tag, Tooltip, Typography, theme } from "antd";
import {
    PlusOutlined, SearchOutlined, EditOutlined, DeleteOutlined,
    DropboxOutlined, ShoppingCartOutlined, CalendarOutlined,
    SwapOutlined, TagOutlined, BarcodeOutlined, AppstoreOutlined,
    UnorderedListOutlined, FilterOutlined, ReloadOutlined,
    RobotOutlined, ThunderboltOutlined, BoxPlotOutlined,
    ScheduleOutlined, ShoppingOutlined, ToolOutlined,
    ExportOutlined, ImportOutlined, EyeOutlined,
    CheckCircleOutlined, ArrowLeftOutlined, ArrowRightOutlined,
    DollarOutlined, InboxOutlined, SafetyCertificateOutlined, PictureOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import { TooltipWrapper as AnimatedTooltip } from "@/components/mvpblocks/AnimatedTooltip";
import ItemMediaGallery, { ProductGallery, MediaInfo } from "@/components/inventory/ItemMediaGallery";
import { inventoryService, InvItem, InvCategory, InvStockStats, AiClassification } from "@/lib/inventoryService";
import { useRouter } from "next/navigation";

const { Title, Text, Paragraph } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };
const glassAuto = (dark: boolean) => dark ? glassDark : glass;

const SELLABLE_FULFILLMENT_TYPES = [
    { value: 'physical', label: 'Physical Goods', icon: <DropboxOutlined />, color: 'var(--theme-color, #7c3aed)', desc: 'Tangible products with stock tracking', example: 'Laptop, T-shirt, Bolt', sellable: true },
    { value: 'ticket', label: 'Ticket / Event', icon: <TagOutlined />, color: '#f59e0b', desc: 'One-time events with capacity & seats', example: 'Concert, Museum entry', sellable: true },
    { value: 'scheduled', label: 'Scheduled Service', icon: <ScheduleOutlined />, color: '#0ea5e9', desc: 'Recurring routes with timetables', example: 'Ship route, Bus line', sellable: true },
    { value: 'rental', label: 'Rental Asset', icon: <SwapOutlined />, color: '#10b981', desc: 'Items rented out & returned', example: 'Camera, Projector, Vehicle', sellable: true },
];

const NON_SELLABLE_TYPES = [
    { value: 'raw_material', label: 'Raw Material', icon: <ToolOutlined />, color: '#78716c', desc: 'Input materials for manufacturing', example: 'Fiberglass resin, Steel sheet', sellable: false },
    { value: 'consumable', label: 'Consumable', icon: <ExportOutlined />, color: '#a1a1aa', desc: 'Used internally, not for resale', example: 'Sandpaper, Cleaning solvent', sellable: false },
    { value: 'semi_finished', label: 'Semi-Finished', icon: <BoxPlotOutlined />, color: '#92400e', desc: 'Work-in-progress or intermediate goods', example: 'Pre-cut hull panel', sellable: false },
];

const FULFILLMENT_TYPES = [...SELLABLE_FULFILLMENT_TYPES, ...NON_SELLABLE_TYPES];

const ITEM_TYPE_FOR_FULFILLMENT: Record<string, string> = {
    physical: 'finished_good', ticket: 'service', scheduled: 'service', rental: 'goods',
    raw_material: 'raw_material', consumable: 'consumable', semi_finished: 'semi_finished',
};

const ITEM_TYPES = [
    { value: 'goods', label: 'Goods' },
    { value: 'service', label: 'Service' },
    { value: 'raw_material', label: 'Raw Material' },
    { value: 'finished_good', label: 'Finished Good' },
    { value: 'semi_finished', label: 'Semi-Finished' },
    { value: 'consumable', label: 'Consumable' },
];

const isSellableType = (ft: string) => !['raw_material', 'consumable', 'semi_finished'].includes(ft);

const STATUS_COLORS: Record<string, string> = {
    active: 'green', draft: 'orange', archived: 'default',
};

const WIZARD_STEPS = [
    { title: 'Type', icon: <AppstoreOutlined /> },
    { title: 'Details', icon: <EditOutlined /> },
    { title: 'Media', icon: <PictureOutlined /> },
    { title: 'Pricing', icon: <DollarOutlined /> },
    { title: 'Inventory', icon: <InboxOutlined /> },
    { title: 'Review', icon: <CheckCircleOutlined /> },
];

function ItemMasterContent() {
    const searchParams = useSearchParams();
    const catalogTenantId = searchParams.get("tenantId") || "default";

    const [items, setItems] = useState<InvItem[]>([]);
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const { startDate, endDate } = useDateRangeStore();
    const [categories, setCategories] = useState<InvCategory[]>([]);
    const [stats, setStats] = useState<InvStockStats | null>(null);
    const [loading, setLoading] = useState(true);

    // Filters
    const [searchTerm, setSearchTerm] = useState("");
    const [filterFulfillment, setFilterFulfillment] = useState<string>("");
    const [filterStatus, setFilterStatus] = useState<string>("");
    const [viewMode, setViewMode] = useState<'table' | 'grid'>('table');

    // Modal
    const [formOpen, setFormOpen] = useState(false);
    const [editingItem, setEditingItem] = useState<InvItem | null>(null);
    const [detailDrawer, setDetailDrawer] = useState<InvItem | null>(null);
    const [aiClassifying, setAiClassifying] = useState(false);
    const [aiResult, setAiResult] = useState<AiClassification | null>(null);
    const [wizardStep, setWizardStep] = useState(0);
    const [selectedFulfillment, setSelectedFulfillment] = useState('physical');
    const [form] = Form.useForm();

    // Category modal
    const [categoryModalOpen, setCategoryModalOpen] = useState(false);
    const [categoryForm] = Form.useForm();

    // Make Sellable modal
    const [sellableModalOpen, setSellableModalOpen] = useState(false);
    const [sellableItem, setSellableItem] = useState<InvItem | null>(null);
    const [sellableType, setSellableType] = useState('physical');
    const [sellablePrice, setSellablePrice] = useState<number>(0);
    const [sellableSaving, setSellableSaving] = useState(false);

    // Gallery media IDs (for wizard)
    const [galleryMediaIds, setGalleryMediaIds] = useState<string[]>([]);

    // Media URL map
    const [mediaMap, setMediaMap] = useState<Record<string, { url: string; filename: string; mimeType?: string }>>({});

    useEffect(() => { loadAll(); }, [catalogTenantId]);

    const loadMediaForItems = useCallback(async (itemList: InvItem[]) => {
        const allMediaIds = [...new Set(itemList.flatMap(i => i.mediaIds || []).filter(Boolean))];
        if (allMediaIds.length === 0) return;
        try {
            const map = await inventoryService.getMediaByIds(allMediaIds);
            setMediaMap(prev => ({ ...prev, ...map }));
        } catch { /* ignore */ }
    }, []);

    const loadAll = async () => {
        setLoading(true);
        try {
            const [itemsData, catsData, statsData] = await Promise.all([
                inventoryService.getItems(catalogTenantId),
                inventoryService.getCategories(catalogTenantId),
                inventoryService.getStockStats(catalogTenantId),
            ]);
            setItems(itemsData);
            setCategories(catsData);
            setStats(statsData);
            loadMediaForItems(itemsData);
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const filteredItems = useMemo(() => {
        let filtered = items;
        if (searchTerm) {
            const s = searchTerm.toLowerCase();
            filtered = filtered.filter(i =>
                i.name.toLowerCase().includes(s) ||
                i.sku?.toLowerCase().includes(s) ||
                i.description?.toLowerCase().includes(s)
            );
        }
        if (filterFulfillment) filtered = filtered.filter(i => i.fulfillmentType === filterFulfillment);
        if (filterStatus) filtered = filtered.filter(i => i.status === filterStatus);
        return filtered;
    }, [items, searchTerm, filterFulfillment, filterStatus]);

    const handleCreate = () => {
        setEditingItem(null);
        setAiResult(null);
        setWizardStep(0);
        setSelectedFulfillment('physical');
        setGalleryMediaIds([]);
        form.resetFields();
        form.setFieldsValue({ fulfillmentType: 'physical', itemType: 'goods', status: 'active', currency: 'IDR', primaryUom: 'pcs' });
        setFormOpen(true);
    };

    const handleEdit = (item: InvItem) => {
        setEditingItem(item);
        setAiResult(null);
        setWizardStep(1); // skip type selection when editing
        setSelectedFulfillment(item.fulfillmentType || 'physical');
        setGalleryMediaIds(item.mediaIds || []);
        form.setFieldsValue(item);
        setFormOpen(true);
    };

    const handleDelete = async (id: string) => {
        try {
            await inventoryService.deleteItem(id);
            message.success("Item deleted");
            loadAll();
        } catch { message.error("Failed to delete"); }
    };

    const handleSubmit = async () => {
        try {
            const values = await form.validateFields();
            values.mediaIds = galleryMediaIds;
            if (editingItem) {
                await inventoryService.updateItem(editingItem.id, values);
                message.success("Item updated");
            } else {
                await inventoryService.createItem(catalogTenantId, values);
                message.success("Item created");
            }
            setFormOpen(false);
            loadAll();
        } catch { message.error("Validation failed"); }
    };

    const handleGalleryUpload = async (file: File): Promise<MediaInfo | null> => {
        const result = await inventoryService.uploadItemMedia(file);
        if (result) {
            const info: MediaInfo = { id: result.id, url: result.url, filename: result.filename, mimeType: result.mimeType };
            setMediaMap(prev => ({ ...prev, [result.id]: info }));
            return info;
        }
        return null;
    };

    const handleGalleryDelete = async (id: string) => {
        await inventoryService.deleteMedia(id);
    };

    const handleAiClassify = async () => {
        const name = form.getFieldValue('name');
        const desc = form.getFieldValue('description');
        if (!name) { message.warning("Enter item name first"); return; }
        setAiClassifying(true);
        try {
            const result = await inventoryService.aiClassifyItem(name, desc);
            setAiResult(result);
            // Auto-fill suggestions
            if (result.suggestedItemType) form.setFieldValue('itemType', result.suggestedItemType);
            if (result.suggestedFulfillmentType) form.setFieldValue('fulfillmentType', result.suggestedFulfillmentType);
            if (result.suggestedTags?.length) form.setFieldValue('tags', result.suggestedTags);
            message.success(`AI classified with ${result.confidence}% confidence`);
        } catch { message.error("AI classification failed"); }
        finally { setAiClassifying(false); }
    };

    const handleCreateCategory = async () => {
        try {
            const values = await categoryForm.validateFields();
            await inventoryService.createCategory(catalogTenantId, values);
            message.success("Category created");
            setCategoryModalOpen(false);
            categoryForm.resetFields();
            loadAll();
        } catch { message.error("Failed to create category"); }
    };

    const openMakeSellable = (item: InvItem) => {
        setSellableItem(item);
        setSellableType('physical');
        setSellablePrice(0);
        setSellableModalOpen(true);
    };

    const handleMakeSellable = async () => {
        if (!sellableItem) return;
        setSellableSaving(true);
        try {
            await inventoryService.updateItem(sellableItem.id, {
                fulfillmentType: sellableType,
                itemType: ITEM_TYPE_FOR_FULFILLMENT[sellableType],
                sellingPrice: sellablePrice,
            });
            message.success(`"${sellableItem.name}" is now a sellable ${sellableType} product!`);
            setSellableModalOpen(false);
            setSellableItem(null);
            if (detailDrawer?.id === sellableItem.id) setDetailDrawer(null);
            loadAll();
        } catch { message.error('Failed to convert item'); }
        finally { setSellableSaving(false); }
    };

    // â”€â”€â”€ Table Columns â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    const columns = [
        {
            title: 'Item',
            key: 'name',
            sorter: (a: InvItem, b: InvItem) => a.name.localeCompare(b.name),
            render: (_: any, r: InvItem) => {
                const firstMediaId = (r.mediaIds || [])[0];
                const media = firstMediaId ? mediaMap[firstMediaId] : null;
                return (
                    <div className="flex items-center gap-3">
                        {media ? (
                            <img src={media.url} alt={r.name}
                                style={{ width: 40, height: 40, borderRadius: 8, objectFit: 'cover' }} />
                        ) : (
                            <div className="w-10 h-10 rounded-lg flex items-center justify-center text-lg"
                                style={{ background: `${FULFILLMENT_TYPES.find(f => f.value === r.fulfillmentType)?.color || 'var(--theme-color, #7c3aed)'}15` }}>
                                {FULFILLMENT_TYPES.find(f => f.value === r.fulfillmentType)?.icon || <DropboxOutlined />}
                            </div>
                        )}
                        <div>
                            <Text strong className="block text-sm cursor-pointer hover:text-[color:var(--theme-color, #7c3aed)]"
                                onClick={() => setDetailDrawer(r)}>{r.name}</Text>
                            <Text type="secondary" className="text-xs">{r.sku}</Text>
                        </div>
                    </div>
                );
            },
        },
        {
            title: 'Type',
            key: 'fulfillmentType',
            width: 140,
            render: (_: any, r: InvItem) => {
                const ft = FULFILLMENT_TYPES.find(f => f.value === r.fulfillmentType);
                return <Tag color={ft?.color} className="rounded-full text-xs px-2">{ft?.label || r.fulfillmentType}</Tag>;
            },
        },
        {
            title: 'Category',
            key: 'category',
            width: 140,
            render: (_: any, r: InvItem) => {
                const cat = categories.find(c => c.id === r.categoryId);
                return cat ? <Tag className="rounded-full text-xs">{cat.name}</Tag> : <Text type="secondary" className="text-xs">-</Text>;
            },
        },
        {
            title: 'Cost',
            dataIndex: 'costPrice',
            width: 120,
            sorter: (a: InvItem, b: InvItem) => (a.costPrice || 0) - (b.costPrice || 0),
            render: (v: number, r: InvItem) => <Text className="text-xs font-medium">{(r.currency || 'IDR')} {(v || 0).toLocaleString()}</Text>,
        },
        {
            title: 'Sell Price',
            dataIndex: 'sellingPrice',
            width: 120,
            sorter: (a: InvItem, b: InvItem) => (a.sellingPrice || 0) - (b.sellingPrice || 0),
            render: (v: number, r: InvItem) => <Text className="text-xs font-medium text-green-600">{(r.currency || 'IDR')} {(v || 0).toLocaleString()}</Text>,
        },
        {
            title: 'UOM',
            dataIndex: 'primaryUom',
            width: 80,
            render: (v: string) => <Text className="text-xs">{v || '-'}</Text>,
        },
        {
            title: 'Status',
            dataIndex: 'status',
            width: 90,
            render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'} className="rounded-full text-xs">{v}</Tag>,
        },
        {
            title: '',
            key: 'actions',
            width: 100,
            render: (_: any, r: InvItem) => (
                <Space size={4}>
                    <AnimatedTooltip content="View">
                        <Button type="text" size="small" icon={<EyeOutlined />}
                            className="text-gray-400 hover:text-[color:var(--theme-color, #7c3aed)]"
                            onClick={() => setDetailDrawer(r)} />
                    </AnimatedTooltip>
                    <AnimatedTooltip content="Edit">
                        <Button type="text" size="small" icon={<EditOutlined />}
                            className="text-gray-400 hover:text-blue-500"
                            onClick={() => handleEdit(r)} />
                    </AnimatedTooltip>
                    {!isSellableType(r.fulfillmentType || '') && (
                        <AnimatedTooltip content="Make Sellable">
                            <Button type="text" size="small" icon={<ShoppingOutlined />}
                                className="text-gray-400 hover:text-green-500"
                                onClick={() => openMakeSellable(r)} />
                        </AnimatedTooltip>
                    )}
                    <AnimatedTooltip content="Locate in Warehouse">
                        <Button type="text" size="small" icon={<InboxOutlined />}
                            className="text-gray-400 hover:text-green-500"
                            onClick={() => router.push(`/admin/inventory/item-locator?bin=${encodeURIComponent(r.sku || r.name)}`)} />
                    </AnimatedTooltip>
                    <Popconfirm title="Delete this item?" onConfirm={() => handleDelete(r.id)}>
                        <AnimatedTooltip content="Delete">
                            <Button type="text" size="small" icon={<DeleteOutlined />}
                                className="text-gray-400 hover:text-red-500" />
                        </AnimatedTooltip>
                    </Popconfirm>
                </Space>
            ),
        },
    ];

    // â”€â”€â”€ Stats Cards â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    const statsCards = [
        { title: 'Total Items', value: stats?.totalItems || 0, icon: <DropboxOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { title: 'Physical', value: stats?.physicalCount || 0, icon: <BoxPlotOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { title: 'Tickets', value: stats?.ticketCount || 0, icon: <TagOutlined />, color: '#f59e0b' },
        { title: 'Scheduled', value: stats?.scheduledCount || 0, icon: <ScheduleOutlined />, color: '#0ea5e9' },
        { title: 'Rental', value: stats?.rentalCount || 0, icon: <SwapOutlined />, color: '#10b981' },
        { title: 'Low Stock', value: stats?.lowStockCount || 0, icon: <ThunderboltOutlined />, color: '#ef4444' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Item Master</AuroraText>}
            subTitle={
                <DecryptedText
                    text="Unified registry for physical goods, services, tickets, schedules, and rental items"
                    animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential
                />
            }
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                <Alert
                    type="info"
                    showIcon
                    message={
                        <>
                            Tenant katalog: <Text code>{catalogTenantId}</Text>
                            {searchParams.get("tenantId") ? (
                                <>
                                    {" "}
                                    (UMKM WA) — <Link href="/admin/ai-studio/umkm">Kelola UMKM</Link>
                                </>
                            ) : null}
                        </>
                    }
                    style={{ borderRadius: 10 }}
                />
                {/* Stats Row */}
                <Row gutter={[12, 12]}>
                    {statsCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...(isDark ? glassDark : glass), borderTop: `3px solid ${s.color}`, position: 'relative', overflow: 'hidden',
                                }}>
                                    <div style={{ position: 'absolute', top: -10, right: -10, width: 60, height: 60, borderRadius: '50%', background: `radial-gradient(circle, ${s.color}18 0%, transparent 70%)`, pointerEvents: 'none' }} />
                                    <div className="flex items-center gap-3" style={{ position: 'relative' }}>
                                        <div className="w-11 h-11 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18, border: `1px solid ${s.color}20` }}>
                                            {s.icon}
                                        </div>
                                        <div>
                                            <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.5)' : 'rgba(0,0,0,0.45)', letterSpacing: 0.5, textTransform: 'uppercase' as const }} className="block">{s.title}</Text>
                                            <Text strong style={{ fontSize: 20, fontWeight: 700, color: s.color }}>{s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Toolbar */}
                <Card size="small" style={{
                    ...(isDark ? glassDark : glass),
                }}>
                    <div className="flex items-center justify-between gap-3 flex-wrap">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                            <Input
                                prefix={<SearchOutlined className="text-gray-400" />}
                                placeholder="Search items..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                allowClear
                                style={{ maxWidth: 280, borderRadius: 8 }}
                            />
                            <Select
                                placeholder="Fulfillment"
                                value={filterFulfillment || undefined}
                                onChange={v => setFilterFulfillment(v || '')}
                                allowClear
                                style={{ width: 160 }}
                                options={[{ value: '', label: 'All Types' }, ...FULFILLMENT_TYPES]}
                            />
                            <Select
                                placeholder="Status"
                                value={filterStatus || undefined}
                                onChange={v => setFilterStatus(v || '')}
                                allowClear
                                style={{ width: 120 }}
                                options={[
                                    { value: '', label: 'All' },
                                    { value: 'active', label: 'Active' },
                                    { value: 'draft', label: 'Draft' },
                                    { value: 'archived', label: 'Archived' },
                                ]}
                            />
                        </div>
                        <div className="flex items-center gap-2">
                            <Segmented
                                size="small"
                                value={viewMode}
                                onChange={v => setViewMode(v as 'table' | 'grid')}
                                options={[
                                    { value: 'table', icon: <UnorderedListOutlined /> },
                                    { value: 'grid', icon: <AppstoreOutlined /> },
                                ]}
                            />
                            <AnimatedTooltip content="Reload">
                                <Button icon={<ReloadOutlined />} onClick={loadAll} />
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_items', title: 'Inventory Items', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'SKU', key: 'sku' }, { header: 'Category', key: 'category' }, { header: 'Stock', key: 'quantityOnHand' }, { header: 'Unit Cost', key: 'unitCost' }], data: items })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_items', title: 'Inventory Items', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'SKU', key: 'sku' }, { header: 'Category', key: 'category' }, { header: 'Stock', key: 'quantityOnHand' }, { header: 'Unit Cost', key: 'unitCost' }], data: items })} /></Tooltip></RbacGuard>
                            </AnimatedTooltip>
                            <AnimatedTooltip content="New Category">
                                <Button icon={<AppstoreOutlined />} onClick={() => setCategoryModalOpen(true)} />
                            </AnimatedTooltip>
                            <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}
                                style={{ background: 'linear-gradient(135deg, var(--theme-color, #7c3aed), var(--theme-secondary, #6366f1))', borderRadius: 8, border: 'none' }}>
                                New Item
                            </Button>
                        </div>
                    </div>
                </Card>

                {/* Table / Grid */}
                <Card size="small" style={{
                    flex: 1, minHeight: 0,
                    ...(isDark ? glassDark : glass), borderLeft: `3px solid var(--theme-color, #7c3aed)`,
                }}>
                    {viewMode === 'table' ? (
                        <Table
                            dataSource={filteredItems}
                            columns={columns}
                            rowKey="id"
                            loading={loading}
                            pagination={{ pageSize: 15, showSizeChanger: true, showTotal: (t, r) => `${r[0]}-${r[1]} of ${t}` }}
                            size="small"
                            scroll={{ x: 900 }}
                        />
                    ) : (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))', gap: 12, padding: 4 }}>
                            {loading ? <Spin className="col-span-full flex justify-center py-20" /> :
                                filteredItems.length === 0 ? <Empty className="col-span-full py-20" description="No items found" /> :
                                    filteredItems.map((item, i) => {
                                        const ft = FULFILLMENT_TYPES.find(f => f.value === item.fulfillmentType);
                                        return (
                                            <motion.div key={item.id} initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.03 }}>
                                                <Card size="small" hoverable className="rounded-xl cursor-pointer" onClick={() => setDetailDrawer(item)}
                                                    style={{ borderColor: `${ft?.color || 'var(--theme-color, #7c3aed)'}30` }}>
                                                    <div className="flex items-start gap-3 mb-2">
                                                        <div className="w-10 h-10 rounded-lg flex items-center justify-center"
                                                            style={{ background: `${ft?.color || 'var(--theme-color, #7c3aed)'}15`, fontSize: 18 }}>
                                                            {ft?.icon || <DropboxOutlined />}
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <Text strong className="block text-sm truncate">{item.name}</Text>
                                                            <Text type="secondary" className="text-xs">{item.sku}</Text>
                                                        </div>
                                                        <Tag color={STATUS_COLORS[item.status || 'active']} className="rounded-full text-xs">{item.status}</Tag>
                                                    </div>
                                                    <div className="flex items-center justify-between">
                                                        <Text className="text-xs">{item.currency} {(item.sellingPrice || 0).toLocaleString()}</Text>
                                                        <Tag color={ft?.color} className="rounded-full text-xs m-0">{ft?.label}</Tag>
                                                    </div>
                                                </Card>
                                            </motion.div>
                                        );
                                    })}
                        </div>
                    )}
                </Card>
            </div>

            {/* â•â•â• Wizard Modal â•â•â• */}
            <Modal
                title={null}
                open={formOpen}
                onCancel={() => setFormOpen(false)}
                footer={null}
                width={900}
                closable={false}
                centered
                styles={{ body: { padding: 0 } }}
            >
                {/* Drawer Header */}
                <div style={{ padding: '20px 28px 0', borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : '#f0f0f0'}`, paddingBottom: 20 }}>
                    <div className="flex items-center justify-between mb-4">
                        <div>
                            <Title level={4} className="!m-0" style={{ background: 'linear-gradient(135deg, var(--theme-color, #7c3aed), var(--theme-secondary, #6366f1))', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                                {editingItem ? 'Edit Item' : 'Create New Item'}
                            </Title>
                            <Text type="secondary" className="text-xs">{WIZARD_STEPS[wizardStep]?.title} â€” Step {wizardStep + 1} of {WIZARD_STEPS.length}</Text>
                        </div>
                        <Button type="text" onClick={() => setFormOpen(false)} style={{ fontSize: 18 }}>âœ•</Button>
                    </div>
                    <Steps current={wizardStep} size="small" onChange={s => { if (editingItem || s < wizardStep) setWizardStep(s); }}
                        items={WIZARD_STEPS.map(s => ({ title: s.title, icon: s.icon }))}
                    />
                </div>

                {/* Step Content */}
                <div style={{ maxHeight: '55vh', overflow: 'auto', padding: '24px 28px' }}>
                    <Form form={form} layout="vertical" size="middle">
                        <AnimatePresence mode="wait">
                            {/* â”€â”€ Step 0: Type Selection â”€â”€ */}
                            {wizardStep === 0 && (
                                <motion.div key="step0" initial={{ opacity: 0, x: 30 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -30 }} transition={{ duration: 0.2 }}>
                                    <Text strong className="text-base block mb-1">What kind of item are you creating?</Text>
                                    <Text type="secondary" className="text-xs block mb-4">Choose the fulfillment model that best describes this item.</Text>

                                    <Text type="secondary" className="text-xs uppercase tracking-wider block mb-2" style={{ color: '#16a34a' }}>ðŸ“¦ Sellable â€” appears in product catalog</Text>
                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 16 }}>
                                        {SELLABLE_FULFILLMENT_TYPES.map((ft, i) => {
                                            const isActive = selectedFulfillment === ft.value;
                                            return (
                                                <motion.div key={ft.value} initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                                    <Card hoverable onClick={() => { setSelectedFulfillment(ft.value); form.setFieldsValue({ fulfillmentType: ft.value, itemType: ITEM_TYPE_FOR_FULFILLMENT[ft.value] }); }}
                                                        style={{ borderRadius: 14, cursor: 'pointer', transition: 'all 0.25s', border: isActive ? `2px solid ${ft.color}` : `2px solid ${isDark ? 'rgba(255,255,255,0.08)' : '#f0f0f0'}`, background: isActive ? `${ft.color}08` : isDark ? 'rgba(255,255,255,0.03)' : '#fff', boxShadow: isActive ? `0 4px 20px ${ft.color}20` : 'none' }}
                                                        styles={{ body: { padding: '16px' } }}>
                                                        <div className="flex items-start gap-3">
                                                            <div style={{ width: 44, height: 44, borderRadius: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 20, background: `${ft.color}${isActive ? '20' : '10'}`, color: ft.color }}>{ft.icon}</div>
                                                            <div className="flex-1">
                                                                <div className="flex items-center gap-2 mb-1"><Text strong className="text-sm">{ft.label}</Text>{isActive && <CheckCircleOutlined style={{ color: ft.color, fontSize: 14 }} />}</div>
                                                                <Text type="secondary" className="text-xs block">{ft.desc}</Text>
                                                            </div>
                                                        </div>
                                                    </Card>
                                                </motion.div>
                                            );
                                        })}
                                    </div>

                                    <Divider style={{ margin: '8px 0 12px' }}><Text type="secondary" className="text-xs">Internal / Non-Sellable</Text></Divider>
                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 10 }}>
                                        {NON_SELLABLE_TYPES.map((ft, i) => {
                                            const isActive = selectedFulfillment === ft.value;
                                            return (
                                                <motion.div key={ft.value} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 + i * 0.04 }}>
                                                    <Card hoverable onClick={() => { setSelectedFulfillment(ft.value); form.setFieldsValue({ fulfillmentType: ft.value, itemType: ITEM_TYPE_FOR_FULFILLMENT[ft.value] }); }}
                                                        style={{ borderRadius: 12, cursor: 'pointer', transition: 'all 0.25s', border: isActive ? `2px solid ${ft.color}` : `2px solid ${isDark ? 'rgba(255,255,255,0.08)' : '#f0f0f0'}`, background: isActive ? `${ft.color}08` : isDark ? 'rgba(255,255,255,0.02)' : '#fafafa', boxShadow: isActive ? `0 3px 14px ${ft.color}20` : 'none' }}
                                                        styles={{ body: { padding: '12px 14px' } }}>
                                                        <div className="flex items-center gap-3">
                                                            <div style={{ width: 36, height: 36, borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, background: `${ft.color}${isActive ? '20' : '10'}`, color: ft.color }}>{ft.icon}</div>
                                                            <div>
                                                                <div className="flex items-center gap-1"><Text strong className="text-xs">{ft.label}</Text>{isActive && <CheckCircleOutlined style={{ color: ft.color, fontSize: 12 }} />}</div>
                                                                <Text type="secondary" style={{ fontSize: 10, display: 'block' }}>{ft.desc}</Text>
                                                            </div>
                                                        </div>
                                                    </Card>
                                                </motion.div>
                                            );
                                        })}
                                    </div>
                                    <Form.Item name="fulfillmentType" hidden><Input /></Form.Item>
                                </motion.div>
                            )}

                            {/* â”€â”€ Step 1: Details â”€â”€ */}
                            {wizardStep === 1 && (
                                <motion.div key="step1" initial={{ opacity: 0, x: 30 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -30 }} transition={{ duration: 0.2 }}>
                                    <Text strong className="text-base block mb-1">Item Details</Text>
                                    <Text type="secondary" className="text-xs block mb-5">Give your item a name, description, and let AI help classify it.</Text>

                                    <Form.Item name="name" label="Item Name" rules={[{ required: true, message: 'Item name is required' }]}>
                                        <Input placeholder={selectedFulfillment === 'physical' ? 'e.g. MacBook Pro 14" M3' : selectedFulfillment === 'ticket' ? 'e.g. Concert VIP Ticket' : selectedFulfillment === 'scheduled' ? 'e.g. Jakarta â†’ Surabaya Ferry' : 'e.g. Canon EOS R5 Camera'}
                                            size="large" style={{ borderRadius: 10 }}
                                            suffix={<Button type="link" icon={<RobotOutlined />} loading={aiClassifying} onClick={handleAiClassify} style={{ color: 'var(--theme-color, #7c3aed)', padding: 0 }}>AI Classify</Button>}
                                        />
                                    </Form.Item>

                                    {aiResult && (
                                        <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }}>
                                            <Card size="small" className="mb-4" style={{ background: 'linear-gradient(135deg, #faf5ff, #f0f0ff)', borderColor: '#d8b4fe', borderRadius: 12 }}>
                                                <div className="flex items-center gap-2 mb-2">
                                                    <div style={{ width: 28, height: 28, borderRadius: 8, background: 'rgba(var(--theme-color-rgb, 124, 58, 237), 0.08)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                        <RobotOutlined style={{ color: 'var(--theme-color, #7c3aed)', fontSize: 14 }} />
                                                    </div>
                                                    <Text strong className="text-xs" style={{ color: 'var(--theme-color, #7c3aed)' }}>AI Suggestion Â· {aiResult.confidence}% confidence</Text>
                                                </div>
                                                <div className="flex gap-2 flex-wrap">
                                                    <Tag color="purple" className="rounded-full">{aiResult.suggestedCategory}</Tag>
                                                    <Tag color="blue" className="rounded-full">{aiResult.suggestedItemType}</Tag>
                                                    <Tag color="green" className="rounded-full">{aiResult.suggestedFulfillmentType}</Tag>
                                                    {aiResult.suggestedTags.map(t => <Tag key={t} className="text-xs rounded-full">{t}</Tag>)}
                                                </div>
                                            </Card>
                                        </motion.div>
                                    )}

                                    <Form.Item name="description" label="Description">
                                        <Input.TextArea rows={3} placeholder="Describe this item in detail..." style={{ borderRadius: 10 }} />
                                    </Form.Item>

                                    <Row gutter={16}>
                                        <Col span={12}>
                                            <Form.Item name="itemType" label="Item Type">
                                                <Select options={ITEM_TYPES} style={{ borderRadius: 10 }} />
                                            </Form.Item>
                                        </Col>
                                        <Col span={12}>
                                            <Form.Item name="categoryId" label="Category">
                                                <Select allowClear placeholder="Select category"
                                                    options={categories.map(c => ({ value: c.id, label: c.name }))}
                                                    dropdownRender={menu => (<>{menu}<Divider className="my-1" /><Button type="link" icon={<PlusOutlined />} onClick={() => setCategoryModalOpen(true)} className="w-full text-left text-xs">Create category</Button></>)}
                                                />
                                            </Form.Item>
                                        </Col>
                                    </Row>
                                    <Row gutter={16}>
                                        <Col span={12}>
                                            <Form.Item name="brand" label="Brand">
                                                <Input placeholder="Brand name" style={{ borderRadius: 10 }} />
                                            </Form.Item>
                                        </Col>
                                        <Col span={12}>
                                            <Form.Item name="tags" label="Tags">
                                                <Select mode="tags" placeholder="Add tags..." style={{ borderRadius: 10 }} />
                                            </Form.Item>
                                        </Col>
                                    </Row>

                                    {/* Type-specific detail fields */}
                                    {(selectedFulfillment === 'ticket') && (<>
                                        <Divider className="my-3" /><Text strong className="text-xs text-gray-400 uppercase tracking-wider block mb-3">ðŸŽ« Event Details</Text>
                                        <Row gutter={16}>
                                            <Col span={12}><Form.Item name={['metadata', 'venue']} label="Venue / Location"><Input placeholder="e.g. Bali Convention Center" style={{ borderRadius: 10 }} /></Form.Item></Col>
                                            <Col span={12}><Form.Item name={['metadata', 'eventDate']} label="Event Date"><Input type="date" style={{ borderRadius: 10 }} /></Form.Item></Col>
                                        </Row>
                                        <Row gutter={16}>
                                            <Col span={12}><Form.Item name={['metadata', 'capacity']} label="Total Capacity"><InputNumber min={1} placeholder="e.g. 500" style={{ width: '100%', borderRadius: 10 }} /></Form.Item></Col>
                                            <Col span={12}><Form.Item name={['metadata', 'seatSections']} label="Seat Sections"><Select mode="tags" placeholder="e.g. VIP, Regular, Standing" style={{ borderRadius: 10 }} /></Form.Item></Col>
                                        </Row>
                                    </>)}

                                    {(selectedFulfillment === 'scheduled') && (<>
                                        <Divider className="my-3" /><Text strong className="text-xs text-gray-400 uppercase tracking-wider block mb-3">ðŸ—“ï¸ Route Details</Text>
                                        <Row gutter={16}>
                                            <Col span={12}><Form.Item name={['metadata', 'origin']} label="Origin"><Input placeholder="e.g. Sanur Harbor" style={{ borderRadius: 10 }} /></Form.Item></Col>
                                            <Col span={12}><Form.Item name={['metadata', 'destination']} label="Destination"><Input placeholder="e.g. Nusa Penida" style={{ borderRadius: 10 }} /></Form.Item></Col>
                                        </Row>
                                        <Row gutter={16}>
                                            <Col span={8}><Form.Item name={['metadata', 'capacity']} label="Capacity"><InputNumber min={1} placeholder="100" style={{ width: '100%', borderRadius: 10 }} /></Form.Item></Col>
                                            <Col span={8}><Form.Item name={['metadata', 'durationMinutes']} label="Duration (min)"><InputNumber min={1} placeholder="45" style={{ width: '100%', borderRadius: 10 }} /></Form.Item></Col>
                                            <Col span={8}><Form.Item name={['metadata', 'vehicleName']} label="Vehicle"><Input placeholder="e.g. KMP Nusa Jaya" style={{ borderRadius: 10 }} /></Form.Item></Col>
                                        </Row>
                                    </>)}

                                    {(selectedFulfillment === 'rental') && (<>
                                        <Divider className="my-3" /><Text strong className="text-xs text-gray-400 uppercase tracking-wider block mb-3">ðŸ”‘ Rental Details</Text>
                                        <Row gutter={16}>
                                            <Col span={8}><Form.Item name={['metadata', 'rentalPeriod']} label="Rental Period"><Select options={[{ value: 'hourly', label: 'Hourly' }, { value: 'daily', label: 'Daily' }, { value: 'weekly', label: 'Weekly' }, { value: 'monthly', label: 'Monthly' }]} style={{ borderRadius: 10 }} /></Form.Item></Col>
