'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { Table, Tag, Button, Space, message, Tabs, Progress, Drawer, Descriptions, Badge, Tooltip, Modal, Form, Input, InputNumber, Select, DatePicker, Row, Col, Card, Typography, theme } from 'antd';
import { PlusOutlined, ReloadOutlined, SearchOutlined, ToolOutlined, CheckCircleOutlined, WarningOutlined, DollarOutlined, SwapOutlined, ClockCircleOutlined, CarOutlined, EyeOutlined, UserOutlined, CalendarOutlined , FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import RbacGuard from '@/components/common/RbacGuard';
import { inventoryService, RentalAsset, RentalContract, RentalStatsType } from '@/lib/inventoryService';
import dayjs from 'dayjs';
import DecryptedText from "@/components/react-bits/DecryptedText";
import { AuroraText } from "@/components/magicui/aurora-text";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

const CONDITION_COLORS: Record<string, string> = { excellent: 'green', good: 'blue', fair: 'orange', poor: 'red' };
const STATUS_COLORS: Record<string, string> = { available: 'green', rented: 'blue', maintenance: 'orange', retired: 'default', active: 'blue', returned: 'green', overdue: 'red', lost: 'volcano', cancelled: 'default' };

const CONTRACT_FIELDS: FieldDef[] = [
    { name: 'contractCode', label: 'Contract Code', required: true },
    { name: 'assetId', label: 'Asset', required: true },
    { name: 'customerName', label: 'Customer Name', required: true },
    { name: 'customerEmail', label: 'Customer Email' },
    { name: 'customerPhone', label: 'Customer Phone' },
    { name: 'customerIdNumber', label: 'ID Number' },
    { name: 'checkoutDate', label: 'Checkout Date', required: true },
    { name: 'expectedReturnDate', label: 'Expected Return', required: true },
    { name: 'dailyRate', label: 'Daily Rate', type: 'number' },
    { name: 'depositAmount', label: 'Deposit', type: 'number' },
    { name: 'subtotal', label: 'Subtotal', type: 'number' },
    { name: 'totalCharge', label: 'Total Charge', type: 'number' },
    { name: 'checkoutCondition', label: 'Checkout Condition' },
    { name: 'checkoutNotes', label: 'Checkout Notes' },
];

export default function RentalsPage() {
    const [assets, setAssets] = useState<RentalAsset[]>([]);
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [contracts, setContracts] = useState<RentalContract[]>([]);
    const [stats, setStats] = useState<RentalStatsType | null>(null);
    const [detailContract, setDetailContract] = useState<RentalContract | null>(null);
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(false);
    const [tab, setTab] = useState('assets');
    const [search, setSearch] = useState('');

    // New Rental Contract modal
    const [contractModalOpen, setContractModalOpen] = useState(false);
    const [contractForm] = Form.useForm();

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [a, c, s] = await Promise.all([
                inventoryService.getRentalAssets(),
                inventoryService.getRentalContracts(),
                inventoryService.getRentalStats(),
            ]);
            setAssets(a); setContracts(c); setStats(s);
        } catch (e: any) { message.error(e.message); }
        setLoading(false);
    }, []);

    useEffect(() => { load(); }, [load]);

    const handleReturn = async (contractId: string) => {
        try {
            await inventoryService.returnRentalAsset(contractId, 'good');
            message.success('Asset returned successfully');
            load();
        } catch (e: any) { message.error(e.message); }
    };

    const handleCancelContract = async (contractId: string) => {
        try {
            await inventoryService.cancelRentalContract(contractId);
            message.success('Contract cancelled â€” asset released');
            load();
        } catch (e: any) { message.error(e.message); }
    };

    const handleCreateContract = async (values: any) => {
        const input: Record<string, any> = {
            contractCode: values.contractCode,
            assetId: values.assetId,
            assetName: values.assetName,
            customerName: values.customerName,
            customerEmail: values.customerEmail,
            customerPhone: values.customerPhone,
            customerIdNumber: values.customerIdNumber,
            checkoutDate: values.checkoutDate?.format ? values.checkoutDate.format('YYYY-MM-DD') : values.checkoutDate,
            expectedReturnDate: values.expectedReturnDate?.format ? values.expectedReturnDate.format('YYYY-MM-DD') : values.expectedReturnDate,
            dailyRate: values.dailyRate,
            depositAmount: values.depositAmount,
            subtotal: values.subtotal,
            totalCharge: values.totalCharge,
            checkoutCondition: values.checkoutCondition,
            checkoutNotes: values.checkoutNotes,
        };
        await inventoryService.createRentalContract('default', input);
        message.success('Rental contract created');
        setContractModalOpen(false);
        contractForm.resetFields();
        load();
    };

    const handleBatchCreateContract = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createRentalContract('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.contractCode || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        load();
        return { success, failed, errors };
    };

    const onAssetChange = (assetId: string) => {
        const asset = assets.find(a => a.id === assetId);
        if (asset) {
            contractForm.setFieldsValue({
                assetName: asset.assetName,
                dailyRate: asset.dailyRate || 0,
                depositAmount: asset.depositAmount || 0,
            });
            recalcRental();
        }
    };

    const recalcRental = () => {
        const checkout = contractForm.getFieldValue('checkoutDate');
        const ret = contractForm.getFieldValue('expectedReturnDate');
        const rate = contractForm.getFieldValue('dailyRate') || 0;
        if (checkout && ret) {
            const days = Math.max(1, ret.diff(checkout, 'day'));
            const subtotal = days * rate;
            contractForm.setFieldsValue({ subtotal, totalCharge: subtotal + (contractForm.getFieldValue('depositAmount') || 0) });
        }
    };

    const fmt = (v: number) => `Rp ${(v || 0).toLocaleString('id-ID')}`;

    const kpis = [
        { label: 'Total Assets', value: stats?.totalAssets || 0, icon: <CarOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { label: 'Available', value: stats?.available || 0, icon: <CheckCircleOutlined />, color: '#16a34a' },
        { label: 'Rented', value: stats?.rented || 0, icon: <SwapOutlined />, color: '#2563eb' },
        { label: 'Maintenance', value: stats?.maintenance || 0, icon: <ToolOutlined />, color: '#d97706' },
        { label: 'Active Contracts', value: stats?.activeContracts || 0, icon: <ClockCircleOutlined />, color: '#0891b2' },
        { label: 'Total Revenue', value: fmt(stats?.totalRevenue || 0), icon: <DollarOutlined />, color: '#dc2626' },
    ];

    const assetColumns = [
        { title: 'Code', dataIndex: 'assetCode', render: (v: string) => <Tag style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Asset Name', dataIndex: 'assetName', ellipsis: true, render: (v: string) => <strong>{v}</strong> },
        { title: 'Category', dataIndex: 'category', render: (v: string) => <Tag color="purple">{v}</Tag> },
        { title: 'Serial No.', dataIndex: 'serialNumber', render: (v: string) => v ? <Tag style={{ fontFamily: 'monospace', fontSize: 11 }}>{v}</Tag> : 'â€”' },
        { title: 'Condition', dataIndex: 'condition', render: (v: string) => <Tag color={CONDITION_COLORS[v] || 'default'}>{v}</Tag> },
        { title: 'Location', dataIndex: 'currentLocation', ellipsis: true },
        { title: 'Daily Rate', dataIndex: 'dailyRate', render: fmt },
        { title: 'Deposit', dataIndex: 'depositAmount', render: fmt },
        { title: 'Rentals', dataIndex: 'totalRentals', render: (v: number) => <strong>{v}</strong> },
        { title: 'Revenue', dataIndex: 'totalRevenue', render: fmt },
        { title: 'Next Maint.', dataIndex: 'nextMaintenanceDate', render: (v: string) => {
            if (!v) return 'â€”';
            const d = new Date(v);
            const now = new Date();
            const isOverdue = d < now;
            return <span style={{ color: isOverdue ? '#f5222d' : undefined }}>{d.toLocaleDateString('id-ID')}{isOverdue ? ' âš ï¸' : ''}</span>;
        }},
        { title: 'Status', dataIndex: 'status', render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'}>{v}</Tag> },
    ];

    const contractColumns = [
        { title: 'Code', dataIndex: 'contractCode', render: (v: string) => <Tag style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Asset', dataIndex: 'assetName', ellipsis: true },
        { title: 'Customer', dataIndex: 'customerName', render: (v: string) => <strong>{v}</strong> },
        { title: 'Checkout', dataIndex: 'checkoutDate', render: (v: string) => new Date(v).toLocaleDateString('id-ID') },
        { title: 'Expected Return', dataIndex: 'expectedReturnDate', render: (v: string) => new Date(v).toLocaleDateString('id-ID') },
        { title: 'Actual Return', dataIndex: 'actualReturnDate', render: (v: string) => v ? new Date(v).toLocaleDateString('id-ID') : <Tag color="blue">Ongoing</Tag> },
        { title: 'Days', dataIndex: 'rentalDays', render: (v: number) => <strong>{v}</strong> },
        { title: 'Subtotal', dataIndex: 'subtotal', render: fmt },
        { title: 'Late Fee', dataIndex: 'lateFee', render: (v: number) => v > 0 ? <span style={{ color: '#f5222d', fontWeight: 600 }}>{fmt(v)}</span> : 'â€”' },
        { title: 'Damage Fee', dataIndex: 'damageFee', render: (v: number) => v > 0 ? <span style={{ color: '#fa8c16', fontWeight: 600 }}>{fmt(v)}</span> : 'â€”' },
        { title: 'Total', dataIndex: 'totalCharge', render: (v: number) => <strong>{fmt(v)}</strong> },
        { title: 'Status', dataIndex: 'status', render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'}>{v}</Tag> },
        { title: 'Actions', render: (_: any, r: RentalContract) => (
            <Space>
                <Button size="small" icon={<EyeOutlined />} onClick={() => setDetailContract(r)}>Detail</Button>
                {r.status === 'active' && (
                    <>
                        <Button size="small" type="primary" onClick={() => handleReturn(r.id)}>Return</Button>
                        <Button size="small" danger onClick={() => Modal.confirm({
                            title: 'Cancel this rental contract?',
                            content: 'The asset will be released back to available status.',
                            okText: 'Cancel Contract',
                            okButtonProps: { danger: true },
                            onOk: () => handleCancelContract(r.id),
                        })} style={{ fontSize: 11 }}>Cancel</Button>
                    </>
                )}
            </Space>
        )},
    ];

    const filteredAssets = assets.filter(a => !search || a.assetName.toLowerCase().includes(search.toLowerCase()) || a.assetCode.toLowerCase().includes(search.toLowerCase()));
    const filteredContracts = contracts.filter(c => !search || c.customerName.toLowerCase().includes(search.toLowerCase()) || c.contractCode.toLowerCase().includes(search.toLowerCase()));

    const contractSteps = [
        {
            title: "Asset & Contract",
            icon: <CarOutlined />,
            fields: ["contractCode", "assetId"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={10}>
                            <Form.Item name="contractCode" label="Contract Code" rules={[{ required: true }]}>
                                <Input placeholder="RNT-2026-XXX" />
                            </Form.Item>
                        </Col>
                        <Col span={14}>
                            <Form.Item name="assetId" label="Asset" rules={[{ required: true, message: 'Select an asset' }]}>
                                <Select placeholder="Select asset" showSearch
                                    filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                                    onChange={onAssetChange}
                                    options={assets.filter(a => a.status === 'available').map(a => ({
                                        value: a.id, label: `${a.assetCode} â€” ${a.assetName} (${a.category || 'â€”'})`
                                    }))} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="assetName" hidden><Input /></Form.Item>
                </>
            ),
        },
        {
            title: "Customer",
            icon: <UserOutlined />,
            fields: ["customerName", "customerEmail", "customerPhone", "customerIdNumber"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="customerName" label="Customer Name" rules={[{ required: true }]}>
                                <Input placeholder="Full name" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="customerEmail" label="Email">
                                <Input placeholder="email@example.com" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="customerPhone" label="Phone">
                                <Input placeholder="+62..." />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="customerIdNumber" label="ID Number">
                                <Input placeholder="KTP / Passport" />
                            </Form.Item>
                        </Col>
                    </Row>
                </>
            ),
        },
        {
            title: "Pricing & Schedule",
            icon: <DollarOutlined />,
            fields: ["checkoutDate", "expectedReturnDate", "dailyRate", "depositAmount", "subtotal", "totalCharge", "checkoutCondition", "checkoutNotes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="checkoutDate" label="Checkout Date" rules={[{ required: true }]}>
                                <DatePicker style={{ width: '100%' }} onChange={() => recalcRental()} />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="expectedReturnDate" label="Expected Return" rules={[{ required: true }]}>
                                <DatePicker style={{ width: '100%' }} onChange={() => recalcRental()} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={6}>
                            <Form.Item name="dailyRate" label="Daily Rate">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" onChange={() => recalcRental()} />
                            </Form.Item>
                        </Col>
                        <Col span={6}>
                            <Form.Item name="depositAmount" label="Deposit">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" onChange={() => recalcRental()} />
                            </Form.Item>
                        </Col>
                        <Col span={6}>
                            <Form.Item name="subtotal" label="Subtotal">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" disabled />
                            </Form.Item>
                        </Col>
                        <Col span={6}>
                            <Form.Item name="totalCharge" label="Total Charge">
                                <InputNumber min={0} style={{ width: '100%' }} prefix="Rp" disabled />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="checkoutCondition" label="Checkout Condition" initialValue="good">
                                <Select options={[
                                    { value: 'excellent', label: 'Excellent' }, { value: 'good', label: 'Good' },
                                    { value: 'fair', label: 'Fair' }, { value: 'poor', label: 'Poor' },
                                ]} />
                            </Form.Item>
                        </Col>
                        <Col span={16}>
                            <Form.Item name="checkoutNotes" label="Checkout Notes">
                                <Input.TextArea rows={1} placeholder="Condition notes..." />
                            </Form.Item>
                        </Col>
                    </Row>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={["#d97706", "#dc2626", "#f59e0b", "#ff0000", "#ea580c"]}>Rental Management</AuroraText>}
            subTitle={<DecryptedText text="Asset tracking, rental contracts, and condition monitoring" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>

                {/* KPI Cards */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 14, marginBottom: 24 }}>
                    {kpis.map((k, i) => (
                        <motion.div key={i} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}
                            style={{ ...(isDark ? glassDark : glass), padding: '16px 18px', borderTop: `3px solid ${k.color}`, position: 'relative', overflow: 'hidden' }}>
                            <div style={{ position: 'absolute', top: -10, right: -10, width: 60, height: 60, borderRadius: '50%', background: `radial-gradient(circle, ${k.color}18 0%, transparent 70%)`, pointerEvents: 'none' }} />
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6, position: 'relative' }}>
                                <span style={{ color: k.color, fontSize: 14 }}>{k.icon}</span>
                                <span style={{ color: isDark ? 'rgba(255,255,255,0.5)' : 'rgba(0,0,0,0.45)', fontSize: 10, letterSpacing: 0.5, textTransform: 'uppercase' as const }}>{k.label}</span>
                            </div>
                            <div style={{ fontSize: 22, fontWeight: 800, color: k.color, position: 'relative', letterSpacing: -0.5 }}>{typeof k.value === 'number' ? k.value : k.value}</div>
                        </motion.div>
                    ))}
                </div>

                {/* Search + Actions */}
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
                    <Input prefix={<SearchOutlined />} placeholder="Search assets, contracts..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: 320 }} allowClear />
                    <Space>
                        <Button icon={<ReloadOutlined />} onClick={load} loading={loading}>Refresh</Button>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_rentals', title: 'Rental Assets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Category', key: 'category' }, { header: 'Status', key: 'status' }, { header: 'Daily Rate', key: 'dailyRate' }], data: assets })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_rentals', title: 'Rental Assets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Category', key: 'category' }, { header: 'Status', key: 'status' }, { header: 'Daily Rate', key: 'dailyRate' }], data: assets })} /></Tooltip></RbacGuard>
                        <Button type="primary" icon={<PlusOutlined />}
                            onClick={() => { contractForm.resetFields(); setContractModalOpen(true); setTab('contracts'); }}
                            style={{ background: 'linear-gradient(135deg, #d97706, #dc2626)', border: 'none', borderRadius: 8 }}>
                            New Contract
                        </Button>
                    </Space>
                </div>

                <Card size="small" style={{ flex: 1, ...(isDark ? glassDark : glass), borderLeft: '3px solid #d97706' }}>
                    {/* Tabs */}
                    <Tabs activeKey={tab} onChange={setTab} items={[
                        { key: 'assets', label: `ðŸ·ï¸ Assets (${assets.length})`, children: (
                            <Table dataSource={filteredAssets} columns={assetColumns} rowKey="id" size="middle" loading={loading}
                                pagination={{ pageSize: 10 }} scroll={{ x: 1400 }} />
                        )},
                        { key: 'contracts', label: `ðŸ“‹ Contracts (${contracts.length})`, children: (
                            <Table dataSource={filteredContracts} columns={contractColumns} rowKey="id" size="middle" loading={loading}
                                pagination={{ pageSize: 10 }} scroll={{ x: 1500 }} />
                        )},
                    ]} />
                </Card>

                {/* Contract Detail Drawer */}
                <Drawer title={`Contract Detail â€” ${detailContract?.contractCode}`} open={!!detailContract} onClose={() => setDetailContract(null)} width={560}>
                    {detailContract && (
                        <Descriptions column={1} bordered size="small">
                            <Descriptions.Item label="Contract Code"><Tag style={{ fontFamily: 'monospace' }}>{detailContract.contractCode}</Tag></Descriptions.Item>
                            <Descriptions.Item label="Asset">{detailContract.assetName}</Descriptions.Item>
                            <Descriptions.Item label="Customer">{detailContract.customerName}</Descriptions.Item>
                            <Descriptions.Item label="Email">{detailContract.customerEmail || 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Phone">{detailContract.customerPhone || 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="ID Number">{detailContract.customerIdNumber || 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Checkout Date">{new Date(detailContract.checkoutDate).toLocaleDateString('id-ID')}</Descriptions.Item>
                            <Descriptions.Item label="Expected Return">{new Date(detailContract.expectedReturnDate).toLocaleDateString('id-ID')}</Descriptions.Item>
                            <Descriptions.Item label="Actual Return">{detailContract.actualReturnDate ? new Date(detailContract.actualReturnDate).toLocaleDateString('id-ID') : <Tag color="blue">Ongoing</Tag>}</Descriptions.Item>
                            <Descriptions.Item label="Rental Days"><strong>{detailContract.rentalDays}</strong></Descriptions.Item>
                            <Descriptions.Item label="Daily Rate">{fmt(detailContract.dailyRate || 0)}</Descriptions.Item>
                            <Descriptions.Item label="Deposit">{fmt(detailContract.depositAmount || 0)}</Descriptions.Item>
                            <Descriptions.Item label="Deposit Returned">{fmt(detailContract.depositReturned || 0)}</Descriptions.Item>
                            <Descriptions.Item label="Subtotal">{fmt(detailContract.subtotal || 0)}</Descriptions.Item>
                            <Descriptions.Item label="Late Fee">{detailContract.lateFee ? <span style={{ color: '#f5222d' }}>{fmt(detailContract.lateFee)}</span> : 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Damage Fee">{detailContract.damageFee ? <span style={{ color: '#fa8c16' }}>{fmt(detailContract.damageFee)}</span> : 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Total Charge"><strong style={{ fontSize: 16 }}>{fmt(detailContract.totalCharge || 0)}</strong></Descriptions.Item>
                            <Descriptions.Item label="Checkout Condition"><Tag color={CONDITION_COLORS[detailContract.checkoutCondition || ''] || 'default'}>{detailContract.checkoutCondition || 'â€”'}</Tag></Descriptions.Item>
                            <Descriptions.Item label="Return Condition">{detailContract.returnCondition ? <Tag color={CONDITION_COLORS[detailContract.returnCondition] || 'default'}>{detailContract.returnCondition}</Tag> : 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Checkout Notes">{detailContract.checkoutNotes || 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Return Notes">{detailContract.returnNotes || 'â€”'}</Descriptions.Item>
                            <Descriptions.Item label="Status"><Tag color={STATUS_COLORS[detailContract.status || ''] || 'default'}>{detailContract.status}</Tag></Descriptions.Item>
                        </Descriptions>
                    )}
                </Drawer>

                {/* â”€â”€â”€ Rental Contract SteppedFormModal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
                <SteppedFormModal
                    open={contractModalOpen}
                    onCancel={() => { setContractModalOpen(false); contractForm.resetFields(); }}
                    onSubmit={handleCreateContract}
                    form={contractForm}
                    title="New Rental Contract"
                    entityName="rental_contract"
                    steps={contractSteps}
                    fields={CONTRACT_FIELDS}
                    width={680}
                    loading={false}
                    onBatchCreate={handleBatchCreateContract}
                    gradient={["#d97706", "#dc2626"]}
                />
            </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { Button, Card, Col, Form, Input, InputNumber, message, Modal, Row, Select, Space, Table, Tag, Tooltip, Typography , theme } from "antd";
import {
    ContainerOutlined, PlusOutlined, ReloadOutlined, SearchOutlined,
    DownloadOutlined, UploadOutlined, SwapOutlined,
    DeleteOutlined, WarningOutlined, GiftOutlined,
    CheckCircleOutlined, InboxOutlined, FileExcelOutlined, FilePdfOutlined,
    BarChartOutlined, UnorderedListOutlined, AuditOutlined } from "@ant-design/icons";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import {
    inventoryService, StockOperation, StockOperationStatsType
} from "@/lib/inventoryService";
import ItemPicker from "@/components/inventory/ItemPicker";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

const OP_TYPES: Record<string, { label: string; color: string; icon: React.ReactNode }> = {
    receive: { label: 'Receive', color: 'green', icon: <DownloadOutlined /> },
    release: { label: 'Release', color: 'blue', icon: <UploadOutlined /> },
    adjust: { label: 'Adjust', color: 'orange', icon: <SwapOutlined /> },
    write_off: { label: 'Write-off', color: 'red', icon: <WarningOutlined /> },
    donate: { label: 'Donate', color: 'purple', icon: <GiftOutlined /> },
};

const STATUS_COLORS: Record<string, string> = {
    completed: 'green', draft: 'default', cancelled: 'red',
};

const REASONS = [
    { value: 'internal_use', label: 'Internal Use' },
    { value: 'damaged', label: 'Damaged' },
    { value: 'expired', label: 'Expired' },
    { value: 'donation', label: 'Donation' },
    { value: 'sample', label: 'Sample' },
    { value: 'production', label: 'Production' },
    { value: 'return_to_vendor', label: 'Return to Vendor' },
    { value: 'inventory_correction', label: 'Inventory Correction' },
    { value: 'other', label: 'Other' },
];

const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : '-';

const STOCK_OP_FIELDS: FieldDef[] = [
    { name: 'operationType', label: 'Operation Type', required: true },
    { name: 'reason', label: 'Reason' },
    { name: 'itemId', label: 'Item', required: true },
    { name: 'itemName', label: 'Item Name' },
    { name: 'quantity', label: 'Quantity', required: true, type: 'number' },
    { name: 'unitCost', label: 'Unit Cost', type: 'number' },
    { name: 'warehouseId', label: 'Warehouse' },
    { name: 'batchNumber', label: 'Batch #' },
    { name: 'expiryDate', label: 'Expiry Date' },
    { name: 'reference', label: 'Reference' },
    { name: 'approvedBy', label: 'Approved By' },
    { name: 'createdBy', label: 'Created By' },
    { name: 'notes', label: 'Notes' },
];

export default function StockOperationsPage() {
    const router = useRouter();
    const [stats, setStats] = useState<StockOperationStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const { startDate, endDate } = useDateRangeStore();
    const [operations, setOperations] = useState<StockOperation[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");
    const [filterType, setFilterType] = useState<string | undefined>();

    // Modal
    const [modalOpen, setModalOpen] = useState(false);
    const [form] = Form.useForm();

    useEffect(() => { loadAll(); }, []);

    const loadAll = async () => {
        setLoading(true);
        try {
            const [statsData, opsData] = await Promise.all([
                inventoryService.getStockOperationStats(),
                inventoryService.getStockOperations('default', { operationType: filterType }),
            ]);
            setStats(statsData);
            setOperations(opsData);
        } catch (err) {
            console.error(err);
            message.error("Failed to load stock operations");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { loadAll(); }, [filterType]);

    const handleCreate = async (values: any) => {
        await inventoryService.createStockOperation('default', values);
        message.success("Stock operation created â€” stock ledger updated");
        setModalOpen(false);
        form.resetFields();
        loadAll();
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try { await inventoryService.createStockOperation('default', r); success++; }
            catch (e: any) { failed++; errors.push(`${r.operationNumber || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        loadAll();
        return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await inventoryService.deleteStockOperation(id);
            message.success("Operation deleted");
            loadAll();
        } catch { message.error("Failed to delete"); }
    };

    // â”€â”€â”€ KPI Cards â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const kpiCards = [
        { title: 'Total Operations', value: stats?.totalOperations || 0, icon: <ContainerOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { title: 'Receives', value: stats?.receives || 0, icon: <DownloadOutlined />, color: '#10b981' },
        { title: 'Releases', value: stats?.releases || 0, icon: <UploadOutlined />, color: '#3b82f6' },
        { title: 'Adjustments', value: stats?.adjustments || 0, icon: <SwapOutlined />, color: '#f59e0b' },
        { title: 'Write-offs', value: stats?.writeOffs || 0, icon: <WarningOutlined />, color: '#ef4444' },
        { title: 'Donations', value: stats?.donations || 0, icon: <GiftOutlined />, color: themeColor },
    ];

    // â”€â”€â”€ Columns â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const columns = [
        {
            title: 'Op #', dataIndex: 'operationNumber', width: 140,
            render: (v: string) => <Text code className="text-xs">{v}</Text>,
        },
        {
            title: 'Type', dataIndex: 'operationType', width: 120,
            render: (v: string) => {
                const t = OP_TYPES[v] || { label: v, color: 'default', icon: null };
                return <Tag icon={t.icon} color={t.color} className="rounded-full text-xs">{t.label}</Tag>;
            },
        },
        {
            title: 'Item', dataIndex: 'itemName', ellipsis: true,
            render: (v: string) => <Text strong className="text-sm">{v || 'Unknown'}</Text>,
        },
        {
            title: 'Quantity', dataIndex: 'quantity', width: 110,
            render: (v: number, r: StockOperation) => {
                const isIn = r.operationType === 'receive';
                return (
                    <Text strong style={{ color: isIn ? '#10b981' : '#ef4444' }}>
                        {isIn ? '+' : '-'}{Math.abs(v)}
                    </Text>
                );
            },
        },
        {
            title: 'Unit Cost', dataIndex: 'unitCost', width: 130,
            render: (v: number) => fmtCurrency(v),
        },
        {
            title: 'Reason', dataIndex: 'reason', width: 140, ellipsis: true,
            render: (v: string) => v ? <Tag className="rounded-full text-xs">{v.replace(/_/g, ' ')}</Tag> : 'â€”',
        },
        {
            title: 'Batch', dataIndex: 'batchNumber', width: 110,
            render: (v: string) => v || 'â€”',
        },
        {
            title: 'Status', dataIndex: 'status', width: 110,
            render: (v: string) => <Tag color={STATUS_COLORS[v] || 'default'} className="rounded-full text-xs">{v}</Tag>,
        },
        {
            title: 'Date', dataIndex: 'createdAt', width: 110,
            render: (v: string) => v ? new Date(v).toLocaleDateString() : 'â€”',
        },
        {
            title: '', key: 'actions', width: 70,
            render: (_: any, r: StockOperation) => (
                <Button size="small" danger icon={<DeleteOutlined />}
                    onClick={() => Modal.confirm({
                        title: 'Delete this operation?',
                        content: 'This will NOT reverse the stock movement.',
                        onOk: () => handleDelete(r.id),
                    })} />
            ),
        },
    ];

    const filteredOps = operations.filter(o =>
        !searchTerm || (o.itemName || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        o.operationNumber.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const opSteps = [
        {
            title: "Operation",
            fields: ["operationType", "reason", "itemId"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="operationType" label="Operation Type" rules={[{ required: true }]}>
                                <Select placeholder="Select type"
                                    options={Object.entries(OP_TYPES).map(([k, v]) => ({
                                        value: k, label: <span>{v.icon} {v.label}</span>,
                                    }))} />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="reason" label="Reason">
                                <Select placeholder="Select reason" options={REASONS} allowClear />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="itemId" label="Item" rules={[{ required: true, message: 'Select an item' }]}>
                        <ItemPicker
                            placeholder="Search items by name or SKU..."
                            onItemSelect={(item) => {
                                if (item) {
                                    form.setFieldsValue({
                                        itemName: item.name,
                                        unitCost: item.costPrice,
                                    });
                                } else {
                                    form.setFieldsValue({ itemName: undefined, unitCost: undefined });
                                }
                            }}
                        />
                    </Form.Item>
                    <Form.Item name="itemName" hidden><input /></Form.Item>
                </>
            ),
        },
        {
            title: "Quantity & Cost",
            fields: ["quantity", "unitCost", "warehouseId", "batchNumber", "expiryDate", "reference"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="quantity" label="Quantity" rules={[{ required: true }]}>
                                <InputNumber min={0.001} style={{ width: '100%' }} placeholder="0" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="unitCost" label="Unit Cost">
                                <InputNumber min={0} style={{ width: '100%' }} placeholder="0" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="warehouseId" label="Warehouse" initialValue="default">
                                <Input placeholder="Warehouse ID" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="batchNumber" label="Batch #">
                                <Input placeholder="Batch number" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="expiryDate" label="Expiry Date">
                                <Input type="date" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="reference" label="Reference">
                                <Input placeholder="External ref" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="approvedBy" label="Approved By">
                                <Input placeholder="Approver name" />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="createdBy" label="Created By">
                                <Input placeholder="Operator name" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="notes" label="Notes">
                        <Input.TextArea rows={2} placeholder="Operation notes" />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={["#10b981", "#059669", "#6366f1", "#00ffff", "#ff00ff"]}>Stock Operations</AuroraText>}
            subTitle={
                <DecryptedText
                    text="Manual inbound, outbound, adjustments, write-offs, and donations"
                    animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential
                />
            }
            extra={[
                <Tooltip key="stock" title="View stock levels"><Button icon={<BarChartOutlined />} onClick={() => router.push('/admin/inventory/stock')}>Stock</Button></Tooltip>,
                <Tooltip key="items" title="Manage items"><Button icon={<UnorderedListOutlined />} onClick={() => router.push('/admin/inventory/items')}>Items</Button></Tooltip>,
                <Tooltip key="opname" title="Stock opname sessions"><Button icon={<AuditOutlined />} onClick={() => router.push('/admin/inventory/stock-opname')}>Opname</Button></Tooltip>,
            ]}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                {/* KPI Cards */}
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...(isDark ? glassDark : glass), borderTop: `3px solid ${s.color}`, position: 'relative', overflow: 'hidden',
                                }}>
                                    <div style={{ position: 'absolute', top: -10, right: -10, width: 60, height: 60, borderRadius: '50%', background: `radial-gradient(circle, ${s.color}18 0%, transparent 70%)`, pointerEvents: 'none' }} />
                                    <div className="flex items-center gap-3" style={{ position: 'relative' }}>
                                        <div className="w-11 h-11 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18, border: `1px solid ${s.color}20` }}>
                                            {s.icon}
                                        </div>
                                        <div>
                                            <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.5)' : 'rgba(0,0,0,0.45)', letterSpacing: 0.5, textTransform: 'uppercase' as const }} className="block">{s.title}</Text>
                                            <Text strong style={{ fontSize: 20, fontWeight: 700, color: s.color }}>{s.value.toLocaleString()}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Main Table Card */}
                <Card size="small" style={{
                    flex: 1, ...(isDark ? glassDark : glass), borderLeft: '3px solid #10b981',
                }}>
                    <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-3">
                            <Space>
                                <span style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 24, height: 24, borderRadius: 7, background: 'linear-gradient(135deg, #10b981, #059669)' }}>
                                    <ContainerOutlined style={{ color: '#fff', fontSize: 12 }} />
                                </span>
                                <span style={{ fontWeight: 600, color: isDark ? 'rgba(255,255,255,0.9)' : 'rgba(0,0,0,0.85)' }}>Operations ({filteredOps.length})</span>
                            </Space>
                            <Input prefix={<SearchOutlined className="text-gray-400" />}
                                placeholder="Search..." value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)} allowClear
                                style={{ maxWidth: 220, borderRadius: 8 }} size="small" />
                            <Select
                                value={filterType} onChange={v => setFilterType(v)} allowClear
                                placeholder="All Types" style={{ width: 140 }} size="small"
                                options={Object.entries(OP_TYPES).map(([k, v]) => ({ value: k, label: v.label }))}
                            />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={loadAll} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_stock-operations', title: 'Stock Operations', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'operationNumber' }, { header: 'Type', key: 'operationType' }, { header: 'Status', key: 'status' }, { header: 'From', key: 'sourceWarehouseName' }, { header: 'To', key: 'destinationWarehouseName' }], data: operations })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_stock-operations', title: 'Stock Operations', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'operationNumber' }, { header: 'Type', key: 'operationType' }, { header: 'Status', key: 'status' }, { header: 'From', key: 'sourceWarehouseName' }, { header: 'To', key: 'destinationWarehouseName' }], data: operations })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />}
                                onClick={() => { form.resetFields(); setModalOpen(true); }}
                                style={{ background: 'linear-gradient(135deg, #10b981, #059669)', borderRadius: 8, border: 'none' }}>
                                New Operation
                            </Button>
                        </Space>
                    </div>

                    <Table
                        dataSource={filteredOps} columns={columns}
                        rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 15, showSizeChanger: false }}
                        scroll={{ x: 1200 }}
                    />
                </Card>
            </div>

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); form.resetFields(); }}
                onSubmit={handleCreate}
                form={form}
                title="New Stock Operation"
                entityName="stock_operation"
                steps={opSteps}
                fields={STOCK_OP_FIELDS}
                loading={false}
                onBatchCreate={handleBatchCreate}
                gradient={["#10b981", "#059669"]}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import {
    Table, Button, Space, Tag, Card, Typography, message,
    Row, Col, Modal, Form, Input, InputNumber, Select, Progress, Tooltip
, theme } from "antd";
import {
    AuditOutlined, PlusOutlined, ReloadOutlined, SearchOutlined,
    FileTextOutlined, CheckCircleOutlined, ClockCircleOutlined,
    ExclamationCircleOutlined, DeleteOutlined, EditOutlined,
    EyeOutlined, WarningOutlined, ArrowRightOutlined,
    CalendarOutlined, TeamOutlined, EnvironmentOutlined,
    FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import {
    inventoryService, OpnameSession, OpnameLine, OpnameStatsType, InvWarehouse
} from "@/lib/inventoryService";
import ItemPicker from "@/components/inventory/ItemPicker";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

const SESSION_STATUSES: Record<string, { color: string; icon: React.ReactNode }> = {
    draft: { color: 'default', icon: <FileTextOutlined /> },
    counting: { color: 'processing', icon: <ClockCircleOutlined /> },
    review: { color: 'orange', icon: <EyeOutlined /> },
    completed: { color: 'green', icon: <CheckCircleOutlined /> },
    cancelled: { color: 'red', icon: <ExclamationCircleOutlined /> },
};

const LINE_STATUSES: Record<string, { color: string }> = {
    pending: { color: 'default' },
    counted: { color: 'blue' },
    verified: { color: 'green' },
    discrepancy: { color: 'red' },
};

const fmtCurrency = (v?: number) => v ? `Rp ${v.toLocaleString()}` : '-';

const SESSION_FIELDS: FieldDef[] = [
    { name: 'sessionCode', label: 'Session Code', required: true },
    { name: 'title', label: 'Title', required: true },
    { name: 'warehouseId', label: 'Warehouse', required: true },
    { name: 'countedBy', label: 'Counted By' },
    { name: 'scheduledDate', label: 'Scheduled Date' },
    { name: 'notes', label: 'Notes' },
];

export default function StockOpnamePage() {
    const [stats, setStats] = useState<OpnameStatsType | null>(null);
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const { startDate, endDate } = useDateRangeStore();
    const [sessions, setSessions] = useState<OpnameSession[]>([]);
    const [warehouses, setWarehouses] = useState<InvWarehouse[]>([]);
    const [opnameLines, setOpnameLines] = useState<Record<string, OpnameLine[]>>({});
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");
    const [expandedSessionId, setExpandedSessionId] = useState<string | null>(null);

    // Modals
    const [sessionModalOpen, setSessionModalOpen] = useState(false);
    const [sessionForm] = Form.useForm();

    const [lineModalOpen, setLineModalOpen] = useState(false);
    const [lineForm] = Form.useForm();
    const [lineSessionId, setLineSessionId] = useState<string | null>(null);

    useEffect(() => { loadAll(); }, []);

    const loadAll = async () => {
        setLoading(true);
        try {
            const [statsData, sessionsData, whData] = await Promise.all([
                inventoryService.getOpnameStats(),
                inventoryService.getOpnameSessions(),
                inventoryService.getWarehouses(),
            ]);
            setStats(statsData);
            setSessions(sessionsData);
            setWarehouses(whData);
        } catch (err) {
            console.error(err);
            message.error("Failed to load stock opname data");
        } finally {
            setLoading(false);
        }
    };

    const loadLines = async (sessionId: string) => {
        try {
            const lines = await inventoryService.getOpnameLines(sessionId);
            setOpnameLines(prev => ({ ...prev, [sessionId]: lines }));
        } catch { console.error("Failed to load lines"); }
    };

    // â”€â”€â”€ Session CRUD â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const handleCreateSession = async (values: any) => {
        const wh = warehouses.find(w => w.id === values.warehouseId);
        const input = { ...values, warehouseName: wh?.name || '' };
        await inventoryService.createOpnameSession('default', input);
        message.success("Session created");
        setSessionModalOpen(false); sessionForm.resetFields(); loadAll();
    };

    const handleBatchCreateSession = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try {
                const wh = warehouses.find(w => w.id === r.warehouseId);
                await inventoryService.createOpnameSession('default', { ...r, warehouseName: wh?.name || '' });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.sessionCode || 'Unknown'}: ${e.message || 'Failed'}`); }
        }
        loadAll();
        return { success, failed, errors };
    };

    const handleStatusChange = async (id: string, newStatus: string) => {
        try {
            await inventoryService.updateOpnameSessionStatus(id, newStatus);
            message.success(`Status â†’ ${newStatus}`);
            loadAll();
        } catch { message.error("Failed to update status"); }
    };

    const handleDeleteSession = async (id: string) => {
        try {
            await inventoryService.deleteOpnameSession(id);
            message.success("Session deleted"); loadAll();
        } catch { message.error("Failed to delete"); }
    };

    // â”€â”€â”€ Line CRUD â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const handleAddLine = async () => {
        try {
            const values = await lineForm.validateFields();
            await inventoryService.addOpnameLine(lineSessionId!, values);
            message.success("Item added");
            setLineModalOpen(false); lineForm.resetFields();
            loadLines(lineSessionId!);
        } catch { message.error("Failed to add item"); }
    };

    // â”€â”€â”€ KPI Cards â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const kpiCards = [
        { title: 'Total Sessions', value: stats?.totalSessions || 0, icon: <AuditOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { title: 'Draft', value: stats?.draft || 0, icon: <FileTextOutlined />, color: '#94a3b8' },
        { title: 'Counting', value: stats?.counting || 0, icon: <ClockCircleOutlined />, color: '#3b82f6' },
        { title: 'In Review', value: stats?.review || 0, icon: <EyeOutlined />, color: '#f59e0b' },
        { title: 'Completed', value: stats?.completed || 0, icon: <CheckCircleOutlined />, color: '#10b981' },
        { title: 'Total Variance', value: fmtCurrency(stats?.totalVariance), icon: <WarningOutlined />, color: stats?.totalVariance && stats.totalVariance < 0 ? '#ef4444' : '#10b981' },
    ];

    // â”€â”€â”€ Session Columns â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const sessionColumns = [
        { title: 'Code', dataIndex: 'sessionCode', width: 140, render: (v: string) => <Text code className="text-xs">{v}</Text> },
        { title: 'Title', dataIndex: 'title', ellipsis: true, render: (v: string) => <Text strong className="text-sm">{v}</Text> },
        { title: 'Warehouse', dataIndex: 'warehouseName', width: 180, ellipsis: true },
        {
            title: 'Progress', key: 'progress', width: 140,
            render: (_: any, r: OpnameSession) => {
                const pct = r.totalItems ? Math.round(((r.itemsCounted || 0) / r.totalItems) * 100) : 0;
                return (
                    <div>
                        <Text className="text-xs">{r.itemsCounted || 0}/{r.totalItems || 0} items</Text>
                        <Progress percent={pct} size="small" strokeColor={pct >= 100 ? '#10b981' : '#6366f1'}
                            showInfo={false} className="!mb-0" />
                    </div>
                );
            },
        },
        { title: 'Counted By', dataIndex: 'countedBy', width: 130 },
        {
            title: 'Scheduled', dataIndex: 'scheduledDate', width: 110,
            render: (v: string) => v ? new Date(v).toLocaleDateString() : 'â€”',
        },
        {
            title: 'Variance', key: 'variance', width: 130,
            render: (_: any, r: OpnameSession) => {
                const v = r.totalVarianceValue || 0;
                if (v === 0) return <Text className="text-xs">â€”</Text>;
                return <Text strong className="text-sm" style={{ color: v < 0 ? '#ef4444' : '#10b981' }}>{fmtCurrency(v)}</Text>;
            },
        },
        {
            title: 'Status', dataIndex: 'status', width: 120,
            render: (v: string) => {
                const s = SESSION_STATUSES[v] || { color: 'default', icon: null };
                return <Tag icon={s.icon} color={s.color} className="rounded-full text-xs">{v}</Tag>;
            },
        },
        {
            title: '', key: 'actions', width: 160,
            render: (_: any, r: OpnameSession) => {
                const transitions: Record<string, { label: string; color: string; next: string }> = {
                    draft: { label: 'Start Count', color: '#3b82f6', next: 'counting' },
                    counting: { label: 'Review', color: '#f59e0b', next: 'review' },
                    review: { label: 'Complete', color: '#10b981', next: 'completed' },
                };
                const action = transitions[r.status || ''];
                return (
                    <Space size="small">
                        {action && (
                            <Button size="small" type="primary"
                                onClick={() => handleStatusChange(r.id, action.next)}
                                style={{ background: action.color, border: 'none', fontSize: 11 }}>
                                {action.label}
                            </Button>
                        )}
                        <Button size="small" danger icon={<DeleteOutlined />}
                            onClick={() => Modal.confirm({ title: 'Delete session?', onOk: () => handleDeleteSession(r.id) })} />
                    </Space>
                );
            },
        },
    ];

    // â”€â”€â”€ Line Columns â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    const lineColumns = [
        { title: '#', dataIndex: 'sortOrder', width: 40 },
        { title: 'Item', dataIndex: 'itemName', render: (v: string) => <Text strong className="text-sm">{v}</Text> },
        { title: 'SKU', dataIndex: 'itemSku', width: 130, render: (v: string) => v ? <Text code className="text-xs">{v}</Text> : '-' },
        { title: 'Zone / Bin', key: 'location', width: 170, render: (_: any, r: OpnameLine) => `${r.zoneName || 'â€”'} / ${r.binCode || 'â€”'}` },
        {
            title: 'System Qty', dataIndex: 'systemQty', width: 100,
            render: (v: number, r: OpnameLine) => `${v} ${r.uom}`,
        },
        {
            title: 'Actual Qty', dataIndex: 'actualQty', width: 100,
            render: (v: number | null, r: OpnameLine) => v !== null && v !== undefined ? `${v} ${r.uom}` :
                <Tag color="default" className="text-xs">Pending</Tag>,
        },
        {
            title: 'Variance', key: 'variance', width: 100,
            render: (_: any, r: OpnameLine) => {
                if (r.varianceQty === null || r.varianceQty === undefined || r.actualQty === null || r.actualQty === undefined) return 'â€”';
                const color = r.varianceQty < 0 ? '#ef4444' : r.varianceQty > 0 ? '#f59e0b' : '#10b981';
                return <Text strong style={{ color }}>{r.varianceQty > 0 ? '+' : ''}{r.varianceQty} {r.uom}</Text>;
            },
        },
        {
            title: 'Value Impact', dataIndex: 'varianceValue', width: 120,
            render: (v: number | null) => {
                if (v === null || v === undefined) return 'â€”';
                const color = v < 0 ? '#ef4444' : v > 0 ? '#f59e0b' : '#10b981';
                return <Text strong style={{ color, fontSize: 12 }}>{fmtCurrency(v)}</Text>;
            },
        },
        {
            title: 'Status', dataIndex: 'status', width: 100,
            render: (v: string) => <Tag color={LINE_STATUSES[v]?.color || 'default'} className="rounded-full text-xs">{v}</Tag>,
        },
    ];

    const filteredSessions = sessions.filter(s =>
        !searchTerm || s.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        s.sessionCode.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const sessionSteps = [
        {
            title: "Session Info",
            icon: <AuditOutlined />,
            fields: ["sessionCode", "title", "warehouseId"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={10}>
                            <Form.Item name="sessionCode" label="Session Code" rules={[{ required: true }]}>
                                <Input placeholder="OPN-2026-XXX" />
                            </Form.Item>
                        </Col>
                        <Col span={14}>
                            <Form.Item name="title" label="Title" rules={[{ required: true }]}>
                                <Input placeholder="Session title" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="warehouseId" label="Warehouse" rules={[{ required: true }]}>
                        <Select placeholder="Select warehouse"
                            options={warehouses.map(w => ({ value: w.id, label: `${w.code} â€” ${w.name}` }))} />
                    </Form.Item>
                </>
            ),
        },
        {
            title: "Schedule & Notes",
            icon: <CalendarOutlined />,
            fields: ["countedBy", "scheduledDate", "notes"],
            content: (
                <>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="countedBy" label="Counted By">
                                <Input placeholder="Person name" />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="scheduledDate" label="Scheduled Date">
                                <Input type="date" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="notes" label="Notes">
                        <Input.TextArea rows={2} placeholder="Session notes" />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Stock Opname</AuroraText>}
            subTitle={
                <DecryptedText
                    text="Physical stock counting, auditing, and variance tracking"
                    animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential
                />
            }
            extra={[
                <Tooltip key="3d" title="View Warehouse in 3D Map"><Button icon={<EnvironmentOutlined />} onClick={() => {
                    const activeSession = expandedSessionId ? sessions.find(s => s.id === expandedSessionId) : sessions[0];
                    const whId = activeSession?.warehouseId;
                    router.push(`/admin/inventory/warehouse-map${whId ? `?warehouse=${whId}` : ''}`);
                }}>3D Map</Button></Tooltip>,
                <Tooltip key="locator" title="Find items in bins"><Button icon={<SearchOutlined />} onClick={() => router.push('/admin/inventory/item-locator')}>Item Locator</Button></Tooltip>,
            ]}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                {/* KPI Cards */}
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...(isDark ? glassDark : glass), borderTop: `3px solid ${s.color}`, position: 'relative', overflow: 'hidden',
                                }}>
                                    <div style={{ position: 'absolute', top: -10, right: -10, width: 60, height: 60, borderRadius: '50%', background: `radial-gradient(circle, ${s.color}18 0%, transparent 70%)`, pointerEvents: 'none' }} />
                                    <div className="flex items-center gap-3" style={{ position: 'relative' }}>
                                        <div className="w-11 h-11 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18, border: `1px solid ${s.color}20` }}>
                                            {s.icon}
                                        </div>
                                        <div>
                                            <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.5)' : 'rgba(0,0,0,0.45)', letterSpacing: 0.5, textTransform: 'uppercase' as const }} className="block">{s.title}</Text>
                                            <Text strong style={{ fontSize: 20, fontWeight: 700, color: s.color }}>{typeof s.value === 'number' ? s.value.toLocaleString() : s.value}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Main Table Card */}
                <Card size="small" style={{
                    flex: 1, ...(isDark ? glassDark : glass), borderLeft: `3px solid var(--theme-color, #7c3aed)`,
                }}>
                    <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-3">
                            <Space>
                                <span style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 24, height: 24, borderRadius: 7, background: 'linear-gradient(135deg, var(--theme-color, #7c3aed), #6366f1)' }}>
                                    <AuditOutlined style={{ color: '#fff', fontSize: 12 }} />
                                </span>
                                <span style={{ fontWeight: 600, color: isDark ? 'rgba(255,255,255,0.9)' : 'rgba(0,0,0,0.85)' }}>Counting Sessions ({sessions.length})</span>
                            </Space>
                            <Input prefix={<SearchOutlined className="text-gray-400" />}
                                placeholder="Search sessions..." value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)} allowClear
                                style={{ maxWidth: 240, borderRadius: 8 }} size="small" />
                        </div>
                        <Space>
                            <Tooltip title="Reload"><Button icon={<ReloadOutlined />} onClick={loadAll} /></Tooltip>
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_stock_opname', title: 'Stock Opname', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'sessionNumber' }, { header: 'Warehouse', key: 'warehouseName' }, { header: 'Status', key: 'status' }], data: sessions })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_stock_opname', title: 'Stock Opname', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'sessionNumber' }, { header: 'Warehouse', key: 'warehouseName' }, { header: 'Status', key: 'status' }], data: sessions })} /></Tooltip></RbacGuard>
                            <Button type="primary" icon={<PlusOutlined />}
                                onClick={() => { sessionForm.resetFields(); setSessionModalOpen(true); }}
                                style={{ background: 'linear-gradient(135deg, var(--theme-color, #7c3aed), var(--theme-secondary, #6366f1))', borderRadius: 8, border: 'none' }}>
                                New Session
                            </Button>
                        </Space>
                    </div>

                    <Table
                        dataSource={filteredSessions} columns={sessionColumns}
                        rowKey="id" loading={loading} size="small"
                        pagination={{ pageSize: 10, showSizeChanger: false }}
                        scroll={{ x: 1200 }}
                        expandable={{
                            expandedRowKeys: expandedSessionId ? [expandedSessionId] : [],
                            onExpand: (expanded, record) => {
                                setExpandedSessionId(expanded ? record.id : null);
                                if (expanded && !opnameLines[record.id]) loadLines(record.id);
                            },
                            expandedRowRender: (record) => (
                                <div className="p-2">
                                    <div className="flex items-center justify-between mb-2">
                                        <Text strong style={{
                                            background: `linear-gradient(to right, ${themeColor}, ${themeColor}dd)`,
                                            WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
                                        }}>Count Items â€” {record.title}</Text>
                                        <Button size="small" icon={<PlusOutlined />}
                                            onClick={() => { setLineSessionId(record.id); lineForm.resetFields(); setLineModalOpen(true); }}
                                            disabled={record.status === 'completed' || record.status === 'cancelled'}
                                            style={{ borderColor: 'var(--theme-color, #7c3aed)', color: 'var(--theme-color, #7c3aed)' }}>
                                            Add Item
                                        </Button>
                                    </div>
                                    <Table dataSource={opnameLines[record.id] || []} columns={lineColumns}
                                        rowKey="id" size="small" pagination={false}
                                        rowClassName={(r) => {
                                            if (r.varianceQty && r.varianceQty !== 0) return 'bg-red-50/50';
                                            return '';
                                        }}
                                    />
                                </div>
                            ),
                        }}
                    />
                </Card>
            </div>

            {/* â”€â”€â”€ Session SteppedFormModal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <SteppedFormModal
                open={sessionModalOpen}
                onCancel={() => { setSessionModalOpen(false); sessionForm.resetFields(); }}
                onSubmit={handleCreateSession}
                form={sessionForm}
                title="New Counting Session"
                entityName="opname_session"
                steps={sessionSteps}
                fields={SESSION_FIELDS}
                width={580}
                loading={false}
                onBatchCreate={handleBatchCreateSession}
                gradient={["var(--theme-color, #7c3aed)", "#6366f1"]}
            />

            {/* â”€â”€â”€ Add Line Item Modal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <Modal title="Add Count Item" open={lineModalOpen}
                onCancel={() => setLineModalOpen(false)} onOk={handleAddLine} okText="Add">
                <Form form={lineForm} layout="vertical">
                    <Row gutter={16}>
                        <Col span={24}>
                            <Form.Item name="itemId" label="Item" rules={[{ required: true, message: 'Select an item' }]}>
                                <ItemPicker
                                    placeholder="Search items by name or SKU..."
                                    onItemSelect={(item) => {
                                        if (item) {
                                            lineForm.setFieldsValue({
                                                itemName: item.name,
                                                itemSku: item.sku,
                                                unitCost: item.costPrice,
                                                uom: item.uom || 'pcs',
                                            });
                                        } else {
                                            lineForm.setFieldsValue({ itemName: undefined, itemSku: undefined, unitCost: undefined, uom: 'pcs' });
                                        }
                                    }}
                                />
                            </Form.Item>
                            <Form.Item name="itemName" hidden><input /></Form.Item>
                            <Form.Item name="itemSku" hidden><input /></Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="zoneName" label="Zone">
                                <Input placeholder="Zone" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="binCode" label="Bin">
                                <Input placeholder="Bin code" />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="uom" label="UOM" initialValue="pcs">
                                <Select options={[
                                    { value: 'pcs', label: 'pcs' }, { value: 'kg', label: 'kg' },
                                    { value: 'ltr', label: 'ltr' }, { value: 'sheet', label: 'sheet' },
                                ]} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item name="systemQty" label="System Qty" rules={[{ required: true }]}>
                                <InputNumber min={0} style={{ width: '100%' }} />
                            </Form.Item>
                        </Col>
                        <Col span={8}>
                            <Form.Item name="unitCost" label="Unit Cost">
                                <InputNumber min={0} style={{ width: '100%' }} />
                            </Form.Item>
                        </Col>
                    </Row>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { Badge, Button, Card, Col, Descriptions, Divider, Empty, Form, Input, InputNumber, message, Row, Select, Space, Spin, Statistic, Table, Tag, Tooltip, Typography , theme } from "antd";
import {
    ArrowUpOutlined, ArrowDownOutlined, SwapOutlined,
    WarningOutlined, ReloadOutlined, PlusOutlined,
    SearchOutlined, ThunderboltOutlined, BarChartOutlined,
    RobotOutlined, DashboardOutlined, CheckCircleOutlined,
    ClockCircleOutlined, ExclamationCircleOutlined,
    FileTextOutlined, UnorderedListOutlined, FileExcelOutlined, FilePdfOutlined, EnvironmentOutlined, AimOutlined } from "@ant-design/icons";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { AuroraText } from "@/components/magicui/aurora-text";
import { TooltipWrapper as AnimatedTooltip } from "@/components/mvpblocks/AnimatedTooltip";
import {
    inventoryService, InvItem, StockLedgerEntry, StockMovement,
    InvStockStats
} from "@/lib/inventoryService";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Title, Text, Paragraph } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

const MOVEMENT_FIELDS: FieldDef[] = [
    { name: 'itemId', label: 'Item ID', required: true },
    { name: 'movementType', label: 'Movement Type', required: true },
    { name: 'quantity', label: 'Quantity', required: true, type: 'number' },
    { name: 'unitCost', label: 'Unit Cost', type: 'number' },
    { name: 'reference', label: 'Reference' },
    { name: 'batchNumber', label: 'Batch Number' },
    { name: 'serialNumber', label: 'Serial Number' },
    { name: 'notes', label: 'Notes' },
];

const MOVEMENT_COLORS: Record<string, string> = {
    IN: 'green', OUT: 'red', TRANSFER: 'blue',
    ADJUST_IN: 'cyan', ADJUST_OUT: 'orange',
    RETURN_IN: 'lime', PRODUCTION: 'purple', CONSUMPTION: 'volcano',
};

const MOVEMENT_ICONS: Record<string, React.ReactNode> = {
    IN: <ArrowDownOutlined />, OUT: <ArrowUpOutlined />,
    TRANSFER: <SwapOutlined />, ADJUST_IN: <ArrowDownOutlined />,
    ADJUST_OUT: <ArrowUpOutlined />, RETURN_IN: <ArrowDownOutlined />,
    PRODUCTION: <CheckCircleOutlined />, CONSUMPTION: <ExclamationCircleOutlined />,
};

export default function StockDashboardPage() {
    const [stats, setStats] = useState<InvStockStats | null>(null);
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const { startDate, endDate } = useDateRangeStore();
    const [ledger, setLedger] = useState<StockLedgerEntry[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [items, setItems] = useState<InvItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");

    // Movement modal
    const [movementModalOpen, setMovementModalOpen] = useState(false);
    const [movementForm] = Form.useForm();

    // AI Anomaly
    const [anomalyLoading, setAnomalyLoading] = useState(false);
    const [anomalyResult, setAnomalyResult] = useState<any>(null);

    useEffect(() => { loadAll(); }, []);

    const loadAll = async () => {
        setLoading(true);
        try {
            const [statsData, ledgerData, movementsData, itemsData] = await Promise.all([
                inventoryService.getStockStats(),
                inventoryService.getStockLedger(),
                inventoryService.getStockMovements('default', { limit: 50 }),
                inventoryService.getItems(),
            ]);
            setStats(statsData);
            setLedger(ledgerData);
            setMovements(movementsData);
            setItems(itemsData);
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const itemMap = useMemo(() => new Map(items.map(i => [i.id, i])), [items]);

    const handleAddMovement = async (values: any) => {
        await inventoryService.createStockMovement('default', values);
        message.success("Stock movement recorded");
        setMovementModalOpen(false);
        movementForm.resetFields();
        loadAll();
    };

    const handleBatchCreateMovement = async (records: any[]) => {
        let success = 0, failed = 0;
        const errors: string[] = [];
        for (const r of records) {
            try {
                await inventoryService.createStockMovement('default', r);
                success++;
            } catch (e: any) {
                failed++;
                errors.push(`${r.reference || 'Unknown'}: ${e.message || 'Failed'}`);
            }
        }
        loadAll();
        return { success, failed, errors };
    };

    const handleAnomalyDetection = async () => {
        setAnomalyLoading(true);
        try {
            const result = await inventoryService.aiDetectAnomalies();
            setAnomalyResult(result);
            if (result.anomalies?.length === 0) {
                message.success("No anomalies detected!");
            } else {
                message.warning(`${result.anomalies?.length || 0} anomalies found`);
            }
        } catch { message.error("AI analysis failed"); }
        finally { setAnomalyLoading(false); }
    };

    // Ledger columns (enriched with item names)
    const ledgerColumns = [
        {
            title: 'Item',
            key: 'item',
            render: (_: any, r: StockLedgerEntry) => {
                const item = itemMap.get(r.itemId);
                return (
                    <div>
                        <Text strong className="text-sm">{item?.name || r.itemId.slice(0, 8)}</Text>
                        <br />
                        <Text type="secondary" className="text-xs">{item?.sku || ''}</Text>
                    </div>
                );
            },
        },
        {
            title: 'Warehouse',
            dataIndex: 'warehouseId',
            width: 120,
            render: (v: string) => <Tag className="rounded-full text-xs">{v || 'Default'}</Tag>,
        },
        {
            title: 'On Hand',
            dataIndex: 'onHand',
            width: 100,
            sorter: (a: StockLedgerEntry, b: StockLedgerEntry) => a.onHand - b.onHand,
            render: (v: number) => <Text strong className="text-sm">{v.toLocaleString()}</Text>,
        },
        {
            title: 'Reserved',
            dataIndex: 'reserved',
            width: 100,
            render: (v: number) => <Text className="text-sm text-orange-500">{v.toLocaleString()}</Text>,
        },
        {
            title: 'Available',
            dataIndex: 'available',
            width: 100,
            sorter: (a: StockLedgerEntry, b: StockLedgerEntry) => a.available - b.available,
            render: (v: number) => {
                const color = v <= 0 ? 'text-red-500' : v < 10 ? 'text-orange-500' : 'text-green-600';
                return <Text strong className={`text-sm ${color}`}>{v.toLocaleString()}</Text>;
            },
        },
        {
            title: 'Status',
            key: 'status',
            width: 90,
            render: (_: any, r: StockLedgerEntry) => {
                const item = itemMap.get(r.itemId);
                const reorder = item?.reorderPoint || 0;
                if (r.onHand <= 0) return <Badge status="error" text={<Text className="text-xs">Out</Text>} />;
                if (reorder > 0 && r.onHand <= reorder) return <Badge status="warning" text={<Text className="text-xs">Low</Text>} />;
                return <Badge status="success" text={<Text className="text-xs">OK</Text>} />;
            },
        },
        {
            title: '',
            key: 'actions',
            width: 60,
            render: (_: any, r: StockLedgerEntry) => {
                const item = itemMap.get(r.itemId);
                return (
                    <Tooltip title="Locate in Warehouse">
                        <Button size="small" type="link" icon={<AimOutlined />}
                            onClick={() => router.push(`/admin/inventory/item-locator?bin=${encodeURIComponent(item?.sku || item?.name || '')}`)}
                            style={{ color: themeColor }} />
                    </Tooltip>
                );
            },
        },
    ];

    const movementColumns = [
        {
            title: 'Time',
            dataIndex: 'createdAt',
            width: 150,
            render: (v: string) => <Text className="text-xs">{new Date(v).toLocaleString()}</Text>,
        },
        {
            title: 'Item',
            key: 'item',
            render: (_: any, r: StockMovement) => {
                const item = itemMap.get(r.itemId);
                return <Text className="text-sm">{item?.name || r.itemId.slice(0, 8)}</Text>;
            },
        },
        {
            title: 'Type',
            dataIndex: 'movementType',
            width: 120,
            render: (v: string) => (
                <Tag icon={MOVEMENT_ICONS[v]} color={MOVEMENT_COLORS[v] || 'default'} className="rounded-full text-xs">
                    {v}
                </Tag>
            ),
        },
        {
            title: 'Qty',
            dataIndex: 'quantity',
            width: 80,
            render: (v: number, r: StockMovement) => {
                const isIn = ['IN', 'RETURN_IN', 'ADJUST_IN', 'PRODUCTION'].includes(r.movementType);
                return <Text className={`text-sm font-medium ${isIn ? 'text-green-600' : 'text-red-500'}`}>
                    {isIn ? '+' : '-'}{Math.abs(v).toLocaleString()}
                </Text>;
            },
        },
        {
            title: 'Reference',
            dataIndex: 'reference',
            width: 140,
            render: (v: string) => <Text className="text-xs">{v || '-'}</Text>,
        },
        {
            title: 'Notes',
            dataIndex: 'notes',
            ellipsis: true,
            render: (v: string) => <Text className="text-xs">{v || '-'}</Text>,
        },
    ];

    const kpiCards = [
        { title: 'Total Items', value: stats?.totalItems || 0, icon: <DashboardOutlined />, color: 'var(--theme-color, #7c3aed)' },
        { title: 'Total On-Hand', value: stats?.totalOnHand || 0, icon: <BarChartOutlined />, color: '#0ea5e9' },
        { title: 'Total Reserved', value: stats?.totalReserved || 0, icon: <ClockCircleOutlined />, color: '#f59e0b' },
        { title: 'Low Stock', value: stats?.lowStockCount || 0, icon: <WarningOutlined />, color: '#ef4444' },
        { title: 'Movements', value: stats?.totalMovements || 0, icon: <SwapOutlined />, color: '#10b981' },
        { title: 'Active Items', value: stats?.activeItems || 0, icon: <CheckCircleOutlined />, color: themeColor },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Stock Dashboard</AuroraText>}
            subTitle={
                <DecryptedText
                    text="Real-time inventory levels, stock movements, and AI-powered anomaly detection"
                    animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential
                />
            }
            extra={[
                <Tooltip key="locator" title="Find items in bins"><Button icon={<AimOutlined />} onClick={() => router.push('/admin/inventory/item-locator')}>Item Locator</Button></Tooltip>,
                <Tooltip key="3d" title="View 3D Warehouse"><Button icon={<EnvironmentOutlined />} onClick={() => router.push('/admin/inventory/warehouse-map')}>3D Map</Button></Tooltip>,
            ]}
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, height: '100%' }}>
                {/* KPI Cards */}
                <Row gutter={[12, 12]}>
                    {kpiCards.map((s, i) => (
                        <Col key={i} xs={12} sm={8} md={4}>
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 260, damping: 20 }}>
                                <Card size="small" className="hover:shadow-md transition-shadow" style={{
                                    ...(isDark ? glassDark : glass), borderTop: `3px solid ${s.color}`, position: 'relative', overflow: 'hidden',
                                }}>
                                    <div style={{ position: 'absolute', top: -10, right: -10, width: 60, height: 60, borderRadius: '50%', background: `radial-gradient(circle, ${s.color}18 0%, transparent 70%)`, pointerEvents: 'none' }} />
                                    <div className="flex items-center gap-3" style={{ position: 'relative' }}>
                                        <div className="w-11 h-11 rounded-xl flex items-center justify-center"
                                            style={{ background: `${s.color}15`, color: s.color, fontSize: 18, border: `1px solid ${s.color}20` }}>
                                            {s.icon}
                                        </div>
                                        <div>
                                            <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.5)' : 'rgba(0,0,0,0.45)', letterSpacing: 0.5, textTransform: 'uppercase' as const }} className="block">{s.title}</Text>
                                            <Text strong style={{ fontSize: 20, fontWeight: 700, color: s.color }}>{s.value.toLocaleString()}</Text>
                                        </div>
                                    </div>
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Toolbar */}
                <Card size="small" style={{
                    ...(isDark ? glassDark : glass), borderLeft: `3px solid var(--theme-color, #7c3aed)`,
                }}>
                    <div className="flex items-center justify-between gap-3 flex-wrap">
                        <div className="flex items-center gap-2">
                            <Input
                                prefix={<SearchOutlined className="text-gray-400" />}
                                placeholder="Search stock..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                allowClear style={{ maxWidth: 260, borderRadius: 8 }}
                            />
                        </div>
                        <div className="flex items-center gap-2">
                            <Button icon={<RobotOutlined />} onClick={handleAnomalyDetection}
                                loading={anomalyLoading}
                                style={{ borderColor: 'var(--theme-color, #7c3aed)', color: 'var(--theme-color, #7c3aed)' }}>
                                AI Anomaly Detection
                            </Button>
                            <AnimatedTooltip content="Reload">
                                <Button icon={<ReloadOutlined />} onClick={loadAll} />
                            <RbacGuard requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'inventory_stock', title: 'Stock Ledger', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Item', key: 'itemName' }, { header: 'Warehouse', key: 'warehouseName' }, { header: 'Type', key: 'transactionType' }, { header: 'Qty', key: 'quantity' }, { header: 'Balance', key: 'balanceAfter' }], data: ledger })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'inventory_stock', title: 'Stock Ledger', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Item', key: 'itemName' }, { header: 'Warehouse', key: 'warehouseName' }, { header: 'Type', key: 'transactionType' }, { header: 'Qty', key: 'quantity' }, { header: 'Balance', key: 'balanceAfter' }], data: ledger })} /></Tooltip></RbacGuard>
                            </AnimatedTooltip>
                            <Button type="primary" icon={<PlusOutlined />}
                                onClick={() => { movementForm.resetFields(); setMovementModalOpen(true); }}
                                style={{ background: 'linear-gradient(135deg, var(--theme-color, #7c3aed), var(--theme-secondary, #6366f1))', borderRadius: 8, border: 'none' }}>
                                Record Movement
                            </Button>
                        </div>
                    </div>
                </Card>

                {/* AI Anomaly Banner */}
                {anomalyResult && (
                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }}>
                        <Card size="small" style={{
                            background: anomalyResult.anomalies?.length > 0 ? '#fff7ed' : '#f0fdf4',
                            borderColor: anomalyResult.anomalies?.length > 0 ? '#fed7aa' : '#bbf7d0',
                            borderRadius: 12,
                        }}>
                            <div className="flex items-start gap-3">
                                <RobotOutlined style={{ fontSize: 20, color: 'var(--theme-color, #7c3aed)' }} />
                                <div className="flex-1">
                                    <Text strong className="text-sm block mb-1">AI Anomaly Analysis</Text>
                                    <Text className="text-xs">{anomalyResult.summary || anomalyResult.message}</Text>
                                    {anomalyResult.anomalies?.length > 0 && (
                                        <div className="mt-2 space-y-1">
                                            {anomalyResult.anomalies.map((a: any, i: number) => (
                                                <div key={i} className="flex items-center gap-2 text-xs">
                                                    <Tag color={a.riskLevel === 'high' ? 'red' : a.riskLevel === 'medium' ? 'orange' : 'green'} className="text-xs rounded-full">
                                                        {a.riskLevel}
                                                    </Tag>
                                                    <Text className="text-xs">{a.itemName}: {a.reason}</Text>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                                <Button type="text" size="small" onClick={() => setAnomalyResult(null)}>âœ•</Button>
                            </div>
                        </Card>
                    </motion.div>
                )}

                {/* Two-column: Stock Levels + Recent Movements */}
                <Row gutter={16} style={{ flex: 1, minHeight: 0 }}>
                    <Col xs={24} lg={14}>
                        <Card size="small" title={
                            <Space>
                                <span style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 24, height: 24, borderRadius: 7, background: 'linear-gradient(135deg, #3b82f6, #1d4ed8)' }}>
                                    <BarChartOutlined style={{ color: '#fff', fontSize: 12 }} />
                                </span>
                                <span style={{ fontWeight: 600, color: isDark ? 'rgba(255,255,255,0.9)' : 'rgba(0,0,0,0.85)' }}>Stock Levels</span>
                            </Space>
                        } style={{ height: '100%', ...(isDark ? glassDark : glass), borderLeft: '3px solid #3b82f6' }}>
                            <Table
                                dataSource={ledger}
                                columns={ledgerColumns}
                                rowKey="id"
                                loading={loading}
