                                        selectedObj.type === 'rack' ? (selectedObj.row && selectedObj.bay ? `${selectedObj.row}-${String(selectedObj.bay).padStart(2, '0')}` : undefined) : undefined,
                                        selectedObj.type === 'zone' ? (selectedObj.label || undefined) : undefined
