                    </div>
                </Form>
            </Modal>

            {/* ─── Transfer Modal ────────────────────────────────────────── */}
            <Modal title="New Stock Transfer" open={trfModalOpen} onCancel={() => setTrfModalOpen(false)}
                onOk={handleCreateTransfer} okText="Create Transfer" width={600}>
                <Form form={trfForm} layout="vertical">
                    <Row gutter={16}>
