"use client";
import React, { useState, useEffect, useCallback } from "react";
import { Card, Button, Space, Tag, Typography, Row, Col, Statistic, Table, Progress, message, Badge, Empty, Spin, Tooltip, Timeline, Divider } from "antd";
import {
    SafetyOutlined, AuditOutlined, CheckCircleOutlined,
    ClockCircleOutlined, PlusOutlined, ReloadOutlined, FileTextOutlined,
    ArrowRightOutlined, BarChartOutlined, ExclamationCircleOutlined,
    LockOutlined, BugOutlined, FormOutlined, StarOutlined,
    WarningOutlined, AlertOutlined, EyeOutlined,
} from "@ant-design/icons";
import { motion } from "framer-motion";
import type { ColumnsType } from "antd/es/table";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useRouter } from "next/navigation";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, Cell, PieChart, Pie } from "recharts";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);

const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

function riskColor(score: number) {
    if (score >= 80) return '#10b981';
    if (score >= 60) return '#f59e0b';
    return '#ef4444';
}

function riskLabel(score: number) {
    if (score >= 80) return 'Low Risk';
    if (score >= 60) return 'Medium Risk';
    return 'High Risk';
}

// Pre-defined audit templates
const AUDIT_TEMPLATES = [
    { id: 'sec-infra', name: 'Infrastructure Security Audit', icon: <SafetyOutlined />, items: 25, severity: 'Critical', color: '#ef4444' },
    { id: 'sec-app', name: 'Application Security Review', icon: <BugOutlined />, items: 20, severity: 'High', color: '#f59e0b' },
    { id: 'sec-access', name: 'Access Control Assessment', icon: <LockOutlined />, items: 15, severity: 'High', color: '#8b5cf6' },
    { id: 'sec-data', name: 'Data Protection Compliance', icon: <SafetyOutlined />, items: 18, severity: 'Critical', color: '#ef4444' },
    { id: 'sec-network', name: 'Network Security Check', icon: <AlertOutlined />, items: 22, severity: 'Medium', color: '#3b82f6' },
    { id: 'sec-incident', name: 'Incident Response Readiness', icon: <WarningOutlined />, items: 12, severity: 'High', color: '#ec4899' },
];

export default function ItsmAuditPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [messageApi, ctx] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [submissions, setSubmissions] = useState<any[]>([]);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const sRes = await gql<{ formSubmissions: any[] }>(`
                query($t:String!){ formSubmissions(tenantId:$t){
                    id status totalScore maxPossibleScore percentage grade
                    submittedBy submittedAt reviewedAt templateName templateCategory
                } }
            `, { t: DEFAULT_TENANT_ID }).catch(() => ({ formSubmissions: [] }));
            const auditSubs = (sRes.formSubmissions || []).filter((s: any) =>
                s.templateCategory === 'audit' || s.templateCategory === 'assessment' ||
                s.templateCategory === 'checklist' || s.percentage > 0
            );
            setSubmissions(auditSubs);
        } catch (e: any) { messageApi.error(e.message); }
        setLoading(false);
    }, [messageApi]);

    useEffect(() => { load(); }, [load]);

    const scoredSubs = submissions.filter(s => s.percentage > 0);
    const avgCompliance = scoredSubs.length > 0 ? scoredSubs.reduce((a: number, s: any) => a + s.percentage, 0) / scoredSubs.length : 0;
    const highRisk = scoredSubs.filter(s => s.percentage < 60).length;
    const medRisk = scoredSubs.filter(s => s.percentage >= 60 && s.percentage < 80).length;
    const lowRisk = scoredSubs.filter(s => s.percentage >= 80).length;

    // Risk distribution for pie
    const riskData = [
        { name: 'Low Risk', value: lowRisk, color: '#10b981' },
        { name: 'Medium Risk', value: medRisk, color: '#f59e0b' },
        { name: 'High Risk', value: highRisk, color: '#ef4444' },
    ].filter(r => r.value > 0);

    const columns: ColumnsType<any> = [
        { title: 'Assessment', dataIndex: 'templateName', render: (v: string) => (
            <Space direction="vertical" size={0}>
                <Text strong style={{ fontSize: 12 }}>{v || 'Security Audit'}</Text>
                <Tag style={{ fontSize: 9 }}>audit</Tag>
            </Space>
        )},
        { title: 'Compliance', key: 'score', width: 130, sorter: (a: any, b: any) => a.percentage - b.percentage, render: (_: any, rec: any) => (
            <Space>
                <Progress type="circle" size={36} percent={rec.percentage}
                    strokeColor={riskColor(rec.percentage)}
                    format={() => <Text style={{ fontSize: 10 }}>{rec.percentage.toFixed(0)}</Text>} />
            </Space>
        )},
        { title: 'Risk Level', key: 'risk', width: 120, render: (_: any, rec: any) => {
            const color = riskColor(rec.percentage);
            return <Tag color={color} style={{ borderRadius: 10 }}>{riskLabel(rec.percentage)}</Tag>;
        }},
        { title: 'Grade', dataIndex: 'grade', width: 100, render: (v: string) => v ? <Tag color={v === 'Excellent' ? 'green' : v === 'Good' ? 'blue' : v === 'Satisfactory' ? 'orange' : 'red'}>{v}</Tag> : '—' },
        { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color={v === 'approved' ? 'green' : v === 'submitted' ? 'blue' : 'default'}>{v}</Tag> },
        { title: 'Audited', dataIndex: 'submittedAt', width: 110, render: (v: string) => v ? <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(v).fromNow()}</Text> : '—' },
        { title: '', key: 'action', width: 50, render: (_: any, rec: any) => (
            <Tooltip title="View Detail"><Button type="text" size="small" icon={<EyeOutlined />} onClick={() => router.push(`/admin/forms/response?id=${rec.id}`)} /></Tooltip>
        )},
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#ef4444', '#f59e0b']}>IT Security Audits</AuroraText>}
            subTitle={<DecryptedText text="Security assessments, compliance audits & vulnerability checks" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <Button key="new" type="primary" icon={<PlusOutlined />} onClick={() => router.push('/admin/forms/builder')}
                    style={{ background: 'linear-gradient(135deg, #ef4444, #dc2626)', border: 'none' }}>New Audit</Button>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={load} />,
            ]}
        >
            {ctx}
            {loading ? <div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" /></div> : (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                    {/* Stats */}
                    <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                        {[
                            { label: 'Audit Templates', value: AUDIT_TEMPLATES.length, color: '#ef4444', icon: <AuditOutlined /> },
                            { label: 'Assessments', value: submissions.length, color: '#3b82f6', icon: <FileTextOutlined /> },
                            { label: 'Compliance Avg', value: `${avgCompliance.toFixed(1)}%`, color: riskColor(avgCompliance), icon: <SafetyOutlined /> },
                            { label: 'High Risk', value: highRisk, color: '#ef4444', icon: <ExclamationCircleOutlined /> },
                            { label: 'Medium Risk', value: medRisk, color: '#f59e0b', icon: <WarningOutlined /> },
                            { label: 'Low Risk', value: lowRisk, color: '#10b981', icon: <CheckCircleOutlined /> },
                        ].map((s, i) => (
                            <Col xs={12} sm={8} md={4} key={i}>
                                <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                    <Card style={{ ...glass, borderTop: `3px solid ${s.color}` }} bodyStyle={{ padding: '12px 14px' }}>
                                        <Statistic title={<Text style={{ fontSize: 10 }}>{s.label}</Text>} value={s.value}
                                            prefix={s.icon} valueStyle={{ color: s.color, fontSize: 18 }} />
                                    </Card>
                                </motion.div>
                            </Col>
                        ))}
                    </Row>

                    {/* Audit Templates */}
                    <Card size="small" title={<Space><AuditOutlined style={{ color: '#ef4444' }} /> Audit Templates</Space>}
                        style={{ ...glass, marginBottom: 16 }} extra={<Button type="link" size="small" icon={<ArrowRightOutlined />} onClick={() => router.push('/admin/forms/templates')}>All Forms</Button>}>
                        <Row gutter={[12, 12]}>
                            {AUDIT_TEMPLATES.map((tpl, i) => (
                                <Col xs={24} sm={12} md={8} key={tpl.id}>
                                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.04 }}>
                                        <Card size="small" hoverable style={{ borderRadius: 12, borderLeft: `3px solid ${tpl.color}`, cursor: 'pointer' }}
                                            onClick={() => router.push('/admin/forms/builder')}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                <Space>
                                                    <span style={{ fontSize: 18, color: tpl.color }}>{tpl.icon}</span>
                                                    <div>
                                                        <Text strong style={{ fontSize: 12 }}>{tpl.name}</Text>
                                                        <div>
                                                            <Tag style={{ fontSize: 9 }}>{tpl.items} items</Tag>
                                                            <Tag color={tpl.severity === 'Critical' ? 'red' : tpl.severity === 'High' ? 'orange' : 'blue'} style={{ fontSize: 9 }}>{tpl.severity}</Tag>
                                                        </div>
                                                    </div>
                                                </Space>
                                            </div>
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </Row>
                    </Card>

                    {/* Risk Overview + Audit Results */}
                    <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                        <Col xs={24} md={8}>
                            <Card size="small" title={<Space><SafetyOutlined style={{ color: '#8b5cf6' }} /> Risk Overview</Space>} style={{ ...glass, height: '100%' }}>
                                {riskData.length > 0 ? (
                                    <>
                                        <div style={{ textAlign: 'center', marginBottom: 12 }}>
                                            <Progress type="dashboard" percent={Math.round(avgCompliance)} size={120}
                                                strokeColor={riskColor(avgCompliance)}
                                                format={() => (
                                                    <div>
                                                        <div style={{ fontSize: 22, fontWeight: 700, color: riskColor(avgCompliance) }}>{avgCompliance.toFixed(1)}%</div>
                                                        <Text type="secondary" style={{ fontSize: 10 }}>Compliance</Text>
                                                    </div>
                                                )} />
                                        </div>
                                        <Space direction="vertical" size={6} style={{ width: '100%' }}>
                                            {riskData.map((r, i) => (
                                                <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', borderRadius: 8, background: `${r.color}08` }}>
                                                    <div style={{ width: 10, height: 10, borderRadius: '50%', background: r.color }} />
                                                    <Text style={{ flex: 1, fontSize: 12 }}>{r.name}</Text>
                                                    <Badge count={r.value} style={{ backgroundColor: r.color }} />
                                                </div>
                                            ))}
                                        </Space>
                                    </>
                                ) : <Empty description="No audit data" />}
                            </Card>
                        </Col>
                        <Col xs={24} md={16}>
                            <Card size="small" title={<Space><FileTextOutlined style={{ color: '#3b82f6' }} /> Audit Results <Badge count={scoredSubs.length} size="small" /></Space>}
                                style={{ ...glass, height: '100%' }}>
                                <Table<any>
                                    dataSource={scoredSubs.slice(0, 15)}
                                    columns={columns}
                                    rowKey="id"
                                    size="small"
                                    pagination={false}
                                    locale={{ emptyText: <Empty description="No audit results. Create an audit form to get started." /> }}
                                />
                            </Card>
                        </Col>
                    </Row>
                </motion.div>
            )}
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Form, Input, Row, Col, InputNumber, Card, Statistic, Progress, Typography, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, FieldTimeOutlined, CheckCircleOutlined, CloseCircleOutlined, ExclamationCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { supaRest, supaInsert, supaDelete } from "@/lib/supaRest";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const FIELDS: FieldDef[] = [
    { name: "period_start", label: "Period Start", required: true },
    { name: "period_end", label: "Period End", required: true },
    { name: "uptime_minutes", label: "Uptime (min)", required: true },
];

export default function AvailabilityPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [form] = Form.useForm();

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const rows = await supaRest('itsm_availability_records', { order: 'period_start.desc' });
            setData(rows);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const body: any = { tenant_id: 'default', period_start: values.period_start, period_end: values.period_end, uptime_minutes: values.uptime_minutes, downtime_minutes: values.downtime_minutes || 0, planned_downtime_minutes: values.planned_downtime_minutes || 0, unplanned_downtime_minutes: values.unplanned_downtime_minutes || 0, mtbf_hours: values.mtbf_hours, mtrs_hours: values.mtrs_hours, incident_count: values.incident_count || 0, sla_target_pct: values.sla_target_pct || 99.9, notes: values.notes };
            await supaInsert('itsm_availability_records', body);
            messageApi.success("Availability record created.");
            setModalOpen(false); form.resetFields(); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await supaDelete('itsm_availability_records', id); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    // Summary stats
    const avgAvail = data.length > 0 ? data.reduce((s, r) => s + (r.availability_pct || 0), 0) / data.length : 0;
    const totalIncidents = data.reduce((s, r) => s + (r.incident_count || 0), 0);
    const totalDowntime = data.reduce((s, r) => s + (r.downtime_minutes || 0), 0);

    const columns: ProColumns<any>[] = [
        { title: 'Period', width: 180, render: (_, r) => <Text>{r.period_start ? new Date(r.period_start).toLocaleDateString('id-ID') : '-'} â†’ {r.period_end ? new Date(r.period_end).toLocaleDateString('id-ID') : '-'}</Text> },
        { title: 'Availability', width: 160, render: (_, r) => { const pct = r.availability_pct || 0; const target = r.sla_target_pct || 99.9; return <Progress percent={Math.round(pct * 100) / 100} size="small" status={pct >= target ? 'success' : 'exception'} format={() => `${pct.toFixed(2)}%`} />; } },
        { title: 'SLA Target', dataIndex: 'sla_target_pct', width: 100, render: (_, r) => <Tag>{r.sla_target_pct || 99.9}%</Tag> },
        { title: 'SLA Met?', width: 80, render: (_, r) => { const pct = r.availability_pct || 0; const target = r.sla_target_pct || 99.9; return pct >= target ? <Tag color="green" icon={<CheckCircleOutlined />}>Yes</Tag> : <Tag color="red" icon={<CloseCircleOutlined />}>No</Tag>; } },
        { title: 'Uptime', dataIndex: 'uptime_minutes', width: 100, render: (_, r) => <Text type="success">{r.uptime_minutes?.toLocaleString()} min</Text> },
        { title: 'Downtime', dataIndex: 'downtime_minutes', width: 100, render: (_, r) => <Text type={r.downtime_minutes > 0 ? 'danger' : 'success'}>{r.downtime_minutes || 0} min</Text> },
        { title: 'Planned DT', dataIndex: 'planned_downtime_minutes', width: 90, render: (_, r) => `${r.planned_downtime_minutes || 0} min` },
        { title: 'Unplanned DT', dataIndex: 'unplanned_downtime_minutes', width: 100, render: (_, r) => <Text type={r.unplanned_downtime_minutes > 0 ? 'danger' : undefined}>{r.unplanned_downtime_minutes || 0} min</Text> },
        { title: 'MTBF', dataIndex: 'mtbf_hours', width: 80, render: (_, r) => r.mtbf_hours ? `${r.mtbf_hours}h` : '-' },
        { title: 'MTRS', dataIndex: 'mtrs_hours', width: 80, render: (_, r) => r.mtrs_hours ? `${r.mtrs_hours}h` : '-' },
        { title: 'Incidents', dataIndex: 'incident_count', width: 80, render: (_, r) => <Tag color={r.incident_count > 0 ? 'orange' : 'green'}>{r.incident_count || 0}</Tag> },
        { title: 'Notes', dataIndex: 'notes', ellipsis: true },
        {
            title: '', valueType: 'option', width: 50,
            render: (_, record) => [
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} size="small" /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Availability Management</AuroraText>}
            subTitle={<DecryptedText text="Track service uptime, SLA compliance, and reliability metrics" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Avg Availability', value: `${avgAvail.toFixed(2)}%`, icon: <CheckCircleOutlined />, color: avgAvail >= 99.9 ? '#10b981' : avgAvail >= 99 ? '#f59e0b' : '#ef4444' },
                    { title: 'Total Records', value: data.length, icon: <FieldTimeOutlined />, color: '#3b82f6' },
                    { title: 'Total Downtime', value: `${totalDowntime} min`, icon: <CloseCircleOutlined />, color: totalDowntime > 0 ? '#ef4444' : '#10b981' },
                    { title: 'Total Incidents', value: totalIncidents, icon: <ExclamationCircleOutlined />, color: totalIncidents > 0 ? '#f59e0b' : '#10b981' },
                    { title: 'SLA Met', value: `${data.filter(r => (r.availability_pct || 0) >= (r.sla_target_pct || 99.9)).length}/${data.length}`, icon: <CheckCircleOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* SLA Compliance Trend */}
            {data.length > 0 && (
                <Card size="small" style={{ ...glass, marginBottom: 16 }} title={<Text strong style={{ fontSize: 13 }}>â±ï¸ Availability Trend</Text>}>
                    <div style={{ display: 'flex', alignItems: 'flex-end', gap: 4, height: 80 }}>
                        {data.slice(0, 12).reverse().map((r, i) => {
                            const pct = r.availability_pct || 0;
                            const target = r.sla_target_pct || 99.9;
                            const met = pct >= target;
                            return (
                                <motion.div key={r.id} initial={{ scaleY: 0 }} animate={{ scaleY: 1 }} transition={{ delay: i * 0.05 }}
                                    style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', transformOrigin: 'bottom' }}>
                                    <Text style={{ fontSize: 8, color: met ? '#10b981' : '#ef4444' }}>{pct.toFixed(1)}%</Text>
                                    <div style={{ width: '100%', height: `${Math.max(pct - 95, 0) * 16}px`, minHeight: 4, borderRadius: '4px 4px 0 0', background: met ? '#10b981' : '#ef4444', maxHeight: 60 }} />
                                </motion.div>
                            );
                        })}
                    </div>
                </Card>
            )}

            <ProTable
                headerTitle={<Space><FieldTimeOutlined /> Availability Records</Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { form.resetFields(); setModalOpen(true); }}>New Record</Button>,
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_availability', title: 'Availability Management', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Service name', key: 'service_name' }, { header: 'Sla target', key: 'sla_target' }, { header: 'Actual availability', key: 'actual_availability' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_availability', title: 'Availability Management', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Service name', key: 'service_name' }, { header: 'Sla target', key: 'sla_target' }, { header: 'Actual availability', key: 'actual_availability' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip></RbacGuard>,
                ]}
            />

            <SteppedFormModal open={modalOpen} onCancel={() => { setModalOpen(false); form.resetFields(); }} onSubmit={handleSave} form={form} title="New Availability Record" entityName="record" steps={[
                { title: "Period & Uptime", icon: <FieldTimeOutlined />, fields: ["period_start", "period_end", "uptime_minutes", "downtime_minutes", "planned_downtime_minutes", "unplanned_downtime_minutes", "sla_target_pct"],
                    content: (<>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="period_start" label="Period Start" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col>
                            <Col span={12}><Form.Item name="period_end" label="Period End" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="uptime_minutes" label="Uptime (minutes)" rules={[{ required: true }]}><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                            <Col span={12}><Form.Item name="downtime_minutes" label="Downtime (minutes)"><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="planned_downtime_minutes" label="Planned Downtime (min)"><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                            <Col span={12}><Form.Item name="unplanned_downtime_minutes" label="Unplanned Downtime (min)"><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                        </Row>
                        <Form.Item name="sla_target_pct" label="SLA Target %"><InputNumber style={{ width: '100%' }} min={0} max={100} step={0.01} /></Form.Item>
                    </>),
                },
                { title: "Metrics", icon: <CheckCircleOutlined />, fields: ["mtbf_hours", "mtrs_hours", "incident_count", "notes"],
                    content: (<>
                        <Row gutter={16}>
                            <Col span={8}><Form.Item name="mtbf_hours" label="MTBF (hours)"><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                            <Col span={8}><Form.Item name="mtrs_hours" label="MTRS (hours)"><InputNumber style={{ width: '100%' }} min={0} step={0.1} /></Form.Item></Col>
                            <Col span={8}><Form.Item name="incident_count" label="Incident Count"><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                        </Row>
                        <Form.Item name="notes" label="Notes"><Input.TextArea rows={3} placeholder="Service/CI identifier, any context about the period" /></Form.Item>
                    </>),
                },
            ]} fields={FIELDS} width={700} gradient={["#52c41a", "#389e0d"]} editMode={false} initialValues={{ sla_target_pct: 99.9, incident_count: 0, downtime_minutes: 0 }} />
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Typography, Card, Statistic, Badge, Tooltip } from "antd";
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { PlusOutlined, DeleteOutlined, EditOutlined, ShopOutlined, CheckCircleOutlined, AppstoreOutlined, FileProtectOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";

const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_CATALOG = `query($status: String, $search: String) { itsmCatalogItems(status: $status, search: $search) { id catalogCode name shortDescription description portfolioServiceId categoryId icon estimatedDelivery cost approvalRequired approvalType fulfillmentGroup status requestCount createdAt } }`;
const GET_CATEGORIES = `query { itsmCategories { id name } }`;
const CREATE_CATALOG = `mutation($tenantId: String!, $input: CreateItsmCatalogInput!) { createItsmCatalogItem(tenantId: $tenantId, input: $input) { id catalogCode } }`;
const UPDATE_CATALOG = `mutation($id: ID!, $input: UpdateItsmCatalogInput!) { updateItsmCatalogItem(id: $id, input: $input) { id } }`;
const DELETE_CATALOG = `mutation($id: ID!) { deleteItsmCatalogItem(id: $id) }`;

const FIELDS: FieldDef[] = [
    { name: "name", label: "Name", required: true },
    { name: "shortDescription", label: "Short Description" },
    { name: "estimatedDelivery", label: "Delivery Time" },
    { name: "cost", label: "Cost" },
];

export default function ItsmCatalogPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [d, c] = await Promise.all([
                gql(GET_CATALOG, { status: filterStatus }),
                gql(GET_CATEGORIES),
            ]);
            setData(d.itsmCatalogItems || []);
            setCategories(c.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const input = {
                name: values.name, shortDescription: values.shortDescription, description: values.description,
                categoryId: values.categoryId, icon: values.icon, estimatedDelivery: values.estimatedDelivery,
                cost: values.cost, approvalRequired: values.approvalRequired || false,
                approvalType: values.approvalType || 'simple', fulfillmentGroup: values.fulfillmentGroup,
                status: values.status || 'active',
            };
            if (editing) {
                await gql(UPDATE_CATALOG, { id: editing.id, input });
                messageApi.success("Catalog item updated.");
            } else {
                const d = await gql(CREATE_CATALOG, { tenantId: DEFAULT_TENANT_ID, input });
                messageApi.success(`Catalog item ${d.createItsmCatalogItem.catalogCode} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_CATALOG, { id }); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: 'Code', dataIndex: 'catalogCode', width: 110, render: (_, r) => <Tag color="cyan" style={{ fontFamily: 'monospace' }}>{r.catalogCode}</Tag> },
        { title: 'Service Name', dataIndex: 'name', ellipsis: true },
        { title: 'Description', dataIndex: 'shortDescription', ellipsis: true, width: 200 },
        { title: 'Delivery', dataIndex: 'estimatedDelivery', width: 140 },
        { title: 'Cost', dataIndex: 'cost', width: 100 },
        { title: 'Approval', dataIndex: 'approvalRequired', width: 90, render: (_, r) => r.approvalRequired ? <Tag color="orange">Required</Tag> : <Tag color="green">No</Tag> },
        { title: 'Status', dataIndex: 'status', width: 90, render: (_, r) => <Tag color={r.status === 'active' ? 'green' : r.status === 'inactive' ? 'default' : 'red'}>{(r.status || '').toUpperCase()}</Tag> },
        { title: 'Requests', dataIndex: 'requestCount', width: 80 },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Service Catalog</AuroraText>}
            subTitle={<DecryptedText text="Services available for request" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <BentoGrid className="mb-4">
                {[
                    { title: 'Total Items', value: data.length, icon: <ShopOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: data.filter(d => d.status === 'active').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Approval Required', value: data.filter(d => d.approvalRequired).length, icon: <FileProtectOutlined />, color: '#f59e0b' },
                    { title: 'Total Requests', value: data.reduce((s, d) => s + (d.requestCount || 0), 0), icon: <AppstoreOutlined />, color: '#8b5cf6' },
                    { title: 'Categories', value: categories.length, icon: <AppstoreOutlined />, color: '#06b6d4' },
                ].map((s, i) => (
                    <BentoGridItem
                        key={i}
                        title={s.title}
                        description="Catalog metric"
                        icon={<span style={{ color: s.color }}>{s.icon}</span>}
                        className={i === 4 ? "col-span-3 lg:col-span-1 lg:col-start-2" : "col-span-3 lg:col-span-1"}
                        header={
                            <div className="flex h-full w-full flex-col items-center justify-center rounded-xl" style={{ backgroundColor: `${s.color}15` }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: s.color }}>
                                    {s.value}
                                </div>
                            </div>
                        }
                    />
                ))}
            </BentoGrid>
            <ProTable
                headerTitle={<Space><ShopOutlined /> Service Catalog <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_catalog', title: 'Service Catalog', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Category', key: 'category' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_catalog', title: 'Service Catalog', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Category', key: 'category' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip></RbacGuard>,
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 120 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }, { value: 'deprecated', label: 'Deprecated' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Catalog Item</Button>,
                ]}
            />

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? `Edit ${editing.catalogCode}` : "New Catalog Item"}
                entityName="catalog item"
                steps={[
                    {
                        title: "Service Details",
                        icon: <ShopOutlined />,
                        fields: ["name", "shortDescription", "description", "categoryId"],
                        content: (
                            <>
                                <Form.Item name="name" label="Service Name" rules={[{ required: true }]}><Input placeholder="e.g., New Laptop, VPN Access" /></Form.Item>
                                <Form.Item name="shortDescription" label="Short Description"><Input placeholder="Brief user-facing summary" /></Form.Item>
                                <Form.Item name="description" label="Full Description"><Input.TextArea rows={3} placeholder="Detailed service info" /></Form.Item>
                                <Form.Item name="categoryId" label="Category">
                                    <Select placeholder="Select" allowClear options={categories.map(c => ({ value: c.id, label: c.name }))} />
                                </Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Delivery & Cost",
                        icon: <ShopOutlined />,
                        fields: ["estimatedDelivery", "cost", "icon"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}><Form.Item name="estimatedDelivery" label="Estimated Delivery"><Input placeholder="e.g., 2 business days" /></Form.Item></Col>
                                    <Col span={12}><Form.Item name="cost" label="Cost"><Input placeholder="e.g., Free, $500" /></Form.Item></Col>
                                </Row>
                                <Form.Item name="icon" label="Icon"><Input placeholder="Icon name or emoji" /></Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Approval & Fulfillment",
                        icon: <ShopOutlined />,
                        fields: ["approvalRequired", "approvalType", "fulfillmentGroup", "status"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="approvalRequired" label="Approval Required?">
                                            <Select options={[{ value: false, label: 'No' }, { value: true, label: 'Yes' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="approvalType" label="Approval Type">
                                            <Select options={[{ value: 'simple', label: 'Simple (1 approver)' }, { value: 'multi_level', label: 'Multi-Level' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                <Form.Item name="fulfillmentGroup" label="Fulfillment Group"><Input placeholder="e.g., IT Service Desk" /></Form.Item>
                                {editing && (
                                    <Form.Item name="status" label="Status">
                                        <Select options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }, { value: 'deprecated', label: 'Deprecated' }]} />
                                    </Form.Item>
                                )}
                            </>
                        ),
                    },
                ]}
                fields={FIELDS}
                width={700}
                gradient={["#13c2c2", "#08979c"]}
                editMode={!!editing}
                initialValues={{ approvalRequired: false, approvalType: 'simple', status: 'active' }}
            />
        </div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Typography, Form, Input, Select, Row, Col, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, AppstoreOutlined, InfoCircleOutlined, SettingOutlined, CheckCircleOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_CATEGORIES = `query { itsmCategories { id name description parentId icon status createdAt } }`;
const CREATE_CATEGORY = `mutation($tenantId: String!, $input: CreateItsmCategoryInput!) { createItsmCategory(tenantId: $tenantId, input: $input) { id } }`;
const UPDATE_CATEGORY = `mutation($id: ID!, $input: UpdateItsmCategoryInput!) { updateItsmCategory(id: $id, input: $input) { id } }`;
const DELETE_CATEGORY = `mutation($id: ID!) { deleteItsmCategory(id: $id) }`;

const iconOptions = [
    { value: 'DesktopOutlined', label: 'ðŸ–¥ï¸ Hardware' },
    { value: 'CodeOutlined', label: 'ðŸ’» Software' },
    { value: 'WifiOutlined', label: 'ðŸ“¶ Network' },
    { value: 'SafetyOutlined', label: 'ðŸ” Security' },
    { value: 'MailOutlined', label: 'ðŸ“§ Email' },
    { value: 'DatabaseOutlined', label: 'ðŸ—„ï¸ Database' },
    { value: 'CloudServerOutlined', label: 'â˜ï¸ Cloud' },
    { value: 'QuestionCircleOutlined', label: 'â“ General' },
    { value: 'PrinterOutlined', label: 'ðŸ–¨ï¸ Printer' },
    { value: 'MobileOutlined', label: 'ðŸ“± Mobile' },
];

const CATEGORY_FIELDS: FieldDef[] = [
    { name: "name", label: "Category Name", required: true },
    { name: "description", label: "Description" },
    { name: "parentId", label: "Parent Category" },
    { name: "icon", label: "Icon" },
    { name: "status", label: "Status" },
];

export default function ItsmCategoriesPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [categories, setCategories] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const d = await gql(GET_CATEGORIES);
            setCategories(d.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(UPDATE_CATEGORY, { id: editing.id, input: values });
                messageApi.success("Category updated.");
            } else {
                await gql(CREATE_CATEGORY, { tenantId: DEFAULT_TENANT_ID, input: values });
                messageApi.success("Category created.");
            }
            setModalOpen(false);
            form.resetFields();
            setEditing(null);
            loadData();
        } catch (err: any) { messageApi.error(err.message); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_CATEGORY, { id }); messageApi.success("Category deleted."); loadData(); }
        catch (err: any) { messageApi.error(err.message); }
    };

    const columns: ProColumns<any>[] = [
        {
            title: 'Icon', dataIndex: 'icon', width: 60,
            render: (_, r) => {
                const match = iconOptions.find(o => o.value === r.icon);
                return <Text style={{ fontSize: 20 }}>{match?.label?.split(' ')[0] || 'ðŸ“'}</Text>;
            }
        },
        { title: 'Name', dataIndex: 'name', render: (_, r) => <Text strong>{r.name}</Text> },
        { title: 'Description', dataIndex: 'description', ellipsis: true },
        {
            title: 'Parent', dataIndex: 'parentId', width: 150,
            render: (_, r) => {
                const parent = categories.find(c => c.id === r.parentId);
                return parent ? <Tag>{parent.name}</Tag> : '-';
            }
        },
        {
            title: 'Status', dataIndex: 'status', width: 100,
            render: (_, r) => <Tag color={r.status === 'active' ? 'green' : 'default'}>{(r.status || '').toUpperCase()}</Tag>
        },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => {
                    setEditing(record);
                    form.setFieldsValue({
                        name: record.name, description: record.description,
                        parentId: record.parentId, icon: record.icon, status: record.status,
                    });
                    setModalOpen(true);
                }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ]
        }
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Service Categories</AuroraText>}
            subTitle={<DecryptedText text="Manage ITSM ticket categories" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Categories', value: categories.length, icon: <AppstoreOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: categories.filter((c: any) => c.status === 'active').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'With SLA', value: categories.filter((c: any) => c.defaultSla).length, icon: <SettingOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <ProTable
                headerTitle={<Space><AppstoreOutlined /> Service Categories <Badge count={categories.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id"
                dataSource={categories}
                loading={loading}
                columns={columns}
                search={false}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_categories', title: 'ITSM Categories', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }], data: categories })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_categories', title: 'ITSM Categories', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }], data: categories })} /></Tooltip></RbacGuard>,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>
                        New Category
                    </Button>,
                ]}
            />

            {/* â”€â”€â”€ Category SteppedFormModal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? "Edit Category" : "New Category"}
                entityName="category"
                steps={[
                    {
                        title: "Basic Info",
                        icon: <InfoCircleOutlined />,
                        fields: ["name", "description"],
                        content: (
                            <>
                                <Form.Item name="name" label="Category Name" rules={[{ required: true }]}>
                                    <Input placeholder="e.g., Hardware, Software, Network" />
                                </Form.Item>
                                <Form.Item name="description" label="Description">
                                    <Input.TextArea rows={3} placeholder="What types of issues fall under this category?" />
                                </Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Settings",
                        icon: <SettingOutlined />,
                        fields: ["parentId", "icon", "status"],
                        content: (
                            <>
                                <Form.Item name="parentId" label="Parent Category">
                                    <Select allowClear placeholder="Select parent (optional)"
                                        options={categories.filter(c => c.id !== editing?.id).map(c => ({ value: c.id, label: c.name }))} />
                                </Form.Item>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="icon" label="Icon">
                                            <Select options={iconOptions} placeholder="Select icon" />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="status" label="Status">
                                            <Select options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                            </>
                        ),
                    },
                ]}
                fields={CATEGORY_FIELDS}
                width={600}
                gradient={["#13c2c2", "#36cfc9"]}
                editMode={!!editing}
                initialValues={{ status: 'active' }}
            />
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { Card, Statistic, Row, Col, Tag, Drawer, Select, Tooltip, Segmented, Typography, Badge, Space, theme } from "antd";
import { CalendarOutlined, CheckCircleOutlined, ToolOutlined, ExclamationCircleOutlined, LeftOutlined, RightOutlined, SwapOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql } from "@/lib/graphql";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import dayjs from "dayjs";

const { Text } = Typography;

const GET_CHANGES = `query { itsmChanges { id changeNumber title status changeType priority riskLevel scheduledStart scheduledEnd implementor approvalStatus impactAssessment rollbackPlan createdAt } }`;

const riskGradients: Record<string, string> = {
    low: "linear-gradient(135deg, #52c41a, #73d13d)",
    medium: "linear-gradient(135deg, #1890ff, #40a9ff)",
    high: "linear-gradient(135deg, #fa8c16, #ffa940)",
    critical: "linear-gradient(135deg, #f5222d, #ff4d4f)",
};
const riskColors: Record<string, string> = { low: "#52c41a", medium: "#1890ff", high: "#fa8c16", critical: "#f5222d" };
const statusColors: Record<string, string> = {
    draft: "default", submitted: "blue", under_review: "cyan", approved: "green",
    scheduled: "geekblue", implementing: "orange", completed: "green", failed: "red", cancelled: "default",
};
const typeColors: Record<string, string> = { standard: "green", normal: "blue", emergency: "red" };
const DAY_HEADERS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

/* helpers */
const isFreezeDay = (d: dayjs.Dayjs) => {
    const q = Math.floor((d.month()) / 3);
    const qEnd = dayjs().year(d.year()).month(q * 3 + 2).endOf("month");
    const freezeStart = qEnd.subtract(6, "day").startOf("day");
    return d.isSame(freezeStart, "day") || (d.isAfter(freezeStart) && (d.isBefore(qEnd.add(1, "day"))));
};

export default function ChangeCalendarPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === "#141414" || antToken.colorBgBase?.includes("14");
    const glass = {
        background: isDark ? "rgba(255,255,255,0.06)" : "rgba(255,255,255,0.65)",
        backdropFilter: "blur(12px)",
        border: `1px solid ${isDark ? "rgba(255,255,255,0.10)" : "rgba(255,255,255,0.45)"}`,
        borderRadius: 14,
    };

    const [data, setData] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [current, setCurrent] = useState(dayjs());
    const [viewMode, setViewMode] = useState<"Month" | "Week">("Month");
    const [selected, setSelected] = useState<any | null>(null);
    const [drawerOpen, setDrawerOpen] = useState(false);
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterRisk, setFilterRisk] = useState<string | undefined>(undefined);
    const [filterType, setFilterType] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const d = await gql(GET_CHANGES);
            setData((d as any).itsmChanges || []);
        } catch { /* silent */ }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    /* filtered data */
    const filtered = useMemo(() => {
        let list = data;
        if (filterStatus) list = list.filter(c => c.status === filterStatus);
        if (filterRisk) list = list.filter(c => c.riskLevel === filterRisk);
        if (filterType) list = list.filter(c => c.changeType === filterType);
        return list;
    }, [data, filterStatus, filterRisk, filterType]);

    /* month stats */
    const monthStart = current.startOf("month");
    const monthEnd = current.endOf("month");
    const monthChanges = useMemo(() => filtered.filter(c => {
        if (!c.scheduledStart) return false;
        const s = dayjs(c.scheduledStart);
        return s.isSame(monthStart, "month") || (s.isAfter(monthStart) && s.isBefore(monthEnd));
    }), [filtered, monthStart, monthEnd]);

    const stats = [
        { title: "Changes This Month", value: monthChanges.length, icon: <CalendarOutlined />, color: "#3b82f6" },
        { title: "Approved", value: monthChanges.filter(c => c.approvalStatus === "approved" || c.status === "approved").length, icon: <CheckCircleOutlined />, color: "#10b981" },
        { title: "Implementing", value: monthChanges.filter(c => c.status === "implementing").length, icon: <ToolOutlined />, color: "#f59e0b" },
        { title: "High Risk", value: monthChanges.filter(c => c.riskLevel === "high" || c.riskLevel === "critical").length, icon: <ExclamationCircleOutlined />, color: "#ef4444" },
    ];

    /* build calendar grid */
    const calendarDays = useMemo(() => {
        if (viewMode === "Week") {
            const weekStart = current.startOf("week").add(current.startOf("week").day() === 0 ? 1 : 0, "day");
            const adjustedStart = current.day() === 0 ? current.subtract(6, "day") : current.startOf("week").add(1, "day");
            return Array.from({ length: 7 }, (_, i) => adjustedStart.add(i, "day"));
        }
        const firstDay = monthStart.startOf("week").add(monthStart.startOf("week").day() === 0 ? 1 : 0, "day");
        const adjustedFirst = monthStart.day() === 0 ? monthStart.subtract(6, "day") : monthStart.startOf("week").add(1, "day");
        const totalCells = Math.ceil((monthStart.day() === 0 ? 6 : monthStart.day() - 1 + monthEnd.date()) / 7) * 7;
        const cells = Math.max(totalCells, 35);
        return Array.from({ length: cells }, (_, i) => adjustedFirst.add(i, "day"));
    }, [current, viewMode, monthStart, monthEnd]);

    /* changes for a specific day */
    const changesForDay = useCallback((day: dayjs.Dayjs) => {
        return filtered.filter(c => {
            if (!c.scheduledStart) return false;
            const s = dayjs(c.scheduledStart).startOf("day");
            const e = c.scheduledEnd ? dayjs(c.scheduledEnd).startOf("day") : s;
            return day.isSame(s, "day") || day.isSame(e, "day") || (day.isAfter(s) && day.isBefore(e));
        });
    }, [filtered]);

    const today = dayjs();

    const openChange = (change: any) => { setSelected(change); setDrawerOpen(true); };
    const nav = (dir: number) => setCurrent(prev => viewMode === "Month" ? prev.add(dir, "month") : prev.add(dir * 7, "day"));

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Change Calendar</AuroraText>}
            subTitle={<DecryptedText text="Visual change schedule for CAB oversight" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.4 }}>
                {/* Stats */}
                <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                    {stats.map((s, i) => (
                        <Col key={i} xs={12} md={6}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                    <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>

                {/* Toolbar */}
                <div style={{ display: "flex", flexWrap: "wrap", gap: 10, alignItems: "center", marginBottom: 16 }}>
                    <Space>
                        <motion.button whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }} onClick={() => nav(-1)}
                            style={{ background: "none", border: `1px solid ${isDark ? "rgba(255,255,255,0.15)" : "#d9d9d9"}`, borderRadius: 8, padding: "4px 10px", cursor: "pointer", color: isDark ? "#fff" : "#333" }}>
                            <LeftOutlined />
                        </motion.button>
                        <Text strong style={{ fontSize: 16, minWidth: 160, textAlign: "center", display: "inline-block" }}>
                            {viewMode === "Month" ? current.format("MMMM YYYY") : `${calendarDays[0]?.format("MMM D")} — ${calendarDays[6]?.format("MMM D, YYYY")}`}
                        </Text>
                        <motion.button whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }} onClick={() => nav(1)}
                            style={{ background: "none", border: `1px solid ${isDark ? "rgba(255,255,255,0.15)" : "#d9d9d9"}`, borderRadius: 8, padding: "4px 10px", cursor: "pointer", color: isDark ? "#fff" : "#333" }}>
                            <RightOutlined />
                        </motion.button>
                        <motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }} onClick={() => setCurrent(dayjs())}
                            style={{ background: themeColor, color: "#fff", border: "none", borderRadius: 8, padding: "4px 14px", cursor: "pointer", fontWeight: 600, fontSize: 13 }}>
                            Today
                        </motion.button>
                    </Space>
                    <div style={{ flex: 1 }} />
                    <Select placeholder="Status" allowClear style={{ width: 130 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: "submitted", label: "Submitted" }, { value: "approved", label: "Approved" }, { value: "implementing", label: "Implementing" }, { value: "completed", label: "Completed" }]} />
                    <Select placeholder="Risk" allowClear style={{ width: 120 }} value={filterRisk} onChange={setFilterRisk}
                        options={[{ value: "low", label: "🟢 Low" }, { value: "medium", label: "🔵 Medium" }, { value: "high", label: "🟠 High" }, { value: "critical", label: "🔴 Critical" }]} />
                    <Select placeholder="Type" allowClear style={{ width: 120 }} value={filterType} onChange={setFilterType}
                        options={[{ value: "normal", label: "Normal" }, { value: "standard", label: "Standard" }, { value: "emergency", label: "Emergency" }]} />
                    <Segmented options={["Month", "Week"]} value={viewMode} onChange={v => setViewMode(v as any)} />
                </div>

                {/* Calendar Grid */}
                <div style={{ overflowX: "auto" }}>
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(7, minmax(120px, 1fr))", gap: 1, minWidth: 840 }}>
                        {/* Day headers */}
                        {DAY_HEADERS.map(d => (
                            <div key={d} style={{
                                textAlign: "center", padding: "8px 0", fontWeight: 700, fontSize: 12,
                                color: isDark ? "rgba(255,255,255,0.55)" : "#8c8c8c",
                                textTransform: "uppercase", letterSpacing: 1,
                            }}>{d}</div>
                        ))}

                        {/* Day cells */}
                        {calendarDays.map((day, idx) => {
                            const isCurrentMonth = day.month() === current.month();
                            const isToday = day.isSame(today, "day");
                            const freeze = isFreezeDay(day);
                            const dayChanges = changesForDay(day);

                            return (
                                <motion.div
                                    key={idx}
                                    initial={{ opacity: 0, scale: 0.95 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    transition={{ delay: idx * 0.008 }}
                                    style={{
                                        minHeight: viewMode === "Week" ? 220 : 110,
                                        padding: 6,
                                        borderRadius: 10,
                                        background: freeze
                                            ? isDark ? "rgba(245,34,45,0.10)" : "rgba(245,34,45,0.06)"
                                            : isToday
                                                ? isDark ? `${themeColor}18` : `${themeColor}08`
                                                : isDark ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.55)",
                                        border: isToday
                                            ? `2px solid ${themeColor}`
                                            : `1px solid ${isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)"}`,
                                        backdropFilter: "blur(8px)",
                                        position: "relative",
                                        opacity: isCurrentMonth || viewMode === "Week" ? 1 : 0.4,
                                        cursor: "pointer",
                                        transition: "box-shadow 0.2s",
                                    }}
                                    whileHover={{ boxShadow: `0 4px 16px ${isDark ? "rgba(0,0,0,0.4)" : "rgba(0,0,0,0.08)"}` }}
                                >
                                    {/* Day number */}
                                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
                                        <Text style={{
                                            fontSize: 13, fontWeight: isToday ? 800 : 500,
                                            color: isToday ? themeColor : isCurrentMonth || viewMode === "Week" ? (isDark ? "#fff" : "#333") : (isDark ? "rgba(255,255,255,0.3)" : "#bbb"),
                                            background: isToday ? `${themeColor}15` : "none",
                                            borderRadius: 6, padding: "0 5px",
                                        }}>
                                            {day.date()}
                                        </Text>
                                        {dayChanges.length > 0 && (
                                            <Badge count={dayChanges.length} size="small" style={{ backgroundColor: themeColor }} />
                                        )}
                                    </div>

                                    {/* Freeze overlay tooltip */}
                                    {freeze && (
                                        <Tooltip title="Change Freeze — No deployments allowed">
                                            <div style={{
                                                fontSize: 9, color: "#f5222d", fontWeight: 700,
                                                textAlign: "center", padding: "1px 0", letterSpacing: 0.5,
                                            }}>🧊 FREEZE</div>
                                        </Tooltip>
                                    )}

                                    {/* Change bars */}
                                    <div style={{ display: "flex", flexDirection: "column", gap: 2, overflow: "hidden" }}>
                                        {dayChanges.slice(0, viewMode === "Week" ? 8 : 3).map(c => (
                                            <motion.div
                                                key={c.id}
                                                whileHover={{ scale: 1.04, boxShadow: "0 2px 8px rgba(0,0,0,0.15)" }}
                                                onClick={(e) => { e.stopPropagation(); openChange(c); }}
                                                style={{
                                                    background: riskGradients[c.riskLevel] || riskGradients.medium,
                                                    borderRadius: 5,
                                                    padding: "2px 6px",
                                                    cursor: "pointer",
                                                    overflow: "hidden",
                                                    whiteSpace: "nowrap",
                                                    textOverflow: "ellipsis",
                                                }}
                                            >
                                                <Text style={{ fontSize: 10, color: "#fff", fontWeight: 600 }}>{c.changeNumber || c.title}</Text>
                                            </motion.div>
                                        ))}
                                        {dayChanges.length > (viewMode === "Week" ? 8 : 3) && (
                                            <Text style={{ fontSize: 9, color: isDark ? "rgba(255,255,255,0.45)" : "#999", textAlign: "center" }}>
                                                +{dayChanges.length - (viewMode === "Week" ? 8 : 3)} more
                                            </Text>
                                        )}
                                    </div>
                                </motion.div>
                            );
                        })}
                    </div>
                </div>

                {/* Legend */}
                <div style={{ display: "flex", gap: 16, marginTop: 14, flexWrap: "wrap", alignItems: "center" }}>
                    <Text style={{ fontSize: 11, color: isDark ? "rgba(255,255,255,0.45)" : "#999" }}>Risk:</Text>
                    {Object.entries(riskColors).map(([k, c]) => (
                        <div key={k} style={{ display: "flex", alignItems: "center", gap: 4 }}>
                            <div style={{ width: 14, height: 8, borderRadius: 4, background: riskGradients[k] }} />
                            <Text style={{ fontSize: 11, textTransform: "capitalize", color: isDark ? "rgba(255,255,255,0.6)" : "#666" }}>{k}</Text>
                        </div>
                    ))}
                    <div style={{ display: "flex", alignItems: "center", gap: 4, marginLeft: 12 }}>
                        <div style={{ width: 14, height: 8, borderRadius: 4, background: "rgba(245,34,45,0.2)", border: "1px solid rgba(245,34,45,0.4)" }} />
                        <Text style={{ fontSize: 11, color: isDark ? "rgba(255,255,255,0.6)" : "#666" }}>Freeze Window</Text>
                    </div>
                </div>
            </motion.div>

            {/* Change Details Drawer */}
            <Drawer
                title={selected ? <Space><SwapOutlined /> {selected.changeNumber}</Space> : "Change Details"}
                open={drawerOpen}
                onClose={() => setDrawerOpen(false)}
                width={420}
            >
                {selected && (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }}>
                        <div style={{ marginBottom: 16 }}>
                            <Text strong style={{ fontSize: 18, display: "block", marginBottom: 8 }}>{selected.title}</Text>
                            <Space wrap>
                                <Tag color={statusColors[selected.status]}>{(selected.status || "").replace(/_/g, " ").toUpperCase()}</Tag>
                                <Tag color={typeColors[selected.changeType]}>{(selected.changeType || "").toUpperCase()}</Tag>
                            </Space>
                        </div>

                        <Card size="small" style={{ ...glass, marginBottom: 12 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                                <Text style={{ fontSize: 12, color: isDark ? "rgba(255,255,255,0.5)" : "#999" }}>Risk Level</Text>
                                <Tag color={riskColors[selected.riskLevel]} style={{ fontWeight: 700 }}>
                                    {(selected.riskLevel || "").toUpperCase()}
                                </Tag>
                            </div>
                            {selected.approvalStatus && (
                                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                    <Text style={{ fontSize: 12, color: isDark ? "rgba(255,255,255,0.5)" : "#999" }}>Approval</Text>
                                    <Tag color={selected.approvalStatus === "approved" ? "green" : selected.approvalStatus === "rejected" ? "red" : "orange"}>
                                        {(selected.approvalStatus || "").toUpperCase()}
                                    </Tag>
                                </div>
                            )}
                        </Card>

                        {[
                            { label: "Scheduled Start", value: selected.scheduledStart ? dayjs(selected.scheduledStart).format("ddd, MMM D YYYY HH:mm") : "—" },
                            { label: "Scheduled End", value: selected.scheduledEnd ? dayjs(selected.scheduledEnd).format("ddd, MMM D YYYY HH:mm") : "—" },
                            { label: "Implementor", value: selected.implementor || "—" },
                        ].map((item, i) => (
                            <div key={i} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: `1px solid ${isDark ? "rgba(255,255,255,0.06)" : "#f0f0f0"}` }}>
                                <Text style={{ fontSize: 12, color: isDark ? "rgba(255,255,255,0.5)" : "#999" }}>{item.label}</Text>
                                <Text strong style={{ fontSize: 13 }}>{item.value}</Text>
                            </div>
                        ))}

                        {selected.impactAssessment && (
                            <div style={{ marginTop: 16 }}>
                                <Text strong style={{ fontSize: 13, display: "block", marginBottom: 6 }}>Impact Assessment</Text>
                                <div style={{ padding: 12, borderRadius: 8, background: isDark ? "rgba(255,255,255,0.04)" : "#f9fafb", fontSize: 13 }}>
                                    {selected.impactAssessment}
                                </div>
                            </div>
                        )}

                        {selected.rollbackPlan && (
                            <div style={{ marginTop: 16 }}>
                                <Text strong style={{ fontSize: 13, display: "block", marginBottom: 6 }}>Rollback Plan</Text>
                                <div style={{ padding: 12, borderRadius: 8, background: isDark ? "rgba(255,255,255,0.04)" : "#f9fafb", fontSize: 13 }}>
                                    {selected.rollbackPlan}
                                </div>
                            </div>
                        )}
                    </motion.div>
                )}
            </Drawer>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Switch, DatePicker, Typography, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, SwapOutlined, FileProtectOutlined, ScheduleOutlined, TeamOutlined, CheckCircleOutlined, ExclamationCircleOutlined, ClockCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_CHANGES = `query($status: String, $changeType: String, $search: String) { itsmChanges(status: $status, changeType: $changeType, search: $search) { id changeNumber title description categoryId changeType priority riskLevel status impact implementationPlan rollbackPlan testPlan scheduledStart scheduledEnd cabRequired cabDecision cabNotes cabDate requestedBy assignedTo assignedGroup reviewNotes createdAt } }`;
const GET_CATEGORIES = `query { itsmCategories { id name } }`;
const CREATE_CHANGE = `mutation($tenantId: String!, $input: CreateItsmChangeInput!) { createItsmChange(tenantId: $tenantId, input: $input) { id changeNumber } }`;
const UPDATE_CHANGE = `mutation($id: ID!, $input: UpdateItsmChangeInput!) { updateItsmChange(id: $id, input: $input) { id } }`;
const DELETE_CHANGE = `mutation($id: ID!) { deleteItsmChange(id: $id) }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
const riskColors: Record<string, string> = { low: 'green', medium: 'blue', high: 'orange', critical: 'red' };
const typeColors: Record<string, string> = { standard: 'green', normal: 'blue', emergency: 'red' };
const statusColors: Record<string, string> = {
    draft: 'default', submitted: 'blue', under_review: 'cyan', approved: 'green',
    scheduled: 'geekblue', implementing: 'orange', completed: 'green', failed: 'red', cancelled: 'default',
};

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "description", label: "Description" },
    { name: "changeType", label: "Change Type" },
    { name: "priority", label: "Priority" },
    { name: "riskLevel", label: "Risk Level" },
];

export default function ItsmChangesPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterType, setFilterType] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [d, c] = await Promise.all([gql(GET_CHANGES, { status: filterStatus, changeType: filterType }), gql(GET_CATEGORIES)]);
            setData(d.itsmChanges || []);
            setCategories(c.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterType, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const input: any = {
                title: values.title, description: values.description, categoryId: values.categoryId,
                changeType: values.changeType || 'normal', priority: values.priority || 'medium',
                riskLevel: values.riskLevel || 'medium', impact: values.impact || 'medium',
                implementationPlan: values.implementationPlan, rollbackPlan: values.rollbackPlan,
                testPlan: values.testPlan, cabRequired: values.cabRequired ?? true,
                requestedBy: values.requestedBy, assignedTo: values.assignedTo, assignedGroup: values.assignedGroup,
            };
            if (editing) {
                input.status = values.status;
                input.cabDecision = values.cabDecision;
                input.cabNotes = values.cabNotes;
                input.reviewNotes = values.reviewNotes;
                await gql(UPDATE_CHANGE, { id: editing.id, input });
                messageApi.success("Change updated.");
            } else {
                const d = await gql(CREATE_CHANGE, { tenantId: DEFAULT_TENANT_ID, input });
                messageApi.success(`Change ${d.createItsmChange.changeNumber} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_CHANGE, { id }); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'changeNumber', width: 110, render: (_, r) => <Tag color="geekblue" style={{ fontFamily: 'monospace' }}>{r.changeNumber}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Type', dataIndex: 'changeType', width: 100, render: (_, r) => <Tag color={typeColors[r.changeType]}>{(r.changeType || '').toUpperCase()}</Tag> },
        { title: 'Priority', dataIndex: 'priority', width: 90, render: (_, r) => <Tag color={priorityColors[r.priority]}>{(r.priority || '').toUpperCase()}</Tag> },
        { title: 'Risk', dataIndex: 'riskLevel', width: 80, render: (_, r) => <Tag color={riskColors[r.riskLevel]}>{(r.riskLevel || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 130, render: (_, r) => <Tag color={statusColors[r.status]}>{(r.status || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'CAB', dataIndex: 'cabRequired', width: 70, render: (_, r) => r.cabRequired ? <Tag color="purple">Yes</Tag> : <Tag>No</Tag> },
        { title: 'Assigned', dataIndex: 'assignedTo', width: 130, ellipsis: true },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Change Management</AuroraText>}
            subTitle={<DecryptedText text="Plan, review, and implement changes" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Changes', value: data.length, icon: <SwapOutlined />, color: '#3b82f6' },
                    { title: 'Approved', value: data.filter((d: any) => d.status === 'approved' || d.status === 'implemented').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Emergency', value: data.filter((d: any) => d.changeType === 'emergency').length, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'Pending Review', value: data.filter((d: any) => d.status === 'pending' || d.status === 'submitted').length, icon: <ClockCircleOutlined />, color: '#f59e0b' },
                    { title: 'Success Rate', value: data.length > 0 ? `${Math.round((data.filter((d: any) => d.status === 'implemented' || d.status === 'closed').length / data.length) * 100)}%` : '—', icon: <CheckCircleOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <ProTable
                headerTitle={<Space><SwapOutlined /> Change Requests <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 150 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'draft', label: 'Draft' }, { value: 'submitted', label: 'Submitted' }, { value: 'under_review', label: 'Under Review' }, { value: 'approved', label: 'Approved' }, { value: 'scheduled', label: 'Scheduled' }, { value: 'implementing', label: 'Implementing' }, { value: 'completed', label: 'Completed' }, { value: 'failed', label: 'Failed' }]} />,
                    <Select key="ft" placeholder="Type" allowClear style={{ width: 120 }} value={filterType} onChange={setFilterType}
                        options={[{ value: 'standard', label: 'Standard' }, { value: 'normal', label: 'Normal' }, { value: 'emergency', label: 'Emergency' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Change</Button>,
                    <RbacGuard requiredRole="manager"><Tooltip key="excel" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => {
                        exportToExcel({
                            fileName: 'itsm_changes',
                            title: 'Change Management Report',
                            dateRange: { start: startDate, end: endDate },
                            columns: [
                                { header: 'Change #', key: 'changeNumber' },
                                { header: 'Title', key: 'title' },
                                { header: 'Type', key: 'changeType' },
                                { header: 'Priority', key: 'priority' },
                                { header: 'Risk', key: 'riskLevel' },
                                { header: 'Status', key: 'status', format: v => (v || '').replace(/_/g, ' ') },
                                { header: 'Assigned To', key: 'assignedTo' },
                            ],
                            data,
                        });
                    }} /></Tooltip>, <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => {
                        exportToPdf({
                            fileName: 'itsm_changes',
                            title: 'Change Management Report',
                            dateRange: { start: startDate, end: endDate },
                            columns: [
                                { header: 'Change #', key: 'changeNumber' },
                                { header: 'Title', key: 'title' },
                                { header: 'Type', key: 'changeType' },
                                { header: 'Priority', key: 'priority' },
                                { header: 'Risk', key: 'riskLevel' },
                                { header: 'Status', key: 'status', format: v => (v || '').replace(/_/g, ' ') },
                                { header: 'Assigned To', key: 'assignedTo' },
                            ],
                            data,
                        });
                    }} /></Tooltip></RbacGuard>,
                ]}
            />

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? `Edit ${editing.changeNumber}` : "New Change Request"}
                entityName="change"
                steps={[
                    {
                        title: "Change Details",
                        icon: <SwapOutlined />,
                        fields: ["title", "description"],
                        content: (
                            <>
                                <Form.Item name="title" label="Change Title" rules={[{ required: true }]}><Input placeholder="What is being changed?" /></Form.Item>
                                <Form.Item name="description" label="Description"><Input.TextArea rows={4} placeholder="Detailed change description, reason, and expected outcome" /></Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Classification & Risk",
                        icon: <FileProtectOutlined />,
                        fields: ["changeType", "categoryId", "priority", "riskLevel", "impact", "cabRequired"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={8}>
                                        <Form.Item name="changeType" label="Change Type">
                                            <Select options={[{ value: 'standard', label: '📋 Standard' }, { value: 'normal', label: '🔄 Normal' }, { value: 'emergency', label: '🚨 Emergency' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={8}>
                                        <Form.Item name="priority" label="Priority">
                                            <Select options={[{ value: 'critical', label: '🔴 Critical' }, { value: 'high', label: '🟠 High' }, { value: 'medium', label: '🔵 Medium' }, { value: 'low', label: '🟢 Low' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={8}>
                                        <Form.Item name="riskLevel" label="Risk Level">
                                            <Select options={[{ value: 'low', label: '🟢 Low' }, { value: 'medium', label: '🔵 Medium' }, { value: 'high', label: '🟠 High' }, { value: 'critical', label: '🔴 Critical' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="categoryId" label="Category">
                                            <Select placeholder="Select" allowClear options={categories.map(c => ({ value: c.id, label: c.name }))} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="cabRequired" label="CAB Required?" valuePropName="checked"><Switch defaultChecked /></Form.Item>
                                    </Col>
                                </Row>
                                {editing && (
                                    <>
                                        <Form.Item name="status" label="Status">
                                            <Select options={[
                                                { value: 'draft', label: 'Draft' }, { value: 'submitted', label: 'Submitted' },
                                                { value: 'under_review', label: 'Under Review' }, { value: 'approved', label: 'Approved' },
                                                { value: 'scheduled', label: 'Scheduled' }, { value: 'implementing', label: 'Implementing' },
                                                { value: 'completed', label: 'Completed' }, { value: 'failed', label: 'Failed' }, { value: 'cancelled', label: 'Cancelled' },
                                            ]} />
                                        </Form.Item>
                                        <Row gutter={16}>
                                            <Col span={12}><Form.Item name="cabDecision" label="CAB Decision"><Select allowClear options={[{ value: 'approved', label: 'Approved' }, { value: 'rejected', label: 'Rejected' }, { value: 'deferred', label: 'Deferred' }]} /></Form.Item></Col>
                                            <Col span={12}><Form.Item name="cabNotes" label="CAB Notes"><Input /></Form.Item></Col>
                                        </Row>
                                    </>
                                )}
                            </>
                        ),
                    },
                    {
                        title: "Plans",
                        icon: <ScheduleOutlined />,
                        fields: ["implementationPlan", "rollbackPlan", "testPlan"],
                        content: (
                            <>
                                <Form.Item name="implementationPlan" label="Implementation Plan"><Input.TextArea rows={3} placeholder="Step-by-step implementation procedure" /></Form.Item>
                                <Form.Item name="rollbackPlan" label="Rollback Plan"><Input.TextArea rows={3} placeholder="How to revert if the change fails" /></Form.Item>
                                <Form.Item name="testPlan" label="Test Plan"><Input.TextArea rows={3} placeholder="How will success be validated?" /></Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Assignment",
                        icon: <TeamOutlined />,
                        fields: ["requestedBy", "assignedTo", "assignedGroup"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}><Form.Item name="requestedBy" label="Requested By"><Input placeholder="Requester name" /></Form.Item></Col>
                                    <Col span={12}><Form.Item name="assignedTo" label="Assigned To"><Input placeholder="Implementer" /></Form.Item></Col>
                                </Row>
                                <Form.Item name="assignedGroup" label="Implementation Team"><Input placeholder="e.g., Change Management Team" /></Form.Item>
                                {editing && (
                                    <Form.Item name="reviewNotes" label="Review Notes"><Input.TextArea rows={2} placeholder="Post-implementation review" /></Form.Item>
                                )}
                            </>
                        ),
                    },
                ]}
                fields={FIELDS}
                width={800}
                gradient={["#2f54eb", "#1d39c4"]}
                editMode={!!editing}
                initialValues={{ changeType: 'normal', priority: 'medium', riskLevel: 'medium', cabRequired: true }}
            />
        </div>
        </CMSLayout>
    );
}

