"use client";

import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { Input, Checkbox, Tag, Badge } from "antd";
import { AimOutlined, SearchOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { useTheme } from "next-themes";
import { usePreferencesStore } from "@/store/usePreferencesStore";

/* ── Colour Maps ────────────────────────────────────────────── */
const CLASS_COLORS: Record<string, string> = {
    server: "#3b82f6", database: "#10b981", application: "#8b5cf6",
    network: "#f97316", storage: "#06b6d4", service: "#ec4899",
};
const CLASS_ICONS: Record<string, string> = {
    server: "🖥", database: "🗄", application: "⚙",
    network: "🌐", storage: "💾", service: "🔗",
};
const REL_COLORS: Record<string, string> = {
    depends_on: "#f59e0b", runs_on: "#3b82f6", connects_to: "#10b981", hosts: "#8b5cf6",
};
const STATUS_DOT: Record<string, string> = { active: "#10b981", inactive: "#6b7280", maintenance: "#f59e0b" };

/* ── Types ──────────────────────────────────────────────────── */
interface TopologyViewerProps {
    configItems: any[];
    relationships: any[];
    onSelectCI?: (ciId: string) => void;
}
interface Node { id: string; x: number; y: number; vx: number; vy: number; r: number; ci: any; }
interface Edge { source: string; target: string; type: string; }

/* ── Force‑directed helpers ─────────────────────────────────── */
function buildGraph(items: any[], rels: any[]): { nodes: Node[]; edges: Edge[] } {
    const degMap = new Map<string, number>();
    rels.forEach(r => { degMap.set(r.sourceId, (degMap.get(r.sourceId) || 0) + 1); degMap.set(r.targetId, (degMap.get(r.targetId) || 0) + 1); });
    const nodes: Node[] = items.map((ci, i) => {
        const angle = (2 * Math.PI * i) / items.length;
        const spread = Math.min(items.length * 18, 220);
        return { id: ci.id, x: 400 + Math.cos(angle) * spread, y: 250 + Math.sin(angle) * spread, vx: 0, vy: 0, r: Math.max(16, Math.min(32, 14 + (degMap.get(ci.id) || 0) * 4)), ci };
    });
    const edges: Edge[] = rels.map(r => ({ source: r.sourceId, target: r.targetId, type: r.type || "depends_on" }));
    return { nodes, edges };
}

function simulate(nodes: Node[], edges: Edge[], iterations: number) {
    const nodeMap = new Map(nodes.map(n => [n.id, n]));
    for (let iter = 0; iter < iterations; iter++) {
        const alpha = 1 - iter / iterations;
        // Repulsion
        for (let i = 0; i < nodes.length; i++) {
            for (let j = i + 1; j < nodes.length; j++) {
                let dx = nodes[j].x - nodes[i].x, dy = nodes[j].y - nodes[i].y;
                const dist = Math.sqrt(dx * dx + dy * dy) || 1;
                const force = (800 * alpha) / (dist * dist);
                const fx = (dx / dist) * force, fy = (dy / dist) * force;
                nodes[i].vx -= fx; nodes[i].vy -= fy;
                nodes[j].vx += fx; nodes[j].vy += fy;
            }
        }
        // Attraction along edges
        edges.forEach(e => {
            const s = nodeMap.get(e.source), t = nodeMap.get(e.target);
            if (!s || !t) return;
            let dx = t.x - s.x, dy = t.y - s.y;
            const dist = Math.sqrt(dx * dx + dy * dy) || 1;
            const force = (dist - 100) * 0.04 * alpha;
            const fx = (dx / dist) * force, fy = (dy / dist) * force;
            s.vx += fx; s.vy += fy;
            t.vx -= fx; t.vy -= fy;
        });
        // Center gravity
        nodes.forEach(n => { n.vx += (400 - n.x) * 0.01 * alpha; n.vy += (250 - n.y) * 0.01 * alpha; });
        // Apply velocity
        nodes.forEach(n => { n.x += n.vx * 0.6; n.y += n.vy * 0.6; n.vx *= 0.85; n.vy *= 0.85; });
    }
}

/* ── Component ──────────────────────────────────────────────── */
export default function TopologyViewer({ configItems, relationships, onSelectCI }: TopologyViewerProps) {
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === "dark";

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [hoveredId, setHoveredId] = useState<string | null>(null);
    const [tooltip, setTooltip] = useState<{ x: number; y: number; ci: any } | null>(null);
    const [search, setSearch] = useState("");
    const [classFilters, setClassFilters] = useState<string[]>(Object.keys(CLASS_COLORS));
    const [statusFilter, setStatusFilter] = useState<string[]>(["active", "inactive", "maintenance"]);
    const [zoom, setZoom] = useState(1);
    const [pan, setPan] = useState({ x: 0, y: 0 });
    const dragging = useRef(false);
    const lastMouse = useRef({ x: 0, y: 0 });

    /* ── Filtered items ────────────────────────────────────── */
    const filtered = useMemo(() => {
        const lc = search.toLowerCase();
        return configItems.filter(ci =>
            classFilters.includes(ci.ciClass || ci.ci_class || "server") &&
            statusFilter.includes(ci.status || "active") &&
            (!lc || (ci.name || "").toLowerCase().includes(lc))
        );
    }, [configItems, classFilters, statusFilter, search]);

    const filteredIds = useMemo(() => new Set(filtered.map(ci => ci.id)), [filtered]);
    const filteredRels = useMemo(() => relationships.filter(r => filteredIds.has(r.sourceId) && filteredIds.has(r.targetId)), [relationships, filteredIds]);

    /* ── Graph layout (computed once per filter change) ───── */
    const { nodes, edges } = useMemo(() => {
        const g = buildGraph(filtered, filteredRels);
        simulate(g.nodes, g.edges, 120);
        return g;
    }, [filtered, filteredRels]);

    const nodeMap = useMemo(() => new Map(nodes.map(n => [n.id, n])), [nodes]);

    /* ── Stats ──────────────────────────────────────────────── */
    const classBreakdown = useMemo(() => {
        const m: Record<string, number> = {};
        filtered.forEach(ci => { const c = ci.ciClass || ci.ci_class || "server"; m[c] = (m[c] || 0) + 1; });
        return m;
    }, [filtered]);

    /* ── Canvas draw ────────────────────────────────────────── */
    const draw = useCallback(() => {
        const cvs = canvasRef.current; if (!cvs) return;
        const ctx = cvs.getContext("2d"); if (!ctx) return;
        const w = cvs.width, h = cvs.height;
        ctx.clearRect(0, 0, w, h);
        ctx.save();
        ctx.translate(pan.x + w / 2, pan.y + h / 2);
        ctx.scale(zoom, zoom);
        ctx.translate(-w / 2, -h / 2);

        const isSelection = selectedId !== null;

        // Draw edges
        edges.forEach(e => {
            const s = nodeMap.get(e.source), t = nodeMap.get(e.target);
            if (!s || !t) return;
            const connected = !isSelection || e.source === selectedId || e.target === selectedId;
            ctx.globalAlpha = connected ? 0.7 : 0.1;
            ctx.strokeStyle = REL_COLORS[e.type] || "#6b7280";
            ctx.lineWidth = connected ? 2 : 1;
            ctx.beginPath(); ctx.moveTo(s.x, s.y); ctx.lineTo(t.x, t.y); ctx.stroke();
            // Arrowhead
            const angle = Math.atan2(t.y - s.y, t.x - s.x);
            const aLen = 8, ax = t.x - Math.cos(angle) * t.r, ay = t.y - Math.sin(angle) * t.r;
            ctx.beginPath();
            ctx.moveTo(ax, ay);
            ctx.lineTo(ax - aLen * Math.cos(angle - 0.4), ay - aLen * Math.sin(angle - 0.4));
            ctx.lineTo(ax - aLen * Math.cos(angle + 0.4), ay - aLen * Math.sin(angle + 0.4));
            ctx.closePath();
            ctx.fillStyle = REL_COLORS[e.type] || "#6b7280"; ctx.fill();
        });

        ctx.globalAlpha = 1;

        // Draw nodes
        nodes.forEach(n => {
            const ciClass = n.ci.ciClass || n.ci.ci_class || "server";
            const color = CLASS_COLORS[ciClass] || "#6b7280";
            const isSelected = n.id === selectedId;
            const isHovered = n.id === hoveredId;
            const connected = !isSelection || isSelected || edges.some(e => (e.source === selectedId && e.target === n.id) || (e.target === selectedId && e.source === n.id));
            ctx.globalAlpha = connected ? 1 : 0.2;

            // Glow
            if (isSelected || isHovered) {
                ctx.shadowColor = color;
                ctx.shadowBlur = isSelected ? 18 : 10;
            }

            // Node body
            ctx.beginPath(); ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
            ctx.fillStyle = isDark ? `${color}33` : `${color}22`;
            ctx.fill();
            ctx.strokeStyle = isSelected ? themeColor : color;
            ctx.lineWidth = isSelected ? 3 : 1.5;
            ctx.stroke();
            ctx.shadowBlur = 0;

            // Icon
            ctx.font = `${n.r * 0.7}px sans-serif`;
            ctx.textAlign = "center"; ctx.textBaseline = "middle";
            ctx.fillStyle = color;
            ctx.fillText(CLASS_ICONS[ciClass] || "●", n.x, n.y);

            // Status dot
            const status = n.ci.status || "active";
            ctx.beginPath(); ctx.arc(n.x + n.r * 0.65, n.y - n.r * 0.65, 4, 0, Math.PI * 2);
            ctx.fillStyle = STATUS_DOT[status] || "#6b7280"; ctx.fill();
            ctx.strokeStyle = isDark ? "#1a1a2e" : "#ffffff"; ctx.lineWidth = 1.5; ctx.stroke();

            // Label
            ctx.font = "10px Inter, sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "top";
            ctx.fillStyle = isDark ? "#cbd5e1" : "#374151";
            const label = (n.ci.name || "").length > 14 ? (n.ci.name || "").slice(0, 12) + "…" : (n.ci.name || "");
            ctx.fillText(label, n.x, n.y + n.r + 4);
        });

        ctx.globalAlpha = 1;
        ctx.restore();
    }, [nodes, edges, nodeMap, selectedId, hoveredId, zoom, pan, isDark, themeColor]);

    useEffect(() => { const id = requestAnimationFrame(draw); return () => cancelAnimationFrame(id); }, [draw]);

    /* ── Hit‑test ────────────────────────────────────────────── */
    const hitTest = useCallback((cx: number, cy: number) => {
        const cvs = canvasRef.current; if (!cvs) return null;
        const w = cvs.width, h = cvs.height;
        const wx = (cx - pan.x - w / 2) / zoom + w / 2;
        const wy = (cy - pan.y - h / 2) / zoom + h / 2;
        for (const n of nodes) {
            const dx = wx - n.x, dy = wy - n.y;
            if (dx * dx + dy * dy <= n.r * n.r) return n;
        }
        return null;
    }, [nodes, zoom, pan]);

    /* ── Mouse handlers ─────────────────────────────────────── */
    const onMouseDown = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
        const rect = canvasRef.current?.getBoundingClientRect(); if (!rect) return;
        const cx = e.clientX - rect.left, cy = e.clientY - rect.top;
        const hit = hitTest(cx, cy);
        if (hit) { setSelectedId(prev => prev === hit.id ? null : hit.id); onSelectCI?.(hit.id); }
        else { dragging.current = true; lastMouse.current = { x: e.clientX, y: e.clientY }; }
    }, [hitTest, onSelectCI]);

    const onMouseMove = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
        if (dragging.current) {
            setPan(p => ({ x: p.x + e.clientX - lastMouse.current.x, y: p.y + e.clientY - lastMouse.current.y }));
            lastMouse.current = { x: e.clientX, y: e.clientY }; return;
        }
        const rect = canvasRef.current?.getBoundingClientRect(); if (!rect) return;
        const cx = e.clientX - rect.left, cy = e.clientY - rect.top;
        const hit = hitTest(cx, cy);
        setHoveredId(hit?.id ?? null);
        if (hit) { setTooltip({ x: e.clientX - rect.left + 12, y: e.clientY - rect.top - 10, ci: hit.ci }); }
        else { setTooltip(null); }
    }, [hitTest]);

    const onMouseUp = useCallback(() => { dragging.current = false; }, []);
    const onWheel = useCallback((e: React.WheelEvent) => { e.preventDefault(); setZoom(z => Math.max(0.3, Math.min(3, z - e.deltaY * 0.001))); }, []);
    const resetView = useCallback(() => { setZoom(1); setPan({ x: 0, y: 0 }); setSelectedId(null); }, []);

    /* ── Resize observer ────────────────────────────────────── */
    const containerRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        const resize = () => {
            const cvs = canvasRef.current, ctr = containerRef.current;
            if (!cvs || !ctr) return;
            cvs.width = ctr.clientWidth;
            cvs.height = 500;
            draw();
        };
        resize();
        window.addEventListener("resize", resize);
        return () => window.removeEventListener("resize", resize);
    }, [draw]);

    /* ── Glass style ────────────────────────────────────────── */
    const glass: React.CSSProperties = {
        background: isDark ? "rgba(15,15,23,0.55)" : "rgba(255,255,255,0.65)",
        backdropFilter: "blur(12px)", border: isDark ? "1px solid rgba(139,92,246,0.15)" : "1px solid rgba(0,0,0,0.08)",
        borderRadius: 12, padding: 10,
    };
    const panelGlass: React.CSSProperties = {
        ...glass, position: "absolute" as const, top: 10, right: 10, zIndex: 5, maxWidth: 220, fontSize: 11,
    };

    return (
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35 }}>
            {/* Stats Bar */}
            <div style={{ display: "flex", gap: 12, marginBottom: 10, flexWrap: "wrap" }}>
                {[
                    { label: "CIs", value: filtered.length, color: themeColor },
                    { label: "Relationships", value: filteredRels.length, color: "#f59e0b" },
                    ...Object.entries(classBreakdown).map(([k, v]) => ({ label: k, value: v, color: CLASS_COLORS[k] || "#6b7280" })),
                ].map((s, i) => (
                    <Tag key={i} style={{ margin: 0, borderRadius: 8, border: "none", background: isDark ? `${s.color}18` : `${s.color}14`, color: s.color, fontWeight: 600, fontSize: 11 }}>
                        {s.label}: {s.value}
                    </Tag>
                ))}
            </div>

            {/* Canvas container */}
            <div ref={containerRef} style={{ position: "relative", borderRadius: 14, overflow: "hidden", border: isDark ? "1px solid rgba(139,92,246,0.12)" : "1px solid rgba(0,0,0,0.08)", background: isDark ? "#0d0d1a" : "#f8fafc" }}>
                <canvas ref={canvasRef} height={500} style={{ display: "block", cursor: dragging.current ? "grabbing" : hoveredId ? "pointer" : "grab" }}
                    onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={() => { dragging.current = false; setTooltip(null); setHoveredId(null); }}
                    onWheel={onWheel} />

                {/* Tooltip */}
                {tooltip && (
                    <div style={{ ...glass, position: "absolute", left: tooltip.x, top: tooltip.y, zIndex: 10, pointerEvents: "none", padding: "8px 12px", fontSize: 11, minWidth: 150 }}>
                        <div style={{ fontWeight: 700, marginBottom: 3, color: isDark ? "#e2e8f0" : "#1e293b" }}>{tooltip.ci.name}</div>
                        <div style={{ color: isDark ? "#94a3b8" : "#64748b" }}>Class: <span style={{ color: CLASS_COLORS[tooltip.ci.ciClass || tooltip.ci.ci_class] || "#6b7280" }}>{tooltip.ci.ciClass || tooltip.ci.ci_class || "—"}</span></div>
                        <div style={{ color: isDark ? "#94a3b8" : "#64748b" }}>Status: {tooltip.ci.status || "—"}</div>
                        <div style={{ color: isDark ? "#94a3b8" : "#64748b" }}>Env: {tooltip.ci.environment || "—"}</div>
                        <div style={{ color: isDark ? "#94a3b8" : "#64748b" }}>IP: {tooltip.ci.ip_address || tooltip.ci.ipAddress || "—"}</div>
                    </div>
                )}

                {/* Control panel */}
                <div style={panelGlass}>
                    <Input size="small" prefix={<SearchOutlined style={{ color: isDark ? "#64748b" : "#9ca3af" }} />}
                        placeholder="Search CI…" value={search} onChange={e => setSearch(e.target.value)}
                        style={{ marginBottom: 8, borderRadius: 6, background: "transparent", fontSize: 11 }} allowClear />

                    <div style={{ fontSize: 10, fontWeight: 600, color: isDark ? "#94a3b8" : "#6b7280", marginBottom: 4, textTransform: "uppercase", letterSpacing: 0.5 }}>CI Class</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 2, marginBottom: 8 }}>
                        {Object.entries(CLASS_COLORS).map(([cls, clr]) => (
                            <Checkbox key={cls} checked={classFilters.includes(cls)} onChange={e => setClassFilters(prev => e.target.checked ? [...prev, cls] : prev.filter(c => c !== cls))}
                                style={{ fontSize: 11, color: isDark ? "#cbd5e1" : "#374151" }}>
                                <span style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
                                    <span style={{ width: 8, height: 8, borderRadius: "50%", background: clr, display: "inline-block" }} />
                                    {cls}
                                </span>
                            </Checkbox>
                        ))}
                    </div>

                    <div style={{ fontSize: 10, fontWeight: 600, color: isDark ? "#94a3b8" : "#6b7280", marginBottom: 4, textTransform: "uppercase", letterSpacing: 0.5 }}>Status</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 2, marginBottom: 8 }}>
                        {["active", "inactive", "maintenance"].map(s => (
                            <Checkbox key={s} checked={statusFilter.includes(s)} onChange={e => setStatusFilter(prev => e.target.checked ? [...prev, s] : prev.filter(x => x !== s))}
                                style={{ fontSize: 11, color: isDark ? "#cbd5e1" : "#374151" }}>
                                <Badge color={STATUS_DOT[s]} text={<span style={{ fontSize: 11, color: isDark ? "#cbd5e1" : "#374151" }}>{s}</span>} />
                            </Checkbox>
                        ))}
                    </div>

                    <motion.button whileHover={{ scale: 1.04 }} whileTap={{ scale: 0.96 }} onClick={resetView}
                        style={{ width: "100%", padding: "4px 0", borderRadius: 6, border: "none", cursor: "pointer", fontSize: 11, fontWeight: 600, color: "#fff", background: `linear-gradient(135deg, ${themeColor}, #6366f1)` }}>
                        <AimOutlined /> Reset View
                    </motion.button>
                </div>

                {/* Legend */}
                <div style={{ ...glass, position: "absolute", bottom: 10, left: 10, zIndex: 5, display: "flex", gap: 14, fontSize: 10 }}>
                    <div>
                        <div style={{ fontWeight: 700, marginBottom: 3, color: isDark ? "#cbd5e1" : "#374151" }}>Classes</div>
                        {Object.entries(CLASS_COLORS).map(([k, v]) => (
                            <div key={k} style={{ display: "flex", alignItems: "center", gap: 4, color: isDark ? "#94a3b8" : "#64748b" }}>
                                <span style={{ width: 8, height: 8, borderRadius: "50%", background: v, display: "inline-block" }} />{k}
                            </div>
                        ))}
                    </div>
                    <div>
                        <div style={{ fontWeight: 700, marginBottom: 3, color: isDark ? "#cbd5e1" : "#374151" }}>Relations</div>
                        {Object.entries(REL_COLORS).map(([k, v]) => (
                            <div key={k} style={{ display: "flex", alignItems: "center", gap: 4, color: isDark ? "#94a3b8" : "#64748b" }}>
                                <span style={{ width: 14, height: 2, background: v, display: "inline-block", borderRadius: 1 }} />{k.replace(/_/g, " ")}
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </motion.div>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, InputNumber, Typography, Descriptions, Modal, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, ClusterOutlined, NodeIndexOutlined, DesktopOutlined, CloudServerOutlined, DatabaseOutlined, ApiOutlined, GlobalOutlined, CheckCircleOutlined, ExclamationCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { supaRest, supaInsert, supaUpdate, supaDelete } from "@/lib/supaRest";
import { gql } from "@/lib/graphql";
import TopologyViewer from "./components/TopologyViewer";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const classIcons: Record<string, React.ReactNode> = { hardware: <DesktopOutlined />, software: <CloudServerOutlined />, network: <GlobalOutlined />, service: <ApiOutlined />, cloud: <CloudServerOutlined />, document: <DatabaseOutlined />, virtual: <CloudServerOutlined /> };
const classColors: Record<string, string> = { hardware: 'blue', software: 'green', network: 'purple', service: 'cyan', cloud: 'geekblue', document: 'orange', virtual: 'magenta' };
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const statusColors: Record<string, string> = { active: 'green', under_maintenance: 'orange', retired: 'default', disposed: 'red', planned: 'blue' };
const critColors: Record<string, string> = { critical: 'red', high: 'orange', medium: 'blue', low: 'green' };

const FIELDS: FieldDef[] = [
    { name: "name", label: "Name", required: true },
    { name: "ci_class", label: "CI Class" },
    { name: "ci_type", label: "CI Type" },
    { name: "status", label: "Status" },
];

export default function CmdbPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [detailOpen, setDetailOpen] = useState(false);
    const [detailItem, setDetailItem] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterClass, setFilterClass] = useState<string | undefined>(undefined);
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [showTopology, setShowTopology] = useState(false);
    const [relationships, setRelationships] = useState<any[]>([]);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const filters: Record<string, string> = {};
            if (filterClass) filters['ci_class'] = `eq.${filterClass}`;
            if (filterStatus) filters['status'] = `eq.${filterStatus}`;
            const rows = await supaRest('itsm_configuration_items', { order: 'ci_number.asc', filters });
            setData(rows);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterClass, filterStatus, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    // Load CI relationships for topology viewer
    useEffect(() => {
        if (!showTopology) return;
        (async () => {
            try {
                const rels: any[] = [];
                for (const ci of data.slice(0, 20)) {
                    try {
                        const res = await gql(`query($ciId: ID!) { itsmCIRelationships(ciId: $ciId) }`, { ciId: ci.id });
                        const parsed = typeof res.itsmCIRelationships === 'string' ? JSON.parse(res.itsmCIRelationships) : (res.itsmCIRelationships || []);
                        if (Array.isArray(parsed)) rels.push(...parsed);
                    } catch { /* skip */ }
                }
                setRelationships(rels);
            } catch { /* ignore */ }
        })();
    }, [showTopology, data]);

    const handleSave = async (values: any) => {
        try {
            const body: any = { name: values.name, ci_class: values.ci_class || 'hardware', ci_type: values.ci_type, status: values.status || 'active', environment: values.environment || 'production', criticality: values.criticality || 'medium', location: values.location, department: values.department, owner: values.owner, vendor: values.vendor, manufacturer: values.manufacturer, model: values.model, serial_number: values.serial_number, ip_address: values.ip_address, os_info: values.os_info, version: values.version, cpu: values.cpu, memory_gb: values.memory_gb, storage_gb: values.storage_gb, notes: values.notes };
            if (editing) {
                await supaUpdate('itsm_configuration_items', editing.id, body);
                messageApi.success("CI updated.");
            } else {
                const seq = data.length > 0 ? Math.max(...data.map(d => parseInt(d.ci_number?.replace('CI-', '') || '0'))) + 1 : 1;
                body.ci_number = `CI-${String(seq).padStart(4, '0')}`;
                body.tenant_id = 'default';
                await supaInsert('itsm_configuration_items', body);
                messageApi.success(`CI ${body.ci_number} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => { 
        try { await supaDelete('itsm_configuration_items', id); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'ci_number', width: 100, render: (_, r) => <Tag color="geekblue" style={{ fontFamily: 'monospace' }}>{r.ci_number}</Tag> },
        { title: 'Name', dataIndex: 'name', ellipsis: true, render: (_, r) => <a onClick={() => { setDetailItem(r); setDetailOpen(true); }}>{r.name}</a> },
        { title: 'Class', dataIndex: 'ci_class', width: 110, render: (_, r) => <Tag icon={classIcons[r.ci_class]} color={classColors[r.ci_class]}>{(r.ci_class || '').toUpperCase()}</Tag> },
        { title: 'Type', dataIndex: 'ci_type', width: 120, ellipsis: true },
        { title: 'Status', dataIndex: 'status', width: 130, render: (_, r) => <Tag color={statusColors[r.status]}>{(r.status || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Criticality', dataIndex: 'criticality', width: 100, render: (_, r) => <Tag color={critColors[r.criticality]}>{(r.criticality || '').toUpperCase()}</Tag> },
        { title: 'Environment', dataIndex: 'environment', width: 110 },
        { title: 'IP Address', dataIndex: 'ip_address', width: 130, render: (_, r) => r.ip_address ? <Tag>{r.ip_address}</Tag> : '-' },
        { title: 'Owner', dataIndex: 'owner', width: 130, ellipsis: true },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete CI?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>CMDB</AuroraText>}
            subTitle={<DecryptedText text="Configuration Management Database â€” Track all IT assets and dependencies" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total CIs', value: data.length, icon: <ClusterOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: data.filter((d: any) => d.status === 'active' || d.status === 'deployed').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Critical', value: data.filter((d: any) => d.criticality === 'critical' || d.criticality === 'high').length, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'Hardware', value: data.filter((d: any) => d.ciClass === 'hardware').length, icon: <DesktopOutlined />, color: '#8b5cf6' },
                    { title: 'Software', value: data.filter((d: any) => d.ciClass === 'software').length, icon: <CloudServerOutlined />, color: '#06b6d4' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Topology Viewer */}
            {showTopology && (
                <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} style={{ marginBottom: 16 }}>
                    <Card size="small" title={<Space><NodeIndexOutlined style={{ color: themeColor }} /> CI Topology Map</Space>} style={{ ...glass, borderTop: `3px solid ${themeColor}` }}>
                        <TopologyViewer configItems={data} relationships={relationships} onSelectCI={(id) => { const ci = data.find((d: any) => d.id === id); if (ci) { setDetailItem(ci); setDetailOpen(true); } }} />
                    </Card>
                </motion.div>
            )}
            <ProTable
                headerTitle={<Space><ClusterOutlined /> Configuration Items <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <Select key="fc" placeholder="Class" allowClear style={{ width: 130 }} value={filterClass} onChange={setFilterClass}
                        options={[{ value: 'hardware', label: 'ðŸ’» Hardware' }, { value: 'software', label: 'âš™ï¸ Software' }, { value: 'network', label: 'ðŸŒ Network' }, { value: 'service', label: 'ðŸ”— Service' }, { value: 'cloud', label: 'â˜ï¸ Cloud' }]} />,
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 150 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'active', label: 'Active' }, { value: 'under_maintenance', label: 'Maintenance' }, { value: 'retired', label: 'Retired' }, { value: 'planned', label: 'Planned' }]} />,
                    <Button key="topo" type={showTopology ? 'primary' : 'default'} icon={<NodeIndexOutlined />} onClick={() => setShowTopology(!showTopology)}>{showTopology ? 'Hide Topology' : 'Show Topology'}</Button>,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New CI</Button>,
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_cmdb', title: 'CMDB Configuration Items', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Ci class', key: 'ci_class' }, { header: 'Ci type', key: 'ci_type' }, { header: 'Status', key: 'status' }, { header: 'Environment', key: 'environment' }, { header: 'Owner', key: 'owner' }], data: data })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_cmdb', title: 'CMDB Configuration Items', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Ci class', key: 'ci_class' }, { header: 'Ci type', key: 'ci_type' }, { header: 'Status', key: 'status' }, { header: 'Environment', key: 'environment' }, { header: 'Owner', key: 'owner' }], data: data })} /></Tooltip></RbacGuard>,
                ]}
            />

            <Modal title={detailItem?.ci_number + ' â€” ' + detailItem?.name} open={detailOpen} onCancel={() => setDetailOpen(false)} footer={null} width={700}>
                {detailItem && (
                    <Descriptions column={2} bordered size="small">
                        <Descriptions.Item label="CI Class">{detailItem.ci_class}</Descriptions.Item>
                        <Descriptions.Item label="CI Type">{detailItem.ci_type}</Descriptions.Item>
                        <Descriptions.Item label="Status"><Tag color={statusColors[detailItem.status]}>{detailItem.status}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Criticality"><Tag color={critColors[detailItem.criticality]}>{detailItem.criticality}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Environment">{detailItem.environment}</Descriptions.Item>
                        <Descriptions.Item label="Location">{detailItem.location || '-'}</Descriptions.Item>
                        <Descriptions.Item label="Owner">{detailItem.owner || '-'}</Descriptions.Item>
                        <Descriptions.Item label="Vendor">{detailItem.vendor || '-'}</Descriptions.Item>
                        <Descriptions.Item label="Model">{detailItem.model || '-'}</Descriptions.Item>
                        <Descriptions.Item label="Serial #">{detailItem.serial_number || '-'}</Descriptions.Item>
                        <Descriptions.Item label="IP Address">{detailItem.ip_address || '-'}</Descriptions.Item>
                        <Descriptions.Item label="OS">{detailItem.os_info || '-'}</Descriptions.Item>
                        <Descriptions.Item label="CPU">{detailItem.cpu || '-'}</Descriptions.Item>
                        <Descriptions.Item label="Memory">{detailItem.memory_gb ? `${detailItem.memory_gb} GB` : '-'}</Descriptions.Item>
                        <Descriptions.Item label="Storage">{detailItem.storage_gb ? `${detailItem.storage_gb} GB` : '-'}</Descriptions.Item>
                        <Descriptions.Item label="Warranty Expiry">{detailItem.warranty_expiry || '-'}</Descriptions.Item>
                        <Descriptions.Item label="Notes" span={2}>{detailItem.notes || '-'}</Descriptions.Item>
                    </Descriptions>
                )}
            </Modal>

            <SteppedFormModal open={modalOpen} onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? `Edit ${editing.ci_number}` : "New Configuration Item"} entityName="ci" steps={[
                { title: "Basic Info", icon: <ClusterOutlined />, fields: ["name", "ci_class", "ci_type", "status", "environment", "criticality"],
                    content: (<>
                        <Form.Item name="name" label="CI Name" rules={[{ required: true }]}><Input placeholder="e.g., PROD-DB-01 (PostgreSQL Primary)" /></Form.Item>
                        <Row gutter={16}>
                            <Col span={8}><Form.Item name="ci_class" label="Class"><Select options={[{ value: 'hardware', label: 'ðŸ’» Hardware' }, { value: 'software', label: 'âš™ï¸ Software' }, { value: 'network', label: 'ðŸŒ Network' }, { value: 'service', label: 'ðŸ”— Service' }, { value: 'cloud', label: 'â˜ï¸ Cloud' }]} /></Form.Item></Col>
                            <Col span={8}><Form.Item name="ci_type" label="Type"><Input placeholder="e.g., server, switch, database" /></Form.Item></Col>
                            <Col span={8}><Form.Item name="environment" label="Environment"><Select options={[{ value: 'production', label: 'Production' }, { value: 'staging', label: 'Staging' }, { value: 'development', label: 'Development' }, { value: 'dr', label: 'DR' }]} /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="status" label="Status"><Select options={[{ value: 'active', label: 'Active' }, { value: 'under_maintenance', label: 'Under Maintenance' }, { value: 'retired', label: 'Retired' }, { value: 'planned', label: 'Planned' }]} /></Form.Item></Col>
                            <Col span={12}><Form.Item name="criticality" label="Criticality"><Select options={[{ value: 'critical', label: 'ðŸ”´ Critical' }, { value: 'high', label: 'ðŸŸ  High' }, { value: 'medium', label: 'ðŸ”µ Medium' }, { value: 'low', label: 'ðŸŸ¢ Low' }]} /></Form.Item></Col>
                        </Row>
                    </>),
                },
                { title: "Technical", icon: <DesktopOutlined />, fields: ["ip_address", "os_info", "cpu", "memory_gb", "storage_gb", "serial_number", "model", "vendor"],
                    content: (<>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="ip_address" label="IP Address"><Input placeholder="10.0.1.50" /></Form.Item></Col>
                            <Col span={12}><Form.Item name="os_info" label="OS"><Input placeholder="Ubuntu 22.04 LTS" /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={8}><Form.Item name="cpu" label="CPU"><Input placeholder="8 vCPU" /></Form.Item></Col>
                            <Col span={8}><Form.Item name="memory_gb" label="Memory (GB)"><InputNumber style={{ width: '100%' }} /></Form.Item></Col>
                            <Col span={8}><Form.Item name="storage_gb" label="Storage (GB)"><InputNumber style={{ width: '100%' }} /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="vendor" label="Vendor"><Input /></Form.Item></Col>
                            <Col span={12}><Form.Item name="manufacturer" label="Manufacturer"><Input /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="model" label="Model"><Input /></Form.Item></Col>
                            <Col span={12}><Form.Item name="serial_number" label="Serial Number"><Input /></Form.Item></Col>
                        </Row>
                    </>),
                },
                { title: "Ownership", icon: <NodeIndexOutlined />, fields: ["owner", "department", "location", "notes"],
                    content: (<>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="owner" label="Owner"><Input /></Form.Item></Col>
                            <Col span={12}><Form.Item name="department" label="Department"><Input /></Form.Item></Col>
                        </Row>
                        <Form.Item name="location" label="Location"><Input placeholder="Jakarta DC-1 Rack A4" /></Form.Item>
                        <Form.Item name="notes" label="Notes"><Input.TextArea rows={3} /></Form.Item>
                    </>),
                },
            ]} fields={FIELDS} width={800} editMode={!!editing} initialValues={{ ci_class: 'hardware', status: 'active', environment: 'production', criticality: 'medium' }} />
        </div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, InputNumber, Descriptions, Modal, Typography, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, SafetyOutlined, FieldTimeOutlined, FileProtectOutlined, ExperimentOutlined, ExclamationCircleOutlined, CheckCircleOutlined, ClockCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { supaRest, supaInsert, supaUpdate, supaDelete } from "@/lib/supaRest";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const statusColors: Record<string, string> = { draft: 'default', active: 'green', under_review: 'blue', approved: 'green', expired: 'red', archived: 'gray' };
const typeColors: Record<string, string> = { bcp: 'blue', drp: 'red', crisis: 'volcano', itrp: 'purple' };
const priorityColors: Record<string, string> = { critical: 'red', high: 'orange', medium: 'blue', low: 'green' };

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "plan_type", label: "Plan Type" },
    { name: "status", label: "Status" },
];

export default function ContinuityPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [detailOpen, setDetailOpen] = useState(false);
    const [detailItem, setDetailItem] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterType, setFilterType] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const filters: Record<string, string> = {};
            if (filterType) filters['plan_type'] = `eq.${filterType}`;
            const rows = await supaRest('itsm_continuity_plans', { order: 'created_at.desc', filters });
            setData(rows);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterType, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const body: any = { title: values.title, plan_type: values.plan_type || 'bcp', description: values.description, scope: values.scope, rto_hours: values.rto_hours, rpo_hours: values.rpo_hours, mtpd_hours: values.mtpd_hours, recovery_priority: values.recovery_priority || 'medium', risk_assessment: values.risk_assessment, recovery_strategy: values.recovery_strategy, recovery_procedures: values.recovery_procedures, communication_plan: values.communication_plan, escalation_contacts: values.escalation_contacts, test_frequency: values.test_frequency || 'annually', plan_owner: values.plan_owner };
            if (editing) {
                body.status = values.status;
                await supaUpdate('itsm_continuity_plans', editing.id, body);
                messageApi.success("Plan updated.");
            } else {
                const seq = data.length > 0 ? Math.max(...data.map(d => parseInt(d.plan_number?.replace('BCP-', '') || '0'))) + 1 : 1;
                body.plan_number = `BCP-${String(seq).padStart(4, '0')}`;
                body.tenant_id = 'default';
                await supaInsert('itsm_continuity_plans', body);
                messageApi.success(`Plan ${body.plan_number} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await supaDelete('itsm_continuity_plans', id); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'plan_number', width: 100, render: (_, r) => <Tag color="red" style={{ fontFamily: 'monospace' }}>{r.plan_number}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true, render: (_, r) => <a onClick={() => { setDetailItem(r); setDetailOpen(true); }}>{r.title}</a> },
        { title: 'Type', dataIndex: 'plan_type', width: 90, render: (_, r) => <Tag color={typeColors[r.plan_type]}>{(r.plan_type || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 110, render: (_, r) => <Tag color={statusColors[r.status]}>{(r.status || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Priority', dataIndex: 'recovery_priority', width: 100, render: (_, r) => <Tag color={priorityColors[r.recovery_priority]}>{(r.recovery_priority || '').toUpperCase()}</Tag> },
        { title: 'RTO', dataIndex: 'rto_hours', width: 80, render: (_, r) => r.rto_hours ? <Tag><FieldTimeOutlined /> {r.rto_hours}h</Tag> : '-' },
        { title: 'RPO', dataIndex: 'rpo_hours', width: 80, render: (_, r) => r.rpo_hours ? <Tag>{r.rpo_hours}h</Tag> : '-' },
        { title: 'Owner', dataIndex: 'plan_owner', width: 130, ellipsis: true },
        { title: 'Last Test', dataIndex: 'last_test_date', width: 100, render: (_, r) => r.last_test_date ? <Tag color={r.last_test_result === 'passed' ? 'green' : 'red'}>{new Date(r.last_test_date).toLocaleDateString('id-ID')}</Tag> : <Tag color="warning">Never</Tag> },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete plan?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Service Continuity</AuroraText>}
            subTitle={<DecryptedText text="Business continuity and disaster recovery plans" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            {/* KPI Stats */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Plans', value: data.length, icon: <SafetyOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: data.filter(d => d.status === 'active' || d.status === 'approved').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Expired / Draft', value: data.filter(d => d.status === 'expired' || d.status === 'draft').length, icon: <ClockCircleOutlined />, color: '#f59e0b' },
                    { title: 'Critical Priority', value: data.filter(d => d.recovery_priority === 'critical').length, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'Avg RTO', value: data.length > 0 ? `${(data.reduce((s, d) => s + (d.rto_hours || 0), 0) / data.length).toFixed(1)}h` : '—', icon: <FieldTimeOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Plan Type Distribution */}
            {data.length > 0 && (
                <Card size="small" style={{ ...glass, marginBottom: 16 }} title={<Text strong style={{ fontSize: 13 }}>🛡️ Plan Type Distribution</Text>}>
                    <div style={{ display: 'flex', gap: 12 }}>
                        {[{ key: 'bcp', label: 'BCP', icon: '📋', color: '#3b82f6' }, { key: 'drp', label: 'DRP', icon: '🔥', color: '#ef4444' }, { key: 'crisis', label: 'Crisis', icon: '🚨', color: '#f59e0b' }, { key: 'itrp', label: 'ITRP', icon: '🔧', color: '#8b5cf6' }].map((t, i) => {
                            const cnt = data.filter(d => d.plan_type === t.key).length;
                            const active = data.filter(d => d.plan_type === t.key && (d.status === 'active' || d.status === 'approved')).length;
                            return (
                                <motion.div key={t.key} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.08 }}
                                    style={{ flex: 1, padding: '12px 10px', borderRadius: 10, background: `${t.color}08`, border: `1px solid ${t.color}20`, textAlign: 'center' }}>
                                    <Text style={{ fontSize: 18, display: 'block' }}>{t.icon}</Text>
                                    <Text strong style={{ fontSize: 20, color: t.color, display: 'block' }}>{cnt}</Text>
                                    <Text style={{ fontSize: 10, display: 'block' }}>{t.label}</Text>
                                    {active > 0 && <Badge count={`${active} active`} style={{ backgroundColor: '#10b981', fontSize: 9 }} />}
                                </motion.div>
                            );
                        })}
                    </div>
                </Card>
            )}

            <ProTable
                headerTitle={<Space><SafetyOutlined /> Continuity Plans <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <Select key="ft" placeholder="Type" allowClear style={{ width: 120 }} value={filterType} onChange={setFilterType}
                        options={[{ value: 'bcp', label: '📋 BCP' }, { value: 'drp', label: '🔥 DRP' }, { value: 'crisis', label: '🚨 Crisis' }, { value: 'itrp', label: '🔧 ITRP' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Plan</Button>,
                    <RbacGuard requiredRole="manager"><Tooltip key="excel" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'continuity_plans', title: 'Service Continuity Plans', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Plan #', key: 'plan_number' }, { header: 'Title', key: 'title' }, { header: 'Type', key: 'plan_type' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'recovery_priority' }, { header: 'RTO (h)', key: 'rto_hours' }, { header: 'RPO (h)', key: 'rpo_hours' }], data })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'continuity_plans', title: 'Service Continuity Plans', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Plan #', key: 'plan_number' }, { header: 'Title', key: 'title' }, { header: 'Type', key: 'plan_type' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'recovery_priority' }, { header: 'RTO (h)', key: 'rto_hours' }, { header: 'RPO (h)', key: 'rpo_hours' }], data })} /></Tooltip></RbacGuard>,
                ]}
            />

            <Modal title={detailItem?.plan_number + ' — ' + detailItem?.title} open={detailOpen} onCancel={() => setDetailOpen(false)} footer={null} width={800}>
                {detailItem && (
                    <Descriptions column={2} bordered size="small">
                        <Descriptions.Item label="Type"><Tag color={typeColors[detailItem.plan_type]}>{detailItem.plan_type?.toUpperCase()}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Status"><Tag color={statusColors[detailItem.status]}>{detailItem.status}</Tag></Descriptions.Item>
                        <Descriptions.Item label="RTO"><strong>{detailItem.rto_hours}h</strong></Descriptions.Item>
                        <Descriptions.Item label="RPO"><strong>{detailItem.rpo_hours}h</strong></Descriptions.Item>
                        <Descriptions.Item label="MTPD">{detailItem.mtpd_hours}h</Descriptions.Item>
                        <Descriptions.Item label="Priority"><Tag color={priorityColors[detailItem.recovery_priority]}>{detailItem.recovery_priority}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Owner">{detailItem.plan_owner}</Descriptions.Item>
                        <Descriptions.Item label="Test Frequency">{detailItem.test_frequency}</Descriptions.Item>
                        <Descriptions.Item label="Scope" span={2}><pre style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailItem.scope || '-'}</pre></Descriptions.Item>
                        <Descriptions.Item label="Risk Assessment" span={2}><pre style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailItem.risk_assessment || '-'}</pre></Descriptions.Item>
                        <Descriptions.Item label="Recovery Strategy" span={2}><pre style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailItem.recovery_strategy || '-'}</pre></Descriptions.Item>
                        <Descriptions.Item label="Recovery Procedures" span={2}><pre style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailItem.recovery_procedures || '-'}</pre></Descriptions.Item>
                        <Descriptions.Item label="Communication Plan" span={2}><pre style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailItem.communication_plan || '-'}</pre></Descriptions.Item>
                        <Descriptions.Item label="Escalation Contacts" span={2}><pre style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailItem.escalation_contacts || '-'}</pre></Descriptions.Item>
                    </Descriptions>
                )}
            </Modal>

            <SteppedFormModal open={modalOpen} onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? `Edit ${editing.plan_number}` : "New Continuity Plan"} entityName="plan" steps={[
                { title: "Plan Details", icon: <SafetyOutlined />, fields: ["title", "plan_type", "description", "scope", "recovery_priority"],
                    content: (<>
                        <Form.Item name="title" label="Plan Title" rules={[{ required: true }]}><Input placeholder="Core Database Disaster Recovery Plan" /></Form.Item>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="plan_type" label="Plan Type"><Select options={[{ value: 'bcp', label: '📋 Business Continuity Plan' }, { value: 'drp', label: '🔥 Disaster Recovery Plan' }, { value: 'crisis', label: '🚨 Crisis Management' }, { value: 'itrp', label: '🔧 IT Recovery Plan' }]} /></Form.Item></Col>
                            <Col span={12}><Form.Item name="recovery_priority" label="Recovery Priority"><Select options={[{ value: 'critical', label: '🔴 Critical' }, { value: 'high', label: '🟠 High' }, { value: 'medium', label: '🔵 Medium' }, { value: 'low', label: '🟢 Low' }]} /></Form.Item></Col>
                        </Row>
                        <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                        <Form.Item name="scope" label="Scope"><Input.TextArea rows={2} placeholder="Which systems/services does this plan cover?" /></Form.Item>
                        {editing && <Form.Item name="status" label="Status"><Select options={[{ value: 'draft', label: 'Draft' }, { value: 'active', label: 'Active' }, { value: 'under_review', label: 'Under Review' }, { value: 'approved', label: 'Approved' }, { value: 'expired', label: 'Expired' }]} /></Form.Item>}
                    </>),
                },
                { title: "Recovery Targets", icon: <FieldTimeOutlined />, fields: ["rto_hours", "rpo_hours", "mtpd_hours", "risk_assessment", "recovery_strategy"],
                    content: (<>
                        <Row gutter={16}>
                            <Col span={8}><Form.Item name="rto_hours" label="RTO (hours)"><InputNumber style={{ width: '100%' }} min={0} step={0.5} /></Form.Item></Col>
                            <Col span={8}><Form.Item name="rpo_hours" label="RPO (hours)"><InputNumber style={{ width: '100%' }} min={0} step={0.5} /></Form.Item></Col>
                            <Col span={8}><Form.Item name="mtpd_hours" label="MTPD (hours)"><InputNumber style={{ width: '100%' }} min={0} /></Form.Item></Col>
                        </Row>
                        <Form.Item name="risk_assessment" label="Risk Assessment"><Input.TextArea rows={3} placeholder="Identify risks, likelihood, and impact" /></Form.Item>
                        <Form.Item name="recovery_strategy" label="Recovery Strategy"><Input.TextArea rows={3} placeholder="How will the service be recovered?" /></Form.Item>
                    </>),
                },
                { title: "Procedures", icon: <FileProtectOutlined />, fields: ["recovery_procedures", "communication_plan", "escalation_contacts", "plan_owner", "test_frequency"],
                    content: (<>
                        <Form.Item name="recovery_procedures" label="Recovery Procedures"><Input.TextArea rows={4} placeholder="Step-by-step recovery instructions" /></Form.Item>
                        <Form.Item name="communication_plan" label="Communication Plan"><Input.TextArea rows={2} /></Form.Item>
                        <Form.Item name="escalation_contacts" label="Escalation Contacts"><Input.TextArea rows={2} placeholder="Name, phone, role" /></Form.Item>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="plan_owner" label="Plan Owner"><Input /></Form.Item></Col>
                            <Col span={12}><Form.Item name="test_frequency" label="Test Frequency"><Select options={[{ value: 'monthly', label: 'Monthly' }, { value: 'quarterly', label: 'Quarterly' }, { value: 'semi_annually', label: 'Semi-Annually' }, { value: 'annually', label: 'Annually' }]} /></Form.Item></Col>
                        </Row>
                    </>),
                },
            ]} fields={FIELDS} width={800} gradient={["#f5222d", "#a8071a"]} editMode={!!editing} initialValues={{ plan_type: 'bcp', recovery_priority: 'medium', test_frequency: 'annually' }} />
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import { ProCard } from "@ant-design/pro-components";
import { Row, Col, Statistic, Tag, Table, Space, Progress, message, Typography, Badge, Tabs, Descriptions, Modal } from "antd";
import {
    AlertOutlined, CheckCircleOutlined,
    TeamOutlined, ThunderboltOutlined,
    WarningOutlined,
    FileTextOutlined, BugOutlined, SyncOutlined, BookOutlined,
    RocketOutlined, ClusterOutlined,
    SafetyOutlined, FieldTimeOutlined,
    CloudUploadOutlined, DashboardOutlined,
    AimOutlined, LineChartOutlined,
    FundOutlined, PieChartOutlined,
    BarChartOutlined, RadarChartOutlined,
    NodeIndexOutlined, ApartmentOutlined,
} from "@ant-design/icons";
import { gql } from "@/lib/graphql";
import { supaRest } from "@/lib/supaRest";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import FormIntegrationWidget from "@/components/forms/FormIntegrationWidget";
import dynamic from "next/dynamic";
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { AnimatedCircularProgressBar } from "@/components/magicui/animated-circular-progress-bar";

// ── Dynamic chart imports (SSR-safe) ──────────────────────
/* eslint-disable @typescript-eslint/no-explicit-any */
const ChartLine: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Line), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const ChartPie: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Pie), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const ChartColumn: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Column), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const ChartArea: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Area), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const ChartRadar: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Radar), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const ChartGauge: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Gauge), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const ChartLiquid: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.Liquid), { ssr: false, loading: () => <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading chart…</div> });
const NetworkGraph: any = dynamic(() => import("@ant-design/charts").then((m: any) => m.NetworkGraph), { ssr: false, loading: () => <div style={{ height: 400, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading network…</div> });

const { Title, Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_STATS = `query { itsmDashboardStats { totalOpen totalUnassigned totalSlaBreach avgResolutionHours slaCompliance totalTickets byCritical byHigh byMedium byLow statusNew statusOpen statusInProgress statusPending statusResolved statusClosed } }`;
const GET_MODULE_COUNTS = `query { itsmModuleCounts { serviceRequests { total open } problems { total open knownErrors } changes { total open } knowledge { total published } } }`;
const GET_RECENT = `query { itsmTickets { id ticketNumber title priority status reporterName assignedTo createdAt slaResolutionDue } }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
const statusColors: Record<string, string> = { new: 'blue', open: 'cyan', in_progress: 'geekblue', pending: 'orange', resolved: 'green', closed: 'default' };
const sevColors: Record<string, string> = { critical: 'red', high: 'orange', medium: 'blue', low: 'green', informational: 'default' };
const evtStatusColors: Record<string, string> = { new: 'blue', acknowledged: 'cyan', escalated: 'red', closed: 'default' };

export default function ItsmDashboardPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [stats, setStats] = useState<any>(null);
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [modules, setModules] = useState<any>(null);
    const [tickets, setTickets] = useState<any[]>([]);
    const [allTickets, setAllTickets] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [cmdbCount, setCmdbCount] = useState(0);
    const [eventsData, setEventsData] = useState<any[]>([]);
    const [releasesData, setReleasesData] = useState<any[]>([]);
    const [agentsData, setAgentsData] = useState<any[]>([]);
    const [continuityData, setContinuityData] = useState<any[]>([]);
    const [availData, setAvailData] = useState<any[]>([]);
    const [deploymentsData, setDeploymentsData] = useState<any[]>([]);
    const [ciRelCount, setCiRelCount] = useState(0);
    const [knowledgeData, setKnowledgeData] = useState<any[]>([]);
    const [ciData, setCiData] = useState<any[]>([]);
    const [selectedNode, setSelectedNode] = useState<any>(null);
    const [nodeModalOpen, setNodeModalOpen] = useState(false);
    const [stakeholdersData, setStakeholdersData] = useState<any[]>([]);

    useEffect(() => {
        (async () => {
            try {
                const [s, m, t] = await Promise.all([gql(GET_STATS), gql(GET_MODULE_COUNTS), gql(GET_RECENT)]);
                setStats(s.itsmDashboardStats);
                setModules(m.itsmModuleCounts);
                const allTix = t.itsmTickets || [];
                setAllTickets(allTix);
                setTickets(allTix.slice(0, 8));
                const [cis, ciRels, events, releases, agents, conts, avails, deps, kbs, stakeholders] = await Promise.all([
                    supaRest('itsm_configuration_items', { select: 'id,ci_number,name,ci_class,status,criticality' }),
                    supaRest('itsm_ci_relationships', { select: 'id' }),
                    supaRest('itsm_events', { select: 'id,event_number,title,severity,status,source,occurred_at', order: 'occurred_at.desc' }),
                    supaRest('itsm_releases', { select: 'id,release_number,title,version,status,release_type,planned_start' }),
                    supaRest('itsm_agents', { select: 'id,name,agent_code,status,role,current_ticket_count,max_tickets,customer_satisfaction_score,sla_compliance_pct,total_tickets_resolved' }),
                    supaRest('itsm_continuity_plans', { select: 'id,plan_number,title,plan_type,status,rto_hours,rpo_hours,last_test_result,last_test_date' }),
                    supaRest('itsm_availability_records', { select: 'id,availability_pct,sla_target_pct,uptime_minutes,downtime_minutes,incident_count,period_start,period_end' }),
                    supaRest('itsm_deployments', { select: 'id,deployment_number,title,status,environment,deployment_type,validation_result,actual_start,created_at', order: 'created_at.desc' }),
                    supaRest('itsm_knowledge_articles', { select: 'id,title,status,category,view_count,helpful_count,created_at' }).catch(() => []),
                    supaRest('itsm_ticket_stakeholders', { select: 'id,ticket_id,stakeholder_name,stakeholder_email,stakeholder_type,role_description,agent_id' }).catch(() => []),
                ]);
                setCmdbCount(cis.length);
                setCiData(cis);
                setCiRelCount(ciRels.length);
                setEventsData(events);
                setReleasesData(releases);
                setAgentsData(agents);
                setContinuityData(conts);
                setAvailData(avails);
                setDeploymentsData(deps);
                setKnowledgeData(kbs);
                setStakeholdersData(stakeholders);
            } catch (err: any) { messageApi.error(err.message); }
            finally { setLoading(false); }
        })();
    }, [messageApi]);

    // ── Computed stats ──────────────────────────────────────
    const critEvents = eventsData.filter(e => (e.severity === 'critical' || e.severity === 'high') && e.status !== 'closed').length;
    const openEvents = eventsData.filter(e => e.status !== 'closed').length;
    const activeAgents = agentsData.filter(a => a.status === 'active').length;
    const avgCsat = activeAgents > 0 ? +(agentsData.filter(a => a.status === 'active').reduce((s, a) => s + (a.customer_satisfaction_score || 0), 0) / activeAgents).toFixed(1) : 0;
    const avgSla = activeAgents > 0 ? +(agentsData.filter(a => a.status === 'active').reduce((s, a) => s + (a.sla_compliance_pct || 0), 0) / activeAgents).toFixed(1) : 0;
    const totalResolved = agentsData.reduce((s, a) => s + (a.total_tickets_resolved || 0), 0);
    const avgUtil = activeAgents > 0 ? Math.round(agentsData.filter(a => a.status === 'active').reduce((s, a) => s + ((a.current_ticket_count || 0) / (a.max_tickets || 10) * 100), 0) / activeAgents) : 0;
    const avgAvail = availData.length > 0 ? +(availData.reduce((s, r) => s + (r.availability_pct || 0), 0) / availData.length).toFixed(2) : 0;
    const activeReleases = releasesData.filter(r => !['deployed', 'cancelled', 'rolled_back'].includes(r.status)).length;
    const activePlans = continuityData.filter(p => p.status === 'active').length;
    const completedDeps = deploymentsData.filter(d => d.status === 'completed').length;

    // ── Table columns ──────────────────────────────────────
    const ticketCols = [
        { title: '#', dataIndex: 'ticketNumber', width: 100, render: (v: any) => <Tag color="purple" style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Priority', dataIndex: 'priority', width: 90, render: (v: any) => <Tag color={priorityColors[v]}>{(v || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 110, render: (v: any) => <Tag color={statusColors[v]}>{(v || '').replace('_', ' ').toUpperCase()}</Tag> },
        { title: 'Assigned', dataIndex: 'assignedTo', width: 120, ellipsis: true, render: (v: any) => v || <Text type="secondary">Unassigned</Text> },
        { title: 'SLA', dataIndex: 'slaResolutionDue', width: 90, render: (v: any) => { if (!v) return '-'; return new Date(v) > new Date() ? <Tag color="green">OK</Tag> : <Tag color="red">Breach</Tag>; } },
    ];

    // ═══════════════════════════════════════════════════════
    // TAB 1: OVERVIEW (existing dashboard content)
    // ═══════════════════════════════════════════════════════
    const overviewTab = (
        <>
            {/* ROW 1: Core ITSM Modules (BENTO GRID) */}
            <BentoGrid className="mb-4">
                <BentoGridItem
                    title="Active Incidents"
                    description={`${stats?.totalOpen || 0} open out of ${stats?.totalTickets || 0} total.`}
                    icon={<AlertOutlined />}
                    onClick={() => router.push('/admin/itsm/tickets')}
                    header={
                        <div style={{ position: 'absolute', right: 20, top: '50%', transform: 'translateY(-50%)', opacity: 0.8 }}>
                            <AnimatedCircularProgressBar
                                max={100}
                                min={0}
                                value={stats?.slaCompliance || 0}
                                gaugePrimaryColor={themeColor}
                                gaugeSecondaryColor="rgba(255,255,255,0.1)"
                                className="w-[80px] h-[80px]"
                            />
                            <div style={{ textAlign: 'center', fontSize: 10, marginTop: 4 }}>SLA Compliance</div>
                        </div>
                    }
                    className="col-span-3 lg:col-span-1"
                />
                <BentoGridItem
                    title="Service Requests"
                    description={`${modules?.serviceRequests?.open || 0} open requests awaiting action.`}
                    icon={<FileTextOutlined />}
                    onClick={() => router.push('/admin/itsm/requests')}
                    className="col-span-3 lg:col-span-1"
                />
                <BentoGridItem
                    title="Problem Management"
                    description={`${modules?.problems?.open || 0} active problems. ${modules?.problems?.knownErrors || 0} known errors.`}
                    icon={<BugOutlined />}
                    onClick={() => router.push('/admin/itsm/problems')}
                    className="col-span-3 lg:col-span-1"
                />
                <BentoGridItem
                    title="Change Control"
                    description={`${modules?.changes?.open || 0} pending changes requiring approval or scheduling.`}
                    icon={<SyncOutlined />}
                    onClick={() => router.push('/admin/itsm/changes')}
                    className="col-span-3 lg:col-span-1"
                />
            </BentoGrid>

            {/* ROW 2: ITIL v4 Modules */}
            <BentoGrid className="mb-4">
                {[
                    { title: 'CMDB', value: cmdbCount, sub: `CIs · ${ciRelCount} Links`, icon: <ClusterOutlined />, color: themeColor, href: '/admin/itsm/cmdb' },
                    { title: 'Events', value: openEvents, sub: critEvents > 0 ? `${critEvents} Critical` : 'All Clear', icon: <ThunderboltOutlined />, color: critEvents > 0 ? '#f5222d' : '#52c41a', href: '/admin/itsm/events', danger: critEvents > 0 },
                    { title: 'Releases', value: activeReleases, sub: `${releasesData.length} Total`, icon: <RocketOutlined />, color: '#9254de', href: '/admin/itsm/releases' },
                    { title: 'Agents', value: activeAgents, sub: `${avgUtil}% Utilized`, icon: <TeamOutlined />, color: '#13c2c2', href: '/admin/itsm/agents' },
                    { title: 'Continuity', value: activePlans, sub: `${continuityData.length} Plans`, icon: <SafetyOutlined />, color: '#f5222d', href: '/admin/itsm/continuity' },
                    { title: 'Availability', value: avgAvail || '-', sub: `${availData.length} Records`, icon: <FieldTimeOutlined />, color: avgAvail >= 99.9 ? '#52c41a' : '#fa8c16', href: '/admin/itsm/availability', suffix: '%' },
                ].map((card, i) => (
                    <BentoGridItem
                        key={i}
                        title={card.title}
                        description={card.sub}
                        icon={<span style={{ color: card.color }}>{card.icon}</span>}
                        onClick={() => router.push(card.href)}
                        className="col-span-3 lg:col-span-1 cursor-pointer"
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl" style={{ backgroundColor: `${card.color}15` }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: card.danger ? '#f5222d' : card.color }}>
                                    {loading ? '...' : card.value}{card.suffix ? <span style={{ fontSize: 13, fontWeight: 400 }}> {card.suffix}</span> : null}
                                </div>
                            </div>
                        }
                    />
                ))}
            </BentoGrid>

            {/* ROW 3: KPIs */}
            <BentoGrid className="mb-4">
                <BentoGridItem
                    title="SLA Compliance"
                    description="SLA targets and CSAT score."
                    icon={<span style={{ color: themeColor }}><AimOutlined /></span>}
                    className="col-span-3 lg:col-span-1"
                    header={
                        <div className="flex h-full w-full flex-col justify-center rounded-xl p-4" style={{ backgroundColor: `rgba(82,196,26,0.05)`, border: '1px solid rgba(0,0,0,0.04)' }}>
                            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 180 }}>
                                <Progress type="dashboard" percent={stats?.slaCompliance || 0} strokeColor={(stats?.slaCompliance || 100) >= 90 ? '#52c41a' : (stats?.slaCompliance || 100) >= 70 ? '#fa8c16' : '#f5222d'} format={(pct) => <div style={{ textAlign: 'center' }}><div style={{ fontSize: 28, fontWeight: 700 }}>{pct}%</div><div style={{ fontSize: 11, color: '#999' }}>SLA Target</div></div>} size={160} />
                            </div>
                            <Row gutter={16} style={{ textAlign: 'center', marginTop: 8 }}>
                                <Col span={8}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}><Statistic title="CSAT" value={avgCsat} valueStyle={{ fontSize: 16, color: avgCsat >= 4.5 ? '#52c41a' : '#fa8c16' }} prefix="⭐" /></motion.div></Col>
                                <Col span={8}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}><Statistic title="Agent SLA" value={avgSla} suffix="%" valueStyle={{ fontSize: 16, color: avgSla >= 95 ? '#52c41a' : '#fa8c16' }} /></motion.div></Col>
                                <Col span={8}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}><Statistic title="Resolved" value={totalResolved} valueStyle={{ fontSize: 16, color: themeColor }} /></motion.div></Col>
                            </Row>
                        </div>
                    }
                />
                <BentoGridItem
                    title="Priority Breakdown"
                    description="Open incidents by priority level."
                    icon={<span style={{ color: '#fa8c16' }}><ThunderboltOutlined /></span>}
                    className="col-span-3 lg:col-span-1"
                    header={
                        <div className="flex h-full w-full flex-col justify-center rounded-xl p-4" style={{ backgroundColor: `rgba(250,140,22,0.05)`, border: '1px solid rgba(0,0,0,0.04)' }}>
                            <Space direction="vertical" style={{ width: '100%' }} size={12}>
                                {[
                                    { label: 'Critical', key: 'byCritical', color: '#f5222d', icon: '🔴' },
                                    { label: 'High', key: 'byHigh', color: '#fa8c16', icon: '🟠' },
                                    { label: 'Medium', key: 'byMedium', color: '#1890ff', icon: '🔵' },
                                    { label: 'Low', key: 'byLow', color: '#52c41a', icon: '🟢' },
                                ].map(p => (
                                    <div key={p.key} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                        <span>{p.icon}</span>
                                        <Text style={{ width: 55, fontSize: 13 }}>{p.label}</Text>
                                        <Progress percent={stats?.totalOpen ? Math.round((stats[p.key] / stats.totalOpen) * 100) : 0} strokeColor={p.color} format={() => <Text strong>{stats?.[p.key] || 0}</Text>} style={{ flex: 1 }} size="small" />
                                    </div>
                                ))}
                            </Space>
                            <div style={{ borderTop: '1px solid rgba(0,0,0,0.06)', marginTop: 16, paddingTop: 12 }}>
                                <Row>
                                    {[
                                        { label: 'New', key: 'statusNew', color: 'blue' },
                                        { label: 'Open', key: 'statusOpen', color: 'cyan' },
                                        { label: 'Progress', key: 'statusInProgress', color: 'geekblue' },
                                        { label: 'Pending', key: 'statusPending', color: 'orange' },
                                        { label: 'Resolved', key: 'statusResolved', color: 'green' },
                                    ].map(s => (
                                        <Col span={4} key={s.key} style={{ textAlign: 'center' }}>
                                            <Tag color={s.color} style={{ fontSize: 10, padding: '0 4px' }}>{stats?.[s.key] || 0}</Tag>
                                            <div style={{ fontSize: 9, color: '#999', marginTop: 2 }}>{s.label}</div>
                                        </Col>
                                    ))}
                                </Row>
                            </div>
                        </div>
                    }
                />
                <BentoGridItem
                    title="Deployments & Releases"
                    description="Recent environments and status."
