    // ═══════════════════════════════════════════════════════
    // TAB 7: ANALYTICS (Interactive Charts)
    // ═══════════════════════════════════════════════════════

    // -- Chart data preparation --
    const priorityPieData = [
        { type: 'Critical', value: stats?.byCritical || 0 },
        { type: 'High', value: stats?.byHigh || 0 },
        { type: 'Medium', value: stats?.byMedium || 0 },
        { type: 'Low', value: stats?.byLow || 0 },
    ].filter(d => d.value > 0);

    const severityPieData = ['critical', 'high', 'medium', 'low', 'informational'].map(sev => ({
        type: sev.charAt(0).toUpperCase() + sev.slice(1),
        value: eventsData.filter(e => e.severity === sev).length,
    })).filter(d => d.value > 0);

    const agentPerformanceData = agentsData.map(a => ({
        name: a.name,
        resolved: a.total_tickets_resolved || 0,
    })).sort((a, b) => b.resolved - a.resolved);

    const agentRadarData = agentsData.filter(a => a.status === 'active').flatMap(a => [
        { agent: a.name, metric: 'CSAT', value: ((a.customer_satisfaction_score || 0) / 5) * 100 },
        { agent: a.name, metric: 'SLA %', value: a.sla_compliance_pct || 0 },
        { agent: a.name, metric: 'Utilization', value: a.max_tickets > 0 ? Math.round(((a.current_ticket_count || 0) / a.max_tickets) * 100) : 0 },
        { agent: a.name, metric: 'Resolved', value: Math.min(100, Math.round(((a.total_tickets_resolved || 0) / Math.max(1, totalResolved)) * 100 * agentsData.length)) },
    ]);

    // Incident trend by date (uses ALL tickets, not just recent 8)
    const incidentTrendData = (() => {
        const dateMap: Record<string, number> = {};
        allTickets.forEach(t => {
            if (t.createdAt) {
                const d = new Date(t.createdAt).toLocaleDateString('en-CA');
                dateMap[d] = (dateMap[d] || 0) + 1;
            }
        });
        return Object.entries(dateMap).sort(([a], [b]) => a.localeCompare(b)).map(([date, count]) => ({ date, count }));
    })();

    // Availability trend
    const availTrendData = availData.map((r, i) => ({
        period: r.period_start ? new Date(r.period_start).toLocaleDateString('en-CA') : `Period ${i + 1}`,
        availability: r.availability_pct || 0,
        target: r.sla_target_pct || 99.9,
    }));

    // Network graph: Issue ↔ Stakeholder (uses junction table for many-to-many)
    const networkData = (() => {
        const nodes: any[] = [];
        const edges: any[] = [];
        const stakeholderSet = new Map<string, boolean>();

        // Add all ticket nodes
        allTickets.forEach(t => {
            nodes.push({
                id: t.id,
                data: {
                    label: t.ticketNumber || t.title?.substring(0, 15),
                    type: 'issue',
                    priority: t.priority,
                    ticketNumber: t.ticketNumber,
                    title: t.title,
                    status: t.status,
                    reporterName: t.reporterName,
                    assignedTo: t.assignedTo,
                    createdAt: t.createdAt,
                    slaResolutionDue: t.slaResolutionDue,
                },
            });
        });

        // Build edges from stakeholders junction table (many-to-many)
        const typeColors: Record<string, string> = { assignee: '#f5222d', watcher: '#1890ff', involved: '#fa8c16', reporter: '#52c41a', approver: '#9254de', escalation: '#eb2f96', affected: '#13c2c2' };
        stakeholdersData.forEach(sh => {
            const stakeholderId = `stakeholder-${sh.stakeholder_name.replace(/\s/g, '-')}`;
            // Add stakeholder node if not already added
            if (!stakeholderSet.has(stakeholderId)) {
                stakeholderSet.set(stakeholderId, true);
                const agentRecord = agentsData.find(a => a.name === sh.stakeholder_name);
                const isAgent = !!agentRecord || !!sh.agent_id;
                nodes.push({
                    id: stakeholderId,
                    data: {
                        label: sh.stakeholder_name,
                        type: isAgent ? 'agent' : 'stakeholder',
                        name: sh.stakeholder_name,
                        email: sh.stakeholder_email,
                        agentCode: agentRecord?.agent_code,
                        role: agentRecord?.role,
                        status: agentRecord?.status,
                        currentTickets: agentRecord?.current_ticket_count,
                        maxTickets: agentRecord?.max_tickets,
                        csat: agentRecord?.customer_satisfaction_score,
                        slaCompliance: agentRecord?.sla_compliance_pct,
                        totalResolved: agentRecord?.total_tickets_resolved,
                        // Count stakeholder relationships
                        linkedTickets: stakeholdersData.filter(s => s.stakeholder_name === sh.stakeholder_name).map(s => s.ticket_id).length,
                    },
                });
            }
            // Add edge from stakeholder to ticket
            const ticketExists = allTickets.some(t => t.id === sh.ticket_id);
            if (ticketExists) {
                edges.push({
                    source: stakeholderId,
                    target: sh.ticket_id,
                    data: { type: sh.stakeholder_type, role: sh.role_description },
                });
            }
        });

        // Fallback: also add edges for tickets with assignedTo but no stakeholder records
        allTickets.forEach(t => {
            if (t.assignedTo) {
                const stakeholderId = `stakeholder-${t.assignedTo.replace(/\s/g, '-')}`;
                const hasStakeholderEdge = edges.some(e => e.source === stakeholderId && e.target === t.id);
                if (!hasStakeholderEdge) {
                    if (!stakeholderSet.has(stakeholderId)) {
                        stakeholderSet.set(stakeholderId, true);
                        const agentRecord = agentsData.find(a => a.name === t.assignedTo);
                        nodes.push({
                            id: stakeholderId,
                            data: { label: t.assignedTo, type: 'agent', name: t.assignedTo, agentCode: agentRecord?.agent_code, role: agentRecord?.role, status: agentRecord?.status },
                        });
                    }
                    edges.push({ source: stakeholderId, target: t.id });
                }
            }
        });

        return { nodes, edges };
    })();

    const handleNodeClick = (nodeData: any) => {
        setSelectedNode(nodeData);
        setNodeModalOpen(true);
    };

    const analyticsTab = (
        <>
            {/* Row 1: 3 charts — Incident Trend, Priority Pie, Event Severity */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24} md={8}>
                    <ProCard title={<Space><LineChartOutlined style={{ color: themeColor }} /> Incident Trend</Space>} bordered style={{ background: 'linear-gradient(135deg, rgba(114,46,209,0.03) 0%, rgba(24,144,255,0.02) 100%)', borderRadius: 12 }}>
                        {incidentTrendData.length > 0 ? (
                            <ChartLine data={incidentTrendData} xField="date" yField="count" smooth point={{ size: 4 }} color={themeColor} height={260} />
                        ) : (
                            <div style={{ height: 260, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">Not enough data</Text></div>
                        )}
                    </ProCard>
                </Col>
                <Col xs={24} md={8}>
                    <ProCard title={<Space><PieChartOutlined style={{ color: '#fa8c16' }} /> Priority Distribution</Space>} bordered style={{ background: 'linear-gradient(135deg, rgba(250,140,22,0.03) 0%, rgba(245,34,45,0.02) 100%)', borderRadius: 12 }}>
                        {priorityPieData.length > 0 ? (
                            <ChartPie data={priorityPieData} angleField="value" colorField="type" innerRadius={0.6} height={260} color={['#f5222d', '#fa8c16', '#1890ff', '#52c41a']} label={{ text: (d: any) => `${d.type}: ${d.value}`, style: { fontSize: 11 } }} legend={{ position: 'bottom' }} />
                        ) : (
                            <div style={{ height: 260, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">No priority data</Text></div>
                        )}
                    </ProCard>
                </Col>
                <Col xs={24} md={8}>
                    <ProCard title={<Space><PieChartOutlined style={{ color: '#f5222d' }} /> Event Severity</Space>} bordered style={{ background: 'linear-gradient(135deg, rgba(245,34,45,0.03) 0%, rgba(250,140,22,0.02) 100%)', borderRadius: 12 }}>
                        {severityPieData.length > 0 ? (
                            <ChartPie data={severityPieData} angleField="value" colorField="type" height={260} color={['#f5222d', '#fa8c16', '#1890ff', '#52c41a', '#bfbfbf']} label={{ text: (d: any) => `${d.type}`, style: { fontSize: 11 } }} legend={{ position: 'bottom' }} />
                        ) : (
                            <div style={{ height: 260, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">No event data</Text></div>
                        )}
                    </ProCard>
                </Col>
            </Row>

            {/* Row 2: Network Graph (large) + Summary sidebar */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24} md={16}>
                    <ProCard title={<Space><NodeIndexOutlined style={{ color: themeColor }} /> Issue ↔ Stakeholder Network</Space>} bordered subTitle="Click any node to view details" style={{ background: 'linear-gradient(135deg, rgba(19,194,194,0.03) 0%, rgba(114,46,209,0.02) 100%)', borderRadius: 12 }}>
                        {networkData.nodes.length > 0 ? (
                            <div style={{ height: 420 }}>
                                <NetworkGraph
                                    data={networkData}
                                    autoFit="view"
                                    node={{
                                        style: {
                                            size: (d: any) => (d.data?.type === 'agent' || d.data?.type === 'stakeholder') ? 32 : 22,
                                            fill: (d: any) => {
                                                if (d.data?.type === 'agent') return '#13c2c2';
                                                if (d.data?.type === 'stakeholder') return '#9254de';
                                                const pColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
                                                return pColors[d.data?.priority] || '#d9d9d9';
                                            },
                                            labelText: (d: any) => d.data?.label || d.id,
                                            labelFontSize: 10,
                                            labelPlacement: 'bottom',
                                            cursor: 'pointer',
                                        },
                                    }}
                                    edge={{
                                        style: {
                                            stroke: '#91d5ff',
                                            lineWidth: 1.5,
                                        },
                                    }}
                                    layout={{
                                        type: 'd3-force',
                                        collide: { radius: 40, strength: 1 },
                                        manyBody: { strength: -600 },
                                        link: { distance: 180 },
                                    }}
                                    behaviors={['drag-canvas', 'zoom-canvas', 'drag-element']}
                                    onReady={(graph: any) => {
                                        graph?.on('node:click', (evt: any) => {
                                            const nodeModel = evt?.target?.id ? graph.getNodeData(evt.target.id) : null;
                                            if (nodeModel?.data) handleNodeClick(nodeModel.data);
                                        });
                                    }}
                                />
                            </div>
                        ) : (
                            <div style={{ height: 420, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">No issue-stakeholder data available. Assign agents to tickets to see the network.</Text></div>
                        )}
                        <div style={{ marginTop: 12, padding: '10px 8px', borderTop: '1px solid rgba(0,0,0,0.06)', borderRadius: 6, background: 'rgba(255,255,255,0.15)' }}>
                            <Space wrap>
                                <Text type="secondary" style={{ fontSize: 12 }}>Legend:</Text>
                                <Badge color="#13c2c2" text={<Text style={{ fontSize: 12 }}>Agent</Text>} />
                                <Badge color="#9254de" text={<Text style={{ fontSize: 12 }}>Stakeholder</Text>} />
                                <Badge color="#f5222d" text={<Text style={{ fontSize: 12 }}>Critical</Text>} />
                                <Badge color="#fa8c16" text={<Text style={{ fontSize: 12 }}>High</Text>} />
                                <Badge color="#1890ff" text={<Text style={{ fontSize: 12 }}>Medium</Text>} />
                                <Badge color="#52c41a" text={<Text style={{ fontSize: 12 }}>Low</Text>} />
                            </Space>
                        </div>
                    </ProCard>
                </Col>
                <Col xs={24} md={8}>
                    <ProCard title={<Space><NodeIndexOutlined style={{ color: themeColor }} /> Network Summary</Space>} bordered style={{ marginBottom: 16, background: 'linear-gradient(135deg, rgba(114,46,209,0.04) 0%, rgba(19,194,194,0.02) 100%)', borderRadius: 12 }}>
                        <Row gutter={[10, 10]}>
                            {[
                                { title: 'Total Nodes', value: networkData.nodes.length, color: themeColor, icon: <NodeIndexOutlined />, gradient: `linear-gradient(135deg, ${themeColor}12 0%, ${themeColor}04 100%)` },
                                { title: 'Agents', value: networkData.nodes.filter(n => n.data?.type === 'agent').length, color: '#13c2c2', icon: <TeamOutlined />, gradient: 'linear-gradient(135deg, rgba(19,194,194,0.1) 0%, rgba(19,194,194,0.02) 100%)' },
                                { title: 'Issues', value: networkData.nodes.filter(n => n.data?.type === 'issue').length, color: '#1890ff', icon: <AlertOutlined />, gradient: 'linear-gradient(135deg, rgba(24,144,255,0.1) 0%, rgba(24,144,255,0.02) 100%)' },
                                { title: 'Connections', value: networkData.edges.length, color: '#9254de', icon: <ApartmentOutlined />, gradient: 'linear-gradient(135deg, rgba(146,84,222,0.1) 0%, rgba(146,84,222,0.02) 100%)' },
                            ].map(item => (
                                <Col span={12} key={item.title}>
                                    <div style={{
                                        background: item.gradient,
                                        borderRadius: 10,
                                        padding: '14px 12px',
                                        borderLeft: `3px solid ${item.color}`,
                                        transition: 'all 0.25s ease',
                                        cursor: 'default',
                                    }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6 }}>
                                            <span style={{ color: item.color, fontSize: 13 }}>{item.icon}</span>
                                            <Text type="secondary" style={{ fontSize: 11, letterSpacing: 0.3 }}>{item.title}</Text>
                                        </div>
                                        <Text strong style={{ fontSize: 26, color: item.color, lineHeight: 1 }}>{item.value}</Text>
                                    </div>
                                </Col>
                            ))}
                        </Row>
                        <div style={{ marginTop: 14, padding: '10px 12px', background: 'rgba(255,255,255,0.3)', borderRadius: 8, border: '1px dashed rgba(0,0,0,0.06)' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Text type="secondary" style={{ fontSize: 11 }}>Node Density</Text>
                                <Text strong style={{ fontSize: 12, color: themeColor }}>{networkData.edges.length > 0 ? (networkData.edges.length / Math.max(1, networkData.nodes.length)).toFixed(1) : '0'} edges/node</Text>
                            </div>
                            <Progress
                                percent={Math.min(100, Math.round((networkData.edges.length / Math.max(1, networkData.nodes.length)) * 25))}
                                showInfo={false}
                                strokeColor={themeColor}
                                size="small"
                                style={{ marginTop: 4 }}
                            />
                        </div>
                    </ProCard>
                    <ProCard title={<Space><BarChartOutlined style={{ color: themeColor }} /> Agent Performance</Space>} bordered style={{ background: 'linear-gradient(135deg, rgba(250,140,22,0.03) 0%, rgba(82,196,26,0.02) 100%)', borderRadius: 12 }}>
                        {agentPerformanceData.length > 0 ? (
                            <ChartColumn data={agentPerformanceData} xField="name" yField="resolved" colorField="name" height={200} label={{ text: (d: any) => `${d.resolved}`, style: { fontSize: 10 } }} legend={false} />
                        ) : (
                            <div style={{ height: 200, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">No agent data</Text></div>
                        )}
                    </ProCard>
                </Col>
            </Row>

            {/* Row 3: Availability Trend + Agent Radar */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24} md={12}>
                    <ProCard title={<Space><FundOutlined style={{ color: themeColor }} /> Availability Trend</Space>} bordered style={{ background: 'linear-gradient(135deg, rgba(82,196,26,0.03) 0%, rgba(24,144,255,0.02) 100%)', borderRadius: 12 }}>
                        {availTrendData.length > 0 ? (
                            <ChartArea data={availTrendData} xField="period" yField="availability" smooth height={280} color={themeColor} areaStyle={{ fillOpacity: 0.15 }} />
                        ) : (
                            <div style={{ height: 280, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">No availability data</Text></div>
                        )}
                    </ProCard>
                </Col>
                <Col xs={24} md={12}>
                    <ProCard title={<Space><RadarChartOutlined style={{ color: '#9254de' }} /> Agent Capability Radar</Space>} bordered style={{ background: 'linear-gradient(135deg, rgba(146,84,222,0.03) 0%, rgba(19,194,194,0.02) 100%)', borderRadius: 12 }}>
                        {agentRadarData.length > 0 ? (
                            <ChartRadar data={agentRadarData} xField="metric" yField="value" colorField="agent" height={280} area={{ style: { fillOpacity: 0.15 } }} legend={{ position: 'bottom' }} />
                        ) : (
                            <div style={{ height: 280, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Text type="secondary">No agent data</Text></div>
                        )}
                    </ProCard>
                </Col>
            </Row>

            {/* Node Detail Modal */}
            <Modal
                title={selectedNode?.type === 'agent' ? '👤 Stakeholder Details' : '🎫 Incident Details'}
                open={nodeModalOpen}
                onCancel={() => { setNodeModalOpen(false); setSelectedNode(null); }}
                footer={null}
                width={520}
            >
                {selectedNode?.type === 'issue' ? (
                    <Descriptions column={1} bordered size="small" style={{ marginTop: 16 }}>
                        <Descriptions.Item label="Ticket #">
                            <Tag color="purple" style={{ fontFamily: 'monospace' }}>{selectedNode.ticketNumber}</Tag>
                        </Descriptions.Item>
                        <Descriptions.Item label="Title">{selectedNode.title}</Descriptions.Item>
                        <Descriptions.Item label="Priority">
                            <Tag color={priorityColors[selectedNode.priority]}>{(selectedNode.priority || '').toUpperCase()}</Tag>
                        </Descriptions.Item>
                        <Descriptions.Item label="Status">
                            <Tag color={statusColors[selectedNode.status]}>{(selectedNode.status || '').replace('_', ' ').toUpperCase()}</Tag>
                        </Descriptions.Item>
                        <Descriptions.Item label="Reporter">{selectedNode.reporterName || 'N/A'}</Descriptions.Item>
                        <Descriptions.Item label="Assigned To">{selectedNode.assignedTo || <Text type="secondary">Unassigned</Text>}</Descriptions.Item>
                        <Descriptions.Item label="Created">{selectedNode.createdAt ? new Date(selectedNode.createdAt).toLocaleString('id-ID') : '-'}</Descriptions.Item>
                        <Descriptions.Item label="SLA Due">
                            {selectedNode.slaResolutionDue ? (
                                new Date(selectedNode.slaResolutionDue) > new Date()
                                    ? <Tag color="green">OK — {new Date(selectedNode.slaResolutionDue).toLocaleString('id-ID')}</Tag>
                                    : <Tag color="red">BREACH — {new Date(selectedNode.slaResolutionDue).toLocaleString('id-ID')}</Tag>
                            ) : '-'}
                        </Descriptions.Item>
                    </Descriptions>
                ) : selectedNode?.type === 'agent' ? (
                    <Descriptions column={1} bordered size="small" style={{ marginTop: 16 }}>
                        <Descriptions.Item label="Name"><Text strong>{selectedNode.name}</Text></Descriptions.Item>
                        <Descriptions.Item label="Agent Code"><Tag style={{ fontFamily: 'monospace' }}>{selectedNode.agentCode || 'N/A'}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Role"><Tag color="blue">{selectedNode.role || 'N/A'}</Tag></Descriptions.Item>
                        <Descriptions.Item label="Status">
                            <Tag color={selectedNode.status === 'active' ? 'green' : 'default'}>{selectedNode.status || 'N/A'}</Tag>
                        </Descriptions.Item>
                        <Descriptions.Item label="Workload">
                            <Progress percent={selectedNode.maxTickets > 0 ? Math.round((selectedNode.currentTickets / selectedNode.maxTickets) * 100) : 0} size="small" format={() => `${selectedNode.currentTickets || 0}/${selectedNode.maxTickets || 0}`} />
                        </Descriptions.Item>
                        <Descriptions.Item label="CSAT">
                            <Tag color={selectedNode.csat >= 4.5 ? 'green' : selectedNode.csat >= 4 ? 'blue' : 'orange'}>⭐ {selectedNode.csat || 0}</Tag>
                        </Descriptions.Item>
                        <Descriptions.Item label="SLA Compliance">
                            <Text style={{ color: selectedNode.slaCompliance >= 95 ? '#52c41a' : '#fa8c16' }}>{selectedNode.slaCompliance || 0}%</Text>
                        </Descriptions.Item>
                        <Descriptions.Item label="Total Resolved">
                            <Text strong style={{ color: '#52c41a' }}>{selectedNode.totalResolved || 0}</Text>
                        </Descriptions.Item>
                        <Descriptions.Item label="Assigned Tickets">
                            {selectedNode.assignedTickets ? selectedNode.assignedTickets.split(', ').map((t: string) => <Tag key={t} color="purple" style={{ fontFamily: 'monospace', marginBottom: 2 }}>{t}</Tag>) : <Text type="secondary">None</Text>}
                        </Descriptions.Item>
                    </Descriptions>
                ) : null}
            </Modal>
        </>
    );

    // ═══════════════════════════════════════════════════════
    // MAIN RENDER
    // ═══════════════════════════════════════════════════════
    const tabItems = [
        { key: 'overview', label: <Space><DashboardOutlined />Overview</Space>, children: overviewTab },
        { key: 'sla', label: <Space><AimOutlined />SLA & Performance</Space>, children: slaTab },
        { key: 'events', label: <Space><ThunderboltOutlined />Events & Monitoring</Space>, children: eventsTab },
        { key: 'agents', label: <Space><TeamOutlined />Agents & Workload</Space>, children: agentsTab },
        { key: 'deployments', label: <Space><CloudUploadOutlined />Deployments & Releases</Space>, children: deploymentsTab },
        { key: 'continuity', label: <Space><SafetyOutlined />Continuity & Knowledge</Space>, children: continuityTab },
        { key: 'analytics', label: <Space><LineChartOutlined />Analytics</Space>, children: analyticsTab },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>ITSM Dashboard</AuroraText>}
            subTitle={<DecryptedText text="IT Service Management — Full ITIL v4 Overview" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div style={{ padding: 12 }}>
            {contextHolder}
            <Tabs
                defaultActiveKey="overview"
                items={tabItems}
                size="middle"
                tabBarStyle={{ marginBottom: 20, fontWeight: 500, ...glass, padding: '4px 8px', border: '1px solid rgba(var(--theme-color-rgb, 139, 92, 246), 0.08)' }}
                type="card"
            />
        </div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Progress, Typography, Timeline, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, CloudUploadOutlined, RocketOutlined, CheckCircleOutlined, CloseCircleOutlined, LoadingOutlined, ClockCircleOutlined, ExclamationCircleOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import { supaRest, supaInsert, supaUpdate, supaDelete } from "@/lib/supaRest";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { useDateRangeStore } from "@/store/useDateRangeStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const statusColors: Record<string, string> = { planned: 'blue', in_progress: 'orange', completed: 'green', failed: 'red', rolled_back: 'volcano', cancelled: 'default' };
const statusIcons: Record<string, React.ReactNode> = { planned: <ClockCircleOutlined />, in_progress: <LoadingOutlined />, completed: <CheckCircleOutlined />, failed: <CloseCircleOutlined />, rolled_back: <CloseCircleOutlined /> };
const typeColors: Record<string, string> = { standard: 'blue', rolling: 'cyan', blue_green: 'green', canary: 'gold', phased: 'purple', big_bang: 'red' };
const envColors: Record<string, string> = { production: 'red', staging: 'orange', development: 'blue', testing: 'cyan', dr: 'purple' };

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "deployment_type", label: "Type" },
    { name: "environment", label: "Environment" },
];

export default function DeploymentsPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterEnv, setFilterEnv] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const filters: Record<string, string> = {};
            if (filterStatus) filters['status'] = `eq.${filterStatus}`;
            if (filterEnv) filters['environment'] = `eq.${filterEnv}`;
            const rows = await supaRest('itsm_deployments', { order: 'created_at.desc', filters });
            setData(rows);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterEnv, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const body: any = { title: values.title, description: values.description, deployment_type: values.deployment_type || 'standard', environment: values.environment || 'production', planned_start: values.planned_start, planned_end: values.planned_end, deployed_by: values.deployed_by, deployment_team: values.deployment_team, deployment_steps: values.deployment_steps, validation_steps: values.validation_steps, rollback_steps: values.rollback_steps };
            if (editing) {
                body.status = values.status;
                if (values.status === 'in_progress' && !editing.actual_start) body.actual_start = new Date().toISOString();
                if ((values.status === 'completed' || values.status === 'failed') && !editing.actual_end) body.actual_end = new Date().toISOString();
                body.validation_result = values.validation_result;
                body.deployment_log = values.deployment_log;
                await supaUpdate('itsm_deployments', editing.id, body);
                messageApi.success("Deployment updated.");
            } else {
                const seq = data.length > 0 ? Math.max(...data.map(d => parseInt(d.deployment_number?.replace('DEP-', '') || '0'))) + 1 : 1;
                body.deployment_number = `DEP-${String(seq).padStart(4, '0')}`;
                body.tenant_id = 'default';
                await supaInsert('itsm_deployments', body);
                messageApi.success(`Deployment ${body.deployment_number} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await supaDelete('itsm_deployments', id); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'deployment_number', width: 110, render: (_, r) => <Tag color="blue" style={{ fontFamily: 'monospace' }}>{r.deployment_number}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Type', dataIndex: 'deployment_type', width: 110, render: (_, r) => <Tag color={typeColors[r.deployment_type]}>{(r.deployment_type || '').replace(/_/g, '-').toUpperCase()}</Tag> },
        { title: 'Environment', dataIndex: 'environment', width: 110, render: (_, r) => <Tag color={envColors[r.environment]}>{(r.environment || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 120, render: (_, r) => <Tag icon={statusIcons[r.status]} color={statusColors[r.status]}>{(r.status || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Deployed By', dataIndex: 'deployed_by', width: 120, ellipsis: true },
        { title: 'Planned', dataIndex: 'planned_start', width: 140, render: (_, r) => r.planned_start ? new Date(r.planned_start).toLocaleString('id-ID', { dateStyle: 'short', timeStyle: 'short' }) : '-' },
        { title: 'Actual', dataIndex: 'actual_start', width: 140, render: (_, r) => r.actual_start ? new Date(r.actual_start).toLocaleString('id-ID', { dateStyle: 'short', timeStyle: 'short' }) : '-' },
        { title: 'Validation', dataIndex: 'validation_result', width: 100, render: (_, r) => r.validation_result ? <Tag color={r.validation_result === 'passed' ? 'green' : 'red'}>{r.validation_result}</Tag> : '-' },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete deployment?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Deployment Management</AuroraText>}
            subTitle={<DecryptedText text="Plan, execute, and track infrastructure deployments" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            {/* KPI Stats */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Deployments', value: data.length, icon: <CloudUploadOutlined />, color: '#3b82f6' },
                    { title: 'Completed', value: data.filter(d => d.status === 'completed').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Failed', value: data.filter(d => d.status === 'failed' || d.status === 'rolled_back').length, icon: <CloseCircleOutlined />, color: '#ef4444' },
                    { title: 'In Progress', value: data.filter(d => d.status === 'in_progress').length, icon: <LoadingOutlined />, color: '#f59e0b' },
                    { title: 'Production', value: data.filter(d => d.environment === 'production').length, icon: <ExclamationCircleOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Environment Distribution */}
            {data.length > 0 && (
                <Card size="small" style={{ ...glass, marginBottom: 16 }} title={<Text strong style={{ fontSize: 13 }}>â˜ï¸ Environment Distribution</Text>}>
                    <div style={{ display: 'flex', gap: 12 }}>
                        {['production', 'staging', 'development', 'testing'].map((env, i) => {
                            const cnt = data.filter(d => d.environment === env).length;
                            const pct = Math.round((cnt / data.length) * 100);
                            const cfg = envColors[env] || 'gray';
                            return (
                                <motion.div key={env} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.08 }}
                                    style={{ flex: 1, padding: '12px 10px', borderRadius: 10, background: `rgba(0,0,0,0.02)`, border: `1px solid rgba(0,0,0,0.06)`, textAlign: 'center', position: 'relative', overflow: 'hidden' }}>
                                    <div style={{ position: 'absolute', bottom: 0, left: 0, height: 4, background: cfg === 'red' ? '#ef4444' : cfg === 'orange' ? '#f59e0b' : cfg === 'blue' ? '#3b82f6' : '#06b6d4', width: `${pct}%`, borderRadius: 4 }} />
                                    <Text style={{ fontSize: 10, textTransform: 'uppercase', letterSpacing: 0.5, display: 'block' }}>{env}</Text>
                                    <Text strong style={{ fontSize: 20 }}>{cnt}</Text>
                                    <Text style={{ fontSize: 10, color: '#9ca3af', display: 'block' }}>{pct}%</Text>
                                </motion.div>
                            );
                        })}
                    </div>
                </Card>
            )}

            <ProTable
                headerTitle={<Space><CloudUploadOutlined /> Deployments <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_deployments', title: 'Deployments', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Environment', key: 'environment' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_deployments', title: 'Deployments', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Environment', key: 'environment' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip></RbacGuard>,
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 140 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'planned', label: 'Planned' }, { value: 'in_progress', label: 'In Progress' }, { value: 'completed', label: 'Completed' }, { value: 'failed', label: 'Failed' }, { value: 'rolled_back', label: 'Rolled Back' }]} />,
                    <Select key="fe" placeholder="Environment" allowClear style={{ width: 140 }} value={filterEnv} onChange={setFilterEnv}
                        options={[{ value: 'production', label: 'ðŸ”´ Production' }, { value: 'staging', label: 'ðŸŸ  Staging' }, { value: 'development', label: 'ðŸ”µ Development' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Deployment</Button>,
                ]}
            />

            <SteppedFormModal open={modalOpen} onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }} onSubmit={handleSave} form={form} title={editing ? `Edit ${editing.deployment_number}` : "New Deployment"} entityName="deployment" steps={[
                { title: "Deployment Info", icon: <CloudUploadOutlined />, fields: ["title", "description", "deployment_type", "environment"],
                    content: (<>
                        <Form.Item name="title" label="Deployment Title" rules={[{ required: true }]}><Input placeholder="NusantaraSoft v4.0 Production Deployment" /></Form.Item>
                        <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="deployment_type" label="Type"><Select options={[{ value: 'standard', label: 'Standard' }, { value: 'rolling', label: 'Rolling' }, { value: 'blue_green', label: 'Blue/Green' }, { value: 'canary', label: 'Canary' }, { value: 'phased', label: 'Phased' }, { value: 'big_bang', label: 'Big Bang' }]} /></Form.Item></Col>
                            <Col span={12}><Form.Item name="environment" label="Environment"><Select options={[{ value: 'production', label: 'ðŸ”´ Production' }, { value: 'staging', label: 'ðŸŸ  Staging' }, { value: 'development', label: 'ðŸ”µ Development' }, { value: 'testing', label: 'Testing' }, { value: 'dr', label: 'DR' }]} /></Form.Item></Col>
                        </Row>
                        {editing && <Form.Item name="status" label="Status"><Select options={[{ value: 'planned', label: 'Planned' }, { value: 'in_progress', label: 'In Progress' }, { value: 'completed', label: 'Completed' }, { value: 'failed', label: 'Failed' }, { value: 'rolled_back', label: 'Rolled Back' }]} /></Form.Item>}
                    </>),
                },
                { title: "Schedule & Team", icon: <RocketOutlined />, fields: ["planned_start", "planned_end", "deployed_by", "deployment_team"],
                    content: (<>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="planned_start" label="Planned Start"><Input type="datetime-local" /></Form.Item></Col>
                            <Col span={12}><Form.Item name="planned_end" label="Planned End"><Input type="datetime-local" /></Form.Item></Col>
                        </Row>
                        <Row gutter={16}>
                            <Col span={12}><Form.Item name="deployed_by" label="Deployed By"><Input /></Form.Item></Col>
                            <Col span={12}><Form.Item name="deployment_team" label="Deployment Team"><Input /></Form.Item></Col>
                        </Row>
                    </>),
                },
                { title: "Steps & Validation", icon: <CheckCircleOutlined />, fields: ["deployment_steps", "validation_steps", "rollback_steps"],
                    content: (<>
                        <Form.Item name="deployment_steps" label="Deployment Steps"><Input.TextArea rows={4} placeholder="1. Pull images\n2. Run migrations\n3. Rolling restart" /></Form.Item>
                        <Form.Item name="validation_steps" label="Validation Steps"><Input.TextArea rows={3} placeholder="1. Health checks\n2. Smoke tests\n3. Monitor dashboards" /></Form.Item>
                        <Form.Item name="rollback_steps" label="Rollback Steps"><Input.TextArea rows={3} placeholder="How to revert if deployment fails" /></Form.Item>
                        {editing && (<>
                            <Form.Item name="validation_result" label="Validation Result"><Select allowClear options={[{ value: 'passed', label: 'âœ… Passed' }, { value: 'failed', label: 'âŒ Failed' }, { value: 'partial', label: 'âš ï¸ Partial' }]} /></Form.Item>
                            <Form.Item name="deployment_log" label="Deployment Log"><Input.TextArea rows={3} placeholder="Deployment execution notes" /></Form.Item>
                        </>)}
                    </>),
                },
            ]} fields={FIELDS} width={800} gradient={["#1890ff", "#096dd9"]} editMode={!!editing} initialValues={{ deployment_type: 'standard', environment: 'production' }} />
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import { Card, Row, Col, Statistic, Tag, Table, Space, message, Typography, Button, Tooltip, Badge, Collapse, InputNumber, Input } from "antd";
import {
    AlertOutlined, ArrowRightOutlined, ClockCircleOutlined,
    WarningOutlined, ReloadOutlined, ThunderboltOutlined,
    FireOutlined, SettingOutlined, UserOutlined, TeamOutlined,
    CrownOutlined, SafetyCertificateOutlined, UndoOutlined, SaveOutlined,
} from "@ant-design/icons";
import { gql } from "@/lib/graphql";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip,
    ResponsiveContainer, Legend,
} from "recharts";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_SLA_POLICIES = `query { itsmSlaPolicies { id name priority responseTimeMinutes resolutionTimeMinutes escalationAfterMinutes } }`;
const GET_TICKETS = `query { itsmTickets { id ticketNumber title status priority slaResponseDue slaResolutionDue slaBreached assignedTo assignedTeam createdAt } }`;
const GET_AGENTS = `query { itsmAgents { id data } }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };

/* ── escalation level definitions ──────────────── */
const LEVELS = [
    { level: 0, label: 'Auto-assign', role: 'System', icon: <SafetyCertificateOutlined />, color: '#52c41a', pct: 0 },
    { level: 1, label: 'Agent', role: 'First Responder', icon: <UserOutlined />, color: '#fadb14', pct: 0 },
    { level: 2, label: 'Team Lead', role: 'Team Lead', icon: <TeamOutlined />, color: '#fa8c16', pct: 50 },
    { level: 3, label: 'Manager', role: 'Manager', icon: <CrownOutlined />, color: '#f5222d', pct: 75 },
    { level: 4, label: 'Director', role: 'Director', icon: <FireOutlined />, color: '#820014', pct: 100 },
];

function getEscalationLevel(ticket: any, policies: any[]): number {
    if (['resolved', 'closed'].includes(ticket.status)) return -1;
    const policy = policies.find(p => p.priority === ticket.priority);
    if (!policy) return 0;
    const elapsed = dayjs().diff(dayjs(ticket.createdAt), 'minute');
    const resMin = policy.resolutionTimeMinutes || 480;
    if (ticket.slaBreached || elapsed >= resMin) return 4;
    if (elapsed >= resMin * 0.75) return 3;
    if (elapsed >= resMin * 0.50) return 2;
    if (elapsed >= (policy.responseTimeMinutes || 60)) return 1;
    return 0;
}

function fmtMinutes(m: number): string {
    if (!m || m <= 0) return '—';
    if (m < 60) return `${Math.round(m)}m`;
    const h = Math.floor(m / 60);
    return h < 24 ? `${h}h ${m % 60}m` : `${Math.floor(h / 24)}d ${h % 24}h`;
}

const DEFAULT_RULES: Record<string, { l1: number; l2: number; targets: string }> = {
    critical: { l1: 15, l2: 30, targets: 'manager@company.com' },
    high: { l1: 30, l2: 60, targets: 'teamlead@company.com' },
    medium: { l1: 120, l2: 240, targets: 'teamlead@company.com' },
    low: { l1: 480, l2: 960, targets: 'agent@company.com' },
};

const LS_KEY = 'itsm_escalation_rules';

function loadRules(): typeof DEFAULT_RULES {
    if (typeof window === 'undefined') return DEFAULT_RULES;
    try { const s = localStorage.getItem(LS_KEY); return s ? JSON.parse(s) : DEFAULT_RULES; } catch { return DEFAULT_RULES; }
}

/* ── component ────────────────────────────────── */
export default function EscalationMatrixPage() {
    const router = useRouter();
    const { themeColor } = usePreferencesStore();
    const [messageApi, ctx] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [tickets, setTickets] = useState<any[]>([]);
    const [policies, setPolicies] = useState<any[]>([]);
    const [agents, setAgents] = useState<any[]>([]);
    const [rules, setRules] = useState<typeof DEFAULT_RULES>(DEFAULT_RULES);

    useEffect(() => { setRules(loadRules()); }, []);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [t, p, a] = await Promise.all([gql(GET_TICKETS), gql(GET_SLA_POLICIES), gql(GET_AGENTS)]);
            setTickets(t.itsmTickets || []);
            setPolicies(p.itsmSlaPolicies || []);
            setAgents(a.itsmAgents || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    /* ── computed: active escalations ────────────── */
    const escalatedTickets = useMemo(() => {
        return tickets
            .map(t => ({ ...t, escLevel: getEscalationLevel(t, policies) }))
            .filter(t => t.escLevel >= 1)
            .sort((a, b) => b.escLevel - a.escLevel);
    }, [tickets, policies]);

    /* ── computed: escalation history (4 weeks) ──── */
    const historyData = useMemo(() => {
        const weeks: { week: string; L1: number; L2: number; L3: number; L4: number }[] = [];
        for (let w = 3; w >= 0; w--) {
            const start = dayjs().subtract(w, 'week').startOf('week');
            const end = start.endOf('week');
            const label = start.format('MMM DD');
            const inRange = tickets.filter(t => {
                const d = dayjs(t.createdAt);
                return d.isAfter(start) && d.isBefore(end);
            });
            const counts = { L1: 0, L2: 0, L3: 0, L4: 0 };
            inRange.forEach(t => {
                const lv = getEscalationLevel(t, policies);
                if (lv === 1) counts.L1++;
                else if (lv === 2) counts.L2++;
                else if (lv === 3) counts.L3++;
                else if (lv >= 4) counts.L4++;
            });
            weeks.push({ week: label, ...counts });
        }
        return weeks;
    }, [tickets, policies]);

    /* ── stats ───────────────────────────────────── */
    const avgLevel = escalatedTickets.length > 0
        ? +(escalatedTickets.reduce((s, t) => s + t.escLevel, 0) / escalatedTickets.length).toFixed(1)
        : 0;
    const openTickets = tickets.filter(t => !['resolved', 'closed'].includes(t.status));
    const escalationRate = openTickets.length > 0
        ? Math.round((escalatedTickets.length / openTickets.length) * 100)
        : 0;
    const priorityCounts = escalatedTickets.reduce<Record<string, number>>((acc, t) => {
        acc[t.priority] = (acc[t.priority] || 0) + 1; return acc;
    }, {});
    const mostEscalated = Object.entries(priorityCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || '—';

    const stats = [
        { title: 'Active Escalations', value: escalatedTickets.length, icon: <AlertOutlined />, color: '#f5222d' },
        { title: 'Avg Escalation Level', value: avgLevel, icon: <ThunderboltOutlined />, color: '#fa8c16' },
        { title: 'Most Escalated', value: (mostEscalated || '').charAt(0).toUpperCase() + (mostEscalated || '').slice(1), icon: <FireOutlined />, color: '#722ed1' },
        { title: 'Escalation Rate', value: `${escalationRate}%`, icon: <WarningOutlined />, color: '#1890ff' },
    ];

    /* ── rules handlers ─────────────────────────── */
    const saveRules = () => { localStorage.setItem(LS_KEY, JSON.stringify(rules)); messageApi.success('Escalation rules saved'); };
    const resetRules = () => { setRules(DEFAULT_RULES); localStorage.removeItem(LS_KEY); messageApi.info('Rules reset to defaults'); };
    const updateRule = (prio: string, field: string, val: any) => setRules(prev => ({ ...prev, [prio]: { ...prev[prio], [field]: val } }));

    /* ── table columns ──────────────────────────── */
    const escColumns = [
        { title: 'Ticket #', dataIndex: 'ticketNumber', width: 110, render: (v: string) => <Tag color="purple" style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Priority', dataIndex: 'priority', width: 90, render: (v: string) => <Tag color={priorityColors[v]}>{(v || '').toUpperCase()}</Tag> },
        {
            title: 'Level', dataIndex: 'escLevel', width: 100, render: (v: number) => {
                const lv = LEVELS[v] || LEVELS[4];
                return <Tag color={lv.color} style={v >= 3 ? { animation: 'pulse-esc 1.5s infinite' } : undefined}>{lv.icon} L{v}</Tag>;
            },
        },
        {
            title: 'Time in Level', key: 'elapsed', width: 120, render: (_: any, r: any) => {
                const elapsed = dayjs().diff(dayjs(r.createdAt), 'minute');
                return <Text style={{ fontSize: 12 }}>{fmtMinutes(elapsed)}</Text>;
            },
        },
        { title: 'Assigned To', dataIndex: 'assignedTo', width: 130, render: (v: string) => v || <Text type="secondary">Unassigned</Text> },
        { title: 'Team', dataIndex: 'assignedTeam', width: 120, render: (v: string) => v ? <Tag>{v}</Tag> : '—' },
    ];

    const policyColumns = [
        { title: 'Priority', dataIndex: 'priority', width: 100, render: (v: string) => <Tag color={priorityColors[v]} style={{ fontWeight: 600 }}>{(v || '').toUpperCase()}</Tag> },
        { title: 'Response Time', dataIndex: 'responseTimeMinutes', width: 130, render: (v: number) => <Space><ClockCircleOutlined style={{ color: '#1890ff' }} />{fmtMinutes(v)}</Space> },
        { title: 'Resolution Time', dataIndex: 'resolutionTimeMinutes', width: 140, render: (v: number) => <Space><ClockCircleOutlined style={{ color: '#52c41a' }} />{fmtMinutes(v)}</Space> },
        { title: 'Escalation After', dataIndex: 'escalationAfterMinutes', width: 140, render: (v: number) => v ? <Space><WarningOutlined style={{ color: '#fa8c16' }} />{fmtMinutes(v)}</Space> : '—' },
        {
            title: 'Time Bar', key: 'bar', width: 200, render: (_: any, r: any) => {
                const max = r.resolutionTimeMinutes || 1;
                const respPct = Math.min(((r.responseTimeMinutes || 0) / max) * 100, 100);
                const escPct = Math.min(((r.escalationAfterMinutes || 0) / max) * 100, 100);
                return (
                    <div style={{ height: 10, borderRadius: 5, background: '#f0f0f0', position: 'relative', overflow: 'hidden' }}>
                        <div style={{ position: 'absolute', left: 0, top: 0, height: '100%', width: '100%', borderRadius: 5, background: 'linear-gradient(90deg, #52c41a, #fadb14, #fa8c16, #f5222d)' }} />
                        <Tooltip title={`Response: ${fmtMinutes(r.responseTimeMinutes)}`}>
                            <div style={{ position: 'absolute', left: `${respPct}%`, top: -2, width: 2, height: 14, background: '#1890ff' }} />
                        </Tooltip>
                        {r.escalationAfterMinutes > 0 && (
                            <Tooltip title={`Escalation: ${fmtMinutes(r.escalationAfterMinutes)}`}>
                                <div style={{ position: 'absolute', left: `${escPct}%`, top: -2, width: 2, height: 14, background: '#f5222d' }} />
                            </Tooltip>
                        )}
                    </div>
                );
            },
        },
    ];

    /* ── render ───────────────────────────────────── */
    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#f5222d", "#fa8c16"]}>Escalation Matrix</AuroraText>}
            subTitle={<DecryptedText text="Visual escalation path configuration & monitoring" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[<Button key="refresh" icon={<ReloadOutlined spin={loading} />} onClick={loadData}>Refresh</Button>]}
        >
            {ctx}
            <style>{`@keyframes pulse-esc { 0%,100%{opacity:1} 50%{opacity:.4} }`}</style>

            {/* ─── 1. Escalation Pipeline Visualization ── */}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                <Card size="small" title={<Space><ThunderboltOutlined style={{ color: themeColor }} /> Escalation Path</Space>} style={{ ...glass, marginBottom: 16 }}>
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0, overflowX: 'auto', padding: '8px 0' }}>
                        {LEVELS.map((lv, i) => (
                            <React.Fragment key={lv.level}>
                                <motion.div
                                    initial={{ opacity: 0, scale: 0.8 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    transition={{ delay: i * 0.1 }}
                                    style={{
                                        minWidth: 130, padding: '14px 12px', borderRadius: 12, textAlign: 'center',
                                        background: `${lv.color}12`, border: `2px solid ${lv.color}40`,
                                        position: 'relative',
                                    }}
                                >
                                    <div style={{ fontSize: 22, color: lv.color, marginBottom: 4 }}>{lv.icon}</div>
                                    <Text strong style={{ fontSize: 13, display: 'block' }}>L{lv.level}: {lv.label}</Text>
                                    <Text style={{ fontSize: 10, color: '#888', display: 'block' }}>{lv.role}</Text>
                                    <Tag color={lv.color} style={{ marginTop: 6, fontSize: 10 }}>
                                        {lv.level === 0 ? 'On Create' : lv.level === 1 ? 'Response SLA' : `${lv.pct}% Resolution`}
                                    </Tag>
                                    <Badge count={escalatedTickets.filter(t => t.escLevel === lv.level).length} style={{ backgroundColor: lv.color, position: 'absolute', top: -6, right: -6 }} />
                                </motion.div>
                                {i < LEVELS.length - 1 && (
                                    <div style={{ display: 'flex', alignItems: 'center', padding: '0 2px' }}>
                                        <div style={{ width: 32, height: 3, background: `linear-gradient(90deg, ${lv.color}, ${LEVELS[i + 1].color})`, borderRadius: 2 }} />
                                        <ArrowRightOutlined style={{ color: LEVELS[i + 1].color, fontSize: 12 }} />
                                    </div>
                                )}
                            </React.Fragment>
                        ))}
                    </div>
                </Card>
            </motion.div>

            {/* ─── 2. Stats Cards ────────────────────── */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {stats.map((s, i) => (
                    <Col xs={12} sm={6} key={s.title}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }} bodyStyle={{ padding: '12px 14px' }}>
                                <Statistic title={<Text style={{ fontSize: 10 }}>{s.title}</Text>} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 22 }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* ─── 3. SLA Policy Matrix ──────────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                <Card size="small" title={<Space><SettingOutlined style={{ color: themeColor }} /> SLA Policy Matrix <Badge count={policies.length} style={{ backgroundColor: themeColor }} /></Space>} style={{ ...glass, marginBottom: 16 }}>
                    <Table dataSource={policies} columns={policyColumns} rowKey="id" size="small" pagination={false} loading={loading} scroll={{ x: 700 }} />
                </Card>
            </motion.div>

            {/* ─── 4. Active Escalations ─────────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                <Card
                    size="small"
                    title={<Space><FireOutlined style={{ color: '#f5222d' }} /> Active Escalations <Badge count={escalatedTickets.length} style={{ backgroundColor: '#f5222d' }} /></Space>}
                    style={{ ...glass, marginBottom: 16 }}
                >
                    <Table
                        dataSource={escalatedTickets.slice(0, 20)}
                        columns={escColumns}
                        rowKey="id"
                        size="small"
                        pagination={false}
                        loading={loading}
                        scroll={{ x: 900 }}
                        onRow={(r) => ({ style: { cursor: 'pointer' }, onClick: () => router.push(`/admin/itsm/tickets/${r.id}`) })}
                    />
                </Card>
            </motion.div>

            {/* ─── 5. Escalation History Chart ────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }}>
                <Card size="small" title={<Space><WarningOutlined style={{ color: '#fa8c16' }} /> Escalation History (Last 4 Weeks)</Space>} style={{ ...glass, marginBottom: 16 }}>
                    <ResponsiveContainer width="100%" height={260}>
                        <BarChart data={historyData} barCategoryGap="20%">
                            <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,0,0,0.06)" />
                            <XAxis dataKey="week" tick={{ fontSize: 11 }} />
                            <YAxis allowDecimals={false} tick={{ fontSize: 10 }} />
                            <RTooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                            <Legend wrapperStyle={{ fontSize: 11 }} />
                            <Bar dataKey="L1" stackId="a" fill="#fadb14" name="Level 1" radius={[0, 0, 0, 0]} />
                            <Bar dataKey="L2" stackId="a" fill="#fa8c16" name="Level 2" />
                            <Bar dataKey="L3" stackId="a" fill="#f5222d" name="Level 3" />
                            <Bar dataKey="L4" stackId="a" fill="#820014" name="Level 4" radius={[4, 4, 0, 0]} />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </motion.div>

            {/* ─── 6. Escalation Rules Config ─────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                <Card
                    size="small"
                    title={<Space><SettingOutlined style={{ color: '#722ed1' }} /> Escalation Rules Configuration</Space>}
                    extra={<Space><Button size="small" icon={<UndoOutlined />} onClick={resetRules}>Reset</Button><Button size="small" type="primary" icon={<SaveOutlined />} onClick={saveRules}>Save</Button></Space>}
                    style={{ ...glass, marginBottom: 16 }}
                >
                    <Collapse
                        accordion
                        items={['critical', 'high', 'medium', 'low'].map(prio => ({
                            key: prio,
                            label: <Space><Tag color={priorityColors[prio]} style={{ fontWeight: 600 }}>{prio.toUpperCase()}</Tag> Escalation Rules</Space>,
                            children: (
                                <Row gutter={16}>
                                    <Col xs={24} sm={8}>
                                        <Text style={{ fontSize: 11, display: 'block', marginBottom: 4 }}>Level 1 After (min)</Text>
                                        <InputNumber min={1} value={rules[prio]?.l1} onChange={v => updateRule(prio, 'l1', v || 15)} style={{ width: '100%' }} />
                                    </Col>
                                    <Col xs={24} sm={8}>
                                        <Text style={{ fontSize: 11, display: 'block', marginBottom: 4 }}>Level 2 After (min)</Text>
                                        <InputNumber min={1} value={rules[prio]?.l2} onChange={v => updateRule(prio, 'l2', v || 60)} style={{ width: '100%' }} />
                                    </Col>
                                    <Col xs={24} sm={8}>
                                        <Text style={{ fontSize: 11, display: 'block', marginBottom: 4 }}>Notification Targets</Text>
                                        <Input value={rules[prio]?.targets} onChange={e => updateRule(prio, 'targets', e.target.value)} placeholder="email or role" />
                                    </Col>
                                </Row>
                            ),
                        }))}
                    />
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Typography, Alert, Badge, Card, Statistic, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, AlertOutlined, WarningOutlined, ThunderboltOutlined, BellOutlined, ExclamationCircleOutlined, CheckCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { supaRest, supaInsert, supaUpdate, supaDelete } from "@/lib/supaRest";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const severityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a', informational: '#8c8c8c' };
const statusColors: Record<string, string> = { new: 'blue', acknowledged: 'cyan', in_progress: 'orange', escalated: 'red', closed: 'default', suppressed: 'gray' };
const typeColors: Record<string, string> = { informational: 'default', warning: 'gold', exception: 'orange', alert: 'red' };
const typeIcons: Record<string, React.ReactNode> = { informational: <BellOutlined />, warning: <WarningOutlined />, exception: <ThunderboltOutlined />, alert: <AlertOutlined /> };

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "source", label: "Source" },
    { name: "severity", label: "Severity" },
];

export default function EventsPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterSev, setFilterSev] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const filters: Record<string, string> = {};
            if (filterStatus) filters['status'] = `eq.${filterStatus}`;
            if (filterSev) filters['severity'] = `eq.${filterSev}`;
            const rows = await supaRest('itsm_events', { order: 'occurred_at.desc', filters });
            setData(rows);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterSev, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const body: any = { title: values.title, description: values.description, source: values.source || 'manual', event_type: values.event_type || 'warning', severity: values.severity || 'medium', category: values.category, resource_name: values.resource_name, resource_type: values.resource_type, metric_name: values.metric_name, metric_value: values.metric_value, threshold_value: values.threshold_value };
            if (editing) {
                body.status = values.status;
                await supaUpdate('itsm_events', editing.id, body);
                messageApi.success("Event updated.");
            } else {
                const seq = data.length > 0 ? Math.max(...data.map(d => parseInt(d.event_number?.replace('EVT-', '') || '0'))) + 1 : 1;
                body.event_number = `EVT-${String(seq).padStart(4, '0')}`;
                body.tenant_id = 'default';
                body.occurred_at = new Date().toISOString();
                await supaInsert('itsm_events', body);
                messageApi.success(`Event ${body.event_number} created.`);
