"use client";

import React, { useState, useEffect, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import { Card, Row, Col, Table, Space, Progress, message, Typography, Segmented, Tooltip, theme } from "antd";
import {
    ClockCircleOutlined, RiseOutlined, FallOutlined,
    ThunderboltOutlined, ReloadOutlined, FieldTimeOutlined,
    DashboardOutlined, FireOutlined, TeamOutlined, BarChartOutlined,
    ArrowUpOutlined, ArrowDownOutlined,
} from "@ant-design/icons";
import { gql } from "@/lib/graphql";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import {
    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip,
    ResponsiveContainer, PieChart, Pie, Cell, BarChart, Bar,
} from "recharts";
import dayjs from "dayjs";

const { Text } = Typography;

const GET_TICKETS = `query { itsmTickets { id ticketNumber title status priority impact urgency categoryId assignedTo assignedTeam reporterName slaResponseDue slaResolutionDue slaBreached createdAt updatedAt resolvedAt closedAt } }`;
const GET_CATEGORIES = `query { itsmCategories { id name parentId } }`;
const GET_STATS = `query { itsmDashboardStats { totalOpen totalUnassigned totalBreached totalDueToday byPriority byStatus avgResponseTime avgResolutionTime resolvedThisWeek slaComplianceRate } }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
const PERIOD_OPTIONS = ['Last 7 Days', 'Last 30 Days', 'Last 90 Days', 'This Year'];
const DAYS_OF_WEEK = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const HOURS = Array.from({ length: 24 }, (_, i) => i);
const HISTOGRAM_BUCKETS = ['<1h', '1-4h', '4-8h', '8-24h', '1-3d', '3-7d', '>7d'];
const HISTOGRAM_COLORS = ['#52c41a', '#73d13d', '#bae637', '#fadb14', '#fa8c16', '#f5222d', '#cf1322'];

function periodToDays(period: string): number {
    if (period === 'Last 7 Days') return 7;
    if (period === 'Last 30 Days') return 30;
    if (period === 'Last 90 Days') return 90;
    return 365;
}

function fmtDuration(minutes: number): string {
    if (!minutes || minutes <= 0) return '—';
    if (minutes < 60) return `${Math.round(minutes)}m`;
    if (minutes < 1440) return `${(minutes / 60).toFixed(1)}h`;
    return `${(minutes / 1440).toFixed(1)}d`;
}

export default function IncidentAnalyticsPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === "#141414" || antToken.colorBgBase?.includes("14");
    const glass = {
        background: isDark ? "rgba(255,255,255,0.06)" : "rgba(255,255,255,0.65)",
        backdropFilter: "blur(12px)",
        border: `1px solid ${isDark ? "rgba(255,255,255,0.10)" : "rgba(255,255,255,0.45)"}`,
        borderRadius: 14,
    };

    const [messageApi, ctx] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [tickets, setTickets] = useState<any[]>([]);
    const [categories, setCategories] = useState<any[]>([]);
    const [stats, setStats] = useState<any>(null);
    const [period, setPeriod] = useState('Last 30 Days');

    useEffect(() => {
        (async () => {
            try {
                const [t, c, s] = await Promise.all([gql(GET_TICKETS), gql(GET_CATEGORIES), gql(GET_STATS)]);
                setTickets(t.itsmTickets || []);
                setCategories(c.itsmCategories || []);
                setStats(s.itsmDashboardStats || {});
            } catch (err: any) { messageApi.error(err.message); }
            finally { setLoading(false); }
        })();
    }, [messageApi]);

    const cutoff = useMemo(() => dayjs().subtract(periodToDays(period), 'day'), [period]);
    const filtered = useMemo(() => tickets.filter(t => dayjs(t.createdAt).isAfter(cutoff)), [tickets, cutoff]);

    // ── KPI Computations ──────────────────────────────────
    const resolved = useMemo(() => filtered.filter(t => t.resolvedAt), [filtered]);
    const closed = useMemo(() => filtered.filter(t => t.status === 'closed' || t.status === 'resolved'), [filtered]);

    const mttr = useMemo(() => {
        if (resolved.length === 0) return 0;
        const total = resolved.reduce((s, t) => s + dayjs(t.resolvedAt).diff(dayjs(t.createdAt), 'minute'), 0);
        return total / resolved.length;
    }, [resolved]);

    const mtbf = useMemo(() => {
        if (filtered.length < 2) return 0;
        const sorted = [...filtered].sort((a, b) => dayjs(a.createdAt).unix() - dayjs(b.createdAt).unix());
        let totalGap = 0;
        for (let i = 1; i < sorted.length; i++) {
            totalGap += dayjs(sorted[i].createdAt).diff(dayjs(sorted[i - 1].createdAt), 'minute');
        }
        return totalGap / (sorted.length - 1);
    }, [filtered]);

    const avgFirstResponse = useMemo(() => {
        const withUpdate = filtered.filter(t => t.updatedAt && t.updatedAt !== t.createdAt);
        if (withUpdate.length === 0) return 0;
        const total = withUpdate.reduce((s, t) => s + dayjs(t.updatedAt).diff(dayjs(t.createdAt), 'minute'), 0);
        return total / withUpdate.length;
    }, [filtered]);

    const reopenedRate = useMemo(() => {
        const reopened = filtered.filter(t => t.status === 'open' && t.resolvedAt);
        return filtered.length > 0 ? (reopened.length / filtered.length) * 100 : 0;
    }, [filtered]);

    const resolutionRate = useMemo(() => {
        return filtered.length > 0 ? (closed.length / filtered.length) * 100 : 0;
    }, [filtered, closed]);

    const backlogGrowth = useMemo(() => {
        const created = filtered.length;
        const resolvedCount = resolved.length;
        return created - resolvedCount;
    }, [filtered, resolved]);

    const kpis = [
        { title: 'MTTR', value: fmtDuration(mttr), icon: <ClockCircleOutlined />, color: '#722ed1', sub: 'Mean Time to Resolve' },
        { title: 'MTBF', value: fmtDuration(mtbf), icon: <FieldTimeOutlined />, color: '#13c2c2', sub: 'Mean Time Between Failures' },
        { title: 'First Response', value: fmtDuration(avgFirstResponse), icon: <ThunderboltOutlined />, color: '#1890ff', sub: 'Avg first response time' },
        { title: 'Reopened Rate', value: `${reopenedRate.toFixed(1)}%`, icon: <ReloadOutlined />, color: '#fa8c16', sub: 'Resolved → reopened' },
        { title: 'Resolution Rate', value: `${resolutionRate.toFixed(1)}%`, icon: <DashboardOutlined />, color: '#52c41a', sub: `${closed.length} of ${filtered.length}` },
        { title: 'Backlog Growth', value: `${backlogGrowth >= 0 ? '+' : ''}${backlogGrowth}`, icon: backlogGrowth > 0 ? <ArrowUpOutlined /> : <ArrowDownOutlined />, color: backlogGrowth > 0 ? '#f5222d' : '#52c41a', sub: 'New minus resolved' },
    ];

    // ── Incident Volume Trend ─────────────────────────────
    const volumeTrend = useMemo(() => {
        const days = periodToDays(period);
        const useWeekly = days > 30;
        const buckets: Record<string, { created: number; resolved: number }> = {};
        for (let i = days - 1; i >= 0; i--) {
            const d = dayjs().subtract(i, 'day');
            const key = useWeekly ? d.startOf('week').format('MM/DD') : d.format('MM/DD');
            if (!buckets[key]) buckets[key] = { created: 0, resolved: 0 };
        }
        filtered.forEach(t => {
            const key = useWeekly ? dayjs(t.createdAt).startOf('week').format('MM/DD') : dayjs(t.createdAt).format('MM/DD');
            if (buckets[key]) buckets[key].created++;
        });
        resolved.forEach(t => {
            const key = useWeekly ? dayjs(t.resolvedAt).startOf('week').format('MM/DD') : dayjs(t.resolvedAt).format('MM/DD');
            if (buckets[key]) buckets[key].resolved++;
        });
        return Object.entries(buckets).map(([date, v]) => ({ date, Created: v.created, Resolved: v.resolved }));
    }, [period, filtered, resolved]);

    // ── Category Breakdown ────────────────────────────────
    const categoryBreakdown = useMemo(() => {
        const catMap: Record<string, string> = {};
        categories.forEach(c => { catMap[c.id] = c.name; });
        const counts: Record<string, number> = {};
        filtered.forEach(t => {
            const name = catMap[t.categoryId] || 'Uncategorized';
            counts[name] = (counts[name] || 0) + 1;
        });
        return Object.entries(counts)
            .map(([name, count]) => ({ name, count }))
            .sort((a, b) => b.count - a.count)
            .slice(0, 10);
    }, [filtered, categories]);

    // ── Priority Distribution (Donut) ─────────────────────
    const priorityDist = useMemo(() => {
        const counts: Record<string, number> = { critical: 0, high: 0, medium: 0, low: 0 };
        filtered.forEach(t => { if (counts[t.priority] !== undefined) counts[t.priority]++; });
        return Object.entries(counts).map(([name, value]) => ({ name: name.charAt(0).toUpperCase() + name.slice(1), value, color: priorityColors[name] }));
    }, [filtered]);

    // ── Resolution Time Histogram ─────────────────────────
    const resolutionHistogram = useMemo(() => {
        const buckets = [0, 0, 0, 0, 0, 0, 0];
        resolved.forEach(t => {
            const mins = dayjs(t.resolvedAt).diff(dayjs(t.createdAt), 'minute');
            if (mins < 60) buckets[0]++;
            else if (mins < 240) buckets[1]++;
            else if (mins < 480) buckets[2]++;
            else if (mins < 1440) buckets[3]++;
            else if (mins < 4320) buckets[4]++;
            else if (mins < 10080) buckets[5]++;
            else buckets[6]++;
        });
        return HISTOGRAM_BUCKETS.map((label, i) => ({ bucket: label, count: buckets[i], fill: HISTOGRAM_COLORS[i] }));
    }, [resolved]);

    // ── Top Assignees ─────────────────────────────────────
    const topAssignees = useMemo(() => {
        const map: Record<string, { assigned: number; resolved: number; totalResolTime: number; slaOk: number }> = {};
        filtered.forEach(t => {
            const name = t.assignedTo || 'Unassigned';
            if (!map[name]) map[name] = { assigned: 0, resolved: 0, totalResolTime: 0, slaOk: 0 };
            map[name].assigned++;
            if (t.resolvedAt) {
                map[name].resolved++;
                map[name].totalResolTime += dayjs(t.resolvedAt).diff(dayjs(t.createdAt), 'minute');
            }
            if (!t.slaBreached) map[name].slaOk++;
        });
        return Object.entries(map)
            .filter(([name]) => name !== 'Unassigned')
            .map(([name, v]) => ({
                name, assigned: v.assigned, resolved: v.resolved,
                avgResol: v.resolved > 0 ? v.totalResolTime / v.resolved : 0,
                compliance: v.assigned > 0 ? Math.round((v.slaOk / v.assigned) * 100) : 100,
            }))
            .sort((a, b) => b.resolved - a.resolved)
            .slice(0, 10);
    }, [filtered]);

    const assigneeCols = [
        { title: 'Assignee', dataIndex: 'name', ellipsis: true },
        { title: 'Assigned', dataIndex: 'assigned', width: 80, sorter: (a: any, b: any) => a.assigned - b.assigned },
        { title: 'Resolved', dataIndex: 'resolved', width: 80, sorter: (a: any, b: any) => a.resolved - b.resolved },
        { title: 'Avg Resolution', dataIndex: 'avgResol', width: 120, render: (v: number) => fmtDuration(v) },
        {
            title: 'SLA Compliance', dataIndex: 'compliance', width: 160,
            render: (v: number) => <Progress percent={v} size="small" strokeColor={v >= 90 ? '#52c41a' : v >= 70 ? '#fa8c16' : '#f5222d'} format={p => `${p}%`} />,
        },
    ];

    // ── Hourly Heatmap ────────────────────────────────────
    const heatmapData = useMemo(() => {
        const grid: number[][] = Array.from({ length: 7 }, () => new Array(24).fill(0));
        filtered.forEach(t => {
            const d = dayjs(t.createdAt);
            const dow = (d.day() + 6) % 7; // Mon=0
            grid[dow][d.hour()]++;
        });
        return grid;
    }, [filtered]);

    const heatmapMax = useMemo(() => Math.max(1, ...heatmapData.flat()), [heatmapData]);

    const chartTextColor = isDark ? 'rgba(255,255,255,0.65)' : '#666';
    const gridStroke = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)';

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#3b82f6", "#8b5cf6"]}>Incident Analytics</AuroraText>}
            subTitle={<DecryptedText text="Comprehensive incident metrics & operational intelligence" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            {ctx}

            {/* ─── 1. Time Period Selector ──────────── */}
            <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: 16 }}>
                <Segmented
                    options={PERIOD_OPTIONS}
                    value={period}
                    onChange={v => setPeriod(v as string)}
                    style={{ background: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(255,255,255,0.75)', borderRadius: 10 }}
                />
                <Text type="secondary" style={{ marginLeft: 12, fontSize: 12 }}>
                    {filtered.length} incidents in period
                </Text>
            </motion.div>

            {/* ─── 2. KPI Cards ────────────────────── */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {kpis.map((k, i) => (
                    <Col xs={12} sm={8} md={4} key={k.title}>
                        <motion.div initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${k.color}`, overflow: 'hidden' }} styles={{ body: { padding: '14px 16px' } }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                                    <span style={{ color: k.color, fontSize: 16 }}>{k.icon}</span>
                                    <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.5)' : '#999' }}>{k.title}</Text>
                                </div>
                                <Text strong style={{ fontSize: 22, color: k.color, display: 'block', lineHeight: 1.2 }}>{k.value}</Text>
                                <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.4)' : '#bbb' }}>{k.sub}</Text>
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* ─── 3. Incident Volume + 4. Category ── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24} md={16}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                        <Card size="small" title={<Space><RiseOutlined style={{ color: themeColor }} /> Incident Volume Trend</Space>} style={{ ...glass, height: '100%' }}>
                            <ResponsiveContainer width="100%" height={300}>
                                <AreaChart data={volumeTrend}>
                                    <defs>
                                        <linearGradient id="gradCreated" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#1890ff" stopOpacity={0.3} />
                                            <stop offset="95%" stopColor="#1890ff" stopOpacity={0.02} />
                                        </linearGradient>
                                        <linearGradient id="gradResolved" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#52c41a" stopOpacity={0.3} />
                                            <stop offset="95%" stopColor="#52c41a" stopOpacity={0.02} />
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                    <XAxis dataKey="date" tick={{ fontSize: 10, fill: chartTextColor }} interval="preserveStartEnd" />
                                    <YAxis allowDecimals={false} tick={{ fontSize: 10, fill: chartTextColor }} />
                                    <RTooltip contentStyle={{ borderRadius: 10, fontSize: 12, background: isDark ? '#1f1f1f' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : '#eee'}` }} />
                                    <Area type="monotone" dataKey="Created" stroke="#1890ff" strokeWidth={2} fill="url(#gradCreated)" />
                                    <Area type="monotone" dataKey="Resolved" stroke="#52c41a" strokeWidth={2} fill="url(#gradResolved)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>

                <Col xs={24} md={8}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }}>
                        <Card size="small" title={<Space><BarChartOutlined style={{ color: themeColor }} /> Top Categories</Space>} style={{ ...glass, height: '100%' }}>
                            <ResponsiveContainer width="100%" height={300}>
                                <BarChart data={categoryBreakdown} layout="vertical" margin={{ left: 10, right: 30 }}>
                                    <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} horizontal={false} />
                                    <XAxis type="number" tick={{ fontSize: 10, fill: chartTextColor }} allowDecimals={false} />
                                    <YAxis dataKey="name" type="category" tick={{ fontSize: 10, fill: chartTextColor }} width={90} />
                                    <RTooltip contentStyle={{ borderRadius: 10, fontSize: 12, background: isDark ? '#1f1f1f' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : '#eee'}` }} />
                                    <Bar dataKey="count" fill={themeColor} radius={[0, 6, 6, 0]} label={{ position: 'right', fontSize: 10, fill: chartTextColor }} />
                                </BarChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ─── 5. Priority Donut + 6. Resolution Histogram ── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                        <Card size="small" title={<Space><FireOutlined style={{ color: '#f5222d' }} /> Priority Distribution</Space>} style={{ ...glass, height: '100%' }}>
                            <ResponsiveContainer width="100%" height={280}>
                                <PieChart>
                                    <Pie
                                        data={priorityDist}
                                        dataKey="value"
                                        nameKey="name"
                                        cx="50%" cy="50%"
                                        innerRadius={60} outerRadius={100}
                                        paddingAngle={3}
                                        label={({ name, value }) => `${name}: ${value}`}
                                    >
                                        {priorityDist.map((d, i) => <Cell key={i} fill={d.color} />)}
                                    </Pie>
                                    <RTooltip contentStyle={{ borderRadius: 10, fontSize: 12, background: isDark ? '#1f1f1f' : '#fff' }} />
                                    <text x="50%" y="46%" textAnchor="middle" dominantBaseline="central" style={{ fontSize: 26, fontWeight: 700, fill: isDark ? '#fff' : '#333' }}>
                                        {filtered.length}
                                    </text>
                                    <text x="50%" y="57%" textAnchor="middle" dominantBaseline="central" style={{ fontSize: 11, fill: isDark ? 'rgba(255,255,255,0.5)' : '#999' }}>
                                        Total
                                    </text>
                                </PieChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>

                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.35 }}>
                        <Card size="small" title={<Space><ClockCircleOutlined style={{ color: '#722ed1' }} /> Resolution Time Distribution</Space>} style={{ ...glass, height: '100%' }}>
                            <ResponsiveContainer width="100%" height={280}>
                                <BarChart data={resolutionHistogram}>
                                    <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                                    <XAxis dataKey="bucket" tick={{ fontSize: 10, fill: chartTextColor }} />
                                    <YAxis allowDecimals={false} tick={{ fontSize: 10, fill: chartTextColor }} />
                                    <RTooltip contentStyle={{ borderRadius: 10, fontSize: 12, background: isDark ? '#1f1f1f' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : '#eee'}` }} />
                                    <Bar dataKey="count" radius={[6, 6, 0, 0]} label={{ position: 'top', fontSize: 10, fill: chartTextColor }}>
                                        {resolutionHistogram.map((d, i) => <Cell key={i} fill={d.fill} />)}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ─── 7. Top Assignees Table ──────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>
                <Card
                    size="small"
                    title={<Space><TeamOutlined style={{ color: themeColor }} /> Top Assignees</Space>}
                    style={{ ...glass, marginBottom: 16 }}
                >
                    <Table
                        dataSource={topAssignees}
                        columns={assigneeCols}
                        rowKey="name"
                        size="small"
                        pagination={false}
                        loading={loading}
                        scroll={{ x: 600 }}
                    />
                </Card>
            </motion.div>

            {/* ─── 8. Hourly Heatmap ───────────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.45 }}>
                <Card
                    size="small"
                    title={<Space><FallOutlined style={{ color: '#9254de' }} /> Incident Heatmap — When Incidents Occur</Space>}
                    style={{ ...glass }}
                >
                    <div style={{ overflowX: 'auto' }}>
                        <div style={{ display: 'grid', gridTemplateColumns: `60px repeat(24, 1fr)`, gap: 2, minWidth: 700 }}>
                            {/* Header row */}
                            <div />
                            {HOURS.map(h => (
                                <div key={h} style={{ textAlign: 'center', fontSize: 9, color: isDark ? 'rgba(255,255,255,0.4)' : '#999', padding: '4px 0' }}>
                                    {h.toString().padStart(2, '0')}
                                </div>
                            ))}

                            {/* Data rows */}
                            {DAYS_OF_WEEK.map((day, rowIdx) => (
                                <React.Fragment key={day}>
                                    <div style={{ fontSize: 11, fontWeight: 600, color: isDark ? 'rgba(255,255,255,0.6)' : '#666', display: 'flex', alignItems: 'center' }}>
                                        {day}
                                    </div>
                                    {HOURS.map(h => {
                                        const val = heatmapData[rowIdx]?.[h] || 0;
                                        const intensity = val / heatmapMax;
                                        return (
                                            <Tooltip key={h} title={`${day} ${h.toString().padStart(2, '0')}:00 — ${val} incident${val !== 1 ? 's' : ''}`}>
                                                <div
                                                    style={{
                                                        borderRadius: 3,
                                                        aspectRatio: '1',
                                                        minHeight: 18,
                                                        background: val === 0
                                                            ? isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.03)'
                                                            : `rgba(${isDark ? '139,92,246' : '114,46,209'}, ${0.15 + intensity * 0.85})`,
                                                        cursor: 'default',
                                                        transition: 'background 0.2s',
                                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                        fontSize: 8,
                                                        color: intensity > 0.5 ? '#fff' : 'transparent',
                                                        fontWeight: 700,
                                                    }}
                                                >
                                                    {val > 0 ? val : ''}
                                                </div>
                                            </Tooltip>
                                        );
                                    })}
                                </React.Fragment>
                            ))}
                        </div>
                    </div>

                    {/* Heatmap legend */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 12, justifyContent: 'flex-end' }}>
                        <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.4)' : '#999' }}>Less</Text>
                        {[0.1, 0.3, 0.5, 0.7, 0.9].map(v => (
                            <div key={v} style={{ width: 14, height: 14, borderRadius: 3, background: `rgba(${isDark ? '139,92,246' : '114,46,209'}, ${v})` }} />
                        ))}
                        <Text style={{ fontSize: 10, color: isDark ? 'rgba(255,255,255,0.4)' : '#999' }}>More</Text>
                    </div>
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Typography, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, BookOutlined, FileTextOutlined, TagOutlined, CheckCircleOutlined, EyeOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_ARTICLES = `query($status: String, $articleType: String, $search: String) { itsmKnowledgeArticles(status: $status, articleType: $articleType, search: $search) { id articleNumber title content categoryId articleType status relatedProblemId author tags views helpfulCount publishedAt createdAt } }`;
const GET_CATEGORIES = `query { itsmCategories { id name } }`;
const CREATE_ARTICLE = `mutation($tenantId: String!, $input: CreateItsmKnowledgeInput!) { createItsmKnowledgeArticle(tenantId: $tenantId, input: $input) { id articleNumber } }`;
const UPDATE_ARTICLE = `mutation($id: ID!, $input: UpdateItsmKnowledgeInput!) { updateItsmKnowledgeArticle(id: $id, input: $input) { id } }`;
const DELETE_ARTICLE = `mutation($id: ID!) { deleteItsmKnowledgeArticle(id: $id) }`;

const statusColors: Record<string, string> = { draft: 'default', review: 'blue', published: 'green', archived: 'red' };
const typeColors: Record<string, string> = { solution: 'green', workaround: 'orange', faq: 'blue', how_to: 'cyan', reference: 'purple' };

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "content", label: "Content" },
    { name: "articleType", label: "Article Type" },
    { name: "author", label: "Author" },
];

export default function ItsmKnowledgePage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterType, setFilterType] = useState<string | undefined>(undefined);
    const [searchText, setSearchText] = useState('');

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [d, c] = await Promise.all([
                gql(GET_ARTICLES, { status: filterStatus, articleType: filterType, search: searchText || undefined }),
                gql(GET_CATEGORIES),
            ]);
            setData(d.itsmKnowledgeArticles || []);
            setCategories(c.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterType, searchText, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const input: any = {
                title: values.title, content: values.content, categoryId: values.categoryId,
                articleType: values.articleType || 'solution', author: values.author,
                tags: values.tags ? values.tags.split(',').map((t: string) => t.trim()).filter(Boolean) : [],
            };
            if (editing) {
                input.status = values.status;
                await gql(UPDATE_ARTICLE, { id: editing.id, input });
                messageApi.success("Article updated.");
            } else {
                const d = await gql(CREATE_ARTICLE, { tenantId: DEFAULT_TENANT_ID, input });
                messageApi.success(`Article ${d.createItsmKnowledgeArticle.articleNumber} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_ARTICLE, { id }); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'articleNumber', width: 100, render: (_, r) => <Tag color="purple" style={{ fontFamily: 'monospace' }}>{r.articleNumber}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Type', dataIndex: 'articleType', width: 110, render: (_, r) => <Tag color={typeColors[r.articleType]}>{(r.articleType || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 100, render: (_, r) => <Tag color={statusColors[r.status]}>{(r.status || '').toUpperCase()}</Tag> },
        { title: 'Author', dataIndex: 'author', width: 120, ellipsis: true },
        { title: 'ðŸ‘', dataIndex: 'views', width: 60, render: (_, r) => r.views || 0 },
        { title: 'ðŸ‘', dataIndex: 'helpfulCount', width: 60, render: (_, r) => r.helpfulCount || 0 },
        { title: 'Tags', dataIndex: 'tags', width: 150, ellipsis: true, render: (_, r) => (r.tags || []).slice(0, 3).map((t: string) => <Tag key={t} style={{ fontSize: 11 }}>{t}</Tag>) },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => {
                    setEditing(record);
                    form.setFieldsValue({ ...record, tags: (record.tags || []).join(', ') });
                    setModalOpen(true);
                }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Knowledge Base</AuroraText>}
            subTitle={<DecryptedText text="Solutions, FAQs, and how-to guides" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Articles', value: data.length, icon: <BookOutlined />, color: '#3b82f6' },
                    { title: 'Published', value: data.filter((d: any) => d.status === 'published').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Draft', value: data.filter((d: any) => d.status === 'draft').length, icon: <FileTextOutlined />, color: '#f59e0b' },
                    { title: 'Total Views', value: data.reduce((s: number, d: any) => s + (d.viewCount || 0), 0), icon: <EyeOutlined />, color: '#8b5cf6' },
                    { title: 'Helpful', value: data.reduce((s: number, d: any) => s + (d.helpfulCount || 0), 0), icon: <CheckCircleOutlined />, color: '#06b6d4' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <ProTable
                headerTitle={<Space><BookOutlined /> Knowledge Base <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolbar={{
                    search: { placeholder: 'Search articles...', onSearch: (v) => setSearchText(v), allowClear: true, style: { width: 250 } },
                }}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_knowledge', title: 'Knowledge Base', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Type', key: 'article_type' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_knowledge', title: 'Knowledge Base', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Type', key: 'article_type' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip></RbacGuard>,
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 120 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'draft', label: 'Draft' }, { value: 'review', label: 'Review' }, { value: 'published', label: 'Published' }, { value: 'archived', label: 'Archived' }]} />,
                    <Select key="ft" placeholder="Type" allowClear style={{ width: 130 }} value={filterType} onChange={setFilterType}
                        options={[{ value: 'solution', label: 'Solution' }, { value: 'workaround', label: 'Workaround' }, { value: 'faq', label: 'FAQ' }, { value: 'how_to', label: 'How-To' }, { value: 'reference', label: 'Reference' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Article</Button>,
                ]}
            />

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? `Edit ${editing.articleNumber}` : "New Knowledge Article"}
                entityName="article"
                steps={[
                    {
                        title: "Article Info",
                        icon: <FileTextOutlined />,
                        fields: ["title", "articleType", "categoryId", "author"],
                        content: (
                            <>
                                <Form.Item name="title" label="Article Title" rules={[{ required: true }]}><Input placeholder="How to..., Solution for..., FAQ:..." /></Form.Item>
                                <Row gutter={16}>
                                    <Col span={8}>
                                        <Form.Item name="articleType" label="Article Type">
                                            <Select options={[{ value: 'solution', label: 'âœ… Solution' }, { value: 'workaround', label: 'ðŸ”§ Workaround' }, { value: 'faq', label: 'â“ FAQ' }, { value: 'how_to', label: 'ðŸ“– How-To' }, { value: 'reference', label: 'ðŸ“Ž Reference' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={8}>
                                        <Form.Item name="categoryId" label="Category">
                                            <Select placeholder="Select" allowClear options={categories.map(c => ({ value: c.id, label: c.name }))} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={8}><Form.Item name="author" label="Author"><Input placeholder="Your name" /></Form.Item></Col>
                                </Row>
                                {editing && (
                                    <Form.Item name="status" label="Status">
                                        <Select options={[{ value: 'draft', label: 'Draft' }, { value: 'review', label: 'In Review' }, { value: 'published', label: 'Published' }, { value: 'archived', label: 'Archived' }]} />
                                    </Form.Item>
                                )}
                            </>
                        ),
                    },
                    {
                        title: "Content",
                        icon: <BookOutlined />,
                        fields: ["content"],
                        content: (
                            <Form.Item name="content" label="Article Content">
                                <Input.TextArea rows={12} placeholder="Write the knowledge article content here. You can use markdown formatting." />
                            </Form.Item>
                        ),
                    },
                    {
                        title: "Tags & Metadata",
                        icon: <TagOutlined />,
                        fields: ["tags"],
                        content: (
                            <Form.Item name="tags" label="Tags (comma-separated)">
                                <Input placeholder="e.g., network, vpn, troubleshooting, windows" />
                            </Form.Item>
                        ),
                    },
                ]}
                fields={FIELDS}
                width={800}
                
                editMode={!!editing}
                initialValues={{ articleType: 'solution' }}
            />
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, InputNumber, Typography, Card, Statistic, Badge, Tooltip } from "antd";
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { PlusOutlined, DeleteOutlined, EditOutlined, ProjectOutlined, RocketOutlined, SendOutlined, CheckCircleOutlined, ClockCircleOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_PORTFOLIO = `query($lifecycleStatus: String, $serviceType: String, $search: String) { itsmPortfolioServices(lifecycleStatus: $lifecycleStatus, serviceType: $serviceType, search: $search) { id serviceCode name description businessOwner technicalOwner lifecycleStatus serviceType criticality costCenter budgetAllocated slaTarget dependencies risks notes publishedToCatalog publishedAt createdAt } }`;
const CREATE_PORTFOLIO = `mutation($tenantId: String!, $input: CreateItsmPortfolioInput!) { createItsmPortfolioService(tenantId: $tenantId, input: $input) { id serviceCode } }`;
const UPDATE_PORTFOLIO = `mutation($id: ID!, $input: UpdateItsmPortfolioInput!) { updateItsmPortfolioService(id: $id, input: $input) { id } }`;
const DELETE_PORTFOLIO = `mutation($id: ID!) { deleteItsmPortfolioService(id: $id) }`;
const PUBLISH_TO_CATALOG = `mutation($portfolioId: String!, $input: PublishToCatalogInput!) { itsmPublishToCatalog(portfolioId: $portfolioId, input: $input) { id catalogCode name } }`;

const lifecycleColors: Record<string, string> = { pipeline: 'default', design: 'blue', transition: 'geekblue', operation: 'green', retired: 'red' };
const criticalityColors: Record<string, string> = { low: 'green', medium: 'blue', high: 'orange', critical: 'red' };
const typeLabels: Record<string, string> = { business: 'ðŸ¢ Business', technical: 'ðŸ”§ Technical', supporting: 'ðŸ”— Supporting' };

const FIELDS: FieldDef[] = [
    { name: "name", label: "Service Name", required: true },
    { name: "description", label: "Description" },
    { name: "serviceType", label: "Service Type" },
    { name: "lifecycleStatus", label: "Lifecycle Status" },
    { name: "criticality", label: "Criticality" },
    { name: "businessOwner", label: "Business Owner" },
    { name: "technicalOwner", label: "Technical Owner" },
];

export default function ItsmPortfolioPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [publishModalOpen, setPublishModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [publishTarget, setPublishTarget] = useState<any>(null);
    const [form] = Form.useForm();
    const [publishForm] = Form.useForm();
    const [filterLifecycle, setFilterLifecycle] = useState<string | undefined>(undefined);
    const [filterType, setFilterType] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const d = await gql(GET_PORTFOLIO, { lifecycleStatus: filterLifecycle, serviceType: filterType });
            setData(d.itsmPortfolioServices || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterLifecycle, filterType, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const input = {
                name: values.name, description: values.description,
                businessOwner: values.businessOwner, technicalOwner: values.technicalOwner,
                lifecycleStatus: values.lifecycleStatus || 'pipeline',
                serviceType: values.serviceType || 'business',
                criticality: values.criticality || 'medium',
                costCenter: values.costCenter, budgetAllocated: values.budgetAllocated ? Number(values.budgetAllocated) : undefined,
                slaTarget: values.slaTarget, dependencies: values.dependencies,
                risks: values.risks, notes: values.notes,
            };
            if (editing) {
                await gql(UPDATE_PORTFOLIO, { id: editing.id, input });
                messageApi.success("Service updated.");
            } else {
                const d = await gql(CREATE_PORTFOLIO, { tenantId: DEFAULT_TENANT_ID, input });
                messageApi.success(`Service ${d.createItsmPortfolioService.serviceCode} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handlePublish = async (values: any) => {
        try {
            const d = await gql(PUBLISH_TO_CATALOG, {
                portfolioId: publishTarget.id,
                input: {
                    name: values.catalogName || publishTarget.name,
                    shortDescription: values.shortDescription,
                    estimatedDelivery: values.estimatedDelivery,
                    cost: values.cost,
                    approvalRequired: values.approvalRequired || false,
                    approvalType: values.approvalType || 'simple',
                    fulfillmentGroup: values.fulfillmentGroup,
                },
            });
            messageApi.success(`Published to catalog as ${d.itsmPublishToCatalog.catalogCode}`);
            setPublishModalOpen(false); publishForm.resetFields(); setPublishTarget(null); loadData();
        } catch (err: any) { messageApi.error(`Publish failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_PORTFOLIO, { id }); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: 'Code', dataIndex: 'serviceCode', width: 110, render: (_, r) => <Tag color="blue" style={{ fontFamily: 'monospace' }}>{r.serviceCode}</Tag> },
        { title: 'Service Name', dataIndex: 'name', ellipsis: true },
        { title: 'Type', dataIndex: 'serviceType', width: 120, render: (_, r) => typeLabels[r.serviceType] || r.serviceType },
        { title: 'Lifecycle', dataIndex: 'lifecycleStatus', width: 120, render: (_, r) => <Tag color={lifecycleColors[r.lifecycleStatus]}>{(r.lifecycleStatus || '').toUpperCase()}</Tag> },
        { title: 'Criticality', dataIndex: 'criticality', width: 100, render: (_, r) => <Tag color={criticalityColors[r.criticality]}>{(r.criticality || '').toUpperCase()}</Tag> },
        { title: 'Business Owner', dataIndex: 'businessOwner', width: 140, ellipsis: true },
        { title: 'Catalog', dataIndex: 'publishedToCatalog', width: 80, render: (_, r) => r.publishedToCatalog ? <Tag color="green">âœ“</Tag> : <Tag>â€”</Tag> },
        {
            title: 'Actions', valueType: 'option', width: 150,
            render: (_, record) => [
                !record.publishedToCatalog && record.lifecycleStatus === 'operation' && (
                    <Button key="pub" type="text" icon={<SendOutlined />} style={{ color: '#52c41a' }}
                        onClick={() => { setPublishTarget(record); publishForm.resetFields(); setPublishModalOpen(true); }} />
                ),
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => {
                    setEditing(record);
                    form.setFieldsValue(record);
                    setModalOpen(true);
                }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ].filter(Boolean),
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Service Portfolio</AuroraText>}
            subTitle={<DecryptedText text="Manage the lifecycle of IT services" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <BentoGrid className="mb-4">
                {[
                    { title: 'Total Services', value: data.length, icon: <ProjectOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: data.filter((d: any) => d.lifecycleStatus === 'active' || d.lifecycleStatus === 'operational').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Pipeline', value: data.filter((d: any) => d.lifecycleStatus === 'pipeline' || d.lifecycleStatus === 'design').length, icon: <RocketOutlined />, color: '#f59e0b' },
                    { title: 'Retiring', value: data.filter((d: any) => d.lifecycleStatus === 'retiring' || d.lifecycleStatus === 'retired').length, icon: <ClockCircleOutlined />, color: '#ef4444' },
                    { title: 'Published', value: data.filter((d: any) => d.publishedToCatalog).length, icon: <SendOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <BentoGridItem
                        key={i}
                        title={s.title}
                        description="Service lifecycle metric"
                        icon={<span style={{ color: s.color }}>{s.icon}</span>}
                        className={i === 4 ? "col-span-3 lg:col-span-1 lg:col-start-2" : "col-span-3 lg:col-span-1"}
                        header={
                            <div className="flex h-full w-full flex-col items-center justify-center rounded-xl" style={{ backgroundColor: `${s.color}15` }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: s.color }}>
                                    {s.value}
                                </div>
                            </div>
                        }
                    />
                ))}
            </BentoGrid>
            <ProTable
                headerTitle={<Space><ProjectOutlined /> Service Portfolio <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_portfolio', title: 'Service Portfolio', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'service_type' }, { header: 'Lifecycle', key: 'lifecycle_stage' }], data: data })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_portfolio', title: 'Service Portfolio', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'service_type' }, { header: 'Lifecycle', key: 'lifecycle_stage' }], data: data })} /></Tooltip></RbacGuard>,
                    <Select key="fl" placeholder="Lifecycle" allowClear style={{ width: 140 }} value={filterLifecycle} onChange={setFilterLifecycle}
                        options={[{ value: 'pipeline', label: 'Pipeline' }, { value: 'design', label: 'Design' }, { value: 'transition', label: 'Transition' }, { value: 'operation', label: 'Operation' }, { value: 'retired', label: 'Retired' }]} />,
                    <Select key="ft" placeholder="Type" allowClear style={{ width: 130 }} value={filterType} onChange={setFilterType}
                        options={[{ value: 'business', label: 'Business' }, { value: 'technical', label: 'Technical' }, { value: 'supporting', label: 'Supporting' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Service</Button>,
                ]}
            />

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? `Edit ${editing.serviceCode}` : "New Service"}
                entityName="service"
                steps={[
                    {
                        title: "Service Info",
                        icon: <ProjectOutlined />,
                        fields: ["name", "description", "serviceType"],
                        content: (
                            <>
                                <Form.Item name="name" label="Service Name" rules={[{ required: true }]}><Input placeholder="e.g., Email Service, VPN Access" /></Form.Item>
                                <Form.Item name="description" label="Description"><Input.TextArea rows={3} placeholder="What this service provides..." /></Form.Item>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="serviceType" label="Service Type">
                                            <Select options={[{ value: 'business', label: 'ðŸ¢ Business' }, { value: 'technical', label: 'ðŸ”§ Technical' }, { value: 'supporting', label: 'ðŸ”— Supporting' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="criticality" label="Criticality">
                                            <Select options={[{ value: 'low', label: 'ðŸŸ¢ Low' }, { value: 'medium', label: 'ðŸ”µ Medium' }, { value: 'high', label: 'ðŸŸ  High' }, { value: 'critical', label: 'ðŸ”´ Critical' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                            </>
                        ),
                    },
                    {
                        title: "Ownership & Budget",
                        icon: <RocketOutlined />,
                        fields: ["businessOwner", "technicalOwner", "costCenter", "budgetAllocated"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}><Form.Item name="businessOwner" label="Business Owner"><Input placeholder="Name" /></Form.Item></Col>
                                    <Col span={12}><Form.Item name="technicalOwner" label="Technical Owner"><Input placeholder="Name" /></Form.Item></Col>
                                </Row>
                                <Row gutter={16}>
                                    <Col span={12}><Form.Item name="costCenter" label="Cost Center"><Input placeholder="e.g., IT-001" /></Form.Item></Col>
                                    <Col span={12}><Form.Item name="budgetAllocated" label="Budget"><InputNumber style={{ width: '100%' }} placeholder="Budget amount" /></Form.Item></Col>
                                </Row>
                            </>
                        ),
                    },
                    {
                        title: "Lifecycle & Risk",
                        icon: <RocketOutlined />,
                        fields: ["lifecycleStatus", "slaTarget", "dependencies", "risks", "notes"],
                        content: (
                            <>
                                <Form.Item name="lifecycleStatus" label="Lifecycle Status">
                                    <Select options={[{ value: 'pipeline', label: 'ðŸ“‹ Pipeline' }, { value: 'design', label: 'ðŸ“ Design' }, { value: 'transition', label: 'ðŸ”„ Transition' }, { value: 'operation', label: 'âœ… Operation' }, { value: 'retired', label: 'ðŸ—„ï¸ Retired' }]} />
                                </Form.Item>
                                <Form.Item name="slaTarget" label="SLA Target"><Input placeholder="e.g., 99.9% uptime" /></Form.Item>
                                <Form.Item name="dependencies" label="Dependencies"><Input.TextArea rows={2} placeholder="Other services this depends on" /></Form.Item>
                                <Form.Item name="risks" label="Risks"><Input.TextArea rows={2} placeholder="Known risks" /></Form.Item>
                                <Form.Item name="notes" label="Notes"><Input.TextArea rows={2} /></Form.Item>
                            </>
                        ),
                    },
                ]}
                fields={FIELDS}
                width={700}
                gradient={["#1890ff", "#096dd9"]}
                editMode={!!editing}
                initialValues={{ serviceType: 'business', criticality: 'medium', lifecycleStatus: 'pipeline' }}
            />

            {/* Publish to Catalog Modal */}
            <SteppedFormModal
                open={publishModalOpen}
                onCancel={() => { setPublishModalOpen(false); setPublishTarget(null); publishForm.resetFields(); }}
                onSubmit={handlePublish}
                form={publishForm}
                title={`Publish "${publishTarget?.name}" to Catalog`}
                entityName="catalog item"
                steps={[
                    {
                        title: "Catalog Details",
                        icon: <SendOutlined />,
                        fields: ["catalogName", "shortDescription", "estimatedDelivery", "cost"],
                        content: (
                            <>
                                <Form.Item name="catalogName" label="Catalog Name"><Input placeholder={publishTarget?.name} /></Form.Item>
                                <Form.Item name="shortDescription" label="Short Description"><Input.TextArea rows={2} placeholder="User-facing description" /></Form.Item>
                                <Row gutter={16}>
                                    <Col span={12}><Form.Item name="estimatedDelivery" label="Delivery Time"><Input placeholder="e.g., 2 business days" /></Form.Item></Col>
                                    <Col span={12}><Form.Item name="cost" label="Cost"><Input placeholder="e.g., Free, $500" /></Form.Item></Col>
                                </Row>
                            </>
                        ),
                    },
                    {
                        title: "Approval & Fulfillment",
                        icon: <RocketOutlined />,
                        fields: ["approvalRequired", "approvalType", "fulfillmentGroup"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="approvalRequired" label="Approval Required?" valuePropName="checked">
                                            <Select options={[{ value: false, label: 'No' }, { value: true, label: 'Yes' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="approvalType" label="Approval Type">
                                            <Select options={[{ value: 'simple', label: 'Simple (1 approver)' }, { value: 'multi_level', label: 'Multi-Level' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                <Form.Item name="fulfillmentGroup" label="Fulfillment Group"><Input placeholder="e.g., IT Service Team" /></Form.Item>
                            </>
                        ),
                    },
                ]}
                fields={[{ name: "catalogName", label: "Name" }, { name: "shortDescription", label: "Description" }]}
                width={650}
                gradient={["#52c41a", "#389e0d"]}
                editMode={false}
                initialValues={{ approvalRequired: false, approvalType: 'simple' }}
            />
        </div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Switch, Typography, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, BugOutlined, SearchOutlined, TeamOutlined, ToolOutlined, CheckCircleOutlined, ClockCircleOutlined, ExclamationCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_PROBLEMS = `query($status: String, $priority: String, $search: String) { itsmProblems(status: $status, priority: $priority, search: $search) { id problemNumber title description categoryId priority status impact rootCause workaround isKnownError knowledgeArticleId assignedTo assignedGroup reporterName reporterEmail resolutionNotes resolvedAt closedAt createdAt } }`;
const GET_CATEGORIES = `query { itsmCategories { id name } }`;
const CREATE_PROBLEM = `mutation($tenantId: String!, $input: CreateItsmProblemInput!) { createItsmProblem(tenantId: $tenantId, input: $input) { id problemNumber } }`;
const UPDATE_PROBLEM = `mutation($id: ID!, $input: UpdateItsmProblemInput!) { updateItsmProblem(id: $id, input: $input) { id } }`;
const DELETE_PROBLEM = `mutation($id: ID!) { deleteItsmProblem(id: $id) }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
const statusColors: Record<string, string> = { new: 'blue', investigating: 'cyan', root_cause_identified: 'geekblue', known_error: 'orange', resolved: 'green', closed: 'default' };

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "description", label: "Description" },
    { name: "priority", label: "Priority" },
    { name: "impact", label: "Impact" },
    { name: "assignedTo", label: "Assigned To" },
];

export default function ItsmProblemsPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterPriority, setFilterPriority] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [d, c] = await Promise.all([gql(GET_PROBLEMS, { status: filterStatus, priority: filterPriority }), gql(GET_CATEGORIES)]);
            setData(d.itsmProblems || []);
            setCategories(c.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterPriority, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(UPDATE_PROBLEM, { id: editing.id, input: {
                    title: values.title, description: values.description, categoryId: values.categoryId,
                    priority: values.priority, status: values.status, impact: values.impact,
                    rootCause: values.rootCause, workaround: values.workaround,
                    isKnownError: values.isKnownError || false, assignedTo: values.assignedTo,
                    assignedGroup: values.assignedGroup, resolutionNotes: values.resolutionNotes,
                }});
                messageApi.success("Problem updated.");
            } else {
                const d = await gql(CREATE_PROBLEM, { tenantId: DEFAULT_TENANT_ID, input: {
                    title: values.title, description: values.description, categoryId: values.categoryId,
                    priority: values.priority || 'medium', impact: values.impact || 'medium',
                    assignedTo: values.assignedTo, assignedGroup: values.assignedGroup,
                    reporterName: values.reporterName, reporterEmail: values.reporterEmail,
                }});
                messageApi.success(`Problem ${d.createItsmProblem.problemNumber} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_PROBLEM, { id }); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'problemNumber', width: 110, render: (_, r) => <Tag color="volcano" style={{ fontFamily: 'monospace' }}>{r.problemNumber}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Priority', dataIndex: 'priority', width: 90, render: (_, r) => <Tag color={priorityColors[r.priority]}>{(r.priority || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 150, render: (_, r) => <Tag color={statusColors[r.status]}>{(r.status || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Impact', dataIndex: 'impact', width: 80, render: (_, r) => <Tag>{(r.impact || '').toUpperCase()}</Tag> },
        { title: 'Known Error', dataIndex: 'isKnownError', width: 100, render: (_, r) => r.isKnownError ? <Tag color="red">Yes</Tag> : <Tag>No</Tag> },
        { title: 'Assigned', dataIndex: 'assignedTo', width: 130, ellipsis: true, render: (_, r) => r.assignedTo || <Text type="secondary" italic>Unassigned</Text> },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Problem Management</AuroraText>}
            subTitle={<DecryptedText text="Root cause investigation and known errors" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Problems', value: data.length, icon: <BugOutlined />, color: '#3b82f6' },
                    { title: 'Open', value: data.filter((d: any) => d.status === 'open' || d.status === 'investigating').length, icon: <SearchOutlined />, color: '#f59e0b' },
                    { title: 'Resolved', value: data.filter((d: any) => d.status === 'resolved' || d.status === 'closed').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Known Errors', value: data.filter((d: any) => d.knownError).length, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'With Workaround', value: data.filter((d: any) => d.workaround).length, icon: <ToolOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <ProTable
                headerTitle={<Space><BugOutlined /> Problems <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 170 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'new', label: 'New' }, { value: 'investigating', label: 'Investigating' }, { value: 'root_cause_identified', label: 'Root Cause ID' }, { value: 'known_error', label: 'Known Error' }, { value: 'resolved', label: 'Resolved' }, { value: 'closed', label: 'Closed' }]} />,
                    <Select key="fp" placeholder="Priority" allowClear style={{ width: 120 }} value={filterPriority} onChange={setFilterPriority}
                        options={[{ value: 'critical', label: 'Critical' }, { value: 'high', label: 'High' }, { value: 'medium', label: 'Medium' }, { value: 'low', label: 'Low' }]} />,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>New Problem</Button>,
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_problems', title: 'Problem Management Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Problem #', key: 'problemNumber' }, { header: 'Title', key: 'title' }, { header: 'Priority', key: 'priority' }, { header: 'Status', key: 'status', format: (v: string) => (v||'').replace(/_/g,' ') }, { header: 'Impact', key: 'impact' }, { header: 'Known Error', key: 'isKnownError', format: (v: boolean) => v ? 'Yes' : 'No' }, { header: 'Assigned', key: 'assignedTo' }], data })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_problems', title: 'Problem Management Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Problem #', key: 'problemNumber' }, { header: 'Title', key: 'title' }, { header: 'Priority', key: 'priority' }, { header: 'Status', key: 'status', format: (v: string) => (v||'').replace(/_/g,' ') }, { header: 'Impact', key: 'impact' }, { header: 'Known Error', key: 'isKnownError', format: (v: boolean) => v ? 'Yes' : 'No' }, { header: 'Assigned', key: 'assignedTo' }], data })} /></Tooltip></RbacGuard>,
                ]}
            />

            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? `Edit ${editing.problemNumber}` : "New Problem"}
                entityName="problem"
                steps={[
                    {
                        title: "Problem Details",
                        icon: <BugOutlined />,
                        fields: ["title", "description"],
                        content: (
                            <>
                                <Form.Item name="title" label="Problem Title" rules={[{ required: true }]}><Input placeholder="Describe the recurring issue" /></Form.Item>
                                <Form.Item name="description" label="Description"><Input.TextArea rows={4} placeholder="What symptoms are being observed across multiple incidents?" /></Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Classification",
                        icon: <ToolOutlined />,
                        fields: ["categoryId", "priority", "impact"],
                        content: (
                            <>
                                <Form.Item name="categoryId" label="Category">
                                    <Select placeholder="Select" allowClear options={categories.map(c => ({ value: c.id, label: c.name }))} />
                                </Form.Item>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="priority" label="Priority">
                                            <Select options={[{ value: 'critical', label: '🔴 Critical' }, { value: 'high', label: '🟠 High' }, { value: 'medium', label: '🔵 Medium' }, { value: 'low', label: '🟢 Low' }]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="impact" label="Impact">
                                            <Select options={[{ value: 'high', label: 'High' }, { value: 'medium', label: 'Medium' }, { value: 'low', label: 'Low' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                {editing && (
                                    <Form.Item name="status" label="Status">
                                        <Select options={[
                                            { value: 'new', label: 'New' }, { value: 'investigating', label: 'Investigating' },
                                            { value: 'root_cause_identified', label: 'Root Cause Identified' },
                                            { value: 'known_error', label: 'Known Error' },
                                            { value: 'resolved', label: 'Resolved' }, { value: 'closed', label: 'Closed' },
                                        ]} />
                                    </Form.Item>
                                )}
                            </>
                        ),
                    },
                    {
                        title: "Root Cause Analysis",
                        icon: <SearchOutlined />,
                        fields: ["rootCause", "workaround", "isKnownError"],
                        content: (
                            <>
                                <Form.Item name="rootCause" label="Root Cause"><Input.TextArea rows={3} placeholder="What was identified as the root cause?" /></Form.Item>
                                <Form.Item name="workaround" label="Workaround"><Input.TextArea rows={3} placeholder="Temporary workaround for affected users" /></Form.Item>
                                <Form.Item name="isKnownError" label="Mark as Known Error" valuePropName="checked"><Switch /></Form.Item>
                                {editing && (
                                    <Form.Item name="resolutionNotes" label="Resolution Notes"><Input.TextArea rows={2} placeholder="How was this resolved permanently?" /></Form.Item>
                                )}
                            </>
                        ),
                    },
                    {
                        title: "Assignment",
                        icon: <TeamOutlined />,
                        fields: ["assignedTo", "assignedGroup", "reporterName", "reporterEmail"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}><Form.Item name="assignedTo" label="Assigned To"><Input placeholder="Investigator" /></Form.Item></Col>
                                    <Col span={12}><Form.Item name="assignedGroup" label="Team"><Input placeholder="e.g., Infrastructure Team" /></Form.Item></Col>
                                </Row>
                                {!editing && (
                                    <Row gutter={16}>
                                        <Col span={12}><Form.Item name="reporterName" label="Reporter Name"><Input /></Form.Item></Col>
                                        <Col span={12}><Form.Item name="reporterEmail" label="Reporter Email"><Input /></Form.Item></Col>
                                    </Row>
                                )}
                            </>
                        ),
                    },
                ]}
                fields={FIELDS}
                width={750}
                gradient={["#fa541c", "#d4380d"]}
                editMode={!!editing}
                initialValues={{ priority: 'medium', impact: 'medium' }}
            />
        </div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Select, Form, Input, Row, Col, Progress, Card, Statistic, Typography, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, SendOutlined, RocketOutlined, CheckCircleOutlined, TagOutlined, ClockCircleOutlined, ExclamationCircleOutlined, CloudUploadOutlined, FileExcelOutlined, FilePdfOutlined  } from "@ant-design/icons";
import { motion } from "framer-motion";
import { supaRest, supaInsert, supaUpdate, supaDelete } from "@/lib/supaRest";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import { useDateRangeStore } from "@/store/useDateRangeStore";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const statusColors: Record<string, string> = { planning: 'blue', building: 'cyan', testing: 'orange', approved: 'green', deploying: 'purple', deployed: 'green', rolled_back: 'red', cancelled: 'default' };
const typeColors: Record<string, string> = { major: 'red', minor: 'blue', patch: 'green', emergency: 'volcano' };
const riskColors: Record<string, string> = { low: 'green', medium: 'blue', high: 'orange', critical: 'red' };
const statusProgress: Record<string, number> = { planning: 15, building: 35, testing: 55, approved: 70, deploying: 85, deployed: 100, rolled_back: 100, cancelled: 0 };

const FIELDS: FieldDef[] = [
    { name: "title", label: "Title", required: true },
    { name: "version", label: "Version" },
    { name: "release_type", label: "Release Type" },
];

export default function ReleasesPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [data, setData] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const filters: Record<string, string> = {};
            if (filterStatus) filters['status'] = `eq.${filterStatus}`;
            const rows = await supaRest('itsm_releases', { order: 'created_at.desc', filters });
            setData(rows);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            const body: any = { title: values.title, version: values.version, description: values.description, release_type: values.release_type || 'minor', priority: values.priority || 'medium', risk_level: values.risk_level || 'medium', planned_start: values.planned_start, planned_end: values.planned_end, release_manager: values.release_manager, build_team: values.build_team, test_lead: values.test_lead, deployment_plan: values.deployment_plan, rollback_plan: values.rollback_plan };
            if (editing) {
                body.status = values.status;
                await supaUpdate('itsm_releases', editing.id, body);
                messageApi.success("Release updated.");
            } else {
                const seq = data.length > 0 ? Math.max(...data.map(d => parseInt(d.release_number?.replace('REL-', '') || '0'))) + 1 : 1;
                body.release_number = `REL-${String(seq).padStart(4, '0')}`;
                body.tenant_id = 'default';
                await supaInsert('itsm_releases', body);
                messageApi.success(`Release ${body.release_number} created.`);
            }
            setModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await supaDelete('itsm_releases', id); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const columns: ProColumns<any>[] = [
        { title: '#', dataIndex: 'release_number', width: 110, render: (_, r) => <Tag color="purple" style={{ fontFamily: 'monospace' }}>{r.release_number}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Version', dataIndex: 'version', width: 100, render: (_, r) => <Tag icon={<TagOutlined />}>{r.version}</Tag> },
        { title: 'Type', dataIndex: 'release_type', width: 100, render: (_, r) => <Tag color={typeColors[r.release_type]}>{(r.release_type || '').toUpperCase()}</Tag> },
        { title: 'Risk', dataIndex: 'risk_level', width: 90, render: (_, r) => <Tag color={riskColors[r.risk_level]}>{(r.risk_level || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 120, render: (_, r) => <Tag color={statusColors[r.status]}>{(r.status || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Progress', dataIndex: 'status', width: 130, render: (_, r) => <Progress percent={statusProgress[r.status] || 0} size="small" status={r.status === 'rolled_back' ? 'exception' : r.status === 'deployed' ? 'success' : 'active'} /> },
        { title: 'Manager', dataIndex: 'release_manager', width: 130, ellipsis: true },
        { title: 'Planned', dataIndex: 'planned_start', width: 100, render: (_, r) => r.planned_start ? new Date(r.planned_start).toLocaleDateString('id-ID') : '-' },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); form.setFieldsValue(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete release?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ],
        },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Release Management</AuroraText>}
            subTitle={<DecryptedText text="Plan, build, test, and deploy releases" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            {/* KPI Stats */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Releases', value: data.length, icon: <RocketOutlined />, color: '#8b5cf6' },
                    { title: 'Deployed', value: data.filter(d => d.status === 'deployed').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'In Progress', value: data.filter(d => ['building', 'testing', 'deploying'].includes(d.status)).length, icon: <CloudUploadOutlined />, color: '#3b82f6' },
                    { title: 'High Risk', value: data.filter(d => d.risk_level === 'high' || d.risk_level === 'critical').length, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'Planning', value: data.filter(d => d.status === 'planning').length, icon: <ClockCircleOutlined />, color: '#f59e0b' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Release Pipeline Visualization */}
            {data.length > 0 && (
                <Card size="small" style={{ ...glass, marginBottom: 16 }} title={<Text strong style={{ fontSize: 13 }}>ðŸš€ Release Pipeline</Text>}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                        {['planning', 'building', 'testing', 'approved', 'deploying', 'deployed'].map((stage, i) => {
                            const cnt = data.filter(d => d.status === stage).length;
                            const cfg = { planning: { color: '#3b82f6', icon: 'ðŸ“‹' }, building: { color: '#06b6d4', icon: 'ðŸ”¨' }, testing: { color: '#f59e0b', icon: 'ðŸ§ª' }, approved: { color: '#10b981', icon: 'âœ…' }, deploying: { color: '#8b5cf6', icon: 'ðŸš€' }, deployed: { color: '#10b981', icon: 'ðŸŽ‰' } }[stage] || { color: '#6b7280', icon: 'ðŸ“¦' };
                            return (
                                <React.Fragment key={stage}>
                                    <motion.div initial={{ scaleX: 0 }} animate={{ scaleX: 1 }} transition={{ delay: i * 0.08 }}
                                        style={{ flex: 1, background: `${cfg.color}10`, border: `1px solid ${cfg.color}30`, borderRadius: 8, padding: '8px 10px', textAlign: 'center', position: 'relative', overflow: 'hidden' }}>
                                        <div style={{ position: 'absolute', bottom: 0, left: 0, width: cnt > 0 ? '100%' : '0%', height: 3, background: cfg.color, borderRadius: 3 }} />
                                        <Text style={{ fontSize: 10, color: cfg.color, display: 'block' }}>{cfg.icon} {stage.replace(/_/g, ' ')}</Text>
                                        <Text strong style={{ fontSize: 16, color: cfg.color }}>{cnt}</Text>
                                    </motion.div>
                                    {i < 5 && <span style={{ color: '#d1d5db', fontSize: 10 }}>â–¸</span>}
                                </React.Fragment>
                            );
                        })}
                    </div>
                </Card>
            )}

            <ProTable
                headerTitle={<Space><RocketOutlined /> Releases <Badge count={data.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id" dataSource={data} loading={loading} columns={columns} search={false}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_releases', title: 'Release Management', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'release_number' }, { header: 'Title', key: 'title' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_releases', title: 'Release Management', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'release_number' }, { header: 'Title', key: 'title' }, { header: 'Status', key: 'status' }], data: data })} /></Tooltip></RbacGuard>,
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 140 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ value: 'planning', label: 'Planning' }, { value: 'building', label: 'Building' }, { value: 'testing', label: 'Testing' }, { value: 'approved', label: 'Approved' }, { value: 'deploying', label: 'Deploying' }, { value: 'deployed', label: 'Deployed' }]} />,
