"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import { Card, Row, Col, Statistic, Tag, Table, Space, Progress, message, Typography, Button, Tooltip, Badge } from "antd";
import {
    AlertOutlined, CheckCircleOutlined, ClockCircleOutlined,
    WarningOutlined, ReloadOutlined, ThunderboltOutlined,
    DashboardOutlined, FieldTimeOutlined, ArrowUpOutlined,
    ArrowDownOutlined, FireOutlined, ExclamationCircleOutlined,
} from "@ant-design/icons";
import { gql } from "@/lib/graphql";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import {
    LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip,
    ResponsiveContainer, PieChart, Pie, Cell, BarChart, Bar, Legend,
    ReferenceLine,
} from "recharts";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_TICKETS = `query { itsmTickets { id ticketNumber title status priority impact urgency slaResponseDue slaResolutionDue slaBreached assignedTo assignedTeam categoryId reporterName createdAt updatedAt resolvedAt } }`;
const GET_SLA_POLICIES = `query { itsmSlaPolicies { id name priority responseTimeMinutes resolutionTimeMinutes escalationAfterMinutes } }`;
const GET_STATS = `query { itsmDashboardStats { totalOpen totalUnassigned totalBreached totalDueToday byPriority byStatus avgResponseTime avgResolutionTime resolvedThisWeek slaComplianceRate } }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
const CHART_COLORS = ['#f5222d', '#fa8c16', '#1890ff', '#52c41a'];
const REFRESH_INTERVAL = 60_000;

/* ── risk helpers ─────────────────────────────────── */
type RiskLevel = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

function getMinutesRemaining(due: string | null): number {
    if (!due) return Infinity;
    return dayjs(due).diff(dayjs(), 'minute');
}

function getRiskLevel(minRemaining: number): RiskLevel {
    if (minRemaining < 15) return 'CRITICAL';
    if (minRemaining < 60) return 'HIGH';
    if (minRemaining < 240) return 'MEDIUM';
    return 'LOW';
}

const riskMeta: Record<RiskLevel, { color: string; tag: string }> = {
    CRITICAL: { color: '#f5222d', tag: 'red' },
    HIGH: { color: '#fa8c16', tag: 'orange' },
    MEDIUM: { color: '#fadb14', tag: 'gold' },
    LOW: { color: '#52c41a', tag: 'green' },
};

function fmtCountdown(min: number): string {
    if (min === Infinity) return '—';
    if (min <= 0) return 'BREACHED';
    if (min < 60) return `${min}m`;
    const h = Math.floor(min / 60);
    const m = min % 60;
    if (h < 24) return m > 0 ? `${h}h ${m}m` : `${h}h`;
    const d = Math.floor(h / 24);
    return `${d}d ${h % 24}h`;
}

function fmtMinutes(m: number): string {
    if (!m || m <= 0) return '—';
    if (m < 60) return `${Math.round(m)}m`;
    return `${(m / 60).toFixed(1)}h`;
}

/* ── component ────────────────────────────────────── */
export default function SlaMonitorPage() {
    const router = useRouter();
    const { themeColor } = usePreferencesStore();
    const [messageApi, ctx] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [tickets, setTickets] = useState<any[]>([]);
    const [policies, setPolicies] = useState<any[]>([]);
    const [stats, setStats] = useState<any>(null);
    const [lastRefresh, setLastRefresh] = useState(Date.now());
    const [secondsAgo, setSecondsAgo] = useState(0);

    /* ── data fetch ──────────────────────────────── */
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [t, p, s] = await Promise.all([gql(GET_TICKETS), gql(GET_SLA_POLICIES), gql(GET_STATS)]);
            setTickets(t.itsmTickets || []);
            setPolicies(p.itsmSlaPolicies || []);
            setStats(s.itsmDashboardStats || {});
            setLastRefresh(Date.now());
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    /* auto-refresh every 60s */
    useEffect(() => {
        const id = setInterval(loadData, REFRESH_INTERVAL);
        return () => clearInterval(id);
    }, [loadData]);

    /* "last updated X seconds ago" ticker */
    useEffect(() => {
        const id = setInterval(() => setSecondsAgo(Math.floor((Date.now() - lastRefresh) / 1000)), 1000);
        return () => clearInterval(id);
    }, [lastRefresh]);

    /* ── computed data ───────────────────────────── */
    const complianceRate = stats?.slaComplianceRate ?? 0;
    const complianceColor = complianceRate >= 95 ? '#52c41a' : complianceRate >= 85 ? '#fadb14' : '#f5222d';

    const openTickets = useMemo(() => tickets.filter(t => !['resolved', 'closed'].includes(t.status)), [tickets]);
    const breachedCount = useMemo(() => openTickets.filter(t => t.slaBreached).length, [openTickets]);
    const withinSla = openTickets.length - breachedCount;

    const dueIn1Hour = useMemo(() => openTickets.filter(t => {
        const m = Math.min(getMinutesRemaining(t.slaResponseDue), getMinutesRemaining(t.slaResolutionDue));
        return m > 0 && m <= 60;
    }).length, [openTickets]);

    const dueToday = stats?.totalDueToday ?? 0;

    /* at-risk tickets (sorted by urgency) */
    const atRiskTickets = useMemo(() => {
        return openTickets
            .map(t => {
                const respMin = getMinutesRemaining(t.slaResponseDue);
                const resolMin = getMinutesRemaining(t.slaResolutionDue);
                const minRemaining = Math.min(respMin, resolMin);
                return { ...t, minRemaining, risk: getRiskLevel(minRemaining) };
            })
            .filter(t => t.minRemaining < Infinity)
            .sort((a, b) => a.minRemaining - b.minRemaining);
    }, [openTickets]);

    /* breach timeline (last 30 days) */
    const breachTimeline = useMemo(() => {
        const map: Record<string, number> = {};
        for (let i = 29; i >= 0; i--) map[dayjs().subtract(i, 'day').format('MM/DD')] = 0;
        tickets.filter(t => t.slaBreached).forEach(t => {
            const key = dayjs(t.updatedAt || t.createdAt).format('MM/DD');
            if (map[key] !== undefined) map[key]++;
        });
        return Object.entries(map).map(([date, count]) => ({ date, count }));
    }, [tickets]);

    const avgBreaches = breachTimeline.length > 0
        ? +(breachTimeline.reduce((s, d) => s + d.count, 0) / breachTimeline.length).toFixed(1)
        : 0;

    /* compliance by priority (donut) */
    const complianceByPriority = useMemo(() => {
        const groups: Record<string, { total: number; ok: number }> = {};
        ['critical', 'high', 'medium', 'low'].forEach(p => (groups[p] = { total: 0, ok: 0 }));
        tickets.forEach(t => {
            const p = t.priority || 'medium';
            if (!groups[p]) return;
            groups[p].total++;
            if (!t.slaBreached) groups[p].ok++;
        });
        return Object.entries(groups).map(([key, v]) => ({
            name: key.charAt(0).toUpperCase() + key.slice(1),
            value: v.total > 0 ? Math.round((v.ok / v.total) * 100) : 100,
            total: v.total,
        }));
    }, [tickets]);

    /* response vs resolution bar chart */
    const responseVsResolution = useMemo(() => {
        return ['critical', 'high', 'medium', 'low'].map(p => {
            const pol = policies.find(pl => pl.priority === p);
            const pTickets = tickets.filter(t => t.priority === p && t.resolvedAt);
            let avgResp = 0, avgResol = 0;
            if (pTickets.length > 0) {
                avgResp = pTickets.reduce((s, t) => s + dayjs(t.updatedAt).diff(dayjs(t.createdAt), 'minute'), 0) / pTickets.length;
                avgResol = pTickets.reduce((s, t) => s + dayjs(t.resolvedAt).diff(dayjs(t.createdAt), 'minute'), 0) / pTickets.length;
            }
            return {
                priority: p.charAt(0).toUpperCase() + p.slice(1),
                'Avg Response': Math.round(avgResp),
                'Avg Resolution': Math.round(avgResol),
                'Response Target': pol?.responseTimeMinutes || 0,
                'Resolution Target': pol?.resolutionTimeMinutes || 0,
            };
        });
    }, [tickets, policies]);

    /* ── KPI stats ───────────────────────────────── */
    const kpis = [
        { title: 'Active Tickets', value: openTickets.length, icon: <AlertOutlined />, color: themeColor },
        { title: 'SLA Breached', value: breachedCount, icon: <FireOutlined />, color: '#f5222d' },
        { title: 'Due in 1 Hour', value: dueIn1Hour, icon: <ExclamationCircleOutlined />, color: '#fa8c16' },
        { title: 'Due Today', value: dueToday, icon: <ClockCircleOutlined />, color: '#fadb14' },
        { title: 'Avg Response', value: fmtMinutes(stats?.avgResponseTime), icon: <ThunderboltOutlined />, color: '#1890ff' },
        { title: 'Avg Resolution', value: fmtMinutes(stats?.avgResolutionTime), icon: <FieldTimeOutlined />, color: '#722ed1' },
    ];

    /* ── table columns ───────────────────────────── */
    const columns = [
        { title: 'Ticket #', dataIndex: 'ticketNumber', width: 110, render: (v: string) => <Tag color="purple" style={{ fontFamily: 'monospace' }}>{v}</Tag> },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        { title: 'Priority', dataIndex: 'priority', width: 90, render: (v: string) => <Tag color={priorityColors[v]}>{(v || '').toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color="geekblue">{(v || '').replace(/_/g, ' ').toUpperCase()}</Tag> },
        { title: 'Response Due', dataIndex: 'slaResponseDue', width: 130, render: (v: string) => v ? dayjs(v).format('MMM DD HH:mm') : '—' },
        { title: 'Resolution Due', dataIndex: 'slaResolutionDue', width: 130, render: (v: string) => v ? dayjs(v).format('MMM DD HH:mm') : '—' },
        {
            title: 'Time Left', key: 'remaining', width: 100, render: (_: any, r: any) => {
                const txt = fmtCountdown(r.minRemaining);
                const color = riskMeta[r.risk as RiskLevel]?.color || '#999';
                return <Text strong style={{ color, fontSize: 13 }}>{txt}</Text>;
            }
        },
        {
            title: 'Risk', key: 'risk', width: 100, render: (_: any, r: any) => {
                const meta = riskMeta[r.risk as RiskLevel];
                return (
                    <Tag color={meta.tag} style={r.risk === 'CRITICAL' ? { animation: 'pulse-red 1.5s infinite' } : undefined}>
                        {r.risk}
                    </Tag>
                );
            }
        },
    ];

    /* ── render ───────────────────────────────────── */
    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#ef4444", "#fa8c16"]}>SLA Monitor</AuroraText>}
            subTitle={<DecryptedText text="Real-time SLA compliance & breach risk monitoring" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Tooltip key="ago" title="Auto-refreshes every 60 seconds">
                    <Text type="secondary" style={{ fontSize: 12, marginRight: 8 }}>
                        <ClockCircleOutlined /> Updated {secondsAgo}s ago
                    </Text>
                </Tooltip>,
                <Button key="refresh" icon={<ReloadOutlined spin={loading} />} onClick={loadData}>Refresh</Button>,
            ]}
        >
            {ctx}
            {/* pulsing keyframe for CRITICAL tags */}
            <style>{`@keyframes pulse-red { 0%,100%{opacity:1} 50%{opacity:.45} }`}</style>

            {/* ─── 1. SLA Health Score Hero Card ──────── */}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                <Card style={{ ...glass, marginBottom: 16, textAlign: 'center', borderTop: `3px solid ${complianceColor}` }} bodyStyle={{ padding: '28px 24px' }}>
                    <Row align="middle" justify="center" gutter={32}>
                        <Col>
                            <Progress
                                type="dashboard"
                                percent={complianceRate}
                                size={170}
                                strokeColor={complianceColor}
                                format={p => (
                                    <div style={{ textAlign: 'center' }}>
                                        <div style={{ fontSize: 36, fontWeight: 700, color: complianceColor }}>{p}%</div>
                                        <div style={{ fontSize: 11, color: '#999' }}>SLA Compliance</div>
                                    </div>
                                )}
                            />
                        </Col>
                        <Col>
                            <Space direction="vertical" size={4} align="start">
                                <Text strong style={{ fontSize: 20 }}>SLA Health Score</Text>
                                <Text type="secondary">{withinSla} of {openTickets.length} tickets within SLA</Text>
                                <Space size={4}>
                                    {complianceRate >= 85
                                        ? <Tag color="green" icon={<ArrowUpOutlined />}>Trending Up</Tag>
                                        : <Tag color="red" icon={<ArrowDownOutlined />}>Needs Attention</Tag>}
                                    <Badge count={`${stats?.resolvedThisWeek ?? 0} resolved this week`} style={{ backgroundColor: '#52c41a', fontSize: 10 }} />
                                </Space>
                            </Space>
                        </Col>
                    </Row>
                </Card>
            </motion.div>

            {/* ─── 2. KPI Stats Row ──────────────────── */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {kpis.map((k, i) => (
                    <Col xs={12} sm={8} md={4} key={k.title}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${k.color}` }} bodyStyle={{ padding: '12px 14px' }}>
                                <Statistic
                                    title={<Text style={{ fontSize: 10 }}>{k.title}</Text>}
                                    value={k.value}
                                    prefix={k.icon}
                                    valueStyle={{ color: k.color, fontSize: 22 }}
                                />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* ─── 3. At-Risk Tickets Table ──────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                <Card
                    size="small"
                    title={<Space><FireOutlined style={{ color: '#f5222d' }} /> At-Risk Tickets <Badge count={atRiskTickets.length} style={{ backgroundColor: '#f5222d' }} /></Space>}
                    style={{ ...glass, marginBottom: 16 }}
                >
                    <Table
                        dataSource={atRiskTickets.slice(0, 15)}
                        columns={columns}
                        rowKey="id"
                        size="small"
                        pagination={false}
                        loading={loading}
                        scroll={{ x: 900 }}
                        onRow={(r) => ({ style: { cursor: 'pointer' }, onClick: () => router.push(`/admin/itsm/tickets/${r.id}`) })}
                    />
                </Card>
            </motion.div>

            {/* ─── 4 & 5. Charts Row ─────────────────── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                {/* Breach Timeline */}
                <Col xs={24} md={14}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                        <Card size="small" title={<Space><WarningOutlined style={{ color: '#f5222d' }} /> SLA Breach Timeline (30 days)</Space>} style={{ ...glass, height: '100%' }}>
                            <ResponsiveContainer width="100%" height={260}>
                                <LineChart data={breachTimeline}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,0,0,0.06)" />
                                    <XAxis dataKey="date" tick={{ fontSize: 10 }} interval={4} />
                                    <YAxis allowDecimals={false} tick={{ fontSize: 10 }} />
                                    <RTooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                                    <ReferenceLine y={avgBreaches} stroke="#fa8c16" strokeDasharray="4 4" label={{ value: `Avg ${avgBreaches}`, fill: '#fa8c16', fontSize: 10 }} />
                                    <Line type="monotone" dataKey="count" stroke="#f5222d" strokeWidth={2} dot={{ r: 2 }} activeDot={{ r: 5 }} name="Breaches" />
                                </LineChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>

                {/* Compliance Donut */}
                <Col xs={24} md={10}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }}>
                        <Card size="small" title={<Space><DashboardOutlined style={{ color: themeColor }} /> SLA by Priority</Space>} style={{ ...glass, height: '100%' }}>
                            <ResponsiveContainer width="100%" height={260}>
                                <PieChart>
                                    <Pie
                                        data={complianceByPriority}
                                        dataKey="value"
                                        nameKey="name"
                                        cx="50%" cy="50%"
                                        innerRadius={55} outerRadius={90}
                                        paddingAngle={3}
                                        label={({ name, value }) => `${name} ${value}%`}
                                    >
                                        {complianceByPriority.map((_, i) => <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />)}
                                    </Pie>
                                    <RTooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} formatter={(v: number, name: string, entry: any) => [`${v}% (${entry.payload.total} tickets)`, name]} />
                                    {/* center text */}
                                    <text x="50%" y="48%" textAnchor="middle" dominantBaseline="central" style={{ fontSize: 22, fontWeight: 700, fill: complianceColor }}>
                                        {complianceRate}%
                                    </text>
                                    <text x="50%" y="58%" textAnchor="middle" dominantBaseline="central" style={{ fontSize: 10, fill: '#999' }}>
                                        Overall
                                    </text>
                                </PieChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ─── 6. Response vs Resolution Bar ─────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                <Card size="small" title={<Space><CheckCircleOutlined style={{ color: '#1890ff' }} /> Response vs Resolution Times (minutes)</Space>} style={{ ...glass, marginBottom: 16 }}>
                    <ResponsiveContainer width="100%" height={280}>
                        <BarChart data={responseVsResolution} barCategoryGap="25%">
                            <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,0,0,0.06)" />
                            <XAxis dataKey="priority" tick={{ fontSize: 11 }} />
                            <YAxis tick={{ fontSize: 10 }} />
                            <RTooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                            <Legend wrapperStyle={{ fontSize: 11 }} />
                            <Bar dataKey="Avg Response" fill="#1890ff" radius={[4, 4, 0, 0]} />
                            <Bar dataKey="Avg Resolution" fill="#722ed1" radius={[4, 4, 0, 0]} />
                            {responseVsResolution.some(d => d['Response Target'] > 0) && (
                                <ReferenceLine y={responseVsResolution.reduce((s, d) => s + d['Response Target'], 0) / 4} stroke="#1890ff" strokeDasharray="4 4" label={{ value: 'Resp Target', fill: '#1890ff', fontSize: 9 }} />
                            )}
                            {responseVsResolution.some(d => d['Resolution Target'] > 0) && (
                                <ReferenceLine y={responseVsResolution.reduce((s, d) => s + d['Resolution Target'], 0) / 4} stroke="#722ed1" strokeDasharray="4 4" label={{ value: 'Resol Target', fill: '#722ed1', fontSize: 9 }} />
                            )}
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

﻿"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import RbacGuard from "@/components/common/RbacGuard";
import { ProTable, ProColumns } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Typography, Form, Input, Select, InputNumber, Row, Col, Card, Statistic, Badge, Tooltip } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, FlagOutlined, ClockCircleOutlined, SettingOutlined, CheckCircleOutlined, FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const GET_POLICIES = `query { itsmSlaPolicies { id name priority responseTimeMinutes resolutionTimeMinutes escalationAfterMinutes status createdAt } }`;
const CREATE_POLICY = `mutation($tenantId: String!, $input: CreateItsmSlaPolicyInput!) { createItsmSlaPolicy(tenantId: $tenantId, input: $input) { id } }`;
const UPDATE_POLICY = `mutation($id: ID!, $input: UpdateItsmSlaPolicyInput!) { updateItsmSlaPolicy(id: $id, input: $input) { id } }`;
const DELETE_POLICY = `mutation($id: ID!) { deleteItsmSlaPolicy(id: $id) }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };

function formatMinutes(m: number): string {
    if (m < 60) return `${m}m`;
    const h = Math.floor(m / 60);
    const rm = m % 60;
    if (h < 24) return rm > 0 ? `${h}h ${rm}m` : `${h}h`;
    const d = Math.floor(h / 24);
    const rh = h % 24;
    return rh > 0 ? `${d}d ${rh}h` : `${d}d`;
}

const SLA_FIELDS: FieldDef[] = [
    { name: "name", label: "Policy Name", required: true },
    { name: "priority", label: "Priority", required: true },
    { name: "responseTimeMinutes", label: "Response Time (min)", required: true },
    { name: "resolutionTimeMinutes", label: "Resolution Time (min)", required: true },
    { name: "escalationAfterMinutes", label: "Escalation After (min)" },
    { name: "status", label: "Status" },
];

export default function ItsmSlaPage() {
    const [messageApi, contextHolder] = message.useMessage();
    const [policies, setPolicies] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const d = await gql(GET_POLICIES);
            setPolicies(d.itsmSlaPolicies || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(UPDATE_POLICY, { id: editing.id, input: values });
                messageApi.success("SLA Policy updated.");
            } else {
                await gql(CREATE_POLICY, { tenantId: DEFAULT_TENANT_ID, input: values });
                messageApi.success("SLA Policy created.");
            }
            setModalOpen(false);
            form.resetFields();
            setEditing(null);
            loadData();
        } catch (err: any) { messageApi.error(err.message); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_POLICY, { id }); messageApi.success("Deleted."); loadData(); }
        catch (err: any) { messageApi.error(err.message); }
    };

    const columns: ProColumns<any>[] = [
        { title: 'Policy Name', dataIndex: 'name', render: (_, r) => <Text strong>{r.name}</Text> },
        {
            title: 'Priority', dataIndex: 'priority', width: 120,
            render: (_, r) => <Tag color={priorityColors[r.priority]} style={{ fontWeight: 600 }}>{(r.priority || '').toUpperCase()}</Tag>
        },
        {
            title: 'Response Time', dataIndex: 'responseTimeMinutes', width: 140,
            render: (_, r) => (
                <Space><ClockCircleOutlined style={{ color: '#1890ff' }} /><Text>{formatMinutes(r.responseTimeMinutes)}</Text></Space>
            )
        },
        {
            title: 'Resolution Time', dataIndex: 'resolutionTimeMinutes', width: 140,
            render: (_, r) => (
                <Space><ClockCircleOutlined style={{ color: '#52c41a' }} /><Text>{formatMinutes(r.resolutionTimeMinutes)}</Text></Space>
            )
        },
        {
            title: 'Escalation After', dataIndex: 'escalationAfterMinutes', width: 140,
            render: (_, r) => r.escalationAfterMinutes ? (
                <Space><ClockCircleOutlined style={{ color: '#fa8c16' }} /><Text>{formatMinutes(r.escalationAfterMinutes)}</Text></Space>
            ) : '-'
        },
        {
            title: 'Status', dataIndex: 'status', width: 100,
            render: (_, r) => <Tag color={r.status === 'active' ? 'green' : 'default'}>{(r.status || '').toUpperCase()}</Tag>
        },
        {
            title: 'Actions', valueType: 'option', width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => {
                    setEditing(record);
                    form.setFieldsValue({
                        name: record.name, priority: record.priority,
                        responseTimeMinutes: record.responseTimeMinutes,
                        resolutionTimeMinutes: record.resolutionTimeMinutes,
                        escalationAfterMinutes: record.escalationAfterMinutes,
                        status: record.status,
                    });
                    setModalOpen(true);
                }} />,
                <Popconfirm key="del" title="Delete this SLA policy?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ]
        }
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>SLA Policies</AuroraText>}
            subTitle={<DecryptedText text="Service Level Agreement configuration" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Policies', value: policies.length, icon: <FlagOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: policies.filter((p: any) => p.status === 'active').length, icon: <CheckCircleOutlined />, color: '#10b981' },
                    { title: 'Avg Response', value: policies.length > 0 ? `${Math.round(policies.reduce((s: number, p: any) => s + (p.responseTimeMinutes || 0), 0) / policies.length)}m` : '—', icon: <ClockCircleOutlined />, color: '#f59e0b' },
                    { title: 'Avg Resolution', value: policies.length > 0 ? `${Math.round(policies.reduce((s: number, p: any) => s + (p.resolutionTimeMinutes || 0), 0) / policies.length)}m` : '—', icon: <ClockCircleOutlined />, color: '#8b5cf6' },
                    { title: 'Priority Levels', value: [...new Set(policies.map((p: any) => p.priority))].length, icon: <SettingOutlined />, color: '#06b6d4' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={Math.floor(24 / 5)}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <ProTable
                headerTitle={<Space><FlagOutlined /> SLA Policies <Badge count={policies.length} style={{ backgroundColor: themeColor }} /></Space>}
                rowKey="id"
                dataSource={policies}
                loading={loading}
                columns={columns}
                search={false}
                toolBarRender={() => [
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setModalOpen(true); }}>
                        New SLA Policy
                    </Button>,
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'sla_policies', title: 'SLA Policies', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Priority', key: 'priority' }, { header: 'Response (min)', key: 'responseTimeMinutes' }, { header: 'Resolution (min)', key: 'resolutionTimeMinutes' }, { header: 'Escalation (min)', key: 'escalationAfterMinutes' }, { header: 'Status', key: 'status' }], data: policies })} /></Tooltip> <Tooltip key="pd" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'sla_policies', title: 'SLA Policies', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Priority', key: 'priority' }, { header: 'Response (min)', key: 'responseTimeMinutes' }, { header: 'Resolution (min)', key: 'resolutionTimeMinutes' }, { header: 'Escalation (min)', key: 'escalationAfterMinutes' }, { header: 'Status', key: 'status' }], data: policies })} /></Tooltip></RbacGuard>,
                ]}
            />

            {/* ─── SLA SteppedFormModal ─────────────── */}
            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? "Edit SLA Policy" : "New SLA Policy"}
                entityName="sla_policy"
                steps={[
                    {
                        title: "Policy Info",
                        icon: <FlagOutlined />,
                        fields: ["name", "priority"],
                        content: (
                            <>
                                <Form.Item name="name" label="Policy Name" rules={[{ required: true }]}>
                                    <Input placeholder="e.g., P1 - Critical" />
                                </Form.Item>
                                <Form.Item name="priority" label="Priority" rules={[{ required: true }]}>
                                    <Select options={[
                                        { value: 'critical', label: '🔴 Critical' },
                                        { value: 'high', label: '🟠 High' },
                                        { value: 'medium', label: '🔵 Medium' },
                                        { value: 'low', label: '🟢 Low' },
                                    ]} />
                                </Form.Item>
                            </>
                        ),
                    },
                    {
                        title: "Time Targets",
                        icon: <ClockCircleOutlined />,
                        fields: ["responseTimeMinutes", "resolutionTimeMinutes", "escalationAfterMinutes", "status"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="responseTimeMinutes" label="Response Time (minutes)" rules={[{ required: true }]}>
                                            <InputNumber min={1} style={{ width: '100%' }} addonAfter="min" />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="resolutionTimeMinutes" label="Resolution Time (minutes)" rules={[{ required: true }]}>
                                            <InputNumber min={1} style={{ width: '100%' }} addonAfter="min" />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="escalationAfterMinutes" label="Escalation After (minutes)">
                                            <InputNumber min={1} style={{ width: '100%' }} addonAfter="min" />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="status" label="Status">
                                            <Select options={[{ value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' }]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                            </>
                        ),
                    },
                ]}
                fields={SLA_FIELDS}
                width={600}
                gradient={["#fa8c16", "#faad14"]}
                editMode={!!editing}
                initialValues={{ priority: 'medium', responseTimeMinutes: 120, resolutionTimeMinutes: 480, escalationAfterMinutes: 240, status: 'active' }}
            />
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { ProCard } from "@ant-design/pro-components";
import { Button, message, Tag, Space, Typography, Descriptions, Timeline, Input, Switch, Divider, Row, Col, Tooltip, Badge } from "antd";
import {
    ArrowLeftOutlined, ClockCircleOutlined, UserOutlined, SendOutlined,
    TeamOutlined, LinkOutlined, ExclamationCircleOutlined, CheckCircleOutlined,
    CustomerServiceOutlined, RobotOutlined, BulbOutlined, ThunderboltOutlined,
} from "@ant-design/icons";
import { gql } from "@/lib/graphql";
import { useRouter, useParams } from "next/navigation";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const { Title, Text, Paragraph } = Typography;
const { TextArea } = Input;

const GET_TICKET = `query($id: String!) { itsmTicket(id: $id) { id ticketNumber title description categoryId priority status impact urgency contactId accountId individualId pmStakeholderId reporterName reporterEmail assignedTo assignedGroup slaPolicyId slaResponseDue slaResolutionDue slaResponseMet slaResolutionMet channel resolutionNotes resolvedAt closedAt createdAt updatedAt } }`;
const GET_COMMENTS = `query($ticketId: String!) { itsmTicketComments(ticketId: $ticketId) { id author content isInternal createdAt } }`;
const GET_CATEGORIES = `query { itsmCategories { id name } }`;
const ADD_COMMENT = `mutation($input: AddItsmCommentInput!) { addItsmComment(input: $input) { id } }`;
const UPDATE_TICKET = `mutation($id: ID!, $input: UpdateItsmTicketInput!) { updateItsmTicket(id: $id, input: $input) { id } }`;

const priorityColors: Record<string, string> = { critical: '#f5222d', high: '#fa8c16', medium: '#1890ff', low: '#52c41a' };
const statusColors: Record<string, string> = { new: 'blue', open: 'cyan', in_progress: 'geekblue', pending: 'orange', resolved: 'green', closed: 'default' };

function SlaCountdown({ due }: { due: string }) {
    const [remaining, setRemaining] = useState('');
    const [breach, setBreach] = useState(false);
    useEffect(() => {
        const update = () => {
            const diff = new Date(due).getTime() - Date.now();
            if (diff <= 0) { setBreach(true); setRemaining('BREACHED'); return; }
            const h = Math.floor(diff / 3600000);
            const m = Math.floor((diff % 3600000) / 60000);
            setRemaining(`${h}h ${m}m`);
            setBreach(false);
        };
        update();
        const iv = setInterval(update, 60000);
        return () => clearInterval(iv);
    }, [due]);
    return <Tag color={breach ? 'red' : 'green'} icon={breach ? <ExclamationCircleOutlined /> : <ClockCircleOutlined />}>{remaining}</Tag>;
}

export default function TicketDetailPage() {
    const router = useRouter();
    const params = useParams();
    const ticketId = params?.id as string;
    const [messageApi, contextHolder] = message.useMessage();
    const [ticket, setTicket] = useState<any>(null);
    const [comments, setComments] = useState<any[]>([]);
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();
    const [commentText, setCommentText] = useState('');
    const [isInternal, setIsInternal] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    // AI states
    const [aiLoading, setAiLoading] = useState<string | null>(null);
    const [aiCategorize, setAiCategorize] = useState<any>(null);
    const [aiResolution, setAiResolution] = useState<any>(null);
    const [aiSlaRisk, setAiSlaRisk] = useState<any>(null);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [t, c, cats] = await Promise.all([
                gql(GET_TICKET, { id: ticketId }),
                gql(GET_COMMENTS, { ticketId }),
                gql(GET_CATEGORIES),
            ]);
            setTicket(t.itsmTicket);
            setComments(c.itsmTicketComments || []);
            setCategories(cats.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [ticketId, messageApi]);

    useEffect(() => { load(); }, [load]);

    const handleAddComment = async () => {
        if (!commentText.trim()) return;
        setSubmitting(true);
        try {
            await gql(ADD_COMMENT, { input: { ticketId, content: commentText, isInternal, author: 'Admin' } });
            setCommentText('');
            messageApi.success('Comment added.');
            load();
        } catch (err: any) { messageApi.error(err.message); }
        finally { setSubmitting(false); }
    };

    const handleStatusChange = async (newStatus: string) => {
        try {
            await gql(UPDATE_TICKET, { id: ticketId, input: { status: newStatus } });
            messageApi.success(`Status changed to ${newStatus.replace('_', ' ')}`);
            load();
        } catch (err: any) { messageApi.error(err.message); }
    };

    // AI Handlers
    const handleAiCategorize = async () => {
        if (!ticket) return;
        setAiLoading('categorize');
        try {
            const raw = await gql(`query($title: String!, $description: String) { itsmAiCategorize(title: $title, description: $description) }`, { title: ticket.title, description: ticket.description });
            setAiCategorize(JSON.parse(raw.itsmAiCategorize));
        } catch (err: any) { messageApi.error('AI categorization failed: ' + err.message); }
        finally { setAiLoading(null); }
    };

    const handleAiResolution = async () => {
        setAiLoading('resolution');
        try {
            const raw = await gql(`query($ticketId: String!) { itsmAiSuggestResolution(ticketId: $ticketId) }`, { ticketId });
            setAiResolution(JSON.parse(raw.itsmAiSuggestResolution));
        } catch (err: any) { messageApi.error('AI suggestion failed: ' + err.message); }
        finally { setAiLoading(null); }
    };

    const handleAiSlaRisk = async () => {
        setAiLoading('sla');
        try {
            const raw = await gql(`query($ticketId: String!) { itsmAiSlaRisk(ticketId: $ticketId) }`, { ticketId });
            setAiSlaRisk(JSON.parse(raw.itsmAiSlaRisk));
        } catch (err: any) { messageApi.error('AI risk analysis failed: ' + err.message); }
        finally { setAiLoading(null); }
    };

    const categoryName = categories.find(c => c.id === ticket?.categoryId)?.name || '-';

    if (loading) return <CMSLayout title="Loading..."><div style={{ padding: 24 }}><ProCard loading bordered /></div></CMSLayout>;
    if (!ticket) return <CMSLayout title="Not Found"><div style={{ padding: 24 }}><Text>Ticket not found.</Text></div></CMSLayout>;

    return (
        <CMSLayout title={`Ticket ${ticket.ticketNumber}`} subTitle={ticket.title}>
        <div style={{ padding: 24 }}>
            {contextHolder}
            <Space style={{ marginBottom: 16 }}>
                <Button icon={<ArrowLeftOutlined />} onClick={() => router.push('/admin/itsm/tickets')}>Back to Tickets</Button>
            </Space>

            {/* Header */}
            <ProCard bordered style={{ marginBottom: 16 }}>
                <Row justify="space-between" align="middle">
                    <Col>
                        <Space size={12} align="center">
                            <Tag color="purple" style={{ fontSize: 16, padding: '4px 12px', fontFamily: 'monospace' }}>{ticket.ticketNumber}</Tag>
                            <Title level={4} style={{ margin: 0 }}>{ticket.title}</Title>
                        </Space>
                    </Col>
                    <Col>
                        <Space>
                            <Tag color={priorityColors[ticket.priority]} style={{ fontSize: 13 }}>{(ticket.priority || '').toUpperCase()}</Tag>
                            <Tag color={statusColors[ticket.status]} style={{ fontSize: 13 }}>{(ticket.status || '').replace('_', ' ').toUpperCase()}</Tag>
                        </Space>
                    </Col>
                </Row>
            </ProCard>

            <Row gutter={[16, 16]}>
                {/* Left Side — Detail + Activity */}
                <Col xs={24} lg={16}>
                    {/* Description */}
                    <ProCard title="Description" bordered style={{ marginBottom: 16 }}>
                        <Paragraph>{ticket.description || <Text type="secondary" italic>No description provided.</Text>}</Paragraph>
                    </ProCard>

                    {/* Resolution */}
                    {ticket.resolutionNotes && (
                        <ProCard title={<Space><CheckCircleOutlined style={{ color: '#52c41a' }} /> Resolution</Space>} bordered style={{ marginBottom: 16 }}>
                            <Paragraph>{ticket.resolutionNotes}</Paragraph>
                        </ProCard>
                    )}

                    {/* Activity Timeline */}
                    <ProCard title="Activity" bordered style={{ marginBottom: 16 }}>
                        <Timeline
                            items={comments.map(c => ({
                                color: c.isInternal ? 'orange' : 'blue',
                                children: (
                                    <div>
                                        <Space>
                                            <Text strong>{c.author}</Text>
                                            {c.isInternal && <Tag color="orange" style={{ fontSize: 10 }}>INTERNAL</Tag>}
                                            <Text type="secondary" style={{ fontSize: 12 }}>{new Date(c.createdAt).toLocaleString()}</Text>
                                        </Space>
                                        <Paragraph style={{ marginTop: 4, marginBottom: 0 }}>{c.content}</Paragraph>
                                    </div>
                                ),
                            }))}
                        />
                        {comments.length === 0 && <Text type="secondary">No comments yet.</Text>}

                        <Divider />
                        <TextArea rows={3} value={commentText} onChange={e => setCommentText(e.target.value)} placeholder="Add a comment..." />
                        <div style={{ marginTop: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <Space><Switch checked={isInternal} onChange={setIsInternal} size="small" /><Text type="secondary">Internal Note</Text></Space>
                            <Button type="primary" icon={<SendOutlined />} onClick={handleAddComment} loading={submitting} disabled={!commentText.trim()}>
                                {isInternal ? 'Add Internal Note' : 'Reply'}
                            </Button>
                        </div>
                    </ProCard>
                </Col>

                {/* Right Side — Info Panel */}
                <Col xs={24} lg={8}>
                    {/* Ticket Info */}
                    <ProCard title="Details" bordered style={{ marginBottom: 16 }}>
                        <Descriptions column={1} size="small">
                            <Descriptions.Item label="Category">{categoryName}</Descriptions.Item>
                            <Descriptions.Item label="Impact"><Tag>{(ticket.impact || '').toUpperCase()}</Tag></Descriptions.Item>
                            <Descriptions.Item label="Urgency"><Tag>{(ticket.urgency || '').toUpperCase()}</Tag></Descriptions.Item>
                            <Descriptions.Item label="Channel">{ticket.channel || '-'}</Descriptions.Item>
                            <Descriptions.Item label="Created">{new Date(ticket.createdAt).toLocaleString()}</Descriptions.Item>
                            <Descriptions.Item label="Updated">{new Date(ticket.updatedAt).toLocaleString()}</Descriptions.Item>
                        </Descriptions>
                    </ProCard>

                    {/* Reporter Info with Cross-Module Links */}
                    <ProCard title={<Space><UserOutlined /> Reporter</Space>} bordered style={{ marginBottom: 16 }}>
                        <Descriptions column={1} size="small">
                            <Descriptions.Item label="Name">{ticket.reporterName || '-'}</Descriptions.Item>
                            <Descriptions.Item label="Email">{ticket.reporterEmail || '-'}</Descriptions.Item>
                        </Descriptions>
                        <Divider style={{ margin: '8px 0' }} />
                        <Space direction="vertical" size={4}>
                            <Text type="secondary" style={{ fontSize: 11 }}>Linked Entities:</Text>
                            {ticket.contactId && (
                                <Tooltip title="View CRM Contact">
                                    <Button type="link" size="small" icon={<LinkOutlined />} onClick={() => router.push('/admin/crm/contacts')}>
                                        📇 CRM Contact
                                    </Button>
                                </Tooltip>
                            )}
                            {ticket.individualId && (
                                <Tooltip title="View CRM Individual">
                                    <Button type="link" size="small" icon={<LinkOutlined />} onClick={() => router.push('/admin/crm/individuals')}>
                                        👤 CRM Individual
                                    </Button>
                                </Tooltip>
                            )}
                            {ticket.accountId && (
                                <Tooltip title="View CRM Account">
                                    <Button type="link" size="small" icon={<LinkOutlined />} onClick={() => router.push('/admin/crm/accounts')}>
                                        🏢 CRM Account
                                    </Button>
                                </Tooltip>
                            )}
                            {ticket.pmStakeholderId && (
                                <Tooltip title="View PM Stakeholder">
                                    <Button type="link" size="small" icon={<LinkOutlined />} onClick={() => router.push('/admin/pm/projects')}>
                                        📋 PM Stakeholder
                                    </Button>
                                </Tooltip>
                            )}
                            {!ticket.contactId && !ticket.individualId && !ticket.accountId && !ticket.pmStakeholderId && (
                                <Text type="secondary" italic>No linked entities</Text>
                            )}
                        </Space>
                    </ProCard>

                    {/* Assignment */}
                    <ProCard title={<Space><TeamOutlined /> Assignment</Space>} bordered style={{ marginBottom: 16 }}>
                        <Descriptions column={1} size="small">
                            <Descriptions.Item label="Agent">{ticket.assignedTo || <Text type="secondary">Unassigned</Text>}</Descriptions.Item>
                            <Descriptions.Item label="Group">{ticket.assignedGroup || '-'}</Descriptions.Item>
                        </Descriptions>
                    </ProCard>

                    {/* SLA */}
                    <ProCard title={<Space><ClockCircleOutlined /> SLA</Space>} bordered style={{ marginBottom: 16 }}>
                        <Descriptions column={1} size="small">
                            <Descriptions.Item label="Response Due">
                                {ticket.slaResponseDue ? <SlaCountdown due={ticket.slaResponseDue} /> : '-'}
                            </Descriptions.Item>
                            <Descriptions.Item label="Resolution Due">
                                {ticket.slaResolutionDue ? <SlaCountdown due={ticket.slaResolutionDue} /> : '-'}
                            </Descriptions.Item>
                        </Descriptions>
                    </ProCard>

                    {/* Quick Actions */}
                    <ProCard title="Quick Actions" bordered style={{ marginBottom: 16 }}>
                        <Space direction="vertical" style={{ width: '100%' }}>
                            {ticket.status === 'new' && <Button block onClick={() => handleStatusChange('open')}>Open Ticket</Button>}
                            {(ticket.status === 'new' || ticket.status === 'open') && <Button block type="primary" onClick={() => handleStatusChange('in_progress')}>Start Working</Button>}
                            {ticket.status === 'in_progress' && <Button block onClick={() => handleStatusChange('pending')}>Set Pending</Button>}
                            {(ticket.status === 'in_progress' || ticket.status === 'pending') && <Button block type="primary" style={{ background: '#52c41a' }} onClick={() => handleStatusChange('resolved')}>Resolve</Button>}
                            {ticket.status === 'resolved' && <Button block onClick={() => handleStatusChange('closed')}>Close Ticket</Button>}
                        </Space>
                    </ProCard>

                    {/* AI Assist Panel */}
                    <ProCard
                        title={<Space><RobotOutlined style={{ color: themeColor }} /> AI Assist</Space>}
                        bordered
                        style={{ marginBottom: 16, background: 'linear-gradient(135deg, #f5f0ff 0%, #e8f4fd 100%)' }}
                        headerBordered
                    >
                        <Space direction="vertical" style={{ width: '100%' }} size={10}>
                            {/* Categorize Button */}
                            <Button
                                block
                                icon={<BulbOutlined />}
                                loading={aiLoading === 'categorize'}
                                onClick={handleAiCategorize}
                                style={{ background: aiCategorize ? '#f6ffed' : undefined, borderColor: aiCategorize ? '#b7eb8f' : undefined }}
                            >
                                🏷️ Auto-Categorize
                            </Button>
                            {aiCategorize && (
                                <div style={{ padding: '8px 12px', background: '#fff', borderRadius: 8, border: '1px solid #d9d9d9', fontSize: 12 }}>
                                    <div><Text strong>Category:</Text> <Tag color="purple">{aiCategorize.suggestedCategory}</Tag></div>
                                    <div><Text strong>Priority:</Text> <Tag color={aiCategorize.suggestedPriority === 'critical' ? 'red' : aiCategorize.suggestedPriority === 'high' ? 'orange' : 'blue'}>{(aiCategorize.suggestedPriority || '').toUpperCase()}</Tag></div>
                                    <div><Text strong>Group:</Text> {aiCategorize.suggestedAssignmentGroup}</div>
                                    <div style={{ marginTop: 4 }}><Text type="secondary">{aiCategorize.reasoning}</Text></div>
                                    <div style={{ marginTop: 4 }}><Text type="secondary">Confidence: {Math.round((aiCategorize.confidence || 0) * 100)}%</Text></div>
                                </div>
                            )}

                            {/* Suggest Resolution Button */}
                            <Button
                                block
                                icon={<ThunderboltOutlined />}
                                loading={aiLoading === 'resolution'}
                                onClick={handleAiResolution}
                                style={{ background: aiResolution ? '#f6ffed' : undefined, borderColor: aiResolution ? '#b7eb8f' : undefined }}
                            >
                                🔧 Suggest Resolution
                            </Button>
                            {aiResolution && (
                                <div style={{ padding: '8px 12px', background: '#fff', borderRadius: 8, border: '1px solid #d9d9d9', fontSize: 12 }}>
                                    <div style={{ marginBottom: 4 }}><Text strong>Steps:</Text></div>
                                    <ol style={{ margin: 0, paddingLeft: 16 }}>
                                        {(aiResolution.suggestedSteps || []).map((s: string, i: number) => (
                                            <li key={i} style={{ marginBottom: 2 }}>{s}</li>
                                        ))}
                                    </ol>
                                    <div style={{ marginTop: 6 }}><Text strong>Est. Time:</Text> {aiResolution.estimatedResolutionTime}</div>
                                    <div><Text type="secondary">Confidence: {Math.round((aiResolution.confidence || 0) * 100)}%</Text></div>
                                </div>
                            )}

                            {/* SLA Risk Button */}
                            <Button
                                block
                                icon={<ExclamationCircleOutlined />}
                                loading={aiLoading === 'sla'}
                                onClick={handleAiSlaRisk}
                                style={{ background: aiSlaRisk ? '#f6ffed' : undefined, borderColor: aiSlaRisk ? '#b7eb8f' : undefined }}
                            >
                                📊 SLA Risk Analysis
                            </Button>
                            {aiSlaRisk && (
                                <div style={{ padding: '8px 12px', background: '#fff', borderRadius: 8, border: '1px solid #d9d9d9', fontSize: 12 }}>
                                    <div><Text strong>Risk Level:</Text> <Tag color={aiSlaRisk.riskLevel === 'high' || aiSlaRisk.riskLevel === 'critical' ? 'red' : aiSlaRisk.riskLevel === 'medium' ? 'orange' : 'green'}>{(aiSlaRisk.riskLevel || '').toUpperCase()}</Tag></div>
                                    <div><Text strong>SLA Status:</Text> <Tag color={aiSlaRisk.slaStatus === 'breached' ? 'red' : aiSlaRisk.slaStatus === 'at_risk' ? 'orange' : 'green'}>{(aiSlaRisk.slaStatus || '').replace('_', ' ').toUpperCase()}</Tag></div>
                                    <div><Text strong>Remaining:</Text> {aiSlaRisk.remainingTime}</div>
                                    <div style={{ marginTop: 4 }}><Text type="secondary">{aiSlaRisk.recommendation}</Text></div>
                                    {aiSlaRisk.suggestedEscalation && <Tag color="red" style={{ marginTop: 4 }}>⚠️ Escalation Recommended</Tag>}
                                </div>
                            )}
                        </Space>
                    </ProCard>
                </Col>
            </Row>
        </div>
        </CMSLayout>
    );
}

