    const [messageApi, contextHolder] = message.useMessage();
    const [tickets, setTickets] = useState<any[]>([]);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [categories, setCategories] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();
    const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
    const [filterPriority, setFilterPriority] = useState<string | undefined>(undefined);
    const [searchText, setSearchText] = useState('');
    const [reporterResults, setReporterResults] = useState<any[]>([]);
    const [selectedReporter, setSelectedReporter] = useState<any>(null);
    const [aiSuggesting, setAiSuggesting] = useState(false);
    const [aiSuggestion, setAiSuggestion] = useState<any>(null);
    const [showQuickCreate, setShowQuickCreate] = useState(false);
    const [quickTitle, setQuickTitle] = useState('');
    const [quickPriority, setQuickPriority] = useState('medium');
    const [quickChannel, setQuickChannel] = useState('portal');
    const [quickCreating, setQuickCreating] = useState(false);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [t, c] = await Promise.all([
                gql(GET_TICKETS, { status: filterStatus, priority: filterPriority, search: searchText || undefined }),
                gql(GET_CATEGORIES),
            ]);
            setTickets(t.itsmTickets || []);
            setCategories(c.itsmCategories || []);
        } catch (err: any) { messageApi.error(err.message); }
        finally { setLoading(false); }
    }, [filterStatus, filterPriority, searchText, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Realtime sync for itsm_tickets ──
    const { isConnected: realtimeConnected } = useRealtimeSync({
        table: 'itsm_tickets',
        onEvent: useCallback((eventType: string, newRecord: any, oldRecord: any) => {
            const title = newRecord?.title || oldRecord?.title || 'Ticket';
            if (eventType === 'INSERT') {
                messageApi.info(`🆕 New ticket created: ${title}`);
            } else if (eventType === 'UPDATE') {
                messageApi.info(`✏️ Ticket updated: ${title}`);
            } else if (eventType === 'DELETE') {
                messageApi.info(`🗑️ Ticket deleted: ${title}`);
            }
            loadData();
        }, [messageApi, loadData]),
    });

    const handleSearchReporter = async (value: string) => {
        if (value.length < 2) { setReporterResults([]); return; }
        try {
            const d = await gql(SEARCH_REPORTERS, { search: value });
            setReporterResults(d.itsmSearchReporters || []);
        } catch { /* ignore */ }
    };

    const handleAiCategorize = async () => {
        const title = form.getFieldValue('title');
        const desc = form.getFieldValue('description');
        if (!title) { messageApi.warning('Please enter a title first'); return; }
        setAiSuggesting(true);
        try {
            const raw = await gql(`query($title: String!, $description: String) { itsmAiCategorize(title: $title, description: $description) }`, { title, description: desc });
            const result = JSON.parse(raw.itsmAiCategorize);
            setAiSuggestion(result);
            messageApi.success('AI suggestion ready â€” review below');
        } catch (err: any) { messageApi.error('AI failed: ' + err.message); }
        finally { setAiSuggesting(false); }
    };

    const handleSave = async (values: any) => {
        try {
            const input: any = {
                title: values.title,
                description: values.description,
                categoryId: values.categoryId,
                priority: values.priority || 'medium',
                impact: values.impact || 'medium',
                urgency: values.urgency || 'medium',
                channel: values.channel || 'portal',
                assignedTo: values.assignedTo,
                assignedGroup: values.assignedGroup,
                reporterName: values.reporterName,
                reporterEmail: values.reporterEmail,
            };

            if (selectedReporter) {
                input.reporterName = selectedReporter.name;
                input.reporterEmail = selectedReporter.email;
                if (selectedReporter.type === 'contact') input.contactId = selectedReporter.entityId;
                if (selectedReporter.type === 'account') input.accountId = selectedReporter.entityId;
                if (selectedReporter.type === 'individual') input.individualId = selectedReporter.entityId;
                if (selectedReporter.type === 'pm_stakeholder') input.pmStakeholderId = selectedReporter.entityId;
            }

            if (editing) {
                input.status = values.status;
                input.resolutionNotes = values.resolutionNotes;
                await gql(UPDATE_TICKET, { id: editing.id, input });
                messageApi.success("Ticket updated.");
            } else {
                const d = await gql(CREATE_TICKET, { tenantId: DEFAULT_TENANT_ID, input });
                messageApi.success(`Ticket ${d.createItsmTicket.ticketNumber} created.`);
            }
            setModalOpen(false);
            setSelectedReporter(null);
            setAiSuggestion(null);
            form.resetFields();
            setEditing(null);
            loadData();
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_TICKET, { id }); messageApi.success("Ticket deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    // Inline update handler — partial update on a single field
    const handleInlineUpdate = async (id: string, field: string, value: any) => {
        try {
            await gql(UPDATE_TICKET, { id, input: { [field]: value } });
            setTickets(prev => prev.map(t => t.id === id ? { ...t, [field]: value } : t));
            messageApi.success(`Updated ${field.replace(/([A-Z])/g, ' $1').toLowerCase()}`);
        } catch (err: any) {
            messageApi.error(`Update failed: ${err.message}`);
        }
    };

    // Quick-create ticket handler
    const handleQuickCreate = async () => {
        if (!quickTitle.trim()) { messageApi.warning('Enter a ticket title'); return; }
        setQuickCreating(true);
        try {
            const d = await gql(CREATE_TICKET, {
                tenantId: DEFAULT_TENANT_ID,
                input: {
                    title: quickTitle.trim(),
                    priority: quickPriority,
                    channel: quickChannel,
                    impact: 'medium',
                    urgency: 'medium',
                },
            });
            messageApi.success(`Ticket ${d.createItsmTicket.ticketNumber} created`);
            setQuickTitle('');
            loadData();
        } catch (err: any) {
            messageApi.error(`Create failed: ${err.message}`);
        } finally {
            setQuickCreating(false);
        }
    };

    const columns: ProColumns<any>[] = [
        {
            title: 'Ticket #', dataIndex: 'ticketNumber', width: 110,
            render: (_, r) => <Tag color="purple" style={{ cursor: 'pointer', fontFamily: 'monospace' }} onClick={() => router.push(`/admin/itsm/tickets/${r.id}`)}>{r.ticketNumber}</Tag>
        },
        { title: 'Title', dataIndex: 'title', ellipsis: true },
        {
            title: 'Priority', dataIndex: 'priority', width: 100,
            render: (_, r) => (
                <Select
                    value={r.priority}
                    size="small"
                    variant="borderless"
                    style={{ width: '100%' }}
                    aria-label={`Priority for ${r.ticketNumber}`}
                    onClick={(e) => e.stopPropagation()}
                    onChange={(val) => handleInlineUpdate(r.id, 'priority', val)}
                    options={[
                        { value: 'critical', label: <Tag color="#f5222d">CRITICAL</Tag> },
                        { value: 'high', label: <Tag color="#fa8c16">HIGH</Tag> },
                        { value: 'medium', label: <Tag color="#1890ff">MEDIUM</Tag> },
                        { value: 'low', label: <Tag color="#52c41a">LOW</Tag> },
                    ]}
                />
            )
        },
        {
            title: 'Status', dataIndex: 'status', width: 130,
            render: (_, r) => (
                <Select
                    value={r.status}
                    size="small"
                    variant="borderless"
                    style={{ width: '100%' }}
                    aria-label={`Status for ${r.ticketNumber}`}
                    onClick={(e) => e.stopPropagation()}
                    onChange={(val) => handleInlineUpdate(r.id, 'status', val)}
                    options={[
                        { value: 'new', label: <Tag color="blue">NEW</Tag> },
                        { value: 'open', label: <Tag color="cyan">OPEN</Tag> },
                        { value: 'in_progress', label: <Tag color="geekblue">IN PROGRESS</Tag> },
                        { value: 'pending', label: <Tag color="orange">PENDING</Tag> },
                        { value: 'resolved', label: <Tag color="green">RESOLVED</Tag> },
                        { value: 'closed', label: <Tag>CLOSED</Tag> },
                    ]}
                />
            )
        },
        {
            title: 'Reporter', dataIndex: 'reporterName', width: 150, ellipsis: true,
            render: (_, r) => {
                const linked = r.contactId || r.individualId || r.accountId || r.pmStakeholderId;
                return <Space size={4}>{linked && <Badge status="success" />}<Text>{r.reporterName || '-'}</Text></Space>;
            }
        },
        {
            title: 'Assigned To', dataIndex: 'assignedTo', width: 140, ellipsis: true,
            render: (_, r: any) => (
                <Input
                    size="small"
                    variant="borderless"
                    placeholder="Unassigned"
                    defaultValue={r.assignedTo || ''}
                    aria-label={`Assignee for ${r.ticketNumber}`}
                    onClick={(e) => e.stopPropagation()}
                    onPressEnter={(e) => {
                        const val = (e.target as HTMLInputElement).value;
                        handleInlineUpdate(r.id, 'assignedTo', val);
                    }}
                    onBlur={(e) => {
                        if (e.target.value !== (r.assignedTo || '')) {
                            handleInlineUpdate(r.id, 'assignedTo', e.target.value);
                        }
                    }}
                    style={{ fontStyle: r.assignedTo ? 'normal' : 'italic', color: r.assignedTo ? 'inherit' : '#999' }}
                />
            )
        },
        { title: 'Channel', dataIndex: 'channel', width: 90, render: (_: any, r: any) => channelLabels[r.channel] || r.channel },
        {
            title: 'SLA', dataIndex: 'slaResolutionDue', width: 80,
            render: (_, r) => {
                if (!r.slaResolutionDue) return '-';
                const breach = new Date(r.slaResolutionDue) < new Date();
                return breach ? <Tag color="red">BREACH</Tag> : <Tag color="green">OK</Tag>;
            }
        },
        {
            title: 'Actions', valueType: 'option', width: 120,
            render: (_, record) => [
                <Tooltip key="view" title="View Details"><Button type="text" icon={<EyeOutlined />} onClick={() => router.push(`/admin/itsm/tickets/${record.id}`)} /></Tooltip>,
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => {
                    setEditing(record);
                    form.setFieldsValue({
                        title: record.title, description: record.description,
                        categoryId: record.categoryId, channel: record.channel,
                        priority: record.priority, impact: record.impact, urgency: record.urgency,
                        reporterName: record.reporterName, reporterEmail: record.reporterEmail,
                        assignedTo: record.assignedTo, assignedGroup: record.assignedGroup,
                        status: record.status, resolutionNotes: record.resolutionNotes,
                    });
                    setModalOpen(true);
                }} />,
                <Popconfirm key="del" title="Delete this ticket?" onConfirm={() => handleDelete(record.id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>,
            ]
        }
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Helpdesk Tickets</AuroraText>}
            subTitle={<DecryptedText text="Manage IT support tickets" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
        <div>
            {contextHolder}
            <ProTable
                headerTitle={
                    <Space>
                        <CustomerServiceOutlined /> Helpdesk Tickets
                        {/* LIVE Indicator */}
                        {realtimeConnected && (
                            <span style={{
                                display: 'inline-flex', alignItems: 'center', gap: 5,
                                padding: '2px 10px', borderRadius: 12,
                                background: 'rgba(16, 185, 129, 0.1)',
                                border: '1px solid rgba(16, 185, 129, 0.25)',
                                fontSize: 10, fontWeight: 700, color: '#10b981',
                                textTransform: 'uppercase', letterSpacing: 1,
                            }}>
                                <span style={{
                                    width: 7, height: 7, borderRadius: '50%',
                                    background: '#10b981',
                                    animation: 'pulse-live 1.5s ease-in-out infinite',
                                }} />
                                LIVE
                                <style>{`@keyframes pulse-live { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.3); } }`}</style>
                            </span>
                        )}
                    </Space>
                }
                rowKey="id"
                dataSource={tickets}
                loading={loading}
                columns={columns}
                search={false}
                toolbar={{
                    search: { placeholder: 'Search tickets...', onSearch: (v) => setSearchText(v), allowClear: true, style: { width: 250 } },
                }}
                toolBarRender={() => [
                    <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'itsm_tickets', title: 'ITSM Tickets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'ticketNumber' }, { header: 'Subject', key: 'subject' }, { header: 'Priority', key: 'priority' }, { header: 'Status', key: 'status' }], data: tickets })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'itsm_tickets', title: 'ITSM Tickets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Number', key: 'ticketNumber' }, { header: 'Subject', key: 'subject' }, { header: 'Priority', key: 'priority' }, { header: 'Status', key: 'status' }], data: tickets })} /></Tooltip></RbacGuard>,
                    <Select key="fs" placeholder="Status" allowClear style={{ width: 130 }} value={filterStatus} onChange={setFilterStatus}
                        options={[
                            { value: 'new', label: 'New' }, { value: 'open', label: 'Open' },
                            { value: 'in_progress', label: 'In Progress' }, { value: 'pending', label: 'Pending' },
                            { value: 'resolved', label: 'Resolved' }, { value: 'closed', label: 'Closed' },
                        ]}
                    />,
                    <Select key="fp" placeholder="Priority" allowClear style={{ width: 120 }} value={filterPriority} onChange={setFilterPriority}
                        options={[
                            { value: 'critical', label: 'Critical' }, { value: 'high', label: 'High' },
                            { value: 'medium', label: 'Medium' }, { value: 'low', label: 'Low' },
                        ]}
                    />,
                    <Button key="quick" type="dashed" icon={<PlusOutlined />}
                        onClick={() => setShowQuickCreate(!showQuickCreate)}
                        aria-label="Quick create ticket"
                        style={{ borderColor: showQuickCreate ? themeColor : undefined, color: showQuickCreate ? themeColor : undefined }}
                    >
                        Quick Create
                    </Button>,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); setSelectedReporter(null); setAiSuggestion(null); form.resetFields(); setModalOpen(true); }}
                        style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: 'none', borderRadius: 8 }}
                    >
                        New Ticket
                    </Button>,
                ]}
                onRow={(record) => ({
                    onClick: () => router.push(`/admin/itsm/tickets/${record.id}`),
                    style: { cursor: 'pointer' },
                    'aria-label': `Ticket ${record.ticketNumber}: ${record.title}`,
                })}
            />

            {/* ─── Quick Create Bar ─── */}
            <AnimatePresence>
                {showQuickCreate && (
                    <motion.div
                        initial={{ opacity: 0, height: 0, marginTop: 0 }}
                        animate={{ opacity: 1, height: 'auto', marginTop: 12 }}
                        exit={{ opacity: 0, height: 0, marginTop: 0 }}
                        transition={{ duration: 0.25 }}
                        style={{ overflow: 'hidden' }}
                    >
                        <div style={{
                            display: 'flex', alignItems: 'center', gap: 10,
                            padding: '10px 16px', borderRadius: 12,
                            background: `linear-gradient(135deg, ${themeColor}08, ${themeColor}04)`,
                            border: `1px solid ${themeColor}30`,
                        }}>
                            <Input
                                placeholder="Quick ticket title — describe the issue..."
                                value={quickTitle}
                                onChange={(e) => setQuickTitle(e.target.value)}
                                onPressEnter={handleQuickCreate}
                                style={{ flex: 1, borderRadius: 8 }}
                                aria-label="Quick ticket title"
                            />
                            <Select
                                value={quickPriority}
                                onChange={setQuickPriority}
                                size="middle"
                                style={{ width: 120 }}
                                aria-label="Quick ticket priority"
                                options={[
                                    { value: 'critical', label: '🔴 Critical' },
                                    { value: 'high', label: '🟠 High' },
                                    { value: 'medium', label: '🔵 Medium' },
                                    { value: 'low', label: '🟢 Low' },
                                ]}
                            />
                            <Select
                                value={quickChannel}
                                onChange={setQuickChannel}
                                size="middle"
                                style={{ width: 120 }}
                                aria-label="Quick ticket channel"
                                options={[
                                    { value: 'portal', label: '🌐 Portal' },
                                    { value: 'email', label: '📧 Email' },
                                    { value: 'phone', label: '📞 Phone' },
                                    { value: 'chat', label: '💬 Chat' },
                                ]}
                            />
                            <Button
                                type="primary"
                                loading={quickCreating}
                                onClick={handleQuickCreate}
                                aria-label="Submit quick ticket"
                                style={{
                                    background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`,
                                    border: 'none', borderRadius: 8,
                                }}
                            >
                                Create
                            </Button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* â”€â”€â”€ Ticket SteppedFormModal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <SteppedFormModal
                open={modalOpen}
                onCancel={() => { setModalOpen(false); setEditing(null); form.resetFields(); setAiSuggestion(null); }}
                onSubmit={handleSave}
                form={form}
                title={editing ? `Edit ${editing.ticketNumber}` : "New Ticket"}
                entityName="ticket"
                steps={[
                    {
                        title: "Issue Details",
                        icon: <AlertOutlined />,
                        fields: ["title", "description"],
                        content: (
                            <>
                                <Form.Item name="title" label="Title" rules={[{ required: true }]}>
                                    <Input placeholder="Brief description of the issue" />
                                </Form.Item>
                                <Form.Item name="description" label="Description">
                                    <Input.TextArea rows={4} placeholder="Detailed description, steps to reproduce, etc." />
                                </Form.Item>

                                {/* AI Auto-Categorize */}
                                {!editing && (
                                    <div style={{ padding: '10px 14px', background: `linear-gradient(135deg, ${themeColor}10 0%, ${themeColor}06 100%)`, borderRadius: 8, border: `1px solid ${themeColor}20` }}>
                                        <Space>
                                            <Button icon={<RobotOutlined />} loading={aiSuggesting} onClick={handleAiCategorize}
                                                style={{ background: themeColor, color: '#fff', border: 'none' }}>
                                                ðŸ¤– AI Auto-Categorize
                                            </Button>
                                            {aiSuggestion && (
                                                <Space size={4}>
                                                    <Tag color="purple">{aiSuggestion.suggestedCategory}</Tag>
                                                    <Tag color={aiSuggestion.suggestedPriority === 'critical' ? 'red' : aiSuggestion.suggestedPriority === 'high' ? 'orange' : 'blue'}>{(aiSuggestion.suggestedPriority || '').toUpperCase()}</Tag>
                                                    <Tag color="green">{Math.round((aiSuggestion.confidence || 0) * 100)}%</Tag>
                                                </Space>
                                            )}
                                        </Space>
                                        {aiSuggestion && <div style={{ marginTop: 6, fontSize: 12, color: '#666' }}>{aiSuggestion.reasoning}</div>}
                                    </div>
                                )}
                            </>
                        ),
                    },
                    {
                        title: "Classification",
                        icon: <SettingOutlined />,
                        fields: ["categoryId", "channel", "priority", "impact", "urgency"],
                        content: (
                            <>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="categoryId" label="Category">
                                            <Select placeholder="Select category" allowClear
                                                options={categories.map(c => ({ value: c.id, label: c.name }))} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="channel" label="Channel">
                                            <Select options={[
                                                { value: 'portal', label: 'ðŸŒ Portal' }, { value: 'email', label: 'ðŸ“§ Email' },
                                                { value: 'phone', label: 'ðŸ“ž Phone' }, { value: 'chat', label: 'ðŸ’¬ Chat' },
                                            ]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                <Row gutter={16}>
                                    <Col span={8}>
                                        <Form.Item name="priority" label="Priority">
                                            <Select options={[
                                                { value: 'critical', label: 'ðŸ”´ Critical' }, { value: 'high', label: 'ðŸŸ  High' },
                                                { value: 'medium', label: 'ðŸ”µ Medium' }, { value: 'low', label: 'ðŸŸ¢ Low' },
                                            ]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={8}>
                                        <Form.Item name="impact" label="Impact">
                                            <Select options={[
                                                { value: 'high', label: 'High' }, { value: 'medium', label: 'Medium' }, { value: 'low', label: 'Low' },
                                            ]} />
                                        </Form.Item>
                                    </Col>
                                    <Col span={8}>
                                        <Form.Item name="urgency" label="Urgency">
                                            <Select options={[
                                                { value: 'high', label: 'High' }, { value: 'medium', label: 'Medium' }, { value: 'low', label: 'Low' },
                                            ]} />
                                        </Form.Item>
                                    </Col>
                                </Row>
                                {editing && (
                                    <Row gutter={16}>
                                        <Col span={12}>
                                            <Form.Item name="status" label="Status">
                                                <Select options={[
                                                    { value: 'new', label: 'New' }, { value: 'open', label: 'Open' },
                                                    { value: 'in_progress', label: 'In Progress' }, { value: 'pending', label: 'Pending' },
                                                    { value: 'resolved', label: 'Resolved' }, { value: 'closed', label: 'Closed' },
                                                ]} />
                                            </Form.Item>
                                        </Col>
                                        <Col span={12}>
                                            <Form.Item name="resolutionNotes" label="Resolution Notes">
                                                <Input.TextArea rows={2} />
                                            </Form.Item>
                                        </Col>
                                    </Row>
                                )}
                            </>
                        ),
                    },
                    {
                        title: "Reporter",
                        icon: <UserOutlined />,
                        fields: ["reporterName", "reporterEmail"],
                        content: (
                            <>
                                <div style={{ marginBottom: 16 }}>
                                    <Text type="secondary" style={{ display: 'block', marginBottom: 8 }}>Search CRM Contacts, Individuals, Accounts, or PM Stakeholders:</Text>
                                    <Select
                                        showSearch placeholder="Search reporter..." filterOption={false}
                                        onSearch={handleSearchReporter}
                                        onChange={(_, opt: any) => {
                                            const r = reporterResults.find(rr => rr.id === opt?.value);
                                            setSelectedReporter(r || null);
                                        }}
                                        style={{ width: '100%' }} suffixIcon={<SearchOutlined />}
                                        value={selectedReporter?.id} allowClear onClear={() => setSelectedReporter(null)}
                                        notFoundContent={null}
                                    >
                                        {reporterResults.map(r => (
                                            <Select.Option key={r.id} value={r.id}>
                                                <Space>
                                                    <Tag color={r.type === 'contact' ? 'blue' : r.type === 'individual' ? 'green' : r.type === 'account' ? 'gold' : 'purple'}>
                                                        {typeLabels[r.type] || r.type}
                                                    </Tag>
                                                    <span><strong>{r.name}</strong>{r.email ? ` â€” ${r.email}` : ''}{r.extra ? ` (${r.extra})` : ''}</span>
                                                </Space>
                                            </Select.Option>
                                        ))}
                                    </Select>
                                    {selectedReporter && (
                                        <div style={{ marginTop: 8, padding: '8px 12px', background: '#f6ffed', borderRadius: 6, border: '1px solid #b7eb8f' }}>
                                            <Text strong>Linked: </Text>
                                            <Tag color="green">{typeLabels[selectedReporter.type]}</Tag>
                                            <Text>{selectedReporter.name}</Text>
                                        </div>
                                    )}
                                </div>
                                <Row gutter={16}>
                                    <Col span={12}>
                                        <Form.Item name="reporterName" label="Reporter Name">
                                            <Input placeholder="Or enter manually" />
                                        </Form.Item>
                                    </Col>
                                    <Col span={12}>
                                        <Form.Item name="reporterEmail" label="Reporter Email">
                                            <Input placeholder="reporter@company.com" />
                                        </Form.Item>
                                    </Col>
                                </Row>
                            </>
                        ),
                    },
                    {
                        title: "Assignment",
                        icon: <TeamOutlined />,
                        fields: ["assignedTo", "assignedGroup"],
                        content: (
                            <Row gutter={16}>
                                <Col span={12}>
                                    <Form.Item name="assignedTo" label="Assigned To">
                                        <Input placeholder="Agent name" />
                                    </Form.Item>
                                </Col>
                                <Col span={12}>
                                    <Form.Item name="assignedGroup" label="Support Group">
                                        <Input placeholder="e.g., L1 Support, Network Team" />
                                    </Form.Item>
                                </Col>
                            </Row>
                        ),
                    },
                ]}
                fields={TICKET_FIELDS}
                width={750}
                gradient={[themeColor, `${themeColor}dd`]}
                editMode={!!editing}
                initialValues={{ priority: 'medium', impact: 'medium', urgency: 'medium', channel: 'portal' }}
            />
        </div>
        </CMSLayout>
    );
}

import React, { useState, useRef, useEffect, useCallback } from "react";
import { mediaService, MediaFile } from "@/lib/mediaService";
import { studioService, StudioNotebook, StudioSource, ChatResponse } from "@/lib/studioService";
import {
    List, Typography, Input, Button, Avatar, Spin, message, Tag, Progress,
    Modal, Upload, Drawer, Empty, Space, Popconfirm
} from "antd";
import type { UploadProps } from "antd";
import {
    RobotOutlined, SendOutlined, FileOutlined, LoadingOutlined,
    FileTextOutlined, PlusOutlined, DeleteOutlined, CloseOutlined,
    BookOutlined, CloudUploadOutlined, CheckCircleFilled, ClockCircleOutlined,
    SyncOutlined, ExclamationCircleOutlined, AppstoreAddOutlined,
    MenuFoldOutlined, MenuUnfoldOutlined, MessageOutlined
} from "@ant-design/icons";
import ReactMarkdown from 'react-markdown';
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { AnimatePresence, motion } from "framer-motion";

const { Text, Paragraph } = Typography;
const { TextArea } = Input;

const CURRENT_USER_ID = "00000000-0000-0000-0000-000000000001";

interface AIStudioDrawerProps { visible: boolean; onClose: () => void; }

export default function AIStudioDrawer({ visible, onClose }: AIStudioDrawerProps) {
    const { themeColor } = usePreferencesStore();

    // Notebook
    const [notebooks, setNotebooks] = useState<StudioNotebook[]>([]);
    const [activeNotebook, setActiveNotebook] = useState<StudioNotebook | null>(null);
    const [loadingNotebooks, setLoadingNotebooks] = useState(true);
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [newNotebookName, setNewNotebookName] = useState("");
    const [creatingNotebook, setCreatingNotebook] = useState(false);

    // Sources
    const [sources, setSources] = useState<StudioSource[]>([]);
    const [loadingSources, setLoadingSources] = useState(false);
    const [showAddMediaModal, setShowAddMediaModal] = useState(false);
    const [mediaFiles, setMediaFiles] = useState<MediaFile[]>([]);
    const [loadingMedia, setLoadingMedia] = useState(false);
    const [addingMedia, setAddingMedia] = useState<Set<string>>(new Set());

    // Chat
    const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'assistant'; content: string; references?: any[]; timestamp: number }[]>([]);
    const [chatInput, setChatInput] = useState("");
    const [isChatting, setIsChatting] = useState(false);
    const [conversationId, setConversationId] = useState<string | undefined>();
    const [showReferences, setShowReferences] = useState<number | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Layout
    const [showSources, setShowSources] = useState(true);

    // Poll
    const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

    useEffect(() => { if (visible) loadNotebooks(); return () => { if (pollRef.current) clearInterval(pollRef.current); }; }, [visible]);
    useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [chatHistory]);

    const loadNotebooks = async () => {
        setLoadingNotebooks(true);
        try { setNotebooks(await studioService.getNotebooks(CURRENT_USER_ID)); } catch { }
        finally { setLoadingNotebooks(false); }
    };

    const selectNotebook = async (nb: StudioNotebook) => {
        setActiveNotebook(nb); setChatHistory([]); setConversationId(undefined); setShowReferences(null);
        loadSourceStatus(nb.id);
    };

    const loadSourceStatus = async (notebookId: string) => {
        setLoadingSources(true);
        try {
            const list = await studioService.getSourceStatus(notebookId);
            setSources(list);
            if (list.some((s: StudioSource) => s.parse_status === 'parsing')) startPolling(notebookId);
        } catch { } finally { setLoadingSources(false); }
    };

    const startPolling = (notebookId: string) => {
        if (pollRef.current) clearInterval(pollRef.current);
        pollRef.current = setInterval(async () => {
            try {
                const list = await studioService.getSourceStatus(notebookId);
                setSources(list);
                if (!list.some((s: StudioSource) => s.parse_status === 'parsing') && pollRef.current) clearInterval(pollRef.current);
            } catch { }
        }, 5000);
    };

    const handleCreateNotebook = async () => {
        if (!newNotebookName.trim()) return;
        setCreatingNotebook(true);
        try {
            const nb = await studioService.createNotebook(newNotebookName, "", CURRENT_USER_ID);
            message.success(`Notebook "${newNotebookName}" created`);
            setNewNotebookName(""); setShowCreateModal(false);
            await loadNotebooks(); selectNotebook(nb);
        } catch (e: any) { message.error(e.message || "Failed"); }
        finally { setCreatingNotebook(false); }
    };

    const handleDeleteNotebook = async (id: string) => {
        try {
            await studioService.deleteNotebook(id); message.success("Deleted");
            if (activeNotebook?.id === id) { setActiveNotebook(null); setSources([]); setChatHistory([]); }
            loadNotebooks();
        } catch (e: any) { message.error(e.message || "Failed"); }
    };

    const openMediaModal = async () => {
        setShowAddMediaModal(true); setLoadingMedia(true);
        try { setMediaFiles(await mediaService.getMedia({ limit: 50 })); } catch { message.error("Failed to load media"); }
        finally { setLoadingMedia(false); }
    };

    const handleAddMedia = async (mediaId: string) => {
        if (!activeNotebook) return;
        setAddingMedia(prev => new Set(prev).add(mediaId));
        try { await studioService.addMediaToNotebook(activeNotebook.id, mediaId); message.success("Source added"); loadSourceStatus(activeNotebook.id); }
        catch (e: any) { message.error(e.message || "Failed"); }
        finally { setAddingMedia(prev => { const s = new Set(prev); s.delete(mediaId); return s; }); }
    };

    const handleUploadFile: UploadProps['customRequest'] = async (options) => {
        if (!activeNotebook) return;
        const { file, onSuccess, onError } = options as any;
        try { await studioService.uploadFileToNotebook(activeNotebook.id, file); onSuccess?.({}, file); message.success(`"${(file as File).name}" uploaded`); loadSourceStatus(activeNotebook.id); }
        catch (e: any) { onError?.(e); message.error(e.message || "Upload failed"); }
    };

    const handleRemoveSource = async (sourceId: string) => {
        if (!activeNotebook) return;
        try { await studioService.removeSource(activeNotebook.id, sourceId); message.success("Removed"); loadSourceStatus(activeNotebook.id); }
        catch (e: any) { message.error(e.message || "Failed"); }
    };

    const handleChatSend = async () => {
        if (!chatInput.trim() || !activeNotebook) return;
        if (sources.filter(s => s.parse_status === 'done').length === 0) { message.warning("No parsed sources yet."); return; }
        const userMsg = { role: 'user' as const, content: chatInput, timestamp: Date.now() };
        setChatHistory(prev => [...prev, userMsg]); setChatInput(""); setIsChatting(true);
        try {
            const result: ChatResponse = await studioService.chat(activeNotebook.id, userMsg.content, conversationId, CURRENT_USER_ID);
            setConversationId(result.conversationId);
            setChatHistory(prev => [...prev, { role: 'assistant', content: result.answer, references: result.references, timestamp: Date.now() }]);
        } catch (e: any) { message.error(e.message || "Chat failed"); }
        finally { setIsChatting(false); }
    };

    const getStatusIcon = (status: string) => {
        if (status === 'done') return <CheckCircleFilled style={{ color: '#52c41a', fontSize: 12 }} />;
        if (status === 'parsing') return <SyncOutlined spin style={{ color: themeColor, fontSize: 12 }} />;
        if (status === 'error') return <ExclamationCircleOutlined style={{ color: '#ff4d4f', fontSize: 12 }} />;
        return <ClockCircleOutlined style={{ color: '#8c8c8c', fontSize: 12 }} />;
    };

    const formatBytes = (bytes: number) => {
        if (bytes === 0) return '0 B'; const k = 1024; const s = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + s[i];
    };

    return (
        <Drawer title={null} size={760} onClose={onClose} open={visible} closable={false}
            styles={{ header: { display: 'none' }, body: { padding: 0, overflow: 'hidden' } }}>
            <div style={{ display: 'flex', height: '100%', overflow: 'hidden' }}>

                {/* LEFT: Notebooks + Sources */}
                <AnimatePresence mode="wait">
                    {showSources && (
                        <motion.div
                            initial={{ width: 0, opacity: 0 }} animate={{ width: 220, opacity: 1 }} exit={{ width: 0, opacity: 0 }}
                            transition={{ duration: 0.2 }}
                            style={{ flexShrink: 0, display: 'flex', flexDirection: 'column', borderRight: '1px solid rgba(0,0,0,0.06)', overflow: 'hidden', height: '100%' }}
                        >
                            {/* Header */}
                            <div style={{ padding: '12px 12px 8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid rgba(0,0,0,0.06)', flexShrink: 0 }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                    <RobotOutlined style={{ fontSize: 14, color: themeColor }} />
                                    <Text strong style={{ fontSize: 13 }}>AI Studio</Text>
                                </div>
                                <button onClick={onClose} style={{ width: 24, height: 24, borderRadius: 6, border: 'none', background: 'rgba(0,0,0,0.04)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, color: 'rgba(0,0,0,0.4)' }}>
                                    <CloseOutlined />
                                </button>
                            </div>

                            {/* Notebooks Section */}
                            <div style={{ padding: '8px 10px 4px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
                                <Text style={{ fontSize: 9, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', opacity: 0.4 }}>Notebooks</Text>
                                <Button type="text" size="small" icon={<PlusOutlined style={{ fontSize: 11 }} />} onClick={() => setShowCreateModal(true)}
                                    style={{ width: 22, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'rgba(0,0,0,0.3)' }} />
                            </div>
                            <div style={{ flex: activeNotebook ? '0 0 auto' : '1', maxHeight: activeNotebook ? 180 : undefined, overflowY: 'auto', padding: '0 6px' }} className="custom-scrollbar">
                                {loadingNotebooks ? <div style={{ textAlign: 'center', padding: 16 }}><Spin size="small" /></div> :
                                    notebooks.length === 0 ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={<span style={{ fontSize: 10, opacity: 0.4 }}>No notebooks</span>} style={{ margin: '16px 0' }} /> :
                                        notebooks.map(nb => (
                                            <div key={nb.id} onClick={() => selectNotebook(nb)}
                                                style={{
                                                    padding: '6px 8px', borderRadius: 8, cursor: 'pointer', marginBottom: 2, display: 'flex', alignItems: 'center', gap: 8,
                                                    background: activeNotebook?.id === nb.id ? `${themeColor}14` : 'transparent',
                                                    border: activeNotebook?.id === nb.id ? `1px solid ${themeColor}33` : '1px solid transparent',
                                                }}>
                                                <span style={{ fontSize: 14 }}>{nb.icon || '📓'}</span>
                                                <div style={{ flex: 1, minWidth: 0 }}>
                                                    <Text ellipsis style={{ fontSize: 11, fontWeight: 500, display: 'block' }}>{nb.name}</Text>
                                                    <Text style={{ fontSize: 9, opacity: 0.4 }}>{nb.source_count || 0} sources</Text>
                                                </div>
                                                <Popconfirm title="Delete?" onConfirm={(e) => { e?.stopPropagation(); handleDeleteNotebook(nb.id); }} onCancel={e => e?.stopPropagation()}>
                                                    <Button type="text" size="small" danger icon={<DeleteOutlined style={{ fontSize: 10 }} />}
                                                        onClick={e => e.stopPropagation()} style={{ width: 20, height: 20, opacity: 0.3 }} />
                                                </Popconfirm>
                                            </div>
                                        ))
                                }
                            </div>

                            {/* Sources Section (when notebook selected) */}
                            {activeNotebook && (
                                <>
                                    <div style={{ padding: '8px 10px 4px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid rgba(0,0,0,0.06)', flexShrink: 0 }}>
                                        <Text style={{ fontSize: 9, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', opacity: 0.4 }}>Sources ({sources.length})</Text>
                                        <Space size={2}>
                                            <Button type="text" size="small" icon={<AppstoreAddOutlined style={{ fontSize: 11 }} />} onClick={openMediaModal}
                                                style={{ width: 22, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'rgba(0,0,0,0.3)' }} />
                                            <Upload customRequest={handleUploadFile} showUploadList={false} multiple>
                                                <Button type="text" size="small" icon={<CloudUploadOutlined style={{ fontSize: 11 }} />}
                                                    style={{ width: 22, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'rgba(0,0,0,0.3)' }} />
                                            </Upload>
                                        </Space>
                                    </div>
                                    <div style={{ flex: 1, overflowY: 'auto', padding: '0 6px 6px' }} className="custom-scrollbar">
                                        {loadingSources ? <div style={{ textAlign: 'center', padding: 12 }}><Spin size="small" /></div> :
                                            sources.length === 0 ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={<span style={{ fontSize: 10, opacity: 0.4 }}>Add sources</span>} style={{ margin: '12px 0' }} /> :
                                                sources.map(s => (
                                                    <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '4px 6px', borderRadius: 6, marginBottom: 1 }} className="group">
                                                        {getStatusIcon(s.parse_status)}
                                                        <div style={{ flex: 1, minWidth: 0 }}>
                                                            <Text ellipsis style={{ fontSize: 10, display: 'block' }}>{s.filename}</Text>
                                                            <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                                <Text style={{ fontSize: 9, opacity: 0.4 }}>{formatBytes(s.file_size)}</Text>
                                                                {s.chunk_count > 0 && <Text style={{ fontSize: 9, opacity: 0.4 }}>· {s.chunk_count} chunks</Text>}
                                                            </div>
                                                            {s.parse_status === 'parsing' && <Progress percent={Math.round(s.parse_progress * 100)} size="small" strokeColor={themeColor} style={{ marginTop: 2 }} />}
                                                        </div>
                                                        <Button type="text" size="small" danger icon={<DeleteOutlined style={{ fontSize: 9 }} />}
                                                            onClick={() => handleRemoveSource(s.id)} style={{ width: 18, height: 18, opacity: 0 }} className="group-hover:!opacity-100" />
                                                    </div>
                                                ))
                                        }
                                    </div>
                                </>
                            )}
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* RIGHT: Chat */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden', minWidth: 0 }}>
                    {/* Chat Header */}
                    <div style={{ padding: '10px 14px', borderBottom: '1px solid rgba(0,0,0,0.06)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexShrink: 0 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                            <Button type="text" size="small" icon={showSources ? <MenuFoldOutlined /> : <MenuUnfoldOutlined />}
                                onClick={() => setShowSources(!showSources)} style={{ width: 26, height: 26, display: 'flex', alignItems: 'center', justifyContent: 'center' }} />
                            <Text strong style={{ fontSize: 12 }}>{activeNotebook ? activeNotebook.name : 'Select a notebook'}</Text>
                            {activeNotebook && sources.some(s => s.parse_status === 'parsing') && <Tag color="processing" icon={<SyncOutlined spin />} style={{ fontSize: 9, margin: 0, lineHeight: '16px', padding: '0 4px' }}>Parsing</Tag>}
                        </div>
                        {conversationId && (
                            <Button type="text" size="small" style={{ fontSize: 10, color: 'rgba(0,0,0,0.4)' }}
                                onClick={() => { setChatHistory([]); setConversationId(undefined); }}>New Chat</Button>
                        )}
                    </div>

                    {/* Chat Messages */}
                    <div style={{ flex: 1, overflowY: 'auto', padding: 14 }} className="custom-scrollbar">
                        {!activeNotebook ? (
                            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', gap: 12, opacity: 0.5 }}>
                                <BookOutlined style={{ fontSize: 36, color: themeColor }} />
                                <Text style={{ fontSize: 11, textAlign: 'center', maxWidth: 200 }}>Select or create a notebook to start chatting with your documents.</Text>
                            </div>
                        ) : chatHistory.length === 0 ? (
                            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', gap: 12, opacity: 0.5 }}>
                                <RobotOutlined style={{ fontSize: 36, color: themeColor }} />
                                <div style={{ textAlign: 'center' }}>
                                    <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>Ask about your sources</Text>
                                    <Text style={{ fontSize: 10, opacity: 0.7, maxWidth: 220, display: 'block' }}>AI will reference parsed documents to answer your questions.</Text>
                                </div>
                            </div>
                        ) : (
                            chatHistory.map((msg, i) => (
                                <div key={i} style={{ marginBottom: 14, display: 'flex', justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start' }}>
                                    <div style={{ maxWidth: '85%' }}>
                                        <div style={{
                                            padding: '10px 14px', fontSize: 12, lineHeight: 1.6, wordBreak: 'break-word',
                                            borderRadius: msg.role === 'user' ? '14px 14px 4px 14px' : '14px 14px 14px 4px',
                                            background: msg.role === 'user' ? themeColor : `${themeColor}0a`,
                                            color: msg.role === 'user' ? '#fff' : 'inherit',
                                            boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
                                        }}>
                                            <div className="prose prose-sm dark:prose-invert max-w-none [&_p]:m-0 [&_ul]:my-1 [&_ol]:my-1 [&_li]:my-0">
                                                <ReactMarkdown>{msg.content}</ReactMarkdown>
                                            </div>
                                        </div>
                                        {msg.references && msg.references.length > 0 && (
                                            <div style={{ marginTop: 4 }}>
                                                <button onClick={() => setShowReferences(showReferences === i ? null : i)}
                                                    style={{ fontSize: 9, color: 'rgba(0,0,0,0.35)', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}>
                                                    📄 {msg.references.length} source{msg.references.length > 1 ? 's' : ''} cited
                                                </button>
                                                <AnimatePresence>
                                                    {showReferences === i && (
                                                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} style={{ overflow: 'hidden' }}>
                                                            <div style={{ marginTop: 4, display: 'flex', flexDirection: 'column', gap: 4 }}>
                                                                {msg.references.map((ref: any, ri: number) => (
                                                                    <div key={ri} style={{ padding: '6px 8px', borderRadius: 6, background: 'rgba(0,0,0,0.03)', fontSize: 10 }}>
                                                                        <Text strong style={{ fontSize: 9, color: themeColor, display: 'block', marginBottom: 2 }}>{ref.docName}</Text>
                                                                        <Text style={{ fontSize: 9, opacity: 0.5 }} className="line-clamp-2">{ref.content}</Text>
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        </motion.div>
                                                    )}
                                                </AnimatePresence>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))
                        )}
                        {isChatting && <div style={{ display: 'flex', justifyContent: 'flex-start', marginBottom: 14 }}><div style={{ padding: 10, borderRadius: 14, background: `${themeColor}08` }}><Spin indicator={<LoadingOutlined spin />} size="small" /></div></div>}
                        <div ref={messagesEndRef} />
                    </div>

                    {/* Chat Input */}
                    <div style={{ padding: '10px 14px', borderTop: '1px solid rgba(0,0,0,0.06)', display: 'flex', gap: 8, flexShrink: 0 }}>
                        <Input value={chatInput} onChange={e => setChatInput(e.target.value)} onPressEnter={handleChatSend}
                            placeholder={activeNotebook ? "Ask about your sources..." : "Select a notebook"} disabled={isChatting || !activeNotebook}
                            style={{ borderRadius: 10, flex: 1 }} />
                        <Button type="primary" icon={<SendOutlined />} onClick={handleChatSend} loading={isChatting} disabled={!activeNotebook}
                            style={{ borderRadius: 10, backgroundColor: themeColor, borderColor: themeColor }} />
                    </div>
                </div>
            </div>

            {/* Create Notebook Modal */}
            <Modal title={<span><BookOutlined style={{ color: themeColor, marginRight: 8 }} />Create Notebook</span>}
                open={showCreateModal} onCancel={() => setShowCreateModal(false)} onOk={handleCreateNotebook}
                confirmLoading={creatingNotebook} okText="Create" okButtonProps={{ style: { backgroundColor: themeColor } }} centered>
                <div style={{ paddingTop: 16 }}>
                    <Input size="large" value={newNotebookName} onChange={e => setNewNotebookName(e.target.value)}
                        placeholder="e.g. Q4 Research Analysis" onPressEnter={handleCreateNotebook} />
                </div>
            </Modal>

            {/* Add from Media Library Modal */}
            <Modal title={<span><AppstoreAddOutlined style={{ color: themeColor, marginRight: 8 }} />Add from Media Library</span>}
                open={showAddMediaModal} onCancel={() => setShowAddMediaModal(false)} footer={null} width={500} centered>
                {loadingMedia ? <div style={{ textAlign: 'center', padding: 40 }}><Spin size="large" /></div> : (
                    <List className="max-h-[350px] overflow-y-auto" dataSource={mediaFiles} renderItem={item => {
                        const added = sources.some(s => s.media_id === item.id);
                        return (
                            <List.Item actions={[added ? <Tag key="a" color="success">Added</Tag> :
                                <Button key="b" type="primary" size="small" icon={<PlusOutlined />} loading={addingMedia.has(item.id)}
                                    onClick={() => handleAddMedia(item.id)} style={{ backgroundColor: themeColor }}>Add</Button>]}>
                                <List.Item.Meta
                                    avatar={<Avatar icon={<FileOutlined />} shape="square" style={{ backgroundColor: `${themeColor}22`, color: themeColor }} />}
                                    title={<Text style={{ fontSize: 12 }}>{item.filename}</Text>}
                                    description={<Text style={{ fontSize: 10, opacity: 0.5 }}>{item.mime_type}</Text>} />
                            </List.Item>);
                    }} />
                )}
            </Modal>
        </Drawer>
    );
}

