                                    <RTooltip contentStyle={ttStyle} />
                                    <Bar dataKey="count" fill="#f59e0b" radius={[0, 6, 6, 0]} label={{ position: 'right', fontSize: 9, fill: chartText }} />
                                </BarChart>
                            </ResponsiveContainer>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={8}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.65 }}>
                        <Card
                            size="small"
                            title={<Space><CheckCircleOutlined style={{ color: '#10b981' }} /> Retry Success Rate</Space>}
                            style={{ ...glass, height: '100%', display: 'flex', flexDirection: 'column' }}
                        >
                            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '16px 0' }}>
                                <Progress
                                    type="dashboard"
                                    percent={87.5}
                                    size={130}
                                    strokeColor={{ '0%': '#10b981', '100%': '#3b82f6' }}
                                    format={p => (
                                        <>
                                            <Text strong style={{ fontSize: 26, color: '#10b981' }}>{p}%</Text>
                                            <br />
                                            <Text type="secondary" style={{ fontSize: 10 }}>success</Text>
                                        </>
                                    )}
                                />
                                <div style={{ marginTop: 12, textAlign: 'center' }}>
                                    <Text type="secondary" style={{ fontSize: 11 }}>
                                        1,247 retried · 1,091 succeeded
                                    </Text>
                                </div>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ─── Recent Errors Table ────────────────── */}
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.7 }}>
                <Card
                    size="small"
                    title={<Space><ClockCircleOutlined style={{ color: '#ef4444' }} /><Text strong>Recent Errors</Text></Space>}
                    style={glass}
                >
                    <Table
                        dataSource={RECENT_ERRORS}
                        rowKey="key"
                        size="small"
                        pagination={false}
                        columns={[
                            {
                                title: 'Time', dataIndex: 'ts', width: 80,
                                render: (v: string) => <Text style={{ fontSize: 11, fontFamily: 'monospace' }}>{v}</Text>,
                            },
                            {
                                title: 'Source', dataIndex: 'source', width: 140,
                                render: (v: string) => <Text strong style={{ fontSize: 12, fontFamily: 'monospace' }}>{v}</Text>,
                            },
                            {
                                title: 'Error', dataIndex: 'message', ellipsis: true,
                                render: (v: string) => <Text type="danger" style={{ fontSize: 11 }}>{v}</Text>,
                            },
                            {
                                title: 'Consumer', dataIndex: 'consumer', width: 140,
                                render: (v: string) => <Tag style={{ borderRadius: 8, fontSize: 10 }}>{v}</Tag>,
                            },
                        ]}
                    />
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Statistic, Space, Tag, Button, Table, Badge } from 'antd';
import { SwapOutlined, DatabaseOutlined, LinkOutlined, ReloadOutlined, CheckCircleOutlined, ThunderboltOutlined, ShareAltOutlined, InboxOutlined } from '@ant-design/icons';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const QUEUES = [
    { name: 'email.send', messages: 23, consumers: 2, rate: '12/s', state: 'running', color: '#3b82f6' },
    { name: 'notifications.push', messages: 5, consumers: 1, rate: '8/s', state: 'running', color: '#8b5cf6' },
    { name: 'reports.generate', messages: 0, consumers: 1, rate: '2/s', state: 'idle', color: '#10b981' },
    { name: 'webhooks.dispatch', messages: 12, consumers: 2, rate: '15/s', state: 'running', color: '#f59e0b' },
    { name: 'audit.process', messages: 0, consumers: 1, rate: '5/s', state: 'idle', color: '#06b6d4' },
];
const EXCHANGES = [
    { name: 'events.topic', type: 'topic', bindings: 5, durable: true },
    { name: 'notifications.fanout', type: 'fanout', bindings: 3, durable: true },
    { name: 'dlx.exchange', type: 'direct', bindings: 2, durable: true },
    { name: 'amq.default', type: 'direct', bindings: 0, durable: true },
];

export default function RabbitMQPage() {
    const { themeColor } = usePreferencesStore();
    const totalMessages = QUEUES.reduce((s, q) => s + q.messages, 0);
    const totalConsumers = QUEUES.reduce((s, q) => s + q.consumers, 0);

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#ff6600', '#10b981']}>RabbitMQ</AuroraText>} subTitle={<DecryptedText text="Queue browser, exchange topology & message rates" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[<Button key="o" icon={<LinkOutlined />} type="primary" onClick={() => window.open('http://localhost:15672', '_blank')}>Open RabbitMQ</Button>, <Button key="r" icon={<ReloadOutlined />} />]}>
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Queues', v: QUEUES.length, c: '#3b82f6', i: <InboxOutlined /> }, { t: 'Messages Ready', v: totalMessages, c: totalMessages > 50 ? '#f59e0b' : '#10b981', i: <DatabaseOutlined /> }, { t: 'Consumers', v: totalConsumers, c: '#8b5cf6', i: <CheckCircleOutlined /> }, { t: 'Exchanges', v: EXCHANGES.length, c: '#f59e0b', i: <ShareAltOutlined /> }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} prefix={s.i} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Card size="small" style={glass} title={<Space><InboxOutlined style={{ color: '#3b82f6' }} /><Text strong>Queues</Text><Badge count={QUEUES.length} style={{ backgroundColor: themeColor }} /></Space>}>
                    <Table dataSource={QUEUES} rowKey="name" size="small" pagination={false} columns={[
                        { title: 'Queue', dataIndex: 'name', render: (v: string) => <Text strong style={{ fontSize: 12, fontFamily: 'monospace' }}>{v}</Text> },
                        { title: 'Messages', dataIndex: 'messages', width: 80, render: (v: number) => <Text strong style={{ color: v > 20 ? '#f59e0b' : '#10b981' }}>{v}</Text> },
                        { title: 'Consumers', dataIndex: 'consumers', width: 80 },
                        { title: 'Rate', dataIndex: 'rate', render: (v: string) => <Tag color="blue" style={{ borderRadius: 8, fontSize: 10 }}>{v}</Tag> },
                        { title: 'State', dataIndex: 'state', render: (v: string) => <Tag color={v === 'running' ? 'green' : 'default'} style={{ borderRadius: 10, fontSize: 10 }}>{v}</Tag> },
                    ]} />
                </Card>

                <Card size="small" style={glass} title={<Space><ShareAltOutlined style={{ color: '#f59e0b' }} /><Text strong>Exchanges</Text></Space>}>
                    <Table dataSource={EXCHANGES} rowKey="name" size="small" pagination={false} columns={[
                        { title: 'Exchange', dataIndex: 'name', render: (v: string) => <Text strong style={{ fontSize: 12, fontFamily: 'monospace' }}>{v}</Text> },
                        { title: 'Type', dataIndex: 'type', render: (v: string) => <Tag color={v === 'topic' ? 'blue' : v === 'fanout' ? 'purple' : 'green'} style={{ borderRadius: 8, fontSize: 10 }}>{v}</Tag> },
                        { title: 'Bindings', dataIndex: 'bindings', width: 80 },
                        { title: 'Durable', dataIndex: 'durable', render: (v: boolean) => <Tag color={v ? 'green' : 'default'} style={{ borderRadius: 10, fontSize: 10 }}>{v ? 'Yes' : 'No'}</Tag> },
                    ]} />
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Button, Spin, Statistic, message, Tooltip, Table, Tag, Space, Empty, Badge } from 'antd';
import { BarChartOutlined, SmileOutlined, FrownOutlined, MehOutlined, RiseOutlined, EyeOutlined, ShareAltOutlined, HeartOutlined, GlobalOutlined, ReloadOutlined, FileExcelOutlined, FilePdfOutlined, FileSearchOutlined } from '@ant-design/icons';
import { newsService, NewsDashboard, NewsArticle, NewsSocialPost } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const sentColors: Record<string, string> = { positive: '#10b981', negative: '#ef4444', neutral: '#94a3b8' };

function HorizontalBar({ items }: { items: { label: string; value: number; color: string }[] }) {
    const max = Math.max(...items.map(i => i.value), 1);
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {items.map((item, i) => (
                <motion.div key={item.label} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.06 }} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <Text style={{ fontSize: 11, minWidth: 80, textAlign: 'right' }}>{item.label}</Text>
                    <div style={{ flex: 1, height: 22, borderRadius: 11, background: 'rgba(0,0,0,0.04)', overflow: 'hidden', position: 'relative' }}>
                        <motion.div initial={{ width: 0 }} animate={{ width: `${(item.value / max) * 100}%` }} transition={{ delay: 0.3 + i * 0.06, duration: 0.5 }}
                            style={{ height: '100%', borderRadius: 11, background: item.color, display: 'flex', alignItems: 'center', paddingLeft: 8, minWidth: item.value > 0 ? 30 : 0 }}>
                            {item.value > 0 && <Text style={{ fontSize: 10, color: '#fff', fontWeight: 600 }}>{item.value}</Text>}
                        </motion.div>
                    </div>
                </motion.div>
            ))}
        </div>
    );
}

export default function AnalyticsPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [dashboard, setDashboard] = useState<NewsDashboard | null>(null);
    const [articles, setArticles] = useState<NewsArticle[]>([]);
    const [posts, setPosts] = useState<NewsSocialPost[]>([]);

    const load = useCallback(async () => { setLoading(true); try { const [d, a, p] = await Promise.all([newsService.getDashboard(), newsService.getArticles(), newsService.getSocialPosts()]); setDashboard(d); setArticles(a); setPosts(p); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    if (loading || !dashboard) return <CMSLayout title="Analytics"><div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div></CMSLayout>;

    const s = dashboard.sentiment;
    const catCounts = new Map<string, number>();
    for (const a of articles) { catCounts.set(a.category || 'general', (catCounts.get(a.category || 'general') || 0) + 1); }
    const catItems = [...catCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8).map((c, i) => ({ label: c[0], value: c[1], color: ['#3b82f6','#10b981','#f59e0b','#8b5cf6','#06b6d4','#ec4899','#f97316','#14b8a6'][i % 8] }));

    const platformCounts = new Map<string, number>();
    for (const p of posts) { platformCounts.set(p.platform, (platformCounts.get(p.platform) || 0) + 1); }
    const platformItems = [...platformCounts.entries()].map(p => ({ label: p[0], value: p[1], color: { twitter: '#1DA1F2', facebook: '#4267B2', linkedin: '#0077B5', instagram: '#E4405F' }[p[0]] || '#94a3b8' }));

    const topArticles = [...articles].sort((a, b) => Math.abs(b.sentimentScore) - Math.abs(a.sentimentScore)).slice(0, 10);

    const expData = articles.map(a => ({ title: a.title, category: a.category, sentiment: a.sentimentLabel, score: a.sentimentScore, author: a.author || '', published: a.publishedAt ? dayjs(a.publishedAt).format('YYYY-MM-DD') : '' }));

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#3b82f6', '#10b981']}>Analytics & Reports</AuroraText>} subTitle={<DecryptedText text="Cross-channel performance metrics and intelligence reports" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
            <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Excel"><Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({ fileName: 'news_analytics', title: 'News Analytics Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Category', key: 'category' }, { header: 'Sentiment', key: 'sentiment' }, { header: 'Score', key: 'score' }], data: expData })} /></Tooltip><Tooltip title="PDF"><Button size="small" icon={<FilePdfOutlined />} onClick={() => exportToPdf({ fileName: 'news_analytics', title: 'News Analytics Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Category', key: 'category' }, { header: 'Sentiment', key: 'sentiment' }, { header: 'Score', key: 'score' }], data: expData })} /></Tooltip></RbacGuard>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[
                        { title: 'Total Articles', value: dashboard.totalArticles, icon: <FileSearchOutlined />, color: '#3b82f6' },
                        { title: 'Social Posts', value: posts.length, icon: <ShareAltOutlined />, color: '#8b5cf6' },
                        { title: 'Total Reach', value: dashboard.totalReach, icon: <EyeOutlined />, color: '#06b6d4' },
                        { title: 'Avg Sentiment', value: `${s.avgScore > 0 ? '+' : ''}${s.avgScore}`, icon: s.avgScore >= 0 ? <SmileOutlined /> : <FrownOutlined />, color: s.avgScore >= 0 ? '#10b981' : '#ef4444' },
                        { title: 'Positive %', value: `${s.total ? Math.round(s.positive / s.total * 100) : 0}%`, icon: <SmileOutlined />, color: '#10b981' },
                        { title: 'Sources', value: dashboard.activeSources, icon: <GlobalOutlined />, color: '#f59e0b' },
                    ].map((st, i) => (
                        <Col key={i} xs={12} md={4}><motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${st.color}` }}><Statistic title={st.title} value={st.value} prefix={st.icon} valueStyle={{ color: st.color, fontSize: 18 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Row gutter={[14, 14]}>
                    <Col xs={24} md={12}>
                        <Card size="small" style={{ ...glass, height: '100%' }} title={<><BarChartOutlined style={{ color: '#3b82f6' }} /> <Text strong style={{ fontSize: 13 }}>Articles by Category</Text></>}>
                            {catItems.length === 0 ? <Empty description="No data" /> : <HorizontalBar items={catItems} />}
                        </Card>
                    </Col>
                    <Col xs={24} md={12}>
                        <Card size="small" style={{ ...glass, height: '100%' }} title={<><ShareAltOutlined style={{ color: '#8b5cf6' }} /> <Text strong style={{ fontSize: 13 }}>Posts by Platform</Text></>}>
                            {platformItems.length === 0 ? <Empty description="No social posts" /> : <HorizontalBar items={platformItems} />}
                        </Card>
                    </Col>
                </Row>

                <Row gutter={[14, 14]}>
                    <Col xs={24} md={8}>
                        <Card size="small" style={{ ...glass, height: '100%' }} title={<><SmileOutlined style={{ color: '#10b981' }} /> <Text strong style={{ fontSize: 13 }}>Sentiment Breakdown</Text></>}>
                            <HorizontalBar items={[{ label: 'Positive', value: s.positive, color: '#10b981' }, { label: 'Neutral', value: s.neutral, color: '#94a3b8' }, { label: 'Negative', value: s.negative, color: '#ef4444' }]} />
                        </Card>
                    </Col>
                    <Col xs={24} md={16}>
                        <Card size="small" style={glass} title={<><RiseOutlined style={{ color: '#f59e0b' }} /> <Text strong style={{ fontSize: 13 }}>Top Impact Articles</Text></>}>
                            {topArticles.length === 0 ? <Empty description="No articles" /> :
                                <Table size="small" dataSource={topArticles.map(a => ({ ...a, key: a.id }))} pagination={false} scroll={{ x: 500 }} columns={[
                                    { title: 'Title', dataIndex: 'title', ellipsis: true },
                                    { title: 'Sentiment', dataIndex: 'sentimentLabel', width: 90, render: (v: string) => <Tag color={sentColors[v]} style={{ borderRadius: 8 }}>{v}</Tag> },
                                    { title: 'Score', dataIndex: 'sentimentScore', width: 70, align: 'center' as const, render: (v: number) => <Text style={{ fontFamily: 'monospace', fontWeight: 700, color: v > 0 ? '#10b981' : v < 0 ? '#ef4444' : '#94a3b8' }}>{v > 0 ? '+' : ''}{v}</Text> },
                                ]} />}
                        </Card>
                    </Col>
                </Row>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Button, Space, Tag, Spin, Empty, Modal, Form, Input, Select, InputNumber, Statistic, message, Tooltip, Badge, Row, Col, Popconfirm, Drawer, List } from 'antd';
import { RobotOutlined, PlusOutlined, PlayCircleOutlined, PauseCircleOutlined, DeleteOutlined, HistoryOutlined, ReloadOutlined, GlobalOutlined, CheckCircleOutlined, CloseCircleOutlined, ClockCircleOutlined, ThunderboltOutlined, FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { newsService, NewsCrawlJob, NewsCrawlHistory } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const statusColors: Record<string, string> = { active: 'green', paused: 'orange', error: 'red', completed: 'blue' };

export default function WebCrawlerPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [jobs, setJobs] = useState<NewsCrawlJob[]>([]);
    const [addModal, setAddModal] = useState(false);
    const [historyDrawer, setHistoryDrawer] = useState<string | null>(null);
    const [history, setHistory] = useState<NewsCrawlHistory[]>([]);
    const [historyLoading, setHistoryLoading] = useState(false);
    const [form] = Form.useForm();
    const [running, setRunning] = useState<Set<string>>(new Set());

    const load = useCallback(async () => { setLoading(true); try { setJobs(await newsService.getCrawlJobs()); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    const addJob = async () => { try { const v = await form.validateFields(); await newsService.createCrawlJob(undefined, { name: v.name, jobType: v.jobType || 'rss', targetUrl: v.targetUrl, schedule: v.schedule, selectors: v.selectors ? JSON.parse(v.selectors) : {}, maxDepth: v.maxDepth || 1 }); message.success('Crawler created'); setAddModal(false); form.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const runJob = async (id: string) => { setRunning(p => new Set(p).add(id)); try { await newsService.executeCrawl(id); message.success('Crawl completed'); load(); } catch (e: any) { message.error(e.message); } finally { setRunning(p => { const n = new Set(p); n.delete(id); return n; }); } };
    const togglePause = async (id: string, current: string) => { try { await newsService.updateCrawlJob(id, { status: current === 'active' ? 'paused' : 'active' }); load(); } catch (e: any) { message.error(e.message); } };
    const delJob = async (id: string) => { try { await newsService.deleteCrawlJob(id); message.success('Deleted'); load(); } catch (e: any) { message.error(e.message); } };
    const showHistory = async (id: string) => { setHistoryDrawer(id); setHistoryLoading(true); try { setHistory(await newsService.getCrawlHistory(id)); } catch {} finally { setHistoryLoading(false); } };

    const totalJobs = jobs.length;
    const activeJobs = jobs.filter(j => j.status === 'active').length;
    const totalPages = jobs.reduce((s, j) => s + (j.totalPagesCrawled || 0), 0);
    const totalArticles = jobs.reduce((s, j) => s + (j.totalArticlesExtracted || 0), 0);

    const cols: any[] = [
        { title: 'Name', key: 'name', render: (_: any, r: NewsCrawlJob) => (<div><Text strong style={{ fontSize: 13 }}>{r.name}</Text><br /><Text type="secondary" style={{ fontSize: 10, fontFamily: 'monospace' }}>{r.targetUrl?.slice(0, 50)}{(r.targetUrl?.length || 0) > 50 ? '...' : ''}</Text></div>) },
        { title: 'Type', dataIndex: 'jobType', width: 80, render: (v: string) => <Tag>{v?.toUpperCase()}</Tag> },
        { title: 'Status', dataIndex: 'status', width: 90, render: (v: string) => <Tag color={statusColors[v] || 'default'}>{v}</Tag> },
        { title: 'Pages', dataIndex: 'totalPagesCrawled', width: 70, align: 'center' as const },
        { title: 'Articles', dataIndex: 'totalArticlesExtracted', width: 80, align: 'center' as const },
        { title: 'Last Run', key: 'lr', width: 140, render: (_: any, r: NewsCrawlJob) => r.lastRunAt ? <Text style={{ fontSize: 11 }}>{dayjs(r.lastRunAt).format('DD MMM HH:mm')}</Text> : <Text type="secondary" style={{ fontSize: 11 }}>Never</Text> },
        { title: 'Actions', key: 'a', width: 160, render: (_: any, r: NewsCrawlJob) => (<Space size={4}>
            <Tooltip title="Run now"><Button type="text" size="small" icon={<ThunderboltOutlined />} loading={running.has(r.id)} onClick={() => runJob(r.id)} style={{ color: '#10b981' }} /></Tooltip>
            <Tooltip title={r.status === 'active' ? 'Pause' : 'Resume'}><Button type="text" size="small" icon={r.status === 'active' ? <PauseCircleOutlined /> : <PlayCircleOutlined />} onClick={() => togglePause(r.id, r.status)} /></Tooltip>
            <Tooltip title="History"><Button type="text" size="small" icon={<HistoryOutlined />} onClick={() => showHistory(r.id)} /></Tooltip>
            <Popconfirm title="Delete?" onConfirm={() => delJob(r.id)}><Button type="text" size="small" icon={<DeleteOutlined />} danger /></Popconfirm>
        </Space>) },
    ];

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#f59e0b', '#10b981']}>Web Crawler</AuroraText>} subTitle={<DecryptedText text="Configure web scrapers and RSS feeds for automated content ingestion" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { form.resetFields(); setAddModal(true); }} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>New Crawler</Button>,
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
            <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Excel"><Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({ fileName: 'crawlers', title: 'Web Crawlers', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'URL', key: 'targetUrl' }, { header: 'Type', key: 'jobType' }, { header: 'Status', key: 'status' }, { header: 'Pages', key: 'totalPagesCrawled' }, { header: 'Articles', key: 'totalArticlesExtracted' }], data: jobs })} /></Tooltip></RbacGuard>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Total Jobs', v: totalJobs, c: '#3b82f6' }, { t: 'Active', v: activeJobs, c: '#10b981' }, { t: 'Pages Crawled', v: totalPages, c: '#f59e0b' }, { t: 'Articles Found', v: totalArticles, c: '#8b5cf6' }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>
                <Card style={glass}>
                    {loading ? <div style={{ textAlign: 'center', padding: 60 }}><Spin /></div> : jobs.length === 0 ? <Empty description="No crawlers configured yet" /> :
                        <Table columns={cols} dataSource={jobs.map(j => ({ ...j, key: j.id }))} size="middle" scroll={{ x: 800 }} pagination={{ pageSize: 20 }} />
                    }
                </Card>
            </motion.div>

            <Modal title="New Crawler" open={addModal} onOk={addJob} onCancel={() => setAddModal(false)} okText="Create" width={520}>
                <Form form={form} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="name" label="Name" rules={[{ required: true }]}><Input placeholder="Tech News RSS" /></Form.Item>
                    <Form.Item name="targetUrl" label="Target URL" rules={[{ required: true }]}><Input placeholder="https://example.com/rss.xml" /></Form.Item>
                    <Row gutter={12}><Col span={12}><Form.Item name="jobType" label="Type" initialValue="rss"><Select options={[{ label: 'RSS Feed', value: 'rss' }, { label: 'Web Page', value: 'web' }, { label: 'Sitemap', value: 'sitemap' }, { label: 'API', value: 'api' }]} /></Form.Item></Col><Col span={12}><Form.Item name="maxDepth" label="Max Depth" initialValue={1}><InputNumber min={1} max={5} style={{ width: '100%' }} /></Form.Item></Col></Row>
                    <Form.Item name="schedule" label="Schedule (cron)" initialValue="0 */6 * * *"><Input placeholder="0 */6 * * *" /></Form.Item>
                    <Form.Item name="selectors" label="CSS Selectors (JSON, optional)"><Input.TextArea rows={3} placeholder='{"title":"h1","content":".article-body"}' /></Form.Item>
                </Form>
            </Modal>

            <Drawer title="Crawl History" open={!!historyDrawer} onClose={() => setHistoryDrawer(null)} width={420}>
                {historyLoading ? <Spin /> : history.length === 0 ? <Empty description="No crawl history" /> :
                    <List size="small" dataSource={history} renderItem={(h, i) => (
                        <motion.div key={h.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03 }}>
                            <List.Item>
                                <div style={{ width: '100%' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <Tag color={h.status === 'completed' ? 'green' : h.status === 'failed' ? 'red' : 'blue'}>{h.status}</Tag>
                                        <Text style={{ fontSize: 11 }}>{h.startedAt ? dayjs(h.startedAt).format('DD MMM HH:mm') : ''}</Text>
                                    </div>
                                    <Space style={{ marginTop: 4, fontSize: 11 }} split="·">
                                        <Text type="secondary">Pages: {h.pagesCrawled}</Text>
                                        <Text type="secondary">Found: {h.articlesFound}</Text>
                                        <Text type="secondary">New: {h.articlesNew}</Text>
                                        <Text type="secondary">{h.durationMs}ms</Text>
                                    </Space>
                                </div>
                            </List.Item>
                        </motion.div>
                    )} />
                }
            </Drawer>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Statistic, Typography, Spin, message, Tag, Badge, Space, List, Empty, Tooltip, Button } from 'antd';
import { GlobalOutlined, FileSearchOutlined, RobotOutlined, ShareAltOutlined, AlertOutlined, RiseOutlined, SmileOutlined, FrownOutlined, MehOutlined, ReloadOutlined, FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { newsService, NewsDashboard, NewsArticle } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const sentColors: Record<string, string> = { positive: '#10b981', negative: '#ef4444', neutral: '#94a3b8' };

function SentimentDonut({ pos, neg, neu }: { pos: number; neg: number; neu: number }) {
    const total = pos + neg + neu || 1;
    const r = 38, cx = 50, cy = 50, c = 2 * Math.PI * r;
    const segments = [
        { pct: pos / total, color: '#10b981' },
        { pct: neg / total, color: '#ef4444' },
        { pct: neu / total, color: '#94a3b8' },
    ];
    let offset = 0;
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
            <svg viewBox="0 0 100 100" width={80} height={80}>
                {segments.map((s, i) => { const dash = s.pct * c; const o = offset; offset += dash; return <circle key={i} cx={cx} cy={cy} r={r} fill="none" stroke={s.color} strokeWidth={8} strokeDasharray={`${dash} ${c - dash}`} strokeDashoffset={-o} style={{ transform: 'rotate(-90deg)', transformOrigin: '50% 50%' }} />; })}
                <text x={cx} y={cy + 4} textAnchor="middle" fontSize="12" fontWeight="700" fill="currentColor">{total}</text>
            </svg>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                {[{ l: 'Positive', v: pos, c: '#10b981', i: <SmileOutlined /> }, { l: 'Negative', v: neg, c: '#ef4444', i: <FrownOutlined /> }, { l: 'Neutral', v: neu, c: '#94a3b8', i: <MehOutlined /> }].map((s, i) => (
                    <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <div style={{ width: 8, height: 8, borderRadius: '50%', background: s.c }} />
                        <Text style={{ fontSize: 11 }}>{s.l}: <strong>{s.v}</strong> ({Math.round((s.v / total) * 100)}%)</Text>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default function NewsDashboardPage() {
    const { themeColor } = usePreferencesStore();
    const [loading, setLoading] = useState(true);
    const [dashboard, setDashboard] = useState<NewsDashboard | null>(null);
    const [recentArticles, setRecentArticles] = useState<NewsArticle[]>([]);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [d, articles] = await Promise.all([newsService.getDashboard(), newsService.getArticles(undefined, {})]);
            setDashboard(d);
            setRecentArticles(articles.slice(0, 8));
        } catch (e: any) { message.error(e.message); }
        finally { setLoading(false); }
    }, []);
    useEffect(() => { load(); }, [load]);

    if (loading || !dashboard) return <CMSLayout title="News Intelligence"><div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div></CMSLayout>;
    const s = dashboard.sentiment;

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#06b6d4', '#8b5cf6']}>News Intelligence</AuroraText>}
            subTitle={<DecryptedText text="Media monitoring, sentiment analysis & competitive intelligence" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[<Button key="r" icon={<ReloadOutlined />} onClick={load}>Refresh</Button>]}
        >
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <BentoGrid className="max-w-full">
                    <BentoGridItem
                        title="Total Articles"
                        description="Indexed across all sources"
                        icon={<FileSearchOutlined style={{ color: '#3b82f6' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-blue-500/10">
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#3b82f6' }}>{dashboard.totalArticles.toLocaleString()}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Active Sources"
                        description="Tracked media outlets"
                        icon={<GlobalOutlined style={{ color: '#10b981' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-emerald-500/10">
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#10b981' }}>{dashboard.activeSources.toLocaleString()}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Active Crawlers"
                        description="Automated scrapers"
                        icon={<RobotOutlined style={{ color: '#f59e0b' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-amber-500/10">
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#f59e0b' }}>{dashboard.activeCrawlers.toLocaleString()}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Social Accounts"
                        description="Connected API integrations"
                        icon={<ShareAltOutlined style={{ color: '#8b5cf6' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-purple-500/10">
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#8b5cf6' }}>{dashboard.connectedAccounts.toLocaleString()}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Total Reach"
                        description="Estimated audience footprint"
                        icon={<RiseOutlined style={{ color: '#06b6d4' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-cyan-500/10">
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#06b6d4' }}>{dashboard.totalReach.toLocaleString()}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Active Alerts"
                        description="Real-time notifications"
                        icon={<AlertOutlined style={{ color: '#ef4444' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-red-500/10">
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#ef4444' }}>{dashboard.activeAlerts.toLocaleString()}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                </BentoGrid>

                <Row gutter={[14, 14]}>
                    <Col xs={24} md={10}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                            <Card size="small" style={{ ...glass, height: '100%' }} title={<><SmileOutlined style={{ color: '#10b981' }} /> <Text strong style={{ fontSize: 13 }}>Sentiment Overview</Text></>}>
                                <SentimentDonut pos={s.positive} neg={s.negative} neu={s.neutral} />
                                <div style={{ marginTop: 12, padding: '8px 12px', borderRadius: 8, background: `${s.avgScore >= 0 ? '#10b98110' : '#ef444410'}`, border: `1px solid ${s.avgScore >= 0 ? '#10b98130' : '#ef444430'}` }}>
                                    <Text style={{ fontSize: 12 }}>Average Score: <strong style={{ color: s.avgScore >= 0 ? '#10b981' : '#ef4444' }}>{s.avgScore > 0 ? '+' : ''}{s.avgScore}</strong></Text>
                                </div>
                            </Card>
                        </motion.div>
                    </Col>
                    <Col xs={24} md={14}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.35 }}>
                            <Card size="small" style={{ ...glass, height: '100%' }} title={<><FileSearchOutlined style={{ color: '#3b82f6' }} /> <Text strong style={{ fontSize: 13 }}>Recent Articles</Text> <Badge count={recentArticles.length} style={{ backgroundColor: themeColor }} /></>}>
                                {recentArticles.length === 0 ? <Empty description="No articles yet — set up sources or run a crawler" /> : (
                                    <List size="small" dataSource={recentArticles} renderItem={(a, i) => (
                                        <motion.div key={a.id} initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.4 + i * 0.04 }}>
                                            <List.Item style={{ padding: '6px 0', borderBottom: '1px solid rgba(0,0,0,0.04)' }}>
                                                <div style={{ flex: 1, minWidth: 0 }}>
                                                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                                        <div style={{ width: 6, height: 6, borderRadius: '50%', background: sentColors[a.sentimentLabel] || '#94a3b8', flexShrink: 0 }} />
                                                        <Text strong style={{ fontSize: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.title}</Text>
                                                    </div>
                                                    <Text type="secondary" style={{ fontSize: 10, marginLeft: 12 }}>{a.author || 'Unknown'} · {a.publishedAt ? dayjs(a.publishedAt).fromNow() : '—'}</Text>
                                                </div>
                                                <Tag color={sentColors[a.sentimentLabel]} style={{ fontSize: 9, borderRadius: 8, margin: 0 }}>{a.sentimentLabel}</Tag>
                                            </List.Item>
                                        </motion.div>
                                    )} />
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                </Row>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Button, Space, Tag, Spin, Empty, Input, Select, Drawer, message, Tooltip, Badge, Row, Col, Statistic, Modal, Form } from 'antd';
import { FileSearchOutlined, BookOutlined, StarOutlined, StarFilled, EyeOutlined, PlusOutlined, LinkOutlined, ReloadOutlined, FileExcelOutlined, FilePdfOutlined, SmileOutlined, FrownOutlined, MehOutlined, SearchOutlined } from '@ant-design/icons';
import { newsService, NewsArticle } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
dayjs.extend(relativeTime);

const { Text, Paragraph } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const sentColors: Record<string, string> = { positive: '#10b981', negative: '#ef4444', neutral: '#94a3b8', mixed: '#f59e0b' };
const sentIcons: Record<string, React.ReactNode> = { positive: <SmileOutlined />, negative: <FrownOutlined />, neutral: <MehOutlined /> };

export default function NewsFeedPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [articles, setArticles] = useState<NewsArticle[]>([]);
    const [search, setSearch] = useState('');
    const [filterCategory, setFilterCategory] = useState<string | undefined>();
    const [filterSentiment, setFilterSentiment] = useState<string | undefined>();
    const [selected, setSelected] = useState<NewsArticle | null>(null);
    const [addModal, setAddModal] = useState(false);
    const [form] = Form.useForm();

    const load = useCallback(async () => { setLoading(true); try { setArticles(await newsService.getArticles(undefined, { search: search || undefined, category: filterCategory, sentiment: filterSentiment })); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, [search, filterCategory, filterSentiment]);
    useEffect(() => { load(); }, [load]);

    const addArticle = async () => { try { const v = await form.validateFields(); await newsService.createArticle(undefined, v); message.success('Article added'); setAddModal(false); form.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };

    const categories = [...new Set(articles.map(a => a.category).filter(Boolean))];
    const posCount = articles.filter(a => a.sentimentLabel === 'positive').length;
    const negCount = articles.filter(a => a.sentimentLabel === 'negative').length;
    const neuCount = articles.filter(a => a.sentimentLabel === 'neutral').length;

    const cols: any[] = [
        { title: 'Article', key: 'title', render: (_: any, r: NewsArticle) => (<div style={{ maxWidth: 400 }}><Text strong style={{ fontSize: 13 }}>{r.title}</Text>{r.author && <><br /><Text type="secondary" style={{ fontSize: 11 }}>{r.author}</Text></>}{r.publishedAt && <Text type="secondary" style={{ fontSize: 10, marginLeft: 8 }}>{dayjs(r.publishedAt).fromNow()}</Text>}</div>) },
        { title: 'Category', dataIndex: 'category', width: 110, render: (v: string) => <Tag>{v || 'general'}</Tag> },
        { title: 'Sentiment', key: 'sent', width: 120, render: (_: any, r: NewsArticle) => (<Space><span style={{ color: sentColors[r.sentimentLabel] }}>{sentIcons[r.sentimentLabel]}</span><Tag color={sentColors[r.sentimentLabel]} style={{ borderRadius: 8 }}>{r.sentimentLabel}</Tag></Space>), filters: [{ text: 'Positive', value: 'positive' }, { text: 'Negative', value: 'negative' }, { text: 'Neutral', value: 'neutral' }], onFilter: (v: any, r: NewsArticle) => r.sentimentLabel === v },
        { title: 'Score', dataIndex: 'sentimentScore', width: 80, align: 'center' as const, render: (v: number) => <Text style={{ fontFamily: 'monospace', fontSize: 12, color: v > 0 ? '#10b981' : v < 0 ? '#ef4444' : '#94a3b8' }}>{v > 0 ? '+' : ''}{v}</Text>, sorter: (a: NewsArticle, b: NewsArticle) => a.sentimentScore - b.sentimentScore },
        { title: '', key: 'a', width: 60, render: (_: any, r: NewsArticle) => (<Space><Tooltip title="Preview"><Button type="text" size="small" icon={<EyeOutlined />} onClick={() => setSelected(r)} /></Tooltip>{r.url && <Tooltip title="Open source"><a href={r.url} target="_blank" rel="noopener"><LinkOutlined /></a></Tooltip>}</Space>) },
    ];

    const expData = articles.map(a => ({ title: a.title, author: a.author || '', category: a.category || '', sentiment: a.sentimentLabel, score: a.sentimentScore, published: a.publishedAt ? dayjs(a.publishedAt).format('YYYY-MM-DD') : '' }));

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#3b82f6', '#06b6d4']}>News Feed</AuroraText>} subTitle={<DecryptedText text="Aggregated news from all sources with sentiment scoring" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { form.resetFields(); setAddModal(true); }} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>Add Article</Button>,
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
            <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Excel"><Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({ fileName: 'news_feed', title: 'News Feed', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Author', key: 'author' }, { header: 'Category', key: 'category' }, { header: 'Sentiment', key: 'sentiment' }, { header: 'Score', key: 'score' }], data: expData })} /></Tooltip><Tooltip title="PDF"><Button size="small" icon={<FilePdfOutlined />} onClick={() => exportToPdf({ fileName: 'news_feed', title: 'News Feed', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Category', key: 'category' }, { header: 'Sentiment', key: 'sentiment' }, { header: 'Score', key: 'score' }], data: expData })} /></Tooltip></RbacGuard>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Total', v: articles.length, c: '#3b82f6' }, { t: 'Positive', v: posCount, c: '#10b981' }, { t: 'Negative', v: negCount, c: '#ef4444' }, { t: 'Neutral', v: neuCount, c: '#94a3b8' }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Card size="small" style={glass}>
                    <Space wrap>
                        <Input.Search placeholder="Search articles..." style={{ width: 260 }} allowClear value={search} onChange={e => setSearch(e.target.value)} onSearch={load} prefix={<SearchOutlined />} />
                        <Select placeholder="Category" allowClear style={{ width: 150 }} value={filterCategory} onChange={v => { setFilterCategory(v); }} options={categories.map(c => ({ label: c, value: c }))} />
                        <Select placeholder="Sentiment" allowClear style={{ width: 140 }} value={filterSentiment} onChange={v => { setFilterSentiment(v); }} options={[{ label: '😊 Positive', value: 'positive' }, { label: '😞 Negative', value: 'negative' }, { label: '😐 Neutral', value: 'neutral' }]} />
                    </Space>
                </Card>

                <Card style={glass}>
                    {loading ? <div style={{ textAlign: 'center', padding: 60 }}><Spin /></div> : articles.length === 0 ? <Empty description="No articles found" /> :
                        <Table columns={cols} dataSource={articles.map(a => ({ ...a, key: a.id }))} size="middle" scroll={{ x: 800 }} pagination={{ pageSize: 20, showTotal: t => `${t} articles` }} />
                    }
                </Card>
            </motion.div>

            <Drawer title={selected?.title} open={!!selected} onClose={() => setSelected(null)} width={520}>
                {selected && (<div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    <Space><Tag color={sentColors[selected.sentimentLabel]}>{selected.sentimentLabel}</Tag><Text type="secondary">{selected.author}</Text><Text type="secondary">{selected.publishedAt ? dayjs(selected.publishedAt).format('DD MMM YYYY') : ''}</Text></Space>
                    {selected.summary && <Card size="small" style={{ background: '#f8fafc' }}><Paragraph style={{ fontSize: 13 }}>{selected.summary}</Paragraph></Card>}
                    {selected.content && <Paragraph style={{ fontSize: 13 }}>{selected.content}</Paragraph>}
                    {selected.url && <a href={selected.url} target="_blank" rel="noopener"><Button icon={<LinkOutlined />} block>Open Source</Button></a>}
                    {selected.keywords && (selected.keywords as string[]).length > 0 && <div><Text type="secondary" style={{ fontSize: 11 }}>Keywords:</Text><br />{(selected.keywords as string[]).map((k, i) => <Tag key={i} style={{ fontSize: 10, marginTop: 4 }}>{k}</Tag>)}</div>}
                </div>)}
            </Drawer>

            <Modal title="Add Article" open={addModal} onOk={addArticle} onCancel={() => setAddModal(false)} okText="Add">
                <Form form={form} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="title" label="Title" rules={[{ required: true }]}><Input placeholder="Article title" /></Form.Item>
                    <Form.Item name="url" label="URL"><Input placeholder="https://..." /></Form.Item>
                    <Form.Item name="author" label="Author"><Input placeholder="Author name" /></Form.Item>
                    <Form.Item name="summary" label="Summary"><Input.TextArea rows={3} /></Form.Item>
                    <Form.Item name="category" label="Category" initialValue="general"><Select options={[{ label: 'General', value: 'general' }, { label: 'Technology', value: 'technology' }, { label: 'Finance', value: 'finance' }, { label: 'Industry', value: 'industry' }, { label: 'Crawled', value: 'crawled' }]} /></Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Button, Space, Tag, Spin, Empty, Table, Statistic, Modal, Form, Input, Select, message, Tooltip, Badge, Popconfirm, List, Timeline } from 'antd';
import { FundProjectionScreenOutlined, PlusOutlined, GlobalOutlined, RiseOutlined, FallOutlined, MinusOutlined, DeleteOutlined, ReloadOutlined, AimOutlined, ThunderboltOutlined, BulbOutlined, FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { newsService, NewsCompetitor, NewsMarketSignal } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const impactColors: Record<string, string> = { positive: '#10b981', negative: '#ef4444', neutral: '#94a3b8' };
const impactIcons: Record<string, React.ReactNode> = { positive: <RiseOutlined />, negative: <FallOutlined />, neutral: <MinusOutlined /> };
const signalColors: Record<string, string> = { news: '#3b82f6', price_change: '#f59e0b', product_launch: '#8b5cf6', hiring: '#10b981', funding: '#06b6d4', partnership: '#ec4899' };

export default function MarketSoundingPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [competitors, setCompetitors] = useState<NewsCompetitor[]>([]);
    const [signals, setSignals] = useState<NewsMarketSignal[]>([]);
    const [compModal, setCompModal] = useState(false);
    const [signalModal, setSignalModal] = useState(false);
    const [compForm] = Form.useForm();
    const [signalForm] = Form.useForm();

    const load = useCallback(async () => { setLoading(true); try { const [c, s] = await Promise.all([newsService.getCompetitors(), newsService.getMarketSignals()]); setCompetitors(c); setSignals(s); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    const addComp = async () => { try { const v = await compForm.validateFields(); await newsService.createCompetitor(undefined, { ...v, keywords: v.keywords || [] }); message.success('Competitor added'); setCompModal(false); compForm.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const addSignal = async () => { try { const v = await signalForm.validateFields(); await newsService.createMarketSignal(undefined, v); message.success('Signal added'); setSignalModal(false); signalForm.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const delComp = async (id: string) => { try { await newsService.deleteCompetitor(id); message.success('Removed'); load(); } catch (e: any) { message.error(e.message); } };

    if (loading) return <CMSLayout title="Market Sounding"><div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div></CMSLayout>;

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#f59e0b', '#06b6d4']}>Market Sounding</AuroraText>} subTitle={<DecryptedText text="Competitive intelligence, market trends & industry benchmarks" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="comp" icon={<PlusOutlined />} onClick={() => { compForm.resetFields(); setCompModal(true); }}>Add Competitor</Button>,
            <Button key="sig" type="primary" icon={<ThunderboltOutlined />} onClick={() => { signalForm.resetFields(); setSignalModal(true); }} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>Add Signal</Button>,
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
            <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Excel"><Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({ fileName: 'market_signals', title: 'Market Signals', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Type', key: 'signalType' }, { header: 'Title', key: 'title' }, { header: 'Impact', key: 'impact' }, { header: 'Confidence', key: 'confidence' }], data: signals })} /></Tooltip></RbacGuard>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Competitors', v: competitors.length, c: '#3b82f6' }, { t: 'Market Signals', v: signals.length, c: '#f59e0b' }, { t: 'Positive Impact', v: signals.filter(s => s.impact === 'positive').length, c: '#10b981' }, { t: 'Negative Impact', v: signals.filter(s => s.impact === 'negative').length, c: '#ef4444' }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Card title={<><AimOutlined style={{ color: themeColor }} /> <Text strong>Competitors</Text> <Badge count={competitors.length} style={{ backgroundColor: themeColor }} /></>} style={glass} size="small">
                    {competitors.length === 0 ? <Empty description="No competitors tracked yet" /> : (
                        <Row gutter={[12, 12]}>
                            {competitors.map((c, i) => (
                                <Col key={c.id} xs={24} sm={12} md={8}>
                                    <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                                        <Card size="small" hoverable style={{ borderLeft: `3px solid ${themeColor}`, borderRadius: 10 }} actions={[<Popconfirm key="del" title="Remove?" onConfirm={() => delComp(c.id)}><DeleteOutlined style={{ color: '#ef4444' }} /></Popconfirm>]}>
                                            <Text strong style={{ fontSize: 14 }}>{c.name}</Text>
                                            {c.industry && <><br /><Tag style={{ fontSize: 10, marginTop: 4 }}>{c.industry}</Tag></>}
                                            {c.website && <><br /><a href={c.website} target="_blank" rel="noopener" style={{ fontSize: 11 }}><GlobalOutlined /> {c.website.replace(/https?:\/\//, '').slice(0, 30)}</a></>}
                                            {c.description && <><br /><Text type="secondary" style={{ fontSize: 11, marginTop: 4, display: 'block' }}>{c.description.slice(0, 80)}</Text></>}
                                            <div style={{ marginTop: 6 }}><Text type="secondary" style={{ fontSize: 10 }}>Signals: {c.signalCount || 0}</Text></div>
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </Row>
                    )}
                </Card>

                <Card title={<><BulbOutlined style={{ color: '#f59e0b' }} /> <Text strong>Market Signals Timeline</Text> <Badge count={signals.length} style={{ backgroundColor: '#f59e0b' }} /></>} style={glass}>
                    {signals.length === 0 ? <Empty description="No market signals recorded" /> : (
                        <Timeline mode="left" items={signals.slice(0, 20).map((s, i) => ({
                            color: impactColors[s.impact] || '#94a3b8',
                            children: (
                                <motion.div key={s.id} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.04 }} style={{ padding: '4px 0' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                        <Tag color={signalColors[s.signalType] || 'default'} style={{ fontSize: 10, borderRadius: 6 }}>{s.signalType.replace('_', ' ')}</Tag>
                                        <span style={{ color: impactColors[s.impact], fontSize: 12 }}>{impactIcons[s.impact]}</span>
                                    </div>
                                    <Text strong style={{ fontSize: 13, display: 'block', marginTop: 2 }}>{s.title}</Text>
                                    {s.description && <Text type="secondary" style={{ fontSize: 11, display: 'block' }}>{s.description.slice(0, 120)}</Text>}
                                    <Text type="secondary" style={{ fontSize: 10 }}>{s.detectedAt ? dayjs(s.detectedAt).format('DD MMM YYYY HH:mm') : ''} · Confidence: {Math.round((s.confidence || 0) * 100)}%</Text>
                                </motion.div>
                            ),
                        }))} />
                    )}
                </Card>
            </motion.div>

            <Modal title="Add Competitor" open={compModal} onOk={addComp} onCancel={() => setCompModal(false)} okText="Add">
                <Form form={compForm} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="name" label="Name" rules={[{ required: true }]}><Input placeholder="Competitor name" /></Form.Item>
                    <Form.Item name="website" label="Website"><Input placeholder="https://..." /></Form.Item>
                    <Form.Item name="industry" label="Industry"><Input placeholder="e.g. Technology, Finance" /></Form.Item>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                    <Form.Item name="keywords" label="Tracking Keywords"><Select mode="tags" placeholder="Add keywords" /></Form.Item>
                </Form>
            </Modal>

            <Modal title="Add Market Signal" open={signalModal} onOk={addSignal} onCancel={() => setSignalModal(false)} okText="Add">
                <Form form={signalForm} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="signalType" label="Signal Type" rules={[{ required: true }]}><Select options={[{ label: 'News', value: 'news' }, { label: 'Price Change', value: 'price_change' }, { label: 'Product Launch', value: 'product_launch' }, { label: 'Hiring', value: 'hiring' }, { label: 'Funding', value: 'funding' }, { label: 'Partnership', value: 'partnership' }]} /></Form.Item>
                    <Form.Item name="title" label="Title" rules={[{ required: true }]}><Input placeholder="Signal headline" /></Form.Item>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                    <Form.Item name="competitorId" label="Competitor"><Select allowClear placeholder="Link to competitor" options={competitors.map(c => ({ label: c.name, value: c.id }))} /></Form.Item>
                    <Row gutter={12}><Col span={12}><Form.Item name="impact" label="Impact" initialValue="neutral"><Select options={[{ label: '📈 Positive', value: 'positive' }, { label: '📉 Negative', value: 'negative' }, { label: '➖ Neutral', value: 'neutral' }]} /></Form.Item></Col><Col span={12}><Form.Item name="sourceUrl" label="Source URL"><Input placeholder="https://..." /></Form.Item></Col></Row>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Button, Space, Tag, Spin, Empty, Table, Statistic, Modal, Form, Input, Select, message, Tooltip, Badge, Popconfirm } from 'antd';
import { EditOutlined, PlusOutlined, SendOutlined, CheckCircleOutlined, CloseCircleOutlined, CalendarOutlined, DeleteOutlined, ReloadOutlined, EyeOutlined, FileExcelOutlined, FilePdfOutlined, ScheduleOutlined } from '@ant-design/icons';
import { newsService, NewsContentDraft, NewsCalendarEntry } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import dayjs from 'dayjs';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const statusColors: Record<string, string> = { draft: 'default', review: 'blue', approved: 'cyan', scheduled: 'orange', published: 'green', rejected: 'red' };

export default function PublishingPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [drafts, setDrafts] = useState<NewsContentDraft[]>([]);
    const [calendar, setCalendar] = useState<NewsCalendarEntry[]>([]);
    const [addModal, setAddModal] = useState(false);
    const [calModal, setCalModal] = useState(false);
    const [form] = Form.useForm();
    const [calForm] = Form.useForm();

    const load = useCallback(async () => { setLoading(true); try { const [d, c] = await Promise.all([newsService.getContentDrafts(), newsService.getContentCalendar()]); setDrafts(d); setCalendar(c); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    const addDraft = async () => { try { const v = await form.validateFields(); await newsService.createContentDraft(undefined, v); message.success('Draft created'); setAddModal(false); form.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const addCal = async () => { try { const v = await calForm.validateFields(); await newsService.createCalendarEntry(undefined, { ...v, scheduledDate: v.scheduledDate }); message.success('Added to calendar'); setCalModal(false); calForm.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const updateStatus = async (id: string, status: string) => { try { await newsService.updateContentDraft(id, { status }); message.success(`Status: ${status}`); load(); } catch (e: any) { message.error(e.message); } };
    const delDraft = async (id: string) => { try { await newsService.deleteContentDraft(id); message.success('Deleted'); load(); } catch (e: any) { message.error(e.message); } };

    const total = drafts.length;
    const draftCount = drafts.filter(d => d.status === 'draft').length;
    const published = drafts.filter(d => d.status === 'published').length;
    const scheduled = drafts.filter(d => d.status === 'scheduled').length;

    const cols: any[] = [
        { title: 'Title', key: 'title', render: (_: any, r: NewsContentDraft) => (<div><Text strong style={{ fontSize: 13 }}>{r.title}</Text><br /><Tag style={{ fontSize: 10 }}>{r.contentType}</Tag></div>) },
        { title: 'Channels', key: 'ch', width: 150, render: (_: any, r: NewsContentDraft) => <Space size={4} wrap>{((r.targetChannels as string[]) || []).map((c, i) => <Tag key={i} style={{ fontSize: 10 }}>{c}</Tag>)}</Space> },
        { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color={statusColors[v]}>{v}</Tag>, filters: Object.keys(statusColors).map(s => ({ text: s, value: s })), onFilter: (v: any, r: any) => r.status === v },
        { title: 'Created', key: 'c', width: 130, render: (_: any, r: NewsContentDraft) => <Text style={{ fontSize: 11 }}>{r.createdAt ? dayjs(r.createdAt).format('DD MMM HH:mm') : '—'}</Text> },
        { title: 'Actions', key: 'a', width: 180, render: (_: any, r: NewsContentDraft) => (<Space size={4}>
            {r.status === 'draft' && <Tooltip title="Submit for Review"><Button type="text" size="small" icon={<EyeOutlined />} onClick={() => updateStatus(r.id, 'review')} /></Tooltip>}
            {r.status === 'review' && <><Tooltip title="Approve"><Button type="text" size="small" icon={<CheckCircleOutlined />} style={{ color: '#10b981' }} onClick={() => updateStatus(r.id, 'approved')} /></Tooltip><Tooltip title="Reject"><Button type="text" size="small" icon={<CloseCircleOutlined />} danger onClick={() => updateStatus(r.id, 'rejected')} /></Tooltip></>}
            {r.status === 'approved' && <Tooltip title="Publish"><Button type="text" size="small" icon={<SendOutlined />} style={{ color: '#3b82f6' }} onClick={() => updateStatus(r.id, 'published')} /></Tooltip>}
            <Popconfirm title="Delete?" onConfirm={() => delDraft(r.id)}><Button type="text" size="small" icon={<DeleteOutlined />} danger /></Popconfirm>
        </Space>) },
    ];

    // Calendar grid (simple month view)
    const today = dayjs();
    const daysInMonth = today.daysInMonth();
    const calDays = Array.from({ length: daysInMonth }, (_, i) => {
        const d = today.startOf('month').add(i, 'day');
        const items = calendar.filter(c => c.scheduledDate === d.format('YYYY-MM-DD'));
        return { date: d, items };
    });

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#8b5cf6', '#3b82f6']}>Content Publishing</AuroraText>} subTitle={<DecryptedText text="Create, review, schedule & publish content across channels" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { form.resetFields(); setAddModal(true); }} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>New Draft</Button>,
            <Button key="cal" icon={<CalendarOutlined />} onClick={() => { calForm.resetFields(); setCalModal(true); }}>Schedule</Button>,
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
            <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Excel"><Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({ fileName: 'content_publishing', title: 'Content Publishing', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Type', key: 'contentType' }, { header: 'Status', key: 'status' }], data: drafts })} /></Tooltip></RbacGuard>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Total', v: total, c: '#3b82f6' }, { t: 'Drafts', v: draftCount, c: '#94a3b8' }, { t: 'Published', v: published, c: '#10b981' }, { t: 'Scheduled', v: scheduled, c: '#f59e0b' }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Card title={<><CalendarOutlined style={{ color: themeColor }} /> <Text strong>Content Calendar — {today.format('MMMM YYYY')}</Text></>} size="small" style={glass}>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 4 }}>
                        {['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d => <div key={d} style={{ textAlign: 'center', fontSize: 10, fontWeight: 600, color: '#94a3b8', padding: 4 }}>{d}</div>)}
                        {Array.from({ length: today.startOf('month').day() }, (_, i) => <div key={`e${i}`} />)}
                        {calDays.map(({ date, items }, i) => (
                            <motion.div key={i} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.01 }} style={{ padding: 4, minHeight: 50, borderRadius: 6, background: date.isSame(today, 'day') ? `${themeColor}10` : 'rgba(0,0,0,0.02)', border: date.isSame(today, 'day') ? `1px solid ${themeColor}30` : '1px solid transparent', fontSize: 11 }}>
                                <div style={{ fontWeight: date.isSame(today, 'day') ? 700 : 400, color: date.isSame(today, 'day') ? themeColor : undefined, marginBottom: 2 }}>{date.date()}</div>
                                {items.map((it, j) => <div key={j} style={{ fontSize: 9, padding: '1px 4px', borderRadius: 4, background: it.color || '#3b82f6', color: '#fff', marginBottom: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{it.title}</div>)}
                            </motion.div>
                        ))}
                    </div>
                </Card>

                <Card style={glass} title={<><EditOutlined style={{ color: themeColor }} /> <Text strong>Content Drafts</Text> <Badge count={total} style={{ backgroundColor: themeColor }} /></>}>
                    {loading ? <Spin /> : drafts.length === 0 ? <Empty description="No content drafts" /> :
                        <Table columns={cols} dataSource={drafts.map(d => ({ ...d, key: d.id }))} size="small" scroll={{ x: 700 }} pagination={{ pageSize: 15 }} />}
                </Card>
            </motion.div>

            <Modal title="New Content Draft" open={addModal} onOk={addDraft} onCancel={() => setAddModal(false)} okText="Create" width={520}>
                <Form form={form} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="title" label="Title" rules={[{ required: true }]}><Input placeholder="Content title" /></Form.Item>
                    <Form.Item name="body" label="Body"><Input.TextArea rows={4} placeholder="Write content..." /></Form.Item>
                    <Row gutter={12}><Col span={12}><Form.Item name="contentType" label="Type" initialValue="article"><Select options={[{ label: 'Article', value: 'article' }, { label: 'Social Post', value: 'social_post' }, { label: 'Newsletter', value: 'newsletter' }, { label: 'Press Release', value: 'press_release' }]} /></Form.Item></Col><Col span={12}><Form.Item name="targetChannels" label="Channels"><Select mode="multiple" options={[{ label: 'Website', value: 'website' }, { label: 'Twitter/X', value: 'twitter' }, { label: 'Facebook', value: 'facebook' }, { label: 'LinkedIn', value: 'linkedin' }]} /></Form.Item></Col></Row>
                    <Form.Item name="tags" label="Tags"><Select mode="tags" placeholder="Add tags" /></Form.Item>
                </Form>
            </Modal>

            <Modal title="Schedule Content" open={calModal} onOk={addCal} onCancel={() => setCalModal(false)} okText="Schedule">
                <Form form={calForm} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="title" label="Title" rules={[{ required: true }]}><Input /></Form.Item>
                    <Form.Item name="scheduledDate" label="Date" rules={[{ required: true }]}><Input type="date" /></Form.Item>
                    <Form.Item name="channel" label="Channel" rules={[{ required: true }]}><Select options={[{ label: 'Website', value: 'website' }, { label: 'Twitter', value: 'twitter' }, { label: 'Facebook', value: 'facebook' }, { label: 'LinkedIn', value: 'linkedin' }]} /></Form.Item>
                    <Form.Item name="description" label="Notes"><Input.TextArea rows={2} /></Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Button, Space, Tag, Spin, Empty, Table, Statistic, Input, message, Tooltip, Badge } from 'antd';
import { SmileOutlined, FrownOutlined, MehOutlined, ExperimentOutlined, ReloadOutlined, ThunderboltOutlined, FileExcelOutlined, FilePdfOutlined, SearchOutlined } from '@ant-design/icons';
import { newsService, NewsSentimentEntry, NewsSentimentSummary } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useDateRangeStore } from '@/store/useDateRangeStore';
import { exportToPdf, exportToExcel } from '@/lib/exportUtils';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import RbacGuard from '@/components/common/RbacGuard';
import dayjs from 'dayjs';

const { Text, Paragraph } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const sentColors: Record<string, string> = { positive: '#10b981', negative: '#ef4444', neutral: '#94a3b8' };

function SentimentGauge({ summary }: { summary: NewsSentimentSummary }) {
    const total = summary.total || 1;
    const segments = [
        { label: 'Positive', count: summary.positive, color: '#10b981', icon: <SmileOutlined /> },
        { label: 'Neutral', count: summary.neutral, color: '#94a3b8', icon: <MehOutlined /> },
        { label: 'Negative', count: summary.negative, color: '#ef4444', icon: <FrownOutlined /> },
    ];
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ display: 'flex', height: 24, borderRadius: 12, overflow: 'hidden' }}>
                {segments.map((s, i) => (
                    <motion.div key={i} initial={{ width: 0 }} animate={{ width: `${(s.count / total) * 100}%` }} transition={{ delay: 0.3 + i * 0.1, duration: 0.5 }}
                        style={{ background: s.color, display: 'flex', alignItems: 'center', justifyContent: 'center', minWidth: s.count > 0 ? 30 : 0 }}>
                        {s.count > 0 && <Text style={{ fontSize: 10, color: '#fff', fontWeight: 600 }}>{Math.round((s.count / total) * 100)}%</Text>}
                    </motion.div>
                ))}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                {segments.map((s, i) => (
                    <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                        <span style={{ color: s.color, fontSize: 14 }}>{s.icon}</span>
                        <Text style={{ fontSize: 11 }}>{s.label}: <strong>{s.count}</strong></Text>
                    </div>
                ))}
            </div>
        </div>
    );
}

function KeywordCloud({ entries }: { entries: NewsSentimentEntry[] }) {
    const freqMap = new Map<string, number>();
    for (const e of entries) {
        for (const kw of (e.keywords as string[] || [])) { freqMap.set(kw, (freqMap.get(kw) || 0) + 1); }
    }
    const sorted = [...freqMap.entries()].sort((a, b) => b[1] - a[1]).slice(0, 25);
    const max = sorted[0]?.[1] || 1;
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, justifyContent: 'center', padding: '8px 0' }}>
            {sorted.map(([word, count], i) => {
                const size = 11 + Math.round((count / max) * 12);
                const opacity = 0.4 + (count / max) * 0.6;
                return (<motion.span key={word} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity, scale: 1 }} transition={{ delay: i * 0.02 }} style={{ fontSize: size, fontWeight: count > max * 0.5 ? 700 : 400, color: '#3b82f6', padding: '2px 6px', cursor: 'default' }} title={`${count} occurrences`}>{word}</motion.span>);
            })}
        </div>
    );
}

export default function SentimentAnalysisPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [loading, setLoading] = useState(true);
    const [entries, setEntries] = useState<NewsSentimentEntry[]>([]);
    const [summary, setSummary] = useState<NewsSentimentSummary>({ total: 0, positive: 0, negative: 0, neutral: 0, avgScore: 0 });
    const [analyzeText, setAnalyzeText] = useState('');
    const [analyzing, setAnalyzing] = useState(false);

    const load = useCallback(async () => { setLoading(true); try { const [e, s] = await Promise.all([newsService.getSentimentEntries(), newsService.getSentimentSummary()]); setEntries(e); setSummary(s); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    const doAnalyze = async () => { if (!analyzeText.trim()) return; setAnalyzing(true); try { const r = await newsService.analyzeSentiment(undefined, analyzeText); message.success(`Sentiment: ${r.label} (score: ${r.score})`); setAnalyzeText(''); load(); } catch (e: any) { message.error(e.message); } finally { setAnalyzing(false); } };

    const cols: any[] = [
        { title: 'Text', key: 'text', ellipsis: true, render: (_: any, r: NewsSentimentEntry) => <Text style={{ fontSize: 12 }}>{r.textSnippet || '—'}</Text> },
        { title: 'Score', dataIndex: 'score', width: 80, align: 'center' as const, sorter: (a: any, b: any) => a.score - b.score, render: (v: number) => <Text style={{ fontFamily: 'monospace', fontSize: 12, fontWeight: 700, color: v > 0 ? '#10b981' : v < 0 ? '#ef4444' : '#94a3b8' }}>{v > 0 ? '+' : ''}{v}</Text> },
        { title: 'Label', dataIndex: 'label', width: 100, render: (v: string) => <Tag color={sentColors[v]} style={{ borderRadius: 8 }}>{v}</Tag>, filters: [{ text: 'Positive', value: 'positive' }, { text: 'Negative', value: 'negative' }, { text: 'Neutral', value: 'neutral' }], onFilter: (v: any, r: any) => r.label === v },
        { title: 'Confidence', dataIndex: 'magnitude', width: 90, align: 'center' as const, render: (v: number) => <Text style={{ fontSize: 11 }}>{Math.round((v || 0) * 100)}%</Text> },
        { title: 'Source', dataIndex: 'sourceType', width: 90, render: (v: string) => <Tag>{v}</Tag> },
        { title: 'Date', key: 'd', width: 130, render: (_: any, r: NewsSentimentEntry) => <Text style={{ fontSize: 11 }}>{r.analyzedAt ? dayjs(r.analyzedAt).format('DD MMM HH:mm') : '—'}</Text> },
    ];
    const expData = entries.map(e => ({ text: e.textSnippet, score: e.score, label: e.label, confidence: Math.round((e.magnitude || 0) * 100), source: e.sourceType, date: e.analyzedAt ? dayjs(e.analyzedAt).format('YYYY-MM-DD') : '' }));

    if (loading) return <CMSLayout title="Sentiment Analysis"><div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div></CMSLayout>;

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#10b981', '#ef4444']}>Sentiment Analysis</AuroraText>} subTitle={<DecryptedText text="NLP-powered sentiment tracking across all news sources" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
            <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Excel"><Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({ fileName: 'sentiment', title: 'Sentiment Analysis', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Text', key: 'text' }, { header: 'Score', key: 'score' }, { header: 'Label', key: 'label' }, { header: 'Confidence', key: 'confidence' }], data: expData })} /></Tooltip><Tooltip title="PDF"><Button size="small" icon={<FilePdfOutlined />} onClick={() => exportToPdf({ fileName: 'sentiment', title: 'Sentiment Analysis', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Text', key: 'text' }, { header: 'Score', key: 'score' }, { header: 'Label', key: 'label' }], data: expData })} /></Tooltip></RbacGuard>,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Total Analyzed', v: summary.total, c: '#3b82f6' }, { t: 'Positive', v: summary.positive, c: '#10b981', i: <SmileOutlined /> }, { t: 'Negative', v: summary.negative, c: '#ef4444', i: <FrownOutlined /> }, { t: 'Avg Score', v: `${summary.avgScore > 0 ? '+' : ''}${summary.avgScore}`, c: summary.avgScore >= 0 ? '#10b981' : '#ef4444' }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} prefix={s.i} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Row gutter={[14, 14]}>
                    <Col xs={24} md={14}>
                        <Card size="small" style={glass} title={<><ExperimentOutlined style={{ color: themeColor }} /> <Text strong style={{ fontSize: 13 }}>Sentiment Distribution</Text></>}>
                            <SentimentGauge summary={summary} />
                        </Card>
                    </Col>
                    <Col xs={24} md={10}>
                        <Card size="small" style={glass} title={<><ThunderboltOutlined style={{ color: '#f59e0b' }} /> <Text strong style={{ fontSize: 13 }}>Analyze Text</Text></>}>
                            <Input.TextArea rows={3} value={analyzeText} onChange={e => setAnalyzeText(e.target.value)} placeholder="Paste text here to analyze sentiment..." />
                            <Button type="primary" icon={<ThunderboltOutlined />} loading={analyzing} onClick={doAnalyze} block style={{ marginTop: 8, borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>Analyze Sentiment</Button>
                        </Card>
                    </Col>
                </Row>

                {entries.length > 0 && (
                    <Card size="small" style={glass} title={<><SearchOutlined style={{ color: '#3b82f6' }} /> <Text strong style={{ fontSize: 13 }}>Keyword Cloud</Text></>}>
                        <KeywordCloud entries={entries} />
                    </Card>
                )}

                <Card style={glass} title={<><ExperimentOutlined style={{ color: themeColor }} /> <Text strong>All Entries</Text> <Badge count={entries.length} style={{ backgroundColor: themeColor }} /></>}>
                    <Table columns={cols} dataSource={entries.map(e => ({ ...e, key: e.id }))} size="small" scroll={{ x: 700 }} pagination={{ pageSize: 20, showTotal: t => `${t} entries` }} />
                </Card>
            </motion.div>
        </CMSLayout>
    );
}

'use client';
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Button, Space, Tag, Spin, Empty, Modal, Form, Input, Select, Table, Statistic, message, Tooltip, Badge, Popconfirm } from 'antd';
import { ShareAltOutlined, PlusOutlined, TwitterOutlined, FacebookOutlined, LinkedinOutlined, InstagramOutlined, SendOutlined, DeleteOutlined, ReloadOutlined, HeartOutlined, MessageOutlined, RetweetOutlined, EyeOutlined, UserOutlined } from '@ant-design/icons';
import { newsService, NewsSocialAccount, NewsSocialPost } from '@/lib/newsService';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const platformColors: Record<string, string> = { twitter: '#1DA1F2', facebook: '#4267B2', linkedin: '#0077B5', instagram: '#E4405F', tiktok: '#000000' };
const platformIcons: Record<string, React.ReactNode> = { twitter: <TwitterOutlined />, facebook: <FacebookOutlined />, linkedin: <LinkedinOutlined />, instagram: <InstagramOutlined />, tiktok: <EyeOutlined /> };
const fmtK = (v: number) => { if (v >= 1e6) return `${(v/1e6).toFixed(1)}M`; if (v >= 1e3) return `${(v/1e3).toFixed(1)}K`; return String(v); };

export default function SocialMediaPage() {
    const { themeColor } = usePreferencesStore();
    const [loading, setLoading] = useState(true);
    const [accounts, setAccounts] = useState<NewsSocialAccount[]>([]);
    const [posts, setPosts] = useState<NewsSocialPost[]>([]);
    const [accountModal, setAccountModal] = useState(false);
    const [postModal, setPostModal] = useState(false);
    const [accountForm] = Form.useForm();
    const [postForm] = Form.useForm();

    const load = useCallback(async () => { setLoading(true); try { const [a, p] = await Promise.all([newsService.getSocialAccounts(), newsService.getSocialPosts()]); setAccounts(a); setPosts(p); } catch (e: any) { message.error(e.message); } finally { setLoading(false); } }, []);
    useEffect(() => { load(); }, [load]);

    const addAccount = async () => { try { const v = await accountForm.validateFields(); await newsService.createSocialAccount(undefined, v); message.success('Account connected'); setAccountModal(false); accountForm.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const addPost = async () => { try { const v = await postForm.validateFields(); await newsService.createSocialPost(undefined, v); message.success('Post created'); setPostModal(false); postForm.resetFields(); load(); } catch (e: any) { if (e.message) message.error(e.message); } };
    const delAccount = async (id: string) => { try { await newsService.deleteSocialAccount(id); message.success('Removed'); load(); } catch (e: any) { message.error(e.message); } };

    const totalFollowers = accounts.reduce((s, a) => s + (a.followersCount || 0), 0);
    const totalPosts = posts.length;
    const published = posts.filter(p => p.status === 'published').length;
    const scheduled = posts.filter(p => p.status === 'scheduled').length;

    if (loading) return <CMSLayout title="Social Media"><div style={{ textAlign: 'center', padding: 100 }}><Spin size="large" /></div></CMSLayout>;

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#1DA1F2', '#E4405F']}>Social Media</AuroraText>} subTitle={<DecryptedText text="Multi-platform social media monitoring & publishing" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[
            <Button key="acc" icon={<PlusOutlined />} onClick={() => { accountForm.resetFields(); setAccountModal(true); }}>Connect Account</Button>,
            <Button key="post" type="primary" icon={<SendOutlined />} onClick={() => { postForm.resetFields(); setPostModal(true); }} style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}>New Post</Button>,
            <Button key="r" icon={<ReloadOutlined />} onClick={load} />,
        ]}>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[12, 12]}>
                    {[{ t: 'Connected', v: accounts.length, c: '#3b82f6' }, { t: 'Total Followers', v: fmtK(totalFollowers), c: '#10b981' }, { t: 'Published', v: published, c: '#8b5cf6' }, { t: 'Scheduled', v: scheduled, c: '#f59e0b' }].map((s, i) => (
                        <Col key={i} xs={12} md={6}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.c}` }}><Statistic title={s.t} value={s.v} valueStyle={{ color: s.c, fontSize: 20 }} /></Card></motion.div></Col>
                    ))}
                </Row>

                <Card title={<><ShareAltOutlined style={{ color: themeColor }} /> <Text strong>Connected Accounts</Text> <Badge count={accounts.length} style={{ backgroundColor: themeColor }} /></>} style={glass} size="small">
                    {accounts.length === 0 ? <Empty description="No social accounts connected yet" /> : (
                        <Row gutter={[12, 12]}>
                            {accounts.map((a, i) => (
                                <Col key={a.id} xs={24} sm={12} md={8} lg={6}>
                                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.05 }}>
                                        <Card size="small" hoverable style={{ borderLeft: `3px solid ${platformColors[a.platform] || themeColor}`, borderRadius: 10 }} actions={[<Popconfirm key="del" title="Remove?" onConfirm={() => delAccount(a.id)}><DeleteOutlined style={{ color: '#ef4444' }} /></Popconfirm>]}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
                                                <div style={{ width: 36, height: 36, borderRadius: '50%', background: `${platformColors[a.platform]}15`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, color: platformColors[a.platform] }}>{platformIcons[a.platform] || <ShareAltOutlined />}</div>
                                                <div><Text strong style={{ fontSize: 13 }}>{a.displayName || a.accountName}</Text><br /><Tag color={platformColors[a.platform]} style={{ fontSize: 9, borderRadius: 6 }}>{a.platform}</Tag></div>
                                            </div>
                                            <Space split="·" style={{ fontSize: 11 }}>
                                                <Text type="secondary"><UserOutlined /> {fmtK(a.followersCount)}</Text>
                                                <Text type="secondary">{a.postsCount} posts</Text>
                                            </Space>
                                            <div style={{ marginTop: 6 }}><Tag color={a.status === 'connected' ? 'green' : 'red'} style={{ fontSize: 10 }}>{a.status}</Tag></div>
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </Row>
                    )}
                </Card>

                <Card title={<><SendOutlined style={{ color: themeColor }} /> <Text strong>Posts</Text> <Badge count={totalPosts} style={{ backgroundColor: '#3b82f6' }} /></>} style={glass}>
                    {posts.length === 0 ? <Empty description="No posts yet" /> :
                        <Table size="small" scroll={{ x: 700 }} dataSource={posts.map(p => ({ ...p, key: p.id }))} pagination={{ pageSize: 15 }} columns={[
                            { title: 'Platform', key: 'p', width: 100, render: (_: any, r: NewsSocialPost) => <Tag color={platformColors[r.platform]} icon={platformIcons[r.platform]}>{r.platform}</Tag> },
                            { title: 'Content', dataIndex: 'content', ellipsis: true },
                            { title: 'Status', dataIndex: 'status', width: 100, render: (v: string) => <Tag color={v === 'published' ? 'green' : v === 'scheduled' ? 'blue' : 'default'}>{v}</Tag> },
                            { title: 'Date', key: 'd', width: 140, render: (_: any, r: NewsSocialPost) => <Text style={{ fontSize: 11 }}>{r.publishedAt ? dayjs(r.publishedAt).format('DD MMM HH:mm') : r.scheduledAt ? dayjs(r.scheduledAt).format('DD MMM HH:mm') : '—'}</Text> },
                            { title: '', key: 'a', width: 50, render: (_: any, r: NewsSocialPost) => <Popconfirm title="Delete?" onConfirm={() => newsService.deleteSocialPost(r.id).then(load)}><Button type="text" size="small" icon={<DeleteOutlined />} danger /></Popconfirm> },
                        ]} />
                    }
                </Card>
            </motion.div>

            <Modal title="Connect Social Account" open={accountModal} onOk={addAccount} onCancel={() => setAccountModal(false)} okText="Connect">
                <Form form={accountForm} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="platform" label="Platform" rules={[{ required: true }]}><Select options={[{ label: '𝕏 Twitter/X', value: 'twitter' }, { label: 'Facebook', value: 'facebook' }, { label: 'LinkedIn', value: 'linkedin' }, { label: 'Instagram', value: 'instagram' }, { label: 'TikTok', value: 'tiktok' }]} /></Form.Item>
                    <Form.Item name="accountName" label="Account Handle" rules={[{ required: true }]}><Input placeholder="@username" /></Form.Item>
                    <Form.Item name="displayName" label="Display Name"><Input placeholder="Company Name" /></Form.Item>
                    <Form.Item name="profileUrl" label="Profile URL"><Input placeholder="https://twitter.com/..." /></Form.Item>
                </Form>
            </Modal>

            <Modal title="Create Post" open={postModal} onOk={addPost} onCancel={() => setPostModal(false)} okText="Create">
                <Form form={postForm} layout="vertical" style={{ marginTop: 12 }}>
                    <Form.Item name="platform" label="Platform" rules={[{ required: true }]}><Select options={accounts.map(a => ({ label: `${a.platform} — ${a.accountName}`, value: a.platform }))} /></Form.Item>
                    <Form.Item name="content" label="Content" rules={[{ required: true }]}><Input.TextArea rows={4} placeholder="Write your post..." showCount maxLength={280} /></Form.Item>
                    <Form.Item name="hashtags" label="Hashtags"><Select mode="tags" placeholder="Add hashtags" /></Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

