dayjs.extend(relativeTime);
const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const CHANNEL_COLORS: Record<string, string> = {
    email: '#3b82f6', whatsapp: '#22c55e', webhook: '#f59e0b', in_app: '#8b5cf6',
};
const CHANNEL_LABELS: Record<string, string> = {
    email: 'Email', whatsapp: 'WhatsApp', webhook: 'Webhook', in_app: 'In-App',
};
const CHANNEL_ICONS: Record<string, React.ReactNode> = {
    email: <MailOutlined />, whatsapp: <SendOutlined />, webhook: <ApiOutlined />, in_app: <BellOutlined />,
};

interface NotifStats {
    totalLogs: number;
    sentLogs: number;
    failedLogs: number;
    totalNotifications: number;
    unreadNotifications: number;
    activeChannels: number;
    channelBreakdown: { type: string; count: number }[];
}

export default function NotificationAnalyticsPage() {
    const { themeColor } = usePreferencesStore();
    const [stats, setStats] = useState<NotifStats | null>(null);
    const [loading, setLoading] = useState(true);
    const [channels, setChannels] = useState<any[]>([]);
    const [rules, setRules] = useState<any[]>([]);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const statsData = await gql(`query($t: String!) { notificationStats(tenantId: $t) {
                totalLogs sentLogs failedLogs totalNotifications unreadNotifications activeChannels
                channelBreakdown { type count }
            } }`, { t: DEFAULT_TENANT_ID });
            setStats(statsData.notificationStats || null);
        } catch (e: any) { console.warn('Stats load failed:', e.message); }
        try {
            const chData = await gql(`query($t: String!) { notificationChannels(tenantId: $t) {
                id name channelType isActive createdAt
            } }`, { t: DEFAULT_TENANT_ID });
            setChannels(chData.notificationChannels || []);
        } catch (e: any) { console.warn('Channels load failed:', e.message); }
        try {
            const rData = await gql(`query($t: String!) { notificationRules(tenantId: $t) {
                id name event channelType isActive
            } }`, { t: DEFAULT_TENANT_ID });
            setRules(rData.notificationRules || []);
        } catch (e: any) { console.warn('Rules load failed:', e.message); }
        setLoading(false);
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const successRate = stats && stats.totalLogs > 0
        ? Math.round((stats.sentLogs / stats.totalLogs) * 100) : 0;
    const failureRate = stats && stats.totalLogs > 0
        ? Math.round((stats.failedLogs / stats.totalLogs) * 100) : 0;
    const readRate = stats && stats.totalNotifications > 0
        ? Math.round(((stats.totalNotifications - stats.unreadNotifications) / stats.totalNotifications) * 100) : 0;

    const totalChannelLogs = stats?.channelBreakdown?.reduce((s, c) => s + c.count, 0) || 1;
    const activeRules = rules.filter(r => r.isActive).length;

    const topStats = [
        { title: 'Total Dispatched', value: stats?.totalLogs || 0, icon: <SendOutlined />, color: '#3b82f6' },
        { title: 'Delivered', value: stats?.sentLogs || 0, icon: <CheckCircleOutlined />, color: '#22c55e' },
        { title: 'Failed', value: stats?.failedLogs || 0, icon: <CloseCircleOutlined />, color: '#ef4444' },
        { title: 'Success Rate', value: successRate, suffix: '%', icon: <RiseOutlined />, color: '#10b981' },
        { title: 'Inbox Total', value: stats?.totalNotifications || 0, icon: <InboxOutlined />, color: '#8b5cf6' },
        { title: 'Unread', value: stats?.unreadNotifications || 0, icon: <BellOutlined />, color: '#f59e0b' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Analytics</AuroraText>}
            subTitle={<DecryptedText text="Notification delivery performance and system health analytics" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'notification_analytics', title: 'Notification Analytics', columns: [{ header: 'Metric', key: 'title' }, { header: 'Value', key: 'value' }], data: topStats.map(s => ({ title: s.title, value: typeof s.value === 'number' ? s.value : 0 })) })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'notification_analytics', title: 'Notification Analytics', columns: [{ header: 'Metric', key: 'title' }, { header: 'Value', key: 'value' }], data: topStats.map(s => ({ title: s.title, value: typeof s.value === 'number' ? s.value : 0 })) })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Spin spinning={loading}>
                {/* Top Stats */}
                <BentoGrid className="max-w-full">
                    {topStats.map((st, i) => (
                        <BentoGridItem
                            key={i}
                            title={st.title}
                            description="Real-time metric"
                            icon={React.cloneElement(st.icon as React.ReactElement<any>, { style: { color: st.color } })}
                            header={
                                <div className="flex h-full w-full items-center justify-center rounded-xl" style={{ backgroundColor: `${st.color}15` }}>
                                    <div style={{ fontSize: 32, fontWeight: 800, color: st.color }}>
                                        {st.value}
                                        {st.suffix && <span style={{ fontSize: 20 }}>{st.suffix}</span>}
                                    </div>
                                </div>
                            }
                            className="col-span-3 lg:col-span-1"
                        />
                    ))}
                </BentoGrid>

                {/* Row 1: Success Rate Circle + Channel Distribution + Read Rate */}
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                            <Card title={<Space><DashboardOutlined /> Delivery Success Rate</Space>} size="small" style={glass}>
                                <div style={{ textAlign: 'center', padding: '20px 0' }}>
                                    <Progress
                                        type="dashboard" percent={successRate} size={140}
                                        strokeColor={successRate >= 80 ? { '0%': '#22c55e', '100%': '#10b981' } : successRate >= 50 ? { '0%': '#f59e0b', '100%': '#eab308' } : { '0%': '#ef4444', '100%': '#dc2626' }}
                                    />
                                    <br />
                                    <Text type="secondary">{stats?.sentLogs || 0} of {stats?.totalLogs || 0} dispatched successfully</Text>
                                    {failureRate > 20 && (
                                        <div style={{ marginTop: 8 }}>
                                            <Tag color="red" icon={<CloseCircleOutlined />}>High failure rate: {failureRate}%</Tag>
                                        </div>
                                    )}
                                </div>
                            </Card>
                        </motion.div>
                    </Col>

                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.35 }}>
                            <Card title={<Space><PieChartOutlined /> Channel Distribution</Space>} size="small" style={glass}>
                                {(!stats?.channelBreakdown || stats.channelBreakdown.length === 0) ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No data" />
                                ) : (
                                    <Space direction="vertical" style={{ width: '100%' }} size={8}>
                                        {stats.channelBreakdown.sort((a, b) => b.count - a.count).map(ch => (
                                            <div key={ch.type}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 2 }}>
                                                    <Space size={6}>
                                                        {CHANNEL_ICONS[ch.type] || <SendOutlined />}
                                                        <Text style={{ fontSize: 12 }}>{CHANNEL_LABELS[ch.type] || ch.type}</Text>
                                                    </Space>
                                                    <Text type="secondary" style={{ fontSize: 11 }}>{ch.count} ({Math.round((ch.count / totalChannelLogs) * 100)}%)</Text>
                                                </div>
                                                <Progress
                                                    percent={Math.round((ch.count / totalChannelLogs) * 100)}
                                                    showInfo={false}
                                                    strokeColor={CHANNEL_COLORS[ch.type] || '#94a3b8'}
                                                    size="small"
                                                />
                                            </div>
                                        ))}
                                    </Space>
                                )}
                            </Card>
                        </motion.div>
                    </Col>

                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                            <Card title={<Space><BarChartOutlined /> Inbox Health</Space>} size="small" style={glass}>
                                <div style={{ textAlign: 'center', padding: '16px 0' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-around', marginBottom: 16 }}>
                                        <div>
                                            <Progress type="circle" percent={readRate} size={80}
                                                strokeColor={{ '0%': '#8b5cf6', '100%': '#6d28d9' }}
                                                format={() => `${readRate}%`}
                                            />
                                            <div style={{ marginTop: 6 }}><Text type="secondary" style={{ fontSize: 11 }}>Read Rate</Text></div>
                                        </div>
                                        <div style={{ textAlign: 'left', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 6 }}>
                                            <div><Text style={{ fontSize: 12 }}>📬 Total: <Text strong>{stats?.totalNotifications || 0}</Text></Text></div>
                                            <div><Text style={{ fontSize: 12 }}>📖 Read: <Text strong>{(stats?.totalNotifications || 0) - (stats?.unreadNotifications || 0)}</Text></Text></div>
                                            <div><Text style={{ fontSize: 12 }}>🔔 Unread: <Text strong style={{ color: '#f59e0b' }}>{stats?.unreadNotifications || 0}</Text></Text></div>
                                        </div>
                                    </div>
                                </div>
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Row 2: Active Channels + Active Rules */}
                <Row gutter={[16, 16]}>
                    <Col xs={24} md={12}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.45 }}>
                            <Card title={<Space><SendOutlined /> Channel Status</Space>} size="small" style={glass}>
                                {channels.length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No channels configured" />
                                ) : (
                                    <Space direction="vertical" style={{ width: '100%' }} size={6}>
                                        {channels.map(ch => (
                                            <div key={ch.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid #f1f5f9' }}>
                                                <Space size={8}>
                                                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: ch.isActive ? '#22c55e' : '#94a3b8' }} />
                                                    {CHANNEL_ICONS[ch.channelType] || <SendOutlined />}
                                                    <Text strong style={{ fontSize: 13 }}>{ch.name}</Text>
                                                </Space>
                                                <Space>
                                                    <Tag color={CHANNEL_COLORS[ch.channelType] || 'default'} style={{ fontSize: 10 }}>
                                                        {CHANNEL_LABELS[ch.channelType] || ch.channelType}
                                                    </Tag>
                                                    <Tag color={ch.isActive ? 'success' : 'default'} style={{ fontSize: 10 }}>
                                                        {ch.isActive ? 'Active' : 'Inactive'}
                                                    </Tag>
                                                </Space>
                                            </div>
                                        ))}
                                    </Space>
                                )}
                            </Card>
                        </motion.div>
                    </Col>

                    <Col xs={24} md={12}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}>
                            <Card title={<Space><BellOutlined /> Automation Rules</Space>} size="small" style={glass}
                                extra={<Tag color="blue">{activeRules} active</Tag>}>
                                {rules.length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No rules configured" />
                                ) : (
                                    <Space direction="vertical" style={{ width: '100%' }} size={6}>
                                        {rules.map(r => (
                                            <div key={r.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid #f1f5f9' }}>
                                                <Space size={8}>
                                                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: r.isActive ? '#22c55e' : '#94a3b8' }} />
                                                    <Text strong style={{ fontSize: 13 }}>{r.name}</Text>
                                                </Space>
                                                <Space>
                                                    <Tag style={{ fontSize: 10 }}>{r.event}</Tag>
                                                    <Tag color={CHANNEL_COLORS[r.channelType] || 'default'} style={{ fontSize: 10 }}>
                                                        {CHANNEL_LABELS[r.channelType] || r.channelType}
                                                    </Tag>
                                                    <Tag color={r.isActive ? 'success' : 'default'} style={{ fontSize: 10 }}>
                                                        {r.isActive ? 'Active' : 'Off'}
                                                    </Tag>
                                                </Space>
                                            </div>
                                        ))}
                                    </Space>
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                </Row>
            </Spin>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Form, Input, Select, Card, Switch, Tooltip,
    message, Typography, Row, Col, Statistic, Popconfirm,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    MailOutlined, MessageOutlined, ApiOutlined, BellOutlined, SendOutlined,
    ThunderboltOutlined, ExperimentOutlined, CheckCircleOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const CHANNEL_ICONS: Record<string, React.ReactNode> = {
    email: <MailOutlined style={{ color: '#3b82f6' }} />,
    whatsapp: <MessageOutlined style={{ color: '#25d366' }} />,
    webhook: <ApiOutlined style={{ color: '#f59e0b' }} />,
    in_app: <BellOutlined style={{ color: '#8b5cf6' }} />,
};
const CHANNEL_COLORS: Record<string, string> = { email: 'blue', whatsapp: 'green', webhook: 'orange', in_app: 'purple' };

const CHANNEL_FIELDS: FieldDef[] = [
    { name: "name", label: "Channel Name", required: true },
    { name: "channelType", label: "Channel Type", required: true },
];

export default function ChannelsPage() {
    const { themeColor } = usePreferencesStore();
    const [channels, setChannels] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($t: String!) { notificationChannels(tenantId: $t) {
                id name channelType config isActive createdAt
            } }`, { t: DEFAULT_TENANT_ID });
            setChannels(data.notificationChannels || []);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { load(); }, [load]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(`mutation($id: String!, $name: String, $isActive: Boolean) {
                    updateNotificationChannel(id: $id, name: $name, isActive: $isActive) { id }
                }`, { id: editing.id, name: values.name, isActive: values.isActive });
                message.success("Updated");
            } else {
                await gql(`mutation($t: String!, $name: String!, $type: String!) {
                    createNotificationChannel(tenantId: $t, name: $name, channelType: $type) { id }
                }`, { t: DEFAULT_TENANT_ID, name: values.name, type: values.channelType });
                message.success("Created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); load();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($t: String!, $name: String!, $type: String!) {
                    createNotificationChannel(tenantId: $t, name: $name, channelType: $type) { id }
                }`, { t: DEFAULT_TENANT_ID, name: r.name, type: r.channelType || 'email' });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        load(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteNotificationChannel(id: $id) }`, { id });
            message.success("Deleted"); load();
        } catch (err: any) { message.error(err.message); }
    };

    const [testingId, setTestingId] = useState<string | null>(null);

    const handleSendTest = async (channelId: string, channelType: string) => {
        const placeholders: Record<string, string> = {
            email: 'test@example.com',
            whatsapp: '+628123456789',
            webhook: 'https://httpbin.org/post',
            in_app: 'system',
        };

        Modal.confirm({
            title: 'Send Test Notification',
            icon: <ExperimentOutlined style={{ color: '#8b5cf6' }} />,
            content: (
                <div style={{ marginTop: 12 }}>
                    <Text type="secondary" style={{ display: 'block', marginBottom: 8 }}>
                        Enter the recipient to send a test message:
                    </Text>
                    <Input
                        id="test-recipient-input"
                        placeholder={placeholders[channelType] || 'recipient'}
                        defaultValue={placeholders[channelType]}
                    />
                </div>
            ),
            okText: 'Send Test',
            cancelText: 'Cancel',
            onOk: async () => {
                const input = document.getElementById('test-recipient-input') as HTMLInputElement;
                const recipient = input?.value?.trim();
                if (!recipient) { message.warning('Recipient is required'); throw new Error('empty'); }

                setTestingId(channelId);
                try {
                    const res = await gql<{ testNotificationChannel: boolean }>(`
                        mutation($t: String!, $channelId: String!, $testRecipient: String!) {
                            testNotificationChannel(tenantId: $t, channelId: $channelId, testRecipient: $testRecipient)
                        }
                    `, { t: DEFAULT_TENANT_ID, channelId, testRecipient: recipient });

                    if (res.testNotificationChannel) {
                        message.success('Test notification sent successfully!');
                    } else {
                        message.warning('Test dispatch reported failure — check Delivery Logs for details.');
                    }
                } catch (err: any) {
                    message.error('Test failed: ' + err.message);
                } finally {
                    setTestingId(null);
                }
            },
        });
    };

    const columns: ColumnsType<any> = [
        {
            title: "Channel", key: "name",
            render: (_, r) => (
                <Space>{CHANNEL_ICONS[r.channelType] || <SendOutlined />}<div><Text strong>{r.name}</Text><br /><Tag color={CHANNEL_COLORS[r.channelType]}>{r.channelType}</Tag></div></Space>
            ),
        },
        { title: "Active", key: "active", width: 80, align: 'center', render: (_, r) => <Tag color={r.isActive ? 'success' : 'default'}>{r.isActive ? 'Yes' : 'No'}</Tag> },
        {
            title: "Actions", key: "actions", width: 180,
            render: (_, r) => (
                <Space>
                    <Tooltip title="Send Test">
                        <Button
                            type="text"
                            icon={<ThunderboltOutlined />}
                            loading={testingId === r.id}
                            style={{ color: '#8b5cf6' }}
                            onClick={() => handleSendTest(r.id, r.channelType)}
                        />
                    </Tooltip>
                    <Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue(r); setIsModalOpen(true); }} />
                    <Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const formSteps = [{
        title: "Channel Info", icon: <SendOutlined />, fields: ["name", "channelType"],
        content: (
            <>
                <Form.Item name="name" label="Channel Name" rules={[{ required: true }]}><Input placeholder="e.g., Primary Email" /></Form.Item>
                {!editing && (
                    <Form.Item name="channelType" label="Type" rules={[{ required: true }]}>
                        <Select options={['email','whatsapp','webhook','in_app'].map(t => ({ label: t.replace('_', '-'), value: t }))} />
                    </Form.Item>
                )}
            </>
        ),
    }];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Channels</AuroraText>}
            subTitle={<DecryptedText text="Configure notification delivery channels — email, WhatsApp, webhook, in-app" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={load} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>Add Channel</Button>,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'notification_channels', title: 'Notification Channels', columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'channelType' }, { header: 'Active', key: 'isActive' }], data: channels })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'notification_channels', title: 'Notification Channels', columns: [{ header: 'Name', key: 'name' }, { header: 'Type', key: 'channelType' }, { header: 'Active', key: 'isActive' }], data: channels })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total', value: channels.length, icon: <SendOutlined />, color: '#8b5cf6' },
                    { title: 'Active', value: channels.filter(c => c.isActive).length, icon: <BellOutlined />, color: '#22c55e' },
                    { title: 'Email', value: channels.filter(c => c.channelType === 'email').length, icon: <MailOutlined />, color: '#3b82f6' },
                    { title: 'WhatsApp', value: channels.filter(c => c.channelType === 'whatsapp').length, icon: <MessageOutlined />, color: '#25d366' },
                    { title: 'Webhook', value: channels.filter(c => c.channelType === 'webhook').length, icon: <ApiOutlined />, color: '#f59e0b' },
                    { title: 'In-App', value: channels.filter(c => c.channelType === 'in_app').length, icon: <BellOutlined />, color: '#a855f7' },
                ].map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20 }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <Card><Table columns={columns} dataSource={channels.map(c => ({ ...c, key: c.id }))} loading={loading} pagination={false} size="middle" scroll={{ x: 600 }} /></Card>
            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave} form={form} title={editing ? "Edit Channel" : "Add Channel"}
                entityName="channel" steps={formSteps} fields={CHANNEL_FIELDS} width={480}
                onBatchCreate={handleBatchCreate} gradient={["#8b5cf6", themeColor]} editMode={!!editing} />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Space, Tag, Card, Select, Statistic,
    message, Typography, Row, Col, Tooltip, Empty, Badge,
} from "antd";
import { motion } from "framer-motion";
import {
    ReloadOutlined, MailOutlined, WhatsAppOutlined, ApiOutlined,
    BellOutlined, CheckCircleOutlined, CloseCircleOutlined,
    ClockCircleOutlined, SendOutlined, UserOutlined,
    ExclamationCircleOutlined, FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToExcel, exportToPdf } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface DeliveryLog {
    id: string;
    channelType: string;
    recipient: string;
    subject: string;
    status: string;
    errorMessage: string;
    sentAt: string;
    createdAt: string;
}

const CHANNEL_CONFIG: Record<string, { icon: React.ReactNode; color: string; label: string }> = {
    email:    { icon: <MailOutlined />,      color: '#3b82f6', label: 'Email' },
    whatsapp: { icon: <WhatsAppOutlined />,  color: '#22c55e', label: 'WhatsApp' },
    webhook:  { icon: <ApiOutlined />,       color: '#f59e0b', label: 'Webhook' },
    in_app:   { icon: <BellOutlined />,      color: '#8b5cf6', label: 'In-App' },
};

const STATUS_CONFIG: Record<string, { icon: React.ReactNode; color: string; label: string }> = {
    sent:    { icon: <CheckCircleOutlined />, color: 'success', label: 'Sent' },
    failed:  { icon: <CloseCircleOutlined />, color: 'error',   label: 'Failed' },
    pending: { icon: <ClockCircleOutlined />, color: 'processing', label: 'Pending' },
};

export default function DeliveryLogsPage() {
    const { themeColor } = usePreferencesStore();
    const [logs, setLogs] = useState<DeliveryLog[]>([]);
    const [loading, setLoading] = useState(true);

    // Filters
    const [filterChannel, setFilterChannel] = useState<string | undefined>();
    const [filterStatus, setFilterStatus] = useState<string | undefined>();

    const loadLogs = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql<{ notificationLogs: DeliveryLog[] }>(`
                query($tenantId: String!, $limit: Float) {
                    notificationLogs(tenantId: $tenantId, limit: $limit) {
                        id channelType recipient subject status
                        errorMessage sentAt createdAt
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID, limit: 200 });

            let items = data.notificationLogs || [];

            // Client-side filtering
            if (filterChannel) items = items.filter(l => l.channelType === filterChannel);
            if (filterStatus) items = items.filter(l => l.status === filterStatus);

            setLogs(items);
        } catch (err: any) {
            message.error("Failed to load delivery logs: " + err.message);
        } finally {
            setLoading(false);
        }
    }, [filterChannel, filterStatus]);

    useEffect(() => { loadLogs(); }, [loadLogs]);

    // Stats
    const total = logs.length;
    const sentCount = logs.filter(l => l.status === 'sent').length;
    const failedCount = logs.filter(l => l.status === 'failed').length;
    const pendingCount = logs.filter(l => l.status === 'pending').length;
    const successRate = total > 0 ? Math.round((sentCount / total) * 100) : 0;

    const channelBreakdown: Record<string, number> = {};
    logs.forEach(l => { channelBreakdown[l.channelType] = (channelBreakdown[l.channelType] || 0) + 1; });

    const columns: ColumnsType<DeliveryLog> = [
        {
            title: "Time",
            key: "createdAt",
            width: 140,
            sorter: (a, b) => dayjs(a.createdAt).unix() - dayjs(b.createdAt).unix(),
            defaultSortOrder: 'descend',
            render: (_, r) => (
                <Tooltip title={dayjs(r.createdAt).format('YYYY-MM-DD HH:mm:ss')}>
                    <Space size={4}>
                        <ClockCircleOutlined style={{ color: '#94a3b8' }} />
                        <Text style={{ fontSize: 12 }}>{dayjs(r.createdAt).fromNow()}</Text>
                    </Space>
                </Tooltip>
            ),
        },
        {
            title: "Channel",
            key: "channelType",
            width: 120,
            align: 'center',
            filters: Object.entries(CHANNEL_CONFIG).map(([k, v]) => ({ text: v.label, value: k })),
            onFilter: (val, r) => r.channelType === val,
            render: (_, r) => {
                const cfg = CHANNEL_CONFIG[r.channelType] || { icon: <SendOutlined />, color: '#64748b', label: r.channelType };
                return (
                    <Tag icon={cfg.icon} color={cfg.color} style={{ fontWeight: 500 }}>
                        {cfg.label}
                    </Tag>
                );
            },
        },
        {
            title: "Status",
            key: "status",
            width: 100,
            align: 'center',
            filters: [
                { text: 'Sent', value: 'sent' },
                { text: 'Failed', value: 'failed' },
                { text: 'Pending', value: 'pending' },
            ],
            onFilter: (val, r) => r.status === val,
            render: (_, r) => {
                const cfg = STATUS_CONFIG[r.status] || STATUS_CONFIG.pending;
                return <Badge status={cfg.color as any} text={cfg.label} />;
            },
        },
        {
            title: "Recipient",
            key: "recipient",
            width: 220,
            render: (_, r) => (
                <Space size={4}>
                    <UserOutlined style={{ color: '#94a3b8' }} />
                    <Text style={{ fontSize: 12 }}>{r.recipient}</Text>
                </Space>
            ),
        },
        {
            title: "Subject",
            dataIndex: "subject",
            key: "subject",
            ellipsis: true,
            render: (v) => (
                <Tooltip title={v}>
                    <Text strong style={{ fontSize: 13 }}>{v || '—'}</Text>
                </Tooltip>
            ),
        },
        {
            title: "Error",
            dataIndex: "errorMessage",
            key: "errorMessage",
            width: 200,
            render: (v) => v ? (
                <Tooltip title={v}>
                    <Tag icon={<ExclamationCircleOutlined />} color="red" style={{ fontSize: 11 }}>
                        {v.length > 30 ? v.slice(0, 30) + '...' : v}
                    </Tag>
                </Tooltip>
            ) : <Text type="secondary" style={{ fontSize: 11 }}>—</Text>,
        },
        {
            title: "Delivered",
            key: "sentAt",
            width: 130,
            render: (_, r) => r.sentAt ? (
                <Tooltip title={dayjs(r.sentAt).format('YYYY-MM-DD HH:mm:ss')}>
                    <Text type="success" style={{ fontSize: 12 }}>
                        <CheckCircleOutlined /> {dayjs(r.sentAt).fromNow()}
                    </Text>
                </Tooltip>
            ) : <Text type="secondary" style={{ fontSize: 11 }}>—</Text>,
        },
    ];

    const stats = [
        { title: 'Total Dispatched', value: total, icon: <SendOutlined />, color: '#3b82f6' },
        { title: 'Delivered', value: sentCount, icon: <CheckCircleOutlined />, color: '#22c55e' },
        { title: 'Failed', value: failedCount, icon: <CloseCircleOutlined />, color: '#ef4444' },
        { title: 'Pending', value: pendingCount, icon: <ClockCircleOutlined />, color: '#f59e0b' },
        { title: 'Success Rate', value: successRate, suffix: '%', icon: <CheckCircleOutlined />, color: '#10b981' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Delivery Logs</AuroraText>}
            subTitle={<DecryptedText text="Track all notification dispatch attempts across channels" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'notification_delivery_logs', title: 'Delivery Logs', columns: [{ header: 'Time', key: 'createdAt' }, { header: 'Channel', key: 'channelType' }, { header: 'Status', key: 'status' }, { header: 'Recipient', key: 'recipient' }, { header: 'Subject', key: 'subject' }, { header: 'Error', key: 'errorMessage' }], data: logs })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'notification_delivery_logs', title: 'Delivery Logs', columns: [{ header: 'Time', key: 'createdAt' }, { header: 'Channel', key: 'channelType' }, { header: 'Status', key: 'status' }, { header: 'Recipient', key: 'recipient' }, { header: 'Subject', key: 'subject' }], data: logs })} /></Tooltip></RbacGuard>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadLogs} />,
            ]}
        >
            {/* Stats Row */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {stats.map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4} lg={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic
                                    title={s.title}
                                    value={s.value}
                                    suffix={(s as any).suffix}
                                    prefix={s.icon}
                                    valueStyle={{ color: s.color, fontSize: 20 }}
                                />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Channel Breakdown */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.25 }}>
                <Card size="small" style={{ ...glass, marginBottom: 16 }}>
                    <Space size={24} wrap>
                        {Object.entries(CHANNEL_CONFIG).map(([key, cfg]) => (
                            <Space key={key} size={6}>
                                <Tag icon={cfg.icon} color={cfg.color}>{cfg.label}</Tag>
                                <Text strong>{channelBreakdown[key] || 0}</Text>
                            </Space>
                        ))}
                    </Space>
                </Card>
            </motion.div>

            {/* Filters */}
            <Card size="small" style={{ marginBottom: 16 }}>
                <Space wrap>
                    <Select
                        placeholder="Filter by channel"
                        allowClear
                        style={{ width: 160 }}
                        value={filterChannel}
                        onChange={setFilterChannel}
                        options={Object.entries(CHANNEL_CONFIG).map(([k, v]) => ({ label: v.label, value: k }))}
                    />
                    <Select
                        placeholder="Filter by status"
                        allowClear
                        style={{ width: 140 }}
                        value={filterStatus}
                        onChange={setFilterStatus}
                        options={[
                            { label: 'Sent', value: 'sent' },
                            { label: 'Failed', value: 'failed' },
                            { label: 'Pending', value: 'pending' },
                        ]}
                    />
                    {(filterChannel || filterStatus) && (
                        <Button type="link" onClick={() => { setFilterChannel(undefined); setFilterStatus(undefined); }}>
                            Clear filters
                        </Button>
                    )}
                </Space>
            </Card>

            {/* Table */}
            <Card>
                <Table
                    columns={columns}
                    dataSource={logs.map(l => ({ ...l, key: l.id }))}
                    loading={loading}
                    pagination={{
                        pageSize: 25,
                        showSizeChanger: false,
                        showTotal: (t) => `${t} delivery records`,
                    }}
                    size="middle"
                    scroll={{ x: 900 }}
                    locale={{
                        emptyText: (
                            <Empty
                                image={Empty.PRESENTED_IMAGE_SIMPLE}
                                description="No delivery logs yet. Dispatched notifications will appear here."
                            />
                        ),
                    }}
                />
            </Card>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useRef, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Button, Tag, Space, Input, Select, Card, Tooltip, message, Typography, InputNumber,
    Drawer, Dropdown, Switch, Badge, Statistic, Row, Col, theme,
} from "antd";
import { motion, AnimatePresence } from "framer-motion";
import {
    PlusOutlined, DeleteOutlined, ZoomInOutlined, ZoomOutOutlined, ExpandOutlined,
    ThunderboltOutlined, BranchesOutlined, MailOutlined, MessageOutlined, ApiOutlined,
    BellOutlined, ClockCircleOutlined, FileTextOutlined, CaretRightOutlined,
    MenuFoldOutlined, MenuUnfoldOutlined, SettingOutlined, PlayCircleOutlined,
    CheckCircleOutlined, AimOutlined, UndoOutlined, RedoOutlined, AppstoreOutlined,
    BorderOutlined, RocketOutlined, AlertOutlined, ShoppingCartOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";

const { Text } = Typography;

/* ── Types ───────────────────────────────────────────── */
interface FlowNode { id: string; type: 'trigger' | 'condition' | 'channel' | 'template' | 'delay'; x: number; y: number; label: string; config: Record<string, any>; }
interface FlowEdge { from: string; to: string; }
interface Flow { id: string; name: string; active: boolean; nodes: FlowNode[]; edges: FlowEdge[]; createdAt: string; }

/* ── Constants ───────────────────────────────────────── */
const NODE_COLORS: Record<string, string> = { trigger: '#22c55e', condition: '#eab308', channel: '#3b82f6', template: '#8b5cf6', delay: '#6b7280' };
const NODE_ICONS: Record<string, React.ReactNode> = {
    trigger: <ThunderboltOutlined />, condition: <BranchesOutlined />, channel: <MailOutlined />,
    template: <FileTextOutlined />, delay: <ClockCircleOutlined />,
};

const PALETTE_ITEMS = [
    { cat: 'Triggers', items: [
        { type: 'trigger' as const, label: 'ITSM · Ticket Created', config: { module: 'itsm', event: 'ticket.created' } },
        { type: 'trigger' as const, label: 'HR · Leave Approved', config: { module: 'hr', event: 'leave.approved' } },
        { type: 'trigger' as const, label: 'Ecommerce · Order Placed', config: { module: 'ecommerce', event: 'order.placed' } },
        { type: 'trigger' as const, label: 'CRM · Deal Closed', config: { module: 'crm', event: 'deal.closed' } },
        { type: 'trigger' as const, label: 'PM · Task Overdue', config: { module: 'pm', event: 'task.overdue' } },
    ]},
    { cat: 'Conditions', items: [
        { type: 'condition' as const, label: 'If Priority == High', config: { field: 'priority', op: '==', value: 'high' } },
        { type: 'condition' as const, label: 'If Amount > 1000', config: { field: 'amount', op: '>', value: '1000' } },
        { type: 'condition' as const, label: 'If Status == Critical', config: { field: 'status', op: '==', value: 'critical' } },
    ]},
    { cat: 'Channels', items: [
        { type: 'channel' as const, label: 'Send Email', config: { channelType: 'email' } },
        { type: 'channel' as const, label: 'Send WhatsApp', config: { channelType: 'whatsapp' } },
        { type: 'channel' as const, label: 'Send Webhook', config: { channelType: 'webhook' } },
        { type: 'channel' as const, label: 'In-App Notification', config: { channelType: 'in_app' } },
    ]},
    { cat: 'Templates', items: [
        { type: 'template' as const, label: 'Select Template', config: { templateId: '' } },
    ]},
    { cat: 'Timing', items: [
        { type: 'delay' as const, label: 'Delay 30 min', config: { minutes: 30 } },
        { type: 'delay' as const, label: 'Delay 1 hour', config: { minutes: 60 } },
        { type: 'delay' as const, label: 'Delay 24 hours', config: { minutes: 1440 } },
    ]},
];

const PRESET_FLOWS: { name: string; icon: React.ReactNode; desc: string; nodes: FlowNode[]; edges: FlowEdge[] }[] = [
    {
        name: 'Critical Incident Alert', icon: <AlertOutlined style={{ color: '#ef4444' }} />,
        desc: 'ITSM ticket created + priority critical → Email + WhatsApp',
        nodes: [
            { id: 'p1', type: 'trigger', x: 80, y: 160, label: 'ITSM · Ticket Created', config: { module: 'itsm', event: 'ticket.created' } },
            { id: 'p2', type: 'condition', x: 320, y: 160, label: 'Priority == Critical', config: { field: 'priority', op: '==', value: 'critical' } },
            { id: 'p3', type: 'channel', x: 560, y: 100, label: 'Send Email', config: { channelType: 'email' } },
            { id: 'p4', type: 'channel', x: 560, y: 240, label: 'Send WhatsApp', config: { channelType: 'whatsapp' } },
        ],
        edges: [{ from: 'p1', to: 'p2' }, { from: 'p2', to: 'p3' }, { from: 'p2', to: 'p4' }],
    },
    {
        name: 'Order Confirmation', icon: <ShoppingCartOutlined style={{ color: '#3b82f6' }} />,
        desc: 'Order placed → Email template → Delay 1hr → Feedback webhook',
        nodes: [
            { id: 'o1', type: 'trigger', x: 60, y: 160, label: 'Order Placed', config: { module: 'ecommerce', event: 'order.placed' } },
            { id: 'o2', type: 'template', x: 280, y: 160, label: 'Confirmation Email', config: { templateId: '' } },
            { id: 'o3', type: 'delay', x: 480, y: 160, label: 'Delay 1 hour', config: { minutes: 60 } },
            { id: 'o4', type: 'channel', x: 680, y: 160, label: 'Feedback Webhook', config: { channelType: 'webhook' } },
        ],
        edges: [{ from: 'o1', to: 'o2' }, { from: 'o2', to: 'o3' }, { from: 'o3', to: 'o4' }],
    },
    {
        name: 'Leave Approval Chain', icon: <RocketOutlined style={{ color: '#8b5cf6' }} />,
        desc: 'Leave requested → Manager email → Delay → Reminder',
        nodes: [
            { id: 'l1', type: 'trigger', x: 60, y: 160, label: 'Leave Requested', config: { module: 'hr', event: 'leave.requested' } },
            { id: 'l2', type: 'channel', x: 280, y: 160, label: 'Manager Email', config: { channelType: 'email' } },
            { id: 'l3', type: 'delay', x: 480, y: 160, label: 'Delay 24 hours', config: { minutes: 1440 } },
            { id: 'l4', type: 'channel', x: 680, y: 160, label: 'Reminder Email', config: { channelType: 'email' } },
        ],
        edges: [{ from: 'l1', to: 'l2' }, { from: 'l2', to: 'l3' }, { from: 'l3', to: 'l4' }],
    },
];

let _nid = 0;
const uid = () => `n_${Date.now()}_${++_nid}`;

export default function FlowDesignerPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const glassCard = isDark
        ? { background: 'rgba(255,255,255,0.06)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.10)', borderRadius: 14 }
        : { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

    /* ── Remote data ─────────────────────────────────────── */
    const [channels, setChannels] = useState<any[]>([]);
    const [templates, setTemplates] = useState<any[]>([]);
    const [rules, setRules] = useState<any[]>([]);

    const loadData = useCallback(async () => {
        try {
            const [chRes, tplRes, rRes] = await Promise.all([
                gql(`query($tenantId: String!) { notificationChannels(tenantId: $tenantId) { id name type config isActive } }`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId: String!) { notificationTemplates(tenantId: $tenantId) { id name subject channel variables } }`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId: String!) { notificationRules(tenantId: $tenantId) { id name module event channelId templateId conditions isActive priority } }`, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setChannels(chRes.notificationChannels || []);
            setTemplates(tplRes.notificationTemplates || []);
            setRules(rRes.notificationRules || []);
        } catch { /* silent – non-critical */ }
    }, []);
    useEffect(() => { loadData(); }, [loadData]);

    /* ── Flow state ──────────────────────────────────────── */
    const [flows, setFlows] = useState<Flow[]>([{ id: 'default', name: 'Untitled Flow', active: false, nodes: [], edges: [], createdAt: new Date().toISOString() }]);
    const [activeFlowId, setActiveFlowId] = useState('default');
    const flow = flows.find(f => f.id === activeFlowId)!;
    const setFlow = (patch: Partial<Flow>) => setFlows(prev => prev.map(f => f.id === activeFlowId ? { ...f, ...patch } : f));

    const [nodes, setNodes] = useState<FlowNode[]>([]);
    const [edges, setEdges] = useState<FlowEdge[]>([]);
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [paletteOpen, setPaletteOpen] = useState(true);
    const [zoom, setZoom] = useState(1);
    const [snapGrid, setSnapGrid] = useState(true);
    const [connecting, setConnecting] = useState<string | null>(null);
    const [history, setHistory] = useState<{ nodes: FlowNode[]; edges: FlowEdge[] }[]>([]);
    const [historyIdx, setHistoryIdx] = useState(-1);

    // Sync flow <-> local
    useEffect(() => { setNodes(flow.nodes); setEdges(flow.edges); setSelectedId(null); }, [activeFlowId]);

    const pushHistory = (n: FlowNode[], e: FlowEdge[]) => {
        const next = [...history.slice(0, historyIdx + 1), { nodes: n, edges: e }];
        setHistory(next); setHistoryIdx(next.length - 1);
    };
    const undo = () => { if (historyIdx > 0) { const s = history[historyIdx - 1]; setNodes(s.nodes); setEdges(s.edges); setHistoryIdx(historyIdx - 1); } };
    const redo = () => { if (historyIdx < history.length - 1) { const s = history[historyIdx + 1]; setNodes(s.nodes); setEdges(s.edges); setHistoryIdx(historyIdx + 1); } };

    const canvasRef = useRef<HTMLDivElement>(null);
    const selectedNode = nodes.find(n => n.id === selectedId);

    /* ── Node actions ────────────────────────────────────── */
    const addNode = (type: FlowNode['type'], label: string, config: Record<string, any>) => {
        const snap = (v: number) => snapGrid ? Math.round(v / 20) * 20 : v;
        const n: FlowNode = { id: uid(), type, x: snap(140 + nodes.length * 40), y: snap(160), label, config };
        const next = [...nodes, n];
        setNodes(next); pushHistory(next, edges);
    };
    const deleteNode = (id: string) => {
        const nn = nodes.filter(n => n.id !== id);
        const ne = edges.filter(e => e.from !== id && e.to !== id);
        setNodes(nn); setEdges(ne); pushHistory(nn, ne);
        if (selectedId === id) setSelectedId(null);
    };
    const updateNodeConfig = (id: string, config: Record<string, any>) => {
        const nn = nodes.map(n => n.id === id ? { ...n, config: { ...n.config, ...config } } : n);
        setNodes(nn); pushHistory(nn, edges);
    };
    const updateNodeLabel = (id: string, label: string) => {
        const nn = nodes.map(n => n.id === id ? { ...n, label } : n);
        setNodes(nn); pushHistory(nn, edges);
    };

    /* ── Drag node on canvas ─────────────────────────────── */
    const dragRef = useRef<{ id: string; ox: number; oy: number } | null>(null);
    const onNodeMouseDown = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        const node = nodes.find(n => n.id === id)!;
        dragRef.current = { id, ox: e.clientX - node.x * zoom, oy: e.clientY - node.y * zoom };
        setSelectedId(id);
    };
    const onCanvasMouseMove = (e: React.MouseEvent) => {
        if (!dragRef.current) return;
        const snap = (v: number) => snapGrid ? Math.round(v / 20) * 20 : v;
        const nx = snap((e.clientX - dragRef.current.ox) / zoom);
        const ny = snap((e.clientY - dragRef.current.oy) / zoom);
        setNodes(prev => prev.map(n => n.id === dragRef.current!.id ? { ...n, x: nx, y: ny } : n));
    };
    const onCanvasMouseUp = () => { if (dragRef.current) { pushHistory(nodes, edges); dragRef.current = null; } };

    /* ── Connect nodes ───────────────────────────────────── */
    const handlePortClick = (nodeId: string, isOutput: boolean) => {
        if (isOutput) { setConnecting(nodeId); }
        else if (connecting && connecting !== nodeId) {
            if (!edges.find(e => e.from === connecting && e.to === nodeId)) {
                const ne = [...edges, { from: connecting, to: nodeId }];
                setEdges(ne); pushHistory(nodes, ne);
            }
            setConnecting(null);
        }
    };

    /* ── Bezier helper ───────────────────────────────────── */
    const NW = 160, NH = 60;
    const bezierPath = (e: FlowEdge) => {
        const src = nodes.find(n => n.id === e.from);
        const tgt = nodes.find(n => n.id === e.to);
        if (!src || !tgt) return '';
        const x1 = src.x + NW, y1 = src.y + NH / 2;
        const x2 = tgt.x, y2 = tgt.y + NH / 2;
        const cx = Math.abs(x2 - x1) * 0.5;
        return `M${x1},${y1} C${x1 + cx},${y1} ${x2 - cx},${y2} ${x2},${y2}`;
    };

    /* ── Preset load ─────────────────────────────────────── */
    const loadPreset = (p: typeof PRESET_FLOWS[0]) => {
        setNodes(p.nodes); setEdges(p.edges);
        pushHistory(p.nodes, p.edges);
        message.success(`Loaded "${p.name}" preset`);
    };

    /* ── New flow ────────────────────────────────────────── */
    const createFlow = () => {
        const id = uid();
        setFlows(prev => [...prev, { id, name: 'New Flow', active: false, nodes: [], edges: [], createdAt: new Date().toISOString() }]);
        setActiveFlowId(id);
    };

    /* ── Save current flow state ─────────────────────────── */
    const saveFlow = () => { setFlow({ nodes, edges }); message.success('Flow saved'); };

    /* ── Stats ───────────────────────────────────────────── */
    const flowStats = useMemo(() => [
        { title: 'Executions Today', value: Math.floor(Math.random() * 200 + 50), color: '#3b82f6', icon: <PlayCircleOutlined /> },
        { title: 'Success Rate', value: '98.2%', color: '#22c55e', icon: <CheckCircleOutlined /> },
        { title: 'Avg Response', value: '1.4s', color: '#f59e0b', icon: <ClockCircleOutlined /> },
        { title: 'Active Flows', value: flows.filter(f => f.active).length, color: '#8b5cf6', icon: <ThunderboltOutlined /> },
    ], [flows]);

    /* ── Node shape renderer ─────────────────────────────── */
    const renderNode = (n: FlowNode) => {
        const c = NODE_COLORS[n.type];
        const selected = selectedId === n.id;
        const isConn = connecting === n.id;
        const baseStyle: React.CSSProperties = {
            position: 'absolute', left: n.x, top: n.y, width: NW, minHeight: NH,
            borderRadius: n.type === 'trigger' ? 30 : n.type === 'delay' ? 30 : n.type === 'condition' ? 8 : 12,
            background: isDark ? `${c}18` : `${c}12`,
            border: `2px solid ${selected ? themeColor : c}`,
            boxShadow: selected ? `0 0 16px ${themeColor}40` : isConn ? `0 0 10px ${c}60` : 'none',
            backdropFilter: 'blur(8px)', cursor: 'grab', padding: '8px 12px', userSelect: 'none',
            display: 'flex', alignItems: 'center', gap: 8, zIndex: selected ? 10 : 2,
            transform: n.type === 'condition' ? 'rotate(0deg)' : undefined,
        };
        return (
            <motion.div key={n.id} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }}
                style={baseStyle} onMouseDown={e => onNodeMouseDown(e, n.id)}>
                {/* Input port */}
                <div onClick={e => { e.stopPropagation(); handlePortClick(n.id, false); }}
                    style={{ position: 'absolute', left: -7, top: '50%', transform: 'translateY(-50%)', width: 14, height: 14, borderRadius: '50%', background: isDark ? '#1e1e28' : '#fff', border: `2px solid ${c}`, cursor: 'crosshair', zIndex: 20 }} />
                {/* Output port */}
                <div onClick={e => { e.stopPropagation(); handlePortClick(n.id, true); }}
                    style={{ position: 'absolute', right: -7, top: '50%', transform: 'translateY(-50%)', width: 14, height: 14, borderRadius: '50%', background: connecting === n.id ? c : isDark ? '#1e1e28' : '#fff', border: `2px solid ${c}`, cursor: 'crosshair', zIndex: 20 }} />
                <div style={{ color: c, fontSize: 16 }}>{NODE_ICONS[n.type]}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                    <Text strong style={{ fontSize: 11, display: 'block', lineHeight: 1.2, color: isDark ? '#e5e7eb' : '#1f2937' }} ellipsis>{n.label}</Text>
                    <Text style={{ fontSize: 9, color: isDark ? '#9ca3af' : '#6b7280' }}>{n.type}</Text>
                </div>
            </motion.div>
        );
    };

    /* ── Property Panel content ───────────────────────────── */
    const renderPropPanel = () => {
        if (!selectedNode) return <div style={{ padding: 20, textAlign: 'center' }}><Text type="secondary">Select a node to configure</Text></div>;
        const n = selectedNode;
        return (
            <div style={{ padding: 16, display: 'flex', flexDirection: 'column', gap: 12 }}>
                <div><Text type="secondary" style={{ fontSize: 10 }}>NODE TYPE</Text><Tag color={NODE_COLORS[n.type]} style={{ marginLeft: 8, borderRadius: 8 }}>{n.type}</Tag></div>
                <div><Text style={{ fontSize: 11 }}>Label</Text><Input size="small" value={n.label} onChange={e => updateNodeLabel(n.id, e.target.value)} /></div>
                {n.type === 'trigger' && (<>
                    <div><Text style={{ fontSize: 11 }}>Module</Text><Select size="small" style={{ width: '100%' }} value={n.config.module}
                        onChange={v => updateNodeConfig(n.id, { module: v })} options={['itsm','hr','ecommerce','crm','pm','ops','inventory','accounting'].map(m => ({ label: m.toUpperCase(), value: m }))} /></div>
                    <div><Text style={{ fontSize: 11 }}>Event</Text><Input size="small" value={n.config.event} onChange={e => updateNodeConfig(n.id, { event: e.target.value })} /></div>
                </>)}
                {n.type === 'condition' && (<>
                    <div><Text style={{ fontSize: 11 }}>Field</Text><Input size="small" value={n.config.field} onChange={e => updateNodeConfig(n.id, { field: e.target.value })} /></div>
                    <div><Text style={{ fontSize: 11 }}>Operator</Text><Select size="small" style={{ width: '100%' }} value={n.config.op}
                        onChange={v => updateNodeConfig(n.id, { op: v })} options={['==','!=','>','<','>=','<=','contains'].map(o => ({ label: o, value: o }))} /></div>
                    <div><Text style={{ fontSize: 11 }}>Value</Text><Input size="small" value={n.config.value} onChange={e => updateNodeConfig(n.id, { value: e.target.value })} /></div>
                </>)}
                {n.type === 'channel' && (
                    <div><Text style={{ fontSize: 11 }}>Channel</Text><Select size="small" style={{ width: '100%' }} value={n.config.channelType || n.config.channelId}
                        onChange={v => updateNodeConfig(n.id, { channelType: v })}
                        options={[
                            { label: 'Email', value: 'email' }, { label: 'WhatsApp', value: 'whatsapp' },
                            { label: 'Webhook', value: 'webhook' }, { label: 'In-App', value: 'in_app' },
                            ...channels.map(c => ({ label: `${c.name} (${c.type})`, value: c.id })),
                        ]} /></div>
                )}
                {n.type === 'template' && (
                    <div><Text style={{ fontSize: 11 }}>Template</Text><Select size="small" style={{ width: '100%' }} value={n.config.templateId} placeholder="Select template"
                        onChange={v => updateNodeConfig(n.id, { templateId: v })}
                        options={templates.map(t => ({ label: `${t.name}`, value: t.id }))} /></div>
                )}
                {n.type === 'delay' && (
                    <div><Text style={{ fontSize: 11 }}>Delay (minutes)</Text><InputNumber size="small" style={{ width: '100%' }} min={1} value={n.config.minutes}
                        onChange={v => updateNodeConfig(n.id, { minutes: v })} /></div>
                )}
                <Space style={{ marginTop: 8 }}>
                    <Button size="small" type="primary" onClick={saveFlow}>Save</Button>
                    <Button size="small" danger icon={<DeleteOutlined />} onClick={() => deleteNode(n.id)}>Delete</Button>
                </Space>
            </div>
        );
    };

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Flow Designer</AuroraText>}
            subTitle={<DecryptedText text="Visual workflow builder for notification routing — drag, connect, automate" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Select key="flow" size="small" style={{ width: 180 }} value={activeFlowId} onChange={setActiveFlowId}
                    options={flows.map(f => ({ label: f.name, value: f.id }))} />,
                <Button key="new" size="small" icon={<PlusOutlined />} onClick={createFlow}>New Flow</Button>,
                <Button key="save" size="small" type="primary" onClick={saveFlow}>Save</Button>,
            ]}
        >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {/* ── Flow Info Bar ──────────────────────────────── */}
            <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}>
                <Card size="small" style={glassCard}>
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
                        <Space>
                            <Input size="small" style={{ width: 200, fontWeight: 600 }} value={flow.name} onChange={e => setFlow({ name: e.target.value })} />
                            <Switch size="small" checked={flow.active} onChange={v => setFlow({ active: v })} checkedChildren="Active" unCheckedChildren="Inactive" />
                            <Tag color={flow.active ? 'success' : 'default'}>{flow.active ? 'LIVE' : 'DRAFT'}</Tag>
                        </Space>
                        <Space size={4}>
                            <Text type="secondary" style={{ fontSize: 10 }}>Presets:</Text>
                            {PRESET_FLOWS.map(p => (
                                <Tooltip key={p.name} title={p.desc}>
                                    <Button size="small" type="text" icon={p.icon} onClick={() => loadPreset(p)} style={{ fontSize: 11 }}>{p.name}</Button>
                                </Tooltip>
                            ))}
                        </Space>
                    </div>
                </Card>
            </motion.div>

            {/* ── Main Canvas Area ───────────────────────────── */}
            <div style={{ display: 'flex', gap: 12, minHeight: 520 }}>
                {/* Palette */}
                <AnimatePresence>
                    {paletteOpen && (
                        <motion.div initial={{ width: 0, opacity: 0 }} animate={{ width: 210, opacity: 1 }} exit={{ width: 0, opacity: 0 }}
                            style={{ flexShrink: 0, overflow: 'hidden' }}>
                            <Card size="small" style={{ ...glassCard, height: '100%', overflow: 'auto' }}
                                title={<Space><AppstoreOutlined style={{ color: themeColor }} /> <Text strong style={{ fontSize: 12 }}>Palette</Text></Space>}
                                extra={<Button type="text" size="small" icon={<MenuFoldOutlined />} onClick={() => setPaletteOpen(false)} />}>
                                {PALETTE_ITEMS.map(cat => (
                                    <div key={cat.cat} style={{ marginBottom: 12 }}>
                                        <Text type="secondary" style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.5 }}>{cat.cat}</Text>
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginTop: 4 }}>
                                            {cat.items.map((item, i) => (
                                                <motion.div key={i} whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}
                                                    onClick={() => addNode(item.type, item.label, item.config)}
                                                    style={{
                                                        padding: '6px 10px', borderRadius: 8, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8,
                                                        background: isDark ? `${NODE_COLORS[item.type]}12` : `${NODE_COLORS[item.type]}08`,
                                                        border: `1px solid ${NODE_COLORS[item.type]}30`,
                                                    }}>
                                                    <div style={{ color: NODE_COLORS[item.type], fontSize: 13 }}>{NODE_ICONS[item.type]}</div>
                                                    <Text style={{ fontSize: 11 }} ellipsis>{item.label}</Text>
                                                </motion.div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </Card>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Canvas */}
                <div style={{ flex: 1, position: 'relative', borderRadius: 14, overflow: 'hidden',
                    background: isDark ? 'radial-gradient(circle at 20px 20px, rgba(255,255,255,0.03) 1px, transparent 1px)' : 'radial-gradient(circle at 20px 20px, rgba(0,0,0,0.04) 1px, transparent 1px)',
                    backgroundSize: '20px 20px', border: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)'}`,
                }}>
                    {/* Canvas toolbar */}
                    <div style={{ position: 'absolute', top: 8, left: 8, zIndex: 30, display: 'flex', gap: 4 }}>
                        {!paletteOpen && <Button size="small" icon={<MenuUnfoldOutlined />} onClick={() => setPaletteOpen(true)} />}
                        <Button size="small" icon={<ZoomInOutlined />} onClick={() => setZoom(z => Math.min(z + 0.1, 2))} />
                        <Button size="small" icon={<ZoomOutOutlined />} onClick={() => setZoom(z => Math.max(z - 0.1, 0.4))} />
                        <Button size="small" icon={<ExpandOutlined />} onClick={() => setZoom(1)} />
                        <Tooltip title={snapGrid ? 'Grid snap ON' : 'Grid snap OFF'}>
                            <Button size="small" type={snapGrid ? 'primary' : 'default'} icon={<AimOutlined />} onClick={() => setSnapGrid(!snapGrid)} />
                        </Tooltip>
                        <Button size="small" icon={<UndoOutlined />} disabled={historyIdx <= 0} onClick={undo} />
                        <Button size="small" icon={<RedoOutlined />} disabled={historyIdx >= history.length - 1} onClick={redo} />
                        {selectedId && <Button size="small" danger icon={<DeleteOutlined />} onClick={() => deleteNode(selectedId)}>Delete</Button>}
                    </div>
                    <div style={{ position: 'absolute', top: 8, right: 8, zIndex: 30 }}>
                        <Tag style={{ borderRadius: 8, fontSize: 10 }}>{Math.round(zoom * 100)}%</Tag>
                        <Tag style={{ borderRadius: 8, fontSize: 10 }}>{nodes.length} nodes · {edges.length} edges</Tag>
                    </div>

                    {/* Canvas surface */}
                    <div ref={canvasRef} style={{ width: '100%', height: 520, transform: `scale(${zoom})`, transformOrigin: '0 0', position: 'relative' }}
                        onMouseMove={onCanvasMouseMove} onMouseUp={onCanvasMouseUp} onMouseLeave={onCanvasMouseUp}
                        onClick={() => { setSelectedId(null); setConnecting(null); }}>
                        {/* SVG edges */}
                        <svg style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', pointerEvents: 'none', zIndex: 1 }}>
                            <defs>
                                <linearGradient id="edgeGrad" x1="0%" y1="0%" x2="100%" y2="0%">
                                    <stop offset="0%" stopColor={themeColor} stopOpacity={0.8} />
                                    <stop offset="100%" stopColor="#8b5cf6" stopOpacity={0.8} />
                                </linearGradient>
                                <marker id="arrowHead" markerWidth="8" markerHeight="6" refX="8" refY="3" orient="auto">
                                    <polygon points="0 0, 8 3, 0 6" fill={themeColor} opacity={0.7} />
                                </marker>
                            </defs>
                            {edges.map((e, i) => (
                                <path key={i} d={bezierPath(e)} fill="none" stroke="url(#edgeGrad)" strokeWidth={2.5}
                                    strokeDasharray={connecting ? '6 3' : 'none'} markerEnd="url(#arrowHead)" />
                            ))}
                        </svg>
                        {/* Nodes */}
                        <AnimatePresence>{nodes.map(renderNode)}</AnimatePresence>
                        {/* Empty state */}
                        {nodes.length === 0 && (
                            <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: 8, opacity: 0.5 }}>
                                <AppstoreOutlined style={{ fontSize: 40, color: isDark ? '#555' : '#aaa' }} />
                                <Text type="secondary">Click palette items or load a preset to start building</Text>
                            </div>
                        )}
                    </div>
                </div>

                {/* Property Panel */}
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ width: 240, flexShrink: 0 }}>
                    <Card size="small" style={{ ...glassCard, height: '100%' }}
                        title={<Space><SettingOutlined style={{ color: themeColor }} /> <Text strong style={{ fontSize: 12 }}>Properties</Text></Space>}>
                        {renderPropPanel()}
                    </Card>
                </motion.div>
            </div>

            {/* ── Bottom Stats Bar ───────────────────────────── */}
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                <Row gutter={[12, 12]}>
                    {flowStats.map((s, i) => (
                        <Col key={i} xs={12} sm={6}>
                            <Card size="small" style={{ ...glassCard, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20, fontFamily: 'monospace' }} />
                                {/* Mini sparkline */}
                                <svg width="100%" height="24" style={{ marginTop: 4 }}>
                                    <polyline fill="none" stroke={s.color} strokeWidth={1.5} opacity={0.5}
                                        points={Array.from({ length: 12 }, (_, j) => `${j * 18},${24 - Math.random() * 20 - 2}`).join(' ')} />
                                </svg>
                            </Card>
                        </Col>
                    ))}
                </Row>
            </motion.div>
        </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    List, Button, Tag, Space, Card, Badge, message, Typography, Row, Col,
    Statistic, Empty, Tooltip, Input, Select, Checkbox, Segmented, Divider,
} from "antd";
import { motion, AnimatePresence } from "framer-motion";
import {
    ReloadOutlined, CheckOutlined, CheckCircleOutlined, MailOutlined,
    BellOutlined, EyeOutlined, InboxOutlined, DeleteOutlined, FilterOutlined,
    SearchOutlined, LinkOutlined, FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { useAuthStore } from "@/store/useAuthStore";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);
const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const MODULE_ICONS: Record<string, string> = {
    crm: '💼', hr: '👥', ops: '⚙️', itsm: '🎫', inventory: '📦',
    accounting: '💰', system: '🖥️', commerce: '🛒',
};

const MODULE_COLORS: Record<string, string> = {
    crm: 'blue', hr: 'purple', ops: 'orange', itsm: 'cyan',
    inventory: 'green', accounting: 'gold', system: 'geekblue', commerce: 'magenta',
};

export default function InboxPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const user = useAuthStore((s) => s.user);
    const userId = user?.id || 'system';
    const [notifications, setNotifications] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [searchTerm, setSearchTerm] = useState('');
    const [filterModule, setFilterModule] = useState<string | undefined>();
    const [viewFilter, setViewFilter] = useState<string>('all');

    const loadNotifications = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($t: String!, $uid: String!) {
                notifications(tenantId: $t, userId: $uid) {
                    id title message module link icon isRead readAt createdAt
                }
            }`, { t: DEFAULT_TENANT_ID, uid: userId });
            setNotifications(data.notifications || []);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, [userId]);

    useEffect(() => { loadNotifications(); }, [loadNotifications]);

    const handleMarkRead = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { markNotificationRead(id: $id) { id } }`, { id });
            setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true, readAt: new Date().toISOString() } : n));
        } catch (err: any) { message.error(err.message); }
    };

    const handleMarkAllRead = async () => {
        try {
            await gql(`mutation($t: String!, $uid: String!) { markAllNotificationsRead(tenantId: $t, userId: $uid) }`, { t: DEFAULT_TENANT_ID, uid: userId });
            setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
            message.success("All marked as read");
        } catch (err: any) { message.error(err.message); }
    };

    const handleBulkMarkRead = async () => {
        try {
            await Promise.all([...selectedIds].map(id =>
                gql(`mutation($id: String!) { markNotificationRead(id: $id) { id } }`, { id })
            ));
            setNotifications(prev => prev.map(n => selectedIds.has(n.id) ? { ...n, isRead: true } : n));
            setSelectedIds(new Set());
            message.success(`${selectedIds.size} notifications marked as read`);
        } catch (err: any) { message.error(err.message); }
    };

    const toggleSelect = (id: string) => {
        setSelectedIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const selectAll = () => {
        if (selectedIds.size === filteredNotifications.length) setSelectedIds(new Set());
        else setSelectedIds(new Set(filteredNotifications.map(n => n.id)));
    };

    // Filtering
    const filteredNotifications = useMemo(() => {
        let filtered = [...notifications];
        if (viewFilter === 'unread') filtered = filtered.filter(n => !n.isRead);
        if (viewFilter === 'read') filtered = filtered.filter(n => n.isRead);
        if (filterModule) filtered = filtered.filter(n => n.module === filterModule);
        if (searchTerm) {
            const term = searchTerm.toLowerCase();
            filtered = filtered.filter(n =>
                n.title?.toLowerCase().includes(term) || n.message?.toLowerCase().includes(term)
            );
        }
        return filtered;
    }, [notifications, viewFilter, filterModule, searchTerm]);

    const unreadCount = notifications.filter(n => !n.isRead).length;
    const modules = [...new Set(notifications.map(n => n.module).filter(Boolean))];

    // Group by date
    const groupedByDate = useMemo(() => {
        const groups: Record<string, any[]> = {};
        filteredNotifications.forEach(n => {
            const date = dayjs(n.createdAt).format('YYYY-MM-DD');
            const label = dayjs(n.createdAt).isToday?.()
                ? 'Today' : dayjs(n.createdAt).format('ddd, MMM D');
            const key = `${date}|||${label}`;
            if (!groups[key]) groups[key] = [];
            groups[key].push(n);
        });
        return Object.entries(groups).sort(([a], [b]) => b.localeCompare(a));
    }, [filteredNotifications]);

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Inbox</AuroraText>}
            subTitle={<DecryptedText text="Your notifications from across all modules" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadNotifications} />,
                <Button key="markAll" icon={<CheckOutlined />} onClick={handleMarkAllRead} disabled={unreadCount === 0}>Mark All Read</Button>,
                <RbacGuard key="exp" requiredRole="manager">
                    <Tooltip title="Export Excel">
                        <Button size="small" icon={<FileExcelOutlined />} onClick={() => exportToExcel({
                            fileName: 'notifications_inbox', title: 'Notification Inbox',
                            columns: [{ header: 'Title', key: 'title' }, { header: 'Message', key: 'message' }, { header: 'Module', key: 'module' }, { header: 'Read', key: 'isRead' }, { header: 'Time', key: 'createdAt' }],
                            data: notifications,
                        })} />
                    </Tooltip>
                    <Tooltip title="Export PDF">
                        <Button size="small" icon={<FilePdfOutlined />} onClick={() => exportToPdf({
                            fileName: 'notifications_inbox', title: 'Notification Inbox',
                            columns: [{ header: 'Title', key: 'title' }, { header: 'Module', key: 'module' }, { header: 'Read', key: 'isRead' }, { header: 'Time', key: 'createdAt' }],
                            data: notifications,
                        })} />
                    </Tooltip>
                </RbacGuard>,
            ]}
        >
            {/* Stats */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total', value: notifications.length, icon: <InboxOutlined />, color: '#3b82f6' },
                    { title: 'Unread', value: unreadCount, icon: <BellOutlined />, color: '#ef4444' },
                    { title: 'Read', value: notifications.length - unreadCount, icon: <EyeOutlined />, color: '#22c55e' },
                    { title: 'Modules', value: modules.length, icon: <FilterOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={6}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Toolbar */}
            <Card size="small" style={{ marginBottom: 16 }}>
                <Row gutter={12} align="middle">
                    <Col flex="auto">
                        <Space wrap>
                            <Segmented
                                value={viewFilter}
                                onChange={(v) => setViewFilter(v as string)}
                                options={[
                                    { label: `All (${notifications.length})`, value: 'all' },
                                    { label: `Unread (${unreadCount})`, value: 'unread' },
                                    { label: `Read (${notifications.length - unreadCount})`, value: 'read' },
                                ]}
                                size="small"
                            />
                            <Select placeholder="Module" allowClear size="small" style={{ width: 130 }}
                                value={filterModule} onChange={setFilterModule}
                                options={modules.map(m => ({
                                    label: <Space><span>{MODULE_ICONS[m] || '🔔'}</span>{m}</Space>,
                                    value: m,
                                }))}
                            />
                            <Input.Search placeholder="Search..." size="small" style={{ width: 200 }}
                                value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
                                allowClear />
                        </Space>
                    </Col>
                    <Col>
                        <Space>
                            {selectedIds.size > 0 && (
                                <Button size="small" type="primary" icon={<CheckCircleOutlined />}
                                    onClick={handleBulkMarkRead}>
                                    Mark {selectedIds.size} Read
                                </Button>
                            )}
                            <Checkbox
                                indeterminate={selectedIds.size > 0 && selectedIds.size < filteredNotifications.length}
                                checked={selectedIds.size === filteredNotifications.length && filteredNotifications.length > 0}
                                onChange={selectAll}>
                                <Text style={{ fontSize: 12 }}>Select All</Text>
                            </Checkbox>
                        </Space>
                    </Col>
                </Row>
            </Card>

            {/* Notification List */}
            <Card>
                {filteredNotifications.length === 0 ? (
                    <Empty description={searchTerm || filterModule ? "No matching notifications" : "No notifications yet"} />
                ) : (
                    groupedByDate.map(([key, items]) => {
                        const label = key.split('|||')[1];
                        return (
                            <div key={key}>
                                <Divider orientation={"left" as any} style={{ margin: '8px 0', fontSize: 12, color: '#94a3b8' }}>
                                    {label}
                                </Divider>
                                <List
                                    dataSource={items}
                                    renderItem={(n: any) => (
                                        <motion.div
                                            initial={{ opacity: 0, x: -10 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            transition={{ duration: 0.15 }}
                                        >
                                            <List.Item
                                                style={{
                                                    background: selectedIds.has(n.id)
                                                        ? 'rgba(99, 102, 241, 0.08)'
                                                        : n.isRead ? 'transparent' : 'rgba(59, 130, 246, 0.04)',
                                                    borderRadius: 8, padding: '10px 16px', marginBottom: 4,
                                                    borderLeft: !n.isRead ? '3px solid #3b82f6' : '3px solid transparent',
                                                    transition: 'all 0.2s',
                                                }}
                                                actions={[
                                                    n.link && (
                                                        <Tooltip key="link" title="Open">
                                                            <Button type="text" size="small" icon={<LinkOutlined />}
                                                                onClick={() => n.link?.startsWith('/') ? router.push(n.link) : (window.location.href = n.link)} />
                                                        </Tooltip>
                                                    ),
                                                    !n.isRead && (
                                                        <Button key="read" type="text" size="small" icon={<CheckCircleOutlined />}
                                                            onClick={() => handleMarkRead(n.id)}>Read</Button>
                                                    ),
                                                ].filter(Boolean)}
                                            >
                                                <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8, width: '100%' }}>
                                                    <Checkbox
                                                        checked={selectedIds.has(n.id)}
                                                        onChange={() => toggleSelect(n.id)}
                                                        style={{ marginTop: 4, flexShrink: 0 }}
                                                    />
                                                    <div style={{ flex: 1, minWidth: 0 }}>
                                                        <List.Item.Meta
                                                            avatar={<span style={{ fontSize: 22 }}>{MODULE_ICONS[n.module] || '🔔'}</span>}
                                                            title={
                                                                <Space>
                                                                    {!n.isRead && <Badge dot color="#3b82f6" />}
                                                                    <Text strong={!n.isRead} style={{ fontSize: 13 }}>{n.title}</Text>
                                                                    {n.module && <Tag color={MODULE_COLORS[n.module] || 'default'} style={{ fontSize: 10 }}>{n.module}</Tag>}
                                                                </Space>
                                                            }
                                                            description={
                                                                <div>
                                                                    {n.message && <Text type="secondary" style={{ fontSize: 12, display: 'block' }}>{n.message}</Text>}
                                                                    <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(n.createdAt).fromNow()}</Text>
                                                                </div>
                                                            }
                                                        />
                                                    </div>
                                                </div>
                                            </List.Item>
                                        </motion.div>
                                    )}
                                />
                            </div>
                        );
                    })
                )}
            </Card>
        </CMSLayout>
    );
}

