"use client";

import React, { useState, useEffect } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Card, Row, Col, Switch, Space, Typography, Divider, Badge,
    Button, message, Tag, Alert, List,
} from "antd";
import { motion } from "framer-motion";
import {
    BellOutlined, MailOutlined, SendOutlined, ApiOutlined,
    SoundOutlined, DesktopOutlined, ClockCircleOutlined,
    SaveOutlined, RocketOutlined, BugOutlined, DollarOutlined,
    ShoppingOutlined, TeamOutlined, SettingOutlined, CheckCircleOutlined,
} from "@ant-design/icons";
import { useNotificationStore } from "@/store/useNotificationStore";

const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface ChannelPref {
    key: string;
    label: string;
    icon: React.ReactNode;
    color: string;
    enabled: boolean;
    description: string;
}

interface ModulePref {
    key: string;
    label: string;
    icon: React.ReactNode;
    enabled: boolean;
}

interface BrowserPref {
    key: string;
    label: string;
    icon: React.ReactNode;
    enabled: boolean;
    description: string;
}

export default function NotificationPreferencesPage() {
    const { themeColor } = usePreferencesStore();
    const { realtimeActive } = useNotificationStore();

    // Channel preferences
    const [channels, setChannels] = useState<ChannelPref[]>([
        { key: 'in_app', label: 'In-App Notifications', icon: <BellOutlined style={{ color: '#8b5cf6' }} />, color: '#8b5cf6', enabled: true, description: 'Bell icon alerts in the admin panel' },
        { key: 'email', label: 'Email Notifications', icon: <MailOutlined style={{ color: '#3b82f6' }} />, color: '#3b82f6', enabled: true, description: 'Receive notifications via email' },
        { key: 'whatsapp', label: 'WhatsApp Messages', icon: <SendOutlined style={{ color: '#22c55e' }} />, color: '#22c55e', enabled: false, description: 'Receive alerts via WhatsApp' },
        { key: 'webhook', label: 'Webhook Integrations', icon: <ApiOutlined style={{ color: '#f59e0b' }} />, color: '#f59e0b', enabled: false, description: 'Push notifications to external services' },
    ]);

    // Module preferences
    const [modules, setModules] = useState<ModulePref[]>([
        { key: 'ops', label: 'Operations', icon: <RocketOutlined style={{ color: '#8b5cf6' }} />, enabled: true },
        { key: 'itsm', label: 'ITSM / Ticketing', icon: <BugOutlined style={{ color: '#ef4444' }} />, enabled: true },
        { key: 'crm', label: 'CRM', icon: <MailOutlined style={{ color: '#06b6d4' }} />, enabled: true },
        { key: 'hr', label: 'HR & People', icon: <TeamOutlined style={{ color: '#22c55e' }} />, enabled: true },
        { key: 'ecommerce', label: 'Commerce & Sales', icon: <ShoppingOutlined style={{ color: '#ec4899' }} />, enabled: false },
        { key: 'accounting', label: 'Accounting & Finance', icon: <DollarOutlined style={{ color: '#6366f1' }} />, enabled: true },
        { key: 'system', label: 'System Alerts', icon: <SettingOutlined style={{ color: '#94a3b8' }} />, enabled: true },
    ]);

    // Browser preferences
    const [browser, setBrowser] = useState<BrowserPref[]>([
        { key: 'desktop', label: 'Desktop Notifications', icon: <DesktopOutlined style={{ color: '#3b82f6' }} />, enabled: true, description: 'Show browser push notifications for new alerts' },
        { key: 'sound', label: 'Notification Sound', icon: <SoundOutlined style={{ color: '#22c55e' }} />, enabled: true, description: 'Play a chime when new notifications arrive' },
    ]);

    const [notifPermission, setNotifPermission] = useState<string>('default');

    useEffect(() => {
        if (typeof window !== 'undefined' && 'Notification' in window) {
            setNotifPermission(Notification.permission);
        }
    }, []);

    const toggleChannel = (key: string) => {
        setChannels(prev => prev.map(c => c.key === key ? { ...c, enabled: !c.enabled } : c));
    };

    const toggleModule = (key: string) => {
        setModules(prev => prev.map(m => m.key === key ? { ...m, enabled: !m.enabled } : m));
    };

    const toggleBrowser = (key: string) => {
        if (key === 'desktop' && notifPermission !== 'granted') {
            Notification.requestPermission().then(p => {
                setNotifPermission(p);
                if (p === 'granted') {
                    setBrowser(prev => prev.map(b => b.key === key ? { ...b, enabled: true } : b));
                }
            });
            return;
        }
        setBrowser(prev => prev.map(b => b.key === key ? { ...b, enabled: !b.enabled } : b));
    };

    const handleSave = () => {
        // Store preferences in localStorage for now
        const prefs = {
            channels: Object.fromEntries(channels.map(c => [c.key, c.enabled])),
            modules: Object.fromEntries(modules.map(m => [m.key, m.enabled])),
            browser: Object.fromEntries(browser.map(b => [b.key, b.enabled])),
        };
        localStorage.setItem('notification_preferences', JSON.stringify(prefs));
        message.success('Notification preferences saved');
    };

    // Load from localStorage on mount
    useEffect(() => {
        const saved = localStorage.getItem('notification_preferences');
        if (saved) {
            try {
                const prefs = JSON.parse(saved);
                if (prefs.channels) {
                    setChannels(prev => prev.map(c => ({ ...c, enabled: prefs.channels[c.key] ?? c.enabled })));
                }
                if (prefs.modules) {
                    setModules(prev => prev.map(m => ({ ...m, enabled: prefs.modules[m.key] ?? m.enabled })));
                }
                if (prefs.browser) {
                    setBrowser(prev => prev.map(b => ({ ...b, enabled: prefs.browser[b.key] ?? b.enabled })));
                }
            } catch { /* ignore malformed */ }
        }
    }, []);

    const enabledChannelCount = channels.filter(c => c.enabled).length;
    const enabledModuleCount = modules.filter(m => m.enabled).length;

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Notification Preferences</AuroraText>}
            subTitle={<DecryptedText text="Configure how and when you receive notifications" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="save" type="primary" icon={<SaveOutlined />} onClick={handleSave}>
                    Save Preferences
                </Button>,
            ]}
        >
            {/* Realtime Status */}
            <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}>
                <Alert
                    type={realtimeActive ? 'success' : 'info'}
                    message={
                        <Space>
                            {realtimeActive ? <CheckCircleOutlined style={{ color: '#22c55e' }} /> : <ClockCircleOutlined style={{ color: '#3b82f6' }} />}
                            <Text strong style={{ fontSize: 13 }}>
                                {realtimeActive
                                    ? 'Supabase Realtime Connected — notifications are pushed instantly'
                                    : 'Using 30-second polling — Realtime connection pending'}
                            </Text>
                            <Badge status={realtimeActive ? 'success' : 'processing'} text={realtimeActive ? 'WebSocket Active' : 'Polling'} />
                        </Space>
                    }
                    showIcon={false}
                    style={{ marginBottom: 16, borderRadius: 12, borderLeft: `4px solid ${realtimeActive ? '#22c55e' : '#3b82f6'}` }}
                />
            </motion.div>

            <Row gutter={[16, 16]}>
                {/* Channel Preferences */}
                <Col xs={24} md={12}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.1 }}>
                        <Card
                            title={<Space><BellOutlined /> Delivery Channels <Tag color="blue">{enabledChannelCount} active</Tag></Space>}
                            size="small"
                            style={glass}
                        >
                            <Space direction="vertical" style={{ width: '100%' }} size={12}>
                                {channels.map((ch) => (
                                    <div key={ch.key} style={{
                                        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                        padding: '10px 14px', borderRadius: 10,
                                        background: ch.enabled ? 'rgba(99, 102, 241, 0.04)' : 'transparent',
                                        border: `1px solid ${ch.enabled ? 'rgba(99, 102, 241, 0.12)' : 'rgba(0,0,0,0.06)'}`,
                                        transition: 'all 0.2s',
                                    }}>
                                        <Space size={12}>
                                            <div style={{
                                                width: 36, height: 36, borderRadius: 10,
                                                background: `${ch.color}15`, display: 'flex',
                                                alignItems: 'center', justifyContent: 'center',
                                            }}>
                                                {ch.icon}
                                            </div>
                                            <div>
                                                <Text strong style={{ fontSize: 13 }}>{ch.label}</Text>
                                                <br />
                                                <Text type="secondary" style={{ fontSize: 11 }}>{ch.description}</Text>
                                            </div>
                                        </Space>
                                        <Switch checked={ch.enabled} onChange={() => toggleChannel(ch.key)} />
                                    </div>
                                ))}
                            </Space>
                        </Card>
                    </motion.div>
                </Col>

                {/* Browser Preferences */}
                <Col xs={24} md={12}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.2 }}>
                        <Card
                            title={<Space><DesktopOutlined /> Browser Alerts</Space>}
                            size="small"
                            style={glass}
                        >
                            <Space direction="vertical" style={{ width: '100%' }} size={12}>
                                {browser.map((b) => (
                                    <div key={b.key} style={{
                                        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                        padding: '10px 14px', borderRadius: 10,
                                        background: b.enabled ? 'rgba(34, 197, 94, 0.04)' : 'transparent',
                                        border: `1px solid ${b.enabled ? 'rgba(34, 197, 94, 0.12)' : 'rgba(0,0,0,0.06)'}`,
                                        transition: 'all 0.2s',
                                    }}>
                                        <Space size={12}>
                                            {b.icon}
                                            <div>
                                                <Text strong style={{ fontSize: 13 }}>{b.label}</Text>
                                                <br />
                                                <Text type="secondary" style={{ fontSize: 11 }}>{b.description}</Text>
                                            </div>
                                        </Space>
                                        <Space>
                                            {b.key === 'desktop' && notifPermission !== 'granted' && (
                                                <Tag color="orange" style={{ fontSize: 10 }}>Permission needed</Tag>
                                            )}
                                            <Switch checked={b.enabled && (b.key !== 'desktop' || notifPermission === 'granted')} onChange={() => toggleBrowser(b.key)} />
                                        </Space>
                                    </div>
                                ))}
                            </Space>

                            <Divider style={{ margin: '16px 0 12px' }} />

                            {/* Connection Status */}
                            <div style={{ padding: '8px 14px', borderRadius: 10, background: 'rgba(99,102,241,0.04)' }}>
                                <Space direction="vertical" size={4} style={{ width: '100%' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                        <Text type="secondary" style={{ fontSize: 12 }}>Realtime Connection</Text>
                                        <Badge status={realtimeActive ? 'success' : 'default'} text={
                                            <Text style={{ fontSize: 11, color: realtimeActive ? '#22c55e' : '#94a3b8' }}>
                                                {realtimeActive ? 'Connected' : 'Disconnected'}
                                            </Text>
                                        } />
                                    </div>
                                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                        <Text type="secondary" style={{ fontSize: 12 }}>Browser Notifications</Text>
                                        <Badge status={notifPermission === 'granted' ? 'success' : notifPermission === 'denied' ? 'error' : 'warning'} text={
                                            <Text style={{ fontSize: 11, color: notifPermission === 'granted' ? '#22c55e' : notifPermission === 'denied' ? '#ef4444' : '#f59e0b' }}>
                                                {notifPermission === 'granted' ? 'Granted' : notifPermission === 'denied' ? 'Blocked' : 'Not Set'}
                                            </Text>
                                        } />
                                    </div>
                                </Space>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Module Subscriptions */}
            <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
                <Col xs={24}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                        <Card
                            title={<Space><SettingOutlined /> Module Subscriptions <Tag color="purple">{enabledModuleCount} active</Tag></Space>}
                            size="small"
                            style={glass}
                        >
                            <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 12 }}>
                                Choose which modules can send you notifications. Disabled modules will be muted.
                            </Text>
                            <Row gutter={[12, 12]}>
                                {modules.map((mod) => (
                                    <Col key={mod.key} xs={12} sm={8} md={6}>
                                        <div
                                            onClick={() => toggleModule(mod.key)}
                                            style={{
                                                cursor: 'pointer',
                                                padding: '14px 16px',
                                                borderRadius: 10,
                                                textAlign: 'center',
                                                background: mod.enabled ? 'rgba(99, 102, 241, 0.06)' : 'rgba(0,0,0,0.02)',
                                                border: `1.5px solid ${mod.enabled ? 'rgba(99, 102, 241, 0.2)' : 'rgba(0,0,0,0.06)'}`,
                                                transition: 'all 0.2s',
                                            }}
                                        >
                                            <div style={{ fontSize: 22, marginBottom: 4 }}>{mod.icon}</div>
                                            <Text strong style={{ fontSize: 12 }}>{mod.label}</Text>
                                            <div style={{ marginTop: 6 }}>
                                                <Switch size="small" checked={mod.enabled} />
                                            </div>
                                        </div>
                                    </Col>
                                ))}
                            </Row>
                        </Card>
                    </motion.div>
                </Col>
            </Row>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Form, Input, Select, Card, Switch, Tooltip,
    message, Typography, Row, Col, Statistic,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    NodeIndexOutlined, ThunderboltOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const MODULE_COLORS: Record<string, string> = {
    crm: '#1890ff', hr: '#9254de', ops: '#fa8c16', itsm: '#13c2c2',
    inventory: '#52c41a', ecommerce: '#eb2f96', accounting: '#faad14', pm: '#2f54eb',
};

const MODULE_OPTIONS = ['crm','hr','ops','itsm','inventory','ecommerce','accounting','pm'].map(m => ({ label: m.toUpperCase(), value: m }));
const EVENT_OPTIONS = ['create','update','delete','assign','complete','overdue','status_change'].map(e => ({ label: e.replace('_', ' '), value: e }));
const RECIPIENT_OPTIONS = ['assignee','creator','role','email','webhook'].map(r => ({ label: r, value: r }));

const RULE_FIELDS: FieldDef[] = [
    { name: "name", label: "Rule Name", required: true },
    { name: "module", label: "Module", required: true },
    { name: "event", label: "Event", required: true },
];

export default function RulesPage() {
    const { themeColor } = usePreferencesStore();
    const [rules, setRules] = useState<any[]>([]);
    const [channels, setChannels] = useState<any[]>([]);
    const [templates, setTemplates] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [moduleFilter, setModuleFilter] = useState<string | undefined>(undefined);
    const [form] = Form.useForm();

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [rulesData, chData, tplData] = await Promise.all([
                gql(`query($t: String!) { notificationRules(tenantId: $t) {
                    id name module event channelId templateId recipientType recipientValue isActive channelName templateName createdAt
                } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!) { notificationChannels(tenantId: $t) { id name channelType } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!) { notificationTemplates(tenantId: $t) { id name channelType } }`, { t: DEFAULT_TENANT_ID }),
            ]);
            setRules(rulesData.notificationRules || []);
            setChannels(chData.notificationChannels || []);
            setTemplates(tplData.notificationTemplates || []);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { load(); }, [load]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(`mutation($id: String!, $name: String, $module: String, $event: String, $isActive: Boolean) {
                    updateNotificationRule(id: $id, name: $name, module: $module, event: $event, isActive: $isActive) { id }
                }`, { id: editing.id, ...values });
                message.success("Updated");
            } else {
                await gql(`mutation($t: String!, $name: String!, $module: String!, $event: String!, $channelId: String, $templateId: String, $recipientType: String, $recipientValue: String) {
                    createNotificationRule(tenantId: $t, name: $name, module: $module, event: $event, channelId: $channelId, templateId: $templateId, recipientType: $recipientType, recipientValue: $recipientValue) { id }
                }`, { t: DEFAULT_TENANT_ID, ...values });
                message.success("Created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); load();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($t: String!, $name: String!, $module: String!, $event: String!) {
                    createNotificationRule(tenantId: $t, name: $name, module: $module, event: $event) { id }
                }`, { t: DEFAULT_TENANT_ID, name: r.name, module: r.module, event: r.event });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        load(); return { success, failed, errors };
    };

    const handleToggle = async (id: string, isActive: boolean) => {
        try {
            await gql(`mutation($id: String!, $isActive: Boolean) { updateNotificationRule(id: $id, isActive: $isActive) { id } }`, { id, isActive });
            load();
        } catch (err: any) { message.error(err.message); }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteNotificationRule(id: $id) }`, { id });
            message.success("Deleted"); load();
        } catch (err: any) { message.error(err.message); }
    };

    const columns: ColumnsType<any> = [
        {
            title: "Rule", key: "name",
            render: (_, r) => (<div><Text strong>{r.name}</Text><br /><Text type="secondary" style={{ fontSize: 11 }}>When {r.module}.{r.event}</Text></div>),
        },
        { title: "Module", dataIndex: "module", width: 100, render: (v: string) => <Tag color={MODULE_COLORS[v] || 'default'} style={{ fontWeight: 500 }}>{v.toUpperCase()}</Tag> },
        { title: "Event", dataIndex: "event", width: 120, render: (v: string) => <Tag color="geekblue">{v.replace('_', ' ')}</Tag> },
        { title: "Channel", key: "channel", width: 130, render: (_, r) => r.channelName ? <Tag>{r.channelName}</Tag> : '—' },
        { title: "Recipient", dataIndex: "recipientType", width: 100, render: (v: string) => <Tag>{v}</Tag> },
        { title: "Active", key: "active", width: 70, render: (_, r) => <Switch size="small" checked={r.isActive} onChange={(v) => handleToggle(r.id, v)} /> },
        {
            title: "Actions", key: "actions", width: 100,
            render: (_, r) => (
                <Space>
                    <Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue(r); setIsModalOpen(true); }} />
                    <Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const formSteps = [{
        title: "Rule Info", icon: <NodeIndexOutlined />, fields: ["name", "module", "event", "channelId", "templateId", "recipientType", "recipientValue"],
        content: (
            <>
                <Form.Item name="name" label="Rule Name" rules={[{ required: true }]}><Input placeholder="e.g., Notify assignee on ticket create" /></Form.Item>
                <Row gutter={12}>
                    <Col span={12}><Form.Item name="module" label="Module" rules={[{ required: true }]}><Select options={MODULE_OPTIONS} /></Form.Item></Col>
                    <Col span={12}><Form.Item name="event" label="Event" rules={[{ required: true }]}><Select options={EVENT_OPTIONS} /></Form.Item></Col>
                </Row>
                <Row gutter={12}>
                    <Col span={12}>
                        <Form.Item name="channelId" label="Channel">
                            <Select allowClear placeholder="Select channel" options={channels.map(c => ({ label: `${c.name} (${c.channelType})`, value: c.id }))} />
                        </Form.Item>
                    </Col>
                    <Col span={12}>
                        <Form.Item name="templateId" label="Template">
                            <Select allowClear placeholder="Select template" options={templates.map(t => ({ label: `${t.name} (${t.channelType})`, value: t.id }))} />
                        </Form.Item>
                    </Col>
                </Row>
                <Row gutter={12}>
                    <Col span={12}><Form.Item name="recipientType" label="Recipient Type" initialValue="assignee"><Select options={RECIPIENT_OPTIONS} /></Form.Item></Col>
                    <Col span={12}><Form.Item name="recipientValue" label="Recipient Value"><Input placeholder="email or role name" /></Form.Item></Col>
                </Row>
            </>
        ),
    }];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Rules</AuroraText>}
            subTitle={<DecryptedText text="Trigger rules — define when notifications fire and who receives them" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={load} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>Create Rule</Button>,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'notification_rules', title: 'Notification Rules', columns: [{ header: 'Name', key: 'name' }, { header: 'Module', key: 'module' }, { header: 'Event', key: 'event' }, { header: 'Recipient', key: 'recipientType' }, { header: 'Active', key: 'isActive' }], data: rules })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'notification_rules', title: 'Notification Rules', columns: [{ header: 'Name', key: 'name' }, { header: 'Module', key: 'module' }, { header: 'Event', key: 'event' }, { header: 'Recipient', key: 'recipientType' }], data: rules })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Rules', value: rules.length, icon: <NodeIndexOutlined />, color: '#8b5cf6' },
                    { title: 'Active', value: rules.filter(r => r.isActive).length, icon: <ThunderboltOutlined />, color: '#22c55e' },
                    { title: 'Inactive', value: rules.filter(r => !r.isActive).length, icon: <NodeIndexOutlined />, color: '#94a3b8' },
                    { title: 'Modules', value: [...new Set(rules.map(r => r.module))].length, icon: <NodeIndexOutlined />, color: '#3b82f6' },
                    { title: 'Event Types', value: [...new Set(rules.map(r => r.event))].length, icon: <ThunderboltOutlined />, color: '#f59e0b' },
                ].map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}><Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20 }} /></Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            <Card extra={
                <Space>
                    <Select value={moduleFilter} onChange={setModuleFilter} allowClear placeholder="Filter by module" style={{ width: 160 }}
                        options={[...new Set(rules.map(r => r.module))].map(m => ({ label: m.toUpperCase(), value: m }))} />
                </Space>
            }>
                <Table columns={columns}
                    dataSource={(moduleFilter ? rules.filter(r => r.module === moduleFilter) : rules).map(r => ({ ...r, key: r.id }))}
                    loading={loading} pagination={false} size="middle" scroll={{ x: 800 }} />
            </Card>
            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave} form={form} title={editing ? "Edit Rule" : "Create Rule"}
                entityName="rule" steps={formSteps} fields={RULE_FIELDS} width={600}
                onBatchCreate={handleBatchCreate} gradient={["#f59e0b", themeColor]} editMode={!!editing} />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Form, Input, Select, Card, Tooltip,
    message, Typography, Row, Col, Statistic,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    FileTextOutlined, CodeOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const CHANNEL_COLORS: Record<string, string> = { email: 'blue', whatsapp: 'green', webhook: 'orange', in_app: 'purple' };

const TEMPLATE_FIELDS: FieldDef[] = [
    { name: "name", label: "Template Name", required: true },
    { name: "channelType", label: "Channel Type", required: true },
    { name: "body", label: "Body", required: true },
];

export default function TemplatesPage() {
    const { themeColor } = usePreferencesStore();
    const [templates, setTemplates] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($t: String!) { notificationTemplates(tenantId: $t) {
                id name channelType subject body variables isActive createdAt
            } }`, { t: DEFAULT_TENANT_ID });
            setTemplates(data.notificationTemplates || []);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { load(); }, [load]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(`mutation($id: String!, $name: String, $subject: String, $body: String) {
                    updateNotificationTemplate(id: $id, name: $name, subject: $subject, body: $body) { id }
                }`, { id: editing.id, ...values });
                message.success("Updated");
            } else {
                await gql(`mutation($t: String!, $name: String!, $type: String!, $body: String!, $subject: String) {
                    createNotificationTemplate(tenantId: $t, name: $name, channelType: $type, body: $body, subject: $subject) { id }
                }`, { t: DEFAULT_TENANT_ID, ...values, type: values.channelType });
                message.success("Created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); load();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($t: String!, $name: String!, $type: String!, $body: String!) {
                    createNotificationTemplate(tenantId: $t, name: $name, channelType: $type, body: $body) { id }
                }`, { t: DEFAULT_TENANT_ID, name: r.name, type: r.channelType || 'email', body: r.body || '' });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        load(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteNotificationTemplate(id: $id) }`, { id });
            message.success("Deleted"); load();
        } catch (err: any) { message.error(err.message); }
    };

    const columns: ColumnsType<any> = [
        {
            title: "Template", key: "name",
            render: (_, r) => (<div><Text strong>{r.name}</Text><br /><Text type="secondary" style={{ fontSize: 11 }}>{r.subject || '(no subject)'}</Text></div>),
        },
        { title: "Channel", dataIndex: "channelType", width: 100, render: (v: string) => <Tag color={CHANNEL_COLORS[v]}>{v}</Tag> },
        {
            title: "Variables", key: "vars", width: 200,
            render: (_, r) => (r.variables || []).map((v: string) => <Tag key={v} color="geekblue" style={{ fontSize: 10 }}>{`{{${v}}}`}</Tag>),
        },
        { title: "Active", key: "active", width: 70, render: (_, r) => <Tag color={r.isActive ? 'success' : 'default'}>{r.isActive ? 'Yes' : 'No'}</Tag> },
        {
            title: "Actions", key: "actions", width: 120,
            render: (_, r) => (
                <Space>
                    <Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue(r); setIsModalOpen(true); }} />
                    <Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const formSteps = [{
        title: "Template Info", icon: <FileTextOutlined />, fields: ["name", "channelType", "subject", "body"],
        content: (
            <>
                <Form.Item name="name" label="Template Name" rules={[{ required: true }]}><Input placeholder="e.g., Ticket Assigned" /></Form.Item>
                {!editing && (
                    <Form.Item name="channelType" label="Channel" rules={[{ required: true }]}>
                        <Select options={['email','whatsapp','webhook','in_app'].map(t => ({ label: t.replace('_', '-'), value: t }))} />
                    </Form.Item>
                )}
                <Form.Item name="subject" label="Subject (email only)"><Input placeholder="e.g., You have been assigned to {{ticket_id}}" /></Form.Item>
                <Form.Item name="body" label="Body" rules={[{ required: true }]} extra="Use {{variable_name}} for dynamic content">
                    <Input.TextArea rows={5} placeholder="Hello {{user_name}}, a new task has been assigned to you." />
                </Form.Item>
            </>
        ),
    }];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Templates</AuroraText>}
            subTitle={<DecryptedText text="Message templates with dynamic variable placeholders" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={load} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>Create Template</Button>,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'notification_templates', title: 'Notification Templates', columns: [{ header: 'Name', key: 'name' }, { header: 'Channel', key: 'channelType' }, { header: 'Subject', key: 'subject' }, { header: 'Active', key: 'isActive' }], data: templates })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'notification_templates', title: 'Notification Templates', columns: [{ header: 'Name', key: 'name' }, { header: 'Channel', key: 'channelType' }, { header: 'Subject', key: 'subject' }], data: templates })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total', value: templates.length, icon: <FileTextOutlined />, color: '#8b5cf6' },
                    { title: 'Active', value: templates.filter(t => t.isActive).length, icon: <CodeOutlined />, color: '#22c55e' },
                    { title: 'Email', value: templates.filter(t => t.channelType === 'email').length, icon: <FileTextOutlined />, color: '#3b82f6' },
                    { title: 'WhatsApp', value: templates.filter(t => t.channelType === 'whatsapp').length, icon: <FileTextOutlined />, color: '#25d366' },
                    { title: 'Webhook', value: templates.filter(t => t.channelType === 'webhook').length, icon: <FileTextOutlined />, color: '#f59e0b' },
                    { title: 'Variables', value: [...new Set(templates.flatMap(t => t.variables || []))].length, icon: <CodeOutlined />, color: '#ec4899' },
                ].map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}><Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20 }} /></Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <Card><Table columns={columns} dataSource={templates.map(t => ({ ...t, key: t.id }))} loading={loading} pagination={false} size="middle" scroll={{ x: 700 }} /></Card>
            <SteppedFormModal open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave} form={form} title={editing ? "Edit Template" : "Create Template"}
                entityName="template" steps={formSteps} fields={TEMPLATE_FIELDS} width={560}
                onBatchCreate={handleBatchCreate} gradient={["#8b5cf6", themeColor]} editMode={!!editing} />
        </CMSLayout>
    );
}

'use client';
import React, { useState } from 'react';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Table, Typography, Button, Space, Tag, Modal, Form, Input, Select, message, Row, Col, Statistic, Tooltip, Drawer, Badge } from 'antd';
import { ApiOutlined, PlusOutlined, ReloadOutlined, DeleteOutlined, EditOutlined, SendOutlined, CheckCircleOutlined, CloseCircleOutlined, EyeOutlined, ThunderboltOutlined, LinkOutlined, ClockCircleOutlined } from '@ant-design/icons';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
dayjs.extend(relativeTime);

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const MOCK_WH = [
    { id: 'wh-1', name: 'Slack Notifications', url: 'https://hooks.slack.com/services/T00/B00/xxxx', events: ['order.created', 'order.cancelled'], isActive: true, lastTriggered: new Date(Date.now() - 3600000).toISOString(), successCount: 142, failureCount: 3, createdAt: new Date(Date.now() - 86400000 * 30).toISOString() },
    { id: 'wh-2', name: 'CRM Sync', url: 'https://api.crm.example.com/webhooks', events: ['contact.created', 'deal.won'], isActive: true, lastTriggered: new Date(Date.now() - 7200000).toISOString(), successCount: 89, failureCount: 1, createdAt: new Date(Date.now() - 86400000 * 60).toISOString() },
    { id: 'wh-3', name: 'Analytics Pipeline', url: 'https://analytics.internal/ingest', events: ['page.viewed', 'user.signup'], isActive: false, successCount: 1200, failureCount: 15, createdAt: new Date(Date.now() - 86400000 * 90).toISOString() },
    { id: 'wh-4', name: 'Inventory Alert', url: 'https://warehouse.api/stock-alert', events: ['inventory.low_stock'], isActive: true, lastTriggered: new Date(Date.now() - 1800000).toISOString(), successCount: 56, failureCount: 0, createdAt: new Date(Date.now() - 86400000 * 14).toISOString() },
];

const MOCK_LOGS = [
    { id: 'dl-1', webhookId: 'wh-1', webhookName: 'Slack Notifications', event: 'order.created', status: 'success', statusCode: 200, responseTime: 145, payload: '{"event":"order.created"}', createdAt: new Date(Date.now() - 300000).toISOString() },
    { id: 'dl-2', webhookId: 'wh-2', webhookName: 'CRM Sync', event: 'contact.created', status: 'success', statusCode: 201, responseTime: 230, payload: '{"event":"contact.created"}', createdAt: new Date(Date.now() - 600000).toISOString() },
    { id: 'dl-3', webhookId: 'wh-1', webhookName: 'Slack Notifications', event: 'order.cancelled', status: 'failed', statusCode: 500, responseTime: 5000, payload: '{"event":"order.cancelled"}', createdAt: new Date(Date.now() - 900000).toISOString() },
    { id: 'dl-4', webhookId: 'wh-4', webhookName: 'Inventory Alert', event: 'inventory.low_stock', status: 'success', statusCode: 200, responseTime: 98, payload: '{"event":"inventory.low_stock"}', createdAt: new Date(Date.now() - 1200000).toISOString() },
];

const EVENT_OPTIONS = [
    { label: '📦 order.created', value: 'order.created' }, { label: '❌ order.cancelled', value: 'order.cancelled' },
    { label: '👤 contact.created', value: 'contact.created' }, { label: '🎯 deal.won', value: 'deal.won' },
    { label: '📊 page.viewed', value: 'page.viewed' }, { label: '🆕 user.signup', value: 'user.signup' },
    { label: '⚠️ inventory.low_stock', value: 'inventory.low_stock' },
];

export default function WebhooksPage() {
    const { themeColor } = usePreferencesStore();
    const [webhooks, setWebhooks] = useState<any[]>(MOCK_WH);
    const [logs] = useState<any[]>(MOCK_LOGS);
    const [modalOpen, setModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [logDrawer, setLogDrawer] = useState(false);
    const [selectedWh, setSelectedWh] = useState<any>(null);
    const [testingId, setTestingId] = useState<string | null>(null);
    const [form] = Form.useForm();

    const handleSave = () => {
        form.validateFields().then(values => {
            if (editingId) { setWebhooks(prev => prev.map(w => w.id === editingId ? { ...w, ...values } : w)); message.success('Updated'); }
            else { setWebhooks(prev => [...prev, { id: `wh-${Date.now()}`, ...values, isActive: true, successCount: 0, failureCount: 0, createdAt: new Date().toISOString() }]); message.success('Created'); }
            setModalOpen(false); setEditingId(null); form.resetFields();
        });
    };

    const handleTest = async (wh: any) => {
        setTestingId(wh.id); await new Promise(r => setTimeout(r, 1200));
        setWebhooks(prev => prev.map(w => w.id === wh.id ? { ...w, lastTriggered: new Date().toISOString(), successCount: w.successCount + 1 } : w));
        message.success(`Test ping sent to ${wh.name} — 200 OK`); setTestingId(null);
    };

    const totalDel = webhooks.reduce((s, w) => s + w.successCount + w.failureCount, 0);
    const totalOk = webhooks.reduce((s, w) => s + w.successCount, 0);
    const totalFail = webhooks.reduce((s, w) => s + w.failureCount, 0);

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, '#f59e0b', '#3b82f6']}>Webhooks</AuroraText>} subTitle={<DecryptedText text="Manage webhook endpoints and delivery logs" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[<Button key="r" icon={<ReloadOutlined />} />, <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditingId(null); form.resetFields(); setModalOpen(true); }} style={{ background: `linear-gradient(135deg, ${themeColor}, #6366f1)`, border: 'none', borderRadius: 8 }}>New Webhook</Button>]}>
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <Row gutter={[12, 12]}>
                    {[{ title: 'Endpoints', value: webhooks.length, color: '#3b82f6', icon: <ApiOutlined /> }, { title: 'Active', value: webhooks.filter(w => w.isActive).length, color: '#10b981', icon: <CheckCircleOutlined /> }, { title: 'Deliveries', value: totalDel, color: '#8b5cf6', icon: <SendOutlined /> }, { title: 'Success Rate', value: `${totalDel > 0 ? Math.round((totalOk / totalDel) * 100) : 0}%`, color: '#06b6d4', icon: <ThunderboltOutlined /> }, { title: 'Successful', value: totalOk, color: '#10b981', icon: <CheckCircleOutlined /> }, { title: 'Failed', value: totalFail, color: totalFail > 0 ? '#ef4444' : '#94a3b8', icon: <CloseCircleOutlined /> }].map((s, i) => (
                        <Col key={i} xs={12} md={4}><motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}><Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}><Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 18 }} /></Card></motion.div></Col>
                    ))}
                </Row>
                <Card style={glass} title={<Space><ApiOutlined style={{ color: themeColor }} /><Text strong>Webhook Endpoints</Text><Badge count={webhooks.length} style={{ backgroundColor: themeColor }} /></Space>}>
                    <Table dataSource={webhooks} rowKey="id" size="middle" pagination={false} scroll={{ x: 900 }} columns={[
                        { title: 'Name', dataIndex: 'name', render: (v: string, r: any) => <Space><div style={{ width: 8, height: 8, borderRadius: '50%', background: r.isActive ? '#10b981' : '#94a3b8', boxShadow: r.isActive ? '0 0 6px #10b98160' : 'none' }} /><Text strong style={{ fontSize: 13 }}>{v}</Text></Space> },
                        { title: 'URL', dataIndex: 'url', ellipsis: true, width: 240, render: (v: string) => <Text copyable style={{ fontSize: 11, fontFamily: 'monospace' }}>{v}</Text> },
                        { title: 'Events', dataIndex: 'events', width: 180, render: (v: string[]) => <Space wrap size={2}>{v.slice(0, 2).map(e => <Tag key={e} style={{ fontSize: 10, borderRadius: 10, margin: 0 }}>{e}</Tag>)}{v.length > 2 && <Tag style={{ fontSize: 10 }}>+{v.length - 2}</Tag>}</Space> },
                        { title: 'OK', dataIndex: 'successCount', width: 60, align: 'center' as const, render: (v: number) => <Text style={{ color: '#10b981', fontWeight: 600 }}>{v}</Text> },
                        { title: 'Fail', dataIndex: 'failureCount', width: 60, align: 'center' as const, render: (v: number) => <Text style={{ color: v > 0 ? '#ef4444' : '#94a3b8', fontWeight: 600 }}>{v}</Text> },
                        { title: 'Last', dataIndex: 'lastTriggered', width: 110, render: (v: string) => v ? <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(v).fromNow()}</Text> : '—' },
                        { title: '', key: 'act', width: 180, render: (_: any, r: any) => <Space size={4}><Tooltip title="Test"><Button size="small" icon={<ThunderboltOutlined />} loading={testingId === r.id} onClick={() => handleTest(r)} /></Tooltip><Tooltip title="Logs"><Button size="small" icon={<EyeOutlined />} onClick={() => { setSelectedWh(r); setLogDrawer(true); }} /></Tooltip><Tooltip title="Edit"><Button size="small" icon={<EditOutlined />} onClick={() => { setEditingId(r.id); form.setFieldsValue(r); setModalOpen(true); }} /></Tooltip><Tooltip title="Delete"><Button size="small" danger icon={<DeleteOutlined />} onClick={() => { setWebhooks(prev => prev.filter(w => w.id !== r.id)); message.success('Deleted'); }} /></Tooltip></Space> },
                    ]} />
                </Card>
                <Card style={glass} title={<Space><ClockCircleOutlined style={{ color: '#8b5cf6' }} /><Text strong>Recent Deliveries</Text></Space>}>
                    <Table dataSource={logs} rowKey="id" size="small" pagination={false} columns={[
                        { title: 'Webhook', dataIndex: 'webhookName', render: (v: string) => <Text style={{ fontSize: 12 }}>{v}</Text> },
                        { title: 'Event', dataIndex: 'event', render: (v: string) => <Tag style={{ fontSize: 10, borderRadius: 10 }}>{v}</Tag> },
                        { title: 'Status', dataIndex: 'status', width: 80, render: (v: string) => <Tag color={v === 'success' ? 'green' : v === 'failed' ? 'red' : 'orange'} style={{ borderRadius: 10, fontSize: 10 }}>{v}</Tag> },
                        { title: 'Code', dataIndex: 'statusCode', width: 60, render: (v: number) => <Text style={{ fontSize: 11, fontFamily: 'monospace' }}>{v || '—'}</Text> },
                        { title: 'Time', dataIndex: 'responseTime', width: 70, render: (v: number) => <Text style={{ fontSize: 11 }}>{v ? `${v}ms` : '—'}</Text> },
                        { title: 'When', dataIndex: 'createdAt', width: 120, render: (v: string) => <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(v).fromNow()}</Text> },
                    ]} />
                </Card>
            </motion.div>
            <Modal title={editingId ? 'Edit Webhook' : 'New Webhook'} open={modalOpen} onCancel={() => { setModalOpen(false); setEditingId(null); form.resetFields(); }} onOk={handleSave} okText={editingId ? 'Update' : 'Create'} width={520}>
                <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
                    <Form.Item name="name" label="Name" rules={[{ required: true }]}><Input placeholder="e.g. Slack Notifications" /></Form.Item>
                    <Form.Item name="url" label="URL" rules={[{ required: true, type: 'url' }]}><Input placeholder="https://example.com/webhook" prefix={<LinkOutlined />} /></Form.Item>
                    <Form.Item name="events" label="Events" rules={[{ required: true }]}><Select mode="multiple" placeholder="Select events" options={EVENT_OPTIONS} /></Form.Item>
                </Form>
            </Modal>
            <Drawer title={`Logs — ${selectedWh?.name || ''}`} open={logDrawer} onClose={() => setLogDrawer(false)} width={500}>
                <Table dataSource={selectedWh ? logs.filter(l => l.webhookId === selectedWh.id) : []} rowKey="id" size="small" pagination={{ pageSize: 20 }} columns={[
                    { title: 'Event', dataIndex: 'event', render: (v: string) => <Tag style={{ fontSize: 10 }}>{v}</Tag> },
                    { title: 'Status', dataIndex: 'status', width: 80, render: (v: string) => <Tag color={v === 'success' ? 'green' : 'red'} style={{ fontSize: 10, borderRadius: 10 }}>{v}</Tag> },
                    { title: 'Code', dataIndex: 'statusCode', width: 50 },
                    { title: 'When', dataIndex: 'createdAt', render: (v: string) => <Text type="secondary" style={{ fontSize: 10 }}>{dayjs(v).fromNow()}</Text> },
                ]} />
            </Drawer>
        </CMSLayout>
    );
}

