"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { AnimatedCircularProgressBar } from "@/components/magicui/animated-circular-progress-bar";
import {
    Card, Row, Col, Statistic, Tag, Space, Typography, Spin, List, Progress,
    Empty, Button, Tooltip, Timeline, Divider,
} from "antd";
import { motion } from "framer-motion";
import {
    BookOutlined, RocketOutlined, CheckCircleOutlined, ClockCircleOutlined,
    WarningOutlined, ThunderboltOutlined, ScheduleOutlined, BarChartOutlined,
    SendOutlined, BellOutlined, MailOutlined, ApiOutlined,
    PlusOutlined, InboxOutlined, PlayCircleOutlined, ArrowRightOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined, ReloadOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);
const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const STATUS_CONFIG: Record<string, { color: string; icon: React.ReactNode }> = {
    pending: { color: '#94a3b8', icon: <ClockCircleOutlined /> },
    in_progress: { color: '#3b82f6', icon: <ThunderboltOutlined /> },
    completed: { color: '#22c55e', icon: <CheckCircleOutlined /> },
    cancelled: { color: '#ef4444', icon: <WarningOutlined /> },
    failed: { color: '#ef4444', icon: <WarningOutlined /> },
};

const PRIORITY_COLORS: Record<string, string> = {
    critical: '#ef4444', high: '#f59e0b', medium: '#3b82f6', low: '#94a3b8',
};

const CATEGORY_COLORS: Record<string, string> = {
    infrastructure: '#3b82f6', security: '#ef4444', monitoring: '#22c55e',
    deployment: '#8b5cf6', maintenance: '#f59e0b', compliance: '#06b6d4',
    other: '#94a3b8',
};

const DELIVERY_ICONS: Record<string, React.ReactNode> = {
    email: <MailOutlined style={{ color: '#3b82f6' }} />,
    whatsapp: <SendOutlined style={{ color: '#22c55e' }} />,
    webhook: <ApiOutlined style={{ color: '#f59e0b' }} />,
    in_app: <BellOutlined style={{ color: '#8b5cf6' }} />,
};

export default function OpsDashboardPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [playbooks, setPlaybooks] = useState<any[]>([]);
    const [runs, setRuns] = useState<any[]>([]);
    const [schedules, setSchedules] = useState<any[]>([]);
    const [deliveryLogs, setDeliveryLogs] = useState<any[]>([]);
    const [notifStats, setNotifStats] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [pbData, runData, schData, logData] = await Promise.all([
                gql(`query($t: String!) { opsPlaybooks(tenantId: $t) { id name category priority isActive estimatedMinutes createdAt } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!) { opsRuns(tenantId: $t) { id name status playbookName playbookPriority startedAt completedAt dueAt createdAt } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!) { opsSchedules(tenantId: $t) { id name cronExpression isActive playbookName nextRunAt lastRunAt timezone } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!, $limit: Float) { notificationLogs(tenantId: $t, limit: $limit) { id channelType recipient subject status createdAt } }`, { t: DEFAULT_TENANT_ID, limit: 10 }),
            ]);
            setPlaybooks(pbData.opsPlaybooks || []);
            setRuns(runData.opsRuns || []);
            setSchedules(schData.opsSchedules || []);
            setDeliveryLogs(logData.notificationLogs || []);
        } catch { /* ignore */ }
        try {
            const nsData = await gql(`query($t: String!) { notificationStats(tenantId: $t) {
                totalLogs sentLogs failedLogs totalNotifications unreadNotifications activeChannels
                channelBreakdown { type count }
            } }`, { t: DEFAULT_TENANT_ID });
            setNotifStats(nsData.notificationStats || null);
        } catch { /* ignore */ }
        setLoading(false);
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const activeRuns = runs.filter(r => r.status === 'in_progress');
    const completedRuns = runs.filter(r => r.status === 'completed');
    const pendingRuns = runs.filter(r => r.status === 'pending');
    const overdueRuns = runs.filter(r => r.dueAt && dayjs(r.dueAt).isBefore(dayjs()) && r.status !== 'completed');
    const completionRate = runs.length > 0 ? Math.round((completedRuns.length / runs.length) * 100) : 0;
    const activeSchedules = schedules.filter(s => s.isActive);

    // Playbook category distribution
    const categoryMap: Record<string, number> = {};
    playbooks.forEach(p => { const cat = p.category || 'other'; categoryMap[cat] = (categoryMap[cat] || 0) + 1; });
    const totalPb = playbooks.length || 1;

    // Priority distribution
    const priorityMap: Record<string, number> = {};
    playbooks.forEach(p => { const pri = p.priority || 'medium'; priorityMap[pri] = (priorityMap[pri] || 0) + 1; });

    // Build unified activity timeline
    const activityItems = [
        ...runs.slice(0, 5).map(r => ({
            time: r.createdAt,
            color: STATUS_CONFIG[r.status]?.color || '#94a3b8',
            icon: STATUS_CONFIG[r.status]?.icon || <ClockCircleOutlined />,
            title: r.name,
            desc: `${r.status.replace('_', ' ')} - ${r.playbookName || 'Playbook'}`,
            type: 'run' as const,
        })),
        ...deliveryLogs.slice(0, 5).map(d => ({
            time: d.createdAt,
            color: d.status === 'sent' ? '#22c55e' : d.status === 'failed' ? '#ef4444' : '#f59e0b',
            icon: DELIVERY_ICONS[d.channelType] || <BellOutlined />,
            title: d.subject || 'Notification',
            desc: `${d.channelType} > ${d.recipient}`,
            type: 'notification' as const,
        })),
    ].sort((a, b) => dayjs(b.time).unix() - dayjs(a.time).unix()).slice(0, 8);

    const stats = [
        { title: 'Playbooks', value: playbooks.length, icon: <BookOutlined />, color: '#8b5cf6' },
        { title: 'Active Runs', value: activeRuns.length, icon: <RocketOutlined />, color: '#3b82f6' },
        { title: 'Pending', value: pendingRuns.length, icon: <ClockCircleOutlined />, color: '#f59e0b' },
        { title: 'Completed', value: completedRuns.length, icon: <CheckCircleOutlined />, color: '#22c55e' },
        { title: 'Overdue', value: overdueRuns.length, icon: <WarningOutlined />, color: '#ef4444' },
        { title: 'Schedules', value: activeSchedules.length, icon: <ScheduleOutlined />, color: '#06b6d4' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Operations</AuroraText>}
            subTitle={<DecryptedText text="Manage recurring operational workflows and task execution" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ops_dashboard', title: 'Operations Dashboard', columns: [{ header: 'Run', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Playbook', key: 'playbookName' }, { header: 'Priority', key: 'playbookPriority' }, { header: 'Created', key: 'createdAt' }], data: runs })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ops_dashboard', title: 'Operations Dashboard', columns: [{ header: 'Run', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Playbook', key: 'playbookName' }, { header: 'Priority', key: 'playbookPriority' }, { header: 'Created', key: 'createdAt' }], data: runs })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Spin spinning={loading}>
                {/* Stats Row (BENTO GRID) */}
                <BentoGrid className="mb-6 max-w-full">
                    <BentoGridItem
                        title="Completion Rate"
                        description={`${completedRuns.length} of ${runs.length} runs completed`}
                        icon={<BarChartOutlined style={{ color: '#3b82f6' }} />}
                        header={
                            <div className="flex flex-col h-full w-full items-center justify-center rounded-xl bg-blue-500/10">
                                <AnimatedCircularProgressBar
                                    max={100}
                                    min={0}
                                    value={completionRate}
                                    gaugePrimaryColor={completionRate >= 80 ? "#22c55e" : "#3b82f6"}
                                    gaugeSecondaryColor="rgba(59, 130, 246, 0.1)"
                                    className="w-[80px] h-[80px] scale-90"
                                />
                                <div style={{ fontSize: 11, marginTop: 4, color: completionRate >= 80 ? "#22c55e" : "#3b82f6", fontWeight: 600 }}>System Health</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Playbooks"
                        description="Active operational workflows"
                        icon={<BookOutlined style={{ color: '#8b5cf6' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-purple-500/10" onClick={() => router.push('/admin/ops/playbooks')} style={{ cursor: 'pointer' }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#8b5cf6' }}>{playbooks.length}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Active Runs"
                        description="Currently executing"
                        icon={<RocketOutlined style={{ color: '#3b82f6' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-blue-500/10" onClick={() => router.push('/admin/ops/runs')} style={{ cursor: 'pointer' }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#3b82f6' }}>{activeRuns.length}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                    <BentoGridItem
                        title="Overdue"
                        description="Requires immediate action"
                        icon={<WarningOutlined style={{ color: '#ef4444' }} />}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl bg-red-500/10" onClick={() => router.push('/admin/ops/runs')} style={{ cursor: 'pointer' }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: '#ef4444' }}>{overdueRuns.length}</div>
                            </div>
                        }
                        className="col-span-3 lg:col-span-1"
                    />
                </BentoGrid>

                {/* Row 1: Active Runs */}
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>

                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.35 }}>
                            <Card title={<Space><RocketOutlined style={{ color: '#3b82f6' }} /> Active Runs</Space>} size="small" style={glass}
                                extra={<Button type="link" size="small" onClick={() => router.push('/admin/ops/runs')}>View All <ArrowRightOutlined /></Button>}>
                                {activeRuns.length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No active runs" />
                                ) : (
                                    <List
                                        size="small"
                                        dataSource={activeRuns.slice(0, 5)}
                                        renderItem={(run: any) => (
                                            <List.Item style={{ cursor: 'pointer' }} onClick={() => router.push(`/admin/ops/runs/${run.id}`)}>
                                                <List.Item.Meta
                                                    avatar={<ThunderboltOutlined style={{ color: '#3b82f6', fontSize: 18 }} />}
                                                    title={<Text strong style={{ fontSize: 13, color: '#7c3aed' }}>{run.name}</Text>}
                                                    description={
                                                        <Space size={4}>
                                                            <Tag color={PRIORITY_COLORS[run.playbookPriority] || '#94a3b8'} style={{ fontSize: 10 }}>{run.playbookPriority}</Tag>
                                                            <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(run.createdAt).fromNow()}</Text>
                                                        </Space>
                                                    }
                                                />
                                            </List.Item>
                                        )}
                                    />
                                )}
                            </Card>
                        </motion.div>
                    </Col>

                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                            <Card title={<Space><WarningOutlined style={{ color: '#ef4444' }} /> Overdue Tasks</Space>} size="small" style={{ ...glass, borderTop: overdueRuns.length > 0 ? '3px solid #ef4444' : undefined }}>
                                {overdueRuns.length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="All on track!" />
                                ) : (
                                    <List
                                        size="small"
                                        dataSource={overdueRuns.slice(0, 5)}
                                        renderItem={(run: any) => (
                                            <List.Item style={{ cursor: 'pointer' }} onClick={() => router.push(`/admin/ops/runs/${run.id}`)}>
                                                <List.Item.Meta
                                                    avatar={<WarningOutlined style={{ color: '#ef4444' }} />}
                                                    title={<Text strong style={{ fontSize: 13, color: '#7c3aed' }}>{run.name}</Text>}
                                                    description={<Text type="danger" style={{ fontSize: 11 }}>Due {dayjs(run.dueAt).fromNow()}</Text>}
                                                />
                                            </List.Item>
                                        )}
                                    />
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Row 2: Category Distribution + Priority + Schedule Health */}
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.45 }}>
                            <Card title={<Space><BookOutlined /> Playbook Categories</Space>} size="small" style={glass}>
                                {Object.entries(categoryMap).length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No playbooks" />
                                ) : (
                                    <Space direction="vertical" style={{ width: '100%' }} size={8}>
                                        {Object.entries(categoryMap).sort((a, b) => b[1] - a[1]).map(([cat, count]) => (
                                            <div key={cat}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 2 }}>
                                                    <Text style={{ fontSize: 12, textTransform: 'capitalize' }}>{cat}</Text>
                                                    <Text type="secondary" style={{ fontSize: 11 }}>{count}</Text>
                                                </div>
                                                <Progress
                                                    percent={Math.round((count / totalPb) * 100)}
                                                    showInfo={false}
                                                    strokeColor={CATEGORY_COLORS[cat.toLowerCase()] || '#94a3b8'}
                                                    size="small"
                                                />
                                            </div>
                                        ))}
                                    </Space>
                                )}
                            </Card>
                        </motion.div>
                    </Col>

                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}>
                            <Card title={<Space><ThunderboltOutlined /> Priority Distribution</Space>} size="small" style={glass}>
                                <div style={{ display: 'flex', justifyContent: 'space-around', padding: '16px 0' }}>
                                    {['critical', 'high', 'medium', 'low'].map(pri => (
                                        <div key={pri} style={{ textAlign: 'center' }}>
                                            <Progress
                                                type="circle"
                                                percent={Math.round(((priorityMap[pri] || 0) / totalPb) * 100)}
                                                size={60}
                                                strokeColor={PRIORITY_COLORS[pri]}
                                                format={() => priorityMap[pri] || 0}
                                            />
                                            <div style={{ marginTop: 6 }}>
                                                <Tag color={PRIORITY_COLORS[pri]} style={{ fontSize: 10, textTransform: 'capitalize' }}>{pri}</Tag>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </Card>
                        </motion.div>
                    </Col>

                    <Col xs={24} md={8}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.55 }}>
                            <Card title={<Space><ScheduleOutlined style={{ color: '#06b6d4' }} /> Schedule Health</Space>} size="small" style={glass}>
                                {schedules.length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No schedules" />
                                ) : (
                                    <List
                                        size="small"
                                        dataSource={schedules.slice(0, 5)}
                                        renderItem={(sch: any) => (
                                            <List.Item>
                                                <List.Item.Meta
                                                    avatar={
                                                        <div style={{ width: 8, height: 8, borderRadius: '50%', background: sch.isActive ? '#22c55e' : '#94a3b8', marginTop: 6 }} />
                                                    }
                                                    title={<Text strong style={{ fontSize: 12 }}>{sch.name}</Text>}
                                                    description={
                                                        <Space size={4}>
                                                            <Tag style={{ fontSize: 10 }}>{sch.cronExpression}</Tag>
                                                            {sch.nextRunAt && (
                                                                <Text type="secondary" style={{ fontSize: 10 }}>
                                                                    Next: {dayjs(sch.nextRunAt).fromNow()}
                                                                </Text>
                                                            )}
                                                        </Space>
                                                    }
                                                />
                                            </List.Item>
                                        )}
                                    />
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Row 2.25: Execution Duration Trends */}
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    <Col xs={24}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.56 }}>
                            <Card title={<Space><BarChartOutlined /> Execution Duration Trends</Space>} size="small" style={glass}
                                extra={<Button type="link" size="small" onClick={() => router.push('/admin/ops/history')}>View History <ArrowRightOutlined /></Button>}>
                                {(() => {
                                    // Compute avg duration per playbook from completed runs
                                    const pbDurations: Record<string, { totalMin: number; count: number; max: number }> = {};
                                    runs.filter(r => r.startedAt && r.completedAt && r.status === 'completed').forEach(r => {
                                        const name = r.playbookName || 'Unknown';
                                        const mins = dayjs(r.completedAt).diff(dayjs(r.startedAt), 'minute');
                                        if (!pbDurations[name]) pbDurations[name] = { totalMin: 0, count: 0, max: 0 };
                                        pbDurations[name].totalMin += mins;
                                        pbDurations[name].count++;
                                        pbDurations[name].max = Math.max(pbDurations[name].max, mins);
                                    });
                                    const entries = Object.entries(pbDurations).sort((a, b) => (b[1].totalMin / b[1].count) - (a[1].totalMin / a[1].count));
                                    const maxAvg = entries.length > 0 ? Math.max(...entries.map(([, v]) => v.totalMin / v.count)) : 1;

                                    if (entries.length === 0) return <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No completed runs with duration data" />;
                                    return (
                                        <Space direction="vertical" style={{ width: '100%' }} size={8}>
                                            {entries.map(([name, stats]) => {
                                                const avg = Math.round(stats.totalMin / stats.count);
                                                const pct = Math.round((avg / maxAvg) * 100);
                                                // Find matching playbook for estimated time
                                                const pb = playbooks.find(p => p.name === name);
                                                const est = pb?.estimatedMinutes || 0;
                                                const isOverEstimate = est > 0 && avg > est * 1.2;
                                                return (
                                                    <div key={name}>
                                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 2 }}>
                                                            <Space size={6}>
                                                                <BookOutlined style={{ color: '#8b5cf6', fontSize: 12 }} />
                                                                <Text style={{ fontSize: 12 }}>{name}</Text>
                                                                {isOverEstimate && (
                                                                    <Tooltip title={`Avg ${avg} min exceeds estimate of ${est} min`}>
                                                                        <Tag color="red" style={{ fontSize: 9 }}>Slow</Tag>
                                                                    </Tooltip>
                                                                )}
                                                            </Space>
                                                            <Space size={8}>
                                                                <Text type="secondary" style={{ fontSize: 11 }}>Avg: {avg} min</Text>
                                                                <Text type="secondary" style={{ fontSize: 10 }}>({stats.count} runs)</Text>
                                                                {est > 0 && <Tag style={{ fontSize: 9 }}>Est: {est}m</Tag>}
                                                            </Space>
                                                        </div>
                                                        <Progress
                                                            percent={pct}
                                                            showInfo={false}
                                                            strokeColor={isOverEstimate ? '#ef4444' : avg > 60 ? '#f59e0b' : '#22c55e'}
                                                            size="small"
                                                        />
                                                    </div>
                                                );
                                            })}
                                        </Space>
                                    );
                                })()}
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Row 2.5: Communication Health + Quick Actions */}
                <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    <Col xs={24} md={12}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.58 }}>
                            <Card title={<Space><SendOutlined /> Communication Health</Space>} size="small" style={glass}
                                extra={<Button type="link" size="small" onClick={() => router.push('/admin/notifications/analytics')}>Details <ArrowRightOutlined /></Button>}>
                                {notifStats ? (
                                    <Row gutter={[12, 8]}>
                                        <Col span={8} style={{ textAlign: 'center' }}>
                                            <Progress type="circle" percent={notifStats.totalLogs > 0 ? Math.round((notifStats.sentLogs / notifStats.totalLogs) * 100) : 0} size={64}
                                                strokeColor={notifStats.totalLogs > 0 && (notifStats.sentLogs / notifStats.totalLogs) >= 0.8 ? '#22c55e' : '#f59e0b'} />
                                            <div style={{ marginTop: 4 }}><Text type="secondary" style={{ fontSize: 10 }}>Success Rate</Text></div>
                                        </Col>
                                        <Col span={16}>
                                            <Space direction="vertical" size={2} style={{ width: '100%' }}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <Text style={{ fontSize: 11 }}>Dispatched</Text>
                                                    <Text strong style={{ fontSize: 11 }}>{notifStats.totalLogs}</Text>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <Text style={{ fontSize: 11, color: '#22c55e' }}>Delivered</Text>
                                                    <Text strong style={{ fontSize: 11, color: '#22c55e' }}>{notifStats.sentLogs}</Text>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <Text style={{ fontSize: 11, color: '#ef4444' }}>Failed</Text>
                                                    <Text strong style={{ fontSize: 11, color: '#ef4444' }}>{notifStats.failedLogs}</Text>
                                                </div>
                                                <Divider style={{ margin: '4px 0' }} />
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <Text style={{ fontSize: 11 }}>Channels Active</Text>
                                                    <Tag color="blue" style={{ fontSize: 10 }}>{notifStats.activeChannels}</Tag>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <Text style={{ fontSize: 11 }}>Unread Inbox</Text>
                                                    <Tag color={notifStats.unreadNotifications > 0 ? 'orange' : 'green'} style={{ fontSize: 10 }}>{notifStats.unreadNotifications}</Tag>
                                                </div>
                                            </Space>
                                        </Col>
                                    </Row>
                                ) : (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No notification data" />
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                    <Col xs={24} md={12}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.58 }}>
                            <Card title={<Space><PlayCircleOutlined /> Quick Actions</Space>} size="small" style={glass}>
                                <Space wrap>
                                    <Button type="primary" icon={<PlusOutlined />} onClick={() => router.push('/admin/ops/runs')}>
                                        New Run
                                    </Button>
                                    <Button icon={<BookOutlined />} onClick={() => router.push('/admin/ops/playbooks')}>
                                        Manage Playbooks
                                    </Button>
                                    <Button icon={<ScheduleOutlined />} onClick={() => router.push('/admin/ops/schedules')}>
                                        View Schedules
                                    </Button>
                                    <Button icon={<ClockCircleOutlined />} onClick={() => router.push('/admin/ops/history')}>
                                        Run History
                                    </Button>
                                    <Button icon={<InboxOutlined />} onClick={() => router.push('/admin/notifications/inbox')}>
                                        Notification Inbox
                                    </Button>
                                </Space>
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* Row 3: Activity Timeline */}
                <Row gutter={[16, 16]}>
                    <Col xs={24}>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.6 }}>
                            <Card title={<Space><ClockCircleOutlined /> Recent Activity</Space>} size="small" style={glass}>
                                {activityItems.length === 0 ? (
                                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No recent activity" />
                                ) : (
                                    <Timeline
                                        mode="left"
                                        items={activityItems.map(item => ({
                                            color: item.color,
                                            dot: item.icon,
                                            children: (
                                                <div>
                                                    <Space size={8}>
                                                        <Tag color={item.type === 'run' ? 'blue' : 'purple'} style={{ fontSize: 10 }}>
                                                            {item.type === 'run' ? 'OPS RUN' : 'NOTIFICATION'}
                                                        </Tag>
                                                        <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(item.time).fromNow()}</Text>
                                                    </Space>
                                                    <div><Text strong style={{ fontSize: 13 }}>{item.title}</Text></div>
                                                    <Text type="secondary" style={{ fontSize: 11 }}>{item.desc}</Text>
                                                </div>
                                            ),
                                        }))}
                                    />
                                )}
                            </Card>
                        </motion.div>
                    </Col>
                </Row>
            </Spin>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Card, message, Typography, Row, Col, Statistic,
    Select, Tooltip, Progress, Empty,
} from "antd";
import { motion } from "framer-motion";
import {
    ReloadOutlined, CheckCircleOutlined, ClockCircleOutlined,
    WarningOutlined, FileExcelOutlined, FilePdfOutlined,
    BarChartOutlined, RocketOutlined, ExclamationCircleOutlined,
    StopOutlined, BookOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import duration from "dayjs/plugin/duration";

dayjs.extend(relativeTime);
dayjs.extend(duration);
const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const STATUS_ICONS: Record<string, React.ReactNode> = {
    completed: <CheckCircleOutlined style={{ color: '#22c55e' }} />,
    failed: <ExclamationCircleOutlined style={{ color: '#ef4444' }} />,
    cancelled: <StopOutlined style={{ color: '#6b7280' }} />,
};
const STATUS_COLORS: Record<string, string> = {
    completed: 'success', failed: 'error', cancelled: 'warning',
};
const PRIORITY_COLORS: Record<string, string> = {
    critical: '#ef4444', high: '#f59e0b', medium: '#3b82f6', low: '#94a3b8',
};

export default function HistoryPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [runs, setRuns] = useState<any[]>([]);
    const [allRuns, setAllRuns] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [filterStatus, setFilterStatus] = useState<string | undefined>();
    const [filterPlaybook, setFilterPlaybook] = useState<string | undefined>();

    const loadRuns = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($t: String!) { opsRuns(tenantId: $t) {
                id name status playbookId playbookName playbookPriority startedBy startedAt completedAt dueAt createdAt
            } }`, { t: DEFAULT_TENANT_ID });
            const completed = (data.opsRuns || []).filter((r: any) => ['completed', 'cancelled', 'failed'].includes(r.status));
            setAllRuns(completed);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadRuns(); }, [loadRuns]);

    // Apply filters
    useEffect(() => {
        let filtered = [...allRuns];
        if (filterStatus) filtered = filtered.filter(r => r.status === filterStatus);
        if (filterPlaybook) filtered = filtered.filter(r => r.playbookName === filterPlaybook);
        setRuns(filtered);
    }, [allRuns, filterStatus, filterPlaybook]);

    const completedCount = allRuns.filter(r => r.status === 'completed').length;
    const cancelledCount = allRuns.filter(r => r.status === 'cancelled').length;
    const failedCount = allRuns.filter(r => r.status === 'failed').length;
    const successRate = allRuns.length > 0 ? Math.round((completedCount / allRuns.length) * 100) : 0;

    const avgDuration = (() => {
        const withDuration = allRuns.filter(r => r.startedAt && r.completedAt);
        if (!withDuration.length) return 'N/A';
        const total = withDuration.reduce((s, r) => s + dayjs(r.completedAt).diff(dayjs(r.startedAt), 'minute'), 0);
        return `${Math.round(total / withDuration.length)} min`;
    })();

    // Playbook breakdown
    const playbookMap: Record<string, { count: number; completed: number; failed: number; totalMin: number }> = {};
    allRuns.forEach(r => {
        const name = r.playbookName || 'Unknown';
        if (!playbookMap[name]) playbookMap[name] = { count: 0, completed: 0, failed: 0, totalMin: 0 };
        playbookMap[name].count++;
        if (r.status === 'completed') playbookMap[name].completed++;
        if (r.status === 'failed') playbookMap[name].failed++;
        if (r.startedAt && r.completedAt) {
            playbookMap[name].totalMin += dayjs(r.completedAt).diff(dayjs(r.startedAt), 'minute');
        }
    });
    const playbookBreakdown = Object.entries(playbookMap).sort((a, b) => b[1].count - a[1].count);
    const maxPbCount = playbookBreakdown.length > 0 ? playbookBreakdown[0][1].count : 1;
    const playbookOptions = playbookBreakdown.map(([name]) => ({ label: name, value: name }));

    const columns: ColumnsType<any> = [
        {
            title: "Run", key: "name", width: 280,
            sorter: (a, b) => a.name.localeCompare(b.name),
            render: (_, r) => (
                <div style={{ cursor: 'pointer' }} onClick={() => router.push(`/admin/ops/runs/${r.id}`)}>
                    <Text strong style={{ color: '#7c3aed', fontSize: 13 }}>{r.name}</Text><br />
                    <Space size={4}>
                        <BookOutlined style={{ color: '#94a3b8', fontSize: 11 }} />
                        <Text type="secondary" style={{ fontSize: 11 }}>{r.playbookName}</Text>
                        {r.playbookPriority && <Tag color={PRIORITY_COLORS[r.playbookPriority]} style={{ fontSize: 9 }}>{r.playbookPriority}</Tag>}
                    </Space>
                </div>
            ),
        },
        {
            title: "Status", dataIndex: "status", width: 110, align: 'center',
            filters: [
                { text: 'Completed', value: 'completed' },
                { text: 'Failed', value: 'failed' },
                { text: 'Cancelled', value: 'cancelled' },
            ],
            onFilter: (val, r) => r.status === val,
            render: (v: string) => (
                <Tag color={STATUS_COLORS[v] || 'default'} icon={STATUS_ICONS[v]} style={{ textTransform: 'capitalize' }}>
                    {v}
                </Tag>
            ),
        },
        {
            title: "Duration", key: "duration", width: 100, align: 'right',
            sorter: (a, b) => {
                const dA = a.startedAt && a.completedAt ? dayjs(a.completedAt).diff(dayjs(a.startedAt)) : 0;
                const dB = b.startedAt && b.completedAt ? dayjs(b.completedAt).diff(dayjs(b.startedAt)) : 0;
                return dA - dB;
            },
            render: (_, r) => {
                if (!r.startedAt || !r.completedAt) return <Text type="secondary">-</Text>;
                const mins = dayjs(r.completedAt).diff(dayjs(r.startedAt), 'minute');
                return <Text style={{ fontSize: 12 }}>{mins < 60 ? `${mins} min` : `${Math.floor(mins / 60)}h ${mins % 60}m`}</Text>;
            },
        },
        {
            title: "Completed", key: "completedAt", width: 150,
            sorter: (a, b) => dayjs(a.completedAt || 0).unix() - dayjs(b.completedAt || 0).unix(),
            defaultSortOrder: 'descend',
            render: (_, r) => r.completedAt ? (
                <Tooltip title={dayjs(r.completedAt).format('YYYY-MM-DD HH:mm:ss')}>
                    <Text style={{ fontSize: 12 }}>{dayjs(r.completedAt).format('MMM D, HH:mm')}</Text>
                </Tooltip>
            ) : '-',
        },
        { title: "Started By", dataIndex: "startedBy", width: 120, render: (v: string) => v || '-' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>History</AuroraText>}
            subTitle={<DecryptedText text="Completed operational runs with duration analytics and outcome tracking" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadRuns} />,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ops_history', title: 'Operations History', columns: [{ header: 'Run', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Playbook', key: 'playbookName' }, { header: 'Started By', key: 'startedBy' }, { header: 'Completed', key: 'completedAt' }], data: runs })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ops_history', title: 'Operations History', columns: [{ header: 'Run', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Playbook', key: 'playbookName' }, { header: 'Started By', key: 'startedBy' }], data: runs })} /></Tooltip></RbacGuard>,
            ]}
        >
            {/* Stats Row */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Runs', value: allRuns.length, icon: <RocketOutlined />, color: '#8b5cf6' },
                    { title: 'Completed', value: completedCount, icon: <CheckCircleOutlined />, color: '#22c55e' },
                    { title: 'Failed', value: failedCount, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'Cancelled', value: cancelledCount, icon: <StopOutlined />, color: '#f59e0b' },
                    { title: 'Success Rate', value: successRate, suffix: '%', icon: <BarChartOutlined />, color: '#10b981' },
                    { title: 'Avg Duration', value: avgDuration, icon: <ClockCircleOutlined />, color: '#3b82f6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} suffix={(s as any).suffix} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20 }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Playbook Breakdown */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.25 }}>
                        <Card title={<Space><BarChartOutlined /> Runs by Playbook</Space>} size="small" style={glass}>
                            {playbookBreakdown.length === 0 ? (
                                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No historical runs" />
                            ) : (
                                <Space direction="vertical" style={{ width: '100%' }} size={6}>
                                    {playbookBreakdown.map(([name, stats]) => {
                                        const totalTime = stats.totalMin < 60 ? `${stats.totalMin}m` : `${Math.floor(stats.totalMin / 60)}h ${stats.totalMin % 60}m`;
                                        return (
                                            <div key={name}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 2 }}>
                                                    <Space size={6}>
                                                        <BookOutlined style={{ color: '#8b5cf6' }} />
                                                        <Text style={{ fontSize: 12 }}>{name}</Text>
                                                    </Space>
                                                    <Space size={8}>
                                                        <Tag color="green" style={{ fontSize: 10 }}>{stats.completed} ok</Tag>
                                                        {stats.failed > 0 && <Tag color="red" style={{ fontSize: 10 }}>{stats.failed} fail</Tag>}
                                                        <Text type="secondary" style={{ fontSize: 10 }}>{totalTime}</Text>
                                                    </Space>
                                                </div>
                                                <Progress
                                                    percent={Math.round((stats.count / maxPbCount) * 100)}
                                                    showInfo={false}
                                                    strokeColor={stats.failed > 0 ? '#f59e0b' : '#8b5cf6'}
                                                    size="small"
                                                />
                                            </div>
                                        );
                                    })}
                                </Space>
                            )}
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Filters */}
            <Card size="small" style={{ marginBottom: 16 }}>
                <Space wrap>
                    <Select placeholder="Filter by status" allowClear style={{ width: 160 }} value={filterStatus} onChange={setFilterStatus}
                        options={[{ label: 'Completed', value: 'completed' }, { label: 'Cancelled', value: 'cancelled' }, { label: 'Failed', value: 'failed' }]} />
                    <Select placeholder="Filter by playbook" allowClear style={{ width: 220 }} value={filterPlaybook} onChange={setFilterPlaybook}
                        options={playbookOptions} />
                    {(filterStatus || filterPlaybook) && (
                        <Button type="link" onClick={() => { setFilterStatus(undefined); setFilterPlaybook(undefined); }}>
                            Clear filters
                        </Button>
                    )}
                </Space>
            </Card>

            {/* Table */}
            <Card>
                <Table
                    columns={columns}
                    dataSource={runs.map(r => ({ ...r, key: r.id }))}
                    loading={loading}
                    pagination={{ pageSize: 20, showTotal: (t) => `${t} historical runs` }}
                    size="middle"
                    scroll={{ x: 800 }}
                />
            </Card>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useParams, useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Card, Row, Col, Tag, Space, Typography, Spin, Steps, List, Empty,
    Button, Tooltip, Descriptions, Badge, Timeline, Divider, Modal, message,
} from "antd";
import { motion } from "framer-motion";
import {
    BookOutlined, OrderedListOutlined, ClockCircleOutlined,
    PlayCircleOutlined, CheckCircleOutlined, ArrowLeftOutlined,
    ThunderboltOutlined, ExclamationCircleOutlined, StopOutlined,
    UserOutlined, CalendarOutlined, RocketOutlined,
    EditOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);
const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const PRIORITY_COLORS: Record<string, string> = { critical: '#ef4444', high: '#f59e0b', medium: '#3b82f6', low: '#94a3b8' };
const STATUS_COLORS: Record<string, string> = {
    pending: '#94a3b8', in_progress: '#3b82f6', completed: '#22c55e', failed: '#ef4444', cancelled: '#6b7280',
};
const STEP_TYPE_CONFIG: Record<string, { color: string; icon: React.ReactNode }> = {
    task: { color: '#3b82f6', icon: <CheckCircleOutlined /> },
    approval: { color: '#f59e0b', icon: <ExclamationCircleOutlined /> },
    check: { color: '#22c55e', icon: <CheckCircleOutlined /> },
    notification: { color: '#8b5cf6', icon: <ThunderboltOutlined /> },
};

export default function PlaybookDetailPage() {
    const { themeColor } = usePreferencesStore();
    const params = useParams();
    const router = useRouter();
    const playbookId = params.id as string;

    const [playbook, setPlaybook] = useState<any>(null);
    const [steps, setSteps] = useState<any[]>([]);
    const [runs, setRuns] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    const loadData = useCallback(async () => {
        if (!playbookId) return;
        setLoading(true);
        try {
            const [pbData, stepsData, runsData] = await Promise.all([
                gql(`query($t: String!) { opsPlaybooks(tenantId: $t) {
                    id name description category priority estimatedMinutes tags isActive createdBy createdAt
                } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($pbId: String!) { opsPlaybookSteps(playbookId: $pbId) {
                    id playbookId stepOrder title description stepType isRequired defaultAssigneeId estimatedMinutes
                } }`, { pbId: playbookId }),
                gql(`query($t: String!) { opsRuns(tenantId: $t) {
                    id name status playbookId playbookName playbookPriority startedAt completedAt dueAt createdAt
                } }`, { t: DEFAULT_TENANT_ID }),
            ]);
            const pb = (pbData.opsPlaybooks || []).find((p: any) => p.id === playbookId);
            setPlaybook(pb || null);
            setSteps((stepsData.opsPlaybookSteps || []).sort((a: any, b: any) => a.stepOrder - b.stepOrder));
            setRuns((runsData.opsRuns || []).filter((r: any) => r.playbookId === playbookId));
        } catch (e: any) { message.error(e.message); }
        finally { setLoading(false); }
    }, [playbookId]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleStartRun = async () => {
        if (!playbook) return;
        try {
            const res = await gql(`mutation($t: String!, $pbId: String!, $name: String!) {
                createOpsRun(tenantId: $t, playbookId: $pbId, name: $name) { id }
            }`, { t: DEFAULT_TENANT_ID, pbId: playbook.id, name: `${playbook.name} - ${dayjs().format('MMM D HH:mm')}` });
            message.success("Run started!");
            router.push(`/admin/ops/runs/${res.createOpsRun.id}`);
        } catch (e: any) { message.error(e.message); }
    };

    const completedRuns = runs.filter(r => r.status === 'completed').length;
    const failedRuns = runs.filter(r => r.status === 'failed').length;
    const activeRuns = runs.filter(r => r.status === 'in_progress').length;
    const totalEstMinutes = steps.reduce((s, st) => s + (st.estimatedMinutes || 0), 0);

    if (loading) return (
        <CMSLayout title="Loading...">
            <div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" /></div>
        </CMSLayout>
    );

    if (!playbook) return (
        <CMSLayout title="Not Found">
            <Empty description="Playbook not found" />
            <div style={{ textAlign: 'center', marginTop: 16 }}>
                <Button onClick={() => router.push('/admin/ops/playbooks')}>Back to Playbooks</Button>
            </div>
        </CMSLayout>
    );

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#8b5cf6", "#a78bfa"]}>{playbook.name}</AuroraText>}
            subTitle={<DecryptedText text={playbook.description || 'Operational playbook template'} animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="back" icon={<ArrowLeftOutlined />} onClick={() => router.push('/admin/ops/playbooks')}>Back</Button>,
                <Button key="run" type="primary" icon={<PlayCircleOutlined />}
                    onClick={() => Modal.confirm({ title: `Start new run from "${playbook.name}"?`, onOk: handleStartRun })}>
                    Start Run
                </Button>,
            ]}
        >
            {/* Top Meta Row */}
            <Row gutter={[12, 12]} style={{ marginBottom: 20 }}>
                {[
                    { title: 'Steps', value: steps.length, icon: <OrderedListOutlined />, color: '#8b5cf6' },
                    { title: 'Est. Duration', value: totalEstMinutes ? `${totalEstMinutes} min` : 'N/A', icon: <ClockCircleOutlined />, color: '#f59e0b' },
                    { title: 'Total Runs', value: runs.length, icon: <RocketOutlined />, color: '#3b82f6' },
                    { title: 'Completed', value: completedRuns, icon: <CheckCircleOutlined />, color: '#22c55e' },
                    { title: 'Failed', value: failedRuns, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { title: 'Active', value: activeRuns, icon: <ThunderboltOutlined />, color: '#06b6d4' },
                ].map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}`, textAlign: 'center' }}>
                                <div style={{ fontSize: 11, color: '#64748b', marginBottom: 2 }}>{s.title}</div>
                                <div style={{ fontSize: 20, fontWeight: 700, color: s.color }}>{React.isValidElement(s.icon) && <span style={{ marginRight: 6 }}>{s.icon}</span>}{s.value}</div>
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                {/* Playbook Info */}
                <Col xs={24} md={8}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.25 }}>
                        <Card title={<Space><BookOutlined /> Playbook Details</Space>} size="small" style={glass}>
                            <Descriptions column={1} size="small" labelStyle={{ fontWeight: 600, fontSize: 11 }} contentStyle={{ fontSize: 12 }}>
                                <Descriptions.Item label="Category">
                                    <Tag style={{ textTransform: 'capitalize' }}>{playbook.category}</Tag>
                                </Descriptions.Item>
                                <Descriptions.Item label="Priority">
                                    <Tag color={PRIORITY_COLORS[playbook.priority]}>{playbook.priority}</Tag>
                                </Descriptions.Item>
                                <Descriptions.Item label="Status">
                                    <Badge status={playbook.isActive ? 'success' : 'default'} text={playbook.isActive ? 'Active' : 'Inactive'} />
                                </Descriptions.Item>
                                <Descriptions.Item label="Est. Duration">
                                    {playbook.estimatedMinutes ? `${playbook.estimatedMinutes} min` : 'Not set'}
                                </Descriptions.Item>
                                <Descriptions.Item label="Created By">
                                    <Space size={4}><UserOutlined />{playbook.createdBy || 'system'}</Space>
                                </Descriptions.Item>
                                <Descriptions.Item label="Created">
                                    <Space size={4}><CalendarOutlined />{dayjs(playbook.createdAt).format('MMM D, YYYY')}</Space>
                                </Descriptions.Item>
                            </Descriptions>
                        </Card>
                    </motion.div>
                </Col>

                {/* Step Pipeline */}
                <Col xs={24} md={16}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                        <Card title={<Space><OrderedListOutlined /> Step Pipeline ({steps.length} steps)</Space>} size="small" style={glass}>
                            {steps.length === 0 ? (
                                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No steps defined. Add steps from the Playbooks page." />
                            ) : (
                                <Steps
                                    direction="vertical"
                                    size="small"
                                    current={-1}
                                    items={steps.map((st, idx) => {
                                        const cfg = STEP_TYPE_CONFIG[st.stepType] || STEP_TYPE_CONFIG.task;
                                        return {
                                            title: (
                                                <Space>
                                                    <Text strong style={{ fontSize: 13 }}>{st.title}</Text>
                                                    {st.isRequired && <Tag color="red" style={{ fontSize: 9 }}>Required</Tag>}
                                                </Space>
                                            ),
                                            description: (
                                                <Space size={6} wrap>
                                                    <Tag color={cfg.color} style={{ fontSize: 10 }}>{st.stepType}</Tag>
                                                    {st.estimatedMinutes > 0 && <Text type="secondary" style={{ fontSize: 11 }}>{st.estimatedMinutes} min</Text>}
                                                    {st.description && <Text type="secondary" style={{ fontSize: 11 }}>- {st.description}</Text>}
                                                </Space>
                                            ),
                                            icon: <div style={{
                                                width: 24, height: 24, borderRadius: '50%',
                                                background: cfg.color, color: '#fff',
                                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                fontSize: 12, fontWeight: 700,
                                            }}>{idx + 1}</div>,
                                        };
                                    })}
                                />
                            )}
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Run History */}
            <Row gutter={[16, 16]}>
                <Col xs={24}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.4 }}>
                        <Card title={<Space><RocketOutlined /> Run History ({runs.length})</Space>} size="small" style={glass}>
                            {runs.length === 0 ? (
                                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No runs yet. Start one above!" />
                            ) : (
                                <List
                                    size="small"
                                    dataSource={runs.sort((a: any, b: any) => dayjs(b.createdAt).unix() - dayjs(a.createdAt).unix())}
                                    renderItem={(run: any) => (
                                        <List.Item
                                            style={{ cursor: 'pointer' }}
                                            onClick={() => router.push(`/admin/ops/runs/${run.id}`)}
                                            actions={[
                                                <Tag key="s" color={STATUS_COLORS[run.status]} style={{ fontSize: 10 }}>
                                                    {run.status.replace('_', ' ')}
                                                </Tag>,
                                            ]}
                                        >
                                            <List.Item.Meta
                                                avatar={
                                                    run.status === 'completed' ? <CheckCircleOutlined style={{ color: '#22c55e', fontSize: 18 }} /> :
                                                    run.status === 'in_progress' ? <ThunderboltOutlined style={{ color: '#3b82f6', fontSize: 18 }} /> :
                                                    run.status === 'failed' ? <ExclamationCircleOutlined style={{ color: '#ef4444', fontSize: 18 }} /> :
                                                    run.status === 'cancelled' ? <StopOutlined style={{ color: '#6b7280', fontSize: 18 }} /> :
                                                    <ClockCircleOutlined style={{ color: '#94a3b8', fontSize: 18 }} />
                                                }
                                                title={<Text strong style={{ fontSize: 13, color: '#7c3aed' }}>{run.name}</Text>}
                                                description={
                                                    <Space size={8}>
                                                        <Text type="secondary" style={{ fontSize: 11 }}>
                                                            {dayjs(run.createdAt).format('MMM D, YYYY HH:mm')}
                                                        </Text>
                                                        {run.completedAt && (
                                                            <Text type="secondary" style={{ fontSize: 11 }}>
                                                                Duration: {dayjs(run.completedAt).diff(dayjs(run.startedAt || run.createdAt), 'minute')} min
                                                            </Text>
                                                        )}
                                                    </Space>
                                                }
                                            />
                                        </List.Item>
                                    )}
                                />
                            )}
                        </Card>
                    </motion.div>
                </Col>
            </Row>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Form, Input, Select, Card, Empty,
    message, Typography, Row, Col, Statistic, Tooltip, InputNumber, Drawer, List, Checkbox,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    BookOutlined, PlayCircleOutlined, OrderedListOutlined,
    ThunderboltOutlined, ClockCircleOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const PRIORITY_COLORS: Record<string, string> = { critical: 'red', high: 'orange', medium: 'blue', low: 'default' };
const STEP_TYPE_COLORS: Record<string, string> = { task: 'blue', approval: 'orange', check: 'green', notification: 'purple' };

const PLAYBOOK_FIELDS: FieldDef[] = [
    { name: "name", label: "Playbook Name", required: true },
    { name: "description", label: "Description" },
    { name: "category", label: "Category" },
];

export default function PlaybooksPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [playbooks, setPlaybooks] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingPb, setEditingPb] = useState<any>(null);
    const [form] = Form.useForm();

    // Steps drawer
    const [stepsDrawerOpen, setStepsDrawerOpen] = useState(false);
    const [selectedPb, setSelectedPb] = useState<any>(null);
    const [steps, setSteps] = useState<any[]>([]);
    const [stepsLoading, setStepsLoading] = useState(false);
    const [stepForm] = Form.useForm();
    const [stepModalOpen, setStepModalOpen] = useState(false);
    const [editingStep, setEditingStep] = useState<any>(null);

    const [runsMap, setRunsMap] = useState<Record<string, { count: number; totalMinutes: number }>>({}); 

    const loadPlaybooks = useCallback(async () => {
        setLoading(true);
        try {
            const [pbData, runData] = await Promise.all([
                gql(`query($t: String!) { opsPlaybooks(tenantId: $t) {
                    id name description category priority estimatedMinutes tags isActive createdBy createdAt
                } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!) { opsRuns(tenantId: $t) {
                    id playbookId startedAt completedAt status
                } }`, { t: DEFAULT_TENANT_ID }),
            ]);
            setPlaybooks(pbData.opsPlaybooks || []);
            // Build runs aggregation per playbook
            const map: Record<string, { count: number; totalMinutes: number }> = {};
            (runData.opsRuns || []).forEach((r: any) => {
                if (!r.playbookId) return;
                if (!map[r.playbookId]) map[r.playbookId] = { count: 0, totalMinutes: 0 };
                map[r.playbookId].count++;
                if (r.startedAt && r.completedAt) {
                    map[r.playbookId].totalMinutes += dayjs(r.completedAt).diff(dayjs(r.startedAt), 'minute');
                }
            });
            setRunsMap(map);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadPlaybooks(); }, [loadPlaybooks]);

    const loadSteps = async (playbookId: string) => {
        setStepsLoading(true);
        try {
            const data = await gql(`query($pbId: String!) { opsPlaybookSteps(playbookId: $pbId) {
                id playbookId stepOrder title description stepType isRequired defaultAssigneeId estimatedMinutes
            } }`, { pbId: playbookId });
            setSteps(data.opsPlaybookSteps || []);
        } catch (err: any) { message.error(err.message); }
        finally { setStepsLoading(false); }
    };

    const handleSave = async (values: any) => {
        try {
            if (editingPb) {
                await gql(`mutation($id: String!, $name: String, $description: String, $category: String, $priority: String, $estimatedMinutes: Float) {
                    updateOpsPlaybook(id: $id, name: $name, description: $description, category: $category, priority: $priority, estimatedMinutes: $estimatedMinutes) { id }
                }`, { id: editingPb.id, ...values });
                message.success("Playbook updated");
            } else {
                await gql(`mutation($t: String!, $name: String!, $description: String, $category: String, $priority: String, $estimatedMinutes: Float) {
                    createOpsPlaybook(tenantId: $t, name: $name, description: $description, category: $category, priority: $priority, estimatedMinutes: $estimatedMinutes) { id }
                }`, { t: DEFAULT_TENANT_ID, ...values });
                message.success("Playbook created");
            }
            setIsModalOpen(false); form.resetFields(); setEditingPb(null); loadPlaybooks();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($t: String!, $name: String!, $description: String, $category: String) {
                    createOpsPlaybook(tenantId: $t, name: $name, description: $description, category: $category) { id }
                }`, { t: DEFAULT_TENANT_ID, name: r.name, description: r.description, category: r.category });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadPlaybooks(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteOpsPlaybook(id: $id) }`, { id });
            message.success("Deleted"); loadPlaybooks();
        } catch (err: any) { message.error(err.message); }
    };

    const handleStartRun = async (pb: any) => {
        try {
            await gql(`mutation($t: String!, $pbId: String!, $name: String!) {
                createOpsRun(tenantId: $t, playbookId: $pbId, name: $name) { id }
            }`, { t: DEFAULT_TENANT_ID, pbId: pb.id, name: `${pb.name} — ${dayjs().format('MMM D HH:mm')}` });
            message.success("Run started!");
        } catch (err: any) { message.error(err.message); }
    };

    // Steps CRUD
    const handleSaveStep = async (values: any) => {
        try {
            if (editingStep) {
                await gql(`mutation($id: String!, $title: String, $description: String, $stepType: String, $stepOrder: Float, $isRequired: Boolean, $estimatedMinutes: Float) {
                    updateOpsPlaybookStep(id: $id, title: $title, description: $description, stepType: $stepType, stepOrder: $stepOrder, isRequired: $isRequired, estimatedMinutes: $estimatedMinutes) { id }
                }`, { id: editingStep.id, ...values });
                message.success("Step updated");
            } else {
                await gql(`mutation($pbId: String!, $title: String!, $description: String, $stepType: String, $stepOrder: Float, $isRequired: Boolean, $estimatedMinutes: Float) {
                    createOpsPlaybookStep(playbookId: $pbId, title: $title, description: $description, stepType: $stepType, stepOrder: $stepOrder, isRequired: $isRequired, estimatedMinutes: $estimatedMinutes) { id }
                }`, { pbId: selectedPb.id, ...values });
                message.success("Step added");
            }
            setStepModalOpen(false); stepForm.resetFields(); setEditingStep(null);
            loadSteps(selectedPb.id);
        } catch (err: any) { message.error(err.message); }
    };

    const handleDeleteStep = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteOpsPlaybookStep(id: $id) }`, { id });
            message.success("Step deleted"); loadSteps(selectedPb.id);
        } catch (err: any) { message.error(err.message); }
    };

    const columns: ColumnsType<any> = [
        {
            title: "Playbook", key: "name", width: 260,
            render: (_, r) => (
                <Space>
                    <BookOutlined style={{ fontSize: 20, color: PRIORITY_COLORS[r.priority] === 'red' ? '#ef4444' : '#8b5cf6' }} />
                    <div>
                        <Text strong style={{ color: '#7c3aed', cursor: 'pointer' }} onClick={() => router.push(`/admin/ops/playbooks/${r.id}`)}>{r.name}</Text>
                        {!r.isActive && <Tag color="default" style={{ marginLeft: 6 }}>Inactive</Tag>}
                        <br />
                        <Text type="secondary" style={{ fontSize: 11 }}>{r.description || 'No description'}</Text>
                    </div>
                </Space>
            ),
        },
        { title: "Category", dataIndex: "category", width: 120, render: (v: string) => <Tag style={{ textTransform: 'capitalize' }}>{v}</Tag> },
        { title: "Priority", dataIndex: "priority", width: 100, render: (v: string) => <Tag color={PRIORITY_COLORS[v]}>{v}</Tag> },
        { title: "Est. Time", dataIndex: "estimatedMinutes", width: 90, align: 'right' as const, render: (v: number) => v ? `${v} min` : '—' },
        {
            title: "Runs / Total Time", key: "runStats", width: 140, align: 'center' as const,
            render: (_: any, r: any) => {
                const stats = runsMap[r.id];
                if (!stats || stats.count === 0) return <Text type="secondary" style={{ fontSize: 11 }}>No runs</Text>;
                const totalTime = stats.totalMinutes < 60 ? `${stats.totalMinutes}m` : `${Math.floor(stats.totalMinutes / 60)}h ${stats.totalMinutes % 60}m`;
                return (
                    <Tooltip title={`${stats.count} runs, total execution: ${totalTime}`}>
                        <Tag color="blue" style={{ fontSize: 10 }}>{stats.count} runs</Tag>
                        <br />
                        <Text type="secondary" style={{ fontSize: 10 }}>{totalTime}</Text>
                    </Tooltip>
                );
            },
        },
        {
            title: "Actions", key: "actions", width: 200,
            render: (_, r) => (
                <Space>
                    <Tooltip title="View/Edit Steps">
                        <Button type="text" icon={<OrderedListOutlined />} onClick={() => {
                            setSelectedPb(r); setStepsDrawerOpen(true); loadSteps(r.id);
                        }} />
                    </Tooltip>
                    <Tooltip title="Start Run">
                        <Button type="text" icon={<PlayCircleOutlined style={{ color: '#22c55e' }} />}
                            onClick={() => Modal.confirm({ title: `Start "${r.name}"?`, onOk: () => handleStartRun(r) })} />
                    </Tooltip>
                    <Button type="text" icon={<EditOutlined />} onClick={() => {
                        setEditingPb(r); form.setFieldsValue(r); setIsModalOpen(true);
                    }} />
                    <Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({
                        title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id),
                    })} />
                </Space>
            ),
        },
    ];

    const formSteps = [{
        title: "Playbook Info", icon: <BookOutlined />, fields: ["name", "description", "category", "priority", "estimatedMinutes"],
        content: (
            <>
                <Form.Item name="name" label="Playbook Name" rules={[{ required: true }]}><Input placeholder="e.g., Daily Server Health Check" /></Form.Item>
                <Form.Item name="description" label="Description"><Input.TextArea rows={3} placeholder="Describe the operational workflow" /></Form.Item>
                <Row gutter={12}>
                    <Col span={8}>
                        <Form.Item name="category" label="Category" initialValue="general">
                            <Select options={['general','maintenance','compliance','onboarding','security','reporting'].map(c => ({ label: c, value: c }))} />
                        </Form.Item>
                    </Col>
                    <Col span={8}>
                        <Form.Item name="priority" label="Priority" initialValue="medium">
                            <Select options={['critical','high','medium','low'].map(p => ({ label: p, value: p }))} />
                        </Form.Item>
                    </Col>
                    <Col span={8}>
                        <Form.Item name="estimatedMinutes" label="Est. Minutes"><InputNumber min={0} style={{ width: '100%' }} /></Form.Item>
                    </Col>
                </Row>
            </>
        ),
    }];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Playbooks</AuroraText>}
            subTitle={<DecryptedText text="Reusable operational task templates with steps and assignees" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadPlaybooks} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditingPb(null); form.resetFields(); setIsModalOpen(true); }}>Create Playbook</Button>,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ops_playbooks', title: 'Playbooks', columns: [{ header: 'Name', key: 'name' }, { header: 'Category', key: 'category' }, { header: 'Priority', key: 'priority' }, { header: 'Est. Minutes', key: 'estimatedMinutes' }, { header: 'Active', key: 'isActive' }], data: playbooks })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ops_playbooks', title: 'Playbooks', columns: [{ header: 'Name', key: 'name' }, { header: 'Category', key: 'category' }, { header: 'Priority', key: 'priority' }, { header: 'Est. Minutes', key: 'estimatedMinutes' }], data: playbooks })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total', value: playbooks.length, icon: <BookOutlined />, color: '#8b5cf6' },
                    { title: 'Active', value: playbooks.filter(p => p.isActive).length, icon: <ThunderboltOutlined />, color: '#22c55e' },
                    { title: 'Avg Duration', value: playbooks.length ? `${Math.round(playbooks.reduce((s, p) => s + (p.estimatedMinutes || 0), 0) / playbooks.length)} min` : '0', icon: <ClockCircleOutlined />, color: '#f59e0b' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            <Card><Table columns={columns} dataSource={playbooks.map(p => ({ ...p, key: p.id }))} loading={loading} pagination={false} size="middle" scroll={{ x: 1000 }} /></Card>

            <SteppedFormModal
                open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditingPb(null); form.resetFields(); }}
                onSubmit={handleSave} form={form} title={editingPb ? "Edit Playbook" : "Create Playbook"}
                entityName="playbook" steps={formSteps} fields={PLAYBOOK_FIELDS} width={620}
                onBatchCreate={handleBatchCreate} gradient={["#8b5cf6", themeColor]} editMode={!!editingPb}
            />

            {/* Steps Drawer */}
            <Drawer title={<Space><OrderedListOutlined /> Steps — {selectedPb?.name}</Space>}
                open={stepsDrawerOpen} onClose={() => setStepsDrawerOpen(false)} width={520}
                extra={<Button type="primary" size="small" icon={<PlusOutlined />}
                    onClick={() => { setEditingStep(null); stepForm.resetFields(); stepForm.setFieldsValue({ stepOrder: steps.length + 1 }); setStepModalOpen(true); }}>Add Step</Button>}
            >
                <List
                    loading={stepsLoading}
                    dataSource={steps}
                    locale={{ emptyText: <Empty description="No steps yet. Add your first step above." /> }}
                    renderItem={(step: any, idx: number) => (
                        <List.Item
                            actions={[
                                <Button key="e" type="text" size="small" icon={<EditOutlined />} onClick={() => {
                                    setEditingStep(step); stepForm.setFieldsValue(step); setStepModalOpen(true);
                                }} />,
                                <Button key="d" type="text" size="small" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({
                                    title: `Delete step "${step.title}"?`, onOk: () => handleDeleteStep(step.id),
                                })} />,
                            ]}
                        >
                            <List.Item.Meta
                                avatar={<Tag color={STEP_TYPE_COLORS[step.stepType] || 'blue'} style={{ minWidth: 26, textAlign: 'center' }}>{idx + 1}</Tag>}
                                title={<Space><Text strong>{step.title}</Text>{step.isRequired && <Tag color="red" style={{ fontSize: 10 }}>Required</Tag>}</Space>}
                                description={<Space size={4}>
                                    <Tag>{step.stepType}</Tag>
                                    {step.estimatedMinutes > 0 && <Text type="secondary" style={{ fontSize: 11 }}>{step.estimatedMinutes} min</Text>}
                                    {step.description && <Text type="secondary" style={{ fontSize: 11 }}>— {step.description}</Text>}
                                </Space>}
                            />
                        </List.Item>
                    )}
                />
            </Drawer>

            {/* Step Modal */}
            <Modal title={editingStep ? "Edit Step" : "Add Step"} open={stepModalOpen}
                onCancel={() => { setStepModalOpen(false); setEditingStep(null); stepForm.resetFields(); }}
                onOk={() => stepForm.validateFields().then(handleSaveStep)} width={480}
            >
                <Form form={stepForm} layout="vertical">
                    <Form.Item name="title" label="Step Title" rules={[{ required: true }]}><Input placeholder="e.g., Verify backup status" /></Form.Item>
                    <Form.Item name="description" label="Description"><Input.TextArea rows={2} /></Form.Item>
                    <Row gutter={12}>
                        <Col span={8}><Form.Item name="stepOrder" label="Order"><InputNumber min={1} style={{ width: '100%' }} /></Form.Item></Col>
                        <Col span={8}>
                            <Form.Item name="stepType" label="Type" initialValue="task">
                                <Select options={['task','approval','check','notification'].map(t => ({ label: t, value: t }))} />
                            </Form.Item>
                        </Col>
                        <Col span={8}><Form.Item name="estimatedMinutes" label="Est. Min"><InputNumber min={0} style={{ width: '100%' }} /></Form.Item></Col>
                    </Row>
                    <Form.Item name="isRequired" valuePropName="checked" initialValue={true}><Checkbox>Required step</Checkbox></Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useParams, useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import {
    Card, Row, Col, Tag, Space, Typography, Button, Steps, Progress,
    message, Modal, Input, Divider, Timeline, Tooltip, Avatar, Empty,
    Statistic, Descriptions, Badge, Alert,
} from "antd";
import { motion } from "framer-motion";
import {
    RocketOutlined, CheckCircleOutlined, ClockCircleOutlined,
    PlayCircleOutlined, StopOutlined, ReloadOutlined, ArrowLeftOutlined,
    UserOutlined, EditOutlined, WarningOutlined, ThunderboltOutlined,
    ExclamationCircleOutlined, FileExcelOutlined, FilePdfOutlined,
    CalendarOutlined, FieldTimeOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import duration from "dayjs/plugin/duration";

dayjs.extend(relativeTime);
dayjs.extend(duration);

const { Text, Title, Paragraph } = Typography;
const { TextArea } = Input;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const STATUS_COLORS: Record<string, string> = {
    pending: 'default', in_progress: 'processing', completed: 'success', cancelled: 'warning', failed: 'error',
};
const STATUS_ICONS: Record<string, React.ReactNode> = {
    pending: <ClockCircleOutlined />,
    in_progress: <ThunderboltOutlined style={{ color: '#3b82f6' }} />,
    completed: <CheckCircleOutlined style={{ color: '#22c55e' }} />,
    cancelled: <WarningOutlined style={{ color: '#f59e0b' }} />,
    failed: <ExclamationCircleOutlined style={{ color: '#ef4444' }} />,
};

export default function RunDetailPage() {
    const params = useParams();
    const router = useRouter();
    const runId = params?.id as string;
    const { themeColor } = usePreferencesStore();

    const [run, setRun] = useState<any>(null);
    const [steps, setSteps] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [noteModal, setNoteModal] = useState<{ open: boolean; stepId: string; note: string }>({ open: false, stepId: '', note: '' });

    const loadData = useCallback(async () => {
        if (!runId) return;
        setLoading(true);
        try {
            const [runData, stepsData] = await Promise.all([
                gql(`query($t: String!) { opsRuns(tenantId: $t) {
                    id name status playbookId playbookName playbookCategory playbookPriority
                    startedBy startedAt completedAt dueAt notes scheduleId createdAt
                } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($runId: String!) { opsRunSteps(runId: $runId) {
                    id runId stepId stepOrder title status assigneeId assigneeName
                    startedAt completedAt notes completedBy createdAt
                } }`, { runId }),
            ]);
            const found = (runData.opsRuns || []).find((r: any) => r.id === runId);
            setRun(found || null);
            setSteps((stepsData.opsRunSteps || []).sort((a: any, b: any) => a.stepOrder - b.stepOrder));
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, [runId]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleStatusChange = async (status: string) => {
        try {
            await gql(`mutation($id: String!, $status: String!) { updateOpsRunStatus(id: $id, status: $status) { id } }`, { id: runId, status });
            message.success(`Run ${status.replace('_', ' ')}`);
            loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleStepStatus = async (stepId: string, status: string) => {
        try {
            await gql(`mutation($id: String!, $status: String!) { updateOpsRunStepStatus(id: $id, status: $status) { id } }`, { id: stepId, status });
            message.success(`Step ${status.replace('_', ' ')}`);
            loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleStepNote = async () => {
        if (!noteModal.stepId) return;
        try {
            // Use direct Supabase REST for step notes update
            const SUPABASE_URL = 'http://localhost:8000';
            const SUPABASE_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYW5vbiIsImlzcyI6InN1cGFiYXNlIiwiaWF0IjoxNzc1MjE1MjE4LCJleHAiOjIxNDU5MTY4MDB9.6q7QrCyLzEJ-m2Mw8Y29BNR_tF3fKAfbXhdcc4HKxhE';
            await fetch(`${SUPABASE_URL}/rest/v1/ops_run_steps?id=eq.${noteModal.stepId}`, {
                method: 'PATCH',
                headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ notes: noteModal.note }),
            });
            message.success('Note saved');
            setNoteModal({ open: false, stepId: '', note: '' });
            loadData();
        } catch (err: any) { message.error(err.message); }
    };

    if (loading && !run) {
        return <CMSLayout title="Loading..."><Card loading style={glass} /></CMSLayout>;
    }
    if (!run) {
        return (
            <CMSLayout title="Run Not Found">
                <Empty description="This run does not exist or was deleted">
                    <Button onClick={() => router.push('/admin/ops/runs')}>Back to Runs</Button>
                </Empty>
            </CMSLayout>
        );
    }

    const completedSteps = steps.filter(s => s.status === 'completed').length;
    const failedSteps = steps.filter(s => s.status === 'failed').length;
    const inProgressSteps = steps.filter(s => s.status === 'in_progress').length;
    const progressPercent = steps.length > 0 ? Math.round((completedSteps / steps.length) * 100) : 0;
    const currentStepIdx = steps.findIndex(s => s.status === 'pending' || s.status === 'in_progress');

    const runDuration = (() => {
        const start = run.startedAt || run.createdAt;
        const end = run.completedAt || new Date().toISOString();
        const mins = dayjs(end).diff(dayjs(start), 'minute');
        if (mins < 60) return `${mins} min`;
        return `${Math.floor(mins / 60)}h ${mins % 60}m`;
    })();

    const isOverdue = run.dueAt && dayjs(run.dueAt).isBefore(dayjs()) && !['completed', 'cancelled'].includes(run.status);

    // Build timeline events from steps
    const timelineEvents = steps
        .filter(s => s.startedAt || s.completedAt)
        .flatMap(s => {
            const events: any[] = [];
            if (s.startedAt) events.push({ time: s.startedAt, label: `Started: ${s.title}`, color: 'blue', user: s.assigneeName });
            if (s.completedAt) events.push({ time: s.completedAt, label: `Completed: ${s.title}`, color: s.status === 'failed' ? 'red' : 'green', user: s.completedBy });
            return events;
        })
        .sort((a, b) => dayjs(b.time).unix() - dayjs(a.time).unix());

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>{run.name}</AuroraText>}
            subTitle={<Space><Tag color={STATUS_COLORS[run.status]}>{run.status?.replace('_', ' ')}</Tag><Text type="secondary">{run.playbookName}</Text></Space>}
            extra={[
                <Button key="back" icon={<ArrowLeftOutlined />} onClick={() => router.push('/admin/ops/runs')}>Back</Button>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
                run.status === 'pending' && (
                    <Button key="start" type="primary" icon={<PlayCircleOutlined />} onClick={() => handleStatusChange('in_progress')}>
                        Start Run
                    </Button>
                ),
                run.status === 'in_progress' && progressPercent === 100 && (
                    <Button key="complete" type="primary" style={{ background: '#22c55e' }} icon={<CheckCircleOutlined />}
                        onClick={() => handleStatusChange('completed')}>
                        Mark Complete
                    </Button>
                ),
                run.status === 'in_progress' && (
                    <Button key="cancel" danger icon={<StopOutlined />}
                        onClick={() => Modal.confirm({ title: 'Cancel this run?', onOk: () => handleStatusChange('cancelled') })}>
                        Cancel
                    </Button>
                ),
                <RbacGuard key="exp" requiredRole="manager">
                    <Tooltip title="Export PDF">
                        <Button size="small" icon={<FilePdfOutlined />} onClick={() => exportToPdf({
                            fileName: `run_${run.name}`, title: `Run: ${run.name}`,
                            columns: [{ header: 'Step', key: 'title' }, { header: 'Status', key: 'status' }, { header: 'Assignee', key: 'assigneeName' }, { header: 'Notes', key: 'notes' }],
                            data: steps,
                        })} />
                    </Tooltip>
                </RbacGuard>,
            ]}
        >
            {isOverdue && (
                <Alert type="warning" message={<Space><WarningOutlined />This run is <Text strong type="danger">overdue</Text> — due {dayjs(run.dueAt).fromNow()}</Space>}
                    showIcon={false} style={{ marginBottom: 16, borderRadius: 12 }} banner />
            )}

            {/* ─── Run Metadata ─── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col xs={24} md={16}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                        <Card size="small" style={glass}>
                            <Descriptions size="small" column={{ xs: 1, md: 3 }} labelStyle={{ fontSize: 12, color: '#94a3b8' }}>
                                <Descriptions.Item label="Playbook">{run.playbookName}</Descriptions.Item>
                                <Descriptions.Item label="Category"><Tag>{run.playbookCategory}</Tag></Descriptions.Item>
                                <Descriptions.Item label="Priority"><Tag color={run.playbookPriority === 'critical' ? 'red' : run.playbookPriority === 'high' ? 'orange' : 'blue'}>{run.playbookPriority}</Tag></Descriptions.Item>
                                <Descriptions.Item label="Started By">{run.startedBy || '—'}</Descriptions.Item>
                                <Descriptions.Item label="Started At">{run.startedAt ? dayjs(run.startedAt).format('MMM D, HH:mm') : '—'}</Descriptions.Item>
                                <Descriptions.Item label="Due">{run.dueAt ? dayjs(run.dueAt).format('MMM D, HH:mm') : '—'}</Descriptions.Item>
                                {run.notes && <Descriptions.Item label="Notes" span={3}><Paragraph style={{ margin: 0, fontSize: 12 }}>{run.notes}</Paragraph></Descriptions.Item>}
                            </Descriptions>
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} md={8}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.1 }}>
                        <Card size="small" style={{ ...glass, textAlign: 'center' }}>
                            <Progress type="circle" percent={progressPercent} size={100}
                                strokeColor={progressPercent === 100 ? '#22c55e' : { '0%': '#6366f1', '100%': '#3b82f6' }}
                                format={() => <span style={{ fontSize: 20, fontWeight: 700 }}>{progressPercent}%</span>} />
                            <div style={{ marginTop: 8 }}>
                                <Text type="secondary" style={{ fontSize: 12 }}>{completedSteps} of {steps.length} steps</Text>
                            </div>
                            <Row gutter={8} style={{ marginTop: 12 }}>
                                <Col span={8}><Statistic title="Done" value={completedSteps} valueStyle={{ color: '#22c55e', fontSize: 18 }} /></Col>
                                <Col span={8}><Statistic title="Active" value={inProgressSteps} valueStyle={{ color: '#3b82f6', fontSize: 18 }} /></Col>
                                <Col span={8}><Statistic title="Failed" value={failedSteps} valueStyle={{ color: '#ef4444', fontSize: 18 }} /></Col>
                            </Row>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ─── Step Execution ─── */}
            <Row gutter={[16, 16]}>
                <Col xs={24} lg={16}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.2 }}>
                        <Card title={<Space><ThunderboltOutlined /> Step Execution</Space>} size="small" style={glass}>
                            {steps.length === 0 ? (
                                <Empty description="No steps defined for this run" />
                            ) : (
                                <Steps direction="vertical" current={currentStepIdx >= 0 ? currentStepIdx : steps.length} size="small"
                                    items={steps.map((step, idx) => ({
                                        title: (
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
                                                <Space>
                                                    <Text strong style={{ fontSize: 13 }}>{step.title}</Text>
                                                    <Tag color={STATUS_COLORS[step.status]} style={{ fontSize: 10 }}>{step.status?.replace('_', ' ')}</Tag>
                                                </Space>
                                                <Space size={4}>
                                                    {step.assigneeName && (
                                                        <Tag icon={<UserOutlined />} color="blue" style={{ fontSize: 10, margin: 0 }}>{step.assigneeName}</Tag>
                                                    )}
                                                </Space>
                                            </div>
                                        ),
                                        description: (
                                            <div style={{ padding: '6px 0' }}>
                                                {step.notes && (
                                                    <Text type="secondary" style={{ fontSize: 11, display: 'block', marginBottom: 6 }}>{step.notes}</Text>
                                                )}
                                                <Space size={4} wrap>
                                                    {step.startedAt && (
                                                        <Text type="secondary" style={{ fontSize: 10 }}>
                                                            <CalendarOutlined /> Started {dayjs(step.startedAt).format('HH:mm')}
                                                        </Text>
                                                    )}
                                                    {step.completedAt && (
                                                        <Text type="secondary" style={{ fontSize: 10, marginLeft: 8 }}>
                                                            <CheckCircleOutlined /> Completed {dayjs(step.completedAt).fromNow()}
                                                        </Text>
                                                    )}
                                                    {step.completedBy && (
                                                        <Text type="secondary" style={{ fontSize: 10, marginLeft: 8 }}>by {step.completedBy}</Text>
                                                    )}
                                                </Space>

                                                {/* Action buttons */}
                                                {run.status === 'in_progress' && (
                                                    <div style={{ marginTop: 6 }}>
                                                        <Space size={4}>
                                                            {step.status === 'pending' && (
                                                                <Button size="small" type="primary" icon={<PlayCircleOutlined />}
                                                                    onClick={() => handleStepStatus(step.id, 'in_progress')}>
                                                                    Start
                                                                </Button>
                                                            )}
                                                            {step.status === 'in_progress' && (
                                                                <>
                                                                    <Button size="small" type="primary" style={{ background: '#22c55e' }}
                                                                        icon={<CheckCircleOutlined />} onClick={() => handleStepStatus(step.id, 'completed')}>
                                                                        Complete
                                                                    </Button>
                                                                    <Button size="small" danger icon={<ExclamationCircleOutlined />}
                                                                        onClick={() => handleStepStatus(step.id, 'failed')}>
                                                                        Fail
                                                                    </Button>
                                                                </>
                                                            )}
                                                            {(step.status === 'pending' || step.status === 'in_progress') && (
                                                                <Button size="small" icon={<EditOutlined />}
                                                                    onClick={() => setNoteModal({ open: true, stepId: step.id, note: step.notes || '' })}>
                                                                    Note
                                                                </Button>
                                                            )}
                                                        </Space>
                                                    </div>
                                                )}
                                            </div>
                                        ),
                                        status: step.status === 'completed' ? 'finish' : step.status === 'in_progress' ? 'process' : step.status === 'failed' ? 'error' : 'wait',
                                    }))}
                                />
                            )}
                        </Card>
                    </motion.div>
                </Col>

                {/* ─── Activity Timeline ─── */}
                <Col xs={24} lg={8}>
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                        <Card title={<Space><FieldTimeOutlined /> Activity Timeline</Space>} size="small" style={glass}>
                            {timelineEvents.length === 0 ? (
                                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No activity yet" />
                            ) : (
                                <Timeline
                                    items={timelineEvents.slice(0, 20).map(evt => ({
                                        color: evt.color,
                                        children: (
                                            <div>
                                                <Text style={{ fontSize: 12 }}>{evt.label}</Text>
                                                <br />
                                                <Space size={4}>
                                                    {evt.user && <Text type="secondary" style={{ fontSize: 10 }}>{evt.user}</Text>}
                                                    <Text type="secondary" style={{ fontSize: 10 }}>{dayjs(evt.time).format('HH:mm')}</Text>
                                                </Space>
                                            </div>
                                        ),
                                    }))}
                                />
                            )}
                        </Card>

                        {/* Quick Stats */}
                        <Card size="small" style={{ ...glass, marginTop: 16 }}>
                            <Space direction="vertical" size={8} style={{ width: '100%' }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <Text type="secondary" style={{ fontSize: 12 }}>Duration</Text>
                                    <Text strong style={{ fontSize: 12 }}>{runDuration}</Text>
                                </div>
                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <Text type="secondary" style={{ fontSize: 12 }}>Assignees</Text>
                                    <Text strong style={{ fontSize: 12 }}>{[...new Set(steps.filter(s => s.assigneeName).map(s => s.assigneeName))].length}</Text>
                                </div>
                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <Text type="secondary" style={{ fontSize: 12 }}>Steps with Notes</Text>
                                    <Text strong style={{ fontSize: 12 }}>{steps.filter(s => s.notes).length}</Text>
                                </div>
                                {run.scheduleId && (
                                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                        <Text type="secondary" style={{ fontSize: 12 }}>Triggered by</Text>
                                        <Tag color="purple" style={{ fontSize: 10 }}>Schedule</Tag>
                                    </div>
                                )}
                            </Space>
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* Step Note Modal */}
            <Modal title="Step Notes" open={noteModal.open} onCancel={() => setNoteModal({ open: false, stepId: '', note: '' })}
                onOk={handleStepNote} okText="Save Note">
                <TextArea rows={4} value={noteModal.note} onChange={e => setNoteModal(prev => ({ ...prev, note: e.target.value }))}
                    placeholder="Add execution notes, observations, or issues..." />
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Card, message, Typography,
    Row, Col, Statistic, Tooltip, Drawer, List, Steps, Input, Progress,
} from "antd";
import { motion } from "framer-motion";
import {
    RocketOutlined, ReloadOutlined, CheckCircleOutlined, ClockCircleOutlined,
    PlayCircleOutlined, PauseCircleOutlined, StopOutlined, DeleteOutlined,
    UserOutlined, ThunderboltOutlined, WarningOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);
const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const STATUS_COLORS: Record<string, string> = {
    pending: 'default', in_progress: 'processing', completed: 'success', cancelled: 'warning', failed: 'error',
};
const PRIORITY_COLORS: Record<string, string> = { critical: 'red', high: 'orange', medium: 'blue', low: 'default' };

export default function RunsPage() {
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [runs, setRuns] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [stepsMap, setStepsMap] = useState<Record<string, { total: number; completed: number }>>({}); 
    const [selectedRun, setSelectedRun] = useState<any>(null);
    const [runSteps, setRunSteps] = useState<any[]>([]);
    const [stepsLoading, setStepsLoading] = useState(false);
    const [drawerOpen, setDrawerOpen] = useState(false);

    const loadRuns = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`query($t: String!) { opsRuns(tenantId: $t) {
                id name status playbookId playbookName playbookCategory playbookPriority
                startedBy startedAt completedAt dueAt notes createdAt
            } }`, { t: DEFAULT_TENANT_ID });
            const activeRuns = (data.opsRuns || []).filter((r: any) => r.status !== 'completed');
            setRuns(activeRuns);
            // Load steps progress for each active run
            const map: Record<string, { total: number; completed: number }> = {};
            await Promise.allSettled(activeRuns.map(async (r: any) => {
                try {
                    const stepsData = await gql(`query($runId: String!) { opsRunSteps(runId: $runId) { id status } }`, { runId: r.id });
                    const steps = stepsData.opsRunSteps || [];
                    map[r.id] = { total: steps.length, completed: steps.filter((s: any) => s.status === 'completed').length };
                } catch { /* ignore */ }
            }));
            setStepsMap(map);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadRuns(); }, [loadRuns]);

    const loadRunSteps = async (runId: string) => {
        setStepsLoading(true);
        try {
            const data = await gql(`query($runId: String!) { opsRunSteps(runId: $runId) {
                id runId stepId stepOrder title status assigneeId assigneeName startedAt completedAt notes completedBy
            } }`, { runId });
            setRunSteps(data.opsRunSteps || []);
        } catch { /* ignore */ } finally { setStepsLoading(false); }
    };

    const handleStatusChange = async (id: string, status: string) => {
        try {
            await gql(`mutation($id: String!, $status: String!) { updateOpsRunStatus(id: $id, status: $status) { id } }`, { id, status });
            message.success(`Run ${status}`);
            loadRuns();
        } catch (err: any) { message.error(err.message); }
    };

    const handleStepComplete = async (stepId: string) => {
        try {
            await gql(`mutation($id: String!, $status: String!) { updateOpsRunStepStatus(id: $id, status: $status) { id } }`, { id: stepId, status: 'completed' });
            message.success("Step completed");
            loadRunSteps(selectedRun.id);
            loadRuns();
        } catch (err: any) { message.error(err.message); }
    };

    const activeRuns = runs.filter(r => r.status === 'in_progress');
    const pendingRuns = runs.filter(r => r.status === 'pending');

    const columns: ColumnsType<any> = [
        {
            title: "Run", key: "name",
            render: (_, r) => (
                <Space style={{ cursor: 'pointer' }} onClick={() => router.push(`/admin/ops/runs/${r.id}`)}>
                    <RocketOutlined style={{ fontSize: 18, color: r.status === 'in_progress' ? '#3b82f6' : '#94a3b8' }} />
                    <div>
                        <Text strong style={{ color: '#6366f1' }}>{r.name}</Text><br />
                        <Text type="secondary" style={{ fontSize: 11 }}>{r.playbookName}</Text>
                    </div>
                </Space>
            ),
        },
        { title: "Status", dataIndex: "status", width: 120, render: (v: string) => <Tag color={STATUS_COLORS[v]}>{v?.replace('_', ' ')}</Tag> },
        { title: "Priority", key: "priority", width: 90, render: (_, r) => <Tag color={PRIORITY_COLORS[r.playbookPriority]}>{r.playbookPriority}</Tag> },
        {
            title: "Due", key: "due", width: 130,
            sorter: (a: any, b: any) => {
                if (!a.dueAt) return 1;
                if (!b.dueAt) return -1;
                return dayjs(a.dueAt).unix() - dayjs(b.dueAt).unix();
            },
            render: (_: any, r: any) => {
                if (!r.dueAt) return <Text type="secondary" style={{ fontSize: 11 }}>No deadline</Text>;
                const isOverdue = dayjs(r.dueAt).isBefore(dayjs());
                return (
                    <Tooltip title={dayjs(r.dueAt).format('YYYY-MM-DD HH:mm')}>
                        <Tag color={isOverdue ? 'red' : 'blue'} style={{ fontSize: 10 }}>
                            {isOverdue ? '⚠️' : '⏰'} {dayjs(r.dueAt).fromNow()}
                        </Tag>
                    </Tooltip>
                );
            },
        },
        {
            title: "Progress", key: "progress", width: 120,
            render: (_: any, r: any) => {
                const stats = stepsMap[r.id];
                if (!stats || stats.total === 0) return <Text type="secondary" style={{ fontSize: 10 }}>-</Text>;
                const pct = Math.round((stats.completed / stats.total) * 100);
                return (
                    <Tooltip title={`${stats.completed}/${stats.total} steps completed`}>
                        <Progress
                            percent={pct}
                            size="small"
                            strokeColor={pct === 100 ? '#22c55e' : pct > 50 ? '#3b82f6' : '#f59e0b'}
                            format={() => <Text style={{ fontSize: 10 }}>{stats.completed}/{stats.total}</Text>}
                        />
                    </Tooltip>
                );
            },
        },
        { title: "Started", key: "started", width: 130, render: (_, r) => r.startedAt ? <Text style={{ fontSize: 12 }}>{dayjs(r.startedAt).fromNow()}</Text> : '—' },
        {
            title: "Actions", key: "actions", width: 200,
            render: (_, r) => (
                <Space>
                    <Tooltip title="View Steps">
                        <Button type="text" icon={<CheckCircleOutlined />} onClick={() => {
                            setSelectedRun(r); setDrawerOpen(true); loadRunSteps(r.id);
                        }} />
                    </Tooltip>
                    {r.status === 'pending' && (
                        <Tooltip title="Start"><Button type="text" icon={<PlayCircleOutlined style={{ color: '#22c55e' }} />}
                            onClick={() => handleStatusChange(r.id, 'in_progress')} /></Tooltip>
                    )}
                    {r.status === 'in_progress' && (
                        <Tooltip title="Cancel"><Button type="text" icon={<StopOutlined style={{ color: '#ef4444' }} />}
                            onClick={() => Modal.confirm({ title: 'Cancel this run?', onOk: () => handleStatusChange(r.id, 'cancelled') })} /></Tooltip>
                    )}
                    <Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({
                        title: 'Delete run?', onOk: async () => {
                            await gql(`mutation($id: String!) { deleteOpsRun(id: $id) }`, { id: r.id });
                            message.success("Deleted"); loadRuns();
                        },
                    })} />
                </Space>
            ),
        },
    ];

    const completedSteps = runSteps.filter(s => s.status === 'completed').length;
    const currentStep = runSteps.findIndex(s => s.status === 'pending' || s.status === 'in_progress');

    const failedRuns = runs.filter(r => r.status === 'failed');
    const overdueRuns = runs.filter(r => r.dueAt && dayjs(r.dueAt).isBefore(dayjs()) && r.status !== 'completed');

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Active Runs</AuroraText>}
            subTitle={<DecryptedText text="Monitor and manage currently executing operational workflows" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadRuns} />,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ops_runs', title: 'Active Runs', columns: [{ header: 'Run', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Playbook', key: 'playbookName' }, { header: 'Priority', key: 'playbookPriority' }, { header: 'Created', key: 'createdAt' }], data: runs })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ops_runs', title: 'Active Runs', columns: [{ header: 'Run', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Playbook', key: 'playbookName' }, { header: 'Priority', key: 'playbookPriority' }], data: runs })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'In Progress', value: activeRuns.length, icon: <ThunderboltOutlined />, color: '#3b82f6' },
                    { title: 'Pending', value: pendingRuns.length, icon: <ClockCircleOutlined />, color: '#f59e0b' },
                    { title: 'Failed', value: failedRuns.length, icon: <WarningOutlined />, color: '#ef4444' },
                    { title: 'Overdue', value: overdueRuns.length, icon: <WarningOutlined />, color: '#dc2626' },
                    { title: 'Total Active', value: runs.length, icon: <RocketOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20 }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            <Card><Table columns={columns} dataSource={runs.map(r => ({ ...r, key: r.id }))} loading={loading} pagination={false} size="middle" scroll={{ x: 1000 }} /></Card>

            {/* Steps Execution Drawer */}
            <Drawer title={<Space><RocketOutlined /> Run Steps — {selectedRun?.name}</Space>}
                open={drawerOpen} onClose={() => setDrawerOpen(false)} width={520}
                extra={<Tag color={STATUS_COLORS[selectedRun?.status]}>{selectedRun?.status?.replace('_', ' ')}</Tag>}
            >
                <Card size="small" style={{ marginBottom: 16 }}>
                    <Text type="secondary">Progress: {completedSteps} / {runSteps.length} steps</Text>
                </Card>
                <Steps direction="vertical" current={currentStep >= 0 ? currentStep : runSteps.length} size="small"
                    items={runSteps.map(step => ({
                        title: (
                            <Space>
                                <Text strong>{step.title}</Text>
                                {step.assigneeName && <Tag icon={<UserOutlined />} color="blue" style={{ fontSize: 10 }}>{step.assigneeName}</Tag>}
                            </Space>
                        ),
                        description: (
                            <Space direction="vertical" size={2}>
                                {step.notes && <Text type="secondary" style={{ fontSize: 11 }}>{step.notes}</Text>}
                                {step.status === 'pending' && selectedRun?.status === 'in_progress' && (
                                    <Button size="small" type="primary" icon={<CheckCircleOutlined />}
                                        onClick={() => handleStepComplete(step.id)} style={{ marginTop: 4 }}>
                                        Complete
                                    </Button>
                                )}
                                {step.completedAt && <Text type="secondary" style={{ fontSize: 10 }}>Completed {dayjs(step.completedAt).fromNow()}</Text>}
                            </Space>
                        ),
                        status: step.status === 'completed' ? 'finish' : step.status === 'in_progress' ? 'process' : step.status === 'failed' ? 'error' : 'wait',
                    }))}
                />
            </Drawer>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Form, Input, Select, Card, Tooltip,
    message, Typography, Row, Col, Statistic, Switch,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    ScheduleOutlined, ClockCircleOutlined, PlayCircleOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import dayjs from "dayjs";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

const SCHEDULE_FIELDS: FieldDef[] = [
    { name: "name", label: "Schedule Name", required: true },
    { name: "cronExpression", label: "Cron Expression", required: true },
];

export default function SchedulesPage() {
    const { themeColor } = usePreferencesStore();
    const [schedules, setSchedules] = useState<any[]>([]);
    const [playbooks, setPlaybooks] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [form] = Form.useForm();

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [schData, pbData] = await Promise.all([
                gql(`query($t: String!) { opsSchedules(tenantId: $t) {
                    id name cronExpression timezone isActive playbookId playbookName playbookCategory nextRunAt lastRunAt createdBy createdAt
                } }`, { t: DEFAULT_TENANT_ID }),
                gql(`query($t: String!) { opsPlaybooks(tenantId: $t) { id name category } }`, { t: DEFAULT_TENANT_ID }),
            ]);
            setSchedules(schData.opsSchedules || []);
            setPlaybooks(pbData.opsPlaybooks || []);
        } catch (err: any) { message.error(err.message); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(`mutation($id: String!, $name: String, $cronExpression: String, $timezone: String) {
                    updateOpsSchedule(id: $id, name: $name, cronExpression: $cronExpression, timezone: $timezone) { id }
                }`, { id: editing.id, ...values });
                message.success("Schedule updated");
            } else {
                await gql(`mutation($t: String!, $pbId: String!, $name: String!, $cron: String!, $tz: String) {
                    createOpsSchedule(tenantId: $t, playbookId: $pbId, name: $name, cronExpression: $cron, timezone: $tz) { id }
                }`, { t: DEFAULT_TENANT_ID, pbId: values.playbookId, name: values.name, cron: values.cronExpression, tz: values.timezone });
                message.success("Schedule created");
            }
            setIsModalOpen(false); form.resetFields(); setEditing(null); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleToggle = async (id: string, isActive: boolean) => {
        try {
            await gql(`mutation($id: String!, $isActive: Boolean) { updateOpsSchedule(id: $id, isActive: $isActive) { id } }`, { id, isActive });
            message.success(isActive ? 'Activated' : 'Deactivated'); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteOpsSchedule(id: $id) }`, { id });
            message.success("Deleted"); loadData();
        } catch (err: any) { message.error(err.message); }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                const pb = playbooks.find(p => p.name === r.playbookName) || playbooks[0];
                if (!pb) throw new Error('No playbook found');
                await gql(`mutation($t: String!, $pbId: String!, $name: String!, $cron: String!) {
                    createOpsSchedule(tenantId: $t, playbookId: $pbId, name: $name, cronExpression: $cron) { id }
                }`, { t: DEFAULT_TENANT_ID, pbId: pb.id, name: r.name, cron: r.cronExpression });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadData(); return { success, failed, errors };
    };

    const columns: ColumnsType<any> = [
        {
            title: "Schedule", key: "name", width: 220,
            render: (_, r) => (
                <Space>
                    <ScheduleOutlined style={{ fontSize: 18, color: r.isActive ? '#3b82f6' : '#94a3b8' }} />
                    <div>
                        <Text strong>{r.name}</Text>
                        {!r.isActive && <Tag color="default" style={{ marginLeft: 6 }}>Inactive</Tag>}
                        <br />
                        <Text type="secondary" style={{ fontSize: 11 }}>{r.playbookName}</Text>
                    </div>
                </Space>
            ),
        },
        { title: "Cron", dataIndex: "cronExpression", width: 130, render: (v: string) => <Text code style={{ fontSize: 11 }}>{v}</Text> },
        { title: "Timezone", dataIndex: "timezone", width: 130, render: (v: string) => <Text style={{ fontSize: 11 }}>{v}</Text> },
        { title: "Active", key: "isActive", width: 80, align: 'center', render: (_, r) => <Switch checked={r.isActive} size="small" onChange={(v) => handleToggle(r.id, v)} /> },
        {
            title: "Next Run", key: "nextRun", width: 140,
            render: (_, r) => {
                if (!r.isActive) return <Text type="secondary" style={{ fontSize: 11 }}>—</Text>;
                if (!r.nextRunAt) return <Text type="secondary" style={{ fontSize: 11 }}>Not scheduled</Text>;
                const isOverdue = dayjs(r.nextRunAt).isBefore(dayjs());
                return (
                    <Tooltip title={dayjs(r.nextRunAt).format('MMM D, HH:mm')}>
                        <Tag color={isOverdue ? 'red' : 'blue'} style={{ fontSize: 11 }}>
                            <ClockCircleOutlined /> {dayjs(r.nextRunAt).fromNow()}
                        </Tag>
                    </Tooltip>
                );
            },
        },
        {
            title: "Last Run", key: "lastRun", width: 140,
            render: (_, r) => r.lastRunAt ? (
                <Tooltip title={dayjs(r.lastRunAt).format('MMM D, HH:mm')}>
                    <Text style={{ fontSize: 12 }}>{dayjs(r.lastRunAt).fromNow()}</Text>
                </Tooltip>
            ) : <Text type="secondary" style={{ fontSize: 11 }}>Never</Text>,
        },
        {
            title: "Actions", key: "actions", width: 140,
            render: (_, r) => (
                <Space>
                    <Button type="text" icon={<EditOutlined />} onClick={() => { setEditing(r); form.setFieldsValue(r); setIsModalOpen(true); }} />
                    <Button type="text" danger icon={<DeleteOutlined />} onClick={() => Modal.confirm({ title: `Delete "${r.name}"?`, onOk: () => handleDelete(r.id) })} />
                </Space>
            ),
        },
    ];

    const formSteps = [{
        title: "Schedule Info", icon: <ScheduleOutlined />, fields: ["name", "playbookId", "cronExpression", "timezone"],
        content: (
            <>
                <Form.Item name="name" label="Schedule Name" rules={[{ required: true }]}><Input placeholder="e.g., Daily Health Check" /></Form.Item>
                {!editing && (
                    <Form.Item name="playbookId" label="Playbook" rules={[{ required: true }]}>
                        <Select placeholder="Select playbook" options={playbooks.map(p => ({ label: `${p.name} (${p.category})`, value: p.id }))} />
                    </Form.Item>
                )}
                <Form.Item name="cronExpression" label="Cron Expression" rules={[{ required: true }]} extra="e.g., 0 9 * * * (daily at 9am)">
                    <Input placeholder="0 9 * * *" />
                </Form.Item>
                <Form.Item name="timezone" label="Timezone" initialValue="Asia/Jakarta">
                    <Select options={['Asia/Jakarta','Asia/Singapore','UTC','America/New_York','Europe/London'].map(t => ({ label: t, value: t }))} />
                </Form.Item>
            </>
        ),
    }];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#6366f1", "#a78bfa"]}>Schedules</AuroraText>}
            subTitle={<DecryptedText text="Recurring schedule definitions for automatic playbook execution" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadData} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); form.resetFields(); setIsModalOpen(true); }}>Create Schedule</Button>,
                <RbacGuard key="exp" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'ops_schedules', title: 'Schedules', columns: [{ header: 'Name', key: 'name' }, { header: 'Cron', key: 'cronExpression' }, { header: 'Timezone', key: 'timezone' }, { header: 'Active', key: 'isActive' }, { header: 'Playbook', key: 'playbookName' }], data: schedules })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'ops_schedules', title: 'Schedules', columns: [{ header: 'Name', key: 'name' }, { header: 'Cron', key: 'cronExpression' }, { header: 'Timezone', key: 'timezone' }, { header: 'Playbook', key: 'playbookName' }], data: schedules })} /></Tooltip></RbacGuard>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total', value: schedules.length, icon: <ScheduleOutlined />, color: '#8b5cf6' },
                    { title: 'Active', value: schedules.filter(s => s.isActive).length, icon: <PlayCircleOutlined />, color: '#22c55e' },
                    { title: 'Inactive', value: schedules.filter(s => !s.isActive).length, icon: <ClockCircleOutlined />, color: '#94a3b8' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            <Card><Table columns={columns} dataSource={schedules.map(s => ({ ...s, key: s.id }))} loading={loading} pagination={false} size="middle" scroll={{ x: 900 }} /></Card>

            <SteppedFormModal
                open={isModalOpen} onCancel={() => { setIsModalOpen(false); setEditing(null); form.resetFields(); }}
                onSubmit={handleSave} form={form} title={editing ? "Edit Schedule" : "Create Schedule"}
                entityName="schedule" steps={formSteps} fields={SCHEDULE_FIELDS} width={520}
                onBatchCreate={handleBatchCreate} gradient={["#06b6d4", themeColor]} editMode={!!editing}
            />
        </CMSLayout>
    );
}

