"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table,
    Button,
    Space,
    Tag,
    Modal,
    Input,
    Form,
    message,
    Popconfirm,
    Dropdown,
    Empty,
    Card, Row, Col, Statistic, Tooltip, Segmented, Spin,
} from "antd";
import { motion, AnimatePresence } from "framer-motion";
import {
    PlusOutlined,
    EditOutlined,
    DeleteOutlined,
    EyeOutlined,
    CopyOutlined,
    MoreOutlined,
    GlobalOutlined,
    FileTextOutlined,
    CloudUploadOutlined,
    AppstoreOutlined,
    UnorderedListOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { FileExcelOutlined, FilePdfOutlined } from "@ant-design/icons";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import pageService, { CMSPage } from "@/lib/pageService";

const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

// Sample data for development (when Supabase is not connected)
const samplePages: CMSPage[] = [
    {
        id: "1",
        title: "Home Page",
        slug: "home",
        content: [],
        status: "published",
        author_id: "1",
        meta_title: "Home - Nusantarasoft",
        meta_description: "Welcome to Nusantarasoft",
        created_at: "2024-01-15T10:00:00Z",
        updated_at: "2024-12-20T14:30:00Z",
        published_at: "2024-01-15T12:00:00Z",
    },
    {
        id: "2",
        title: "About Us",
        slug: "about",
        content: [],
        status: "published",
        author_id: "1",
        created_at: "2024-02-10T09:00:00Z",
        updated_at: "2024-12-18T11:00:00Z",
        published_at: "2024-02-10T10:00:00Z",
    },
    {
        id: "3",
        title: "Contact",
        slug: "contact",
        content: [],
        status: "draft",
        author_id: "1",
        created_at: "2024-03-05T08:00:00Z",
        updated_at: "2024-12-15T16:00:00Z",
    },
    {
        id: "4",
        title: "Services",
        slug: "services",
        content: [],
        status: "draft",
        author_id: "2",
        created_at: "2024-04-20T14:00:00Z",
        updated_at: "2024-12-10T09:30:00Z",
    },
];

export default function PagesListPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const router = useRouter();
    const [pages, setPages] = useState<CMSPage[]>([]);
    const [loading, setLoading] = useState(true);
    const [createModalOpen, setCreateModalOpen] = useState(false);
    const [viewMode, setViewMode] = useState<"grid" | "table">("grid");
    const [form] = Form.useForm();

    useEffect(() => {
        loadPages();
    }, []);

    const loadPages = async () => {
        setLoading(true);
        try {
            const data = await pageService.getPages();
            // Use sample data if no data from Supabase (dev mode)
            setPages(data.length > 0 ? data : samplePages);
        } catch (error) {
            // Fallback to sample data
            setPages(samplePages);
        }
        setLoading(false);
    };

    const handleCreatePage = async (values: { title: string; slug: string }) => {
        const newPage = await pageService.createPage({
            title: values.title,
            slug: values.slug || values.title.toLowerCase().replace(/\s+/g, "-"),
        });

        if (newPage) {
            message.success("Page created!");
            setCreateModalOpen(false);
            form.resetFields();
            router.push(`/admin/pages/builder?id=${newPage.id}`);
        } else {
            // Dev mode - create locally
            const localPage: CMSPage = {
                id: `local-${Date.now()}`,
                title: values.title,
                slug: values.slug || values.title.toLowerCase().replace(/\s+/g, "-"),
                content: [],
                status: "draft",
                author_id: "1",
                created_at: new Date().toISOString(),
                updated_at: new Date().toISOString(),
            };
            setPages([localPage, ...pages]);
            setCreateModalOpen(false);
            form.resetFields();
            message.success("Page created (local mode)");
            router.push(`/admin/pages/builder?id=${localPage.id}`);
        }
    };

    const handleDeletePage = async (id: string) => {
        const success = await pageService.deletePage(id);
        if (success) {
            message.success("Page deleted");
            loadPages();
        } else {
            // Dev mode - delete locally
            setPages(pages.filter(p => p.id !== id));
            message.success("Page deleted (local mode)");
        }
    };

    const handleDuplicatePage = async (id: string) => {
        const newPage = await pageService.duplicatePage(id);
        if (newPage) {
            message.success("Page duplicated!");
            loadPages();
        } else {
            // Dev mode
            const original = pages.find(p => p.id === id);
            if (original) {
                const copy: CMSPage = {
                    ...original,
                    id: `local-${Date.now()}`,
                    title: `${original.title} (Copy)`,
                    slug: `${original.slug}-copy`,
                    status: "draft",
                    created_at: new Date().toISOString(),
                    updated_at: new Date().toISOString(),
                };
                setPages([copy, ...pages]);
                message.success("Page duplicated (local mode)");
            }
        }
    };

    const handlePublish = async (id: string, currentStatus: string) => {
        if (currentStatus === "published") {
            await pageService.unpublishPage(id);
            message.info("Page unpublished");
        } else {
            await pageService.publishPage(id);
            message.success("Page published!");
        }
        loadPages();
    };

    const columns: ColumnsType<CMSPage> = [
        {
            title: "Title",
            dataIndex: "title",
            key: "title",
            render: (text, record) => (
                <Space>
                    <FileTextOutlined />
                    <a onClick={() => router.push(`/admin/pages/builder?id=${record.id}`)}>
                        {text}
                    </a>
                </Space>
            ),
        },
        {
            title: "Slug",
            dataIndex: "slug",
            key: "slug",
            render: (slug) => (
                <Tag>/{slug}</Tag>
            ),
        },
        {
            title: "Status",
            dataIndex: "status",
            key: "status",
            render: (status) => (
                <Tag color={status === "published" ? "green" : "orange"}>
                    {status === "published" ? <><GlobalOutlined /> Published</> : "Draft"}
                </Tag>
            ),
        },
        {
            title: "Last Updated",
            dataIndex: "updated_at",
            key: "updated_at",
            render: (date) => new Date(date).toLocaleDateString("en-US", {
                year: "numeric",
                month: "short",
                day: "numeric",
                hour: "2-digit",
                minute: "2-digit",
            }),
        },
        {
            title: "Actions",
            key: "actions",
            width: 180,
            render: (_, record) => (
                <Space>
                    <Button
                        size="small"
                        icon={<EditOutlined />}
                        onClick={() => router.push(`/admin/pages/builder?id=${record.id}`)}
                    >
                        Edit
                    </Button>
                    <Dropdown
                        menu={{
                            items: [
                                {
                                    key: "preview",
                                    icon: <EyeOutlined />,
                                    label: "Preview",
                                    onClick: () => window.open(`/${record.slug}`, "_blank"),
                                },
                                {
                                    key: "publish",
                                    icon: <CloudUploadOutlined />,
                                    label: record.status === "published" ? "Unpublish" : "Publish",
                                    onClick: () => handlePublish(record.id, record.status),
                                },
                                {
                                    key: "duplicate",
                                    icon: <CopyOutlined />,
                                    label: "Duplicate",
                                    onClick: () => handleDuplicatePage(record.id),
                                },
                                { type: "divider" },
                                {
                                    key: "delete",
                                    icon: <DeleteOutlined />,
                                    label: "Delete",
                                    danger: true,
                                    onClick: () => {
                                        Modal.confirm({
                                            title: "Delete Page?",
                                            content: `Are you sure you want to delete "${record.title}"?`,
                                            okText: "Delete",
                                            okType: "danger",
                                            onOk: () => handleDeletePage(record.id),
                                        });
                                    },
                                },
                            ],
                        }}
                    >
                        <Button size="small" icon={<MoreOutlined />} />
                    </Dropdown>
                </Space>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Pages</AuroraText>}
            subTitle={<DecryptedText text="Manage your website pages" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Segmented
                    key="view"
                    options={[
                        { value: 'grid', icon: <AppstoreOutlined /> },
                        { value: 'table', icon: <UnorderedListOutlined /> }
                    ]}
                    value={viewMode}
                    onChange={(val) => setViewMode(val as "grid" | "table")}
                />,
                <Button
                    key="create"
                    type="primary"
                    icon={<PlusOutlined />}
                    onClick={() => setCreateModalOpen(true)}
                >
                    Create Page
                </Button>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Pages', value: pages.length, icon: <FileTextOutlined />, color: '#3b82f6' },
                    { title: 'Published', value: pages.filter(p => p.status === 'published').length, icon: <GlobalOutlined />, color: '#10b981' },
                    { title: 'Draft', value: pages.filter(p => p.status === 'draft').length, icon: <FileTextOutlined />, color: '#f59e0b' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            {loading ? (
                <div style={{ textAlign: 'center', padding: '40px 0' }}>
                    <Spin size="large" />
                </div>
            ) : pages.length === 0 ? (
                <Empty
                    description="No pages yet"
                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                >
                    <Button
                        type="primary"
                        icon={<PlusOutlined />}
                        onClick={() => setCreateModalOpen(true)}
                    >
                        Create Your First Page
                    </Button>
                </Empty>
            ) : viewMode === 'table' ? (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                    <Table scroll={{ x: 900 }}
                        columns={columns}
                        dataSource={pages}
                        rowKey="id"
                        pagination={{
                            pageSize: 10,
                            showSizeChanger: true,
                            showTotal: (total) => `${total} pages`,
                        }}
                        style={{ ...glass, padding: 12 }}
                    />
                </motion.div>
            ) : (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                    <Row gutter={[16, 16]}>
                        <AnimatePresence>
                            {pages.map((page, index) => (
                                <Col xs={24} md={12} lg={8} key={page.id}>
                                    <motion.div
                                        initial={{ opacity: 0, y: 20 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        exit={{ opacity: 0, scale: 0.9 }}
                                        transition={{ delay: index * 0.05 }}
                                    >
                                        <Card
                                            hoverable
                                            style={{ ...glass, height: '100%', overflow: 'hidden' }}
                                            bodyStyle={{ padding: 20 }}
                                            actions={[
                                                <Tooltip key="preview" title="Preview"><EyeOutlined onClick={() => window.open(`/${page.slug}`, "_blank")} /></Tooltip>,
                                                <Tooltip key="edit" title="Edit"><EditOutlined onClick={() => router.push(`/admin/pages/builder?id=${page.id}`)} /></Tooltip>,
                                                <Tooltip key="duplicate" title="Duplicate"><CopyOutlined onClick={() => handleDuplicatePage(page.id)} /></Tooltip>,
                                                <Dropdown key="more" menu={{
                                                    items: [
                                                        {
                                                            key: "publish",
                                                            icon: <CloudUploadOutlined />,
                                                            label: page.status === "published" ? "Unpublish" : "Publish",
                                                            onClick: () => handlePublish(page.id, page.status),
                                                        },
                                                        { type: 'divider' },
                                                        {
                                                            key: "delete",
                                                            icon: <DeleteOutlined />,
                                                            label: "Delete",
                                                            danger: true,
                                                            onClick: () => {
                                                                Modal.confirm({
                                                                    title: "Delete Page?",
                                                                    content: `Are you sure you want to delete "${page.title}"?`,
                                                                    okText: "Delete",
                                                                    okType: "danger",
                                                                    onOk: () => handleDeletePage(page.id),
                                                                });
                                                            },
                                                        }
                                                    ]
                                                }}>
                                                    <MoreOutlined />
                                                </Dropdown>
                                            ]}
                                        >
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                                                <div style={{ fontWeight: 600, fontSize: 16 }}>
                                                    <a onClick={() => router.push(`/admin/pages/builder?id=${page.id}`)} style={{ color: 'inherit' }}>
                                                        {page.title}
                                                    </a>
                                                </div>
                                            </div>
                                            <div style={{ marginBottom: 16, display: 'flex', gap: 8, alignItems: 'center' }}>
                                                <Tag color={page.status === "published" ? "green" : "orange"} style={{ margin: 0, borderRadius: 12, padding: '0 10px' }}>
                                                    {page.status === "published" ? <><GlobalOutlined /> Published</> : "Draft"}
                                                </Tag>
                                                <Tag style={{ margin: 0, borderRadius: 4, background: 'rgba(0,0,0,0.02)' }}>/{page.slug}</Tag>
                                            </div>
                                            <div style={{ color: '#888', fontSize: 12, display: 'flex', alignItems: 'center', gap: 6 }}>
                                                <FileTextOutlined /> Updated: {new Date(page.updated_at || new Date()).toLocaleDateString()}
                                            </div>
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </AnimatePresence>
                    </Row>
                </motion.div>
            )}

            {/* Create Page Modal */}
            <Modal
                title="Create New Page"
                open={createModalOpen}
                onCancel={() => setCreateModalOpen(false)}
                footer={null}
            >
                <Form
                    form={form}
                    layout="vertical"
                    onFinish={handleCreatePage}
                >
                    <Form.Item
                        name="title"
                        label="Page Title"
                        rules={[{ required: true, message: "Please enter a page title" }]}
                    >
                        <Input placeholder="e.g., About Us" />
                    </Form.Item>
                    <Form.Item
                        name="slug"
                        label="URL Slug (optional)"
                        extra="Leave empty to auto-generate from title"
                    >
                        <Input
                            prefix="/"
                            placeholder="e.g., about-us"
                        />
                    </Form.Item>
                    <Form.Item>
                        <Space>
                            <Button onClick={() => setCreateModalOpen(false)}>
                                Cancel
                            </Button>
                            <Button type="primary" htmlType="submit" icon={<PlusOutlined />}>
                                Create & Edit
                            </Button>
                        </Space>
                    </Form.Item>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Card, Table, Button, Select, Tag, Space, Typography, Spin, Statistic,
    Row, Col, Switch, Collapse, Tooltip, Empty, theme, Badge, Divider,
} from "antd";
import { motion } from "framer-motion";
import {
    SearchOutlined, UserOutlined, AppstoreOutlined, ThunderboltOutlined,
    SafetyOutlined, ApartmentOutlined, ShareAltOutlined, LockOutlined,
    CheckCircleFilled, CloseCircleFilled, SwapOutlined, CrownOutlined,
    RightOutlined, TeamOutlined, IdcardOutlined, DownOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";

const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface User { id: string; name: string; email: string; role: string; profileId: string; }
interface Profile { id: string; name: string; description: string; objectPermissions: string; systemPermissions: string; }
interface Role { id: string; name: string; parentId: string | null; description: string; }
interface PermissionSet { id: string; name: string; description: string; objectPermissions: string; systemPermissions: string; assignedUsers: string; }
interface SharingRule { id: string; name: string; objectName: string; type: string; sharedFrom: string; sharedTo: string; accessLevel: string; }
interface OWD { id: string; objectName: string; defaultAccess: string; }
interface CRUD { create: boolean; read: boolean; edit: boolean; delete: boolean; viewAll: boolean; modifyAll: boolean; }

const CRUD_KEYS: (keyof CRUD)[] = ["create", "read", "edit", "delete", "viewAll", "modifyAll"];
const CRUD_LABELS: Record<keyof CRUD, string> = { create: "Create", read: "Read", edit: "Edit", delete: "Delete", viewAll: "View All", modifyAll: "Modify All" };
const EMPTY_CRUD: CRUD = { create: false, read: false, edit: false, delete: false, viewAll: false, modifyAll: false };

const SYS_PERM_CATEGORIES: Record<string, string[]> = {
    Setup: ["ManageUsers", "ManageProfiles", "ManageRoles", "ManageSharing", "CustomizeApplication"],
    Data: ["ExportData", "ImportData", "BulkDelete", "MassTransfer", "DataExport"],
    Reports: ["CreateReports", "ManageDashboards", "ViewAllReports", "ScheduleReports"],
    Users: ["ResetPasswords", "ManageLoginAccess", "AssignPermSets", "DelegateAdmin"],
    API: ["ApiAccess", "ManageConnectedApps", "ManageWebhooks", "OAuthAccess"],
};

function parseCrud(json: string | undefined, objectName: string): CRUD {
    if (!json) return { ...EMPTY_CRUD };
    try {
        const perms = JSON.parse(json);
        const obj = Array.isArray(perms) ? perms.find((p: any) => p.object === objectName) : perms[objectName];
        if (!obj) return { ...EMPTY_CRUD };
        return { create: !!obj.create, read: !!obj.read, edit: !!obj.edit, delete: !!obj.delete, viewAll: !!obj.viewAll, modifyAll: !!obj.modifyAll };
    } catch { return { ...EMPTY_CRUD }; }
}

function parseSysPerms(json: string | undefined): string[] {
    if (!json) return [];
    try { const p = JSON.parse(json); return Array.isArray(p) ? p : Object.keys(p).filter(k => p[k]); } catch { return []; }
}

function mergeCrud(a: CRUD, b: CRUD): CRUD {
    return { create: a.create || b.create, read: a.read || b.read, edit: a.edit || b.edit, delete: a.delete || b.delete, viewAll: a.viewAll || b.viewAll, modifyAll: a.modifyAll || b.modifyAll };
}

function crudHasAny(c: CRUD) { return CRUD_KEYS.some(k => c[k]); }

function accessLevel(c: CRUD): { label: string; color: string } {
    if (c.modifyAll) return { label: "Full Access", color: "green" };
    if (c.create && c.read && c.edit && c.delete) return { label: "Read-Write", color: "blue" };
    if (c.read) return { label: "Read-Only", color: "orange" };
    return { label: "No Access", color: "red" };
}

const CrudBadge = ({ val }: { val: boolean }) => val
    ? <CheckCircleFilled style={{ color: "#22c55e", fontSize: 18 }} />
    : <CloseCircleFilled style={{ color: "#ef4444", fontSize: 18 }} />;

export default function AccessAnalyzerPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const glassCard = isDark ? { background: 'rgba(30,30,30,0.78)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 } : glass;

    const [users, setUsers] = useState<User[]>([]);
    const [profiles, setProfiles] = useState<Profile[]>([]);
    const [roles, setRoles] = useState<Role[]>([]);
    const [permSets, setPermSets] = useState<PermissionSet[]>([]);
    const [sharingRules, setSharingRules] = useState<SharingRule[]>([]);
    const [owds, setOwds] = useState<OWD[]>([]);
    const [loading, setLoading] = useState(true);

    const [userId, setUserId] = useState<string | null>(null);
    const [objectName, setObjectName] = useState<string | null>(null);
    const [compareUserId, setCompareUserId] = useState<string | null>(null);
    const [showCompare, setShowCompare] = useState(false);
    const [showAllSys, setShowAllSys] = useState(false);
    const [selectedRoleId, setSelectedRoleId] = useState<string | null>(null);

    const loadAll = useCallback(async () => {
        setLoading(true);
        try {
            const [uData, pData, rData, psData, srData, oData] = await Promise.all([
                gql(`query($tenantId:String!){users(tenantId:$tenantId){id name email role profileId}}`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId:String!){rbacProfiles(tenantId:$tenantId){id name description objectPermissions systemPermissions}}`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId:String!){rbacRoles(tenantId:$tenantId){id name parentId description}}`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId:String!){rbacPermissionSets(tenantId:$tenantId){id name description objectPermissions systemPermissions assignedUsers}}`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId:String!){rbacSharingRules(tenantId:$tenantId){id name objectName type sharedFrom sharedTo accessLevel}}`, { tenantId: DEFAULT_TENANT_ID }),
                gql(`query($tenantId:String!){rbacOrgWideDefaults(tenantId:$tenantId){id objectName defaultAccess}}`, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setUsers(uData.users || []);
            setProfiles(pData.rbacProfiles || []);
            setRoles(rData.rbacRoles || []);
            setPermSets(psData.rbacPermissionSets || []);
            setSharingRules(srData.rbacSharingRules || []);
            setOwds(oData.rbacOrgWideDefaults || []);
        } catch { /* silent */ } finally { setLoading(false); }
    }, []);

    useEffect(() => { loadAll(); }, [loadAll]);

    const user = useMemo(() => users.find(u => u.id === userId), [users, userId]);
    const compareUser = useMemo(() => users.find(u => u.id === compareUserId), [users, compareUserId]);
    const objectList = useMemo(() => owds.map(o => o.objectName).sort(), [owds]);

    // --- resolve for a user ---
    const resolveAccess = useCallback((u: User | undefined, obj: string) => {
        if (!u) return { profile: null as Profile | null, profileCrud: EMPTY_CRUD, psList: [] as { ps: PermissionSet; crud: CRUD }[], psCrud: EMPTY_CRUD, owd: null as OWD | null, role: null as Role | null, rolePath: [] as Role[], matchingRules: [] as SharingRule[], effective: EMPTY_CRUD, sysPerms: [] as string[] };
        const prof = profiles.find(p => p.id === u.profileId) || null;
        const profileCrud = prof ? parseCrud(prof.objectPermissions, obj) : { ...EMPTY_CRUD };
        const userPSes = permSets.filter(ps => { try { const au = JSON.parse(ps.assignedUsers || "[]"); return au.includes(u.id); } catch { return false; } });
        const psList = userPSes.map(ps => ({ ps, crud: parseCrud(ps.objectPermissions, obj) }));
        const psCrud = psList.reduce((acc, p) => mergeCrud(acc, p.crud), { ...EMPTY_CRUD });
        const owd = owds.find(o => o.objectName === obj) || null;
        const userRole = roles.find(r => r.name === u.role) || null;
        const rolePath: Role[] = [];
        let cur = userRole;
        while (cur) { rolePath.push(cur); cur = roles.find(r => r.id === cur!.parentId) || null; }
        const matchingRules = sharingRules.filter(sr => sr.objectName === obj && (sr.sharedTo === u.role || sr.sharedTo === u.id));
        const effective = mergeCrud(profileCrud, psCrud);
        const profSys = prof ? parseSysPerms(prof.systemPermissions) : [];
        const psSys = userPSes.flatMap(ps => parseSysPerms(ps.systemPermissions));
        const sysPerms = [...new Set([...profSys, ...psSys])];
        return { profile: prof, profileCrud, psList, psCrud, owd, role: userRole, rolePath, matchingRules, effective, sysPerms };
    }, [profiles, permSets, owds, roles, sharingRules]);

    const analysis = useMemo(() => userId && objectName ? resolveAccess(user, objectName) : null, [userId, objectName, user, resolveAccess]);
    const compareAnalysis = useMemo(() => compareUserId && objectName ? resolveAccess(compareUser, objectName) : null, [compareUserId, objectName, compareUser, resolveAccess]);

    // --- waterfall steps ---
    const waterfallSteps = useMemo(() => {
        if (!analysis) return [];
        let cumulative = { ...EMPTY_CRUD };
        const steps = [
            { num: 1, name: "Profile", icon: <SafetyOutlined />, source: analysis.profile?.name || "None", crud: analysis.profileCrud, grants: crudHasAny(analysis.profileCrud) },
            { num: 2, name: "Permission Sets", icon: <ThunderboltOutlined />, source: analysis.psList.map(p => p.ps.name).join(", ") || "None", crud: analysis.psCrud, grants: crudHasAny(analysis.psCrud) },
            { num: 3, name: "Org-Wide Default", icon: <LockOutlined />, source: analysis.owd?.defaultAccess || "Not set", crud: { ...EMPTY_CRUD, read: analysis.owd?.defaultAccess !== "private" }, grants: analysis.owd?.defaultAccess !== "private" },
            { num: 4, name: "Role Hierarchy", icon: <ApartmentOutlined />, source: analysis.role?.name || "No role", crud: { ...EMPTY_CRUD, read: analysis.rolePath.length > 1 }, grants: analysis.rolePath.length > 1 },
            { num: 5, name: "Sharing Rules", icon: <ShareAltOutlined />, source: analysis.matchingRules.map(r => r.name).join(", ") || "None", crud: { ...EMPTY_CRUD, read: analysis.matchingRules.length > 0 }, grants: analysis.matchingRules.length > 0 },
        ];
        return steps.map(s => { cumulative = mergeCrud(cumulative, s.crud); return { ...s, cumulative: { ...cumulative } }; });
    }, [analysis]);

    // --- full matrix for user ---
    const fullMatrix = useMemo(() => {
        if (!user) return [];
        return objectList.map(obj => {
            const r = resolveAccess(user, obj);
            return { key: obj, object: obj, ...r.effective };
        }).sort((a, b) => a.object.localeCompare(b.object));
    }, [user, objectList, resolveAccess]);

    const matrixCols: ColumnsType<any> = [
        { title: "Object", dataIndex: "object", key: "object", width: 160, render: (v: string) => <Text strong style={{ textTransform: "capitalize" }}>{v}</Text> },
        ...CRUD_KEYS.map(k => ({
            title: CRUD_LABELS[k], dataIndex: k, key: k, width: 90, align: "center" as const,
            render: (v: boolean) => <CrudBadge val={v} />,
        })),
    ];

    // --- role tree helpers ---
    const buildHierarchyPath = (roleId: string | null): Role[] => {
        const path: Role[] = [];
        let cur = roles.find(r => r.id === roleId);
        while (cur) { path.unshift(cur); cur = roles.find(r => r.id === cur!.parentId) ?? undefined; }
        return path;
    };
    const directReports = (roleId: string) => roles.filter(r => r.parentId === roleId);
    const roleUsers = (roleName: string) => users.filter(u => u.role === roleName);

    // --- comparison matrix ---
    const comparisonMatrix = useMemo(() => {
        if (!user || !compareUser || !showCompare) return [];
        return objectList.map(obj => {
            const a = resolveAccess(user, obj);
            const b = resolveAccess(compareUser, obj);
            const hasDiff = CRUD_KEYS.some(k => a.effective[k] !== b.effective[k]);
            return { key: obj, object: obj, a: a.effective, b: b.effective, hasDiff };
        }).sort((a, b) => a.object.localeCompare(b.object));
    }, [user, compareUser, showCompare, objectList, resolveAccess]);

    const renderEffectiveSummary = (eff: CRUD, label: string, userInfo?: { profile?: string | null; psCount?: number }) => (
        <Card size="small" style={{ ...glassCard, borderTop: `3px solid ${themeColor}` }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <div>
                    <Title level={5} style={{ margin: 0 }}>{label}</Title>
                    {userInfo && (
                        <div style={{ marginTop: 4, display: "flex", gap: 8 }}>
                            {userInfo.profile && <Tag icon={<IdcardOutlined />} color="blue" style={{ fontSize: 11 }}>{userInfo.profile}</Tag>}
                            {(userInfo.psCount || 0) > 0 && <Tag icon={<ThunderboltOutlined />} color="purple" style={{ fontSize: 11 }}>{userInfo.psCount} Permission Sets</Tag>}
                        </div>
                    )}
                </div>
                <Tag color={accessLevel(eff).color} style={{ fontSize: 13, padding: "2px 12px" }}>{accessLevel(eff).label}</Tag>
            </div>
            <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
                {CRUD_KEYS.map(k => (
                    <div key={k} style={{ textAlign: "center", minWidth: 64, padding: "6px 0", borderRadius: 8, background: eff[k] ? (isDark ? "rgba(34,197,94,0.08)" : "rgba(34,197,94,0.05)") : "transparent" }}>
                        <CrudBadge val={eff[k]} />
                        <div style={{ fontSize: 11, marginTop: 2, color: isDark ? "#bbb" : "#666" }}>{CRUD_LABELS[k]}</div>
                    </div>
                ))}
            </div>
            {analysis?.owd && <div style={{ marginTop: 10 }}><Tag icon={<LockOutlined />} color="default">Record-Level: {analysis.owd.defaultAccess}</Tag></div>}
        </Card>
    );

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Access Analyzer</AuroraText>}
            subTitle={<DecryptedText text="Analyze why a user has or doesn't have access — trace permissions step by step" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            <Spin spinning={loading}>
                {/* ── Stat Cards ── */}
                <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                    {[
                        { title: "Users", value: users.length, icon: <TeamOutlined />, color: "#3b82f6" },
                        { title: "Profiles", value: profiles.length, icon: <IdcardOutlined />, color: "#10b981" },
                        { title: "Permission Sets", value: permSets.length, icon: <ThunderboltOutlined />, color: "#8b5cf6" },
                        { title: "Sharing Rules", value: sharingRules.length, icon: <ShareAltOutlined />, color: "#f59e0b" },
                    ].map((s, i) => (
                        <Col key={i} xs={12} md={6}>
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                <Card size="small" style={{ ...glassCard, borderTop: `3px solid ${s.color}` }}>
                                    <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                                </Card>
                            </motion.div>
                        </Col>
                    ))}
                </Row>
                {/* ── Selector Bar ── */}
                <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }}>
                    <Card size="small" style={{ ...glassCard, marginBottom: 16 }}>
                        <Row gutter={12} align="middle">
                            <Col xs={24} md={8}>
                                <Select placeholder="Select User" showSearch value={userId} onChange={setUserId}
                                    optionFilterProp="label" style={{ width: "100%" }} allowClear
                                    options={users.map(u => ({ value: u.id, label: `${u.name} (${u.email})` }))}
                                    suffixIcon={<UserOutlined />} />
                            </Col>
                            <Col xs={24} md={8}>
                                <Select placeholder="Select Object" showSearch value={objectName} onChange={setObjectName}
                                    optionFilterProp="label" style={{ width: "100%" }} allowClear
                                    options={objectList.map(o => ({ value: o, label: o.charAt(0).toUpperCase() + o.slice(1) }))}
                                    suffixIcon={<AppstoreOutlined />} />
                            </Col>
                            <Col xs={24} md={8}>
                                <Space>
                                    <Button type="primary" icon={<SearchOutlined />} disabled={!userId || !objectName}
                                        onClick={() => { /* already reactive */ }}>Analyze Access</Button>
                                    <Tooltip title="Compare with another user">
                                        <Button icon={<SwapOutlined />} onClick={() => setShowCompare(!showCompare)}
                                            type={showCompare ? "primary" : "default"}>Compare</Button>
                                    </Tooltip>
                                </Space>
                            </Col>
                        </Row>
                        {showCompare && (
                            <Row style={{ marginTop: 10 }}>
                                <Col xs={24} md={8}>
                                    <Select placeholder="Compare User" showSearch value={compareUserId} onChange={setCompareUserId}
                                        optionFilterProp="label" style={{ width: "100%" }} allowClear
                                        options={users.filter(u => u.id !== userId).map(u => ({ value: u.id, label: `${u.name} (${u.email})` }))}
                                        suffixIcon={<UserOutlined />} />
                                </Col>
                            </Row>
                        )}
                    </Card>
                </motion.div>

                {analysis && objectName && (
                    <>
                        {/* ── Effective Access Summary ── */}
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}>
                            <Row gutter={12} style={{ marginBottom: 16 }}>
                                <Col xs={24} md={showCompare && compareAnalysis ? 12 : 24}>
                                    {renderEffectiveSummary(analysis.effective, user?.name || "User", { profile: analysis.profile?.name, psCount: analysis.psList.length })}
                                </Col>
                                {showCompare && compareAnalysis && (
                                    <Col xs={24} md={12}>
                                        {renderEffectiveSummary(compareAnalysis.effective, compareUser?.name || "Compare User", { profile: compareAnalysis.profile?.name, psCount: compareAnalysis.psList.length })}
                                    </Col>
                                )}
                            </Row>
                        </motion.div>

                        {/* ── Comparison Diff ── */}
                        {showCompare && compareAnalysis && (
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.08 }}>
                                <Card size="small" title={<Space><SwapOutlined /> Access Differences</Space>} style={{ ...glassCard, marginBottom: 16 }}>
                                    <div style={{ display: "flex", gap: 24, flexWrap: "wrap" }}>
                                        {CRUD_KEYS.map(k => {
                                            const a = analysis.effective[k], b = compareAnalysis.effective[k];
                                            const diff = a !== b;
                                            return (
                                                <div key={k} style={{ textAlign: "center", padding: "6px 14px", borderRadius: 8, background: diff ? (isDark ? "rgba(239,68,68,0.12)" : "rgba(239,68,68,0.06)") : "transparent" }}>
                                                    <Text style={{ fontSize: 11 }}>{CRUD_LABELS[k]}</Text>
                                                    <div style={{ display: "flex", gap: 8, justifyContent: "center", marginTop: 4 }}>
                                                        <CrudBadge val={a} /><Text type="secondary">vs</Text><CrudBadge val={b} />
                                                    </div>
                                                    {diff && <Tag color="red" style={{ marginTop: 4, fontSize: 10 }}>DIFF</Tag>}
                                                </div>
                                            );
                                        })}
                                    </div>
                                </Card>
                            </motion.div>
                        )}

                        {/* ── Permission Resolution Waterfall ── */}
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
                            <Card size="small" title={<Space><ThunderboltOutlined /> Permission Resolution Waterfall</Space>} style={{ ...glassCard, marginBottom: 16 }}>
                                <div style={{ position: "relative", paddingLeft: 28 }}>
                                    <div style={{ position: "absolute", left: 13, top: 0, bottom: 0, width: 2, background: isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.08)" }} />
                                    {waterfallSteps.map((step, i) => (
                                        <motion.div key={step.num} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.12 + i * 0.06 }}
                                            style={{ position: "relative", marginBottom: i < waterfallSteps.length - 1 ? 16 : 0 }}>
                                            <div style={{ position: "absolute", left: -22, top: 8, width: 20, height: 20, borderRadius: "50%", background: step.grants ? "#22c55e" : (isDark ? "#444" : "#e5e7eb"), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, color: step.grants ? "#fff" : "#999", fontWeight: 700 }}>
                                                {step.num}
                                            </div>
                                            <Card size="small" style={{ ...glassCard, borderLeft: `3px solid ${step.grants ? "#22c55e" : (isDark ? "#555" : "#d1d5db")}` }}>
                                                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
                                                    <Space><span style={{ fontSize: 16 }}>{step.icon}</span><Text strong>{step.name}</Text></Space>
                                                    <Tag color={step.grants ? "success" : "default"}>{step.grants ? "Grants access" : "No additional access"}</Tag>
                                                </div>
                                                <div style={{ marginTop: 6, fontSize: 12 }}>
                                                    <Text type="secondary">Source:</Text> <Text>{step.source}</Text>
                                                </div>
                                                <div style={{ display: "flex", gap: 8, marginTop: 8, flexWrap: "wrap" }}>
                                                    {CRUD_KEYS.filter(k => step.crud[k]).map(k => <Tag key={k} color="green" style={{ fontSize: 11 }}>{CRUD_LABELS[k]}</Tag>)}
                                                    {!crudHasAny(step.crud) && <Tag style={{ fontSize: 11 }}>None</Tag>}
                                                </div>
                                                <div style={{ marginTop: 6, fontSize: 11, color: isDark ? "#888" : "#999" }}>
                                                    Cumulative: {CRUD_KEYS.filter(k => step.cumulative[k]).map(k => CRUD_LABELS[k]).join(", ") || "None"}
                                                </div>
                                            </Card>
                                        </motion.div>
                                    ))}
                                </div>
                            </Card>
                        </motion.div>

                        {/* ── Permission Matrix ── */}
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                            <Card size="small" title={<Space><AppstoreOutlined /> Full Object Permission Matrix</Space>} style={{ ...glassCard, marginBottom: 16 }}>
                                <Table columns={matrixCols} dataSource={fullMatrix} pagination={false} size="small" bordered scroll={{ x: 700, y: 340 }}
                                    locale={{ emptyText: "No objects available" }} />
                            </Card>
                        </motion.div>

                        {/* ── System Permissions ── */}
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.18 }}>
                            <Card size="small" title={<Space><SafetyOutlined /> System Permissions</Space>}
                                extra={<Switch size="small" checkedChildren="All" unCheckedChildren="Granted" checked={showAllSys} onChange={setShowAllSys} />}
                                style={{ ...glassCard, marginBottom: 16 }}>
                                <Collapse ghost size="small" items={Object.entries(SYS_PERM_CATEGORIES).map(([cat, perms]) => {
                                    const items = perms.map(p => ({ name: p, granted: analysis.sysPerms.includes(p), source: profiles.find(pr => parseSysPerms(pr.systemPermissions).includes(p))?.name || permSets.find(ps => parseSysPerms(ps.systemPermissions).includes(p))?.name || "—" }));
                                    const filtered = showAllSys ? items : items.filter(i => i.granted);
                                    return {
                                        key: cat,
                                        label: <Space><Text strong>{cat}</Text><Badge count={items.filter(i => i.granted).length} style={{ background: themeColor }} /></Space>,
                                        children: filtered.length === 0 ? <Text type="secondary">No permissions</Text> : (
                                            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                                                {filtered.map(p => (
                                                    <Tag key={p.name} color={p.granted ? "green" : "default"} style={{ margin: 0 }}>
                                                        {p.granted ? <CheckCircleFilled /> : <CloseCircleFilled />} {p.name}
                                                        <Text type="secondary" style={{ fontSize: 10, marginLeft: 4 }}>({p.source})</Text>
                                                    </Tag>
                                                ))}
                                            </div>
                                        ),
                                    };
                                })} />
                            </Card>
                        </motion.div>

                        {/* ── Comparison Matrix (side-by-side all objects) ── */}
                        {showCompare && compareAnalysis && comparisonMatrix.length > 0 && (
                            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.19 }}>
                                <Card size="small" title={<Space><SwapOutlined /> Full Comparison Matrix</Space>}
                                    style={{ ...glassCard, marginBottom: 16 }}>
                                    <Table size="small" bordered pagination={false} scroll={{ x: 900, y: 300 }}
                                        dataSource={comparisonMatrix}
                                        columns={[
                                            { title: "Object", dataIndex: "object", key: "object", width: 130, fixed: "left",
                                                render: (v: string, rec: any) => (
                                                    <Space>
                                                        <Text strong style={{ textTransform: "capitalize" }}>{v}</Text>
                                                        {rec.hasDiff && <Badge dot color="red" />}
                                                    </Space>
                                                ) },
                                            ...CRUD_KEYS.flatMap(k => [
                                                { title: <Tooltip title={`${user?.name} — ${CRUD_LABELS[k]}`}><Text style={{ fontSize: 11 }}>A</Text></Tooltip>,
                                                    key: `a_${k}`, width: 48, align: "center" as const,
                                                    render: (_: any, rec: any) => {
                                                        const diff = rec.a[k] !== rec.b[k];
                                                        return <span style={diff ? { background: isDark ? "rgba(239,68,68,0.15)" : "rgba(239,68,68,0.08)", borderRadius: 4, padding: 2 } : {}}><CrudBadge val={rec.a[k]} /></span>;
                                                    } },
                                                { title: <Tooltip title={`${compareUser?.name} — ${CRUD_LABELS[k]}`}><Text style={{ fontSize: 11 }}>B</Text></Tooltip>,
                                                    key: `b_${k}`, width: 48, align: "center" as const,
                                                    render: (_: any, rec: any) => {
                                                        const diff = rec.a[k] !== rec.b[k];
                                                        return <span style={diff ? { background: isDark ? "rgba(239,68,68,0.15)" : "rgba(239,68,68,0.08)", borderRadius: 4, padding: 2 } : {}}><CrudBadge val={rec.b[k]} /></span>;
                                                    } },
                                            ]),
                                        ]} />
                                    <div style={{ marginTop: 8, fontSize: 11, color: isDark ? "#888" : "#999" }}>
                                        <Text type="secondary">A = {user?.name} | B = {compareUser?.name} | </Text>
                                        <Badge dot color="red" /> <Text type="secondary">= differences found</Text>
                                    </div>
                                </Card>
                            </motion.div>
                        )}

                        {/* ── Role Hierarchy Visualization ── */}
                        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                            <Card size="small" title={<Space><ApartmentOutlined /> Role Hierarchy</Space>} style={{ ...glassCard }}>
                                {analysis.role ? (
                                    <Row gutter={16}>
                                        <Col xs={24} md={8}>
                                            <Text type="secondary" style={{ fontSize: 12, marginBottom: 8, display: "block" }}>Path to Top</Text>
                                            <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                                                {buildHierarchyPath(analysis.role.id).map((r, i) => (
                                                    <div key={r.id} style={{ display: "flex", alignItems: "center", gap: 6, paddingLeft: i * 16 }}>
                                                        {i > 0 && <DownOutlined style={{ fontSize: 9, color: "#999" }} />}
                                                        <Tag color={r.id === analysis.role!.id ? themeColor : "default"}
                                                            style={r.id === analysis.role!.id ? { border: `2px solid ${themeColor}`, fontWeight: 700, boxShadow: `0 0 8px ${themeColor}33` } : { cursor: "pointer" }}
                                                            onClick={() => setSelectedRoleId(r.id)}
                                                            icon={i === 0 ? <CrownOutlined /> : <ApartmentOutlined />}>
                                                            {r.name}
                                                        </Tag>
                                                    </div>
                                                ))}
                                            </div>
                                        </Col>
                                        <Col xs={24} md={8}>
                                            <Text type="secondary" style={{ fontSize: 12, marginBottom: 8, display: "block" }}>Direct Reports ({directReports(analysis.role.id).length})</Text>
                                            <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                                                {directReports(analysis.role.id).length > 0
                                                    ? directReports(analysis.role.id).map(r => (
                                                        <Tag key={r.id} onClick={() => setSelectedRoleId(r.id)}
                                                            style={{ cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 4 }}
                                                            icon={<ApartmentOutlined />}>
                                                            {r.name}
                                                            <Badge count={roleUsers(r.name).length} size="small"
                                                                style={{ background: "#8b5cf6", marginLeft: 4 }} />
                                                        </Tag>
                                                    ))
                                                    : <Text type="secondary" style={{ fontSize: 12 }}>No direct reports</Text>}
                                            </div>
                                        </Col>
                                        <Col xs={24} md={8}>
                                            <Text type="secondary" style={{ fontSize: 12, marginBottom: 8, display: "block" }}>
                                                {selectedRoleId ? `Users in ${roles.find(r => r.id === selectedRoleId)?.name}` : "Click a role to see users"}
                                            </Text>
                                            {selectedRoleId ? (
                                                <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                                                    {roleUsers(roles.find(r => r.id === selectedRoleId)?.name || "").map(u => (
                                                        <Tag key={u.id} icon={<UserOutlined />}
                                                            color={u.id === userId ? themeColor : "default"}
                                                            style={u.id === userId ? { fontWeight: 600 } : {}}>
                                                            {u.name} <Text type="secondary" style={{ fontSize: 10 }}>({u.email})</Text>
                                                        </Tag>
                                                    ))}
                                                    {roleUsers(roles.find(r => r.id === selectedRoleId)?.name || "").length === 0 && (
                                                        <Text type="secondary" style={{ fontSize: 12 }}>No users assigned to this role</Text>
                                                    )}
                                                </div>
                                            ) : (
                                                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="" style={{ margin: 0 }} />
                                            )}
                                        </Col>
                                    </Row>
                                ) : <Empty description="No role assigned to this user" />}
                            </Card>
                        </motion.div>
                    </>
                )}

                {!analysis && !loading && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ marginTop: 60 }}>
                        <Empty description="Select a user and object above to analyze access permissions" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                    </motion.div>
                )}
            </Spin>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Space, Tag, Card, Select, DatePicker,
    message, Typography, Spin, Row, Col, Statistic, Tooltip, Empty,
} from "antd";
import { motion } from "framer-motion";
import {
    ReloadOutlined, FileExcelOutlined, FilePdfOutlined, AuditOutlined,
    UserOutlined, AppstoreOutlined, CalendarOutlined, DownloadOutlined,
    ClockCircleOutlined, BarChartOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import isToday from "dayjs/plugin/isToday";

dayjs.extend(relativeTime);
dayjs.extend(isToday);

const { Text } = Typography;
const { RangePicker } = DatePicker;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface ExportLog {
    id: string;
    userId: string;
    userEmail: string;
    userName: string;
    exportType: string;
    module: string;
    fileName: string;
    recordCount: number;
    dateRangeStart: string;
    dateRangeEnd: string;
    userAgent: string;
    createdAt: string;
}

interface ExportLogResult {
    logs: ExportLog[];
    total: number;
}

const MODULE_COLORS: Record<string, string> = {
    itsm: '#ef4444', crm: '#3b82f6', hr: '#8b5cf6', pm: '#f59e0b',
    inventory: '#10b981', ecommerce: '#ec4899', accounting: '#6366f1',
    ops: '#0891b2', commerce: '#d946ef', notifications: '#f97316',
};

function getModuleColor(module: string): string {
    const prefix = (module.split('.')[0] || module.split('_')[0])?.toLowerCase();
    return MODULE_COLORS[prefix] || '#64748b';
}

export default function ExportLogsPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [logs, setLogs] = useState<ExportLog[]>([]);
    const [total, setTotal] = useState(0);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(1);
    const [pageSize] = useState(25);

    // Filters
    const [filterModule, setFilterModule] = useState<string | undefined>();
    const [filterType, setFilterType] = useState<string | undefined>();
    const [filterDateRange, setFilterDateRange] = useState<[dayjs.Dayjs, dayjs.Dayjs] | null>(null);

    const loadLogs = useCallback(async () => {
        setLoading(true);
        try {
            const offset = (page - 1) * pageSize;
            const data = await gql<{ dataExportLogs: ExportLogResult }>(`
                query($tenantId: String!, $limit: Float, $offset: Float) {
                    dataExportLogs(tenantId: $tenantId, limit: $limit, offset: $offset) {
                        logs {
                            id userId userEmail userName exportType module
                            fileName recordCount dateRangeStart dateRangeEnd
                            userAgent createdAt
                        }
                        total
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID, limit: 200, offset: 0 });
            const all = data.dataExportLogs?.logs || [];
            setTotal(data.dataExportLogs?.total || 0);

            // Client-side filtering (server returns all for stats)
            let filtered = all;
            if (filterModule) filtered = filtered.filter(l => l.module?.includes(filterModule));
            if (filterType) filtered = filtered.filter(l => l.exportType === filterType);
            if (filterDateRange) {
                const [start, end] = filterDateRange;
                filtered = filtered.filter(l => {
                    const d = dayjs(l.createdAt);
                    return d.isAfter(start.startOf('day')) && d.isBefore(end.endOf('day'));
                });
            }

            setLogs(filtered);
        } catch (err: any) {
            message.error("Failed to load export logs: " + err.message);
        } finally {
            setLoading(false);
        }
    }, [page, pageSize, filterModule, filterType, filterDateRange]);

    useEffect(() => { loadLogs(); }, [loadLogs]);

    // Stats
    const todayCount = logs.filter(l => dayjs(l.createdAt).isToday()).length;
    const uniqueUsers = new Set(logs.map(l => l.userEmail)).size;
    const pdfCount = logs.filter(l => l.exportType === 'pdf').length;
    const excelCount = logs.filter(l => l.exportType === 'excel').length;
    const totalRecords = logs.reduce((sum, l) => sum + (l.recordCount || 0), 0);

    // Top module
    const moduleCounts: Record<string, number> = {};
    logs.forEach(l => { moduleCounts[l.module] = (moduleCounts[l.module] || 0) + 1; });
    const topModule = Object.entries(moduleCounts).sort((a, b) => b[1] - a[1])[0];

    // Unique modules for filter
    const allModules = [...new Set(logs.map(l => l.module))].sort();

    const columns: ColumnsType<ExportLog> = [
        {
            title: "Time",
            key: "createdAt",
            width: 160,
            sorter: (a, b) => dayjs(a.createdAt).unix() - dayjs(b.createdAt).unix(),
            defaultSortOrder: 'descend',
            render: (_, r) => (
                <Tooltip title={dayjs(r.createdAt).format('YYYY-MM-DD HH:mm:ss')}>
                    <Space size={4}>
                        <ClockCircleOutlined style={{ color: '#94a3b8' }} />
                        <Text style={{ fontSize: 12 }}>{dayjs(r.createdAt).fromNow()}</Text>
                    </Space>
                </Tooltip>
            ),
        },
        {
            title: "User",
            key: "user",
            width: 200,
            render: (_, r) => (
                <Space size={4}>
                    <UserOutlined style={{ color: '#3b82f6' }} />
                    <div>
                        <Text strong style={{ fontSize: 13 }}>{r.userName || 'Unknown'}</Text>
                        <br />
                        <Text type="secondary" style={{ fontSize: 11 }}>{r.userEmail}</Text>
                    </div>
                </Space>
            ),
        },
        {
            title: "Type",
            key: "exportType",
            width: 90,
            align: 'center',
            filters: [{ text: 'PDF', value: 'pdf' }, { text: 'Excel', value: 'excel' }],
            onFilter: (val, r) => r.exportType === val,
            render: (_, r) => (
                r.exportType === 'pdf'
                    ? <Tag icon={<FilePdfOutlined />} color="red">PDF</Tag>
                    : <Tag icon={<FileExcelOutlined />} color="green">Excel</Tag>
            ),
        },
        {
            title: "Module",
            key: "module",
            width: 180,
            render: (_, r) => (
                <Tag color={getModuleColor(r.module)} style={{ textTransform: 'capitalize' }}>
                    {r.module?.replace(/[._]/g, ' ')}
                </Tag>
            ),
        },
        {
            title: "Records",
            dataIndex: "recordCount",
            key: "recordCount",
            width: 90,
            align: 'right',
            sorter: (a, b) => a.recordCount - b.recordCount,
            render: (v) => <Text strong>{(v || 0).toLocaleString()}</Text>,
        },
        {
            title: "File",
            dataIndex: "fileName",
            key: "fileName",
            ellipsis: true,
            render: (v) => (
                <Tooltip title={v}>
                    <Text code style={{ fontSize: 11 }}>{v}</Text>
                </Tooltip>
            ),
        },
    ];

    const stats = [
        { title: 'Total Exports', value: total, icon: <DownloadOutlined />, color: '#3b82f6' },
        { title: 'Today', value: todayCount, icon: <CalendarOutlined />, color: '#10b981' },
        { title: 'PDF Exports', value: pdfCount, icon: <FilePdfOutlined />, color: '#ef4444' },
        { title: 'Excel Exports', value: excelCount, icon: <FileExcelOutlined />, color: '#22c55e' },
        { title: 'Unique Users', value: uniqueUsers, icon: <UserOutlined />, color: '#8b5cf6' },
        { title: 'Records Exported', value: totalRecords, icon: <BarChartOutlined />, color: '#f59e0b' },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Export Audit Log</AuroraText>}
            subTitle={<DecryptedText text="Compliance audit trail — track all data exports across modules" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exports" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'export_audit_log', title: 'Export Audit Log', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'User', key: 'userName' }, { header: 'Email', key: 'userEmail' }, { header: 'Type', key: 'exportType' }, { header: 'Module', key: 'module' }, { header: 'File', key: 'fileName' }, { header: 'Records', key: 'recordCount' }, { header: 'Date', key: 'createdAt' }], data: logs })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'export_audit_log', title: 'Export Audit Log', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'User', key: 'userName' }, { header: 'Email', key: 'userEmail' }, { header: 'Type', key: 'exportType' }, { header: 'Module', key: 'module' }, { header: 'File', key: 'fileName' }, { header: 'Records', key: 'recordCount' }, { header: 'Date', key: 'createdAt' }], data: logs })} /></Tooltip></RbacGuard>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadLogs} />,
            ]}
        >
            {/* Stats Row */}
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {stats.map((s, i) => (
                    <Col key={i} xs={12} sm={8} md={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color, fontSize: 20 }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* Top Module Banner */}
            {topModule && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                    <Card size="small" style={{ ...glass, marginBottom: 16, borderLeft: `4px solid ${getModuleColor(topModule[0])}` }}>
                        <Space>
                            <AppstoreOutlined style={{ fontSize: 18, color: getModuleColor(topModule[0]) }} />
                            <Text>Most exported module: <Text strong style={{ textTransform: 'capitalize' }}>{topModule[0]?.replace(/[._]/g, ' ')}</Text> ({topModule[1]} exports)</Text>
                        </Space>
                    </Card>
                </motion.div>
            )}

            {/* Filters */}
            <Card size="small" style={{ marginBottom: 16 }}>
                <Space wrap>
                    <Select
                        placeholder="Filter by module"
                        allowClear
                        style={{ width: 200 }}
                        value={filterModule}
                        onChange={setFilterModule}
                        options={allModules.map(m => ({ label: m.replace(/[._]/g, ' '), value: m }))}
                    />
                    <Select
                        placeholder="Export type"
                        allowClear
                        style={{ width: 140 }}
                        value={filterType}
                        onChange={setFilterType}
                        options={[{ label: 'PDF', value: 'pdf' }, { label: 'Excel', value: 'excel' }]}
                    />
                    <RangePicker
                        value={filterDateRange}
                        onChange={(dates) => setFilterDateRange(dates as [dayjs.Dayjs, dayjs.Dayjs] | null)}
                    />
                    {(filterModule || filterType || filterDateRange) && (
                        <Button type="link" onClick={() => { setFilterModule(undefined); setFilterType(undefined); setFilterDateRange(null); }}>
                            Clear filters
                        </Button>
                    )}
                </Space>
            </Card>

            {/* Table */}
            <Card>
                <Table scroll={{ x: 900 }}
                    columns={columns}
                    dataSource={logs.map(l => ({ ...l, key: l.id }))}
                    loading={loading}
                    pagination={{
                        total: logs.length,
                        pageSize,
                        showSizeChanger: false,
                        showTotal: (t) => `${t} export records`,
                    }}
                    size="middle"
                    locale={{
                        emptyText: (
                            <Empty
                                image={Empty.PRESENTED_IMAGE_SIMPLE}
                                description="No export activity recorded yet. Exports will appear here automatically."
                            />
                        ),
                    }}
                />
            </Card>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Card, Tabs, Table, Button, Space, Modal, Form, Input,
    message, Typography, Row, Col, Statistic, Badge, Tooltip,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, DeleteOutlined, ReloadOutlined,
    TeamOutlined, UsergroupAddOutlined, FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Team {
    id: string;
    name: string;
    description: string;
}

interface PublicGroup {
    id: string;
    name: string;
    description: string;
}

const TEAM_FIELDS: FieldDef[] = [
    { name: "name", label: "Team Name", required: true },
    { name: "description", label: "Description" },
];

const GROUP_FIELDS: FieldDef[] = [
    { name: "name", label: "Group Name", required: true },
    { name: "description", label: "Description" },
];

export default function GroupsTeamsPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [teams, setTeams] = useState<Team[]>([]);
    const [teamsLoading, setTeamsLoading] = useState(true);
    const [teamModalOpen, setTeamModalOpen] = useState(false);
    const [teamForm] = Form.useForm();

    const [groups, setGroups] = useState<PublicGroup[]>([]);
    const [groupsLoading, setGroupsLoading] = useState(true);
    const [groupModalOpen, setGroupModalOpen] = useState(false);
    const [groupForm] = Form.useForm();

    const loadTeams = useCallback(async () => {
        setTeamsLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    teams(tenantId: $tenantId) { id name description }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setTeams(data.teams || []);
        } catch (err: any) {
            message.error(err.message);
        } finally {
            setTeamsLoading(false);
        }
    }, []);

    const loadGroups = useCallback(async () => {
        setGroupsLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    publicGroups(tenantId: $tenantId) { id name description }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setGroups(data.publicGroups || []);
        } catch (err: any) {
            message.error(err.message);
        } finally {
            setGroupsLoading(false);
        }
    }, []);

    useEffect(() => { loadTeams(); loadGroups(); }, [loadTeams, loadGroups]);

    const handleCreateTeam = async (values: any) => {
        try {
            await gql(`
                mutation($tenantId: String!, $name: String!, $description: String) {
                    createTeam(tenantId: $tenantId, name: $name, description: $description) { id }
                }
            `, { tenantId: DEFAULT_TENANT_ID, ...values });
            message.success("Team created");
            setTeamModalOpen(false);
            teamForm.resetFields();
            loadTeams();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleBatchCreateTeams = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $name: String!, $description: String) {
                    createTeam(tenantId: $tenantId, name: $name, description: $description) { id }
                }`, { tenantId: DEFAULT_TENANT_ID, name: r.name, description: r.description || null });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadTeams(); return { success, failed, errors };
    };

    const handleDeleteTeam = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteTeam(id: $id) }`, { id });
            message.success("Team deleted");
            loadTeams();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleCreateGroup = async (values: any) => {
        try {
            await gql(`
                mutation($tenantId: String!, $name: String!, $description: String) {
                    createPublicGroup(tenantId: $tenantId, name: $name, description: $description) { id }
                }
            `, { tenantId: DEFAULT_TENANT_ID, ...values });
            message.success("Public group created");
            setGroupModalOpen(false);
            groupForm.resetFields();
            loadGroups();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleBatchCreateGroups = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $name: String!, $description: String) {
                    createPublicGroup(tenantId: $tenantId, name: $name, description: $description) { id }
                }`, { tenantId: DEFAULT_TENANT_ID, name: r.name, description: r.description || null });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadGroups(); return { success, failed, errors };
    };

    const handleDeleteGroup = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deletePublicGroup(id: $id) }`, { id });
            message.success("Group deleted");
            loadGroups();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const teamColumns: ColumnsType<Team> = [
        {
            title: "Team", key: "team",
            render: (_, record) => (
                <Space>
                    <TeamOutlined style={{ fontSize: 18, color: '#1677ff' }} />
                    <div>
                        <Text strong>{record.name}</Text>
                        <br />
                        <Text type="secondary" style={{ fontSize: 12 }}>{record.description || 'No description'}</Text>
                    </div>
                </Space>
            ),
        },
        {
            title: "Actions", key: "actions", width: 100,
            render: (_, record) => (
                <Button type="text" danger icon={<DeleteOutlined />}
                    onClick={() => Modal.confirm({ title: `Delete team "${record.name}"?`, onOk: () => handleDeleteTeam(record.id) })}
                />
            ),
        },
    ];

    const groupColumns: ColumnsType<PublicGroup> = [
        {
            title: "Group", key: "group",
            render: (_, record) => (
                <Space>
                    <UsergroupAddOutlined style={{ fontSize: 18, color: '#52c41a' }} />
                    <div>
                        <Text strong>{record.name}</Text>
                        <br />
                        <Text type="secondary" style={{ fontSize: 12 }}>{record.description || 'No description'}</Text>
                    </div>
                </Space>
            ),
        },
        {
            title: "Actions", key: "actions", width: 100,
            render: (_, record) => (
                <Button type="text" danger icon={<DeleteOutlined />}
                    onClick={() => Modal.confirm({ title: `Delete group "${record.name}"?`, onOk: () => handleDeleteGroup(record.id) })}
                />
            ),
        },
    ];

    const teamFormSteps = [
        {
            title: "Team Info",
            icon: <TeamOutlined />,
            fields: ["name", "description"],
            content: (
                <>
                    <Form.Item name="name" label="Team Name" rules={[{ required: true }]}>
                        <Input placeholder="e.g., West Region Sales" />
                    </Form.Item>
                    <Form.Item name="description" label="Description">
                        <Input.TextArea placeholder="Purpose of this team" rows={2} />
                    </Form.Item>
                </>
            ),
        },
    ];

    const groupFormSteps = [
        {
            title: "Group Info",
            icon: <UsergroupAddOutlined />,
            fields: ["name", "description"],
            content: (
                <>
                    <Form.Item name="name" label="Group Name" rules={[{ required: true }]}>
                        <Input placeholder="e.g., All Sales Managers" />
                    </Form.Item>
                    <Form.Item name="description" label="Description">
                        <Input.TextArea placeholder="Purpose of this group" rows={2} />
                    </Form.Item>
                </>
            ),
        },
    ];

    const tabItems = [
        {
            key: "teams",
            label: <Space><TeamOutlined /> Teams</Space>,
            children: (
                <>
                    <div style={{ marginBottom: 16 }}>
                        <Button type="primary" icon={<PlusOutlined />} onClick={() => { teamForm.resetFields(); setTeamModalOpen(true); }}>
                            Create Team
                        </Button>
                    </div>
                    <Table scroll={{ x: 900 }} columns={teamColumns} dataSource={teams.map(t => ({ ...t, key: t.id }))} loading={teamsLoading}
                        pagination={false} size="middle" locale={{ emptyText: "No teams yet" }} />
                </>
            ),
        },
        {
            key: "groups",
            label: <Space><UsergroupAddOutlined /> Public Groups</Space>,
            children: (
                <>
                    <div style={{ marginBottom: 16 }}>
                        <Button type="primary" icon={<PlusOutlined />} onClick={() => { groupForm.resetFields(); setGroupModalOpen(true); }}>
                            Create Public Group
                        </Button>
                    </div>
                    <Table scroll={{ x: 900 }} columns={groupColumns} dataSource={groups.map(g => ({ ...g, key: g.id }))} loading={groupsLoading}
                        pagination={false} size="middle" locale={{ emptyText: "No public groups yet" }} />
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Groups & Teams</AuroraText>}
            subTitle={<DecryptedText text="Manage teams for record-level access and public groups for sharing" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exports" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'groups_teams', title: 'Groups & Teams', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Type', key: 'type' }, { header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }], data: [...teams.map(t => ({ ...t, type: 'Team' })), ...groups.map(g => ({ ...g, type: 'Public Group' }))] })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'groups_teams', title: 'Groups & Teams', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Type', key: 'type' }, { header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }], data: [...teams.map(t => ({ ...t, type: 'Team' })), ...groups.map(g => ({ ...g, type: 'Public Group' }))] })} /></Tooltip></RbacGuard>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={() => { loadTeams(); loadGroups(); }} />,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Teams', value: teams.length, icon: <TeamOutlined />, color: '#3b82f6' },
                    { title: 'Public Groups', value: groups.length, icon: <UsergroupAddOutlined />, color: '#10b981' },
                    { title: 'Total Entities', value: teams.length + groups.length, icon: <TeamOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <Card><Tabs items={tabItems} /></Card>

            <SteppedFormModal
                open={teamModalOpen}
                onCancel={() => { setTeamModalOpen(false); teamForm.resetFields(); }}
                onSubmit={handleCreateTeam}
                form={teamForm}
                title="Create Team"
                entityName="team"
                steps={teamFormSteps}
                fields={TEAM_FIELDS}
                width={500}
                onBatchCreate={handleBatchCreateTeams}
                gradient={["#1677ff", "#0ea5e9"]}
            />

            <SteppedFormModal
                open={groupModalOpen}
                onCancel={() => { setGroupModalOpen(false); groupForm.resetFields(); }}
                onSubmit={handleCreateGroup}
                form={groupForm}
                title="Create Public Group"
                entityName="public-group"
                steps={groupFormSteps}
                fields={GROUP_FIELDS}
                width={500}
                onBatchCreate={handleBatchCreateGroups}
                gradient={["#52c41a", "#10b981"]}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Space, Modal, Form, Input, Card, Tag, Tooltip,
    message, Typography, Checkbox, Spin, Row, Col, Statistic,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, DeleteOutlined, ReloadOutlined,
    KeyOutlined, SettingOutlined, FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface PermissionSet {
    id: string;
    name: string;
    description: string;
    isSystem: boolean;
    tenantId: string;
}

interface ObjPerm {
    id: string;
    objectName: string;
    canCreate: boolean;
    canRead: boolean;
    canEdit: boolean;
    canDelete: boolean;
    canViewAll: boolean;
    canModifyAll: boolean;
}

const SYSTEM_OBJECTS = [
    "pages", "media", "blocks", "users", "settings", "datasets",
    "individuals", "accounts", "contacts", "leads", "opportunities",
    "cases", "activities", "projects", "tasks", "teams",
];

const PS_FIELDS: FieldDef[] = [
    { name: "name", label: "Name", required: true },
    { name: "description", label: "Description" },
];

export default function PermissionSetsPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [sets, setSets] = useState<PermissionSet[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [form] = Form.useForm();

    const [selectedPS, setSelectedPS] = useState<PermissionSet | null>(null);
    const [permsOpen, setPermsOpen] = useState(false);
    const [objPerms, setObjPerms] = useState<ObjPerm[]>([]);
    const [permsLoading, setPermsLoading] = useState(false);

    const loadSets = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    permissionSets(tenantId: $tenantId) {
                        id name description isSystem tenantId
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setSets(data.permissionSets || []);
        } catch (err: any) {
            message.error("Failed to load: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadSets(); }, [loadSets]);

    const loadObjPerms = async (psId: string) => {
        setPermsLoading(true);
        try {
            const data = await gql(`
                query($permissionSetId: String!) {
                    permissionSetObjectPermissions(permissionSetId: $permissionSetId) {
                        id objectName canCreate canRead canEdit canDelete canViewAll canModifyAll
                    }
                }
            `, { permissionSetId: psId });
            setObjPerms(data.permissionSetObjectPermissions || []);
        } catch (err: any) {
            message.error(err.message);
        } finally {
            setPermsLoading(false);
        }
    };

    const handleSave = async (values: any) => {
        try {
            await gql(`
                mutation($tenantId: String!, $name: String!, $description: String) {
                    createPermissionSet(tenantId: $tenantId, name: $name, description: $description) { id }
                }
            `, { tenantId: DEFAULT_TENANT_ID, name: values.name, description: values.description });
            message.success("Permission set created");
            setIsModalOpen(false);
            form.resetFields();
            loadSets();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $name: String!, $description: String) {
                    createPermissionSet(tenantId: $tenantId, name: $name, description: $description) { id }
                }`, { tenantId: DEFAULT_TENANT_ID, name: r.name, description: r.description || null });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadSets(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deletePermissionSet(id: $id) }`, { id });
            message.success("Permission set deleted");
            loadSets();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handlePermChange = async (objectName: string, field: string, value: boolean) => {
        if (!selectedPS) return;
        const existing = objPerms.find(p => p.objectName === objectName);
        const input = {
            objectName,
            canCreate: existing?.canCreate ?? false,
            canRead: existing?.canRead ?? false,
            canEdit: existing?.canEdit ?? false,
            canDelete: existing?.canDelete ?? false,
            canViewAll: existing?.canViewAll ?? false,
            canModifyAll: existing?.canModifyAll ?? false,
            [field]: value,
        };
        try {
            await gql(`
                mutation($permissionSetId: String!, $objectName: String!, $canCreate: Boolean, $canRead: Boolean, $canEdit: Boolean, $canDelete: Boolean, $canViewAll: Boolean, $canModifyAll: Boolean) {
                    upsertPermissionSetObjectPermission(
                        permissionSetId: $permissionSetId, objectName: $objectName,
                        canCreate: $canCreate, canRead: $canRead, canEdit: $canEdit,
                        canDelete: $canDelete, canViewAll: $canViewAll, canModifyAll: $canModifyAll
                    ) { id }
                }
            `, { permissionSetId: selectedPS.id, ...input });
            setObjPerms(prev => {
                const idx = prev.findIndex(p => p.objectName === objectName);
                const updated = { ...existing, id: existing?.id || '', ...input } as ObjPerm;
                if (idx >= 0) { const n = [...prev]; n[idx] = updated; return n; }
                return [...prev, updated];
            });
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const columns: ColumnsType<PermissionSet> = [
        {
            title: "Permission Set", key: "ps",
            render: (_, record) => (
                <Space>
                    <KeyOutlined style={{ fontSize: 18, color: '#1677ff' }} />
                    <div>
                        <Text strong>{record.name}</Text>
                        {record.isSystem && <Tag color="gold" style={{ marginLeft: 8 }}>System</Tag>}
                        <br />
                        <Text type="secondary" style={{ fontSize: 12 }}>{record.description}</Text>
                    </div>
                </Space>
            ),
        },
        {
            title: "Actions", key: "actions", width: 160,
            render: (_, record) => (
                <Space>
                    <Button type="text" icon={<SettingOutlined />} onClick={() => { setSelectedPS(record); setPermsOpen(true); loadObjPerms(record.id); }}>
                        Configure
                    </Button>
                    <Button type="text" danger icon={<DeleteOutlined />} disabled={record.isSystem}
                        onClick={() => Modal.confirm({ title: `Delete "${record.name}"?`, onOk: () => handleDelete(record.id) })}
                    />
                </Space>
            ),
        },
    ];

    const permColumns: ColumnsType<{ object: string }> = [
        { title: "Object", dataIndex: "object", key: "object", width: 150, render: (v) => <Text strong style={{ textTransform: 'capitalize' }}>{v}</Text> },
        ...["canCreate", "canRead", "canEdit", "canDelete", "canViewAll", "canModifyAll"].map(field => ({
            title: field.replace("can", "").replace("All", " All"),
            key: field, width: 90, align: "center" as const,
            render: (_: any, record: { object: string }) => {
                const perm = objPerms.find(p => p.objectName === record.object);
                const checked = perm ? (perm as any)[field] : false;
                return <Checkbox checked={checked} onChange={e => handlePermChange(record.object, field, e.target.checked)} />;
            },
        })),
    ];

    const formSteps = [
        {
            title: "Permission Set",
            icon: <KeyOutlined />,
            fields: ["name", "description"],
            content: (
                <>
                    <Form.Item name="name" label="Name" rules={[{ required: true }]}>
                        <Input placeholder="e.g., Marketing Tools Access" />
                    </Form.Item>
                    <Form.Item name="description" label="Description">
                        <Input.TextArea placeholder="What does this permission set grant?" rows={2} />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Permission Sets</AuroraText>}
            subTitle={<DecryptedText text="Additive permissions assigned to individual users" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exports" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'permission_sets', title: 'Permission Sets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }, { header: 'System', key: 'isSystem', format: (v: boolean) => v ? 'Yes' : 'No' }], data: sets })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'permission_sets', title: 'Permission Sets', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }, { header: 'System', key: 'isSystem', format: (v: boolean) => v ? 'Yes' : 'No' }], data: sets })} /></Tooltip></RbacGuard>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadSets} />,
                <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { form.resetFields(); setIsModalOpen(true); }}>
                    Create Permission Set
                </Button>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Sets', value: sets.length, icon: <KeyOutlined />, color: '#3b82f6' },
                    { title: 'System Sets', value: sets.filter(s => s.isSystem).length, icon: <SettingOutlined />, color: '#f59e0b' },
                    { title: 'Custom Sets', value: sets.filter(s => !s.isSystem).length, icon: <KeyOutlined />, color: '#10b981' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <Card>
                <Table columns={columns} dataSource={sets.map(s => ({ ...s, key: s.id }))} loading={loading} pagination={false} size="middle" />
            </Card>

            <SteppedFormModal
                open={isModalOpen}
                onCancel={() => { setIsModalOpen(false); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title="Create Permission Set"
                entityName="permission-set"
                steps={formSteps}
                fields={PS_FIELDS}
                width={520}
                onBatchCreate={handleBatchCreate}
                gradient={["#0ea5e9", "#6366f1"]}
            />

            {/* Permissions Configuration Modal — kept as separate specialized workflow */}
            <Modal title={<Space><KeyOutlined /> Permissions — {selectedPS?.name}</Space>}
                open={permsOpen} onCancel={() => setPermsOpen(false)} footer={null} width={900}>
                <Spin spinning={permsLoading}>
                    <Table columns={permColumns} dataSource={SYSTEM_OBJECTS.map(obj => ({ key: obj, object: obj }))}
                        pagination={false} size="small" bordered scroll={{ y: 400 }} />
                </Spin>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Table, Button, Tag, Space, Modal, Form, Input, Switch,
    Card, Checkbox, message, Tooltip, Typography, Spin, Row, Col, Statistic, Divider,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, SafetyOutlined,
    ReloadOutlined, IdcardOutlined, SettingOutlined,
    FileExcelOutlined, FilePdfOutlined, CloudDownloadOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Profile {
    id: string;
    name: string;
    description: string;
    isSystem: boolean;
    isCustom: boolean;
    tenantId: string;
}

interface ObjectPermission {
    id: string;
    objectName: string;
    canCreate: boolean;
    canRead: boolean;
    canEdit: boolean;
    canDelete: boolean;
    canViewAll: boolean;
    canModifyAll: boolean;
}

const SYSTEM_OBJECTS = [
    "pages", "media", "blocks", "users", "settings", "datasets",
    "individuals", "accounts", "contacts", "leads", "opportunities",
    "cases", "activities", "projects", "tasks", "teams",
];

const EXPORT_PERMISSION_KEYS = [
    { key: 'export.pdf', label: 'PDF Export', description: 'Allow exporting data as PDF reports', icon: <FilePdfOutlined style={{ color: '#ef4444' }} /> },
    { key: 'export.excel', label: 'Excel Export', description: 'Allow exporting data as Excel spreadsheets', icon: <FileExcelOutlined style={{ color: '#22c55e' }} /> },
    { key: 'export.bulk', label: 'Bulk Export', description: 'Allow exporting all records (no row limit)', icon: <CloudDownloadOutlined style={{ color: '#3b82f6' }} /> },
];

const PROFILE_FIELDS: FieldDef[] = [
    { name: "name", label: "Profile Name", required: true },
    { name: "description", label: "Description" },
];

export default function ProfilesPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [profiles, setProfiles] = useState<Profile[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [form] = Form.useForm();

    const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);
    const [objectPerms, setObjectPerms] = useState<ObjectPermission[]>([]);
    const [permsLoading, setPermsLoading] = useState(false);
    const [permsDrawerOpen, setPermsDrawerOpen] = useState(false);
    const [exportPerms, setExportPerms] = useState<Record<string, boolean>>({});

    const loadProfiles = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    profiles(tenantId: $tenantId) {
                        id name description isSystem isCustom tenantId
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setProfiles(data.profiles || []);
        } catch (err: any) {
            message.error("Failed to load profiles: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadProfiles(); }, [loadProfiles]);

    const loadObjectPermissions = async (profileId: string) => {
        setPermsLoading(true);
        try {
            const data = await gql(`
                query($profileId: String!) {
                    profileObjectPermissions(profileId: $profileId) {
                        id objectName canCreate canRead canEdit canDelete canViewAll canModifyAll
                    }
                }
            `, { profileId });
            setObjectPerms(data.profileObjectPermissions || []);
        } catch (err: any) {
            message.error("Failed to load permissions: " + err.message);
        } finally {
            setPermsLoading(false);
        }
    };

    const loadSystemPermissions = async (profileId: string) => {
        try {
            const data = await gql(`
                query($profileId: String!) {
                    profileSystemPermissions(profileId: $profileId) {
                        id permissionKey isEnabled
                    }
                }
            `, { profileId });
            const perms: Record<string, boolean> = {};
            (data.profileSystemPermissions || []).forEach((p: any) => {
                perms[p.permissionKey] = p.isEnabled;
            });
            setExportPerms(perms);
        } catch { /* ignore */ }
    };

    const handleExportPermChange = async (profileId: string, permissionKey: string, isEnabled: boolean) => {
        try {
            await gql(`
                mutation($profileId: String!, $permissionKey: String!, $isEnabled: Boolean!) {
                    upsertProfileSystemPermission(profileId: $profileId, permissionKey: $permissionKey, isEnabled: $isEnabled) {
                        id permissionKey isEnabled
                    }
                }
            `, { profileId, permissionKey, isEnabled });
            setExportPerms(prev => ({ ...prev, [permissionKey]: isEnabled }));
            message.success(`${permissionKey} ${isEnabled ? 'enabled' : 'disabled'}`);
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleSave = async (values: any) => {
        try {
            if (editingProfile) {
                await gql(`
                    mutation($id: String!, $name: String, $description: String) {
                        updateProfile(id: $id, name: $name, description: $description) { id }
                    }
                `, { id: editingProfile.id, name: values.name, description: values.description });
                message.success("Profile updated");
            } else {
                await gql(`
                    mutation($tenantId: String!, $name: String!, $description: String) {
                        createProfile(tenantId: $tenantId, name: $name, description: $description) { id }
                    }
                `, { tenantId: DEFAULT_TENANT_ID, name: values.name, description: values.description });
                message.success("Profile created");
            }
            setIsModalOpen(false);
            form.resetFields();
            setEditingProfile(null);
            loadProfiles();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $name: String!, $description: String) {
                    createProfile(tenantId: $tenantId, name: $name, description: $description) { id }
                }`, { tenantId: DEFAULT_TENANT_ID, name: r.name, description: r.description || null });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadProfiles(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteProfile(id: $id) }`, { id });
            message.success("Profile deleted");
            loadProfiles();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handlePermissionChange = async (
        profileId: string, objectName: string, field: string, value: boolean
    ) => {
        const existing = objectPerms.find(p => p.objectName === objectName);
        const input = {
            objectName,
            canCreate: existing?.canCreate ?? false,
            canRead: existing?.canRead ?? false,
            canEdit: existing?.canEdit ?? false,
            canDelete: existing?.canDelete ?? false,
            canViewAll: existing?.canViewAll ?? false,
            canModifyAll: existing?.canModifyAll ?? false,
            [field]: value,
        };
        try {
            await gql(`
                mutation($profileId: String!, $objectName: String!, $canCreate: Boolean, $canRead: Boolean, $canEdit: Boolean, $canDelete: Boolean, $canViewAll: Boolean, $canModifyAll: Boolean) {
                    upsertProfileObjectPermission(
                        profileId: $profileId, objectName: $objectName,
                        canCreate: $canCreate, canRead: $canRead, canEdit: $canEdit,
                        canDelete: $canDelete, canViewAll: $canViewAll, canModifyAll: $canModifyAll
                    ) { id }
                }
            `, { profileId, ...input });
            setObjectPerms(prev => {
                const idx = prev.findIndex(p => p.objectName === objectName);
                const updated = { ...existing, id: existing?.id || '', ...input } as ObjectPermission;
                if (idx >= 0) { const n = [...prev]; n[idx] = updated; return n; }
                return [...prev, updated];
            });
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const columns: ColumnsType<Profile> = [
        {
            title: "Profile",
            key: "profile",
            render: (_, record) => (
                <Space>
                    <IdcardOutlined style={{ fontSize: 20, color: record.isSystem ? '#faad14' : '#1677ff' }} />
                    <div>
                        <Text strong>{record.name}</Text>
                        {record.isSystem && <Tag color="gold" style={{ marginLeft: 8 }}>System</Tag>}
                        {record.isCustom && <Tag color="blue" style={{ marginLeft: 8 }}>Custom</Tag>}
                        <br />
                        <Text type="secondary" style={{ fontSize: 12 }}>{record.description}</Text>
                    </div>
                </Space>
            ),
        },
        {
            title: "Actions",
            key: "actions",
            width: 200,
            render: (_, record) => (
                <Space>
                    <Tooltip title="Object Permissions">
                        <Button
                            type="text"
                            icon={<SettingOutlined />}
                            onClick={() => {
                                setSelectedProfile(record);
                                setPermsDrawerOpen(true);
                                loadObjectPermissions(record.id);
                                loadSystemPermissions(record.id);
                            }}
                        />
                    </Tooltip>
                    <Button
                        type="text"
                        icon={<EditOutlined />}
                        onClick={() => {
                            setEditingProfile(record);
                            form.setFieldsValue({ name: record.name, description: record.description });
                            setIsModalOpen(true);
                        }}
                        disabled={record.isSystem}
                    />
                    <Button
                        type="text"
                        danger
                        icon={<DeleteOutlined />}
                        disabled={record.isSystem}
                        onClick={() => Modal.confirm({
                            title: `Delete "${record.name}"?`,
                            onOk: () => handleDelete(record.id),
                        })}
                    />
                </Space>
            ),
        },
    ];

    const permColumns: ColumnsType<{ object: string }> = [
        { title: "Object", dataIndex: "object", key: "object", width: 150, render: (v) => <Text strong style={{ textTransform: 'capitalize' }}>{v}</Text> },
        ...["canCreate", "canRead", "canEdit", "canDelete", "canViewAll", "canModifyAll"].map(field => ({
            title: field.replace("can", "").replace("All", " All"),
            key: field,
            width: 90,
            align: "center" as const,
            render: (_: any, record: { object: string }) => {
                const perm = objectPerms.find(p => p.objectName === record.object);
                const checked = perm ? (perm as any)[field] : false;
                return (
                    <Checkbox
                        checked={checked}
                        onChange={e => handlePermissionChange(selectedProfile!.id, record.object, field, e.target.checked)}
                    />
                );
            },
        })),
    ];

    const permData = SYSTEM_OBJECTS.map(obj => ({ key: obj, object: obj }));

    const formSteps = [
        {
            title: "Profile Info",
            icon: <IdcardOutlined />,
            fields: ["name", "description"],
            content: (
                <>
                    <Form.Item name="name" label="Profile Name" rules={[{ required: true }]}>
                        <Input placeholder="e.g., Sales Manager" />
                    </Form.Item>
                    <Form.Item name="description" label="Description">
                        <Input.TextArea placeholder="Description of this profile's purpose" rows={3} />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Profiles</AuroraText>}
            subTitle={<DecryptedText text="Manage permission profiles — base template for user access" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exports" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'profiles', title: 'Permission Profiles', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }, { header: 'System', key: 'isSystem', format: (v: boolean) => v ? 'Yes' : 'No' }, { header: 'Custom', key: 'isCustom', format: (v: boolean) => v ? 'Yes' : 'No' }], data: profiles })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'profiles', title: 'Permission Profiles', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Description', key: 'description' }, { header: 'System', key: 'isSystem', format: (v: boolean) => v ? 'Yes' : 'No' }, { header: 'Custom', key: 'isCustom', format: (v: boolean) => v ? 'Yes' : 'No' }], data: profiles })} /></Tooltip></RbacGuard>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadProfiles} />,
                <Button
                    key="add"
                    type="primary"
                    icon={<PlusOutlined />}
                    onClick={() => {
                        setEditingProfile(null);
                        form.resetFields();
                        setIsModalOpen(true);
                    }}
                >
                    Create Profile
                </Button>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Profiles', value: profiles.length, icon: <IdcardOutlined />, color: '#3b82f6' },
                    { title: 'System', value: profiles.filter(p => p.isSystem).length, icon: <SafetyOutlined />, color: '#f59e0b' },
                    { title: 'Custom', value: profiles.filter(p => p.isCustom).length, icon: <IdcardOutlined />, color: '#10b981' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <Card>
                <Table
                    columns={columns}
                    dataSource={profiles.map(p => ({ ...p, key: p.id }))}
                    loading={loading}
                    pagination={false}
                    size="middle"
                />
            </Card>

            <SteppedFormModal
                open={isModalOpen}
                onCancel={() => { setIsModalOpen(false); setEditingProfile(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editingProfile ? "Edit Profile" : "Create Profile"}
                entityName="profile"
                steps={formSteps}
                fields={PROFILE_FIELDS}
                width={520}
                onBatchCreate={handleBatchCreate}
                gradient={["#6366f1", "var(--theme-color, #8b5cf6)"]}
                editMode={!!editingProfile}
            />

            {/* Object Permissions Modal — kept as separate specialized workflow */}
            <Modal
                title={<Space><SafetyOutlined /><span>Permissions — {selectedProfile?.name}</span></Space>}
                open={permsDrawerOpen}
                onCancel={() => setPermsDrawerOpen(false)}
                footer={null}
                width={900}
            >
                <Spin spinning={permsLoading}>
                    {/* Export Permissions */}
                    <Card
                        size="small"
                        title={<Space><CloudDownloadOutlined /> Export Permissions</Space>}
                        style={{ marginBottom: 16, borderLeft: '3px solid #3b82f6' }}
                    >
                        <Row gutter={[16, 12]}>
                            {EXPORT_PERMISSION_KEYS.map(ep => (
                                <Col key={ep.key} xs={24} sm={8}>
                                    <Space direction="vertical" size={2} style={{ width: '100%' }}>
                                        <Space>
                                            {ep.icon}
                                            <Text strong>{ep.label}</Text>
                                        </Space>
                                        <Text type="secondary" style={{ fontSize: 11 }}>{ep.description}</Text>
                                        <Switch
                                            checked={exportPerms[ep.key] ?? true}
                                            onChange={(checked) => selectedProfile && handleExportPermChange(selectedProfile.id, ep.key, checked)}
                                            checkedChildren="On"
                                            unCheckedChildren="Off"
                                            style={{ marginTop: 4 }}
                                        />
                                    </Space>
                                </Col>
                            ))}
                        </Row>
                    </Card>

                    <Divider style={{ margin: '8px 0 12px' }} />

                    {/* Object Permissions */}
                    <Table columns={permColumns} dataSource={permData} pagination={false} size="small" bordered scroll={{ y: 400 }} />
                </Spin>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Card, Button, Space, Modal, Form, Input, Select, Tree, Tag,
    message, Typography, Empty, Descriptions, Row, Col, Statistic,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,
    ApartmentOutlined, CrownOutlined, FileTextOutlined,
} from "@ant-design/icons";
import type { DataNode } from "antd/es/tree";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface Role {
    id: string;
    name: string;
    description: string;
    level: number;
    parentRoleId: string | null;
    tenantId: string;
}

const ROLE_FIELDS: FieldDef[] = [
    { name: "name", label: "Role Name", required: true },
    { name: "description", label: "Description" },
    { name: "parentRoleId", label: "Parent Role" },
];

export default function RolesPage() {
    const { themeColor } = usePreferencesStore();
    const [roles, setRoles] = useState<Role[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [form] = Form.useForm();
    const [selectedKeys, setSelectedKeys] = useState<string[]>([]);
    const [selectedRole, setSelectedRole] = useState<Role | null>(null);

    const loadRoles = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    roles(tenantId: $tenantId) {
                        id name description level parentRoleId tenantId
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setRoles(data.roles || []);
        } catch (err: any) {
            message.error("Failed to load roles: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadRoles(); }, [loadRoles]);

    const handleSave = async (values: any) => {
        try {
            if (editingRole) {
                await gql(`
                    mutation($id: String!, $name: String, $description: String, $parentRoleId: String) {
                        updateRole(id: $id, name: $name, description: $description, parentRoleId: $parentRoleId) { id }
                    }
                `, { id: editingRole.id, name: values.name, description: values.description, parentRoleId: values.parentRoleId || null });
                message.success("Role updated");
            } else {
                await gql(`
                    mutation($tenantId: String!, $name: String!, $description: String, $parentRoleId: String) {
                        createRole(tenantId: $tenantId, name: $name, description: $description, parentRoleId: $parentRoleId) { id }
                    }
                `, { tenantId: DEFAULT_TENANT_ID, name: values.name, description: values.description, parentRoleId: values.parentRoleId || null });
                message.success("Role created");
            }
            setIsModalOpen(false);
            form.resetFields();
            setEditingRole(null);
            loadRoles();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleBatchCreate = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $name: String!, $description: String, $parentRoleId: String) {
                    createRole(tenantId: $tenantId, name: $name, description: $description, parentRoleId: $parentRoleId) { id }
                }`, { tenantId: DEFAULT_TENANT_ID, name: r.name, description: r.description || null, parentRoleId: r.parentRoleId || null });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadRoles(); return { success, failed, errors };
    };

    const handleDelete = async (id: string) => {
        const children = roles.filter(r => r.parentRoleId === id);
        if (children.length > 0) {
            message.error("Cannot delete role with child roles. Remove children first.");
            return;
        }
        try {
            await gql(`mutation($id: String!) { deleteRole(id: $id) }`, { id });
            message.success("Role deleted");
            setSelectedRole(null);
            setSelectedKeys([]);
            loadRoles();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const buildTree = (parentId: string | null = null): DataNode[] => {
        return roles
            .filter(r => r.parentRoleId === parentId)
            .sort((a, b) => a.level - b.level || a.name.localeCompare(b.name))
            .map(r => ({
                key: r.id,
                title: (
                    <Space>
                        {r.level === 0 && <CrownOutlined style={{ color: '#faad14' }} />}
                        <Text strong>{r.name}</Text>
                        <Tag color={r.level === 0 ? 'gold' : r.level === 1 ? 'blue' : 'default'}>
                            L{r.level}
                        </Tag>
                    </Space>
                ),
                children: buildTree(r.id),
            }));
    };

    const rootRoles = roles.filter(r => !r.parentRoleId);
    const treeData = rootRoles.length > 0 ? buildTree(null) : [];

    const handleSelect = (keys: React.Key[]) => {
        setSelectedKeys(keys as string[]);
        if (keys.length > 0) {
            const role = roles.find(r => r.id === keys[0]);
            setSelectedRole(role || null);
        } else {
            setSelectedRole(null);
        }
    };

    const formSteps = [
        {
            title: "Role Info",
            icon: <ApartmentOutlined />,
            fields: ["name", "description", "parentRoleId"],
            content: (
                <>
                    <Form.Item name="name" label="Role Name" rules={[{ required: true }]}>
                        <Input placeholder="e.g., VP Sales" />
                    </Form.Item>
                    <Form.Item name="description" label="Description">
                        <Input.TextArea placeholder="Description of this role" rows={2} />
                    </Form.Item>
                    <Form.Item name="parentRoleId" label="Parent Role">
                        <Select
                            allowClear
                            placeholder="Select parent role (leave empty for top-level)"
                            options={roles
                                .filter(r => editingRole ? r.id !== editingRole.id : true)
                                .map(r => ({ value: r.id, label: `${r.name} (L${r.level})` }))}
                        />
                    </Form.Item>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Roles & Hierarchy</AuroraText>}
            subTitle={<DecryptedText text="Define organizational hierarchy for vertical data access" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="reload" icon={<ReloadOutlined />} onClick={loadRoles} />,
                <Button
                    key="add"
                    type="primary"
                    icon={<PlusOutlined />}
                    onClick={() => {
                        setEditingRole(null);
                        form.resetFields();
                        if (selectedRole) form.setFieldsValue({ parentRoleId: selectedRole.id });
                        setIsModalOpen(true);
                    }}
                >
                    Add Role
                </Button>,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'Total Roles', value: roles.length, icon: <ApartmentOutlined />, color: '#3b82f6' },
                    { title: 'Root Roles', value: roles.filter(r => !r.parentRoleId).length, icon: <CrownOutlined />, color: '#f59e0b' },
                    { title: 'Max Depth', value: roles.length > 0 ? Math.max(...roles.map(r => r.level)) + 1 : 0, icon: <ApartmentOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <div style={{ display: 'flex', gap: 16 }}>
                <Card
                    title={<Space><ApartmentOutlined /> Role Hierarchy</Space>}
                    style={{ flex: 1, minWidth: 350 }}
                    loading={loading}
                >
                    {treeData.length > 0 ? (
                        <Tree
                            treeData={treeData}
                            selectedKeys={selectedKeys}
                            onSelect={handleSelect}
                            defaultExpandAll
                            showLine={{ showLeafIcon: false }}
                            blockNode
                            style={{ fontSize: 14 }}
                        />
                    ) : (
                        <Empty description="No roles defined yet" />
                    )}
                </Card>

                <Card
                    title="Role Details"
                    style={{ flex: 1, minWidth: 350 }}
                    extra={
                        selectedRole && (
                            <Space>
                                <Button
                                    size="small"
                                    icon={<EditOutlined />}
                                    onClick={() => {
                                        setEditingRole(selectedRole);
                                        form.setFieldsValue({
                                            name: selectedRole.name,
                                            description: selectedRole.description,
                                            parentRoleId: selectedRole.parentRoleId,
                                        });
                                        setIsModalOpen(true);
                                    }}
                                >
                                    Edit
                                </Button>
                                <Button
                                    size="small"
                                    danger
                                    icon={<DeleteOutlined />}
                                    onClick={() => Modal.confirm({
                                        title: `Delete "${selectedRole.name}"?`,
                                        content: "This will also remove hierarchy paths.",
                                        onOk: () => handleDelete(selectedRole.id),
                                    })}
                                >
                                    Delete
                                </Button>
                            </Space>
                        )
                    }
                >
                    {selectedRole ? (
                        <Descriptions column={1} bordered size="small">
                            <Descriptions.Item label="Name">{selectedRole.name}</Descriptions.Item>
                            <Descriptions.Item label="Description">{selectedRole.description || '—'}</Descriptions.Item>
                            <Descriptions.Item label="Level">
                                <Tag color={selectedRole.level === 0 ? 'gold' : 'blue'}>Level {selectedRole.level}</Tag>
                            </Descriptions.Item>
                            <Descriptions.Item label="Parent Role">
                                {selectedRole.parentRoleId
                                    ? roles.find(r => r.id === selectedRole.parentRoleId)?.name || '—'
                                    : <Tag>Root (No Parent)</Tag>}
                            </Descriptions.Item>
                            <Descriptions.Item label="Direct Reports">
                                {roles.filter(r => r.parentRoleId === selectedRole.id).length} roles
                            </Descriptions.Item>
                        </Descriptions>
                    ) : (
                        <Empty description="Select a role from the hierarchy tree" />
                    )}
                </Card>
            </div>

            <SteppedFormModal
                open={isModalOpen}
                onCancel={() => { setIsModalOpen(false); setEditingRole(null); form.resetFields(); }}
                onSubmit={handleSave}
                form={form}
                title={editingRole ? "Edit Role" : "Create Role"}
                entityName="role"
                steps={formSteps}
                fields={ROLE_FIELDS}
                width={550}
                onBatchCreate={handleBatchCreate}
                gradient={["#f59e0b", "#d97706"]}
                editMode={!!editingRole}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import {
    Card, Tabs, Table, Button, Space, Modal, Form, Input, Select, Tag, Tooltip,
    message, Typography, Spin, Row, Col, Statistic,
} from "antd";
import { motion } from "framer-motion";
import {
    PlusOutlined, DeleteOutlined, ReloadOutlined,
    LockOutlined, ShareAltOutlined, EyeOutlined,
    FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import SteppedFormModal from "@/components/common/SteppedFormModal";
import type { FieldDef } from "@/components/common/DataImportExport";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

interface OrgWideDefault {
    id: string;
    objectName: string;
    internalAccess: string;
    externalAccess: string;
}

interface SharingRule {
    id: string;
    name: string;
    objectName: string;
    ruleType: string;
    accessLevel: string;
    isActive: boolean;
}

interface FieldPerm {
    id: string;
    objectName: string;
    fieldName: string;
    isVisible: boolean;
    isEditable: boolean;
}

const SYSTEM_OBJECTS = [
    "pages", "media", "blocks", "users", "settings", "datasets",
    "individuals", "accounts", "contacts", "leads", "opportunities",
    "cases", "activities", "projects", "tasks", "teams",
];

const ACCESS_OPTIONS = [
    { value: "private", label: "Private" },
    { value: "public_read", label: "Public Read Only" },
    { value: "public_rw", label: "Public Read/Write" },
];

const RULE_FIELDS: FieldDef[] = [
    { name: "name", label: "Rule Name", required: true },
    { name: "objectName", label: "Object", required: true },
    { name: "ruleType", label: "Rule Type", required: true },
    { name: "accessLevel", label: "Access Level" },
];

export default function SharingPage() {
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [owds, setOwds] = useState<OrgWideDefault[]>([]);
    const [owdLoading, setOwdLoading] = useState(true);

    const [rules, setRules] = useState<SharingRule[]>([]);
    const [rulesLoading, setRulesLoading] = useState(true);
    const [ruleModalOpen, setRuleModalOpen] = useState(false);
    const [ruleForm] = Form.useForm();

    const [flsProfile, setFlsProfile] = useState<string>("");
    const [flsObject, setFlsObject] = useState<string>("");
    const [fieldPerms, setFieldPerms] = useState<FieldPerm[]>([]);
    const [flsLoading, setFlsLoading] = useState(false);
    const [profiles, setProfiles] = useState<{ id: string; name: string }[]>([]);

    const loadOwds = useCallback(async () => {
        setOwdLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    orgWideDefaults(tenantId: $tenantId) {
                        id objectName internalAccess externalAccess
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setOwds(data.orgWideDefaults || []);
        } catch (err: any) {
            message.error(err.message);
        } finally {
            setOwdLoading(false);
        }
    }, []);

    const loadRules = useCallback(async () => {
        setRulesLoading(true);
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    sharingRules(tenantId: $tenantId) {
                        id name objectName ruleType accessLevel isActive
                    }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setRules(data.sharingRules || []);
        } catch (err: any) {
            message.error(err.message);
        } finally {
            setRulesLoading(false);
        }
    }, []);

    const loadProfiles = useCallback(async () => {
        try {
            const data = await gql(`
                query($tenantId: String!) {
                    profiles(tenantId: $tenantId) { id name }
                }
            `, { tenantId: DEFAULT_TENANT_ID });
            setProfiles(data.profiles || []);
        } catch { /* ignore */ }
    }, []);

    useEffect(() => { loadOwds(); loadRules(); loadProfiles(); }, [loadOwds, loadRules, loadProfiles]);

    const handleOwdChange = async (objectName: string, field: string, value: string) => {
        const existing = owds.find(o => o.objectName === objectName);
        try {
            await gql(`
                mutation($tenantId: String!, $objectName: String!, $internalAccess: String!, $externalAccess: String) {
                    upsertOrgWideDefault(tenantId: $tenantId, objectName: $objectName, internalAccess: $internalAccess, externalAccess: $externalAccess) { id }
                }
            `, {
                tenantId: DEFAULT_TENANT_ID,
                objectName,
                internalAccess: field === 'internalAccess' ? value : (existing?.internalAccess || 'private'),
                externalAccess: field === 'externalAccess' ? value : (existing?.externalAccess || 'private'),
            });
            loadOwds();
            message.success(`Updated ${objectName} access`);
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleCreateRule = async (values: any) => {
        try {
            await gql(`
                mutation($tenantId: String!, $name: String!, $objectName: String!, $ruleType: String!, $accessLevel: String) {
                    createSharingRule(tenantId: $tenantId, name: $name, objectName: $objectName, ruleType: $ruleType, accessLevel: $accessLevel) { id }
                }
            `, { tenantId: DEFAULT_TENANT_ID, ...values });
            message.success("Sharing rule created");
            setRuleModalOpen(false);
            ruleForm.resetFields();
            loadRules();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const handleBatchCreateRules = async (records: any[]) => {
        let success = 0, failed = 0; const errors: string[] = [];
        for (const r of records) {
            try {
                await gql(`mutation($tenantId: String!, $name: String!, $objectName: String!, $ruleType: String!, $accessLevel: String) {
                    createSharingRule(tenantId: $tenantId, name: $name, objectName: $objectName, ruleType: $ruleType, accessLevel: $accessLevel) { id }
                }`, { tenantId: DEFAULT_TENANT_ID, name: r.name, objectName: r.objectName, ruleType: r.ruleType, accessLevel: r.accessLevel || 'read' });
                success++;
            } catch (e: any) { failed++; errors.push(`${r.name}: ${e.message}`); }
        }
        loadRules(); return { success, failed, errors };
    };

    const handleDeleteRule = async (id: string) => {
        try {
            await gql(`mutation($id: String!) { deleteSharingRule(id: $id) }`, { id });
            message.success("Rule deleted");
            loadRules();
        } catch (err: any) {
            message.error(err.message);
        }
    };

    const loadFLS = async (profileId: string, objectName: string) => {
        if (!profileId || !objectName) return;
        setFlsLoading(true);
        try {
            const data = await gql(`
                query($profileId: String!, $objectName: String) {
                    fieldPermissions(profileId: $profileId, objectName: $objectName) {
                        id objectName fieldName isVisible isEditable
                    }
                }
            `, { profileId, objectName });
            setFieldPerms(data.fieldPermissions || []);
        } catch (err: any) {
            message.error(err.message);
        } finally {
            setFlsLoading(false);
        }
    };

    const owdColumns: ColumnsType<{ object: string }> = [
        {
            title: "Object", dataIndex: "object", key: "object", width: 180,
            render: (v) => <Text strong style={{ textTransform: 'capitalize' }}>{v}</Text>
        },
        {
            title: "Internal Access", key: "internal",
            render: (_, record) => {
                const owd = owds.find(o => o.objectName === record.object);
                return (
                    <Select
                        value={owd?.internalAccess || "private"}
                        options={ACCESS_OPTIONS}
                        style={{ width: 200 }}
                        onChange={v => handleOwdChange(record.object, 'internalAccess', v)}
                    />
                );
            }
        },
        {
            title: "External Access", key: "external",
            render: (_, record) => {
                const owd = owds.find(o => o.objectName === record.object);
                return (
                    <Select
                        value={owd?.externalAccess || "private"}
                        options={ACCESS_OPTIONS}
                        style={{ width: 200 }}
                        onChange={v => handleOwdChange(record.object, 'externalAccess', v)}
                    />
                );
            }
        },
    ];

    const rulesColumns: ColumnsType<SharingRule> = [
        { title: "Name", dataIndex: "name", key: "name", render: (v) => <Text strong>{v}</Text> },
        { title: "Object", dataIndex: "objectName", key: "objectName", render: (v) => <Tag>{v}</Tag> },
        { title: "Type", dataIndex: "ruleType", key: "ruleType", render: (v) => <Tag color="blue">{v}</Tag> },
        {
            title: "Access", dataIndex: "accessLevel", key: "accessLevel",
            render: (v) => <Tag color={v === 'read_write' ? 'green' : 'default'}>{v}</Tag>
        },
        {
            title: "Active", dataIndex: "isActive", key: "isActive",
            render: (v) => v ? <Tag color="success">Active</Tag> : <Tag>Inactive</Tag>
        },
        {
            title: "Actions", key: "actions", width: 80,
            render: (_, record) => (
                <Button type="text" danger icon={<DeleteOutlined />}
                    onClick={() => Modal.confirm({ title: `Delete "${record.name}"?`, onOk: () => handleDeleteRule(record.id) })}
                />
            ),
        },
    ];

    const flsColumns: ColumnsType<FieldPerm> = [
        { title: "Field", dataIndex: "fieldName", key: "fieldName", render: (v) => <Text code>{v}</Text> },
        {
            title: "Visible", dataIndex: "isVisible", key: "isVisible", width: 100, align: "center",
            render: (v) => v ? <Tag color="green">Yes</Tag> : <Tag color="red">No</Tag>
        },
        {
            title: "Editable", dataIndex: "isEditable", key: "isEditable", width: 100, align: "center",
            render: (v) => v ? <Tag color="green">Yes</Tag> : <Tag color="red">No</Tag>
        },
    ];

    const ruleFormSteps = [
        {
            title: "Rule Setup",
            icon: <ShareAltOutlined />,
            fields: ["name", "objectName", "ruleType", "accessLevel"],
            content: (
                <>
                    <Form.Item name="name" label="Rule Name" rules={[{ required: true }]}>
                        <Input placeholder="e.g., Share Leads with Marketing" />
                    </Form.Item>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item name="objectName" label="Object" rules={[{ required: true }]}>
                                <Select options={SYSTEM_OBJECTS.map(o => ({ value: o, label: o.charAt(0).toUpperCase() + o.slice(1) }))} />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item name="ruleType" label="Rule Type" rules={[{ required: true }]}>
                                <Select options={[
                                    { value: "owner_based", label: "Owner-Based" },
                                    { value: "criteria_based", label: "Criteria-Based" },
                                ]} />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item name="accessLevel" label="Access Level" initialValue="read">
                        <Select options={[
                            { value: "read", label: "Read Only" },
                            { value: "read_write", label: "Read/Write" },
                        ]} />
                    </Form.Item>
                </>
            ),
        },
    ];

    const tabItems = [
        {
            key: "owd",
            label: <Space><LockOutlined /> Org-Wide Defaults</Space>,
            children: (
                <Spin spinning={owdLoading}>
                    <Table scroll={{ x: 900 }} columns={owdColumns} dataSource={SYSTEM_OBJECTS.map(obj => ({ key: obj, object: obj }))} pagination={false} size="small" bordered />
                </Spin>
            ),
        },
        {
            key: "sharing",
            label: <Space><ShareAltOutlined /> Sharing Rules</Space>,
            children: (
                <>
                    <div style={{ marginBottom: 16 }}>
                        <Button type="primary" icon={<PlusOutlined />} onClick={() => { ruleForm.resetFields(); setRuleModalOpen(true); }}>
                            Create Sharing Rule
                        </Button>
                    </div>
                    <Table scroll={{ x: 900 }} columns={rulesColumns} dataSource={rules.map(r => ({ ...r, key: r.id }))} loading={rulesLoading}
                        pagination={false} size="middle" locale={{ emptyText: "No sharing rules yet" }} />
                </>
            ),
        },
        {
            key: "fls",
            label: <Space><EyeOutlined /> Field-Level Security</Space>,
            children: (
                <>
                    <Space style={{ marginBottom: 16 }}>
                        <Select placeholder="Select Profile" style={{ width: 200 }}
                            options={profiles.map(p => ({ value: p.id, label: p.name }))}
                            onChange={v => { setFlsProfile(v); if (flsObject) loadFLS(v, flsObject); }}
                        />
                        <Select placeholder="Select Object" style={{ width: 200 }}
                            options={SYSTEM_OBJECTS.map(o => ({ value: o, label: o.charAt(0).toUpperCase() + o.slice(1) }))}
                            onChange={v => { setFlsObject(v); if (flsProfile) loadFLS(flsProfile, v); }}
                        />
                    </Space>
                    <Spin spinning={flsLoading}>
                        <Table scroll={{ x: 900 }} columns={flsColumns} dataSource={fieldPerms.map(f => ({ ...f, key: f.id }))} pagination={false}
                            size="small" bordered locale={{ emptyText: "Select a profile and object to view field-level security" }} />
                    </Spin>
                </>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Sharing & Security</AuroraText>}
            subTitle={<DecryptedText text="Configure organization-wide defaults, sharing rules, and field-level security" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exports" requiredRole="manager"><Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'sharing_rules', title: 'Sharing Rules', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Object', key: 'objectName' }, { header: 'Type', key: 'ruleType' }, { header: 'Access Level', key: 'accessLevel' }, { header: 'Active', key: 'isActive', format: (v: boolean) => v ? 'Yes' : 'No' }], data: rules })} /></Tooltip> <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'sharing_rules', title: 'Sharing Rules', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Object', key: 'objectName' }, { header: 'Type', key: 'ruleType' }, { header: 'Access Level', key: 'accessLevel' }, { header: 'Active', key: 'isActive', format: (v: boolean) => v ? 'Yes' : 'No' }], data: rules })} /></Tooltip></RbacGuard>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={() => { loadOwds(); loadRules(); }} />,
            ]}
        >
            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                {[
                    { title: 'OWD Settings', value: owds.length, icon: <LockOutlined />, color: '#3b82f6' },
                    { title: 'Sharing Rules', value: rules.length, icon: <ShareAltOutlined />, color: '#10b981' },
                    { title: 'Active Rules', value: rules.filter(r => r.isActive).length, icon: <ShareAltOutlined />, color: '#8b5cf6' },
                ].map((s, i) => (
                    <Col key={i} xs={12} md={8}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card size="small" style={{ ...glass, borderTop: `3px solid ${s.color}` }}>
                                <Statistic title={s.title} value={s.value} prefix={s.icon} valueStyle={{ color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>
            <Card><Tabs items={tabItems} /></Card>

            <SteppedFormModal
                open={ruleModalOpen}
                onCancel={() => { setRuleModalOpen(false); ruleForm.resetFields(); }}
                onSubmit={handleCreateRule}
                form={ruleForm}
                title="Create Sharing Rule"
                entityName="sharing-rule"
                steps={ruleFormSteps}
                fields={RULE_FIELDS}
                width={580}
                onBatchCreate={handleBatchCreateRules}
                gradient={["#ec4899", "var(--theme-accent, #a855f7)"]}
            />
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion, AnimatePresence } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { Badge, Button, Card, Col, DatePicker, Empty, Input, InputNumber, message, Modal, Progress, Row, Segmented, Select, Space, Spin, Statistic, Table, Tag, Tooltip, Typography } from "antd";
import {
    UnorderedListOutlined, SearchOutlined, FilterOutlined,
    ProjectOutlined, ClockCircleOutlined, CheckCircleOutlined,
    ExclamationCircleOutlined, UserOutlined, FireOutlined,
    ThunderboltOutlined, CalendarOutlined, DashboardOutlined,
    ArrowUpOutlined, MinusOutlined, ArrowDownOutlined, FileExcelOutlined, FilePdfOutlined,
    ReloadOutlined, AppstoreOutlined, EditOutlined, CloseOutlined, SaveOutlined, PlusOutlined, EyeOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import KanbanBoard from "../components/KanbanBoard";

const { Text } = Typography;

const GET_ALL_TASKS = `
  query GetAllTasks($tenantId: String!) {
    pmTasks(tenantId: $tenantId) {
      id
      projectId
      sprintId
      title
      description
      status
      priority
      type
      assigneeId
      assignee { id firstName lastName }
      estimatedHours
      loggedHours
      startDate
      dueDate
      tags
      createdAt
    }
  }
`;

const GET_PROJECTS = `
  query GetProjects($tenantId: String!) {
    pmProjects(tenantId: $tenantId) { id name projectNumber status }
  }
`;

const UPDATE_TASK = `
  mutation UpdateTask($id: ID!, $input: UpdatePmTaskInput!) {
    updatePmTask(id: $id, input: $input) { id status priority type title }
  }
`;

const GET_MEMBERS = `
  query GetMembers($tenantId: String!) {
    pmMembers(tenantId: $tenantId) { id userId user { id firstName lastName email } role }
  }
`;

const CREATE_TASK = `
  mutation CreateTask($tenantId: String!, $input: CreatePmTaskInput!) {
    createPmTask(tenantId: $tenantId, input: $input) { id title status }
  }
`;

const STATUS_CONFIG: Record<string, { color: string; icon: React.ReactNode; label: string }> = {
    todo: { color: '#64748b', icon: <UnorderedListOutlined />, label: 'To Do' },
    in_progress: { color: '#3b82f6', icon: <ClockCircleOutlined />, label: 'In Progress' },
    in_review: { color: 'var(--theme-color, #8b5cf6)', icon: <ThunderboltOutlined />, label: 'In Review' },
    done: { color: '#10b981', icon: <CheckCircleOutlined />, label: 'Done' },
    blocked: { color: '#ef4444', icon: <ExclamationCircleOutlined />, label: 'Blocked' },
};

const PRIORITY_CONFIG: Record<string, { color: string; icon: React.ReactNode }> = {
    critical: { color: '#ef4444', icon: <FireOutlined /> },
    high: { color: '#f59e0b', icon: <ArrowUpOutlined /> },
    medium: { color: '#3b82f6', icon: <MinusOutlined /> },
    low: { color: '#6b7280', icon: <ArrowDownOutlined /> },
};

export default function BacklogPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [tasks, setTasks] = useState<any[]>([]);
    const [projects, setProjects] = useState<any[]>([]);
    const [members, setMembers] = useState<any[]>([]);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<string | null>(null);
    const [priorityFilter, setPriorityFilter] = useState<string | null>(null);
    const [projectFilter, setProjectFilter] = useState<string | null>(null);
    const [typeFilter, setTypeFilter] = useState<string | null>(null);
    const [assigneeFilter, setAssigneeFilter] = useState<string | null>(null);
    const [sprintFilter, setSprintFilter] = useState<string | null>(null);
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    // ── New interactive state ──
    const [messageApi, contextHolder] = message.useMessage();
    const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);
    const [viewMode, setViewMode] = useState<string>('table');

    // ── Quick-create state ──
    const [quickCreateOpen, setQuickCreateOpen] = useState(false);
    const [quickTitle, setQuickTitle] = useState('');
    const [quickProject, setQuickProject] = useState<string | null>(null);
    const [quickType, setQuickType] = useState('task');
    const [quickPriority, setQuickPriority] = useState('medium');
    const [quickCreating, setQuickCreating] = useState(false);

    // ── Saved Views ──
    const [savedViews, setSavedViews] = useState<{ name: string; filters: any }[]>([]);
    const [saveViewModalOpen, setSaveViewModalOpen] = useState(false);
    const [newViewName, setNewViewName] = useState('');

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [taskData, projData, memberData] = await Promise.all([
                gql(GET_ALL_TASKS, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_MEMBERS, { tenantId: DEFAULT_TENANT_ID }).catch(() => ({ pmMembers: [] })),
            ]);
            setTasks(taskData.pmTasks || []);
            setProjects(projData.pmProjects || []);
            setMembers(memberData.pmMembers || []);
        } catch (err: any) {
            messageApi.error("Failed to load backlog data: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Load saved views from localStorage ──
    useEffect(() => {
        const saved = localStorage.getItem('nusantarasoft-pm-saved-views');
        if (saved) setSavedViews(JSON.parse(saved));
    }, []);

    const handleSaveView = () => {
        if (!newViewName.trim()) return;
        const view = {
            name: newViewName.trim(),
            filters: { search, statusFilter, priorityFilter, projectFilter, typeFilter, assigneeFilter, sprintFilter, viewMode },
        };
        const updated = [...savedViews.filter(v => v.name !== view.name), view];
        setSavedViews(updated);
        localStorage.setItem('nusantarasoft-pm-saved-views', JSON.stringify(updated));
        setSaveViewModalOpen(false);
        setNewViewName('');
        messageApi.success(`View "${view.name}" saved`);
    };

    const handleLoadView = (view: any) => {
        setSearch(view.filters.search || '');
        setStatusFilter(view.filters.statusFilter || null);
        setPriorityFilter(view.filters.priorityFilter || null);
        setProjectFilter(view.filters.projectFilter || null);
        setTypeFilter(view.filters.typeFilter || null);
        setAssigneeFilter(view.filters.assigneeFilter || null);
        setSprintFilter(view.filters.sprintFilter || null);
        if (view.filters.viewMode) setViewMode(view.filters.viewMode);
        messageApi.info(`Loaded view "${view.name}"`);
    };

    const handleDeleteView = (name: string) => {
        const updated = savedViews.filter(v => v.name !== name);
        setSavedViews(updated);
        localStorage.setItem('nusantarasoft-pm-saved-views', JSON.stringify(updated));
        messageApi.success(`View deleted`);
    };

    // ── Project map ──
    const projectMap = useMemo(() => {
        const m = new Map<string, any>();
        projects.forEach(p => m.set(p.id, p));
        return m;
    }, [projects]);

    // ── Filters ──
    const filtered = useMemo(() => {
        let result = [...tasks];
        if (search) {
            const q = search.toLowerCase();
            result = result.filter(t =>
                (t.title || '').toLowerCase().includes(q) ||
                (t.description || '').toLowerCase().includes(q) ||
                (t.tags || []).some((tag: string) => tag.toLowerCase().includes(q))
            );
        }
        if (statusFilter) result = result.filter(t => t.status === statusFilter);
        if (priorityFilter) result = result.filter(t => t.priority === priorityFilter);
        if (projectFilter) result = result.filter(t => t.projectId === projectFilter);
        if (typeFilter) result = result.filter(t => t.type === typeFilter);
        if (assigneeFilter) {
            if (assigneeFilter === '__unassigned__') result = result.filter(t => !t.assigneeId);
            else result = result.filter(t => t.assigneeId === assigneeFilter || t.assignee?.id === assigneeFilter || t.assignee?.userId === assigneeFilter);
        }
        if (sprintFilter) {
            if (sprintFilter === 'assigned') result = result.filter(t => t.sprintId);
            else result = result.filter(t => !t.sprintId);
        }
        return result;
    }, [tasks, search, statusFilter, priorityFilter, projectFilter, typeFilter, assigneeFilter, sprintFilter]);

    // ── Computed stats ──
    const totalTasks = tasks.length;
    const todoCount = tasks.filter(t => t.status === 'todo').length;
    const inProgressCount = tasks.filter(t => t.status === 'in_progress').length;
    const inReviewCount = tasks.filter(t => t.status === 'in_review').length;
    const doneCount = tasks.filter(t => t.status === 'done').length;
    const blockedCount = tasks.filter(t => t.status === 'blocked').length;
    const overdueCount = tasks.filter(t => t.dueDate && dayjs(t.dueDate).isBefore(dayjs()) && t.status !== 'done').length;
    const unassignedCount = tasks.filter(t => !t.assigneeId).length;
    const totalEstimated = tasks.reduce((sum, t) => sum + (t.estimatedHours || 0), 0);
    const totalLogged = tasks.reduce((sum, t) => sum + (t.loggedHours || 0), 0);

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(12px)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    // ── Inline update handler ──
    const handleInlineUpdate = async (id: string, field: string, value: string) => {
        try {
            const parsedValue = field === 'estimatedHours' ? parseFloat(value) || 0 : value;
            await gql(UPDATE_TASK, { id, input: { [field]: parsedValue } });
            messageApi.success(`Task ${field === 'estimatedHours' ? 'hours' : field === 'assigneeId' ? 'assignee' : field} updated`);
            loadData();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error(`Failed to update ${field}`); }
    };

    // ── Quick-create handler ──
    const handleQuickCreate = async () => {
        if (!quickTitle.trim() || !quickProject) {
            messageApi.warning('Task title and project are required');
            return;
        }
        setQuickCreating(true);
        try {
            await gql(CREATE_TASK, {
                tenantId: DEFAULT_TENANT_ID,
                input: {
                    projectId: quickProject,
                    title: quickTitle.trim(),
                    type: quickType,
                    priority: quickPriority,
                    status: 'todo',
                },
            });
            messageApi.success(`Task "${quickTitle.trim()}" created`);
            setQuickTitle('');
            loadData();
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error('Failed to create task');
        } finally {
            setQuickCreating(false);
        }
    };

    // ── Bulk action handler ──
    const handleBulkUpdate = async (field: string, value: string) => {
        if (selectedRowKeys.length === 0) return;
        try {
            await Promise.all(selectedRowKeys.map(id => gql(UPDATE_TASK, { id, input: { [field]: value } })));
            messageApi.success(`Updated ${selectedRowKeys.length} tasks`);
            setSelectedRowKeys([]);
            loadData();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error('Bulk update failed'); }
    };

    // ── Kanban task update handler ──
    const handleKanbanUpdate = async (taskId: string, updates: Record<string, any>) => {
        try {
            await gql(UPDATE_TASK, { id: taskId, input: updates });
            messageApi.success('Task updated');
            loadData();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error('Failed to update task'); }
    };

    const columns = [
        {
            title: 'Task',
            dataIndex: 'title',
            key: 'title',
            render: (_: any, record: any) => {
                const proj = projectMap.get(record.projectId);
                return (
                    <div>
                        <Tooltip title={record.description ? <div style={{ maxWidth: 300, fontSize: 11 }}>{record.description.slice(0, 200)}{record.description.length > 200 ? '...' : ''}</div> : 'No description'} placement="topLeft">
                            <a onClick={(e) => { e.stopPropagation(); router.push(`/admin/pm/tasks/${record.id}`); }} style={{ fontWeight: 600, fontSize: 14 }}>
                                {record.title}
                            </a>
                        </Tooltip>
                        <div style={{ fontSize: 11, color: isDark ? '#94a3b8' : '#888', marginTop: 2 }}>
                            {proj && (
                                <Tag
                                    icon={<ProjectOutlined />}
                                    color="geekblue"
                                    style={{ fontSize: 10, cursor: 'pointer' }}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        router.push(`/admin/pm/dashboard?projectId=${record.projectId}`);
                                    }}
                                >
                                    {proj.name}
                                </Tag>
                            )}
                        </div>
                    </div>
                );
            },
        },
        {
            title: 'Status',
            dataIndex: 'status',
            key: 'status',
            width: 150,
            render: (status: string, record: any) => (
                <Select size="small" value={status} style={{ width: 130 }} variant="borderless"
                    onClick={(e) => e.stopPropagation()}
                    onChange={(val) => handleInlineUpdate(record.id, 'status', val)}
                    options={Object.entries(STATUS_CONFIG).map(([k, v]) => ({
                        label: <Tag color={v.color} icon={v.icon} style={{ margin: 0 }}>{v.label}</Tag>, value: k,
                    }))}
                />
            ),
            filters: Object.entries(STATUS_CONFIG).map(([k, v]) => ({ text: v.label, value: k })),
            onFilter: (value: any, record: any) => record.status === value,
        },
        {
            title: 'Priority',
            dataIndex: 'priority',
            key: 'priority',
            width: 120,
            render: (priority: string, record: any) => (
                <Select size="small" value={priority} style={{ width: 110 }} variant="borderless"
                    onClick={(e) => e.stopPropagation()}
                    onChange={(val) => handleInlineUpdate(record.id, 'priority', val)}
                    options={Object.entries(PRIORITY_CONFIG).map(([k, v]) => ({
                        label: <Tag color={v.color} icon={v.icon} style={{ margin: 0, textTransform: 'capitalize' as const }}>{k}</Tag>, value: k,
                    }))}
                />
            ),
            sorter: (a: any, b: any) => {
                const order: Record<string,number> = { critical: 0, high: 1, medium: 2, low: 3 };
                return (order[a.priority] ?? 4) - (order[b.priority] ?? 4);
            },
        },
        {
            title: 'Type',
            dataIndex: 'type',
            key: 'type',
            width: 100,
            render: (type: string, record: any) => (
                <Select size="small" value={type} style={{ width: 90 }} variant="borderless"
                    onClick={(e) => e.stopPropagation()}
                    onChange={(val) => handleInlineUpdate(record.id, 'type', val)}
                    options={['task', 'bug', 'story', 'epic'].map(t => ({
                        label: <Tag color={t === 'bug' ? 'red' : t === 'story' ? 'green' : t === 'epic' ? 'purple' : 'default'} style={{ margin: 0, textTransform: 'capitalize' as const }}>{t}</Tag>,
                        value: t,
                    }))}
                />
            ),
        },
        {
            title: 'Assignee',
            key: 'assignee',
            width: 150,
            render: (_: any, record: any) => (
                <Select
                    size="small"
                    value={record.assigneeId || undefined}
                    placeholder="Unassigned"
                    style={{ width: 140 }}
                    variant="borderless"
                    allowClear
                    showSearch
                    optionFilterProp="label"
                    onClick={(e) => e.stopPropagation()}
                    onChange={(val) => handleInlineUpdate(record.id, 'assigneeId', val || '')}
                    options={members.map(m => ({
                        value: m.userId || m.user?.id || m.id,
                        label: m.user ? `${m.user.firstName} ${m.user.lastName}` : m.id,
                    }))}
                />
            ),
        },
        {
            title: 'Hours',
            key: 'hours',
            width: 110,
            render: (_: any, record: any) => {
                const est = record.estimatedHours || 0;
                const log = record.loggedHours || 0;
                return (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }} onClick={(e) => e.stopPropagation()}>
                        <InputNumber
                            size="small"
                            min={0}
                            max={999}
                            step={0.5}
                            value={est}
                            style={{ width: 55, fontSize: 11 }}
                            variant="borderless"
                            onChange={(val) => {
                                if (val !== null && val !== est) handleInlineUpdate(record.id, 'estimatedHours', String(val));
                            }}
                        />
                        {est > 0 && (
                            <Tooltip title={`${log}h logged / ${est}h estimated`}>
                                <Progress
                                    percent={est > 0 ? Math.min(100, Math.round((log / est) * 100)) : 0}
                                    size="small"
                                    strokeColor={log > est ? '#ef4444' : log > est * 0.8 ? '#f59e0b' : '#10b981'}
                                    trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                                    format={() => `${log}h`}
                                    style={{ width: 40 }}
                                />
                            </Tooltip>
                        )}
                    </div>
                );
            },
        },
        {
            title: 'Due Date',
            dataIndex: 'dueDate',
            key: 'dueDate',
            width: 140,
            sorter: (a: any, b: any) => {
                if (!a.dueDate) return 1;
                if (!b.dueDate) return -1;
                return dayjs(a.dueDate).unix() - dayjs(b.dueDate).unix();
            },
            render: (date: string, record: any) => {
                const isOverdue = date && dayjs(date).isBefore(dayjs()) && record.status !== 'done';
                return (
                    <div onClick={(e) => e.stopPropagation()}>
                        <DatePicker
                            size="small"
                            value={date ? dayjs(date) : null}
                            variant="borderless"
                            format="MMM D"
                            style={{ width: 100 }}
                            onChange={(d) => handleInlineUpdate(record.id, 'dueDate', d ? d.format('YYYY-MM-DD') : '')}
                            status={isOverdue ? 'error' : undefined}
                            suffixIcon={isOverdue ? <Tag color="red" style={{ fontSize: 8, padding: '0 3px', margin: 0 }}>LATE</Tag> : <CalendarOutlined style={{ fontSize: 11 }} />}
                        />
                    </div>
                );
            },
        },
    ];



    // ── Row selection config ──
    const rowSelection = {
        selectedRowKeys,
        onChange: (keys: React.Key[]) => setSelectedRowKeys(keys),
    };

    // ── Shared CMSLayout props ──
    const layoutExtra = [<Segmented key="view" aria-label="Switch view mode" options={[{ value: 'table', icon: <UnorderedListOutlined /> }, { value: 'board', icon: <AppstoreOutlined /> }]} value={viewMode} onChange={(v) => setViewMode(v as string)} />, <RbacGuard key="exports" requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button aria-label="Export to Excel" icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'pm_backlog', title: 'PM Backlog Tasks', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'priority' }, { header: 'Project', key: 'projectName' }], data: tasks })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button aria-label="Export to PDF" icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'pm_backlog', title: 'PM Backlog Tasks', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Title', key: 'title' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'priority' }, { header: 'Project', key: 'projectName' }], data: tasks })} /></Tooltip></RbacGuard>];

    if (loading) {
        return (
            <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Backlog</AuroraText>}
            subTitle={<DecryptedText text="All tasks across all projects" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={layoutExtra}>
                {contextHolder}
                <div style={{ textAlign: 'center', padding: 120 }}>
                    <Spin size="large" />
                </div>
            </CMSLayout>
        );
    }

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Backlog</AuroraText>}
            subTitle={<DecryptedText text="All tasks across all projects" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={layoutExtra}>
            {contextHolder}

            {/* ── Stats Row ── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                {[
                    { title: 'Total Tasks', value: totalTasks, icon: <ProjectOutlined style={{ color: themeColor }} />, color: themeColor },
                    { title: 'To Do', value: todoCount, icon: <ClockCircleOutlined style={{ color: '#6366f1' }} />, color: '#6366f1' },
                    { title: 'In Progress', value: inProgressCount, icon: <ThunderboltOutlined style={{ color: '#3b82f6' }} />, color: '#3b82f6' },
                    { title: 'In Review', value: inReviewCount, icon: <EyeOutlined style={{ color: '#8b5cf6' }} />, color: '#8b5cf6' },
                    { title: 'Done', value: doneCount, icon: <CheckCircleOutlined style={{ color: '#10b981' }} />, color: '#10b981' },
                    { title: 'Overdue', value: overdueCount, icon: <ExclamationCircleOutlined style={{ color: '#ef4444' }} />, color: '#ef4444' },
                ].map((s, i) => (
                    <Col key={i} xs={24} sm={12} lg={4}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                            <Card style={{ ...glassCard, borderTop: `3px solid ${s.color}` }} size="small">
                                <Statistic title={<span style={{ fontSize: 12 }}>{s.title}</span>} value={s.value} prefix={s.icon} valueStyle={{ fontSize: 24, fontWeight: 700, color: s.color }} />
                            </Card>
                        </motion.div>
                    </Col>
                ))}
            </Row>

            {/* ── Effort Summary ── */}
            <Card style={{ ...glassCard, marginBottom: 16 }} size="small">
                <Row gutter={24} align="middle">
                    <Col>
                        <Text type="secondary" style={{ fontSize: 12 }}>Total Effort: </Text>
                        <Text strong>{totalLogged}h</Text>
                        <Text type="secondary" style={{ fontSize: 11 }}> / {totalEstimated}h estimated</Text>
                    </Col>
                    <Col flex={1} style={{ maxWidth: 300 }}>
                        <Progress
                            percent={totalEstimated > 0 ? Math.round((totalLogged / totalEstimated) * 100) : 0}
                            size="small"
                            strokeColor={{ '0%': 'var(--theme-color, #8b5cf6)', '100%': 'var(--theme-secondary, #6366f1)' }}
                            trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                        />
                    </Col>
                    <Col>
                        <Text type="secondary" style={{ fontSize: 12 }}>
                            {projects.length} projects • {blockedCount} blocked
                        </Text>
                    </Col>
                    <Col>
                        <Button type="text" size="small" icon={<ReloadOutlined />} onClick={loadData} aria-label="Reload data" />
                    </Col>
                </Row>
            </Card>

            {/* ── Search & Filters ── */}
            <Card style={{ ...glassCard, marginBottom: 16 }} size="small" role="region" aria-label="Task filters">
                <Space size={12} wrap style={{ width: '100%' }}>
                    <Input
                        placeholder="Search tasks, tags..."
                        prefix={<SearchOutlined />}
                        value={search}
                        onChange={e => setSearch(e.target.value)}
                        allowClear
                        style={{ width: 280 }}
                        aria-label="Search tasks"
                    />
                    <Select
                        placeholder="Status"
                        allowClear
                        value={statusFilter}
                        onChange={setStatusFilter}
                        style={{ width: 160 }}
                        options={[
                            { label: `To Do (${tasks.filter(t => t.status === 'todo').length})`, value: 'todo' },
                            { label: `In Progress (${tasks.filter(t => t.status === 'in_progress').length})`, value: 'in_progress' },
                            { label: `In Review (${tasks.filter(t => t.status === 'in_review').length})`, value: 'in_review' },
                            { label: `Done (${tasks.filter(t => t.status === 'done').length})`, value: 'done' },
                            { label: `Blocked (${tasks.filter(t => t.status === 'blocked').length})`, value: 'blocked' },
                        ]}
                        aria-label="Status filter"
                    />
                    <Select
                        placeholder="Priority"
                        allowClear
                        value={priorityFilter}
                        onChange={setPriorityFilter}
                        style={{ width: 130 }}
                        options={['critical', 'high', 'medium', 'low'].map(p => ({
                            label: p.charAt(0).toUpperCase() + p.slice(1), value: p
                        }))}
                        aria-label="Priority filter"
                    />
                    <Select
                        placeholder="Project"
                        allowClear
                        value={projectFilter}
                        onChange={setProjectFilter}
                        style={{ width: 200 }}
                        options={projects.map(p => ({ label: p.name, value: p.id }))}
                        showSearch
                        filterOption={(input, option) =>
                            (option?.label ?? '').toString().toLowerCase().includes(input.toLowerCase())
                        }
                        aria-label="Project filter"
                    />
                    <Select
                        placeholder="Type"
                        allowClear
                        value={typeFilter}
                        onChange={setTypeFilter}
                        style={{ width: 120 }}
                        options={['task', 'bug', 'story', 'epic'].map(t => ({
                            label: t.charAt(0).toUpperCase() + t.slice(1), value: t
                        }))}
                        aria-label="Type filter"
                    />
                    <Select
                        placeholder="Assignee"
                        allowClear
                        value={assigneeFilter}
                        onChange={setAssigneeFilter}
                        style={{ width: 160 }}
                        showSearch
                        filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                        options={[
                            { label: 'Unassigned', value: '__unassigned__' },
                            ...members.map(m => ({
                                label: `${m.user?.firstName || ''} ${m.user?.lastName || ''}`.trim() || m.user?.email || 'Unknown',
                                value: m.userId || m.user?.id || m.id,
                            })),
                        ]}
                        aria-label="Assignee filter"
                    />
                    <Select
                        placeholder="Sprint"
                        allowClear
                        value={sprintFilter}
                        onChange={setSprintFilter}
                        style={{ width: 140 }}
                        options={[
                            { label: 'Has Sprint', value: 'assigned' },
                            { label: 'No Sprint (Backlog)', value: 'unassigned' },
                        ]}
                        aria-label="Sprint filter"
                    />
                    {(search || statusFilter || priorityFilter || projectFilter || typeFilter || assigneeFilter || sprintFilter) && (
                        <Tag color="blue">{filtered.length} results</Tag>
                    )}
                </Space>

                {/* Saved Views Row */}
                <div style={{ marginTop: 12, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                    <Text type="secondary" style={{ fontSize: 11 }}>Views:</Text>
                    {savedViews.map(view => (
                        <Tag
                            key={view.name}
                            closable
                            onClose={(e) => { e.preventDefault(); handleDeleteView(view.name); }}
                            onClick={() => handleLoadView(view)}
                            style={{ cursor: 'pointer', fontSize: 11, borderRadius: 6 }}
                            color="purple"
                        >
                            {view.name}
                        </Tag>
                    ))}
                    <Button
                        size="small"
                        type="dashed"
                        icon={<PlusOutlined />}
                        onClick={() => setSaveViewModalOpen(true)}
                        style={{ fontSize: 11, borderRadius: 6 }}
                    >
                        Save Current
                    </Button>
                </div>
            </Card>

            {/* ── Bulk Actions Bar ── */}
            <AnimatePresence>
                {selectedRowKeys.length > 0 && (
                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}>
                        <Card size="small" style={{ ...glassCard, marginBottom: 16, borderLeft: `3px solid ${themeColor}` }}>
                            <Space size={12} wrap align="center">
                                <Tag color="purple" style={{ fontSize: 13, padding: '2px 10px' }}>{selectedRowKeys.length} selected</Tag>
                                <Select placeholder="Set Status" size="small" style={{ width: 150 }}
                                    onChange={(val) => handleBulkUpdate('status', val)}
                                    options={Object.entries(STATUS_CONFIG).map(([k, v]) => ({ label: v.label, value: k }))}
                                />
                                <Select placeholder="Set Priority" size="small" style={{ width: 140 }}
                                    onChange={(val) => handleBulkUpdate('priority', val)}
                                    options={['critical', 'high', 'medium', 'low'].map(p => ({ label: p.charAt(0).toUpperCase() + p.slice(1), value: p }))}
                                />
                                <Button size="small" icon={<CloseOutlined />} onClick={() => setSelectedRowKeys([])}>Clear</Button>
                            </Space>
                        </Card>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* ── Tasks Table / Board ── */}
            <Card
                title={
                    <Space>
                        <UnorderedListOutlined style={{ color: themeColor }} />
                        <span style={{ fontWeight: 600 }}>All Tasks</span>
                        <Tag color="purple">{filtered.length}</Tag>
                    </Space>
                }
                extra={
                    <Button
                        type={quickCreateOpen ? 'default' : 'primary'}
                        size="small"
                        icon={quickCreateOpen ? <CloseOutlined /> : <PlusOutlined />}
                        onClick={() => setQuickCreateOpen(!quickCreateOpen)}
                        style={quickCreateOpen ? {} : {
                            background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`,
                            border: 'none',
                            borderRadius: 8,
                        }}
                        aria-label={quickCreateOpen ? 'Close quick create' : 'Quick create task'}
                    >
                        {quickCreateOpen ? 'Cancel' : 'New Task'}
                    </Button>
                }
                style={glassCard}
                role="region"
                aria-label="Task list"
            >
                {/* Quick-Create Bar */}
                <AnimatePresence>
                    {quickCreateOpen && (
                        <motion.div
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 'auto' }}
                            exit={{ opacity: 0, height: 0 }}
                            style={{ overflow: 'hidden', marginBottom: 16 }}
                        >
                            <div style={{
                                display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap',
                                padding: '16px',
                                background: isDark ? 'rgba(139,92,246,0.08)' : 'linear-gradient(135deg, rgba(139,92,246,0.05), rgba(139,92,246,0.02))',
                                border: isDark ? '1px solid rgba(139,92,246,0.3)' : '1px solid rgba(139,92,246,0.2)',
                                borderRadius: 12,
                                boxShadow: isDark ? '0 4px 20px rgba(139,92,246,0.1)' : '0 4px 20px rgba(139,92,246,0.05)',
                                transition: 'all 0.3s ease',
                            }} className="hover:border-[color:var(--theme-color)] hover:shadow-md">
                                <PlusOutlined style={{ color: themeColor, fontSize: 16 }} />
                                <Input
                                    placeholder="Task title... (press Enter to create)"
                                    value={quickTitle}
                                    onChange={e => setQuickTitle(e.target.value)}
                                    onPressEnter={handleQuickCreate}
                                    size="small"
                                    style={{ flex: 1, minWidth: 200, borderRadius: 8 }}
                                    autoFocus
                                    aria-label="New task title"
                                />
                                <Select
                                    size="small"
                                    placeholder="Project *"
                                    value={quickProject}
                                    onChange={setQuickProject}
                                    style={{ width: 160 }}
                                    showSearch
                                    optionFilterProp="label"
                                    options={projects.filter(p => p.status === 'active').map(p => ({ value: p.id, label: p.name }))}
                                    aria-label="Select project for new task"
                                />
                                <Select
                                    size="small"
                                    value={quickType}
                                    onChange={setQuickType}
                                    style={{ width: 90 }}
                                    options={['task', 'bug', 'story', 'epic'].map(t => ({
                                        label: <Tag color={t === 'bug' ? 'red' : t === 'story' ? 'green' : t === 'epic' ? 'purple' : 'default'} style={{ margin: 0, textTransform: 'capitalize' as const }}>{t}</Tag>,
                                        value: t,
                                    }))}
                                    aria-label="Task type"
                                />
                                <Select
                                    size="small"
                                    value={quickPriority}
                                    onChange={setQuickPriority}
                                    style={{ width: 110 }}
                                    options={Object.entries(PRIORITY_CONFIG).map(([k, v]) => ({
                                        label: <Tag color={v.color} icon={v.icon} style={{ margin: 0, textTransform: 'capitalize' as const }}>{k}</Tag>,
                                        value: k,
                                    }))}
                                    aria-label="Task priority"
                                />
                                <Button
                                    type="primary"
                                    size="small"
                                    icon={<PlusOutlined />}
                                    onClick={handleQuickCreate}
                                    loading={quickCreating}
                                    disabled={!quickTitle.trim() || !quickProject}
                                    style={{
                                        background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`,
                                        border: 'none',
                                        borderRadius: 8,
                                    }}
                                    aria-label="Create task"
                                >
                                    Create
                                </Button>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {filtered.length === 0 ? (
                    <motion.div initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }}>
                        <Card style={{ ...glassCard, padding: 40, textAlign: 'center', borderStyle: 'dashed', borderWidth: 2, marginTop: 16 }}>
                            <Empty
                                description={
                                    <span style={{ fontSize: 16, fontWeight: 500, color: isDark ? '#94a3b8' : '#64748b' }}>
                                        {tasks.length === 0
                                            ? "No tasks found across your projects."
                                            : "No tasks match your current filters."}
                                    </span>
                                }
                            />
                        </Card>
                    </motion.div>
                ) : viewMode === 'board' ? (
                    <KanbanBoard
                        tasks={filtered}
                        onTaskUpdate={handleKanbanUpdate}
                        onTaskClick={(task: any) => router.push(`/admin/pm/tasks/${task.id}`)}
                        themeColor={themeColor}
                        isDark={isDark}
                    />
                ) : (
                    <Table scroll={{ x: 900 }}
                        dataSource={filtered}
                        columns={columns}
                        rowKey="id"
                        rowSelection={rowSelection}
                        pagination={{ pageSize: 20, showSizeChanger: true, showTotal: (t) => `${t} tasks` }}
                        size="small"
                        style={{ fontSize: 13 }}
                        onRow={(record) => ({
                            onClick: () => router.push(`/admin/pm/tasks/${record.id}`),
                            style: { cursor: 'pointer' },
                        })}
                    />
                )}
            </Card>


            {/* ── Save View Modal ── */}
            <Modal
                title="Save View"
                open={saveViewModalOpen}
                onCancel={() => setSaveViewModalOpen(false)}
                onOk={handleSaveView}
                okText="Save"
                okButtonProps={{ disabled: !newViewName.trim() }}
            >
                <Input
                    placeholder="View name (e.g. 'My High Priority Bugs')"
                    value={newViewName}
                    onChange={e => setNewViewName(e.target.value)}
                    onPressEnter={handleSaveView}
                    autoFocus
                />
            </Modal>

        </CMSLayout>
    );
}

