"use client";

import React, { useState, useEffect } from 'react';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Typography, Avatar, Tag, Button, Input, Dropdown } from 'antd';
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd';
import { 
    PlusOutlined, 
    MoreOutlined, 
    CheckCircleOutlined, 
    ClockCircleOutlined,
    ExclamationCircleOutlined,
    UserOutlined,
    SearchOutlined
} from '@ant-design/icons';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { useTheme } from "next-themes";
import { AuroraText } from '@/components/magicui/aurora-text';
import { motion } from 'framer-motion';

const { Text, Title } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', border: '1px solid rgba(255,255,255,0.45)' };

// Initial Mock Data
const initialData = {
    tasks: {
        'task-1': { id: 'task-1', content: 'Design landing page', priority: 'High', status: 'To Do', assignee: 'Alex', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Alex' },
        'task-2': { id: 'task-2', content: 'Setup CI/CD pipeline', priority: 'Critical', status: 'To Do', assignee: 'Sam', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Sam' },
        'task-3': { id: 'task-3', content: 'Implement auth module', priority: 'Medium', status: 'In Progress', assignee: 'Jordan', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Jordan' },
        'task-4': { id: 'task-4', content: 'Update payment gateway', priority: 'High', status: 'In Progress', assignee: 'Taylor', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Taylor' },
        'task-5': { id: 'task-5', content: 'Fix navbar bug on mobile', priority: 'Low', status: 'Done', assignee: 'Alex', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Alex' },
    },
    columns: {
        'col-1': { id: 'col-1', title: 'To Do', taskIds: ['task-1', 'task-2'] },
        'col-2': { id: 'col-2', title: 'In Progress', taskIds: ['task-3', 'task-4'] },
        'col-3': { id: 'col-3', title: 'Review', taskIds: [] },
        'col-4': { id: 'col-4', title: 'Done', taskIds: ['task-5'] },
    },
    columnOrder: ['col-1', 'col-2', 'col-3', 'col-4'],
};

const getPriorityColor = (priority: string) => {
    switch (priority) {
        case 'Critical': return '#ef4444';
        case 'High': return '#f59e0b';
        case 'Medium': return '#3b82f6';
        default: return '#10b981';
    }
};

export default function KanbanBoardPage() {
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const isDark = resolvedTheme === 'dark';
    const [data, setData] = useState(initialData);
    const [isBrowser, setIsBrowser] = useState(false);

    useEffect(() => {
        setIsBrowser(true);
    }, []);

    const onDragEnd = (result: any) => {
        const { destination, source, draggableId } = result;

        if (!destination) return;
        if (destination.droppableId === source.droppableId && destination.index === source.index) return;

        const start = data.columns[source.droppableId as keyof typeof data.columns];
        const finish = data.columns[destination.droppableId as keyof typeof data.columns];

        if (start === finish) {
            const newTaskIds = Array.from(start.taskIds);
            newTaskIds.splice(source.index, 1);
            newTaskIds.splice(destination.index, 0, draggableId);

            const newColumn = { ...start, taskIds: newTaskIds };
            setData(prev => ({
                ...prev,
                columns: { ...prev.columns, [newColumn.id]: newColumn }
            }));
            return;
        }

        // Moving to a different column
        const startTaskIds = Array.from(start.taskIds);
        startTaskIds.splice(source.index, 1);
        const newStart = { ...start, taskIds: startTaskIds };

        const finishTaskIds = Array.from(finish.taskIds);
        finishTaskIds.splice(destination.index, 0, draggableId);
        const newFinish = { ...finish, taskIds: finishTaskIds };

        setData(prev => ({
            ...prev,
            columns: {
                ...prev.columns,
                [newStart.id]: newStart,
                [newFinish.id]: newFinish,
            }
        }));
    };

    if (!isBrowser) return null;

    return (
        <CMSLayout 
            title={<AuroraText colors={[themeColor, '#ff6d5a', '#10b981']}>Kanban Board</AuroraText>} 
            subTitle="Manage project tasks with drag-and-drop workflow"
            extra={[
                <Input key="search" prefix={<SearchOutlined />} placeholder="Search tasks..." style={{ width: 200, borderRadius: 20 }} />,
                <Avatar.Group key="users" size="small" max={{ count: 3 }} className="mr-2">
                    <Avatar src="https://api.dicebear.com/7.x/avataaars/svg?seed=Alex" />
                    <Avatar src="https://api.dicebear.com/7.x/avataaars/svg?seed=Sam" />
                    <Avatar src="https://api.dicebear.com/7.x/avataaars/svg?seed=Jordan" />
                    <Avatar src="https://api.dicebear.com/7.x/avataaars/svg?seed=Taylor" />
                </Avatar.Group>,
                <Button key="add" type="primary" icon={<PlusOutlined />} style={{ backgroundColor: themeColor, borderRadius: 8 }}>New Task</Button>
            ]}
        >
            <div className="flex h-full gap-4 overflow-x-auto pb-4 custom-scrollbar" style={{ minHeight: 'calc(100vh - 180px)' }}>
                <DragDropContext onDragEnd={onDragEnd}>
                    {data.columnOrder.map((columnId) => {
                        const column = data.columns[columnId as keyof typeof data.columns];
                        const tasks = column.taskIds.map(taskId => data.tasks[taskId as keyof typeof data.tasks]);

                        return (
                            <div key={column.id} className="flex flex-col min-w-[320px] max-w-[320px]">
                                <div className="flex items-center justify-between mb-3 px-1">
                                    <div className="flex items-center gap-2">
                                        <Text strong className="text-sm">{column.title}</Text>
                                        <Tag className="rounded-full m-0 border-none bg-black/5 dark:bg-white/10 text-xs">
                                            {tasks.length}
                                        </Tag>
                                    </div>
                                    <Button type="text" size="small" icon={<MoreOutlined />} />
                                </div>

                                <Droppable droppableId={column.id}>
                                    {(provided, snapshot) => (
                                        <div
                                            ref={provided.innerRef}
                                            {...provided.droppableProps}
                                            className="flex-1 rounded-xl p-2 transition-colors duration-200"
                                            style={{
                                                ...glass,
                                                background: snapshot.isDraggingOver 
                                                    ? (isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.04)')
                                                    : (isDark ? 'rgba(15,15,23,0.4)' : 'rgba(249,250,251,0.5)'),
                                                minHeight: 150
                                            }}
                                        >
                                            {tasks.map((task, index) => (
                                                <Draggable key={task.id} draggableId={task.id} index={index}>
                                                    {(provided, snapshot) => (
                                                        <div
                                                            ref={provided.innerRef}
                                                            {...provided.draggableProps}
                                                            {...provided.dragHandleProps}
                                                            style={{ ...provided.draggableProps.style }}
                                                        >
                                                            <Card
                                                                size="small"
                                                                hoverable
                                                                className="mb-3 cursor-grab active:cursor-grabbing shadow-sm hover:shadow-md transition-shadow"
                                                                style={{ 
                                                                    borderRadius: 12,
                                                                    boxShadow: snapshot.isDragging ? '0 20px 25px -5px rgba(0, 0, 0, 0.2), 0 10px 10px -5px rgba(0, 0, 0, 0.1)' : '0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)',
                                                                    transition: snapshot.isDragging ? 'none' : 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                                                                    borderLeft: `4px solid ${getPriorityColor(task.priority)}`
                                                                }}
                                                                bodyStyle={{ padding: '12px' }}
                                                            >
                                                                <div className="flex flex-col gap-2">
                                                                    <div className="flex justify-between items-start">
                                                                        <Tag color={getPriorityColor(task.priority)} className="border-none text-[10px] m-0 rounded-full px-2">
                                                                            {task.priority}
                                                                        </Tag>
                                                                        <Button type="text" size="small" icon={<MoreOutlined />} className="h-5 w-5 opacity-40 hover:opacity-100" />
                                                                    </div>
                                                                    <Text className="text-sm font-medium leading-tight block mb-2 cursor-pointer hover:text-blue-500 transition-colors" onClick={(e) => { e.stopPropagation(); window.location.href = `/admin/pm/tasks/${task.id}`; }}>{task.content}</Text>
                                                                    <div className="flex justify-between items-end mt-auto">
                                                                        <div className="flex items-center gap-1.5 text-gray-400 text-xs">
                                                                            {column.title === 'Done' ? <CheckCircleOutlined className="text-green-500" /> : <ClockCircleOutlined />}
                                                                            <span>{task.id}</span>
                                                                        </div>
                                                                        <div onClick={(e) => { e.stopPropagation(); window.location.href = `/admin/pm/workload?user=${task.assignee}`; }} className="cursor-pointer hover:scale-110 transition-transform">
                                                                            <Avatar src={task.avatar} size="small" className="border-2 border-white dark:border-gray-800" />
                                                                        </div>
                                                                    </div>
                                                                </div>
                                                            </Card>
                                                        </div>
                                                    )}
                                                </Draggable>
                                            ))}
                                            {provided.placeholder}
                                            <Button type="dashed" block icon={<PlusOutlined />} className="mt-1 opacity-60 hover:opacity-100 border-dashed bg-transparent" style={{ borderRadius: 8 }}>
                                                Add Task
                                            </Button>
                                        </div>
                                    )}
                                </Droppable>
                            </div>
                        );
                    })}
                </DragDropContext>
            </div>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useMemo, useCallback } from "react";
import { Badge, Tag, Tooltip, message } from "antd";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";

// ── Types ────────────────────────────────────────────────
interface ColumnDef {
    key: string;
    title: string;
    color: string;
}

interface KanbanBoardProps {
    tasks: any[];
    onTaskUpdate: (taskId: string, updates: Record<string, any>) => Promise<void>;
    onTaskClick: (task: any) => void;
    columns?: ColumnDef[];
    groupBy?: "status" | "priority" | "assignee";
    themeColor: string;
    isDark: boolean;
}

// ── Constants ────────────────────────────────────────────
const DEFAULT_COLUMNS: ColumnDef[] = [
    { key: "todo", title: "Todo", color: "#94a3b8" },
    { key: "in_progress", title: "In Progress", color: "#3b82f6" },
    { key: "in_review", title: "In Review", color: "#8b5cf6" },
    { key: "blocked", title: "Blocked", color: "#ef4444" },
    { key: "done", title: "Done", color: "#10b981" },
];

const PRIORITY_COLUMNS: ColumnDef[] = [
    { key: "critical", title: "Critical", color: "#ef4444" },
    { key: "high", title: "High", color: "#f59e0b" },
    { key: "medium", title: "Medium", color: "#3b82f6" },
    { key: "low", title: "Low", color: "#6b7280" },
];

const TYPE_EMOJI: Record<string, string> = {
    bug: "🐛", story: "📖", task: "✅", epic: "🏔️", spike: "⚡",
};

const PRIORITY_COLORS: Record<string, string> = {
    critical: "#ef4444", high: "#f59e0b", medium: "#3b82f6", low: "#6b7280",
};

const STATUS_FLOW = ["todo", "in_progress", "in_review", "blocked", "done"];
const PRIORITY_FLOW = ["low", "medium", "high", "critical"];

const GROUP_OPTIONS: { key: "status" | "priority" | "assignee"; label: string }[] = [
    { key: "status", label: "Status" },
    { key: "priority", label: "Priority" },
    { key: "assignee", label: "Assignee" },
];

// ── Component ────────────────────────────────────────────
export default function KanbanBoard({
    tasks,
    onTaskUpdate,
    onTaskClick,
    columns: customColumns,
    groupBy: initialGroupBy = "status",
    themeColor,
    isDark,
}: KanbanBoardProps) {
    const [messageApi, contextHolder] = message.useMessage();
    const [groupBy, setGroupBy] = useState<"status" | "priority" | "assignee">(initialGroupBy);
    const [draggingId, setDraggingId] = useState<string | null>(null);
    const [dragOverCol, setDragOverCol] = useState<string | null>(null);
    const [collapsedCols, setCollapsedCols] = useState<Set<string>>(new Set());

    // ── Dynamic columns based on groupBy ─────────────────
    const activeColumns = useMemo<ColumnDef[]>(() => {
        if (customColumns && groupBy === "status") return customColumns;
        if (groupBy === "priority") return PRIORITY_COLUMNS;
        if (groupBy === "assignee") {
            const names = new Set<string>();
            tasks.forEach(t => {
                const name = t.assignee
                    ? `${t.assignee.firstName || ""} ${t.assignee.lastName || ""}`.trim()
                    : "";
                names.add(name || "__unassigned__");
            });
            const cols: ColumnDef[] = [];
            names.forEach(n => {
                if (n === "__unassigned__") {
                    cols.push({ key: "__unassigned__", title: "Unassigned", color: "#94a3b8" });
                } else {
                    cols.push({ key: n, title: n, color: themeColor });
                }
            });
            return cols.length > 0 ? cols : [{ key: "__unassigned__", title: "Unassigned", color: "#94a3b8" }];
        }
        return DEFAULT_COLUMNS;
    }, [customColumns, groupBy, tasks, themeColor]);

    // ── Group tasks into columns ─────────────────────────
    const tasksByColumn = useMemo(() => {
        const map: Record<string, any[]> = {};
        activeColumns.forEach(c => (map[c.key] = []));
        tasks.forEach(t => {
            let key: string;
            if (groupBy === "status") key = t.status || "todo";
            else if (groupBy === "priority") key = t.priority || "medium";
            else {
                const name = t.assignee
                    ? `${t.assignee.firstName || ""} ${t.assignee.lastName || ""}`.trim()
                    : "";
                key = name || "__unassigned__";
            }
            if (map[key]) map[key].push(t);
            else if (map[activeColumns[0]?.key]) map[activeColumns[0].key].push(t);
        });
        return map;
    }, [tasks, activeColumns, groupBy]);

    // ── Collapse toggle ──────────────────────────────────
    const toggleCollapse = useCallback((key: string) => {
        setCollapsedCols(prev => {
            const next = new Set(prev);
            next.has(key) ? next.delete(key) : next.add(key);
            return next;
        });
    }, []);

    // ── Drag handlers (HTML5 native) ─────────────────────
    const handleDragStart = useCallback((e: React.DragEvent, taskId: string) => {
        e.dataTransfer.setData("text/plain", taskId);
        e.dataTransfer.effectAllowed = "move";
        setDraggingId(taskId);
    }, []);

    const handleDragEnd = useCallback(() => {
        setDraggingId(null);
        setDragOverCol(null);
    }, []);

    const handleDragOver = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
    }, []);

    const handleDragEnter = useCallback((colKey: string) => {
        setDragOverCol(colKey);
    }, []);

    const handleDragLeave = useCallback((e: React.DragEvent, colKey: string) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const { clientX: x, clientY: y } = e;
        if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
            setDragOverCol(prev => (prev === colKey ? null : prev));
        }
    }, []);

    const handleDrop = useCallback(async (e: React.DragEvent, colKey: string) => {
        e.preventDefault();
        setDragOverCol(null);
        const taskId = e.dataTransfer.getData("text/plain");
        if (!taskId) return;
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const fieldMap: Record<string, string> = { status: "status", priority: "priority", assignee: "assigneeId" };
        const field = fieldMap[groupBy] || "status";

        // Skip if same column
        const currentVal = groupBy === "assignee"
            ? (task.assignee ? `${task.assignee.firstName || ""} ${task.assignee.lastName || ""}`.trim() || "__unassigned__" : "__unassigned__")
            : task[field];
        if (currentVal === colKey) return;

        try {
            const updateVal = groupBy === "assignee" ? (colKey === "__unassigned__" ? null : colKey) : colKey;
            await onTaskUpdate(taskId, { [field]: updateVal });
            const col = activeColumns.find(c => c.key === colKey);
            messageApi.success(`Moved to ${col?.title || colKey}`);
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error("Failed to move task");
        }
    }, [tasks, groupBy, onTaskUpdate, activeColumns, messageApi]);

    // ── Quick actions ────────────────────────────────────
    const cycleStatus = useCallback(async (e: React.MouseEvent, task: any) => {
        e.stopPropagation();
        const idx = STATUS_FLOW.indexOf(task.status);
        const next = STATUS_FLOW[(idx + 1) % STATUS_FLOW.length];
        try {
            await onTaskUpdate(task.id, { status: next });
        } catch (err: any) { console.error("PM Error", err); }
    }, [onTaskUpdate]);

    const cyclePriority = useCallback(async (e: React.MouseEvent, task: any) => {
        e.stopPropagation();
        const idx = PRIORITY_FLOW.indexOf(task.priority);
        const next = PRIORITY_FLOW[(idx + 1) % PRIORITY_FLOW.length];
        try {
            await onTaskUpdate(task.id, { priority: next });
        } catch (err: any) { console.error("PM Error", err); }
    }, [onTaskUpdate]);

    // ── Render task card ─────────────────────────────────
    const renderCard = (task: any, index: number) => {
        const isBeingDragged = draggingId === task.id;
        const prioColor = PRIORITY_COLORS[task.priority] || "#6b7280";
        const typeEmoji = TYPE_EMOJI[task.type] || "📋";
        const isOverdue = task.dueDate && dayjs(task.dueDate).isBefore(dayjs(), "day") && task.status !== "done";
        const assigneeInitial = task.assignee
            ? `${(task.assignee.firstName || "")[0] || ""}${(task.assignee.lastName || "")[0] || ""}`.toUpperCase()
            : null;
        const tags: string[] = task.tags || [];

        return (
            <motion.div
                key={task.id}
                role="listitem"
                aria-label={`Task: ${task.title}`}
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: isBeingDragged ? 0.4 : 1, y: 0 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.2, delay: index * 0.03 }}
                draggable
                onDragStart={(e: any) => handleDragStart(e, task.id)}
                onDragEnd={handleDragEnd}
                onClick={() => onTaskClick(task)}
                style={{
                    background: isDark ? "rgba(30, 30, 44, 0.4)" : "rgba(248,250,252,0.6)",
                    border: isDark ? "1px solid rgba(139,92,246,0.15)" : "1px solid rgba(0,0,0,0.05)",
                    borderRadius: 10,
                    padding: "12px 14px",
                    marginBottom: 8,
                    cursor: "grab",
                    transition: "box-shadow 0.2s, opacity 0.2s",
                    boxShadow: isDark ? "0 2px 8px rgba(0,0,0,0.3)" : "0 1px 4px rgba(0,0,0,0.06)",
                }}
            >
                {/* Title row */}
                <div style={{ display: "flex", alignItems: "flex-start", gap: 6, marginBottom: 8 }}>
                    <span style={{ fontSize: 14, flexShrink: 0, lineHeight: "18px" }}>{typeEmoji}</span>
                    <span style={{
                        flex: 1, fontSize: 13, fontWeight: 600, lineHeight: "18px",
                        color: isDark ? "#e2e8f0" : "#1f2937",
                        display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical",
                        overflow: "hidden", textOverflow: "ellipsis",
                    }}>
                        {task.title}
                    </span>
                </div>

                {/* Priority + Tags row */}
                <div style={{ display: "flex", alignItems: "center", gap: 4, flexWrap: "wrap", marginBottom: 8 }}>
                    <Tag style={{
                        fontSize: 10, borderRadius: 6, padding: "0 6px", margin: 0,
                        background: `${prioColor}18`, color: prioColor, border: `1px solid ${prioColor}33`,
                        textTransform: "capitalize", fontWeight: 600,
                    }}>
                        {task.priority}
                    </Tag>
                    {tags.slice(0, 2).map((tag: string) => (
                        <Tag key={tag} style={{ fontSize: 10, borderRadius: 6, padding: "0 5px", margin: 0 }} color="cyan">
                            {tag}
                        </Tag>
                    ))}
                    {tags.length > 2 && (
                        <span style={{ fontSize: 10, color: isDark ? "#64748b" : "#94a3b8" }}>+{tags.length - 2}</span>
                    )}
                </div>

                {/* Subtask progress (if subtasks exist) */}
                {task.subtasksDone != null && task.subtasksTotal > 0 && (
                    <div style={{ marginBottom: 8 }}>
                        <div style={{
                            height: 4, borderRadius: 2, background: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)",
                            overflow: "hidden",
                        }}>
                            <div style={{
                                height: "100%", borderRadius: 2,
                                width: `${Math.round((task.subtasksDone / task.subtasksTotal) * 100)}%`,
                                background: task.subtasksDone === task.subtasksTotal ? "#10b981" : themeColor,
                                transition: "width 0.3s",
                            }} />
                        </div>
                        <span style={{ fontSize: 10, color: isDark ? "#64748b" : "#94a3b8" }}>
                            {task.subtasksDone}/{task.subtasksTotal} subtasks
                        </span>
                    </div>
                )}

                {/* Bottom row: assignee, due date, quick actions */}
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                        {/* Assignee */}
                        {assigneeInitial ? (
                            <Tooltip title={`${task.assignee.firstName} ${task.assignee.lastName}`}>
                                <span style={{
                                    width: 22, height: 22, borderRadius: "50%", fontSize: 9, fontWeight: 700,
                                    display: "flex", alignItems: "center", justifyContent: "center",
                                    background: `${themeColor}22`, color: themeColor, flexShrink: 0,
                                }}>
                                    {assigneeInitial}
                                </span>
                            </Tooltip>
                        ) : (
                            <span style={{
                                fontSize: 10, color: isDark ? "#475569" : "#d1d5db",
                                fontStyle: "italic",
                            }}>
                                Unassigned
                            </span>
                        )}

                        {/* Due date */}
                        {task.dueDate && (
                            <span style={{
                                fontSize: 10, fontWeight: 500,
                                color: isOverdue ? "#ef4444" : (isDark ? "#94a3b8" : "#888"),
                                background: isOverdue ? "rgba(239,68,68,0.1)" : "transparent",
                                padding: isOverdue ? "1px 5px" : 0,
                                borderRadius: 4,
                            }}>
                                📅 {dayjs(task.dueDate).format("MMM D")}
                            </span>
                        )}
                    </div>

                    {/* Quick action buttons */}
                    <div style={{ display: "flex", gap: 4 }}>
                        <Tooltip title="Cycle status">
                            <span
                                onClick={(e) => cycleStatus(e, task)}
                                style={{
                                    width: 20, height: 20, borderRadius: 4, fontSize: 11,
                                    display: "flex", alignItems: "center", justifyContent: "center",
                                    cursor: "pointer", transition: "background 0.15s",
                                    background: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)",
                                    color: isDark ? "#94a3b8" : "#64748b",
                                }}
                                onMouseEnter={e => (e.currentTarget.style.background = `${themeColor}22`)}
                                onMouseLeave={e => (e.currentTarget.style.background = isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)")}
                            >
                                ▶
                            </span>
                        </Tooltip>
                        <Tooltip title="Cycle priority">
                            <span
                                onClick={(e) => cyclePriority(e, task)}
                                style={{
                                    width: 20, height: 20, borderRadius: 4, fontSize: 11,
                                    display: "flex", alignItems: "center", justifyContent: "center",
                                    cursor: "pointer", transition: "background 0.15s",
                                    background: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)",
                                    color: prioColor,
                                }}
                                onMouseEnter={e => (e.currentTarget.style.background = `${prioColor}22`)}
                                onMouseLeave={e => (e.currentTarget.style.background = isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)")}
                            >
                                ⚡
                            </span>
                        </Tooltip>
                    </div>
                </div>
            </motion.div>
        );
    };

    // ── Render ────────────────────────────────────────────
    return (
        <div>
            {contextHolder}

            {/* Group By toggle */}
            <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 16 }} role="group" aria-label="Group by options">
                <span style={{ fontSize: 12, fontWeight: 600, color: isDark ? "#94a3b8" : "#64748b" }}>Group by:</span>
                {GROUP_OPTIONS.map(opt => (
                    <span
                        key={opt.key}
                        role="button"
                        tabIndex={0}
                        aria-label={`Group by ${opt.label}`}
                        aria-pressed={groupBy === opt.key}
                        onClick={() => setGroupBy(opt.key)}
                        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setGroupBy(opt.key); } }}
                        style={{
                            fontSize: 12, fontWeight: 600, padding: "4px 12px", borderRadius: 6,
                            cursor: "pointer", transition: "all 0.2s",
                            background: groupBy === opt.key
                                ? `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`
                                : isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)",
                            color: groupBy === opt.key ? "#fff" : (isDark ? "#cbd5e1" : "#374151"),
                            border: groupBy === opt.key ? "none" : isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(0,0,0,0.06)",
                        }}
                    >
                        {opt.label}
                    </span>
                ))}
            </div>

            {/* Columns */}
            <div style={{
                display: "flex", gap: 14, overflowX: "auto",
                padding: "4px 2px 8px 2px",
            }}>
                {activeColumns.map(col => {
                    const colTasks = tasksByColumn[col.key] || [];
                    const isOver = dragOverCol === col.key;
                    const isCollapsed = collapsedCols.has(col.key);

                    return (
                        <div
                            key={col.key}
                            role="region"
                            aria-label={`${col.title} column`}
                            onDragOver={handleDragOver}
                            onDragEnter={() => handleDragEnter(col.key)}
                            onDragLeave={(e) => handleDragLeave(e, col.key)}
                            onDrop={(e) => handleDrop(e, col.key)}
                            style={{
                                flex: "0 0 auto",
                                minWidth: 280,
                                width: 280,
                                display: "flex",
                                flexDirection: "column",
                                background: isDark
                                    ? `rgba(15, 15, 23, ${isOver ? 0.85 : 0.6})`
                                    : `rgba(255,255,255, ${isOver ? 0.75 : 0.5})`,
                                border: isOver
                                    ? `2px dashed ${col.color}`
                                    : isDark
                                        ? "1px solid rgba(139,92,246,0.12)"
                                        : "1px solid rgba(0,0,0,0.06)",
                                borderRadius: 12,
                                padding: 12,
                                transition: "all 0.25s ease",
                                boxShadow: isOver ? `0 0 20px ${col.color}22` : "none",
                            }}
                        >
                            {/* Column header */}
                            <div
                                onClick={() => toggleCollapse(col.key)}
                                style={{
                                    display: "flex", justifyContent: "space-between", alignItems: "center",
                                    marginBottom: 12, padding: "6px 10px",
                                    background: `${col.color}12`, borderRadius: 8,
                                    cursor: "pointer", userSelect: "none",
                                }}
                            >
                                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                    <span style={{
                                        width: 8, height: 8, borderRadius: "50%",
                                        background: col.color, flexShrink: 0,
                                    }} />
                                    <span style={{ fontSize: 12, fontWeight: 700, color: col.color }}>
                                        {col.title}
                                    </span>
                                    <Badge
                                        count={colTasks.length}
                                        style={{ backgroundColor: col.color, fontSize: 10 }}
                                        size="small"
                                    />
                                </div>
                                <span style={{
                                    fontSize: 10, color: isDark ? "#64748b" : "#94a3b8",
                                    transform: isCollapsed ? "rotate(-90deg)" : "rotate(0deg)",
                                    transition: "transform 0.2s",
                                }}>
                                    ▼
                                </span>
                            </div>

                            {/* Drop indicator */}
                            {isOver && (
                                <motion.div
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    style={{
                                        textAlign: "center", padding: "6px 0", marginBottom: 8,
                                        fontSize: 11, fontWeight: 600, color: col.color,
                                        borderRadius: 6,
                                        background: `${col.color}10`,
                                        border: `1px dashed ${col.color}44`,
                                    }}
                                >
                                    ↓ Drop here
                                </motion.div>
                            )}

                            {/* Task cards */}
                            <AnimatePresence mode="popLayout">
                                {!isCollapsed && colTasks.map((task, i) => renderCard(task, i))}
                            </AnimatePresence>

                            {/* Empty state */}
                            {!isCollapsed && colTasks.length === 0 && !isOver && (
                                <div style={{
                                    flex: 1, minHeight: 120,
                                    display: "flex", flexDirection: "column",
                                    alignItems: "center", justifyContent: "center",
                                    opacity: 0.35, fontSize: 12,
                                    color: isDark ? "#64748b" : "#94a3b8",
                                }}>
                                    <span style={{ fontSize: 24, marginBottom: 4 }}>📭</span>
                                    No tasks
                                </div>
                            )}

                            {/* Collapsed indicator */}
                            {isCollapsed && (
                                <div style={{
                                    textAlign: "center", padding: "12px 0",
                                    fontSize: 11, color: isDark ? "#64748b" : "#94a3b8",
                                }}>
                                    {colTasks.length} task{colTasks.length !== 1 ? "s" : ""} hidden
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { Checkbox, Input, Progress, Popconfirm, Tooltip, message, Spin, Empty } from "antd";
import { DeleteOutlined, PlusOutlined, UserOutlined } from "@ant-design/icons";
import { motion, AnimatePresence } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const GET_SUBTASKS = `
  query($tenantId: String!, $projectId: String) {
    pmTasks(tenantId: $tenantId, projectId: $projectId) {
      id title status priority type estimatedHours loggedHours parentTaskId
      assignee { firstName lastName }
    }
  }
`;

const CREATE_TASK = `
  mutation($tenantId: String!, $input: CreatePmTaskInput!) {
    createPmTask(tenantId: $tenantId, input: $input) { id title status }
  }
`;

const UPDATE_TASK = `
  mutation($id: ID!, $input: UpdatePmTaskInput!) {
    updatePmTask(id: $id, input: $input) { id status }
  }
`;

const DELETE_TASK = `
  mutation($id: ID!) {
    deletePmTask(id: $id)
  }
`;

const PRIORITY_COLORS: Record<string, string> = {
    critical: '#ef4444',
    high: '#f59e0b',
    medium: '#3b82f6',
    low: '#6b7280',
};

interface SubtasksListProps {
    parentTaskId: string;
    projectId: string;
    onUpdate?: () => void;
}

export default function SubtasksList({ parentTaskId, projectId, onUpdate }: SubtasksListProps) {
    const [messageApi, contextHolder] = message.useMessage();
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const [loading, setLoading] = useState(true);
    const [tasks, setTasks] = useState<any[]>([]);
    const [newTitle, setNewTitle] = useState("");
    const [adding, setAdding] = useState(false);
    const inputRef = useRef<any>(null);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(GET_SUBTASKS, { tenantId: DEFAULT_TENANT_ID, projectId });
            setTasks(data.pmTasks || []);
        } catch (err: any) { console.error("PM Error", err); } finally {
            setLoading(false);
        }
    }, [projectId]);

    useEffect(() => { loadData(); }, [loadData]);

    const subtasks = useMemo(() => tasks.filter(t => t.parentTaskId === parentTaskId), [tasks, parentTaskId]);
    const doneCount = subtasks.filter(t => t.status === 'done').length;
    const total = subtasks.length;
    const pct = total > 0 ? Math.round((doneCount / total) * 100) : 0;
    const progressColor = total === 0 ? '#d1d5db' : doneCount === total ? '#10b981' : '#3b82f6';

    const handleToggle = async (task: any) => {
        const newStatus = task.status === 'done' ? 'todo' : 'done';
        try {
            await gql(UPDATE_TASK, { id: task.id, input: { status: newStatus } });
            loadData();
            onUpdate?.();
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error('Failed to update subtask');
        }
    };

    const handleAdd = async () => {
        const title = newTitle.trim();
        if (!title) return;
        setAdding(true);
        try {
            await gql(CREATE_TASK, {
                tenantId: DEFAULT_TENANT_ID,
                input: { title, status: 'todo', projectId, parentTaskId, type: 'task', priority: 'medium' },
            });
            setNewTitle("");
            loadData();
            onUpdate?.();
            setTimeout(() => inputRef.current?.focus(), 100);
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error('Failed to add subtask');
        } finally {
            setAdding(false);
        }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(DELETE_TASK, { id });
            messageApi.success('Subtask deleted');
            loadData();
            onUpdate?.();
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error('Failed to delete subtask');
        }
    };

    const containerStyle: React.CSSProperties = {
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.08)',
        borderRadius: 10,
        padding: 12,
        background: isDark ? 'rgba(15, 15, 23, 0.5)' : 'rgba(255,255,255,0.6)',
    };

    if (loading) {
        return (
            <div style={{ ...containerStyle, textAlign: 'center', padding: 24 }}>
                <Spin size="small" />
            </div>
        );
    }

    return (
        <div style={containerStyle}>
            {contextHolder}

            {/* Progress Header */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: total > 0 ? 10 : 0 }}>
                <span style={{ fontSize: 12, fontWeight: 600, color: isDark ? '#cbd5e1' : '#374151', whiteSpace: 'nowrap' }}>
                    {doneCount} / {total} subtasks complete
                </span>
                <Progress
                    percent={pct}
                    size="small"
                    showInfo={false}
                    strokeColor={progressColor}
                    trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                    style={{ flex: 1, margin: 0 }}
                />
            </div>

            {/* Subtask Rows */}
            {total === 0 && (
                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No subtasks yet" style={{ margin: '4px 0' }} />
            )}
            <AnimatePresence initial={false}>
                {subtasks.map(task => {
                    const isDone = task.status === 'done';
                    const prioColor = PRIORITY_COLORS[task.priority] || '#6b7280';
                    const initials = task.assignee
                        ? `${(task.assignee.firstName || '')[0] || ''}${(task.assignee.lastName || '')[0] || ''}`.toUpperCase()
                        : null;

                    return (
                        <motion.div
                            key={task.id}
                            layout
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 28 }}
                            exit={{ opacity: 0, height: 0 }}
                            transition={{ duration: 0.2 }}
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                height: 28,
                                gap: 8,
                                padding: '0 4px',
                                borderRadius: 6,
                                cursor: 'default',
                                transition: 'background 0.15s',
                            }}
                            whileHover={{ backgroundColor: isDark ? 'rgba(139,92,246,0.08)' : 'rgba(0,0,0,0.03)' }}
                        >
                            <Checkbox
                                checked={isDone}
                                onChange={() => handleToggle(task)}
                                style={{ marginRight: 0 }}
                            />
                            <span style={{
                                flex: 1,
                                fontSize: 13,
                                textDecoration: isDone ? 'line-through' : 'none',
                                color: isDone ? (isDark ? '#64748b' : '#9ca3af') : (isDark ? '#e2e8f0' : '#1f2937'),
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap',
                            }}>
                                {task.title}
                            </span>

                            {/* Priority dot */}
                            <Tooltip title={task.priority} placement="top">
                                <span style={{
                                    width: 7, height: 7, borderRadius: '50%',
                                    background: prioColor, flexShrink: 0,
                                }} />
                            </Tooltip>

                            {/* Assignee */}
                            {initials ? (
                                <Tooltip title={`${task.assignee.firstName} ${task.assignee.lastName}`}>
                                    <span style={{
                                        width: 20, height: 20, borderRadius: '50%',
                                        background: `${themeColor}22`, color: themeColor,
                                        fontSize: 9, fontWeight: 700, flexShrink: 0,
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    }}>
                                        {initials}
                                    </span>
                                </Tooltip>
                            ) : (
                                <UserOutlined style={{ fontSize: 11, color: isDark ? '#475569' : '#d1d5db', flexShrink: 0 }} />
                            )}

                            {/* Delete */}
                            <Popconfirm
                                title="Delete this subtask?"
                                onConfirm={() => handleDelete(task.id)}
                                okText="Yes"
                                cancelText="No"
                            >
                                <DeleteOutlined style={{
                                    fontSize: 11, color: isDark ? '#64748b' : '#9ca3af',
                                    cursor: 'pointer', flexShrink: 0,
                                    transition: 'color 0.15s',
                                }}
                                    onMouseEnter={(e) => (e.currentTarget.style.color = '#ef4444')}
                                    onMouseLeave={(e) => (e.currentTarget.style.color = isDark ? '#64748b' : '#9ca3af')}
                                />
                            </Popconfirm>
                        </motion.div>
                    );
                })}
            </AnimatePresence>

            {/* Add Subtask Input */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 8 }}>
                <PlusOutlined style={{ fontSize: 11, color: isDark ? '#64748b' : '#9ca3af' }} />
                <Input
                    ref={inputRef}
                    size="small"
                    variant="borderless"
                    placeholder="Add subtask..."
                    value={newTitle}
                    onChange={e => setNewTitle(e.target.value)}
                    onPressEnter={handleAdd}
                    disabled={adding}
                    style={{
                        flex: 1, fontSize: 13, padding: '2px 4px',
                        background: 'transparent',
                        color: isDark ? '#e2e8f0' : '#1f2937',
                    }}
                />
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Input, Button, Avatar, Segmented, Empty, Typography, Popconfirm, message, Space, Tag, Tooltip } from "antd";
import {
    SendOutlined, DeleteOutlined, MessageOutlined,
    HistoryOutlined, UserOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);

const { Text } = Typography;

const GET_ACTIVITIES = `
  query($projectId: String!) {
    pmActivities(projectId: $projectId)
  }
`;

const CREATE_ACTIVITY = `
  mutation($tenantId: String!, $input: JSON!) {
    createPmActivity(tenantId: $tenantId, input: $input)
  }
`;

const DELETE_ACTIVITY = `
  mutation($id: ID!) {
    deletePmActivity(id: $id)
  }
`;

// ── Helpers ──

const hashColor = (name: string): string => {
    let hash = 0;
    for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
    const colors = ['#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#ec4899', '#06b6d4', '#6366f1'];
    return colors[Math.abs(hash) % colors.length];
};

const getInitials = (name: string): string => {
    const parts = name.trim().split(/\s+/);
    return parts.length >= 2
        ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
        : (name.slice(0, 2)).toUpperCase();
};

const renderRichText = (text: string, isDark: boolean): React.ReactNode[] => {
    // Replace patterns in order: code, bold, italic, @mentions
    const regex = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\*[^*]+\*)|(@\w+)/g;
    const parts: React.ReactNode[] = [];
    let lastIndex = 0;
    let match: RegExpExecArray | null;

    while ((match = regex.exec(text)) !== null) {
        if (match.index > lastIndex) parts.push(text.slice(lastIndex, match.index));
        const m = match[0];
        if (m.startsWith('`')) {
            parts.push(
                <code key={match.index} style={{
                    background: isDark ? 'rgba(139,92,246,0.15)' : 'rgba(0,0,0,0.06)',
                    padding: '1px 5px', borderRadius: 4, fontFamily: 'monospace', fontSize: 12,
                }}>{m.slice(1, -1)}</code>
            );
        } else if (m.startsWith('**')) {
            parts.push(<strong key={match.index}>{m.slice(2, -2)}</strong>);
        } else if (m.startsWith('*')) {
            parts.push(<em key={match.index}>{m.slice(1, -1)}</em>);
        } else if (m.startsWith('@')) {
            parts.push(
                <span key={match.index} style={{
                    background: isDark ? 'rgba(99,102,241,0.25)' : 'rgba(99,102,241,0.12)',
                    color: '#6366f1', padding: '1px 5px', borderRadius: 4, fontWeight: 600, fontSize: 12,
                }}>{m}</span>
            );
        }
        lastIndex = match.index + m.length;
    }
    if (lastIndex < text.length) parts.push(text.slice(lastIndex));
    return parts;
};

const ACTIVITY_ICONS: Record<string, React.ReactNode> = {
    comment: <MessageOutlined style={{ color: '#6366f1' }} />,
    status_change: <HistoryOutlined style={{ color: '#3b82f6' }} />,
    priority_change: <HistoryOutlined style={{ color: '#f59e0b' }} />,
    assignment: <UserOutlined style={{ color: '#10b981' }} />,
};

// ── Component ──

interface TaskCommentsPanelProps {
    taskId: string;
    projectId: string;
}

export default function TaskCommentsPanel({ taskId, projectId }: TaskCommentsPanelProps) {
    const [activities, setActivities] = useState<any[]>([]);
    const [commentText, setCommentText] = useState("");
    const [submitting, setSubmitting] = useState(false);
    const [tab, setTab] = useState<string>("Comments");
    const [messageApi, contextHolder] = message.useMessage();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const MAX_CHARS = 500;

    const loadActivities = useCallback(async () => {
        try {
            const data = await gql(GET_ACTIVITIES, { projectId });
            const raw = data.pmActivities;
            const parsed: any[] = (typeof raw === 'string' ? JSON.parse(raw) : Array.isArray(raw) ? raw : [])
                .filter((a: any) => a.taskId === taskId);
            setActivities(parsed);
        } catch (err: any) { console.error("PM Error", err); }
    }, [projectId, taskId]);

    useEffect(() => { loadActivities(); }, [loadActivities]);

    const comments = useMemo(() =>
        activities.filter(a => a.type === 'comment').sort((a, b) =>
            dayjs(b.createdAt).unix() - dayjs(a.createdAt).unix()
        ), [activities]);

    const allActivities = useMemo(() =>
        [...activities].sort((a, b) =>
            dayjs(b.createdAt).unix() - dayjs(a.createdAt).unix()
        ), [activities]);

    const handleSubmit = async () => {
        const trimmed = commentText.trim();
        if (!trimmed) return;
        setSubmitting(true);
        try {
            await gql(CREATE_ACTIVITY, {
                tenantId: DEFAULT_TENANT_ID,
                input: {
                    type: 'comment',
                    taskId,
                    projectId,
                    author: 'System User',
                    text: trimmed,
                    createdAt: new Date().toISOString(),
                },
            });
            setCommentText("");
            messageApi.success("Comment added");
            loadActivities();
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error("Failed to add comment");
        } finally {
            setSubmitting(false);
        }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(DELETE_ACTIVITY, { id });
            messageApi.success("Comment deleted");
            loadActivities();
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error("Failed to delete comment");
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
            e.preventDefault();
            handleSubmit();
        }
    };

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(12px)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    // ── Render a single comment ──
    const renderComment = (item: any, idx: number) => (
        <motion.div
            key={item.id || idx}
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ delay: idx * 0.04 }}
            style={{
                display: 'flex', gap: 12, padding: '12px 0',
                borderBottom: isDark ? '1px solid rgba(255,255,255,0.05)' : '1px solid rgba(0,0,0,0.05)',
            }}
        >
            <Avatar
                size={34}
                style={{ background: hashColor(item.author || ''), flexShrink: 0, fontSize: 13, fontWeight: 700 }}
            >
                {getInitials(item.author || 'U')}
            </Avatar>
            <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
                    <Space size={8}>
                        <Text strong style={{ fontSize: 13 }}>{item.author}</Text>
                        <Tooltip title={dayjs(item.createdAt).format('YYYY-MM-DD HH:mm')}>
                            <Text type="secondary" style={{ fontSize: 11 }}>{dayjs(item.createdAt).fromNow()}</Text>
                        </Tooltip>
                    </Space>
                    <Popconfirm title="Delete this comment?" onConfirm={() => handleDelete(item.id)} okText="Delete" okType="danger">
                        <Button
                            type="text" size="small" icon={<DeleteOutlined />}
                            style={{ opacity: 0.4, fontSize: 11 }}
                            className="comment-delete-btn"
                        />
                    </Popconfirm>
                </div>
                <div style={{ fontSize: 13, lineHeight: 1.6, wordBreak: 'break-word' }}>
                    {renderRichText(item.text || '', isDark)}
                </div>
            </div>
        </motion.div>
    );

    // ── Render a single activity entry ──
    const renderActivity = (item: any, idx: number) => (
        <motion.div
            key={item.id || idx}
            initial={{ opacity: 0, x: -8 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: idx * 0.03 }}
            style={{
                display: 'flex', gap: 10, padding: '10px 0', alignItems: 'flex-start',
                borderBottom: isDark ? '1px solid rgba(255,255,255,0.04)' : '1px solid rgba(0,0,0,0.04)',
            }}
        >
            <div style={{
                width: 28, height: 28, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                background: isDark ? 'rgba(99,102,241,0.12)' : 'rgba(99,102,241,0.08)', flexShrink: 0, fontSize: 13,
            }}>
                {ACTIVITY_ICONS[item.type] || <HistoryOutlined style={{ color: '#94a3b8' }} />}
            </div>
            <div style={{ flex: 1 }}>
                <Text style={{ fontSize: 12 }}>
                    {item.type === 'comment'
                        ? <><Text strong>{item.author}</Text> commented</>
                        : item.description || <><Text strong>{item.author || 'System'}</Text> {item.type?.replace(/_/g, ' ')}</>
                    }
                </Text>
                <div>
                    <Tooltip title={dayjs(item.createdAt).format('YYYY-MM-DD HH:mm')}>
                        <Text type="secondary" style={{ fontSize: 10 }}>{dayjs(item.createdAt).fromNow()}</Text>
                    </Tooltip>
                </div>
            </div>
        </motion.div>
    );

    return (
        <div style={{ ...glassCard, padding: 16, display: 'flex', flexDirection: 'column' }}>
            {contextHolder}

            {/* ── Tab Selector ── */}
            <div style={{ marginBottom: 14 }}>
                <Segmented
                    value={tab}
                    onChange={(v) => setTab(v as string)}
                    options={[
                        { label: <Space size={4}><MessageOutlined />Comments<Tag style={{ margin: 0, fontSize: 10 }}>{comments.length}</Tag></Space>, value: 'Comments' },
                        { label: <Space size={4}><HistoryOutlined />Activity<Tag style={{ margin: 0, fontSize: 10 }}>{allActivities.length}</Tag></Space>, value: 'Activity' },
                    ]}
                    block
                    style={{ background: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.03)' }}
                />
            </div>

            {/* ── Scrollable Content ── */}
            <div style={{
                maxHeight: 400, overflowY: 'auto', flex: 1, paddingRight: 4,
                scrollbarWidth: 'thin',
            }}>
                <AnimatePresence mode="wait">
                    {tab === 'Comments' ? (
                        <motion.div key="comments" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                            {comments.length === 0 ? (
                                <Empty
                                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                                    description={<Text type="secondary" style={{ fontSize: 12 }}>No comments yet. Start the conversation!</Text>}
                                    style={{ padding: '40px 0' }}
                                />
                            ) : (
                                comments.map((item, idx) => renderComment(item, idx))
                            )}
                        </motion.div>
                    ) : (
                        <motion.div key="activity" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                            {allActivities.length === 0 ? (
                                <Empty
                                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                                    description={<Text type="secondary" style={{ fontSize: 12 }}>No activity recorded yet.</Text>}
                                    style={{ padding: '40px 0' }}
                                />
                            ) : (
                                allActivities.map((item, idx) => renderActivity(item, idx))
                            )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* ── Add Comment Input ── */}
            <div style={{
                marginTop: 14, paddingTop: 12,
                borderTop: isDark ? '1px solid rgba(255,255,255,0.06)' : '1px solid rgba(0,0,0,0.06)',
            }}>
                <Input.TextArea
                    value={commentText}
                    onChange={(e) => setCommentText(e.target.value.slice(0, MAX_CHARS))}
                    onKeyDown={handleKeyDown}
                    placeholder="Add a comment... Use @name to mention someone"
                    autoSize={{ minRows: 2, maxRows: 5 }}
                    style={{
                        background: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.02)',
                        borderColor: isDark ? 'rgba(139,92,246,0.2)' : 'rgba(0,0,0,0.08)',
                        borderRadius: 8, fontSize: 13,
                    }}
                />
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 8 }}>
                    <Text type="secondary" style={{ fontSize: 11 }}>
                        {commentText.length}/{MAX_CHARS} · Ctrl+Enter to send
                    </Text>
                    <Button
                        type="primary"
                        icon={<SendOutlined />}
                        size="small"
                        loading={submitting}
                        disabled={!commentText.trim()}
                        onClick={handleSubmit}
                        style={{
                            background: commentText.trim()
                                ? 'linear-gradient(135deg, #8b5cf6, #6366f1)'
                                : undefined,
                            border: 'none', borderRadius: 6,
                        }}
                    >
                        Send
                    </Button>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Select, Button, Tag, Popconfirm, Tooltip, message, Spin, Empty } from "antd";
import { PlusOutlined, DeleteOutlined, ArrowLeftOutlined, ArrowRightOutlined, WarningOutlined, LinkOutlined } from "@ant-design/icons";
import { motion, AnimatePresence } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { usePreferencesStore } from "@/store/usePreferencesStore";

const GET_DEPENDENCIES = `
  query($projectId: String!) {
    pmTaskDependencies(projectId: $projectId) {
      id projectId taskId dependsOnTaskId type lag createdAt
    }
  }
`;
const GET_TASKS = `
  query($tenantId: String!, $projectId: String) {
    pmTasks(tenantId: $tenantId, projectId: $projectId) {
      id title status priority type
    }
  }
`;
const CREATE_DEPENDENCY = `
  mutation($tenantId: String!, $input: CreatePmTaskDependencyInput!) {
    createPmTaskDependency(tenantId: $tenantId, input: $input) { id }
  }
`;
const DELETE_DEPENDENCY = `
  mutation($id: ID!) {
    deletePmTaskDependency(id: $id)
  }
`;

const PRIORITY_COLORS: Record<string, string> = { critical: '#ef4444', high: '#f59e0b', medium: '#3b82f6', low: '#6b7280' };
const STATUS_COLORS: Record<string, string> = { done: '#10b981', in_progress: '#3b82f6', todo: '#6b7280', review: '#f59e0b' };
const DEP_TYPE_LABELS: Record<string, string> = {
    finish_to_start: 'FS', start_to_start: 'SS', finish_to_finish: 'FF', start_to_finish: 'SF',
};

interface TaskDependenciesProps {
    taskId: string;
    projectId: string;
    onUpdate?: () => void;
}

export default function TaskDependencies({ taskId, projectId, onUpdate }: TaskDependenciesProps) {
    const [messageApi, contextHolder] = message.useMessage();
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const [loading, setLoading] = useState(true);
    const [deps, setDeps] = useState<any[]>([]);
    const [tasks, setTasks] = useState<any[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [formType, setFormType] = useState('finish_to_start');
    const [formTarget, setFormTarget] = useState<string | undefined>();
    const [formDir, setFormDir] = useState<'depends_on' | 'blocks'>('depends_on');
    const [adding, setAdding] = useState(false);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [dData, tData] = await Promise.all([
                gql(GET_DEPENDENCIES, { projectId }),
                gql(GET_TASKS, { tenantId: DEFAULT_TENANT_ID, projectId }),
            ]);
            setDeps(dData.pmTaskDependencies || []);
            setTasks(tData.pmTasks || []);
        } catch (err: any) { console.error("PM Error", err); } finally { setLoading(false); }
    }, [projectId]);

    useEffect(() => { loadData(); }, [loadData]);

    const taskMap = useMemo(() => new Map(tasks.map(t => [t.id, t])), [tasks]);
    const blockedBy = useMemo(() => deps.filter(d => d.taskId === taskId), [deps, taskId]);
    const blocks = useMemo(() => deps.filter(d => d.dependsOnTaskId === taskId), [deps, taskId]);
    const linkedIds = useMemo(() => new Set([
        ...blockedBy.map(d => d.dependsOnTaskId), ...blocks.map(d => d.taskId), taskId,
    ]), [blockedBy, blocks, taskId]);

    // Cycle detection via DFS
    const wouldCreateCycle = useCallback((fromId: string, toId: string) => {
        const adj = new Map<string, string[]>();
        deps.forEach(d => { adj.set(d.taskId, [...(adj.get(d.taskId) || []), d.dependsOnTaskId]); });
        adj.set(fromId, [...(adj.get(fromId) || []), toId]);
        const visited = new Set<string>(), stack = new Set<string>();
        const dfs = (node: string): boolean => {
            if (stack.has(node)) return true;
            if (visited.has(node)) return false;
            visited.add(node); stack.add(node);
            for (const n of adj.get(node) || []) { if (dfs(n)) return true; }
            stack.delete(node);
            return false;
        };
        return dfs(fromId);
    }, [deps]);

    const handleAdd = async () => {
        if (!formTarget) return;
        const src = formDir === 'depends_on' ? taskId : formTarget;
        const dep = formDir === 'depends_on' ? formTarget : taskId;
        if (wouldCreateCycle(src, dep)) { messageApi.warning('This dependency would create a circular chain!'); return; }
        setAdding(true);
        try {
            await gql(CREATE_DEPENDENCY, {
                tenantId: DEFAULT_TENANT_ID,
                input: { projectId, taskId: src, dependsOnTaskId: dep, type: formType },
            });
            setShowForm(false); setFormTarget(undefined);
            loadData(); onUpdate?.();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error('Failed to add dependency'); } finally { setAdding(false); }
    };

    const handleDelete = async (id: string) => {
        try {
            await gql(DELETE_DEPENDENCY, { id });
            messageApi.success('Dependency removed');
            loadData(); onUpdate?.();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error('Failed to remove dependency'); }
    };

    const glass: React.CSSProperties = {
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.08)',
        borderRadius: 10, padding: 12,
        background: isDark ? 'rgba(15,15,23,0.5)' : 'rgba(255,255,255,0.6)',
    };

    const renderItem = (dep: any, dir: 'in' | 'out') => {
        const tid = dir === 'in' ? dep.dependsOnTaskId : dep.taskId;
        const t = taskMap.get(tid);
        if (!t) return null;
        const arrowColor = t.status === 'done' ? '#10b981' : '#ef4444';
        return (
            <motion.div key={dep.id} initial={{ opacity: 0, x: dir === 'in' ? -12 : 12 }} animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, height: 0 }} transition={{ duration: 0.2 }}
                style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '4px 6px', borderRadius: 6,
                    background: isDark ? 'rgba(139,92,246,0.06)' : 'rgba(0,0,0,0.02)', marginBottom: 4 }}>
                {dir === 'in'
                    ? <ArrowLeftOutlined style={{ fontSize: 10, color: arrowColor }} />
                    : <ArrowRightOutlined style={{ fontSize: 10, color: arrowColor }} />}
                <span style={{ flex: 1, fontSize: 12, color: isDark ? '#e2e8f0' : '#1f2937', overflow: 'hidden',
                    textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{t.title}</span>
                <Tooltip title={t.priority}><span style={{ width: 6, height: 6, borderRadius: '50%',
                    background: PRIORITY_COLORS[t.priority] || '#6b7280', flexShrink: 0 }} /></Tooltip>
                <Tag color={STATUS_COLORS[t.status]} style={{ margin: 0, fontSize: 10, lineHeight: '16px', padding: '0 4px',
                    borderRadius: 4, border: 'none' }}>{t.status?.replace('_', ' ')}</Tag>
                <Tag style={{ margin: 0, fontSize: 9, lineHeight: '14px', padding: '0 3px', borderRadius: 3,
                    background: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)', border: 'none',
                    color: isDark ? '#94a3b8' : '#6b7280' }}>{DEP_TYPE_LABELS[dep.type] || dep.type}</Tag>
                <Popconfirm title="Remove dependency?" onConfirm={() => handleDelete(dep.id)} okText="Yes" cancelText="No">
                    <DeleteOutlined style={{ fontSize: 10, color: isDark ? '#64748b' : '#9ca3af', cursor: 'pointer', flexShrink: 0 }}
                        onMouseEnter={e => (e.currentTarget.style.color = '#ef4444')}
                        onMouseLeave={e => (e.currentTarget.style.color = isDark ? '#64748b' : '#9ca3af')} />
                </Popconfirm>
            </motion.div>
        );
    };

    // Mini-graph: current task center, blockedBy left, blocks right
    const miniGraph = () => {
        const leftNodes = blockedBy.map(d => taskMap.get(d.dependsOnTaskId)).filter(Boolean).slice(0, 4);
        const rightNodes = blocks.map(d => taskMap.get(d.taskId)).filter(Boolean).slice(0, 4);
        if (!leftNodes.length && !rightNodes.length) return null;
        const nodeStyle = (active?: boolean): React.CSSProperties => ({
            padding: '3px 8px', borderRadius: 6, fontSize: 10, maxWidth: 90, overflow: 'hidden',
            textOverflow: 'ellipsis', whiteSpace: 'nowrap', textAlign: 'center',
            background: active ? `${themeColor}22` : isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)',
            border: active ? `1px solid ${themeColor}` : isDark ? '1px solid rgba(255,255,255,0.08)' : '1px solid rgba(0,0,0,0.06)',
            color: active ? themeColor : isDark ? '#cbd5e1' : '#374151', fontWeight: active ? 600 : 400,
        });
        const arrow = (color: string) => (
            <svg width="24" height="12" viewBox="0 0 24 12" style={{ flexShrink: 0 }}>
                <line x1="0" y1="6" x2="18" y2="6" stroke={color} strokeWidth="1.5" />
                <polygon points="18,2 24,6 18,10" fill={color} />
            </svg>
        );
        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                padding: '8px 4px', marginTop: 8, borderTop: isDark ? '1px solid rgba(255,255,255,0.06)' : '1px solid rgba(0,0,0,0.06)',
            }}>
                {leftNodes.length > 0 && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 4, alignItems: 'flex-end' }}>
                        {leftNodes.map(n => <span key={n.id} style={nodeStyle()}>{n.title}</span>)}
                    </div>
                )}
                {leftNodes.length > 0 && arrow(isDark ? '#64748b' : '#9ca3af')}
                <span style={nodeStyle(true)}>{taskMap.get(taskId)?.title || 'Current'}</span>
                {rightNodes.length > 0 && arrow(isDark ? '#64748b' : '#9ca3af')}
                {rightNodes.length > 0 && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 4, alignItems: 'flex-start' }}>
                        {rightNodes.map(n => <span key={n.id} style={nodeStyle()}>{n.title}</span>)}
                    </div>
                )}
            </motion.div>
        );
    };

    if (loading) {
        return <div style={{ ...glass, textAlign: 'center', padding: 24 }}><Spin size="small" /></div>;
    }

    const availableTasks = tasks.filter(t => !linkedIds.has(t.id));
    const sectionLabel = (text: string) => (
        <span style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.5,
            color: isDark ? '#94a3b8' : '#6b7280', marginBottom: 4, display: 'block' }}>{text}</span>
    );

    return (
        <div style={glass}>
            {contextHolder}
            {/* Header */}
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
                <span style={{ fontSize: 12, fontWeight: 600, color: isDark ? '#cbd5e1' : '#374151', display: 'flex', alignItems: 'center', gap: 6 }}>
                    <LinkOutlined style={{ color: themeColor }} /> Dependencies
                    <Tag style={{ margin: 0, fontSize: 10, lineHeight: '16px', padding: '0 4px', borderRadius: 10,
                        background: `${themeColor}18`, color: themeColor, border: 'none' }}>{blockedBy.length + blocks.length}</Tag>
                </span>
                <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                    <Button size="small" type="text" icon={<PlusOutlined />}
                        onClick={() => setShowForm(!showForm)}
                        style={{ fontSize: 11, color: themeColor, borderRadius: 6 }}>Add</Button>
                </motion.div>
            </div>

            {/* Add Form */}
            <AnimatePresence>
                {showForm && (
                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }} transition={{ duration: 0.2 }}
                        style={{ marginBottom: 10, padding: 8, borderRadius: 8,
                            background: isDark ? 'rgba(139,92,246,0.06)' : 'rgba(0,0,0,0.02)',
                            display: 'flex', flexDirection: 'column', gap: 6, overflow: 'hidden' }}>
                        <Select size="small" value={formDir} onChange={v => setFormDir(v)} style={{ width: '100%' }}
                            options={[{ value: 'depends_on', label: 'This task depends on...' }, { value: 'blocks', label: 'This task blocks...' }]} />
                        <Select size="small" value={formType} onChange={v => setFormType(v)} style={{ width: '100%' }}
                            options={Object.entries(DEP_TYPE_LABELS).map(([k, v]) => ({ value: k, label: `${v} — ${k.replace(/_/g, ' ')}` }))} />
                        <Select size="small" showSearch value={formTarget} onChange={v => setFormTarget(v)}
                            filterOption={(input, opt) => (opt?.label as string ?? '').toLowerCase().includes(input.toLowerCase())}
                            placeholder="Select target task" style={{ width: '100%' }}
                            options={availableTasks.map(t => ({ value: t.id, label: t.title }))} />
                        <Button size="small" type="primary" loading={adding} onClick={handleAdd} disabled={!formTarget}
                            style={{ background: `linear-gradient(135deg, ${themeColor}, #6366f1)`, border: 'none', borderRadius: 6, fontSize: 11, alignSelf: 'flex-end' }}>
                            Add Dependency
                        </Button>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Blocked By */}
            {blockedBy.length > 0 && (
                <div style={{ marginBottom: 8 }}>
                    {sectionLabel(`← Blocked By (${blockedBy.length})`)}
                    <AnimatePresence initial={false}>{blockedBy.map(d => renderItem(d, 'in'))}</AnimatePresence>
                </div>
            )}

            {/* Blocks */}
            {blocks.length > 0 && (
                <div style={{ marginBottom: 4 }}>
                    {sectionLabel(`→ Blocks (${blocks.length})`)}
                    <AnimatePresence initial={false}>{blocks.map(d => renderItem(d, 'out'))}</AnimatePresence>
                </div>
            )}

            {/* Empty state */}
            {blockedBy.length === 0 && blocks.length === 0 && !showForm && (
                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No dependencies" style={{ margin: '4px 0' }} />
            )}

            {/* Mini Graph */}
            {miniGraph()}
        </div>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { Select, Button, Modal, Input, message, Typography, Empty } from "antd";
import { PlayCircleOutlined, PauseCircleOutlined, StopOutlined, ClockCircleOutlined, CheckCircleOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import dayjs from "dayjs";

const { Text } = Typography;

const LOG_TIME = `
  mutation LogTime($tenantId: String!, $input: CreatePmTimeLogInput!) {
    logPmTime(tenantId: $tenantId, input: $input) { id hours logDate description }
  }
`;
const GET_TIME_LOGS = `
  query($taskId: String!) {
    pmTimeLogs(taskId: $taskId) { id taskId userId hours logDate description createdAt }
  }
`;
const GET_MY_TASKS = `
  query($tenantId: String!) {
    pmTasks(tenantId: $tenantId) { id title projectId status assignee { firstName lastName } }
  }
`;
const HR_CLOCK_IN = `
  mutation($tenantId: String!, $employeeId: String!) {
    hrClockIn(tenantId: $tenantId, employeeId: $employeeId) { id clockIn }
  }
`;
const HR_CLOCK_OUT = `
  mutation($id: ID!) { hrClockOut(id: $id) { id clockOut workHours } }
`;

const LS = { taskId: "pm_timer_taskId", startTime: "pm_timer_startTime", elapsed: "pm_timer_elapsed", running: "pm_timer_running" };

const fmt = (s: number) => [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map(v => String(v).padStart(2, "0")).join(":");

const PULSE_CSS = `@keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.4;transform:scale(.8)} }`;
const btnMotion = { whileHover: { scale: 1.06 }, whileTap: { scale: 0.94 } };

interface TimeTrackerProps {
    taskId?: string;
    projectId?: string;
    compact?: boolean;
    onTimeLogged?: (hours: number) => void;
}

export default function TimeTracker({ taskId, projectId, compact, onTimeLogged }: TimeTrackerProps) {
    const [messageApi, ctx] = message.useMessage();
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === "dark";

    const [tasks, setTasks] = useState<any[]>([]);
    const [selTask, setSelTask] = useState<string | undefined>(taskId);
    const [elapsed, setElapsed] = useState(0);
    const [running, setRunning] = useState(false);
    const [timeLogs, setTimeLogs] = useState<any[]>([]);
    const [showModal, setShowModal] = useState(false);
    const [desc, setDesc] = useState("");
    const [logging, setLogging] = useState(false);
    const ivRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const hrRef = useRef<string | null>(null);

    // Load tasks
    const loadTasks = useCallback(async () => {
        try {
            const data = await gql(GET_MY_TASKS, { tenantId: DEFAULT_TENANT_ID });
            setTasks(data.pmTasks || []);
        } catch (err: any) { console.error("PM Error", err); }
    }, []);

    useEffect(() => { loadTasks(); }, [loadTasks]);

    // Load time logs for selected task
    const loadLogs = useCallback(async () => {
        if (!selTask) return;
        try {
            const data = await gql(GET_TIME_LOGS, { taskId: selTask });
            setTimeLogs(data.pmTimeLogs || []);
        } catch (err: any) { console.error("PM Error", err); }
    }, [selTask]);

    useEffect(() => { loadLogs(); }, [loadLogs]);

    // Restore from localStorage
    useEffect(() => {
        try {
            const wasRunning = localStorage.getItem(LS.running) === "true";
            const saved = parseInt(localStorage.getItem(LS.elapsed) || "0", 10);
            const savedTask = localStorage.getItem(LS.taskId);
            const start = localStorage.getItem(LS.startTime);
            if (savedTask && !taskId) setSelTask(savedTask);
            if (wasRunning && start) {
                setElapsed(saved + Math.floor((Date.now() - parseInt(start, 10)) / 1000));
                setRunning(true);
            } else setElapsed(saved);
        } catch (err: any) { console.error("PM Error", err); }
    }, []); // eslint-disable-line react-hooks/exhaustive-deps

    // Timer tick
    useEffect(() => {
        if (running) {
            localStorage.setItem(LS.startTime, String(Date.now()));
            localStorage.setItem(LS.running, "true");
            ivRef.current = setInterval(() => {
                setElapsed(prev => {
                    const next = prev + 1;
                    localStorage.setItem(LS.elapsed, String(next));
                    return next;
                });
            }, 1000);
        } else {
            if (ivRef.current) clearInterval(ivRef.current);
            localStorage.setItem(LS.running, "false");
        }
        return () => { if (ivRef.current) clearInterval(ivRef.current); };
    }, [running]);

    useEffect(() => { if (selTask) localStorage.setItem(LS.taskId, selTask); }, [selTask]);

    const filteredTasks = useMemo(() => projectId ? tasks.filter(t => t.projectId === projectId) : tasks, [tasks, projectId]);
    const selTaskObj = useMemo(() => tasks.find(t => t.id === selTask), [tasks, selTask]);
    const todayStr = dayjs().format("YYYY-MM-DD");
    const todayLogs = useMemo(() => timeLogs.filter(l => dayjs(l.logDate || l.createdAt).format("YYYY-MM-DD") === todayStr), [timeLogs, todayStr]);
    const todayTotal = useMemo(() => todayLogs.reduce((s, l) => s + (l.hours || 0), 0), [todayLogs]);

    // Actions
    const handleStart = async () => {
        if (!selTask) {
            messageApi.warning("Select a task first");
            return;
        }
        // HR clock-in attempt (silent fail if no HR module)
        try {
            const d = await gql(HR_CLOCK_IN, { tenantId: DEFAULT_TENANT_ID, employeeId: "current" });
            hrRef.current = d.hrClockIn?.id || null;
        } catch (err: any) { console.error("PM Error", err); }
        setRunning(true);
        localStorage.setItem(LS.elapsed, String(elapsed));
    };

    const handlePause = () => setRunning(false);

    const handleStop = () => {
        setRunning(false);
        if (elapsed > 0) setShowModal(true);
    };

    const handleLog = async () => {
        const hours = Math.round((elapsed / 3600) * 100) / 100;
        setLogging(true);
        try {
            await gql(LOG_TIME, { tenantId: DEFAULT_TENANT_ID, input: { taskId: selTask, hours, logDate: dayjs().format("YYYY-MM-DD"), description: desc.trim() || undefined } });
            if (hrRef.current) { try { await gql(HR_CLOCK_OUT, { id: hrRef.current }); } catch (err: any) { console.error("PM Error", err); } hrRef.current = null; }
            setElapsed(0); setDesc(""); setShowModal(false);
            Object.values(LS).forEach(k => localStorage.removeItem(k));
            messageApi.success(`Logged ${hours}h successfully`);
            onTimeLogged?.(hours);
            loadLogs();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error("Failed to log time"); } finally { setLogging(false); }
    };

    // Shared styles
    const glass: React.CSSProperties = {
        background: isDark ? "rgba(15,15,23,0.7)" : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(12px)",
        border: isDark ? "1px solid rgba(139,92,246,0.15)" : "1px solid rgba(0,0,0,0.06)",
        borderRadius: 12, padding: compact ? "6px 12px" : 20,
    };
    const timerStyle: React.CSSProperties = {
        fontFamily: "monospace", fontSize: compact ? 16 : 32, fontWeight: 700,
        color: isDark ? "#e2e8f0" : "#1f2937", letterSpacing: compact ? 1 : 2,
    };
    const dot = (size: number): React.CSSProperties => ({
        width: size, height: size, borderRadius: "50%", background: "#22c55e",
        animation: "pulse-dot 1.5s ease-in-out infinite", flexShrink: 0,
    });
    const inputStyle: React.CSSProperties = {
        background: isDark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.02)",
        borderColor: isDark ? "rgba(139,92,246,0.2)" : "rgba(0,0,0,0.08)", borderRadius: 8, fontSize: 13,
    };

    // Log modal content
    const modalBody = () => {
        const hours = Math.round((elapsed / 3600) * 100) / 100;
        return (
            <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div style={{ textAlign: "center" }}>
                    <Text style={{ fontSize: 28, fontFamily: "monospace", fontWeight: 700 }}>{fmt(elapsed)}</Text>
                    <div><Text type="secondary">{hours} hours</Text></div>
                </div>
                <Input.TextArea value={desc} onChange={e => setDesc(e.target.value)} placeholder="What did you work on? (optional)"
                    autoSize={{ minRows: 2, maxRows: 4 }} style={inputStyle} />
                <motion.div {...btnMotion}>
                    <Button type="primary" block loading={logging} onClick={handleLog} icon={<CheckCircleOutlined />}
                        style={{ background: `linear-gradient(135deg, ${themeColor}, #6366f1)`, border: "none", borderRadius: 8, height: 40 }}>
                        Log Time
                    </Button>
                </motion.div>
            </div>
        );
    };

    const logModal = <Modal open={showModal} onCancel={() => setShowModal(false)} title="Log Time" footer={null} destroyOnClose>{modalBody()}</Modal>;

    // Compact mode
    if (compact) {
        return (
            <div style={{ ...glass, display: "flex", alignItems: "center", gap: 10, height: 40 }}>
                {ctx}<style>{PULSE_CSS}</style>
                {running && <span style={dot(8)} />}
                <span style={timerStyle}>{fmt(elapsed)}</span>
                {selTaskObj && <Text ellipsis style={{ fontSize: 12, maxWidth: 140, color: isDark ? "#94a3b8" : "#6b7280" }}>{selTaskObj.title}</Text>}
                <div style={{ marginLeft: "auto", display: "flex", gap: 4 }}>
                    {!running ? (
                        <motion.div {...btnMotion}><Button size="small" type="primary" icon={<PlayCircleOutlined />} onClick={handleStart}
                            style={{ background: "#22c55e", border: "none", borderRadius: 6 }} /></motion.div>
                    ) : (
                        <motion.div {...btnMotion}><Button size="small" danger icon={<StopOutlined />} onClick={handleStop}
                            style={{ borderRadius: 6 }} /></motion.div>
                    )}
                </div>
                {logModal}
            </div>
        );
    }

    // Full mode
    return (
        <div style={glass}>
            {ctx}<style>{PULSE_CSS}</style>

            {/* Timer */}
            <div style={{ textAlign: "center", marginBottom: 20 }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10 }}>
                    {running && <span style={dot(10)} />}
                    <span style={timerStyle}>{fmt(elapsed)}</span>
                </div>
            </div>

            {/* Task Selector */}
            <div style={{ marginBottom: 16 }}>
                <Text style={{ fontSize: 12, color: isDark ? "#94a3b8" : "#6b7280", marginBottom: 6, display: "block" }}>
                    <ClockCircleOutlined /> Task
                </Text>
                <Select value={selTask} onChange={setSelTask} placeholder="Select a task to track" showSearch
                    filterOption={(input, opt) => (opt?.label as string ?? "").toLowerCase().includes(input.toLowerCase())}
                    options={filteredTasks.map(t => ({ value: t.id, label: `${t.title}${t.projectId ? ` · ${t.projectId.slice(0, 6)}` : ""}` }))}
                    style={{ width: "100%" }} disabled={running} />
            </div>

            {/* Controls */}
            <div style={{ display: "flex", gap: 8, justifyContent: "center", marginBottom: 20 }}>
                {!running ? (
                    <motion.div {...btnMotion} style={{ flex: 1 }}>
                        <Button type="primary" block icon={<PlayCircleOutlined />} onClick={handleStart} size="large"
                            style={{ background: "#22c55e", border: "none", borderRadius: 8, fontWeight: 600 }}>Start</Button>
                    </motion.div>
                ) : (<>
                    <motion.div {...btnMotion} style={{ flex: 1 }}>
                        <Button block icon={<PauseCircleOutlined />} onClick={handlePause} size="large"
                            style={{ background: "#f59e0b", color: "#fff", border: "none", borderRadius: 8, fontWeight: 600 }}>Pause</Button>
                    </motion.div>
                    <motion.div {...btnMotion} style={{ flex: 1 }}>
                        <Button danger block icon={<StopOutlined />} onClick={handleStop} size="large"
                            style={{ borderRadius: 8, fontWeight: 600 }}>Stop</Button>
                    </motion.div>
                </>)}
            </div>

            {/* Today's Summary */}
            <div style={{ borderTop: isDark ? "1px solid rgba(255,255,255,0.06)" : "1px solid rgba(0,0,0,0.06)", paddingTop: 14 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                    <Text strong style={{ fontSize: 13, color: isDark ? "#cbd5e1" : "#374151" }}>Today&apos;s Logged Time</Text>
                    <Text style={{ fontSize: 13, fontWeight: 700, color: themeColor }}>{todayTotal.toFixed(1)}h</Text>
                </div>
                {todayLogs.length === 0 ? (
                    <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No time logged today" style={{ margin: "4px 0", padding: "8px 0" }} />
                ) : todayLogs.map((log, i) => (
                    <motion.div key={log.id || i} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                        style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "6px 8px", borderRadius: 6, marginBottom: 4,
                            background: isDark ? "rgba(139,92,246,0.06)" : "rgba(0,0,0,0.02)" }}>
                        <Text style={{ fontSize: 12, color: isDark ? "#cbd5e1" : "#374151" }}>{log.description || "No description"}</Text>
                        <Text style={{ fontSize: 12, fontWeight: 600, fontFamily: "monospace", color: themeColor }}>{log.hours}h</Text>
                    </motion.div>
                ))}
            </div>
            {logModal}
        </div>
    );
}

