const BUILDING = {
  floors: 5,
  width: 12,
  depth: 8,
  floorHeight: 3.2,
  columnRadius: 0.25,
  wallThickness: 0.3,
  windowWidth: 1.8,
  windowHeight: 1.6,
  windowsPerSide: 4,
  windowsPerEnd: 2,
};

