      {/* Glass walls */}
      <mesh position={[0, 5.2, 0]}>
        <boxGeometry args={[4, 2.2, 3]} />
        <meshStandardMaterial color="#88BBDD" transparent opacity={0.12} side={THREE.DoubleSide} />
      </mesh>
      {/* Frame */}
      {[[-2, 5.2, 0], [2, 5.2, 0]].map((p, i) => (
        <mesh key={`cf-${i}`} position={p as [number, number, number]}>
