          <meshStandardMaterial color="#555" metalness={0.6} roughness={0.3} />
        </mesh>
      ))}
      {/* Monitor desk */}
      <mesh position={[0, 4.5, 0]}>
        <boxGeometry args={[2.5, 0.06, 1]} />
