      </mesh>
      {/* Monitors */}
      {[-0.8, 0, 0.8].map((x, i) => (
        <mesh key={`mon-${i}`} position={[x, 4.9, -0.2]} rotation={[0.2, 0, 0]}>
          <boxGeometry args={[0.5, 0.35, 0.02]} />
          <meshStandardMaterial color="#111" emissive="#2244FF" emissiveIntensity={0.2} />
        </mesh>
      ))}
      {/* Stairs */}
      {Array.from({ length: 8 }).map((_, i) => (
