                    </motion.div>
                </Col>

                {/* Sprint Health */}
                <Col xs={24} lg={10}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>
                        <Card
                            title={<Space><WarningOutlined style={{ color: themeColor }} /> Sprint Health</Space>}
                            size="small"
                            style={glassCard}
                        >
                            <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                                {/* Scope Change */}
                                <Card size="small" style={{ ...glassCard, borderLeft: `3px solid ${scopeChange > 20 ? "#ef4444" : scopeChange > 10 ? "#f59e0b" : "#10b981"}` }}>
                                    <Row align="middle" justify="space-between">
                                        <Col>
                                            <Text style={{ fontSize: 12 }}>Scope Change</Text>
                                            <div>
                                                <Text strong style={{ fontSize: 20, color: scopeChange > 20 ? "#ef4444" : scopeChange > 10 ? "#f59e0b" : "#10b981" }}>
                                                    {scopeChange}%
                                                </Text>
                                            </div>
                                        </Col>
                                        <Col>
                                            <Progress
                                                type="circle" percent={Math.min(100, scopeChange)} size={52}
                                                strokeColor={scopeChange > 20 ? "#ef4444" : scopeChange > 10 ? "#f59e0b" : "#10b981"}
                                                trailColor={isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)"}
                                                format={() => <ExclamationCircleOutlined style={{ fontSize: 14, color: scopeChange > 20 ? "#ef4444" : "#10b981" }} />}
                                            />
                                        </Col>
                                    </Row>
                                </Card>

                                {/* Avg Time to Complete */}
                                <Card size="small" style={{ ...glassCard, borderLeft: `3px solid #3b82f6` }}>
                                    <Row align="middle" justify="space-between">
                                        <Col>
                                            <Text style={{ fontSize: 12 }}>Avg Time to Complete</Text>
                                            <div>
                                                <Text strong style={{ fontSize: 20, color: "#3b82f6" }}>
                                                    {avgTimeToComplete}
                                                </Text>
                                                <Text type="secondary" style={{ fontSize: 12 }}> days</Text>
                                            </div>
                                        </Col>
                                        <Col>
                                            <ClockCircleOutlined style={{ fontSize: 28, color: "#3b82f6", opacity: 0.6 }} />
                                        </Col>
                                    </Row>
                                </Card>

                                {/* Blocked Tasks */}
                                <Card size="small" style={{ ...glassCard, borderLeft: `3px solid ${blockedTasks > 0 ? "#ef4444" : "#10b981"}` }}>
                                    <Row align="middle" justify="space-between">
                                        <Col>
                                            <Text style={{ fontSize: 12 }}>Blocked Tasks</Text>
                                            <div>
                                                <Text strong style={{ fontSize: 20, color: blockedTasks > 0 ? "#ef4444" : "#10b981" }}>
                                                    {blockedTasks}
                                                </Text>
                                                {blockedTasks > 0 && (
                                                    <Tag color="red" style={{ marginLeft: 8, fontSize: 10 }}>NEEDS ATTENTION</Tag>
                                                )}
                                            </div>
                                        </Col>
                                        <Col>
                                            <ExclamationCircleOutlined style={{ fontSize: 28, color: blockedTasks > 0 ? "#ef4444" : "#10b981", opacity: 0.6 }} />
                                        </Col>
                                    </Row>
                                </Card>

                                {/* Carryover Estimate */}
                                <Card size="small" style={{ ...glassCard, borderLeft: `3px solid ${carryoverEstimate > 0 ? "#f59e0b" : "#10b981"}` }}>
                                    <Row align="middle" justify="space-between">
                                        <Col>
                                            <Text style={{ fontSize: 12 }}>Carryover Estimate</Text>
                                            <div>
                                                <Text strong style={{ fontSize: 20, color: carryoverEstimate > 0 ? "#f59e0b" : "#10b981" }}>
                                                    {carryoverEstimate}
                                                </Text>
                                                <Text type="secondary" style={{ fontSize: 12 }}> tasks</Text>
                                            </div>
                                        </Col>
                                        <Col>
                                            <WarningOutlined style={{ fontSize: 28, color: carryoverEstimate > 0 ? "#f59e0b" : "#10b981", opacity: 0.6 }} />
                                        </Col>
                                    </Row>
                                </Card>
                            </div>
                        </Card>
                    </motion.div>
                </Col>
            </Row>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useMemo } from "react";
import { ProTable, ProColumns, ModalForm, ProFormText, ProFormTextArea, ProForm, ProCard, ProFormSelect, ProFormDigit } from "@ant-design/pro-components";
import { Button, message, Tag, Popconfirm, Space, Row, Col, Tooltip, theme } from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, RobotOutlined, TeamOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";

// ─── GraphQL ───────────────────────────────────────────────
const GET_STAKEHOLDERS = `query($projectId: String!) { pmStakeholders(projectId: $projectId) { id name title organization role contactInfo interestLevel influenceLevel supportLevel engagementStrategy communicationNeeds notes } }`;
const CREATE_STAKEHOLDER = `mutation($tenantId: String!, $input: CreatePmStakeholderInput!) { createPmStakeholder(tenantId: $tenantId, input: $input) { id } }`;
const UPDATE_STAKEHOLDER = `mutation($id: ID!, $input: UpdatePmStakeholderInput!) { updatePmStakeholder(id: $id, input: $input) { id } }`;
const DELETE_STAKEHOLDER = `mutation($id: ID!) { deletePmStakeholder(id: $id) }`;

const AI_STAKEHOLDERS = `query($projectId: String!) { generateStakeholderAnalysis(projectId: $projectId) }`;

// ─── Power/Interest Grid Quadrant ──────────────────────────

function PowerInterestGrid({ stakeholders, isDark }: { stakeholders: any[]; isDark: boolean }) {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    const gridSize = 400;
    const padding = 50;
    const plotSize = gridSize - padding * 2;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Clear
        ctx.clearRect(0, 0, gridSize, gridSize);

        // Quadrant backgrounds
        const quadrants = [
            { x: padding, y: padding, color: 'rgba(82,196,26,0.08)', label: 'Keep Satisfied' },           // High Power, Low Interest
            { x: padding + plotSize / 2, y: padding, color: 'rgba(245,34,45,0.08)', label: 'Manage Closely' },     // High Power, High Interest
            { x: padding, y: padding + plotSize / 2, color: 'rgba(217,217,217,0.08)', label: 'Monitor' },      // Low Power, Low Interest
            { x: padding + plotSize / 2, y: padding + plotSize / 2, color: 'rgba(24,144,255,0.08)', label: 'Keep Informed' },   // Low Power, High Interest
        ];

        quadrants.forEach((q, i) => {
            ctx.fillStyle = q.color;
            ctx.fillRect(q.x, q.y, plotSize / 2, plotSize / 2);
            ctx.fillStyle = isDark ? '#64748b' : '#999';
            ctx.font = '11px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(q.label, q.x + plotSize / 4, q.y + 15);
        });

        // Grid lines
        ctx.strokeStyle = isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(padding + plotSize / 2, padding);
        ctx.lineTo(padding + plotSize / 2, padding + plotSize);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(padding, padding + plotSize / 2);
        ctx.lineTo(padding + plotSize, padding + plotSize / 2);
        ctx.stroke();
        ctx.setLineDash([]);

        // Border
        ctx.strokeStyle = isDark ? 'rgba(255,255,255,0.15)' : '#d9d9d9';
        ctx.strokeRect(padding, padding, plotSize, plotSize);

        // Axis labels
        ctx.fillStyle = isDark ? '#94a3b8' : '#555';
        ctx.font = 'bold 12px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Interest Level →', gridSize / 2, gridSize - 5);
        ctx.save();
        ctx.translate(12, gridSize / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillText('Power / Influence →', 0, 0);
        ctx.restore();

        // Plot stakeholders
        const colors = ['#1890ff', '#f5222d', '#52c41a', '#722ed1', '#fa8c16', '#13c2c2', '#eb2f96', '#faad14'];
        stakeholders.forEach((s, i) => {
            const interest = (s.interestLevel || 3);
            const power = (s.influenceLevel || 3);
            const x = padding + ((interest - 1) / 4) * plotSize;
            const y = padding + plotSize - ((power - 1) / 4) * plotSize;

            ctx.fillStyle = colors[i % colors.length];
            ctx.beginPath();
            ctx.arc(x, y, 8, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = isDark ? '#e2e8f0' : '#333';
            ctx.font = '10px sans-serif';
            ctx.textAlign = 'left';
            const displayName = s.name.length > 12 ? s.name.substring(0, 12) + '…' : s.name;
            ctx.fillText(displayName, x + 11, y + 4);
        });

    }, [stakeholders, gridSize, plotSize, isDark]);

    return (
        <ProCard title={<Space><TeamOutlined /> Power / Interest Grid</Space>} bordered>
            <div style={{ display: 'flex', justifyContent: 'center' }}>
                <canvas ref={canvasRef} width={gridSize} height={gridSize} style={{ border: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : '#f0f0f0'}`, borderRadius: 8 }} />
            </div>
        </ProCard>
    );
}

export default function StakeholderTab({ projectId }: { projectId: string }) {
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const [messageApi, contextHolder] = message.useMessage();
    const [stakeholders, setStakeholders] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [modalOpen, setModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const [aiLoading, setAiLoading] = useState(false);

    const loadData = React.useCallback(async () => {
        setLoading(true);
        try {
            const d = await gql(GET_STAKEHOLDERS, { projectId });
            setStakeholders(d.pmStakeholders || []);
        } catch (err: any) { console.error("PM Error", err);  messageApi.error("Failed to load stakeholders."); }
        finally { setLoading(false); }
    }, [projectId, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (values: any) => {
        try {
            if (editing) {
                await gql(UPDATE_STAKEHOLDER, { id: editing.id, input: values });
                messageApi.success("Stakeholder updated.");
            } else {
                await gql(CREATE_STAKEHOLDER, { tenantId: DEFAULT_TENANT_ID, input: { ...values, projectId } });
                messageApi.success("Stakeholder added.");
            }
            setModalOpen(false); loadData();
            return true;
        } catch (err: any) { messageApi.error(`Failed: ${err.message}`); return false; }
    };

    const handleDelete = async (id: string) => {
        try { await gql(DELETE_STAKEHOLDER, { id }); messageApi.success("Stakeholder deleted."); loadData(); }
        catch (err: any) { messageApi.error(`Delete failed: ${err.message}`); }
    };

    const handleAi = async () => {
        setAiLoading(true);
        try {
            const d = await gql(AI_STAKEHOLDERS, { projectId });
            const raw = d.generateStakeholderAnalysis;
            // AI returns { stakeholders: [...] } or a JSON string
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            const items = Array.isArray(parsed) ? parsed : (parsed?.stakeholders || parsed?.items || []);
            for (const item of items) {
                await gql(CREATE_STAKEHOLDER, {
                    tenantId: DEFAULT_TENANT_ID,
                    input: {
                        projectId, name: item.name || item.title,
                        role: item.role, organization: item.organization,
                        interestLevel: item.interestLevel || 3,
                        influenceLevel: item.influenceLevel || 3,
                        engagementStrategy: item.engagementStrategy,
                    }
                });
            }
            messageApi.success(`Added ${items.length} stakeholders from AI analysis.`);
            loadData();
        } catch (err: any) { messageApi.error(`AI failed: ${err.message}`); }
        finally { setAiLoading(false); }
    };

    const supportColors: Record<string, string> = { champion: 'green', supporter: 'blue', neutral: 'default', resistant: 'orange', blocker: 'red' };

    const columns: ProColumns<any>[] = [
        { title: "Name", dataIndex: "name", width: "15%" },
        { title: "Title", dataIndex: "title" },
        { title: "Organization", dataIndex: "organization" },
        { title: "Role", dataIndex: "role" },
        { title: "Interest", dataIndex: "interestLevel", render: (_, r) => <Tag>{r.interestLevel || '-'}/5</Tag> },
        { title: "Influence", dataIndex: "influenceLevel", render: (_, r) => <Tag>{r.influenceLevel || '-'}/5</Tag> },
        {
            title: "Support", dataIndex: "supportLevel",
            render: (_, r) => r.supportLevel ? <Tag color={supportColors[r.supportLevel]}>{r.supportLevel.toUpperCase()}</Tag> : '-'
        },
        { title: "Strategy", dataIndex: "engagementStrategy", ellipsis: true },
        {
            title: "Actions", valueType: "option",
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />} onClick={() => { setEditing(record); setModalOpen(true); }} />,
                <Popconfirm key="del" title="Delete?" onConfirm={() => handleDelete(record.id)}>
                    <Button type="text" danger icon={<DeleteOutlined />} />
                </Popconfirm>
            ]
        }
    ];

    return (
        <div>
            {contextHolder}

            {/* Power / Interest Grid */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                <Col span={24}>
                    <PowerInterestGrid stakeholders={stakeholders} isDark={isDark} />
                </Col>
            </Row>

            {/* Stakeholder Register Table */}
            <ProTable
                headerTitle="Stakeholder Register"
                rowKey="id"
                dataSource={stakeholders}
                loading={loading}
                columns={columns}
                search={false}
                toolBarRender={() => [
                    <Button key="ai" type="dashed" icon={<RobotOutlined />} loading={aiLoading} onClick={handleAi}>
                        AI Stakeholder Analysis
                    </Button>,
                    <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => { setEditing(null); setModalOpen(true); }}>
                        Add Stakeholder
                    </Button>
                ]}
            />

            <ModalForm
                title={editing ? "Edit Stakeholder" : "Add Stakeholder"}
                open={modalOpen}
                onOpenChange={setModalOpen}
                onFinish={handleSave}
                initialValues={editing || { interestLevel: 3, influenceLevel: 3, supportLevel: 'neutral' }}
                modalProps={{ destroyOnClose: true }}
                width={700}
            >
                <ProForm.Group>
                    <ProFormText name="name" label="Full Name" rules={[{ required: true }]} width="md" />
                    <ProFormText name="title" label="Job Title" width="md" />
                </ProForm.Group>
                <ProForm.Group>
                    <ProFormText name="organization" label="Organization" width="md" />
                    <ProFormText name="role" label="Project Role" width="md" placeholder="e.g. Sponsor, User, Advisor" />
                </ProForm.Group>
                <ProFormText name="contactInfo" label="Contact Info" placeholder="Email or phone" />
                <ProForm.Group>
                    <ProFormDigit name="interestLevel" label="Interest Level (1-5)" min={1} max={5} width="sm" />
                    <ProFormDigit name="influenceLevel" label="Influence Level (1-5)" min={1} max={5} width="sm" />
                    <ProFormSelect name="supportLevel" label="Support Level" width="sm" options={[
                        { value: 'champion', label: 'Champion' }, { value: 'supporter', label: 'Supporter' },
                        { value: 'neutral', label: 'Neutral' }, { value: 'resistant', label: 'Resistant' },
                        { value: 'blocker', label: 'Blocker' },
                    ]} />
                </ProForm.Group>
                <ProFormTextArea name="engagementStrategy" label="Engagement Strategy" />
                <ProFormTextArea name="communicationNeeds" label="Communication Needs" />
                <ProFormTextArea name="notes" label="Notes" />
            </ModalForm>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { ProTable, ProColumns, ModalForm, ProFormText, ProFormSelect, ProFormTextArea, ProForm, ProFormDigit } from "@ant-design/pro-components";
import { Button, message, Space, Tag, Popconfirm, Row, Col, Card, Statistic, Progress, Alert } from "antd";
import { GlobalOutlined, PlusOutlined, DeleteOutlined, EditOutlined, RobotOutlined, ThunderboltOutlined, HeartOutlined, TeamOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer, Tooltip as RTooltip, Legend } from 'recharts';

const GET_METRICS = `
  query GetSustainabilityMetrics($projectId: String!) {
    pmSustainabilityMetrics(projectId: $projectId)
  }
`;

const CREATE_METRIC = `
  mutation CreateSustainability(
    $tenantId: String!, $projectId: String!, $dimension: String!, $metricName: String!,
    $description: String, $unit: String, $targetValue: Float, $actualValue: Float,
    $baselineValue: Float, $measurementPeriod: String, $dataSource: String, $status: String, $notes: String
  ) {
    createPmSustainabilityMetric(
      tenantId: $tenantId, projectId: $projectId, dimension: $dimension, metricName: $metricName,
      description: $description, unit: $unit, targetValue: $targetValue, actualValue: $actualValue,
      baselineValue: $baselineValue, measurementPeriod: $measurementPeriod, dataSource: $dataSource,
      status: $status, notes: $notes
    )
  }
`;

const UPDATE_METRIC = `
  mutation UpdateSustainability(
    $id: ID!, $dimension: String, $metricName: String, $description: String, $unit: String,
    $targetValue: Float, $actualValue: Float, $baselineValue: Float,
    $measurementPeriod: String, $dataSource: String, $status: String, $notes: String
  ) {
    updatePmSustainabilityMetric(
      id: $id, dimension: $dimension, metricName: $metricName, description: $description, unit: $unit,
      targetValue: $targetValue, actualValue: $actualValue, baselineValue: $baselineValue,
      measurementPeriod: $measurementPeriod, dataSource: $dataSource, status: $status, notes: $notes
    )
  }
`;

const DELETE_METRIC = `
  mutation DeleteSustainability($id: ID!) {
    deletePmSustainabilityMetric(id: $id)
  }
`;

const AI_SUSTAINABILITY = `
  query GenerateSustainability($projectId: String!) {
    generateSustainabilityImpact(projectId: $projectId)
  }
`;

const DIMENSION_OPTIONS = [
    { label: '🌍 Environmental', value: 'environmental', color: '#10b981', icon: <ThunderboltOutlined /> },
    { label: '👥 Social', value: 'social', color: '#3b82f6', icon: <TeamOutlined /> },
    { label: '💰 Economic', value: 'economic', color: '#f59e0b', icon: <HeartOutlined /> },
    { label: '🏢 Governance', value: 'governance', color: '#8b5cf6', icon: <GlobalOutlined /> },
];

const STATUS_OPTIONS = [
    { label: 'Baseline Set', value: 'baseline' },
    { label: 'Tracking', value: 'tracking' },
    { label: 'On Target', value: 'on_target' },
    { label: 'Below Target', value: 'below_target' },
    { label: 'Exceeded', value: 'exceeded' },
];

export default function SustainabilityTab({ projectId }: { projectId: string }) {
    const [messageApi, contextHolder] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [aiLoading, setAiLoading] = useState(false);
    const [metrics, setMetrics] = useState<any[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(GET_METRICS, { projectId });
            setMetrics(data.pmSustainabilityMetrics || []);
        } catch (err: any) { console.error("PM Error", err); } finally {
            setLoading(false);
        }
    }, [projectId]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleDelete = async (id: string) => {
        try {
            await gql(DELETE_METRIC, { id });
            messageApi.success("Metric deleted.");
            loadData();
        } catch (error: any) {
            messageApi.error(`Failed: ${error.message}`);
        }
    };

    const handleFinish = async (values: any) => {
        try {
            if (editing) {
                await gql(UPDATE_METRIC, {
                    id: editing.id,
                    dimension: values.dimension,
                    metricName: values.metricName || values.metric_name,
                    description: values.description,
                    unit: values.unit,
                    targetValue: values.targetValue ?? values.target_value,
                    actualValue: values.actualValue ?? values.actual_value,
                    baselineValue: values.baselineValue ?? values.baseline_value,
                    measurementPeriod: values.measurementPeriod || values.measurement_period,
                    dataSource: values.dataSource || values.data_source,
                    status: values.status,
                    notes: values.notes,
                });
                messageApi.success("Metric updated.");
            } else {
                await gql(CREATE_METRIC, {
                    tenantId: DEFAULT_TENANT_ID,
                    projectId,
                    dimension: values.dimension,
                    metricName: values.metricName,
                    description: values.description,
                    unit: values.unit,
                    targetValue: values.targetValue,
                    actualValue: values.actualValue,
                    baselineValue: values.baselineValue,
                    measurementPeriod: values.measurementPeriod,
                    dataSource: values.dataSource,
                    status: values.status || 'baseline',
                    notes: values.notes,
                });
                messageApi.success("Metric added.");
            }
            setIsModalOpen(false);
            loadData();
            return true;
        } catch (error: any) {
            messageApi.error(`Failed: ${error.message}`);
            return false;
        }
    };

    const handleAiGenerate = async () => {
        setAiLoading(true);
        try {
            const data = await gql(AI_SUSTAINABILITY, { projectId });
            const raw = data.generateSustainabilityImpact;
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            const recs = Array.isArray(parsed) ? parsed : (parsed?.metrics || parsed?.items || []);
            for (const r of recs) {
                await gql(CREATE_METRIC, {
                    tenantId: DEFAULT_TENANT_ID,
                    projectId,
                    dimension: r.dimension || 'environmental',
                    metricName: r.metricName || r.metric_name || 'Unnamed Metric',
                    description: r.description || '',
                    unit: r.unit || '',
                    targetValue: r.targetValue || r.target_value || 0,
                    actualValue: r.actualValue || r.actual_value || 0,
                    baselineValue: r.baselineValue || r.baseline_value || 0,
                    measurementPeriod: r.measurementPeriod || r.measurement_period || '',
                    dataSource: r.dataSource || r.data_source || 'AI Generated',
                    status: 'baseline',
                    notes: r.notes || '',
                });
            }
            messageApi.success(`Added ${recs.length} metrics.`);
            loadData();
        } catch (error: any) {
            messageApi.error(`AI generation failed: ${error.message}`);
        } finally {
            setAiLoading(false);
        }
    };

    // Group metrics by dimension
    const dimensionCounts = DIMENSION_OPTIONS.map(d => ({
        ...d,
        count: metrics.filter(m => m.dimension === d.value).length,
        onTarget: metrics.filter(m => m.dimension === d.value && (m.status === 'on_target' || m.status === 'exceeded')).length,
    }));

    const chartData = useMemo(() =>
        metrics.filter((m: any) => (m.targetValue || m.target_value) || (m.actualValue || m.actual_value)).map((m: any) => ({
            name: (m.metricName || m.metric_name || '').slice(0, 15),
            Target: Number(m.targetValue || m.target_value || 0),
            Actual: Number(m.actualValue || m.actual_value || 0),
        })),
    [metrics]);

    const getProgress = (actual: number, target: number) => {
        if (!target || target === 0) return 0;
        return Math.min(Math.round((actual / target) * 100), 100);
    };

    const columns: ProColumns<any>[] = [
        {
            title: "Dimension", dataIndex: "dimension", width: 130,
            render: (_, r) => {
                const d = DIMENSION_OPTIONS.find(opt => opt.value === r.dimension);
                return <Tag color={d?.color || 'default'}>{d?.label || r.dimension}</Tag>;
            }
        },
        {
            title: "Metric", dataIndex: "metric_name",
            render: (_, r) => <strong>{r.metric_name || r.metricName}</strong>,
        },
        { title: "Unit", dataIndex: "unit", width: 80 },
        {
            title: "Progress", width: 150,
            render: (_, r) => {
                const actual = r.actual_value || r.actualValue || 0;
                const target = r.target_value || r.targetValue || 0;
                const pct = getProgress(actual, target);
                return (
                    <div>
                        <Progress percent={pct} size="small"
                            strokeColor={pct >= 80 ? '#10b981' : pct >= 50 ? '#f59e0b' : '#ef4444'}
                        />
                        <span style={{ fontSize: 10, color: isDark ? '#94a3b8' : '#888' }}>
                            {actual} / {target} {r.unit || ''}
                        </span>
                    </div>
                );
            }
        },
        {
            title: "Status", dataIndex: "status", width: 110,
            render: (_, r) => {
                const color = r.status === 'exceeded' ? 'green' : r.status === 'on_target' ? 'cyan'
                    : r.status === 'below_target' ? 'red' : r.status === 'tracking' ? 'blue' : 'default';
                return <Tag color={color}>{(r.status || 'baseline').replace('_', ' ').toUpperCase()}</Tag>;
            }
        },
        {
            title: "Actions", valueType: "option", width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />}
                    onClick={() => {
                        setEditing({
                            ...record,
                            metricName: record.metric_name || record.metricName,
                            targetValue: record.target_value || record.targetValue,
                            actualValue: record.actual_value || record.actualValue,
                            baselineValue: record.baseline_value || record.baselineValue,
                            measurementPeriod: record.measurement_period || record.measurementPeriod,
                            dataSource: record.data_source || record.dataSource,
                        });
                        setIsModalOpen(true);
                    }}
                />,
                <Popconfirm key="del" title="Delete metric?" onConfirm={() => handleDelete(record.id)}>
                    <Button type="text" danger icon={<DeleteOutlined />} />
                </Popconfirm>
            ]
        }
    ];

    return (
        <div>
            {contextHolder}
            <Alert
                message="Sustainability & ESG Tracking"
                description="PMBOK 8 emphasizes sustainability as a core project management concern. Track environmental, social, economic, and governance metrics to ensure project outcomes align with organizational sustainability goals."
                type="info"
                showIcon
                icon={<GlobalOutlined />}
                style={{ marginBottom: 16, borderRadius: 10 }}
            />

            {/* Dimension Summary */}
            <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                {dimensionCounts.map(d => (
                    <Col key={d.value} xs={12} sm={6}>
                        <Card size="small" style={{
                            background: isDark ? `${d.color}12` : `${d.color}08`,
                            border: `1px solid ${d.color}33`, borderRadius: 10,
                        }}>
                            <Statistic
                                title={<span style={{ fontSize: 11 }}>{d.label}</span>}
                                value={d.count}
                                suffix={<span style={{ fontSize: 11, color: '#10b981' }}>({d.onTarget} on target)</span>}
                            />
                        </Card>
                    </Col>
                ))}
            </Row>

            {chartData.length > 0 && (
                <Card size="small" title={<Space><span style={{ fontWeight: 600 }}>Target vs Actual Performance</span></Space>} style={{ marginBottom: 16, borderRadius: 10, background: isDark ? 'rgba(15,15,23,0.7)' : undefined, border: isDark ? '1px solid rgba(255,255,255,0.06)' : undefined }}>
                    <div style={{ height: 220 }}>
                        <ResponsiveContainer>
                            <BarChart data={chartData} margin={{ left: 10, right: 10, bottom: 20 }}>
                                <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)'} />
                                <XAxis dataKey="name" tick={{ fontSize: 9, fill: isDark ? '#94a3b8' : '#64748b' }} interval={0} angle={-20} textAnchor="end" />
                                <YAxis tick={{ fontSize: 10, fill: isDark ? '#94a3b8' : '#64748b' }} />
                                <RTooltip contentStyle={{ background: isDark ? '#1e1e2e' : '#fff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`, borderRadius: 8, fontSize: 12 }} />
                                <Legend />
                                <Bar dataKey="Target" fill="#6366f1" radius={[4, 4, 0, 0]} />
                                <Bar dataKey="Actual" fill="#10b981" radius={[4, 4, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </Card>
            )}

            <ProTable
                headerTitle={
                    <Space>
                        <GlobalOutlined style={{ color: 'var(--theme-color, #8b5cf6)' }} />
                        <span>Sustainability Metrics</span>
                    </Space>
                }
                rowKey="id"
                dataSource={metrics}
                loading={loading}
                columns={columns}
                search={false}
                toolBarRender={() => [
                    <Button key="ai" type="dashed" icon={<RobotOutlined />}
                        loading={aiLoading} onClick={handleAiGenerate}>
                        AI Generate Metrics
                    </Button>,
                    <Button key="add" type="primary" icon={<PlusOutlined />}
                        onClick={() => { setEditing(null); setIsModalOpen(true); }}
                        style={{ background: 'linear-gradient(135deg, var(--theme-color, #8b5cf6), var(--theme-secondary, #6366f1))', border: 'none', borderRadius: 8 }}
                    >
                        Add Metric
                    </Button>
                ]}
            />

            <ModalForm
                title={editing ? "Edit Metric" : "Add Sustainability Metric"}
                open={isModalOpen}
                onOpenChange={setIsModalOpen}
                onFinish={handleFinish}
                initialValues={editing || { status: 'baseline', dimension: 'environmental' }}
                modalProps={{ destroyOnClose: true }}
            >
                <ProForm.Group>
                    <ProFormSelect name="dimension" label="Dimension" width="sm" options={DIMENSION_OPTIONS} rules={[{ required: true }]} />
                    <ProFormText name="metricName" label="Metric Name" width="md" rules={[{ required: true }]} />
                </ProForm.Group>
                <ProFormTextArea name="description" label="Description" />
                <ProForm.Group>
                    <ProFormText name="unit" label="Unit" width="xs" placeholder="e.g., tCO2e" />
                    <ProFormDigit name="baselineValue" label="Baseline Value" width="sm" />
                    <ProFormDigit name="targetValue" label="Target Value" width="sm" />
                    <ProFormDigit name="actualValue" label="Actual Value" width="sm" />
                </ProForm.Group>
                <ProForm.Group>
                    <ProFormText name="measurementPeriod" label="Measurement Period" width="sm" placeholder="e.g., Monthly" />
                    <ProFormText name="dataSource" label="Data Source" width="sm" />
                    <ProFormSelect name="status" label="Status" width="sm" options={STATUS_OPTIONS} />
                </ProForm.Group>
                <ProFormTextArea name="notes" label="Notes" />
            </ModalForm>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { ProTable, ProColumns, ModalForm, ProFormText, ProFormSelect, ProFormTextArea, ProForm } from "@ant-design/pro-components";
import { Button, message, Space, Tag, Popconfirm, Alert, Card, Row, Col, Statistic } from "antd";
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RTooltip } from 'recharts';
import { ToolOutlined, PlusOutlined, DeleteOutlined, EditOutlined, RobotOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from 'next-themes';
import { usePreferencesStore } from '@/store/usePreferencesStore';

const GET_TAILORING = `
  query GetTailoringLog($projectId: String!) {
    pmTailoringLog(projectId: $projectId)
  }
`;

const CREATE_TAILORING = `
  mutation CreateTailoring(
    $tenantId: String!, $projectId: String!, $area: String!,
    $tailoredApproach: String!, $rationale: String!,
    $originalApproach: String, $impact: String, $decidedBy: String, $status: String
  ) {
    createPmTailoringEntry(
      tenantId: $tenantId, projectId: $projectId, area: $area,
      tailoredApproach: $tailoredApproach, rationale: $rationale,
      originalApproach: $originalApproach, impact: $impact, decidedBy: $decidedBy, status: $status
    )
  }
`;

const UPDATE_TAILORING = `
  mutation UpdateTailoring(
    $id: ID!, $area: String, $tailoredApproach: String, $rationale: String,
    $originalApproach: String, $impact: String, $decidedBy: String, $status: String
  ) {
    updatePmTailoringEntry(
      id: $id, area: $area, tailoredApproach: $tailoredApproach, rationale: $rationale,
      originalApproach: $originalApproach, impact: $impact, decidedBy: $decidedBy, status: $status
    )
  }
`;

const DELETE_TAILORING = `
  mutation DeleteTailoring($id: ID!) {
    deletePmTailoringEntry(id: $id)
  }
`;

const AI_TAILORING = `
  query GenerateTailoring($projectId: String!) {
    generateTailoringRecommendations(projectId: $projectId)
  }
`;

const AREA_OPTIONS = [
    { label: 'Processes', value: 'processes' },
    { label: 'Engagement', value: 'engagement' },
    { label: 'Tools', value: 'tools' },
    { label: 'Methods', value: 'methods' },
    { label: 'Artifacts', value: 'artifacts' },
    { label: 'Life Cycle', value: 'life_cycle' },
    { label: 'Governance', value: 'governance' },
];

const STATUS_OPTIONS = [
    { label: 'Proposed', value: 'proposed' },
    { label: 'Approved', value: 'approved' },
    { label: 'Implemented', value: 'implemented' },
    { label: 'Rejected', value: 'rejected' },
];

export default function TailoringTab({ projectId }: { projectId: string }) {
    const { resolvedTheme } = useTheme();
    const { themeColor } = usePreferencesStore();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const [messageApi, contextHolder] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [aiLoading, setAiLoading] = useState(false);
    const [entries, setEntries] = useState<any[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editing, setEditing] = useState<any>(null);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(GET_TAILORING, { projectId });
            setEntries(data.pmTailoringLog || []);
        } catch (err: any) { console.error("PM Error", err); } finally {
            setLoading(false);
        }
    }, [projectId]);

    useEffect(() => { loadData(); }, [loadData]);

    const areaDist = useMemo(() => {
        const counts: Record<string, number> = {};
        entries.forEach((e: any) => { const a = e.area || 'other'; counts[a] = (counts[a] || 0) + 1; });
        const colors: Record<string, string> = { processes: '#3b82f6', engagement: '#10b981', tools: '#f59e0b', methods: '#8b5cf6', artifacts: '#6366f1', life_cycle: '#f97316', governance: '#14b8a6' };
        return Object.entries(counts).map(([area, count]) => ({ name: area.replace('_', ' '), value: count, color: colors[area] || '#6b7280' }));
    }, [entries]);

    const statusDist = useMemo(() => {
        const counts: Record<string, number> = {};
        entries.forEach((e: any) => { const s = e.status || 'proposed'; counts[s] = (counts[s] || 0) + 1; });
        const colors: Record<string, string> = { proposed: '#f59e0b', approved: '#3b82f6', implemented: '#10b981', rejected: '#ef4444' };
        return Object.entries(counts).map(([status, count]) => ({ name: status, value: count, color: colors[status] || '#6b7280' }));
    }, [entries]);

    const handleDelete = async (id: string) => {
        try {
            await gql(DELETE_TAILORING, { id });
            messageApi.success("Entry deleted.");
            loadData();
        } catch (error: any) {
            messageApi.error(`Failed: ${error.message}`);
        }
    };

    const handleFinish = async (values: any) => {
        try {
            if (editing) {
                await gql(UPDATE_TAILORING, {
                    id: editing.id,
                    area: values.area,
                    tailoredApproach: values.tailoredApproach || values.tailored_approach,
                    rationale: values.rationale,
                    originalApproach: values.originalApproach || values.original_approach,
                    impact: values.impact,
                    decidedBy: values.decidedBy || values.decided_by,
                    status: values.status,
                });
                messageApi.success("Entry updated.");
            } else {
                await gql(CREATE_TAILORING, {
                    tenantId: DEFAULT_TENANT_ID,
                    projectId,
                    area: values.area,
                    tailoredApproach: values.tailoredApproach,
                    rationale: values.rationale,
                    originalApproach: values.originalApproach,
                    impact: values.impact,
                    decidedBy: values.decidedBy,
                    status: values.status || 'proposed',
                });
                messageApi.success("Entry added.");
            }
            setIsModalOpen(false);
            loadData();
            return true;
        } catch (error: any) {
            messageApi.error(`Failed: ${error.message}`);
            return false;
        }
    };

    const handleAiGenerate = async () => {
        setAiLoading(true);
        try {
            const data = await gql(AI_TAILORING, { projectId });
            const raw = data.generateTailoringRecommendations;
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            const recs = Array.isArray(parsed) ? parsed : (parsed?.recommendations || parsed?.items || []);
            for (const r of recs) {
                await gql(CREATE_TAILORING, {
                    tenantId: DEFAULT_TENANT_ID,
                    projectId,
                    area: r.area || 'processes',
                    tailoredApproach: r.tailoredApproach || r.tailored_approach || '',
                    rationale: r.rationale || '',
                    originalApproach: r.originalApproach || r.original_approach || '',
                    impact: r.impact || '',
                    decidedBy: 'AI',
                    status: 'proposed',
                });
            }
            messageApi.success(`Added ${recs.length} AI recommendations.`);
            loadData();
        } catch (error: any) {
            messageApi.error(`AI generation failed: ${error.message}`);
        } finally {
            setAiLoading(false);
        }
    };

    const columns: ProColumns<any>[] = [
        {
            title: "Area", dataIndex: "area", width: 120,
            render: (_, r) => <Tag color="blue">{(r.area || '').toUpperCase()}</Tag>
        },
        {
            title: "Tailored Approach", dataIndex: "tailored_approach",
            render: (_, r) => r.tailored_approach || r.tailoredApproach || '-',
        },
        {
            title: "Original Approach", dataIndex: "original_approach", width: 200,
            render: (_, r) => r.original_approach || r.originalApproach || '-',
        },
        { title: "Rationale", dataIndex: "rationale", width: 200, ellipsis: true },
        {
            title: "Decided By", dataIndex: "decided_by", width: 100,
            render: (_, r) => r.decided_by || r.decidedBy || '-',
        },
        {
            title: "Status", dataIndex: "status", width: 110,
            render: (_, r) => {
                const color = r.status === 'approved' ? 'green' : r.status === 'implemented' ? 'cyan' : r.status === 'rejected' ? 'red' : 'default';
                return <Tag color={color}>{(r.status || 'proposed').toUpperCase()}</Tag>;
            }
        },
        {
            title: "Actions", valueType: "option", width: 100,
            render: (_, record) => [
                <Button key="edit" type="text" icon={<EditOutlined />}
                    onClick={() => {
                        setEditing({
                            ...record,
                            tailoredApproach: record.tailored_approach || record.tailoredApproach,
                            originalApproach: record.original_approach || record.originalApproach,
                            decidedBy: record.decided_by || record.decidedBy,
                        });
                        setIsModalOpen(true);
                    }}
                />,
                <Popconfirm key="del" title="Delete entry?" onConfirm={() => handleDelete(record.id)}>
                    <Button type="text" danger icon={<DeleteOutlined />} />
                </Popconfirm>
            ]
        }
    ];

    return (
        <div>
            {contextHolder}
            <Alert
                message="Tailoring Log"
                description="Document how project management processes, methods, and artifacts have been tailored to fit the specific project context. PMBOK 7 emphasizes that every project is unique and tailoring is essential."
                type="info"
                showIcon
                icon={<ToolOutlined />}
                style={{ marginBottom: 16, borderRadius: 10 }}
            />

            <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                <Col xs={12} md={8}>
                    <Card size="small" style={{ borderRadius: 10, borderTop: `3px solid ${themeColor}`, background: isDark ? 'rgba(15,15,23,0.7)' : undefined }}>
                        <Statistic title={<span style={{ fontSize: 11 }}>Total Entries</span>} value={entries.length} valueStyle={{ fontSize: 20, fontWeight: 700 }} />
                    </Card>
                </Col>
                <Col xs={12} md={8}>
                    <Card size="small" style={{ borderRadius: 10, borderTop: '3px solid #10b981', background: isDark ? 'rgba(15,15,23,0.7)' : undefined }}>
                        <Statistic title={<span style={{ fontSize: 11 }}>Implemented</span>} value={entries.filter((e: any) => e.status === 'implemented').length} valueStyle={{ fontSize: 20, fontWeight: 700, color: '#10b981' }} />
                    </Card>
                </Col>
                <Col xs={12} md={8}>
                    <Card size="small" style={{ borderRadius: 10, borderTop: '3px solid #f59e0b', background: isDark ? 'rgba(15,15,23,0.7)' : undefined }}>
                        <Statistic title={<span style={{ fontSize: 11 }}>Pending Review</span>} value={entries.filter((e: any) => e.status === 'proposed').length} valueStyle={{ fontSize: 20, fontWeight: 700, color: '#f59e0b' }} />
                    </Card>
                </Col>
            </Row>

            {entries.length > 0 && (
                <Card size="small" title={<span style={{ fontWeight: 600 }}>Tailoring Distribution</span>} style={{ marginBottom: 16, borderRadius: 10, background: isDark ? 'rgba(15,15,23,0.7)' : undefined, border: isDark ? '1px solid rgba(255,255,255,0.06)' : undefined }}>
                    <div style={{ display: 'flex', gap: 24, justifyContent: 'center', flexWrap: 'wrap' }}>
                        <div style={{ textAlign: 'center' }}>
                            <div style={{ width: 130, height: 130, margin: '0 auto' }}>
                                <ResponsiveContainer>
                                    <PieChart>
                                        <Pie data={areaDist} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={28} outerRadius={52} paddingAngle={3} strokeWidth={0}>
                                            {areaDist.map((a, i) => <Cell key={i} fill={a.color} />)}
                                        </Pie>
                                        <RTooltip />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                            <div style={{ fontSize: 11, fontWeight: 600, marginTop: 4, color: isDark ? '#e2e8f0' : '#333' }}>By Area</div>
                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, justifyContent: 'center', marginTop: 4 }}>
                                {areaDist.map(a => (
                                    <div key={a.name} style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9 }}>
                                        <div style={{ width: 6, height: 6, borderRadius: '50%', background: a.color }} />
                                        <span style={{ color: isDark ? '#94a3b8' : '#64748b', textTransform: 'capitalize' }}>{a.name} ({a.value})</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <div style={{ textAlign: 'center' }}>
                            <div style={{ width: 130, height: 130, margin: '0 auto' }}>
                                <ResponsiveContainer>
                                    <PieChart>
                                        <Pie data={statusDist} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={28} outerRadius={52} paddingAngle={3} strokeWidth={0}>
                                            {statusDist.map((s, i) => <Cell key={i} fill={s.color} />)}
                                        </Pie>
                                        <RTooltip />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                            <div style={{ fontSize: 11, fontWeight: 600, marginTop: 4, color: isDark ? '#e2e8f0' : '#333' }}>By Status</div>
                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, justifyContent: 'center', marginTop: 4 }}>
                                {statusDist.map(s => (
                                    <div key={s.name} style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9 }}>
                                        <div style={{ width: 6, height: 6, borderRadius: '50%', background: s.color }} />
                                        <span style={{ color: isDark ? '#94a3b8' : '#64748b', textTransform: 'capitalize' }}>{s.name} ({s.value})</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            <ProTable
                headerTitle={
                    <Space>
                        <ToolOutlined style={{ color: 'var(--theme-color, #8b5cf6)' }} />
                        <span>Tailoring Decisions</span>
                    </Space>
                }
                rowKey="id"
                dataSource={entries}
                loading={loading}
                columns={columns}
                search={false}
                toolBarRender={() => [
                    <Button key="ai" type="dashed" icon={<RobotOutlined />}
                        loading={aiLoading} onClick={handleAiGenerate}>
                        AI Recommend
                    </Button>,
                    <Button key="add" type="primary" icon={<PlusOutlined />}
                        onClick={() => { setEditing(null); setIsModalOpen(true); }}
                        style={{ background: 'linear-gradient(135deg, var(--theme-color, #8b5cf6), var(--theme-secondary, #6366f1))', border: 'none', borderRadius: 8 }}
                    >
                        Add Entry
                    </Button>
                ]}
            />

            <ModalForm
                title={editing ? "Edit Tailoring Entry" : "Add Tailoring Entry"}
                open={isModalOpen}
                onOpenChange={(open) => { if (!open) setEditing(null); setIsModalOpen(open); }}
                onFinish={handleFinish}
                initialValues={editing || { status: 'proposed' }}
                modalProps={{ destroyOnClose: true }}
            >
                <ProForm.Group>
                    <ProFormSelect name="area" label="Area" width="sm" options={AREA_OPTIONS} rules={[{ required: true }]} />
                    <ProFormSelect name="status" label="Status" width="sm" options={STATUS_OPTIONS} />
                </ProForm.Group>
                <ProFormTextArea name="tailoredApproach" label="Tailored Approach" rules={[{ required: true }]}
                    placeholder="Describe the tailored approach..." />
                <ProFormTextArea name="originalApproach" label="Original Approach"
                    placeholder="What was the standard/original approach?" />
                <ProFormTextArea name="rationale" label="Rationale" rules={[{ required: true }]}
                    placeholder="Why was tailoring necessary?" />
                <ProForm.Group>
                    <ProFormTextArea name="impact" label="Impact" width="md"
                        placeholder="What is the impact of this tailoring?" />
                    <ProFormText name="decidedBy" label="Decided By" width="sm" />
                </ProForm.Group>
            </ModalForm>
        </div>
    );
}

