                            style={{ width: 260, minWidth: 260, display: 'flex', flexDirection: 'column' }}
                        >
                            <div style={{ position: 'sticky', top: 16 }}>
                                <Card
                                    size="small"
                                    title={
                                        <div className="flex items-center gap-2">
                                            <span style={{
                                                background: `linear-gradient(to right, ${themeColor}, ${themeColor}dd)`,
