        </CMSLayout>
    );
}

"use client";

import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RTooltip } from 'recharts';

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { Button, Card, Col, Descriptions, Drawer, Empty, Form, Input, message, Modal, Popconfirm, Row, Select, Space, Spin, Statistic, Steps, Table, Tag, Tooltip, Typography, Segmented } from "antd";
import {
    BookOutlined, BulbOutlined, SearchOutlined, FilterOutlined,
    FolderOpenOutlined, TagOutlined, CalendarOutlined,
    ExclamationCircleOutlined, CheckCircleOutlined,
    InfoCircleOutlined, WarningOutlined, FileExcelOutlined, FilePdfOutlined,
    PlusOutlined, EditOutlined, DeleteOutlined, SaveOutlined, CloseOutlined, ReloadOutlined, AppstoreOutlined, BarsOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text, Paragraph } = Typography;

const GET_ALL_LESSONS = `
  query GetAllLessonsLearned($tenantId: String!) {
    pmAllLessonsLearned(tenantId: $tenantId)
  }
`;

const GET_PROJECTS = `
  query GetProjects($tenantId: String!) {
    pmProjects(tenantId: $tenantId) { id name projectNumber }
  }
`;

const CREATE_LESSON = `
  mutation CreateLesson($tenantId: String!, $input: CreatePmLessonLearnedInput!) {
    createPmLessonLearned(tenantId: $tenantId, input: $input) { id }
  }
`;

const UPDATE_LESSON = `
  mutation UpdateLesson($id: ID!, $input: UpdatePmLessonLearnedInput!) {
    updatePmLessonLearned(id: $id, input: $input) { id }
  }
`;

const DELETE_LESSON = `
  mutation DeleteLesson($id: ID!) {
    deletePmLessonLearned(id: $id)
  }
`;

const CATEGORY_OPTIONS = ['process', 'technical', 'management', 'communication', 'risk', 'quality', 'other'];
const PHASE_OPTIONS = ['initiation', 'planning', 'execution', 'monitoring', 'closing'];

const CATEGORY_COLORS: Record<string, string> = {
    process: '#3b82f6',
    technical: '#8b5cf6',
    management: '#f59e0b',
    communication: '#10b981',
    risk: '#ef4444',
    quality: '#06b6d4',
    other: '#6b7280',
};

const CATEGORY_CONFIG: Record<string, { color: string; icon: React.ReactNode }> = {
    process: { color: 'var(--theme-color, #8b5cf6)', icon: <BookOutlined /> },
    technical: { color: '#3b82f6', icon: <BulbOutlined /> },
    management: { color: '#6366f1', icon: <FolderOpenOutlined /> },
    communication: { color: '#10b981', icon: <InfoCircleOutlined /> },
    risk: { color: '#f59e0b', icon: <WarningOutlined /> },
    quality: { color: '#22c55e', icon: <CheckCircleOutlined /> },
    other: { color: '#6b7280', icon: <TagOutlined /> },
};

export default function KnowledgeBasePage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [lessons, setLessons] = useState<any[]>([]);
    const [search, setSearch] = useState("");
    const [categoryFilter, setCategoryFilter] = useState<string | null>(null);
    const [phaseFilter, setPhaseFilter] = useState<string | null>(null);
    const [projectFilter, setProjectFilter] = useState<string | null>(null);
    const [viewingLesson, setViewingLesson] = useState<any>(null);
    const [viewMode, setViewMode] = useState<'table' | 'grid'>('grid');
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    // ── CRUD state ──
    const [createOpen, setCreateOpen] = useState(false);
    const [createStep, setCreateStep] = useState(0);
    const [createForm] = Form.useForm();
    const [editForm] = Form.useForm();
    const [editing, setEditing] = useState(false);
    const [saving, setSaving] = useState(false);
    const [projects, setProjects] = useState<any[]>([]);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await gql(GET_ALL_LESSONS, { tenantId: DEFAULT_TENANT_ID });
            setLessons(data.pmAllLessonsLearned || []);
        } catch (err: any) { console.error("PM Error", err); } finally {
            setLoading(false);
        }
    }, []);

    const loadProjects = useCallback(async () => {
        try {
            const data = await gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID });
            setProjects(data.pmProjects || []);
        } catch (err: any) { console.error("PM Error", err); }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Create ──
    const openCreateModal = async () => {
        if (projects.length === 0) await loadProjects();
        createForm.resetFields();
        setCreateStep(0);
        setCreateOpen(true);
    };

    const handleCreate = async () => {
        try {
            const values = await createForm.validateFields();
            setSaving(true);
            await gql(CREATE_LESSON, {
                tenantId: DEFAULT_TENANT_ID,
                input: {
                    projectId: values.projectId,
                    title: values.title,
                    category: values.category,
                    phase: values.phase,
                    situation: values.situation,
                    impact: values.impact,
                    lesson: values.lesson,
                    recommendation: values.recommendation,
                    submittedBy: values.submittedBy,
                    tags: values.tags,
                },
            });
            message.success('Lesson created successfully');
            setCreateOpen(false);
            loadData();
        } catch (e: any) {
            if (e?.errorFields) return; // validation error
            message.error('Failed to create lesson');
        } finally {
            setSaving(false);
        }
    };

    // ── Edit ──
    const startEdit = () => {
        if (!viewingLesson) return;
        editForm.setFieldsValue({
            title: viewingLesson.title,
            category: viewingLesson.category,
            phase: viewingLesson.phase,
            situation: viewingLesson.situation,
            impact: viewingLesson.impact,
            lesson: viewingLesson.lesson,
            recommendation: viewingLesson.recommendation,
            submittedBy: viewingLesson.submitted_by,
            tags: viewingLesson.tags || [],
        });
        setEditing(true);
    };

    const handleUpdate = async () => {
        try {
            const values = await editForm.validateFields();
            setSaving(true);
            await gql(UPDATE_LESSON, {
                id: viewingLesson.id,
                input: {
                    title: values.title,
                    category: values.category,
                    phase: values.phase,
                    situation: values.situation,
                    impact: values.impact,
                    lesson: values.lesson,
                    recommendation: values.recommendation,
                    submittedBy: values.submittedBy,
                    tags: values.tags,
                },
            });
            message.success('Lesson updated successfully');
            setEditing(false);
            setViewingLesson(null);
            loadData();
        } catch (e: any) {
            if (e?.errorFields) return;
            message.error('Failed to update lesson');
        } finally {
            setSaving(false);
        }
    };

    // ── Delete ──
    const handleDelete = async () => {
        try {
            setSaving(true);
            await gql(DELETE_LESSON, { id: viewingLesson.id });
            message.success('Lesson deleted');
            setViewingLesson(null);
            setEditing(false);
            loadData();
        } catch (err: any) { console.error("PM Error", err); 
            message.error('Failed to delete lesson');
        } finally {
            setSaving(false);
        }
    };

    // ── Filters ──
    const filtered = useMemo(() => {
        let result = [...lessons];
        if (search) {
            const q = search.toLowerCase();
            result = result.filter(l =>
                (l.title || '').toLowerCase().includes(q) ||
                (l.lesson || '').toLowerCase().includes(q) ||
                (l.situation || '').toLowerCase().includes(q) ||
                (l.recommendation || '').toLowerCase().includes(q) ||
                (l.tags || []).some((t: string) => t.toLowerCase().includes(q))
            );
        }
        if (categoryFilter) result = result.filter(l => l.category === categoryFilter);
        if (phaseFilter) result = result.filter(l => l.phase === phaseFilter);
        if (projectFilter) result = result.filter(l => l.project?.name === projectFilter);
        return result;
    }, [lessons, search, categoryFilter, phaseFilter, projectFilter]);

    // ── Computed stats ──
    const allCategories = useMemo(() => {
        const cats = new Set(lessons.map(l => l.category).filter(Boolean));
        return Array.from(cats);
    }, [lessons]);

    const allPhases = useMemo(() => {
        const phases = new Set(lessons.map(l => l.phase).filter(Boolean));
        return Array.from(phases);
    }, [lessons]);

    const allProjects = useMemo(() => {
        const projs = new Map();
        lessons.forEach(l => {
            if (l.project) projs.set(l.project.id, l.project);
        });
        return Array.from(projs.values());
    }, [lessons]);

    const allProjectNames = useMemo(() => {
        const names = new Set<string>();
        lessons.forEach(l => { if (l.project?.name) names.add(l.project.name); });
        return Array.from(names).sort();
    }, [lessons]);

    const allTags = useMemo(() => {
        const tags = new Set<string>();
        lessons.forEach(l => (l.tags || []).forEach((t: string) => tags.add(t)));
        return Array.from(tags);
    }, [lessons]);

    const categoryDistribution = useMemo(() => {
        return allCategories.map(c => ({
            category: c,
            count: lessons.filter(l => l.category === c).length,
            ...(CATEGORY_CONFIG[c] || CATEGORY_CONFIG.other),
        }));
    }, [lessons, allCategories]);

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(12px)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    const exportCols = [{ header: 'Title', key: 'title' }, { header: 'Project', key: 'projectName' }, { header: 'Category', key: 'category' }, { header: 'Impact', key: 'impact' }];
    const exportPayload = { fileName: 'pm_knowledge_base', title: 'Lessons Learned', dateRange: { start: startDate, end: endDate }, columns: exportCols, data: lessons };

    const headerExtra = [
        <RbacGuard key="crud" requiredRole="manager">
            <Tooltip title="New Lesson"><Button icon={<PlusOutlined />} type="primary" size="small" onClick={openCreateModal} /></Tooltip>
        </RbacGuard>,
        <Tooltip key="reload" title="Reload"><Button icon={<ReloadOutlined />} size="small" onClick={loadData} loading={loading} /></Tooltip>,
        <RbacGuard key="exports" requiredRole="manager">
            <Tooltip title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel(exportPayload)} /></Tooltip>
            <Tooltip title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf(exportPayload)} /></Tooltip>
        </RbacGuard>,
    ];

    const columns = [
        {
            title: 'Lesson', dataIndex: 'title', key: 'title',
            sorter: (a: any, b: any) => (a.title || '').localeCompare(b.title || ''),
            render: (_: any, record: any) => (
                <div>
                    <a onClick={() => setViewingLesson(record)} style={{ fontWeight: 600, fontSize: 14 }}>
                        {record.title || 'Untitled Lesson'}
                    </a>
                    <div style={{ fontSize: 11, color: isDark ? '#94a3b8' : '#888', marginTop: 2 }}>
                        {record.project?.name && (
                            <Tag icon={<FolderOpenOutlined />} color="geekblue" style={{ fontSize: 10, cursor: 'pointer' }}
                                onClick={(e) => { e.stopPropagation(); router.push(`/admin/pm/dashboard?projectId=${record.project.id}`); }}>
                                {record.project.name}
                            </Tag>
                        )}
                    </div>
                </div>
            ),
        },
        {
            title: 'Category', dataIndex: 'category', key: 'category', width: 120,
            sorter: (a: any, b: any) => (a.category || '').localeCompare(b.category || ''),
            render: (category: string) => {
                const cfg = CATEGORY_CONFIG[category] || CATEGORY_CONFIG.other;
                return <Tag color={cfg.color} icon={cfg.icon} style={{ textTransform: 'capitalize' }}>{category || 'other'}</Tag>;
            },
            filters: allCategories.map(c => ({ text: c, value: c })),
            onFilter: (value: any, record: any) => record.category === value,
        },
        {
            title: 'Phase', dataIndex: 'phase', key: 'phase', width: 110,
            render: (phase: string) => phase ? <Tag color="default" style={{ textTransform: 'capitalize', fontSize: 11 }}>{phase}</Tag> : <Text type="secondary">—</Text>,
        },
        {
            title: 'Impact', dataIndex: 'impact', key: 'impact', width: 200, ellipsis: { showTitle: false },
            render: (impact: string) => impact ? <Tooltip title={impact}><Text style={{ fontSize: 12 }}>{impact}</Text></Tooltip> : <Text type="secondary">—</Text>,
        },
        {
            title: 'Tags', dataIndex: 'tags', key: 'tags', width: 160,
            render: (tags: string[]) => (
                <Space size={2} wrap>
                    {(tags || []).slice(0, 3).map(tag => <Tag key={tag} color="cyan" style={{ fontSize: 10 }}>{tag}</Tag>)}
                    {(tags || []).length > 3 && <Tag style={{ fontSize: 10 }}>+{tags.length - 3}</Tag>}
                </Space>
            ),
        },
        {
            title: 'Submitted', dataIndex: 'submitted_date', key: 'submitted_date', width: 110,
            sorter: (a: any, b: any) => dayjs(a.submitted_date).unix() - dayjs(b.submitted_date).unix(),
            render: (date: string) => date ? <Text style={{ fontSize: 11 }}><CalendarOutlined style={{ marginRight: 4 }} />{dayjs(date).format('MMM D, YYYY')}</Text> : <Text type="secondary">—</Text>,
        },
    ];

    // ── Create step content ──
    const createStepItems = [
        { title: 'Basic', content: (
            <>
                <Form.Item name="projectId" label="Project" rules={[{ required: true, message: 'Select a project' }]}>
                    <Select placeholder="Select project" showSearch optionFilterProp="label"
                        options={projects.map(p => ({ label: `${p.name} (${p.projectNumber || ''})`, value: p.id }))} />
                </Form.Item>
                <Form.Item name="title" label="Title" rules={[{ required: true, message: 'Enter a title' }]}>
                    <Input placeholder="Lesson title" />
                </Form.Item>
                <Form.Item name="category" label="Category">
                    <Select placeholder="Category" allowClear options={CATEGORY_OPTIONS.map(c => ({ label: c.charAt(0).toUpperCase() + c.slice(1), value: c }))} />
                </Form.Item>
                <Form.Item name="phase" label="Phase">
                    <Select placeholder="Phase" allowClear options={PHASE_OPTIONS.map(p => ({ label: p.charAt(0).toUpperCase() + p.slice(1), value: p }))} />
                </Form.Item>
            </>
        )},
        { title: 'Details', content: (
            <>
                <Form.Item name="situation" label="Situation"><Input.TextArea rows={3} placeholder="Describe the situation..." /></Form.Item>
                <Form.Item name="impact" label="Impact"><Input.TextArea rows={3} placeholder="What was the impact?" /></Form.Item>
                <Form.Item name="lesson" label="Lesson Learned"><Input.TextArea rows={3} placeholder="What was the lesson?" /></Form.Item>
                <Form.Item name="recommendation" label="Recommendation"><Input.TextArea rows={3} placeholder="Recommendations..." /></Form.Item>
            </>
        )},
        { title: 'Meta', content: (
            <>
                <Form.Item name="submittedBy" label="Submitted By"><Input placeholder="Name" /></Form.Item>
                <Form.Item name="tags" label="Tags"><Select mode="tags" placeholder="Add tags" /></Form.Item>
            </>
        )},
    ];

    const cmsTitle = <AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Knowledge Base</AuroraText>;
    const cmsSubTitle = <DecryptedText text="Cross-project lessons learned repository" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />;

    if (loading && lessons.length === 0) {
        return (
            <CMSLayout title={cmsTitle} subTitle={cmsSubTitle} extra={headerExtra}>
                <div style={{ textAlign: 'center', padding: 120 }}><Spin size="large" /></div>
            </CMSLayout>
        );
    }

    return (
        <CMSLayout title={cmsTitle} subTitle={cmsSubTitle} extra={headerExtra}>
            {/* ── Stats Row ── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                <Col xs={24} sm={8} lg={6}>
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0 }}>
                        <Card style={{ ...glassCard, borderTop: `3px solid ${themeColor}` }} size="small">
                            <Statistic title={<span style={{ fontSize: 12 }}>Total Lessons</span>} value={lessons.length}
                                prefix={<BookOutlined style={{ color: themeColor }} />} valueStyle={{ fontSize: 28, fontWeight: 700, color: themeColor }} />
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} sm={8} lg={6}>
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}>
                        <Card style={{ ...glassCard, borderTop: '3px solid #3b82f6' }} size="small">
                            <Statistic title={<span style={{ fontSize: 12 }}>Contributing Projects</span>} value={allProjects.length}
                                prefix={<FolderOpenOutlined style={{ color: '#3b82f6' }} />} valueStyle={{ fontSize: 28, fontWeight: 700, color: '#3b82f6' }} />
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} sm={8} lg={6}>
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
                        <Card style={{ ...glassCard, borderTop: '3px solid #10b981' }} size="small">
                            <Statistic title={<span style={{ fontSize: 12 }}>Categories</span>} value={allCategories.length}
                                prefix={<TagOutlined style={{ color: '#10b981' }} />} valueStyle={{ fontSize: 28, fontWeight: 700, color: '#10b981' }} />
                        </Card>
                    </motion.div>
                </Col>
                <Col xs={24} sm={8} lg={6}>
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                        <Card style={{ ...glassCard, borderTop: '3px solid #f59e0b' }} size="small">
                            <Statistic title={<span style={{ fontSize: 12 }}>Unique Tags</span>} value={allTags.length}
                                prefix={<BulbOutlined style={{ color: '#f59e0b' }} />} valueStyle={{ fontSize: 28, fontWeight: 700, color: '#f59e0b' }} />
                        </Card>
                    </motion.div>
                </Col>
            </Row>

            {/* ── Category Distribution Donut ── */}
            {categoryDistribution.length > 0 && (
                <Card size="small" title={<Space><FolderOpenOutlined style={{ color: themeColor }} />Category Distribution</Space>} style={{ ...glassCard, marginBottom: 16 }}>
                    <Row gutter={16} align="middle">
                        <Col xs={24} md={10}>
                            <div style={{ height: 180 }}>
                                <ResponsiveContainer>
                                    <PieChart>
                                        <Pie
                                            data={categoryDistribution.filter((c: any) => c.count > 0)}
                                            dataKey="count"
                                            nameKey="category"
                                            cx="50%" cy="50%"
                                            innerRadius={45} outerRadius={70}
                                            paddingAngle={3}
                                            strokeWidth={0}
                                        >
                                            {categoryDistribution.filter((c: any) => c.count > 0).map((entry: any, i: number) => (
                                                <Cell key={i} fill={entry.color || CATEGORY_COLORS[entry.category] || themeColor} />
                                            ))}
                                        </Pie>
                                        <RTooltip formatter={(value: number, name: string) => [`${value} lessons`, name]} />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </Col>
                        <Col xs={24} md={14}>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                                {categoryDistribution.map((cat: any) => (
                                    <div
                                        key={cat.category}
                                        onClick={() => setCategoryFilter(categoryFilter === cat.category ? null : cat.category)}
                                        style={{
                                            display: 'flex', alignItems: 'center', gap: 8,
                                            padding: '6px 10px', borderRadius: 8, cursor: 'pointer',
                                            background: categoryFilter === cat.category ? `${themeColor}15` : 'transparent',
                                            border: categoryFilter === cat.category ? `1px solid ${themeColor}30` : '1px solid transparent',
                                            transition: 'all 0.2s',
                                        }}
                                    >
                                        <div style={{ width: 10, height: 10, borderRadius: '50%', background: cat.color || CATEGORY_COLORS[cat.category] || themeColor, flexShrink: 0 }} />
                                        <span style={{ flex: 1, fontSize: 12, fontWeight: categoryFilter === cat.category ? 600 : 400, textTransform: 'capitalize' }}>{cat.category}</span>
                                        <Tag style={{ margin: 0, borderRadius: 10, fontSize: 11 }}>{cat.count}</Tag>
                                    </div>
                                ))}
                            </div>
                        </Col>
                    </Row>
                </Card>
            )}

            {/* ── Phase Distribution Mini Bars ── */}
            {allPhases.length > 0 && (
                <Card size="small" title={<Space><CalendarOutlined style={{ color: themeColor }} />Phase Distribution</Space>} style={{ ...glassCard, marginBottom: 16 }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                        {allPhases.map((phase: string) => {
                            const count = lessons.filter(l => l.phase === phase).length;
                            const pct = lessons.length > 0 ? Math.round((count / lessons.length) * 100) : 0;
                            return (
                                <div key={phase} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                    <span style={{ width: 100, fontSize: 11, textTransform: 'capitalize', flexShrink: 0, color: isDark ? '#94a3b8' : '#64748b' }}>{phase}</span>
                                    <div style={{ flex: 1, height: 8, borderRadius: 4, background: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)', overflow: 'hidden' }}>
                                        <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ duration: 0.6, delay: 0.1 }}
                                            style={{ height: '100%', borderRadius: 4, background: `linear-gradient(90deg, ${themeColor}, ${themeColor}88)` }} />
                                    </div>
                                    <span style={{ fontSize: 11, fontWeight: 600, width: 40, textAlign: 'right' }}>{count}</span>
                                </div>
                            );
                        })}
                    </div>
                </Card>
            )}

            {/* ── Search & Filters ── */}
            <Card style={{ ...glassCard, marginBottom: 16 }} size="small">
                <Space size={12} wrap style={{ width: '100%' }}>
                    <Input placeholder="Search lessons, tags, recommendations..." prefix={<SearchOutlined />}
                        value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ width: 320 }} />
                    <Select placeholder="Category" allowClear value={categoryFilter} onChange={setCategoryFilter} style={{ width: 160 }}
                        options={allCategories.map(c => ({ label: c.charAt(0).toUpperCase() + c.slice(1), value: c }))} />
                    <Select placeholder="Phase" allowClear value={phaseFilter} onChange={setPhaseFilter} style={{ width: 160 }}
                        options={allPhases.map(p => ({ label: p.charAt(0).toUpperCase() + p.slice(1), value: p }))} />
                    <Select
                        placeholder="Project"
                        allowClear
                        value={projectFilter}
                        onChange={setProjectFilter}
                        style={{ width: 180 }}
                        showSearch
                        filterOption={(input, option) => (option?.label as string || '').toLowerCase().includes(input.toLowerCase())}
                        options={allProjectNames.map((p: string) => ({ label: p, value: p }))}
                    />
                    {(search || categoryFilter || phaseFilter || projectFilter) && <Tag color="blue">{filtered.length} results</Tag>}
                </Space>
            </Card>

            {/* ── Lessons Display ── */}
            <Card 
                title={
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Space><BookOutlined style={{ color: themeColor }} /><span style={{ fontWeight: 600 }}>Lessons Learned</span><Tag color="purple">{filtered.length}</Tag></Space>
                        <Segmented 
                            options={[
                                { value: 'grid', icon: <AppstoreOutlined /> },
                                { value: 'table', icon: <BarsOutlined /> }
                            ]} 
                            value={viewMode} 
                            onChange={(val) => setViewMode(val as 'grid' | 'table')} 
                        />
                    </div>
                } 
                style={glassCard}
            >
                {filtered.length === 0 ? (
                    <Empty description={lessons.length === 0 ? "No lessons recorded yet. Click 'New Lesson' to add one." : "No lessons match your current filters."} />
                ) : viewMode === 'table' ? (
                    <Table scroll={{ x: 900 }} dataSource={filtered} columns={columns} rowKey="id"
                        pagination={{ pageSize: 15, showSizeChanger: true }} size="small" style={{ fontSize: 13 }}
                        onRow={(record) => ({ onClick: () => setViewingLesson(record), style: { cursor: 'pointer' } })} />
                ) : (
                    <Row gutter={[16, 16]}>
                        {filtered.map(lesson => {
                            const cfg = CATEGORY_CONFIG[lesson.category] || CATEGORY_CONFIG.other;
                            return (
                                <Col xs={24} sm={12} md={8} xl={6} key={lesson.id}>
                                    <motion.div whileHover={{ y: -4 }} transition={{ duration: 0.2 }}>
                                        <Card 
                                            hoverable 
                                            onClick={() => setViewingLesson(lesson)}
                                            bodyStyle={{ padding: '16px' }}
                                            style={{ 
                                                ...glassCard, 
                                                height: '100%', 
                                                borderTop: `3px solid ${cfg.color}`,
                                                display: 'flex',
                                                flexDirection: 'column'
                                            }}
                                        >
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                                                <Tag color={cfg.color} icon={cfg.icon} style={{ textTransform: 'capitalize', margin: 0 }}>
                                                    {lesson.category || 'other'}
                                                </Tag>
                                                {lesson.phase && <span style={{ fontSize: 10, color: isDark ? '#94a3b8' : '#64748b', textTransform: 'uppercase', letterSpacing: 0.5, fontWeight: 600 }}>{lesson.phase}</span>}
                                            </div>
                                            <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 8, lineHeight: 1.3, color: isDark ? '#fff' : '#111' }}>
                                                {lesson.title || 'Untitled Lesson'}
                                            </div>
                                            {lesson.project?.name && (
                                                <div style={{ fontSize: 11, color: isDark ? '#94a3b8' : '#64748b', marginBottom: 12, display: 'flex', alignItems: 'center', gap: 4 }}>
                                                    <FolderOpenOutlined /> {lesson.project.name}
                                                </div>
                                            )}
                                            <div style={{ flex: 1, fontSize: 12, color: isDark ? '#cbd5e1' : '#475569', marginBottom: 16, overflow: 'hidden', textOverflow: 'ellipsis', display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical' }}>
                                                {lesson.lesson || 'No lesson content provided.'}
                                            </div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: 'auto' }}>
                                                <Space size={2} wrap style={{ maxWidth: '70%' }}>
                                                    {(lesson.tags || []).slice(0, 2).map((tag: string) => <Tag key={tag} color="cyan" style={{ fontSize: 9, margin: 0 }}>{tag}</Tag>)}
                                                    {(lesson.tags || []).length > 2 && <Tag style={{ fontSize: 9, margin: 0 }}>+{lesson.tags.length - 2}</Tag>}
                                                </Space>
                                                <span style={{ fontSize: 10, color: isDark ? '#94a3b8' : '#64748b' }}>
                                                    {lesson.submitted_date ? dayjs(lesson.submitted_date).format('MMM D, YYYY') : ''}
                                                </span>
                                            </div>
                                        </Card>
                                    </motion.div>
                                </Col>
                            );
                        })}
                    </Row>
                )}
            </Card>

            {/* ── Detail Drawer ── */}
            <Drawer
                title={<Space><BulbOutlined style={{ color: '#f59e0b' }} /><span>{editing ? 'Edit Lesson' : 'Lesson Details'}</span></Space>}
                width={600} open={!!viewingLesson}
                onClose={() => { setViewingLesson(null); setEditing(false); }}
                extra={
                    <Space>
                        {viewingLesson?.project && !editing && (
                            <Button size="small" onClick={() => router.push(`/admin/pm/dashboard?projectId=${viewingLesson.project.id}`)}>Open Project</Button>
                        )}
                        {!editing ? (
                            <RbacGuard requiredRole="manager">
                                <Button icon={<EditOutlined />} size="small" onClick={startEdit}>Edit</Button>
                                <Popconfirm title="Delete this lesson?" description="This action cannot be undone." onConfirm={handleDelete} okButtonProps={{ danger: true, loading: saving }}>
                                    <Button icon={<DeleteOutlined />} size="small" danger>Delete</Button>
                                </Popconfirm>
                            </RbacGuard>
                        ) : (
                            <>
                                <Button icon={<CloseOutlined />} size="small" onClick={() => setEditing(false)}>Cancel</Button>
                                <Button icon={<SaveOutlined />} size="small" type="primary" loading={saving} onClick={handleUpdate}>Save</Button>
                            </>
                        )}
                    </Space>
                }
            >
                {viewingLesson && !editing && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
                        <div style={{ padding: 16, background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)', borderRadius: 12, border: isDark ? '1px solid rgba(255,255,255,0.08)' : '1px solid rgba(0,0,0,0.06)' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
                                <div>
                                    <h2 style={{ margin: 0, fontSize: 20, fontWeight: 700 }}>{viewingLesson.title || 'Untitled Lesson'}</h2>
                                    {viewingLesson.project && (
                                        <div style={{ marginTop: 8 }}>
                                            <Tag icon={<FolderOpenOutlined />} color="geekblue" style={{ cursor: 'pointer' }} onClick={() => router.push(`/admin/pm/dashboard?projectId=${viewingLesson.project.id}`)}>
                                                {viewingLesson.project.name} ({viewingLesson.project.project_number})
                                            </Tag>
                                        </div>
                                    )}
                                </div>
                                {(() => { const cfg = CATEGORY_CONFIG[viewingLesson.category] || CATEGORY_CONFIG.other; return <Tag color={cfg.color} icon={cfg.icon} style={{ margin: 0 }}>{viewingLesson.category || 'other'}</Tag>; })()}
                            </div>

                            {viewingLesson.phase && (
                                <div style={{ marginBottom: 16 }}>
                                    <Steps size="small" current={PHASE_OPTIONS.indexOf(viewingLesson.phase)} items={PHASE_OPTIONS.map(p => ({ title: p.charAt(0).toUpperCase() + p.slice(1) }))} />
                                </div>
                            )}

                            <div style={{ display: 'flex', gap: 24, fontSize: 12, color: isDark ? '#94a3b8' : '#64748b' }}>
                                <div><span style={{ fontWeight: 600 }}>Submitted by:</span> {viewingLesson.submitted_by || '—'}</div>
                                <div><span style={{ fontWeight: 600 }}>Date:</span> {viewingLesson.submitted_date ? dayjs(viewingLesson.submitted_date).format('MMMM D, YYYY') : '—'}</div>
                            </div>
                        </div>

                        <div>
                            <h3 style={{ fontSize: 14, fontWeight: 700, color: '#f59e0b', marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}><ExclamationCircleOutlined /> Situation</h3>
                            <div style={{ padding: 16, background: isDark ? 'rgba(245, 158, 11, 0.1)' : 'rgba(245, 158, 11, 0.05)', borderRadius: 8, borderLeft: '4px solid #f59e0b', fontSize: 14, lineHeight: 1.6 }}>
                                {viewingLesson.situation || 'No situation described.'}
                            </div>
                        </div>

                        <div>
                            <h3 style={{ fontSize: 14, fontWeight: 700, color: '#ef4444', marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}><WarningOutlined /> Impact</h3>
                            <div style={{ padding: 16, background: isDark ? 'rgba(239, 68, 68, 0.1)' : 'rgba(239, 68, 68, 0.05)', borderRadius: 8, borderLeft: '4px solid #ef4444', fontSize: 14, lineHeight: 1.6 }}>
                                {viewingLesson.impact || 'No impact described.'}
                            </div>
                        </div>

                        <div>
                            <h3 style={{ fontSize: 14, fontWeight: 700, color: themeColor, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}><BulbOutlined /> Lesson Learned</h3>
                            <div style={{ padding: 16, background: isDark ? 'rgba(139, 92, 246, 0.1)' : 'rgba(139, 92, 246, 0.05)', borderRadius: 8, borderLeft: `4px solid ${themeColor}`, fontSize: 14, lineHeight: 1.6 }}>
                                {viewingLesson.lesson || 'No lesson documented.'}
                            </div>
                        </div>

                        <div>
                            <h3 style={{ fontSize: 14, fontWeight: 700, color: '#10b981', marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}><CheckCircleOutlined /> Recommendation</h3>
                            <div style={{ padding: 16, background: isDark ? 'rgba(16, 185, 129, 0.1)' : 'rgba(16, 185, 129, 0.05)', borderRadius: 8, borderLeft: '4px solid #10b981', fontSize: 14, lineHeight: 1.6 }}>
                                {viewingLesson.recommendation || 'No recommendation provided.'}
                            </div>
                        </div>

                        {(viewingLesson.tags || []).length > 0 && (
                            <div>
                                <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}><TagOutlined /> Tags</h3>
                                <Space size={6} wrap>{viewingLesson.tags.map((tag: string) => <Tag key={tag} color="cyan">{tag}</Tag>)}</Space>
                            </div>
                        )}
                    </div>
                )}
                {viewingLesson && editing && (
                    <Form form={editForm} layout="vertical" size="small">
                        <Form.Item name="title" label="Title" rules={[{ required: true }]}><Input /></Form.Item>
                        <Row gutter={12}>
                            <Col span={12}><Form.Item name="category" label="Category"><Select allowClear options={CATEGORY_OPTIONS.map(c => ({ label: c.charAt(0).toUpperCase() + c.slice(1), value: c }))} /></Form.Item></Col>
                            <Col span={12}><Form.Item name="phase" label="Phase"><Select allowClear options={PHASE_OPTIONS.map(p => ({ label: p.charAt(0).toUpperCase() + p.slice(1), value: p }))} /></Form.Item></Col>
                        </Row>
                        <Form.Item name="situation" label="Situation"><Input.TextArea rows={3} /></Form.Item>
                        <Form.Item name="impact" label="Impact"><Input.TextArea rows={3} /></Form.Item>
                        <Form.Item name="lesson" label="Lesson Learned"><Input.TextArea rows={3} /></Form.Item>
                        <Form.Item name="recommendation" label="Recommendation"><Input.TextArea rows={3} /></Form.Item>
                        <Form.Item name="submittedBy" label="Submitted By"><Input /></Form.Item>
                        <Form.Item name="tags" label="Tags"><Select mode="tags" placeholder="Add tags" /></Form.Item>
                    </Form>
                )}
            </Drawer>

            {/* ── Create Modal ── */}
            <Modal title={<Space><PlusOutlined style={{ color: themeColor }} /> New Lesson Learned</Space>}
                open={createOpen} onCancel={() => setCreateOpen(false)} width={560}
                footer={
                    <Space>
                        {createStep > 0 && <Button onClick={() => setCreateStep(s => s - 1)}>Back</Button>}
                        {createStep < 2 ? (
                            <Button type="primary" onClick={async () => {
                                try {
                                    if (createStep === 0) await createForm.validateFields(['projectId', 'title']);
                                    setCreateStep(s => s + 1);
                                } catch (err: any) { console.error("PM Error", err); }
                            }}>Next</Button>
                        ) : (
                            <Button type="primary" icon={<SaveOutlined />} loading={saving} onClick={handleCreate}>Create Lesson</Button>
                        )}
                    </Space>
                }
            >
                <Steps current={createStep} size="small" style={{ marginBottom: 24 }}
                    items={createStepItems.map(s => ({ title: s.title }))} />
                <Form form={createForm} layout="vertical" size="small">
                    <div style={{ display: createStep === 0 ? 'block' : 'none' }}>{createStepItems[0].content}</div>
                    <div style={{ display: createStep === 1 ? 'block' : 'none' }}>{createStepItems[1].content}</div>
                    <div style={{ display: createStep === 2 ? 'block' : 'none' }}>{createStepItems[2].content}</div>
                </Form>
            </Modal>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion, AnimatePresence } from "framer-motion";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import {
    Badge, Button, Card, Col, Collapse, Empty, Input, InputNumber, message,
    Modal, Progress, Row, Select, Space, Spin, Statistic, Tag, Tooltip, Typography
} from "antd";
import {
    CheckCircleOutlined, ClockCircleOutlined, ExclamationCircleOutlined,
    FireOutlined, UserOutlined, CalendarOutlined, ProjectOutlined,
    ThunderboltOutlined, RocketOutlined, PlusOutlined, ReloadOutlined,
    CarryOutOutlined, FieldTimeOutlined, ArrowUpOutlined, MinusOutlined,
    ArrowDownOutlined, SmileOutlined, SearchOutlined
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, Cell } from "recharts";
import TimeTracker from "../components/TimeTracker";

const { Text, Title } = Typography;

// ── GraphQL ──────────────────────────────────────────────
const GET_ME = `query { me { id email fullName role } }`;

const GET_MY_TASKS = `
  query($tenantId: String!, $assigneeId: String) {
    pmTasks(tenantId: $tenantId, assigneeId: $assigneeId) {
      id projectId sprintId title description status priority type
      assigneeId estimatedHours loggedHours startDate dueDate tags createdAt
      assignee { id firstName lastName }
    }
  }
`;

const GET_PROJECTS = `
  query($tenantId: String!) {
    pmProjects(tenantId: $tenantId) { id name projectNumber status }
  }
`;

const UPDATE_TASK = `
  mutation UpdateTask($id: ID!, $input: UpdatePmTaskInput!) {
    updatePmTask(id: $id, input: $input) { id status }
  }
`;

const LOG_TIME = `
  mutation LogTime($tenantId: String!, $input: CreatePmTimeLogInput!) {
    logPmTime(tenantId: $tenantId, input: $input) { id hours }
  }
`;

const STATUS_FLOW = ["todo", "in_progress", "in_review", "done"] as const;
const STATUS_CONFIG: Record<string, { color: string; icon: React.ReactNode; label: string }> = {
    todo: { color: "#64748b", icon: <CarryOutOutlined />, label: "To Do" },
    in_progress: { color: "#3b82f6", icon: <ClockCircleOutlined />, label: "In Progress" },
    in_review: { color: "var(--theme-color, #8b5cf6)", icon: <ThunderboltOutlined />, label: "In Review" },
    done: { color: "#10b981", icon: <CheckCircleOutlined />, label: "Done" },
};

const PRIORITY_ICON: Record<string, React.ReactNode> = {
    critical: <FireOutlined style={{ color: "#ef4444" }} />,
    high: <ArrowUpOutlined style={{ color: "#f59e0b" }} />,
    medium: <MinusOutlined style={{ color: "#3b82f6" }} />,
    low: <ArrowDownOutlined style={{ color: "#6b7280" }} />,
};

const DEMO_USER = { id: "demo", email: "demo@nusantarasoft.com", fullName: "Demo User", role: "member" };

export default function MyWorkPage() {
    const router = useRouter();
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === "dark";

    const [messageApi, contextHolder] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [user, setUser] = useState<any>(null);
    const [tasks, setTasks] = useState<any[]>([]);
    const [projects, setProjects] = useState<any[]>([]);

    // Quick log time
    const [logModal, setLogModal] = useState(false);
    const [logTask, setLogTask] = useState<string | null>(null);
    const [logHours, setLogHours] = useState<number>(1);
    const [logDesc, setLogDesc] = useState("");
    const [logSaving, setLogSaving] = useState(false);
    const [taskSearch, setTaskSearch] = useState("");

    const glassCard = {
        background: isDark ? "rgba(15, 15, 23, 0.7)" : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(12px)",
        border: isDark ? "1px solid rgba(139,92,246,0.15)" : "1px solid rgba(0,0,0,0.06)",
        borderRadius: 12,
    };

    // ── Data Loading ─────────────────────────────────────────
    const loadData = useCallback(async () => {
        setLoading(true);
        let currentUser = DEMO_USER;
        try {
            const meData = await gql(GET_ME, {});
            if (meData?.me) currentUser = meData.me;
        } catch (err: any) { console.error("PM Error", err); }
        setUser(currentUser);

        try {
            const [taskData, projData] = await Promise.all([
                gql(GET_MY_TASKS, { tenantId: DEFAULT_TENANT_ID, assigneeId: currentUser.id }),
                gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setTasks(taskData.pmTasks || []);
            setProjects(projData.pmProjects || []);
        } catch (err: any) { console.error("PM Error", err); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Project Map ──────────────────────────────────────────
    const projectMap = useMemo(() => {
        const m = new Map<string, any>();
        projects.forEach(p => m.set(p.id, p));
        return m;
    }, [projects]);

    // ── Time-of-day greeting ─────────────────────────────────
    const greeting = useMemo(() => {
        const h = new Date().getHours();
        if (h < 12) return "Good morning";
        if (h < 17) return "Good afternoon";
        return "Good evening";
    }, []);

    // ── Computed data ────────────────────────────────────────
    const today = dayjs().startOf("day");

    const overdueTasks = useMemo(() =>
        tasks.filter(t => t.dueDate && dayjs(t.dueDate).isBefore(today) && t.status !== "done"),
    [tasks, today]);

    const dueTodayTasks = useMemo(() =>
        tasks.filter(t => t.dueDate && dayjs(t.dueDate).isSame(today, "day") && t.status !== "done"),
    [tasks, today]);

    const inProgressCount = tasks.filter(t => t.status === "in_progress").length;

    const tasksByStatus = useMemo(() => {
        const map: Record<string, any[]> = { todo: [], in_progress: [], in_review: [], done: [] };
        tasks.forEach(t => {
            // For "done", only show tasks completed today (by createdAt or if status is done today)
            if (t.status === "done") {
                map.done.push(t);
            } else if (map[t.status]) {
                map[t.status].push(t);
            }
        });
        return map;
    }, [tasks]);

    // -- Filtered by search --
    const filteredTasksByStatus = useMemo(() => {
        if (!taskSearch.trim()) return tasksByStatus;
        const q = taskSearch.toLowerCase();
        const filtered: Record<string, any[]> = { todo: [], in_progress: [], in_review: [], done: [] };
        Object.entries(tasksByStatus).forEach(([status, items]) => {
            filtered[status] = items.filter((t: any) =>
                t.title?.toLowerCase().includes(q) ||
                projectMap.get(t.projectId)?.name?.toLowerCase().includes(q)
            );
        });
        return filtered;
    }, [tasksByStatus, taskSearch, projectMap]);

    // -- Recently completed (last 5 done tasks) --
    const recentlyCompleted = useMemo(() =>
        tasks
            .filter(t => t.status === "done")
            .sort((a, b) => dayjs(b.createdAt).unix() - dayjs(a.createdAt).unix())
            .slice(0, 5),
    [tasks]);

    // -- Productivity streak --
    const streak = useMemo(() => {
        let count = 0;
        for (let i = 0; i < 30; i++) {
            const day = dayjs().subtract(i, "day");
            const hasDone = tasks.some(t =>
                t.status === "done" && t.createdAt && dayjs(t.createdAt).isSame(day, "day")
            );
            if (hasDone) count++;
            else if (i > 0) break;
        }
        return count;
    }, [tasks]);

    // ── Weekly summary ───────────────────────────────────────
    const weeklyData = useMemo(() => {
        const startOfWeek = dayjs().startOf("week").add(1, "day"); // Monday
        const days = ["Mon", "Tue", "Wed", "Thu", "Fri"];
        return days.map((name, i) => {
            const day = startOfWeek.add(i, "day");
            const count = tasks.filter(t =>
                t.status === "done" && t.createdAt && dayjs(t.createdAt).isSame(day, "day")
            ).length;
            return { name, count };
        });
    }, [tasks]);

    const weeklyDone = weeklyData.reduce((s, d) => s + d.count, 0);
    const weeklyHours = useMemo(() =>
        tasks.filter(t => t.status === "done").reduce((s, t) => s + (t.loggedHours || 0), 0),
    [tasks]);

    // ── Active projects (that I have tasks in) ───────────────
    const activeProjects = useMemo(() => {
        const counts = new Map<string, { total: number; done: number }>();
        tasks.forEach(t => {
            if (!counts.has(t.projectId)) counts.set(t.projectId, { total: 0, done: 0 });
            const c = counts.get(t.projectId)!;
            c.total++;
            if (t.status === "done") c.done++;
        });
        return Array.from(counts.entries())
            .map(([pid, c]) => ({ project: projectMap.get(pid), ...c }))
            .filter(p => p.project)
            .sort((a, b) => b.total - a.total);
    }, [tasks, projectMap]);

    // ── Handlers ─────────────────────────────────────────────
    const cycleStatus = async (task: any) => {
        const idx = STATUS_FLOW.indexOf(task.status);
        const next = STATUS_FLOW[(idx + 1) % STATUS_FLOW.length];
        try {
            await gql(UPDATE_TASK, { id: task.id, input: { status: next } });
            messageApi.success(`Moved to ${STATUS_CONFIG[next]?.label}`);
            loadData();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error("Failed to update status"); }
    };

    const handleStatusChange = async (taskId: string, newStatus: string) => {
        try {
            await gql(UPDATE_TASK, { id: taskId, input: { status: newStatus } });
            messageApi.success(`Status updated to ${STATUS_CONFIG[newStatus]?.label}`);
            loadData();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error("Failed to update status"); }
    };

    const handleLogTime = async () => {
        if (!logTask || !logHours) { messageApi.warning("Select task and hours"); return; }
        setLogSaving(true);
        try {
            await gql(LOG_TIME, {
                tenantId: DEFAULT_TENANT_ID,
                input: {
                    taskId: logTask,
                    userId: user?.id || "demo",
                    hours: logHours,
                    logDate: dayjs().format("YYYY-MM-DD"),
                    description: logDesc || undefined,
                },
            });
            messageApi.success("Time logged!");
            setLogModal(false);
            setLogTask(null);
            setLogHours(1);
            setLogDesc("");
            loadData();
        } catch (err: any) { console.error("PM Error", err);  messageApi.error("Failed to log time"); }
        finally { setLogSaving(false); }
    };

    // ── Task Row Renderer ────────────────────────────────────
    const renderTaskRow = (t: any, accent?: string) => {
        const proj = projectMap.get(t.projectId);
        const isOverdue = t.dueDate && dayjs(t.dueDate).isBefore(today) && t.status !== "done";
        return (
            <motion.div
                key={t.id}
                role="button"
                aria-label={`Task: ${t.title}`}
                tabIndex={0}
                onKeyDown={(e: React.KeyboardEvent) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); router.push(`/admin/pm/tasks/${t.id}`); } }}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                whileHover={{ x: 4 }}
                style={{
                    display: "flex", alignItems: "center", gap: 10, padding: "10px 14px",
                    borderRadius: 10, marginBottom: 6, cursor: "pointer",
                    background: isDark ? "rgba(30,30,44,0.6)" : "rgba(255,255,255,0.7)",
                    border: isDark ? "1px solid rgba(139,92,246,0.1)" : "1px solid rgba(0,0,0,0.04)",
                    borderLeft: `3px solid ${accent || STATUS_CONFIG[t.status]?.color || "#64748b"}`,
                }}
                onClick={() => router.push(`/admin/pm/tasks/${t.id}`)}
            >
                <div style={{ flex: 1, minWidth: 0 }}>
                    <Text strong style={{ fontSize: 13, display: "block" }} ellipsis>{t.title}</Text>
                    <Space size={4} style={{ marginTop: 4 }}>
                        {proj && <Tag color="geekblue" style={{ fontSize: 10, borderRadius: 6, padding: "0 6px", margin: 0 }}>{proj.name}</Tag>}
                        {t.priority && PRIORITY_ICON[t.priority]}
                        {t.type && <Tag color={t.type === "bug" ? "red" : t.type === "story" ? "green" : "purple"} style={{ fontSize: 10, borderRadius: 6, padding: "0 6px", margin: 0 }}>{t.type}</Tag>}
                    </Space>
                </div>
                {t.dueDate && (
                    <Text style={{ fontSize: 11, color: isOverdue ? "#ef4444" : isDark ? "#94a3b8" : "#888", whiteSpace: "nowrap" }}>
                        <CalendarOutlined style={{ marginRight: 3 }} />
                        {dayjs(t.dueDate).format("MMM D")}
                    </Text>
                )}
                <Text type="secondary" style={{ fontSize: 11, whiteSpace: "nowrap" }}>
                    <ClockCircleOutlined style={{ marginRight: 3 }} />
                    {t.loggedHours || 0}h
                </Text>
                <Select
                    size="small" value={t.status} variant="borderless"
                    style={{ width: 120 }}
                    onClick={e => e.stopPropagation()}
                    onChange={val => handleStatusChange(t.id, val)}
                    options={STATUS_FLOW.map(s => ({ label: <Tag color={STATUS_CONFIG[s].color} style={{ margin: 0, fontSize: 10 }}>{STATUS_CONFIG[s].label}</Tag>, value: s }))}
                    aria-label={`Change status for ${t.title}`}
                />
            </motion.div>
        );
    };

    // ── Loading State ────────────────────────────────────────
    if (loading) {
        return (
            <CMSLayout
                title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>My Work</AuroraText>}
                subTitle={<DecryptedText text="Your personal task dashboard" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            >
                <div style={{ textAlign: "center", padding: 120 }}><Spin size="large" /></div>
            </CMSLayout>
        );
    }

    const userName = user?.fullName || user?.email?.split("@")[0] || "there";

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>My Work</AuroraText>}
            subTitle={<DecryptedText text="Your personal task dashboard" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Button key="log" type="primary" icon={<FieldTimeOutlined />} onClick={() => setLogModal(true)}
                    style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: "none", borderRadius: 8 }}
                    aria-label="Log Time">
                    Log Time
                </Button>,
                <Button key="reload" type="text" icon={<ReloadOutlined />} onClick={loadData} aria-label="Reload data" />,
            ]}
        >
            {contextHolder}

            {/* ── Welcome Header ── */}
            <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
                <Card style={{ ...glassCard, marginBottom: 20, borderLeft: `4px solid ${themeColor}` }} size="small" role="region" aria-label="Welcome summary">
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 16 }}>
                        <div>
                            <Title level={4} style={{ margin: 0 }}>
                                {greeting}, <span style={{ background: `linear-gradient(to right, ${themeColor}, ${themeColor}dd)`, WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>{userName}</span> 👋
                            </Title>
                            <Text type="secondary" style={{ fontSize: 13 }}>{dayjs().format("dddd, MMMM D, YYYY")}</Text>
                        </div>
                        <Space size={24}>
                            <Statistic title={<span style={{ fontSize: 11 }}>Due Today</span>} value={dueTodayTasks.length} valueStyle={{ fontSize: 20, fontWeight: 700, color: "#f59e0b" }} prefix={<CalendarOutlined />} />
                            <Statistic title={<span style={{ fontSize: 11 }}>Overdue</span>} value={overdueTasks.length} valueStyle={{ fontSize: 20, fontWeight: 700, color: "#ef4444" }} prefix={<ExclamationCircleOutlined />} />
                            <Statistic title={<span style={{ fontSize: 11 }}>In Progress</span>} value={inProgressCount} valueStyle={{ fontSize: 20, fontWeight: 700, color: "#3b82f6" }} prefix={<ClockCircleOutlined />} />
                        </Space>
                    </div>
                </Card>
            </motion.div>

            {/* ── Time Tracker ── */}
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}>
                <Card size="small" style={{ ...glassCard, marginBottom: 20 }} role="region" aria-label="Time tracker">
                    <TimeTracker compact onTimeLogged={loadData} />
                </Card>
            </motion.div>

            <Row gutter={[20, 20]}>
                {/* ── Main Content Column ── */}
                <Col xs={24} lg={18}>
                    {/* ── Focus: Due Today / Overdue ── */}
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
                        <Card
                            title={<Space><ExclamationCircleOutlined style={{ color: "#ef4444" }} /><span style={{ fontWeight: 600 }}>Focus — Needs Attention</span><Badge count={overdueTasks.length + dueTodayTasks.length} style={{ backgroundColor: "#ef4444" }} /></Space>}
                            size="small"
                            style={{ ...glassCard, marginBottom: 20 }}
                            role="region"
                            aria-label="Tasks needing attention"
                        >
                            {overdueTasks.length === 0 && dueTodayTasks.length === 0 ? (
                                <div style={{ textAlign: "center", padding: "30px 0" }}>
                                    <SmileOutlined style={{ fontSize: 36, color: "#10b981", marginBottom: 8 }} />
                                    <div><Text strong style={{ fontSize: 15, color: "#10b981" }}>All caught up! 🎉</Text></div>
                                    <Text type="secondary" style={{ fontSize: 12 }}>No overdue or urgent tasks. Great job!</Text>
                                </div>
                            ) : (
                                <>
                                    {overdueTasks.length > 0 && (
                                        <div style={{ marginBottom: overdueTasks.length > 0 && dueTodayTasks.length > 0 ? 12 : 0 }}>
                                            <Text type="secondary" style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 1, marginBottom: 6, display: "block" }}>
                                                🔴 Overdue ({overdueTasks.length})
                                            </Text>
                                            {overdueTasks.map(t => renderTaskRow(t, "#ef4444"))}
                                        </div>
                                    )}
                                    {dueTodayTasks.length > 0 && (
                                        <div>
                                            <Text type="secondary" style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 1, marginBottom: 6, display: "block" }}>
                                                🟠 Due Today ({dueTodayTasks.length})
                                            </Text>
                                            {dueTodayTasks.map(t => renderTaskRow(t, "#f59e0b"))}
                                        </div>
                                    )}
                                </>
                            )}
                        </Card>
                    </motion.div>

                    {/* ── Tasks Grouped by Status ── */}
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                        <Card
                            title={
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
                                    <Space><CarryOutOutlined style={{ color: themeColor }} /><span style={{ fontWeight: 600 }}>My Tasks</span><Tag color="purple">{tasks.length}</Tag></Space>
                                    <Input
                                        prefix={<SearchOutlined style={{ color: isDark ? '#64748b' : '#94a3b8', fontSize: 12 }} />}
                                        placeholder="Filter tasks..."
                                        value={taskSearch}
                                        onChange={e => setTaskSearch(e.target.value)}
                                        allowClear
                                        style={{ width: 180, borderRadius: 8 }}
                                        size="small"
                                    />
                                </div>
                            }
                            size="small"
                            style={{ ...glassCard, marginBottom: 20 }}
                            role="region"
                            aria-label="My tasks grouped by status"
                        >
                            {tasks.length === 0 ? (
                                <Empty description="No tasks assigned yet. Check back soon!" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                            ) : (
                                <Collapse
                                    ghost
                                    defaultActiveKey={["todo", "in_progress", "in_review"]}
                                    items={STATUS_FLOW.map(status => {
                                        const items = filteredTasksByStatus[status] || [];
                                        const cfg = STATUS_CONFIG[status];
                                        return {
                                            key: status,
                                            label: (
                                                <Space>
                                                    {cfg.icon}
                                                    <Text strong style={{ color: cfg.color }}>{cfg.label}</Text>
                                                    <Badge count={items.length} style={{ backgroundColor: cfg.color }} size="small" />
                                                </Space>
                                            ),
                                            children: items.length === 0
                                                ? <Text type="secondary" style={{ fontSize: 12, padding: "8px 0", display: "block" }}>No tasks in this status</Text>
                                                : items.map(t => renderTaskRow(t)),
                                        };
                                    })}
                                />
                            )}
                        </Card>
                    </motion.div>

                    {/* -- Recently Completed -- */}
                    {recentlyCompleted.length > 0 && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }}>
                            <Card
                                title={<Space><CheckCircleOutlined style={{ color: "#10b981" }} /><span style={{ fontWeight: 600 }}>Recently Completed</span><Tag color="green">{recentlyCompleted.length}</Tag></Space>}
                                size="small"
                                style={{ ...glassCard, marginBottom: 20, borderLeft: '4px solid #10b981' }}
                            >
                                {recentlyCompleted.map((t, i) => {
                                    const proj = projectMap.get(t.projectId);
                                    return (
                                        <motion.div
                                            key={t.id}
                                            initial={{ opacity: 0, x: -8 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            transition={{ delay: i * 0.04 }}
                                            style={{
                                                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                                                padding: '8px 12px', borderRadius: 8, marginBottom: 4,
                                                background: isDark ? 'rgba(16,185,129,0.06)' : 'rgba(16,185,129,0.04)',
                                                border: isDark ? '1px solid rgba(16,185,129,0.1)' : '1px solid rgba(16,185,129,0.08)',
                                            }}
                                        >
                                            <Space size={8}>
                                                <CheckCircleOutlined style={{ color: '#10b981', fontSize: 14 }} />
                                                <div>
                                                    <Text style={{ fontSize: 12, textDecoration: 'line-through', opacity: 0.7 }}>{t.title}</Text>
                                                    {proj && <Tag style={{ fontSize: 9, borderRadius: 6, padding: '0 5px', margin: '0 0 0 6px' }}>{proj.name}</Tag>}
                                                </div>
                                            </Space>
                                            <Text type="secondary" style={{ fontSize: 10 }}>
                                                {t.createdAt ? dayjs(t.createdAt).fromNow() : ''}
                                            </Text>
                                        </motion.div>
                                    );
                                })}
                            </Card>
                        </motion.div>
                    )}

                    {/* ── Weekly Summary ── */}
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                        <Card
                            title={<Space><RocketOutlined style={{ color: themeColor }} /><span style={{ fontWeight: 600 }}>Weekly Summary</span></Space>}
                            size="small"
                            style={glassCard}
                            role="region"
                            aria-label="Weekly summary"
                        >
                            <Row gutter={24} align="middle">
                                <Col xs={24} md={14}>
                                    <ResponsiveContainer width="100%" height={160}>
                                        <BarChart data={weeklyData}>
                                            <CartesianGrid strokeDasharray="3 3" stroke={isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)"} />
                                            <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke={isDark ? "#64748b" : "#94a3b8"} />
                                            <YAxis tick={{ fontSize: 11 }} stroke={isDark ? "#64748b" : "#94a3b8"} allowDecimals={false} />
                                            <RTooltip contentStyle={{ background: isDark ? "#1e1e2c" : "#fff", border: "none", borderRadius: 8, fontSize: 12 }} />
                                            <Bar dataKey="count" radius={[6, 6, 0, 0]} name="Completed">
                                                {weeklyData.map((_, i) => (
                                                    <Cell key={i} fill={`${themeColor}${i === dayjs().day() - 1 ? "ff" : "88"}`} />
                                                ))}
                                            </Bar>
                                        </BarChart>
                                    </ResponsiveContainer>
                                </Col>
                                <Col xs={24} md={10}>
                                    <div style={{ display: "flex", flexDirection: "column", gap: 16, padding: "0 8px" }}>
                                        <Statistic
                                            title={<span style={{ fontSize: 11 }}>Tasks Completed This Week</span>}
                                            value={weeklyDone}
                                            prefix={<CheckCircleOutlined style={{ color: "#10b981" }} />}
                                            valueStyle={{ fontSize: 28, fontWeight: 700, color: "#10b981" }}
                                        />
                                        <Statistic
                                            title={<span style={{ fontSize: 11 }}>Hours Logged (Completed)</span>}
                                            value={weeklyHours}
                                            suffix="h"
                                            prefix={<ClockCircleOutlined style={{ color: themeColor }} />}
                                            valueStyle={{ fontSize: 28, fontWeight: 700 }}
                                        />
                                    </div>
                                </Col>
                            </Row>
                        </Card>
                    </motion.div>
                </Col>

                {/* ── Sidebar: Active Projects ── */}
                <Col xs={24} lg={6}>
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.15 }}>
                        <Card
                            title={<Space><ProjectOutlined style={{ color: themeColor }} /><span style={{ fontWeight: 600, fontSize: 13 }}>My Projects</span></Space>}
                            size="small"
                            style={{ ...glassCard, marginBottom: 20 }}
                            role="region"
                            aria-label="My projects"
                        >
                            {activeProjects.length === 0 ? (
                                <Empty description="No active projects" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                            ) : (
                                <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                                    {activeProjects.map(({ project, total, done }) => {
                                        const pct = total > 0 ? Math.round((done / total) * 100) : 0;
                                        return (
                                            <motion.div
                                                key={project.id}
                                                whileHover={{ scale: 1.02 }}
                                                onClick={() => router.push(`/admin/pm/dashboard?projectId=${project.id}`)}
                                                style={{
                                                    padding: "10px 12px", borderRadius: 10, cursor: "pointer",
                                                    background: isDark ? "rgba(30,30,44,0.5)" : "rgba(245,243,255,0.6)",
                                                    border: isDark ? "1px solid rgba(139,92,246,0.1)" : "1px solid rgba(139,92,246,0.08)",
                                                }}
                                            >
                                                <Text strong style={{ fontSize: 12, display: "block", marginBottom: 4 }}>{project.name}</Text>
                                                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
                                                    <Text type="secondary" style={{ fontSize: 10 }}>{done}/{total} tasks</Text>
                                                    <Tag color={project.status === "active" ? "green" : "default"} style={{ fontSize: 9, borderRadius: 6, padding: "0 5px", margin: 0 }}>
                                                        {project.status?.toUpperCase()}
                                                    </Tag>
                                                </div>
                                                <Progress
                                                    percent={pct} size="small"
                                                    strokeColor={pct >= 75 ? "#10b981" : pct >= 40 ? "#f59e0b" : themeColor}
                                                    trailColor={isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)"}
                                                />
                                            </motion.div>
                                        );
                                    })}
                                </div>
                            )}
                        </Card>
                    </motion.div>

                    {/* ── Quick Stats Sidebar Card ── */}
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 }}>
                        <Card
                            title={<Space><ThunderboltOutlined style={{ color: "#f59e0b" }} /><span style={{ fontWeight: 600, fontSize: 13 }}>Quick Stats</span></Space>}
                            size="small"
                            style={glassCard}
                            role="region"
                            aria-label="Quick stats"
                        >
                            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                                {[
                                    { label: "Total Tasks", value: tasks.length, color: themeColor },
                                    { label: "Completed", value: tasksByStatus.done.length, color: "#10b981" },
                                    { label: "In Progress", value: tasksByStatus.in_progress.length, color: "#3b82f6" },
                                    { label: "To Do", value: tasksByStatus.todo.length, color: "#64748b" },
                                    { label: "In Review", value: tasksByStatus.in_review.length, color: "var(--theme-color, #8b5cf6)" },
                                ].map(s => (
                                    <div key={s.label} style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                        <Space size={6}>
                                            <div style={{ width: 8, height: 8, borderRadius: 2, background: s.color }} />
                                            <Text style={{ fontSize: 12 }}>{s.label}</Text>
                                        </Space>
                                        <Text strong style={{ fontSize: 14, color: s.color }}>{s.value}</Text>
                                    </div>
                                ))}
                            </div>
                            {tasks.length > 0 && (
                                <Progress
                                    percent={tasks.length > 0 ? Math.round((tasksByStatus.done.length / tasks.length) * 100) : 0}
                                    size="small"
                                    strokeColor={{ "0%": themeColor, "100%": "#10b981" }}
                                    trailColor={isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)"}
                                    style={{ marginTop: 14 }}
                                    format={p => <span style={{ fontSize: 11 }}>{p}% done</span>}
                                />
                            )}
                        </Card>
                    </motion.div>

                    {/* -- Productivity Streak -- */}
                    {streak > 0 && (
                        <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.3 }}>
                            <Card
                                size="small"
                                style={{ ...glassCard, marginTop: 20, borderTop: `3px solid ${streak >= 5 ? '#f59e0b' : '#10b981'}`, textAlign: 'center' }}
                            >
                                <div style={{ fontSize: 36, fontWeight: 800, lineHeight: 1.2, background: `linear-gradient(135deg, ${streak >= 5 ? '#f59e0b' : '#10b981'}, ${streak >= 5 ? '#ef4444' : '#3b82f6'})`, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                                    {streak}
                                </div>
                                <Text strong style={{ fontSize: 12 }}>Day Streak</Text>
                                <div><Text type="secondary" style={{ fontSize: 10 }}>{streak >= 5 ? 'On fire! Keep it up!' : 'Great progress!'}</Text></div>
                                <div style={{ display: 'flex', justifyContent: 'center', gap: 3, marginTop: 8 }}>
                                    {Array.from({ length: Math.min(streak, 7) }).map((_, i) => (
                                        <div key={i} style={{ width: 8, height: 8, borderRadius: 2, background: streak >= 5 ? '#f59e0b' : '#10b981' }} />
                                    ))}
                                </div>
                            </Card>
                        </motion.div>
                    )}
                </Col>
            </Row>

            {/* ── Quick Log Time Modal ── */}
            <Modal
                title={<Space><FieldTimeOutlined style={{ color: themeColor }} /> Quick Log Time</Space>}
                open={logModal}
                onCancel={() => setLogModal(false)}
                onOk={handleLogTime}
                confirmLoading={logSaving}
                okText="Log Time"
                okButtonProps={{ style: { background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: "none", borderRadius: 8 } }}
            >
                <div style={{ display: "flex", flexDirection: "column", gap: 16, marginTop: 16 }}>
                    <div>
                        <Text strong style={{ fontSize: 12, display: "block", marginBottom: 6 }}>Task</Text>
                        <Select
                            placeholder="Select a task..."
                            value={logTask}
                            onChange={setLogTask}
                            style={{ width: "100%" }}
                            showSearch
                            optionFilterProp="label"
                            options={tasks.filter(t => t.status !== "done").map(t => ({
                                value: t.id,
                                label: `${t.title} (${projectMap.get(t.projectId)?.name || "—"})`,
                            }))}
                        />
                    </div>
                    <div>
                        <Text strong style={{ fontSize: 12, display: "block", marginBottom: 6 }}>Hours</Text>
                        <InputNumber min={0.25} max={24} step={0.25} value={logHours} onChange={v => setLogHours(v || 1)} style={{ width: "100%" }} />
                    </div>
                    <div>
                        <Text strong style={{ fontSize: 12, display: "block", marginBottom: 6 }}>Description (optional)</Text>
                        <Input.TextArea rows={2} value={logDesc} onChange={e => setLogDesc(e.target.value)} placeholder="What did you work on?" />
                    </div>
                </div>
            </Modal>
        </CMSLayout>
    );
}

"use client";

