source:
"use client";
import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Card, Button, Space, Tag, Typography, Row, Col, Statistic, Table, Progress, message, Select, Badge, Empty, Spin, Tabs, theme } from "antd";
import {
    CheckSquareOutlined, ProjectOutlined, FormOutlined, CheckCircleOutlined,
    PlusOutlined, ReloadOutlined, FileTextOutlined,
    ArrowRightOutlined, BarChartOutlined, ExclamationCircleOutlined,
    SafetyOutlined, StarOutlined, RiseOutlined, FallOutlined,
    EyeOutlined, ClockCircleOutlined,
} from "@ant-design/icons";
import { motion } from "framer-motion";
import CMSLayout from "@/components/layout/CMSLayout";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useRouter } from "next/navigation";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, Cell, RadarChart, Radar, PolarGrid, PolarAngleAxis, PolarRadiusAxis, LineChart, Line, PieChart, Pie } from "recharts";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);

const { Text } = Typography;
const COLORS = ['#10b981', '#3b82f6', '#8b5cf6', '#f59e0b', '#ef4444', '#ec4899'];



// Pre-built quality checklist templates
const CHECKLIST_TEMPLATES = [
    { id: 'qa-sprint', name: 'Sprint QA Checklist', items: 12, category: 'Development', color: '#3b82f6' },
    { id: 'qa-release', name: 'Release Readiness', items: 18, category: 'Deployment', color: '#10b981' },
    { id: 'qa-code', name: 'Code Review Standards', items: 15, category: 'Code Quality', color: '#8b5cf6' },
    { id: 'qa-ux', name: 'UX Review Checklist', items: 10, category: 'Design', color: '#ec4899' },
    { id: 'qa-security', name: 'Security Assessment', items: 20, category: 'Security', color: '#ef4444' },
    { id: 'qa-perf', name: 'Performance Testing', items: 8, category: 'Performance', color: '#f59e0b' },
];

const STATUS_TAG: Record<string, { color: string }> = {
    passed: { color: '#10b981' }, on_target: { color: '#10b981' }, completed: { color: '#10b981' },
    failed: { color: '#ef4444' }, off_target: { color: '#ef4444' },
    in_progress: { color: '#3b82f6' }, pending: { color: '#f59e0b' }, scheduled: { color: '#6366f1' },
    active: { color: '#3b82f6' }, draft: { color: '#6b7280' },
};

const SEVERITY_TAG: Record<string, { color: string }> = {
    critical: { color: '#ef4444' }, high: { color: '#f59e0b' }, medium: { color: '#3b82f6' },
    low: { color: '#6b7280' }, info: { color: '#10b981' },
};

export default function PmQualityPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const router = useRouter();
    const [messageApi, ctx] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [submissions, setSubmissions] = useState<any[]>([]);
    const [templates, setTemplates] = useState<any[]>([]);
    const [projects, setProjects] = useState<any[]>([]);
    const [selectedProject, setSelectedProject] = useState<string | null>(null);
    const [metrics, setMetrics] = useState<any[]>([]);
    const [checklists, setChecklists] = useState<any[]>([]);
    const [inspections, setInspections] = useState<any[]>([]);
    const [qualityLoading, setQualityLoading] = useState(false);

    const glassCard = useMemo(() => ({
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(12px)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    }), [isDark]);

    // Load form data + projects
    const load = useCallback(async () => {
        setLoading(true);
        try {
            const [tRes, sRes, pRes] = await Promise.all([
                gql<{ formTemplates: any[] }>(`query($t:String!){ formTemplates(tenantId:$t){ id name category status } }`, { t: DEFAULT_TENANT_ID }).catch(() => ({ formTemplates: [] })),
                gql<{ formSubmissions: any[] }>(`query($t:String!){ formSubmissions(tenantId:$t){ id status totalScore maxPossibleScore percentage grade submittedBy submittedAt templateName templateCategory } }`, { t: DEFAULT_TENANT_ID }).catch(() => ({ formSubmissions: [] })),
                gql<{ pmProjects: any[] }>(`query($t:String!){ pmProjects(tenantId:$t){ id name projectNumber status } }`, { t: DEFAULT_TENANT_ID }).catch(() => ({ pmProjects: [] })),
            ]);
            setTemplates(tRes.formTemplates || []);
            const qualitySubs = (sRes.formSubmissions || []).filter((s: any) =>
                s.templateCategory === 'checklist' || s.templateCategory === 'assessment' || s.templateCategory === 'audit' || s.percentage > 0
            );
            setSubmissions(qualitySubs);
            setProjects(pRes.pmProjects || []);
        } catch (e: any) { messageApi.error(e.message); }
        setLoading(false);
    }, [messageApi]);

    // Load project-specific quality data
    const loadQualityData = useCallback(async (projectId: string) => {
        setQualityLoading(true);
        try {
            const [mRes, cRes, iRes] = await Promise.all([
                gql<{ pmQualityMetrics: any[] }>(`query($projectId:String!){ pmQualityMetrics(projectId:$projectId){ id projectId metricName category targetValue actualValue unit status trend measuredAt notes createdAt updatedAt } }`, { projectId }).catch(() => ({ pmQualityMetrics: [] })),
                gql<{ pmQualityChecklists: any[] }>(`query($projectId:String!){ pmQualityChecklists(projectId:$projectId){ id projectId name category description items status completedItems totalItems completedBy completedAt createdAt updatedAt } }`, { projectId }).catch(() => ({ pmQualityChecklists: [] })),
                gql<{ pmQualityInspections: any[] }>(`query($projectId:String!){ pmQualityInspections(projectId:$projectId){ id projectId inspectionType inspector status findings recommendations severity scheduledDate completedDate notes createdAt updatedAt } }`, { projectId }).catch(() => ({ pmQualityInspections: [] })),
            ]);
            setMetrics(mRes.pmQualityMetrics || []);
            setChecklists(cRes.pmQualityChecklists || []);
            setInspections(iRes.pmQualityInspections || []);
        } catch (err: any) { console.error("PM Error", err); }
        setQualityLoading(false);
    }, []);

    useEffect(() => { load(); }, [load]);
    useEffect(() => {
        if (selectedProject) loadQualityData(selectedProject);
        else { setMetrics([]); setChecklists([]); setInspections([]); }
    }, [selectedProject, loadQualityData]);

    // Computed form stats
    const scoredSubs = submissions.filter(s => s.percentage > 0);
    const avgScore = scoredSubs.length > 0 ? scoredSubs.reduce((a: number, s: any) => a + s.percentage, 0) / scoredSubs.length : 0;
    const passRate = scoredSubs.length > 0 ? Math.round((scoredSubs.filter(s => s.percentage >= 70).length / scoredSubs.length) * 100) : 0;

    // Chart data
    const templateScoreMap: Record<string, number[]> = {};
    scoredSubs.forEach((s: any) => {
        const name = (s.templateName || 'Unknown').slice(0, 20);
        if (!templateScoreMap[name]) templateScoreMap[name] = [];
        templateScoreMap[name].push(s.percentage);
    });
    const barData = Object.entries(templateScoreMap).map(([name, scores]) => ({
        name, avgScore: Math.round(scores.reduce((a, s) => a + s, 0) / scores.length),
    }));

    // Quality KPIs
    const metricsOnTarget = metrics.filter(m => m.status === 'on_target' || m.status === 'passed').length;
    const inspCompleted = inspections.filter(i => i.status === 'completed').length;
    const checkPassed = checklists.filter(c => c.status === 'completed' || c.status === 'passed').length;
    const openIssues = inspections.filter(i => i.status !== 'completed' && i.severity && ['critical', 'high'].includes(i.severity)).length;
    const complianceRate = metrics.length > 0 ? Math.round((metricsOnTarget / metrics.length) * 100) : (scoredSubs.length > 0 ? passRate : 0);

    // Radar data for quality dimensions
    const radarData = useMemo(() => {
        const dims = [
            { name: 'Code Quality', key: 'Code Quality', fallback: avgScore },
            { name: 'Testing', key: 'Performance', fallback: passRate },
            { name: 'Security', key: 'Security', fallback: complianceRate },
            { name: 'Documentation', key: 'Development', fallback: avgScore * 0.85 },
            { name: 'Performance', key: 'Deployment', fallback: avgScore * 0.9 },
            { name: 'Reliability', key: 'Design', fallback: complianceRate * 0.95 },
        ];
        return dims.map(d => {
            const relevantMetrics = metrics.filter(m => m.category === d.key);
            const score = relevantMetrics.length > 0
                ? Math.round(relevantMetrics.filter(m => m.status === 'on_target' || m.status === 'passed').length / relevantMetrics.length * 100)
                : Math.round(d.fallback);
            return { dimension: d.name, score: Math.max(0, Math.min(100, score)) };
        });
    }, [metrics, avgScore, passRate, complianceRate]);

    const statCards: Array<{ label: string; value: string | number; color: string; icon: React.ReactNode; trend: 'up' | 'down' | 'stable' }> = [
        { label: 'Quality Metrics', value: metrics.length || CHECKLIST_TEMPLATES.length, color: '#3b82f6', icon: <BarChartOutlined />, trend: 'up' },
        { label: 'Avg Score', value: `${avgScore.toFixed(1)}%`, color: avgScore >= 70 ? '#10b981' : '#f59e0b', icon: <StarOutlined />, trend: avgScore >= 70 ? 'up' : 'down' },
        { label: 'Inspections Done', value: inspCompleted || inspections.length, color: '#8b5cf6', icon: <EyeOutlined />, trend: 'stable' },
        { label: 'Checklists Passed', value: checkPassed || submissions.filter(s => s.status === 'approved').length, color: '#10b981', icon: <CheckCircleOutlined />, trend: 'up' },
        { label: 'Open Issues', value: openIssues || submissions.filter(s => s.status === 'submitted').length, color: '#ef4444', icon: <ExclamationCircleOutlined />, trend: openIssues > 0 ? 'down' : 'up' },
        { label: 'Compliance', value: `${complianceRate}%`, color: complianceRate >= 80 ? '#10b981' : '#f59e0b', icon: <SafetyOutlined />, trend: complianceRate >= 80 ? 'up' : 'down' },
    ];

    // Metric columns
    const metricCols = [
        { title: 'Metric', dataIndex: 'metricName', key: 'metricName', render: (v: string, r: any) => (
            <div><Text strong style={{ fontSize: 12 }}>{v}</Text><div><Tag style={{ fontSize: 9, borderRadius: 8 }}>{r.category || 'General'}</Tag></div></div>
        )},
        { title: 'Target', dataIndex: 'targetValue', key: 'targetValue', width: 90, render: (v: number, r: any) => <Text style={{ fontSize: 12 }}>{v ?? '-'} {r.unit || ''}</Text> },
        { title: 'Actual', dataIndex: 'actualValue', key: 'actualValue', width: 90, render: (v: number, r: any) => {
            const ok = r.targetValue != null && v != null && v >= r.targetValue;
            return <Text style={{ fontSize: 12, color: ok ? '#10b981' : v != null ? '#ef4444' : undefined }}>{v ?? '-'} {r.unit || ''}</Text>;
        }},
        { title: 'Trend', key: 'trend', width: 60, render: (_: any, r: any) => {
            if (r.trend === 'up') return <RiseOutlined style={{ color: '#10b981', fontSize: 16 }} />;
            if (r.trend === 'down') return <FallOutlined style={{ color: '#ef4444', fontSize: 16 }} />;
            return <Text type="secondary" style={{ fontSize: 11 }}>—</Text>;
        }},
        { title: 'Status', dataIndex: 'status', key: 'status', width: 100, render: (v: string) => {
            const cfg = STATUS_TAG[v] || { color: '#6b7280' };
            return <Tag color={cfg.color} style={{ fontSize: 10, borderRadius: 8 }}>{(v || 'unknown').replace(/_/g, ' ').toUpperCase()}</Tag>;
        }},
        { title: 'Measured', dataIndex: 'measuredAt', key: 'measuredAt', width: 100, render: (v: string) => <Text type="secondary" style={{ fontSize: 11 }}>{v ? dayjs(v).fromNow() : '-'}</Text> },
    ];

    // Inspection columns
    const inspCols = [
        { title: 'Type', dataIndex: 'inspectionType', key: 'type', render: (v: string) => <Text strong style={{ fontSize: 12 }}>{(v || '').replace(/_/g, ' ')}</Text> },
        { title: 'Inspector', dataIndex: 'inspector', key: 'inspector', width: 120, render: (v: string) => <Text style={{ fontSize: 12 }}>{v || '-'}</Text> },
        { title: 'Severity', dataIndex: 'severity', key: 'severity', width: 90, render: (v: string) => {
            const cfg = SEVERITY_TAG[v] || { color: '#6b7280' };
            return <Tag color={cfg.color} style={{ fontSize: 10, borderRadius: 8 }}>{(v || '-').toUpperCase()}</Tag>;
        }},
        { title: 'Status', dataIndex: 'status', key: 'status', width: 100, render: (v: string) => {
            const cfg = STATUS_TAG[v] || { color: '#6b7280' };
            return <Tag color={cfg.color} style={{ fontSize: 10, borderRadius: 8 }}>{(v || '-').replace(/_/g, ' ').toUpperCase()}</Tag>;
        }},
        { title: 'Findings', dataIndex: 'findings', key: 'findings', ellipsis: true, render: (v: string) => <Text style={{ fontSize: 11 }}>{v || '-'}</Text> },
        { title: 'Scheduled', dataIndex: 'scheduledDate', key: 'scheduledDate', width: 100, render: (v: string) => <Text type="secondary" style={{ fontSize: 11 }}>{v ? dayjs(v).format('MMM D, YYYY') : '-'}</Text> },
    ];

    const tabItems = [
        {
            key: 'overview', label: <Space><BarChartOutlined /> Overview</Space>,
            children: (
                <Row gutter={[16, 16]}>
                    <Col xs={24} md={14}>
                        <Card size="small" title={<Space><BarChartOutlined style={{ color: '#3b82f6' }} /> Quality Radar</Space>} style={glassCard}>
                            <div style={{ height: 280 }}>
                                {radarData.length > 0 ? (
                                    <ResponsiveContainer>
                                        <RadarChart data={radarData} outerRadius="75%">
                                            <PolarGrid stroke={isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)'} />
                                            <PolarAngleAxis dataKey="dimension" tick={{ fontSize: 10, fill: isDark ? '#94a3b8' : '#64748b' }} />
                                            <PolarRadiusAxis domain={[0, 100]} tick={{ fontSize: 9 }} />
                                            <Radar name="Quality Score" dataKey="score" stroke={themeColor} fill={themeColor} fillOpacity={0.25} strokeWidth={2} />
                                        </RadarChart>
                                    </ResponsiveContainer>
                                ) : <Empty description="No quality data available" />}
                            </div>
                        </Card>
                    </Col>
                    <Col xs={24} md={10}>
                        <Card size="small" title={<Space><FileTextOutlined style={{ color: '#8b5cf6' }} /> Recent Evaluations</Space>} style={{ ...glassCard, height: '100%' }}>
                            {scoredSubs.slice(0, 8).map((s: any, i: number) => (
                                <motion.div key={s.id} initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.04 }}
                                    style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.04)' : '#f5f5f5'}` }}>
                                    <div>
                                        <Text strong style={{ fontSize: 12 }}>{s.templateName || 'Checklist'}</Text>
                                        <div><Tag style={{ fontSize: 9 }}>{s.status}</Tag></div>
                                    </div>
                                    <Progress type="circle" size={32} percent={s.percentage}
                                        strokeColor={s.percentage >= 70 ? '#10b981' : '#ef4444'}
                                        format={() => <Text style={{ fontSize: 9 }}>{s.percentage.toFixed(0)}</Text>} />
                                </motion.div>
                            ))}
                            {scoredSubs.length === 0 && <Empty description="No results yet" />}
                        </Card>
                    </Col>
                </Row>
            ),
        },
        {
            key: 'metrics', label: <Space><BarChartOutlined /> Metrics <Badge count={metrics.length} size="small" /></Space>,
            children: metrics.length > 0 ? (
                <Card size="small" style={glassCard}>
                    <Table dataSource={metrics} columns={metricCols} rowKey="id" size="small" pagination={{ pageSize: 10 }}
                        style={{ fontSize: 12 }} />
                </Card>
            ) : (
                <Card style={glassCard}>
                    <Empty description={selectedProject ? "No quality metrics found for this project" : "Select a project to view quality metrics"} image={Empty.PRESENTED_IMAGE_SIMPLE}>
                        {selectedProject && <Button type="primary" size="small" icon={<PlusOutlined />} style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: 'none', marginTop: 8 }}>Add Metric</Button>}
                    </Empty>
                </Card>
            ),
        },
        {
            key: 'checklists', label: <Space><CheckSquareOutlined /> Checklists <Badge count={checklists.length + CHECKLIST_TEMPLATES.length} size="small" /></Space>,
            children: (
                <div>
                    {/* Project Checklists from backend */}
                    {checklists.length > 0 && (
                        <Card size="small" title={<Space><CheckSquareOutlined style={{ color: '#10b981' }} /> Project Checklists</Space>} style={{ ...glassCard, marginBottom: 16 }}>
                            <Row gutter={[12, 12]}>
                                {checklists.map((cl: any, i: number) => {
                                    const pct = cl.totalItems > 0 ? Math.round((cl.completedItems / cl.totalItems) * 100) : 0;
                                    const statusCfg = STATUS_TAG[cl.status] || { color: '#6b7280' };
                                    return (
                                        <Col xs={24} sm={12} md={8} key={cl.id}>
                                            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                                <Card size="small" hoverable style={{ ...glassCard, borderTop: `3px solid ${statusCfg.color}` }}>
                                                    <Space direction="vertical" size={6} style={{ width: '100%' }}>
                                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                                            <div>
                                                                <Text strong style={{ fontSize: 12 }}>{cl.name}</Text>
                                                                <div><Tag style={{ fontSize: 9, borderRadius: 8 }}>{cl.category || 'General'}</Tag>
                                                                <Tag color={statusCfg.color} style={{ fontSize: 9, borderRadius: 8 }}>{(cl.status || '').toUpperCase()}</Tag></div>
                                                            </div>
                                                            <Progress type="circle" size={36} percent={pct} strokeColor={pct >= 80 ? '#10b981' : pct >= 50 ? '#f59e0b' : '#6366f1'}
                                                                format={() => <Text style={{ fontSize: 9 }}>{pct}%</Text>} />
                                                        </div>
                                                        <Progress percent={pct} size="small" showInfo={false} strokeColor={pct >= 80 ? '#10b981' : pct >= 50 ? '#f59e0b' : '#6366f1'}
                                                            trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'} />
                                                        <Text type="secondary" style={{ fontSize: 10 }}>{cl.completedItems}/{cl.totalItems} items complete</Text>
                                                    </Space>
                                                </Card>
                                            </motion.div>
                                        </Col>
                                    );
                                })}
                            </Row>
                        </Card>
                    )}
                    {/* Template Checklists */}
                    <Card size="small" title={<Space><FormOutlined style={{ color: '#3b82f6' }} /> Checklist Templates</Space>} style={glassCard}>
                        <Row gutter={[12, 12]}>
                            {CHECKLIST_TEMPLATES.map((tpl, i) => (
                                <Col xs={24} sm={12} md={8} key={tpl.id}>
                                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.05 }}>
                                        <Card hoverable size="small" style={{ ...glassCard, borderTop: `3px solid ${tpl.color}`, cursor: 'pointer' }}
                                            onClick={() => router.push('/admin/forms/builder')}>
                                            <Space direction="vertical" size={6} style={{ width: '100%' }}>
                                                <Space>
                                                    <CheckSquareOutlined style={{ fontSize: 18, color: tpl.color }} />
                                                    <div>
                                                        <Text strong style={{ fontSize: 12 }}>{tpl.name}</Text>
                                                        <div><Tag color={tpl.color} style={{ fontSize: 9, borderRadius: 8 }}>{tpl.category}</Tag></div>
                                                    </div>
                                                </Space>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                    <Text type="secondary" style={{ fontSize: 10 }}>{tpl.items} check items</Text>
                                                    <Button type="link" size="small" icon={<FormOutlined />} style={{ fontSize: 11 }}>Use</Button>
                                                </div>
                                            </Space>
                                        </Card>
                                    </motion.div>
                                </Col>
                            ))}
                        </Row>
                    </Card>
                </div>
            ),
        },
        {
            key: 'gates', label: <Space><SafetyOutlined /> Quality Gates</Space>,
            children: (
                <Card size="small" style={glassCard}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, overflow: 'auto', padding: '20px 0' }}>
                        {[
                            { name: 'Code Review', status: complianceRate >= 80 ? 'passed' : complianceRate >= 50 ? 'warning' : 'pending', metric: `${complianceRate}%` },
                            { name: 'Unit Tests', status: passRate >= 80 ? 'passed' : passRate >= 50 ? 'warning' : 'pending', metric: `${passRate}%` },
                            { name: 'Security Scan', status: openIssues === 0 ? 'passed' : 'warning', metric: `${openIssues} issues` },
                            { name: 'Integration', status: inspCompleted > 0 ? 'passed' : 'pending', metric: `${inspCompleted} done` },
                            { name: 'Acceptance', status: checkPassed > 0 ? 'passed' : 'pending', metric: `${checkPassed} passed` },
                            { name: 'Release Ready', status: complianceRate >= 80 && passRate >= 80 && openIssues === 0 ? 'passed' : 'blocked', metric: complianceRate >= 80 ? 'Ready' : 'Blocked' },
                        ].map((gate, i, arr) => {
                            const gateColor = gate.status === 'passed' ? '#10b981' : gate.status === 'warning' ? '#f59e0b' : gate.status === 'blocked' ? '#ef4444' : '#64748b';
                            const gateIcon = gate.status === 'passed' ? <CheckCircleOutlined /> : gate.status === 'warning' ? <ExclamationCircleOutlined /> : <ClockCircleOutlined />;
                            return (
                                <React.Fragment key={gate.name}>
                                    <motion.div
                                        initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.1 }}
                                        style={{
                                            display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8,
                                            padding: '16px 24px', borderRadius: 12, minWidth: 120,
                                            background: isDark ? `${gateColor}15` : `${gateColor}10`,
                                            border: `2px solid ${gateColor}44`,
                                        }}
                                    >
                                        <div style={{ fontSize: 24, color: gateColor }}>{gateIcon}</div>
                                        <Text strong style={{ fontSize: 12, textAlign: 'center' }}>{gate.name}</Text>
                                        <Tag color={gateColor} style={{ fontSize: 10, borderRadius: 8 }}>{gate.metric}</Tag>
                                        <Tag color={gateColor} style={{ fontSize: 9, borderRadius: 6, margin: 0 }}>{gate.status.toUpperCase()}</Tag>
                                    </motion.div>
                                    {i < arr.length - 1 && (
                                        <div style={{ display: 'flex', alignItems: 'center', color: isDark ? '#64748b' : '#94a3b8', fontSize: 18 }}>-{'>'}</div>
                                    )}
                                </React.Fragment>
                            );
                        })}
                    </div>
                </Card>
            ),
        },
        {
            key: 'inspections', label: <Space><EyeOutlined /> Inspections <Badge count={inspections.length} size="small" /></Space>,
            children: inspections.length > 0 ? (
                <Card size="small" style={glassCard}>
                    <Table dataSource={inspections} columns={inspCols} rowKey="id" size="small" pagination={{ pageSize: 10 }}
                        style={{ fontSize: 12 }} />
                </Card>
            ) : (
                <Card style={glassCard}>
                    <Empty description={selectedProject ? "No inspections found for this project" : "Select a project to view inspections"} image={Empty.PRESENTED_IMAGE_SIMPLE}>
                        {selectedProject && <Button type="primary" size="small" icon={<PlusOutlined />} style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: 'none', marginTop: 8 }}>Schedule Inspection</Button>}
                    </Empty>
                </Card>
            ),
        },
    ];

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#10b981', '#3b82f6']}>Quality Management</AuroraText>}
            subTitle={<DecryptedText text="Quality metrics, checklists, inspections & assessments" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <Button key="new" type="primary" icon={<PlusOutlined />} onClick={() => router.push('/admin/forms/builder')}
                    style={{ background: 'linear-gradient(135deg, #10b981, #059669)', border: 'none' }}>Create Checklist</Button>,
                <Button key="forms" icon={<ArrowRightOutlined />} onClick={() => router.push('/admin/forms/templates')}>Form Templates</Button>,
                <Button key="reload" icon={<ReloadOutlined />} onClick={() => { load(); if (selectedProject) loadQualityData(selectedProject); }} />,
            ]}
        >
            {ctx}
            {loading ? <div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" /></div> : (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                    {/* Project Selector */}
                    <Card size="small" style={{ ...glassCard, marginBottom: 16, borderTop: `3px solid ${themeColor}` }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
                            <ProjectOutlined style={{ fontSize: 18, color: themeColor }} />
                            <Text strong style={{ fontSize: 13 }}>Project:</Text>
                            <Select
                                placeholder="All Projects (Summary)"
                                value={selectedProject}
                                onChange={setSelectedProject}
                                allowClear
                                showSearch
                                optionFilterProp="label"
                                style={{ minWidth: 280 }}
                                loading={qualityLoading}
                                options={projects.map(p => ({ value: p.id, label: `${p.name} (${p.projectNumber})` }))}
                            />
                            {selectedProject && <Tag color={themeColor} style={{ borderRadius: 8, fontSize: 10 }}>Project-specific data loaded</Tag>}
                            {!selectedProject && <Text type="secondary" style={{ fontSize: 11 }}>Select a project to load metrics, checklists & inspections</Text>}
                        </div>
                    </Card>

                    {/* KPI Stats */}
                    <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
                        {statCards.map((s, i) => (
                            <Col xs={12} sm={8} md={4} key={i}>
                                <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}>
                                    <Card style={{ ...glassCard, borderTop: `3px solid ${s.color}` }} styles={{ body: { padding: '12px 14px' } }}>
                                        <Statistic title={<Text style={{ fontSize: 10 }}>{s.label}</Text>} value={s.value}
                                            prefix={s.icon} valueStyle={{ color: s.color, fontSize: 18 }} />
                                        {s.trend && (
                                            <div style={{ marginTop: 4, fontSize: 10, color: s.trend === 'up' ? '#10b981' : s.trend === 'down' ? '#ef4444' : '#64748b' }}>
                                                {s.trend === 'up' ? <RiseOutlined /> : s.trend === 'down' ? <FallOutlined /> : null}
                                                {' '}{s.trend === 'up' ? 'Improving' : s.trend === 'down' ? 'Declining' : 'Stable'}
                                            </div>
                                        )}
                                    </Card>
                                </motion.div>
                            </Col>
                        ))}
                    </Row>

                    {/* Tabs */}
                    {qualityLoading ? (
                        <div style={{ textAlign: 'center', padding: 60 }}><Spin /><div style={{ marginTop: 8 }}><Text type="secondary">Loading quality data…</Text></div></div>
                    ) : (
                        <Tabs defaultActiveKey="overview" items={tabItems} />
                    )}
                </motion.div>
            )}
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import RbacGuard from "@/components/common/RbacGuard";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { Button, Card, Col, Divider, Empty, message, Progress, Row, Select, Space, Spin, Statistic, Table, Tag, Tooltip, Typography, Skeleton } from "antd";
import {
    BarChartOutlined, ProjectOutlined, CheckCircleOutlined,
    ClockCircleOutlined, ExclamationCircleOutlined, DollarOutlined,
    TeamOutlined, FundProjectionScreenOutlined, DashboardOutlined,
    FireOutlined, AimOutlined, TrophyOutlined, WarningOutlined,
    RiseOutlined, FallOutlined, BulbOutlined, ThunderboltOutlined,
    NodeIndexOutlined, FileTextOutlined, SafetyCertificateOutlined,
    AlertOutlined, RocketOutlined, ForkOutlined, FileExcelOutlined, FilePdfOutlined,
    ReloadOutlined, InfoCircleOutlined } from "@ant-design/icons";
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip as RTooltip, CartesianGrid, Legend } from 'recharts';
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useDateRangeStore } from "@/store/useDateRangeStore";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text, Title } = Typography;

const GET_PORTFOLIO = `
  query GetPortfolioSummary($tenantId: String!) {
    pmPortfolioSummary(tenantId: $tenantId)
  }
`;

const GET_ALL_TASKS = `
  query GetAllTasks($tenantId: String!) {
    pmTasks(tenantId: $tenantId) {
      id projectId status priority type assigneeId
      assignee { id firstName lastName }
      estimatedHours loggedHours dueDate createdAt
    }
  }
`;

const GENERATE_STATUS_REPORT = `
  query GenerateStatusReport($projectId: String!) {
    generateStatusReport(projectId: $projectId)
  }
`;

const GENERATE_CRITICAL_PATH = `
  query GenerateCriticalPath($projectId: String!) {
    generateCriticalPath(projectId: $projectId)
  }
`;

const STATUS_CONFIG: Record<string, { color: string; label: string }> = {
    active: { color: '#10b981', label: 'Active' },
    planning: { color: '#6366f1', label: 'Planning' },
    paused: { color: '#f59e0b', label: 'Paused' },
    completed: { color: '#22c55e', label: 'Completed' },
    cancelled: { color: '#ef4444', label: 'Cancelled' },
};

export default function ReportsPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [projects, setProjects] = useState<any[]>([]);
    const [tasks, setTasks] = useState<any[]>([]);
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    const [showAllTeam, setShowAllTeam] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    // ── AI Feature State ──
    const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
    const [statusReport, setStatusReport] = useState<any>(null);
    const [statusReportLoading, setStatusReportLoading] = useState(false);
    const [criticalPath, setCriticalPath] = useState<any>(null);
    const [criticalPathLoading, setCriticalPathLoading] = useState(false);
    const [messageApi, contextHolder] = message.useMessage();

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [portData, taskData] = await Promise.all([
                gql(GET_PORTFOLIO, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_ALL_TASKS, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setProjects(portData.pmPortfolioSummary || []);
            setTasks(taskData.pmTasks || []);
        } catch (err: any) {
            messageApi.error("Failed to load reports data: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Computed Metrics ──
    const totalProjects = projects.length;
    const activeProjects = projects.filter(p => p.status === 'active').length;
    const completedProjects = projects.filter(p => p.status === 'completed').length;

    const totalTasks = tasks.length;
    const tasksDone = tasks.filter(t => t.status === 'done').length;
    const tasksInProgress = tasks.filter(t => t.status === 'in_progress').length;
    const tasksTodo = tasks.filter(t => t.status === 'todo').length;
    const tasksBlocked = tasks.filter(t => t.status === 'blocked').length;
    const tasksOverdue = tasks.filter(t =>
        t.dueDate && dayjs(t.dueDate).isBefore(dayjs()) && t.status !== 'done'
    ).length;

    const totalEstimated = tasks.reduce((s, t) => s + (t.estimatedHours || 0), 0);
    const totalLogged = tasks.reduce((s, t) => s + (t.loggedHours || 0), 0);
    const effortVariance = totalEstimated > 0 ? Math.round(((totalLogged - totalEstimated) / totalEstimated) * 100) : 0;

    const totalBudget = projects.reduce((s, p) => s + (p.budget || 0), 0);
    const totalSpent = projects.reduce((s, p) => s + (p.spent || 0), 0);
    const budgetVariance = totalBudget > 0 ? Math.round(((totalSpent - totalBudget) / totalBudget) * 100) : 0;

    // ── Priority Distribution ──
    const priorityDist = useMemo(() => {
        const buckets: Record<string, number> = { critical: 0, high: 0, medium: 0, low: 0 };
        tasks.forEach(t => { if (buckets[t.priority] !== undefined) buckets[t.priority]++; });
        return buckets;
    }, [tasks]);

    // ── Type Distribution ──
    const typeDist = useMemo(() => {
        const buckets: Record<string, number> = {};
        tasks.forEach(t => { buckets[t.type] = (buckets[t.type] || 0) + 1; });
        return buckets;
    }, [tasks]);

    // ── Team Workload ──
    const teamWorkload = useMemo(() => {
        const map = new Map<string, { name: string; total: number; done: number; inProgress: number; hours: number }>();
        tasks.forEach(t => {
            const key = t.assigneeId || '__unassigned__';
            const name = t.assignee ? `${t.assignee.firstName} ${t.assignee.lastName}` : 'Unassigned';
            if (!map.has(key)) map.set(key, { name, total: 0, done: 0, inProgress: 0, hours: 0 });
            const entry = map.get(key)!;
            entry.total++;
            if (t.status === 'done') entry.done++;
            if (t.status === 'in_progress') entry.inProgress++;
            entry.hours += t.loggedHours || 0;
        });
        return Array.from(map.values()).sort((a, b) => b.total - a.total);
    }, [tasks]);

    // ── Project Health Scores ──
    const projectHealth = useMemo(() => {
        return projects
            .filter(p => p.status === 'active' || p.status === 'planning')
            .map(p => {
                const tc = p.taskCounts || { total: 0, done: 0, inProgress: 0 };
                const taskPct = tc.total > 0 ? Math.round((tc.done / tc.total) * 100) : 0;

                // Timeline health
                let timelineScore = 100;
                if (p.start_date && p.end_date) {
                    const totalDays = dayjs(p.end_date).diff(dayjs(p.start_date), 'day');
                    const elapsed = dayjs().diff(dayjs(p.start_date), 'day');
                    const timelinePct = totalDays > 0 ? Math.round((elapsed / totalDays) * 100) : 0;
                    const gap = timelinePct - taskPct;
                    if (gap > 20) timelineScore = 40;
                    else if (gap > 10) timelineScore = 70;
                }

                // Budget health
                let budgetScore = 100;
                if (p.budget && p.budget > 0) {
                    const budgetPct = Math.round(((p.spent || 0) / p.budget) * 100);
                    if (budgetPct > 100) budgetScore = 20;
                    else if (budgetPct > 85) budgetScore = 60;
                }

                const overallScore = Math.round((taskPct * 0.4 + timelineScore * 0.3 + budgetScore * 0.3));

                return {
                    id: p.id,
                    name: p.name,
                    project_number: p.project_number,
                    status: p.status,
                    priority: p.priority,
                    taskPct,
                    timelineScore,
                    budgetScore,
                    overallScore,
                    taskCounts: tc,
                };
            })
            .sort((a, b) => a.overallScore - b.overallScore);
    }, [projects]);

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(12px)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    // ── AI Handlers ──
    const handleGenerateStatusReport = async () => {
        if (!selectedProjectId) { messageApi.warning('Select a project first'); return; }
        setStatusReportLoading(true);
        try {
            const data = await gql(GENERATE_STATUS_REPORT, { projectId: selectedProjectId });
            setStatusReport(data.generateStatusReport);
            messageApi.success('Status report generated!');
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error('AI status report failed. Check your AI service.');
        } finally {
            setStatusReportLoading(false);
        }
    };

    const handleGenerateCriticalPath = async () => {
        if (!selectedProjectId) { messageApi.warning('Select a project first'); return; }
        setCriticalPathLoading(true);
        try {
            const data = await gql(GENERATE_CRITICAL_PATH, { projectId: selectedProjectId });
            setCriticalPath(data.generateCriticalPath);
            messageApi.success('Critical path analysis generated!');
        } catch (err: any) { console.error("PM Error", err); 
            messageApi.error('AI critical path failed. Check your AI service.');
        } finally {
            setCriticalPathLoading(false);
        }
    };

    const selectedProjectName = selectedProjectId
        ? projects.find(p => p.id === selectedProjectId)?.name || 'Selected Project'
        : null;

    const healthColumns = [
        {
            title: 'Project',
            dataIndex: 'name',
            key: 'name',
            render: (_: any, record: any) => (
                <div>
                    <a
                        onClick={() => router.push(`/admin/pm/dashboard?projectId=${record.id}`)}
                        style={{ fontWeight: 600, fontSize: 13 }}
                    >
                        {record.name}
                    </a>
                    <div style={{ fontSize: 10, color: isDark ? '#94a3b8' : '#888' }}>
                        {record.project_number}
                    </div>
                </div>
            ),
        },
        {
            title: 'Health Score',
            dataIndex: 'overallScore',
            key: 'overallScore',
            width: 130,
            sorter: (a: any, b: any) => a.overallScore - b.overallScore,
            render: (score: number) => {
                const color = score >= 75 ? '#10b981' : score >= 50 ? '#f59e0b' : '#ef4444';
                return (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <Progress
                            type="circle"
                            percent={score}
                            size={36}
                            strokeColor={color}
                            trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                            format={() => (
                                <span style={{ fontSize: 10, fontWeight: 700, color }}>{score}</span>
                            )}
                        />
                    </div>
                );
            },
        },
        {
            title: 'Tasks',
            key: 'tasks',
            width: 120,
            render: (_: any, record: any) => (
                <div>
                    <Progress
                        percent={record.taskPct}
                        size="small"
                        strokeColor={record.taskPct >= 75 ? '#10b981' : record.taskPct >= 40 ? '#f59e0b' : '#6366f1'}
                        trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                    />
                    <Text type="secondary" style={{ fontSize: 10 }}>
                        {record.taskCounts.done}/{record.taskCounts.total}
                    </Text>
                </div>
            ),
        },
        {
            title: 'Timeline',
            key: 'timeline',
            width: 90,
            render: (_: any, record: any) => {
                const color = record.timelineScore >= 75 ? '#10b981' : record.timelineScore >= 50 ? '#f59e0b' : '#ef4444';
                const icon = record.timelineScore >= 75 ? <CheckCircleOutlined /> : record.timelineScore >= 50 ? <ClockCircleOutlined /> : <WarningOutlined />;
                return <Tag color={color} icon={icon} style={{ fontSize: 10 }}>{record.timelineScore}%</Tag>;
            },
        },
        {
            title: 'Budget',
            key: 'budget',
            width: 90,
            render: (_: any, record: any) => {
                const color = record.budgetScore >= 75 ? '#10b981' : record.budgetScore >= 50 ? '#f59e0b' : '#ef4444';
                const icon = record.budgetScore >= 75 ? <CheckCircleOutlined /> : record.budgetScore >= 50 ? <ClockCircleOutlined /> : <WarningOutlined />;
                return <Tag color={color} icon={icon} style={{ fontSize: 10 }}>{record.budgetScore}%</Tag>;
            },
        },
        {
            title: 'Status',
            dataIndex: 'status',
            key: 'status',
            width: 90,
            render: (status: string) => {
                const cfg = STATUS_CONFIG[status] || { color: '#6b7280', label: status };
                return <Tag color={cfg.color} style={{ textTransform: 'capitalize' as const, fontSize: 10 }}>{cfg.label}</Tag>;
            },
        },
    ];

    if (loading) {
        return (
            <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Reports</AuroraText>}
            subTitle={<DecryptedText text="Portfolio analytics & insights" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[<Tooltip key="refresh" title="Refresh data"><Button icon={<ReloadOutlined />} size="small" onClick={loadData} /></Tooltip>, <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'pm_reports', title: 'PM Portfolio Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'priority' }, { header: 'Budget', key: 'budget' }, { header: 'Spent', key: 'spent' }], data: projects })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'pm_reports', title: 'PM Portfolio Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'priority' }, { header: 'Budget', key: 'budget' }, { header: 'Spent', key: 'spent' }], data: projects })} /></Tooltip></RbacGuard>]}>
                <div style={{ padding: '24px 0' }}>
                    <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                        {[1, 2, 3, 4, 5, 6].map(i => (
                            <Col xs={24} sm={12} lg={4} key={i}>
                                <Card style={{ ...glassCard, height: 90 }} size="small">
                                    <Skeleton active paragraph={{ rows: 1 }} title={false} />
                                </Card>
                            </Col>
                        ))}
                    </Row>
                    <Row gutter={[16, 16]}>
                        <Col xs={24} md={12}>
                            <Card style={{ ...glassCard, height: 300 }} size="small">
                                <Skeleton active paragraph={{ rows: 6 }} />
                            </Card>
                        </Col>
                        <Col xs={24} md={12}>
                            <Card style={{ ...glassCard, height: 300 }} size="small">
                                <Skeleton active paragraph={{ rows: 6 }} />
                            </Card>
                        </Col>
                    </Row>
                </div>
            </CMSLayout>
        );
    }

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Reports</AuroraText>}
            subTitle={<DecryptedText text="Portfolio analytics & insights" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={[<Tooltip key="refresh" title="Refresh data"><Button icon={<ReloadOutlined />} size="small" onClick={loadData} /></Tooltip>, <RbacGuard requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({ fileName: 'pm_reports', title: 'PM Portfolio Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'priority' }, { header: 'Budget', key: 'budget' }, { header: 'Spent', key: 'spent' }], data: projects })} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({ fileName: 'pm_reports', title: 'PM Portfolio Report', dateRange: { start: startDate, end: endDate }, columns: [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Priority', key: 'priority' }, { header: 'Budget', key: 'budget' }, { header: 'Spent', key: 'spent' }], data: projects })} /></Tooltip></RbacGuard>]}>
            {contextHolder}

            {/* ── Executive Summary ── */}
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.4 }}>
            <BentoGrid className="max-w-full mb-6">
                {[
                    { label: 'Total Projects', value: totalProjects, icon: <ProjectOutlined />, color: '#6366f1' },
                    { label: 'Task Completion', value: totalTasks > 0 ? Math.round((tasksDone / totalTasks) * 100) : 0, suffix: '%', icon: <CheckCircleOutlined />, color: '#10b981' },
                    { label: 'Budget Used', value: totalBudget > 0 ? Math.round((totalSpent / totalBudget) * 100) : 0, suffix: '%', icon: <DollarOutlined />, color: totalSpent > totalBudget ? '#ef4444' : '#f59e0b' },
                    { label: 'Overdue Tasks', value: tasksOverdue, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                    { label: 'Effort Variance', value: effortVariance, suffix: '%', icon: effortVariance > 0 ? <RiseOutlined /> : <FallOutlined />, color: effortVariance > 0 ? '#ef4444' : '#10b981' },
                    { label: 'Team Members', value: teamWorkload.filter(t => t.name !== 'Unassigned').length, icon: <TeamOutlined />, color: '#3b82f6' },
                ].map((s, i) => (
                    <BentoGridItem
                        key={i}
                        title={s.label}
                        description="Executive metric"
                        icon={<span style={{ color: s.color }}>{s.icon}</span>}
                        header={
                            <div className="flex h-full w-full items-center justify-center rounded-xl" style={{ backgroundColor: `${s.color}15` }}>
                                <div style={{ fontSize: 32, fontWeight: 800, color: s.color }}>
                                    {s.value}
                                    {s.suffix && <span style={{ fontSize: 20 }}>{s.suffix}</span>}
                                </div>
                            </div>
                        }
                        className="col-span-6 md:col-span-3 lg:col-span-2"
                    />
                ))}
            </BentoGrid>
            </motion.div>

            {/* ── Task Status Distribution & Priority Distribution (Recharts) ── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                <Col xs={24} md={12}>
                    <Card size="small" title={<Space><BarChartOutlined style={{ color: themeColor }} />Task Status Distribution</Space>} style={glassCard}>
                        <div style={{ height: 220 }}>
                            <ResponsiveContainer>
                                <PieChart>
                                    <Pie
                                        data={[
                                            { name: 'Done', value: tasks.filter(t => t.status === 'done').length, color: '#10b981' },
                                            { name: 'In Progress', value: tasks.filter(t => t.status === 'in_progress').length, color: '#3b82f6' },
                                            { name: 'To Do', value: tasks.filter(t => t.status === 'todo').length, color: '#6366f1' },
                                            { name: 'In Review', value: tasks.filter(t => t.status === 'in_review').length, color: '#8b5cf6' },
                                            { name: 'Blocked', value: tasks.filter(t => t.status === 'blocked').length, color: '#ef4444' },
                                        ].filter(d => d.value > 0)}
                                        dataKey="value"
                                        nameKey="name"
                                        cx="50%" cy="50%"
                                        innerRadius={55} outerRadius={85}
                                        paddingAngle={3}
                                        strokeWidth={0}
                                    >
                                        {[
                                            { name: 'Done', value: tasks.filter(t => t.status === 'done').length, color: '#10b981' },
                                            { name: 'In Progress', value: tasks.filter(t => t.status === 'in_progress').length, color: '#3b82f6' },
                                            { name: 'To Do', value: tasks.filter(t => t.status === 'todo').length, color: '#6366f1' },
                                            { name: 'In Review', value: tasks.filter(t => t.status === 'in_review').length, color: '#8b5cf6' },
                                            { name: 'Blocked', value: tasks.filter(t => t.status === 'blocked').length, color: '#ef4444' },
                                        ].filter(d => d.value > 0).map((entry, i) => (
                                            <Cell key={i} fill={entry.color} />
                                        ))}
                                    </Pie>
                                    <RTooltip />
                                </PieChart>
                            </ResponsiveContainer>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 12, marginTop: 4 }}>
                            {[{ name: 'Done', color: '#10b981' }, { name: 'In Progress', color: '#3b82f6' }, { name: 'To Do', color: '#6366f1' }, { name: 'In Review', color: '#8b5cf6' }, { name: 'Blocked', color: '#ef4444' }].map(s => (
                                <div key={s.name} style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11 }}>
                                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: s.color }} />
                                    <span style={{ color: isDark ? '#94a3b8' : '#64748b' }}>{s.name}</span>
                                </div>
                            ))}
                        </div>
                    </Card>
                </Col>
                <Col xs={24} md={12}>
                    <Card size="small" title={<Space><FireOutlined style={{ color: '#ef4444' }} />Priority Distribution</Space>} style={glassCard}>
                        <div style={{ height: 250 }}>
                            <ResponsiveContainer>
                                <BarChart data={[
                                    { name: 'Critical', count: priorityDist.critical, fill: '#ef4444' },
                                    { name: 'High', count: priorityDist.high, fill: '#f59e0b' },
                                    { name: 'Medium', count: priorityDist.medium, fill: '#3b82f6' },
                                    { name: 'Low', count: priorityDist.low, fill: '#6b7280' },
                                ]} layout="vertical" margin={{ left: 10, right: 20 }}>
                                    <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)'} />
                                    <XAxis type="number" tick={{ fontSize: 11, fill: isDark ? '#94a3b8' : '#64748b' }} />
                                    <YAxis type="category" dataKey="name" tick={{ fontSize: 11, fill: isDark ? '#94a3b8' : '#64748b' }} width={60} />
                                    <RTooltip />
                                    <Bar dataKey="count" radius={[0, 6, 6, 0]}>
                                        {[
                                            { fill: '#ef4444' },
                                            { fill: '#f59e0b' },
                                            { fill: '#3b82f6' },
                                            { fill: '#6b7280' },
                                        ].map((entry, i) => (
                                            <Cell key={i} fill={entry.fill} />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </Col>
            </Row>

            {/* ── Effort & Budget Analytics ── */}
            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                <Col xs={24} lg={12}>
                    <Card
                        title={<Space><ClockCircleOutlined style={{ color: themeColor }} /> Effort Analytics</Space>}
                        size="small"
                        style={glassCard}
                    >
                        <Row gutter={16}>
                            <Col span={12}>
                                <Statistic
                                    title={<span style={{ fontSize: 11 }}>Estimated Hours</span>}
                                    value={totalEstimated}
                                    suffix="h"
                                    valueStyle={{ fontSize: 20, fontWeight: 600 }}
                                />
                            </Col>
                            <Col span={12}>
                                <Statistic
                                    title={<span style={{ fontSize: 11 }}>Logged Hours</span>}
                                    value={totalLogged}
                                    suffix="h"
                                    valueStyle={{ fontSize: 20, fontWeight: 600, color: totalLogged > totalEstimated ? '#ef4444' : '#10b981' }}
                                />
                            </Col>
                        </Row>
                        <Progress
                            percent={totalEstimated > 0 ? Math.min(100, Math.round((totalLogged / totalEstimated) * 100)) : 0}
                            strokeColor={totalLogged > totalEstimated ? '#ef4444' : { '0%': 'var(--theme-color, #8b5cf6)', '100%': 'var(--theme-secondary, #6366f1)' }}
                            trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                            style={{ marginTop: 12 }}
                        />
                    </Card>
                </Col>
                <Col xs={24} lg={12}>
                    <Card
                        title={<Space><DollarOutlined style={{ color: '#f59e0b' }} /> Budget Analytics</Space>}
                        size="small"
                        style={glassCard}
                    >
                        <Row gutter={16}>
                            <Col span={12}>
                                <Statistic
                                    title={<span style={{ fontSize: 11 }}>Total Budget</span>}
                                    value={totalBudget}
                                    prefix="$"
                                    valueStyle={{ fontSize: 20, fontWeight: 600 }}
                                />
                            </Col>
                            <Col span={12}>
                                <Statistic
                                    title={<span style={{ fontSize: 11 }}>Total Spent</span>}
                                    value={totalSpent}
                                    prefix="$"
                                    valueStyle={{ fontSize: 20, fontWeight: 600, color: totalSpent > totalBudget ? '#ef4444' : '#10b981' }}
                                />
                            </Col>
                        </Row>
                        <Progress
                            percent={totalBudget > 0 ? Math.min(100, Math.round((totalSpent / totalBudget) * 100)) : 0}
                            strokeColor={totalSpent > totalBudget ? '#ef4444' : { '0%': '#f59e0b', '100%': '#10b981' }}
                            trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                            style={{ marginTop: 12 }}
                        />
                    </Card>
                </Col>
            </Row>

            {/* ── Team Workload ── */}
            <Card
                title={<Space><TeamOutlined style={{ color: '#3b82f6' }} /> Team Workload</Space>}
                size="small"
                style={{ ...glassCard, marginBottom: 24 }}
            >
                {teamWorkload.length === 0 ? (
                    <Empty description="No tasks assigned yet." />
                ) : (
                    <>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                        {(showAllTeam ? teamWorkload : teamWorkload.slice(0, 10)).map((member, i) => {
                            const donePct = member.total > 0 ? Math.round((member.done / member.total) * 100) : 0;
                            return (
                                <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                                    <Text style={{ width: 140, fontSize: 12, fontWeight: 500 }}>
                                        {member.name === 'Unassigned' ? (
                                            <Text type="secondary" style={{ fontSize: 12 }}>Unassigned</Text>
                                        ) : member.name}
                                    </Text>
                                    <Progress
                                        percent={donePct}
                                        size="small"
                                        strokeColor={donePct >= 80 ? '#10b981' : donePct >= 40 ? '#f59e0b' : '#6366f1'}
                                        trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                                        style={{ flex: 1 }}
                                    />
                                    <Text type="secondary" style={{ fontSize: 10, width: 100, textAlign: 'right' }}>
                                        {member.done}/{member.total} tasks • {member.hours}h
                                    </Text>
                                </div>
                            );
                        })}
                    </div>
                    {teamWorkload.length > 10 && (
                        <div style={{ textAlign: 'center', marginTop: 8 }}>
                            <Button type="link" size="small" onClick={() => setShowAllTeam(v => !v)}>
                                {showAllTeam ? 'Show Less' : `Show All (${teamWorkload.length})`}
                            </Button>
                        </div>
                    )}
                    </>
                )}
            </Card>

            {/* ── Project Health Scorecard ── */}
            <Card
                title={
                    <Space>
                        <SafetyCertificateOutlined style={{ color: themeColor }} />
                        <span style={{ fontWeight: 600 }}>Project Health Scorecard</span>
                        <Tooltip title="Score = 40% task completion + 30% timeline health + 30% budget health"><InfoCircleOutlined style={{ color: isDark ? '#64748b' : '#94a3b8', fontSize: 12 }} /></Tooltip>
                        <Tag color="purple">{projectHealth.length}</Tag>
                    </Space>
                }
                style={glassCard}
            >
                {projectHealth.length === 0 ? (
                    <Empty description="No active projects to score." />
                ) : (
                    <Table scroll={{ x: 900 }}
                        dataSource={projectHealth}
                        columns={healthColumns}
                        rowKey="id"
                        pagination={false}
                        size="small"
                        style={{ fontSize: 13 }}
                        onRow={(record) => ({
                            onClick: () => router.push(`/admin/pm/dashboard?projectId=${record.id}`),
                            style: { cursor: 'pointer' },
                        })}
                    />
                )}
            </Card>

            {/* ── Type Distribution ── */}
            {Object.keys(typeDist).length > 0 && (
                <Card
                    title={<Space><FundProjectionScreenOutlined style={{ color: themeColor }} /> Task Type Distribution</Space>}
                    size="small"
                    style={{ ...glassCard, marginTop: 16 }}
                >
                    <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                        {Object.entries(typeDist).sort((a, b) => b[1] - a[1]).map(([type, count]) => {
                            const color = type === 'bug' ? '#ef4444' : type === 'story' ? '#10b981' : type === 'epic' ? 'var(--theme-color, #8b5cf6)' : '#3b82f6';
                            const pct = totalTasks > 0 ? Math.round((count / totalTasks) * 100) : 0;
                            return (
                                <Card key={type} size="small" hoverable style={{
                                    flex: '1 1 120px', maxWidth: 160, textAlign: 'center',
                                    borderTop: `3px solid ${color}`,
                                }}>
                                    <div style={{ fontSize: 22, fontWeight: 700, color }}>{count}</div>
                                    <Text style={{ fontSize: 12, textTransform: 'capitalize' }}>{type}</Text>
                                    <div>
                                        <Text type="secondary" style={{ fontSize: 10 }}>{pct}% of total</Text>
                                    </div>
                                </Card>
                            );
                        })}
                    </div>
                </Card>
            )}

            {/* ═══════════════════════════════════════════════════════════════ */}
            {/* ─── AI-POWERED INSIGHTS ─────────────────────────────────────── */}
            {/* ═══════════════════════════════════════════════════════════════ */}

            <Divider style={{ borderColor: isDark ? 'rgba(139,92,246,0.2)' : 'rgba(0,0,0,0.06)' }}>
                <Space>
                    <BulbOutlined style={{ color: '#f59e0b' }} />
                    <Text strong style={{ fontSize: 14, letterSpacing: 0.5 }}>AI-Powered Insights</Text>
                </Space>
            </Divider>

            {/* ── Project Selector for AI ── */}
            <Card
                size="small"
                style={{ ...glassCard, marginBottom: 20, borderTop: `3px solid ${themeColor}` }}
            >
                <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
                    <BulbOutlined style={{ fontSize: 18, color: '#f59e0b' }} />
                    <Text strong style={{ fontSize: 13 }}>Select a project for AI analysis:</Text>
                    <Select
                        placeholder="Choose a project…"
                        value={selectedProjectId}
                        onChange={(val) => {
                            setSelectedProjectId(val);
                            setStatusReport(null);
                            setCriticalPath(null);
                        }}
                        style={{ minWidth: 260 }}
                        allowClear
                        showSearch
                        optionFilterProp="label"
                        options={projects.filter(p => p.status === 'active' || p.status === 'planning').map(p => ({
                            value: p.id,
                            label: `${p.name} (${p.project_number})`,
                        }))}
                    />
                    <Button
                        type="primary"
                        icon={<FileTextOutlined />}
                        loading={statusReportLoading}
                        onClick={handleGenerateStatusReport}
                        disabled={!selectedProjectId}
                        style={{ borderRadius: 8, background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)` }}
                    >
                        Generate Status Report
                    </Button>
                    <Button
                        icon={<ForkOutlined />}
                        loading={criticalPathLoading}
                        onClick={handleGenerateCriticalPath}
                        disabled={!selectedProjectId}
                        style={{ borderRadius: 8 }}
                    >
                        Analyze Critical Path
                    </Button>
                </div>
            </Card>

            {/* ── AI Status Report ── */}
            {statusReport && (
                <Card
                    title={
                        <Space>
                            <FileTextOutlined style={{ color: themeColor }} />
                            <span style={{ fontWeight: 600 }}>AI Status Report</span>
                            {selectedProjectName && (
                                <Tag color="purple" style={{ fontSize: 10, borderRadius: 8 }}>{selectedProjectName}</Tag>
                            )}
                        </Space>
                    }
                    size="small"
                    style={{ ...glassCard, marginBottom: 20 }}
                    extra={
                        statusReport.reportDate && (
                            <Text type="secondary" style={{ fontSize: 11 }}>{statusReport.reportDate}</Text>
                        )
                    }
                >
                    {/* Health Score + Executive Summary */}
                    <div style={{
                        display: 'flex', alignItems: 'center', gap: 16, padding: '14px 18px',
                        borderRadius: 14, marginBottom: 16,
                        background: isDark ? 'rgba(99,102,241,0.08)' : 'rgba(99,102,241,0.04)',
                        border: '1px solid rgba(99,102,241,0.15)',
                    }}>
                        <Progress
                            type="circle" percent={statusReport.healthScore || 0} size={64}
                            strokeColor={
                                (statusReport.healthScore || 0) >= 70 ? '#10b981'
                                    : (statusReport.healthScore || 0) >= 40 ? '#f59e0b' : '#ef4444'
                            }
                            format={(pct) => <span style={{ fontSize: 16, fontWeight: 700 }}>{pct}</span>}
                        />
                        <div style={{ flex: 1 }}>
                            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 4 }}>
                                <Text strong style={{ fontSize: 14 }}>Project Health</Text>
                                {statusReport.overallHealth && (
                                    <Tag color={
                                        statusReport.overallHealth === 'green' ? 'green'
                                            : statusReport.overallHealth === 'yellow' ? 'orange' : 'red'
                                    } style={{ fontSize: 10, borderRadius: 8, textTransform: 'uppercase' }}>
                                        {statusReport.overallHealth}
                                    </Tag>
                                )}
                                {statusReport.scheduleAssessment && (
                                    <Tag color={
                                        statusReport.scheduleAssessment === 'on_track' ? 'green'
                                            : statusReport.scheduleAssessment === 'at_risk' ? 'orange' : 'red'
                                    } style={{ fontSize: 10, borderRadius: 8 }}>
                                        Schedule: {statusReport.scheduleAssessment?.replace('_', ' ')}
                                    </Tag>
                                )}
                                {statusReport.budgetAssessment && (
                                    <Tag color={
                                        statusReport.budgetAssessment === 'on_track' ? 'green'
                                            : statusReport.budgetAssessment === 'at_risk' ? 'orange' : 'red'
                                    } style={{ fontSize: 10, borderRadius: 8 }}>
                                        Budget: {statusReport.budgetAssessment?.replace('_', ' ')}
                                    </Tag>
                                )}
                            </div>
                            <Text type="secondary" style={{ fontSize: 12 }}>
                                {statusReport.executiveSummary}
                            </Text>
                        </div>
                    </div>

                    <Row gutter={[16, 16]}>
                        {/* Accomplishments */}
                        {statusReport.accomplishments && statusReport.accomplishments.length > 0 && (
                            <Col xs={24} md={12}>
                                <div style={{
                                    padding: '12px 14px', borderRadius: 12,
                                    background: isDark ? 'rgba(16,185,129,0.06)' : 'rgba(16,185,129,0.03)',
                                    border: '1px solid rgba(16,185,129,0.12)',
                                    height: '100%',
                                }}>
                                    <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: '#10b981' }}>
                                        <CheckCircleOutlined style={{ marginRight: 6 }} />
                                        Accomplishments
                                    </Text>
                                    {statusReport.accomplishments.map((item: string, idx: number) => (
                                        <div key={idx} style={{ display: 'flex', gap: 6, marginBottom: 4, alignItems: 'flex-start' }}>
                                            <span style={{ color: '#10b981', fontWeight: 700, fontSize: 11 }}>✓</span>
                                            <Text style={{ fontSize: 11 }}>{item}</Text>
                                        </div>
                                    ))}
                                </div>
                            </Col>
                        )}

                        {/* Next Period Goals */}
                        {statusReport.nextPeriodGoals && statusReport.nextPeriodGoals.length > 0 && (
                            <Col xs={24} md={12}>
                                <div style={{
                                    padding: '12px 14px', borderRadius: 12,
                                    background: isDark ? 'rgba(99,102,241,0.06)' : 'rgba(99,102,241,0.03)',
                                    border: '1px solid rgba(99,102,241,0.12)',
                                    height: '100%',
                                }}>
                                    <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: themeColor }}>
                                        <RocketOutlined style={{ marginRight: 6 }} />
                                        Next Period Goals
                                    </Text>
                                    {statusReport.nextPeriodGoals.map((item: string, idx: number) => (
                                        <div key={idx} style={{ display: 'flex', gap: 6, marginBottom: 4, alignItems: 'flex-start' }}>
                                            <span style={{ color: themeColor, fontWeight: 700, fontSize: 11 }}>→</span>
                                            <Text style={{ fontSize: 11 }}>{item}</Text>
                                        </div>
                                    ))}
                                </div>
                            </Col>
                        )}

                        {/* Blockers */}
                        {statusReport.blockers && statusReport.blockers.length > 0 && (
                            <Col xs={24} md={12}>
                                <div style={{
                                    padding: '12px 14px', borderRadius: 12,
                                    background: isDark ? 'rgba(239,68,68,0.06)' : 'rgba(239,68,68,0.03)',
                                    border: '1px solid rgba(239,68,68,0.12)',
                                    height: '100%',
                                }}>
                                    <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: '#ef4444' }}>
                                        <ExclamationCircleOutlined style={{ marginRight: 6 }} />
                                        Blockers
                                    </Text>
                                    {statusReport.blockers.map((item: string, idx: number) => (
                                        <div key={idx} style={{ display: 'flex', gap: 6, marginBottom: 4, alignItems: 'flex-start' }}>
                                            <span style={{ color: '#ef4444', fontWeight: 700, fontSize: 11 }}>⚠</span>
                                            <Text style={{ fontSize: 11 }}>{item}</Text>
                                        </div>
                                    ))}
                                </div>
                            </Col>
                        )}

                        {/* Risk Highlights */}
                        {statusReport.riskHighlights && statusReport.riskHighlights.length > 0 && (
                            <Col xs={24} md={12}>
                                <div style={{
                                    padding: '12px 14px', borderRadius: 12,
                                    background: isDark ? 'rgba(245,158,11,0.06)' : 'rgba(245,158,11,0.03)',
                                    border: '1px solid rgba(245,158,11,0.12)',
                                    height: '100%',
                                }}>
                                    <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: '#f59e0b' }}>
                                        <WarningOutlined style={{ marginRight: 6 }} />
                                        Risk Highlights
                                    </Text>
                                    {statusReport.riskHighlights.map((risk: any, idx: number) => (
                                        <div key={idx} style={{
                                            padding: '6px 10px', marginBottom: 4, borderRadius: 8,
                                            background: isDark ? 'rgba(255,255,255,0.02)' : 'rgba(0,0,0,0.01)',
                                        }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                                <Tag
                                                    color={risk.severity === 'high' ? 'red' : risk.severity === 'medium' ? 'orange' : 'blue'}
                                                    style={{ fontSize: 9, borderRadius: 6, margin: 0 }}
                                                >
                                                    {(risk.severity || 'info').toUpperCase()}
                                                </Tag>
                                                <Text style={{ fontSize: 11 }}>{risk.risk}</Text>
                                            </div>
                                            {risk.mitigation && (
                                                <Text type="secondary" style={{ fontSize: 10, display: 'block', marginTop: 2, paddingLeft: 4 }}>
                                                    Mitigation: {risk.mitigation}
                                                </Text>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </Col>
                        )}
                    </Row>

                    {/* Recommendations */}
                    {statusReport.recommendations && statusReport.recommendations.length > 0 && (
                        <div style={{ marginTop: 14 }}>
                            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8 }}>
                                <BulbOutlined style={{ color: '#f59e0b', marginRight: 6 }} />
                                Recommendations
                            </Text>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                                {statusReport.recommendations.map((rec: string, idx: number) => (
                                    <div key={idx} style={{
                                        padding: '8px 12px', borderRadius: 8,
                                        background: isDark ? 'rgba(139,92,246,0.06)' : 'rgba(139,92,246,0.03)',
                                        border: '1px solid rgba(139,92,246,0.1)',
                                        display: 'flex', gap: 8, alignItems: 'flex-start',
                                    }}>
                                        <span style={{ color: themeColor, fontWeight: 700, fontSize: 11 }}>💡</span>
                                        <Text style={{ fontSize: 11 }}>{rec}</Text>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </Card>
            )}

            {/* ── AI Critical Path Analysis ── */}
            {criticalPath && (
                <Card
                    title={
                        <Space>
                            <ForkOutlined style={{ color: themeColor }} />
                            <span style={{ fontWeight: 600 }}>Critical Path Analysis</span>
                            {selectedProjectName && (
                                <Tag color="purple" style={{ fontSize: 10, borderRadius: 8 }}>{selectedProjectName}</Tag>
                            )}
                        </Space>
                    }
                    size="small"
                    style={{ ...glassCard, marginBottom: 20 }}
                >
                    {/* Summary + Risk to Timeline */}
                    <div style={{
                        display: 'flex', alignItems: 'center', gap: 16, padding: '14px 18px',
                        borderRadius: 14, marginBottom: 16, flexWrap: 'wrap',
                        background: isDark ? 'rgba(139,92,246,0.08)' : 'rgba(139,92,246,0.04)',
                        border: '1px solid rgba(139,92,246,0.15)',
                    }}>
                        <div style={{
                            width: 56, height: 56, borderRadius: 14,
                            background: (() => {
                                const r = criticalPath.riskToTimeline;
                                return r === 'high' ? 'linear-gradient(135deg, #ef4444, #f87171)'
                                    : r === 'medium' ? 'linear-gradient(135deg, #f59e0b, #fbbf24)'
                                        : 'linear-gradient(135deg, #10b981, #34d399)';
                            })(),
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            color: '#fff', fontSize: 22, fontWeight: 700,
                        }}>
                            <NodeIndexOutlined />
                        </div>
                        <div style={{ flex: 1, minWidth: 200 }}>
                            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 4 }}>
                                <Text strong style={{ fontSize: 14 }}>Schedule Analysis</Text>
                                {criticalPath.riskToTimeline && (
                                    <Tag color={
                                        criticalPath.riskToTimeline === 'high' ? 'red'
                                            : criticalPath.riskToTimeline === 'medium' ? 'orange' : 'green'
                                    } style={{ fontSize: 10, borderRadius: 8, textTransform: 'uppercase' }}>
                                        Risk: {criticalPath.riskToTimeline}
                                    </Tag>
                                )}
                            </div>
                            <Text type="secondary" style={{ fontSize: 12 }}>{criticalPath.summary}</Text>
                        </div>
                        <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
                            {criticalPath.totalCriticalPathDuration !== undefined && (
                                <div style={{ textAlign: 'center' }}>
                                    <div style={{ fontSize: 20, fontWeight: 800, color: themeColor }}>
                                        {criticalPath.totalCriticalPathDuration}
                                    </div>
                                    <Text type="secondary" style={{ fontSize: 10 }}>Critical Days</Text>
                                </div>
                            )}
                            {criticalPath.scheduleVariance !== undefined && (
                                <div style={{ textAlign: 'center' }}>
                                    <div style={{
                                        fontSize: 20, fontWeight: 800,
                                        color: criticalPath.scheduleVariance > 0 ? '#ef4444' : '#10b981',
                                    }}>
                                        {criticalPath.scheduleVariance > 0 ? '+' : ''}{criticalPath.scheduleVariance}
                                    </div>
                                    <Text type="secondary" style={{ fontSize: 10 }}>Variance (days)</Text>
                                </div>
                            )}
                            {criticalPath.expectedCompletionDate && (
                                <div style={{ textAlign: 'center' }}>
                                    <div style={{ fontSize: 14, fontWeight: 700, color: isDark ? '#e2e8f0' : '#1e293b' }}>
                                        {dayjs(criticalPath.expectedCompletionDate).format('MMM D, YYYY')}
                                    </div>
                                    <Text type="secondary" style={{ fontSize: 10 }}>Expected Completion</Text>
                                </div>
                            )}
                        </div>
                    </div>

                    <Row gutter={[16, 16]}>
                        {/* Critical Path Tasks */}
                        {criticalPath.criticalPathTasks && criticalPath.criticalPathTasks.length > 0 && (
                            <Col xs={24} lg={14}>
                                <div style={{
                                    padding: '12px 14px', borderRadius: 12,
                                    background: isDark ? 'rgba(239,68,68,0.05)' : 'rgba(239,68,68,0.02)',
                                    border: '1px solid rgba(239,68,68,0.1)',
                                }}>
                                    <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 10, color: '#ef4444' }}>
                                        <FireOutlined style={{ marginRight: 6 }} />
                                        Critical Path Tasks ({criticalPath.criticalPathTasks.length})
                                    </Text>
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                                        {criticalPath.criticalPathTasks.map((task: any, idx: number) => (
                                            <div key={idx} style={{
                                                display: 'flex', alignItems: 'center', gap: 10,
                                                padding: '8px 12px', borderRadius: 10,
                                                background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.01)',
                                                border: isDark ? '1px solid rgba(255,255,255,0.05)' : '1px solid rgba(0,0,0,0.03)',
                                            }}>
                                                <div style={{
                                                    width: 28, height: 28, borderRadius: 8,
                                                    background: task.isCritical ? 'linear-gradient(135deg, #ef4444, #f87171)' : 'linear-gradient(135deg, #6366f1, #818cf8)',
                                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                    color: '#fff', fontSize: 11, fontWeight: 700, flexShrink: 0,
                                                }}>
                                                    {idx + 1}
                                                </div>
                                                <div style={{ flex: 1, minWidth: 0 }}>
                                                    <Text style={{ fontSize: 12, fontWeight: 600, display: 'block' }}>
                                                        {task.taskTitle}
                                                    </Text>
                                                    <div style={{ display: 'flex', gap: 10, marginTop: 2, flexWrap: 'wrap' }}>
                                                        <Text type="secondary" style={{ fontSize: 10 }}>
                                                            ⏱ {task.estimatedDays} days
                                                        </Text>
                                                        {task.slack !== undefined && (
                                                            <Text type="secondary" style={{
                                                                fontSize: 10,
                                                                color: task.slack === 0 ? '#ef4444' : undefined,
                                                            }}>
                                                                Slack: {task.slack}d
                                                            </Text>
                                                        )}
                                                        {task.earliestStart && (
                                                            <Text type="secondary" style={{ fontSize: 10 }}>
                                                                {dayjs(task.earliestStart).format('MMM D')} → {dayjs(task.latestFinish).format('MMM D')}
                                                            </Text>
                                                        )}
                                                    </div>
                                                </div>
                                                {task.isCritical && (
                                                    <Tag color="red" style={{ fontSize: 9, borderRadius: 6, margin: 0 }}>CRITICAL</Tag>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </Col>
                        )}

                        {/* Non Critical + Bottlenecks + Recommendations */}
                        <Col xs={24} lg={10}>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                                {/* Non-Critical Tasks */}
                                {criticalPath.nonCriticalTasks && criticalPath.nonCriticalTasks.length > 0 && (
                                    <div style={{
                                        padding: '12px 14px', borderRadius: 12,
                                        background: isDark ? 'rgba(16,185,129,0.05)' : 'rgba(16,185,129,0.02)',
                                        border: '1px solid rgba(16,185,129,0.1)',
                                    }}>
                                        <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: '#10b981' }}>
                                            <SafetyCertificateOutlined style={{ marginRight: 6 }} />
                                            Non-Critical Tasks (with Float)
                                        </Text>
                                        {criticalPath.nonCriticalTasks.slice(0, 5).map((task: any, idx: number) => (
                                            <div key={idx} style={{
                                                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                                padding: '4px 0', borderBottom: idx < criticalPath.nonCriticalTasks.length - 1
                                                    ? `1px solid ${isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.03)'}` : 'none',
                                            }}>
                                                <Text style={{ fontSize: 11 }}>{task.taskTitle}</Text>
                                                <Tag style={{ fontSize: 9, borderRadius: 6, margin: 0 }} color="green">
                                                    +{task.totalFloat}d float
                                                </Tag>
                                            </div>
                                        ))}
                                    </div>
                                )}

                                {/* Bottlenecks */}
                                {criticalPath.bottlenecks && criticalPath.bottlenecks.length > 0 && (
                                    <div style={{
                                        padding: '12px 14px', borderRadius: 12,
                                        background: isDark ? 'rgba(245,158,11,0.06)' : 'rgba(245,158,11,0.03)',
                                        border: '1px solid rgba(245,158,11,0.12)',
                                    }}>
                                        <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: '#f59e0b' }}>
                                            <AlertOutlined style={{ marginRight: 6 }} />
                                            Bottlenecks
                                        </Text>
                                        {criticalPath.bottlenecks.map((item: string, idx: number) => (
                                            <div key={idx} style={{ display: 'flex', gap: 6, marginBottom: 3 }}>
                                                <span style={{ color: '#f59e0b', fontWeight: 700, fontSize: 11 }}>⚠</span>
                                                <Text style={{ fontSize: 11 }}>{item}</Text>
                                            </div>
                                        ))}
                                    </div>
                                )}

                                {/* Recommendations */}
                                {criticalPath.recommendations && criticalPath.recommendations.length > 0 && (
                                    <div style={{
                                        padding: '12px 14px', borderRadius: 12,
                                        background: isDark ? 'rgba(139,92,246,0.06)' : 'rgba(139,92,246,0.03)',
                                        border: '1px solid rgba(139,92,246,0.1)',
                                    }}>
                                        <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 8, color: themeColor }}>
                                            <BulbOutlined style={{ marginRight: 6 }} />
                                            Schedule Optimization
                                        </Text>
                                        {criticalPath.recommendations.map((rec: string, idx: number) => (
                                            <div key={idx} style={{ display: 'flex', gap: 6, marginBottom: 3 }}>
                                                <span style={{ color: themeColor, fontWeight: 700, fontSize: 11 }}>💡</span>
                                                <Text style={{ fontSize: 11 }}>{rec}</Text>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </Col>
                    </Row>
                </Card>
            )}

            {/* ── Empty state when no AI results ── */}
            {!statusReport && !criticalPath && selectedProjectId && (
                <Card
                    size="small"
                    style={{ ...glassCard, marginBottom: 20, textAlign: 'center' }}
                >
                    <div style={{ padding: 32 }}>
                        <BulbOutlined style={{ fontSize: 40, color: '#f59e0b', opacity: 0.4 }} />
                        <div style={{ marginTop: 8 }}>
                            <Text type="secondary" style={{ fontSize: 12 }}>
                                Click "Generate Status Report" or "Analyze Critical Path" above to get AI-powered insights for {selectedProjectName}.
                            </Text>
                        </div>
                    </div>
                </Card>
            )}
        </CMSLayout>
    );
}

