"use client";

import React, { useState, useEffect, useCallback, useMemo, useRef } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { Card, Col, Empty, Input, message, Progress, Row, Segmented, Select, Space, Spin, Statistic, Tag, Tooltip, Typography, Button } from "antd";
import {
    ProjectOutlined, CheckCircleOutlined, FlagOutlined,
    LeftOutlined, RightOutlined, SearchOutlined,
    AimOutlined, CalendarOutlined, RocketOutlined,
    DragOutlined, UndoOutlined, ReloadOutlined,
    FileExcelOutlined, FilePdfOutlined
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import dayjs from "dayjs";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import { useRouter } from "next/navigation";
import RbacGuard from "@/components/common/RbacGuard";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";

const { Text } = Typography;

const GET_PROJECTS = `
  query($tenantId: String!) {
    pmProjects(tenantId: $tenantId) {
      id name projectNumber status methodology startDate endDate budget description
    }
  }
`;

const GET_TASKS = `
  query($tenantId: String!) {
    pmTasks(tenantId: $tenantId) {
      id projectId title status priority type estimatedHours dueDate startDate
    }
  }
`;

const GET_MILESTONES = `
  query($projectId: String!) {
    pmMilestones(projectId: $projectId) {
      id name projectId targetDate status description
    }
  }
`;

const UPDATE_PROJECT = `
  mutation UpdateProject($id: ID!, $input: UpdatePmProjectInput!) {
    updatePmProject(id: $id, input: $input) {
      id name status startDate endDate
    }
  }
`;

const UPDATE_TASK = `
  mutation UpdateTask($id: ID!, $input: UpdatePmTaskInput!) {
    updatePmTask(id: $id, input: $input) {
      id title status startDate dueDate
    }
  }
`;

const STATUS_BAR_COLOR: Record<string, string> = {
    active: 'var(--theme-color, #8b5cf6)',
    completed: '#22c55e',
    planning: '#6b7280',
    on_hold: '#f59e0b',
    paused: '#f59e0b',
    cancelled: '#ef4444',
};

const MILESTONE_COLOR: Record<string, string> = {
    completed: '#22c55e',
    pending: '#f59e0b',
    overdue: '#ef4444',
};

const PRIORITY_COLOR: Record<string, string> = {
    critical: '#ef4444',
    high: '#f59e0b',
    medium: '#3b82f6',
    low: '#6b7280',
};

const ROADMAP_PROJECT_BAR = 'ROADMAP_PROJECT_BAR';
const ROADMAP_EPIC_BAR = 'ROADMAP_EPIC_BAR';

interface RoadmapDragItem {
    id: string;
    type: 'project' | 'epic';
    startDate: string;
    endDate: string;
    projectId?: string; // for epics
}

// ── DraggableProjectBar ──
function DraggableProjectBar({
    project,
    leftPct,
    widthPct,
    barColor,
    taskPct,
    isDark,
    themeColor,
    onExpand,
    isExpanded,
}: {
    project: any;
    leftPct: number;
    widthPct: number;
    barColor: string;
    taskPct: number;
    isDark: boolean;
    themeColor: string;
    onExpand: () => void;
    isExpanded: boolean;
}): React.ReactElement {
    const ref = useRef<HTMLDivElement>(null);

    const [{ isDragging }, drag] = useDrag<RoadmapDragItem, void, { isDragging: boolean }>(() => ({
        type: ROADMAP_PROJECT_BAR,
        item: {
            id: project.id,
            type: 'project' as const,
            startDate: project.startDate,
            endDate: project.endDate,
        },
        collect: (monitor) => ({
            isDragging: monitor.isDragging(),
        }),
    }), [project.id, project.startDate, project.endDate]);

    drag(ref);

    // unused tc removed

    return (
        <Tooltip title={
            <div style={{ fontSize: 12 }}>
                <div style={{ fontWeight: 700 }}>{project.name}</div>
                <div>{dayjs(project.startDate).format('MMM D, YYYY')} — {dayjs(project.endDate).format('MMM D, YYYY')}</div>
                <div>Tasks: ({taskPct}%)</div>
                {project.methodology && <div>Methodology: {project.methodology}</div>}
                <div style={{ marginTop: 4, color: '#94a3b8', fontSize: 11, display: 'flex', alignItems: 'center', gap: 4 }}>
                    <DragOutlined /> Drag to reschedule
                </div>
            </div>
        }>
            <div
                ref={ref}
                style={{
                    position: 'absolute',
                    left: `${leftPct}%`, width: `${widthPct}%`,
                    height: 24, top: 10, borderRadius: 6, cursor: isDragging ? 'grabbing' : 'grab',
                    background: `linear-gradient(135deg, ${barColor}cc, ${barColor}88)`,
                    border: `1px solid ${barColor}`,
                    display: 'flex', alignItems: 'center', paddingLeft: 8, overflow: 'hidden',
                    transition: isDragging ? 'none' : 'all 0.2s ease',
                    boxShadow: isDragging ? `0 4px 16px ${barColor}44` : `0 2px 8px ${barColor}22`,
                    opacity: isDragging ? 0.5 : 1,
                    zIndex: isDragging ? 20 : 1,
                }}
                onClick={() => onExpand()}
                onMouseEnter={e => {
                    if (!isDragging) {
                        e.currentTarget.style.filter = 'brightness(1.2)';
                        e.currentTarget.style.transform = 'scaleY(1.15)';
                        e.currentTarget.style.zIndex = '5';
                    }
                }}
                onMouseLeave={e => {
                    if (!isDragging) {
                        e.currentTarget.style.filter = 'brightness(1)';
                        e.currentTarget.style.transform = 'scaleY(1)';
                        e.currentTarget.style.zIndex = '1';
                    }
                }}
            >
                {/* Progress fill */}
                <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: `${taskPct}%`, background: `${barColor}44`, borderRadius: '6px 0 0 6px' }} />
                <Text style={{ fontSize: 10, fontWeight: 600, color: '#fff', position: 'relative', zIndex: 2, textShadow: '0 1px 2px rgba(0,0,0,0.3)' }}>{taskPct}%</Text>
            </div>
        </Tooltip>
    );
}

// ── DraggableEpicBar ──
function DraggableEpicBar({
    epic,
    ePct,
    eW,
    epicColor,
    projectStartDate,
    projectEndDate,
}: {
    epic: any;
    ePct: number;
    eW: number;
    epicColor: string;
    projectStartDate: string;
    projectEndDate: string;
}): React.ReactElement {
    const ref = useRef<HTMLDivElement>(null);
    const epicStart = epic.startDate || projectStartDate;
    const epicEnd = epic.dueDate || projectEndDate;

    const [{ isDragging }, drag] = useDrag<RoadmapDragItem, void, { isDragging: boolean }>(() => ({
        type: ROADMAP_EPIC_BAR,
        item: {
            id: epic.id,
            type: 'epic' as const,
            startDate: epicStart,
            endDate: epicEnd,
            projectId: epic.projectId,
        },
        collect: (monitor) => ({
            isDragging: monitor.isDragging(),
        }),
    }), [epic.id, epicStart, epicEnd]);

    drag(ref);

    return (
        <Tooltip title={
            <div>
                <div style={{ fontWeight: 600 }}>{epic.title}</div>
                <div>Priority: {epic.priority}</div>
                <div>Status: {epic.status}</div>
                <div style={{ marginTop: 4, color: '#94a3b8', fontSize: 11, display: 'flex', alignItems: 'center', gap: 4 }}>
                    <DragOutlined /> Drag to reschedule
                </div>
            </div>
        }>
            <div
                ref={ref}
                style={{
                    position: 'absolute', left: `${ePct}%`, width: `${eW}%`,
                    height: 16, top: 8, borderRadius: 4, cursor: isDragging ? 'grabbing' : 'grab',
                    background: `linear-gradient(135deg, ${epicColor}aa, ${epicColor}66)`,
                    border: `1px solid ${epicColor}88`,
                    transition: isDragging ? 'none' : 'all 0.2s ease',
                    opacity: isDragging ? 0.5 : 1,
                    boxShadow: isDragging ? `0 3px 12px ${epicColor}44` : 'none',
                    zIndex: isDragging ? 20 : 1,
                }}
            />
        </Tooltip>
    );
}

// ── RoadmapDropZone ──
function RoadmapDropZone({
    children,
    totalDays,
    onRescheduleProject,
    onRescheduleEpic,
    minWidth,
    isDark,
}: {
    children: React.ReactNode;
    totalDays: number;
    onRescheduleProject: (id: string, newStart: string, newEnd: string, oldStart: string, oldEnd: string) => void;
    onRescheduleEpic: (id: string, newStart: string, newEnd: string, oldStart: string, oldEnd: string) => void;
    minWidth: number;
    isDark: boolean;
}): React.ReactElement {
    const containerRef = useRef<HTMLDivElement>(null);

    const [{ isOver: isOverProject }, dropProject] = useDrop<RoadmapDragItem, void, { isOver: boolean }>(() => ({
        accept: [ROADMAP_PROJECT_BAR, ROADMAP_EPIC_BAR],
        drop: (item, monitor) => {
            const delta = monitor.getDifferenceFromInitialOffset();
            if (!delta || !containerRef.current) return;

            const containerWidth = containerRef.current.getBoundingClientRect().width;
            const deltaDays = Math.round((delta.x / containerWidth) * totalDays);

            if (deltaDays === 0) return;

            const newStart = dayjs(item.startDate).add(deltaDays, 'day').format('YYYY-MM-DD');
            const newEnd = dayjs(item.endDate).add(deltaDays, 'day').format('YYYY-MM-DD');

            if (item.type === 'project') {
                onRescheduleProject(item.id, newStart, newEnd, item.startDate, item.endDate);
            } else {
                onRescheduleEpic(item.id, newStart, newEnd, item.startDate, item.endDate);
            }
        },
        collect: (monitor) => ({
            isOver: monitor.isOver(),
        }),
    }), [totalDays, onRescheduleProject, onRescheduleEpic]);

    const setRef = useCallback((node: HTMLDivElement | null) => {
        (containerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        dropProject(node);
    }, [dropProject]);

    return (
        <div
            ref={setRef}
            style={{
                position: 'relative',
                minWidth,
                outline: isOverProject ? `2px dashed ${isDark ? 'rgba(139,92,246,0.4)' : 'rgba(99,102,241,0.3)'}` : 'none',
                outlineOffset: -2,
                borderRadius: 8,
                transition: 'outline 0.2s ease',
            }}
        >
            {children}
        </div>
    );
}


export default function RoadmapPage() {
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();
    const router = useRouter();
    const [projects, setProjects] = useState<any[]>([]);
    const [tasks, setTasks] = useState<any[]>([]);
    const [milestones, setMilestones] = useState<any[]>([]);
    const [statusFilter, setStatusFilter] = useState<string | null>(null);
    const [methodologyFilter, setMethodologyFilter] = useState<string | null>(null);
    const [search, setSearch] = useState('');
    const [zoom, setZoom] = useState<string>('Quarter');
    const [quarterOffset, setQuarterOffset] = useState(0);
    const [expandedProject, setExpandedProject] = useState<string | null>(null);
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    const [messageApi, contextHolder] = message.useMessage();
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [projData, taskData] = await Promise.all([
                gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_TASKS, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            const projs = projData.pmProjects || [];
            setProjects(projs);
            setTasks(taskData.pmTasks || []);
            // Load milestones for all projects
            const msResults = await Promise.all(
                projs.map((p: any) => gql(GET_MILESTONES, { projectId: p.id }).catch((e: any) => {
                    console.error(`Failed to load milestones for project ${p.id}:`, e);
                    return { pmMilestones: [] };
                }))
            );
            setMilestones(msResults.flatMap((r: any) => r.pmMilestones || []));
        } catch (err: any) {
            messageApi.error("Failed to load roadmap data: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Filtered projects ──
    const filteredProjects = useMemo(() => {
        return projects
            .filter(p => p.startDate && p.endDate)
            .filter(p => !statusFilter || p.status === statusFilter)
            .filter(p => !methodologyFilter || p.methodology === methodologyFilter)
            .filter(p => !search || p.name.toLowerCase().includes(search.toLowerCase()))
            .sort((a, b) => dayjs(a.startDate).unix() - dayjs(b.startDate).unix());
    }, [projects, statusFilter, methodologyFilter, search]);

    // ── Task counts per project ──
    const tasksByProject = useMemo(() => {
        const map = new Map<string, { total: number; done: number }>();
        tasks.forEach(t => {
            const entry = map.get(t.projectId) || { total: 0, done: 0 };
            entry.total++;
            if (t.status === 'done' || t.status === 'completed') entry.done++;
            map.set(t.projectId, entry);
        });
        return map;
    }, [tasks]);

    // ── Timeline range based on zoom ──
    const timelineRange = useMemo(() => {
        const now = dayjs();
        const qStart = now.startOf('quarter').add(quarterOffset * 3, 'month');
        if (zoom === 'Month') {
            const start = qStart;
            const end = start.add(1, 'month');
            return { start, end, months: 1 };
        }
        if (zoom === 'Year') {
            const start = qStart.startOf('year');
            const end = start.add(1, 'year');
            return { start, end, months: 12 };
        }
        // Quarter default
        return { start: qStart, end: qStart.add(3, 'month'), months: 3 };
    }, [zoom, quarterOffset]);

    // ── Month columns ──
    const monthColumns = useMemo(() => {
        const cols: { label: string; start: dayjs.Dayjs; end: dayjs.Dayjs }[] = [];
        let cursor = timelineRange.start;
        while (cursor.isBefore(timelineRange.end)) {
            const next = cursor.add(1, 'month');
            cols.push({ label: cursor.format('MMM YYYY'), start: cursor, end: next.isBefore(timelineRange.end) ? next : timelineRange.end });
            cursor = next;
        }
        return cols;
    }, [timelineRange]);

    const totalDays = useMemo(() => Math.max(1, timelineRange.end.diff(timelineRange.start, 'day')), [timelineRange]);

    const todayPct = useMemo(() => {
        const offset = dayjs().diff(timelineRange.start, 'day');
        return Math.max(0, Math.min(100, (offset / totalDays) * 100));
    }, [timelineRange, totalDays]);

    // ── Stats ──
    const activeCount = projects.filter(p => p.status === 'active').length;
    const upcomingMs = milestones.filter(m => {
        const d = dayjs(m.targetDate);
        return d.isAfter(dayjs()) && d.diff(dayjs(), 'day') <= 30 && m.status !== 'completed';
    }).length;
    const completionRate = useMemo(() => {
        let total = 0, done = 0;
        tasksByProject.forEach(v => { total += v.total; done += v.done; });
        return total > 0 ? Math.round((done / total) * 100) : 0;
    }, [tasksByProject]);

    // ── Epics for expanded project ──
    const getEpics = (projectId: string) => tasks.filter(t => t.projectId === projectId && t.type === 'epic');
    const getProjectMilestones = (projectId: string) => milestones.filter(m => m.projectId === projectId);

    const calcBarPosition = (startDate: string, endDate: string) => {
        const s = dayjs(startDate);
        const e = dayjs(endDate);
        const leftPct = Math.max(0, (s.diff(timelineRange.start, 'day') / totalDays) * 100);
        const widthPct = Math.max(1, (e.diff(s, 'day') / totalDays) * 100);
        return { leftPct: Math.min(leftPct, 100), widthPct: Math.min(widthPct, 100 - Math.min(leftPct, 100)) };
    };

    // ── Drag-to-Reschedule: Project ──
    const handleRescheduleProject = useCallback(async (
        projectId: string,
        newStartDate: string,
        newEndDate: string,
        oldStartDate: string,
        oldEndDate: string
    ) => {
        // Optimistic update
        setProjects(prev => prev.map(p =>
            p.id === projectId ? { ...p, startDate: newStartDate, endDate: newEndDate } : p
        ));

        const undoKey = `undo-project-${projectId}-${Date.now()}`;
        try {
            await gql(UPDATE_PROJECT, {
                id: projectId,
                input: { startDate: newStartDate, endDate: newEndDate },
            });

            const projectName = projects.find(p => p.id === projectId)?.name || 'Project';
            messageApi.success({
                content: (
                    <span>
                        {projectName} rescheduled to {dayjs(newStartDate).format('MMM D')} — {dayjs(newEndDate).format('MMM D, YYYY')}{' '}
                        <Button
                            type="link"
                            size="small"
                            icon={<UndoOutlined />}
                            onClick={async () => {
                                try {
                                    await gql(UPDATE_PROJECT, {
                                        id: projectId,
                                        input: { startDate: oldStartDate, endDate: oldEndDate },
                                    });
                                    setProjects(prev => prev.map(p =>
                                        p.id === projectId ? { ...p, startDate: oldStartDate, endDate: oldEndDate } : p
                                    ));
                                    messageApi.success('Reschedule undone');
                                } catch (err: any) { console.error("PM Error", err); 
                                    messageApi.error('Failed to undo reschedule');
                                }
                            }}
                            style={{ padding: '0 4px' }}
                        >
                            Undo
                        </Button>
                    </span>
                ),
                key: undoKey,
                duration: 6,
            });
        } catch (err: any) {
            // Rollback
            setProjects(prev => prev.map(p =>
                p.id === projectId ? { ...p, startDate: oldStartDate, endDate: oldEndDate } : p
            ));
            messageApi.error(`Failed to reschedule: ${err.message}`);
        }
    }, [projects, messageApi]);

    // ── Drag-to-Reschedule: Epic (task) ──
    const handleRescheduleEpic = useCallback(async (
        taskId: string,
        newStartDate: string,
        newEndDate: string,
        oldStartDate: string,
        oldEndDate: string
    ) => {
        // Optimistic update
        setTasks(prev => prev.map(t =>
            t.id === taskId ? { ...t, startDate: newStartDate, dueDate: newEndDate } : t
        ));

        const undoKey = `undo-epic-${taskId}-${Date.now()}`;
        try {
            await gql(UPDATE_TASK, {
                id: taskId,
                input: { startDate: newStartDate, dueDate: newEndDate },
            });

            const epicTitle = tasks.find(t => t.id === taskId)?.title || 'Epic';
            messageApi.success({
                content: (
                    <span>
                        {epicTitle} rescheduled to {dayjs(newStartDate).format('MMM D')} — {dayjs(newEndDate).format('MMM D, YYYY')}{' '}
                        <Button
                            type="link"
                            size="small"
                            icon={<UndoOutlined />}
                            onClick={async () => {
                                try {
                                    await gql(UPDATE_TASK, {
                                        id: taskId,
                                        input: { startDate: oldStartDate, dueDate: oldEndDate },
                                    });
                                    setTasks(prev => prev.map(t =>
                                        t.id === taskId ? { ...t, startDate: oldStartDate, dueDate: oldEndDate } : t
                                    ));
                                    messageApi.success('Reschedule undone');
                                } catch (err: any) { console.error("PM Error", err); 
                                    messageApi.error('Failed to undo reschedule');
                                }
                            }}
                            style={{ padding: '0 4px' }}
                        >
                            Undo
                        </Button>
                    </span>
                ),
                key: undoKey,
                duration: 6,
            });
        } catch (err: any) {
            // Rollback
            setTasks(prev => prev.map(t =>
                t.id === taskId ? { ...t, startDate: oldStartDate, dueDate: oldEndDate } : t
            ));
            messageApi.error(`Failed to reschedule: ${err.message}`);
        }
    }, [tasks, messageApi]);

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    if (loading) {
        return (
            <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Roadmap</AuroraText>}
                subTitle={<DecryptedText text="Strategic quarterly timeline of projects and epics" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}>
                <div style={{ textAlign: 'center', padding: 120 }}><Spin size="large" /></div>
            </CMSLayout>
        );
    }

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Roadmap</AuroraText>}
            subTitle={<DecryptedText text="Strategic quarterly timeline of projects and epics" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <RbacGuard key="exp" requiredRole="manager">
                    <Tooltip title="Export to Excel">
                        <Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({
                            fileName: 'pm_roadmap',
                            title: 'PM Roadmap',
                            dateRange: { start: timelineRange.start.format('YYYY-MM-DD'), end: timelineRange.end.format('YYYY-MM-DD') },
                            columns: [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Start', key: 'startDate' }, { header: 'End', key: 'endDate' }, { header: 'Methodology', key: 'methodology' }],
                            data: filteredProjects,
                        })} />
                    </Tooltip>
                    <Tooltip title="Export to PDF">
                        <Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({
                            fileName: 'pm_roadmap',
                            title: 'PM Roadmap',
                            dateRange: { start: timelineRange.start.format('YYYY-MM-DD'), end: timelineRange.end.format('YYYY-MM-DD') },
                            columns: [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Start', key: 'startDate' }, { header: 'End', key: 'endDate' }, { header: 'Methodology', key: 'methodology' }],
                            data: filteredProjects,
                        })} />
                    </Tooltip>
                </RbacGuard>
            ]}>
            {contextHolder}

            <DndProvider backend={HTML5Backend}>
                {/* ── Summary Stats ── */}
                <BentoGrid className="max-w-full mb-6">
                    {[
                        { label: 'Active Projects', value: activeCount, icon: <RocketOutlined />, color: themeColor },
                        { label: 'Upcoming Milestones', value: upcomingMs, icon: <FlagOutlined />, color: '#f59e0b' },
                        { label: 'Completion Rate', value: completionRate, icon: <CheckCircleOutlined />, color: '#10b981', suffix: "%" },
                    ].map((s, i) => (
                        <BentoGridItem
                            key={i}
                            title={s.label}
                            description="Roadmap summary"
                            icon={<span style={{ color: s.color }}>{s.icon}</span>}
                            header={
                                <div className="flex h-full w-full flex-col items-center justify-center rounded-xl" style={{ backgroundColor: `${s.color}15` }}>
                                    <div style={{ fontSize: 32, fontWeight: 800, color: s.color }}>
                                        {s.value}
                                        {s.suffix && <span style={{ fontSize: 20 }}>{s.suffix}</span>}
                                    </div>
                                    {s.label === 'Completion Rate' && (
                                        <div className="mt-2 w-1/2">
                                            <Progress percent={completionRate} size="small" showInfo={false} strokeColor={{ '0%': '#10b981', '100%': '#34d399' }} />
                                        </div>
                                    )}
                                </div>
                            }
                            className="col-span-3 lg:col-span-1"
                        />
                    ))}
                </BentoGrid>

                {/* ── Filters & Navigation ── */}
                <Card style={{ ...glassCard, marginBottom: 16 }} size="small">
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                        <Space size={12} wrap>
                            <Select placeholder="Status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 140 }}
                                options={[{ label: 'Active', value: 'active' }, { label: 'Planning', value: 'planning' }, { label: 'Completed', value: 'completed' }, { label: 'On Hold', value: 'on_hold' }]} />
                            <Select placeholder="Methodology" allowClear value={methodologyFilter} onChange={setMethodologyFilter} style={{ width: 140 }}
                                options={[{ label: 'Agile', value: 'agile' }, { label: 'Waterfall', value: 'waterfall' }, { label: 'Hybrid', value: 'hybrid' }]} />
                            <Input placeholder="Search projects..." prefix={<SearchOutlined />} value={search} onChange={e => setSearch(e.target.value)} style={{ width: 180 }} allowClear />
                        </Space>
                        <Space size={8}>
                            <Tooltip title="Refresh roadmap">
                                <Button icon={<ReloadOutlined />} size="small" onClick={loadData} />
                            </Tooltip>
                            <Tooltip title="Drag project & epic bars horizontally to reschedule">
                                <Tag icon={<DragOutlined />} color="purple" style={{ fontSize: 11, cursor: 'help' }}>Drag to reschedule</Tag>
                            </Tooltip>
                            <div style={{ cursor: 'pointer', padding: '4px 8px', borderRadius: 6, background: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)' }}
                                onClick={() => setQuarterOffset(o => o - 1)}>
                                <LeftOutlined style={{ fontSize: 12 }} />
                            </div>
                            <Tooltip title="Jump to today">
                                <Button size="small" onClick={() => setQuarterOffset(0)} disabled={quarterOffset === 0}
                                    style={{ borderRadius: 6, fontSize: 11, fontWeight: 600 }}>
                                    Today
                                </Button>
                            </Tooltip>
                            <Text strong style={{ fontSize: 13, minWidth: 120, textAlign: 'center' }}>
                                {timelineRange.start.format('MMM YYYY')} — {timelineRange.end.subtract(1, 'day').format('MMM YYYY')}
                            </Text>
                            <div style={{ cursor: 'pointer', padding: '4px 8px', borderRadius: 6, background: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)' }}
                                onClick={() => setQuarterOffset(o => o + 1)}>
                                <RightOutlined style={{ fontSize: 12 }} />
                            </div>
                            <Segmented size="small" value={zoom} onChange={v => setZoom(v as string)} options={['Month', 'Quarter', 'Year']} />
                        </Space>
                    </div>
                </Card>

                {/* ── Timeline Chart ── */}
                <Card
                    title={<Space><CalendarOutlined style={{ color: themeColor }} /><span style={{ fontWeight: 600 }}>Project Roadmap</span><Tag color="purple">{filteredProjects.length}</Tag></Space>}
                    style={glassCard}
                >
                    {filteredProjects.length === 0 ? (
                        <Empty description="No projects match current filters. Adjust filters or add projects with dates." />
                    ) : (
                        <div style={{ display: 'flex', minHeight: 100 }}>
                            {/* ── Label Column ── */}
                            <div style={{ width: 220, flexShrink: 0 }}>
                                <div style={{ height: 36, marginBottom: 4 }} />
                                {filteredProjects.map(project => {
                                    const barColor = project.status === 'active' ? themeColor : (STATUS_BAR_COLOR[project.status] || '#6b7280');
                                    return (
                                        <React.Fragment key={project.id}>
                                            <div style={{ height: 44, display: 'flex', alignItems: 'center', paddingRight: 8, cursor: 'pointer' }}
                                                onClick={() => setExpandedProject(expandedProject === project.id ? null : project.id)}>
                                                <div style={{ display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                                                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                                        <div style={{ width: 8, height: 8, borderRadius: 2, background: barColor, flexShrink: 0 }} />
                                                        <Text strong style={{ fontSize: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 120 }} title={project.name}>{project.name}</Text>
                                                        <Tooltip title="Open project">
                                                            <RocketOutlined
                                                                style={{ fontSize: 11, color: themeColor, cursor: 'pointer', opacity: 0.7 }}
                                                                onClick={(e) => { e.stopPropagation(); router.push(`/admin/pm/dashboard?projectId=${project.id}`); }}
                                                            />
                                                        </Tooltip>
                                                    </div>
                                                    <div style={{ display: 'flex', gap: 4, marginLeft: 14, marginTop: 2 }}>
                                                        <Tag style={{ fontSize: 9, lineHeight: '14px', height: 16, padding: '0 4px', margin: 0, borderRadius: 4 }} color={barColor}>{project.status}</Tag>
                                                        {project.methodology && <Tag style={{ fontSize: 9, lineHeight: '14px', height: 16, padding: '0 4px', margin: 0, borderRadius: 4 }}>{project.methodology}</Tag>}
                                                    </div>
                                                </div>
                                            </div>
                                            {/* Epic labels when expanded */}
                                            {expandedProject === project.id && getEpics(project.id).map(epic => (
                                                <div key={epic.id} style={{ height: 32, display: 'flex', alignItems: 'center', paddingLeft: 22 }}>
                                                    <Text type="secondary" style={{ fontSize: 11, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 180 }}>{epic.title}</Text>
                                                </div>
                                            ))}
                                        </React.Fragment>
                                    );
                                })}
                            </div>

                            {/* ── Bar Area ── */}
                            <div style={{ flex: 1, overflowX: 'auto', position: 'relative' }}>
                                <RoadmapDropZone
                                    totalDays={totalDays}
                                    onRescheduleProject={handleRescheduleProject}
                                    onRescheduleEpic={handleRescheduleEpic}
                                    minWidth={zoom === 'Year' ? 900 : zoom === 'Month' ? 400 : 600}
                                    isDark={isDark}
                                >
                                    {/* Month Headers Grid */}
                                    <div style={{
                                        display: 'grid',
                                        gridTemplateColumns: `repeat(${monthColumns.length}, 1fr)`,
                                        height: 36,
                                        borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)'}`,
                                        marginBottom: 4,
                                    }}>
                                        {monthColumns.map((col, i) => (
                                            <div key={i} style={{
                                                display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
                                                paddingBottom: 6, fontSize: 11, fontWeight: 600,
                                                color: isDark ? '#94a3b8' : '#64748b',
                                                borderRight: i < monthColumns.length - 1 ? `1px solid ${isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.04)'}` : 'none',
                                            }}>
                                                {col.label}
                                            </div>
                                        ))}
                                    </div>

                                    {/* Today Line */}
                                    {todayPct > 0 && todayPct < 100 && (
                                        <div style={{
                                            position: 'absolute', left: `${todayPct}%`, top: 0, bottom: 0,
                                            width: 2, background: 'linear-gradient(to bottom, #ef4444, transparent)',
                                            zIndex: 10, opacity: 0.7, pointerEvents: 'none',
                                        }}>
                                            <div style={{
                                                position: 'absolute', top: 4, left: '50%', transform: 'translateX(-50%)',
                                                fontSize: 9, fontWeight: 700, color: '#ef4444', whiteSpace: 'nowrap',
                                                background: isDark ? '#0f0f17' : '#fff', padding: '1px 4px', borderRadius: 3,
                                            }}>TODAY</div>
                                        </div>
                                    )}

                                    {/* Month Grid Lines */}
                                    {monthColumns.map((_, i) => {
                                        const pct = (i / monthColumns.length) * 100;
                                        return i > 0 ? <div key={`grid-${i}`} style={{
                                            position: 'absolute', left: `${pct}%`, top: 36, bottom: 0,
                                            width: 1, background: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.04)', zIndex: 0,
                                        }} /> : null;
                                    })}

                                    {/* Project Bars + Milestones + Epics */}
                                    {filteredProjects.map(project => {
                                        const { leftPct, widthPct } = calcBarPosition(project.startDate, project.endDate);
                                        const barColor = project.status === 'active' ? themeColor : (STATUS_BAR_COLOR[project.status] || '#6b7280');
                                        const tc = tasksByProject.get(project.id) || { total: 0, done: 0 };
                                        const taskPct = tc.total > 0 ? Math.round((tc.done / tc.total) * 100) : 0;
                                        const projMilestones = getProjectMilestones(project.id);

                                        return (
                                            <React.Fragment key={project.id}>
                                                {/* Project bar row */}
                                                <div style={{ position: 'relative', height: 44 }}>
                                                    <DraggableProjectBar
                                                        project={project}
                                                        leftPct={leftPct}
                                                        widthPct={widthPct}
                                                        barColor={barColor}
                                                        taskPct={taskPct}
                                                        isDark={isDark}
                                                        themeColor={themeColor}
                                                        onExpand={() => setExpandedProject(expandedProject === project.id ? null : project.id)}
                                                        isExpanded={expandedProject === project.id}
                                                    />

                                                    {/* Milestone diamonds (non-draggable) */}
                                                    {projMilestones.map(ms => {
                                                        const msDay = dayjs(ms.targetDate);
                                                        const msPct = (msDay.diff(timelineRange.start, 'day') / totalDays) * 100;
                                                        if (msPct < 0 || msPct > 100) return null;
                                                        const msStatus = ms.status === 'completed' ? 'completed' : msDay.isBefore(dayjs()) ? 'overdue' : 'pending';
                                                        const msColor = MILESTONE_COLOR[msStatus] || '#f59e0b';
                                                        return (
                                                            <Tooltip key={ms.id} title={<div><div style={{ fontWeight: 600 }}>{ms.name}</div><div>{msDay.format('MMM D, YYYY')}</div><Tag color={msColor} style={{ marginTop: 4 }}>{msStatus}</Tag></div>}>
                                                                <div style={{
                                                                    position: 'absolute', left: `${msPct}%`, top: 6,
                                                                    width: 12, height: 12, transform: 'translateX(-50%) rotate(45deg)',
                                                                    background: msColor, border: `2px solid ${isDark ? '#0f0f17' : '#fff'}`,
                                                                    zIndex: 8, cursor: 'pointer', boxShadow: `0 2px 8px ${msColor}66`,
                                                                    transition: 'all 0.2s ease',
                                                                }} className="hover:scale-125 hover:shadow-lg hover:z-10" />
                                                            </Tooltip>
                                                        );
                                                    })}
                                                </div>

                                                {/* Expanded epic rows (draggable) */}
                                                {expandedProject === project.id && getEpics(project.id).map(epic => {
                                                    const epicStart = epic.startDate || project.startDate;
                                                    const epicEnd = epic.dueDate || project.endDate;
                                                    const { leftPct: ePct, widthPct: eW } = calcBarPosition(epicStart, epicEnd);
                                                    const epicColor = PRIORITY_COLOR[epic.priority] || '#3b82f6';
                                                    return (
                                                        <div key={epic.id} style={{ position: 'relative', height: 32 }}>
                                                            <DraggableEpicBar
                                                                epic={epic}
                                                                ePct={ePct}
                                                                eW={eW}
                                                                epicColor={epicColor}
                                                                projectStartDate={project.startDate}
                                                                projectEndDate={project.endDate}
                                                            />
                                                        </div>
                                                    );
                                                })}
                                            </React.Fragment>
                                        );
                                    })}
                                </RoadmapDropZone>
                            </div>
                        </div>
                    )}
                </Card>

                {/* ── Legend ── */}
                <Card style={{ ...glassCard, marginTop: 16 }} size="small">
                    <Space size={16} wrap>
                        <Text strong style={{ fontSize: 12 }}>Legend:</Text>
                        {[
                            { label: 'Active', color: themeColor },
                            { label: 'Completed', color: '#22c55e' },
                            { label: 'Planning', color: '#6b7280' },
                            { label: 'On Hold', color: '#f59e0b' },
                        ].map(s => (
                            <Space key={s.label} size={4}>
                                <div style={{ width: 12, height: 12, borderRadius: 3, background: `linear-gradient(135deg, ${s.color}cc, ${s.color}88)` }} />
                                <Text style={{ fontSize: 11 }}>{s.label}</Text>
                            </Space>
                        ))}
                        <Space size={4}>
                            <div style={{ width: 10, height: 10, transform: 'rotate(45deg)', background: '#f59e0b', borderRadius: 1 }} />
                            <Text style={{ fontSize: 11 }}>Milestone</Text>
                        </Space>
                        <Space size={4}>
                            <div style={{ width: 2, height: 12, background: '#ef4444', borderRadius: 1 }} />
                            <Text style={{ fontSize: 11, color: '#ef4444' }}>Today</Text>
                        </Space>
                        <Space size={4}>
                            <DragOutlined style={{ fontSize: 12, color: isDark ? '#94a3b8' : '#64748b' }} />
                            <Text style={{ fontSize: 11, color: isDark ? '#94a3b8' : '#64748b' }}>Drag bars to reschedule</Text>
                        </Space>
                    </Space>
                </Card>
            </DndProvider>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import {
    Card, Row, Col, Tag, Space, Select, Typography, Tooltip, Spin, message,
    Input, Progress, Breadcrumb, Popconfirm, DatePicker, Button,
} from "antd";
import {
    ArrowLeftOutlined, CopyOutlined, DeleteOutlined, LinkOutlined,
    ProjectOutlined, ClockCircleOutlined, CheckCircleOutlined,
    ExclamationCircleOutlined, UserOutlined, FireOutlined,
    ThunderboltOutlined, CalendarOutlined, RobotOutlined,
    ArrowUpOutlined, MinusOutlined, ArrowDownOutlined,
    EditOutlined, TagsOutlined, FieldTimeOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { useTheme } from "next-themes";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import SubtasksList from "../../components/SubtasksList";
import TaskCommentsPanel from "../../components/TaskCommentsPanel";
import TaskDependencies from "../../components/TaskDependencies";
import TimeTracker from "../../components/TimeTracker";

dayjs.extend(relativeTime);
const { Text } = Typography;

/* ── GraphQL ─────────────────────────────────────── */
const GET_TASK = `
  query($tenantId: String!, $id: String!) {
    pmTask(tenantId: $tenantId, id: $id) {
      id title description status priority type assigneeId reporterId
      projectId sprintId estimatedHours loggedHours dueDate tags
      assignee { id firstName lastName }
      reporter { id firstName lastName }
      createdAt updatedAt
    }
  }
`;
const GET_PROJECTS = `
  query($tenantId: String!) {
    pmProjects(tenantId: $tenantId) { id name projectNumber status }
  }
`;
const GET_SPRINTS = `
  query($tenantId: String!) {
    pmSprints(tenantId: $tenantId) { id name status projectId }
  }
`;
const UPDATE_TASK = `
  mutation($tenantId: String!, $id: String!, $input: UpdatePmTaskInput!) {
    updatePmTask(tenantId: $tenantId, id: $id, input: $input) { id title status }
  }
`;
const DELETE_TASK = `
  mutation($tenantId: String!, $id: String!) {
    deletePmTask(tenantId: $tenantId, id: $id)
  }
`;
const GENERATE_DESC = `
  mutation($tenantId: String!, $title: String!) {
    generateTaskDescription(tenantId: $tenantId, title: $title)
  }
`;

/* ── Constants ───────────────────────────────────── */
const STATUS_CONFIG: Record<string, { color: string; icon: React.ReactNode; label: string }> = {
    todo: { color: '#64748b', icon: <MinusOutlined />, label: 'To Do' },
    in_progress: { color: '#3b82f6', icon: <ClockCircleOutlined />, label: 'In Progress' },
    in_review: { color: 'var(--theme-color, #8b5cf6)', icon: <ThunderboltOutlined />, label: 'In Review' },
    done: { color: '#10b981', icon: <CheckCircleOutlined />, label: 'Done' },
    blocked: { color: '#ef4444', icon: <ExclamationCircleOutlined />, label: 'Blocked' },
};
const PRIORITY_CONFIG: Record<string, { color: string; icon: React.ReactNode }> = {
    critical: { color: '#ef4444', icon: <FireOutlined /> },
    high: { color: '#f59e0b', icon: <ArrowUpOutlined /> },
    medium: { color: '#3b82f6', icon: <MinusOutlined /> },
    low: { color: '#6b7280', icon: <ArrowDownOutlined /> },
};
const TYPE_ICONS: Record<string, string> = {
    bug: '🐛', story: '📖', task: '✅', epic: '🏔️', spike: '⚡',
};
const STATUS_ORDER = ['todo', 'in_progress', 'in_review', 'done', 'blocked'];
const PRIORITY_ORDER = ['low', 'medium', 'high', 'critical'];

/* ── Component ───────────────────────────────────── */
export default function TaskDetailPage() {
    const params = useParams();
    const router = useRouter();
    const id = params.id as string;
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const [messageApi, contextHolder] = message.useMessage();
    const [loading, setLoading] = useState(true);
    const [task, setTask] = useState<any>(null);
    const [projects, setProjects] = useState<any[]>([]);
    const [sprints, setSprints] = useState<any[]>([]);

    // Inline editing states
    const [editingTitle, setEditingTitle] = useState(false);
    const [titleDraft, setTitleDraft] = useState('');
    const [editingDesc, setEditingDesc] = useState(false);
    const [descDraft, setDescDraft] = useState('');
    const [aiGenerating, setAiGenerating] = useState(false);
    const [editingTags, setEditingTags] = useState(false);
    const [tagsDraft, setTagsDraft] = useState('');
    const titleRef = useRef<any>(null);

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(12px)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    /* ── Data Loading ──────────────────────────── */
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [taskData, projData, sprintData] = await Promise.all([
                gql(GET_TASK, { tenantId: DEFAULT_TENANT_ID, id }),
                gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_SPRINTS, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setTask(taskData.pmTask || null);
            setProjects(projData.pmProjects || []);
            setSprints(sprintData.pmSprints || []);
        } catch {
            messageApi.error('Failed to load task');
        } finally {
            setLoading(false);
        }
    }, [id, messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    /* ── Derived ──────────────────────────────── */
    const projectMap = useMemo(() => {
        const m = new Map<string, any>();
        projects.forEach(p => m.set(p.id, p));
        return m;
    }, [projects]);

    const project = task ? projectMap.get(task.projectId) : null;
    const projectSprints = useMemo(() =>
        sprints.filter(s => !task?.projectId || s.projectId === task.projectId),
    [sprints, task]);

    /* ── Auto-save field ─────────────────────── */
    const updateField = async (field: string, value: any) => {
        try {
            await gql(UPDATE_TASK, { tenantId: DEFAULT_TENANT_ID, id, input: { [field]: value } });
            messageApi.success({ content: `Updated ${field.replace(/([A-Z])/g, ' $1').toLowerCase()}`, duration: 1.5 });
            loadData();
        } catch {
            messageApi.error(`Failed to update ${field}`);
        }
    };

    /* ── Status / Priority Cycling ───────────── */
    const cycleStatus = () => {
        if (!task) return;
        const idx = STATUS_ORDER.indexOf(task.status);
        const next = STATUS_ORDER[(idx + 1) % STATUS_ORDER.length];
        updateField('status', next);
    };
    const cyclePriority = () => {
        if (!task) return;
        const idx = PRIORITY_ORDER.indexOf(task.priority);
        const next = PRIORITY_ORDER[(idx + 1) % PRIORITY_ORDER.length];
        updateField('priority', next);
    };

    /* ── Title Editing ───────────────────────── */
    const startEditTitle = () => {
        setTitleDraft(task?.title || '');
        setEditingTitle(true);
        setTimeout(() => titleRef.current?.focus(), 50);
    };
    const saveTitle = () => {
        setEditingTitle(false);
        if (titleDraft.trim() && titleDraft.trim() !== task?.title) {
            updateField('title', titleDraft.trim());
        }
    };

    /* ── Description Editing ─────────────────── */
    const startEditDesc = () => { setDescDraft(task?.description || ''); setEditingDesc(true); };
    const saveDesc = () => {
        setEditingDesc(false);
        if (descDraft !== (task?.description || '')) updateField('description', descDraft);
    };
    const handleAiGenerate = async () => {
        if (!task?.title) return;
        setAiGenerating(true);
        try {
            const data = await gql(GENERATE_DESC, { tenantId: DEFAULT_TENANT_ID, title: task.title });
            const generated = data.generateTaskDescription;
            if (generated) { setDescDraft(generated); setEditingDesc(true); messageApi.success('AI generated description!'); }
        } catch { messageApi.error('AI generation failed'); }
        finally { setAiGenerating(false); }
    };

    /* ── Tags Editing ────────────────────────── */
    const startEditTags = () => { setTagsDraft((task?.tags || []).join(', ')); setEditingTags(true); };
    const saveTags = () => {
        setEditingTags(false);
        const newTags = tagsDraft.split(',').map(t => t.trim()).filter(Boolean);
        updateField('tags', newTags);
    };

    /* ── Delete ──────────────────────────────── */
    const handleDelete = async () => {
        try {
            await gql(DELETE_TASK, { tenantId: DEFAULT_TENANT_ID, id });
            messageApi.success('Task deleted');
            router.push('/admin/pm/backlog');
        } catch { messageApi.error('Failed to delete task'); }
    };

    /* ── Copy Link ───────────────────────────── */
    const copyLink = () => {
        navigator.clipboard.writeText(window.location.href);
        messageApi.success({ content: 'Link copied!', duration: 1.5 });
    };
    const copyId = () => {
        navigator.clipboard.writeText(id);
        messageApi.success({ content: 'ID copied!', duration: 1.5 });
    };

    /* ── Computed ─────────────────────────────── */
    const est = task?.estimatedHours || 0;
    const logged = task?.loggedHours || 0;
    const hoursPct = est > 0 ? Math.min(100, Math.round((logged / est) * 100)) : 0;

    /* ── Sidebar field component ─────────────── */
    const SidebarField = ({ label, children }: { label: string; children: React.ReactNode }) => (
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: isDark ? '1px solid rgba(255,255,255,0.04)' : '1px solid rgba(0,0,0,0.04)' }}>
            <Text type="secondary" style={{ fontSize: 12, minWidth: 80 }}>{label}</Text>
            <div style={{ flex: 1, textAlign: 'right' }}>{children}</div>
        </div>
    );

    /* ── Loading / Not found ─────────────────── */
    if (loading && !task) {
        return (
            <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Task</AuroraText>}>
                <div style={{ textAlign: 'center', padding: 120 }}><Spin size="large" /></div>
            </CMSLayout>
        );
    }
    if (!task) {
        return (
            <CMSLayout title="Task Not Found">
                <div style={{ textAlign: 'center', padding: 80 }}>
                    <Text type="secondary">No task found with this ID.</Text><br />
                    <Button type="link" onClick={() => router.push('/admin/pm/backlog')}>Back to Backlog</Button>
                </div>
            </CMSLayout>
        );
    }

    const statusCfg = STATUS_CONFIG[task.status] || { color: '#6b7280', label: task.status, icon: <MinusOutlined /> };
    const prioCfg = PRIORITY_CONFIG[task.priority] || { color: '#6b7280', icon: <MinusOutlined /> };

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>{task.title?.slice(0, 30) || 'Task'}</AuroraText>}
            subTitle={<DecryptedText text={`Task Detail · ${id.slice(0, 8)}`} animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
        >
            {contextHolder}

            {/* ── Top Actions Bar ──────────────────── */}
            <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
                <Card size="small" style={{ ...glassCard, marginBottom: 16 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
                        <Space size={8}>
                            <Button icon={<ArrowLeftOutlined />} onClick={() => router.back()} size="small" aria-label="Go back">Back</Button>
                            <Breadcrumb items={[
                                { title: <a onClick={() => router.push('/admin/pm/projects')}>Projects</a> },
                                { title: project ? <a onClick={() => router.push(`/admin/pm/dashboard?projectId=${task.projectId}`)}>{project.name}</a> : 'Unknown' },
                                { title: task.title?.slice(0, 40) },
                            ]} />
                        </Space>
                        <Space size={8}>
                            <Tooltip title="Copy link"><Button icon={<LinkOutlined />} size="small" onClick={copyLink} aria-label="Copy link" /></Tooltip>
                            {project && (
                                <Button icon={<ProjectOutlined />} size="small"
                                    onClick={() => router.push(`/admin/pm/dashboard?projectId=${task.projectId}`)}>
                                    Open in Project
                                </Button>
                            )}
                            <Popconfirm title="Delete this task?" description="This action cannot be undone." onConfirm={handleDelete} okText="Delete" okType="danger">
                                <Button danger icon={<DeleteOutlined />} size="small">Delete</Button>
                            </Popconfirm>
                        </Space>
                    </div>
                </Card>
            </motion.div>

            {/* ── Two-Column Layout ────────────────── */}
            <Row gutter={[16, 16]}>
                {/* ── Left Column (Main Content) ─────── */}
                <Col xs={24} lg={16}>
                    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
                        style={{ display: 'flex', flexDirection: 'column', gap: 16 }}
                        role="article" aria-label={`Task: ${task.title}`}>

                        {/* Task Header */}
                        <Card style={glassCard}>
                            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
                                <span style={{ fontSize: 28, lineHeight: 1 }}>{TYPE_ICONS[task.type] || '✅'}</span>
                                <div style={{ flex: 1 }}>
                                    {/* Title — inline editable */}
                                    {editingTitle ? (
                                        <Input ref={titleRef} value={titleDraft} onChange={e => setTitleDraft(e.target.value)}
                                            onBlur={saveTitle} onPressEnter={saveTitle}
                                            style={{ fontSize: 22, fontWeight: 700, padding: '4px 8px', borderColor: themeColor }} />
                                    ) : (
                                        <div onClick={startEditTitle} style={{ cursor: 'pointer', fontSize: 22, fontWeight: 700, color: isDark ? '#f1f5f9' : '#0f172a', lineHeight: 1.3 }}>
                                            {task.title}
                                            <EditOutlined style={{ fontSize: 14, marginLeft: 8, opacity: 0.3 }} />
                                        </div>
                                    )}
                                    <Space size={8} style={{ marginTop: 10 }} wrap>
                                        <Tooltip title="Click to cycle status">
                                            <Tag color={statusCfg.color} icon={statusCfg.icon}
                                                style={{ cursor: 'pointer', fontWeight: 600 }} onClick={cycleStatus}>
                                                {statusCfg.label}
                                            </Tag>
                                        </Tooltip>
                                        <Tooltip title="Click to cycle priority">
                                            <Tag color={prioCfg.color} icon={prioCfg.icon}
                                                style={{ cursor: 'pointer', textTransform: 'capitalize', fontWeight: 600 }} onClick={cyclePriority}>
                                                {task.priority}
                                            </Tag>
                                        </Tooltip>
                                        <Tag style={{ textTransform: 'capitalize' }}>{TYPE_ICONS[task.type] || ''} {task.type}</Tag>
                                    </Space>
                                </div>
                            </div>
                        </Card>

                        {/* Description */}
                        <Card title={<Space><EditOutlined style={{ color: themeColor }} /> Description</Space>}
                            size="small" style={glassCard}
                            extra={
                                <Button size="small" icon={<RobotOutlined />} loading={aiGenerating} onClick={handleAiGenerate}
                                    style={{ borderRadius: 6 }}>AI Generate</Button>
                            }>
                            {editingDesc ? (
                                <Input.TextArea value={descDraft} onChange={e => setDescDraft(e.target.value)}
                                    onBlur={saveDesc} autoSize={{ minRows: 3, maxRows: 12 }} autoFocus
                                    style={{ borderColor: themeColor, fontSize: 13 }} />
                            ) : (
                                <div onClick={startEditDesc} style={{
                                    cursor: 'pointer', whiteSpace: 'pre-wrap', fontSize: 13, lineHeight: 1.7,
                                    minHeight: 60, padding: 8, borderRadius: 8,
                                    color: task.description ? (isDark ? '#e2e8f0' : '#1f2937') : (isDark ? '#64748b' : '#9ca3af'),
                                    background: isDark ? 'rgba(255,255,255,0.02)' : 'rgba(0,0,0,0.01)',
                                }}>
                                    {task.description || 'Click to add description...'}
                                </div>
                            )}
                        </Card>

                        {/* Subtasks */}
                        <Card title={<Space><CheckCircleOutlined style={{ color: themeColor }} /> Subtasks</Space>}
                            size="small" style={glassCard}>
                            <SubtasksList parentTaskId={id} projectId={task.projectId} onUpdate={loadData} />
                        </Card>

                        {/* Comments & Activity */}
                        <TaskCommentsPanel taskId={id} projectId={task.projectId} />
                    </motion.div>
                </Col>

                {/* ── Right Column (Sidebar) ──────────── */}
                <Col xs={24} lg={8}>
                    <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.2 }}
                        style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>

                        {/* Details Card */}
                        <Card title={<Space><ProjectOutlined style={{ color: themeColor }} /> Details</Space>}
                            size="small" style={glassCard}>
                            <SidebarField label="Status">
                                <Select size="small" value={task.status} variant="borderless" style={{ width: 140 }}
                                    onChange={v => updateField('status', v)}
                                    aria-label="Task status"
                                    options={Object.entries(STATUS_CONFIG).map(([k, v]) => ({
                                        label: <Tag color={v.color} icon={v.icon} style={{ margin: 0 }}>{v.label}</Tag>, value: k,
                                    }))} />
                            </SidebarField>
                            <SidebarField label="Priority">
                                <Select size="small" value={task.priority} variant="borderless" style={{ width: 120 }}
                                    onChange={v => updateField('priority', v)}
                                    aria-label="Task priority"
                                    options={Object.entries(PRIORITY_CONFIG).map(([k, v]) => ({
                                        label: <Tag color={v.color} icon={v.icon} style={{ margin: 0, textTransform: 'capitalize' as const }}>{k}</Tag>, value: k,
                                    }))} />
                            </SidebarField>
                            <SidebarField label="Type">
                                <Select size="small" value={task.type} variant="borderless" style={{ width: 120 }}
                                    onChange={v => updateField('type', v)}
                                    aria-label="Task type"
                                    options={['task', 'bug', 'story', 'epic', 'spike'].map(t => ({
                                        label: <span>{TYPE_ICONS[t]} {t.charAt(0).toUpperCase() + t.slice(1)}</span>, value: t,
                                    }))} />
                            </SidebarField>
                            <SidebarField label="Assignee">
                                <Space size={4}>
                                    <UserOutlined style={{ color: themeColor, fontSize: 12 }} />
                                    <Text style={{ fontSize: 12 }}>
                                        {task.assignee ? `${task.assignee.firstName} ${task.assignee.lastName}` : 'Unassigned'}
                                    </Text>
                                </Space>
                            </SidebarField>
                            <SidebarField label="Reporter">
                                <Text style={{ fontSize: 12 }} type="secondary">
                                    {task.reporter ? `${task.reporter.firstName} ${task.reporter.lastName}` : '—'}
                                </Text>
                            </SidebarField>
                            <SidebarField label="Sprint">
                                <Select size="small" value={task.sprintId || undefined} variant="borderless"
                                    style={{ width: 140 }} allowClear placeholder="No sprint"
                                    onChange={v => updateField('sprintId', v || null)}
                                    options={projectSprints.map(s => ({ label: s.name, value: s.id }))} />
                            </SidebarField>
                            <SidebarField label="Due Date">
                                <DatePicker size="small" variant="borderless"
                                    value={task.dueDate ? dayjs(task.dueDate) : null}
                                    onChange={d => updateField('dueDate', d ? d.format('YYYY-MM-DD') : null)}
                                    style={{ width: 130 }}
                                    suffixIcon={<CalendarOutlined style={{ color: themeColor }} />} />
                            </SidebarField>
                            <SidebarField label="Tags">
                                {editingTags ? (
                                    <Input size="small" value={tagsDraft} onChange={e => setTagsDraft(e.target.value)}
                                        onBlur={saveTags} onPressEnter={saveTags} autoFocus
                                        placeholder="tag1, tag2" style={{ width: 150, fontSize: 11 }} />
                                ) : (
                                    <div onClick={startEditTags} style={{ cursor: 'pointer', display: 'flex', flexWrap: 'wrap', gap: 4, justifyContent: 'flex-end' }}>
                                        {(task.tags || []).length > 0
                                            ? (task.tags || []).map((tag: string) => <Tag key={tag} color="cyan" style={{ fontSize: 10, margin: 0 }}>{tag}</Tag>)
                                            : <Text type="secondary" style={{ fontSize: 11 }}><TagsOutlined /> Add tags</Text>
                                        }
                                    </div>
                                )}
                            </SidebarField>
                        </Card>

                        {/* Time Tracking Card */}
                        <Card title={<Space><FieldTimeOutlined style={{ color: themeColor }} /> Time Tracking</Space>}
                            size="small" style={glassCard}>
                            <div style={{ marginBottom: 12 }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
                                    <Text style={{ fontSize: 12 }}>
                                        <ClockCircleOutlined /> {logged}h logged
                                    </Text>
                                    <Text type="secondary" style={{ fontSize: 12 }}>
                                        {est}h estimated
                                    </Text>
                                </div>
                                <Progress
                                    percent={hoursPct}
                                    size="small"
                                    strokeColor={hoursPct > 100 ? '#ef4444' : hoursPct > 80 ? '#f59e0b' : themeColor}
                                    trailColor={isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}
                                    format={() => `${hoursPct}%`}
                                />
                            </div>
                            <TimeTracker taskId={id} projectId={task.projectId} compact onTimeLogged={() => loadData()} />
                        </Card>

                        {/* Dependencies Card */}
                        <Card title={<Space><LinkOutlined style={{ color: themeColor }} /> Dependencies</Space>}
                            size="small" style={glassCard}>
                            <TaskDependencies taskId={id} projectId={task.projectId} onUpdate={loadData} />
                        </Card>

                        {/* Meta Info Card */}
                        <Card title={<Space><CalendarOutlined style={{ color: themeColor }} /> Meta</Space>}
                            size="small" style={glassCard}>
                            <SidebarField label="Created">
                                <Tooltip title={dayjs(task.createdAt).format('YYYY-MM-DD HH:mm:ss')}>
                                    <Text style={{ fontSize: 12 }}>{dayjs(task.createdAt).format('MMM D, YYYY')} · {dayjs(task.createdAt).fromNow()}</Text>
                                </Tooltip>
                            </SidebarField>
                            <SidebarField label="Updated">
                                <Tooltip title={dayjs(task.updatedAt).format('YYYY-MM-DD HH:mm:ss')}>
                                    <Text style={{ fontSize: 12 }}>{dayjs(task.updatedAt).format('MMM D, YYYY')} · {dayjs(task.updatedAt).fromNow()}</Text>
                                </Tooltip>
                            </SidebarField>
                            <SidebarField label="ID">
                                <Tooltip title="Click to copy">
                                    <Text code style={{ fontSize: 11, cursor: 'pointer' }} onClick={copyId}>
                                        {id.slice(0, 12)}… <CopyOutlined style={{ fontSize: 10 }} />
                                    </Text>
                                </Tooltip>
                            </SidebarField>
                        </Card>
                    </motion.div>
                </Col>
            </Row>
        </CMSLayout>
    );
}

