import { HTML5Backend } from "react-dnd-html5-backend";

const { Text, Title } = Typography;

const GET_PROJECTS = `
  query GetProjects($tenantId: String!) {
    pmProjects(tenantId: $tenantId) {
      id name projectNumber status priority startDate endDate budget spent
    }
  }
`;

const GET_PORTFOLIO = `
  query GetPortfolioSummary($tenantId: String!) {
    pmPortfolioSummary(tenantId: $tenantId)
  }
`;

const UPDATE_PROJECT = `
  mutation UpdateProject($id: ID!, $input: UpdatePmProjectInput!) {
    updatePmProject(id: $id, input: $input) {
      id name status startDate endDate
    }
  }
`;

const STATUS_COLOR: Record<string, string> = {
    active: '#10b981',
    planning: '#6366f1',
    paused: '#f59e0b',
    completed: '#22c55e',
    cancelled: '#ef4444',
};

const PRIORITY_COLOR: Record<string, string> = {
    critical: '#ef4444',
    high: '#f59e0b',
    medium: '#3b82f6',
    low: '#6b7280',
};

const ZOOM_MONTHS: Record<string, number> = { '3M': 3, '6M': 6, '1Y': 12, 'All': 0 };

const TIMELINE_BAR_TYPE = 'TIMELINE_BAR';

interface TimelineDragItem {
    projectId: string;
    startDate: string;
    endDate: string;
}

// ── DraggableBar Component ──
function DraggableBar({
    project,
    startPct,
    widthPct,
    barColor,
    isOverdue,
    taskPct,
    daysRemaining,
    isDark,
    themeColor,
    timelineRange,
    onNavigate,
}: {
    project: any;
    startPct: number;
    widthPct: number;
    barColor: string;
    isOverdue: boolean;
    taskPct: number;
    daysRemaining: number;
    isDark: boolean;
    themeColor: string;
    timelineRange: { start: dayjs.Dayjs; end: dayjs.Dayjs; totalDays: number };
    onNavigate: () => void;
}): React.ReactElement {
    const ref = useRef<HTMLDivElement>(null);
    const pStart = dayjs(project.startDate);
    const pEnd = dayjs(project.endDate);
    const tc = project.taskCounts;

    const [{ isDragging }, drag] = useDrag<TimelineDragItem, void, { isDragging: boolean }>(() => ({
        type: TIMELINE_BAR_TYPE,
        item: { projectId: project.id, startDate: project.startDate, endDate: project.endDate },
        collect: (monitor) => ({
            isDragging: monitor.isDragging(),
        }),
    }), [project.id, project.startDate, project.endDate]);

    drag(ref);

    const popoverContent = (
        <div style={{ width: 260, fontSize: 12 }}>
            <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 8 }}>{project.name}</div>
            <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
                <Tag color={barColor} style={{ margin: 0 }}>{project.status}</Tag>
                <Tag color={PRIORITY_COLOR[project.priority] || '#6b7280'} style={{ margin: 0 }}>{project.priority}</Tag>
            </div>
            <div style={{ color: isDark ? '#94a3b8' : '#64748b', marginBottom: 6 }}>
                <CalendarOutlined /> {pStart.format('MMM D, YYYY')} — {pEnd.format('MMM D, YYYY')}
            </div>
            <Progress percent={taskPct} size="small" strokeColor={barColor} style={{ marginBottom: 6 }} />
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                <span>Tasks: {tc.done}/{tc.total}</span>
                <span>{tc.inProgress} in progress</span>
            </div>
            {isOverdue
                ? <div style={{ color: '#ef4444', fontWeight: 600 }}>⚠ Overdue by {Math.abs(daysRemaining)} days</div>
                : project.status !== 'completed' && <div style={{ color: themeColor }}>{daysRemaining} days remaining</div>
            }
            <div style={{ marginTop: 8, color: isDark ? '#94a3b8' : '#94a3b8', fontSize: 11, display: 'flex', alignItems: 'center', gap: 4 }}>
                <DragOutlined /> Drag to reschedule
            </div>
        </div>
    );

    return (
        <div key={project.id} style={{ position: 'relative', height: 44, marginBottom: 4 }}>
            <Popover content={popoverContent} placement="right" mouseEnterDelay={0.3}>
                <div
                    ref={ref}
                    style={{
                        position: 'absolute',
                        left: `${startPct}%`,
                        width: `${Math.min(widthPct, 100 - startPct)}%`,
                        height: 24, top: 10,
                        borderRadius: 6, cursor: isDragging ? 'grabbing' : 'grab',
                        background: `linear-gradient(135deg, ${barColor}cc, ${barColor}88)`,
                        border: isOverdue ? '2px solid #ef4444' : `1px solid ${barColor}`,
                        display: 'flex', alignItems: 'center', paddingLeft: 8, overflow: 'hidden',
                        transition: isDragging ? 'none' : 'all 0.2s ease',
                        boxShadow: isDragging ? `0 4px 16px ${barColor}44` : `0 2px 8px ${barColor}22`,
                        opacity: isDragging ? 0.5 : 1,
                        zIndex: isDragging ? 20 : 1,
                    }}
                    onClick={(e) => {
                        if (!isDragging) {
                            onNavigate();
                        }
                    }}
                    onMouseEnter={e => {
                        if (!isDragging) {
                            const el = e.currentTarget;
                            el.style.filter = 'brightness(1.2)';
                            el.style.transform = 'scaleY(1.15)';
                            el.style.zIndex = '5';
                        }
                    }}
                    onMouseLeave={e => {
                        if (!isDragging) {
                            const el = e.currentTarget;
                            el.style.filter = 'brightness(1)';
                            el.style.transform = 'scaleY(1)';
                            el.style.zIndex = '1';
                        }
                    }}
                >
                    <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: `${taskPct}%`, background: `${barColor}44`, borderRadius: '6px 0 0 6px' }} />
                    <Text style={{ fontSize: 10, fontWeight: 600, color: '#fff', position: 'relative', zIndex: 2, textShadow: '0 1px 2px rgba(0,0,0,0.3)' }}>{taskPct}%</Text>
                    <Tag style={{ fontSize: 9, marginLeft: 4, position: 'relative', zIndex: 2, lineHeight: '14px', height: 16, border: 'none', background: 'rgba(255,255,255,0.2)', color: '#fff' }}>{project.status}</Tag>
                </div>
            </Popover>
        </div>
    );
}

// ── TimelineDropZone Component ──
function TimelineDropZone({
    children,
    timelineRange,
    onReschedule,
    minBarWidth,
    isDark,
}: {
    children: React.ReactNode;
    timelineRange: { start: dayjs.Dayjs; end: dayjs.Dayjs; totalDays: number };
    onReschedule: (projectId: string, newStartDate: string, newEndDate: string, oldStartDate: string, oldEndDate: string) => void;
    minBarWidth: number | undefined;
    isDark: boolean;
}): React.ReactElement {
    const containerRef = useRef<HTMLDivElement>(null);

    const [{ isOver }, drop] = useDrop<TimelineDragItem, void, { isOver: boolean }>(() => ({
        accept: TIMELINE_BAR_TYPE,
        drop: (item, monitor) => {
            const delta = monitor.getDifferenceFromInitialOffset();
            if (!delta || !containerRef.current) return;

            const containerWidth = containerRef.current.getBoundingClientRect().width;
            const deltaDays = Math.round((delta.x / containerWidth) * timelineRange.totalDays);

            if (deltaDays === 0) return;

            const newStart = dayjs(item.startDate).add(deltaDays, 'day').format('YYYY-MM-DD');
            const newEnd = dayjs(item.endDate).add(deltaDays, 'day').format('YYYY-MM-DD');

            onReschedule(item.projectId, newStart, newEnd, item.startDate, item.endDate);
        },
        collect: (monitor) => ({
            isOver: monitor.isOver(),
        }),
    }), [timelineRange.totalDays, onReschedule]);

    // Combine refs
    const setRef = useCallback((node: HTMLDivElement | null) => {
        (containerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        drop(node);
    }, [drop]);

    return (
        <div
            ref={setRef}
            style={{
                position: 'relative',
                minWidth: minBarWidth,
                outline: isOver ? `2px dashed ${isDark ? 'rgba(139,92,246,0.4)' : 'rgba(99,102,241,0.3)'}` : 'none',
                outlineOffset: -2,
                borderRadius: 8,
                transition: 'outline 0.2s ease',
            }}
        >
            {children}
        </div>
    );
}

export default function TimelinePage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const { themeColor } = usePreferencesStore();
    const { startDate, endDate } = useDateRangeStore();
    const [projects, setProjects] = useState<any[]>([]);
    const [portfolio, setPortfolio] = useState<any[]>([]);
    const [statusFilter, setStatusFilter] = useState<string | null>(null);
    const [priorityFilter, setPriorityFilter] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [zoom, setZoom] = useState<string>('All');
    const { resolvedTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    const [messageApi, contextHolder] = message.useMessage();
    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === 'dark';

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [projData, portData] = await Promise.all([
                gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_PORTFOLIO, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setProjects(projData.pmProjects || []);
            setPortfolio(portData.pmPortfolioSummary || []);
        } catch (err: any) {
            messageApi.error("Failed to load timeline data: " + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const enrichedProjects = useMemo(() => {
        const portMap = new Map<string, any>();
        portfolio.forEach(p => portMap.set(p.id, p));
        return projects
            .filter(p => p.startDate && p.endDate)
            .filter(p => !statusFilter || p.status === statusFilter)
            .filter(p => !priorityFilter || p.priority === priorityFilter)
            .filter(p => !searchQuery.trim() || p.name?.toLowerCase().includes(searchQuery.toLowerCase()) || p.projectNumber?.toLowerCase().includes(searchQuery.toLowerCase()))
            .sort((a, b) => dayjs(a.startDate).unix() - dayjs(b.startDate).unix())
            .map(p => ({
                ...p,
                taskCounts: portMap.get(p.id)?.taskCounts || { total: 0, done: 0, inProgress: 0 },
            }));
    }, [projects, portfolio, statusFilter, priorityFilter, searchQuery]);

    const timelineRange = useMemo(() => {
        if (enrichedProjects.length === 0) return { start: dayjs(), end: dayjs().add(6, 'month'), totalDays: 180 };
        const dates = enrichedProjects.map(p => ({ start: dayjs(p.startDate), end: dayjs(p.endDate) }));
        const earliest = dates.reduce((min, d) => d.start.isBefore(min) ? d.start : min, dates[0].start);
        const latest = dates.reduce((max, d) => d.end.isAfter(max) ? d.end : max, dates[0].end);
        const zoomMonths = ZOOM_MONTHS[zoom];
        const start = zoomMonths ? dayjs().subtract(Math.floor(zoomMonths / 3), 'month') : earliest.subtract(7, 'day');
        const end = zoomMonths ? dayjs().add(zoomMonths - Math.floor(zoomMonths / 3), 'month') : latest.add(7, 'day');
        return { start, end, totalDays: Math.max(1, end.diff(start, 'day')) };
    }, [enrichedProjects, zoom]);

    const monthMarkers = useMemo(() => {
        const markers: { label: string; leftPct: number }[] = [];
        let cursor = timelineRange.start.startOf('month');
        while (cursor.isBefore(timelineRange.end)) {
            const dayOffset = cursor.diff(timelineRange.start, 'day');
            const pct = timelineRange.totalDays > 0 ? (dayOffset / timelineRange.totalDays) * 100 : 0;
            if (pct >= 0 && pct <= 100) markers.push({ label: cursor.format('MMM YYYY'), leftPct: pct });
            cursor = cursor.add(1, 'month');
        }
        return markers;
    }, [timelineRange]);

    const todayPct = useMemo(() => {
        const dayOffset = dayjs().diff(timelineRange.start, 'day');
        return timelineRange.totalDays > 0 ? Math.max(0, Math.min(100, (dayOffset / timelineRange.totalDays) * 100)) : 50;
    }, [timelineRange]);

    const withDates = projects.filter(p => p.startDate && p.endDate);
    const overdueProjects = withDates.filter(p => dayjs(p.endDate).isBefore(dayjs()) && p.status !== 'completed' && p.status !== 'cancelled');
    const activeProjects = projects.filter(p => p.status === 'active');
    const upcomingMilestones = withDates.filter(p => {
        const e = dayjs(p.endDate);
        return e.isAfter(dayjs()) && e.diff(dayjs(), 'day') <= 30 && p.status !== 'completed';
    });

    // ── Drag-to-Reschedule handler ──
    const handleReschedule = useCallback(async (
        projectId: string,
        newStartDate: string,
        newEndDate: string,
        oldStartDate: string,
        oldEndDate: string
    ) => {
        // Optimistic update
        setProjects(prev => prev.map(p =>
            p.id === projectId ? { ...p, startDate: newStartDate, endDate: newEndDate } : p
        ));

        const undoKey = `undo-${projectId}-${Date.now()}`;

        try {
            await gql(UPDATE_PROJECT, {
                id: projectId,
                input: { startDate: newStartDate, endDate: newEndDate },
            });

            const projectName = projects.find(p => p.id === projectId)?.name || 'Project';

            messageApi.success({
                content: (
                    <span>
                        {projectName} rescheduled to {dayjs(newStartDate).format('MMM D')} — {dayjs(newEndDate).format('MMM D, YYYY')}{' '}
                        <Button
                            type="link"
                            size="small"
                            icon={<UndoOutlined />}
                            onClick={async () => {
                                try {
                                    await gql(UPDATE_PROJECT, {
                                        id: projectId,
                                        input: { startDate: oldStartDate, endDate: oldEndDate },
                                    });
                                    setProjects(prev => prev.map(p =>
                                        p.id === projectId ? { ...p, startDate: oldStartDate, endDate: oldEndDate } : p
                                    ));
                                    messageApi.success('Reschedule undone');
                                } catch (err: any) { console.error("PM Error", err); 
                                    messageApi.error('Failed to undo reschedule');
                                }
                            }}
                            style={{ padding: '0 4px' }}
                        >
                            Undo
                        </Button>
                    </span>
                ),
                key: undoKey,
                duration: 6,
            });
        } catch (err: any) {
            // Rollback on failure
            setProjects(prev => prev.map(p =>
                p.id === projectId ? { ...p, startDate: oldStartDate, endDate: oldEndDate } : p
            ));
            messageApi.error(`Failed to reschedule: ${err.message}`);
        }
    }, [projects, messageApi]);

    const glassCard = {
        background: isDark ? 'rgba(15, 15, 23, 0.7)' : 'rgba(255,255,255,0.85)',
        border: isDark ? '1px solid rgba(139,92,246,0.15)' : '1px solid rgba(0,0,0,0.06)',
        borderRadius: 12,
    };

    const minBarWidth = zoom === '3M' ? 1200 : zoom === '6M' ? 900 : zoom === '1Y' ? 800 : undefined;

    const exportCols = [{ header: 'Name', key: 'name' }, { header: 'Status', key: 'status' }, { header: 'Start', key: 'startDate' }, { header: 'End', key: 'endDate' }, { header: 'Progress', key: 'progress' }];
    const exportArgs = { fileName: 'pm_timeline', title: 'PM Timeline', dateRange: { start: startDate, end: endDate }, columns: exportCols, data: projects };

    const headerExtra = [<RbacGuard key="exp" requiredRole="manager"><Tooltip key="xl" title="Export to Excel"><Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel(exportArgs)} /></Tooltip> <Tooltip key="pdf" title="Export to PDF"><Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf(exportArgs)} /></Tooltip></RbacGuard>];

    if (loading) {
        return (
            <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Timeline</AuroraText>}
                subTitle={<DecryptedText text="Cross-project Gantt-style timeline view" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={headerExtra}>
                <div style={{ textAlign: 'center', padding: 120 }}><Spin size="large" /></div>
            </CMSLayout>
        );
    }

    return (
        <CMSLayout title={<AuroraText colors={[themeColor, "var(--theme-secondary, #6366f1)", "var(--theme-accent, #a78bfa)"]}>Timeline</AuroraText>}
            subTitle={<DecryptedText text="Cross-project Gantt-style timeline view" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />} extra={headerExtra}>
            {contextHolder}

            <DndProvider backend={HTML5Backend}>
                {/* ── Stats ── */}
                <BentoGrid className="max-w-full mb-6">
                    {[
                        { label: 'Projects with Timeline', value: withDates.length, suffix: true, icon: <CalendarOutlined />, color: themeColor },
                        { label: 'Active Projects', value: activeProjects.length, icon: <ClockCircleOutlined />, color: '#10b981' },
                        { label: 'Overdue', value: overdueProjects.length, icon: <ExclamationCircleOutlined />, color: '#ef4444' },
                        { label: 'Due in 30 Days', value: upcomingMilestones.length, icon: <FlagOutlined />, color: '#f59e0b' },
                    ].map((s, i) => (
                        <BentoGridItem
                            key={i}
                            title={s.label}
                            description="Timeline metric"
                            icon={<span style={{ color: s.color }}>{s.icon}</span>}
                            header={
                                <div className="flex h-full w-full flex-col items-center justify-center rounded-xl" style={{ backgroundColor: `${s.color}15` }}>
                                    <div style={{ fontSize: 32, fontWeight: 800, color: s.color }}>
                                        {s.value}
                                    </div>
                                    {s.suffix && projects.length > 0 && (
                                        <div className="mt-2 text-xs" style={{ color: "rgba(255,255,255,0.7)" }}>
                                            {Math.round((withDates.length / projects.length) * 100)}% of total
                                        </div>
                                    )}
                                </div>
                            }
                            className="col-span-4 lg:col-span-1"
                        />
                    ))}
                </BentoGrid>

                {/* ── Filters & Zoom ── */}
                <Card style={{ ...glassCard, marginBottom: 16 }} size="small">
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                        <Space size={12} wrap>
                            <Input
                                prefix={<SearchOutlined style={{ color: isDark ? '#64748b' : '#94a3b8' }} />}
                                placeholder="Search projects..."
                                value={searchQuery}
                                onChange={e => setSearchQuery(e.target.value)}
                                allowClear
                                style={{ width: 180, borderRadius: 8 }}
                            />
                            <Select placeholder="Filter by status" allowClear value={statusFilter} onChange={setStatusFilter} style={{ width: 160 }}
                                options={[{ label: 'Active', value: 'active' }, { label: 'Planning', value: 'planning' }, { label: 'Paused', value: 'paused' }, { label: 'Completed', value: 'completed' }, { label: 'Cancelled', value: 'cancelled' }]} />
                            <Select placeholder="Filter by priority" allowClear value={priorityFilter} onChange={setPriorityFilter} style={{ width: 160 }}
                                options={[{ label: '🔴 Critical', value: 'critical' }, { label: '🟡 High', value: 'high' }, { label: '🔵 Medium', value: 'medium' }, { label: '⚪ Low', value: 'low' }]} />
                            <Text type="secondary" style={{ fontSize: 12 }}>
                                Showing {enrichedProjects.length} project{enrichedProjects.length !== 1 ? 's' : ''} with timeline data
                            </Text>
                        </Space>
                        <Space size={8}>
                            <Tooltip title="Refresh timeline">
                                <Button icon={<ReloadOutlined />} size="small" onClick={loadData} />
                            </Tooltip>
                            <Tooltip title="Drag project bars horizontally to reschedule">
                                <Tag icon={<DragOutlined />} color="purple" style={{ fontSize: 11, cursor: 'help' }}>Drag to reschedule</Tag>
                            </Tooltip>
                            <ZoomInOutlined style={{ color: themeColor, fontSize: 14 }} />
                            <Segmented size="small" value={zoom} onChange={v => setZoom(v as string)} options={['3M', '6M', '1Y', 'All']} />
                        </Space>
                    </div>
                </Card>

                {/* ── Timeline Chart ── */}
                <Card
                    title={<Space><FieldTimeOutlined style={{ color: themeColor }} /><span style={{ fontWeight: 600 }}>Project Timeline</span><Tag color="purple">{enrichedProjects.length}</Tag></Space>}
                    style={glassCard}
                >
                    {enrichedProjects.length === 0 ? (
                        <motion.div initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }}>
                            <Card style={{ ...glassCard, padding: 60, textAlign: 'center', borderStyle: 'dashed', borderWidth: 2, margin: '16px 0' }}>
                                <CalendarOutlined style={{ fontSize: 64, color: isDark ? 'rgba(139,92,246,0.5)' : 'rgba(139,92,246,0.4)', marginBottom: 24 }} />
                                <div style={{ fontSize: 18, fontWeight: 600, marginBottom: 12, color: isDark ? '#f8fafc' : '#0f172a' }}>No Timeline Data Available</div>
                                <Text type="secondary" style={{ display: 'block', maxWidth: 420, margin: '0 auto 24px', fontSize: 14 }}>
                                    Set start and end dates on your projects to visualize them here on the Gantt chart. You can also drag project bars to quickly reschedule.
                                </Text>
                                <Button type="primary" size="large" onClick={() => router.push('/admin/pm/projects')} style={{ borderRadius: 12, paddingLeft: 24, paddingRight: 24 }}>
                                    Manage Projects
                                </Button>
                            </Card>
                        </motion.div>
                    ) : (
                        <div style={{ display: 'flex', minHeight: 100 }}>
                            {/* ── Label Column ── */}
                            <div style={{ width: 212, flexShrink: 0 }}>
                                <div style={{ height: 32, marginBottom: 8 }} />
                                {enrichedProjects.map((project) => {
                                    const barColor = STATUS_COLOR[project.status] || '#6b7280';
                                    const isOverdue = dayjs().isAfter(dayjs(project.endDate)) && project.status !== 'completed' && project.status !== 'cancelled';
                                    return (
                                        <div key={project.id} style={{ height: 44, marginBottom: 4, display: 'flex', alignItems: 'center', paddingRight: 8, cursor: 'pointer' }}
                                            onClick={() => router.push(`/admin/pm/dashboard?projectId=${project.id}`)}>
                                            <div style={{ display: 'flex', flexDirection: 'column' }}>
                                                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                                    <Badge color={barColor} style={{ minWidth: 8 }} />
                                                    <Text strong style={{ fontSize: 12, maxWidth: 150, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={project.name}>{project.name}</Text>
                                                    {isOverdue && <ExclamationCircleOutlined style={{ color: '#ef4444', fontSize: 11 }} />}
                                                </div>
                                                <Text type="secondary" style={{ fontSize: 10, marginLeft: 14 }}>{project.projectNumber}</Text>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            {/* ── Bar Area (scrollable, relative container) ── */}
                            <div style={{ flex: 1, overflowX: 'auto', position: 'relative' }}>
                                <TimelineDropZone
                                    timelineRange={timelineRange}
                                    onReschedule={handleReschedule}
                                    minBarWidth={minBarWidth}
                                    isDark={isDark}
                                >
                                    {/* Month Headers */}
                                    <div style={{ position: 'relative', height: 32, borderBottom: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)'}`, marginBottom: 8 }}>
                                        {monthMarkers.map((m, i) => (
                                            <div key={i} style={{ position: 'absolute', left: `${m.leftPct}%`, bottom: 4, fontSize: 10, fontWeight: 600, color: isDark ? '#94a3b8' : '#64748b', transform: 'translateX(-50%)', whiteSpace: 'nowrap' }}>
                                                {m.label}
                                            </div>
                                        ))}
                                    </div>

                                    {/* Today Line — pure percentage inside bar area */}
                                    <div style={{ position: 'absolute', left: `${todayPct}%`, top: 0, bottom: 0, width: 2, background: 'linear-gradient(to bottom, #ef4444, transparent)', zIndex: 10, opacity: 0.7, pointerEvents: 'none' }}>
                                        <div style={{ position: 'absolute', top: 4, left: '50%', transform: 'translateX(-50%)', fontSize: 9, fontWeight: 700, color: '#ef4444', whiteSpace: 'nowrap', background: isDark ? '#0f0f17' : '#fff', padding: '1px 4px', borderRadius: 3 }}>
                                            TODAY
                                        </div>
                                    </div>

                                    {/* Milestone Markers */}
                                    {enrichedProjects.filter(p => {
                                        const daysUntilEnd = dayjs(p.endDate).diff(dayjs(), 'day');
                                        return daysUntilEnd >= 0 && daysUntilEnd <= 7 && p.status !== 'completed' && p.status !== 'cancelled';
                                    }).map(p => {
                                        const endPct = timelineRange.totalDays > 0 ? Math.max(0, Math.min(100, (dayjs(p.endDate).diff(timelineRange.start, 'day') / timelineRange.totalDays) * 100)) : 0;
                                        return (
                                            <div key={`ms-${p.id}`} style={{ position: 'absolute', left: `${endPct}%`, top: 32, bottom: 0, width: 0, zIndex: 8, pointerEvents: 'none' }}>
                                                <div style={{ position: 'absolute', top: 0, left: -4, width: 8, height: 8, borderRadius: '50%', background: '#f59e0b', border: '2px solid #fff', boxShadow: '0 0 6px rgba(245,158,11,0.5)' }} />
                                            </div>
                                        );
                                    })}

                                    {/* Month Grid Lines — pure percentage inside bar area */}
                                    {monthMarkers.map((m, i) => (
                                        <div key={`grid-${i}`} style={{ position: 'absolute', left: `${m.leftPct}%`, top: 32, bottom: 0, width: 1, background: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.04)', zIndex: 0 }} />
                                    ))}

                                    {/* Project Bars (Draggable) */}
                                    {enrichedProjects.map((project, idx) => {
                                        const pStart = dayjs(project.startDate);
                                        const pEnd = dayjs(project.endDate);
                                        const now = dayjs();
                                        const startPct = timelineRange.totalDays > 0 ? Math.max(0, (pStart.diff(timelineRange.start, 'day') / timelineRange.totalDays) * 100) : 0;
                                        const widthPct = timelineRange.totalDays > 0 ? Math.max(1, (pEnd.diff(pStart, 'day') / timelineRange.totalDays) * 100) : 5;
                                        const isOverdue = now.isAfter(pEnd) && project.status !== 'completed' && project.status !== 'cancelled';
                                        const tc = project.taskCounts;
                                        const taskPct = tc.total > 0 ? Math.round((tc.done / tc.total) * 100) : 0;
                                        const barColor = STATUS_COLOR[project.status] || '#6b7280';
                                        const daysRemaining = pEnd.diff(now, 'day');

                                        return (
                                            <DraggableBar
                                                key={project.id}
                                                project={project}
                                                startPct={startPct}
                                                widthPct={widthPct}
                                                barColor={barColor}
                                                isOverdue={isOverdue}
                                                taskPct={taskPct}
                                                daysRemaining={daysRemaining}
                                                isDark={isDark}
                                                themeColor={themeColor}
                                                timelineRange={timelineRange}
                                                onNavigate={() => router.push(`/admin/pm/dashboard?projectId=${project.id}`)}
                                            />
                                        );
                                    })}
                                </TimelineDropZone>
                            </div>
                        </div>
                    )}
                </Card>

                <Card style={{ ...glassCard, marginTop: 16, padding: '12px 16px' }} size="small">
                    <Space size={20} wrap>
                        <Text strong style={{ fontSize: 13, textTransform: 'uppercase', letterSpacing: 0.5, color: themeColor }}>Legend</Text>
                        {Object.entries(STATUS_COLOR).map(([status, color]) => (
                            <Space key={status} size={6} style={{ background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)', padding: '4px 10px', borderRadius: 20 }}>
                                <div style={{ width: 14, height: 14, borderRadius: 4, background: `linear-gradient(135deg, ${color}dd, ${color}99)`, boxShadow: `0 2px 6px ${color}44` }} />
                                <Text style={{ fontSize: 12, textTransform: 'capitalize', fontWeight: 500 }}>{status}</Text>
                            </Space>
                        ))}
                        <Space size={6} style={{ background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)', padding: '4px 10px', borderRadius: 20 }}>
                            <div style={{ width: 3, height: 14, background: '#ef4444', borderRadius: 2, boxShadow: '0 0 6px rgba(239,68,68,0.5)' }} />
                            <Text style={{ fontSize: 12, color: '#ef4444', fontWeight: 600 }}>Today</Text>
                        </Space>
                        <Space size={6} style={{ background: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)', padding: '4px 10px', borderRadius: 20 }}>
                            <div style={{ width: 10, height: 10, borderRadius: '50%', background: '#f59e0b', border: '2px solid #fff', boxShadow: '0 0 6px rgba(245,158,11,0.6)' }} />
                            <Text style={{ fontSize: 12, color: '#f59e0b', fontWeight: 600 }}>Due this week</Text>
                        </Space>
                        <Space size={6}>
                            <DragOutlined style={{ fontSize: 14, color: isDark ? '#94a3b8' : '#64748b' }} />
                            <Text style={{ fontSize: 12, color: isDark ? '#94a3b8' : '#64748b', fontStyle: 'italic' }}>Drag bars to reschedule</Text>
                        </Space>
                    </Space>
                </Card>
            </DndProvider>
        </CMSLayout>
    );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
import CMSLayout from "@/components/layout/CMSLayout";
import { motion } from "framer-motion";
import { AuroraText } from "@/components/magicui/aurora-text";
import DecryptedText from "@/components/react-bits/DecryptedText";
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { Alert, Avatar, Badge, Button, Card, Col, Divider, Empty, Input, Progress, Row, Segmented, Select, Space, Spin, Statistic, Table, Tag, Tooltip, Typography } from "antd";
import {
    TeamOutlined, ClockCircleOutlined, WarningOutlined,
    UnorderedListOutlined, AppstoreOutlined, SearchOutlined,
    ExclamationCircleOutlined, FireOutlined, UserOutlined,
    CheckCircleOutlined, SyncOutlined, PauseCircleOutlined,
    ProjectOutlined, FileExcelOutlined, FilePdfOutlined,
} from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import { useTheme } from "next-themes";
import { useRouter } from "next/navigation";
import dayjs from "dayjs";
import { usePreferencesStore } from "@/store/usePreferencesStore";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, ReferenceLine, Cell, Legend, PieChart, Pie, AreaChart, Area } from "recharts";
import { exportToPdf, exportToExcel } from "@/lib/exportUtils";
import RbacGuard from "@/components/common/RbacGuard";
import { message } from "antd";
import { DragDropContext, Droppable, Draggable, DropResult } from "@hello-pangea/dnd";

const { Text } = Typography;

const GET_TASKS = `
  query($tenantId: String!) {
    pmTasks(tenantId: $tenantId) {
      id projectId title status priority type estimatedHours loggedHours
      assigneeId dueDate startDate
      assignee { id firstName lastName }
    }
  }
`;

const GET_PROJECTS = `
  query($tenantId: String!) {
    pmProjects(tenantId: $tenantId) { id name projectNumber status }
  }
`;

const UPDATE_TASK_ASSIGNEE = `
  mutation($id: ID!, $assigneeId: String) {
    updatePmTask(id: $id, input: { assigneeId: $assigneeId }) { id }
  }
`;

const PROJECT_COLORS = ['#6366f1', '#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6', '#14b8a6', '#f97316', '#06b6d4', '#e11d48'];

export default function WorkloadPage() {
    const router = useRouter();
    const { themeColor } = usePreferencesStore();
    const { resolvedTheme } = useTheme();
    const [messageApi, contextHolder] = message.useMessage();
    const [mounted, setMounted] = useState(false);
    const [loading, setLoading] = useState(true);
    const [tasks, setTasks] = useState<any[]>([]);
    const [projects, setProjects] = useState<any[]>([]);
    const [viewMode, setViewMode] = useState<string>("heatmap");
    const [filterProject, setFilterProject] = useState<string | null>(null);
    const [filterPeriod, setFilterPeriod] = useState<string>("all");
    const [searchName, setSearchName] = useState("");
    const [expandedRows, setExpandedRows] = useState<string[]>([]);

    useEffect(() => setMounted(true), []);
    const isDark = mounted && resolvedTheme === "dark";

    const glassCard = useMemo(() => ({
        background: isDark ? "rgba(15, 15, 23, 0.7)" : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(12px)",
        border: isDark ? "1px solid rgba(139,92,246,0.15)" : "1px solid rgba(0,0,0,0.06)",
        borderRadius: 12,
    }), [isDark]);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [tData, pData] = await Promise.all([
                gql(GET_TASKS, { tenantId: DEFAULT_TENANT_ID }),
                gql(GET_PROJECTS, { tenantId: DEFAULT_TENANT_ID }),
            ]);
            setTasks(tData.pmTasks || []);
            setProjects(pData.pmProjects || []);
        } catch (err: any) { 
            messageApi.error("Failed to load workload data: " + err.message);
        } finally { setLoading(false); }
    }, [messageApi]);

    useEffect(() => { loadData(); }, [loadData]);

    // ── Filter tasks ──
    const filteredTasks = useMemo(() => {
        let result = tasks;
        if (filterProject) result = result.filter(t => t.projectId === filterProject);
        if (filterPeriod === "week") {
            const start = dayjs().startOf("week");
            const end = dayjs().endOf("week");
            result = result.filter(t => {
                const d = t.dueDate ? dayjs(t.dueDate) : t.startDate ? dayjs(t.startDate) : null;
                return d && d.isAfter(start) && d.isBefore(end);
            });
        } else if (filterPeriod === "month") {
            const start = dayjs().startOf("month");
            const end = dayjs().endOf("month");
            result = result.filter(t => {
                const d = t.dueDate ? dayjs(t.dueDate) : t.startDate ? dayjs(t.startDate) : null;
                return d && d.isAfter(start) && d.isBefore(end);
            });
        }
        return result;
    }, [tasks, filterProject, filterPeriod]);

    // ── Build team member data ──
    const teamData = useMemo(() => {
        const map = new Map<string, {
            id: string; name: string; firstName: string; lastName: string;
            tasks: any[]; totalEstimated: number; totalLogged: number;
            byProject: Map<string, number>; byStatus: Record<string, number>;
        }>();
        filteredTasks.forEach(t => {
            if (!t.assigneeId || !t.assignee) return;
            const key = t.assigneeId;
            if (!map.has(key)) {
                map.set(key, {
                    id: key,
                    name: `${t.assignee.firstName} ${t.assignee.lastName}`,
                    firstName: t.assignee.firstName,
                    lastName: t.assignee.lastName,
                    tasks: [], totalEstimated: 0, totalLogged: 0,
                    byProject: new Map(), byStatus: {},
                });
            }
            const m = map.get(key)!;
            m.tasks.push(t);
            m.totalEstimated += t.estimatedHours || 0;
            m.totalLogged += t.loggedHours || 0;
            const projName = projects.find(p => p.id === t.projectId)?.name || "Other";
            m.byProject.set(projName, (m.byProject.get(projName) || 0) + (t.estimatedHours || 0));
            m.byStatus[t.status] = (m.byStatus[t.status] || 0) + 1;
        });
        let result = Array.from(map.values()).sort((a, b) => b.totalEstimated - a.totalEstimated);
        if (searchName) result = result.filter(m => m.name.toLowerCase().includes(searchName.toLowerCase()));
        return result;
    }, [filteredTasks, projects, searchName]);

    const unassignedTasks = useMemo(() => filteredTasks.filter(t => !t.assigneeId), [filteredTasks]);
    const totalMembers = teamData.length;
    const totalEstimated = teamData.reduce((s, m) => s + m.totalEstimated, 0);
    const avgHours = totalMembers > 0 ? Math.round(totalEstimated / totalMembers) : 0;
    const overloaded = teamData.filter(m => m.totalEstimated > 40).length;

    // ── Heatmap chart data ──
    const projectNameList = useMemo(() => {
        const set = new Set<string>();
        teamData.forEach(m => m.byProject.forEach((_, name) => set.add(name)));
        return Array.from(set);
    }, [teamData]);

    const heatmapData = useMemo(() => teamData.map(m => {
        const entry: any = { name: m.name.length > 14 ? m.name.slice(0, 14) + "…" : m.name, total: m.totalEstimated };
        projectNameList.forEach(pn => { entry[pn] = m.byProject.get(pn) || 0; });
        return entry;
    }), [teamData, projectNameList]);

    // ── Workload color ──
    const getLoadColor = (hours: number) => hours > 40 ? "#ef4444" : hours > 30 ? "#f59e0b" : "#10b981";
    const getLoadLabel = (hours: number) => hours > 40 ? "Overloaded" : hours > 30 ? "At Capacity" : "Available";

    // ── Drag Handlers ──
    const handleDragEnd = async (result: DropResult) => {
        const { source, destination, draggableId } = result;
        if (!destination) return;
        if (source.droppableId === destination.droppableId) return;

        const newAssigneeId = destination.droppableId === "unassigned" ? null : destination.droppableId;
        
        // Optimistic UI update
        setTasks(prev => prev.map(t => t.id === draggableId ? { ...t, assigneeId: newAssigneeId } : t));
        
        try {
            await gql(UPDATE_TASK_ASSIGNEE, { id: draggableId, assigneeId: newAssigneeId });
            messageApi.success("Task reassigned");
        } catch (err: any) {
            console.error(err);
            messageApi.error("Failed to reassign task");
            loadData(); // revert
        }
    };

    // ── Table columns ──
    const tableColumns = [
        {
            title: "Name", dataIndex: "name", key: "name", sorter: (a: any, b: any) => a.name.localeCompare(b.name),
            render: (name: string, r: any) => (
                <Space>
                    <Avatar size={28} style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}bb)`, fontSize: 11 }}>
                        {r.firstName?.[0]}{r.lastName?.[0]}
                    </Avatar>
                    <div>
                        <Text strong style={{ fontSize: 12 }}>{name}</Text>
                        {r.totalEstimated > 40 && <Tag color="red" style={{ fontSize: 9, marginLeft: 4, borderRadius: 8 }}>OVERLOADED</Tag>}
                    </div>
                </Space>
            ),
        },
        {
            title: "Active", key: "active", width: 75, sorter: (a: any, b: any) => (a.byStatus.in_progress || 0) - (b.byStatus.in_progress || 0),
            render: (_: any, r: any) => <Text style={{ fontSize: 12 }}>{(r.byStatus.in_progress || 0) + (r.byStatus.todo || 0)}</Text>,
        },
        {
            title: "Done", key: "done", width: 70, sorter: (a: any, b: any) => (a.byStatus.done || 0) - (b.byStatus.done || 0),
            render: (_: any, r: any) => <Text style={{ fontSize: 12, color: "#10b981" }}>{r.byStatus.done || 0}</Text>,
        },
        {
            title: "Estimated", dataIndex: "totalEstimated", key: "est", width: 100,
            sorter: (a: any, b: any) => a.totalEstimated - b.totalEstimated,
            render: (v: number) => <Text style={{ fontSize: 12, fontWeight: 600, color: getLoadColor(v) }}>{v}h</Text>,
        },
        {
            title: "Logged", dataIndex: "totalLogged", key: "logged", width: 90,
            sorter: (a: any, b: any) => a.totalLogged - b.totalLogged,
            render: (v: number) => <Text style={{ fontSize: 12 }}>{v}h</Text>,
        },
        {
            title: "Utilization", key: "util", width: 120,
            sorter: (a: any, b: any) => {
                const ua = a.totalEstimated > 0 ? a.totalLogged / a.totalEstimated : 0;
                const ub = b.totalEstimated > 0 ? b.totalLogged / b.totalEstimated : 0;
                return ua - ub;
            },
            render: (_: any, r: any) => {
                const pct = r.totalEstimated > 0 ? Math.round((r.totalLogged / r.totalEstimated) * 100) : 0;
                return <Progress percent={Math.min(pct, 100)} size="small" strokeColor={pct > 100 ? "#ef4444" : themeColor}
                    trailColor={isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)"} format={() => `${pct}%`} />;
            },
        },
        {
            title: "Projects", key: "projects", width: 200,
            render: (_: any, r: any) => (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 3 }}>
                    {(Array.from(r.byProject.keys()) as string[]).slice(0, 3).map((pn: string) => (
                        <Tag key={pn} style={{ fontSize: 9, borderRadius: 8, margin: 0 }}>{pn}</Tag>
                    ))}
                    {r.byProject.size > 3 && <Tag style={{ fontSize: 9, borderRadius: 8, margin: 0 }}>+{r.byProject.size - 3}</Tag>}
                </div>
            ),
        },
    ];

    // ── Expanded row: member's task list ──
    const expandedRowRender = (record: any) => {
        const memberTasks = record.tasks.sort((a: any, b: any) => (b.estimatedHours || 0) - (a.estimatedHours || 0));
        const statusColor: Record<string, string> = { todo: "#64748b", in_progress: "#3b82f6", done: "#10b981", blocked: "#ef4444", review: "#8b5cf6" };
        return (
            <div style={{ padding: "8px 16px" }}>
                {memberTasks.map((t: any) => (
                    <div key={t.id} style={{
                        display: "flex", justifyContent: "space-between", alignItems: "center",
                        padding: "6px 0", borderBottom: `1px solid ${isDark ? "rgba(255,255,255,0.04)" : "#f5f5f5"}`,
                    }}>
                        <Space size={8}>
                            <Tag color={statusColor[t.status] || "#6b7280"} style={{ fontSize: 9, borderRadius: 8 }}>
                                {(t.status || "").replace(/_/g, " ").toUpperCase()}
                            </Tag>
                            <Text style={{ fontSize: 12 }}>{t.title}</Text>
                        </Space>
                        <Space size={12}>
                            <Text type="secondary" style={{ fontSize: 10 }}>{t.estimatedHours || 0}h est</Text>
                            <Text type="secondary" style={{ fontSize: 10 }}>{t.loggedHours || 0}h log</Text>
                            {t.dueDate && <Text type="secondary" style={{ fontSize: 10 }}>{dayjs(t.dueDate).format("MMM D")}</Text>}
                        </Space>
                    </div>
                ))}
            </div>
        );
    };

    if (loading) {
        return (
            <CMSLayout title={<AuroraText colors={[themeColor, "#3b82f6", "#10b981"]}>Workload</AuroraText>}
                subTitle={<DecryptedText text="Team resource capacity management" animateOn="view" revealDirection="start" speed={40} sequential />}>
                <div style={{ textAlign: "center", padding: 120 }}><Spin size="large" /></div>
            </CMSLayout>
        );
    }

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, "#3b82f6", "#10b981"]}>Workload</AuroraText>}
            subTitle={<DecryptedText text="Team resource capacity management" animateOn="view" revealDirection="start" speed={40} sequential />}
            extra={[
                <RbacGuard key="exports" requiredRole="manager">
                    <Space>
                        <Tooltip title="Export to Excel">
                            <Button icon={<FileExcelOutlined />} size="small" onClick={() => exportToExcel({
                                fileName: 'pm_workload',
                                title: 'Team Workload Report',
                                columns: [{ header: 'Name', key: 'name' }, { header: 'Active', key: 'active' }, { header: 'Estimated', key: 'totalEstimated' }, { header: 'Logged', key: 'totalLogged' }],
                                data: teamData.map(m => ({ name: m.name, active: (m.byStatus.in_progress || 0) + (m.byStatus.todo || 0), totalEstimated: m.totalEstimated, totalLogged: m.totalLogged }))
                            })} />
                        </Tooltip>
                        <Tooltip title="Export to PDF">
                            <Button icon={<FilePdfOutlined />} size="small" onClick={() => exportToPdf({
                                fileName: 'pm_workload',
                                title: 'Team Workload Report',
                                columns: [{ header: 'Name', key: 'name' }, { header: 'Active', key: 'active' }, { header: 'Estimated', key: 'totalEstimated' }, { header: 'Logged', key: 'totalLogged' }],
                                data: teamData.map(m => ({ name: m.name, active: (m.byStatus.in_progress || 0) + (m.byStatus.todo || 0), totalEstimated: m.totalEstimated, totalLogged: m.totalLogged }))
                            })} />
                        </Tooltip>
                    </Space>
                </RbacGuard>
            ]}
        >
            {contextHolder}
            {/* ── Unassigned Alert ── */}
            {unassignedTasks.length > 0 && (
                <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}>
                    <Alert
                        type="warning" showIcon icon={<ExclamationCircleOutlined />}
                        message={<Text strong style={{ fontSize: 13 }}>{unassignedTasks.length} task{unassignedTasks.length > 1 ? "s are" : " is"} unassigned</Text>}
                        description={<Text type="secondary" style={{ fontSize: 11 }}>These tasks have no team member assigned and won't appear in workload calculations.</Text>}
                        action={<Button size="small" type="primary" onClick={() => router.push("/admin/pm/backlog")}
                            style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}dd)`, border: "none", borderRadius: 8 }}>View Backlog</Button>}
                        style={{ ...glassCard, marginBottom: 16, borderLeft: "4px solid #f59e0b" }}
                    />
                </motion.div>
            )}

            {/* ── Summary Stats ── */}
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.4 }}>
                <BentoGrid className="max-w-full mb-5">
                    {[
                        { label: "Team Members", value: totalMembers, color: "#3b82f6", icon: <TeamOutlined /> },
                        { label: "Avg Hours/Person", value: avgHours, suffix: "h", color: themeColor, icon: <ClockCircleOutlined /> },
                        { label: "Overloaded", value: overloaded, color: overloaded > 0 ? "#ef4444" : "#10b981", icon: <FireOutlined /> },
                        { label: "Unassigned Tasks", value: unassignedTasks.length, color: unassignedTasks.length > 0 ? "#f59e0b" : "#10b981", icon: <WarningOutlined /> },
                    ].map((s, i) => (
                        <BentoGridItem
                            key={i}
                            title={s.label}
                            description="Resource metric"
                            icon={<span style={{ color: s.color }}>{s.icon}</span>}
                            header={
                                <div className="flex h-full w-full flex-col items-center justify-center rounded-xl" style={{ backgroundColor: `${s.color}15` }}>
                                    <div style={{ fontSize: 32, fontWeight: 800, color: s.color }}>
                                        {s.value}
                                        {s.suffix && <span style={{ fontSize: 20 }}>{s.suffix}</span>}
                                    </div>
                                </div>
                            }
                            className="col-span-4 lg:col-span-1"
                        />
                    ))}
                </BentoGrid>
            </motion.div>

            {/* ── Team Utilization BentoGrid ── */}
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.12 }}>
                <BentoGrid className="max-w-full mb-5 md:grid-cols-3 md:auto-rows-[20rem]">
                    {/* Capacity Distribution */}
                    <BentoGridItem
                        title={<div className="flex items-center gap-2"><TeamOutlined className="text-blue-500" /> <span className="text-lg font-bold">Capacity Distribution</span></div>}
                        description="Team workload balancing"
                        header={
                            <div className="flex h-full w-full flex-1 flex-col items-center justify-center rounded-xl bg-blue-500/5 p-4">
                                {(() => {
                                    const capacityDistribution = [
                                        { name: "Available", value: teamData.filter(m => m.totalEstimated <= 30).length, color: "#10b981" },
                                        { name: "At Capacity", value: teamData.filter(m => m.totalEstimated > 30 && m.totalEstimated <= 40).length, color: "#f59e0b" },
                                        { name: "Overloaded", value: teamData.filter(m => m.totalEstimated > 40).length, color: "#ef4444" },
                                    ];
                                    const total = capacityDistribution.reduce((s, d) => s + d.value, 0);
                                    return (
                                        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 16, width: '100%', height: '100%' }}>
                                            <div style={{ width: 140, height: 140, position: "relative" }}>
                                                <ResponsiveContainer>
                                                    <PieChart>
                                                        <Pie data={capacityDistribution} cx="50%" cy="50%" innerRadius={40} outerRadius={65} paddingAngle={3} dataKey="value" stroke="none" isAnimationActive={true} animationDuration={1000} animationBegin={200} animationEasing="ease-out">
                                                            {capacityDistribution.map((entry, idx) => (
                                                                <Cell key={idx} fill={entry.color} style={{ outline: 'none', transition: 'all 0.3s ease' }} className="hover:opacity-80" />
                                                            ))}
                                                        </Pie>
                                                        <RTooltip contentStyle={{ background: isDark ? "rgba(15,15,23,0.95)" : "#fff", border: isDark ? "1px solid rgba(139,92,246,0.2)" : "1px solid #e5e7eb", borderRadius: 8, fontSize: 12, boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} cursor={{ fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)' }} />
                                                    </PieChart>
                                                </ResponsiveContainer>
                                                <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)", textAlign: "center" }}>
                                                    <Text style={{ fontSize: 18, fontWeight: 700, display: "block", lineHeight: 1.1 }}>{total}</Text>
                                                    <Text type="secondary" style={{ fontSize: 9 }}>members</Text>
                                                </div>
                                            </div>
                                            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                                                {capacityDistribution.map(d => (
                                                    <div key={d.name} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                                        <div style={{ width: 10, height: 10, borderRadius: 3, background: d.color }} />
                                                        <Text type="secondary" style={{ fontSize: 11, minWidth: 70 }}>{d.name}</Text>
                                                        <Text style={{ fontSize: 13, fontWeight: 600 }}>{d.value}</Text>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    );
                                })()}
                            </div>
                        }
                        className="md:col-span-1"
                        icon={null}
                    />

                    {/* Hours by Project */}
                    <BentoGridItem
                        title={<div className="flex items-center gap-2"><ProjectOutlined className="text-purple-500" /> <span className="text-lg font-bold">Hours by Project</span></div>}
                        description="Top 5 projects by estimated hours"
                        header={
                            <div className="flex h-full w-full flex-1 flex-col justify-center rounded-xl bg-purple-500/5 p-4">
                                {(() => {
                                    const projectHoursData = projectNameList.map(pn => {
                                        let sum = 0;
                                        teamData.forEach(m => { sum += m.byProject.get(pn) || 0; });
                                        return { name: pn, hours: sum };
                                    }).sort((a,b) => b.hours - a.hours).slice(0, 5); // top 5 projects
                                    
                                    return (
                                        <div style={{ height: '100%', minHeight: 180, width: '100%' }}>
                                            <ResponsiveContainer>
                                                <BarChart data={projectHoursData} margin={{ left: 0, right: 10, top: 5, bottom: 20 }}>
                                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDark ? "rgba(255,255,255,0.06)" : "#f0f0f0"} />
                                                    <XAxis dataKey="name" tick={{ fontSize: 10 }} axisLine={false} tickLine={false} interval={0} angle={-15} textAnchor="end" />
                                                    <YAxis tick={{ fontSize: 10 }} unit="h" axisLine={false} tickLine={false} />
                                                    <RTooltip contentStyle={{ background: isDark ? "rgba(15,15,23,0.95)" : "#fff", border: isDark ? "1px solid rgba(139,92,246,0.2)" : "1px solid #e5e7eb", borderRadius: 8, fontSize: 12, boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} cursor={{ fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)' }} />
                                                    <Bar dataKey="hours" radius={[4, 4, 0, 0]} isAnimationActive={true} animationDuration={1000} animationBegin={300} animationEasing="ease-out">
                                                        {projectHoursData.map((entry, index) => (
                                                            <Cell key={`cell-${index}`} fill={PROJECT_COLORS[index % PROJECT_COLORS.length]} style={{ outline: 'none', transition: 'all 0.3s ease' }} className="hover:opacity-80" />
                                                        ))}
                                                    </Bar>
                                                </BarChart>
                                            </ResponsiveContainer>
                                        </div>
                                    );
                                })()}
                            </div>
                        }
                        className="md:col-span-2"
                        icon={null}
                    />

                    {/* Total Hours Summary */}
                    <BentoGridItem
                        title={<div className="flex items-center gap-2"><ClockCircleOutlined className="text-emerald-500" /> <span className="text-lg font-bold">Total Hours Summary</span></div>}
                        description="Overall estimated vs logged hours"
                        header={
                            <div className="flex h-full w-full flex-1 flex-row items-center justify-around rounded-xl bg-emerald-500/5 p-4">
                                <Statistic title={<Text style={{ fontSize: 12 }}>Total Estimated</Text>} value={totalEstimated} suffix="h" valueStyle={{ fontSize: 28, fontWeight: 700, color: themeColor }} />
                                <div style={{ width: 1, height: 50, background: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.06)" }} />
                                <Statistic title={<Text style={{ fontSize: 12 }}>Total Logged</Text>} value={teamData.reduce((s, m) => s + m.totalLogged, 0)} suffix="h" valueStyle={{ fontSize: 28, fontWeight: 700, color: "#10b981" }} />
                                <div style={{ width: 1, height: 50, background: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.06)" }} />
                                <Statistic title={<Text style={{ fontSize: 12 }}>Capacity Used</Text>} value={totalMembers > 0 ? Math.round((totalEstimated / (totalMembers * 40)) * 100) : 0} suffix="%" valueStyle={{ fontSize: 28, fontWeight: 700 }} />
                            </div>
                        }
                        className="md:col-span-3 md:auto-rows-[10rem]"
                        icon={null}
                    />
                </BentoGrid>
            </motion.div>

            {/* ── Filters ── */}
            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                <Card size="small" style={{ ...glassCard, marginBottom: 20 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
                        <ProjectOutlined style={{ color: themeColor }} />
                        <Select placeholder="All Projects" value={filterProject} onChange={setFilterProject} allowClear showSearch
                            optionFilterProp="label" style={{ minWidth: 200 }}
                            options={projects.map(p => ({ value: p.id, label: `${p.name} (${p.projectNumber})` }))} />
                        <Select value={filterPeriod} onChange={setFilterPeriod} style={{ width: 130 }}
                            options={[{ value: "all", label: "All Time" }, { value: "week", label: "This Week" }, { value: "month", label: "This Month" }]} />
                        <Input prefix={<SearchOutlined />} placeholder="Search member…" value={searchName}
                            onChange={e => setSearchName(e.target.value)} style={{ width: 180 }} allowClear />
                        <div style={{ flex: 1 }} />
                        <Segmented value={viewMode} onChange={(v) => setViewMode(v as string)}
                            options={[
                                { value: "heatmap", icon: <UnorderedListOutlined />, label: "Heatmap" },
                                { value: "cards", icon: <AppstoreOutlined />, label: "Cards" },
                                { value: "board", icon: <AppstoreOutlined />, label: "Interactive Board" },
                            ]} />
                    </div>
                </Card>
            </motion.div>

            {/* ── Heatmap View ── */}
            {viewMode === "heatmap" && (
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                    <Card title={<Space><TeamOutlined style={{ color: themeColor }} /> Workload Heatmap</Space>} size="small"
                        style={{ ...glassCard, marginBottom: 20 }}>
                        {heatmapData.length === 0 ? <Empty description="No team members with assigned tasks" /> : (
                            <div style={{ height: Math.max(250, heatmapData.length * 44 + 60) }}>
                                <ResponsiveContainer>
                                    <BarChart data={heatmapData} layout="vertical" margin={{ left: 10, right: 30, top: 5, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke={isDark ? "rgba(255,255,255,0.06)" : "#f0f0f0"} />
                                        <XAxis type="number" tick={{ fontSize: 10 }} unit="h" />
                                        <YAxis dataKey="name" type="category" width={110} tick={{ fontSize: 11 }} />
                                        <RTooltip contentStyle={{
                                            background: isDark ? "rgba(15,15,23,0.95)" : "#fff",
                                            border: isDark ? "1px solid rgba(139,92,246,0.2)" : "1px solid #e5e7eb",
                                            borderRadius: 8, fontSize: 12,
                                        }} />
                                        <Legend wrapperStyle={{ fontSize: 10 }} />
                                        <ReferenceLine x={40} stroke="#ef4444" strokeDasharray="4 4" strokeWidth={1.5}
                                            label={{ value: "40h Capacity", position: "top", fontSize: 10, fill: "#ef4444" }} />
                                        {projectNameList.map((pn, i) => (
                                            <Bar key={pn} dataKey={pn} stackId="hours" fill={PROJECT_COLORS[i % PROJECT_COLORS.length]}
                                                radius={i === projectNameList.length - 1 ? [0, 4, 4, 0] : [0, 0, 0, 0]} />
                                        ))}
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                        {/* Color legend */}
                        <div style={{ display: "flex", gap: 16, marginTop: 8, justifyContent: "center" }}>
                            {[{ label: "Available (<30h)", color: "#10b981" }, { label: "At Capacity (30-40h)", color: "#f59e0b" }, { label: "Overloaded (>40h)", color: "#ef4444" }].map(l => (
                                <Space key={l.label} size={4}>
                                    <div style={{ width: 10, height: 10, borderRadius: 3, background: l.color }} />
                                    <Text type="secondary" style={{ fontSize: 10 }}>{l.label}</Text>
                                </Space>
                            ))}
                        </div>
                    </Card>
                </motion.div>
            )}

            {/* ── Card Grid View ── */}
            {viewMode === "cards" && (
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                    {teamData.length === 0 ? (
                        <Card style={glassCard}><Empty description="No team members with assigned tasks" /></Card>
                    ) : (
                        <Row gutter={[16, 16]} style={{ marginBottom: 20 }}>
                            {teamData.map((m, i) => {
                                const utilPct = m.totalEstimated > 0 ? Math.round((m.totalLogged / m.totalEstimated) * 100) : 0;
                                const loadColor = getLoadColor(m.totalEstimated);
                                const statusIcons: Record<string, { icon: React.ReactNode; color: string }> = {
                                    todo: { icon: <PauseCircleOutlined />, color: "#64748b" },
                                    in_progress: { icon: <SyncOutlined />, color: "#3b82f6" },
                                    done: { icon: <CheckCircleOutlined />, color: "#10b981" },
                                    blocked: { icon: <ExclamationCircleOutlined />, color: "#ef4444" },
                                };
                                return (
                                    <Col xs={24} sm={12} lg={8} xl={6} key={m.id}>
                                        <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ delay: i * 0.04 }} whileHover={{ y: -4, scale: 1.02 }} style={{ height: '100%' }}>
                                            <Card hoverable size="small" style={{ ...glassCard, borderTop: `3px solid ${loadColor}`, height: '100%', display: 'flex', flexDirection: 'column' }} bodyStyle={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                                                <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 12 }}>
                                                    <Avatar size={40} style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}bb)`, fontWeight: 700, fontSize: 14 }}>
                                                        {m.firstName?.[0]}{m.lastName?.[0]}
                                                    </Avatar>
                                                    <div style={{ flex: 1, minWidth: 0 }}>
                                                        <Text strong style={{ fontSize: 13, display: "block" }}>{m.name}</Text>
                                                        <Space size={8}>
                                                            <Text type="secondary" style={{ fontSize: 10 }}>{m.tasks.length} tasks</Text>
                                                            <Text style={{ fontSize: 10, fontWeight: 600, color: loadColor }}>{m.totalEstimated}h</Text>
                                                        </Space>
                                                    </div>
                                                    {m.totalEstimated > 40 && (
                                                        <Tooltip title="Overloaded — above 40h capacity">
                                                            <FireOutlined style={{ color: "#ef4444", fontSize: 16 }} />
                                                        </Tooltip>
                                                    )}
                                                </div>
                                                {/* Capacity bar */}
                                                <div style={{ marginBottom: 10 }}>
                                                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                                                        <Text type="secondary" style={{ fontSize: 10 }}>Capacity</Text>
                                                        <Text style={{ fontSize: 10, fontWeight: 600, color: loadColor }}>{m.totalEstimated}h / 40h</Text>
                                                    </div>
                                                    <div style={{ height: 8, borderRadius: 4, background: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)", overflow: "hidden" }}>
                                                        <div style={{
                                                            width: `${Math.min(100, (m.totalEstimated / 40) * 100)}%`,
                                                            height: "100%", borderRadius: 4,
                                                            background: `linear-gradient(90deg, ${loadColor}cc, ${loadColor})`,
                                                            transition: "width 0.5s ease",
                                                        }} />
                                                    </div>
                                                    <div style={{ display: "flex", justifyContent: "space-between", marginTop: 2 }}>
                                                        <Text type="secondary" style={{ fontSize: 9 }}>Logged: {m.totalLogged}h</Text>
                                                        <Text type="secondary" style={{ fontSize: 9 }}>{getLoadLabel(m.totalEstimated)}</Text>
                                                    </div>
                                                </div>
                                                {/* Status dots */}
                                                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                                                    {Object.entries(m.byStatus).map(([status, count]) => {
                                                        const cfg = statusIcons[status] || { icon: <UserOutlined />, color: "#6b7280" };
                                                        return (
                                                            <Tooltip key={status} title={`${status.replace(/_/g, " ")}: ${count}`}>
                                                                <Tag icon={cfg.icon} color={cfg.color} style={{ fontSize: 9, borderRadius: 8, margin: 0 }}>
                                                                    {count}
                                                                </Tag>
                                                            </Tooltip>
                                                        );
                                                    })}
                                                </div>
                                                {/* Capacity label */}
                                                <div style={{ marginTop: 8, textAlign: "center" }}>
                                                    <Tag color={loadColor} style={{ fontSize: 9, borderRadius: 10 }}>{getLoadLabel(m.totalEstimated)}</Tag>
                                                </div>
                                            </Card>
                                        </motion.div>
                                    </Col>
                                );
                            })}
                        </Row>
                    )}
                </motion.div>
            )}

            {/* ── Task Distribution Table ── */}
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
                <Card title={<Space><TeamOutlined style={{ color: "#3b82f6" }} /> Task Distribution</Space>}
                    size="small" style={glassCard} extra={<Tag color="blue">{teamData.length} members</Tag>}>
                    <Table
                        dataSource={teamData} columns={tableColumns} rowKey="id" size="small"
                        pagination={teamData.length > 15 ? { pageSize: 15, showSizeChanger: false } : false}
                        scroll={{ x: 750 }}
                        expandable={{
                            expandedRowRender,
                            expandedRowKeys: expandedRows,
                            onExpand: (expanded, record) => setExpandedRows(expanded ? [...expandedRows, record.id] : expandedRows.filter(k => k !== record.id)),
                            rowExpandable: (record) => record.tasks.length > 0,
                        }}
                        onRow={() => ({ style: { cursor: "pointer" } })}
                    />
                </Card>
            </motion.div>


            {/* ── Interactive Board View ── */}
            {viewMode === "board" && (
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
                    <div style={{ display: "flex", gap: 20, overflowX: "auto", paddingBottom: 24, minHeight: "calc(100vh - 280px)" }}>
                        <DragDropContext onDragEnd={handleDragEnd}>
                            {[{ id: "unassigned", name: "Unassigned", tasks: unassignedTasks, totalEstimated: 0, totalLogged: 0 }, ...teamData].map(col => {
                                const isUnassigned = col.id === "unassigned";
                                const loadColor = isUnassigned ? "#6b7280" : getLoadColor(col.totalEstimated);
                                return (
                                    <div key={col.id} style={{ flex: "0 0 340px", display: "flex", flexDirection: "column" }}>
                                        {/* Column Header */}
                                        <div style={{
                                            ...glassCard,
                                            padding: "16px", marginBottom: 12,
                                            borderTop: `4px solid ${loadColor}`,
                                            position: "relative", overflow: "hidden"
                                        }}>
                                            <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 40, background: `linear-gradient(180deg, ${loadColor}1a, transparent)` }} />
                                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", position: "relative", zIndex: 1 }}>
                                                <Space>
                                                    {!isUnassigned ? (
                                                        <Avatar size={36} style={{ background: `linear-gradient(135deg, ${themeColor}, ${themeColor}bb)`, fontWeight: 700 }}>
                                                            {col.name.split(" ").map(n => n[0]).join("")}
                                                        </Avatar>
                                                    ) : (
                                                        <Avatar size={36} icon={<UserOutlined />} style={{ background: "#4b5563" }} />
                                                    )}
                                                    <div>
                                                        <Text strong style={{ fontSize: 14 }}>{col.name}</Text>
                                                        {!isUnassigned && (
                                                            <div style={{ fontSize: 11, color: isDark ? "rgba(255,255,255,0.45)" : "rgba(0,0,0,0.45)" }}>
                                                                <span style={{ color: loadColor, fontWeight: 600 }}>{col.totalEstimated}h</span> / 40h capacity
                                                            </div>
                                                        )}
                                                    </div>
                                                </Space>
                                                <Badge count={col.tasks.length} style={{ backgroundColor: isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.06)", color: isDark ? "#fff" : "#000", boxShadow: "none" }} />
                                            </div>
                                            {!isUnassigned && (
                                                <div style={{ marginTop: 12, height: 4, borderRadius: 2, background: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.04)", overflow: "hidden" }}>
                                                    <div style={{
                                                        width: `${Math.min(100, (col.totalEstimated / 40) * 100)}%`, height: "100%",
                                                        background: `linear-gradient(90deg, ${loadColor}cc, ${loadColor})`,
                                                        transition: "width 0.5s ease"
                                                    }} />
                                                </div>
                                            )}
                                        </div>

                                        {/* Column Body / Droppable Area */}
                                        <Droppable droppableId={col.id}>
                                            {(provided, snapshot) => (
                                                <div
                                                    ref={provided.innerRef}
                                                    {...provided.droppableProps}
                                                    style={{
                                                        flex: 1, padding: "12px 8px", borderRadius: 12,
                                                        background: snapshot.isDraggingOver ? (isDark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.03)") : "transparent",
                                                        border: snapshot.isDraggingOver ? `1px dashed ${themeColor}88` : "1px dashed transparent",
                                                        transition: "all 0.2s ease",
                                                        display: "flex", flexDirection: "column", gap: 12
                                                    }}
                                                >
                                                    {col.tasks.map((t, idx) => {
                                                        const pColor = PROJECT_COLORS[t.projectId?.length % PROJECT_COLORS.length || 0];
                                                        const projName = projects.find(p => p.id === t.projectId)?.name || "Task";
                                                        return (
                                                            <Draggable key={t.id} draggableId={t.id} index={idx}>
                                                                {(provided, snapshot) => (
                                                                    <div
                                                                        ref={provided.innerRef}
                                                                        {...provided.draggableProps}
                                                                        {...provided.dragHandleProps}
                                                                        style={{
                                                                            ...provided.draggableProps.style,
                                                                            ...glassCard,
                                                                            padding: "14px 16px",
                                                                            background: snapshot.isDragging ? (isDark ? "rgba(30,30,44,0.95)" : "#ffffff") : (isDark ? "rgba(20,20,30,0.7)" : "#ffffff"),
                                                                            boxShadow: snapshot.isDragging ? "0 12px 24px rgba(0,0,0,0.2)" : (isDark ? "0 4px 6px rgba(0,0,0,0.1)" : "0 1px 3px rgba(0,0,0,0.05)"),
                                                                            transform: snapshot.isDragging ? "scale(1.02) rotate(1deg)" : "none",
                                                                            borderLeft: `4px solid ${t.priority === 'high' ? '#ef4444' : t.priority === 'medium' ? '#f59e0b' : '#10b981'}`,
                                                                            cursor: "grab",
                                                                        }}
                                                                    >
                                                                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
                                                                            <Tag color={pColor} style={{ border: "none", margin: 0, borderRadius: 6, fontSize: 10, padding: "0 6px" }}>{projName}</Tag>
                                                                            <Tag style={{ border: "none", margin: 0, borderRadius: 6, fontSize: 9, background: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.04)" }}>
                                                                                {t.status.replace(/_/g, ' ').toUpperCase()}
                                                                            </Tag>
                                                                        </div>
                                                                        <Text strong style={{ fontSize: 13, lineHeight: 1.4, display: "block", marginBottom: 12 }}>{t.title}</Text>
                                                                        
                                                                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                                                            <Space size={16}>
                                                                                <Tooltip title="Estimated Hours">
                                                                                    <span style={{ fontSize: 11, color: isDark ? "rgba(255,255,255,0.6)" : "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", gap: 4 }}>
                                                                                        <ClockCircleOutlined /> {t.estimatedHours || 0}h
                                                                                    </span>
                                                                                </Tooltip>
                                                                                {t.dueDate && (
                                                                                    <span style={{ fontSize: 11, color: dayjs(t.dueDate).isBefore(dayjs()) ? "#ef4444" : (isDark ? "rgba(255,255,255,0.6)" : "rgba(0,0,0,0.6)") }}>
                                                                                        {dayjs(t.dueDate).format("MMM D")}
                                                                                    </span>
                                                                                )}
                                                                            </Space>
                                                                            {t.loggedHours > 0 && (
                                                                                <Tooltip title={`Logged: ${t.loggedHours}h`}>
                                                                                    <div style={{ width: 24, height: 24, borderRadius: "50%", background: isDark ? "rgba(16,185,129,0.15)" : "#d1fae5", color: "#10b981", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 9, fontWeight: 700 }}>
                                                                                        {t.loggedHours}
                                                                                    </div>
                                                                                </Tooltip>
                                                                            )}
                                                                        </div>
                                                                    </div>
                                                                )}
                                                            </Draggable>
                                                        );
                                                    })}
                                                    {provided.placeholder}
                                                </div>
                                            )}
                                        </Droppable>
                                    </div>
                                );
                            })}
                        </DragDropContext>
                    </div>
                </motion.div>
            )}
        </CMSLayout>
    );
}

'use client';
import React, { useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Space, Tag, Button, Table, Badge, Select, Input, Divider, message, Spin, Segmented, theme } from 'antd';
import {
    DatabaseOutlined, PlayCircleOutlined, SaveOutlined, DownloadOutlined,
    BarChartOutlined, LineChartOutlined, PieChartOutlined, AreaChartOutlined,
    TableOutlined, CodeOutlined, MenuFoldOutlined, MenuUnfoldOutlined,
    FileExcelOutlined, FilePdfOutlined, ClockCircleOutlined, ThunderboltOutlined,
} from '@ant-design/icons';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { dremioService, QueryResult } from '@/lib/dremioService';
import {
    BarChart, Bar, LineChart, Line, PieChart, Pie, AreaChart, Area,
    XAxis, YAxis, CartesianGrid, Tooltip as RTooltip, ResponsiveContainer, Cell, Legend,
} from 'recharts';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };
const COLORS = ['#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#ec4899', '#06b6d4', '#f97316'];

const SUPABASE_TABLES = ['users', 'employees', 'invoices', 'tickets', 'contacts', 'projects', 'inventory_items'];

const DEMO_DATA: Record<string, any>[] = [
    { id: 1, name: 'Andi Wijaya', department: 'Engineering', revenue: 125000, deals: 8, status: 'Active', region: 'Jakarta', score: 92 },
    { id: 2, name: 'Sari Dewi', department: 'Sales', revenue: 245000, deals: 15, status: 'Active', region: 'Surabaya', score: 88 },
    { id: 3, name: 'Budi Santoso', department: 'Marketing', revenue: 89000, deals: 5, status: 'Active', region: 'Bandung', score: 76 },
    { id: 4, name: 'Maya Putri', department: 'Support', revenue: 67000, deals: 3, status: 'Inactive', region: 'Medan', score: 81 },
    { id: 5, name: 'Riko Pratama', department: 'Engineering', revenue: 198000, deals: 12, status: 'Active', region: 'Jakarta', score: 95 },
    { id: 6, name: 'Dian Lestari', department: 'Sales', revenue: 312000, deals: 18, status: 'Active', region: 'Yogyakarta', score: 90 },
    { id: 7, name: 'Hendra Gunawan', department: 'Finance', revenue: 156000, deals: 7, status: 'Active', region: 'Semarang', score: 85 },
    { id: 8, name: 'Nina Sari', department: 'Marketing', revenue: 73000, deals: 4, status: 'Inactive', region: 'Bali', score: 72 },
    { id: 9, name: 'Agus Salim', department: 'Support', revenue: 94000, deals: 6, status: 'Active', region: 'Makassar', score: 78 },
    { id: 10, name: 'Lina Marlina', department: 'Finance', revenue: 185000, deals: 10, status: 'Active', region: 'Jakarta', score: 87 },
];
const DEMO_COLUMNS = [
    { name: 'id', type: 'INTEGER' }, { name: 'name', type: 'VARCHAR' }, { name: 'department', type: 'VARCHAR' },
    { name: 'revenue', type: 'BIGINT' }, { name: 'deals', type: 'INTEGER' }, { name: 'status', type: 'VARCHAR' },
    { name: 'region', type: 'VARCHAR' }, { name: 'score', type: 'INTEGER' },
];

type ChartType = 'bar' | 'line' | 'pie' | 'area';
type ViewMode = 'table' | 'chart';

export default function ReportBuilderPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const glassCard = isDark ? glassDark : glass;
    const [messageApi, contextHolder] = message.useMessage();

    // Panel state
    const [leftCollapsed, setLeftCollapsed] = useState(false);

    // Data source state
    const [source, setSource] = useState<'supabase' | 'dremio'>('supabase');
    const [selectedTable, setSelectedTable] = useState<string>('');
    const [catalogItems, setCatalogItems] = useState<string[]>([]);
    const [catalogLoading, setCatalogLoading] = useState(false);
    const [dremioManualTable, setDremioManualTable] = useState('');

    // Query state
    const [sql, setSql] = useState('');
    const [running, setRunning] = useState(false);
    const [execTime, setExecTime] = useState(0);

    // Results state
    const [columns, setColumns] = useState<{ name: string; type: string }[]>([]);
    const [rows, setRows] = useState<Record<string, any>[]>([]);
    const [viewMode, setViewMode] = useState<ViewMode>('table');
    const [chartType, setChartType] = useState<ChartType>('bar');

    // Save state
    const [reportName, setReportName] = useState('');

    // ─── Load Dremio Catalog ──────────────────────────────────────────────
    const loadCatalog = useCallback(async () => {
        setCatalogLoading(true);
        try {
            const items = await dremioService.getCatalog();
            setCatalogItems(items.map(i => i.path.join('.')));
        } catch {
            setCatalogItems([]);
        }
        setCatalogLoading(false);
    }, []);

    // ─── Handle source change ─────────────────────────────────────────────
    const handleSourceChange = (val: 'supabase' | 'dremio') => {
        setSource(val);
        setSelectedTable('');
        setSql('');
        setColumns([]);
        setRows([]);
        if (val === 'dremio') loadCatalog();
    };

    // ─── Handle table select ─────────────────────────────────────────────
    const handleTableSelect = (table: string) => {
        setSelectedTable(table);
        const query = source === 'dremio'
            ? `SELECT * FROM ${table} LIMIT 100`
            : `SELECT * FROM "${table}" LIMIT 100`;
        setSql(query);
    };

    // ─── Run Query ────────────────────────────────────────────────────────
    const handleRunQuery = async () => {
        if (!sql.trim()) { messageApi.warning('Enter a SQL query first'); return; }
        setRunning(true);
        const start = Date.now();

        try {
            if (source === 'dremio') {
                const result: QueryResult = await dremioService.runSQL(sql.trim());
                setColumns(result.columns);
                setRows(result.rows.map((r, i) => ({ ...r, _key: i })));
                setExecTime(Date.now() - start);
                messageApi.success(`Query returned ${result.rowCount} rows`);
                setRunning(false);
                return;
            }
        } catch (err: any) {
            console.warn('Live query failed, using demo data:', err.message);
        }

        // Fallback: demo data
        setColumns(DEMO_COLUMNS);
        setRows(DEMO_DATA.map((r, i) => ({ ...r, _key: i })));
        setExecTime(Date.now() - start);
        messageApi.info('Showing demo data (live connection unavailable)');
        setRunning(false);
    };

    // ─── Chart helpers ────────────────────────────────────────────────────
    const stringCol = columns.find(c => ['VARCHAR', 'TEXT', 'CHAR', 'STRING'].some(t => c.type.toUpperCase().includes(t)));
    const numberCol = columns.find(c => ['INT', 'BIGINT', 'FLOAT', 'DOUBLE', 'DECIMAL', 'NUMBER', 'INTEGER'].some(t => c.type.toUpperCase().includes(t)));
    const xKey = stringCol?.name || columns[0]?.name || 'name';
    const yKey = numberCol?.name || columns[1]?.name || 'value';

    // ─── Export handlers ──────────────────────────────────────────────────
    const handleExportCsv = async () => {
        if (!rows.length) return;
        try {
            const csv = await dremioService.exportCsv(sql);
            dremioService.downloadCsv(csv, `${reportName || 'report'}.csv`);
            messageApi.success('CSV exported');
        } catch {
            const headers = columns.map(c => c.name).join(',');
            const csvRows = rows.map(r => columns.map(c => r[c.name] ?? '').join(','));
            const csv = [headers, ...csvRows].join('\n');
            dremioService.downloadCsv(csv, `${reportName || 'report'}.csv`);
            messageApi.success('CSV exported (local)');
        }
    };

    const handleExportExcel = async () => {
        if (!rows.length) return;
        try {
            await dremioService.downloadExcel({ jobId: '', rowCount: rows.length, columns, rows, status: 'COMPLETED' }, `${reportName || 'report'}.xlsx`);
            messageApi.success('Excel exported');
        } catch {
            messageApi.error('Excel export requires xlsx library');
        }
    };

    const handleExportPdf = () => {
        if (!rows.length) return;
        const printWin = window.open('', '_blank');
        if (!printWin) return;
        const tableHtml = `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:12px">
            <tr>${columns.map(c => `<th style="background:#f0f0f0">${c.name}</th>`).join('')}</tr>
            ${rows.map(r => `<tr>${columns.map(c => `<td>${r[c.name] ?? ''}</td>`).join('')}</tr>`).join('')}
        </table>`;
        printWin.document.write(`<html><head><title>${reportName || 'Report'}</title></head><body><h2>${reportName || 'Report'}</h2>${tableHtml}</body></html>`);
        printWin.document.close();
        printWin.print();
    };

    // ─── Save Report ──────────────────────────────────────────────────────
    const handleSaveReport = () => {
        if (!reportName.trim()) { messageApi.warning('Enter a report name'); return; }
        const saved = JSON.parse(localStorage.getItem('nusantara_saved_reports') || '[]');
        saved.push({ id: Date.now(), name: reportName, sql, source, chartType, table: selectedTable, savedAt: new Date().toISOString() });
        localStorage.setItem('nusantara_saved_reports', JSON.stringify(saved));
        messageApi.success(`Report "${reportName}" saved`);
    };

    // ─── Render Chart ─────────────────────────────────────────────────────
    const renderChart = () => {
        if (!rows.length) return <div style={{ textAlign: 'center', padding: 60 }}><Text type="secondary">Run a query first to visualize data</Text></div>;
        const chartData = rows.slice(0, 50);
        const common = { data: chartData, margin: { top: 10, right: 20, left: 10, bottom: 10 } };
        const gridStroke = isDark ? 'rgba(255,255,255,0.06)' : '#f0f0f0';

        return (
            <div style={{ height: 320 }}>
                <ResponsiveContainer>
                    {chartType === 'bar' ? (
                        <BarChart {...common}>
                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                            <XAxis dataKey={xKey} tick={{ fontSize: 10 }} />
                            <YAxis tick={{ fontSize: 10 }} />
                            <RTooltip />
                            <Legend />
                            <Bar dataKey={yKey} fill={themeColor || '#8b5cf6'} radius={[6, 6, 0, 0]} />
                        </BarChart>
                    ) : chartType === 'line' ? (
                        <LineChart {...common}>
                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                            <XAxis dataKey={xKey} tick={{ fontSize: 10 }} />
                            <YAxis tick={{ fontSize: 10 }} />
                            <RTooltip />
                            <Legend />
                            <Line type="monotone" dataKey={yKey} stroke={themeColor || '#3b82f6'} strokeWidth={2} dot={{ r: 3 }} />
                        </LineChart>
                    ) : chartType === 'area' ? (
                        <AreaChart {...common}>
                            <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                            <XAxis dataKey={xKey} tick={{ fontSize: 10 }} />
                            <YAxis tick={{ fontSize: 10 }} />
                            <RTooltip />
                            <Legend />
                            <Area type="monotone" dataKey={yKey} stroke={themeColor || '#10b981'} fill={themeColor || '#10b981'} fillOpacity={0.2} />
                        </AreaChart>
                    ) : (
                        <PieChart>
                            <Pie data={chartData} cx="50%" cy="50%" innerRadius={50} outerRadius={100} paddingAngle={2}
                                dataKey={yKey} nameKey={xKey} label={({ name, percent }) => `${name} (${(percent * 100).toFixed(0)}%)`}
                                labelLine={{ stroke: '#999', strokeWidth: 1 }}>
                                {chartData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                            </Pie>
                            <RTooltip />
                            <Legend />
                        </PieChart>
                    )}
                </ResponsiveContainer>
            </div>
        );
    };

    // ─── Table columns for Ant Design ─────────────────────────────────────
    const tableColumns = columns.map(c => ({
        title: c.name,
        dataIndex: c.name,
        key: c.name,
        ellipsis: true,
        render: (v: any) => {
            if (v === null || v === undefined) return <Text type="secondary" style={{ fontSize: 11 }}>null</Text>;
            if (typeof v === 'number') return <Text style={{ fontSize: 12, fontFamily: 'monospace', color: '#10b981' }}>{v.toLocaleString()}</Text>;
            return <Text style={{ fontSize: 12 }}>{String(v)}</Text>;
        },
    }));

    const sqlEditorStyle: React.CSSProperties = {
        width: '100%', fontFamily: "'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace",
        fontSize: 13, lineHeight: 1.6, background: '#1a1a2e', color: '#e2e8f0',
        border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, padding: '12px 14px',
        minHeight: 140, resize: 'vertical',
    };

    return (
        <CMSLayout
            title={<AuroraText colors={[themeColor, '#8b5cf6', '#06b6d4']}>Report Builder</AuroraText>}
            subTitle={<DecryptedText text="Query data sources, visualize results & export reports" animateOn="view" revealDirection="center" speed={40} maxIterations={15} sequential />}
            extra={[
                <Input key="name" placeholder="Report name…" size="small" value={reportName} onChange={e => setReportName(e.target.value)}
                    style={{ width: 180, borderRadius: 8 }} />,
                <Button key="save" icon={<SaveOutlined />} type="primary" onClick={handleSaveReport}>Save</Button>,
            ]}
        >
            {contextHolder}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <Row gutter={[14, 14]}>
                    {/* ═══════════ LEFT PANEL: Data Source ═══════════ */}
                    <Col xs={24} md={leftCollapsed ? 1 : 6}>
                        <AnimatePresence mode="wait">
                            {leftCollapsed ? (
                                <motion.div key="collapsed" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                                    <Button icon={<MenuUnfoldOutlined />} type="text" onClick={() => setLeftCollapsed(false)}
                                        style={{ ...glassCard, width: '100%', height: 48 }} />
                                </motion.div>
                            ) : (
                                <motion.div key="expanded" initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}>
                                    <Card size="small" style={glassCard}
                                        title={<Space><DatabaseOutlined style={{ color: '#3b82f6' }} /><Text strong>Data Source</Text></Space>}
                                        extra={<Button type="text" size="small" icon={<MenuFoldOutlined />} onClick={() => setLeftCollapsed(true)} />}>
                                        <Space direction="vertical" style={{ width: '100%' }} size={10}>
                                            <div>
                                                <Text type="secondary" style={{ fontSize: 11 }}>Source</Text>
                                                <Select value={source} onChange={handleSourceChange} style={{ width: '100%', marginTop: 4 }} size="small"
                                                    options={[
                                                        { label: '🐘 Supabase — nusantarasoft', value: 'supabase' },
                                                        { label: '🏔️ Dremio — Lakehouse', value: 'dremio' },
                                                    ]} />
                                            </div>

                                            {source === 'supabase' ? (
                                                <div>
                                                    <Text type="secondary" style={{ fontSize: 11 }}>Table</Text>
                                                    <Select value={selectedTable || undefined} placeholder="Select table…"
                                                        onChange={handleTableSelect} style={{ width: '100%', marginTop: 4 }} size="small"
                                                        options={SUPABASE_TABLES.map(t => ({ label: t, value: t }))} />
                                                </div>
                                            ) : (
                                                <>
                                                    <div>
                                                        <Text type="secondary" style={{ fontSize: 11 }}>Catalog {catalogLoading && <Spin size="small" />}</Text>
                                                        {catalogItems.length > 0 ? (
                                                            <Select value={selectedTable || undefined} placeholder="Select dataset…" showSearch
                                                                onChange={handleTableSelect} style={{ width: '100%', marginTop: 4 }} size="small"
                                                                options={catalogItems.map(t => ({ label: t, value: t }))} />
                                                        ) : (
                                                            <>
                                                                <Input size="small" placeholder="schema.table" value={dremioManualTable}
                                                                    onChange={e => setDremioManualTable(e.target.value)} style={{ marginTop: 4 }} />
                                                                <Button size="small" block type="dashed" style={{ marginTop: 4 }}
                                                                    onClick={() => { if (dremioManualTable) handleTableSelect(dremioManualTable); }}>
                                                                    Use Table
                                                                </Button>
                                                            </>
                                                        )}
                                                    </div>
                                                </>
                                            )}

                                            <Divider style={{ margin: '4px 0' }} />
                                            <div>
                                                <Text type="secondary" style={{ fontSize: 11 }}>Quick Tables</Text>
                                                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginTop: 6 }}>
                                                    {(source === 'supabase' ? SUPABASE_TABLES : ['Samples.SF_incidents2016.csv', 'sys.options']).map(t => (
                                                        <Tag key={t} style={{ fontSize: 10, cursor: 'pointer', borderRadius: 6 }}
                                                            onClick={() => handleTableSelect(t)}>{t}</Tag>
                                                    ))}
                                                </div>
                                            </div>
                                        </Space>
                                    </Card>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </Col>

                    {/* ═══════════ CENTER PANEL: SQL Editor ═══════════ */}
                    <Col xs={24} md={leftCollapsed ? 11 : 9}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}>
                            <Card size="small" style={glassCard}
                                title={<Space><CodeOutlined style={{ color: '#f59e0b' }} /><Text strong>SQL Editor</Text>
                                    <Tag color={source === 'dremio' ? 'blue' : 'green'} style={{ fontSize: 10, borderRadius: 8 }}>{source}</Tag>
                                </Space>}
                                extra={
                                    <Button icon={<PlayCircleOutlined />} type="primary" size="small" loading={running} onClick={handleRunQuery}
                                        style={{ borderRadius: 8 }}>
                                        Run Query
                                    </Button>
                                }>
                                <textarea value={sql} onChange={e => setSql(e.target.value)} placeholder="-- Write your SQL query here&#10;SELECT * FROM table_name LIMIT 100"
                                    style={sqlEditorStyle} spellCheck={false} />
                                {rows.length > 0 && (
                                    <Space style={{ marginTop: 10 }} size={12}>
                                        <Tag icon={<ThunderboltOutlined />} color="green" style={{ borderRadius: 8 }}>{execTime}ms</Tag>
                                        <Tag icon={<TableOutlined />} color="blue" style={{ borderRadius: 8 }}>{rows.length} rows</Tag>
                                        <Tag icon={<DatabaseOutlined />} color="purple" style={{ borderRadius: 8 }}>{columns.length} columns</Tag>
                                    </Space>
                                )}
                            </Card>
                        </motion.div>
                    </Col>

                    {/* ═══════════ RIGHT PANEL: Controls ═══════════ */}
                    <Col xs={24} md={leftCollapsed ? 12 : 9}>
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
                            <Card size="small" style={glassCard}
                                title={<Space><BarChartOutlined style={{ color: '#8b5cf6' }} /><Text strong>Visualization</Text></Space>}>
                                <Space direction="vertical" style={{ width: '100%' }} size={10}>
                                    <div>
                                        <Text type="secondary" style={{ fontSize: 11 }}>View Mode</Text>
                                        <div style={{ marginTop: 6 }}>
                                            <Segmented value={viewMode} onChange={v => setViewMode(v as ViewMode)} block
                                                options={[
                                                    { label: <Space size={4}><TableOutlined />Table</Space>, value: 'table' },
                                                    { label: <Space size={4}><BarChartOutlined />Chart</Space>, value: 'chart' },
                                                ]} />
                                        </div>
                                    </div>
                                    {viewMode === 'chart' && (
                                        <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }}>
                                            <Text type="secondary" style={{ fontSize: 11 }}>Chart Type</Text>
                                            <Row gutter={[6, 6]} style={{ marginTop: 6 }}>
                                                {([
                                                    { key: 'bar', icon: <BarChartOutlined />, label: 'Bar' },
                                                    { key: 'line', icon: <LineChartOutlined />, label: 'Line' },
                                                    { key: 'pie', icon: <PieChartOutlined />, label: 'Pie' },
                                                    { key: 'area', icon: <AreaChartOutlined />, label: 'Area' },
                                                ] as const).map(ct => (
                                                    <Col key={ct.key} span={6}>
                                                        <Button size="small" block type={chartType === ct.key ? 'primary' : 'default'}
                                                            icon={ct.icon} onClick={() => setChartType(ct.key)}
                                                            style={{ fontSize: 10, borderRadius: 8 }}>{ct.label}</Button>
                                                    </Col>
                                                ))}
                                            </Row>
                                            {columns.length > 0 && (
                                                <div style={{ marginTop: 8 }}>
                                                    <Text type="secondary" style={{ fontSize: 10 }}>X: <Tag style={{ fontSize: 10 }}>{xKey}</Tag> Y: <Tag style={{ fontSize: 10 }}>{yKey}</Tag></Text>
                                                </div>
                                            )}
                                        </motion.div>
                                    )}
                                    <Divider style={{ margin: '4px 0' }} />
                                    <div>
                                        <Text type="secondary" style={{ fontSize: 11 }}>Export</Text>
                                        <Row gutter={[6, 6]} style={{ marginTop: 6 }}>
                                            <Col span={8}>
                                                <Button size="small" block icon={<DownloadOutlined />} onClick={handleExportCsv}
                                                    disabled={!rows.length} style={{ fontSize: 10, borderRadius: 8 }}>CSV</Button>
                                            </Col>
                                            <Col span={8}>
                                                <Button size="small" block icon={<FileExcelOutlined />} onClick={handleExportExcel}
                                                    disabled={!rows.length} style={{ fontSize: 10, borderRadius: 8 }}>Excel</Button>
                                            </Col>
                                            <Col span={8}>
                                                <Button size="small" block icon={<FilePdfOutlined />} onClick={handleExportPdf}
                                                    disabled={!rows.length} style={{ fontSize: 10, borderRadius: 8 }}>PDF</Button>
                                            </Col>
                                        </Row>
                                    </div>
                                </Space>
                            </Card>
                        </motion.div>
                    </Col>
                </Row>

                {/* ═══════════ RESULTS PANEL ═══════════ */}
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
                    <Card size="small" style={glassCard}
                        title={
                            <Space>
                                {viewMode === 'table' ? <TableOutlined style={{ color: '#10b981' }} /> : <BarChartOutlined style={{ color: '#8b5cf6' }} />}
                                <Text strong>{viewMode === 'table' ? 'Results' : 'Chart'}</Text>
                                {rows.length > 0 && (
                                    <>
                                        <Badge count={`${rows.length} rows`} style={{ backgroundColor: '#10b981', fontSize: 10 }} />
                                        <Badge count={`${columns.length} cols`} style={{ backgroundColor: '#3b82f6', fontSize: 10 }} />
                                    </>
                                )}
                            </Space>
                        }
                        extra={
                            rows.length > 0 && (
                                <Space size={4}>
                                    <Tag icon={<ClockCircleOutlined />} style={{ fontSize: 10, borderRadius: 8 }}>{execTime}ms</Tag>
                                    <Button size="small" type="text" icon={<PlayCircleOutlined />} onClick={handleRunQuery} loading={running} />
                                </Space>
                            )
                        }>
                        {running ? (
                            <div style={{ textAlign: 'center', padding: 60 }}><Spin size="large" tip="Running query…" /></div>
                        ) : rows.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: 60 }}>
                                <CodeOutlined style={{ fontSize: 40, color: isDark ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.1)' }} />
                                <div style={{ marginTop: 12 }}><Text type="secondary">Select a data source and run a query to see results</Text></div>
                            </div>
                        ) : viewMode === 'table' ? (
                            <Table dataSource={rows} rowKey="_key" size="small" scroll={{ x: 'max-content' }}
                                pagination={{ pageSize: 15, size: 'small', showSizeChanger: true, showTotal: (t) => <Text type="secondary" style={{ fontSize: 11 }}>{t} total rows</Text> }}
                                columns={tableColumns} />
                        ) : (
                            renderChart()
                        )}
                    </Card>
                </motion.div>
            </motion.div>
        </CMSLayout>
    );
}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import CMSLayout from '@/components/layout/CMSLayout';
import { Card, Row, Col, Typography, Statistic, Space, Tag, Button, Table, Input, Select, Timeline, Skeleton, message, theme } from 'antd';
import {
    FileTextOutlined, BarChartOutlined, ClockCircleOutlined, PlusOutlined, DownloadOutlined,
    CalendarOutlined, ReloadOutlined, CheckCircleOutlined, PieChartOutlined, PlayCircleOutlined,
    EditOutlined, DeleteOutlined, SearchOutlined, ThunderboltOutlined, AppstoreOutlined,
} from '@ant-design/icons';
import { gql, DEFAULT_TENANT_ID } from '@/lib/graphql';
import { usePreferencesStore } from '@/store/usePreferencesStore';
import { AuroraText } from '@/components/magicui/aurora-text';
import DecryptedText from '@/components/react-bits/DecryptedText';
import { BentoGrid, BentoGridItem } from "@/components/magicui/bento-grid";
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

const { Text } = Typography;
const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };
const glassDark = { background: 'rgba(12,12,30,0.92)', backdropFilter: 'blur(16px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14 };

/* ═══ Demo fallback data — shown when backend returns empty arrays ═══ */
const DEMO_REPORTS = [
    { id: 'RPT-001', name: 'Monthly Revenue Summary', module: 'Financial',
      type: 'chart', createdAt: '2025-04-10T08:00:00Z', lastRun: '2025-05-28T08:30:00Z',
      status: 'active', schedule: 'Monthly' },
    { id: 'RPT-002', name: 'Employee Headcount Report', module: 'HR',
      type: 'table', createdAt: '2025-03-15T10:00:00Z', lastRun: '2025-05-27T14:00:00Z',
      status: 'active', schedule: 'Weekly' },
    { id: 'RPT-003', name: 'Inventory Valuation', module: 'Inventory',
      type: 'table', createdAt: '2025-02-20T06:00:00Z', lastRun: '2025-05-29T06:00:00Z',
      status: 'active', schedule: 'Daily' },
    { id: 'RPT-004', name: 'Sales Pipeline Analysis', module: 'CRM',
      type: 'chart', createdAt: '2025-04-01T12:00:00Z', lastRun: '2025-05-25T10:00:00Z',
      status: 'draft', schedule: null },
    { id: 'RPT-005', name: 'SLA Compliance Dashboard', module: 'ITSM',
      type: 'metric', createdAt: '2025-01-18T09:00:00Z', lastRun: '2025-05-28T12:00:00Z',
      status: 'active', schedule: 'Weekly' },
    { id: 'RPT-006', name: 'Audit Trail Export', module: 'Compliance',
      type: 'table', createdAt: '2025-03-05T11:00:00Z', lastRun: '2025-05-26T09:00:00Z',
      status: 'active', schedule: 'Monthly' },
    { id: 'RPT-007', name: 'Quarterly Revenue Forecast', module: 'Financial',
      type: 'chart', createdAt: '2025-05-01T08:00:00Z', lastRun: '2025-05-20T15:00:00Z',
      status: 'active', schedule: 'Quarterly' },
    { id: 'RPT-008', name: 'Customer Churn Analysis', module: 'CRM',
      type: 'metric', createdAt: '2025-04-22T14:00:00Z', lastRun: null,
      status: 'draft', schedule: null },
    { id: 'RPT-009', name: 'Warehouse Stock Levels', module: 'Inventory',
      type: 'table', createdAt: '2025-05-10T07:00:00Z', lastRun: '2025-05-29T07:00:00Z',
      status: 'active', schedule: 'Daily' },
    { id: 'RPT-010', name: 'HR Attrition Trends', module: 'HR',
      type: 'chart', createdAt: '2025-02-14T09:00:00Z', lastRun: null,
      status: 'archived', schedule: null },
];

const DEMO_ACTIVITY = [
    { report: 'Monthly Revenue Summary', time: '2 hours ago', status: 'completed', duration: '4.2s', format: 'PDF' },
    { report: 'Inventory Valuation', time: '5 hours ago', status: 'completed', duration: '8.1s', format: 'Excel' },
    { report: 'SLA Compliance Dashboard', time: '1 day ago', status: 'completed', duration: '2.8s', format: 'PDF' },
    { report: 'Audit Trail Export', time: '2 days ago', status: 'failed', duration: '—', format: 'CSV' },
    { report: 'Employee Headcount Report', time: '3 days ago', status: 'completed', duration: '3.5s', format: 'Excel' },
];

const MODULE_COLORS: Record<string, string> = {
    Financial: '#3b82f6', HR: '#10b981', CRM: '#f59e0b',
    Inventory: '#8b5cf6', ITSM: '#06b6d4', Compliance: '#ef4444',
};
const TYPE_LABELS: Record<string, string> = {
    chart: '📊 Chart', table: '📋 Table', metric: '🔢 Metric',
};

/* ═══ Reports Dashboard Component ═══ */
export default function ReportsDashboardPage() {
    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const glassCard = isDark ? glassDark : glass;
    const router = useRouter();
    const [messageApi, contextHolder] = message.useMessage();

    const [loading, setLoading] = useState(true);
    const [reports, setReports] = useState<any[]>([]);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState<string | null>(null);

    /* ── Fetch real data with demo fallback ── */
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [rptRes, tplRes, schRes] = await Promise.all([
                gql<{ allReports: any[] }>(
                    `query($tenantId: String!) { allReports(tenantId: $tenantId) }`,
                    { tenantId: DEFAULT_TENANT_ID },
                ).catch(() => ({ allReports: [] })),
                gql<{ reportTemplates: any[] }>(
                    `query($tenantId: String!) { reportTemplates(tenantId: $tenantId) }`,
                    { tenantId: DEFAULT_TENANT_ID },
                ).catch(() => ({ reportTemplates: [] })),
                gql<{ reportSchedules: any[] }>(
                    `query($tenantId: String!) { reportSchedules(tenantId: $tenantId) }`,
                    { tenantId: DEFAULT_TENANT_ID },
                ).catch(() => ({ reportSchedules: [] })),
            ]);
            const live = rptRes.allReports;
            setReports(Array.isArray(live) && live.length > 0 ? live : DEMO_REPORTS);
        } catch {
            setReports(DEMO_REPORTS);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    /* ── Computed KPI stats ── */
    const stats = useMemo(() => {
        const total = reports.length;
        const active = reports.filter(r => r.status === 'active').length;
        const drafts = reports.filter(r => r.status === 'draft').length;
        const scheduled = reports.filter(r => r.schedule).length;
        const totalExports = reports.filter(r => r.lastRun).length;
        return { total, active, drafts, scheduled, totalExports, avgGen: '3.8s' };
    }, [reports]);

    /* ── Filtered list for table ── */
    const filteredReports = useMemo(() => {
        let list = reports;
        if (statusFilter) list = list.filter(r => r.status === statusFilter);
        if (search) {
            const q = search.toLowerCase();
            list = list.filter(r => r.name?.toLowerCase().includes(q));
        }
        return list;
    }, [reports, statusFilter, search]);

    /* ── Module distribution for donut chart ── */
    const moduleData = useMemo(() => {
        const counts: Record<string, number> = {};
        reports.forEach(r => {
            const m = r.module || 'Other';
            counts[m] = (counts[m] || 0) + 1;
        });
        return Object.entries(counts).map(([name, value]) => ({
            name, value, color: MODULE_COLORS[name] || '#6b7280',
        }));
    }, [reports]);

    /* ── KPI card config ── */
    const kpiCards = [
        { t: 'Total Reports', v: stats.total, c: '#3b82f6', i: <FileTextOutlined /> },
        { t: 'Active', v: stats.active, c: '#10b981', i: <CheckCircleOutlined /> },
        { t: 'Drafts', v: stats.drafts, c: '#f59e0b', i: <EditOutlined /> },
        { t: 'Scheduled', v: stats.scheduled, c: '#8b5cf6', i: <CalendarOutlined /> },
        { t: 'Total Exports', v: stats.totalExports, c: '#06b6d4', i: <DownloadOutlined /> },
        { t: 'Avg Generation', v: stats.avgGen, c: '#ec4899', i: <ThunderboltOutlined /> },
    ];

    /* ── Table columns ── */
    const columns = [
        { title: 'Report Name', dataIndex: 'name', key: 'name',
          render: (v: string) => <Text strong style={{ fontSize: 12 }}>{v}</Text> },
        { title: 'Module', dataIndex: 'module', key: 'module', width: 105,
          render: (v: string) => (
              <Tag color={MODULE_COLORS[v] || 'default'} style={{ fontSize: 10, borderRadius: 8 }}>{v}</Tag>
          ) },
        { title: 'Type', dataIndex: 'type', key: 'type', width: 90,
          render: (v: string) => (
              <Tag style={{ fontSize: 10, borderRadius: 8 }}>{TYPE_LABELS[v] || v}</Tag>
          ) },
        { title: 'Created', dataIndex: 'createdAt', key: 'createdAt', width: 100,
          render: (v: string) => (
              <Text type="secondary" style={{ fontSize: 11 }}>{v ? new Date(v).toLocaleDateString() : '—'}</Text>
          ) },
        { title: 'Last Run', dataIndex: 'lastRun', key: 'lastRun', width: 100,
          render: (v: string) => (
              <Text type="secondary" style={{ fontSize: 11 }}>{v ? new Date(v).toLocaleDateString() : '—'}</Text>
          ) },
        { title: 'Status', dataIndex: 'status', key: 'status', width: 90,
          render: (v: string) => (
              <Tag color={v === 'active' ? 'green' : v === 'draft' ? 'orange' : 'default'}
                  style={{ fontSize: 10, borderRadius: 10 }}>{v}</Tag>
          ) },
        { title: 'Schedule', dataIndex: 'schedule', key: 'schedule', width: 95,
          render: (v: string) => (
              <Text type="secondary" style={{ fontSize: 11 }}>{v || '—'}</Text>
          ) },
        { title: 'Actions', key: 'actions', width: 150,
          render: (_: any, rec: any) => (
              <Space size={2}>
                  <Button type="text" size="small"
                      icon={<PlayCircleOutlined style={{ fontSize: 12, color: '#10b981' }} />}
                      onClick={e => { e.stopPropagation(); messageApi.info(`Running ${rec.name}…`); }} />
                  <Button type="text" size="small"
                      icon={<DownloadOutlined style={{ fontSize: 12, color: '#3b82f6' }} />}
                      onClick={e => { e.stopPropagation(); messageApi.info(`Downloading ${rec.name}…`); }} />
                  <Button type="text" size="small"
                      icon={<EditOutlined style={{ fontSize: 12, color: '#f59e0b' }} />}
                      onClick={e => { e.stopPropagation(); router.push(`/admin/reports/builder?id=${rec.id}`); }} />
                  <Button type="text" size="small"
                      icon={<DeleteOutlined style={{ fontSize: 12, color: '#ef4444' }} />}
                      onClick={e => { e.stopPropagation(); messageApi.warning(`Delete ${rec.name}?`); }} />
              </Space>
          ) },
    ];

    /* ═══ Render ═══ */
    return (
        <CMSLayout
