                    { title: 'Total Users', value: sampleUsers.length, icon: <UserOutlined />, color: '#3b82f6' },
                    { title: 'Active', value: sampleUsers.filter(u => u.status === 'active').length, icon: <UserOutlined />, color: '#10b981' },
