// S3/MinIO configuration
const S3_ENDPOINT = process.env.NEXT_PUBLIC_S3_ENDPOINT || "http://127.0.0.1:9000";
const S3_BUCKET = process.env.NEXT_PUBLIC_S3_BUCKET || "cms-media";
const S3_ACCESS_KEY = process.env.S3_ACCESS_KEY || "minioadmin";
const S3_SECRET_KEY = process.env.S3_SECRET_KEY || "minioadmin";
const S3_REGION = process.env.S3_REGION || "us-east-1";

// Create S3 client for MinIO
const s3Client = new S3Client({
    endpoint: S3_ENDPOINT,
    region: S3_REGION,
    credentials: {
        accessKeyId: S3_ACCESS_KEY,
        secretAccessKey: S3_SECRET_KEY,
    },
    forcePathStyle: true, // Required for MinIO
});

// Generate unique file key
function generateFileKey(filename: string, folder = "uploads"): string {
    const timestamp = Date.now();
    const randomId = Math.random().toString(36).substring(2, 8);
    const extension = filename.split(".").pop() || "";
    const baseName = filename.replace(/\.[^/.]+$/, "").replace(/[^a-zA-Z0-9]/g, "-");
    return `${folder}/${timestamp}-${randomId}-${baseName}.${extension}`;
}

// POST - Upload file to S3
export async function POST(request: NextRequest) {
    console.log("S3 Upload API called");
    console.log("S3 Config:", { endpoint: S3_ENDPOINT, bucket: S3_BUCKET, region: S3_REGION });

    try {
        const formData = await request.formData();
        const file = formData.get("file") as File | null;
        const folder = (formData.get("folder") as string) || "uploads";

        if (!file) {
            return NextResponse.json(
                { success: false, error: "No file provided" },
                { status: 400 }
            );
        }

        console.log("Uploading file:", file.name, "size:", file.size, "type:", file.type);

        // Read file as buffer
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // Generate file key
        const key = generateFileKey(file.name, folder);
        console.log("Generated key:", key);

        // Upload to S3
        const command = new PutObjectCommand({
            Bucket: S3_BUCKET,
            Key: key,
            Body: buffer,
            ContentType: file.type,
        });

        console.log("Sending to S3...");
        await s3Client.send(command);
        console.log("S3 upload successful!");

        // Build URL - use public endpoint for browser access
        const S3_PUBLIC_ENDPOINT = process.env.NEXT_PUBLIC_S3_PUBLIC_ENDPOINT || S3_ENDPOINT.replace("minio:", "localhost:");
        const url = `${S3_PUBLIC_ENDPOINT}/${S3_BUCKET}/${key}`;

        // Save metadata to database via GraphQL
        // Use GRAPHQL_API_URL (server-side) which points to Docker hostname
        const GRAPHQL_URL = process.env.GRAPHQL_API_URL || process.env.NEXT_PUBLIC_GRAPHQL_URL || 'http://middleware:4001/graphql';
        console.log("Saving metadata to database via GraphQL:", GRAPHQL_URL);

        const mutation = `
            mutation CreateMedia($input: UploadMediaInput!) {
                createMedia(uploadMediaInput: $input) {
                    id
                    filename
                    originalName
                    url
                    s3Key
                    mimeType
                    sizeBytes
                    altText
                    createdAt
                }
            }
        `;

        try {
            const graphqlResponse = await fetch(GRAPHQL_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    query: mutation,
                    variables: {
                        input: {
                            filename: file.name,
                            originalName: file.name,
                            url,
                            s3Key: key,
                            mimeType: file.type,
                            sizeBytes: file.size,
                            altText: file.name,
                        },
                    },
                }),
            });

            const graphqlResult = await graphqlResponse.json();
            console.log("GraphQL save result:", graphqlResult);

            if (graphqlResult.errors) {
                console.error("GraphQL errors:", graphqlResult.errors);
                // Still return success for S3, but log the DB error
            }

            const savedMedia = graphqlResult.data?.createMedia;
            if (savedMedia) {
                return NextResponse.json({
                    success: true,
                    media: {
                        id: savedMedia.id,
                        filename: savedMedia.filename,
                        original_name: savedMedia.originalName,
                        url: savedMedia.url,
                        s3_key: savedMedia.s3Key,
                        mime_type: savedMedia.mimeType,
                        size_bytes: savedMedia.sizeBytes,
                        alt_text: savedMedia.altText,
                        created_at: savedMedia.createdAt,
                    },
                });
            }
        } catch (graphqlError) {
            console.error("GraphQL save failed:", graphqlError);
            // Continue with S3-only response if GraphQL fails
        }

        // Fallback: return S3 metadata if GraphQL save failed
        return NextResponse.json({
            success: true,
            media: {
                id: key,
                filename: file.name,
                original_name: file.name,
                url,
                s3_key: key,
                mime_type: file.type,
                size_bytes: file.size,
                created_at: new Date().toISOString(),
            },
        });
    } catch (error: any) {
        console.error("S3 upload error:", error);
        console.error("Error name:", error.name);
        console.error("Error message:", error.message);
        console.error("Error stack:", error.stack);
        return NextResponse.json(
            { success: false, error: error.message || "Upload failed", details: error.name },
            { status: 500 }
        );
    }
}

// DELETE - Delete file from S3
export async function DELETE(request: NextRequest) {
    try {
        const { searchParams } = new URL(request.url);
        const key = searchParams.get("key");

        if (!key) {
            return NextResponse.json(
                { success: false, error: "No key provided" },
                { status: 400 }
            );
        }

        const command = new DeleteObjectCommand({
            Bucket: S3_BUCKET,
            Key: key,
        });

        await s3Client.send(command);

        return NextResponse.json({ success: true });
    } catch (error: any) {
        console.error("S3 delete error:", error);
        return NextResponse.json(
            { success: false, error: error.message || "Delete failed" },
            { status: 500 }
        );
    }
}

"use client";

import React, { useState } from "react";
import {
    Card,
    Form,
    Input,
    Button,
    Select,
    Switch,
    Space,
    Divider,
    Empty,
    message,
    Modal,
} from "antd";
import {
    PlusOutlined,
    DeleteOutlined,
    DragOutlined,
    SettingOutlined,
} from "@ant-design/icons";

// Field types
type FieldType = "text" | "email" | "textarea" | "select" | "checkbox" | "number" | "phone";

interface FormField {
    id: string;
    type: FieldType;
    label: string;
    placeholder?: string;
    required?: boolean;
    options?: string[]; // For select fields
}

interface FormBuilderProps {
    fields?: FormField[];
    onChange?: (fields: FormField[]) => void;
    submitLabel?: string;
    onSubmitLabelChange?: (label: string) => void;
    editable?: boolean;
}

// Field type options
const fieldTypes: { value: FieldType; label: string }[] = [
    { value: "text", label: "Text" },
    { value: "email", label: "Email" },
    { value: "textarea", label: "Text Area" },
    { value: "select", label: "Dropdown" },
    { value: "checkbox", label: "Checkbox" },
    { value: "number", label: "Number" },
    { value: "phone", label: "Phone" },
];

/**
 * Form Builder Block Component
 * Visual form builder for creating custom forms
 */
export default function FormBuilder({
    fields = [],
    onChange,
    submitLabel = "Submit",
    onSubmitLabelChange,
    editable = false,
}: FormBuilderProps) {
    const [editingField, setEditingField] = useState<FormField | null>(null);
    const [editModalOpen, setEditModalOpen] = useState(false);
    const [form] = Form.useForm();

    const addField = (type: FieldType) => {
        const newField: FormField = {
            id: `field-${Date.now()}`,
            type,
            label: `New ${type.charAt(0).toUpperCase() + type.slice(1)} Field`,
            placeholder: "",
            required: false,
        };
        if (onChange) {
            onChange([...fields, newField]);
        }
    };

    const updateField = (id: string, updates: Partial<FormField>) => {
        if (onChange) {
            onChange(
                fields.map((f) => (f.id === id ? { ...f, ...updates } : f))
            );
        }
    };

    const deleteField = (id: string) => {
        if (onChange) {
            onChange(fields.filter((f) => f.id !== id));
        }
    };

    const openEditModal = (field: FormField) => {
        setEditingField(field);
        form.setFieldsValue(field);
        setEditModalOpen(true);
    };

    const saveFieldEdit = () => {
        form.validateFields().then((values) => {
            if (editingField) {
                updateField(editingField.id, values);
                setEditModalOpen(false);
                setEditingField(null);
            }
        });
    };

    const handleFormSubmit = (values: any) => {
        console.log("Form submitted:", values);
        message.success("Form submitted successfully!");
    };

    // Render form preview/actual form
    const renderFormField = (field: FormField) => {
        const commonProps = {
            placeholder: field.placeholder,
        };

        switch (field.type) {
            case "textarea":
                return <Input.TextArea {...commonProps} rows={4} />;
            case "select":
                return (
                    <Select {...commonProps}>
                        {(field.options || []).map((opt) => (
                            <Select.Option key={opt} value={opt}>
                                {opt}
                            </Select.Option>
                        ))}
                    </Select>
                );
            case "checkbox":
                return <Switch />;
            case "number":
                return <Input type="number" {...commonProps} />;
            default:
                return <Input type={field.type} {...commonProps} />;
        }
    };

    if (fields.length === 0 && !editable) {
        return (
            <Card>
                <Empty description="No form fields configured" />
            </Card>
        );
    }

    return (
        <div style={{ padding: 16 }}>
            {/* Form Preview */}
            <Card title="Form Preview">
                <Form layout="vertical" onFinish={handleFormSubmit}>
                    {fields.map((field) => (
                        <div
                            key={field.id}
                            style={{
                                position: "relative",
                                padding: editable ? "8px 0" : 0,
                                borderRadius: 4,
                            }}
                        >
                            <Form.Item
                                name={field.id}
                                label={field.label}
                                rules={
                                    field.required
                                        ? [{ required: true, message: `${field.label} is required` }]
                                        : []
                                }
                                valuePropName={field.type === "checkbox" ? "checked" : "value"}
                            >
                                {renderFormField(field)}
                            </Form.Item>

                            {editable && (
                                <Space
                                    style={{
                                        position: "absolute",
                                        top: 8,
                                        right: 0,
                                    }}
                                >
                                    <Button
                                        size="small"
                                        icon={<SettingOutlined />}
                                        onClick={() => openEditModal(field)}
                                    />
                                    <Button
                                        size="small"
                                        danger
                                        icon={<DeleteOutlined />}
                                        onClick={() => deleteField(field.id)}
                                    />
                                </Space>
                            )}
                        </div>
                    ))}

                    <Form.Item>
                        <Button type="primary" htmlType="submit">
                            {submitLabel}
                        </Button>
                    </Form.Item>
                </Form>
            </Card>

            {/* Field Palette (Editor Mode) */}
            {editable && (
                <Card title="Add Field" style={{ marginTop: 16 }}>
                    <Space wrap>
                        {fieldTypes.map((ft) => (
                            <Button
                                key={ft.value}
                                icon={<PlusOutlined />}
                                onClick={() => addField(ft.value)}
                            >
                                {ft.label}
                            </Button>
                        ))}
                    </Space>

                    <Divider />

                    <Form.Item label="Submit Button Label">
                        <Input
                            value={submitLabel}
                            onChange={(e) => onSubmitLabelChange?.(e.target.value)}
                            placeholder="Submit"
                        />
                    </Form.Item>
                </Card>
            )}

            {/* Field Edit Modal */}
            <Modal
                title="Edit Field"
                open={editModalOpen}
                onOk={saveFieldEdit}
                onCancel={() => setEditModalOpen(false)}
            >
                <Form form={form} layout="vertical">
                    <Form.Item name="label" label="Label" rules={[{ required: true }]}>
                        <Input />
                    </Form.Item>
                    <Form.Item name="placeholder" label="Placeholder">
                        <Input />
                    </Form.Item>
                    <Form.Item name="required" label="Required" valuePropName="checked">
                        <Switch />
                    </Form.Item>
                    {editingField?.type === "select" && (
                        <Form.Item name="options" label="Options (one per line)">
                            <Input.TextArea
                                rows={4}
                                placeholder="Option 1&#10;Option 2&#10;Option 3"
                                onChange={(e) => {
                                    const options = e.target.value.split("\n").filter(Boolean);
                                    form.setFieldValue("options", options);
                                }}
                                value={(form.getFieldValue("options") || []).join("\n")}
                            />
                        </Form.Item>
                    )}
                </Form>
            </Modal>
        </div>
    );
}

"use client";

import React, { useState } from "react";
import { Card, Image, Row, Col, Modal, Button, Upload, Empty, Tooltip } from "antd";
import {
    UploadOutlined,
    DeleteOutlined,
    EyeOutlined,
    PlusOutlined,
} from "@ant-design/icons";

interface GalleryImage {
    id: string;
    src: string;
    alt?: string;
    caption?: string;
}

interface ImageGalleryProps {
    images?: GalleryImage[];
    onChange?: (images: GalleryImage[]) => void;
    columns?: 2 | 3 | 4 | 6;
    gap?: number;
    editable?: boolean;
}

/**
 * Image Gallery Block Component
 * Displays images in a responsive grid with lightbox preview
 */
export default function ImageGallery({
    images = [],
    onChange,
    columns = 4,
    gap = 16,
    editable = false,
}: ImageGalleryProps) {
    const [previewOpen, setPreviewOpen] = useState(false);
    const [previewIndex, setPreviewIndex] = useState(0);

    const handlePreview = (index: number) => {
        setPreviewIndex(index);
        setPreviewOpen(true);
    };

    const handleDelete = (id: string) => {
        if (onChange) {
            onChange(images.filter((img) => img.id !== id));
        }
    };

    const handleUpload = (file: File) => {
        const newImage: GalleryImage = {
            id: `img-${Date.now()}`,
            src: URL.createObjectURL(file),
            alt: file.name,
        };
        if (onChange) {
            onChange([...images, newImage]);
        }
        return false; // Prevent default upload
    };

    const span = 24 / columns;

    if (images.length === 0 && !editable) {
        return (
            <Card>
                <Empty description="No images in gallery" />
            </Card>
        );
    }

    return (
        <div style={{ padding: 16 }}>
            <Row gutter={[gap, gap]}>
                {images.map((image, index) => (
                    <Col key={image.id} span={span}>
                        <Card
                            bodyStyle={{ padding: 0 }}
                            cover={
                                <div
                                    style={{
                                        position: "relative",
                                        aspectRatio: "1",
                                        overflow: "hidden",
                                    }}
                                >
                                    <img
                                        src={image.src}
                                        alt={image.alt || ""}
                                        style={{
                                            width: "100%",
                                            height: "100%",
                                            objectFit: "cover",
                                        }}
                                    />
                                    <div
                                        style={{
                                            position: "absolute",
                                            inset: 0,
                                            background: "rgba(0,0,0,0.5)",
                                            display: "flex",
                                            gap: 8,
                                            alignItems: "center",
                                            justifyContent: "center",
                                            opacity: 0,
                                            transition: "opacity 0.2s",
                                        }}
                                        className="gallery-overlay"
                                        onMouseEnter={(e) => {
                                            (e.currentTarget as HTMLElement).style.opacity = "1";
                                        }}
                                        onMouseLeave={(e) => {
                                            (e.currentTarget as HTMLElement).style.opacity = "0";
                                        }}
                                    >
                                        <Tooltip title="Preview">
                                            <Button
                                                type="primary"
                                                shape="circle"
                                                icon={<EyeOutlined />}
                                                onClick={() => handlePreview(index)}
                                            />
                                        </Tooltip>
                                        {editable && (
                                            <Tooltip title="Delete">
                                                <Button
                                                    danger
                                                    shape="circle"
                                                    icon={<DeleteOutlined />}
                                                    onClick={() => handleDelete(image.id)}
                                                />
                                            </Tooltip>
                                        )}
                                    </div>
                                </div>
                            }
                        >
                            {image.caption && (
                                <Card.Meta
                                    description={image.caption}
                                    style={{ padding: 12 }}
                                />
                            )}
                        </Card>
                    </Col>
                ))}

                {editable && (
                    <Col span={span}>
                        <Upload
                            accept="image/*"
                            showUploadList={false}
                            beforeUpload={handleUpload}
                        >
                            <Card
                                style={{
                                    aspectRatio: "1",
                                    display: "flex",
                                    alignItems: "center",
                                    justifyContent: "center",
                                    cursor: "pointer",
                                    border: "2px dashed #d9d9d9",
                                }}
                                bodyStyle={{
                                    display: "flex",
                                    flexDirection: "column",
                                    alignItems: "center",
                                    justifyContent: "center",
                                    height: "100%",
                                }}
                            >
                                <PlusOutlined style={{ fontSize: 32, color: "#999" }} />
                                <div style={{ marginTop: 8, color: "#999" }}>Add Image</div>
                            </Card>
                        </Upload>
                    </Col>
                )}
            </Row>

            {/* Lightbox Preview */}
            <Image.PreviewGroup
                preview={{
                    visible: previewOpen,
                    current: previewIndex,
                    onVisibleChange: (visible) => setPreviewOpen(visible),
                }}
            >
                {images.map((image) => (
                    <Image key={image.id} src={image.src} style={{ display: "none" }} />
                ))}
            </Image.PreviewGroup>
        </div>
    );
}

"use client";

import React, { useState } from "react";
import { Card, Button, Input, Space, Tooltip, Dropdown } from "antd";
import {
    BoldOutlined,
    ItalicOutlined,
    UnderlineOutlined,
    OrderedListOutlined,
    UnorderedListOutlined,
    LinkOutlined,
    PictureOutlined,
    AlignLeftOutlined,
    AlignCenterOutlined,
    AlignRightOutlined,
    FontSizeOutlined,
} from "@ant-design/icons";

interface RichTextEditorProps {
    value?: string;
    onChange?: (value: string) => void;
    placeholder?: string;
    minHeight?: number;
}

/**
 * Basic Rich Text Editor Component
 * Uses contentEditable with toolbar buttons
 * For full WYSIWYG, consider integrating Tiptap or Slate
 */
export default function RichTextEditor({
    value = "",
    onChange,
    placeholder = "Enter your content...",
    minHeight = 200,
}: RichTextEditorProps) {
    const [content, setContent] = useState(value);
    const editorRef = React.useRef<HTMLDivElement>(null);

    const execCommand = (command: string, value?: string) => {
        document.execCommand(command, false, value);
        editorRef.current?.focus();
        handleChange();
    };

    const handleChange = () => {
        const html = editorRef.current?.innerHTML || "";
        setContent(html);
        onChange?.(html);
    };

    const headingSizes = [
        { key: "1", label: "Heading 1" },
        { key: "2", label: "Heading 2" },
        { key: "3", label: "Heading 3" },
        { key: "4", label: "Heading 4" },
        { key: "p", label: "Paragraph" },
    ];

    const insertLink = () => {
        const url = prompt("Enter URL:", "https://");
        if (url) {
            execCommand("createLink", url);
        }
    };

    const insertImage = () => {
        const url = prompt("Enter image URL:", "https://");
        if (url) {
            execCommand("insertImage", url);
        }
    };

    return (
        <Card size="small" styles={{ body: { padding: 0 } }}>
            {/* Toolbar */}
            <div
                style={{
                    padding: "8px 12px",
                    borderBottom: "1px solid #f0f0f0",
                    background: "#fafafa",
                    display: "flex",
                    flexWrap: "wrap",
                    gap: 4,
                }}
            >
                <Space size={4}>
                    <Dropdown
                        menu={{
                            items: headingSizes.map((h) => ({
                                key: h.key,
                                label: h.label,
                                onClick: () => {
                                    if (h.key === "p") {
                                        execCommand("formatBlock", "p");
                                    } else {
                                        execCommand("formatBlock", `h${h.key}`);
                                    }
                                },
                            })),
                        }}
                    >
                        <Button size="small" icon={<FontSizeOutlined />}>
                            Format
                        </Button>
                    </Dropdown>

                    <div style={{ width: 1, height: 20, background: "#d9d9d9" }} />

                    <Tooltip title="Bold">
                        <Button
                            size="small"
                            icon={<BoldOutlined />}
                            onClick={() => execCommand("bold")}
                        />
                    </Tooltip>
                    <Tooltip title="Italic">
                        <Button
                            size="small"
                            icon={<ItalicOutlined />}
                            onClick={() => execCommand("italic")}
                        />
                    </Tooltip>
                    <Tooltip title="Underline">
                        <Button
                            size="small"
                            icon={<UnderlineOutlined />}
                            onClick={() => execCommand("underline")}
                        />
                    </Tooltip>

                    <div style={{ width: 1, height: 20, background: "#d9d9d9" }} />

                    <Tooltip title="Bullet List">
                        <Button
                            size="small"
                            icon={<UnorderedListOutlined />}
                            onClick={() => execCommand("insertUnorderedList")}
                        />
                    </Tooltip>
                    <Tooltip title="Numbered List">
                        <Button
                            size="small"
                            icon={<OrderedListOutlined />}
                            onClick={() => execCommand("insertOrderedList")}
                        />
                    </Tooltip>

                    <div style={{ width: 1, height: 20, background: "#d9d9d9" }} />

                    <Tooltip title="Align Left">
                        <Button
                            size="small"
                            icon={<AlignLeftOutlined />}
                            onClick={() => execCommand("justifyLeft")}
                        />
                    </Tooltip>
                    <Tooltip title="Align Center">
                        <Button
                            size="small"
                            icon={<AlignCenterOutlined />}
                            onClick={() => execCommand("justifyCenter")}
                        />
                    </Tooltip>
                    <Tooltip title="Align Right">
                        <Button
                            size="small"
                            icon={<AlignRightOutlined />}
                            onClick={() => execCommand("justifyRight")}
                        />
                    </Tooltip>

                    <div style={{ width: 1, height: 20, background: "#d9d9d9" }} />

                    <Tooltip title="Insert Link">
                        <Button size="small" icon={<LinkOutlined />} onClick={insertLink} />
                    </Tooltip>
                    <Tooltip title="Insert Image">
                        <Button
                            size="small"
                            icon={<PictureOutlined />}
                            onClick={insertImage}
                        />
                    </Tooltip>
                </Space>
            </div>

            {/* Editor */}
            <div
                ref={editorRef}
                contentEditable
                style={{
                    minHeight,
                    padding: 16,
                    outline: "none",
                    lineHeight: 1.6,
                }}
                dangerouslySetInnerHTML={{ __html: content }}
                onInput={handleChange}
                onBlur={handleChange}
                data-placeholder={placeholder}
            />

            <style jsx global>{`
                [contenteditable]:empty:before {
                    content: attr(data-placeholder);
                    color: #bfbfbf;
                }
            `}</style>
        </Card>
    );
}

"use client";

import React, { useState, useRef, useEffect, useCallback } from "react";
import { motion, useDragControls, PanInfo } from "framer-motion";
import { Button, Space, Tooltip, theme } from "antd";
import {
    MenuFoldOutlined,
    MenuUnfoldOutlined,
    VerticalLeftOutlined,
    VerticalRightOutlined,
    DragOutlined,
} from "@ant-design/icons";

export type DockPosition = "left" | "right" | "float";

interface FloatingPanelProps {
    id: string;
    title: string;
    icon: React.ReactNode;
    children: React.ReactNode;
    dockPosition: DockPosition;
    onDockChange: (pos: DockPosition) => void;
    minimized: boolean;
    onMinimizedChange: (v: boolean) => void;
    defaultWidth?: number;
    minWidth?: number;
    maxWidth?: number;
    minHeight?: number;
    maxHeight?: number;
    showHeader?: boolean;
    dragConstraintsRef?: any;
}

export function FloatingPanel({
    id,
    title,
    icon,
    children,
    dockPosition,
    onDockChange,
    minimized,
    onMinimizedChange,
    defaultWidth = 280,
    minWidth = 240,
    maxWidth = 480,
    minHeight = 200,
    maxHeight = 600,
    showHeader = true,
    dragConstraintsRef,
}: FloatingPanelProps) {
    const { token } = theme.useToken();
    const [height, setHeight] = useState(400);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const panelRef = useRef<HTMLDivElement>(null);
    const dragControls = useDragControls();

    // Detect dark mode
    const isDarkMode = token.colorBgContainer === '#141414' || token.colorBgBase === '#000';

    const effectiveDockPosition = minimized ? "float" : dockPosition;

    // Handle drag end to detect dock zones
    const handleDragEnd = useCallback((event: MouseEvent | TouchEvent | PointerEvent, info: PanInfo) => {
        const point = info.point;
        const viewportWidth = window.innerWidth;
        const dockThreshold = 80; // pixels from edge to trigger dock

        if (point.x < dockThreshold) {
            onDockChange("left");
        } else if (point.x > viewportWidth - dockThreshold) {
            onDockChange("right");
        }
        // Update position for next time
        setPosition({ x: info.offset.x, y: info.offset.y });
    }, [onDockChange]);

    // Glassmorphism styles
    const glassStyle: React.CSSProperties = {
        background: isDarkMode
            ? "rgba(30, 30, 30, 0.85)"
            : "rgba(255, 255, 255, 0.75)",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
    };

    // Get position styles based on dock mode
    const getPositionStyles = (): React.CSSProperties => {
        if (effectiveDockPosition === "left") {
            return {
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: minimized ? 48 : defaultWidth,
                zIndex: 1000,
            };
        }
        if (effectiveDockPosition === "right") {
            return {
                position: "absolute",
                right: 0,
                top: 0,
                bottom: 0,
                width: minimized ? 48 : defaultWidth,
                zIndex: 1000,
            };
        }
        // Float mode
        return {
            position: "absolute",
            zIndex: 1001,
            width: minimized ? 48 : defaultWidth,
            height: minimized ? 48 : height,
            maxHeight: maxHeight,
            minHeight: minHeight,
        };
    };

    // Toggle minimize - ensure it works both ways
    const handleMinimizeToggle = () => {
        onMinimizedChange(!minimized);
    };

    const panelContent = (
        <div
            ref={panelRef}
            style={{
                ...getPositionStyles(),
                ...glassStyle,
                borderRadius: effectiveDockPosition === "float" ? 12 : 8,
                boxShadow: effectiveDockPosition === "float"
                    ? "0 8px 32px rgba(0,0,0,0.15)"
                    : "0 1px 2px 0 rgba(0, 0, 0, 0.04)",
                border: `1px solid ${isDarkMode ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.08)"}`,
                display: "flex",
                flexDirection: "column",
                overflow: "hidden",
                transition: "width 0.2s ease, height 0.2s ease",
            }}
        >
            {/* Header - Always shows with glassmorphism */}
            {showHeader && (
                <div
                    style={{
                        padding: minimized ? "0 8px" : "0 12px",
                        background: 'rgba(255, 255, 255, 0.1)',
                        borderBottom: '1px solid rgba(139, 92, 246, 0.2)',
                        height: 40,
                        minHeight: 40,
                        color: isDarkMode ? '#e5e7eb' : '#374151',
                        display: "flex",
                        alignItems: "center",
                        justifyContent: minimized ? "center" : "space-between",
                        gap: 8,
                        cursor: effectiveDockPosition === "float" ? "move" : "default",
                        userSelect: "none",
                        flexShrink: 0,
                    }}
                    onPointerDown={(e) => effectiveDockPosition === "float" && dragControls.start(e)}
                >
                    {minimized ? (
                        <Tooltip title={`${title} (Click to expand)`} placement={effectiveDockPosition === "left" ? "right" : "left"}>
                            <Button
                                type="text"
                                size="small"
                                icon={icon}
                                onClick={handleMinimizeToggle}
                                className="text-gray-400 hover:text-violet-500 w-7 h-7 flex items-center justify-center p-0"
                            />
                        </Tooltip>
                    ) : (
                        <>
                            <Space size={8}>
                                <span style={{ fontSize: 14 }} className="text-violet-500">{icon}</span>
                                <span style={{
                                    background: 'linear-gradient(to right, var(--theme-color, #8b5cf6), #6366f1)',
                                    WebkitBackgroundClip: 'text',
                                    WebkitTextFillColor: 'transparent',
                                    fontWeight: 600,
                                    fontSize: '14px'
                                }}>{title}</span>
                            </Space>
                            <Space size={2}>
                                {/* Dock Left */}
                                <Tooltip title="Dock Left">
                                    <Button
                                        type="text"
                                        size="small"
                                        icon={<VerticalRightOutlined />}
                                        onClick={() => onDockChange("left")}
                                        className={dockPosition === "left" ? "text-violet-500 bg-violet-50 dark:bg-violet-900/20 w-6 h-6 flex items-center justify-center p-0" : "text-gray-400 hover:text-violet-500 w-6 h-6 flex items-center justify-center p-0"}
                                    />
                                </Tooltip>
                                {/* Float */}
                                <Tooltip title="Float">
                                    <Button
                                        type="text"
                                        size="small"
                                        icon={<DragOutlined />}
                                        onClick={() => onDockChange("float")}
                                        className={dockPosition === "float" ? "text-violet-500 bg-violet-50 dark:bg-violet-900/20 w-6 h-6 flex items-center justify-center p-0" : "text-gray-400 hover:text-violet-500 w-6 h-6 flex items-center justify-center p-0"}
                                    />
                                </Tooltip>
                                {/* Dock Right */}
                                <Tooltip title="Dock Right">
                                    <Button
                                        type="text"
                                        size="small"
                                        icon={<VerticalLeftOutlined />}
                                        onClick={() => onDockChange("right")}
                                        className={dockPosition === "right" ? "text-violet-500 bg-violet-50 dark:bg-violet-900/20 w-6 h-6 flex items-center justify-center p-0" : "text-gray-400 hover:text-violet-500 w-6 h-6 flex items-center justify-center p-0"}
                                    />
                                </Tooltip>
                                {/* Minimize/Expand */}
                                <Tooltip title={minimized ? "Expand" : "Minimize"}>
                                    <Button
                                        type="text"
                                        size="small"
                                        icon={minimized ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
                                        onClick={handleMinimizeToggle}
                                        className="text-gray-400 hover:text-violet-500 w-6 h-6 flex items-center justify-center p-0"
                                    />
                                </Tooltip>
                            </Space>
                        </>
                    )}
                </div>
            )}

            {/* Body - with glassmorphism background */}
            {!minimized && (
                <div
                    style={{
                        flex: 1,
                        overflowY: "auto",
                        overflowX: "hidden",
                        background: isDarkMode ? "rgba(0,0,0,0.2)" : "rgba(255,255,255,0.5)",
                    }}
                >
                    {children}
                </div>
            )}
        </div>
    );

    // Float mode with drag constraints
    if (effectiveDockPosition === "float") {
        return (
            <motion.div
                drag
                dragControls={dragControls}
                dragMomentum={false}
                dragConstraints={dragConstraintsRef || {
                    left: 0,
                    right: typeof window !== 'undefined' ? window.innerWidth - defaultWidth - 300 : 800,
                    top: 0,
                    bottom: typeof window !== 'undefined' ? window.innerHeight - height - 120 : 600,
                }}
                onDragEnd={handleDragEnd}
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                style={{
                    position: "absolute",
                    top: 20,
                    left: id === "library" ? 20 : 'calc(100% - 300px)',
                    right: undefined,
                }}
            >
                {panelContent}
            </motion.div>
        );
    }

    return panelContent;
}

export default FloatingPanel;

