    { name: 'BIM Models', path: '/admin/pm/construction-3d', icon: '🏗️', group: 'Facility', keywords: 'bim 3d ifc construction' },
];

const ACTIONS: ActionItem[] = [
    { name: 'Create New Project', action: '/admin/pm/projects', icon: '➕', group: 'Quick Actions', keywords: 'new project create' },
    { name: 'Create Ticket', action: '/admin/itsm/tickets', icon: '🎫', group: 'Quick Actions', keywords: 'new ticket incident' },
    { name: 'View My Tasks', action: '/admin/pm/my-work', icon: '✅', group: 'Quick Actions', keywords: 'my work tasks' },
    { name: 'Toggle Dark Mode', action: 'toggle-theme', icon: '🌙', group: 'Quick Actions', keywords: 'dark light theme' },
    { name: 'Open AI Studio', action: 'open-ai', icon: '🤖', group: 'Quick Actions', keywords: 'ai assistant' },
];

const STORAGE_KEY = 'nusantarasoft-recent-pages';

function getRecentPages(): PageItem[] {
    if (typeof window === 'undefined') return [];
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? JSON.parse(raw) : [];
    } catch { return []; }
}

function addRecentPage(page: PageItem) {
    const recent = getRecentPages().filter(p => p.path !== page.path);
    recent.unshift(page);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(recent.slice(0, 5)));
}

/** Group pages by their group field, preserving insertion order */
function groupPages(pages: PageItem[]): Record<string, PageItem[]> {
    const groups: Record<string, PageItem[]> = {};
    for (const page of pages) {
        if (!groups[page.group]) groups[page.group] = [];
        groups[page.group].push(page);
    }
    return groups;
}

// ─── Live Search Queries ─────────────────────────────────────
const SEARCH_TASKS = `
  query SearchTasks($tenantId: String!) {
    pmTasks(tenantId: $tenantId) {
      id title status priority type
      assignee { firstName lastName }
    }
  }
`;

const SEARCH_PROJECTS = `
  query SearchProjects($tenantId: String!) {
    pmProjects(tenantId: $tenantId) { id name projectNumber status }
  }
`;

const SEARCH_TICKETS = `
  query SearchTickets($tenantId: String!) {
    itsmTickets(tenantId: $tenantId) {
      id title status priority ticketNumber
    }
  }
`;

interface LiveResult {
    id: string;
    title: string;
    subtitle: string;
    path: string;
    icon: string;
    group: string;
}

export default function CommandPalette({ isDark, themeColor }: CommandPaletteProps) {
    const [open, setOpen] = useState(false);
    const [search, setSearch] = useState("");
    const router = useRouter();
    const containerRef = useRef<HTMLDivElement>(null);
    const [liveResults, setLiveResults] = useState<LiveResult[]>([]);
    const [liveLoading, setLiveLoading] = useState(false);
    const searchTimerRef = useRef<NodeJS.Timeout | null>(null);
    const liveDataCacheRef = useRef<{ tasks: any[]; projects: any[]; tickets: any[] } | null>(null);

    // Keyboard shortcut to open
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.key === "k") {
                e.preventDefault();
                e.stopPropagation();
                setOpen(prev => !prev);
            }
        };
        document.addEventListener("keydown", handleKeyDown);
        return () => document.removeEventListener("keydown", handleKeyDown);
    }, []);

    // Reset search on open; prefetch live data
    useEffect(() => {
        if (open) {
            setSearch("");
            setLiveResults([]);
            // Prefetch data on first open
            if (!liveDataCacheRef.current) {
                Promise.all([
                    gql(SEARCH_TASKS, { tenantId: DEFAULT_TENANT_ID }).catch(() => ({ pmTasks: [] })),
                    gql(SEARCH_PROJECTS, { tenantId: DEFAULT_TENANT_ID }).catch(() => ({ pmProjects: [] })),
                    gql(SEARCH_TICKETS, { tenantId: DEFAULT_TENANT_ID }).catch(() => ({ itsmTickets: [] })),
                ]).then(([taskData, projData, ticketData]) => {
                    liveDataCacheRef.current = {
                        tasks: taskData.pmTasks || [],
                        projects: projData.pmProjects || [],
                        tickets: ticketData.itsmTickets || [],
                    };
                });
            }
        }
    }, [open]);

    // Debounced live search against cached data
    useEffect(() => {
        if (searchTimerRef.current) clearTimeout(searchTimerRef.current);

        if (search.length < 2) {
            setLiveResults([]);
            setLiveLoading(false);
            return;
        }

        setLiveLoading(true);
        searchTimerRef.current = setTimeout(() => {
            const cache = liveDataCacheRef.current;
            if (!cache) {
                setLiveLoading(false);
                return;
            }

            const q = search.toLowerCase();
            const results: LiveResult[] = [];

            // Search tasks
            cache.tasks
                .filter((t: any) => t.title?.toLowerCase().includes(q) || t.id?.toLowerCase().includes(q))
                .slice(0, 5)
                .forEach((t: any) => {
                    const assigneeName = t.assignee ? `${t.assignee.firstName} ${t.assignee.lastName}` : 'Unassigned';
                    results.push({
                        id: `task-${t.id}`,
                        title: t.title,
                        subtitle: `${t.status?.replace('_', ' ')} · ${t.priority} · ${assigneeName}`,
                        path: `/admin/pm/tasks/${t.id}`,
                        icon: t.type === 'bug' ? '🐛' : t.type === 'story' ? '📖' : t.type === 'epic' ? '🏔️' : '✅',
                        group: 'Tasks',
                    });
                });

            // Search projects
            cache.projects
                .filter((p: any) => p.name?.toLowerCase().includes(q) || p.projectNumber?.toLowerCase().includes(q))
                .slice(0, 3)
                .forEach((p: any) => {
                    results.push({
                        id: `proj-${p.id}`,
                        title: p.name,
                        subtitle: `${p.projectNumber || ''} · ${p.status}`,
                        path: `/admin/pm/dashboard?projectId=${p.id}`,
                        icon: '📁',
                        group: 'Projects',
                    });
                });

            // Search tickets
            cache.tickets
                .filter((t: any) => t.title?.toLowerCase().includes(q) || t.ticketNumber?.toLowerCase().includes(q))
                .slice(0, 5)
                .forEach((t: any) => {
                    results.push({
                        id: `ticket-${t.id}`,
                        title: t.title,
                        subtitle: `${t.ticketNumber || ''} · ${t.status} · ${t.priority}`,
                        path: `/admin/itsm/tickets/${t.id}`,
                        icon: '🎫',
                        group: 'Tickets',
                    });
                });

            setLiveResults(results);
            setLiveLoading(false);
        }, 150);

        return () => {
            if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
        };
    }, [search]);

    const handleSelect = useCallback((path: string) => {
        const page = PAGES.find(p => p.path === path);
        if (page) addRecentPage(page);
        router.push(path);
        setOpen(false);
    }, [router]);

    const handleAction = useCallback((action: string) => {
        if (action === 'toggle-theme') {
            // Dispatch custom event for theme toggle
            window.dispatchEvent(new CustomEvent('toggle-dark-mode'));
            setOpen(false);
            return;
        }
        if (action === 'open-ai') {
            window.dispatchEvent(new CustomEvent('open-ai-studio'));
            setOpen(false);
            return;
        }
        // Navigation actions
        const page = PAGES.find(p => p.path === action);
        if (page) addRecentPage(page);
        router.push(action);
        setOpen(false);
    }, [router]);

    const recentPages = getRecentPages();
    const grouped = groupPages(PAGES);
    const showRecent = !search && recentPages.length > 0;

    if (!open) return null;

    // Style tokens
    const overlayBg = isDark ? 'rgba(0, 0, 0, 0.6)' : 'rgba(0, 0, 0, 0.35)';
    const modalBg = isDark
        ? 'rgba(30, 30, 40, 0.92)'
        : 'rgba(255, 255, 255, 0.92)';
    const modalBorder = isDark
        ? '1px solid rgba(255, 255, 255, 0.1)'
        : '1px solid rgba(0, 0, 0, 0.08)';
    const inputColor = isDark ? '#f0f0f0' : '#1a1a1a';
    const placeholderColor = isDark ? 'rgba(255,255,255,0.4)' : 'rgba(0,0,0,0.35)';
    const groupColor = isDark ? 'rgba(255,255,255,0.45)' : 'rgba(0,0,0,0.4)';
    const itemColor = isDark ? '#e0e0e0' : '#1a1a1a';
    const separatorBg = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.05)';
    const footerColor = isDark ? 'rgba(255,255,255,0.35)' : 'rgba(0,0,0,0.35)';
    const kbdBg = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)';
    const kbdBorder = isDark ? 'rgba(255,255,255,0.12)' : 'rgba(0,0,0,0.1)';

    const palette = (
        <div
            style={{
                position: 'fixed',
                inset: 0,
                zIndex: 9999,
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'center',
                paddingTop: '15vh',
                background: overlayBg,
                backdropFilter: 'blur(8px)',
                WebkitBackdropFilter: 'blur(8px)',
                animation: 'cmdkOverlayIn 0.15s ease-out',
            }}
            onClick={() => setOpen(false)}
        >
            <div
                ref={containerRef}
                onClick={e => e.stopPropagation()}
                style={{
                    width: '100%',
                    maxWidth: 640,
                    margin: '0 16px',
                    background: modalBg,
                    border: modalBorder,
                    borderRadius: 16,
                    boxShadow: isDark
                        ? '0 25px 60px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,255,255,0.05)'
                        : '0 25px 60px rgba(0,0,0,0.15), 0 0 0 1px rgba(0,0,0,0.03)',
                    backdropFilter: 'blur(20px)',
                    WebkitBackdropFilter: 'blur(20px)',
                    overflow: 'hidden',
                    animation: 'cmdkModalIn 0.15s ease-out',
                }}
            >
                <Command
                    label="Global Command Palette"
                    loop
                    style={{ width: '100%' }}
                >
                    {/* Search input */}
                    <div style={{
                        display: 'flex',
                        alignItems: 'center',
                        padding: '14px 16px',
                        borderBottom: `1px solid ${separatorBg}`,
                        gap: 10,
                    }}>
                        <svg
                            width="18" height="18" viewBox="0 0 24 24" fill="none"
                            stroke={placeholderColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
                            style={{ flexShrink: 0 }}
                        >
                            <circle cx="11" cy="11" r="8" />
                            <path d="m21 21-4.3-4.3" />
                        </svg>
                        <Command.Input
                            value={search}
                            onValueChange={setSearch}
                            placeholder="Search tasks, projects, tickets, pages..."
                            autoFocus
                            style={{
                                flex: 1,
                                border: 'none',
                                outline: 'none',
                                background: 'transparent',
                                fontSize: 15,
                                color: inputColor,
                                caretColor: themeColor,
                            }}
                        />
                        <kbd style={{
                            fontSize: 11,
                            padding: '2px 6px',
                            borderRadius: 5,
                            background: kbdBg,
                            border: `1px solid ${kbdBorder}`,
                            color: footerColor,
                            fontFamily: 'inherit',
                            flexShrink: 0,
                        }}>
                            ⌘K
                        </kbd>
                    </div>

                    {/* Results list */}
                    <Command.List style={{
                        maxHeight: 360,
                        overflowY: 'auto',
                        padding: '8px',
                    }}>
                        <Command.Empty style={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            padding: '40px 16px',
                            color: placeholderColor,
                            fontSize: 14,
                        }}>
                            {liveLoading ? 'Searching...' : 'No matching results'}
                        </Command.Empty>

                        {/* Live Search Results */}
                        {liveResults.length > 0 && (() => {
                            const liveGroups: Record<string, LiveResult[]> = {};
                            liveResults.forEach(r => {
                                if (!liveGroups[r.group]) liveGroups[r.group] = [];
                                liveGroups[r.group].push(r);
                            });
                            return Object.entries(liveGroups).map(([group, results]) => (
                                <Command.Group key={`live-${group}`} heading={group} style={{ marginBottom: 4 }}>
                                    {results.map(result => (
                                        <Command.Item
                                            key={result.id}
                                            value={`${result.title} ${result.subtitle} ${result.group}`}
                                            onSelect={() => { router.push(result.path); setOpen(false); }}
                                            style={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: 10,
                                                padding: '8px 10px',
                                                borderRadius: 8,
                                                cursor: 'pointer',
                                                fontSize: 14,
                                                color: itemColor,
                                                transition: 'background 0.12s',
                                            }}
                                            data-theme-color={themeColor}
                                        >
                                            <span style={{ fontSize: 16, width: 22, textAlign: 'center' }}>{result.icon}</span>
                                            <div style={{ flex: 1, minWidth: 0 }}>
                                                <div style={{ fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{result.title}</div>
                                                <div style={{ fontSize: 11, color: groupColor, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{result.subtitle}</div>
                                            </div>
                                            <span style={{ fontSize: 11, color: groupColor, flexShrink: 0 }}>{result.group}</span>
                                        </Command.Item>
                                    ))}
                                </Command.Group>
                            ));
                        })()}

                        {/* Recent */}
                        {showRecent && (
                            <Command.Group
                                heading="Recent"
                                style={{ marginBottom: 4 }}
                            >
                                {recentPages.map(page => (
                                    <Command.Item
                                        key={`recent-${page.path}`}
                                        value={`${page.name} ${page.keywords} recent`}
                                        onSelect={() => handleSelect(page.path)}
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 10,
                                            padding: '8px 10px',
                                            borderRadius: 8,
                                            cursor: 'pointer',
                                            fontSize: 14,
                                            color: itemColor,
                                            transition: 'background 0.12s',
                                        }}
                                        data-theme-color={themeColor}
                                    >
                                        <span style={{ fontSize: 16, width: 22, textAlign: 'center' }}>{page.icon}</span>
                                        <span style={{ flex: 1 }}>{page.name}</span>
                                        <span style={{ fontSize: 11, color: groupColor }}>{page.group}</span>
                                    </Command.Item>
                                ))}
                            </Command.Group>
                        )}

                        {/* Quick Actions */}
                        <Command.Group
                            heading="Quick Actions"
                            style={{ marginBottom: 4 }}
                        >
                            {ACTIONS.map(action => (
                                <Command.Item
                                    key={action.action}
                                    value={`${action.name} ${action.keywords}`}
                                    onSelect={() => handleAction(action.action)}
                                    style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 10,
                                        padding: '8px 10px',
                                        borderRadius: 8,
                                        cursor: 'pointer',
                                        fontSize: 14,
                                        color: itemColor,
                                        transition: 'background 0.12s',
                                    }}
                                    data-theme-color={themeColor}
                                >
                                    <span style={{ fontSize: 16, width: 22, textAlign: 'center' }}>{action.icon}</span>
                                    <span style={{ flex: 1 }}>{action.name}</span>
                                </Command.Item>
                            ))}
                        </Command.Group>

                        {/* Navigation pages grouped by module */}
                        {Object.entries(grouped).map(([group, pages]) => (
                            <Command.Group
                                key={group}
                                heading={group}
                                style={{ marginBottom: 4 }}
                            >
                                {pages.map(page => (
                                    <Command.Item
                                        key={page.path}
                                        value={`${page.name} ${page.keywords} ${page.group}`}
                                        onSelect={() => handleSelect(page.path)}
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 10,
                                            padding: '8px 10px',
                                            borderRadius: 8,
                                            cursor: 'pointer',
                                            fontSize: 14,
                                            color: itemColor,
                                            transition: 'background 0.12s',
                                        }}
                                        data-theme-color={themeColor}
                                    >
                                        <span style={{ fontSize: 16, width: 22, textAlign: 'center' }}>{page.icon}</span>
                                        <span style={{ flex: 1 }}>{page.name}</span>
                                        <span style={{ fontSize: 11, color: groupColor }}>{page.group}</span>
                                    </Command.Item>
                                ))}
                            </Command.Group>
                        ))}
                    </Command.List>

                    {/* Footer */}
                    <div style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: 16,
                        padding: '10px 16px',
                        borderTop: `1px solid ${separatorBg}`,
                        fontSize: 11,
                        color: footerColor,
                    }}>
                        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                            <kbd style={{ padding: '1px 5px', borderRadius: 4, background: kbdBg, border: `1px solid ${kbdBorder}`, fontFamily: 'inherit', fontSize: 10 }}>↑</kbd>
                            <kbd style={{ padding: '1px 5px', borderRadius: 4, background: kbdBg, border: `1px solid ${kbdBorder}`, fontFamily: 'inherit', fontSize: 10 }}>↓</kbd>
                            Navigate
                        </span>
                        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                            <kbd style={{ padding: '1px 5px', borderRadius: 4, background: kbdBg, border: `1px solid ${kbdBorder}`, fontFamily: 'inherit', fontSize: 10 }}>↵</kbd>
                            Open
                        </span>
                        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                            <kbd style={{ padding: '1px 5px', borderRadius: 4, background: kbdBg, border: `1px solid ${kbdBorder}`, fontFamily: 'inherit', fontSize: 10 }}>Esc</kbd>
                            Close
                        </span>
                    </div>
                </Command>
            </div>

            {/* Dynamic styles for cmdk + animations */}
            <style>{`
                @keyframes cmdkOverlayIn {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }
                @keyframes cmdkModalIn {
                    from { opacity: 0; transform: scale(0.96) translateY(-8px); }
                    to { opacity: 1; transform: scale(1) translateY(0); }
                }
                [cmdk-group-heading] {
                    font-size: 11px;
                    font-weight: 600;
                    text-transform: uppercase;
                    letter-spacing: 0.5px;
                    padding: 8px 10px 4px;
                    color: ${groupColor};
                    user-select: none;
                }
                [cmdk-item] {
                    content-visibility: auto;
                }
                [cmdk-item][data-selected="true"] {
                    background: ${isDark
                        ? `rgba(${hexToRgbStr(themeColor)}, 0.18)`
                        : `rgba(${hexToRgbStr(themeColor)}, 0.1)`} !important;
                }
                [cmdk-item]:hover {
                    background: ${isDark
                        ? 'rgba(255,255,255,0.06)'
                        : 'rgba(0,0,0,0.04)'};
                }
                [cmdk-input]::placeholder {
                    color: ${placeholderColor};
                }
                [cmdk-list]::-webkit-scrollbar {
                    width: 6px;
                }
                [cmdk-list]::-webkit-scrollbar-track {
                    background: transparent;
                }
                [cmdk-list]::-webkit-scrollbar-thumb {
                    background: ${isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'};
                    border-radius: 3px;
                }
            `}</style>
        </div>
    );

    if (typeof document === 'undefined') return null;
    return createPortal(palette, document.body);
}

/** Convert hex color to "r, g, b" string for rgba() usage */
function hexToRgbStr(hex: string): string {
    const sanitized = hex.replace('#', '');
    const bigint = parseInt(sanitized, 16);
    const r = (bigint >> 16) & 255;
    const g = (bigint >> 8) & 255;
    const b = bigint & 255;
    return `${r}, ${g}, ${b}`;
}

"use client";

import React, { useState, useRef, useCallback } from "react";
import {
  Button, Modal, Upload, Table, Select, Tag, Progress, Space,
  Tooltip, message, Typography, Divider, Alert, Input, Tabs,
} from "antd";
import {
  ImportOutlined, ExportOutlined, CloudUploadOutlined,
  FileExcelOutlined, FileTextOutlined, DownloadOutlined,
  CheckCircleOutlined, CloseCircleOutlined, SwapOutlined,
  DatabaseOutlined, CopyOutlined, InboxOutlined,
} from "@ant-design/icons";
import type { FormInstance } from "antd";

const { Text, Title } = Typography;
const { Dragger } = Upload;

export interface FieldDef {
  name: string;
  label: string;
  required?: boolean;
  type?: "string" | "number" | "boolean" | "date" | "array" | "json";
}

interface DataImportExportProps {
  form: FormInstance;
  entityName: string;
  fields: FieldDef[];
  onBatchCreate?: (records: any[]) => Promise<{ success: number; failed: number; errors?: string[] }>;
  onAfterImport?: () => void;
  gradient?: [string, string];
}

// ─── Helpers ────────────────────────────────────────
function camelToSnake(s: string) { return s.replace(/[A-Z]/g, m => "_" + m.toLowerCase()); }
function snakeToCamel(s: string) { return s.replace(/_([a-z])/g, (_, c) => c.toUpperCase()); }
function normalizeKey(s: string) { return s.toLowerCase().replace(/[\s_\-]+/g, ""); }

function autoMatchColumns(sourceHeaders: string[], targetFields: FieldDef[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  for (const header of sourceHeaders) {
    const normalizedH = normalizeKey(header);
    const camelH = snakeToCamel(header);
    const snakeH = camelToSnake(header);
    let matched = false;
    for (const f of targetFields) {
      const normalizedF = normalizeKey(f.name);
      const normalizedLabel = normalizeKey(f.label);
      if (
        normalizedH === normalizedF ||
        normalizedH === normalizedLabel ||
        camelH === f.name ||
        snakeH === camelToSnake(f.name) ||
        header.toLowerCase() === f.name.toLowerCase() ||
        header.toLowerCase() === f.label.toLowerCase()
      ) {
        mapping[header] = f.name;
        matched = true;
        break;
      }
    }
    if (!matched) mapping[header] = "__skip__";
  }
  return mapping;
}

function applyMapping(row: Record<string, any>, mapping: Record<string, string>): Record<string, any> {
  const result: Record<string, any> = {};
  for (const [srcKey, targetKey] of Object.entries(mapping)) {
    if (targetKey === "__skip__" || !targetKey) continue;
    result[targetKey] = row[srcKey];
  }
  return result;
}

async function parseFile(file: File): Promise<{ headers: string[]; rows: Record<string, any>[] }> {
  const ext = file.name.split(".").pop()?.toLowerCase();
  if (ext === "json") {
    const text = await file.text();
    const parsed = JSON.parse(text);
    const arr = Array.isArray(parsed) ? parsed : [parsed];
    if (arr.length === 0) return { headers: [], rows: [] };
    return { headers: Object.keys(arr[0]), rows: arr };
  }
  // CSV or XLS/XLSX
  const XLSX = await import("xlsx");
  const buffer = await file.arrayBuffer();
  const wb = XLSX.read(buffer, { type: "array" });
  const sheet = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json<Record<string, any>>(sheet, { defval: "" });
  const headers = rows.length > 0 ? Object.keys(rows[0]) : [];
  return { headers, rows };
}

// ─── Component ──────────────────────────────────────
export default function DataImportExport({
  form, entityName, fields, onBatchCreate, onAfterImport, gradient,
}: DataImportExportProps) {
  const g1 = gradient?.[0] || "#6366f1";
  const g2 = gradient?.[1] || "var(--theme-color, #8b5cf6)";

  // Import modal
  const [importOpen, setImportOpen] = useState(false);
  const [importStep, setImportStep] = useState<"upload" | "mapping" | "done">("upload");
  const [importHeaders, setImportHeaders] = useState<string[]>([]);
  const [importRows, setImportRows] = useState<Record<string, any>[]>([]);
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [jsonPaste, setJsonPaste] = useState("");

  // Batch import modal
  const [batchOpen, setBatchOpen] = useState(false);
  const [batchStep, setBatchStep] = useState<"upload" | "mapping" | "preview" | "progress" | "done">("upload");
  const [batchHeaders, setBatchHeaders] = useState<string[]>([]);
  const [batchRows, setBatchRows] = useState<Record<string, any>[]>([]);
  const [batchMapping, setBatchMapping] = useState<Record<string, string>>({});
  const [batchProgress, setBatchProgress] = useState({ total: 0, done: 0, success: 0, failed: 0, errors: [] as string[] });

  // ═══ IMPORT (single record) ═══
  const handleImportFile = async (file: File) => {
    try {
      const { headers, rows } = await parseFile(file);
      if (rows.length === 0) { message.warning("File is empty"); return; }
      setImportHeaders(headers);
      setImportRows(rows);
      const mapping = autoMatchColumns(headers, fields);
      setColumnMapping(mapping);
      const autoMatched = Object.values(mapping).filter(v => v !== "__skip__").length;
      if (autoMatched === headers.length) {
        // All matched, apply directly
        form.setFieldsValue(applyMapping(rows[0], mapping));
        message.success(`Imported ${autoMatched} fields from ${file.name}`);
        setImportOpen(false);
        onAfterImport?.();
      } else {
        setImportStep("mapping");
      }
    } catch (e: any) {
      message.error(`Failed to parse file: ${e.message}`);
    }
  };

  const handleJsonPaste = () => {
    try {
      const parsed = JSON.parse(jsonPaste);
      const obj = Array.isArray(parsed) ? parsed[0] : parsed;
      const headers = Object.keys(obj);
      setImportHeaders(headers);
      setImportRows([obj]);
      const mapping = autoMatchColumns(headers, fields);
      setColumnMapping(mapping);
      const autoMatched = Object.values(mapping).filter(v => v !== "__skip__").length;
      if (autoMatched === headers.length) {
        form.setFieldsValue(applyMapping(obj, mapping));
        message.success(`Imported ${autoMatched} fields`);
        setImportOpen(false);
        onAfterImport?.();
      } else {
        setImportStep("mapping");
      }
    } catch (e: any) {
      message.error(`Invalid JSON: ${e.message}`);
    }
  };

  const applyImportMapping = () => {
    const mapped = applyMapping(importRows[0], columnMapping);
    form.setFieldsValue(mapped);
    const count = Object.values(columnMapping).filter(v => v !== "__skip__").length;
    message.success(`Mapped ${count} fields into form`);
    setImportOpen(false);
    setImportStep("upload");
    onAfterImport?.();
  };

  const resetImport = () => {
    setImportOpen(false);
    setImportStep("upload");
    setImportHeaders([]);
    setImportRows([]);
    setColumnMapping({});
    setJsonPaste("");
  };

  // ═══ EXPORT ═══
  const handleExport = () => {
    const values = form.getFieldsValue();
    const clean: Record<string, any> = {};
    for (const [k, v] of Object.entries(values)) {
      if (v !== undefined && v !== null && v !== "") clean[k] = v;
    }
    const json = JSON.stringify(clean, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${entityName}_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    message.success("Exported to JSON");
  };

  // ═══ TEMPLATE ═══
  const handleDownloadTemplate = (format: "json" | "csv") => {
    if (format === "json") {
      const template: Record<string, any> = {};
      fields.forEach(f => {
        template[f.name] = f.type === "number" ? 0 : f.type === "boolean" ? false : f.type === "array" ? [] : "";
      });
      const json = JSON.stringify([template], null, 2);
      const blob = new Blob([json], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${entityName}_template.json`;
      a.click();
      URL.revokeObjectURL(url);
    } else {
      const headers = fields.map(f => f.name).join(",");
      const blob = new Blob([headers + "\n"], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${entityName}_template.csv`;
      a.click();
      URL.revokeObjectURL(url);
    }
    message.success(`Downloaded ${format.toUpperCase()} template`);
  };

  // ═══ BATCH IMPORT ═══
  const handleBatchFile = async (file: File) => {
    try {
      const { headers, rows } = await parseFile(file);
      if (rows.length === 0) { message.warning("File is empty"); return; }
      setBatchHeaders(headers);
      setBatchRows(rows);
      const mapping = autoMatchColumns(headers, fields);
      setBatchMapping(mapping);
      const autoMatched = Object.values(mapping).filter(v => v !== "__skip__").length;
      if (autoMatched === headers.length) {
        setBatchStep("preview");
      } else {
        setBatchStep("mapping");
      }
    } catch (e: any) {
      message.error(`Failed to parse file: ${e.message}`);
    }
  };

  const applyBatchMapping = () => setBatchStep("preview");

  const executeBatchImport = async () => {
    if (!onBatchCreate) return;
    setBatchStep("progress");
    const mappedRows = batchRows.map(r => applyMapping(r, batchMapping));
    setBatchProgress({ total: mappedRows.length, done: 0, success: 0, failed: 0, errors: [] });
    const result = await onBatchCreate(mappedRows);
    setBatchProgress({
      total: mappedRows.length,
      done: mappedRows.length,
      success: result.success,
      failed: result.failed,
      errors: result.errors || [],
    });
    setBatchStep("done");
  };

  const resetBatch = () => {
    setBatchOpen(false);
    setBatchStep("upload");
    setBatchHeaders([]);
    setBatchRows([]);
    setBatchMapping({});
    setBatchProgress({ total: 0, done: 0, success: 0, failed: 0, errors: [] });
  };

  // ─── Mapping Table ─────────────────────────────────
  const renderMappingTable = (
    headers: string[],
    mapping: Record<string, string>,
    setMapping: (m: Record<string, string>) => void,
    rows: Record<string, any>[],
  ) => {
    const autoMatched = Object.values(mapping).filter(v => v !== "__skip__").length;
    return (
      <div>
        <div className="flex items-center justify-between mb-3">
          <div>
            <Text strong className="text-sm">Map Source Columns → Form Fields</Text>
            <div>
              <Tag color={autoMatched === headers.length ? "green" : "orange"} className="rounded-full mt-1">
                {autoMatched}/{headers.length} auto-matched
              </Tag>
            </div>
          </div>
          <Button size="small" onClick={() => setMapping(autoMatchColumns(headers, fields))}>
            Reset Mapping
          </Button>
        </div>
        <div style={{
          maxHeight: 350, overflowY: "auto",
          border: "1px solid #f0f0f0", borderRadius: 10, padding: 12,
          background: "#fafafa",
        }}>
          {headers.map((h, i) => (
            <div key={i} className="flex items-center gap-2 mb-2" style={{ minHeight: 36 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <Tag className="rounded text-xs truncate" style={{ maxWidth: "100%" }}>{h}</Tag>
                {rows[0] && (
                  <Text type="secondary" className="text-xs block truncate" style={{ maxWidth: 160 }}>
                    {String(rows[0][h] ?? "").slice(0, 40)}
                  </Text>
                )}
              </div>
              <SwapOutlined className="text-gray-400" style={{ fontSize: 12 }} />
              <Select
                size="small"
                value={mapping[h] || "__skip__"}
                onChange={(v) => setMapping({ ...mapping, [h]: v })}
                style={{ width: 180 }}
                options={[
                  { value: "__skip__", label: <Text type="secondary" className="text-xs">⏭ (skip)</Text> },
                  ...fields.map(f => ({
                    value: f.name,
                    label: <span className="text-xs">{f.required ? "* " : ""}{f.label}</span>,
                  })),
                ]}
              />
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ─── Render ────────────────────────────────────────
  return (
    <>
      {/* Toolbar */}
      <div style={{
        display: "flex", gap: 6, flexWrap: "wrap",
        padding: "8px 0",
        borderBottom: "1px solid #f0f0f0",
        marginBottom: 12,
      }}>
        <Tooltip title="Import from JSON, CSV, or Excel">
          <Button size="small" icon={<ImportOutlined />}
            onClick={() => { resetImport(); setImportOpen(true); }}
            style={{ borderRadius: 6, fontSize: 12 }}>
            Import
          </Button>
        </Tooltip>
        <Tooltip title="Export current form data as JSON">
          <Button size="small" icon={<ExportOutlined />}
            onClick={handleExport}
            style={{ borderRadius: 6, fontSize: 12 }}>
            Export
          </Button>
        </Tooltip>
        {onBatchCreate && (
          <Tooltip title="Batch import multiple records from file">
            <Button size="small" icon={<DatabaseOutlined />}
              onClick={() => { resetBatch(); setBatchOpen(true); }}
              style={{ borderRadius: 6, fontSize: 12 }}>
              Batch Import
            </Button>
