  open: boolean;
  onCancel: () => void;
  onSubmit: (values: any) => Promise<void>;
  form: FormInstance;
  title: string;
  entityName: string;
  steps: StepDef[];
  fields: FieldDef[];
  width?: number;
  loading?: boolean;
  onBatchCreate?: (records: any[]) => Promise<{ success: number; failed: number; errors?: string[] }>;
  gradient?: [string, string];
  editMode?: boolean;
  initialValues?: Record<string, any>;
}

const fmtValue = (v: any): React.ReactNode => {
  if (v === undefined || v === null || v === "") return <Text type="secondary" className="text-xs">—</Text>;
  if (typeof v === "boolean") return <Tag color={v ? "green" : "default"} className="rounded-full text-xs">{v ? "Yes" : "No"}</Tag>;
  if (Array.isArray(v)) {
    if (v.length === 0) return <Text type="secondary" className="text-xs">—</Text>;
    return <>{v.map((item, i) => <Tag key={i} className="rounded-full text-xs mb-0.5">{String(item)}</Tag>)}</>;
  }
  if (typeof v === "object") return <Text code className="text-xs">{JSON.stringify(v)}</Text>;
  if (typeof v === "number") {
    if (v >= 1000) return <Text strong className="text-sm">{v.toLocaleString()}</Text>;
    return <Text className="text-sm">{v}</Text>;
  }
  return <Text className="text-sm">{String(v)}</Text>;
};

export default function SteppedFormModal({
  open, onCancel, onSubmit, form, title, entityName,
  steps, fields, width = 620, loading = false,
  onBatchCreate, gradient, editMode = false, initialValues,
}: SteppedFormModalProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const { themeColor } = usePreferencesStore();
  const g1 = gradient?.[0] || themeColor || "#6366f1";
  const g2 = gradient?.[1] || `${themeColor}dd` || "var(--theme-color, #8b5cf6)";

  const totalSteps = steps.length + 1; // +1 for review step
  const isReviewStep = currentStep === steps.length;

  const handleNext = async () => {
    if (currentStep < steps.length) {
      try {
        const currentFields = steps[currentStep].fields;
        if (currentFields.length > 0) {
          await form.validateFields(currentFields);
        }
        setCurrentStep(currentStep + 1);
      } catch {
        // validation error, stay
      }
    }
  };

  const handleBack = () => {
    if (currentStep > 0) setCurrentStep(currentStep - 1);
  };

  const handleSubmit = async () => {
    try {
      const values = form.getFieldsValue();
      await onSubmit(values);
      setCurrentStep(0);
    } catch {
      // handled by parent
    }
  };

  const handleCancel = () => {
    setCurrentStep(0);
    onCancel();
  };

  const goToStep = (step: number) => {
    if (step < steps.length) setCurrentStep(step);
  };

  // Build review data
  const reviewData = useMemo(() => {
    if (!open) return [];
    const values = form.getFieldsValue();
    return steps.map((step, i) => ({
      title: step.title,
      stepIndex: i,
      items: step.fields
        .map(fieldName => {
          const fieldDef = fields.find(f => f.name === fieldName);
          return {
            name: fieldName,
            label: fieldDef?.label || fieldName,
            value: values[fieldName],
          };
        })
        .filter(item => item.value !== undefined && item.value !== null && item.value !== ""),
    }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, currentStep, steps, fields]);

  return (
    <Modal
      title={
        <span
          style={{ fontSize: 16, fontWeight: 600, background: `linear-gradient(135deg, ${g1}, ${g2})`, WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}
        >
          {editMode ? `✏️ ${title}` : `✨ ${title}`}
        </span>
      }
      open={open}
      onCancel={handleCancel}
      footer={null}
      width={width}
      centered
      destroyOnClose={false}
      styles={{
        header: { padding: "14px 24px", background: `linear-gradient(135deg, ${g1}06, ${g2}03)`, borderBottom: "1px solid #f0f0f0" },
        body: { padding: 0 },
      }}
    >
      {/* Steps indicator */}
      <div style={{ padding: "12px 24px 8px", borderBottom: "1px solid #f5f5f5", background: `linear-gradient(135deg, ${g1}04, ${g2}02)` }}>
        <div className="themed-steps" style={{ '--step-theme-color': g1, '--step-theme-color-light': `${g1}18` } as React.CSSProperties}>
          <style>{`
            .themed-steps .ant-steps-item .ant-steps-item-icon {
              width: 28px !important;
              height: 28px !important;
              line-height: 28px !important;
              font-size: 14px !important;
              overflow: visible !important;
            }
            .themed-steps .ant-steps-item .ant-steps-item-icon .ant-steps-icon {
              font-size: 14px !important;
            }
            .themed-steps .ant-steps-item .ant-steps-item-icon .anticon {
              font-size: 14px !important;
            }
            .themed-steps .ant-steps-item-process .ant-steps-item-icon {
              background: var(--step-theme-color) !important;
              border-color: var(--step-theme-color) !important;
            }
            .themed-steps .ant-steps-item-process .ant-steps-item-icon > .ant-steps-icon,
            .themed-steps .ant-steps-item-process .ant-steps-item-icon .anticon {
              color: #fff !important;
            }
            .themed-steps .ant-steps-item-process .ant-steps-item-icon .anticon svg {
              fill: #fff !important;
            }
            .themed-steps .ant-steps-item-finish .ant-steps-item-icon {
              background: var(--step-theme-color-light) !important;
              border-color: var(--step-theme-color) !important;
            }
            .themed-steps .ant-steps-item-finish .ant-steps-item-icon > .ant-steps-icon,
            .themed-steps .ant-steps-item-finish .ant-steps-item-icon .anticon {
              color: var(--step-theme-color) !important;
            }
            .themed-steps .ant-steps-item-finish .ant-steps-item-icon .anticon svg {
              fill: var(--step-theme-color) !important;
            }
            .themed-steps .ant-steps-item-finish > .ant-steps-item-container > .ant-steps-item-tail::after {
              background-color: var(--step-theme-color) !important;
            }
            .themed-steps .ant-steps-item-wait .ant-steps-item-icon {
              border-color: #d9d9d9 !important;
              background: transparent !important;
            }
            .themed-steps .ant-steps-item-wait .ant-steps-item-icon > .ant-steps-icon,
            .themed-steps .ant-steps-item-wait .ant-steps-item-icon .anticon {
              color: rgba(0,0,0,0.25) !important;
            }
          `}</style>
          <Steps
            size="small"
            current={currentStep}
            items={[
              ...steps.map((s, i) => ({
                title: <Text className="text-xs" style={{ whiteSpace: 'nowrap' }}>{s.title}</Text>,
                icon: s.icon,
              })),
              {
                title: <Text className="text-xs" style={{ whiteSpace: 'nowrap' }}>Review</Text>,
                icon: <FileTextOutlined />,
              },
            ]}
            style={{ maxWidth: "100%" }}
          />
        </div>
      </div>

      {/* Content */}
      <div style={{ padding: "16px 28px" }}>
        {/* Import/Export toolbar — only on first step */}
        {currentStep === 0 && (
          <DataImportExport
            form={form}
            entityName={entityName}
            fields={fields}
            onBatchCreate={onBatchCreate}
            gradient={[g1, g2]}
          />
        )}

        <Form form={form} layout="vertical" size="middle" initialValues={initialValues}>
          {/* Render ALL form steps — hide non-active with display:none to preserve field state */}
          {steps.map((step, idx) => (
            <div key={`step-${idx}`} style={{ display: currentStep === idx ? 'block' : 'none' }}>
              {step.content}
            </div>
          ))}
        </Form>

          {/* Review Step — rendered separately (no form fields) */}
          {isReviewStep && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <FileTextOutlined style={{ color: g1 }} />
                <Text strong className="text-sm">Review Before Submitting</Text>
              </div>

              {reviewData.map((section, i) => (
                <Card
                  key={i}
                  size="small"
                  className="mb-2 cursor-pointer hover:shadow-sm transition-shadow"
                  onClick={() => goToStep(section.stepIndex)}
                  style={{
                    borderRadius: 10,
                    border: "1px solid #f0f0f0",
                    background: "#fafafa",
                  }}
                  title={
                    <div className="flex items-center justify-between">
                      <Text strong className="text-xs">{section.title}</Text>
                      <Divider orientation="vertical" />
                      <Button type="link" size="small" icon={<EditOutlined />} className="text-xs p-0"
                        style={{ color: g1, height: "auto" }}>
                        Edit
                      </Button>
                    </div>
                  }
                  styles={{ header: { minHeight: 32, padding: "4px 12px" }, body: { padding: "8px 12px" } }}
                >
                  {section.items.length === 0 ? (
                    <Text type="secondary" className="text-xs">No fields filled</Text>
                  ) : (
                    <Descriptions size="small" column={2} colon={false}>
                      {section.items.map((item, j) => (
                        <Descriptions.Item
                          key={j}
                          label={<Text type="secondary" className="text-xs">{item.label}</Text>}
                          span={typeof item.value === "object" && !Array.isArray(item.value) ? 2 : 1}
                        >
                          {fmtValue(item.value)}
                        </Descriptions.Item>
                      ))}
                    </Descriptions>
                  )}
                </Card>
              ))}

              <Alert
                message={<Text className="text-xs">Click any section to go back and edit</Text>}
                type="info"
                showIcon
                style={{ borderRadius: 8, marginTop: 8 }}
              />
            </div>
          )}
      </div>

      {/* Footer Navigation */}
      <div style={{
        padding: "12px 28px 20px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
      }}>
        <div>
          {currentStep > 0 && (
            <Button onClick={handleBack} style={{ borderRadius: 8 }} icon={<ArrowLeftOutlined />}>
              Back
            </Button>
          )}
        </div>

        <Space>
          <Text type="secondary" className="text-xs">
            Step {currentStep + 1} of {totalSteps}
          </Text>
          {!isReviewStep ? (
            <Button
              type="primary"
              onClick={handleNext}
              style={{
                background: `linear-gradient(135deg, ${g1}, ${g2})`,
                border: "none",
                borderRadius: 8,
                minWidth: 120,
              }}
              icon={<ArrowRightOutlined />}
            >
              Next
            </Button>
          ) : (
            <Button
              type="primary"
              onClick={handleSubmit}
              loading={loading}
              style={{
                background: "linear-gradient(135deg, #10b981, #059669)",
                border: "none",
                borderRadius: 8,
                minWidth: 140,
              }}
              icon={<CheckCircleOutlined />}
            >
              {editMode ? "Save Changes" : "Submit"}
            </Button>
          )}
        </Space>
      </div>
    </Modal>
  );
}

"use client";

import React, { useState } from "react";
import { motion } from "framer-motion";

interface MagicButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    children: React.ReactNode;
    className?: string;
    icon?: React.ReactNode;
    size?: "small" | "default" | "large";
}

export const MagicButton: React.FC<MagicButtonProps> = ({
    children,
    className = "",
    icon,
    size = "default",
    disabled,
    ...props
}) => {
    const [isHovered, setIsHovered] = useState(false);
    const isSmall = size === "small";
    const isLarge = size === "large";
    const contentWidth = isLarge ? 130 : isSmall ? 66 : 76;
    const padding = isLarge ? "px-5" : isSmall ? "pl-4 pr-5" : "px-4";
    const circleSize = isSmall ? 18 : 24;
    const buttonHeight = isSmall ? "h-7" : "h-9";
    const circleTop = isSmall ? 5 : 6;
    const circleLeft = isLarge ? 18 : isSmall ? 8 : 14;
    const textOffset = isLarge ? 20 : isSmall ? 14 : 14;
    // Using same distance from right edge as left icon from left edge
    const circleRight = circleLeft;

    // Muted gradient for disabled state
    const borderGradient = disabled
        ? "conic-gradient(from 0deg at 50% 50%, transparent 0deg, transparent 270deg, #9ca3af 300deg, #6b7280 330deg, #4b5563 345deg, #9ca3af 360deg)"
        : "conic-gradient(from 0deg at 50% 50%, transparent 0deg, transparent 270deg, var(--theme-accent, #00ffff) 300deg, var(--theme-secondary, #ff00ff) 330deg, var(--theme-color, #9333ea) 345deg, var(--theme-accent, #00ffff) 360deg)";

    return (
        <div className={`relative inline-block ${disabled ? "opacity-60" : ""}`}>
            {/* Outer wrapper for beam effect - masked to show only border */}
            <span
                className="absolute inset-[-1.5px] rounded-full pointer-events-none overflow-hidden"
                style={{
                    zIndex: 0,
                    // Mask creates a ring by making center transparent
                    WebkitMask: "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
                    WebkitMaskComposite: "xor",
                    maskComposite: "exclude",
                    padding: "1.5px", // This controls border thickness
                }}
            >
                <span
                    className="absolute inset-[-200%]"
                    style={{
                        background: borderGradient,
                        animation: "spin 3s linear infinite",
                    }}
                />
            </span>

            <motion.button
                whileTap={disabled ? {} : { scale: 0.98 }}
                onMouseEnter={() => !disabled && setIsHovered(true)}
                onMouseLeave={() => setIsHovered(false)}
                disabled={disabled}
                className={`
                    group relative inline-flex ${buttonHeight} items-center justify-center 
                    rounded-full ${padding} ${isSmall ? 'text-[11px]' : 'text-xs'} font-medium
                    ${disabled ? "cursor-not-allowed" : "cursor-pointer"} overflow-hidden
                    bg-white dark:bg-[#1a1b23]
                    shadow-[0_4px_14px_rgba(var(--theme-color-rgb,147,51,234),0.15),0_2px_6px_rgba(0,0,0,0.08)]
                    dark:shadow-[0_4px_14px_rgba(var(--theme-color-rgb,147,51,234),0.4),0_2px_6px_rgba(0,0,0,0.2)]
                    ${className}
                `}
                {...props as any}
            >
                {/* Expanding circle - animates from icon size to fill button */}
                <motion.span
                    className="absolute rounded-full"
                    style={{
                        background: "linear-gradient(135deg, var(--theme-color, #9333ea) 0%, var(--theme-color, #7c3aed) 30%, var(--theme-secondary, #6366f1) 60%, var(--theme-accent, #00ffff) 100%)",
                        zIndex: 1,
                    }}
                    initial={{
                        left: circleLeft,
                        top: circleTop,
                        width: circleSize,
                        height: circleSize,
                    }}
                    animate={isHovered ? {
                        left: -50,
                        top: -50,
                        width: 300,
                        height: 300,
                    } : {
                        left: circleLeft,
                        top: circleTop,
                        width: circleSize,
                        height: circleSize,
                    }}
                    transition={{
                        duration: 0.4,
                        ease: "easeOut",
                    }}
                />

                {/* Shimmer effect */}
                <span
                    className="absolute inset-0 overflow-hidden rounded-full pointer-events-none transition-opacity duration-300"
                    style={{
                        zIndex: 2,
                        opacity: isHovered ? 1 : 0,
                    }}
                >
                    <span
                        className="absolute inset-0"
                        style={{
                            background: "linear-gradient(105deg, transparent 20%, rgba(255,255,255,0.4) 45%, rgba(255,255,255,0.6) 50%, rgba(255,255,255,0.4) 55%, transparent 80%)",
                            animation: "shimmer-move 2s ease-in-out infinite",
                        }}
                    />
                </span>

                {/* Left Icon - Positioned exactly at circle center */}
                <motion.span
                    className="absolute flex items-center justify-center rounded-full"
                    style={{
                        left: circleLeft,
                        top: circleTop,
                        width: circleSize,
                        height: circleSize,
                        zIndex: 20
                    }}
                    animate={isHovered ? { opacity: 0, scale: 0.75 } : { opacity: 1, scale: 1 }}
                    transition={{ duration: 0.3 }}
                >
                    <span className={`text-white ${isSmall ? 'text-[10px]' : 'text-xs'} flex items-center justify-center`}>{icon}</span>
                </motion.span>

                {/* Right Icon - Same vertical position as left icon */}
                <motion.span
                    className="absolute flex items-center justify-center rounded-full"
                    style={{
                        right: circleRight,
                        top: circleTop,
                        width: circleSize,
                        height: circleSize,
                        zIndex: 20
                    }}
                    animate={isHovered ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.75 }}
                    transition={{ duration: 0.3, delay: 0.2 }}
                >
                    <span className="text-white text-xs flex items-center justify-center">{icon}</span>
                </motion.span>

                {/* Content Text */}
                <span className="relative flex items-center justify-center" style={{ width: contentWidth, zIndex: 10 }}>
                    <motion.span
                        className="font-semibold whitespace-nowrap"
                        animate={isHovered ? { x: -8, color: "#ffffff" } : { x: textOffset, color: "var(--theme-color, #7c3aed)" }}
                        transition={{ duration: 0.3, delay: 0.1 }}
                    >
                        {children}
                    </motion.span>
                </span>
            </motion.button>
        </div>
    );
};

import React from 'react';
import { useDcimStore } from '@/store/useDcimStore';

export function FloorPlanCanvas({ onRackClick }: { onRackClick?: (id: string) => void }) {
    const { racks, selectedRackId, viewMode } = useDcimStore();

    // Mapping 3D coordinates to 2D SVG canvas (scale x20 for visibility)
    const scale = 20;
    const offsetX = 400; // Center X
    const offsetY = 300; // Center Y

    const getRackColor = (rack: any) => {
        if (selectedRackId === rack.id) return '#1890ff';
        if (viewMode === 'Thermal') {
            return rack.temp > 29 ? '#f5222d' : rack.temp > 25 ? '#faad14' : '#52c41a';
        }
        if (viewMode === 'Power') {
            return rack.power > 7 ? '#722ed1' : rack.power > 4 ? '#108ee9' : '#87d068';
        }
        return rack.status === 'critical' ? '#f5222d' : rack.status === 'warning' ? '#faad14' : '#1f1f1f';
    };

    return (
        <svg width="100%" height="100%" viewBox="0 0 800 600" style={{ background: '#f0f2f5', borderRadius: 8 }}>
            {/* Grid Pattern */}
            <defs>
                <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
                    <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#e8e8e8" strokeWidth="1"/>
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />

            {/* Room Boundary */}
            <rect x="100" y="50" width="600" height="500" fill="none" stroke="#d9d9d9" strokeWidth="4" rx="8" />
            <text x="120" y="80" fill="#bfbfbf" fontSize="16" fontWeight="bold">Main Data Hall</text>

            {/* Render Racks from Store */}
            {racks.map(rack => {
                const cx = offsetX + (rack.x * scale);
                const cy = offsetY + (rack.z * scale);
                const width = 0.8 * scale;
                const height = 1.2 * scale;

                return (
                    <g 
                        key={rack.id} 
                        transform={`translate(${cx - width/2}, ${cy - height/2})`} 
                        onClick={() => onRackClick?.(rack.id)}
                        style={{ cursor: 'pointer' }}
                    >
                        <rect 
                            width={width} 
                            height={height} 
                            fill={getRackColor(rack)} 
                            rx="2"
                            stroke={selectedRackId === rack.id ? '#096dd9' : '#000'}
                            strokeWidth={selectedRackId === rack.id ? 2 : 1}
                        />
                        {/* Rack label if zoomed in enough, but keeping simple for now */}
                        <text x={width/2} y={height/2 + 3} fill="white" fontSize="8" textAnchor="middle" style={{ pointerEvents: 'none' }}>
                            {rack.name}
                        </text>
                    </g>
                );
            })}

            {/* CRAC Units */}
            <g transform={`translate(${offsetX - 8*scale - 15}, ${offsetY - 2*scale - 20})`}>
                <rect width="30" height="40" fill="#434343" rx="4" />
                <text x="15" y="25" fill="#fff" fontSize="10" textAnchor="middle">CRAC</text>
            </g>
            <g transform={`translate(${offsetX + 8*scale - 15}, ${offsetY - 2*scale - 20})`}>
                <rect width="30" height="40" fill="#434343" rx="4" />
                <text x="15" y="25" fill="#fff" fontSize="10" textAnchor="middle">CRAC</text>
            </g>
        </svg>
    );
}

import React, { useRef, useState } from 'react';
import { useFrame } from '@react-three/fiber';
import { RoundedBox, Html, useCursor, TransformControls } from '@react-three/drei';
import * as THREE from 'three';
import { ServerUnit } from './ServerUnit';
import { useDcimStore } from '@/store/useDcimStore';

interface RackModelProps {
    data: any;
    viewMode: string;
    onClick: (data: any) => void;
    isSelected: boolean;
}

export function RackModel({ data, viewMode, onClick, isSelected }: RackModelProps) {
    const { editMode, updateRackPosition, racks } = useDcimStore();
    const [hovered, setHovered] = useState(false);
    useCursor(hovered, 'pointer', 'auto');
    const ref = useRef<THREE.Group>(null);
    const ledMaterial = useRef<THREE.MeshStandardMaterial>(null);

    const getColor = () => {
        if (isSelected) return '#1890ff';
        if (hovered) return '#40a9ff';
        
        switch (viewMode) {
            case 'Thermal': return data.temp < 25 ? '#52c41a' : data.temp < 29 ? '#faad14' : '#ff4d4f';
            case 'Power': return data.power < 4 ? '#87d068' : data.power < 7 ? '#108ee9' : '#722ed1';
            case 'Utilization': 
                const util = data.usedU / data.totalU;
                return util < 0.5 ? '#d9d9d9' : util < 0.8 ? '#52c41a' : '#ff4d4f';
            default: return '#262626';
        }
    };

    useFrame(({ clock }) => {
        if (ledMaterial.current && data.status !== 'normal') {
            const speed = data.status === 'critical' ? 10 : 3;
            ledMaterial.current.emissiveIntensity = ((Math.sin(clock.elapsedTime * speed) + 1) / 2) * 5 + 2;
        } else if (ledMaterial.current) {
            ledMaterial.current.emissiveIntensity = 2; // Base glow for normal
        }
    });

    const handleDragEnd = () => {
        if (ref.current) {
            const p = ref.current.position;
            const snapX = Math.round(p.x * 2) / 2;
            const snapZ = Math.round(p.z * 2) / 2;
            updateRackPosition(data.id, snapX, snapZ, data.rotationY);
        }
    };

    // Basic collision check against other racks
    const isColliding = racks.some(r => {
        if (r.id === data.id) return false;
        const dx = r.x - data.x;
        const dz = r.z - data.z;
        return Math.sqrt(dx * dx + dz * dz) < 0.8;
    });

    const rackGroup = (
        <group position={[data.x, 1, data.z]} 
               rotation={[0, data.rotationY || 0, 0]}
               onClick={(e) => { e.stopPropagation(); onClick(data); }}
               onPointerOver={(e) => { e.stopPropagation(); setHovered(true); }}
               onPointerOut={() => setHovered(false)}
               ref={ref}
        >
            {editMode && isSelected && (
                <mesh position={[0, -0.9, 0]} rotation={[-Math.PI / 2, 0, 0]}>
                    <ringGeometry args={[1.2, 1.4, 32]} />
                    <meshBasicMaterial color={isColliding ? "#ff4d4f" : "#1890ff"} transparent opacity={0.8} />
                </mesh>
            )}
            {editMode && isSelected && (
                <Html position={[0, 2.5, 0]} center>
                    <div style={{ background: 'rgba(0,0,0,0.8)', padding: 4, borderRadius: 8, display: 'flex', gap: 4, pointerEvents: 'auto' }}>
                        <button 
                            onClick={(e) => { 
                                e.stopPropagation(); 
                                updateRackPosition(data.id, data.x, data.z, (data.rotationY || 0) + Math.PI / 2); 
                            }}
                            style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer', padding: '4px 8px' }}
                        >
                            Rotate +90°
                        </button>
                    </div>
                </Html>
            )}
            <RoundedBox args={[0.8, 2, 1.2]} radius={0.05} smoothness={4}>
                <meshStandardMaterial color={getColor()} metalness={viewMode === 'Normal' ? 0.6 : 0.1} roughness={0.4} />
            </RoundedBox>

            {viewMode === 'Normal' && (
                <mesh position={[0, 0, 0.61]}>
                    <planeGeometry args={[0.7, 1.9]} />
                    <meshPhysicalMaterial color="#111" transparent opacity={0.6} roughness={0.1} metalness={0.8} />
                </mesh>
            )}

            {viewMode === 'Normal' && Array.from({ length: Math.floor(data.usedU / 4) }).map((_, i) => (
                <ServerUnit key={i} position={[0, -0.8 + (i * 0.15), 0.5]} status={data.status} />
            ))}

            {viewMode === 'Normal' && (
                <mesh position={[0.3, 0.9, 0.62]}>
                    <circleGeometry args={[0.02, 16]} />
                    <meshStandardMaterial 
                        ref={ledMaterial}
                        color={data.status === 'critical' ? '#ff4d4f' : data.status === 'warning' ? '#faad14' : '#52c41a'} 
                        emissive={data.status === 'critical' ? '#ff4d4f' : data.status === 'warning' ? '#faad14' : '#52c41a'}
                        emissiveIntensity={data.status === 'normal' ? 2 : 5}
                        toneMapped={false}
                    />
                </mesh>
            )}

            {(hovered || isSelected || viewMode !== 'Normal') && !editMode && (
                <Html position={[0, 1.2, 0]} center style={{ pointerEvents: 'none' }}>
                    <div style={{
                        background: 'rgba(0,0,0,0.75)', color: 'white', padding: '4px 8px',
                        borderRadius: 4, fontSize: 12, backdropFilter: 'blur(4px)',
                        border: isSelected ? '1px solid #1890ff' : 'none', whiteSpace: 'nowrap'
                    }}>
                        <strong>{data.name}</strong>
                        {viewMode === 'Thermal' && <div>{data.temp}°C</div>}
                        {viewMode === 'Power' && <div>{data.power} kW</div>}
                        {viewMode === 'Utilization' && <div>{Math.round((data.usedU/data.totalU)*100)}% Used</div>}
                    </div>
                </Html>
            )}
        </group>
    );

    if (editMode && isSelected) {
        return (
            <TransformControls mode="translate" showY={false} onMouseUp={handleDragEnd} translationSnap={0.5}>
                {rackGroup}
            </TransformControls>
        );
    }

    return rackGroup;
}

import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

export function ServerUnit({ position, status }: { position: [number, number, number], status: string }) {
    const ledRef = useRef<THREE.MeshStandardMaterial>(null);

    useFrame(({ clock }) => {
        if (ledRef.current) {
            // Blinking activity light
            if (status === 'normal') {
                ledRef.current.emissiveIntensity = Math.random() > 0.9 ? 5 : 0;
            } else if (status === 'critical') {
                ledRef.current.emissiveIntensity = Math.random() > 0.5 ? 8 : 2;
            } else {
                ledRef.current.emissiveIntensity = 4;
            }
        }
    });

    return (
        <group position={position}>
            <mesh>
                <boxGeometry args={[0.6, 0.1, 0.2]} />
                <meshStandardMaterial color="#1f1f1f" />
            </mesh>
            <mesh position={[0.2, 0, 0.11]}>
                <circleGeometry args={[0.015, 16]} />
                <meshStandardMaterial 
                    ref={ledRef}
                    color={status === 'critical' ? '#ff4d4f' : '#52c41a'} 
                    emissive={status === 'critical' ? '#ff4d4f' : '#52c41a'}
                    toneMapped={false}
                />
            </mesh>
        </group>
    );
}

