"use client";

import React, { useRef } from "react";
import { useDrag, useDrop, DndProvider } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";

// Item type for drag and drop
export const ItemTypes = {
    BLOCK: "block",
    LIBRARY_BLOCK: "library_block",
};

// Wrapper type for library items
interface LibraryItem {
    type: string;
    name: string;
    icon: string;
}

// Draggable block from library
interface DraggableLibraryBlockProps {
    item: LibraryItem;
    children: React.ReactNode;
}

export const DraggableLibraryBlock: React.FC<DraggableLibraryBlockProps> = ({ item, children }) => {
    const ref = useRef<HTMLDivElement>(null);
    const [{ isDragging }, drag] = useDrag(() => ({
        type: ItemTypes.LIBRARY_BLOCK,
        item: { type: item.type, name: item.name, icon: item.icon },
        collect: (monitor) => ({
            isDragging: monitor.isDragging(),
        }),
    }));

    drag(ref);

    return (
        <div
            ref={ref}
            style={{
                opacity: isDragging ? 0.5 : 1,
                cursor: "grab",
            }}
        >
            {children}
        </div>
    );
};

// Sortable block in canvas
interface SortableBlockProps {
    id: string;
    index: number;
    moveBlock: (dragIndex: number, hoverIndex: number) => void;
    children: React.ReactNode;
}

interface DragItem {
    index: number;
    id: string;
    type: string;
}

export const SortableBlock: React.FC<SortableBlockProps> = ({ id, index, moveBlock, children }) => {
    const ref = useRef<HTMLDivElement>(null);

    const [{ handlerId }, drop] = useDrop<DragItem, void, { handlerId: string | symbol | null }>({
        accept: ItemTypes.BLOCK,
        collect(monitor) {
            return {
                handlerId: monitor.getHandlerId(),
            };
        },
        hover(item: DragItem, monitor) {
            if (!ref.current) {
                return;
            }
            const dragIndex = item.index;
            const hoverIndex = index;

            // Don't replace items with themselves
            if (dragIndex === hoverIndex) {
                return;
            }

            // Determine rectangle on screen
            const hoverBoundingRect = ref.current?.getBoundingClientRect();

            // Get vertical middle
            const hoverMiddleY = (hoverBoundingRect.bottom - hoverBoundingRect.top) / 2;

            // Determine mouse position
            const clientOffset = monitor.getClientOffset();

            // Get pixels to the top
            const hoverClientY = (clientOffset?.y || 0) - hoverBoundingRect.top;

            // Only perform the move when the mouse has crossed half of the items height
            // When dragging downwards, only move when the cursor is below 50%
            // When dragging upwards, only move when the cursor is above 50%
            if (dragIndex < hoverIndex && hoverClientY < hoverMiddleY) {
                return;
            }
            if (dragIndex > hoverIndex && hoverClientY > hoverMiddleY) {
                return;
            }

            // Time to actually perform the action
            moveBlock(dragIndex, hoverIndex);

            // Note: we're mutating the monitor item here!
            // Generally it's better to avoid mutations,
            // but it's good here for the sake of performance
            // to avoid expensive index searches.
            item.index = hoverIndex;
        },
    });

    const [{ isDragging }, drag] = useDrag({
        type: ItemTypes.BLOCK,
        item: () => {
            return { id, index };
        },
        collect: (monitor) => ({
            isDragging: monitor.isDragging(),
        }),
    });

    drag(drop(ref));

    return (
        <div
            ref={ref}
            data-handler-id={handlerId}
            style={{
                opacity: isDragging ? 0.4 : 1,
                cursor: "move",
            }}
        >
            {children}
        </div>
    );
};

// Drop zone for canvas
interface CanvasDropZoneProps {
    onDrop: (item: LibraryItem) => void;
    children: React.ReactNode;
    isEmpty: boolean;
}

export const CanvasDropZone: React.FC<CanvasDropZoneProps> = ({ onDrop, children, isEmpty }) => {
    const ref = useRef<HTMLDivElement>(null);
    const [{ isOver, canDrop, isDirectlyOver }, drop] = useDrop(() => ({
        accept: ItemTypes.LIBRARY_BLOCK,
        drop: (item: LibraryItem, monitor) => {
            // Only handle drop if dropping directly on canvas, not on nested drop zones
            if (monitor.didDrop()) {
                // A nested drop zone already handled this drop
                return;
            }
            onDrop(item);
        },
        collect: (monitor) => ({
            isOver: monitor.isOver(),
            canDrop: monitor.canDrop(),
            isDirectlyOver: monitor.isOver({ shallow: true }),
        }),
    }));

    drop(ref);

    const isActive = isDirectlyOver && canDrop;

    return (
        <div
            ref={ref}
            style={{
                minHeight: isEmpty ? 300 : "auto",
                background: isActive ? "rgba(22, 119, 255, 0.1)" : isEmpty ? "#fafafa" : "transparent",
                border: isActive ? "2px dashed #1677ff" : isEmpty ? "2px dashed #d9d9d9" : "none",
                borderRadius: 8,
                transition: "all 0.2s",
            }}
        >
            {isEmpty && !isActive && (
                <div style={{
                    textAlign: "center",
                    padding: 60,
                    color: "#999"
                }}>
                    Drag blocks here to start building
                </div>
            )}
            {isActive && isEmpty && (
                <div style={{
                    textAlign: "center",
                    padding: 60,
                    color: "#1677ff"
                }}>
                    Drop to add block
                </div>
            )}
            {!isEmpty && children}
        </div>
    );
};

// DnD Provider wrapper
export const DnDProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return (
        <DndProvider backend={HTML5Backend}>
            {children}
        </DndProvider>
    );
};

export default DnDProvider;

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Button, Input, List, Avatar, Typography, Space, theme } from 'antd';
import { RobotOutlined, SendOutlined, CloseOutlined, UserOutlined, ExperimentOutlined } from '@ant-design/icons';
import { motion, AnimatePresence } from 'framer-motion';
import { usePreferencesStore } from '@/store/usePreferencesStore';

const { Text } = Typography;

interface Message {
  id: string;
  sender: 'user' | 'ai';
  text: string;
  time: string;
}

export function FacilityCopilot() {
    const [isOpen, setIsOpen] = useState(false);
    const [input, setInput] = useState('');
    const [messages, setMessages] = useState<Message[]>([
        {
            id: '1',
            sender: 'ai',
            text: 'Hello! I am your Facility AI Copilot. I can analyze telemetry, trigger BMS overrides, or check SCADA alarms. How can I assist you today?',
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
    ]);

    const { themeColor } = usePreferencesStore();
    const { token: antToken } = theme.useToken();
    const isDark = antToken.colorBgContainer === '#141414' || antToken.colorBgBase?.includes('14');
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(() => {
        if (isOpen) {
            scrollToBottom();
        }
    }, [messages, isOpen]);

    const handleSend = () => {
        if (!input.trim()) return;

        const userMsg: Message = {
            id: Date.now().toString(),
            sender: 'user',
            text: input,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };
        setMessages(prev => [...prev, userMsg]);
        setInput('');

        // Mock AI Response
        setTimeout(() => {
            const aiMsg: Message = {
                id: (Date.now() + 1).toString(),
                sender: 'ai',
                text: 'Analyzing facility telemetry... No critical anomalies detected at this moment. Would you like me to generate a summary report?',
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            };
            setMessages(prev => [...prev, aiMsg]);
        }, 1500);
    };

    const glassStyle = {
        background: isDark ? 'rgba(20,20,20,0.85)' : 'rgba(255,255,255,0.85)',
        backdropFilter: 'blur(16px)',
        border: `1px solid ${isDark ? '#333' : '#e0e0e0'}`,
        boxShadow: '0 8px 32px rgba(0, 0, 0, 0.15)',
        borderRadius: 16,
        overflow: 'hidden'
    };

    return (
        <div style={{ position: 'fixed', bottom: 24, right: 24, zIndex: 999, display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 20, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 20, scale: 0.95, transition: { duration: 0.2 } }}
                        style={{
                            ...glassStyle,
                            width: 380,
                            height: 600,
                            marginBottom: 16,
                            display: 'flex',
                            flexDirection: 'column'
                        }}
                    >
                        {/* Header */}
                        <div style={{ padding: '16px 20px', background: themeColor, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <Space>
                                <ExperimentOutlined style={{ color: '#fff', fontSize: 18 }} />
                                <Text strong style={{ color: '#fff', fontSize: 16 }}>Facility AI Copilot</Text>
                            </Space>
                            <Button type="text" icon={<CloseOutlined style={{ color: '#fff' }} />} onClick={() => setIsOpen(false)} />
                        </div>

                        {/* Chat Body */}
                        <div style={{ flex: 1, padding: 16, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 16 }}>
                            {messages.map((msg) => (
                                <div key={msg.id} style={{ display: 'flex', flexDirection: msg.sender === 'user' ? 'row-reverse' : 'row', gap: 12 }}>
                                    <Avatar 
                                        icon={msg.sender === 'user' ? <UserOutlined /> : <RobotOutlined />} 
                                        style={{ backgroundColor: msg.sender === 'user' ? themeColor : (isDark ? '#333' : '#f0f0f0'), color: msg.sender === 'user' ? '#fff' : (isDark ? '#fff' : '#000') }}
                                    />
                                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: msg.sender === 'user' ? 'flex-end' : 'flex-start', maxWidth: '75%' }}>
                                        <div style={{
                                            padding: '10px 14px',
                                            borderRadius: 12,
                                            background: msg.sender === 'user' ? themeColor : (isDark ? '#2a2a2a' : '#f5f5f5'),
                                            color: msg.sender === 'user' ? '#fff' : (isDark ? '#fff' : '#000'),
                                            borderTopRightRadius: msg.sender === 'user' ? 2 : 12,
                                            borderTopLeftRadius: msg.sender === 'ai' ? 2 : 12,
                                            boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
                                        }}>
                                            <Text style={{ color: 'inherit' }}>{msg.text}</Text>
                                        </div>
                                        <Text type="secondary" style={{ fontSize: 11, marginTop: 4 }}>{msg.time}</Text>
                                    </div>
                                </div>
                            ))}
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Input Area */}
                        <div style={{ padding: 16, borderTop: `1px solid ${isDark ? '#333' : '#f0f0f0'}` }}>
                            <Input
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onPressEnter={handleSend}
                                placeholder="Ask Copilot..."
                                variant="filled"
                                suffix={
                                    <Button 
                                        type="primary" 
                                        shape="circle" 
                                        icon={<SendOutlined />} 
                                        size="small" 
                                        onClick={handleSend} 
                                        style={{ background: themeColor, border: 'none' }}
                                    />
                                }
                                style={{ borderRadius: 24, paddingLeft: 16, paddingRight: 8, paddingBottom: 6, paddingTop: 6 }}
                            />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                <Button
                    type="primary"
                    shape="circle"
                    size="large"
                    icon={<RobotOutlined style={{ fontSize: 24 }} />}
                    onClick={() => setIsOpen(!isOpen)}
                    style={{
                        width: 64,
                        height: 64,
                        background: themeColor,
                        border: 'none',
                        boxShadow: `0 8px 24px ${themeColor}80`
                    }}
                />
            </motion.div>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from "react";
import { Card, Tag, Space, Typography, Button, Badge, Progress, Empty, Tooltip, List, Avatar } from "antd";
import { FormOutlined, BarChartOutlined, CheckCircleOutlined, ClockCircleOutlined, RightOutlined, FileTextOutlined, TrophyOutlined } from "@ant-design/icons";
import { motion } from "framer-motion";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
dayjs.extend(relativeTime);

const { Text } = Typography;

interface FormTemplate {
    id: string; name: string; category: string; status: string; fieldCount: number;
}

interface FormSubmission {
    id: string; templateName?: string; templateCategory?: string;
    status: string; totalScore: number; percentage: number; grade?: string;
    submittedAt?: string;
}

const CATEGORY_COLORS: Record<string, string> = {
    kpi: '#f5222d', survey: '#1890ff', assessment: '#52c41a',
    checklist: '#fa8c16', feedback: '#722ed1', audit: '#13c2c2', custom: '#595959',
};

function gradeColor(grade?: string) {
    if (!grade) return '#595959';
    if (grade === 'Excellent') return '#52c41a';
    if (grade === 'Good') return '#1890ff';
    if (grade === 'Satisfactory') return '#faad14';
    return '#ff4d4f';
}

interface FormIntegrationWidgetProps {
    /** Filter templates by category: 'kpi' | 'survey' | 'checklist' | 'audit' | etc. */
    categories?: string[];
    /** Title override */
    title?: string;
    /** Max items to show */
    maxItems?: number;
    /** Animation delay index (for staggered animations) */
    animIndex?: number;
    /** Glass style override */
    style?: React.CSSProperties;
}

const glass = { background: 'rgba(255,255,255,0.65)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.45)', borderRadius: 14 };

/**
 * Reusable Form Builder integration widget for module dashboards.
 * Shows available form templates and recent submissions relevant to the module.
 */
export default function FormIntegrationWidget({
    categories = [],
    title = "Forms & Evaluations",
    maxItems = 3,
    animIndex = 12,
    style,
}: FormIntegrationWidgetProps) {
    const [templates, setTemplates] = useState<FormTemplate[]>([]);
    const [submissions, setSubmissions] = useState<FormSubmission[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const loadData = async () => {
            try {
                const [tplRes, subRes] = await Promise.all([
                    gql<{ formTemplates: FormTemplate[] }>(`
                        query($tid: String!) {
                            formTemplates(tenantId: $tid, status: "published") {
                                id name category status fieldCount
                            }
                        }
                    `, { tid: DEFAULT_TENANT_ID }),
                    gql<{ formSubmissions: FormSubmission[] }>(`
                        query($tid: String!) {
                            formSubmissions(tenantId: $tid) {
                                id templateName templateCategory status totalScore percentage grade submittedAt
                            }
                        }
                    `, { tid: DEFAULT_TENANT_ID }),
                ]);
                let tpls = tplRes.formTemplates || [];
                let subs = subRes.formSubmissions || [];
                // Filter by category if provided
                if (categories.length > 0) {
                    tpls = tpls.filter(t => categories.includes(t.category));
                    subs = subs.filter(s => s.templateCategory && categories.includes(s.templateCategory));
                }
                setTemplates(tpls.slice(0, maxItems));
                setSubmissions(subs.slice(0, maxItems));
            } catch (e) {
                console.error('FormIntegrationWidget error:', e);
            }
            setLoading(false);
        };
        loadData();
    }, [categories.join(','), maxItems]);

    const totalForms = templates.length;
    const totalSubs = submissions.length;
    const pendingReview = submissions.filter(s => s.status === 'submitted').length;
    const approved = submissions.filter(s => s.status === 'approved').length;

    if (loading) return null; // Don't show skeleton to avoid layout shift

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: animIndex * 0.06, duration: 0.4 }}
        >
            <Card
                title={<><FormOutlined style={{ color: '#722ed1' }} /> {title}</>}
                size="small"
                style={{ ...glass, ...style }}
                extra={
                    <Button type="link" size="small" href="/admin/forms/templates" style={{ fontSize: 11 }}>
                        View All <RightOutlined />
                    </Button>
                }
            >
                {/* Quick Stats Row */}
                <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'wrap' }}>
                    <Tag icon={<FileTextOutlined />} color="purple">{totalForms} forms</Tag>
                    <Tag icon={<ClockCircleOutlined />} color="orange">{pendingReview} pending</Tag>
                    <Tag icon={<CheckCircleOutlined />} color="green">{approved} approved</Tag>
                </div>

                {templates.length === 0 && submissions.length === 0 ? (
                    <Empty description="No forms available" image={Empty.PRESENTED_IMAGE_SIMPLE} style={{ margin: '8px 0' }} />
                ) : (
                    <Space direction="vertical" size={8} style={{ width: '100%' }}>
                        {/* Active Templates */}
                        {templates.length > 0 && (
                            <div>
                                <Text type="secondary" style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.5 }}>Available Forms</Text>
                                {templates.map((t, i) => (
                                    <motion.div
                                        key={t.id}
                                        initial={{ opacity: 0, x: -10 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        transition={{ delay: 0.3 + i * 0.08 }}
                                        style={{
                                            display: 'flex', alignItems: 'center', gap: 8,
                                            padding: '6px 0', borderBottom: '1px solid rgba(0,0,0,0.04)',
                                        }}
                                    >
                                        <Avatar size={28} style={{ backgroundColor: CATEGORY_COLORS[t.category] || '#595959', fontSize: 11 }}>
                                            {t.category === 'kpi' ? <BarChartOutlined /> : <FormOutlined />}
                                        </Avatar>
                                        <div style={{ flex: 1, minWidth: 0 }}>
                                            <Text strong style={{ fontSize: 12, display: 'block' }} ellipsis>{t.name}</Text>
                                            <Space size={4}>
                                                <Tag color={CATEGORY_COLORS[t.category]} style={{ fontSize: 9, margin: 0, lineHeight: '16px' }}>{t.category}</Tag>
                                                <Text type="secondary" style={{ fontSize: 10 }}>{t.fieldCount} fields</Text>
                                            </Space>
                                        </div>
                                        <Button type="link" size="small" href={`/admin/forms/submissions`} style={{ fontSize: 10 }}>
                                            Fill →
                                        </Button>
                                    </motion.div>
                                ))}
                            </div>
                        )}

                        {/* Recent Submissions */}
                        {submissions.length > 0 && (
                            <div style={{ marginTop: 8 }}>
                                <Text type="secondary" style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.5 }}>Recent Submissions</Text>
                                {submissions.map((s, i) => (
                                    <motion.div
                                        key={s.id}
                                        initial={{ opacity: 0, x: -10 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        transition={{ delay: 0.5 + i * 0.08 }}
                                        style={{
                                            display: 'flex', alignItems: 'center', gap: 8,
                                            padding: '6px 0', borderBottom: '1px solid rgba(0,0,0,0.04)',
                                        }}
                                    >
                                        <div style={{ flex: 1, minWidth: 0 }}>
                                            <Text style={{ fontSize: 12 }} ellipsis>{s.templateName || 'Form Response'}</Text>
                                            <div>
                                                <Tag color={s.status === 'approved' ? 'green' : s.status === 'submitted' ? 'blue' : 'default'} style={{ fontSize: 9, margin: 0 }}>
                                                    {s.status}
                                                </Tag>
                                                {s.submittedAt && <Text type="secondary" style={{ fontSize: 10, marginLeft: 4 }}>{dayjs(s.submittedAt).fromNow()}</Text>}
                                            </div>
                                        </div>
                                        {s.percentage > 0 ? (
                                            <Tooltip title={`${s.totalScore.toFixed(1)} — ${s.grade || ''}`}>
                                                <Progress
                                                    type="circle"
                                                    size={32}
                                                    percent={s.percentage}
                                                    strokeColor={gradeColor(s.grade)}
                                                    format={() => <span style={{ fontSize: 9 }}>{Math.round(s.percentage)}%</span>}
                                                />
                                            </Tooltip>
                                        ) : (
                                            <Badge status="processing" text={<Text type="secondary" style={{ fontSize: 10 }}>Pending</Text>} />
                                        )}
                                    </motion.div>
                                ))}
                            </div>
                        )}
                    </Space>
                )}
            </Card>
        </motion.div>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { Select, Typography, Tag, Space } from "antd";
import { BankOutlined, UserOutlined } from "@ant-design/icons";
import { gql, DEFAULT_TENANT_ID } from "@/lib/graphql";

const { Text } = Typography;

interface CrmAccount {
    id: string;
    name: string;
    type?: string;
    industry?: string;
    phone?: string;
    email?: string;
    status?: string;
}

interface CrmContact {
    id: string;
    individualFirstName?: string;
    individualLastName?: string;
    email?: string;
    phone?: string;
    accountId?: string;
    accountName?: string;
    title?: string;
    department?: string;
    status?: string;
}

interface CrmAccountPickerProps {
    value?: string;
    onChange?: (value: string | undefined) => void;
    onAccountSelect?: (account: CrmAccount | null) => void;
    placeholder?: string;
    style?: React.CSSProperties;
    disabled?: boolean;
    allowClear?: boolean;
    size?: "small" | "middle" | "large";
}

interface CrmContactPickerProps {
    value?: string;
    onChange?: (value: string | undefined) => void;
    onContactSelect?: (contact: CrmContact | null) => void;
    accountId?: string;
    placeholder?: string;
    style?: React.CSSProperties;
    disabled?: boolean;
    allowClear?: boolean;
    size?: "small" | "middle" | "large";
}

const TYPE_COLORS: Record<string, string> = {
    customer: "green",
    partner: "purple",
    vendor: "orange",
    prospect: "blue",
};

export function CrmAccountPicker({
    value,
    onChange,
    onAccountSelect,
    placeholder = "Search CRM accounts...",
    style,
    disabled = false,
    allowClear = true,
    size = "middle",
}: CrmAccountPickerProps) {
    const [accounts, setAccounts] = useState<CrmAccount[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        loadAccounts();
    }, []);

    const loadAccounts = async () => {
        setLoading(true);
        try {
            const data = await gql(
                `query($tenantId: String!) {
                    accounts(tenantId: $tenantId) {
                        id name type industry phone email status
                    }
                }`,
                { tenantId: DEFAULT_TENANT_ID }
            );
            setAccounts(data.accounts || []);
        } catch (err) {
            console.error("Failed to load CRM accounts:", err);
        } finally {
            setLoading(false);
        }
    };

    const options = useMemo(
        () =>
            accounts
                .filter((a) => a.status === "active")
                .map((account) => ({
                    value: account.id,
                    label: (
                        <div className="flex items-center justify-between w-full">
                            <Space size={4}>
                                <BankOutlined style={{ color: "#1677ff" }} />
                                <Text strong className="text-sm">
                                    {account.name}
                                </Text>
                            </Space>
                            <Space size={4}>
                                {account.type && (
                                    <Tag
                                        color={TYPE_COLORS[account.type] || "default"}
                                        className="rounded-full text-xs m-0"
                                    >
                                        {account.type}
                                    </Tag>
                                )}
                                {account.industry && (
                                    <Text type="secondary" className="text-xs">
                                        {account.industry}
                                    </Text>
                                )}
                            </Space>
                        </div>
                    ),
                    searchText: `${account.name} ${account.type || ""} ${account.industry || ""}`.toLowerCase(),
                    account,
                })),
        [accounts]
    );

    const handleChange = (selectedId: string | undefined) => {
        onChange?.(selectedId);
        if (selectedId) {
            const found = accounts.find((a) => a.id === selectedId) || null;
            onAccountSelect?.(found);
        } else {
            onAccountSelect?.(null);
        }
    };

    return (
        <Select
            showSearch
            value={value}
            onChange={handleChange}
            placeholder={placeholder}
            loading={loading}
            disabled={disabled}
            allowClear={allowClear}
            size={size}
            style={{ width: "100%", ...style }}
            suffixIcon={<BankOutlined style={{ color: "#13c2c2" }} />}
            filterOption={(input, option) =>
                (option as any)?.searchText?.includes(input.toLowerCase()) ?? false
            }
            options={options}
            optionLabelProp="label"
            popupMatchSelectWidth={false}
            notFoundContent={loading ? "Loading accounts..." : "No accounts found"}
        />
    );
}

export function CrmContactPicker({
    value,
    onChange,
    onContactSelect,
    accountId,
    placeholder = "Search CRM contacts...",
