                }
                
                .cms-inner-sider .ant-menu-item,
                .cms-inner-sider .ant-menu-submenu-title {
                    padding-inline: 12px !important;
                }
                
                /* Fix segmented control to fit within sidebar */
                .cms-inner-sider .ant-segmented {
