                    style={{
                        background: `linear-gradient(135deg, ${themePalette.primary} 0%, ${themePalette.secondary} 50%, ${themePalette.accent} 100%)`,
                        borderRadius: 16,
                        padding: "20px 20px 16px",
                        marginBottom: 24,
                        position: "relative",
                        overflow: "hidden",
