                                    background: themePalette[key],
                                    border: "2px solid rgba(255,255,255,0.4)",
                                    boxShadow: "0 2px 4px rgba(0,0,0,0.2)",
                                }} />
                            </Tooltip>
                        ))}
                    </div>
