export const MagicTweet = ({
  tweet,
  className,
  ...props
}: {
  tweet: Tweet
  className?: string
}) => {
  const enrichedTweet = enrichTweet(tweet)
  return (
    <div
      className={cn(
        "relative flex h-fit w-full max-w-lg flex-col gap-4 overflow-hidden rounded-xl border p-5",
        className
      )}
      {...props}
    >
      <TweetHeader tweet={enrichedTweet} />
      <TweetBody tweet={enrichedTweet} />
      <TweetMedia tweet={enrichedTweet} />
    </div>
  )
}

/**
 * TweetCard (Server Side Only)
 */
export const TweetCard = async ({
  id,
  components,
  fallback = <TweetSkeleton />,
  onError,
  ...props
}: TweetProps & {
  className?: string
}) => {
  const tweet = id
    ? await getTweet(id).catch((err) => {
        if (onError) {
          onError(err)
        } else {
          console.error(err)
        }
      })
    : undefined

  if (!tweet) {
    const NotFound = components?.TweetNotFound || TweetNotFound
    return <NotFound {...props} />
  }

  return (
    <Suspense fallback={fallback}>
      <MagicTweet tweet={tweet} {...props} />
    </Suspense>
  )
}

"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import { motion, MotionProps, useInView } from "motion/react"

import { cn } from "@/lib/utils"

interface TypingAnimationProps extends MotionProps {
  children?: string
  words?: string[]
  className?: string
  duration?: number
  typeSpeed?: number
  deleteSpeed?: number
  delay?: number
  pauseDelay?: number
  loop?: boolean
  as?: React.ElementType
  startOnView?: boolean
  showCursor?: boolean
  blinkCursor?: boolean
  cursorStyle?: "line" | "block" | "underscore"
}

export function TypingAnimation({
  children,
  words,
  className,
  duration = 100,
  typeSpeed,
  deleteSpeed,
  delay = 0,
  pauseDelay = 1000,
  loop = false,
  as: Component = "span",
  startOnView = true,
  showCursor = true,
  blinkCursor = true,
  cursorStyle = "line",
  ...props
}: TypingAnimationProps) {
  const MotionComponent = motion.create(Component, {
    forwardMotionProps: true,
  })

  const [displayedText, setDisplayedText] = useState<string>("")
  const [currentWordIndex, setCurrentWordIndex] = useState(0)
  const [currentCharIndex, setCurrentCharIndex] = useState(0)
  const [phase, setPhase] = useState<"typing" | "pause" | "deleting">("typing")
  const elementRef = useRef<HTMLElement | null>(null)
  const isInView = useInView(elementRef as React.RefObject<Element>, {
    amount: 0.3,
    once: true,
  })

  const wordsToAnimate = useMemo(
    () => words || (children ? [children] : []),
    [words, children]
  )
  const hasMultipleWords = wordsToAnimate.length > 1

  const typingSpeed = typeSpeed || duration
  const deletingSpeed = deleteSpeed || typingSpeed / 2

  const shouldStart = startOnView ? isInView : true

  useEffect(() => {
    if (!shouldStart || wordsToAnimate.length === 0) return

    const timeoutDelay =
      delay > 0 && displayedText === ""
        ? delay
        : phase === "typing"
          ? typingSpeed
          : phase === "deleting"
            ? deletingSpeed
            : pauseDelay

    const timeout = setTimeout(() => {
      const currentWord = wordsToAnimate[currentWordIndex] || ""
      const graphemes = Array.from(currentWord)

      switch (phase) {
        case "typing":
          if (currentCharIndex < graphemes.length) {
            setDisplayedText(graphemes.slice(0, currentCharIndex + 1).join(""))
            setCurrentCharIndex(currentCharIndex + 1)
          } else {
            if (hasMultipleWords || loop) {
              const isLastWord = currentWordIndex === wordsToAnimate.length - 1
              if (!isLastWord || loop) {
                setPhase("pause")
              }
            }
          }
          break

        case "pause":
          setPhase("deleting")
          break

        case "deleting":
          if (currentCharIndex > 0) {
            setDisplayedText(graphemes.slice(0, currentCharIndex - 1).join(""))
            setCurrentCharIndex(currentCharIndex - 1)
          } else {
            const nextIndex = (currentWordIndex + 1) % wordsToAnimate.length
            setCurrentWordIndex(nextIndex)
            setPhase("typing")
          }
          break
      }
    }, timeoutDelay)

    return () => clearTimeout(timeout)
  }, [
    shouldStart,
    phase,
    currentCharIndex,
    currentWordIndex,
    displayedText,
    wordsToAnimate,
    hasMultipleWords,
    loop,
    typingSpeed,
    deletingSpeed,
    pauseDelay,
    delay,
  ])

  const currentWordGraphemes = Array.from(
    wordsToAnimate[currentWordIndex] || ""
  )
  const isComplete =
    !loop &&
    currentWordIndex === wordsToAnimate.length - 1 &&
    currentCharIndex >= currentWordGraphemes.length &&
    phase !== "deleting"

  const shouldShowCursor =
    showCursor &&
    !isComplete &&
    (hasMultipleWords || loop || currentCharIndex < currentWordGraphemes.length)

  const getCursorChar = () => {
    switch (cursorStyle) {
      case "block":
        return "▌"
      case "underscore":
        return "_"
      case "line":
      default:
        return "|"
    }
  }

  return (
    <MotionComponent
      ref={elementRef}
      className={cn("leading-[5rem] tracking-[-0.02em]", className)}
      {...props}
    >
      {displayedText}
      {shouldShowCursor && (
        <span
          className={cn("inline-block", blinkCursor && "animate-blink-cursor")}
        >
          {getCursorChar()}
        </span>
      )}
    </MotionComponent>
  )
}

"use client"

import React, { ElementType, ReactNode, useEffect, useState } from "react"

import { cn } from "@/lib/utils"

export interface VideoTextProps {
  /**
   * The video source URL
   */
  src: string
  /**
   * Additional className for the container
   */
  className?: string
  /**
   * Whether to autoplay the video
   */
  autoPlay?: boolean
  /**
   * Whether to mute the video
   */
  muted?: boolean
  /**
   * Whether to loop the video
   */
  loop?: boolean
  /**
   * Whether to preload the video
   */
  preload?: "auto" | "metadata" | "none"
  /**
   * The content to display (will have the video "inside" it)
   */
  children: ReactNode
  /**
   * Font size for the text mask (in viewport width units)
   * @default 10
   */
  fontSize?: string | number
  /**
   * Font weight for the text mask
   * @default "bold"
   */
  fontWeight?: string | number
  /**
   * Text anchor for the text mask
   * @default "middle"
   */
  textAnchor?: string
  /**
   * Dominant baseline for the text mask
   * @default "middle"
   */
  dominantBaseline?: string
  /**
   * Font family for the text mask
   * @default "sans-serif"
   */
  fontFamily?: string
  /**
   * The element type to render for the text
   * @default "div"
   */
  as?: ElementType
}

export function VideoText({
  src,
  children,
  className = "",
  autoPlay = true,
  muted = true,
  loop = true,
  preload = "auto",
  fontSize = 20,
  fontWeight = "bold",
  textAnchor = "middle",
  dominantBaseline = "middle",
  fontFamily = "sans-serif",
  as: Component = "div",
}: VideoTextProps) {
  const [svgMask, setSvgMask] = useState("")
  const content = React.Children.toArray(children).join("")

  useEffect(() => {
    const updateSvgMask = () => {
      const responsiveFontSize =
        typeof fontSize === "number" ? `${fontSize}vw` : fontSize
      const newSvgMask = `<svg xmlns='http://www.w3.org/2000/svg' width='100%' height='100%'><text x='50%' y='50%' font-size='${responsiveFontSize}' font-weight='${fontWeight}' text-anchor='${textAnchor}' dominant-baseline='${dominantBaseline}' font-family='${fontFamily}'>${content}</text></svg>`
      setSvgMask(newSvgMask)
    }

    updateSvgMask()
    window.addEventListener("resize", updateSvgMask)
    return () => window.removeEventListener("resize", updateSvgMask)
  }, [content, fontSize, fontWeight, textAnchor, dominantBaseline, fontFamily])

  const dataUrlMask = `url("data:image/svg+xml,${encodeURIComponent(svgMask)}")`

  // Cast Component to any to avoid TypeScript error about children prop
  const Comp = Component as any

  return (
    <Comp className={cn(`relative size-full`, className)}>
      {/* Create a container that masks the video to only show within text */}
      <div
        className="absolute inset-0 flex items-center justify-center"
        style={{
          maskImage: dataUrlMask,
          WebkitMaskImage: dataUrlMask,
          maskSize: "contain",
          WebkitMaskSize: "contain",
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
          maskPosition: "center",
          WebkitMaskPosition: "center",
        }}
      >
        <video
          className="h-full w-full object-cover"
          autoPlay={autoPlay}
          muted={muted}
          loop={loop}
          preload={preload}
          playsInline
        >
          <source src={src} />
          Your browser does not support the video tag.
        </video>
      </div>

      {/* Add a backup text element for SEO/accessibility */}
      <span className="sr-only">{content}</span>
    </Comp>
  )
}

"use client"

import React, { HTMLAttributes, useCallback, useMemo } from "react"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"

interface WarpBackgroundProps extends HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode
  perspective?: number
  beamsPerSide?: number
  beamSize?: number
  beamDelayMax?: number
  beamDelayMin?: number
  beamDuration?: number
  gridColor?: string
}

const Beam = ({
  width,
  x,
  delay,
  duration,
}: {
  width: string | number
  x: string | number
  delay: number
  duration: number
}) => {
  const hue = Math.floor(Math.random() * 360)
  const ar = Math.floor(Math.random() * 10) + 1

  return (
    <motion.div
      style={
        {
          "--x": `${x}`,
          "--width": `${width}`,
          "--aspect-ratio": `${ar}`,
          "--background": `linear-gradient(hsl(${hue} 80% 60%), transparent)`,
        } as React.CSSProperties
      }
      className={`absolute top-0 left-[var(--x)] [aspect-ratio:1/var(--aspect-ratio)] [width:var(--width)] [background:var(--background)]`}
      initial={{ y: "100cqmax", x: "-50%" }}
      animate={{ y: "-100%", x: "-50%" }}
      transition={{
        duration,
        delay,
        repeat: Infinity,
        ease: "linear",
      }}
    />
  )
}

export const WarpBackground: React.FC<WarpBackgroundProps> = ({
  children,
  perspective = 100,
  className,
  beamsPerSide = 3,
  beamSize = 5,
  beamDelayMax = 3,
  beamDelayMin = 0,
  beamDuration = 3,
  gridColor = "var(--border)",
  ...props
}) => {
  const generateBeams = useCallback(() => {
    const beams = []
    const cellsPerSide = Math.floor(100 / beamSize)
    const step = cellsPerSide / beamsPerSide

    for (let i = 0; i < beamsPerSide; i++) {
      const x = Math.floor(i * step)
      const delay = Math.random() * (beamDelayMax - beamDelayMin) + beamDelayMin
      beams.push({ x, delay })
    }
    return beams
  }, [beamsPerSide, beamSize, beamDelayMax, beamDelayMin])

  const topBeams = useMemo(() => generateBeams(), [generateBeams])
  const rightBeams = useMemo(() => generateBeams(), [generateBeams])
  const bottomBeams = useMemo(() => generateBeams(), [generateBeams])
  const leftBeams = useMemo(() => generateBeams(), [generateBeams])

  return (
    <div className={cn("relative rounded border p-20", className)} {...props}>
      <div
        style={
          {
            "--perspective": `${perspective}px`,
            "--grid-color": gridColor,
            "--beam-size": `${beamSize}%`,
          } as React.CSSProperties
        }
        className={
          "[container-type:size] pointer-events-none absolute top-0 left-0 size-full overflow-hidden [clipPath:inset(0)] [perspective:var(--perspective)] [transform-style:preserve-3d]"
        }
      >
        {/* top side */}
        <div className="[container-type:inline-size] absolute z-20 [height:100cqmax] [width:100cqi] [transform-origin:50%_0%] [transform:rotateX(-90deg)] [background-size:var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,_var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] [transform-style:preserve-3d]">
          {topBeams.map((beam, index) => (
            <Beam
              key={`top-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
        {/* bottom side */}
        <div className="[container-type:inline-size] absolute top-full [height:100cqmax] [width:100cqi] [transform-origin:50%_0%] [transform:rotateX(-90deg)] [background-size:var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,_var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] [transform-style:preserve-3d]">
          {bottomBeams.map((beam, index) => (
            <Beam
              key={`bottom-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
        {/* left side */}
        <div className="[container-type:inline-size] absolute top-0 left-0 [height:100cqmax] [width:100cqh] [transform-origin:0%_0%] [transform:rotate(90deg)_rotateX(-90deg)] [background-size:var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,_var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] [transform-style:preserve-3d]">
          {leftBeams.map((beam, index) => (
            <Beam
              key={`left-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
        {/* right side */}
        <div className="[container-type:inline-size] absolute top-0 right-0 [height:100cqmax] [width:100cqh] [transform-origin:100%_0%] [transform:rotate(-90deg)_rotateX(-90deg)] [background-size:var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,_var(--grid-color)_0_1px,_transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] [transform-style:preserve-3d]">
          {rightBeams.map((beam, index) => (
            <Beam
              key={`right-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
      </div>
      <div className="relative">{children}</div>
    </div>
  )
}

"use client";

import React from "react";
import { Spin, Empty, Typography, Button, Table, Tabs } from "antd";
import {
    FilePdfOutlined,
    FileWordOutlined,
    FileExcelOutlined,
    FilePptOutlined,
    FileOutlined,
    FileUnknownOutlined,
    DownloadOutlined
} from "@ant-design/icons";
import DocViewer, { DocViewerRenderers, IDocument } from "@cyntler/react-doc-viewer";

const { Text } = Typography;

interface DocumentPreviewProps {
    url: string;
    filename: string;
    mimeType?: string;
}

// Custom Renderer for DOCX using docx-preview
const DOCXRenderer = ({ mainState: { currentDocument } }: any) => {
    const containerRef = React.useRef<HTMLDivElement>(null);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);

    React.useEffect(() => {
        if (!currentDocument || !currentDocument.uri) return;

        const loadDocx = async () => {
            setLoading(true);
            setError(null);
            try {
                // Check if uri is string
                if (typeof currentDocument.uri !== 'string') {
                    throw new Error("Invalid document URI");
                }

                const response = await fetch(currentDocument.uri);
                if (!response.ok) throw new Error(`Failed to fetch document: ${response.statusText}`);

                const blob = await response.blob();

                // Clear previous content
                if (containerRef.current) {
                    containerRef.current.innerHTML = '';
                }

                // Dynamic import to ensure client-side execution
                // @ts-ignore
                const docx = await import('docx-preview');

                if (containerRef.current) {
                    await docx.renderAsync(blob, containerRef.current, containerRef.current, {
                        inWrapper: true,
                        ignoreWidth: false,
                        ignoreHeight: false
                    });
                }

            } catch (err) {
                console.error("docx-preview error:", err);
                setError((err as Error).message);
            } finally {
                setLoading(false);
            }
        };

        loadDocx();
    }, [currentDocument]);

    if (loading) return <div className="p-10 text-center"><Spin tip="Rendering Word Document..." /></div>;

    if (error) return (
        <div className="p-10 text-center flex flex-col items-center justify-center h-full">
            <FileUnknownOutlined className="text-4xl text-red-400 mb-4" />
            <Text type="danger">Failed to render document</Text>
            <Text type="secondary" className="text-xs mt-2">{error}</Text>
        </div>
    );

    return (
        <div className="w-full h-full bg-[#f3f4f6] dark:bg-[#1f2937] overflow-y-auto flex flex-col items-center py-8">
            <div
                ref={containerRef}
                className="w-full flex justify-center"
            />
            <style dangerouslySetInnerHTML={{
                __html: `
                /* Make the wrapper transparent so it blends with our React container */
                .docx-wrapper {
                    padding: 0 24px 24px 24px !important;
                    background: transparent !important;
                    width: 100% !important;
                    display: flex !important;
                    flex-direction: column !important;
                    align-items: center !important;
                }
                
                /* Page Styling - FORCE WHITE BACKGROUND and A4 shape */
                .docx-wrapper section.docx,
                .docx-wrapper .docx {
                    background-color: #ffffff !important;
                    background-image: none !important;
                    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05) !important;
                    margin: 0 auto 24px auto !important;
                    padding: 60px 72px !important; /* Better margins for reading */
                    min-height: 1056px !important; /* Approx letter height */
                    width: 100% !important;
                    display: block !important;
                    border-radius: 4px !important;
                    color: #1f2937 !important; /* Dark gray for text readability */
                }

                /* Ensure dark text on the white paper regardless of dark mode */
                .docx-wrapper p, .docx-wrapper span, .docx-wrapper div, .docx-wrapper h1, .docx-wrapper h2, .docx-wrapper h3, .docx-wrapper h4, .docx-wrapper h5, .docx-wrapper h6 {
                    color: #1f2937 !important;
                }

                /* Override ANY inline background colors injected by docx-preview on internal elements */
                /* CRITICAL: Must target descendants of section.docx, otherwise the page itself becomes transparent */
                .docx-wrapper section.docx *,
                .docx-wrapper .docx * {
                    background-color: transparent !important;
                    background: transparent !important;
                    opacity: 1 !important; /* Fix potential opacity inheritance bugs */
                }

                /* Basic table styling for docx */
                .docx-wrapper table {
                    border-collapse: collapse !important;
                    width: 100% !important;
                    background-color: transparent !important;
                    background: transparent !important;
                }
                .docx-wrapper td, .docx-wrapper th {
                    border: 1px solid #d1d5db !important;
                    padding: 4px 8px !important;
                    background-color: transparent !important;
                    background: transparent !important;
                }
            `}} />
        </div>
    );
};

// Custom Renderer for XLSX using XLSX + Ant Design Table (matches DataPreview style)
const XLSXRenderer = ({ mainState: { currentDocument } }: any) => {
    const [columns, setColumns] = React.useState<any[]>([]);
    const [rows, setRows] = React.useState<any[]>([]);
    const [sheetNames, setSheetNames] = React.useState<string[]>([]);
    const [activeSheet, setActiveSheet] = React.useState(0);
    const [workbookRef, setWorkbookRef] = React.useState<any>(null);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);

    const parseSheet = React.useCallback((workbook: any, sheetIndex: number) => {
        const XLSX = require('xlsx');
        const sheet = workbook.Sheets[workbook.SheetNames[sheetIndex]];
        const jsonData: any[][] = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null });

        if (jsonData.length === 0) {
            setColumns([]);
            setRows([]);
            return;
        }

        // First row as headers
        const headers = (jsonData[0] || []).map((h: any, i: number) => ({
            title: (
                <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                    <span style={{ fontSize: 12, fontWeight: 600 }}>{h != null ? String(h) : `Col ${i + 1}`}</span>
                </div>
            ),
            dataIndex: `col_${i}`,
            key: `col_${i}`,
            ellipsis: true,
            width: Math.max(150, String(h || '').length * 10), // Boosted to 150 minWidth
            render: (val: any) => {
                if (val === null || val === undefined || val === '') return <span style={{ color: "#bfbfbf", fontStyle: "italic" }}>—</span>;
                if (typeof val === 'number') return <span style={{ fontSize: 13, fontFamily: "'Inter', monospace", color: '#1d4ed8' }}>{val}</span>;
                return <span style={{ fontSize: 13, fontFamily: "'Inter', sans-serif" }}>{String(val)}</span>;
            },
        }));

        const dataRows = jsonData.slice(1).map((row: any[], rowIdx: number) => {
            const obj: any = { _key: rowIdx };
            headers.forEach((_: any, colIdx: number) => {
                obj[`col_${colIdx}`] = row[colIdx] ?? null;
            });
            return obj;
        });

        setColumns(headers);
        setRows(dataRows);
    }, []);

    React.useEffect(() => {
        if (!currentDocument || !currentDocument.uri) return;

        const loadXlsx = async () => {
            setLoading(true);
            setError(null);
            try {
                const XLSX = await import("xlsx");

                if (typeof currentDocument.uri !== 'string') {
                    throw new Error("Invalid document URI");
                }

                const response = await fetch(currentDocument.uri);
                if (!response.ok) throw new Error(`Failed to fetch spreadsheet: ${response.statusText}`);

                const arrayBuffer = await response.arrayBuffer();
                const workbook = XLSX.read(arrayBuffer, { type: 'array' });

                setWorkbookRef(workbook);
                setSheetNames(workbook.SheetNames);
                setActiveSheet(0);
                parseSheet(workbook, 0);
            } catch (err) {
                console.error("XLSX error:", err);
                setError((err as Error).message);
            } finally {
                setLoading(false);
            }
        };

        loadXlsx();
    }, [currentDocument]);

    const handleSheetChange = (index: number) => {
        if (workbookRef) {
            setActiveSheet(index);
            parseSheet(workbookRef, index);
        }
    };

    const tableContainerRef = React.useRef<HTMLDivElement>(null);
    const [tableScrollHeight, setTableScrollHeight] = React.useState<number>(400);

    React.useEffect(() => {
        if (!tableContainerRef.current) return;

        const observer = new ResizeObserver((entries) => {
            for (const entry of entries) {
                // Determine exact pixel height for the scrollable body by subtracting just the Header margin (~40px)
                const newHeight = entry.contentRect.height - 40;
                setTableScrollHeight(Math.max(newHeight, 100)); // Minimum 100px so it never completely collapses
            }
        });

        observer.observe(tableContainerRef.current);
        return () => observer.disconnect();
    }, [rows]); // Re-evaluate when active dataset renders

    if (loading) return <div className="p-10 text-center"><Spin tip="Rendering Spreadsheet..." /></div>;

    if (error) return (
        <div className="p-10 text-center flex flex-col items-center justify-center h-full">
            <FileUnknownOutlined className="text-4xl text-red-400 mb-4" />
            <Text type="danger">Failed to render spreadsheet</Text>
            <Text type="secondary" className="text-xs mt-2">{error}</Text>
        </div>
    );

    return (
        <div className="w-full h-full flex flex-col bg-white">
            {/* Header with stats and sheet tabs */}
            <div style={{ padding: '8px 16px', borderBottom: '1px solid #f0f0f0', display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8, flexShrink: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                    <span style={{ fontSize: 12, color: '#6b7280' }}>Rows: <strong>{rows.length}</strong></span>
                    <span style={{ fontSize: 12, color: '#6b7280' }}>Cols: <strong>{columns.length}</strong></span>
                </div>

                {sheetNames.length > 1 && (
                    <Tabs
                        size="small"
                        activeKey={activeSheet.toString()}
                        onChange={(key) => handleSheetChange(Number(key))}
                        items={sheetNames.map((name, idx) => ({
                            key: idx.toString(),
                            label: name
                        }))}
                        style={{ margin: 0 }}
                        className="document-preview-tabs"
                    />
                )}
            </div>

            {/* Scrollable Table Area handled natively by Ant Table */}
            <div ref={tableContainerRef} className="absolute-table" style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
                <Table
                    columns={columns}
                    dataSource={rows}
                    rowKey="_key"
                    size="small"
                    pagination={false}
                    bordered
                    scroll={{ x: 'max-content', y: tableScrollHeight }}
                />
            </div>
        </div>
    );
};

export function isDocumentPreviewable(filename?: string, mimeType?: string): boolean {
    if (!filename || typeof filename !== 'string') return false;
    const parts = filename.toLowerCase().split(".");
    const ext = parts.length > 1 ? parts.pop() : "";

    return ["pdf", "docx", "xlsx", "txt", "csv", "png", "jpg", "jpeg", "gif"].includes(ext || "");
}

export function getDocumentIcon(filename: string, mimeType?: string): React.ReactNode {
    if (!filename) return <FileOutlined style={{ fontSize: 48, color: "#8c8c8c" }} />;
    const parts = filename.toLowerCase().split(".");
    const ext = parts.length > 1 ? parts.pop() : "";

    if (ext === "pdf" || mimeType === "application/pdf") return <FilePdfOutlined style={{ fontSize: 48, color: "#ff4d4f" }} />;
    if (ext === "docx" || mimeType?.includes("word") || mimeType?.includes("docx")) return <FileWordOutlined style={{ fontSize: 48, color: "#1890ff" }} />;
    if (ext === "xlsx" || mimeType?.includes("sheet") || mimeType?.includes("excel")) return <FileExcelOutlined style={{ fontSize: 48, color: "#52c41a" }} />;
    if (["ppt", "pptx"].includes(ext || "")) return <FilePptOutlined style={{ fontSize: 48, color: "#fa8c16" }} />;
    return <FileOutlined style={{ fontSize: 48, color: "#8c8c8c" }} />;
}

export default function DocumentPreview({ url, filename, mimeType }: DocumentPreviewProps) {
    // Diagnostic logging
    React.useEffect(() => {
        console.log('[DocumentPreview] Rendering:', { hasUrl: !!url, filename, mimeType });
    }, [url, filename, mimeType]);

    if (!url || !filename) {
        return (
            <div className="flex flex-col items-center justify-center p-12 bg-gray-50 rounded-lg border border-dashed border-gray-300">
                <FileUnknownOutlined style={{ fontSize: 48, color: '#bfbfbf', marginBottom: 16 }} />
                <Text type="secondary">{!url ? "No preview URL available" : "Missing filename"}</Text>
            </div>
        );
    }

    if (typeof url !== 'string' || typeof filename !== 'string') {
        console.error('[DocumentPreview] Invalid props:', { url, filename, mimeType });
        return (
            <div className="flex flex-col items-center justify-center p-12 bg-gray-50 rounded-lg border border-dashed border-red-300">
                <FileUnknownOutlined style={{ fontSize: 48, color: '#ff4d4f', marginBottom: 16 }} />
                <Text type="danger">Invalid file data for preview</Text>
            </div>
        );
    }

    const fileExtension = filename.split('.').pop()?.toLowerCase() || "";

    // Use manual renderers for DOCX and XLSX to avoid DocViewer crashes
    if (fileExtension === 'docx') {
        // Construct a mock "mainState" to reuse the renderer logic or just refactor the renderer to take props
        // To be safe and clean, we'll instantiate the renderer component directly with the document object
        return (
            <div style={{ height: '100%', border: "1px solid #f0f0f0", borderRadius: 8, overflow: "hidden", background: "#fff" }}>
                <DOCXRenderer mainState={{ currentDocument: { uri: url } }} />
            </div>
        );
    }

    if (fileExtension === 'xlsx') {
        return (
            <div style={{ height: '100%', border: "1px solid #f0f0f0", borderRadius: 8, overflow: "hidden", background: "#fff" }}>
                <XLSXRenderer mainState={{ currentDocument: { uri: url } }} />
            </div>
        );
    }

    // For other types, use DocViewer as fallback (e.g., pdf, png, etc.)
    const docs: IDocument[] = [
        {
            uri: url,
            fileName: filename,
            fileType: fileExtension
        }
    ];

    console.log('[DocumentPreview] Docs config (Fallback):', docs);

    return (
        <div style={{ height: '100%', border: "1px solid #f0f0f0", borderRadius: 8, overflow: "hidden", background: "#fff" }}>
            <DocViewer
                documents={docs}
                pluginRenderers={DocViewerRenderers}
                theme={{
                    primary: "#722ed1",
                    secondary: "#ffffff",
                    tertiary: "#f5f5f5",
                    textPrimary: "#000000",
                    textSecondary: "#8c8c8c",
                    textTertiary: "#fffff",
                    disableThemeScrollbar: false,
                }}
                config={{
                    header: {
                        disableHeader: true,
                        disableFileName: true,
                        retainURLParams: false
                    }
                }}
                style={{ height: '100%' }}
            />
        </div>
    );
}

