        category: 'Security',
        date: 'Mar 22, 2024',
      },
    ];

    // Items per page
    const itemsPerPage = 3;

    // Enhanced pagination component with content
    const EnhancedPagination = ({
      variant = 'default',
    }: {
      variant?: 'default' | 'outline' | 'rounded';
    }) => {
      const [page, setPage] = useState(1);

      // Calculate total pages
      const totalPages = Math.ceil(demoItems.length / itemsPerPage);

      // Get current items
      const startIndex = (page - 1) * itemsPerPage;
      const currentItems = demoItems.slice(
        startIndex,
        startIndex + itemsPerPage,
      );

      return (
        <div className="space-y-6">
          {/* Content area */}
          <motion.div
            className="bg-card/50 rounded-md border p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            key={`page-${page}`} // Key changes force re-animation
            transition={{ duration: 0.3 }}
          >
            <div className="mb-4 flex items-center justify-between border-b pb-2">
              <h4 className="text-muted-foreground text-sm font-medium">
                Showing {startIndex + 1}-
                {Math.min(startIndex + itemsPerPage, demoItems.length)} of{' '}
                {demoItems.length} items
              </h4>
              <span className="bg-primary/10 text-primary rounded-full px-2 py-1 text-xs font-medium">
                Page {page} of {totalPages}
              </span>
            </div>

            <div className="space-y-4">
              {currentItems.map((item) => (
                <motion.div
                  key={item.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{
                    duration: 0.3,
                    delay: (item.id % itemsPerPage) * 0.1,
                  }}
                  className="hover:bg-muted/50 flex items-center justify-between rounded-md border p-3"
                >
                  <div>
                    <h3 className="font-medium">{item.title}</h3>
                    <div className="text-muted-foreground flex items-center gap-2 text-sm">
                      <span className="bg-primary/10 text-primary rounded-full px-2 py-0.5 text-xs font-medium">
                        {item.category}
                      </span>
                      <span>{item.date}</span>
                    </div>
                  </div>
                  <button className="hover:bg-muted rounded-full p-2">
                    <ChevronRight className="text-muted-foreground h-4 w-4" />
                  </button>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Pagination controls */}
          <Pagination className="py-2">
            <PaginationContent>
              <PaginationItem>
                <motion.div
                  initial="initial"
                  animate="animate"
                  exit="exit"
                  whileHover="hover"
                  variants={itemVariants}
                  transition={{ duration: 0.3 }}
                >
                  <PaginationPrevious
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      if (page > 1) setPage(page - 1);
                    }}
                    className={cn(
                      page <= 1 ? 'pointer-events-none opacity-50' : '',
                      variant === 'rounded' ? 'rounded-full' : '',
                    )}
                  />
                </motion.div>
              </PaginationItem>

              {Array.from({ length: totalPages }).map((_, i) => {
                const pageNum = i + 1;
                const isActive = pageNum === page;

                // Show ellipsis for many pages
                if (totalPages > 5) {
                  // Always show first and last page
                  if (pageNum === 1 || pageNum === totalPages) {
                    return (
                      <PaginationItem key={pageNum}>
                        <motion.div
                          initial="initial"
                          animate="animate"
                          exit="exit"
                          whileHover="hover"
                          variants={itemVariants}
                          transition={{ duration: 0.3 }}
                        >
                          <PaginationLink
                            href="#"
                            isActive={isActive}
                            onClick={(e) => {
                              e.preventDefault();
                              setPage(pageNum);
                            }}
                            className={cn(
                              getButtonStyle(isActive),
                              variant === 'outline' && 'border',
                              'transition-all duration-200',
                            )}
                          >
                            {pageNum}
                          </PaginationLink>
                        </motion.div>
                      </PaginationItem>
                    );
                  }

                  // Show current page and adjacent pages
                  if (
                    pageNum === page ||
                    pageNum === page - 1 ||
                    pageNum === page + 1
                  ) {
                    return (
                      <PaginationItem key={pageNum}>
                        <motion.div
                          initial="initial"
                          animate="animate"
                          exit="exit"
                          whileHover="hover"
                          variants={itemVariants}
                          transition={{ duration: 0.3 }}
                        >
                          <PaginationLink
                            href="#"
                            isActive={isActive}
                            onClick={(e) => {
                              e.preventDefault();
                              setPage(pageNum);
                            }}
                            className={cn(
                              getButtonStyle(isActive),
                              variant === 'outline' && 'border',
                              'transition-all duration-200',
                            )}
                          >
                            {pageNum}
                          </PaginationLink>
                        </motion.div>
                      </PaginationItem>
                    );
                  }

                  // Show ellipsis
                  if (
                    (pageNum === 2 && page > 3) ||
                    (pageNum === totalPages - 1 && page < totalPages - 2)
                  ) {
                    return (
                      <PaginationItem key={`ellipsis-${pageNum}`}>
                        <motion.div
                          initial="initial"
                          animate="animate"
                          exit="exit"
                          variants={itemVariants}
                          transition={{ duration: 0.3 }}
                        >
                          <PaginationEllipsis />
                        </motion.div>
                      </PaginationItem>
                    );
                  }

                  return null;
                }

                // Show all pages if total pages <= 5
                return (
                  <PaginationItem key={pageNum}>
                    <motion.div
                      initial="initial"
                      animate="animate"
                      exit="exit"
                      whileHover="hover"
                      variants={itemVariants}
                      transition={{ duration: 0.3 }}
                    >
                      <PaginationLink
                        href="#"
                        isActive={isActive}
                        onClick={(e) => {
                          e.preventDefault();
                          setPage(pageNum);
                        }}
                        className={cn(
                          getButtonStyle(isActive),
                          variant === 'outline' && 'border',
                          'transition-all duration-200',
                        )}
                      >
                        {pageNum}
                      </PaginationLink>
                    </motion.div>
                  </PaginationItem>
                );
              })}

              <PaginationItem>
                <motion.div
                  initial="initial"
                  animate="animate"
                  exit="exit"
                  whileHover="hover"
                  variants={itemVariants}
                  transition={{ duration: 0.3 }}
                >
                  <PaginationNext
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      if (page < totalPages) setPage(page + 1);
                    }}
                    className={cn(
                      page >= totalPages
                        ? 'pointer-events-none opacity-50'
                        : '',
                      variant === 'rounded' ? 'rounded-full' : '',
                    )}
                  />
                </motion.div>
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
      );
    };

    return (
      <div className="mx-auto max-w-6xl px-4 py-12">
        <div className="mb-12 text-center">
          <h2 className="mb-2 text-3xl font-bold tracking-tight">
            Pagination Examples
          </h2>
          <p className="text-muted-foreground mx-auto max-w-2xl">
            Interactive pagination components that demonstrate real content
            navigation. Each example shows how pagination can be used to
            navigate through a collection of items.
          </p>
        </div>

        <div className="space-y-16">
          {/* Default Variant */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="bg-card rounded-lg border p-6 shadow-sm"
          >
            <h3 className="mb-6 text-xl font-semibold">Default Style</h3>
            <EnhancedPagination />
          </motion.div>

          {/* Outline Variant */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="bg-card rounded-lg border p-6 shadow-sm"
          >
            <h3 className="mb-6 text-xl font-semibold">Outline Style</h3>
            <EnhancedPagination variant="outline" />
          </motion.div>

          {/* Rounded Variant */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="bg-card rounded-lg border p-6 shadow-sm"
          >
            <h3 className="mb-6 text-xl font-semibold">Rounded Style</h3>
            <EnhancedPagination variant="rounded" />
          </motion.div>
        </div>
      </div>
    );
  }

  // Otherwise, just return the pagination component
  return PaginationComponent;
}

