export default function WorkingChatbot() {
  const [responseTimes, setResponseTimes] = useState<Record<string, number>>(
    {},
  );
  const [input, setInput] = useState('');
  const startTimeRef = useRef<number>(0);
  // Using theme for styling is handled by Tailwind's dark mode classes

  const transport = useMemo(
    () =>
      new DefaultChatTransport({
        api: '/api/demo-chat',
      }),
    [],
  );

  const { messages, status, error, sendMessage } = useChat({
    transport,
    onFinish: ({ message }) => {
      const duration = (Date.now() - startTimeRef.current) / 1000;
      setResponseTimes((prev) => ({ ...prev, [message.id]: duration }));
    },
  });

  // Check if the AI is currently generating a response
  const isLoading = status === 'submitted' || status === 'streaming';

  const handleSubmit = useCallback(
    (e?: React.FormEvent) => {
      e?.preventDefault();
      if (!input.trim()) return;
      startTimeRef.current = Date.now();
      sendMessage({ parts: [{ type: 'text', text: input.trim() }] });
      setInput('');
    },
    [input, sendMessage, setInput],
  );

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault();
        handleSubmit();
      }
    },
    [handleSubmit],
  );

  return (
    <div className="mx-auto flex h-svh w-full max-w-4xl flex-col pb-0.5">
      <div className="border-primary/20 bg-card/40 text-card-foreground h-full flex-1 overflow-y-auto rounded-xl border p-4 text-sm leading-6 shadow-md sm:text-base sm:leading-7">
        {messages.length > 0 ? (
          messages.map((m) => {
            return (
              <div key={m.id} className="mb-4 whitespace-pre-wrap">
                {m.role === 'user' ? (
                  <div className="flex flex-row px-2 py-4 sm:px-4">
                    <img
                      alt="user"
                      className="mr-2 flex size-6 rounded-full sm:mr-4 md:size-8"
                      src="https://i.postimg.cc/j5dW4vFd/Mvpblocks.webp"
                      width={32}
                      height={32}
                    />
                    <div className="flex max-w-3xl items-center">
                      <p>
                        {m.parts.map((part) =>
                          part.type === 'text' ? part.text : null,
                        )}
                      </p>
                    </div>
                  </div>
                ) : (
                  <div className="relative mb-4 flex rounded-xl bg-neutral-50 px-2 py-6 sm:px-4 dark:bg-neutral-900">
                    <Bot className="bg-secondary text-primary mr-2 flex size-8 rounded-full p-1 sm:mr-4" />{' '}
                    <div className="markdown-body w-full max-w-3xl overflow-x-auto rounded-xl">
                      <Markdown>
                        {m.parts
                          .map((part) =>
                            part.type === 'text' ? part.text : '',
                          )
                          .join('')}
                      </Markdown>
                      {responseTimes[m.id] && (
                        <div className="mt-2 text-xs text-neutral-500">
                          Response time: {responseTimes[m.id].toFixed(3)}s
                        </div>
                      )}
                    </div>
                    <button
                      type="button"
                      title="copy"
                      className="absolute top-2 right-2 rounded-full bg-rose-500 p-1 opacity-50 transition-all hover:opacity-75 active:scale-95 dark:bg-neutral-800"
                      onClick={() => {
                        const textContent = m.parts
                          .filter((part) => part.type === 'text')
                          .join('');
                        navigator.clipboard.writeText(textContent);
                        toast.success('Copied to clipboard');
                      }}
                    >
                      <Copy className="h-4 w-4 text-white" />
                    </button>
                  </div>
                )}
              </div>
            );
          })
        ) : (
          <div className="flex h-full flex-col items-center justify-center">
            <p className="text-muted-foreground mx-auto px-2 text-center text-xl font-semibold tracking-wide md:text-2xl">
              Start Chatting with
              <br />
              <span className="text-primary text-2xl font-bold md:text-4xl">
                MVPBlocks
              </span>
              <span className="text-primary">.AI</span>
            </p>
            <div className="group relative mt-6">
              <div className="from-primary/30 to-primary/10 absolute -inset-1 rounded-full bg-gradient-to-r opacity-75 blur-md transition-opacity duration-500 group-hover:opacity-100"></div>
              <img
                src="/assets/robo.svg"
                alt="AI Assistant"
                width={250}
                height={250}
                className="relative transition-all duration-500 hover:scale-105 active:scale-95"
              />
            </div>
          </div>
        )}
        {isLoading && (
          <div className="bg-primary/5 mx-auto flex w-fit items-center gap-2 rounded-full px-4 py-2">
            <Sparkles className="text-primary h-4 w-4 animate-pulse" />
            <span className="from-primary/80 to-primary animate-pulse bg-gradient-to-r bg-clip-text text-sm font-medium text-transparent">
              Generating response...
            </span>
          </div>
        )}
        {error && (
          <div className="border-destructive/20 bg-destructive/10 text-destructive mx-auto w-fit rounded-lg border p-3">
            Something went wrong! Please try again.
          </div>
        )}
      </div>

      <form className="mt-2" onSubmit={handleSubmit}>
        <div className="relative">
          <AiInput
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onSubmit={handleSubmit}
            onKeyDown={handleKeyDown}
          />
        </div>
      </form>
    </div>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useRef } from 'react';
import { motion, useMotionValue, transform } from 'framer-motion';

const ICON_CONFIG = {
  margin: 20,
  size: 100,
};

const CONTAINER_CONFIG = {
  width: 420,
  height: 420,
};

const GRID_SIZE = 10;
const COLS = 12;

function useIconTransform({
  x,
  y,
  scale,
  planeX,
  planeY,
  xOffset,
  yOffset,
}: {
  x: any;
  y: any;
  scale: any;
  planeX: any;
  planeY: any;
  xOffset: number;
  yOffset: number;
}) {
  const xScale = useRef(1);
  const yScale = useRef(1);
  const createScreenRange = (axis: 'width' | 'height') => [
    -60,
    80,
    CONTAINER_CONFIG[axis] - (ICON_CONFIG.size + ICON_CONFIG.margin) / 2 - 80,
    CONTAINER_CONFIG[axis] - (ICON_CONFIG.size + ICON_CONFIG.margin) / 2 + 60,
  ];

  const xRange = createScreenRange('width');
  const yRange = createScreenRange('height');

  const mapScreenToXOffset = transform(xRange, [50, 0, 0, -50]);
  const mapScreenToYOffset = transform(yRange, [50, 0, 0, -50]);
  const mapScreenXToScale = transform(xRange, [0, 1, 1, 0]);
  const mapScreenYToScale = transform(yRange, [0, 1, 1, 0]);

  const updateScale = useCallback(() => {
    const newScale = Math.min(xScale.current, yScale.current);
    scale.set(newScale);
  }, [scale]);

  useEffect(() => {
    // Calculate initial position
    const initialX = planeX.get() + xOffset + 20;
    xScale.current = mapScreenXToScale(initialX);
    x.set(mapScreenToXOffset(initialX));

    return planeX.onChange((v: number) => {
      const screen = v + xOffset + 20;
      xScale.current = mapScreenXToScale(screen);

      x.set(mapScreenToXOffset(screen));
      updateScale();
    });
  }, [
    planeX,
    x,
    scale,
    xOffset,
    mapScreenXToScale,
    mapScreenToXOffset,
    updateScale,
  ]);

  useEffect(() => {
    // Calculate initial position
    const initialY = planeY.get() + yOffset + 20;
    yScale.current = mapScreenYToScale(initialY);
    y.set(mapScreenToYOffset(initialY));

    return planeY.onChange((v: number) => {
      const screen = v + yOffset + 20;
      yScale.current = mapScreenYToScale(screen);

      y.set(mapScreenToYOffset(screen));
      updateScale();
    });
  }, [
    planeY,
    y,
    scale,
    yOffset,
    mapScreenYToScale,
    mapScreenToYOffset,
    updateScale,
  ]);

  // Initial scale update
  useEffect(() => {
    updateScale();
  }, [updateScale]);
}

function BubbleItem({
  row,
  col,
  planeX,
  planeY,
  colorIndex,
}: {
  row: number;
  col: number;
  planeX: any;
  planeY: any;
  colorIndex: number;
}) {
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const scale = useMotionValue(1);

  const length = ICON_CONFIG.size + ICON_CONFIG.margin;
  const xOffset = col * length + (row % 2) * (length / 2);
  const yOffset = row * ICON_CONFIG.size;

  useIconTransform({ x, y, scale, planeX, planeY, xOffset, yOffset });

  const colors = [
    'bg-chart-1',
    'bg-chart-2',
    'bg-chart-3',
    'bg-chart-4',
    'bg-chart-5',
  ];
  const colorClass = colors[colorIndex % colors.length];
  return (
    <motion.div
      style={{
        position: 'absolute',
        left: xOffset,
        top: yOffset,
        x,
        y,
        scale,
        width: ICON_CONFIG.size,
        height: ICON_CONFIG.size,
      }}
      className={`rounded-full ${colorClass} shadow-lg`}
    />
  );
}

export default function BubbleBoard() {
  const GRID_SIZE_PX = 1000;
  const DEVICE_SIZE = CONTAINER_CONFIG.width;

  const initialOffset = -(GRID_SIZE_PX - DEVICE_SIZE) / 2;
  const x = useMotionValue(initialOffset);
  const y = useMotionValue(initialOffset);

  const grid = useMemo(() => {
    return new Array(GRID_SIZE)
      .fill(null)
      .map((_, i) => new Array(COLS).fill(null).map((_, j) => j));
  }, []);

  return (
    <div
      className="relative m-8 overflow-hidden rounded-3xl"
      style={{
        width: CONTAINER_CONFIG.width,
        height: CONTAINER_CONFIG.height,
        boxShadow: 'inset 0 0 50px 0px hsl(var(--foreground) / 30%)',
      }}
    >
      <motion.div
        drag
        dragConstraints={{
          left: -650,
          right: 50,
          top: -600,
          bottom: 50,
        }}
        style={{
          width: 1000,
          height: 1000,
          x,
          y,
          background: 'transparent',
        }}
        className="cursor-grab active:cursor-grabbing"
      >
        {grid.map((rows, rowIndex) =>
          rows.map((colIndex) => (
            <BubbleItem
              key={`${rowIndex}-${colIndex}`}
              row={rowIndex}
              col={colIndex}
              planeX={x}
              planeY={y}
              colorIndex={rowIndex * COLS + colIndex}
            />
          )),
        )}
      </motion.div>
    </div>
  );
}

