            <button
                onClick={handleCopy}
                className="absolute top-2 right-2 px-2 py-1 text-xs text-neutral-400 bg-neutral-800 rounded hover:bg-neutral-700 transition-colors opacity-0 group-hover:opacity-100"
            >
                {copied ? "Copied!" : "Copy"}
            </button>
        </div>
    );
};

