                <div
                    className={cn(
                        "w-full h-full grid [grid-area:1/1] overflow-hidden relative [border-radius:var(--radius)] [background:radial-gradient(ellipse_80%_50%_at_var(--bg-x)_var(--bg-y),_hsl(240,15%,25%),transparent)]",
                        className
                    )}
                >
                    {children}
                </div>
            </div>
        </div>
    );
};

