"use client";

/**
 * Auth Context - Authentication via GraphQL Middleware
 * NO direct Supabase access
 */

import React, { createContext, useContext, useState, useEffect, ReactNode } from "react";
import {
    graphql,
    queries,
    mutations,
    getStoredToken,
    getStoredRefreshToken,
    storeAuthTokens,
    clearAuthTokens,
    isAuthGraphQLError,
} from "@/lib/graphqlClient";
import type { User, AuthResponse } from "@/lib/graphqlTypes";
import { useAuthStore } from "@/store/useAuthStore";

// User profile type for backward compatibility
interface UserProfile {
    id: string;
    email: string;
    full_name?: string;
    role: string;
    two_factor_enabled: boolean;
    two_factor_secret?: string;
    created_at: string;
}

interface AuthContextType {
    user: User | null;
    profile: UserProfile | null;
    loading: boolean;
    signIn: (email: string, password: string) => Promise<{ error?: string; requiresTwoFactor?: boolean }>;
    signUp: (email: string, password: string, fullName?: string) => Promise<{ error?: string }>;
    signOut: () => Promise<void>;
    verifyTwoFactor: (code: string) => Promise<{ error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

function applyUserSession(me: User) {
    const profile: UserProfile = {
        id: me.id,
        email: me.email,
        full_name: me.fullName,
        role: me.role,
        two_factor_enabled: false,
        created_at: me.createdAt || new Date().toISOString(),
    };
    useAuthStore.getState().syncFromAuth(me);
    return { user: me, profile };
}

async function fetchMe(accessToken: string): Promise<User | null> {
    const data = await graphql<{ me: User | null }>(queries.me, { token: accessToken });
    return data.me ?? null;
}

async function tryRefreshTokens(): Promise<string | null> {
    const refreshToken = getStoredRefreshToken();
    if (!refreshToken) return null;

    try {
        const data = await graphql<{ refreshToken: { accessToken: string; refreshToken: string } }>(
            mutations.refreshToken,
            { variables: { refreshToken } },
        );
        if (!data.refreshToken?.accessToken) return null;
        storeAuthTokens(data.refreshToken.accessToken, data.refreshToken.refreshToken);
        return data.refreshToken.accessToken;
    } catch {
        return null;
    }
}

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<User | null>(null);
    const [profile, setProfile] = useState<UserProfile | null>(null);
    const [loading, setLoading] = useState(true);
    useEffect(() => {
        checkSession();
    }, []);

    const checkSession = async () => {
        let token = getStoredToken();
        if (!token) {
            setLoading(false);
            return;
        }

        const fetchMeOrNull = async (accessToken: string): Promise<User | null> => {
            try {
                return await fetchMe(accessToken);
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error);
                if (isAuthGraphQLError(message)) return null;
                throw error;
            }
        };

        try {
            let me = await fetchMeOrNull(token);

            if (!me) {
                const refreshed = await tryRefreshTokens();
                if (refreshed) {
                    me = await fetchMeOrNull(refreshed);
                }
            }

            if (me) {
                const session = applyUserSession(me);
                setUser(session.user);
                setProfile(session.profile);
            } else {
                clearAuthTokens();
                useAuthStore.getState().clearUser();
            }
        } catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            console.error("Session check failed:", message);
            // Network / middleware errors: keep tokens so refresh does not feel like logout
        }

        setLoading(false);
    };

    const signIn = async (email: string, password: string) => {
        try {
            const data = await graphql<{ signIn: AuthResponse }>(mutations.signIn, {
                variables: { email, password },
            });

            if (data.signIn) {
                storeAuthTokens(data.signIn.accessToken, data.signIn.refreshToken);
                const session = applyUserSession(data.signIn.user);
                setUser(session.user);
                setProfile(session.profile);
                return {};
            }

            return { error: "Sign in failed" };
        } catch (error) {
            return { error: error instanceof Error ? error.message : "Sign in failed" };
        }
    };

    const signUp = async (email: string, password: string, fullName?: string) => {
        try {
            const data = await graphql<{ signUp: AuthResponse }>(mutations.signUp, {
                variables: { email, password, name: fullName },
            });

            if (data.signUp) {
                storeAuthTokens(data.signUp.accessToken, data.signUp.refreshToken);
                const session = applyUserSession(data.signUp.user);
                setUser(session.user);
                setProfile(session.profile);
                return {};
            }

            return { error: "Sign up failed" };
        } catch (error) {
            return { error: error instanceof Error ? error.message : "Sign up failed" };
        }
    };

    const verifyTwoFactor = async (code: string) => {
        if (code.length !== 6 || !/^\d+$/.test(code)) {
            return { error: "Invalid verification code" };
        }

        return {};
    };

    const signOut = async () => {
        try {
            const token = getStoredToken();
            await graphql<{ signOut: boolean }>(mutations.signOut, { token: token || undefined });
        } catch (error) {
            console.error("Sign out error:", error);
        }

        clearAuthTokens();
        setUser(null);
        setProfile(null);
        useAuthStore.getState().clearUser();
    };

    return (
        <AuthContext.Provider value={{
            user,
            profile,
            loading,
            signIn,
            signUp,
            signOut,
            verifyTwoFactor,
        }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error("useAuth must be used within an AuthProvider");
    }
    return context;
}

import { useState, useEffect } from 'react';

type UseMediaQueryOptions = {
  defaultValue?: boolean;
  initializeWithValue?: boolean;
};

const IS_SERVER = typeof window === 'undefined';

export function useMediaQuery(
  query: string,
  {
    defaultValue = false,
    initializeWithValue = true,
  }: UseMediaQueryOptions = {},
): boolean {
  const getMatches = (query: string): boolean => {
    if (IS_SERVER) {
      return defaultValue;
    }
    return window.matchMedia(query).matches;
  };

  const [matches, setMatches] = useState<boolean>(() => {
    if (initializeWithValue) {
      return getMatches(query);
    }
    return defaultValue;
  });

  // Handles the change event of the media query.
  function handleChange() {
    setMatches(getMatches(query));
  }

  useEffect(() => {
    const matchMedia = window.matchMedia(query);

    // Triggered at the first client-side load and if query changes
    handleChange();

    // Use deprecated `addListener` and `removeListener` to support Safari < 14 (#135)
    if (matchMedia.addListener) {
      matchMedia.addListener(handleChange);
    } else {
      matchMedia.addEventListener('change', handleChange);
    }

    return () => {
      if (matchMedia.removeListener) {
        matchMedia.removeListener(handleChange);
      } else {
        matchMedia.removeEventListener('change', handleChange);
      }
    };
  }, [query]);

  return matches;
}

'use client';

// Inspired by react-hot-toast library
import * as React from 'react';

import type { ToastActionElement, ToastProps } from '@/components/ui/toast';

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const actionTypes = {
  ADD_TOAST: 'ADD_TOAST',
  UPDATE_TOAST: 'UPDATE_TOAST',
  DISMISS_TOAST: 'DISMISS_TOAST',
  REMOVE_TOAST: 'REMOVE_TOAST',
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType['ADD_TOAST'];
      toast: ToasterToast;
    }
  | {
      type: ActionType['UPDATE_TOAST'];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType['DISMISS_TOAST'];
      toastId?: ToasterToast['id'];
    }
  | {
      type: ActionType['REMOVE_TOAST'];
      toastId?: ToasterToast['id'];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t,
        ),
      };

    case 'DISMISS_TOAST': {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      };
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, 'id'>;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id });

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id: id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, [state]);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  };
}

export { useToast, toast };

