const SUPABASE_URL = typeof window !== 'undefined' ? 'http://localhost:8000' : (process.env.NEXT_PUBLIC_SUPABASE_URL || 'http://kong:8000');
const SUPABASE_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYW5vbiIsImlzcyI6InN1cGFiYXNlIiwiaWF0IjoxNzc1MjE1MjE4LCJleHAiOjIxNDU5MTY4MDB9.6q7QrCyLzEJ-m2Mw8Y29BNR_tF3fKAfbXhdcc4HKxhE';

export async function supaRest<T = any[]>(
    table: string,
    options?: {
        select?: string;
        filters?: Record<string, string>;
        order?: string;
        limit?: number;
    }
): Promise<T> {
    const params = new URLSearchParams();
    params.set('select', options?.select || '*');
    if (options?.order) params.set('order', options.order);
    if (options?.limit) params.set('limit', String(options.limit));
    if (options?.filters) {
        for (const [col, val] of Object.entries(options.filters)) {
            if (val) params.set(col, val);
        }
    }
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?${params}`, {
        headers: {
            'apikey': SUPABASE_KEY,
            'Authorization': `Bearer ${SUPABASE_KEY}`,
            'Content-Type': 'application/json',
        },
    });
    if (!res.ok) {
        const err = await res.json().catch(() => ({ message: res.statusText }));
        throw new Error(err.message || res.statusText);
    }
    return res.json() as Promise<T>;
}

export async function supaInsert<T = any>(table: string, body: Record<string, any>): Promise<T> {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}`, {
        method: 'POST',
        headers: {
            'apikey': SUPABASE_KEY,
            'Authorization': `Bearer ${SUPABASE_KEY}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=representation',
        },
        body: JSON.stringify(body),
    });
    if (!res.ok) {
        const err = await res.json().catch(() => ({ message: res.statusText }));
        throw new Error(err.message || err.details || res.statusText);
    }
    const data = await res.json();
    return Array.isArray(data) ? data[0] : data;
}

export async function supaUpdate<T = any>(table: string, id: string, body: Record<string, any>): Promise<T> {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?id=eq.${id}`, {
        method: 'PATCH',
        headers: {
            'apikey': SUPABASE_KEY,
            'Authorization': `Bearer ${SUPABASE_KEY}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=representation',
        },
        body: JSON.stringify(body),
    });
    if (!res.ok) {
        const err = await res.json().catch(() => ({ message: res.statusText }));
        throw new Error(err.message || res.statusText);
    }
    const data = await res.json();
    return Array.isArray(data) ? data[0] : data;
}

export async function supaDelete(table: string, id: string): Promise<void> {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
